-- lgup2 데이터베이스 구조 내보내기
CREATE DATABASE IF NOT EXISTS `lgup2` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci */;
USE `lgup2`;

-- 테이블 lgup2.attraction 구조 내보내기
CREATE TABLE IF NOT EXISTS `attraction` (
  `attr_id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `url` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `hours_of_operation` text DEFAULT NULL,
  `holidays` varchar(255) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `transportation` text DEFAULT NULL,
  `image_urls` text DEFAULT NULL,
  `image_count` int(11) DEFAULT 0,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `attr_code` varchar(50) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`attr_id`)
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 데이터 lgup2.attraction:~224 rows (대략적) 내보내기

-- 테이블 lgup2.attraction_kcontents_data 구조 내보내기
CREATE TABLE IF NOT EXISTS `attraction_kcontents_data` (
  `attr_id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `address` varchar(512) DEFAULT NULL,
  `url` varchar(512) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `hours_of_operation` text DEFAULT NULL,
  `holidays` varchar(255) DEFAULT NULL,
  `transportation` text DEFAULT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `keyword` text DEFAULT NULL,
  `drama_name_en_list` text DEFAULT NULL,
  `drama_image` text DEFAULT NULL,
  `image_count` int(11) DEFAULT NULL,
  PRIMARY KEY (`attr_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 데이터 lgup2.attraction_kcontents_data:~241 rows (대략적) 내보내기

-- 테이블 lgup2.bookmark 구조 내보내기
CREATE TABLE IF NOT EXISTS `bookmark` (
  `bookmark_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `extracted_from_convers_id` int(11) DEFAULT NULL,
  `place_type` int(11) DEFAULT 0,
  `reference_id` int(11) DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `image_url` varchar(255) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `location_name` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `keyword` varchar(255) DEFAULT NULL,
  `trip_tip` text DEFAULT NULL,
  PRIMARY KEY (`bookmark_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `bookmark_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

