-- 테이블 lgup2.conversations 구조 내보내기
CREATE TABLE IF NOT EXISTS `conversations` (
  `convers_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `fullconverse` text DEFAULT NULL COMMENT '전체 대화 내용',
  `question` text NOT NULL COMMENT '사용자 질문',
  `response` text NOT NULL COMMENT 'GPT 응답',
  `datetime` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`convers_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_datetime` (`datetime`),
  CONSTRAINT `conversations_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1341 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 데이터 lgup2.conversations:~1,216 rows (대략적) 내보내기

-- 테이블 lgup2.conversations_spot 구조 내보내기
CREATE TABLE IF NOT EXISTS `conversations_spot` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `conversations_id` int(11) NOT NULL,
  `spot_type` enum('attraction','restaurant','celeb_restaurant','festival') NOT NULL,
  `spot_id` int(11) NOT NULL,
  `mentioned_at` datetime DEFAULT current_timestamp(),
  `mention_count` int(11) DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `fk_user` (`user_id`),
  KEY `fk_conversation` (`conversations_id`),
  CONSTRAINT `fk_conversation` FOREIGN KEY (`conversations_id`) REFERENCES `conversations` (`convers_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 데이터 lgup2.conversations_spot:~0 rows (대략적) 내보내기

-- 테이블 lgup2.destinations 구조 내보내기
CREATE TABLE IF NOT EXISTS `destinations` (
  `destination_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `extracted_from_convers_id` int(11) DEFAULT NULL,
  `place_type` int(11) DEFAULT 0,
  `reference_id` int(11) DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `schedule_id` int(11) NOT NULL,
  `visit_order` int(11) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `custom_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '사용자 정의 필드 (Time, Cost, Memo 등)' CHECK (json_valid(`custom_fields`)),
  PRIMARY KEY (`destination_id`),
  KEY `user_id` (`user_id`),
  KEY `schedule_id` (`schedule_id`),
  CONSTRAINT `destinations_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `destinations_ibfk_2` FOREIGN KEY (`schedule_id`) REFERENCES `schedules` (`schedule_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=474 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 데이터 lgup2.destinations:~151 rows (대략적) 내보내기

-- 테이블 lgup2.entertainment 구조 내보내기
