  `image_url` varchar(512) DEFAULT NULL COMMENT '대표 이미지 URL',
  `instagram_address` varchar(255) DEFAULT NULL COMMENT '인스타그램 주소 또는 태그',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '위도',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '경도',
  `description` text DEFAULT NULL COMMENT '이벤트 상세 설명',
  `detail_url` varchar(512) DEFAULT NULL COMMENT '상세 정보 웹사이트 URL',
  PRIMARY KEY (`festival_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

