-- 테이블 lgup2.restaurant 구조 내보내기
CREATE TABLE IF NOT EXISTS `restaurant` (
  `restaurant_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '식당 고유 ID',
  `restaurant_name` varchar(255) NOT NULL COMMENT '식당 이름',
  `place` varchar(100) DEFAULT NULL COMMENT '식당 소재 지역/코드',
  `image_path` varchar(512) DEFAULT NULL COMMENT '이미지 경로 또는 URL',
  `description` text DEFAULT NULL COMMENT '식당 상세 설명 및 메뉴 목록',
  `Latitude` decimal(10,6) DEFAULT NULL COMMENT '위도',
  `Longitude` decimal(10,6) DEFAULT NULL COMMENT '경도',
  `price` varchar(100) DEFAULT NULL COMMENT '가격대 정보',
  `near_subway` varchar(255) DEFAULT NULL COMMENT '인근 지하철역 정보 및 거리',
  `signature_menu` varchar(512) DEFAULT NULL COMMENT '대표 메뉴 (가격 포함)',
  `operatingday` varchar(100) DEFAULT NULL COMMENT '주요 운영 요일',
  `website` varchar(512) DEFAULT NULL COMMENT '공식 웹사이트 주소',
  `type` varchar(100) DEFAULT NULL COMMENT '식당 유형 (예: 음식점, 카페)',
  `notice` text DEFAULT NULL COMMENT '공지사항/유의사항 등 기타 정보',
  `operatinghour` text DEFAULT NULL COMMENT '상세 운영 시간 정보',
  `tel` varchar(50) DEFAULT NULL COMMENT '전화번호',
  `holidays` varchar(255) DEFAULT NULL COMMENT '정기 휴무일/휴일',
  PRIMARY KEY (`restaurant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 데이터 lgup2.restaurant:~1,098 rows (대략적) 내보내기

-- 테이블 lgup2.schedules 구조 내보내기
CREATE TABLE IF NOT EXISTS `schedules` (
  `schedule_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `day_number` int(11) NOT NULL,
  `day_title` varchar(255) DEFAULT NULL,
  `schedule_date` date DEFAULT NULL,
  `description` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`schedule_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `schedules_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 테이블 데이터 lgup2.schedules:~20 rows (대략적) 내보내기

-- 테이블 lgup2.schedule_table_metadata 구조 내보내기
CREATE TABLE IF NOT EXISTS `schedule_table_metadata` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `schedule_id` int(11) NOT NULL,
  `column_order` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '컬럼 순서 배열' CHECK (json_valid(`column_order`)),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_schedule` (`schedule_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `schedule_table_metadata_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `schedule_table_metadata_ibfk_2` FOREIGN KEY (`schedule_id`) REFERENCES `schedules` (`schedule_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 테이블 데이터 lgup2.schedule_table_metadata:~13 rows (대략적) 내보내기

-- 테이블 lgup2.travel_plans 구조 내보내기
CREATE TABLE IF NOT EXISTS `travel_plans` (
