  `plan_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '여행 계획 상세 데이터 (JSON)' CHECK (json_valid(`plan_data`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
