INSERT INTO `attraction` (`attr_id`, `title`, `url`, `description`, `phone`, `hours_of_operation`, `holidays`, `address`, `transportation`, `image_urls`, `image_count`, `latitude`, `longitude`, `attr_code`, `created_at`, `updated_at`) VALUES
	(1, '63 Square', 'https://english.visitseoul.net/attractions/63-Square/ENP000210', 'The 63 Square skyscraper is a Yeouido landmark commanding spectacular views of the city. Standing 249 meters (817 ft) high and comprising of 60 floors and three basement levels, 63 Square is one of Korea??s tallest and most recognized buildings. The glass elevators which serve the viewing observatory ascend at a speed of 460 meters per minute, taking just 25 seconds to reach the top, giving passengers the sensation of a rocket-powered take-off as they enjoy breathtaking views. Aqua Planet 63, a major tourist attraction within 63 Square, ceased operations on June 30, 2024. Additionally, the observatory ??3 Art,??where visitors could enjoy views of Seoul and art pieces, also ceased operations on the same day. In 2025, the Centre Pompidou Hanwha Seoul is scheduled to open in 63 Square.    63 Square??s distinctive gold color is the real thing; each of the 14,000 panes of glass was coated with a thin film of 24-carat gold which catches the sunshine, reflecting gold, red and silver as the sun sets, giving the tower its stunning multi-colored sheen.    Frequently Asked Questions about 63 Square         Are pets allowed in the 63 Square(63 Building)?         Pets are not allowed in all viewing areas within 63 Square(63 Building). (As of 2024)          Are there any tourist attractions worth visiting near 63 Square(63 Building)?         These are the following tourist attractions around 63 Square(63 Building).     ?? National Assembly    ?? Yeouido Hangang Park    ?? Yeouido Saetgang Ecological Park        { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "Are pets allowed in the 63 Square(63 Building)?", "acceptedAnswer": { "@type": "Answer", "text": "<div> Pets are not allowed in all viewing areas within 63 Square(63 Building). (As of 2024) </div>" } }, { "@type": "Question", "name": "Are there any tourist attractions worth visiting near 63 Square(63 Building)?", "acceptedAnswer": { "@type": "Answer", "text": "<div> These are the following tourist attractions around 63 Square(63 Building).<br><br> <ul> <li><a href=\\"https://english.visitseoul.net/attractions/National-Assembly-Building_/5763\\"style=\\"color:#0000EE;text-decoration:underline\\">National Assembly</a></li> <li><a href=\\"https://english.visitseoul.net/nature/Yeouido-Hangang-Park-Girls%E2%80%99-Generation-Forest_/12997\\"style=\\"color:#0000EE;text-decoration:underline\\">Yeouido Hangang Park</a></li> <li><a href=\\"https://english.visitseoul.net/nature/Yeouido-Saetgang-Ecological-Park_/5033\\"style=\\"color:#0000EE;text-decoration:underline\\">Yeouido Saetgang Ecological Park</a></li> </ul> </div>" } }, { "@type": "LocalBusiness", "name": "63 Square", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4", "ratingCount": "280" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "jh s" }, "reviewBody": "just a tall building in a residential area. not worth visiting in itself. the restaurants and attractions are mostly intended for families in the area.", "datePublished": "2020-02-19" } }] }', '-6372', 'Temporarily closed', 'Temporarily closed', '07345  50, 63-ro, Yeongdeungpo-gu, Seoul, Korea', 'Subway Line 9/Sillim Line  Saetgang Station  Exit 3,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68043&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68044&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68045&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68046&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.51893420, 126.93846170, 'ENP000210', NULL, NULL),
	(2, 'Seoul Plaza', 'https://english.visitseoul.net/attractions/Seoul-Plaza/ENP001538', 'Seoul Plaza refers to the square located in front of Seoul City Hall, which used to be widely used as a location for public rallies, protests, and events. In 2002 the roadway was completely transformed and grassed over, and the current lively Seoul Plaza with its artwork and culture was inaugurated in 2004. The plaza features a refreshing fountain in the summer and an outdoor ice rink in the winter.', '-40', '', '', '100-101  110, Sejong-daero, Jung-gu, Seoul', 'Subway Line 1 /2  City Hall Station  Exit 5,  89m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68401&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73868&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73869&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68402&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68403&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.56658510, 126.97820380, 'ENP001538', NULL, NULL),
	(3, 'Malli-dong', 'https://english.visitseoul.net/attractions/Mallidong/ENP037156', 'The Malli-dong neighborhood, located near Seoul Station, has been gaining popularity ever since the opening of Seoullo 7071, a sky garden and pedestrian road. This historic district of Seoul is home to a variety of restaurants with delectable food and trendy coffee shops. This area dates back to the state of Joseon, so the locals associate it with the history of the city.', '', '', '', '04528  Manrijae-ro, Jung-gu, Seoul', 'Subway Lines 1/4/Airport Railroad/Gyeongui-Jungang Line/GTX  Seoul Station  Exit 15, 300m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41304&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41305&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41306&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.55887580, 126.97590390, 'ENP037156', NULL, NULL),
	(4, 'Seochon Hanok Village', 'https://english.visitseoul.net/attractions/SeochonHanokVillage/ENPhyd9ee', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}To the west of Gyeongbokgung Palace is a village where various middle-class officials such as court nobles and government officials lived during the Joseon Dynasty. This neighborhood has long been guarded by old shops and hanok houses, along with newly emerged stores, creating a harmonious blend of unique charm and simplicity that can be felt.', '', '', '', '03037  45, Pilwoon-daero, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  617m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60872&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60873&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60874&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60875&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73922&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58024930, 126.96737930, 'ENPhyd9ee', NULL, NULL),
	(5, 'Ikseon-dong Hanok Village', 'https://english.visitseoul.net/attractions/IkseongdongHanokVillage/ENP037008', 'The Ikseon-dong Hanok Village spans a length of around 801 m, connecting Ibis Ambassador, Insadong, and Nakwon Sanga, or Nakwon Music Market, and is home to all kinds of fusion-concept cafes, restaurants, and shops that contrast with the more traditional vibe of the neighboring Insadong area. In fact, it\'s one of the most popular sights for dating in the city! Despite the relatively narrow alleyways of the village, you are in for a treat during the winter season or night hours with the quaint, yet striking scenery all around.      Frequently Asked Questions about Ikseon-dong Hanok Village        What is the nearest subway station to Ikseon-dong Hanok Street?         The nearest subway station to Ikseon-dong Hanok Street is Jongno 3-ga Station (Subway Line 1, 3, 5).          Are there any tourist attractions worth visiting near Ikseon-dong Hanok Street?         These are the following tourist attractions around Ikseon-dong Hanok Street.     Jongmyo Shrine     Gwanghwamun Square     Gyeongbokgung Palace        { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "What is the nearest subway station to Ikseon-dong Hanok Street?", "acceptedAnswer": { "@type": "Answer", "text": "<div>The nearest subway station to Ikseon-dong Hanok Street is Jongno 3-ga Station (Subway Line 1, 3, 5).</div>" } }, { "@type": "Question", "name": "Are there any tourist attractions worth visiting near Ikseon-dong Hanok Street?", "acceptedAnswer": { "@type": "Answer", "text": "<div> These are the following tourist attractions around Ikseon-dong Hanok Street.<br><br> <ul> <li><a href=\\"https://english.visitseoul.net/attractions/Jongmyo_/549\\"style=\\"color:#0000EE;text-decoration: underline\\">Jongmyo Shrine</a></li> <li><a href=\\"https://english.visitseoul.net/attractions/Gwanghwamun-Square_/1901\\"style=\\"color:#0000EE;text-decoration: underline\\">Gwanghwamun Square</a></li> <li><a href=\\"https://english.visitseoul.net/attractions/Gyeongbokgung-Palace_/73\\"style=\\"color:#0000EE;text-decoration: underline\\">Gyeongbokgung Palace</a></li> </ul> </div>" } }, { "@type": "LocalBusiness", "name": "Ikseon-dong Hanok Village", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "72" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Yi Qin" }, "reviewBody": "Recommended by a local to visit which turns out to be one of the most memorable moment of our trip. The area is made up of connecting alleys which makes you feel like you are in a maze but there\'s something good waiting for you at every turn. Quaint little shops and cafes converted from ancient architectures filled up the streets, displaying a perfect blend of modern and history in the heart of Seoul.", "datePublished": "2020-03-15" } }] }', '', '', '', '03133  17, Donhwamun-ro 11ga-gil, Jongno-gu, Seoul', 'Subway Lines 1 / 3 / 5, Jongno 3-ga Station, Exit 4,  141m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67734&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67735&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67736&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67737&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67738&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57339030, 126.98977250, 'ENP037008', NULL, NULL),
	(6, 'Night Views at Banpodaegyo Bridge', 'https://english.visitseoul.net/attractions/Night-Views-at-Banpodaegyo-Bridge/ENP016325', 'Banpodaegyo Bridge is a two level bridge that crosses the Hangang River. The Moonlight Rainbow Fountain display takes place at this bridge and it\'s often possible to see fireworks here as well. The area is a popular date spot and the view at night is beautiful. Bask in the atmosphere and the views of the Hangang River at Banpodaegyo Bridge.', '-4278', '', '', '2085-14, Olympic-daero, Seocho-gu, Seoul', 'Subway Lines 3/7/9  Express Bus Terminal Station  Exit 8-1,  850m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42326&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42327&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12910&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12909&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.51198270, 126.99342230, 'ENP016325', NULL, NULL),
	(7, 'ParkNoSoo Museum', 'https://english.visitseoul.net/attractions/ParkNoSoo-Museum/ENP042350', 'Pro-Japanesepolitician Yoon Deok-young built the house for his daughter in 1937, whichlater became painter Park No-soo??s house in 1973. Park No-soo, who devotedhimself to art over the 40 years he lived in this house, donated it back tosociety along with his artwork. The historical residence was reborn as an artmuseum in 2013 through the Jongno Cultural Foundation.  Despiteits long history of 80 years, this well-maintained building was recognized forits cultural value and was registered Cultural Heritage Material No. 1 of Seoulin 1991.', '-6239', 'Daily 10:00 ~ 18:00', 'Closed Mondays', '03034  34, Ogin 1-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  870m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56153&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56154&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56155&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56156&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56157&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58136690, 126.96674920, 'ENP042350', NULL, NULL),
	(8, 'Sungkyunkwan University', 'https://english.visitseoul.net/attractions/Sungkyunkwan-University/ENP019656', 'Sungkyunkwan University was founded in 1398 and it is the oldest university in Asia. The university was founded by the first king of the Joseon Dynasty, King Taejo of Joseon. Sungkyunkwan University has two campuses, one located in Seoul and the other in the city of Suwon. The Seoul campus is located near Hyehwa Station and visitors can see historical buildings that date back to the Joseon era.', '-794', '', '', '03063  25-2, Sungkyunkwan-ro (Sungkyunkwan Univ.), Jongno-gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 4,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13223&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13224&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13225&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73926&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73927&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58822700, 126.99360600, 'ENP019656', NULL, NULL),
	(9, 'Namsan Cable Car', 'https://english.visitseoul.net/attractions/Namsan-Cable-Car/ENP035015', 'The Namsan Cable Car is the most convenient and fun way to reach the summit of Namsan Mountain! In just a three-minute ride, you can reach the mountain peak up near the N Seoul Tower all the while enjoying a fantastic overlook of downtown Seoul. Not only can you experience the breathtaking view of the autumn foliage in the fall and snow-covered mountainside in the winter, but you can even catch a gorgeous aerial view of the city at night. Near the parking lot of the cable car, the surrounding neighborhood has a great selection of popular restaurants offering tasty menu items from tonkatsu (breaded pork cutlet) to vegetarian bibimbap and more! The 140-meter long Namsan outdoor elevator, Namsam Ormi, is also available for easy access to the cable car platform!', '-3076', 'Daily 10:00 - 23:00 KST', '', '04630  83, Sopa-ro, Jung-gu, Seoul', 'Subway Line 4  Myeongdong Station  Exit 4,  571m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32472&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32473&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32475&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.55773270, 126.98496330, 'ENP035015', NULL, NULL),
	(10, 'Bugak Skyway Octagonal Pavilion', 'https://english.visitseoul.net/attractions/BugakSkywayPavilion/ENP011117', 'Bugak Skyway, which runs along the northeast ridge of Bugaksan (Mt.), has become known as the most beautiful driving route in Korea ever since it opened in September of 1968. The road is forested by thick greenery and leads to an octagonal pavilion (Palgakjeong) located at the top of the mountain, allowing visitors to appreciate a panoramic view of the whole city of Seoul. Ever since Palgakjeong and the surrounding areas underwent renovation and re-opened in April 2010, Bugak Skyway has grown to become a must for local residents and tourists alike. Palgakjeong is located at an elevation of 342 m, allowing visitors to appreciate not only the beauty of mother nature but also a panoramic view of the entire city. Visitors can enjoy a traditional plaza, a pagoda resting area, a wildflower garden and walking trails.        Frequently Asked Questions about Bugak Skyway Palgakjeong Pavilion         What are Bugak Skyway Palgakjeong Pavilion\'s operating hours?         Bugak Skyway Palgakjeong Pavilion is open 24 hours a day, 7 days a week. (As of 2025)          I am curious about the location and price of the Bugak Skyway Palgakjeong Pavilion parking lot.         Bugak Skyway Palgakjeong parking lot is next to Bugak Palgakjeong Pavilion (San 6-18, Pyeongchang-dong, Jongno-gu, Seoul). The parking fee is 400 KRW per 10 minutes. (As of 2025)     { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "What are Bugak Skyway Palgakjeong Pavilion\'s operating hours?", "acceptedAnswer": { "@type": "Answer", "text": "<div>Bugak Skyway Palgakjeong Pavilion is open 24 hours a day, 7 days a week. (As of 2024)</div>" } }, { "@type": "Question", "name": "I am curious about the location and price of the Bugak Skyway Palgakjeong Pavilion parking lot.", "acceptedAnswer": { "@type": "Answer", "text": "<div>Bugak Skyway Palgakjeong parking lot is next to Bugak Palgakjeong Pavilion (San 6-18, Pyeongchang-dong, Jongno-gu, Seoul). The parking fee is 400 KRW per 10 minutes. (As of 2024)</div>" } }, { "@type": "LocalBusiness", "name": "Bugak Skyway Palgakjeong Pavilio", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4", "ratingCount": "13" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Philip P" }, "reviewBody": "De pavilion itself is not very particular, but the views from that mountain are stunning! Walk through the park, look in all directions. Not to be missed!", "datePublished": "2022-04-29" } }] }', '', '', '', '03010  267, Bugaksan-ro, Jongno-gu, Seoul', 'Subway Line 4  Hansung University Station  Exit 6,  take bus 1112 or 1111, get off at Seoul Dawon School or Han Yong-un Activity Center, 2.3 km.', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68348&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68349&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68350&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68351&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68352&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.60690150, 126.97715090, 'ENP011117', NULL, NULL),
	(11, 'Digital Media City', 'https://english.visitseoul.net/attractions/Digital-Media-City/ENP011142', 'Digital Media City (DMC) is an IT and media industry cluster located in Mapo-gu, housing numerous headquarters of major domestic corporations. Currently, it hosts the three major terrestrial broadcasters KBS, MBC, and SBS, along with cable channels like YTN, Channel A, and JTBC, and newspapers such as Dong-A Ilbo and JoongAng Ilbo. Additionally, the Korean Film Archive, the nation\'s only film archive equipped with Korean movie films and related materials, is located there. This makes DMC a hub for the production of Hallyu content. Furthermore, the area is surrounded by various renowned restaurants, making it a recommended tourist destination for those interested in K-media.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Digital Media City", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "12" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "JHL" }, "reviewBody": "This area is the complex of broadcast centers. While walking on broad roads you can watch various art works frequently seen on TV news.With restaurants and cafés, it\'s not a bad place for a half day trip. Also, World Cup Park which is a huge park area including the famous Haneul Park is close.", "datePublished": "2020-05-29" }] }', '', '', '', '366, World Cup buk-ro, Mapo-gu, Seoul', 'Subway Line 6/Gyeongui-Jungang Line/Airport Railroad, Digital Media City Station, Exit 9, 520', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18018&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18019&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18020&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18021&fileTy=MEDIA&fileNo=3&thumbTy=L', 4, 37.57773060, 126.89211520, 'ENP011142', NULL, NULL),
	(12, 'Banpodaegyo Bridge Moonlight Rainbow Fountain', 'https://english.visitseoul.net/attractions/Banpodaegyo-Bridge-Moonlight-Rainbow-Fountain/ENP002220', 'Banpodaegyo Bridge is a two-tiered bridge over the Han River that features the Moonlight Rainbow Fountain, (the world??s longest bridge fountain recognized by the Guinness Book of World Records) with 380 water jets and a dazzling array of multi-colored lights. The Moonlight Rainbow Fountain??s water jets are dynamic and can move in time to music creating spectacular ever-changing displays. Add to that the hundreds of rainbow-colored lighting combinations when night falls, and it is easy to see why Banpodaegyo Bridge is a magnet for tourists year round.   The Moonlight Rainbow Fountain operates from April to October every year, however the schedule of the fountain shows varies from month to month. Each fountain show lasts 20 minutes. In addition, Banpo Hangang Park hosts the "Moonlight Square Cultural Weekend" event every Saturday from 7:00 - 8:30 p.m. from May to October, featuring a variety of musical styles including classical music with commentary, acappella, popera, jazz, brass bands and orchestras.    Frequently Asked Questions about Banpo Bridge Rainbow Fountain         What are Banpo Bridge Rainbow Fountain\'s operating hours?         The Banpo Bridge Rainbow Fountain operates in an increment of 20 minutes, and the operating hours are as follows. (As of 2024)     ??Low season (April-June, September-October): 12:00, 19:30, 20:00, 20:30, 21:00   ??Peak season (July-August): 12:00, 19:30, 20:00, 20:30, 21:00, 21:30   ??Fountain operation may be suspended depending on weather conditions (rain, strong wind) and the number of visitors in the park. (Fountain shutdown conditions: When predicting precipitation during the fountain\'s operating hours (??In the case of a clear day after rain, the facility will be inspected and operated when there are no abnormalities (to prevent malfunction due to humidity), when there is a strong wind of 7m/s or more, and when the opacity of the Han River is 15NTU or more)           What kind of music plays when Banpo Bridge Rainbow Fountain is in operation?         You can check the details of the Banpo Bridge Rainbow Fountain music production on the page below. (As of 2022)    Banpo Bridge Rainbow Fountain Song Information           Where is the Banpo Bridge Rainbow Fountain parking lot?         The parking lots near Banpo Bridge Rainbow Fountain are as follows. Please check the following website for parking rates and real-time parking availability.     ??Banpo 1 Parking Lot (122-1 Jamwon-dong, Seocho-gu, Seoul)   ??Banpo 2 and 3 parking lot (115-5 Banpo-dong, Seocho-gu, Seoul)    Banpo 1-3 Parking Information       { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "What are Banpo Bridge Rainbow Fountain\'s operating hours?", "acceptedAnswer": { "@type": "Answer", "text": "<div>The Banpo Bridge Rainbow Fountain operates in an increment of 20 minutes, and the operating hours are as follows. (As of 2024)<br><br> <ul> <li> Low season (April-June, September-October): 12:00, 19:30, 20:00, 20:30, 21:00</li> <li> Peak season (July-August): 12:00, 19:30, 20:00, 20:30, 21:00, 21:30</li><br> ??Fountain operation may be suspended depending on weather conditions (rain, strong wind) and the number of visitors in the park. (Fountain shutdown conditions: When predicting precipitation during the fountain\'s operating hours (??In the case of a clear day after rain, the facility will be inspected and operated when there are no abnormalities (to prevent malfunction due to humidity), when there is a strong wind of 7m/s or more, and when the opacity of the Han River is 15NTU or more) </ul> </div>" } }, { "@type": "Question", "name": "What kind of music plays when Banpo Bridge Rainbow Fountain is in operation?", "acceptedAnswer": { "@type": "Answer", "text": "<div>You can check the details of the Banpo Bridge Rainbow Fountain music production on the page below. (As of 2022)<br><br> <a href=\\"https://hangang.seoul.go.kr/www/contents/856.do?mid=849"style=\\"color:#0000EE;text-decoration: underline\\">Banpo Bridge Rainbow Fountain Song Information</a> </div>" } }, { "@type": "Question", "name": "Where is the Banpo Bridge Rainbow Fountain parking lot?", "acceptedAnswer": { "@type": "Answer", "text": "<div> The parking lots near Banpo Bridge Rainbow Fountain are as follows. Please check the following website for parking rates and real-time parking availability.<br><br> <ul> <li> Banpo 1 Parking Lot (122-1 Jamwon-dong, Seocho-gu, Seoul)</li> <li> Banpo 2 and 3 parking lot (115-5 Banpo-dong, Seocho-gu, Seoul)</li><br> <a href=\\"https://www.ihangangpark.kr/parking/region/region5\\"style=\\"color:#0000EE;text-decoration: underline\\">Banpo 1-3 Parking Information</a> </ul> </div>" } }, { "@type": "LocalBusiness", "name": "Banpo Bridge Rainbow Fountain", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "3.5", "ratingCount": "265" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Haliza Ali" }, "reviewBody": "I felt that this is a good way to enjoy and observe how the local spends their weekend. I was there on Saturday night - very lovely atmosphere - good flea market of handmade stuff, tattooist, good food and beautiful light show by the bridge.", "datePublished": "2022-07-14" } }] }', '-4278', '* Off Season [April - June & September - October]\n12:00, 19:30, 20:00, 20:30, 21:00 (20 mins)\n* Peak Season [July - August]\n12:00, 19:30, 20:00, 20:30, 21:00, 21:30 (20 mins)', '', '06500  Banpo-dong, Seocho-gu, Seoul', 'Subway Lines 3/7/9  Express Bus Terminal Station  Exit 8-1,  1.1km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=15772&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12908&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1383&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.50858630, 126.99026410, 'ENP002220', NULL, NULL),
	(13, 'Jahamun Tunnel', 'https://english.visitseoul.net/attractions/Jahamun-Tunnel/ENP037158', 'Jahamun Tunnel is a tunnel connecting Cheongdong and Buam-dong in Seoul, and was featured as a filming site for the movie "Parasite." In the movie, this is where Ki-taek and his family pass through in the pouring rain. This small scene has caused Jahamun Tunnel to attract countless tourists and movie fans.', '', '', '', '03022  219, Jahamun-ro, Jongno-gu, Seoul, Korea (Buam-dong)', 'Subway Line 3 Gyeongbokgung Station Exit 3, take bus number 1020, 7022, or 7212, and get off at Buam Community Center,  650m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40989&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40990&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40991&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75392&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75393&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.59114700, 126.96210990, 'ENP037158', NULL, NULL),
	(14, 'Seoullo 7017', 'https://english.visitseoul.net/attractions/Seoullo-7017/ENP023496', 'Seoullo 7017 is an elevated sky garden that is a popular walking destination and tourist spot in the center of Seoul. Originally a highway overpass, it has since been transformed into a pedestrian walkway for the general public to enjoy. Seoullo\'s name is a nod to its original foundation in 1970 and its rebirth in 2017 as a sky garden. There are also 17 pedestrian pathways that allow visitors to walk through several local communities. Seoullo 7017 offers several rest areas, greenery, and cultural experiences at 1 kilometer above street-level.', '-7250', 'Open 24 hours', 'Open year round', '04509  432, Cheongpa-ro, Jung-gu, Seoul   (Bongnae-dong 2-ga, KORAIL Seoul Headquarters)', 'Subway Line 1/4/Gyeongui-Jungang Line/AREX, Seoul Station  Exits Exit 7,  148m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42213&fileTy=MEDIA&fileNo=6&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42214&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42274&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42273&fileTy=MEDIA&fileNo=8&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42275&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.55767410, 126.96974050, 'ENP023496', NULL, NULL),
	(15, 'ChoiManLin Museum', 'https://english.visitseoul.net/attractions/ChoiManLin-Museum/ENP042352', 'Theelegant two-story, Western-style building was built in the 1970s. Here,sculptor Choi Man Lin created his world of art for about 30 years from 1988. Evenwith all its traces of artistry intact, it eventually grew to become the ChoiMan Lin Museum with the help of the Seongbuk-gu District and EMA Architects. Reborn as an art museum in2019, this building contains the traces of sculptor Choi Man Lin, which werepreserved through a remodeling method that protects the appearance of theexisting building as much as possible. Thisbuilding, which shows off its architectural beauty while maximizing itsfunction as an art museum, won the Excellence Award at the 2020 Public BuildingAwards of Korea.', '-11888', 'Daily 10:00 ~ 18:00\nClosed for exhibition preparation (July 1 - September 3)', 'Closed Sundays & Mondays', '02708  23, Solsaem-ro 7-gil, Seongbuk-gu, Seoul', 'Subway Uisinseol   Bukhansanbogukmun Station Exit 2,  438m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56158&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56159&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56160&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56161&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56162&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61067350, 127.00432190, 'ENP042352', NULL, NULL),
	(16, 'Myeongdong Jaemi-ro', 'https://english.visitseoul.net/attractions/2024-jaemiro/ENPhvgb2b', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Jaemi-ro is a comic street located in Myeongdong, Jung-gu. It is a content-specialized street within Sangsang Town\'s cultural content clustering, centered around the former Seoul Animation Center (currently undergoing reconstruction). It\'s a themed street stretching approximately 450m from Exit 3 of Myeongdong Station to the former Seoul Animation Center, adorned with Korean comics, animations, characters, illustrations, and other content. Jaemi-ro, connecting the iconic tourist spots of Seoul, Myeongdong, and Namsan Mountain, offers a valuable experience where visitors can enjoy diverse cultural experiences within the heart of Seoul\'s downtown area.', '', '', '', '04631  24, Toegye-ro 20-gil, Jung-gu, Seoul, Republic of Korea', 'Subway Line 3  Myeongdong Station  Exit 3,  196m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64814&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64815&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64816&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64817&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.55922790, 126.98558280, 'ENPhvgb2b', NULL, NULL),
	(17, 'Kim Joong-up House of Architectural Culture', 'https://english.visitseoul.net/attractions/Kim-Joong-up-House-of-Architectural-Culture/ENP042446', 'Built in the 1970s, this two-story detached house was remodeled in 1986 by Kim Joong-up, who added exotic elements to every corner of the house based on traditional Korean architecture. This is a place where you can get a glimpse of the housing culture of the middle class at the time, and was designated as a Seoul Future Heritage in 2017. The KimJoong-up House of Architectural Culture harmoniously integrates Korean and Western architectural styles. The second-floor living room has an umul-maru, rafter structure, and windows covered with changhoji paper, which are mainly used in hanok, but with a modern interpretation. In contrast, the bathroom was designed in a European style. The dry bathroom with a dressing room attached, something that wasn??t common in Korea during the \'70s and \'80s, has a vintage jade-colored interior that stands out. Stepping out to the elegantly decorated garden, a water element, a characteristic of Kim Joong-up\'s architecture, is located on one side of the yard. Even equipped with its own small greenhouse, the Kim Joong-up House of Architectural Culture contains immense nature in the garden.', '-9962', 'Daily 10:00 ~ 17:00', 'Closed Sundays & Mondays', '02755  11, Jangwi-ro 21na-gil, Seongbuk-gu, Seoul', 'Subway Line 6, Dolgoji Station, Exit 2,  1.5km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56688&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56689&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56690&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56691&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56692&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61498240, 127.04408770, 'ENP042446', NULL, NULL),
	(18, 'Night Views at Haneul Park', 'https://english.visitseoul.net/attractions/NightViewsatHaneulPark/ENP016322', 'Of the five parks within the World Cup Park system in Mapo-gu, Haneul Park is the most beloved and popular. Haneul is the Korean word for "sky" and the park was dubbed Haneul Park because it has the highest elevation of the five parks. The area was once a landfill, but the park was subsequently transformed into an ecological park. Haneul Park is famous for its fields of tall pampas grass, sunset views, and night views of Seoul. The park is also popular as a date spot and as a location for photo shoots.', '-5721', 'Daily, 05:00 to 20:30\n* For more details, please refer to our website', '', '03900  95, Haneulgongwon-ro, Mapo-gu, Seoul', 'Subway Line 6  World Cup Stadium Station  Exit 1,  803m to the Toad Train Ticket Office. \nSubway Line 6  World Cup Stadium Station  Exit 1,  1.9 km to Sky Park.', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68310&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68311&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68312&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68313&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56710360, 126.88692960, 'ENP016322', NULL, NULL),
	(19, 'Gwanghwamun Square at Night', 'https://english.visitseoul.net/attractions/GwanghwamunSquareatNight/ENP016319', 'Gwanghwamun Square is located on Sejong-ro in Jongno-gu and is vast in size. Gwanghwamun Square stretches out from Gwanghwamun Gate, towards Cheonggyecheon Stream, and is divided into 6 sections: ??Recovering the History of Gwanghwamun Gate Plaza,????Reenacting Yukjo Street Plaza,????Korea Main Plaza,????Civil Participation Urban Culture Plaza,????Downtown Plaza??and ??Cheonggyecheon Stream Connector.?? ??      The focal point of the square is the statue of King Sejong the Great. During the day, the square is always busy with people but at night it is a tranquil and beautiful tourist attraction. Gwanghwamun Square, with Inwangsan Mountain just behind it, is not just a beautiful tourist locale. The square has over 600 years of history and it is a place where the spirit of the Korean nation can be felt.      For more information:    Gwanghwamun Square       The Story of King Sejong ??The Story of Admiral Yi   Sunshin', '-10560', '', '', '03154  172, Sejong-daero, Jongno-gu, Seoul', 'Subway Line 5  Gwanghwamun Station  Exit 2,  235m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8799&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8802&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8801&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8800&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57169170, 126.97764920, 'ENP016319', NULL, NULL),
	(20, 'COEX', 'https://english.visitseoul.net/attractions/Coex-convention-center-en/ENP024663', 'COEX is renowned for hosting large-scale exhibitions, international conferences, global convention center operations, and digital media promotional consulting. It hosts various expos centered around food, culture and arts, global issues, energy, and mobility. Additionally, several major summits in Seoul are held at COEX, offering extensive services. The squares and indoor lobby spaces around COEX also conduct various promotions, providing diverse experiences for the foot traffic between Samseong Station and Bongeunsa Station, as well as for exhibitions, COEX Mall, and Parnas Mall visitors.  { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "COEX", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "196" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Anthony Cordato" }, "reviewBody": "Coex Seoul is a massive, cavernous conference center situated on the south side of the Han River. Underneath is Stanfield", "datePublished": "2020-02-29" }] }', '-7041', '', '', '06164  513, Yeongdeung-daero, Gangnam-gu, Seoul (COEX)', 'Subway Line 2 Samseong Station Exit 6, 273m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72651&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72652&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72653&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72654&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72655&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.51168280, 127.05915100, 'ENP024663', NULL, NULL),
	(21, 'Hyundai Card MUSIC LIBRARY,  Hyundai Card VINYL & PLASTIC', 'https://english.visitseoul.net/attractions/hyundaicard-musiclibrary-hyundaicard-vinyl-and-plastic/ENPtvunyc', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Hyundai Card MUSIC LIBRARY is a space to purchase over 10,000 vinyl records carefully selected by genre. It also features turntables and CD players, allowing visitors to listen to their chosen vinyl records on the spot.Hyundai Card VINYL & PLASTIC is an LP record store where you can buy LPs, CDs, and more. The store showcases turntables and CD players, providing a hands-on experience. Eight listening zone tables are available, allowing you to listen to three albums for 30 minutes on weekdays and two albums for 20 minutes on weekends. Keep this in mind when planning your visit.', '-6551', 'Tuesday to Saturday: 12:00 ??21:00 / Sunday and Public Holidays: 12:00 ??18:00', 'Closed during the Lunar New Year and Chuseok holidays', '04400  246, Itaewon-ro, Yongsan-gu, Seoul', 'Subway Line 6, Hangangjin Station, Exit 3,  411m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65759&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65760&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65761&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65762&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65763&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53598200, 127.00140430, 'ENPtvunyc', NULL, NULL),
	(22, 'Fall Foliage Road (World Cup-ro)', 'https://english.visitseoul.net/attractions/Fall-Foliage-Road-World-Cup-ro/ENP038858', 'World Cup-ro, which stretches along Nanjicheon Park, is a great place to take a walk surrounded by endless trees and green park views on both sides. Especially in autumn, the colorful fall leaves starting from World Cup Stadium intersection to Guryong intersection make the road even more beautiful.', '', '', '', '03906  9-1, World Cup-ro 42-gil, Mapo-gu, Seoul   (Street Sales Stand 07)', '', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=45402&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=45403&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=45404&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.57948900, 126.88094560, 'ENP038858', NULL, NULL),
	(23, 'Choong Ang High School', 'https://english.visitseoul.net/attractions/ChoongAngHighSchool/ENPgcblme', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}It is the first private school in the Republic of Korea, established in 1908 during the Japanese colonial period to save and establish the country through education. The school actively participated in national movements such as the March 1st Movement during the Japanese colonial period, the June 1st Movement, and the Gwangju Student Movement. Monuments commemorating the March 1st Movement and the June 10th Movement are erected, allowing visitors to reflect on history. Additionally, the school is famous for its exotic architectural style and is a popular tourist destination, as it was a filming location for the drama ??Winter Sonata.??,-1983,,,03051  164 Changdeokgung-gil', ' Jongno-gu', ' Seoul"', 'Subway Line 3  Anguk Station  Exit 3,  713m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64774&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64772&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64771&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64773&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75735&fileTy=MEDIA&fileNo=1&thumbTy=L', '5', '37.5848813', 127, 0.00000000, 0.00000000, 'ENPgcblme', NULL, NULL),
	(24, 'Kim Geun-tae Memorial Library-Archives', 'https://english.visitseoul.net/attractions/Kim-Geun-tae-Memorial-Library-Archives/ENP041903', 'Kim Geun-tae Memorial Library-Archives which is located at the corner of the way going to Bukhansan National Park, as a Larchiveum, it is a library to read a book but at the same time, it\'s a museum that has a story of democracy and human rights, and also an art gallery to appreciate art works. A courtyard, which was naturally made at the center which was created by connecting the both ends of the two buildings with the bridge, is the most opened space in Kim Geun-tae Memorial Library-Archives and it\'s a space where you can directly feel the sunlight and the wind. As a library and an art gallery, the installation work is located on the courtyard so you can see an art work in the nature. At the rooftop called \'Sanbaramgil\',  various plays and events will be held with the background of the nature.', '-3976', 'Daily 09:00 ~ 20:00\nWeekends 09:00 ~ 17:00', 'Every Monday, National Holiday', '01301  14, Dobongsan-gil, Dobong-gu, Seoul', 'Subway Line 1/7   Dobongsan Station  Exit 1,  300m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54699&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54700&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54701&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54702&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54703&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.69050520, 127.04233880, 'ENP041903', NULL, NULL),
	(25, 'Bukchon Hanok Village', 'https://english.visitseoul.net/attractions/Bukchon-Hanok-Village/ENP000261', 'Bukchon Hanok Village reflects 600 years of Seoul??s history. The village is situated between Gyeongbokgung Palace and Changdeokgung Palace, and its streets are lined with traditional hanok. Unlike other hanok villages (such as Namsangol Hanok Village), Bukchon was not created for tourists and it is a residential village inhabited by Seoulites. The best place within Bukchon to experience the old hanok atmosphere may be Gaehoe-dong. Here, hundreds of hanok sit shoulder to shoulder. Bukchon Hanok Village has been loved by many as a travel destination in Seoul as the charm of the traditional hanok is being rediscovered. There are also art galleries, traditional workshops, and restaurants that have been built out from from hanok, making these spaces both traditional and unique. In the Bukchon Hanok Village, which holds history and culture from time past in every alley, the Bukchon Cultural Center delivers information and cultural context for these traditional and historic spaces.             ??Measures to Take When Visiting Bukchon Hanok Village ??Due to the designation of Bukchon as a Special Management Area (Red Zone), tourist visiting hours will be restricted starting in November 2024. Please refer to the link below for more details.  View more??     ?? Bukchon Hanok Village is a prominent residential area in Seoul, densely populated with hanoks where residents live.    Please keep this in mind and refrain from the following actions. We ask for your cooperation in practicing ??silent tourism.?? - Please keep noise levels to a minimum, (e.g. no loud voices, horsing around, filming, etc.) especially in the 31 Gahoe-dong area    - Please do not litter    - Please keep group visits small, with a maximum of 10 visitors    - Please do not use microphones, megaphones, or loudspeakers    - Please do not take photos or film the interiors of houses, even if the doors are open       The cultural tours of the Bukchon Hanok Village area, (Gahoe-dong 31, 33, etc.) will be phased out. Please keep that in mind when taking the Seoul City Walking tours.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Bukchon Hanok Village", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "5338" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Arielle P" }, "reviewBody": "Hanok village with old Seoul charms. Always one of my favorite places to See traditional artisanal shops and get iconic views of Seoul.", "datePublished": "2024-08-29" }] }', '-3425', '10:00 ~ 17:00 (Restricted Hours: 17:00 ~ 10:00 the following day; visitors are prohibited from entering restricted areas during these hours)\n(The Hanok Village is a residential space for local citizens before it is a tourist attraction.)', '', '03059  37, Gyedong-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 3,  516m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42685&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42686&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42690&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66971&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72459&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57833390, 126.98613630, 'ENP000261', NULL, NULL),
	(26, 'Namsan Seoul Tower', 'https://english.visitseoul.net/attractions/Namsan-Seoul-Tower/ENP000036', 'Namsan Seoul Tower, which has established itself as a romantic island in the heart of the city, is a 236.7-meter-tall tower located at the summit of Namsan Mountain (262m), a place long regarded as a site of good fortune for lifelong love. Offering a breathtaking 360-degree panoramic view of Seoul from an elevation of 480 meters above sea level, it boasts the best vantage point in the city. As a symbol of Seoul and the top tourist destination chosen by international visitors, it has become a romantic sanctuary for couples worldwide who dream of eternal love. Popular attractions for couples include the "Locks of Love" and "Heart Chair," which are widely appreciated.    Namsan Seoul Tower comprises two main sections: the Lower Seoul Tower Plaza and the Upper N Seoul Tower. The Seoul Tower Plaza spans from the 1st to the 4th floor and includes attractions such as Gallery K, the Bodyfriend Lounge, and the Game Plaza. Visitors can also enjoy media art installations on a large 55-inch OLED panel. From the 5th floor up to the T7 floor, the N Seoul Tower features observation decks, the N Gift Shop, and various restaurants and cafes, all open 365 days a year.    Frequently Asked Questions about Namsan Seoul Tower        Can I visit Namsan Seoul Tower on national holidays or regular holidays?         Yes. The Namsan Seoul Tower is open 365 days a year. (As of 2024)          Can I visit Namsan Seoul Tower with my pet?         Pets are not allowed at the Namsan Seoul Tower. (As of 2024)          What are the operating hours of the Namsan Seoul Tower Cable Car and how much is it?         Namsan Seoul Tower Cable Car operates from 10 am to 11 pm. The ticket prices are as follows. (As of 2025)   ??Round-trip fare: Adults 15,000 KRW / Children 11,500 KRW  ??One-way fare: Adults 12,000 KRW / Children 9,000 KRW  (Children: From 36 months to elementary school students)     { "@context": "https://schema.org", "@graph": [{ "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "Can I visit Namsan Seoul Tower on national holidays or regular holidays?", "acceptedAnswer": { "@type": "Answer", "text": "<div>            Yes. The Namsan Seoul Tower is open 365 days a year. (As of 2022)          </div>" } }, { "@type": "Question", "name": "Can I visit Namsan Seoul Tower with my pet?", "acceptedAnswer": { "@type": "Answer", "text": "<div>            Pets are not allowed at the Namsan Seoul Tower. (As of 2022)          </div>" } }, { "@type": "Question", "name": "What are the operating hours of the Namsan Seoul Tower Cable Car and how much is it?", "acceptedAnswer": { "@type": "Answer", "text": " <div>            Namsan Seoul Tower Cable Car operates from 10 am to 11 pm. The ticket prices are as follows. (As of 2024)            <br>                      <br>            ??Round-trip fare: Adults 15,000 KRW / Children 11,500 KRW            <br>            ??One-way fare: Adults 12,000 KRW / Children 9,000 KRW            <br>            (Children: From 36 months to elementary school students)          </div>" } }] }, { "@type": "LocalBusiness", "name": "Namsan Seoul Tower", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4", "ratingCount": "9465" } }] }', '-12652', 'Weekdays 10:00-22:30, Weekends 10:00-23:00\n*Last entry 30 minutes before close', '', '04340  105, Namsangongwon-gil, Yongsan-gu, Seoul, Korea  (Yongsan-dong 2-ga, YTN Seoul Tower)', 'Subway Line 3/4 Chungmuro Station Exit 2,  take Bus 01 (Namsan Circular), get off at \'Namsan Seoul Tower\' stop, 357m\nSubway Line 3 Dongdaemun Station Exit 6,  take Bus 01 (Namsan Circular), get off at \'Namsan Seoul Tower\' stop, 357m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68274&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68275&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65754&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65755&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72447&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55116940, 126.98822660, 'ENP000036', NULL, NULL),
	(27, 'National Assembly Building', 'https://english.visitseoul.net/attractions/National-Assembly-Building/ENP005763', 'The National Assembly Building houses Korea\'s legislative branch of government and it is located in Yeouido. The building represents the democracy and human rights of Korea. The National Assembly Library is located to the right of the main building, and the Assembly Members??Office Building is located to the left. Free tours of the National Assembly are available, but reservations are required. Visitors must reserve a tour date at least three days in advance of the desired visit date.', '-8822', 'Weekdays: 10:00 AM - 17:00 (Entry available at 10:00, 11:00, 14:00, 15:00, 16:00, and 17:00.; Maximum 150 people per session)  \nSaturdays: 10:00 - 12:00 (Entry available at 10:00, 11:00, and 12:00; Maximum 150 people per session)', 'Closed Sundays, holidays & May 31st', '07233  1, Uisadang-daero, Yeongdeungpo-gu, Seoul', 'Subway Line 9  National Assembly Station  Exit 1,  438m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68371&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68372&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68373&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68374&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68375&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53105820, 126.91538160, 'ENP005763', NULL, NULL),
	(28, 'Dongdaemun Design Plaza (DDP)', 'https://english.visitseoul.net/attractions/Dongdaemun-Design-Plaza-en/ENP024679', 'The Dongdaemun Design Plaza (DDP), planned by Seoul City Hall in 2006, opened its doors on March 21, 2014. The purpose of DDP is to utilize design thinking for innovation and development. It also showcases global design trends and design innovation as a birthplace of creative knowledge in the 21st century. As a multi-purpose cultural space, Dongdaemun Design Plaza has been hosting various cultural events since its opening, including exhibitions, fashion shows, new product launches, forums, and conferences. Additionally, the seasonal Seoul Light event transforms DDP\'s exterior walls into a curved silver canvas, offering diverse scenery.        Frequently Asked Questions about Dongdaemun Design Plaza (DDP)         Who can access the Dongdaemun Design Plaza (DDP)?         The Dongdaemun Design Plaza (DDP) is a cultural complex open to all citizens. Not only designers but also students who study design and culture and ordinary citizens, anyone can access it.          Are there lockers at Dongdaemun Design Plaza (DDP)?         For storing items, you can use the paid lockers near Subway Exit 1, on the first floor of the Design Lab, and inside the Art Hall. (As of 2024, specific locations may change)          How much is parking at Dongdaemun Design Plaza (DDP)?         The parking fee at Dongdaemun Design Plaza (DDP) is 400 KRW per 5 minutes (4,800 KRW per hour), with a daily maximum of 50,000 KRW. (As of 2024)     { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "Who can access the Dongdaemun Design Plaza (DDP)?", "acceptedAnswer": { "@type": "Answer", "text": "<div>The Dongdaemun Design Plaza (DDP) is a cultural complex open to all citizens. Not only designers but also students who study design and culture and ordinary citizens, anyone can access it.</div>" } }, { "@type": "Question", "name": "Are there lockers at Dongdaemun Design Plaza (DDP)?", "acceptedAnswer": { "@type": "Answer", "text": "<div>For storing items, you can use the paid lockers near Subway Exit 1, on the first floor of the Design Lab, and inside the Art Hall. (As of 2024, specific locations may change) </div>" } }, { "@type": "Question", "name": "How much is parking at Dongdaemun Design Plaza (DDP)?", "acceptedAnswer": { "@type": "Answer", "text": "<div>The parking fee at Dongdaemun Design Plaza (DDP) is 400 KRW per 5 minutes (4,800 KRW per hour), with a daily maximum of 50,000 KRW. (As of 2024)</div>" } }, { "@type": "LocalBusiness", "name": "Dongdaemun Design Plaza (DDP)", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4", "ratingCount": "2209" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Traveller of the world" }, "reviewBody": "Yes, the structure is stunning. Amazing architecture. Great atmosphere and lot\'s going on. However, expected more in terms of exhibitions. This changes throughout the year. Some boutique shops inside and eateries. I just think they could have made better use of the indoor space. Clean and well kept. Definitely recommend going.      ", "datePublished": "2022-05-30" } }] }', '-2073', '10:00-20:00 KST (Vary by space, see the website)', '', '04566  281, Euljiro, Jung-gu, Seoul (Euljiro 7-ga)', 'Subway Lines 2/4/5, Dongdaemun History & Culture Park Station  Exit 1,  37m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68049&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68050&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68051&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68052&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68053&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56602860, 126.99549240, 'ENP024679', NULL, NULL),
	(29, 'Changsin-dong\'s Cliff Village', 'https://english.visitseoul.net/attractions/2024-changsincliff/ENPgvo4y2', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Changsin-dong Cliff Village, located in Changsin 1, 2, and 3-dong in Dongdaemun-gu, Seoul, has undergone various transformations over the years. It was a quarry village in the 1960s, a wooden village in the 1970s, a sewing factory in the 1990s, and finally a sewing village in the 2000s. It is situated around the rocky cliffs once used as the nation\'s only quarry. Changsin-dong Cliff Village is divided into densely packed, dilapidated, aged homes built on cliffs and precipices and homes formed beneath rocky hills.*Please Note: When visiting, please refrain from making excessive noise, as actual residents live there.', '', '', '', '03091  23-322 Changsin-dong, Dongdaemun-gu, Seoul', 'Subway Line 6  Changsin Station  Exit 1,  708m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64706&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64707&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64708&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64709&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64710&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57854440, 127.01136710, 'ENPgvo4y2', NULL, NULL),
	(30, 'Hangang River Bus', 'https://english.visitseoul.net/attractions/HanRiverBus/ENPmluo32', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Seoul City operates the Hangang River Bus, a differentiated transportation method that anyone can experience in daily life, newly introduced to ensure convenience and leisure for the future of Seoul. Hangang River Bus offers new water transportation that bypasses urban congestion, serving as both a means of transportation and a tourism attraction by providing opportunities to enjoy the Hangang River and connect with local attractions. To establish landmark positioning, we plan to organize and attract events that suit the seasonal and location-specific characteristics. Please try the new Hangang River Bus, a public transportation service beloved by people worldwide. ?? For safety operation inspections, trial runs without passengers will be conducted for one month starting from September 29.', '-5573', 'Weekdays (68 trips daily) 6:30 AM-10:30 PM / Weekends (48 trips daily) 9:30 AM-10:30 PM\nExpress route weekdays 16 trips daily *Weekday commute (6:30 AM-9:00 AM), after work (6:00 PM-8:30 PM)', '', '05500  1-2 Jamsil-dong area, Jamsil Pier, Songpa-gu, Seoul', 'Subway Line 2 Jamsil Saenae Station Exit 7, 1km\nLines 2/8 Jamsil Station Exit 5, 2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74399&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74400&fileTy=MEDIA&fileNo=1&thumbTy=L', 2, 37.52004560, 127.08282140, 'ENPmluo32', NULL, NULL),
	(31, 'Herb Astronomy Park', 'https://english.visitseoul.net/attractions/HerbAstronomyPark/ENP037130', 'Iljasan Herb Astronomical Park, located in Dunchon-dong, Gangdong-gu, Seoul, is an intimate park that is popular for enjoying nature. There is an astronomical observatory that can be used 24 hours a day. Additionally, as the name may entail, there are fresh herbs that grow around the park making it a fragrant space where you can feel relaxed while walking or jogging along the well-maintained trails. After dark, you can see hundreds of tiny lights that illuminate the space, making it even more beautiful.', '', '', '', '134-060  86 Dunchon-dong, Gangdong-gu, Seoul, South Korea', 'Subway Line 9  VHS Medical Center Station  Exit 3,  Take the blue bus 342 or the green bus 2312 ??get off at the Gildong Natural Ecology Park,  296m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40385&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40386&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40384&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40383&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40381&fileTy=MEDIA&fileNo=3&thumbTy=L', 5, 37.53023040, 127.14376030, 'ENP037130', NULL, NULL),
	(32, 'N Seoul Tower at Night', 'https://english.visitseoul.net/attractions/NSeoulToweratNight/ENP016321', 'N Seoul Tower is one of Seoul\'s most famous landmarks and one of the city\'s most beloved attractions. The views from the tower are beautiful but the night views are especially breathtaking. Visitors can take in incredible panoramic views of Seoul from the tower\'s observatory. The tower has been used as a filming location in many Korean TV shows and movies. One of the tower\'s attractions is the locks of love that visitors fasten to Namsan\'s iron railings.      For more information:    N    Seoul Tower     Namsan Park', '-12652', '10:00-22:30', 'Open year round', '04340  105, Namsangongwon-gil, Yongsan-gu, Seoul', 'Subway Lines 3/4  Chungmuro Station or Subway Line 3  Dongguk University Station. Take Circular Bus No. 01 (Namsan Circular) ??get off at the "Namsan Seoul Tower" stop ??walk 357m (8-minute walk)\n\nTake the Seoul City Tour Bus ??get off at the "N Seoul Tower" stop.', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8809&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72914&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72915&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72916&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.54894190, 126.98940410, 'ENP016321', NULL, NULL),
	(33, 'Figure and Ground', 'https://english.visitseoul.net/attractions/Figure-and-Ground/ENP042255', 'Figure and Ground is dressed in red brick, a material commonly used in architecture, but the exterior is wrapped in thin strips going around the building that exudes intense sophistication. It is even more meaningful in that it is a reconstruction of the original form of the 30-something-year-old building that once stood in its place. With a cafe and a boutique on the lower floors and a shared office on the upper floors coexisting in one building, Figure and Ground is buzzing on weekdays and weekends, day and night.', '', 'Ground level café, Conflict Store : Daily 10:00 ~ 22:00', '', '06036  53, Nonhyeon-ro 153-gil, Gangnam-gu, Seoul', 'Subway Line 3/Shinbundang Line  Sinsa Station  Exit 8,  541m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=55789&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=55790&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=55791&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=55792&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=55793&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52016220, 127.02394880, 'ENP042255', NULL, NULL),
	(34, 'Gwanghwamun Square', 'https://english.visitseoul.net/attractions/Gwanghwamun-Square/ENP001899', 'King Taejo of the Joseon Dynasty moved the capital to Hanyang in 1394 and built Gyeongbokgung Palace, the official residence of the Joseon Dynasty. In addition, on both sides of the road in front of the palace??s main gate, the Street of Six Ministries, including Uijeongbu (State Council), was built. It was the best road in Hanyang. In 2009, that road opened again. Gwanghwamun Square and Cheonggye Plaza were built. The square is mostly ??a square that restores the history of Gwanghwamun,????a square that recreates the scenery of the Street of the Six Ministries,????an emblematic square of Korea,????an urban culture square where citizens mingle,????a square in the city center,??and ??a connection to the Cheonggyecheon Stream.??It functions as a space for history, culture, and relaxation. The focal point of this emblematic square in Korea is the statue of King Sejong the Great. The ??downtown square??around the statue of Admiral Yi Sun-sin is also a space appreciated by city dwellers. In addition, artificial ponds and fountains are installed to cool off people from the summer heat. Also, the Haechi statue and Grass Plaza, which are symbols of Seoul, were also created.', '-40', 'Open 24 hours a day, throughout the year, as a city square', 'Open year-around', '03172  B 175, Sejong-daero, Jongno-gu, Seoul, Korea (??종??? ??종??야???', 'Subway Line 5  Gwanghwamun Station  Exit 2,  235m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66716&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66717&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66718&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66719&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57223560, 126.97593380, 'ENP001899', NULL, NULL),
	(35, 'Seoul Sky', 'https://english.visitseoul.net/attractions/SeoulSky/ENPowtoyc', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Located on the top floor of Lotte World Tower in Jamsil, Seoul Sky (5th highest in the world, 500 M) is the highest point in South Korea that offers a 360-degree view of Seoul??s dazzling beauty. From 500 meters in the sky, visitors can admire the city??s diverse charms as they change from day to night and throughout the four seasons. Moreover, Seoul Sky also features thrilling experiential attractions, a variety of exhibition content, a café where visitors can relax with a cup of coffee, and a range of tower-themed souvenirs, making it an ideal spot to create lasting experiences and memories.', '-3581', 'Sun-Thu: 10:30-22:00, Fri-Sat: 10:30-23:00 KST', '', '05551  300, Olympic-ro, Songpa-gu, Seoul (117-123F)', 'Subway  Line 2/8  Jamsil Station   Exit 2,  311m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60808&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60809&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60810&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60811&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60812&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.51310080, 127.10343340, 'ENPowtoyc', NULL, NULL),
	(36, 'Graphic', 'https://english.visitseoul.net/attractions/Graphic/ENP042288', 'The building is in the shape of white cylinders stacked in layers with some cut-out sections, alomost like a multi-tiered cake covered in whipped cream. It is almost impossible to guess the purpose of this three-story high windowless building just by looking at it from the outside. Despite the mysterious appearance from afar, with a closer look one can see the bumpy lines that run vertically along the structure\'s facade. These lines represent the grain of a book\'s pages, implying Graphic\'s identity as a bookstore. Just like the mysterious exterior, the interior is surrounded    by magnificent walls that makeit impossible to guess the interior space is also secretive. Approximately 100new books are brought in every month, providing a new experience each time you visit.    The fact that only adults overthe age of 19 are allowed to enter makes the space even more secretive. A spacewhere you can read books without time constraints becomes a haven for one toshake off the weariness of life while having a light drink with a book.', '-4262', 'Tuesday to Friday: 13:00 -23:00 \nSaturday, Sunday: 11:00 - 23:00', 'Closed Mondays', '04344  33, Hoenamu-ro 39-gil, Yongsan-gu, Seoul', 'Subway Line 6  Itaewon Station  Exit 2,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68208&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68209&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68210&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68211&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.54093330, 126.99353740, 'ENP042288', NULL, NULL),
	(37, 'Changsin-Sungin Quarry Observatory', 'https://english.visitseoul.net/attractions/2024-Chaeseokjangjeonmangdae/ENPauov7d', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The quarry observatory is built atop the summit of Changsin-dong quarry, providing a panoramic view of the city and natural landscapes at a glance.During the Japanese colonial period, a quarry was located in Naksan, Changsin-dong, to supply stone for the exterior of large buildings such as the Government-General of Korea, the old Seoul Station, and the Bank of Korea. After the Korean War, the quarry\'s use was discontinued, but the quarry observatory was located where immigrants and refugees settled to form a village.From the quarry observatory, with nothing obstructing the view, you can enjoy the skyline of Seoul at a glance. The second floor houses a coffee shop (Café Nakta), and the third floor features an outdoor observation deck, allowing you to appreciate the scenery of Seoul\'s cityscape and nature from any vantage point. Especially renowned is the breathtaking view that unfolds alongside the sunset. Enjoy the best panoramic view, a reasonably priced cup of coffee, and homemade ggangjeong and Nakta rice cakes. Small music concerts featuring historical and cultural stories, exhibitions, and live guitar performances are held occasionally.', '-7171', 'Tue-Fri 10:00 - 20:00 / Sat-Sun 10:00 - 22:00', 'Mondays', '03091  51 Naksan 5-gil, Jongno-gu, Seoul', 'Subway Line 6, Changsin Station, Exit 1, 708m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64722&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64723&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64724&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64725&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75486&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57854440, 127.01136710, 'ENPauov7d', NULL, NULL),
	(38, 'Lotte World Tower', 'https://english.visitseoul.net/attractions/Lotte-World-Tower/ENP021278', 'Lotte World Tower is one of Korea\'s architectural crown jewels. The tower symbolizes the meeting of the modern with the traditional, nature and cutting edge technology, and the accomplishments of man. Lotte World Tower contains everything that is necessary for modern urban living.      Soaring 555m into the air; with 123 stories, Lotte World Tower is home to Korea\'s tallest observation deck, (at 500m) Seoul Sky. Korea\'s newest luxury landmark hotel, Signiel Seoul is also located at Lotte World Tower. Also located in the tower is Podium, a multi-floor, multipurpose space where visitors will find a healthcare center, a fitness center, and a financial center.        The Lotte World Mall, a global fashion hub, also calls Lotte World Tower home, and visitors will also be able to shop at Korea\'s largest urban duty free store, Lotte Duty Free. Other features include the shopping mall Avenuel, Korea\'s best urban aquarium, a spectacular classical music hall, and Asia\'s largest multiplex. Experience the best of modern living in Seoul at the Lotte World Tower!   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Lotte World Tower", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "865" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "John E A" }, "reviewBody": "The observatory is floor 122, We had cheese cake and coffee on floor 123. It is a great view of Seoul and the Han River. The tower provides a nice cap to a day at Lotte World adventure park. Get the Combo ticket: About 72,000 won. Lotte world, Aquarium and Tower.", "datePublished": "2024-07-27" }] }', '-8133', 'Please refer to the website.', 'Open year round', '05551  300, Olympic-ro (Sincheon-dong), Songpa-gu, Seoul', 'Subway Lines 2/ 8  Jamsil Station  Exits 2,  29m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68179&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68180&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68181&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68182&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72458&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.51310080, 127.10343340, 'ENP021278', NULL, NULL),
	(39, 'Cheongwadae', 'https://english.visitseoul.net/attractions/Cheongwadae/ENP005538', 'Cheong Wa Dae, meaning "Blue House," was the official residence of the President of South Korea until it was opened to the public in June 2022, becoming a popular tourist destination. The main building features the president\'s office, reception rooms, and conference rooms, while auxiliary buildings include Chunchugwan, the State Guest House, and the rear garden. Cheong Wa Dae is closed every Tuesday, and tour reservations can be made on its official website.   A tour of the Cheong Wa Dae grounds, which encompasses Nokjiwon, Sangchunjae, the residence, the State Guest House, and the main building, typically takes around 1 hour and 30 minutes to 2 hours.   On rainy days, interior tours of key buildings like the main building and Chunchugwan may be restricted to prevent damage. In the event of natural disasters such as typhoons, tours of all or parts of Cheong Wa Dae may be suspended to ensure visitor safety.    { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Cheongwadae", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "231" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Max Y" }, "reviewBody": "Why this place is not in top ten? Nice place to visit, it??s crowded but line moves quickly. Alternatively you can hike 1km to observation deck, overlook Seoul city. ", "datePublished": "2023-10-20" } }] }', '-6450', 'March to November: 09:00 - 18:00 (Last entry 17:00 / Indoor entry closes at 17:30)\nDecember to February: 09:00 - 17:30 (Last entry 16:30 / Indoor entry closes at 17:00)\n*For more details, please refer to our website', 'Closed on Tuesdays (*However, if Tuesday falls on a public holiday or substitute holiday, it will be open as usual and closed the following day.)', '03048  1, Cheongwadae-ro, Jongno-gu, Seoul', 'Subway Line 3, Gyeongbokgung Station, Exit 3 (984m on foot, 16-minute walk)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72703&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72704&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72705&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72706&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72707&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58626870, 126.97660370, 'ENP005538', NULL, NULL),
	(40, 'Sebitseom (Sebitseom Island)', 'https://english.visitseoul.net/attractions/Sebitseom/ENP024645', 'Sebitseom, also known as Sebit Islets, with the meaning ??three shining islands brightening the Hangang River??is the world??s first floating cultural space. It is made up of four artificial islands with wedding halls, Italian restaurants, buffets and cafes, exhibitions, performances and it is used as a marina for yachts and boats!    The Some Sevit, known to be a popular spot for nightlife in South Korea, has colorful and beautiful LED lights that reflect off of the Hangang River, making it a popular filming location for various dramas and movies, such Avengers: Age of Ultron. Enjoy delicious meals and cultural experiences, and remember to bring a camera for the various photo spots at the Floating Island Convention center, the outdoor deck and the roof observatory.', '-4919', 'Daily 11:00 - 22:00', '', '06500  2085-14, Olympic-daero, Seocho-gu, Seoul', 'Subway Lines 3/7/9, Express Bus Terminal Station, Exit 8-1,  650 m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42023&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42026&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42027&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73934&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73935&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.51198270, 126.99342230, 'ENP024645', NULL, NULL),
	(41, 'Hangang Eland Cruise', 'https://english.visitseoul.net/attractions/Hangang-Cruise/ENP002126', 'The ultimate way to experience the Hangang River is by embarking on a cruise. Feel the refreshing breeze as you enjoy the picturesque views along both banks. Various cruises are available day and night, allowing you to appreciate the river??s beauty in a different light. The "Hangang Tour Cruise" runs daily during the day, offering a chance to explore Seoul\'s cityscape while enjoying live entertainment. Every evening at 6 PM, the "Sunset Cruise" provides a romantic view of the setting sun. For those who prefer evening or night outings, the "Moonlight Music Cruise" and "Starlight Cruise" offer stunning nighttime views of the Hangang River. Special options like the "Fireworks Music Cruise," featuring dazzling displays, and the "Dinner Cruise," which includes a buffet or champagne, add an extra luxury to your river experience.Aboard the cruise, you can enjoy live music while soaking in the sights of Seoul\'s iconic landmarks, including Sebitseom Island, Nodeul Island, Yeouido, the National Assembly Building, and Jamsil. It??s an ideal way to spend quality time with a partner, friends, or family, and offers a serene setting for those who wish to enjoy some peaceful reflection alone. Since schedules and routes vary by course, checking the official website for detailed information is advisable.', '-13111', '10:00 AM - 22:00 (Varies per course)\n- Duration may vary depending on the departure point and whether it\'s a round-trip or one-way route.  \n- For detailed schedule information, please refer to the website or call.', 'In case of natural disasters or severe weather conditions.', '07337  Yeouido Dock: E-Land Cruise Ticket Office, 280 Yeouidong-ro, Yeongdeungpo-gu, Seoul / Jamsil Dock: Jamsil E-Cruise, 2 Baekjegobun-ro, Songpa-gu, Seoul', 'Yeouido Dock:  Subway Line 5  Yeouinaru Station  Exit 3,  613m  \nJamsil Dock:  Subway Line 2  Jamsilsaenae Station  Exit 6,  999m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1318&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1321&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1322&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.52486930, 126.93806290, 'ENP002126', NULL, NULL),
	(42, 'Songwoldong', 'https://english.visitseoul.net/attractions/Songwol-dong/ENP010567', 'Songwoldong is a neighborhood in northern Seoul that is home to many of the city\'s historic sites. Deoksugung Palace, the Seoul Museum of History, Gyeonghuigung Palace, Sungnyemun Gate, Seodaemun Prison History Hall and Dongnimmun Gate are all found in Songwoldong. Visitors to Seoul can experience Korean history through a visit to this beautiful and charming area. The area has also been used as a filming location for many Korean TV shows including "Rooftop Prince." Songwoldong is easily accessible by car or public transportation.', '-40', '', '', 'Songwol-dong, Jongno-gu, Seoul', 'Subway Line 5  Seodaemun Station  Exit 3', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=5335&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=5336&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73948&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73949&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57007710, 126.96521530, 'ENP010567', NULL, NULL),
	(43, 'Korea Central Mosque', 'https://english.visitseoul.net/attractions/Seoul-Central-Mosque/ENP004863', 'Located in Hannam-dong, Yongsan-gu, Seoul, the Seoul Central Mosque is the first Islamic Mosque in Korea. It was established on May 21, 1976, after construction began in October 1974. The Korean government provided the site in May 1969 with approximately 4,958 square meters of land, and the construction costs were supported by Islamic countries worldwide, including Saudi Arabia. Situated between the Hangang River and Namsan Mountain, the mosque features prayer halls on the first and second floors, with ablution rooms for men and women in the basement of the annex building. The first floor of the annex houses classrooms, while the second floor has office spaces. The adjacent Islamic Center includes facilities such as an Islamic mission center for children, a Muslim congregation, a women\'s association, and a library. The exterior of the Seoul Central Mosque features a variety of amenities, including halal restaurants, a halal butcher shop, an Islamic bookstore, a halal supermarket, and a travel agency, making it convenient for Muslims and non-Muslims to visit.       Frequently Asked Questions about Korea Central Mosque         What is the nearest subway station to the Seoul Central Mosque?         The nearest subway station to the Seoul Central Mosque is Itaewon Station (Subway Line 6).          Are there any precautions when visiting the Seoul Central Mosque?         You are not allowed to wear revealing clothing such as sleeveless tops, short skirts, or shorts, and smoke inside the mosque. If you enter the mosque wearing revealing clothing, you must put on appropriate attire (such as skirts and hijabs) available in the dressing room next to the security office. Non-Muslims are allowed to enter the mosque, but be careful not to interfere with the prayers by pointing the camera in front of people.          I am curious about the Seoul Central Mosque worship schedule.         You can check the Seoul Central Mosque monthly worship schedule on the website below.    Seoul Central Mosque Worship Schedule      { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "What is the nearest subway station to the Seoul Central Mosque?", "acceptedAnswer": { "@type": "Answer", "text": "<div> The nearest subway station to the Seoul Central Mosque is Itaewon Station (Subway Line 6). </div>" } }, { "@type": "Question", "name": "Are there any precautions when visiting the Seoul Central Mosque?", "acceptedAnswer": { "@type": "Answer", "text": "<div> You are not allowed to wear revealing clothing such as sleeveless tops, short skirts, or shorts, and smoke inside the mosque. Non-Muslims are allowed to enter the mosque, but be careful not to interfere with the prayers by pointing the camera in front of people. </div>" } }, { "@type": "Question", "name": "I am curious about the Seoul Central Mosque worship schedule.", "acceptedAnswer": { "@type": "Answer", "text": "<div> You can check the Seoul Central Mosque monthly worship schedule on the website below.<br><br> <a href=\\"http://www.koreaislam.org/en/prayer-times/\\"style=\\"color:#0000EE;text-decoration:underline\\">Seoul Central Mosque Worship Schedule</a> </div>" } }, { "@type": "LocalBusiness", "name": "the Seoul Central Mosque", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "125" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "eddyphdhong" }, "reviewBody": "my the first time to visit here. only one mosque in korea i think. good place to visit. in itaewon area. with muslim friends it??s good time to show them here", "datePublished": "2020-02-08" } }] }', '-7621', 'Prayer services differ depending on time of the sunrise. Please refer to the website.', '', '04405  39, Usadan-ro 10-gil, Yongsan-gu, Seoul', 'Subway Line 6  Itaewon Station  Exit 3,  477m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17976&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17977&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17979&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17978&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.53385160, 126.99661790, 'ENP004863', NULL, NULL),
	(44, 'Chungdong First Methodist Church', 'https://english.visitseoul.net/attractions/Chungdong-First-Methodist-Church/ENP002132', 'Chungdong First Methodist Church is Korea??s first Protestant church, established in 1885 by American Methodist missionary Henry Appenzeller. The church is Korea\'s representative Protestant church. Chungdong First Methodist operates many religious and missionary programs such as medical services, education services, and missionary training for dispatch to foreign countries.', '+82-2-753-0001~3', 'Worship Services in English:  \n- Contemporary Worship:  Sundays, 9:30 KST (Bethel Chapel)\n- Traditional Worship with Holy Communion:  Sundays, 14:00 KST  (Main Sanctuary)\n\nThe Mangon Christian History Reference Room requires advance reservation to visit. \n- Tuesday to Friday: 10:00 - 17:00 KST\n- Saturday 10:00 - 14:00 KST', 'The Mangon Christian History Reference Room is closed Mondays and Sundays', '04516  46 Jeongdong-gil, Jung-gu, Seoul', 'Subway Lines 1/2  City Hall Station  Exit 10,  404m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16427&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16428&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16429&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.56536270, 126.97255590, 'ENP002132', NULL, NULL),
	(45, 'Jinkwansa Temple', 'https://english.visitseoul.net/attractions/Jinkwansa-Temple/ENP006251', 'Jinkwansa Temple is a centuries-old temple located in Bukhansan National Park. The temple was built by order of King Hyeonjong of the Goryeo Dynasty in gratitude to the great Buddhist priest Jinkwan. History has it that Jinkwan saved King Hyeon-jong\'s life when he was young and the king repaid the priest by building the temple. Jinkwansa Temple is comprised of several buildings and some of the notable buildings include Daeungjeon Hall, Myeongbujeon Hall, and Nahanjeon Hall. The temple also operates temple stay programs where visitors can experience Buddhist culture firsthand. There are programs for groups, children, and youths.', '-8689', '', '', '03308  73, Jingwan-gil, Eunpyeong-gu, Seoul', 'Subway Line 3  Gupabal Station  Exit 3, take bus 7211 or 7723 and get off at Hanago Station,  853m\nSubway Lines 3/6  Yeonsinnae Station  Exit 3, take bus 701 or 7211 and get off at Hanago Station, 853m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=30284&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=30285&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=30286&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=30287&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=30288&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.63814140, 126.94657910, 'ENP006251', NULL, NULL),
	(46, 'Hwanghakjeong (Archery Field)', 'https://english.visitseoul.net/attractions/Hwanghakjeong-Archery-Field/ENP029766', 'Hwanghakjeong is an archery field built by Emperor Gojong who strongly believed that archery was the best activity for training one\'s body and spirit. Originally located in Gyeonguigung Palace, this archery field was relocated here under Inwangsan Mountain during 1922. Known far and wide for its magnificent scenery, Hwanghakjeong is located next to Hwanghakjeong Korean Archery Gallery, allowing visitors to access all kinds of information about Korean archery in one place.', '-6443', '', '', '03027  15-32 Sajik-ro 9-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 1,  750m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22585&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22586&fileTy=MEDIA&fileNo=2&thumbTy=L', 2, 37.57784380, 126.96426340, 'ENP029766', NULL, NULL),
	(47, 'Daegaksa Temple', 'https://english.visitseoul.net/attractions/Daegaksa-Temple/ENP005015', 'Daegaksa Temple is a Buddhist temple founded in 1911 by Yongseong Seunim and located not far from Changdeokgung Palace. Yongseong Seunim was one of the 33 citizen representatives who took part in the March 1st Movement. He was active in the Korean independence movement and his legacy includes significant reforms of modern Buddhism in Korea. The temple was originally just a small hanok and in 1986 the temple was completely ry reconstructed. Today, Daegaksa has a main gate, belfry, and three-story temple.', '-5166', 'Daily from sunrise to sunset.', 'Open year round', '03134  87, Yulgok-ro 10-gil, Jongno-gu, Seoul', 'Subway Lines 1/3/5  Jongno 3(sam)-ga Station  Exit 8,  139m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22637&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22638&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22639&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22640&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57365730, 126.99207690, 'ENP005015', NULL, NULL),
	(48, 'Ehwajang (House)', 'https://english.visitseoul.net/attractions/Ehwajang-House/ENP002481', 'Ehwajang was the residence of Korea\'s first president Rhee Syngman. The residence now functions as a memorial hall for President Rhee Syngman. Ehwajang is comprised of the Rhee Syngman Memorial Hall, Sajeokgwan Library, and Jogakdang. Jogakdang was once the president??s office where Rhee designed and formed the first Korean presidential cabinet.', '-1476', '', '', '110-500  32, Ihwajang 1-gil, Jongno-gu, Seoul', 'Subway Line 4, Hyehwa Station, Exit 2 (15 mins on foot)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17290&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17291&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17292&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17293&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57834290, 127.00643080, 'ENP002481', NULL, NULL),
	(49, 'Segeomjeong Pavilion', 'https://english.visitseoul.net/attractions/Segeomjeong-Pavilion/ENP002395', 'Segeomjeong Pavilion is a well-known historic pavilion and was designated Monument of Seoul No. 4 in 1976. The pavilion itself and the surrounding area are both referred to as Segeomjeong. During the Coup of 1623, rebel forces passed through Changuimun Gate from Segeomjeong in order to attack the palace. In peaceful times during the Joseon Dynasty, guards and soldiers would rest here and clean their swords at the stream.', '-1063', '', '', '03018  244, Segeomjeong-ro, Jongno-gu, Seoul', 'Subway Line 3, Hongje Station  Exits 1 / 2,  Take the 110A Korea University trunk bus from Yujin Shopping Center stop, get off at Segeomjeong/Sangmyung University stop, 85m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16511&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16512&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16513&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16514&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.60043210, 126.96154660, 'ENP002395', NULL, NULL),
	(50, 'Deoksugung Stonewall Walkway', 'https://english.visitseoul.net/attractions/Deoksugung-Stone-Wall-Path/ENP023563', 'The Deoksugung Stone Wall Path is a charming walkway that winds around Deoksugung Palace in Jung-gu, Seoul, bordered by a rustic stone wall. Here, you can experience a serene blend of Joseon-era architecture and modern Seoul, with the path at its most beautiful in spring and autumn, attracting many visitors. After touring Deoksugung Palace, it??s an ideal spot to unwind at nearby cafes or galleries. The path also connects to Jeongdong-gil and the Seoul Museum of Art, making it easy to explore these attractions together.', '-1405', 'Open year round \n*Interior walking path open Tuesday ??Sunday 9:00 ??21:00*', '', '04519  101 Sejong-daero, Jung-gu, Seoul, Deoksugung Stonewall Walkway (Underground)', 'Subway Lines 1 / 2, City Hall Station, Exit 1, 168m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68277&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68278&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68279&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68280&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72581&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.56560720, 126.97694460, 'ENP023563', NULL, NULL),
	(51, 'Gilsangsa Temple', 'https://english.visitseoul.net/attractions/Gilsangsa-Temple/ENP003255', 'Gilsangsa Temple was once one of the foremost yojeong, a place where powerful men used to convene behind the scenes.The temple is named after the woman who donated the buildings, a gisaeng (a female entertainer and/or courtesan) named Kim Yeong-han who had a change of heart after reading "Non-Possession" by Venerable Beopjeong Sunim. The monk initially denied her request, but in 1995 decided to turn the buildings into a temple.  As a result, the temple has a very unusual atmosphere because it kept many of its original features. The temple is highly regarded for its involvement in cultural exchanges with other religions, and its programs to help visitors experience Buddhism.', '-9537', 'Opening hours vary depending on the ceremony and temple schedule. Please refer to the website.', '', '68, Seonjam-ro 5-gil, Seongbuk-gu, Seoul', 'Subway Line 4, Hansung Univ. Station, Exit 6, 65m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65047&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65049&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65050&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65051&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65055&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.59870210, 126.99345000, 'ENP003255', NULL, NULL),
	(52, 'Seodaemun Independence Park', 'https://english.visitseoul.net/attractions/Seodaemun-Independence-Park/ENP001753', 'Seodaemun Independence Park is a park and important historic cultural site. During the Japanese colonial period, the park housed Seodaemun Prison. Japanese imperial authorities arrested and held political prisoners and independence activists here in brutal conditions before the liberation of Korea in 1945. Today, the park is home to a history museum and monuments to independence fighters.  At the Seodaemun Prison History Hall, visitors can learn about the history, struggles, and sacrifices made by Koreans during the colonial era. Visitors to the park can see the historic Dongnimmun Gate (Independence Gate), Independence Hall, and the March 1st Declaration of Independence Monument. There are several memorials and statues of patriots, such as a statue of Seo Jaepil (a Korean independence activist) and the Patriot Martyrs Monument.', '-11365', 'Open 24 hours', '', '03732  251, Tongil-ro, Seodaemun-gu, Seoul', 'Subway Line 3  Dongnimmun Station  Exits 4,  150m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67659&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67660&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67661&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67662&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67663&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57448570, 126.95465720, 'ENP001753', NULL, NULL),
	(53, 'Amsa??dong Prehistoric Settlement Site', 'https://english.visitseoul.net/attractions/Amsa%E2%80%93dong-Prehistoric-Settlement-Site/ENP002174', 'The Amsa-dong Prehistoric Settlement Site is a historic site where visitors can learn about Korea during the Neolithic era. The site has two exhibition halls with displays of ancient artifacts excavated at Amsa, and with educational displays about the lives of pre-historic people who lived during 5,000 BCE. Carbonized acorns, fishing net weights, and stone tools have been excavated at Amsa. Twenty five hut sites have been uncovered during excavations throughout the years and a total of nine huts have been restored to date.??,-9865,Daily 09:30 - 18:00,Closed Mondays & holidays ', '', '', '', '', '', '', 0, 0.00000000, 0.00000000, 'ENP002174', NULL, NULL),
	(54, ' the site will be closed the following day.)"', '05239  875, Olympic-ro, Gangdong-gu, Seoul', 'Subway Line 8   Amsa History Park Station  Exit 3,  773m', 'https://english.visitseoul.net/comm/getImage?srvcI', '5', '37.5573061', '127.1283753', '', '', 0, 0.00000000, 0.00000000, '(* If a holiday falls on a Monday', NULL, NULL),
	(55, 'Yonghakgeong (Mokdong Archery Club)', 'https://english.visitseoul.net/attractions/Yonghakgeong-Mokdong-Archery-Club/ENP002250', 'Yonghakgeong was once a military training ground, and is now known as the Mokdong Archery Club. The club has membership system but one-off lessons can be reserved in advance. After making a reservation, visitors can take archery lessons at the center. There is a pavilion, Western-style archery center (Yanggung Center) and Korean-style archery center (Gukgung Center). Visitors can choose from Western or Korean-style bows for their lessons.', '-7484', 'Yanggung Center\'s Day Lessons: Tuesday & Wednesday 14:00 - 16:00\n* Please make reservations in advance online or by phone', '', '07990  316-8, Mokdongdong-ro, Yangcheon-gu, Seoul', 'Subway Line 5  Omokgyo Station  Exit 4,  538m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16391&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16392&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16393&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16394&fileTy=MEDIA&fileNo=3&thumbTy=L', 4, 37.52942890, 126.88078750, 'ENP002250', NULL, NULL),
	(56, 'Hwagyesa Temple', 'https://english.visitseoul.net/attractions/Hwagyesa-Temple/ENP002021', 'Hwagyesa Temple is located in the Samgaksan Woods, at the foot of Samgaksan Mountain in Seoul. Since the temple is close to center of the city, many people visit to feel the nature. Hwagyesa Temple has established a reputation as a temple that brings Korean Buddhism to an international audience. The temple attracts many Zen masters from all over the world and in addition to Korean and expat Buddhists. Hwagyesa Temple also offers a range of temple stay programs that are open to the general public. Visitors can choose from a one day program, a meditation-focused program, and an activities-focused temple stay program.  { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Hwagyesa Temple", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "5.0", "ratingCount": "16" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "idil a" }, "reviewBody": "It was my first time in temple stay. Amazing experince. Hwagyesa is very close to city centre but also in a very peaceful, silent location. The surrounding is beautiful, the temple family is so kind and nice, they welcomed us so warmly! The food is very delicious as well.This is an unforgettable experience, definitely recommended!", "datePublished": "2020-11-08" }] }', '-3485', 'Opening hours vary depending on what Buddhist ceremonies are taking place, and the temple schedule', '', '01095  117 Hwagyesa-gil, Gangbuk-gu, Seoul', 'Subway Ui-Sinseol Line  Hwagye Station  Exit 2,  922m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20524&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20525&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20526&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20527&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75490&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.63260870, 127.00731440, 'ENP002021', NULL, NULL),
	(57, 'Bongwonsa Temple', 'https://english.visitseoul.net/attractions/Bongwonsa-Temple/ENP028339', 'Originally built on the site of Yonsei University by Queen Jinseong of the Shilla Dynasty in 889 A.D., Bongwonsa Temple was moved to its current site by King Yongjo of the Joseon Dynasty in 1748. The temple grounds holds a pond filled with lotus flowers. This attracts a lot of visitors, especially in the summer, as many gather to view the beautiful blooming flowers as they enjoy the festivities. It\'s the perfect place to visit for calming your mind and spirit.', '-3319', '', '', '03721  75-66, Bongwonsa-gil, Seodaemun-gu, Seoul', 'Subway Line 2, Sinchon Station, Exit 4\nSubway Line 2, Dongnimmun Station, Exit 4', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=21375&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=21376&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73597&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73598&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57129440, 126.94611700, 'ENP028339', NULL, NULL),
	(58, 'Andong Presbyterian Church\'s Soheodang', 'https://english.visitseoul.net/attractions/Andong-Presbyterian-Churchs-Soheodang/ENP002010', 'Andong Presbyterian Church is located in Bukchon Hanok Village. The church dates back to the early 20th century. Most churches at the time were founded and built by Western missionaries. However, Andong is unique in that the church was founded by Koreans. Soheodang is part of the church complex and it is a rest area run by the church. Visitors to Soheodang are welcome to sit and rest while enjoying free tea provided by the church.', '-4048', '* Operating hours vary according to the church\'s prayer service schedule. Please check the times on the church website before visiting.', '', '03061  57, Yunboseon-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  305m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1233&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1234&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1236&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.57840440, 126.98315620, 'ENP002010', NULL, NULL),
	(59, 'Chodae-gil Trail (Bugaksan Mountain)', 'https://english.visitseoul.net/attractions/Chodae-gil-Trail-Bukhansan-Mountain/ENP027112', 'Chodae-gil Trail is a walking trail course created near the base of Bukhansan Mountain to commemorate the opening of the Modern History Memorial Hall. On this course, visitors can visit the tombs of prominent figures who played key roles in the founding of Korea\'s modern history.    (Chodae-gil Trail Course) Modern History Memorial Hall ??Grave of Haegong Shin Ik-hee ??Grave of Martyr Ilsung Lee Jun ??Grave of Gain Kim Byeong-ro ??United Graves of the Independence Army ??Grave of Seongjae Lee Si-yeong - Total Distance: 1.3 km - Total Time: 30 mins', '-6935', '', '', '01013  114, 4.19-ro, Gangbuk-gu, Seoul', 'Subway Line 4, Suyu Station  Exit 4,  take Bus No. 01 (village) Gangbuk at Suyu Station Bus Stop ??Get off at Shinsung Villa Bus Stop, Modern and Contemporary History Museum', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20517&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20518&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20519&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.64106650, 127.00042130, 'ENP027112', NULL, NULL),
	(60, 'Cheongjeon Yi Sang-beom House', 'https://english.visitseoul.net/attractions/2024-cjisbhouse/ENPlpqd8k', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The house and studio of Cheongjeon Yi Sang-beom, an artist recognized for pioneering new directions in Korean Southern School painting, are located west of Gyeongbokgung in Nuha-dong. Built-in 1929, the Yi Sang-beom House is an urban hanok featuring an L-shaped main house and straight-line servant quarters. It is distinguished by its rare kitchen with a cool wooden floor. Yi lived in this small, renovated hanok in Nuha-dong for 43 years. In his studio, known as Cheongjeon Hwasuk, he produced many artworks and mentored exceptional students such as Bae Ryeom and Park No-soo.', '', 'March-October 09:00-18:00\nNovember-February 09:30-17:00', 'Mondays', '03039  31-7 Pirundae-ro, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  619m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65231&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65232&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65233&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65234&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65235&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57839140, 126.96816220, 'ENPlpqd8k', NULL, NULL),
	(61, 'Jongmyo Shrine Stonewall Path', 'https://english.visitseoul.net/attractions/2024-jongmyostonewall/ENP0wav1s', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The Jongmyo Shrine Stonewall Path is a tranquil walkway that stretches along the western wall of Jongmyo Shrine, a UNESCO World Heritage site. Unlike well-known historical and cultural spots like Bukchon and Insadong, this pathway is a hidden gem that has recently gained popularity. Strolling along the pristine, elegant stone wall, visitors can leisurely explore nearby cafes, craft studios, and shops and cafes housed in renovated hanok buildings along the side alleys. The path is beautifully framed by the historic stone wall and lush trees, offering scenic views throughout the seasons. In spring, cherry blossoms and fresh leaves embrace the wall, creating a bright and cheerful atmosphere. In autumn, the wall is transformed into a picturesque setting draped in warm hues, perfect for a romantic walk. This peaceful spot offers an ideal escape from the busy pace of everyday life. Traditional architecture and nature are in harmonious balance, providing a calming ambiance. Jongmyo Stone Wall Path is a fantastic photo spot for capturing traces of Korea??s traditional culture. Walking along the path, visitors can conveniently explore nearby attractions, such as Changgyeonggung Palace, Changdeokgung Palace, Insadong, and Samcheong-dong, where tradition meets modernity, allowing for a well-rounded cultural experience.', '', '', '', '03135  104-1 Gwonnong-dong, Jongno-gu, Seoul', 'Subway Line 5  Jongno 3-ga Station  Exit 7,  383m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68942&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68940&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68941&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68943&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68944&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57553970, 126.99182420, 'ENP0wav1s', NULL, NULL),
	(62, 'Bonghwanggak Pavilion', 'https://english.visitseoul.net/attractions/Bonghwanggak-Pavilion/ENP003305', 'Bonghwanggak Pavilion was constructed in 1912 by Son Byeonghui, the Korean independence activist. Bongwhanggak was built to be an educational facility that taught students the doctrines of Cheondogyo and educated leaders of the Korean independence movement. Cheondogyo is a Korean religion founded by Choe Je-U and its main tenet is that life and death are one, and all things in the universe repeat in an endless cycle. "Bonghwang" is the Korean word for the phoenix and it appeared often in Choe\'s writings, which is how the pavilion came to be named Bonghwanggak. The pavilion is considered the main shrine of Cheondogyo. In 1969, Bongwhanggak was designated Tangible Cultural Property No. 2 by the Seoul Metropolitan Government.', '-40', '', '', '142-090  107-12, Samyang-ro 173-gil, Gangbuk-gu, Seoul', 'Subway Uisinseol Line Bukhansan Ui Station Exit 2, 659m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16415&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16416&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16417&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16418&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73599&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.66029220, 127.00620540, 'ENP003305', NULL, NULL),
	(63, 'Samcheongdong', 'https://english.visitseoul.net/attractions/Samcheong-dong/ENP002121', 'Samcheongdong is Seoul\'s most stylish neighborhood, located just past Gyeongbokgung Palace\'s stone wall lined street. The name "Samcheong" is derived from the words "sam" meaning ??three", and "cheong" meaning "fresh" or "pure", because the mountain, water and the heart of the people in this area are all very fresh and pure. Then it\'s not wonder why many artists have sought out Samcheong-dong over the years. Because of this, Samcheong-dong became known as an artistic area.      The area of Samcheongdong is actually made up of several neighborhoods: Anguk-dong, Sogyeok-dong, Hwa-dong, and Sagan-dong and ends at Samcheong Park. Samcheong-dong is dotted with various art museums, museums, art galleries, restaurants, cafés, and shops; some are traditional, some are modern, but all are unique and colorful.', '-40', '', '', '110-260  Gahoe-dong, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 2,  780m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73782&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73783&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31361&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=24749&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31366&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58201190, 126.98646460, 'ENP002121', NULL, NULL),
	(64, 'Seoul Anglican Cathedral', 'https://english.visitseoul.net/attractions/Seoul-Anglican-Cathedral/ENP002030', 'The Seoul Anglican Cathedral was built during the Japanese colonial era and it is located beside Deoksugung Palace. The cathedral was constructed under the direction of the Rt. Reverend Mark Trollope, the third bishop of the Anglican Church of Korea and British architect Arthur Dixon. Although construction was completed in 1926, the Anglican Church of Korea considers 1890 as the date of the cathedral\'s foundation, since this was the year when the first service of Holy Communion was held. The cathedral is the seat of the Seoul Anglican Diocese and Tangible Cultural Property of Seoul No. 35.', '-7261', 'Daily 11:00 - 16:00', 'Closed Weekends', '100-120  15, Sejong-daero 21-gil, Jung-gu, Seoul', 'Subway Lines 1 & 2, City Hall Station, Exit 3 (195m, 3-minute walk)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67653&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67654&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67655&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.56712920, 126.97591120, 'ENP002030', NULL, NULL),
	(65, 'Yanghwajin Foreign Missionary Cemetery', 'https://english.visitseoul.net/attractions/Yanghwajin-Foreign-Missionary-Cemetery/ENP001153', 'Yanghwajin Foreign Missionary Cemetery is the final resting place for Korea\'s western residents, including Dr. Horace Allen, the first director of Gwanghyewon, the first western-style hospital in Korea, founded in 1885. The cemetery is known as Foreign Missionary Cemetery because of the number of foreign missionaries buried here. Tombs and headstones were built in a western style creating an exotic atmosphere. The cemetery is located near the Hangang (River), an ideal spot for taking a pleasant stroll.      Yanghwajin Foreigners\' Cemetery is situated on the other side of Yanghwajin, opposite the martyrs??shrine. It is regarded as a Protestant shrine because many Protestant missionaries are buried there.  The ??00th Anniversary Memorial Church??was established in Yanhwajin by the ??Council for the 100th Anniversary of the Korean Church??to commemorate a century of missionary work in Korea.       Many of the foreigners who have contributed to the story of modern Korean history are buried in the Yanghwajin cemetery, such as Thomas Bethell, the founder of Daehan Maeil Sinbo (Newspaper); Mary Scranton, the founder of Ewha Hakdang (a mission school for girls, now Ewha Womans University); and Henry Appenzeller, the founder of Chungdong First Methodist Church.      A guided tour in English or Japanese is available in Yanghwajin Foreign Missionary Cemetery when booked in advance. These are conducted four times a day (10:00, 11:30, 14:00, 15:30) except during the New Year\'s holiday, Chuseok holiday and on Christmas day.       Yanghwajin Foreign Missionary Cemetery is located in Hapjeong-dong, Mapo-gu. It is a haven for foreign missionaries and their families who loved, and wished to lie in, Korea. The cemetery is managed by 100th Anniversary Memorial Church and contains Mission Memorial Hall.', '-9426', 'Daily 10:00 - 17:00 (KST)', 'Closed Sundays\n??Guided tours are not offered on Sundays, Jan. 1st, Lunar New Year, Chuseok, and Christmas', '04084  46, Yanghwajin-gil, Mapo-gu, Seoul', 'Subway Lines 2 /6  Hapjeong Station  Exit 7,  319m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13443&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13444&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13445&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72584&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72585&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.54733300, 126.91135630, 'ENP001153', NULL, NULL),
	(66, 'Namsangol Hanok Village', 'https://english.visitseoul.net/attractions/Namsangol-Hanok-Village/ENP000276', 'Namsangol Hanok Village is a collection of five hanok (traditional Korean houses) from the Joseon Dynasty (1392-1910), recovered from different parts of the city and relocated to the northern foot of Namsan Mountain. The interiors of each of these five houses reflect owners from different walks of life, from the middle class to high government officials, noblemen and aristocrats. At Namsangol Hanok Village, visitors can see the hanok of important figures from the Joseon era including the house of Queen Yun\'s parents, who was the Queen Consort to King Sunjong, the 27th king of the Joseon Dynasty; the jaesil (study) of Yun Taekyeong, King Sunjong\'s father-in-law; the house of Min Yeong-hui, a relative of Empress Myeongseong; the house of Lee Seungeop, who was in charge of constructing Gyeongbokgung Palace and the house of Kim Chunyeong, a military official of the Joseon Dynasty. At the hanok village, international visitors can participate in traditional Korean activities such as archery and enjoy traditional Korean performances as well. Anyone who is curious about Korean wedding culture should visit the village on the weekend when traditional wedding ceremonies take place.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Namsangol Hanok Village", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "851" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "blanca" }, "reviewBody": "absolutely beautiful, and sometimes there are special performances so check the date before you visit for a fun extra!", "datePublished": "2023-10-22" }] }', '-11811', 'Summer season (April to October) 09:00 - 21:00 KST\nWinter season (November to March) 09:00 - 20:00 KST', 'Closed Mondays', '04626  28, Toegye-ro 34-gil, Jung-gu, Seoul  Namsangol Hanok Village', 'Subway Lines 3/4  Chungmuro Station  Exit 4,  120m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68269&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68270&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68271&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68272&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66763&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55931500, 126.99447700, 'ENP000276', NULL, NULL),
	(67, 'Seoul National Cemetery', 'https://english.visitseoul.net/attractions/Seoul-National-Cemetery/ENP001965', 'Seoul National Cemetery is the resting place of fallen Korean patriots. The cemetery was established to honor the loyalty and devotion of those who sacrificed and lived for their country. Facilities at the cemetary include the War History Museum, Memorial Tower, Memorial Hall, and the Altar to Patriots and Patriotic Martyrs. Memorial services are held yearly on June 6th, which marks the Korean Memorial Day holiday.', '1522-1555', 'Daily 06:00 - 18:00 (Front gate, central gate, and other 5 gates)\n09:00 - 16:00 (Business facilities opening hours)', '', '06984  210, Hyeonchung-ro (Dongjak-dong), Dongjak-gu, Seoul', 'Subway Line 4/9  Dongjak Station  Exit 4,  62m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49145&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49147&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49150&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49151&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49152&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.50226270, 126.97573300, 'ENP001965', NULL, NULL),
	(68, 'Myeongdong Cathedral', 'https://english.visitseoul.net/attractions/Myeongdong-Cathedral/ENP004036', 'Myeongdong Cathedral is the very first Roman Catholic parish church in Korea. It is also the first Gothic building ever built in Korea and was designated as Historic site No. 285 in Korea. On the basement floor, there is a small sanctuary where the remains of the martyrs are enshrined, and where visitors to the cathedral can pay their respects. Every May, Myeongdong Cathedral holds a cultural festival. The construction of the cathedral started in 1892 and was completed in 1898. Unlike most Gothic buildings, Myeongdong Cathedral was built with bricks instead of stones. It gives the cathedral a characteristic atmosphere. The splendid high ceilings inside the church and the arches in between the magnificent inner pillars show the beautiful Gothic style well. The basement contains the remains of nine saints and martyrs, who devoted their lives to the propagation of Catholicism in Korea. Behind the cathedral, Seongmo Dongsan (St. Mary\'s garden) is situated. During lunch hour, pipe organs are playing here. The garden offers a peaceful resting space after visiting the cathedral.', '-2478', '', 'Closed Mondays', '100-022  74, Myeongdong-gil, Jung-gu, Seoul', 'Subway Line 4, Myeong-dong Station, Exit 8, 590m\nSubway Line 2, Euljiro 1(il)-ga Station, Exit 5, 616m\nSubway Line 2, Euljiro 3(sam)-ga Station, Exit 12, 561m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68292&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68293&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68294&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68295&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73596&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56307860, 126.98699440, 'ENP004036', NULL, NULL),
	(69, 'An Jung-geun Memorial Hall', 'https://english.visitseoul.net/attractions/An-Jung-geun-Memorial-Hall/ENP004281', 'The An Jung-geun Memorial Hall was established to memorialize the Korean patriot An Jung-geun. An fought for Korean independence from Japan and was ultimately executed by Japanese authorities for assassinating Ito Hirobumi in 1909. Ito was a major force behind the Japanese annexation of Korea. The memorial hall is composed of 12 exhibition halls and galleries, an auditorium, a reference library, and a rest area. In addition to exhibition information about An\'s life and some of his calligraphy, the memorial hall also hosts the An Jung-guen Academny and other events each year. Events include visits to historic sites abroad that were important to independence movements and calligraphy contests. Admission to the An Jung-geun Memorial Hall is free.       { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "An Jung-geun Memorial Hall", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "26" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "travelsafer" }, "reviewBody": "This is a very touching museum dedicated to the life of an important Korean martyr who opposed the Japanese rule on the peninsula and ended up killing the Japanese price ruling over Korea. It is a testimony of the struggle of the oppressed people and symbolizes the will of Korea to be free and be ready for anything to reach its independence. I confess that, before visiting this place, I did not know anything about Ahn Jung Geun, but when I got out of the museum I felt quite emotional. His life is narrated as a story of strong belief and resistance until martyrdom. Many parts and panels are in Korean only, but the friendly lady at the entrance and a man who we met on the second floor were very helpful. In particular he gave us a small book in English about his life and pictures. If you can, add this museum to your list of place to visit in Seoul.", "datePublished": "2016-11-18" } }] }', '-4725', 'March to October: 10:00 - 18:00\nNovember to February: 10:00 - 17:00 (KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', '04636  91, Sowol-ro, Jung-gu, Seoul', 'Subway Line 4  Hoehyeon Station  Exit 3,  689m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17277&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17278&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17279&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17280&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74159&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55426100, 126.98133930, 'ENP004281', NULL, NULL),
	(70, 'Hyosa-gil in Heukseok-dong', 'https://english.visitseoul.net/attractions/Hyosa-gil-in-Heukseok-dong-/ENP011112', 'Hyosa-gil in Heukseok-dong is a neighborhood where the architecture and atmosphere of 1960s and 1970s Korea is still intact. At the neighborhood\'s observatory, Seoul landmarks such as the Mapodaegyo Bridge, Hangangdaegyo Bridge, and Namsan Seoul Tower are visible. The observatory is a great vantage point for night views of Seoul and the annual Seoul International Fireworks Festival.', '', '', '', '06910   4, Hyosa-gil, 5-gil, Heukseok-dong, Dongjak-gu, Seoul', 'Subway Line 9  Heukseok Station  Exit 4,  702m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23359&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23360&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23361&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23362&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23363&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53585640, 127.00153840, 'ENP011112', NULL, NULL),
	(71, 'Sukjeongmun Gate', 'https://english.visitseoul.net/attractions/Sukjeongmun-Gate/ENP023760', 'Sukjeongmun Gate is one of Seoul??s four historic great city gates. It is the city\'s northern gate and it can be visited today along the Hanyangdoseong, Seoul City Wall. Cheong Wa Dae, the official residence of the South Korean president is located not far from the gate and city wall. For decades, public access to the gate and its section of the city wall was restricted for security reasons. In 2006, public access to this section of the Hanyangdoseong was restored and it is now a very popular hiking destination. On January 21st, 1963, Sukjeongmun was recognized as part of the Hanyangdoseong, Seoul City Wall and designated Historic Site No. 10.', '-2819', '*March to October (Daily): 09:00 - 18:00 (Last entry at 16:00)\n*Daily - November to February (Daily): 10:00 - 17:00 (Last entry at 15:00)', 'Closed Mondays', '03049  1, Daesagwan-ro, Seongbuk-gu, Seoul', 'Subway Line 3, Gyeongbokgung Station, exit 3, take Blue Bus 710 at the Seoul Police Agency/Gyeongbokgung Station stop. Get off at Korea National Open University/Ihwajang, stop, and transfer to Green Bus 2112. Get off at Seoul Dawon School/Han Yong-un Activity Site, stop,  820 m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22970&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22971&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22972&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22973&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22974&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22975&fileTy=MEDIA&fileNo=1&thumbTy=L', 6, 37.59942580, 126.98368060, 'ENP023760', NULL, NULL),
	(72, 'Yeonghwiwon and Sunginwon Royal Tombs', 'https://english.visitseoul.net/attractions/Yeonghwiwon-and-Sunginwon-Royal-Tombs/ENP004524', 'Yeonghwiwon and Sunginwon are the burial site of members of the Korean royal family and the site was designated Historic Site No. 361 in 1991. Yeonghwiwon is the royal tomb of Princess Consort Sunheon, wife of the 26th king of the Joseon Dynasty, Gojong. Sunginwon is the burial place of Crown Prince Yi Jin, grandson of King Gojong and Princess Consort Sunheon.       In Korea, tombs for kings and queens are traditionally called ??neung??and tombs of princes and royal consorts are called ??won?? Yeonghwiwon and Sunginwon were once known as Hongneung as Queen Myeongseong, the first wife of King Gojong was entombed here. The grave was moved to Geumgok-dong in the city of Namyangju in 1919 following the death of King Gojong. Since then, the site has been known as Yeonghwiwon and Sunginwon. Apart from its historic significance, the greenery and beautiful surroundings here have always attracted sightseers.', '-1438', '* November to January: 09:00 - 17:30 (KST)\n(Ticket booth 09:00 - 16:30 (KST))\n* February-May & September-October: 09:00 - 18:00 (KST)\n (Ticket booth 09:00 - 17:00 (KST))\n* June-August: 09:00 - 18:30 (KST)\n(Ticket booth 09:00 - 17:30 (KST))', 'Closed Mondays', '02456  90, Hongneung-ro, Dongdaemun-gu, Seoul', 'Subway Lines 1/ Gyeongui-Jungang Line/ Suin-Bundang Line  Cheongnyangni Station  Exit 2,  884m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68711&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68712&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68713&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68714&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.59003450, 127.04501500, 'ENP004524', NULL, NULL),
	(73, 'Guam Park', 'https://english.visitseoul.net/attractions/Guam-Park/ENP002027', 'Guam Park is located in Gayang-dong, Seoul. The neighborhood is the birthplace of Heo Jun, a famous Joseon-era doctor and scholar. Next to the park is a museum dedicated to Heo Jun. His name is known in Korea to this day, more than 4 centuries after his death, in part because of his definitive text on Oriental medicine, "Dongui Bogam." There is a large, shrubby rock big enough to accomodate 20 people in the park. Known as Heogabawi Rock, during times of conflict such as the Imjin War and the Second Manchu Invasion of Korea, the rock was used as a refuge.', '-6632', '', '', '07525  42, Heojun-ro 5-gil, Gangseo-gu, Seoul', 'Subway Line 9 Gayang Station Exit 1 , 741m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16126&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16127&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16128&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16129&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.56778210, 126.85265970, 'ENP002027', NULL, NULL),
	(74, 'Old Seoul Engineering School Main Hall', 'https://english.visitseoul.net/attractions/Old-Seoul-Engineering-School-Main-Hall/ENP003387', 'The Old Seoul Engineering School Main Hall (formerly known as the Central Laboratory Complex) was built in 1906 and designated Historic Site No. 289 in 1981. The building was designed by the national Architecture Bureau. While in use as a school, students were taught how to use modern technologies and skills such as dyeing, weaving, papermaking, goldsmithing and woodworking. The building now functions as a museum and is part of Korea National Open University.', '1577-9995', 'Please refer to the website.', '', '03087  86, Daehak-ro, Jongno-gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 2,  237m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12332&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12333&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12334&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.57882840, 127.00364260, 'ENP003387', NULL, NULL),
	(75, 'Maehun Yun Bong-Gil Memorial Hall', 'https://english.visitseoul.net/attractions/Maehun-Yun-Bong-Gil-Memorial-Hall/ENP003759', 'The Maehun Yun Bong-Gil Memorial Hall is dedicated to the resistance fighter, Patriot Yun Bong-gil. Yun\'s pen name was Maehun and he was active in the Korean independence movement during the Japanese colonial era. Located in Seoul\'s Yangjae dong, the first floor of the memorial is an exhibition hall that displays relics and biographical information about Yun Bong-gil in chronological order. On the second floor, the exhibition hall contains photographs and other materials of the Korean independence movement organized by theme. Admission to the memorial hall is free.', '-3886', '* April to October: 10:00 - 18:00\n* November to March: 10:00 - 17:00\n??Last entry is 30 mins prior to closing', 'Closed Mondays, New Year\'s Day, Lunar New Year??s Day & Chuseok', '06773   99, Maeheon-ro, Seocho-gu, Seoul', 'Subway Sinbundang Line  Yangjae Citizen\'s Forest Station  Exit 5,  179m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2255&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2257&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2258&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74827&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74828&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.47022040, 127.03778820, 'ENP003759', NULL, NULL),
	(76, 'Baek In-je House', 'https://english.visitseoul.net/attractions/Baek-Injes-House/ENP021128', 'The Baek Inje??s House, located in Gahoe-dong, Bukchon, is a representative traditional house that well preserves the style of modern hanok architecture. Although built during the Japanese occupation period, it has been designated as a Seoul Metropolitan Folklore Cultural Heritage due to its good condition and its blend of traditional hanok beauty with modern adaptations. Situated on a plot overlooking Bukchon, the property features a spacious Anchae (main living quarters) and a large garden centered around the Sarangchae (men\'s quarters), with a small Byeoldangchae (detached quarters) on the highest point. In this quiet, traditional setting, visitors can glimpse the lifestyle of the wealthy class of that era and observe features that distinguish it from typical upper-class homes of the time. Detailed information on the Baek Inje??s House, including its history, context, and characteristics, is available in the Haengnangchae (servants\' quarters) and small Sarangbang (guest reception room). While general tours don\'t require reservations, entry to some areas like the Sarangchae and Byeoldangchae is only for those with guided tour bookings.   ??Baek In-je (1898 - Unknown): Baek In-je was a Korean patriot who fought for Korean independence during the Japanese colonial era. Baek was also a doctor who devoted much of his time to studying rickets and blood disorders. He made great contributions to the body of research on these medical issues.', '+82-2-724-0200,0200', '09:00-18:00 (Last entry at 17:30)\n??Visitors not on a guided tour may only tour the grounds \n??Fridays & Saturdays until 20:00 during August', 'Closed Mondays & New Year\'s Day', '03055  16, Bukchon-ro 7-gil (Gahoe-dong), Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 2,  464m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68028&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20050&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20052&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14800&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58080350, 126.98416220, 'ENP021128', NULL, NULL),
	(77, 'Jeongdong-gil', 'https://english.visitseoul.net/attractions/Jeongdong-gil/ENP000889', 'Mentioning Jeongdong-gil brings up a couple of imageries: old town neighborhoods, relaxing streets not crowded with people, a peaceful place to take a stroll, and so on. While all the above are true, visitors should also be aware that Jeongdong-gil is full of many historic buildings that managed to survive through Korea\'s turbulent past. It is also a place close to a lot of embassies like the Russian Embassy, British Embassy, US Embassy, German Embassy, etc. Chungdong First Methodist Church and Ewha Girls\' High School are some of the facilities which were built in the earlier era. A century later, Jeongdong-gil has been reborn as a cultural street featuring Seoul Museum of Art, Jeongdong Theater, and many other historical and cultural facilities and attractions.', '-40', '', '', '04516  2, Jeongdong-gil, Jung-gu, Seoul', 'Subway Line 1/2  City Hall Station  Exit 12,  580m \nSubway Line 5  Seodaemun Station  Exits 5,  581m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69082&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69083&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69084&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69085&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.56802580, 126.96919420, 'ENP000889', NULL, NULL),
	(78, 'April 19th National Cemetery', 'https://english.visitseoul.net/attractions/April-19th-National-Cemetery/ENP027106', 'With Bukhansan Mountain as its backdrop, the April 19th National Cemetery is a memorial ground for the people who??ve lost their lives in the April 19th Revolution. Inside the cemetery, there??s a white memorial tower erected in memory of these people and an exhibition hall and memorial hall displaying the events of the April 19th Revolution.', '-1335', 'National Cemetery\n* March - October 06:00 - 18:00\n* November - February 07:00 - 18:00\n\nMemorial Hall\n* March - October 09:30 - 17:30\n* November - February 09:30 - 16:30', '* National Cemetery: Open year round\n* Memorial Hall: Closed Mondays', '01009  17, 4.19-ro 8-gil, Gangbuk-gu, Seoul', 'Subway Line 4, Suyu Station, Exits 2 & 6', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20502&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20505&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20503&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20504&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.64893550, 127.00910360, 'ENP027106', NULL, NULL),
	(79, 'Gyeonggyojang', 'https://english.visitseoul.net/attractions/Gyeonggyojang/ENP001151', 'Gyeonggyojang is an historic site that was the headquarters of the Provisional Korean Government during the Japanese colonial era and the private residence of Kim Koo. Kim Koo was a writer (using the pen name Baekbeom), independence activist and politician who served as the last premier of the Provisional Korean Government. He lived, worked, and ultimately died at Gyeonggyojang at the hands of an assassin. Kim was an immensely influential figure in Korean history and remains deeply revered to this day. Visitors to Gyeonggyojang can learn more about Kim Koo and the Korean independence movement.', '-2693', 'Daily 09:00 - 18:00 KST', 'Closed Mondays & January 1', '03181  29, Saemunan-ro, Jongno-gu, Seoul', 'Subway Line 5  Seodaemun Station  Exit 4,  325m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68162&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68163&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68167&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68168&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56729150, 126.96725540, 'ENP001151', NULL, NULL),
	(80, 'Jeon Tae-il Memorial Hall', 'https://english.visitseoul.net/attractions/Jeon-Tae-il-Memorial-Hall/ENP034860', 'Having been built by the Seoul city government, the Jeon Tae-il Memorial Hall is a labor complex facility erected to illuminate upon the historical significance of Jeon Tae-il, whose self-sacrifice served as a pivotal point in time in the history of the Korean labor movement. The young man gave everything he had to create a world that centered itself around the mentality that workers are people that have the right to live, work, and study in good health. In order to help bring Jeon Tae-il\'s dream into fruition, the hall urges unity between the labor force, the youth of the country, and the public, brought together around the ideals of love and solidarity.', '-1141', 'March - October 10:00 - 18:00\nNovember - February 10:00 - 17:30', 'Closed Mondays, January 1 & holidays', '03191  105, Cheonggyecheon-ro, Jongno-gu, Seoul', 'Subway Line 2/3  Euljiro 3(sam)-ga Station  Exit 2,  362m \nSubway Line 1/3/5  Jongno 3(sam)-ga Station  Exit 15,  373m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32054&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32055&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32056&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75400&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75401&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56915980, 126.98866840, 'ENP034860', NULL, NULL),
	(81, 'Dosan Park', 'https://english.visitseoul.net/attractions/Dosan-Park/ENP001789', 'Dosan Park is a large public park that was established to commemorate Dosan Ahn Chang-ho. Ahn is widely revered in Korea for his patriotism and achievements as an educator. He wrote under the pen name Dosan and was an independence activist, political reformer, and educator. The park features a statue of Ahn Chang-ho as well as a memorial hall dedicated to his memory. At the Dosan Ahn Chang-ho Memorial Hall, visitors can learn more about the life, writings, and achievements of Ahn Chang-ho.    Dosan Park has become a must-visit destination in Gangnam. It is surrounded by numerous restaurants, cafes, galleries, and clothing shops. Additionally, the area features flagship stores of renowned international brands, making it an excellent spot for shopping.', '-9588', 'Dosan Ahn Chang-ho Memorial Hall: Open daily from 10:00 to 18:00', '', '06020  20, Dosan-daero 45-gil, Gangnam-gu, Seoul', 'Subway Line 3, Apgujeong Station, Exits 2 & 3, 882m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60065&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60066&fileTy=MEDIA&fileNo=5&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68282&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68283&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68284&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.52438950, 127.03511730, 'ENP001789', NULL, NULL),
	(82, 'Sajikdan (Sajik Altar)', 'https://english.visitseoul.net/attractions/Sajikdan-Sajik-Altar/ENP001824', 'Sajikdan (Sajik Altar) is an altar built during Joseon Dynasty that was used to pray to the gods for a good harvest. The altar is located in Sajik Park and in addition to the altar, visitors can see the Hwanghakjeong Archery Range and the Dangunseongjeon Shrine. The Jongno Public Library and a children\'s library is also located nearby.', '-7864', '', '', '03027  89, Sajik-ro, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 1,  337m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68722&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68723&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68724&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68726&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68727&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57696860, 126.96670150, 'ENP001824', NULL, NULL),
	(83, 'Seokguram', 'https://english.visitseoul.net/attractions/2024-seokguram/ENPexzzw3', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Seokguram Grotto is nestled halfway up Inwangsan Mountain, just below Chimabawi Rock, and can be reached via the Inwangsan Mountain Trail. Inside, you\'ll find the Three Buddha Statues, while the surrounding forest path features a Buddha statue and a Maitreya Buddha carved into the rocks. Above the main hall at Sanshingak Shrine, a large rock bears a painting of the Mountain Spirit and a tiger that guards Inwangsan. About 30 meters to the right of Seokguram, you can also visit the Cheonhyangam Hermitage. From Seokguram, you\'ll enjoy stunning panoramic views of Seoul, with Namsan Tower visible on the opposite mountain and, on clear days, even Lotte Tower. Below, Gyeongbokgung Palace and the Blue House come into view.', '-2058', '', '', '03034  3-14, Ogin-dong, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  1.7km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67174&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67176&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67177&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67178&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73923&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.58208320, 126.96620830, 'ENPexzzw3', NULL, NULL),
	(84, 'Site of Concubine Jang Huibin??s Well', 'https://english.visitseoul.net/attractions/2024-jangheebin/ENPcyd45f', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The area of the Site of Concubine Jang Huibin??s Well has been associated with Yeonhui Palace, a detached palace since the early Joseon Dynasty. It has been associated with palace grounds, courtyards, main buildings, and the royal family\'s first mulberry orchard. It has been passed down by the name Seojamsil, known as the Site of Concubine Jang Huibin??s Well.The first palace in this area was used as a refuge palace by King Jeongjong, who abdicated the throne to his younger brother, King Taejong, in the 3rd year of King Jeongjong\'s reign (1400). Later, in August of the 7th year of King Sejong\'s reign (1425), the palace was renamed Yeonhui Palace. It is said that there were wells in various places within the palace grounds due to the presence of palace officials and palace women. Among them, the preserved well is called the Site of Concubine Jang Huibin??s Well.During the reign of King Sukjong (1674-1720), Huibin Jang (1659-1701), who followed Queen Inhyeon, who was deposed, briefly stayed at this place as a concubine, but there is no proof she drank from the well. Over time, oral tradition in Yeonhui-dong has perpetuated the belief that "this well is where Huibin Jang drank water," upheld by generations of elders. Consequently, it was chosen for restoration as a part of the community\'s treasure-hunting initiative.', '', '', '', '03702  74 Yeonhui-ro 15-gil, Seodaemun-gu, Seoul', 'Subway Line 2 / Gyeongui Central Line/ Airport Railroad  Hongik University Station  Exit3,  1.6km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64823&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64824&fileTy=MEDIA&fileNo=1&thumbTy=L', 2, 37.57109510, 126.92856410, 'ENPcyd45f', NULL, NULL),
	(85, 'Jeongneung (A Royal Tomb)', 'https://english.visitseoul.net/attractions/Jeongneung-A-Royal-Tomb1/ENP003459', 'Jeongneung is the royal tomb of Queen Sindeok. She was the second wife of King Taejo, the founder of the Joseon Dynasty. It is said that the tomb was originally located behind Deoksugong (Palace) but moved to the current location when a son of King Taejo\'s first wife, King Taejong ( the third king of the Joseon Dynasty) ascended the throne. The original scale of the tomb was reduced as well. Although it is a simple tomb without many of the stone figures traditionally placed before a royal tomb, it has historical interest as it has faithfully kept the style of an early Joseon period tomb. The tomb is in picturesque surrounds with Bukhansan National Park located nearby.', '-5967', 'February - May & September - October 06:00 - 18:00\nJune - August 06:00 - 18:30\nNovember - January 06:30 - 17:30\n* Ticket booth closes 1 hour prior to closing.', 'Closed Mondays', '136-100  116, Arirang-ro 19-gil, Seongbuk-gu, Seoul', 'Subway Ui-Sinseol Line  Jeongneung Station  Exit 2,  584m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72663&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72664&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72665&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72666&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72667&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.60121520, 127.00682100, 'ENP003459', NULL, NULL),
	(86, 'Seokpajeong', 'https://english.visitseoul.net/attractions/Seokpajeong/ENP037164', 'The name of this historical complex, "Seokpachon," translates into English as "surrounded by water, soaring above the clouds" and was given in honor of the great Heungseon Daewongun, the regent of the Joseon Kingdom. The Seokpachon complex is more than 600 years old, but it has been able to maintain its original appearance through careful preservation. This place is remarkable for its extraordinary beauty and it displays a combination of traditional Korean and Chinese architecture. This historic garden is currently under the authority of the Seoul Museum, which celebrates traditional and contemporary Korean art throughout the world.', '-415', '10:00 - 18:00 (Admission closes at 16:00)', 'Monday and Tuesday\n(??Closed Feb 26-May 31 for internal construction and next exhibition.)', '03021  4-1 Changimun-ro 11-gil, Jongno-gu, Seoul', 'Subway Line 3   Gyeongbokgung Station  Exit 3,  take bus 1020, 1711, 7016, 7018, get off at Jahamun Tunnel Entrance', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41310&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41311&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41312&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.59721580, 126.96089080, 'ENP037164', NULL, NULL),
	(87, 'Gyeongbokgung Palace Jibokjae', 'https://english.visitseoul.net/attractions/2024-Jibokjae/ENPfk9nxi', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}This building is located to the west of Geoncheonggung in Gyeongbokgung Palace. It housed about 40,000 books on Western artifacts purchased from the Qing Dynasty and was mainly used as King Gojong??s private library. Additionally, it served as a venue for enshrining portraits of kings or receiving foreign envoys. Originally constructed as a secondary building of Hamnyeongjeon Hall in Changdeokgung, it was relocated to Gyeongbokgung in 1891. The building was opened to the public in 2006, and the books previously housed there are now kept at Seoul National University\'s Kyujanggak Institute for Korean Studies and the Jangseogak Archives of the Academy of Korean Studies. In 2016, Jibokjae was transformed into a library and opened to the public. It is open from April to October, except for July and August, making it a great place to visit if you\'re in Gyeongbokgung during this period.', '-12092', '10:00 ~ 16:00', 'Tuesdays', '03045  161 Sajik-ro, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 5,  1.1km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67952&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67951&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67950&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67949&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58084730, 126.97685150, 'ENPfk9nxi', NULL, NULL),
	(88, 'Salgoji Bridge (Jeongotgyo Bridge)', 'https://english.visitseoul.net/attractions/Salgoji-Bridge-Jeongotgyo-Bridge/ENP002372', 'Salgoji Bridge (Jeongotgyo Bridge) is a historic stone bridge that dates back to the Joseon Dynasty. It stands over point where Cheonggyecheon and Jungangcheon Streams meet the Hangang River. It is the longest bridge from the Joseon era and was first designated Historic Site No. 160 in 1967; then elevated to Treasure No. 1738 in 2011. The bridge stands not far from Hanyang University.', '-7410', '', '', '61-1 Haengdang-dong, Seongdong-gu, Seoul', 'Subway Line 2  Hanyang University Station  Exit 3,  257m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12270&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12271&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12272&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12273&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75706&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55408220, 127.04546910, 'ENP002372', NULL, NULL),
	(89, 'Comfort Women Memorial', 'https://english.visitseoul.net/attractions/Comfort-Women-Memorial/ENP019540', 'The Comfort Women Memorial is located in Namsan, Yejang-dong, Jung-gu, Seoul, and opened in 2016. It serves as a memorial park honoring the victims and survivors of the Japanese military??s wartime sexual slavery. The space is centered around their testimonies, records of victimization, and documentation of Japan??s war crimes, embodying the themes of human rights and peace.', '', '', '', '04628  6, Toegye-ro 26ga-gil, Jung-gu, Seoul', 'Subway Line 4  Myeong-dong Station  Exit 1,  511m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13024&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13025&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13026&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74172&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74173&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55846050, 126.99061360, 'ENP019540', NULL, NULL),
	(90, 'Sungkyunkwan University\'s Myeongryundang Lecture Hall', 'https://english.visitseoul.net/attractions/Sungkyunkwan-Universitys-Myeongryundang-Lecture-Hall/ENP003176', 'Sungkyunkwan University was originally founded centuries ago during the Joseon Dynasty. Myeongryundang Lecture Hall is one of the Joseon era buildings that can still be seen at the university\'s Seoul campus. In the lecture hall\'s courtyard is a beautiful ginko tree that is thought to be more than 500 years old. The tree is known for its beauty and was designated Natural Monument No. 59.       Frequently Asked Questions about Sungkyunkwan University\'s Myeongryundang Lecture Hall         Is there an entrance fee for the Sungkyunkwan Myeongnyundang Lecture Hall?         The Sungkyunkwan Myeongnyundang Lecture Hall entrance is free.          Is the Sungkyunkwan Myeongnyundang Lecture Hall always open?         The Sungkyunkwan Myeongnyundang Lecture Hall opening hours are as follows. (As of 2024)     ??Summer season(March to October) : 09:00~18:00   ??Winter season(November to February) : 09:00~17:00       { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "Is there an entrance fee for the Sungkyunkwan Myeongnyundang Lecture Hall?", "acceptedAnswer": { "@type": "Answer", "text": "<div> The Sungkyunkwan Myeongnyundang Lecture Hall entrance is free. </div>" } }, { "@type": "Question", "name": "Is the Sungkyunkwan Myeongnyundang Lecture Hall always open?", "acceptedAnswer": { "@type": "Answer", "text": "<div> The Sungkyunkwan Myeongnyundang Lecture Hall opening hours are as follows. (As of 2024)<br><br> <ul> <li>Summer season(March to October) : 09:00~18:00</li> <li>Winter season(November to February) : 09:00~17:00</li> </ul> </div>" } }, { "@type": "LocalBusiness", "name": "the Sungkyunkwan Myeongnyundang Lecture Hall", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4", "ratingCount": "12" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Alice C" }, "reviewBody": "The current Seonggyungwan University in Seoul has a long history. Back in Joseon Dynasty, the highest national academy is this very monument. You can still see the seminar hall and the housing quarters for the students in ancient time. The giant ginko tree has been designated a Natural Monument in Korea. The monument is a photo spot especially during autumn. Many university students like to take their graduation photos in this ancient monument too.", "datePublished": "2016-08-21" } }] }', '-2152', 'Summer (March - October): 09:00 - 18:00\n Winter (November - February): 09:00 - 17:00', '', '110-812  25-1, Sungkyunkwan-ro, Jongno-gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 4,  833m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13365&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69077&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69078&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69079&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69080&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.58822700, 126.99360600, 'ENP003176', NULL, NULL),
	(91, 'Shina Memorial Hall', 'https://english.visitseoul.net/attractions/2024-shina/ENPjkm9y3', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Located in Jeong-dong, this building is notable for its uniquely stacked red bricks. It was constructed in the 1930s as a reinforced concrete building with one basement level and two above-ground floors. The structure, finishes, and facilities reflect its nearly 100-year history. Initially used as the Korean branch of the American sewing machine brand ??Singer,??it was purchased by Shina Ilbo, Korea\'s first commercial newspaper, in 1963. Shina Ilbo expanded the building by adding the third and fourth floors in 1975, using it as an annex. Following the forced shutdown of Shina Ilbo, the building was transformed into a memorial to commemorate the founder, Jang Ki-bong, and the newspaper. Today, it houses various businesses, including memorial halls, a café, and boutique shops, on each floor.', '-10572', 'Vary by company', '', '04518  33 Jeongdong-gil, Jung-gu, Seoul', 'Subway Lines 1/2  City Hall Station  Exit 12,  507m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66423&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66424&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66425&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66426&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56712280, 126.97159290, 'ENPjkm9y3', NULL, NULL),
	(92, 'Jungnang Mang-u Space', 'https://english.visitseoul.net/attractions/Jungnang-Mang-u-Space/ENP041904', 'Manguri, which was used as a cemetery for a long time, it was reborn as a Mang-U History & Culture Park to honor the spirits of the activists for independence such as Yu Gwan-sun, Han Yong-un, Ahn Chang-ho and Bang Jeong-hwan. Jungnang Mang-u Space is where the place newly created to honor a sublime meaning of great men by walking a calm nature of Mangusan Mountain. Jungnang Mang-u Space consists of the two buildings, a managing building and an exhibition building. A managing building administers the areas of grave and runs memorial ceremony. At an exhibition building, the works of literary people who are enshrined in Manguri, are being exhibited.', '+82-2-496-8974~6', 'Monday to Friday 09:00-18:00', '', '02178  2, Mangu-ro 91-gil, Jungnang-gu, Seoul', 'Subway Gyeongui-Jungang Line  Yangwon Station  Exit 2,  1.5km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54704&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54705&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54706&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54707&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54708&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.59708520, 127.11473400, 'ENP041904', NULL, NULL),
	(93, 'Bongeunsa Temple', 'https://english.visitseoul.net/attractions/Bongeunsa/ENP000411', 'Bongeunsa is a Buddhist temple founded in 794 during the Silla (one of the Three Kingdoms of Korea) period. The temple has more than 1,000 years of history and has many interesting historic and cultural features, including woodblock carvings of the Avatamsaka Sutra (Flower Garland Sutra). The temple is also a very popular tourist destination, offering various programs relating to traditional Korean Buddhist culture, in a variety of languages.       Bongeunsa is more than a just temple. It provides a place to relax for busy city people and also gives people a chance to reflect upon themselves. The templestay program gives an opportunity to experience everyday life in the temple, which includes traditional Korean Buddhist culture and practices. Visitors can experience some simple Buddhist practices such as the daily dawn service, Korean Zen meditation, Dado (a tea drinking ceremony), and Balwoogongyang (a Buddhist meal with traditional bowls).  Every May on Buddha\'s birthday, Bongeunsa holds the Lotus Lantern Festival on nearby Samseong-don   g.', '-7938', '', '', '06087  531, Bongeunsa-ro, Gangnam-gu, Seoul, Korea', 'Subway Line 9  Bongeunsa Station  Exit 1,  135m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60965&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60966&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60967&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60968&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60969&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.51490220, 127.05841840, 'ENP000411', NULL, NULL),
	(94, 'Pungnaptoseong Fortress', 'https://english.visitseoul.net/attractions/Pungnaptoseong-Fortress/ENP001953', 'Pungnaptoseong Fortress is the site of earthen ramparts that date back to the Baekje period (18 BCE-660 AD). Because many pieces of pottery have been uncovered here during excavations, it is thought that the site may have been a residential area at one time. Another important Baekje site, Mongchontoseong Fortress is located nearby.', '-4867', '', '', '05512  30, Hangaram-ro 20-gil, Songpa-gu, Seoul', 'Subway Line 5/8  Cheonho Station  Exit 9,  127m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12499&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12500&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12501&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12502&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74825&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53868990, 127.12090170, 'ENP001953', NULL, NULL),
	(95, 'Bangi-dong Ancient Baekje Tombs', 'https://english.visitseoul.net/attractions/Bangi-dong-Ancient-Baekje-Tombs/ENP002544', 'The Bangi-dong Ancient Baekje Tombs are ancient tombs in located the Bangi-dong area that date back to the Hanseong Baekje era. The ancient Hanseong Baekje Kingdom was founded along the Hangang River in 18 BCE and lasted for nearly 5 centuries. The tombs were discovered in the 1970s during the Jamsil District Zoning Project and there are 8 tombs altogether. Unfortunately, most of the artifacts were stolen at some point in time, but the tombs themselves were preserved well. Visitors can observe the original structures of the tombs and learn more about Hanseong Baekje. These ancient tombs are an important historical site and the area around the tombs was made into a park. There are paths between the tombs and visitors can take a quiet walk around the park and observe the tombs while enjoying the park\'s fresh air and grass. The site holds the designation of Historic Site No. 270.', '-4881', 'Daily 09:00 ??20:00\n* Winter Season 09:00 ??19:00', '', '05644  219, Ogeum-ro, Songpa-gu, Seoul', 'Subway Line 5 Bangi Station Exit 3, 600m\nSubway Line 9 Songpanaru Station Exit 3, 613m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16452&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16453&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16454&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16455&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73692&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.50837680, 127.11877910, 'ENP002544', NULL, NULL),
	(96, 'Jogyesa Temple', 'https://english.visitseoul.net/attractions/Jogyesa-Temple/ENP002586', 'Jogyesa Temple was established in 1910 under the name Gakhwangsa by monks who aspired for the independence of Korean Buddhism and the restoration of the national capital. At the time, Gakhwangsa was the first temple to be situated within the four main gates of Seoul. In 1937, efforts began to relocate Gakhwangsa to its present site, now known as Jogyesa. Positioned in the heart of Jongno, Seoul, it is the only traditional temple in the city center, offering a place for visitors to rest. The temple grounds are open 24/7, welcoming locals and foreigners anytime. The temple hosts a temple stay program and the annual Lotus Lantern Festival.', '-9288', 'Opening hours vary depending on what Buddhist ceremonies are taking place and the temple schedule', '', '03144  55, Ujeongguk-ro, Jongno-gu, Seoul', 'Subway Line 1  Jonggak Station  Exit 2,  413m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72645&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72646&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72647&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72648&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72649&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57403860, 126.98212970, 'ENP002586', NULL, NULL),
	(97, 'Manhae Han Yong-Un Simujang', 'https://english.visitseoul.net/attractions/Manhae-Han-Yong-Un-Simujang/ENP001399', 'Simujang, the residence of Manhae Han Yong-un, was built in 1933 during the Japanese occupation. Unlike typical hanok homes that face south, this house faces north. As an independence activist, Manhae chose a north-facing site on the hillside to avoid facing the Japanese Government-General of Korea. The house has a rectangular layout with a hip-and-gable roof and features four front rooms and two side rooms. Inside, you??ll find Manhae\'s personal room with preserved artifacts such as his calligraphy, research papers, and court records from his time in prison. After his death, his only daughter, Han Young-sook, lived there. However, when the Japanese Embassy moved across from the property, she relocated to Myeongnyun-dong, and Simujang was transformed into a research center dedicated to Manhae\'s philosophy.', '-4813', 'Daily 09:00 - 18:00 (KST)', 'Open year round', '02879  24, Seongbuk-ro 29-gil, Seongbuk-gu, Seoul', 'Subway Line 4  Hansung University Station  Exit 6,  62 m  to the Samsun-gyo and Seongbuk Cultural Center bus stop. Take the Seongbuk 03 bus and get off at the Supermarket stop.  127m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68839&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68840&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68841&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68842&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.59362070, 126.99169930, 'ENP001399', NULL, NULL),
	(98, 'Wonhyoro Catholic Church', 'https://english.visitseoul.net/attractions/Wonhyoro-Catholic-Church/ENP001862', 'Wonhyoro Catholic Church is located beside Sacred Heart Girls\' High School (once the Yongsan Seminary) and was consecrated in 1902. The church is small in scale but notable for its French Gothic architecture. Visitors to Seoul can visit an important piece of modern Korean history with a stop at Wonhyoro Catholic Church.', '-6122', 'Daily 09:00 - 17:00', 'Hours may vary according to the school\'s schedule', '04361  49, Wonhyo-ro 19-gil, Yongsan-gu, Seoul', 'Subway Line 6/Gyeongui Central   Hyochang Park Station  Exit 4,  1.3km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16661&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16662&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16663&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16664&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74171&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53433360, 126.95403340, 'ENP001862', NULL, NULL),
	(99, 'A Look at Yonsei University\'s 3 Historic Halls', 'https://english.visitseoul.net/attractions/Yonsei-Universitys-Stimson-Hall--Underwood-Hall--Appenzeller-Hall/ENP002435', 'Yonsei University is one of Korea\'s best universities. Its history is deep and many of the buildings on the Yonsei campus have modern historical significance as they were built in the early years of the 20th century. Stimson Hall was the first building ever built on the Yonsei campus and it was constructed in 1920. The hall was designated Historic Site No. 275 in 1981. Underwood Hall, Historic Site No. 276, was the second building ever built at Yonsei University. Today the hall functions as a museum dedicated to the founder of Yonsei, Horace G. Underwood and the Underwood family. Appenzeller Hall was built in 1924 and holds the designation of Historic Site No. 277. The hall was built to commemorate Henry Appenzeller who established the famed Korean boys\' school, Paichai Hakdang.', '-4157', 'Daily 09:00 - 17:00', '', '03722  50, Yonsei-ro, Seodaemun-gu, Seoul', 'Subway Line 2  Sinchon Station  Exits 2,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1601&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1602&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1605&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.56469930, 126.93949720, 'ENP002435', NULL, NULL),
	(100, 'Grand Greenhouse Changgyeonggung Palace', 'https://english.visitseoul.net/attractions/GrandGreenhouseChanggyeonggungPalace/ENP037176', 'Changgyeonggung Palace, one of the four main historical palaces in Seoul, houses a greenhouse built in 1909. It is Korea\'s first greenhouse designed in a Western architectural style. Initially, there was a botanical garden and a zoo. In 2004, the building was restored, retaining the original appearance of the greenhouse, and is open to the public. Here you will find different types of plants, both local and imported from other countries.', '-10197', '09:00 - 20:45', 'Mondays', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul, Korea (창경???', 'Subway Line 4  Hyehwa Station  Exit 4,  779m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40391&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40393&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40555&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74820&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74821&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57881490, 126.99492980, 'ENP037176', NULL, NULL),
	(101, 'Taereung and Gangreung Royal Tombs', 'https://english.visitseoul.net/attractions/Taereung-and-Gangreung-Royal-Tombs/ENP002299', 'Taereung and Gangneung Royal Tombs are the burial sites of royalty from the Joseon Dynasty. Located in Hwarang-dong, Taereung and Gangneung sit next to each other. The Korea National Training Center for Sports sits between the two royal tombs and the center is operated by the Korean Olympic Committee. Taereung is the royal tomb of Queen Munjeong; the second wife of the 11th Joseon king, Jungjong. Gangneung is the royal tomb of the Queen Munjeong\'s son and the 13th Joseon king, Myeongjong and his wife, Queen Insun. In June 2009, all 40 of the royal tombs of the Joseon Dynasty were designated UNESCO World Heritage sites.', '-6536', '* February to May, September & October: 09:00 - 18:00\n* June to August: 09:00 - 18:30\n* November to January: 09:00 - 17:30\n*Last entry 1 hour before closing', 'Closed Mondays', '01794  681, Hwarang-ro, Nowon-gu, Seoul', 'Subway Line 6  Hwarangdae Station  Exit 4,  1.6km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16323&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16324&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16325&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.63436790, 127.09957360, 'ENP002299', NULL, NULL),
	(102, 'Bosingak Pavilion (Bell Ringing Ceremony)', 'https://english.visitseoul.net/attractions/Bosingak-Pavilion-Bell-Ringing-Ceremony/ENP001904', 'Bosingak Pavilion, a bell tower located in Jongno 2-ga, Jongno-gu, was the original site of the Old Bronze Bell (Treasure No.2). Due to cracks that rendered the bell unringable, it is now housed at the National Museum of Korea in Yongsan. The current bell hanging in Bosingak Pavilion is a newly cast replica, funded through public donations. It was installed on August 14, 1985, and first rung the following day, August 15. Bosingak Pavilion is renowned for hosting Korea??s iconic New Year??s Eve bell-ringing ceremony, where the bell is struck 33 times at midnight on December 31. Additionally, the bell is rung 12 times daily at noon, except on Mondays.', '-3036', 'Bosingak Pavillon Ringing Ceremony 11:00 ~ 12:30 (KST)\n* Reservation required for the bell ringing experience', 'Closed Mondays, March 1st, August 15th, and days with inclement weather', '03189  54, Jong-ro, Jongno-gu, Seoul  (Bosingak Pavilion)', 'Subway Line 1  Jonggak Station  Exit 4,  63m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49978&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49979&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49980&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49981&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49985&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56975990, 126.98366040, 'ENP001904', NULL, NULL),
	(103, 'Yakhyeon Catholic Church', 'https://english.visitseoul.net/attractions/Yakhyeon-Catholic-Church/ENP001845', 'Yakhyeon Catholic Church was the first Western-style church ever built in Korea. Located in Jungnim-dong, the church can be seen from Seoullo 7017. Yakhyeon Catholic Church has historical significance as a religious site and its architecture was hugely influential on the architectural styles of other churches in Korea. The building was destroyed by fire in 1998 but it was subsequently restored.', '-2173', '* Museum 09:00 - 18:00\n* Gallery 09 :00 - 18:00\n\n* Mass Schedule:\nMondays 06:00\nTuesdays 19:00\nWednesdays 10:00\nThursdays 10:00, 19:00\nFridays 10:00 (Mass at Hyeonyangtap at Seosomun Martyrs\' Shrine in Seosomun Park)\nSaturdays 18:00 \nSundays 09:30, 11:00, 18:00 (Elementary, middle school students) / 11:00 (General public) / 18:00 (Youth)\n\n\n** The church is closed to visitors during mass.', 'Museum: Closed Mondays, New Year\'s Day & Chuseok\nChurch: Closed to visitors during mass', '04506  447-1, Cheongpa-ro, Jung-gu, Seoul', 'Subway Lines 2 / 5   Chungjeongno Station  Exit 4,  481m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68753&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68754&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68755&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74161&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.55885430, 126.96749340, 'ENP001845', NULL, NULL),
	(104, 'Wongudan Altar', 'https://english.visitseoul.net/attractions/Wongudan-Altar/ENP004198', 'Wongudan was built during the Joseon Dynasty to be an altar for performing divine harvest rituals. Located in central Seoul right near City Hall, it was designated Historic Site No. 157 in 1967. Through the past few centuries the altar was once called Hwandan and more recently Hwangudan. Now officially known as Wongudan Altar, Wongudan is located in close proximity to other major Seoul tourist attractions so it\'s convenient and easy to add a stop to Wongudan on a Seoul travel itinerary. The current Hwangudan Altar is a complex established in 1897 on the site of the old Nambyeolgung Palace. Its altar was built for Emperor Gojong\'s enthronement ceremony and rituals. The Japanese demolished the original complex in 1913, and a railway hotel was built on the site, reducing its size. Today, only the Hwangungu, the stone drum, and a stone gate with three arches remain preserved within the grounds of the Joseon Hotel.', '-9196', 'Daily 07:00 - 21:00', '', '100-070  106, Sogong-ro, Jung-gu, Seoul', 'Subway Lines 1/2  City Hall Station  Exit 6,  157m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68705&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68706&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68707&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68708&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68709&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.56443780, 126.98009940, 'ENP004198', NULL, NULL),
	(105, 'Seodaemun Prison History Hall', 'https://english.visitseoul.net/attractions/Seodaemun-Prison-History-Hall/ENP001831', 'Seodaemun Prison was used to intern Korean patriots during the Japanese occupation. Until the Liberation of Korea on August 15, 1945, it was known as a clandestine mecca for the anti-Japanese resistance fighters, where they were tortured and executed. The Seodaemun Prison History Hall opened in November 1998 in Seodaemun Independence Park to commemorate the patriots who sacrificed their lives in the fight for Korean independence during the Japanese occupation. It consists of a historic exhibition hall, a central prison, jail cells, a hospital, the patriot memorial, an execution room, a tunnel through which corpses were carried, a watchtower, and a basement jail cell where the female patriot, Yu Gwansun, was tortured and killed.', '-8870', 'March - October 09:30 ??18:00\nNovember - February 09:30 ??17:00', 'Closed Mondays, Lunar New Year, January 1st & Chuseok', '120-080  251, Tongil-ro, Seodaemun-gu, Seoul', 'Subway Line 3  Dongnimmun Station  Exit 5,  209m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73784&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67724&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73785&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73786&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73787&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57421690, 126.95616920, 'ENP001831', NULL, NULL),
	(106, 'Uireung', 'https://english.visitseoul.net/attractions/Uireung/ENP005205', 'Uireung is the royal tomb of King Gyeongjong, the 20th king of the Joseon dynasty, and his wife Queen Seonui. Uireung is located inside the Korea National University of Arts campus in Seokgwan-dong, Seongbuk-gu. Most royal tombs are "ssangneung," tombs that are arranged with the king and queen next to each other. At Uireung, the tombs of the king and the queen are arranged front to back. The tomb in the front is Queen Seonui??s and the one in the back belongs to King Gyeongjong. Uireung is closed Mondays.', '-1463', '* February - May & September - October 09:00 - 18:00 KST (Ticket office closes at 17:00 KST)\n* June - August 09:00 - 18:30 KST(Ticket office closes at 17:30 KST)\n* November - January 09:00 - 17:30 KST (Ticket office closes at 16:30 KST)', 'Closed Mondays', '02789  146-37, Hwarang-ro 32-gil, Seongbuk-gu, Seoul', 'Subway Line 1  Sinimun Station  Exit 1,  945m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2971&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2974&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2975&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74829&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74830&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.60632360, 127.05698490, 'ENP005205', NULL, NULL),
	(107, 'Heonilleung', 'https://english.visitseoul.net/attractions/Heonilleung/ENP005240', 'Heonilleung is a UNESCO World Heritage Site and the final resting place of two pairs of the Joseon Dynasty\'s kings and queens. The name of the site is a combination of the names of the two separate tombs, Heonleung and Inleung. The tombs of Joseon\'s third king, Taejong (1367-1422), and his wife, Queen Wongyeong (1365-1420) are at Heonleung. Inleung is the resting place of Joseon\'s 23rd king, Sunjo (1790-1834), and his wife Queen Sunwon (1789-1857). Heonilleung is unique in that it houses two kings born 400 years apart. Visitors to the royal tombs can see examples of early and late Joseon Dynasty royal tombs and there is a weekly talk about the tombs every Saturday. On Lunar New Year\'s Day, traditional performances are held at Heonilleung for the public to enjoy.', '-712', '* February - May & September - October 09:00 - 18:00 KST\n* June - August 09:00 - 18:30 KST\n* November - January 09:00 - 17:30 KST', 'Closed Mondays', '06795  36-10, Heonilleung-gil, Seocho-gu, Seoul', 'Subway Line 3, Yangjae Station, Exit 7. From the Yangjae Station - Seocho Cultural Arts Center bus stop 240m  board buses 440, 741, or 452 and get off at the Heonilleung??Gangnam Seocho Science Reserve Training Center stop. Heonilleung is 662m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23336&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23337&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23338&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23339&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23340&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.47045070, 127.07940160, 'ENP005240', NULL, NULL),
	(108, 'Sodeokmun Gate (Seosomun)', 'https://english.visitseoul.net/attractions/Site-of-Sodeokmun-Gate-Seosomun/ENP023758', 'Sodeokmun Gate was one of the 4 minor city gates of Seoul. It was constructed during the Joseon Dynasty in the reign of King Taejong. Sodeokmun was torn down in 1914 during the Japanese colonial period under the pretext of ??urban planning.??No traces of Sodeokmun Gate remain today but a plaque marks the site of the gate.', '-40', '', '', '04513  100, Seosomun-ro, Jung-gu, Seoul', 'Subway Lines 1/2  City Hall Station  Exit 9,  300m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22980&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22981&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22982&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22983&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22984&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56177520, 126.97406310, 'ENP023758', NULL, NULL),
	(109, 'Sayuksin Park', 'https://english.visitseoul.net/attractions/Sayuksin-Park-EN/ENP004513', 'Sayuksin Park is located atop a hill between the Hangang River and Noryangjin Station. The park encompasses the historic Sayuksinmyo Tombs and the surrounding hilly area. The tombs hold the designation of Seoul Cultural Asset No. 8 and they are the burial site of seven Korean loyalists to the King Danjong, 6th king of the Joseon Dynasty. King Danjong was forced to abdicate by his uncle, who then assumed to the throne to become King Sejo. Seong Sam-Mun, Park Paeng-Nyeon, Ha Wi-Ji, Yi Gae, Yu Seong-Won, Yu Eung-Bu, and Kim Mun-Gi who opposed King Sejo and were buried here by the Hangang River.', '-10584', 'Daily 09:00 - 18:00', '', '06902  191 Noryangjin-ro, Dongjak-gu, Seoul', 'Subway Line 9  Nodeul Station  Exit 1,  432m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68827&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68828&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68830&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68829&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73780&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.51383940, 126.94818580, 'ENP004513', NULL, NULL),
	(110, 'Kyungguksa', 'https://english.visitseoul.net/attractions/2024-kgtemple/ENPkxi16h', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Gyeongguksa Temple, nestled on the eastern slopes of Samgaksan (now known as Bukhansan), is a historic temple founded in the late Goryeo period. Renowned for its scenic mountain surroundings and fresh spring water, it attracts many visitors. The temple complex has 17 buildings, including Geungnakbojeon (Hall of Supreme Bliss), Yeongsanjeon, Myeongbujeon, Gwaneumjeon, and Sibangseonwon. Geungnakbojeon houses the Amitabha Buddha triad, along with wooden Buddhist paintings (designated as Treasure No. 748), Shinjungtaenghwa, and Palsangtaenghwa. Sibangseonwon offers a weekly Sunday meditation session, and the temple also hosts temple stay programs at Hwanheodang and Manwoldang. As one of Seoul\'s significant temples, Gyeongguksa was frequently visited by former President Syngman Rhee. During his tenure as Vice President, Richard Nixon of the United States visited the temple and later described it as one of his most memorable experiences in his memoirs, even including a photograph of his visit.', '-3662', '', '', '02705  113-10 Bogungmun-ro, Seongbuk-gu, Seoul', 'Subway  Ui-Sinseol Line  Bukhansan Bogungmun Station  Exit 2,  252m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67112&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67113&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67114&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67115&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67116&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61342480, 127.00440170, 'ENPkxi16h', NULL, NULL),
	(111, 'Donuimun Gate (Seodaemun)', 'https://english.visitseoul.net/attractions/Site-of-Donuimun-Seodaemun/ENP023759', 'Donuimun Gate was one of the four minor city gates to Seoul and it stood at the Joseon-era western boundary to the city. Today, the area where the gate stood is now known as Seodaemun. The gate was constructed during the Joseon Dynasty and stood for centuries before being destroyed in 1915 during the Japanese colonial period.', '-40', '24 hours', 'Monday', '170 Sinmunno 2(i)-ga, Jongno-gu, Seoul, Republic of Korea', 'Subway Line 5, Seodaemun Station, Exit 4, 262m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18082&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49975&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49976&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49977&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56862120, 126.96847640, 'ENP023759', NULL, NULL),
	(112, 'Jongmyo Shrine', 'https://english.visitseoul.net/attractions/Jongmyo/ENP000507', 'Jongmyo is a royal shrine dedicated to the performance of ancestral rites for the deceased kings and queens of the Joseon Dynasty. Being the place where the royal ancestral tablets are enshrined, Jongmyo\'s atmosphere is solemn and sacred rather than splendid like the royal palaces. The simple and elegant buildings of this shrine have faithfully kept their original forms since the 16th century. Jongmyo is made up of Jeongjeon (the main hall), Yeongnyeongjeon (the hall of eternal peace), and auxiliary buildings such as Jeonsacheong, Eosuksil, Hyangdaecheong and Sindang. Jeongjeon, the main hall of Jongmyo, is a place steeped in royal history and is highly esteemed for its outstanding architecture. It is said to be the world\'s longest single wooden structure with a length measures 109 meters. The main hall is an outstanding example of traditional Korean architecture. Jongmyo was designated as a UNESCO World Cultural Heritage site together with Jongmyo Jerye and Jongmyo Jeryeak. Jongmyo Jerye is the royal ancestral ritual and has been performed for 600 years. The court music performed during the ritual is the Jongmyo Jeryeak.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Jongmyo Shrine", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "752" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Leslie S" }, "reviewBody": "The English language tour was very interesting and informative. The site is beautiful and peaceful. I would recommend it to gain insight into Korean history", "datePublished": "2024-06-02" } }] }', '-880', 'Monday, Wednesday to Friday: Timed Tours (Enter at designated times, accompanied by a guide, and exit together as a group)\n- Korean Guided Tour Times: 9:20 / 10:20 / 11:20 / 12:20 / 13:20 / 14:20 / 15:20 / 16:20 / (March to September) 16:40 *Duration: 1 hour\n- English Guided Tour Times: 10:00 / 12:00 / 14:00 / 16:00\n- Japanese Guided Tour Times: 09:30 / 11:40 / 13:40 / 15:40\n- Chinese Guided Tour Times: 11:00 / 15:00\n\nRegular Admission on Saturdays, Sundays, Public Holidays, and the last Wednesday of every month:\n- February to May, September to October: 09:00-18:00 (Last entry at 17:00)\n- June to August: 09:00-18:30 (Last entry at 17:30)\n- November to January: 09:30-17:30 (Last entry at 16:30)\n(??Please refer to the website for detailed information.)', 'Tuesdays', '03135  157, Jong-ro, Jongno-gu, Seoul', 'Subway Lines 1/3/5  Jongno 3-ga Station  Exit 8,  220m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68173&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68174&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68175&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68176&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68177&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57257520, 126.99391030, 'ENP000507', NULL, NULL),
	(113, 'Sulla-gil Road', 'https://english.visitseoul.net/attractions/Sulla-gil-Road/ENP001932', 'Sulla-gil Road runs through Jongno-gu and is known as Seoul\'s Historical Literary Trail. Sulla-gil is divided into eastern and western sections. Dongsulla-gil is the eastern section and Seoseulla-gil is the street\'s western section.', '-40', '', '', '03134  Seosulla-gil, Jongno-gu, Seoul', 'Subway Lines 1/3/5, Jongno 3(sam)-ga Station  Exit 7,  471m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72657&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72658&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72659&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72660&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72661&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57500150, 126.99174310, 'ENP001932', NULL, NULL),
	(114, 'Seonjeongneung (Tomb)', 'https://english.visitseoul.net/attractions/Seonjeongneung-Tomb/ENP001414', 'Seonjeongneung is the name of Seolleung and Jeongneung combined, and it refers to the royal tombs of King Seongjong (the 9th king of the Joseon Dynasty), Queen Jeonghyeon (the second wife of King Seongjong) and King Jungjong (a son of the two). Seonjeongneung was designated as a UNESCO World Heritage site in 2009, enhancing its status as historic remains. It is easily accessible as it is situated close to Seolleung Station, Subway Line 2. It makes an ideal place for the public to enjoy a stroll.    Seolleung, the tomb of King Seongjong (reigned 1469-1494) was built in 1495; subsequently, the tomb of Queen Jeonghyeon (1462-1530) was built on the east side of Seolleung in 1530. Jeongneung, which is the tomb of King Jungjong (the 11th king of the Joseon Dynasty, reigned 1506-1544), was built in 1544, and was moved from its original site in Wondang, Goyang-gun, Gyeonggi-do, to this current location in 1562 by Queen Munjeong (the second wife of King Jungjong, 1501-1565). Seonjeongneung is designated as Historic Site No. 199 as well as being a UNESCO World Heritage site.    Frequently Asked Questions about Seonjeongneung (Tomb)         How much is the Seonjeongneung Royal Tomb entrance fee?         The admission fee for Seonjeongneung Royal Tomb is as follows. (As of 2025)     ??Individual  - Ages 25 to 64 (Koreans), 19 to 64 (Foreigners) : 1,000 KRW    ??Groups (more than ten people)  - Ages 25 to 64 (Koreans), 19 to 64 (Foreigners) : 800 KRW    Please refer to the official website for free admissions and discounts.          I am curious about the Seonjeongneung Royal Tomb\'s parking information.         There are 48 (2 accessible) parking spaces at the Seonjeongneung Royal Tomb. The parking lot operates 365 days a year, even on holidays. Parking rates are as follows. *The parking lot close after 22:00       (As of 2025)         ??2 hours or less : 400 KRW per 5 minutes   ??Over 2 hours : 600 KRW per 5 minutes            Are there any tourist attractions worth visiting near Seonjeongneung Royal Tomb?         These are the following tourist attractions around Seonjeongneung Royal Tomb.     ?? Starfield Coex Mall    ?? Starfield Library    ?? Garosu-gil        { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "How much is the Seonjeongneung Royal Tomb entrance fee?", "acceptedAnswer": { "@type": "Answer", "text": "<div> The admission fee for Seonjeongneung Royal Tomb is as follows. (As of 2024)<br><br> <ul> <li>Individual</li>- Ages 25 to 64 (Koreans), 19 to 64 (Foreigners) : 1,000 KRW<br>- Ages 7 to 18 (foreigners) : 500 KRW<br><br> <li>Groups (more than ten people)<br>- Ages 25 to 64 (Koreans), 19 to 64 (Foreigners) : 800 KRW<br>- Ages 7 to 18 (foreigners) : 400 KRW</li> </ul><br> Please refer to the official website for free admissions and discounts. </div>" } }, { "@type": "Question", "name": "I am curious about the Seonjeongneung Royal Tomb\'s parking information.", "acceptedAnswer": { "@type": "Answer", "text": "<div> There are 48 (2 accessible) parking spaces at the Seonjeongneung Royal Tomb. The parking lot operates 365 days a year, even on holidays. Parking rates are as follows. *The parking lot closes after 22:00 (As of 2024)<br><br> <ul> <li>2 hours or less : 400 KRW per 5 minutes</li> <li>Over 2 hours : 600 KRW per 5 minutes</li> </ul> </div>" } }, { "@type": "Question", "name": "Are there any tourist attractions worth visiting near Seonjeongneung Royal Tomb?", "acceptedAnswer": { "@type": "Answer", "text": "<div> These are the following tourist attractions around Seonjeongneung Royal Tomb.<br><br> <ul> <li><a href=\\"https://english.visitseoul.net/shopping/COEX-Mall_/271\\"style=\\"color:#0000EE;text-decoration:underline\\">Starfield Coex Mall</a></li> <li><a href=\\"https://english.visitseoul.net/gangnamarea/Starfield-Library_/26568\\"style=\\"color:#0000EE;text-decoration:underline\\">Starfield Library</a></li> <li><a href=\\"https://english.visitseoul.net/shopping/Garosu-gil-in-Sinsadong_/292\\"style=\\"color:#0000EE;text-decoration:underline\\">Garosu-gil</a></li> </ul> </div>" } }, { "@type": "LocalBusiness", "name": "Seonjeongneung (Tomb)", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4", "ratingCount": "168" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "CanisHan" }, "reviewBody": "This royal tomb was located in the center of Gangnam area in contrast with most royal tomb in suburb. There was very good to walk slowly, and could view about Choseon\'s tomb style. Though there was not unique things, but made me calm. There was rest area in center of city like as silent park.", "datePublished": "2021-01-03" } }] }', '-1779', 'March - October, Daily 06:00 - 21:00 \nNovember - January, Daily 06:00 - 17:30 \nFebruary, 06:00 - 18:00', 'Closed Mondays', '135-090  1, Seolleung-ro 100-gil, Gangnam-gu, Seoul', 'Subway Line 2 / Suin-Bundang Line  Seolleung Station  Exit 10,  444m\nSubway Line 9 / Suin-Bundang Line  Seonjeongneung Station Exit 3,  1,000m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32605&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32606&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32607&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32608&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=32609&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.50715350, 127.04942540, 'ENP001414', NULL, NULL),
	(115, 'Seoul Museum of Craft', 'https://english.visitseoul.net/attractions/Seoul-Museum-of-Craft/ENP038092', 'Seoul Museum of Craft Art aims to be an open space where traditional crafts and modern crafts can come together to share the value of crafts and to be the key to unlocking the future of crafts. The museum features galleries on the "beginning of crafts" from mankind long ago, when clay was molded, engraved, and baked, as well as galleries and exhibitions that focus in on the technical, practical, artistic, and cultural values of crafts throughout time and space.', '-13370', '10:00 - 18:00 (Last admission at 17:30)\nFri 10:00 - 21:00', 'Mondays, January 1st, Open on Public Holidays', '03061  4, Yulgok-ro 3-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  141m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67121&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67122&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67123&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67124&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73865&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57685830, 126.98358020, 'ENP038092', NULL, NULL),
	(116, 'Seosomun Shrine History Museum', 'https://english.visitseoul.net/attractions/Seosomun-Shrine-History-Museum/ENP030804', 'Seosomun Shrine History Museum is a history museum where visitors can go see the history of Catholicism in the late Joseon Dynasty.Passing the inscription of Lee Seung-hoon\'s "Wolrakjaecheonsusangjijin" (Moon Falls on the Water) at the entrance, visitors are led to an open plaza. The displays of artworks leads into the library and seminar rooms on the first floor. The special exhibitionhalland small assembly hall is located on the B2 level while the Consolation Hall, permanent exhibition, and Sky Square is located on the third basement floor.The most popular spot inside this attraction is Sky Square. Constructed so that the ceiling connects to the ground level and opens itself up to the sky, this space clearly symbolizes the theme of Seosomun Martyrs\' Shrine and the open pathway betweentheearth and sky.', '-5468', 'Tuesday ~ Sunday 09:30 - 17:30', 'Closed Mondays', '04510  5, Chilpae-ro, Jung-gu, Seoul', 'Subway Line 2/5  Chungjeongno Station  Exit 4,  417m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23421&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23422&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23420&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23423&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73788&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56041780, 126.96862490, 'ENP030804', NULL, NULL),
	(117, 'Seoul Baekje Museum', 'https://english.visitseoul.net/attractions/Seoul-Baekje-Museum/ENP011610', 'The Seoul Baekje Museum is a history museum that was established at the prehistoric site of Baekje-era ruins in Songpa-gu, Seoul. The museum preserves and studies the relics of Baekje and prehistoric Korea. Visitors can learn more about Korea\'s history at the museum\'s 4D theater and exhibition halls. The Seoul Baekje Museum has an extensive collection of artifacts and relics, and there are also educational programs to participate in and enjoy. Learn about Korean history and cultures at the museum!', '-7872', 'Weekdays 09:00 - 19:00\n Fri 09:00~21:00\nWeekend (November - February 09:00 - 18:00) (KST)', 'Closed Mondays & New Year\'s Day\n(Museum opens on holidays that fall on a Monday)', '05540  71, Wiryeseong-daero, Songpa-gu, Seoul', 'Subway Line 9  Hanseong Baekje Station  Exit 2,  363m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=5757&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12174&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74754&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74755&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74756&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.51900920, 127.12163300, 'ENP011610', NULL, NULL),
	(118, 'Seoul Yangnyeongsi Herb Medicine Museum', 'https://english.visitseoul.net/attractions/Yangnyeongsi-Herb-Medicine-Museum/ENP004632', 'The Seoul Yangnyeongsi Herb Medicine Museum was established to preserve and pass on the history and knowledge of traditional Korean medicine. Fittingly, the museum is located across from the Seoul Yangnyeong Market, one of the most famous oriental medicine markets in Korea from which approximately 70% of the nation\'s oriental medicine is distributed. The museum collects, manages, and stores many artifacts and materials to exhibit. Visitors will be able to see everything from the herbs and plants used in traditional medicine, to antique medical records and tools. Admission to the museum is free.', '-10130', 'March - October 10:00 - 18:00\nNovember - February 10:00 - 17:00\n??Last entry is 30 min. before closing', 'Closed Mondays, New Year\'s Day & national holidays', '02566  26, Yangnyeongjungang-ro, Dongdaemun-gu, Seoul', 'Subway Line 1, Jegi-dong Station  Exit 2,  320m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40031&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40032&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40033&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40034&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40035&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.58065490, 127.03762670, 'ENP004632', NULL, NULL),
	(119, 'Kim Geun-tae Memorial Library-Archives', 'https://english.visitseoul.net/attractions/Kim-Geun-tae-Memorial-Library-Archives/ENP041903', 'Kim Geun-tae Memorial Library-Archives which is located at the corner of the way going to Bukhansan National Park, as a Larchiveum, it is a library to read a book but at the same time, it\'s a museum that has a story of democracy and human rights, and also an art gallery to appreciate art works. A courtyard, which was naturally made at the center which was created by connecting the both ends of the two buildings with the bridge, is the most opened space in Kim Geun-tae Memorial Library-Archives and it\'s a space where you can directly feel the sunlight and the wind. As a library and an art gallery, the installation work is located on the courtyard so you can see an art work in the nature. At the rooftop called \'Sanbaramgil\',  various plays and events will be held with the background of the nature.', '-3976', 'Daily 09:00 ~ 20:00\nWeekends 09:00 ~ 17:00', 'Every Monday, National Holiday', '01301  14, Dobongsan-gil, Dobong-gu, Seoul', 'Subway Line 1/7   Dobongsan Station  Exit 1,  300m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54699&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54700&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54701&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54702&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=54703&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.69050520, 127.04233880, 'ENP041903', NULL, NULL),
	(120, 'SeMA Museum of Photography', 'https://english.visitseoul.net/attractions/SeMA-photo-museum/ENPl3j0oy', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The SeMA Museum of Photography, newly opened in Changdong, Dobong-gu, Seoul, is a branch of the Seoul Museum of Art and the first and only public art museum in Korea specializing in photography, established after more than a decade of preparation. The museum plans to continue diverse activities to become a new center for photographic art in Korea and Asia through creative and experimental exhibitions and programs encompassing the entire photography culture and in-depth research, collection, and preservation activities.Notably, the museum is equipped with facilities where visitors can experience the influence and artistic value of photography, including exhibition halls, education rooms, darkrooms, a photo library, and a photobook café for educational programs covering all age groups.The architecture was designed by Austrian architect Mladen Jadric (representative of Jadric Architektur ZTGmbH) and 1990 Urban Architecture (representative Yoon Geun-ju), who visualized and implemented the pixel of photography, which is a picture drawn with light.', '+82 2??124??600', 'Tuesday-Friday 10:00 AM-8:00 PM\nSaturday, Sunday, Holidays\nSummer (March-October) 10:00 AM-7:00 PM\nWinter (November-February) 10:00 AM-6:00 PM\nCulture Day (last Wednesday of each month) 10:00 AM-10:00 PM', 'Closed on January 1 and every Monday * Open on Mondays that fall on holidays', '01411  SeMA Museum of Photography, 68 Madeul-ro 13-gil (Changdong), Dobong-gu, Seoul', 'Subway Line 1/4, Changdong Station, Exit 1, 264m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72487&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72488&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72489&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72490&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73910&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.65553980, 127.04884140, 'ENPl3j0oy', NULL, NULL),
	(121, 'Kukje Gallery', 'https://english.visitseoul.net/attractions/Kukje-Gallery/ENP003241', 'The Kukje Gallery is one of Korea\'s major art galleries and visitors can see artworks from new and established artists. Founded in 1982, the Kukje Gallery exhibits works from prominent foreign artists, but the gallery also exhibits and fosters promising Korean artists. Enjoy incredible contemporary art at the Kukje Gallery.', '-9104', '* Monday - Saturday 10:00 - 18:00 (KST)\n* Sundays & National Holidays 10:00 - 17:00 (KST)', '', '100-200  54, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  812m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16442&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16443&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16444&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73930&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73931&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58072260, 126.98084790, 'ENP003241', NULL, NULL),
	(122, 'National Museum of Art at Deoksugung Palace', 'https://english.visitseoul.net/attractions/National-Museum-of-Art-Deoksugung-Palace/ENP001707', 'The National Museum of Modern and Contemporary Art at Deoksugung opened in 1998 as an annex of the National Museum of Modern and Contemporary Art, Korea. The museum building, Seokjojeon Hall, is located at Deoksugung Palace. Seokjojeon Hall is an exquisite example of Western architecture from the early 20th century. It is the only Korean palace to have an outdoor garden and fountain designed in a Western style. The museum??s location inside the palace means that many visitors choose to combine their visit with a tour of Deoksugung. Jeongdong Park, the Seoul Museum of Art, and Namdaemun Market are some of the nearby tourist attractions. Admission fees vary depending on exhibition but visitors will be able to see beautiful works of art from Korean and international artists.', '-2542', 'Tuesdays, Thursdays, Fridays & Sundays 10:00 - 19:00\nWednesdays & Saturdays 10:00 - 21:00\n* Last entry is 1 hour before closing.', 'Closed Mondays & New Year\'s Day', '04519  99, Sejong-daero, Jung-gu, Seoul', 'Subway Lines 1/2  City Hall Station  Exit 1,  72m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22661&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22662&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22663&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74752&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74753&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56740220, 126.97549920, 'ENP001707', NULL, NULL),
	(123, 'Seodaemun Museum of Natural History', 'https://english.visitseoul.net/attractions/Seodaemun-Museum-of-Natural-History/ENP002613', 'p { text-align: justify; word-spacing: 2px; }  The four-story building of the Seodaemun Museum of Natural History was the first public museum of natural history in Korea. Opened in 2003, the museum displays the origins of life on earth through a variety of real specimens of minerals, rocks and fossils, and through models, including life size models of dinosaurs, from all over the world. The museum is a fun and family-friendly attraction.', '-9149', '* March to October \nWeekdays 09:00 ??18:00 & Weekends 09:00 ??19:00\n* November to February\nWeekdays 09:00 ??17:00 & Weekends 09:00 ??18:00\n\n(Last entry 1 hour before closing)', 'Closed Mondays, January 1st, Lunar New Year & Chuseok', '03718  51, Yeonhui-ro 32-gil, Seodaemun-gu, Seoul', 'Subway Line 2, Sinchon Station Exit 3, take Seodaemun 03 bus from Sinchon Station stop, get off at Seodaemun Natural History Museum Entrance stop, 283m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17244&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17245&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17246&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17247&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72587&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57667300, 126.93747410, 'ENP002613', NULL, NULL),
	(124, 'Reopening of Dongdaemun History Museum Exhibition Hall', 'https://english.visitseoul.net/attractions/exhibitionhallreopening/ENP026206', 'The Dongdaemun History Museum, operated under the Seoul Museum of History, reopened the doors to its permanent exhibition hall following the two-year renovation project on Tuesday, August 11, 2020. The entire, all-new remodeled interior floor is set with carvings and gobo projectors that capture the blueprint of the excavation site of historical remains by layer to emulate the historical, figurative layers that are stacked upon each other at this very geographical site. The exhibition is characterized into the following four different themes: I. Military Training Administration & Lower Directorate; II. City Wall Floodgates; III. Two Centuries of Change; and IV. Excavated History. There are also various, fun programs for children within the exhibition and hands-on space provided that feature sand-crafting, 3D photo zones, and more.', '-2273', 'Daily 10:00 - 18:00', 'Closed Mondays & New Year\'s Day', '04566  281, Eulji-ro, Jung-gu, Seoul  (Dongdaemun History & Culture Park)', 'Subway Lines 2/4/5  Dongdaemun History & Culture Park Station  Exits 1/2,  356m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31627&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31628&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31631&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31632&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56602860, 126.99549240, 'ENP026206', NULL, NULL),
	(125, 'Amore Pacific Museum of Art (APMA)', 'https://english.visitseoul.net/attractions/Amore-Pacific-Museum-of-Art-APMA/ENP030803', 'p{ text-align:justify; word-spacing:2px; }Amore Pacific Museum of Art (APMA) is a newly opened museum inside Amore Pacific\'s Yongsan headquarters. Aiming for "an open space to find beauty in the ordinary", this museum was established as a space for fostering open communication. To this end, the museum collects, studies, and exhibits anicent Korean and contemporary arts, also supporting researchers, academic societies, and young writers in the process. The basement floor features an exhibition showcasing ancient Korean art and contemporary art. Connecting the first three floors, the "Atrium" features the museum lobby, museum shop, another exhibition space called "APMA Cabinet," and a library for museums around the world (apLAP).', '-8305', 'Daily 10:00 - 18:00', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok', '04386  100, Hangang-daero, Yongsan-gu, Seoul', 'Subway Line 4  Sinyongsan Station  Exit 1,  84m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23416&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23418&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73974&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23417&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23419&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52897320, 126.96926550, 'ENP030803', NULL, NULL),
	(126, 'Horim Museum', 'https://english.visitseoul.net/attractions/Horim-Museum-Sinsa/ENP005546', 'The Horim Museum is a privately-run art museum in Korea. The museum is comprised of three buildings, and the museum\'s five-story building hosts much of the art collection. The second, third, and fourth floors display antique and modern art as well as special exhibitions. On the last Thursday of each month, admission to the Horim Museum is free.', '-3986', '10:30 - 18:00 (Last entry 17:00)\n\n- Temporarily closed from 7/27 to 9/1 due to exhibition change at the Shinsa branch', 'Closed Mondays,Sundays, January 1st, Lunar New Year & Chuseok', '06021  317, Dosan-daero, Gangnam-gu, Seoul', 'Subway Suin-Bundang Line  Apgujeong Rodeo Station  Exit 5,  635m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3124&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3125&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3126&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72589&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72590&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52297000, 127.03543070, 'ENP005546', NULL, NULL),
	(127, 'Alive Museum', 'https://english.visitseoul.net/attractions/Alive-Museum-en/ENP024389', 'Firstly opened/introduced the illusive art museum in Korea, called ??Trick Art Museum??in 2009. Since then, with continuously have been developing innovative digital technologies, we launch trick art theme park, ??Alive Museum?? and operate several branches world-widely.', '-2584', '', '', '06221  218, Teheran-ro, Gangnam-gu, Seoul', 'Subway Line 2, Yeoksam Station, Exit 1', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18375&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18376&fileTy=MEDIA&fileNo=1&thumbTy=L', 2, 37.50143600, 127.04095320, 'ENP024389', NULL, NULL),
	(128, '2Gil29Gallery', 'https://english.visitseoul.net/attractions/2024-2Gil29Gallery/ENPrisi5i', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Located in the vibrant Garosu-gil area of Sinsa-dong, Gangnam, where diverse interests and dynamic Seoul culture converge, 2Gil29 Gallery has been actively introducing contemporary art to the public since its opening in 2015. The gallery has fostered active exchanges with prominent Korean artists such as Hong Jung-hee, Choi Sun-ho, Nam June Paik, Lim Young-kyun, and Kang Suk-young while also showcasing works by artists like Kwon Young-ho and Charlie Han to diversify the Korean art market.The gallery??s curatorial approach is based on a wide range of creative works, fostering a more positive and progressive discourse on art. Through deeper communication and interaction with art, it transcends mere visual and auditory engagement, offering meaningful aesthetic and spiritual exchanges with artists. This, in turn, enhances the value of their creative endeavors.In addition, 2Gil29 Gallery is committed to discovering and nurturing emerging talents such as upcycling artist Hong Ji-hee, singer-turned-painter Yoo Hyun-suk, and Kwon Jae-hyuk, a graduate of the University of the Arts London (UAL).', '-8138', '10:00-18:00', 'Closed on Sundays and Mondays  \nClosed for Chuseok holidays from September 16 to 18', '06034  35 Gangnam-daero 158-gil, Gangnam-gu, Seoul', 'Subway Line 3 /Shinbundang Line  Sinsa Station  Exit 8,  460m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67532&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67533&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67534&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67535&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.51978040, 127.02147440, 'ENPrisi5i', NULL, NULL),
	(129, 'Heo Jun Museum', 'https://english.visitseoul.net/attractions/Heo-Jun-Museum/ENP001403', 'The Heo Jun Museum commemorates the life and works of the renowned Joseon-era doctor and scholar, Heo Jun. The museum is located in Gayang-dong near Guam Park and the neighborhood is known as the birthplace of Heo Jun. Visitors can see a range of items relating to Oriental medicine, items once owned by Heo Jun, and medical books. Some of the books on display were written out by Heo Jun\'s hand. A writing model of his most famous work, "Dongui Bogam," is on display and it is still an influential medical tome in Oriental medicine today.', '-12267', '* March - October Weekdays 10:00 - 18:00 & Weekends/Holidays 10:00 - 17:00\n* November - February Weekdays 10:00 - 17:00 & Weekends/Holidays 10:00 - 17:00 (KST)\n??Ticketing stops 1 hour prior to closing.', 'Closed Mondays, Jan. 1st, Lunar New Year\'s Day & Chuseok', '07525  87, Heojun-ro, Gangseo-gu, Seoul', 'Subway Line 9  Gayang Station  Exit 1,  736m\nSubway Line 5  Balsan Station Exit 3, take bus 6657, 6630, 1002 and get off at Hanbogu Ammaeul Apartment, 243m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16357&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16358&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16359&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16360&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75425&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56686850, 126.85295820, 'ENP001403', NULL, NULL),
	(130, 'National Hangeul Museum', 'https://english.visitseoul.net/attractions/NationalHangeulMuseum/ENP035405', 'The National Hangeul Museum was opened on October 9, 2014, to create and promote the literary and cultural value of Hangeul, the nation\'s most significant cultural heritage. The National Hangeul Museum investigates, collects, and researches materials scattered around the country and abroad and shows the cultural diversity and future value of Hangeul through exhibitions. It is a place where Hangeul culture blossoms through education that aims for communication and empathy across generations and nationalities.', '-8244', '10:00 - 18:00\n- Closed for construction from October 2024 to October 8, 2025', 'January 1, Lunar New Year\'s Day, Chuseok\n* Closed days of the Hangeul Library: Saturdays, Sundays, and public holidays (except Hangeul Day)', '04383  139, Seobinggo-ro, Yongsan-gu, Seoul', 'Subway Line 4 / Gyeongui Central Line  Ichon Station  Exit 2,  500m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=52753&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=52755&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=52757&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=52759&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=52761&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.52686140, 126.98073150, 'ENP035405', NULL, NULL),
	(131, 'Gallery Mosoon', 'https://english.visitseoul.net/attractions/2024-mosoon/ENPxua216', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Located on Jeongdong-gil, within the 100-year-old modern cultural heritage site ??Shina Memorial Hall,??this gallery showcases Korean crafts and art. It was established with the hope that visitors traveling from afar will feel that their journey to and from the gallery is part of the exhibition experience itself. Unlike other spaces in Shina Memorial Hall, the gallery has been remodeled with white cube walls and ceilings to give it a more contemporary feel. With each changing exhibition, the gallery introduces new playlists, scents, and furniture, creating a fresh experience every time. Come and appreciate Korean crafts in this cozy and serene space.', '-2294', '12:00~18:00', 'Sun-Mon', '04518  Shina Memorial Hall, Room 203, 33 Jeongdong-gil, Jung-gu, Seoul', 'Subway Line 1/2  City Hall Station  Exit 12,  507m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66550&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66551&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66552&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66553&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56621780, 126.97216310, 'ENPxua216', NULL, NULL),
	(132, 'PKM Gallery', 'https://english.visitseoul.net/attractions/PKM-Gallery/ENP002885', 'p { text-align: justify; word-spacing: 2px; }  The PKM Gallery was established in 2001 and a range of art from diverse mediums can be found on display. Exhibitions include paintings, sculptures, and videos, while the gallery\'s goal is to be known for its quality of art. Prominent Korean and foreign artists fill the gallery\'s rosters and some of the more prominent names are Lee Bul, Jorge Pardo, Michael Joo, and Stephen Prina.', '-10121', 'Tuesday - Sunday 10:00 - 18:00 (KST)', 'Closed Mondays', '03049  40, Samcheong-ro 7-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1823&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1824&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=1825&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75563&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75564&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58406680, 126.98009920, 'ENP002885', NULL, NULL),
	(133, 'ChoiManLin Museum', 'https://english.visitseoul.net/attractions/ChoiManLin-Museum/ENP042352', 'Theelegant two-story, Western-style building was built in the 1970s. Here,sculptor Choi Man Lin created his world of art for about 30 years from 1988. Evenwith all its traces of artistry intact, it eventually grew to become the ChoiMan Lin Museum with the help of the Seongbuk-gu District and EMA Architects. Reborn as an art museum in2019, this building contains the traces of sculptor Choi Man Lin, which werepreserved through a remodeling method that protects the appearance of theexisting building as much as possible. Thisbuilding, which shows off its architectural beauty while maximizing itsfunction as an art museum, won the Excellence Award at the 2020 Public BuildingAwards of Korea.', '-11888', 'Daily 10:00 ~ 18:00\nClosed for exhibition preparation (July 1 - September 3)', 'Closed Sundays & Mondays', '02708  23, Solsaem-ro 7-gil, Seongbuk-gu, Seoul', 'Subway Uisinseol   Bukhansanbogukmun Station Exit 2,  438m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56158&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56159&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56160&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56161&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56162&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61067350, 127.00432190, 'ENP042352', NULL, NULL),
	(134, 'Ilmin Museum of Art', 'https://english.visitseoul.net/attractions/Ilmin-Museum-of-Art/ENP002251', 'Ilmin Museum of Art is a private art museum that mainly exhibits Korean contemporary art. It was originally established to commemorate Kim Sangman, former president of the Donga Ilbo, one of Korea\'s leading media outlets. The museum\'s name was taken from Kim\'s pen name, Ilmin (meaning ??one people??or ??a nation united??in Korean). The museum is run by the Ilmin Cultural Foundation and a variety of special exhibitions and art classes are held throughout the year. The museum has a cafe and restaurant on the first floor.', '-3990', 'Daily 11:00 - 19:00 KST', 'Closed on Mondays', '03187  152, Sejong-daero, Jongno-gu, Seoul', 'Subway Line 5  Gwanghwamun Station  Exit 5,  16m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12728&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12729&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12730&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12731&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56963290, 126.97847160, 'ENP002251', NULL, NULL),
	(135, 'Kim Chong Yung Museum', 'https://english.visitseoul.net/attractions/Kim-Chong-Yung-Museum/ENP002066', 'The Kim Chong Yung Museum was established to honor the legacy and art of the modern artist Kim Chong Yung and to provide support to young artists. Kim was a pioneer of modern scultpure and the museum\'s main hall has a permanent exhibition with Kim\'s works and the new hall showcases artwork from new artists. Art and cultural classes are offered at the museum in two semesters during the calendar year. Admission to the Kim Chong Yung Museum is free.', '-9621', 'March - October 10:00 - 18:00\nDecember - February 10:00 - 17:00 (KST)\n*Café Samiru Operating Hours: 11:00 - 21:00', 'Closed Mondays', '110-848  30, Pyeongchang 32-gil, Jongno-gu, Seoul', 'Subway Line 3 Gyeongbokgung Station Exit 3,  take Bus 1711 and get off at Lotte Apartment, 365m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72868&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72869&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72870&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72871&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72872&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61302770, 126.97764870, 'ENP002066', NULL, NULL),
	(136, 'Arario Gallery Seoul', 'https://english.visitseoul.net/attractions/ArarioGallery/ENP002388', 'p { text-align: justify; word-spacing: 2px; }  Over the years, Arario Gallery Seoul has led the way in curating a harmonic fusion and variety of different art forms in Korea\'s art community through bold collaborations with international artistry that have never been attempted before. Also, the gallery takes the forefront in introducing artwork from today\'s more modern Korean artists having implemented an ongoing and structured system of exclusively-contracted artists. Currently, a wide range of artworks from artists native to India and Southeast Asia, who have yet to come to Korea despite having already experienced China\'s art community, are finally getting some spotlight in Korea. What\'s better is that with the help of continued promotional activity, the search and funding for up-and-coming talent in the respective regions is ongoing as well. Thanks to the gallery\'s efforts grounded in a system of exclusive artists displaying excellence; various collaborations with other galleries, both at home and abroad; introductions of varied artworks from numerous places around the world; and more, the Arario Gallery is set to play out its role as Asia\'s signature gallery that expands upon the possibilities for the future of Korea\'s art community while leading the market as well.      Since its first opening in Sogyeok-dong, Jongno-gu, in 2006, Arario Gallery Seoul has been leading the contemporary art scene based on its solid artist system and bold exhibition planning capabilities. In March 2014, it relocated near the National Museum of Modern and Contemporary Art, and from April 2018 to November 2019, Arario Gallery Seoul Ryse Hotel, its second exhibition space in Seoul, opened near Hongik University. This effort aimed to inherit and develop the youthful and innovative spirit symbolized by the area. In 2022, Arario Gallery Seoul ended its Sogyeok-dong era and reopened with a new look in Wonseo-dong, Jongno-gu, in February 2023. The gallery aims to collaborate and support artists, striving for mutual growth through proactive exploration and consistent support. At the same time, it seeks to realize experimental and serious exhibition planning to continuously contribute to the advancement of the Korean art scene.', '-6162', 'Daily 11:00 - 18:00 (KST)', 'Closed Sundays & Mondays', '03058  85 Yulgok-ro, Jongno-gu, Seoul Arario Gallery', 'Subway Line 3  Anguk Station  Exit 3,  180m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17269&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17270&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17271&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.57783100, 126.98850080, 'ENP002388', NULL, NULL),
	(137, 'Artside Gallery', 'https://english.visitseoul.net/attractions/2024-artside/ENP72zzo1', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Opened in Insadong in 1999, Artside Gallery operates under the motto ??art is the constant centralization of the surroundings.??It aims to bridge artists and the art market by providing various creative directions to domestic and international artists. Based on its beliefs and perspectives, Artside Gallery has been at the forefront of introducing the diverse works and artistic worlds of talented artists from Korea, China, Asia, Europe, and beyond to the domestic and international art scene. Since relocating to Tongui-dong in 2010, the gallery has continued to curate exhibitions that reflect its distinct identity. Through its participation in various domestic and international art fairs, Artside Gallery has opened the door to the global art market and solidified its position as an internationally recognized gallery.', '-1665', 'Tues-Sat 10:00-18:00', 'Closed Sundays and Mondays  \nClosed for Chuseok holidays from September 16 to 18', '03044  15 Jahamun-ro 6-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  282m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67527&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67528&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67529&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67530&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74121&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57808370, 126.97288280, 'ENP72zzo1', NULL, NULL),
	(138, 'Seoul Children\'s Museum', 'https://english.visitseoul.net/attractions/Seoul-Childrens-Museum/ENP011669', 'The Seoul Children??s Museum is a multipurpose learning space filled with activities and experiences for children to enjoy. The museum\'s overall theme is "children designing happiness," and there are educational programs available for children according to both age and theme. The building spans three stories above-ground and an additional 3 stories underground. There is a performance hall, an experience hall, and educational facilities. Additional facilities include a cafe and a nursing room.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Seoul Children\'s Museum", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "14" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Strawberry L" }, "reviewBody": "We had a GREAT time here. Our child with ASD had a grand time and played well with kids from other countries. Incredibly welcoming and lots of useful things for mamas - nice changing rooms, water fountains, cafe with toddler friendly options. Definitely recommend when traveling with toddler/little kid in Seoul.", "datePublished": "2024-08-03" }] }', '-15870', 'Tuesday to Sunday: 10:00 - 18:00 (Last entry at 17:00)', 'Closed Mondays, New Year\'s Day & holidays', '04991,  216, Neungdong-ro, Gwangjin-gu, Seoul', 'Subway Line 7  Children\'s Grand Park Station  Exit 1,  326m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67002&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67003&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67004&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67005&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67006&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.54884980, 127.08176560, 'ENP011669', NULL, NULL),
	(139, 'Museum of Korea Straw and Plants Handicraft', 'https://english.visitseoul.net/attractions/Museum-of-Korea-Straw-and-Plants-Handicraft/ENP003332', 'The Museum of Korea Straw and Plants Handicraft is a private museum that was founded in 1992. The museum promotes cultural awareness of straw and its importance as a raw material in Korea. Straw was used in many different ways and is still used today in folk art. The museum\'s exhibitions display thousands of items made from straw including arts and crafts, tools, relics, and toys. The museum operates various educational programs for laypeople and professionals as well as workshops and crafting classes.', '-9450', '10:00 ??17:00 KST', 'Closed Sundays, Mondays, New Year\'s, Lunar New Year & Chuseok', '03075  45, Sungkyunkwan-ro 4-gil, Jongno-gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 4,  315m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16315&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16316&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16317&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16318&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75407&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58491880, 126.99984710, 'ENP003332', NULL, NULL),
	(140, 'Chojun Textile & Quilt Art Museum', 'https://english.visitseoul.net/attractions/Chojun-Textile-Art-Museum/ENP006463', 'The Chojun Textile & Quilt Art Museum was established in 1998 and specializes in textile and quiltworks. It is the only museum in Korea which is devoted entirely to textiles. Examples of traditional Korean embroidery are on display and museum-goers can also enjoy seeing royal clothing from the Joseon Dynasty. Learn about Eastern and Western textile history and methods at the Chojun Textile & Quilt Art Museum.', '-4747', 'Mon-Fri 10:00-17:00 (Last entry is 30 mins prior to closing)', 'Closed  Saturdays ~ Sundays & national holidays', '04630  66, Toegye-ro 18-gil, Jung-gu, Seoul', 'Subway Line 4  Myeongdong Station  Exit 3,  324m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3588&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3589&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3590&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75487&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75488&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55814440, 126.98425820, 'ENP006463', NULL, NULL),
	(141, 'Seoul Arts Center - Seoul Calligraphy Art Museum', 'https://english.visitseoul.net/attractions/SeoulCalligraphyMuseum/ENPx6grff', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Located within the Seoul Arts Center, the Seoul Calligraphy Art Museum opened in 1988 alongside the Music Hall as the first museum in Korea dedicated to calligraphy. The four-story building houses three exhibition halls across two floors and two storage rooms. Its collection includes historical Korean calligraphy literature such as Geun-yeok Seohwa-sa and more than 1,300 modern calligraphy works from Korea and East Asia. Through continuous exhibitions, the museum conveys the heritage and culture of South Korean calligraphy and painting to visitors.', '1688-1352', 'Tues-Sun 10:00-19:00', 'Monday', '06757  2406 Nambusunhwan-ro, Seocho-gu, Seoul', 'Subway Line 3, Nambu Bus Terminal Station (Seoul Arts Center) Exi 5, 1.4km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74797&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74798&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74799&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74800&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74801&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.47848160, 127.01258330, 'ENPx6grff', NULL, NULL),
	(142, 'Bank of Korea Money Museum', 'https://english.visitseoul.net/attractions/Bank-of-Korea-Money-Museum/ENP002730', 'The main building of the Bank of Korea provides extensive information on the manufacturing process of money and the development of the Korean economy. The collections is vast and there are over 20,000 pieces of Korean and foreign banknotes, coins and tokens on display. The museum consists of four exhibition halls and an information reference library. Admission to the Bank of Korea Money Museum is free.', '-5560', '10:00 - 17:00 (KST)', 'Mondays, Lunar New Year, Chuseok', '100-794  39 Namdaemun-ro, Jung-gu, Seoul  (Bank of Korea Building)', 'Subway Line 4  Hoehyeon Station  Exit 7,  310m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42359&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72850&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72851&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72852&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72853&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56215020, 126.97999190, 'ENP002730', NULL, NULL),
	(143, 'Gallery Hyundai', 'https://english.visitseoul.net/attractions/Gallery-Hyundai-EN/ENP001694', 'Gallery Hyundai is a famous gallery located on Sagandong Gallery Street. The street is known for its many galleries, hence the name, yet Gallery Hyundai stands out from the crowd. The gallery exhibits major contemporary Korean artists, such as Park Su-Geun and Lee Jung-Seob, as well as many major foreign artists. The gallery also has a superb restaurant with a great wine selection.', '-5707', 'Daily 10:00 - 18:00', 'Closed Mondays', '03062  14, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  595m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72841&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72842&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72843&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.57767550, 126.98114940, 'ENP001694', NULL, NULL),
	(144, 'National Museum Of Modern And Contemporary Art: Changdong Residency', 'https://english.visitseoul.net/attractions/National-Museum-Changdong-Residency/ENP002285', 'The Changdong Residency of the National Museum of Modern and Contemporary Art (MMCA) is an arts and cultural space that is designed to allow visitors to get more familiar with modern art. The museum offers various exhibitions, region-linked programs and educational programs. The residency space also provides art studios for Korean and international artists.', '-1910', 'Weekdays 09:00 - 18:00\n* Please refer to the website as hours may be subject to change.', '', '01469  257, Deongneung-ro, Dobong-gu, Seoul', 'Subway Line 4  Suyu Station  Exit 1,  Bus 1127 or 1138, get off at the Foreign Exchange Bank stop, 120 m\nSubway Lines 1/4  Changdong Station  Exit 2,   Bus 1157, get off at the Foreign Exchange Bank stop, 120 m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12488&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12489&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12490&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12491&fileTy=MEDIA&fileNo=3&thumbTy=L', 4, 37.64134140, 127.03823670, 'ENP002285', NULL, NULL),
	(145, 'Seoul Museum of Art (Seosomun Main Building)', 'https://english.visitseoul.net/attractions/Museum-of-Art-Seosomun/ENP001525', 'The Seoul Museum of Art (SeMA) opened in 1988 and has earned a reputation as one of Korea??s leading art venues with a series of world-famous exhibitions. Situated in the center of Seoul, its convenient location and outstanding collections attract large numbers of locals and tourists. The specially-designed building features large windows that fill the interior with natural light. This attracts not only tourists but also artists and even movie directors, some of whom have used the location for filming.      Since it was established in 1988, the main museum building has been relocated to Seosomun-dong in Seoul. The museum has a variety of annexes such as SeMA Gyeonghuigung, located on the historic site of Gyeonghuigung Palace, and the Nam Seoul Annex Building, which is situated in a building that was once the Belgian Embassy. The museum also runs the Naji Art Studio which offers workshops and financial support to new generations of Korean artists to nurture their creativity.      The beautiful Renaissance façade which forms the entrance to the museum was originally part of the Supreme Court, built in 1928. Today it is better known as the iconic image of the Seoul Museum of Art. In March 2006, the arch and the beautifully constructed museum building were designated as Cultural Property No. 237 in recognition of their great historical and architectural value.', '-10844', '(March - October) Tuesdays - Thursdays 10:00 - 20:00  / Friday 10:00-21:00 / Weekends 10:00 - 19:00\n(November - February) Tuesdays - Fridays 10:00 - 20:00 / Friday 10:00-21:00 / Weekends 10:00 - 18:00\n??Culture Day\n- Museum main building, Buk Seoul Museum: last Wednesday of the month 10:00 - 22:00 (KST)', 'New Years Day\nClosed on Mondays', '04515  61, Deoksugung-gil, Jung-gu, Seoul', 'Subway Lines 1/2  City Hall Station  Exit 10,  264m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31415&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31414&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31416&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31417&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31418&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56407180, 126.97454770, 'ENP001525', NULL, NULL),
	(146, 'Hakgojae Gallery', 'https://english.visitseoul.net/attractions/Hakgojae-Gallery/ENP001871', 'Hakgojae Gallery is a modern art gallery and its motto is ??creation of the new by understanding the old.??The architecture of the gallery reflects this motto. The main building of Gallery Hakgojae was designed to look like a hanok, (a traditional Korean house), while the new hall was designed in a modern, 21st-century style of architecture. Though the two architectural styles are different, they harmonize beautifully. Hakgojae Gallery also has a branch in the Shanghai art district of Moganshan Road. Admission to the gallery is free.', '-2164', 'Daily 10:00 ??18:00', 'Closed Mondays', '110-200  50, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3, Anguk Station, Exit 1, 751m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16657&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16658&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16659&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16660&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.58032830, 126.98029580, 'ENP001871', NULL, NULL),
	(147, 'Pace Gallery Seoul', 'https://english.visitseoul.net/attractions/pacegallery/ENPet80lf', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Pace Gallery is one of the world??s foremost contemporary art galleries, representing some of the most influential artists of our time. It has also maintained decades-long relationships with the estates of artists such as Alexander Calder, Jean Dubuffet, Agnes Martin, Louise Nevelson, and Mark Rothko. Since its early years, Pace has supported artists associated with Abstract Expressionism and those working with light and space, establishing itself as a uniquely distinguished gallery across the United States. Today, Pace operates exhibition spaces worldwide, including two galleries in Chelsea, New York, as well as in London, Geneva, Berlin, Hong Kong, Seoul, Los Angeles, and Tokyo.', '-10098', '10:00-18:00', 'Closed every Sunday and Monday', '04348  Pace Gallery, 267 Itaewon-ro, Yongsan-gu, Seoul', 'Subway Line 6, Hangangjin Station, Exit 1, 185m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75512&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75513&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75514&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75515&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75516&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53843360, 127.00136580, 'ENPet80lf', NULL, NULL),
	(148, 'Cheonggyecheon Museum', 'https://english.visitseoul.net/attractions/Cheonggyecheon-Museum/ENP004693', 'The Cheonggyecheon Museum documents the history of the Cheonggyecheon Stream area. The museum spans 6 floors, with several exhibition halls, education facilities, and an auditorium. The museum also offers educational classes for children on the history and ecology of the stream. The building itself is characterized by its long glass exterior, designed to symbolize the flowing waters of the Cheonggyecheon Stream. Admission to the Cheonggyecheon Museum is free.', '-5616', 'Daily 09:00 - 18:00 (KST)', 'Closed Mondays & January 1st\n??November - February: Closed Weekends & Holidays', '04704  530, Cheonggyecheon-ro, Seongdong-gu, Seoul', 'Subway Line 2  Yongdu Station  Exit 5,  497m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69808&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69809&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=69810&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75409&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75410&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57014770, 127.03541320, 'ENP004693', NULL, NULL),
	(149, 'Arario Museum in Space', 'https://english.visitseoul.net/attractions/Arario-Museum-in-Space/ENP020731', 'The Arario Museum in Space is a modern art museum that was established by the chairman of the Arario Corporation, Chang-il Kim. The building that houses the museum was designed by the famed Korean architect Kim Swoo-geun. Until he passed away in 1986, the building served as Kim\'s office and home. Today, the Arario Museum in Space calls the building home and the spaces are full of incredible modern art. This historic building is one of the most unique cultural spaces in Seoul.', '-6356', '10:00 - 19:00 \n(Last entry at 18:00)', 'Closed Mondays', '03058  83, Yulgok-ro (Wonseo-dong), Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 3,  181m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14446&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14447&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14448&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73969&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73970&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57773800, 126.98836150, 'ENP020731', NULL, NULL),
	(150, 'Kyung Hee University Natural History Museum', 'https://english.visitseoul.net/attractions/KyungheeUniversityHistoryMuseum/ENP006957', 'Upon opening its doors in 1978, the Kyunghee University Natural History Museum served as a little respite of nature in the city that boasted of a collection of nearly 90,000 specimen on display. The museum was initially founded upon the purpose of realizing the Kyungee University founding ideology of "Creating a world of culture" grounded in the results that had been obtained through several years of studying nature. The effort continues to approach the distancing relationship between nature and humankind amid rapid societal changes and urbanization with a "respite of nature in the city" that provides a sense of living in harmony with nature. All six floors of the museum display easy-to-understand exhibits capturing a comparison between the current state of evolution and the process of transformation up to the present-day with specimen of different plants and animals, as well as various rocks from sedimentary to igneous and metamorphic rocks that were used for research purposes by specialized teams of professors in various fields. There are courses and tour programs offered to help understand and practice nature preservation and the importance of life within the framework of these exhibited specimen. The Kyunghee University Natural History Museum has collected numerous specimen since the 1940s, while possessing a collection of more recent domestic specimen that have already become extinct or show signs of endangerment. The museum offers the opportunity for children and adults alike to more systematically learn about the classification and ecosystems of animals and plants and prioritizes itself with the fervor of exploring nature, as well as the awareness of nature protection.', '+82-2-961-0142~3', 'Daily 10:00 - 17:00', 'Closed weekends & holidays', '02447  26, Kyungheedae-ro, Dongdaemun-gu, Seoul', 'Subway Line 1, Foreign Language University Station Exit 1,  1.1km\nSubway Line 1, Hoegi Station Exit 1,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=37540&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=37541&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=37542&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=37543&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=37544&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.59671220, 127.05139480, 'ENP006957', NULL, NULL),
	(151, 'Total Museum of Contemporary Art', 'https://english.visitseoul.net/attractions/Total-Museum-of-Contemporary-Art/ENP003085', 'Located in a secluded residential area of Pyeongchang-dong overlooking Bukhansan Mountain, the Total Museum exhibits the best of contemporary Korean art. An outdoor performance stage and outdoor exhibition spaces at the museum offers scenic views as well as a wide variety of cultural events such as lectures and performances. The permanent collection includes sculptures, prints, paintings, videos, and illustrated books ranging from modern art to old masterpieces. The museum also holds special events, such as seminars, concerts and educational programs. Admission fees vary by event.', '-7336', 'Tue - Sun, 13:00 - 18:00 (last entry at 17:30)', 'Closed Mondays, holidays & days of exhibition installation', '03004  8, Pyeongchang 32-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  (Take bus nos. 1020 or 1711 ??Get off at Lotte-Samsung Apartments stop)\nSubway Line 4  Gireum Station  Exit 3,  (Take bus nos. 7211 or 110 ??Get off at Lotte-Samsung Apartments stop)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13435&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13436&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13437&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13438&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75489&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61209900, 126.97573370, 'ENP003085', NULL, NULL),
	(152, 'Gahoe Museum', 'https://english.visitseoul.net/attractions/Gahoe-Museum-EN/ENP018912', '??성??식 최신??코드  The Gahoe Museum is Korean folk art museum established by Yoon Yeolsu. The museum\'s exhibits Director Yoon\'s private collection of folk paintings and folk religious amulets. There are more than 2,000 folk paintings and craftworks on display and the museum aims to showcase and preserve Korean folk art. Visitors can also take folk painting lessons at the museum.', '-1127', '10:00 - 18:00 KST\n\n* Last entry is 40 min. before closing\n* For activities, last entry is 1 hr. before closing', 'Closed Mondays', '03056  52, Bukchon-ro, Jongno-gu, Seoul, Korea', 'Subway Line 3  Anguk Station  Exit 2,  496m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20453&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20454&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20455&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20456&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58140880, 126.98599670, 'ENP018912', NULL, NULL),
	(153, 'An Jung-geun Memorial Hall', 'https://english.visitseoul.net/attractions/An-Jung-geun-Memorial-Hall/ENP004281', 'The An Jung-geun Memorial Hall was established to memorialize the Korean patriot An Jung-geun. An fought for Korean independence from Japan and was ultimately executed by Japanese authorities for assassinating Ito Hirobumi in 1909. Ito was a major force behind the Japanese annexation of Korea. The memorial hall is composed of 12 exhibition halls and galleries, an auditorium, a reference library, and a rest area. In addition to exhibition information about An\'s life and some of his calligraphy, the memorial hall also hosts the An Jung-guen Academny and other events each year. Events include visits to historic sites abroad that were important to independence movements and calligraphy contests. Admission to the An Jung-geun Memorial Hall is free.       { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "An Jung-geun Memorial Hall", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.0", "ratingCount": "26" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "travelsafer" }, "reviewBody": "This is a very touching museum dedicated to the life of an important Korean martyr who opposed the Japanese rule on the peninsula and ended up killing the Japanese price ruling over Korea. It is a testimony of the struggle of the oppressed people and symbolizes the will of Korea to be free and be ready for anything to reach its independence. I confess that, before visiting this place, I did not know anything about Ahn Jung Geun, but when I got out of the museum I felt quite emotional. His life is narrated as a story of strong belief and resistance until martyrdom. Many parts and panels are in Korean only, but the friendly lady at the entrance and a man who we met on the second floor were very helpful. In particular he gave us a small book in English about his life and pictures. If you can, add this museum to your list of place to visit in Seoul.", "datePublished": "2016-11-18" } }] }', '-4725', 'March to October: 10:00 - 18:00\nNovember to February: 10:00 - 17:00 (KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', '04636  91, Sowol-ro, Jung-gu, Seoul', 'Subway Line 4  Hoehyeon Station  Exit 3,  689m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17277&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17278&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17279&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17280&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74159&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55426100, 126.98133930, 'ENP004281', NULL, NULL),
	(154, 'Korean National Police Heritage Museum', 'https://english.visitseoul.net/attractions/Korean-National-Police-Heritage-Museum/ENP020549', 'Established Oct. 14, 2005, the Korean National Police Heritage Museum is the best place in Seoul to go to learn about the history of the police force in Korea. Museum-goers can try hands-on experiences of what the police do and aims to expand citizens understanding of and encourage children\'s dreams of becoming police officers. The Police Museum, which moved to it\'s new location in 2021, aims to become a window of communication between the police and the public with trendy exhibitions and hands-on experience facilities.', '-6751', 'KST 09:30-17:30', 'Closed Mondays, New Year, Lunar New Year, and Chuseok holidays', '03166  162 Songwol-gil, Jongno-gu, Seoul', 'Subway Line 3, Dongnipmun Station, Exit 3,  363m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14412&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14413&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14414&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14415&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57228490, 126.96388620, 'ENP020549', NULL, NULL),
	(155, 'Museum of Medicine', 'https://english.visitseoul.net/attractions/Museum-of-Medicine/ENP000846', 'The Museum of Medicine is a medical museum located at Seoul National University\'s medical school. The museum building was once a hospital (Daehanuiwon Hospital) and it dates back to the early 20th century. The building features a neo-baroque clock tower. The museum also houses research facilities that are used by the Seoul National University Hospital.', '-4628', '* Weekdays 09:00 - 18:00 KST\n* Saturdays 10:00 - 15:00 KST\n* Group visits require advanced reservations via phone', 'Closed Sundays, national holidays, May 1 & October 15', '03080  101, Daehak-ro, Jongno-gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 3,  452m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17287&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17288&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17289&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75390&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58038460, 127.00052550, 'ENP000846', NULL, NULL),
	(156, 'Seoul Metropolitan Archives', 'https://english.visitseoul.net/attractions/Seoul-Metropolitan-Archives/ENP034857', 'As an public archive providing records services for the public, the Seoul Metropolitan Archives collects a number of records and memoirs tracing the history of the city government, as well as the residents of Seoul, and specializes in the preservation and management of such records. The SMA also plans and operates several public programs, including exhibitions, openings, and more.', '-5870', 'Daily 10:00 - 17:00 (KST)', 'Closed Mondays', '03371  7, Tongil-ro 62-gil, Eunpyeong-gu, Seoul', 'Subway Lines 3 / 6  Bulgwang Station  Exit 2,  370m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73871&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73872&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73873&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73874&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.60738320, 126.93471850, 'ENP034857', NULL, NULL),
	(157, 'National Gugak Museum', 'https://english.visitseoul.net/attractions/National-Gugak-Museum/ENP011893', 'The National Gugak Museum is Korea\'s first dedicated gugak (traditional Korean music) museum. The museum collection has approximately 6,000 items that relate to gugak. Visitors can see musical instruments, photos, documents, and much more at the museum. There are six exhibition halls that are organized by theme and the displays showcase everything from videos to instruments.', '-3630', 'Daily 10:00 - 18:00 (Last Entry at 17:30)', 'Closed Mondays & New Year\'s Day', '06757  2364, Nambusunhwan-ro, Seocho-gu, Seoul', 'Subway Line 3  Nambu Bus Terminal Station  Exit 5,  1.2km\nSubway Line 2  Bangbae Station, Exit 1,  1.5km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17039&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17040&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17041&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17042&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73572&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.47848160, 127.01258330, 'ENP011893', NULL, NULL),
	(158, 'National Folk Museum of Korea', 'https://english.visitseoul.net/attractions/National-Folk-Museum-of-Korea/ENP001644', 'The National Folk Museum of Korea displays the culture and folk history of the Korean people from prehistoric times to the end of the Joseon Dynasty. Since its establishment, the museum has dedicated itself to studying and researching the folk history of Korea, and collecting artifacts from different Korean regions in order to pass on an insight into the lifestyle and culture of Koreans. The museum achieves this by offering visitors various seminars, exhibitions, performance art, concerts and hands-on activities.      Located on the grounds of Gyeongbokgung Palace, the National Folk Museum of Korea is well known for its beautiful architecture. The building was constructed in the traditional Korean style comprising several stories with a pagoda on top. The three main exhibition halls at the museum cover different aspects of Korean life, as well as displaying various local costumes, musical instruments and festivals.    { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "National Folk Museum of Korea", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "996" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Kimberry" }, "reviewBody": "The National Folk Museum of Korea vividly depicts traditional Korean life through detailed exhibits and interactive displays. A great place to understand Korea??s roots.", "datePublished": "2024-08-21" }] }', '-6738', '09:00 - 18:00 from March to October \n09:00 - 17:00 from November to February \nExtended evening hours: 09:00 to 20:00 on Saturdays between March and October. \n(No extended evening hours from November to February)', '', '03045  37, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3 Anguk Station Exit 2, 780m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68376&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68377&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68378&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68379&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57805050, 126.97712400, 'ENP001644', NULL, NULL),
	(159, 'Gallery Art Zone at the National Museum of Modern and Contemporary Art', 'https://english.visitseoul.net/attractions/Gallery-Art-Zone/ENP016792', 'The Gallery Art Zone is located on the 1st floor of MMCA and is about 570??in size There are three zones and five gallery spaces. The Gallery Art Zone was borne out of a collaboration with the National Museum of Modern and Contemporary Art (MMCA) and Hyundai Motor Company. The Gallery Art Zone??s aim is to expand the breadth of audiences when it comes to art. Art shouldn??t just be for walls and showcases. The works on display in the Gallery Art Zone can be bought, and regular visitors can bring a piece of art or design home. The Gallery Art Zone shows different aspects of Korean contemporary art and design in each zone. The first zone (Gallery 1) exhibits Korean design and sells works by promising artists, particularly those from the craft sector. The second zone (Galleries 2 and 3) exhibits and sells cultural products that were developed for MMCA, or on display at MMCA. The third zone (Galleries 4 and 5) displays and sells textiles, fashion products, and art books. Additionally, in part as a result of Hyundai Motor Company??s sponsorship, many art related events and special events will be held at the Gallery Art Zone.', '-13491', '* Mondays, Tuesdays, Thursdays, Fridays & Sundays 10:00 - 18:00 \n* Wednesdays & Saturdays 10:00 - 21:00 (KST)', '', '03062  30, Samcheong-ro, (Sogyeok-dong) Jongno-gu, Seoul', 'Subway Line 3, Anguk Station, Exit 1,  764m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=9322&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=9323&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=9324&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.57962250, 126.98093430, 'ENP016792', NULL, NULL),
	(160, 'Modern History Memorial Hall', 'https://english.visitseoul.net/attractions/Modern-History-Memorial-Hall/ENP027105', 'Modern History Memorial Hall was built for the purpose of remembering and spreading awareness of Korean democracy and past independence movements. Spreading awareness of Korean forefathers who??ve valued and fought for ideals of freedom, equality, and democracy, the institution hopes to deliver a message that Korea is the land where forefathers dreamt of independence and achieved it.', '-8403', '09:00~18:00(Last entry at 16:30)', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok\n(* If Monday falls on a public holiday, Tuesday is closed as well.)', '01013  114, 4.19-ro, Gangbuk-gu, Seoul', 'Subway Line 4, Suyu Station Exit 4,  take (village) Gangbuk 01 ??Get off at Shinsung Villa stop', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20498&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20499&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20500&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20501&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.64106650, 127.00042130, 'ENP027105', NULL, NULL),
	(161, 'National Library of Korea', 'https://english.visitseoul.net/attractions/National-Library-of-Korea-EN/ENP011010', 'The National Library of Korea collects and stores Korea\'s literary and intellectual heritage. Located by Seocho Park, the library has a main building and an annex. The library houses millions of volumes and visitors can learn more about the library through the visitor tour program.', '-1010', 'Daily 09:00 - 18:00 (KST)\n* Night Hours 18:00 - 22:00 (KST)\n(Note: Hours may vary for different resource rooms)', 'Closed every 2nd/4th Monday & public holidays\n* Please refer to the website for more details.', '06579  201, Banpo-daero, Seocho-gu, Seoul', 'Subway Line 3/7/9 Express Bus Terminal Station Exit 5, 812m\nSubway Line 2 Seocho Station Exit 6, 771m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16498&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16499&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16500&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73567&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73568&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.49704030, 127.00201680, 'ENP011010', NULL, NULL),
	(162, 'Ground Seoul', 'https://english.visitseoul.net/attractions/2024-groundseoul1/ENP024613', 'Ground Seoul is a versatile cultural space spanning 4958 square meters. It features a distinctive underground layout that allows for beautiful natural lighting within the exhibition areas. This space is designed to seamlessly blend exhibitions, performances, events, and parties, making it a hub for artistic expression. Ground Seoul aims to establish itself as a landmark cultural venue in Insadong, where anyone can easily engage with and appreciate the arts.', '-7488', '11:00~18:00 (Vary per exhibition)', 'Vary per exhibition', '03145  26, Insadong 9-gil, Jongno-gu, Seoul', 'Subway Line 1, Jonggak Station, Exit 3-1, 301m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67376&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67377&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67378&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67379&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73573&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57346650, 126.98361630, 'ENP024613', NULL, NULL),
	(163, 'Kyung Hee University Central Museum', 'https://english.visitseoul.net/attractions/Central-Museum-of-Kyunghee-University/ENP006924', 'Opened in 1955, the Kyunghee University Central Museum is the first archaeology and history museum of Korea. The museum emphasizes the importance of teaching, preserving, and recording historical artifacts. The museum is home to the country\'s finest Siberian artifacts collection. Admission to the museum is free and there are also regular cultural programs throughout the year.', '-1022', 'Weekdays 10:00 - 17:00', 'Closed weekends, national holidays & May 18th (University founding day)', '02447  56-3 Kyungheedae-ro 1na-gil, Dongdaemun-gu, Seoul', 'Subway Line 1 Hoegi Station Exit 1,  1.1km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3787&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3788&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3789&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.59360280, 127.05035640, 'ENP006924', NULL, NULL),
	(164, 'Kyungin Museum of Fine Art', 'https://english.visitseoul.net/attractions/Kyung-In-Museum-of-Fine-Art/ENP002011', 'Founded in 1983 by Gyeongin Lee Geum-hong, Gyeongin Museum of Art is not only a cultural space for artists but also a widely known tourist attraction. The Gyeongin Museum of Art reflects the founder\'s desire to show that the museum is not the exclusive property of a particular group, but a place where people of all ages and backgrounds can feel at home. The interior consists of six exhibition halls, including an atelier, an outdoor garden, and a traditional tea garden, and concerts are held in the outdoor garden in spring and autumn.', '-5101', '10:00~18:00', 'Closed on New Year??s Day, Lunar New Year??s Day, and Chuseok', '03146  11-4 Insa-dong 10-gil, Jongno-gu, Seoul', 'Subway  Line 3  Anguk Station  Exit 5,  354m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60440&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60441&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60442&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60443&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60445&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57320700, 126.98657590, 'ENP002011', NULL, NULL),
	(165, 'Korean Catholic Martyrs??Museum', 'https://english.visitseoul.net/attractions/Korean-Catholic-Martyrs%E2%80%99-Museum/ENP029394', 'To publicize the persecution of Catholic martyrs who lost their lives during the Byeongin Persecution back in 1866, Jeoldusan Matyrs\' Memorial Hall changed its name into Korean Catholic Martyrs??Museum. Its facilities include a pilgrimage church, a sacred r ??oom containing the remains of a martyr, a museum showcasing Catholic records, documents, and relics, and an outdoor exhibition.', '-7496', 'Daily 09:30 - 17:00', 'Closed Mondays', '04085  6, Tojeong-ro, Mapo-gu, Seoul', 'Subway Line 2/6  Hapjeong Station  Exit 7,  500m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22247&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22248&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22249&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75403&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75404&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.54462320, 126.91081600, 'ENP029394', NULL, NULL),
	(166, 'Children\'s Museum of the National Museum of Korea', 'https://english.visitseoul.net/attractions/ChildrensMuseum/ENP020547', 'The Children\'s Museum of the National Museum of Korea showcases the cultural heritage of Korea. The Children\'s Museum is located within the National Museum of Korea.    Children can learn about the way of life and wisdom of people in ancient times through fun activities and exhibits. There is a reproduction of an ancient Korean house from the Goguryeo era and even a reproduction of a pottery workshop and kiln on display. Additionally, children can even try on historical clothing, accessories, and golden crowns.    The museum exhibits reproductions of artifacts that are on display in the National Museum of Korea. Children will be able to learn and gain a deeper understanding of Korean cultural heritage through fun, hands-on experiences.', '-10997', 'Daily 10:00 - 18:00 (KST)\n* Limited extended hours (Last Wednesday of every month)', 'Closed New Year\'s Day, Lunar New Year & Chuseok', '04383  137, Seobinggo-ro, Yongsan-gu, Seoul', 'Subway Line 4 / Gyeongui Central Line  Ichon Station  Exit 2,  309m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=51803&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=51805&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=51807&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.52686140, 126.98073150, 'ENP020547', NULL, NULL),
	(167, 'Tteok Museum', 'https://english.visitseoul.net/attractions/The-Tteok-Rice-Cake-Museum/ENP002037', 'The Tteok Museum is a museum and experience center where visitors can learn about traditional Korean food. Permanent Exhibition Hall No. 1 showcases the different tteok (rice cakes) that were prepared and eaten on Korean holidays. Also on display are the various tools that were needed to create the tteok. Permanent Exhibition Hall No. 2 has displays on the tteok that were eaten during the daily life of a Korean person. From birth, to death, and all the occasions in between, the tteok that were or are served are on display at the Tteok Museum. The museum also offers classes on how to make tteok and other traditional Korean food.', '-6108', 'Daily 10:00 - 18:00', 'Closed Sundays, Lunar New Year, Chuseok', '110-360  71, Donhwamun-ro, Jongno-gu, Seoul', 'Subway Lines 1/3/5  Jongno 3(sam)-ga Station  Exit 7,  286m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14336&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14337&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14338&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14339&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57489190, 126.99064090, 'ENP002037', NULL, NULL),
	(168, 'SJ. Kunsthalle', 'https://english.visitseoul.net/attractions/SJ-Kunsthalle-en/ENP024732', 'SJ. Kunsthalle was made as a cultural-artistic platform for meetings and discussions, providing everyday art linked programs, such as exhibitions, parties, performances, fashion shows, and workshops.', '-11664', '', '', '06054  5, Eonju-ro 148-gil, Gangnam-gu, Seoul', 'Subway Line 7/ Suin Bundang Line  Gangnam-gu Office Station  Exit 3,  1km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18489&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=18490&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72569&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72570&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72571&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52054980, 127.03489650, 'ENP024732', NULL, NULL),
	(169, 'Son Kee Chung Memorial Hall', 'https://english.visitseoul.net/attractions/Son-Kee-Chung-Memorial-Hall/ENP006995', 'The Son Kee Chung Memorial Hall honors the athlete and gold medalist, Son Kee Chung. The memorial hall opened on October 14th, 2012, marking the centennial anniversary of Son\'s birth. The memorial hall was once a school and was in fact Son\'s alma mater. Son Kee Chung was a gold medalist in the 1936 Berlin Olympics Marathon. Though Son Kee Chung was registered as a Japanese athlete, due to the Japanese occupation of the Korean peninsula, his victory was cherished and praised by Korean nationals. Visit the memorial hall to learn more about Son\'s life and how he won his gold medal. Admission is free and there are sometimes special exhibitions.', '-2220', '10:00 - 18:00 (KST)\n* Last entry is 1 hr. before closing time.', 'Closed Mondays & national holidays', '04501  101, Songijeong-ro, Jung-gu, Seoul', 'Subway Line 2/5  Chungjeongno Station  Exit 5,  753m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3819&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3820&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3821&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73944&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73945&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55557810, 126.96474170, 'ENP006995', NULL, NULL),
	(170, 'The National Museum of Korea', 'https://english.visitseoul.net/attractions/NationalMuseumofKorea/ENP000433', 'p { text-align: justify; word-spacing: 2px; }  As a living vestige of Korea\'s history and culture, The National Museum of Korea is home to today\'s best collection of history and culture deeply rooted within the Korean people. Regular exhibitions and education programming speak of the numerous anecdotes of the nearly 420,000 collected historical artifacts with thousands of years of history, while also offering realistic digital animations and VR technology to provide a more impactful experience. The museum includes everything from a simple hand axe of the Paleolithic Period and a magnificient golden crown of the Three Kingdoms Period to Goryeo Period celadons, or pottery, and paintings dating back to the Joseon Period, as well as pictures of modern-era Korea and a variety of other zones dedicated to different cultures throughout the globe. Bring your family, friends, or even that special someone over to the museum for a day of fascination amid a compilation of detailed and colorful history.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "The National Museum of Korea", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "2420" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Angela" }, "reviewBody": "The National Museum of Korea is a treasure trove of Korean history and culture, featuring artifacts from ancient to modern times. A must-visit for history enthusiasts.", "datePublished": "2024-08-21" }] }', '-10997', '- Mon, Tues, Thur, Fri, Sunday 10:00 - 18:00 KST\n- Wed, Saturday 10:00 - 21:00 KST\n*  Outside exhibitions may be viewed from 07:00 KST', '* Closed on Mondays, January 1st, Lunar New Year\'s Day, Chuseok (Sept. 17)\n* Permanent exhibitions close every first Monday in April and October\n(2024 closure days: April 1 (Mon), Nov. 4 (Mon))\n??The special exhibition hall, children\'s museum, and outside', '04383  137, Seobinggo-ro, Yongsan-gu, Seoul', 'Subway Line 4/Gyeongui Central Line  Ichon Station  Exit 2,  309m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68365&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68366&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68367&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68368&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68369&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52686140, 126.98073150, 'ENP000433', NULL, NULL),
	(171, 'Gana Art Center', 'https://english.visitseoul.net/attractions/Gana-Art-Center/ENP002082', 'The Gana Art Center is a multipurpose art space that holds exhibitions, performances, classes, and auctions. The sprawling center was designed by the world-renowned architect Jean Michel Wilmotte. The Gana Art Center operates a convenient shuttle bus for visitors. The shuttle bus runs every day except Mondays and national holidays.', '-1660', 'Tue-Sun 10:00 - 19:00 KST', 'Mondays', '03004  28, Pyeongchang 30-gil, Jongno-gu, Seoul', 'Subway Line 5 Gwanghwamun Station Exit 2 / Subway Line 3 Gyeongbokgung Station Exit 3, take bus 1020 or 1711 and get off at Lotte Apartment, 150m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72857&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72858&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72859&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72860&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.61221180, 126.97517740, 'ENP002082', NULL, NULL),
	(172, 'Museum Kimchikan', 'https://english.visitseoul.net/attractions/Museum-Kimchikan/ENP019924', 'Museum Kimchikan is the place to go to learn about the many varieties of kimchi in the world. See real examples of different kimchi varieties and take part in fun activities! Museum Kimchikan is located in Insa-dong, but at one time, the center was located in Samseon-dong and named the Kimchi Museum. Following the move to Insa-dong, the museum underwent a redesign in addition to the name change.   At Museum Kimchikan, visitors can learn about kimchi in all its different forms as well as use microscopes to view the lactic acid bacteria that helps make kimchi so healthy. Visitors can learn and even taste samples of different varieties of kimchi during their time at the museum. The museum also holds kimchi-making activities and classes and visitors should join in to learn how to make delicious kimchi themselves!    Frequently Asked Questions about Museum Kimchikan        What are the opening hours of the Museum Kimchikan?         Museum Kimchigan is open from 10:00 to 18:00 from Tuesday to Sunday. Admission is until 17:30. (As of 2024)          How much is the Museum Kimchikan entrance fee?         The admission fee for the Museum Kimchikan is as follows. (As of 2024)     ??19 years old or older : 5,000 KRW   ??Ages 8 to 18 : 3,000 KRW   ??36 months to 7 years old : 2,000 KRW            Do I need to make a reservation to visit the Museum Kimchikan?         Solo visits are possible without reservation, but viewing may be restricted depending on group visits.     { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "What are the opening hours of the Museum Kimchikan?", "acceptedAnswer": { "@type": "Answer", "text": "<div> Museum Kimchikan is open from 10:00 to 18:00 from Tuesday to Sunday. Admission is until 17:30. (As of 2024) </div>" } }, { "@type": "Question", "name": "How much is the Museum Kimchikan entrance fee?", "acceptedAnswer": { "@type": "Answer", "text": "<div> The admission fee for the Museum Kimchikan is as follows. (As of 2024)<br><br> <ul> <li>19 years old or older : 5,000 KRW</li> <li>Ages 8 to 18 : 3,000 KRW</li> <li>36 months to 7 years old : 2,000 KRW</li>  </ul> </div>" } }, { "@type": "Question", "name": "Do I need to make a reservation to visit the Museum Kimchikan?", "acceptedAnswer": { "@type": "Answer", "text": "<div> Solo visits are possible without reservation, but viewing may be restricted depending on group visits. </div>" } }, { "@type": "LocalBusiness", "name": "Museum Kimchikan", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "3.5", "ratingCount": "70" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Tibor" }, "reviewBody": "Very nice place to explain history of traditional Korean cuisine I would never believe before how many kimchi kind of combination existing in Korea. If you like it try to find time and visit it", "datePublished": "2019-12-31" } }] }', '-12378', 'Daily 10:00-18:00 (KST)', 'Closed Mondays, Lunar New Year, Chuseok & Christmas', '03149  Insadong-gil 35-4 (Gwanhun-dong), Jongno-gu, Seoul', 'Subway Line 3, Anguk Station, Exit 6, 394m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16375&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16376&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16377&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16378&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.57298720, 126.98445040, 'ENP019924', NULL, NULL),
	(173, 'Seoul Art Space - Sindang Creative Arcade', 'https://english.visitseoul.net/attractions/Sindang-Creative-Arcade/ENP005060', 'The Sindang Creative Arcade is a creative space for artists and an art market. The arcade was re-born into a space for the arts following renovation of empty storefronts at the Sindang Underground Shopping Center in the Jungang Market. The Jungang Market was established in 1917 and the renovation that created the Sindang Creative Arcade has revitalized the area. The creative arcade houses workshops and an art market. Dozens of artists create artworks and crafts in nearly every art medium there is. At the art market, shoppers can purchase unique artwork and items.', '-10985', 'Artist Workshop 09:00 - 20:00 \nCommon Workshop & Photography Room 09:00 - 22:00', 'Art Market closed weekends', '04571  87, Majang-ro, Jung-gu, Seoul', 'Subway Lines 2/6  Sindang Station  Exits 2,  336m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23374&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23375&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23376&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23377&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56896080, 127.01809990, 'ENP005060', NULL, NULL),
	(174, 'National Museum of Korean Contemporary History', 'https://english.visitseoul.net/attractions/Museum-of-Contemporary-History/ENP006667', 'The National Museum of Korean Contemporary History houses exhibitions that span modern Korean history, from the first opening of Korea to outsiders in the late 19th century to today. The museum is the country\'s first national museum of contemporary history. The eight-story museum has many facilities: there are four permanent exhibition halls and two special exhibition halls, seminar rooms, lecture halls, a rooftop garden, a museum shop (that sells souvenirs), a cafe, and storage lockers. The four permanent exhibitions cover different periods of Korean history and there are over 1,500 artifacts and items here. Some of the displays are patriot Ahn Jung-Geun\'s last writings, the March 1st Declaration of Independence, belongings of fallen soldiers from the Korean War, and materials relating to democratic activism. The museum\'s first floor contains two special exhibition halls. Here, you will find a variety of limited-time exhibitions relating to Korean history, politics, society, and culture. Additionally, visitors can listen to, watch, and experience the modernization of Korea through state-of-the-art technology. There is also the Children\'s Museum, where children can learn and experience history for themselves with the museum??s ??Our History??s Treasure Chest??area.', '-12823', '10:00 - 18:00 (Wednesdays and Saturdays: 10:00 - 21:00) \n*Last entry 30 minutes before closing', 'Closed on New Year\'s Day & Chuseok', '03141  198, Sejong-daero, Jongno-gu, Seoul', 'Subway Line 5  Gwanghwamun Station  Exit 2,  217m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41550&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41549&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=41548&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72592&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72593&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57400290, 126.97794900, 'ENP006667', NULL, NULL),
	(175, 'Nature Poem', 'https://english.visitseoul.net/attractions/Nature-Poem-EN/ENP001439', 'Nature Poem is a six-story commercial gallery located in the heart of Gangnam\'s posh Cheongdam-dong neighborhood. Cheongdam-dong is famous for its abundance of premium designer stores. Nature Poem is located near many art galleries and high-end luxury stores, making a visit to Nature Poem a convenient starting point for a tour of Gangnam. Gallery GO, the Nam June Paik Museum and Gallery Jang are all nearby.', '', 'Daily 10:00 - 18:00', 'Closed Sundays', '06011  461, Apgujeong-ro, Gangnam-gu, Seoul', '* Bundang Line, Apgujeong Rodeo Station, Exit 2 (10 mins on foot)* Subway Line 7, Cheongdam Station, Exit 9 (20 mins on foot)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16665&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16666&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16667&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16668&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.52657580, 127.04827200, 'ENP001439', NULL, NULL),
	(176, 'National Meteorological Museum of Korea', 'https://english.visitseoul.net/attractions/National-Meteorological-Museum-of-Korea-EN/ENP040770', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}It is the first meteorological science and history museum that researches and preserves the meteorological culture of Korea from the Joseon Dynasty to modern times. The museum owns the world\'s last surviving rain gauge instrument, known as the Rain Gauge of the Chungcheonggamyeong Provincial Office, Gongju, invented 200 years earlier than the West.The Seoul Meteorological Observatory (52 Songwol-gil, Jongno-gu, Seoul), where the National Meteorological Museum was established, is the center of Korea\'s modern and contemporary meteorological history. The modern meteorological observation started in Wonnam-dong, Gyeongseong, in 1907 and moved to Songwol-dong via Nakwon-dong. The building at the time of its establishment in 1932 and extension in 1939 have been maintained and served as the Korea Meteorological Administration until the administration moved to Dongjak-gu, Seoul, in 1998. For this continuity, it was selected as a ??00-year observatory??by the World Meteorological Organization in 2017. In 2016, when the museum was being built, the Seoul Meteorological Observatory was restored to its original form based on the architectural drawings of the 20th-century meteorological station kept at the National Archives. Please enjoy the change of weather and history at the National Meteorological Museum, the heart of Korea\'s meteorology.', '-2994', '10:00  - 18:00', 'Mondays, January 1, Lunar New Year??s Day and Chuseok', '03178  52, Songwol-gil, Jongno-gu, Seoul', 'Subway Line 5  Seodaemun Station  Exit 4,  860m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50900&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50902&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50904&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50908&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57074800, 126.96722240, 'ENP040770', NULL, NULL),
	(177, 'Jong Ie Nara Paper Art Museum', 'https://english.visitseoul.net/attractions/Jong-Ie-Nara-Paper-Art-Museum/ENP005796', 'The Jongienara Museum opened in 1999 as a Paper Art Museum and was established to revive and recreate Korea\'s world-class paper, K origami, and paper culture. Reopened as the Jongienara Museum in 2008, it goes beyond researching and introducing Korea\'s outstanding origami and paper culture. It pays attention to the excellent role of paper as a craft and art object, presenting the development of a new cultural art genre and modern paper culture and art. The excellence and creativity of Korean origami and paper culture are known to the public through the discovery, exhibitions, and education of current cultural paper artworks.', '-10100', 'Daily 09:30 - 18:00 \n(Last entry 30 mins prior to close)', 'Closed Sundays & Holidays', '100-391  166, Jangchungdan-ro, Jung-gu, Seoul', 'Subway Line 3, Dongguk Univ. Station, Exit 3,  55m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=57693&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=57692&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=57691&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.55967920, 127.00620290, 'ENP005796', NULL, NULL),
	(178, 'Sungshin Women\'s University Costume Museum and Natural History Museum', 'https://english.visitseoul.net/attractions/Sungshin-Womens-University-Costume-Museum-and-Natural-History-Museum/ENP033828', 'p{text-align:justify;word-spacing:2px;}Opened on November 23, 2011, the Park Kwang Hoon Costume Museum is a special museum, displaying over 600 garments, which are currently designated as Seoul\'s Intangible Cultural Property No. 11, donated by the Master Artisan of Needlework, Park Kwang Hoon, as well as more than 2,000 pieces of fabrics and accessories. A variety of Korean attires and accessories are on display, from swaddling clothes and ordinary clothes as well as wedding clothes and royal ritual clothes to shrouds for the deceased.Located in the basement (B1) of the same building, the Natural History Museum exhibits as many as 135,000 samples collected for over 40 years since the 1970s under four themes of rocks, embryogenesis, plants and insects to help visitors learn and feel the nature around them.??Park Kwang Hoon Costume Museum offers various arts and culture programs, including the traditional pattern gilt stamping class, traditional pattern drawing class, and jokduri making class, in addition to its main exhibitions. ??Extra charges apply for experience programs.', 'CostumeMuseum:+82-2-920-2657NaturalHistoryMuseum:+', 'Mon - Sat 10:00 - 17:00 (Closed Sundays and Legal Holidays)', '', '01133  55, Dobong-ro 76ga-gil, Gangbuk-gu, Seoul  (Woonjung Green Campus, B1)', 'Subway Line 4  Mia Station  Exit 1,  500m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28635&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28636&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28637&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28638&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28639&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28640&fileTy=MEDIA&fileNo=2&thumbTy=L', 6, 37.63194980, 127.02726800, 'ENP033828', NULL, NULL),
	(179, 'Culture Station Seoul 284', 'https://english.visitseoul.net/attractions/Culture-Station-Seoul-284/ENP000450', 'Culture Station Seoul 284 is a multipurpose arts and cultural complex. It was once known simply as Seoul Station and it was the city\'s biggest rail station. The station was built during the Japanese colonial era. The first floor is used as a space for performances and exhibitions. The second floor is used for exhibitions, seminars, and meetings. Though admission to Culture Station Seoul 284 is free, performances and exhibitions may charge admission.', '-6827', '', '', '04509  1, Tongil-ro, Jung-gu, Seoul', 'Subway Line 1/4/Airport Railroad/Gyeongui-Jungang Line/GTX-A  Seoul Station Exit 1,  76m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68381&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68382&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68383&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72582&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72583&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55752150, 126.97044010, 'ENP000450', NULL, NULL),
	(180, 'Arko Art Center', 'https://english.visitseoul.net/attractions/Arko-Art-Center/ENP018992', 'Arko Art Center is a public art gallery and art center in the Daehak-ro area. By curating temporary exhibitions, and creating a platform for emerging experimental artists, the gallery has successfully become a staple of the Korean contemporary art scene. The Arko Art Center is also home to INSA Art Space, an alternative space aimed at promoting upcoming artists, as well as maintaining archives and providing seminar rooms and project space. There is no admission fee for the center, but exhibitions may charge entry fees.', '+82-2-760-4850ext.3', 'Daily 11:00 KST - 19:00 KST (Last entry at 18:30 KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year, Chuseok & Christmas', '03087  3, Dongsung-gil, Jongno-Gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 2,  138m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=11947&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73971&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73972&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=11948&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=11949&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57882840, 127.00364260, 'ENP018992', NULL, NULL),
	(181, 'The Hangsangsoo Embroidery', 'https://english.visitseoul.net/attractions/Hansangoo-Embroidery-Museum/ENP003357', 'This unique space preserves all the traces of traditional Korean embroidery techniques that have been restored by collecting and analyzing artifacts from the 1960s to revive Korean embroidery, which was lost through the Korean Empire and Japanese occupation. The Korean Handicraft Institute, which opened in 1963, is the origin of the Hansangsu Embroidery Museum. It has been established as a complex cultural space to preserve and present Korean embroidery to the public. The eldest daughter of Han Sang-soo, a National Intangible Cultural Property embroiderer, has been running the museum as the second director and is preparing for the third succession.', '-3334', 'Tuesday-Sunday 10:00~18:00\nBreak Time 12:00~13:00', 'Monday', '02836  4-10 Seongbuk-ro, Seongbuk-gu, Seoul', 'Subway  Line 4  Hansung University Station  Exit 5,  719m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60044&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60043&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60042&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60041&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60040&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.59552560, 127.00056740, 'ENP003357', NULL, NULL),
	(182, 'Leeum Museum of Art', 'https://english.visitseoul.net/attractions/Leeum-Samsung-Museum-of-Art/ENP001232', 'The Leeum Museum of Art is the perfect place to enjoy traditional and contemporary art created by Korean and international artists. Most of the exhibits on display at the museum are based on the large collection of the founder, the late Lee Byeong-cheol, once president of the Samsung Group. Three world-renowned architects, Maria Botta, Jean Nouvel, and Rem Koolhaas, were commissioned to design the outstanding museum complex. The name Leeum is the acronym of the family name of its founder, ??Lee??and an abbreviated word for museum, ??um?? The museum is composed of three individual buildings linked together as a composite complex. Museum 1 showcases traditional Korean arts and crafts such as calligraphy, ceramic arts and metal craft work, while Museum 2 displays dynamic modern and contemporary art by domestic and international artists, this section includes the Samsung Child Education & Cultural Center which offers cultural education for children.  In the museum basement, a sunken garden and Gabion wall, which is a cylindrical metal container filled with stones, can be found. Art, architecture and nature exist together in perfect harmony.           Frequently Asked Questions about Leeum Museum of Art         Do I need to make a reservation to visit the Leeum Museum of Art?         Leeum Museum of Art operates under a reservation system. Reservations can be made 14 days before the visit. The maximum number of people per reservation is four. On-site ticketing is possible and limited to remaining tickets per reservation time (As of 2025)          Is the Leeum Museum of Art digital guide available for free?         Digital guides that automatically provide explanations when one approaches the exhibits can be borrowed free of charge. The devices are available to elementary school students and anyone older. You must present an identification card such as a passport or resident registration card. The digital guide is available in Korean, English, Chinese, and Japanese. (As of 2025)          Can I visit the Leeum Museum of Art permanent exhibitions for free?         Yes. Permanent exhibitions are free. They are also operated under a reservation system, so please make a reservation before visiting. (As of 2025)     { "@context": "https://schema.org", "@graph": [{ "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "Do I need to make a reservation to visit the Leeum Museum of Art?", "acceptedAnswer": { "@type": "Answer", "text": "<div>            Leeum Museum of Art operates under a reservation system. Reservations can be made 14 days before the visit. The maximum number of people per reservation is four. On-site ticketing is possible and limited to remaining tickets per reservation time (As of 2024)          </div>" } }, { "@type": "Question", "name": "Is the Leeum Museum of Art digital guide available for free?", "acceptedAnswer": { "@type": "Answer", "text": "<div>            Digital guides that automatically provide explanations when one approaches the exhibits can be borrowed free of charge. The devices are available to elementary school students and anyone older. You must present an identification card such as a passport or resident registration card. The digital guide is available in Korean, English, Chinese, and Japanese. (As of 2024)            </div>" } }, { "@type": "Question", "name": "Can I visit the Leeum Museum of Art permanent exhibitions for free?", "acceptedAnswer": { "@type": "Answer", "text": "<div>            Yes. Permanent exhibitions are free. They are also operated under a reservation system, so please make a reservation before visiting. (As of 2024)          </div>" } }] }, { "@type": "LocalBusiness", "name": "Leeum Museum of Art", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "762" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "re1na" }, "reviewBody": "Bit of a walk from nearest subway station but still worthwhile to check out the collection of old artefacts and new contemporary modern art. Good rainy day activity": "2023-09-30" } }] }', '-8835', 'Tue-Sun 10:00 - 18:00', 'Closed Mondays, New Year\'s weekend, New Year\'s Day & Chuseok', '04348  60-16, Itaewon-ro 55-gil, Yongsan-gu, Seoul', 'Subway Line 6  Hangangjin Station  Exit 1,  399m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13560&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13561&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13562&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=13563&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.53763400, 126.99817480, 'ENP001232', NULL, NULL),
	(183, 'Electricity Museum', 'https://english.visitseoul.net/attractions/Electricity-Museum/ENP001958', 'The Electricity Museum is an educational museum located within the KEPCO Art Center. Visitors can learn about the history of electricity here through fun activities, photos, models, and illustrations.', '-10215', 'Daily 10:00 - 18:00', 'Closed Mondays, Lunar New Year & Chuseok', '06732  60, Hyoryeong-ro 72-gil, Seocho-gu, Seoul', 'Subway Line 3 & Shinbundang Line, Yangjae Station, Exit 1 (20 mins on foot)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12429&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12430&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12431&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.48569880, 127.02799810, 'ENP001958', NULL, NULL),
	(184, 'Appenzeller Noble Memorial Museum', 'https://english.visitseoul.net/attractions/Appenzeller-Noble-Memorial-Museum/ENP006430', 'Learn about the history of education in Korea at the Appenzeller Noble Memorial Museum. The museum is housed in what was once the Pai Chai Hakdang, which was Korea\'s first Western-style school. Currently, the school\'s classrooms have been repurposed and are used as a permanent exhibition hall, a special exhibition hall, an experience zone, and a seminar room. In the permanent exhibition hall, visitors can see what the Pai Chai Hakdang looked like in the 1930s at the hall\'s recreated historical classroom. Admission to the museum is free.', '-5817', 'Daily 10:00 - 17:00', 'Closed Mondays, Sundays & Public Holidays', '04516  19, Seosomun-ro 11-gil, Jung-gu, Seoul', 'Subway Line 1 / 2  City Hall Station  Exit 10,  240m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31412&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31413&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31411&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=31410&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.56370520, 126.97228640, 'ENP006430', NULL, NULL),
	(185, 'National Museum of Modern and Contemporary Art, Seoul', 'https://english.visitseoul.net/attractions/National-Museum-of-Modern-and-Contemporary-Art-Seoul/ENP011658', 'The National Museum of Modern and Contemporary Art (MMCA), Seoul is the newest of the four branches. The Seoul branch focuses on introducing global contemporary art. Equipped with multiple facilities, including a library, theater, and a multipurpose hall, MMCA, Seoul strives to accommodate every mode of new artistic endeavors and communication with the public.', '-13121', 'Mondays, Tuesdays, Thursdays, Fridays, and Sundays 10:00 - 18:00 (KST)\nWednesdays & Saturdays 10:00 - 21:00 (KST)\n* Special Night Exhibition 18:00 - 21:00 (KST)\n* Last Entry: 1 Hour Before Closing Time', 'New Year\'s Day, Lunar New Year\'s Day & Chuseok', '30, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  764m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12792&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12793&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12794&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12795&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74386&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57951170, 126.98058620, 'ENP011658', NULL, NULL),
	(186, 'National Aviation Museum of Korea', 'https://english.visitseoul.net/attractions/National-Aviation-Museum-of-Korea/ENP038021', 'The National Aviation Museum of Korea, located at Gimpo Airport, is the first national museum in the aviation field established by the Ministry of Land, Infrastructure and Transport to organize Korea\'s aviation history and promote collective understanding of the aviation industry. The National Aviation Museum of Korea consists of the Aviation History Hall, where visitors can learn about the history of Korean aviation, the Aviation Industry Hall, where visitors can get a glimpse of the current state of the aviation industry, and the Aviation Future Hall, where visitors can see various aviation technologies, airplanes and models for the future. Additionally, there is a unique experience space for those who have always dreamed of flying. Here, visitors can experience aviation through five different spaces including the Black Eagle boarding experience, an in-flight training experience, a pilot control experience, the air sports experience, and the children\'s airport experience.    { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "National Aviation Museum of Korea", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "5.0", "ratingCount": "1" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "traveller_12_14" }, "reviewBody": "From the very early days of mankind dreaming of flying, via Korea??s specific footprint in aviation up to the latest technological developments, the museum has compiled a really amazing and well guided exhibition.", "datePublished": "2023-05-02" }] }', '-10058', 'Daily 10:00 - 18:00', 'Closed Mondays\nJanuary 1, Lunar New Year??s Day\n*If Monday is a public holiday, the museum will be open on that Monday and closed on Tuesday.*', '07505  177 Haneul-gil, Gangseo-gu, Seoul  (Gonghang-dong, National Aviation Museum of Korea)', 'Subway Line 5/9/Airport Railroad/Seohae Line/Gimpo Gold Line  Gimpo Airport Station Exit 4,  988m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42438&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42439&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42440&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42441&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42442&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55675570, 126.80847340, 'ENP038021', NULL, NULL),
	(187, 'Hangaram Art Museum', 'https://english.visitseoul.net/attractions/Hangaram-Art-Museum/ENP004325', 'Hangaram Art Museum is situated on the left side of the main front area of the Seoul Arts Center. It is integrated with various programs offered by the Seoul Arts Center. The museum includes exhibition halls, storage rooms, and an art shop, providing an optimal exhibition environment. It often hosts special exhibitions by world-renowned artists such as Edvard Munch, Bernard Buffet, and Pablo Picasso. Most exhibitions prohibit photography, and observing proper viewing etiquette is important. The outdoor stair plaza serves as an open space for art markets, outdoor festivals, and an outdoor café during the summer season. It also accommodates various public programs, offering a unique cultural experience.', '1668-1352', '10:00 - 19:00 (KST)', 'Closed Mondays', '06757  2406, Nambusunhwan-ro, Seocho-gu, Seoul', 'Subway Line 3  Nambu Bus Terminal Station (Seoul Arts Center)  Exit 5,  695m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16910&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16911&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16912&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16913&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74167&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.47848160, 127.01258330, 'ENP004325', NULL, NULL),
	(188, 'Seoul Book Bogo', 'https://english.visitseoul.net/attractions/Seoul-Book-Bogo/ENP030789', 'p{text-align:justify;word-spacing:2px;}Seoul Book Bogo is a new cultural space created by Seoul Metropolitan Government to house old, secondhand books they gathered from old bookstores around the city. Featuring an old secondhand bookstore, library, and cultural programs, Seoul Book Bogo is separated into 4 spaces for value, sharing, enjoyment, and experience. Visitors can feel the value of old books in the space for value, read books donated by famous intellectuals in the space for sharing, experience unique indie books in the space for enjoyment, and participate in various cultural book programs in the space for experience.', '-11850', 'Weekdays 11:00 AM - 9:00 PM\nSaturdays 10:00 AM - 9:00 PM\nSundays 10:00 AM - 6:00 PM', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok', '05507  1, Ogeum-ro, Songpa-gu, Seoul', 'Subway Line 2, Jamsillaru Station, Exit 1,  160m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23411&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23413&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23414&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23412&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.52126660, 127.10801850, 'ENP030789', NULL, NULL),
	(189, 'Samseyoung', 'https://english.visitseoul.net/attractions/2024-samsy/ENPzcpf02', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Samseyoung aims to be a cultural and artistic space that embraces the past, present, and future. Opened in December 2021, Samseyoung reflects on the past through the collection of antique art that the founder has gathered over 20 years. It is also a space where contemporary cultural and artistic figures come together to engage with the present while looking forward to the future.', '-644', '11:00-18:00', 'Sun-Mon', '03003  2 Pyeongchang 44-gil, Jongno-gu, Seoul  Samseyoung', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  Take Bus 1711 and get off at Pyeongchang-dong Samsung Apartments. 301 m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68330&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68331&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68332&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68333&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68334&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61367890, 126.97832610, 'ENPzcpf02', NULL, NULL),
	(190, 'Space C', 'https://english.visitseoul.net/attractions/Space-C/ENP001441', 'Space C is a venue created and run by Coreana, a Korean cosmetics company. It spans 10 levels comprising a museum, gallery, beauty shop, café, and rooftop garden. On the 5th and 6th floors, visitors will find Korea??s largest cosmetics museum where visitors can learn about the history and development of Korean cosmetics. Space C also houses a large number of cosmetics-related artworks and other artifacts.      The Cosmetics Museum is Space C??s main exhibition hall, presenting the history of Korean cosmetics through a collection of more than 5,300 beauty-related items used by women in the Joseon Dynasty (1392-1910). The C Gallery on the first basement level is a traditional exhibition hall that displays fine art while C Cube on the second basement level plays host to more experimental work. The museum café on the 1st floor reflects the nature of its setting with art exhibits created from everyday objects, giving visitors the chance to continue their cultural odyssey even as they relax. The Beauty Space on the 2nd to 4th floors is a peaceful haven where women can consult a beauty therapist in the skin clinic and indulge in a range of body treatments. The Outdoor Cosmetics Museum on the rooftop of Space C is a garden featuring a collection of important plants which provide key ingredients for the cosmetics industry. From here, visitors can also enjoy spectacular views of the Seoul skyline.', '-9644', 'Tuesday - Friday - 11:00 AM - 6:00 PM', 'Saturday,Sunday, Monday, January 1, Lunar New Year & Chuseok holidays\n* Please refer to the website as opening hours may vary.', '06024  827, Eonju-ro, Gangnam-gu, Seoul', 'Subway Line 3, Apgujeong Station, Exit 3,  567m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=804&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=805&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=806&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72449&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72450&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52319880, 127.03156320, 'ENP001441', NULL, NULL),
	(191, 'Art Sonje Center', 'https://english.visitseoul.net/attractions/Art-Sonje-Center/ENP002405', 'Whereas the Sonje Museum of Art typically focuses exclusively on contemporary artwork, the Art Sonje Center has a multi-pronged focus on art. The museum exhibits art from various genres and the museum also hosts cultural events such as concerts, short film screenings, and performance arts shows by Korean and foreign artists. Major pieces in the museum\'s collection are  Wings of Jupiter by Kwak Hoon and Curtains by Hwang Kyu-Baik.', '-9602', 'Daily 12:00 - 19:00 (KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', '03062  87, Yulgok-ro 3-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  709m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=38265&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74121&fileTy=MEDIA&fileNo=1&thumbTy=L', 2, 37.57942230, 126.98184110, 'ENP002405', NULL, NULL),
	(192, 'Seoul Science Museum', 'https://english.visitseoul.net/attractions/SeoulScienceMuseum/ENPn1ua1r', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The Seoul Science Museum, located in Hageo-dong, Nowon-gu, opened its doors for the first time in Seoul in 2017. It was established to enhance science and cultural facilities in the Gangbuk area, aiming to bridge the gap in science and culture among different regions and promote balanced development across Seoul\'s districts. As a science experiential facility aimed at youth, it operates six permanent exhibition halls with 221 exhibits and a special rotating exhibition hall featuring exhibits related to the history of objects. It offers various educational programs and events, including family-friendly science-making experiences, group science classes for elementary, middle, and high school students, expert lectures, science experiments, and nature ecology programs that families can enjoy together.', '-5390', 'Tue-Fri 09:30-17:30 KST', 'Closed every Monday, January 1st, and the day of Lunar New Year and Chuseok', '01792  160, Hangeulbiseok-ro, Nowon-gu, Seoul', 'Subway Subway  Line1  Hagye Station  Exit 2,  1km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=61371&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=61372&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=61373&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=61374&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=61375&fileTy=MEDIA&fileNo=3&thumbTy=L', 5, 37.64144950, 127.07905750, 'ENPn1ua1r', NULL, NULL),
	(193, 'Kumho Museum of Art', 'https://english.visitseoul.net/attractions/Kumho-Museum-of-Art/ENP003100', 'The Kumho Museum of Art showcases artwork from famous, established artists as well as works from outstanding new artists. The museum hosts a concert series in their recital hall called the Kumho Gallery Concert. The concerts take place every Tuesday, Thursday, and Friday at 20:00 in the evening. There are also presentations on the artists and artworks on exhibition at the museum. These sessions are opened to the public as part of the museum\'s Kumho Academy. The Kumho Museum of Art is located near Gyeongbokgung Palace.', '-5754', 'Daily 10:00 - 18:00 (KST) (Last entry at 17:30)', 'Closed Mondays, Lunar New Year\'s Day & Chuseok', '110-061  18, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 1,  620m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16134&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16135&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16136&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16137&fileTy=MEDIA&fileNo=2&thumbTy=L', 4, 37.57746970, 126.97990830, 'ENP003100', NULL, NULL),
	(194, 'The War Memorial of Korea', 'https://english.visitseoul.net/attractions/WarMemorialofKorea/ENP000859', 'The War Memorial of Korea was established to remember the Korean War (6. 25. 1950 - 7. 27.1953) and to symbolize the desire for peaceful reunification of Korea. The museum consists of 6 individual exhibition halls and a combat experience room, a screening room and an outdoor exhibition area with memorial statues.    The Statue of Brothers located in the south-west corner of the outdoor exhibition area at the museum symbolizes the Korean War and the hope for reunification. The statue depicts a scene where a family??s oldest son, a South Korean soldier and his younger brother, a North Korean soldier meet on a battlefield. Their embrace expresses reconciliation, love and forgiveness.   There is also an extensive garden area around the memorial with an artificial waterfall, and a lake where visitors can picnic whilst enjoying the beautiful landscape. The museum houses more than 10,000 artifacts in the indoor and outdoor exhibition areas. It takes visitors about three hours to complete the tour. The first floor exhibition hall features a history of war from prehistoric times up to the Korean War. The combat experience room on the third floor offers visitors a special opportunity to experience a simulated life and death situation on the battlefield through special effects.', '-3743', 'Tue-Sun 09:30 - 18:00 \n*For more details, please refer to our website.', 'Closed Mondays & the day following national holidays', '04353  29, Itaewon-ro, Yongsan-gu, Seoul', 'Subway Line 4  Samgakji Station  Exits 11,  227m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49153&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49154&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49155&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49156&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49157&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.53961930, 126.97998540, 'ENP000859', NULL, NULL),
	(195, 'Seoul Urban Life Museum', 'https://english.visitseoul.net/attractions/Seoul-Urban-Life-Museum/ENP038243', 'The Seoul Urban Life Museum is a modern life and history museum that focuses on exhibitions and programs that allow guests to reminisce and interact with the memories of Seoul\'s citizens. There are facilities for everyone to enjoy, such as the Living Seoul Exhibition Room, which features displays on the life and scenery of Seoul, the Children\'s Experience Room for kids and the Special Exhibition room where various exhibitions are held throughout the year.', '-6219', 'Daily 09:00 - 18:00 *Closed Mondays* (KST)', 'monday', '01849  27, Dongil-ro 174-gil, Nowon-gu, Seoul', 'Subway Lines 6 / 7  Taereung Station  Exit 5,  320m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42817&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42818&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42819&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=42820&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73895&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61961170, 127.07677870, 'ENP038243', NULL, NULL),
	(196, 'Songeun Art Cube', 'https://english.visitseoul.net/attractions/Songeun-Art-Cube/ENP003778', 'Songeun Art Cube (formerly known as Songeun Gallery) is a space for new artists to exhibit their artworks. Operated by the Songeun Art Foundation, the space functions as a gallery but various arts events also take place here. Ever since it opened in 2002, Songeun Art Cube has held an annual arts award ceremony. Winners are sponsored by the foundation and receive support to exhibit their work.', '-3468', 'Daily 11:00 - 18:30', 'Closed Sundays & holidays', '06182  441, Dosan-daero, Gangnam-gu, Seoul', 'Subway Suin Bundang Line  Apgujeong Rodeo Station  Exit 4,  637m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50321&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50322&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50323&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50324&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=50325&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.52417460, 127.04404430, 'ENP003778', NULL, NULL),
	(197, 'The Seoul Museum of History', 'https://english.visitseoul.net/attractions/The-Seoul-Museum-of-History/ENP002722', 'The Seoul Museum of History is the only museum in Korea that represents the city??s history and culture. Since its establishment on the former site of Gyeonghuigung Palace in 2002, the museum has offered visitors the chance to experience 600 years of Seoul??shistoryand culture through interactive exhibitions. The three-story museum is divided thematically into three exhibition areas, including a special exhibition area, a permanent exhibition area and a hall that exhibits collections donated by the public.      The museum offers accessible and interactive exhibitions to the public with various hands-on programs. For example, visitors are allowed to touch and explore the exhibits on display, which are replicas of originals in the museum. In addition, the museumoffersthe U-Exhibit Guidance System, an automatic translator (various languages are available) for visitors, which makes every tour convenient and interesting.', '-918', 'KST 09:00 - 18:00 (Last Entry: 17:30 )\nExtended Hours: Every Friday until 21:00 \n*For more details, please visit the website.', 'Closed Mondays & New Year\'s Day', '03177  55, Saemunan-ro, Jongno-gu, Seoul', 'Subway Line 5  Gwanghwamun Station  Exit 7,  462m\nSubway Line 5  Seodaemun Station  Exit 4,  641m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68733&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68734&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68735&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68736&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68737&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57146560, 126.96841650, 'ENP002722', NULL, NULL),
	(198, 'Maehun Yun Bong-Gil Memorial Hall', 'https://english.visitseoul.net/attractions/Maehun-Yun-Bong-Gil-Memorial-Hall/ENP003759', 'The Maehun Yun Bong-Gil Memorial Hall is dedicated to the resistance fighter, Patriot Yun Bong-gil. Yun\'s pen name was Maehun and he was active in the Korean independence movement during the Japanese colonial era. Located in Seoul\'s Yangjae dong, the first floor of the memorial is an exhibition hall that displays relics and biographical information about Yun Bong-gil in chronological order. On the second floor, the exhibition hall contains photographs and other materials of the Korean independence movement organized by theme. Admission to the memorial hall is free.', '-3886', '* April to October: 10:00 - 18:00\n* November to March: 10:00 - 17:00\n??Last entry is 30 mins prior to closing', 'Closed Mondays, New Year\'s Day, Lunar New Year??s Day & Chuseok', '06773   99, Maeheon-ro, Seocho-gu, Seoul', 'Subway Sinbundang Line  Yangjae Citizen\'s Forest Station  Exit 5,  179m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2255&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2257&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=2258&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74827&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74828&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.47022040, 127.03778820, 'ENP003759', NULL, NULL),
	(199, 'The store from Tong-in', 'https://english.visitseoul.net/attractions/Tong-in-Shop/ENP025931', 'The oldest gallery specializing in antique art in Insadong, it was founded in 1924 as an antique art store representing Korea and became the backbone of culture and art during the turbulent times. The Tongin Gallery is located inside the Tongin Store and has become the center of Insadong as a complex cultural art space where ancient and contemporary art coexist. It is famous for its ancient art representing Korea and is a favorite place for world leaders. The tiger from a familiar folk tale is the representative character of Tongin Gallery.', '-5520', 'Tue-Sat 10:30~18:30, Sun 12:00~17:00 KST', 'Mondays', '03148  32 Insadong-gil, Jongno-gu, Seoul', 'Subway Line 1/3/5  Jongno 3-ga Station  Exit 5,  334m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60307&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60304&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60305&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60306&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60308&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57380170, 126.98636690, 'ENP025931', NULL, NULL),
	(200, 'Gongpyeong Historic Sites Museum', 'https://english.visitseoul.net/attractions/Gongpyeong-Historic-Sites-Museum/ENP026675', 'Gongpyeong Historic Sites Museum was created when well preserved 16th century Joseon sites were dug up during redevelopment phases of Gongpyeong district 1, 2, and 4.  The museum is largely divided into 4 parts: ??Coexistence of Development and Preservation?? ??Gyeonpyeong-bang of the Joseon Dynasty Period?? ??Modern Gongpyeong-dong?? and ??Historic Sites Archives.?? The completed Gongpyeong Historic Sites Museum displays the various relics and building structures of a neighborhood which managed to remain undisturbed for over 600 years, allowing visitors a closer look at the daily lives of people who had lived back in the Joseon Dynasty.', '-779', 'Daily 09:00 - 18:00 (KST)', 'Closed Mondays', '03161  26, Ujeongguk-ro, Jongno-gu, Seoul  (B1, Centropolis)', 'Subway Line 1  Jonggak Station  Exit 3-1,  69m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20284&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20283&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20286&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20285&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20282&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57161550, 126.98335320, 'ENP026675', NULL, NULL),
	(201, 'Platform-L Contemporary Art Center', 'https://english.visitseoul.net/attractions/PLATFORM-L/ENPn0wsm1', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Platform-L Contemporary Art Center was established to provide audiences with diverse artistic experiences through the creative endeavors of contemporary artists and to contribute to a society enriched with imagination and inspiration. Since its opening in spring 2016, Platform-L has housed facilities including galleries, a live hall, an open courtyard, and lecture rooms. The center presents exhibitions, performances, and video works across a wide range of genres and media.', '-11319', '11:00-20:00', 'Closed every Monday', '06053  11, Eonju-ro 133-gil, Gangnam-gu, Seoul', 'Subway Line 7, Hakdong Station, Exit 10, 284m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75518&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75519&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75520&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75521&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75522&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.51609050, 127.03429290, 'ENPn0wsm1', NULL, NULL),
	(202, 'Mokin Museum', 'https://english.visitseoul.net/attractions/Mokin-Museum/ENP001809', 'The Mokin Museum specializes in traditional wooden sculptures and woodwork. The museum is located in Insa-dong and consists of an underground lounge, an exhibition hall, and a rooftop garden. The museum collection includes traditional Korean wooden sculptures as well as traditional masks, staffs and wooden dolls from other parts of Asia. Mokin hosts various exhibitions and events throughout the year.', '-5697', '* Summer Season 10:30 - 19:00 (Last entry at 18:00) \n* Winter Season 10:30 - 18:00 (Last entry at 17:00)', 'Closed Sundays, Mondays, New Year\'s Day, Lunar New Year & Chuseok', '03022  46-1 Changuimun-ro 5-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  1.9km\nGet off at Buam-dong Community Center and walk 500m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17226&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17227&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17228&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17229&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73932&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58900690, 126.96325860, 'ENP001809', NULL, NULL),
	(203, 'The replica of an old mayor??s office', 'https://english.visitseoul.net/attractions/formermayorsoffice/ENP678cv8', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The Reconstructed Former Mayor??s Office is a workspace used by former mayors of Seoul for over 60 years, from the post-liberation period until May 2008. Located at the center of the 3rd floor of the Seoul Metropolitan Library, this space comprises a planning room, reception room, and office, featuring faithfully restored furniture and office equipment from that time.', '-5023', 'Every Tue-Sun, 09:00-18:00  (Closed on Mondays and public holidays)', 'Mondays and public holidays', '04524  110 Sejong-daero, Jung-gu, Seoul (Seoul Library 3rd floor)', 'Subway Lines 1 / 2  City Hall Station  Exit 5,  53m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64621&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64624&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64625&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64627&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=64628&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.56625700, 126.97781490, 'ENP678cv8', NULL, NULL),
	(204, 'Seo Gallery', 'https://english.visitseoul.net/attractions/Seo-Gallery/ENP001966', 'The Seo Gallery is an arts gallery in Banpo-dong, Seoul. Its exhibitions cover a wide variety of different mediums including, but not limited to, painting, sculpture, photography, architecture, design, and fashion. The gallery also provides various programs to support both older artists and to foster new artists.', '-6115', '10:00 - 17:00 (KST)', 'Closed Weekends', '06648  94, Banpo-daero, Seocho-gu, Seoul', 'Subway Line 2, Seocho Station, Exit 2', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17252&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17253&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17254&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17255&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.48981140, 127.00984170, 'ENP001966', NULL, NULL),
	(205, 'Donuimun Museum Village', 'https://english.visitseoul.net/attractions/Donuimun-Museum-Village/ENP023761', 'The Donuimun Museum Village is an outdoor village that consists of hanok (traditional Korean homes) and buildings that showcase historical eras of Seoul architecture. Visitors can see the architectural styles of the 1900s up to the 1980s at this special outdoor museum. Founded in September 2017, the museum village is conveniently located between the Gangbuk Samsung Hospital and the Seoul Museum of History.       Through urban regeneration efforts, Donuimun Museum Village has preserved 40 out of 63 houses in    Saemunan,    an old neighborhood district. Architecture from Korea\'s modern history era and Joseon Dynasty exist side by side in this newly developed cultural space.       The renovated houses were rehabilitated as exhibition and experience spaces.      ??An exhibition space where the history of Saemunan-dong and the sensibility of the analog generation are alive      - Donuimun Museum Village, Donuimun Club, Seoul Future Heritage Hall, 60s 80s emotional spaces (Citizens??Life History Hall, Saemunan Theater, Seodaemun Photo Studio, and more)       ??Learn about modern and contemporary culture and art in a calm hanok with ??Artist\'s time??(9 Hanok-dong locations)      - Various experience programs such as Socks Remnants Craft Workshop, Hanji (Korean Paper) Craft Workshop, Maedeup (Knot) Workshop, traditional mask clock making, and Danoseon making      - Donuimun Market, Donuimun Time Travel Club, Immersive Theater (??a hundred-year-old night??, Memories??Music Cafe (Saturdays 12:00-15:00), Donuimun Night School         Both interior and exterior including the alleyways, yards, and walls of the village are all part of this unique exhibition playground. Various performances and events including flea market and food trucks will take place in the village square and visitors are encouraged to walk around the village alleyways to learn more about Saemunan and its past residents.', '-7653', 'Tue-Sun 10:00 - 19:00 (KST)', 'Closed Mondays & New Year\'s Day', '03178  14-3, Songwol-gil, Jongno-gu, Seoul', 'Subway Line 5, Seodaemun Station, Exit 4, 349m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=71820&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=71821&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=71822&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=71823&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57074800, 126.96722240, 'ENP023761', NULL, NULL),
	(206, 'THEO', 'https://english.visitseoul.net/attractions/2024-THEO/ENP9q04ig', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Gallery THEO, known for showcasing Korean art\'s broad spectrum and diversity, was established in 2020 by two directors with experience in the UK and the international art market. They aimed to introduce global expertise and networks to the Korean art scene. Located in front of the UNESCO World Heritage site Seonjeongneung, THEO is dedicated to supporting young and talented Korean artists, regardless of artistic genre, and uncovering the potential in their works. The gallery actively provides a platform for Korean artists to grow and thrive. In addition, THEO introduces international artists to the Korean and Asian art communities, fostering cross-cultural exchanges and expanding artistic discourse beyond national borders. THEO continues to host exhibitions featuring diverse artists worldwide. It aims to create a space where artists can coexist and flourish, driven by a commitment to challenging projects and artistic excellence.', '-7766', '13:00~19:00', 'Monday, Sunday, and public holidays', '06156  B1, 55-3 Bongeunsa-ro 68-gil, Gangnam-gu, Seoul', 'Subway Line 9  Samsung Jungang Station  Exit 6,  539m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67542&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67543&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67544&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67545&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.50952060, 127.05355050, 'ENP9q04ig', NULL, NULL),
	(207, 'Seoul Baekje Children\'s Museum', 'https://english.visitseoul.net/attractions/SeoulBaekjeChildrensMuseum/ENPeenv2i', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Seoul Baekje Children\'s Museum is the only children\'s museum in the Gangnam area that exhibits and educates about the fact that Mongchontoseong was the royal fortress of the ancient kingdom of Baekje, Seoul\'s 2,000-year urban history, and the ancient culture of the Han River basin. Seoul Baekje Children\'s Museum is affiliated with Hanseong Baekje Museum and reopened in May 2024. It displays various artifacts excavated from Pungnap-dong Earthen Fortification, Mongchontoseong, and Seokchon-dong Ancient Tombs, which were Baekje\'s royal fortresses. The site offers a range of educational programs and cultural events, allowing visitors to experience and appreciate Seoul\'s rich ancient history and culture firsthand.', '-7972', '[Weekdays] 9:00 AM - 6:00 PM (self-guided tour) *Entry closes at 5:30 PM\n[Weekends and holidays] 9:30 AM - 5:30 PM (reservation required)', 'Closed every Monday, January 1st\n*Open on Mondays that fall on holidays', '05540  Seoul Baekje Children\'s Museum, Olympic-ro 424, Songpa-gu, Seoul', 'Subway Lines 5/9 Olympic Park Station Exit 3, 1.6km / Line 8 Mongchontoseong Station Exit 1, 1.7km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74214&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74215&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74216&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74217&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74218&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52380380, 127.12443320, 'ENPeenv2i', NULL, NULL),
	(208, 'Seoul Sewerage Science Museum', 'https://english.visitseoul.net/attractions/Seoul-Sewerage-Science-Museum-1/ENP033825', 'p { text-align: justify; word-spacing: 2px; }  Established in 2017 to promote the history and science of sewerage, the Seoul Sewerage Science Museum is the nation\'s first science museum specializing in sewerage. It was constructed at the site of the Cheonggyecheon Sewage Treatment Plant, the country\'s first sewage disposal plant, to continue the historical significance and values of the facility. The museum is also a space that is centered on on-site experience, comprised of a science exhibition hall that displays the history, technology, and future of domestic and overseas sewerage, as well as a water reclamation center where visitors can take a look around sewerage facilities. As the center of environmental education, the Seoul Sewerage Science Museum offers various programs to teach the process of sewage purification and the significance of water.', '-4671', 'Tue - Sun 09:00 ??17:00 (Closed Mondays, New Year\'s Day, Lunar New Year\'s, and Chuseok)', '', '04809  64, Jadongchasijang 3-gil, Seongdong-gu, Seoul (Seoul Sewerage Science Museum)  250-4, Yongdap-dong', 'Subway Line 5  Janghanpyeong Station  Exit 8,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28620&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28621&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28622&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28623&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=28624&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.55795630, 127.05783900, 'ENP033825', NULL, NULL),
	(209, 'Gallery Kong', 'https://english.visitseoul.net/attractions/Gallery-Kong/ENP026676', 'Since its opening in 2005, Gallery Kong has showcased a wide range of globally famous photographers, greatly influencing the photography industry in Korea.    When the gallery moved into the newly built facility next to Cheongwadae??s Chunchugwan in Samcheong-dong, it expanded from being just a photo gallery to a multimedia gallery displaying all kinds of modern art, including communication arts, sculpture, video installations, etc.    By showcasing works of globally famous artists like Bernard Faucon (France), Chen Ruo Bing (China), Michael Kenna (UK), and Erwin Olaf (Netherlands), Gallery Kong is a gallery which shows the trend of contemporary art in 21st century Korea. This gallery also plays a very crucial role in helping Korean artists establish presence abroad by connecting them to galleries and shows outside Korea.', '-8434', '* Tuesdays - Saturdays 10:00 - 18:00', 'Closed Mondays, Sundays', '03049  38, Samcheong-ro 7-gil, Jongno-gu, Seoul', 'Subway Line 3, Anguk Station, Exit 1,  1.2 km\nSubway Line 3, Gyeongbokgung Station, Exit 5,  1.5 km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20287&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20288&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20289&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20290&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=20291&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.58402800, 126.97967590, 'ENP026676', NULL, NULL),
	(210, 'Hwanghakjeong Korean Archery Gallery', 'https://english.visitseoul.net/attractions/Hwanghakjeong-Korean-Archery-Gallery/ENP029767', 'Hwanghakjeong Korean Archery Gallery is a place where visitors can go to learn about the history of archery in Korea and see the excellent quality of Korean bows. Made up of 5 different sections including exhibition halls, experience centers, and a permanent exhibition showcasing donated artifacts, this gallery is a great place for visitors to learn about traditional Korean archery and offers various programs where visitors can make arrows, try out archery, and more.', '-2242', 'KST 10:00 - 17:00', 'Closed Monday, New Year\'s Day, Lunar New Year & Chuseok', '03027  15-32 Sajik-ro 9-gil, Jongno-gu, Seoul, Republic of Korea  Hwanghakjeong Archery Museum', 'Subway Line 3  Gyeongbokgung Station  Exit 1,  841m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22587&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22589&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22590&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22588&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57700650, 126.96478980, 'ENP029767', NULL, NULL),
	(211, 'Sungkok Art Museum', 'https://english.visitseoul.net/attractions/Sungkok-Art-Museum/ENP001907', 'p { text-align: justify; word-spacing: 2px; } The Sungkok Art Museum was established in 1995 to promote and foster Korean arts. The museum also commemorates the late founder of the Ssangyong Group, Kim Sungkok, and the museum was built on the site of Kim Sungkok\'s house. Creative work from all artistic genres such as photography, design, and fashion, is showcased in various exhibitions. The museum typically hosts more than a dozen exhibitions each year. There are three exhibition halls and an outdoor sculpture garden.', '-8307', 'Daily 10:00 - 18:00 (KST)\n* Last entry at 17:30 (KST)', 'Closed Sundays, Mondays & Holidays', '03175  42, Gyeonghuigung-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 7,  611m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17256&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17257&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17258&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=17259&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73924&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57227660, 126.97118790, 'ENP001907', NULL, NULL),
	(212, 'Donuimun Museum', 'https://english.visitseoul.net/attractions/Donuimun-Museum/ENP029381', 'p{ text-align:justify; word-spacing:2px; } Donuimun Museum is a new cultural space constructed from old restaurant buildings located in the old neighborhood of Saemunan. Originally built as residential homes back in 1960, these buildings were used as restaurants from 1990 to 2000, some of which included Italian restaurant AGIO and Korean restaurant Hanjeong. While preserving the architecture of the old structure, the buildings were reinforced for safety during their renovation into exhibition spaces.  Located in a central location within Saemunan surrounded by Seoul City Wall and the walls of Gyeonghuigung Palace, the spaces inhabited by AGIO and Hanjeong hold great historical and cultural value. When portions of Gyeonghuigung Palace Wall were discovered underground, the site has been transformed to preserve and display the remains. At Donuimun Museum, visitors can learn about the culture and history surrounding the area around it.     Donuimun Museum  AGIO     * History of the Donuimun Gate Area: After Ports Were Opened/History of the Donuimun Gate Area: Joseon Dynasty (1F)  * Records and Recollections of Two Villages : Gyonam-dong and Saemunan Village (2F)      Donuimun Museum  Hanjeong     * Urban Regeneration of the Saemunan Village / Photo Gallery (1F)  * The Story of Saemunan Village People (2F)      Donuimun Museum  Historic Remains     * Ruins of Gyeonghuigung Palace Wall        About the museum', '-915', 'Daily 09:00 - 18:00 (KST) (Last admission 17:30)', 'Closed Mondays & New Year\'s Day', '03178  35-54, Saemunan-ro, Jongno-gu, Seoul', 'Subway Line 5  Seodaemun Station  Exit 4,  400m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22214&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22215&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22216&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22217&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22218&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57074800, 126.96722240, 'ENP029381', NULL, NULL),
	(213, 'Gallery Chosun', 'https://english.visitseoul.net/attractions/gallerychosun/ENP5hau1h', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Established in 2004, Gallery Chosun traces its roots to Chosun Gallery, which played a pioneering role by participating in international fairs such as ART COLOGNE in Germany, NICAF in Tokyo, and CIGE in Beijing, and organizing over 400 domestic exhibitions. Since its founding, Gallery Chosun has participated in Art Cologne and Art Basel Miami, focusing on contemporary art exhibitions to promote Korean contemporary art internationally.', '-7776', '10:30-18:30', 'Closed every Monday', '03053  64, Bukchon-ro 5-gil, Jongno-gu, Seoul', 'Subway Line 3, Anguk Station, Exit 2, 582m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75507&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75508&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75509&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75510&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57994040, 126.98147440, 'ENP5hau1h', NULL, NULL),
	(214, 'Hohojae Seoul', 'https://english.visitseoul.net/attractions/hohojae-seoul/ENPbnvhzx', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Hohojae is a Hanok Gallery where the space and the artworks harmonize beautifully. Though the name uses the Chinese character ho (?? meaning butterfly, it also reflects the desire to create a place that brings a smile, like a cheerful ??hoho?? laugh. The exhibitions mainly feature works that are easy for the public to relate to. On the first floor, there is a cozy yard and a small flower bed, while the second floor offers a view of hanok rooftops in Palpan-dong through large windows, allowing visitors to fully enjoy the beauty of traditional Korean aesthetics.', '-10386', 'Tuesday??Sunday 11:00??9:00', 'Every Monday', '03054  71-7 Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3, Anguk Station, Exit 2, 830 km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73221&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73222&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73223&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73224&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58279480, 126.98078470, 'ENPbnvhzx', NULL, NULL),
	(215, 'Hanji House', 'https://english.visitseoul.net/attractions/HanjiHouse/ENP6nkrnk', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Hanji House is a space operated by the Korea Craft & Design Foundation to promote the excellence of hanji, a traditional heritage, and expand its use. Hanji House is a space where information on domestic hanji workshops and traditional paper is professionally collected, and it is also a hanji culture promotion center that promotes and exchanges hanji culture.', '-7261', '10:00-19:00', 'Closed on Mondays', '03055  31-9 Bukchon-ro, Jongno-gu, Seoul', 'Subway Line 3 Anguk Station Exit 2, 355m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74868&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74869&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74870&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74871&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74873&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58061350, 126.98388870, 'ENP6nkrnk', NULL, NULL),
	(216, 'KCDF Gallery', 'https://english.visitseoul.net/attractions/KCDFGallery/ENP037044', 'Located along the street of tradition itself, Insadong, KCDF Gallery is a space dedicated to the exhibition of crafts and was created to help promote the rise of the crafts industry, while contributing to a communicative platform for craftsmen and women, as well as the  dissessimation of the  consumer culture of crafts. The KCDF Library is also available, serving as a ground for  research activity that offers literature and various data on  a wide array of crafts designs along with  exhibitions, training programs, and  seminar spaces  for artists in the crafts design culture industry. On the first-floor shop of the gallery, visitors may also purchase premium crafts created by some of the finest specialists and artists in the country.* The Korea Craft & Design Foundation is a public government organization operated by the Ministry of Culture, Sports and Tourism that was established for the promotion of crafts, public design, and traditional & lifestyle culture. The foundation focuses on establishing a cultural identify of Korea through the  dissessimation  and promotion of crafts, design, and tradtional & lifestyle cultures , in addition to contributing to an improved quality of life by strengthening the country\'s compeitive capactiy.', '-10034', '- Exhibition hall: Tue-Sun 10:00 - 18:00\n- Craft Garden: Tue-Sun 10:00 - 19:00\n(Break time 12:00 - 13:00)\n- KCDF Data Room: Tue-Fri 09:00 - 18:00 / Sat 10:00-19:00\n(Break time 12:00 - 13:00)', '', '03145  8, Insadong 11-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 6,  380m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40197&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40198&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40199&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40200&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40201&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57401550, 126.98411990, 'ENP037044', NULL, NULL),
	(217, 'The Museum of Korean Medical History', 'https://english.visitseoul.net/attractions/Museum-of-Korean-Medical-History-at-Kyung-Hee-University/ENP006886', 'The Museum of Korean Medical History at Kyung Hee University displays a wealth of information relating to medicine and history. Some of the artifacts on display are ancient medical books, medical records, and artifacts relating to traditional Korean medicine. Visitors can also learn about the development of traditional medicine in Korea throughout history and information is displayed by time period. The museum is open to the public.', '-4074', 'Daily 10:00 - 16:00', 'Closed Weekends & Holidays', '130-050  26, Kyungheedae-ro, Dongdaemun-gu, Seoul', 'Subway Line 1  Hoegi Station  Exit 1,  1.2km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3764&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3765&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3766&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.59671220, 127.05139480, 'ENP006886', NULL, NULL),
	(218, 'Samsung Museum of Publishing', 'https://english.visitseoul.net/attractions/Samsung-Museum-of-Publishing/ENP003330', 'p { text-align: justify; word-spacing: 2px; }  The Samsung Museum of Publishing is a private museum dedicated to all things related to printing and publishing. Located in Gugi-dong, Jongno-gu, visitors can see all manner of artifacts and historical items at the museum. Founded in 1990 by Kim Jonggyu of the Samsung Publishing Company, guided tours in Korean are available if reserved in advance.', '-6858', 'Weekdays 10:00 - 17:00 (KST)', 'Closed weekends & holidays', '03007  2-2, Bibong-gil, Jongno-gu, Seoul', 'Subway Lines 3 & 6, Bulgwang Station, Exit 2\n(Take bus nos. 7022 or  7211 ??Get off at Gugi Tunnel stop)\n Subway Line 3, Gyeongbokgung Station, Exit 3\n(Take bus nos. 7022 or 7212 ??Get off at Gugi Tunnel stop)', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23378&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23379&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23380&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=23381&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73781&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.60870420, 126.95707270, 'ENP003330', NULL, NULL),
	(219, 'Kim Joong-up House of Architectural Culture', 'https://english.visitseoul.net/attractions/Kim-Joong-up-House-of-Architectural-Culture/ENP042446', 'Built in the 1970s, this two-story detached house was remodeled in 1986 by Kim Joong-up, who added exotic elements to every corner of the house based on traditional Korean architecture. This is a place where you can get a glimpse of the housing culture of the middle class at the time, and was designated as a Seoul Future Heritage in 2017. The KimJoong-up House of Architectural Culture harmoniously integrates Korean and Western architectural styles. The second-floor living room has an umul-maru, rafter structure, and windows covered with changhoji paper, which are mainly used in hanok, but with a modern interpretation. In contrast, the bathroom was designed in a European style. The dry bathroom with a dressing room attached, something that wasn??t common in Korea during the \'70s and \'80s, has a vintage jade-colored interior that stands out. Stepping out to the elegantly decorated garden, a water element, a characteristic of Kim Joong-up\'s architecture, is located on one side of the yard. Even equipped with its own small greenhouse, the Kim Joong-up House of Architectural Culture contains immense nature in the garden.', '-9962', 'Daily 10:00 ~ 17:00', 'Closed Sundays & Mondays', '02755  11, Jangwi-ro 21na-gil, Seongbuk-gu, Seoul', 'Subway Line 6, Dolgoji Station, Exit 2,  1.5km', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56688&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56689&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56690&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56691&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=56692&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.61498240, 127.04408770, 'ENP042446', NULL, NULL),
	(220, 'The Story of King Sejong ??The Story of Admiral Yi Sunshin', 'https://english.visitseoul.net/attractions/King-Sejong-and-Admiral-Yi-Sunshin/ENP005465', 'The Story of King Sejong and The Story of Admiral Yi Sunshin are exhibitions halls about two of Korea\'s national heroes, King Sejong and Admiral Yi. The exhibition halls are located on the B2 level of the Sejong Center for the Performing Arts. In addition to viewing the exhibitions, children can also experience traditional Korean culture and try on hanbok. For more information on these activities, please ask at the information desk.', '-1319', 'Daily 10:00 - 18:30 (Last entry at 18:00 ) *Closed Mondays*', '', '03172  175, Sejong-daero, Jongno-gu, Seoul', '* Subway Line 3, Gyeongbokgung Station, Exit 6   * Subway Line 5, Gwanghwamun Station, Exit 2 (30 m on foot)* Subway Line 1, Jonggak Station, Exit 1', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3083&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3084&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3085&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.57272210, 126.97540230, 'ENP005465', NULL, NULL),
	(221, 'Lotte World Folk Museum', 'https://english.visitseoul.net/attractions/Lotte-World-Folk-Museum/ENP005815', 'The Lotte World Folk Museum highlights Korean folk culture through miniature displays. Located at Lotte World, visitors can enjoy seeing model villages from different periods of history. There is also a crafts room where visitors can see traditional crafts being made. The museum has a children\'s educational facility that runs various kid-friendly programs during school breaks.', '+82-2-411-4761~5', '* Weekdays: 11:00 - 19:00 KST\n* Weekends: 11:00 - 20:00 KST\n??Last entry is 1 hour before closing.', 'Open year round', '05554  240, Olympic-ro, Songpa-gu, Seoul', 'Subway Lines 2 / 8, Jamsil Station, Exit 2, 144m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3255&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3256&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3257&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73589&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73590&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.51128620, 127.09793920, 'ENP005815', NULL, NULL),
	(222, 'Jeongdok Public Library', 'https://english.visitseoul.net/attractions/Jeongdok-Public-Library/ENP001596', 'The Jeongdok Public Library was established to provide Seoulites and visitors with a space to study and enjoy books. The library is affiliated with Yanbian Library in the Yanbian Korean Autonomous Prefecture of China and Japan\'s Tokyo Metropolitan Library. The Jeongdok Public Library is one of the major libraries of the city\'s public library system.', '-7730', 'Study Rooms\n* Weekdays 07:00 - 22:00 (November - February 08:00 - 22:00)\n* Weekends 07:00 - 22:00 (November - February 08:00 - 22:00)', 'Closed on the 1st & 3rd Wednesday of the month, national holidays, and other days as designated by the library', '03055  48, Bukchon-ro 5-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 2,  720m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49854&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49855&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49856&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49857&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=49858&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.58061350, 126.98388870, 'ENP001596', NULL, NULL),
	(223, 'Gyeomjae Jeong Seon Art Museum', 'https://english.visitseoul.net/attractions/Gyeomjae-Jeong-Seon-Art-Museum/ENP001961', 'The Gyeomjae Jeong Seon Art Museum is dedicated to the Joseon-era artist Jeong Seon. Located in Gangseo-gu, the museum has 4 levels. In addition to the special exhibition halls, there is a permanent memorial hall with information about the life and works of Jeong Seon. The museum\'s multipurpose facility can be used for lectures, seminars, and video screenings.', '-4785', 'Tuesday to Friday: 10:00 ??18:00 \nSaturday and Sunday: 10:00 ??17:00 \nNational Holidays 10:00 - 17:00 \n??Last entry is 1 hour before closing.', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', '07522  36, Yangcheon-ro 47-gil, Gangseo-gu, Seoul', 'Subway Line 9, Yangcheon Hyanggyo Station  Exit 1,  487m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72845&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72846&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72847&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72848&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72849&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57223180, 126.83871200, 'ENP001961', NULL, NULL),
	(224, 'Gallery Jiwooheon', 'https://english.visitseoul.net/attractions/GalleryJiwooheon/ENPxj9byw', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}Gallery Jiwooheon is an exhibition venue operated by Designhouse, Inc., located in Bukchon Hanok Village. It was selected as the 2016 Seoul Excellent Hanok for its distinctive structure remodeled from a hanok, which offers both trad itional aesthetics and contemporary convenience and has remarkable architectural beauty. It aspires to identify outstanding new artists at home and abroad while supporting the trend of contemporary art as a gallery with temporal and spatial qualities that shines a light on contemporary art in a space possessing the history of the past.', '-9731', 'Tuesday-Saturday 10:00-18:00 KST (off-time 12:30~13:30)', 'Sunday, Monday, and public holidays', '03052  13, Bukchon-ro 11ra-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 2,  839m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60627&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60628&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60629&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60630&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60631&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.58329910, 126.98294490, 'ENPxj9byw', NULL, NULL),
	(225, 'Children\'s Folk Museum', 'https://english.visitseoul.net/attractions/Childrens-Folk-Museum/ENP005130', 'Located at the National Folk Museum of Korea, the Children??s Folk Museum offers fun hands-on experiences relating to traditional Korean culture. The Children\'s Folk Museum charges no admission and it is located next to the second exhibition hall of the National Folk Museum of Korea. Capacity is limited and operating hours differ by month, so please check in hours advance. 50 people are admitted at a time, for thirty minutes sessions.', '-8164', '09:30 - 17:00', 'Closed Mondays, January 1st, Lunar New Year & Chuseok', '03045,  37, Samcheong-ro, Jongno-gu, Seoul', 'Subway Line 3 Anguk Station Exit 1, 900m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16495&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16496&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16497&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72912&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=72913&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.57805050, 126.97712400, 'ENP005130', NULL, NULL),
	(226, 'Figure Museum W', 'https://english.visitseoul.net/attractions/Figure-Museum-W/ENP015863', 'The Figure Museum W is a museum dedicated to figurines and toys! Visitors to Seoul who have an interest in figurines, anime, and toys should make time to visit the museum. Exhibitions at the museum feature beloved superhero and animated figurines. Visitors can also purchase figures and souvenirs at the museum\'s gift shop.', '-9297', 'Weekdays 13:00~17:00 Weekends 11:00~18:00', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok\n(If a holiday falls on a Monday, the museum opens on Monday and closes the following day.)', '06014  3, Seolleung-ro 158-gil, Gangnam-gu, Seoul', 'Subway Bundang Line  Apgujeong Rodeo Station  Exit 4,  103m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8602&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8603&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8592&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8594&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8596&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8597&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=8601&fileTy=MEDIA&fileNo=2&thumbTy=L', 7, 37.52580050, 127.04038540, 'ENP015863', NULL, NULL),
	(227, 'Korea University Main Hall & Old Main Library', 'https://english.visitseoul.net/attractions/Korea-University-Main-Hall--Old-Main-Library/ENP002962', 'Korea University is one of best universities in all of Korea. Visitors to Seoul can visit the Korea University Main Hall located in Anam-dong, Seoul. This beautiful three-story tall building was built in 1932 during the Japanese colonial period. In 1981 the hall was designated Historic Site No. 285 in 1981. The Old Korea University Main Library, located nearby, was designated Historic Site No. 286 in 1981.', '-4324', 'Same hours as Korea University.', '', '02841  145, Anam-ro, Seongbuk-gu, Seoul', 'Subway Line 6  Anam Station  Exit 2,  527m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68431&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68432&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68433&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.58874960, 127.03237350, 'ENP002962', NULL, NULL),
	(228, 'Shuim Museum', 'https://english.visitseoul.net/attractions/Shuim-Museum/ENP029578', 'Shuim Museum aims to preserve a forgotten culture by integrating it with contemporary culture and arts. Highlighting a heavy theme of life and death, the museum remodeled the founder\'s house as an exhibition venue and resting area. Holding exhibition on the museum\'s collection and various contemporary artists, Shuim Museum hopes to facilitate and encourage communications about art with its visitors.', '-9593', '* Summer (Apr - Oct)\n- Tue - Sat 10:00 - 18:00 (KST)\n- Sun 14:00 - 19:00 (KST)\n\n* Winter (Nov - Mar)\n- Tue - Sat 10:00 - 17:00 (KST)\n- Sun 14:00 - 18:00 (KST)', '', '03015  209-17, Segeomjeong-ro, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  0212, 1020, 1711, 7016, 7018, 7022 (Get off at Sangmyung University Entrance). Subway Line 5  Gwanghwamun Station  Exit 3,  in front of Kyobo Building, 0212, 1020, 1711, 7016, 7018 (Get off at Sangmyung University Entrance).', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22454&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22455&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22456&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22457&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.59948290, 126.95567480, 'ENP029578', NULL, NULL),
	(229, 'National Palace Museum of Korea', 'https://english.visitseoul.net/attractions/National-Palace-Museum-of-Korea/ENP020550', 'The National Palace Museum of Korea showcases 500 years of history with roughly 45,000 artifacts from the Joseon Dynasty. Artifacts on display include texts and poems that were handwritten by kings of the past, robes worn by royalty, jewelry, and other items from the royal courts of Korea. Highlights from the museum collection are many, one highlight is the royal vehicle of Emperor Sunjong, the last king of the Joseon Dynasty. Another highlight of the colelction is the rain gauge pedestal. The rain gauge pedestal was an invention that dated back to the Joseon era.The museum also offers a learning program called "Experiencing Royal Culture;" the program is suitable for people of all ages. Spend time at the National Palace Museum of Korea to experience and learn about the grandeur and history of Korea\'s royalty.??Joseon Dynasty: The royal dynasty lasted from 1392 until 1910. The 518-year reign of the royal Lee family spanned 27 generations.??Rain Gauge Pedestal: The device was used to measure rainfall.??Royal Vehicle of Emperor Sunjong: The vehicle is a 1918 model of the General Motors Cadillac Limo usine.', '-11121', 'Daily 10:00 - 18:00 \n* Wednesday · Saturday 10:00 - 21:00', 'Open year round', '03045  12, Hyoja-ro, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 5,  135m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14392&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14393&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14394&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=14395&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.57702070, 126.97663100, 'ENP020550', NULL, NULL),
	(230, 'Chung Won San Bang', 'https://english.visitseoul.net/attractions/Cheongwon-Sanbang/ENP004996', 'The name "Cheongwon Sanbang" is derived from Shim Yong-sik\'s carpenter\'s pen name "Cheongwon" and means "clear and round." Still making all the doors by hand in a traditional way, the center is dedicated to researching and preserving the window-knitting art, the face of hanok architecture. Shim Yong-sik, a craftsman who reinterprets traditional windows in a modern way and makes original windows, was selected as Seoul\'s Intangible Cultural Property No. 26 in 2006 in recognition of his achievements.', '-3977', 'Saturday 10:00~17:00 (by appointment)', 'By reservation', '03056  27, Bukchon-ro 6-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 3,  430m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60830&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60831&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60833&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=60832&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58042680, 126.98636400, 'ENP004996', NULL, NULL),
	(231, 'Cheongwadae Sarangchae', 'https://english.visitseoul.net/attractions/Cheongwadae-Sarangchae/ENP006007', 'Cheongwadae Sarangchae is a historical memorial museum where visitors can learn about the past, present, and future visions of Seoul and Korea. Originally the home of the public information hall of Cheongwadae (the Blue House, the Korean presidential residence) called ??Hyojadong Sarangbang?? it re-opened with its present name in January 2010 after extensive renovation. Cheongwadae Sarangchae is a two-story building, with exhibition halls, souvenir shops, a resting area on the first floor, and experience zones on the second floor.Cheongwadae Sarangchae features the Korea Hall, the Hi Seoul Hall, a traditional handicrafts demonstration room, a souvenir shop, and a café on the first floor. Various cultural events, such as demonstrations of traditional handicrafts and traditional Korean tea tasting, are held regularly in the lobby. The souvenir shop stocks Cheongwadae-themed goods and traditional Korean items. After viewing the exhibitions, it is pleasant to take a break at the café and enjoy a cup of traditional Korean tea.The Presidential Hall on the second floor displays material about the former presidents of Korea. Here visitors can explore the political and economic events of Korea from the past up to the present day via pictures and visuals. Visitors can also see at a glance a chronology of the past 60 years of Korean history, as well as the major events in the democratization and industrialization of Korea.', '-241', '', '- Closed Tuesdays (If a national holiday falls on Tuesdays, closed on the following weekdays)\n- On January 1st', '45, Hyoja-ro 13-gil, Jongno-gu, Seoul', 'Subway Line 3  Gyeongbokgung Station  Exit 4,  800m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=21561&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=21562&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=21563&fileTy=MEDIA&fileNo=1&thumbTy=L', 3, 37.58262580, 126.97309910, 'ENP006007', NULL, NULL),
	(232, 'Korea Furniture Museum', 'https://english.visitseoul.net/attractions/Korea-Furniture-Museum/ENP003452', 'The Korea Furniture Museum is a unique museum that focuses only on traditional wooden furniture. The museum\'s collection boasts more than 2,500 pieces of traditional Korean furniture. Rather than exhibiting the collection behind glass in a regular museum set-up, the pieces are displayed in 10 hanok to show visitors how these pieces would have actually been used in daily life. Visitors must make reservations in advance to visit the museum. Reservations can be made online in English at the museum\'s website and the ticket includes a guided tour.', '-846', '*The museum is currently closed for renovation.', 'Closed Mondays, Sundays & Public Holidays', '02822  121, Daesagwan-ro, Seongbuk-gu, Seoul', 'Subway Line 4, Hansung University Station Exit 6, take Bus No. 02 to Seongbuk and get off at the entrance of the Korea Furniture Museum, 196m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16430&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16431&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16432&fileTy=MEDIA&fileNo=2&thumbTy=L', 3, 37.59914310, 126.98945440, 'ENP003452', NULL, NULL),
	(233, 'Bukchon Asian Cultural Art Museum', 'https://english.visitseoul.net/attractions/Bukchon-Asian-Cultural-Art-Museum/ENP005667', 'The Bukchon Asian Cultural Art Museum displays Korean and Asian artwork. The museum\'s founder, Kwon Youngdu, dedicated 30 years of his life to collecting art from Korea and other parts of Asia. Located in the Bukchon Hanok Village, the museum was constructed in the style of a traditional Korean hanok. The museum also offers activities programs such as folk painting and traditional cooking.', '-833', '10:00 - 18:30', '', '03052  76, Bukchon-ro 11-gil, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 2,  903m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3183&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3184&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=3185&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73779&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.58402520, 126.98344740, 'ENP005667', NULL, NULL),
	(234, 'Seoul Metropolitan Library', 'https://english.visitseoul.net/attractions/Seoul-Metropolitan-Library/ENP010231', 'The former Seoul City Hall has reopened its doors as the city\'s main public library. Seoul Metropolitan Library is the city\'s main public library and it\'s easily accessible from City Hall Station\'s exit 4 or 5. The "Tong Tong" Seoul City Walking Tour takes visitors through the library and the new Seoul City Hall building. Tours are free and led by a cultural tour guide.', '-2353', '* Weekdays 09:00 - 21:00 KST\n* Weekends 09:00 - 18:00 KST', 'Closed Mondays', '04524   110, Sejong-daero, Jung-gu, Seoul', 'Subway Lines 1 / 2, City Hall Station, Exits 4,  126m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68405&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68406&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=70522&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68407&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68408&fileTy=MEDIA&fileNo=4&thumbTy=L', 5, 37.56658510, 126.97820380, 'ENP010231', NULL, NULL),
	(235, 'Beautiful Tea Museum', 'https://english.visitseoul.net/attractions/Beautiful-Tea-Museum/ENP004467', 'The Beautiful Tea Museum collects and exhibits information and items related to tea. Located in an elegant Hanok in the Insa-dong area, visitors can learn about and sample a wide range of teas. There are also porcelain works on display and for purchase from talented ceramists. At the tea shop inside the museum, over 110 kinds of tea from around the world including Korea, China, Japan, and Europe are on offer. Admission to the museum is free.', '-7333', 'Gallery 11:30 - 20:00 KST\n* Museum open year-round', 'Open year round', '03162  19-11, Insadong-gil, Jongno-gu, Seoul', 'Subway Lines 1/3/5, Jongno 3(sam)-ga Station  Exit 5,  241m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12515&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12516&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12517&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=12518&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73973&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57228920, 126.98582840, 'ENP004467', NULL, NULL),
	(236, 'Popcon D Square', 'https://english.visitseoul.net/attractions/Popcon-D-Square/ENP025768', 'Popcon D Square is a cultural space operated by Daewon Media, a company specializing in animation. Through spaces that reflect the imaginary more than reality, visitors will be sure to enjoy their experiences here.    A place that shows a wide range of exhibitions not limited to a country or genre, Popcon D Square continues to expand itself as a place where visitors can come to enjoy culture and content within the city.', '-9293', 'Weekdays 10:30 - 20:30\nFridays & Weekends 10:30 - 21:00', '', '04377  55, Hangang-daero 23-gil, Yongsan-gu, Seoul  Hyundai I-Park Mall, Popcon D Square', 'Subway Line 4, Sinyongsan Station, Exit 2,  240m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=19474&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=19476&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=19477&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=19478&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=19479&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.52870670, 126.96321930, 'ENP025768', NULL, NULL),
	(237, 'Choonwondang Museum of Korean Medicine', 'https://english.visitseoul.net/attractions/Choonwondang-Museum-of-Korean-Medicine/ENP002637', 'The Choonwondang Museum of Korean Medicine first opened in 2008 and is dedicated to hanbang, also known as Oriental medicine. The museum spans 7 floors, from the B1 level to the 6th floor and there are exhibitions halls, a decocting room, a quality inspection facility, a cultural space, a doctor??s office and an infirmary. The museum\'s exhibition halls display various historical artifacts relating to Oriental medicine. Display pieces date from the Three Kingdoms era to the Joseon Dynasty. The museum is gaining popularity as a new cultural venue where people can learn about Korean culture and hanbang.', '-5597', 'Mondays-Fridays 09:00 - 18:00 (KST)\nSaturdays 09:00 - 13:00 (KST)', 'Closed Sundays & national holidays', '03139  27, Donhwamun-ro 9-gil, Jongno-gu, Seoul', 'Subway Lines 1/3/5, Jongno 3(sam)-ga Station  Exit 5,  186m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16319&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16320&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16321&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16322&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75418&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57159240, 126.99017340, 'ENP002637', NULL, NULL),
	(238, 'Heunginjimun Gate (Dongdaemun)', 'https://english.visitseoul.net/attractions/Heunginjimun-Gate/ENP001999', 'Heunginjimun Gate is a major historical site in Seoul. More commonly known as Dongdaemun Gate (Great Eastern Gate), it was designated treasure no. 1 by the Korean government. During the Joseon Dynasty, Heunginjimun Gate was one of eight city gates along the historic Seoul City Wall and it served as the main gate for the eastern part of the city. Heunginjimun is known for its exquisite architecture and beauty; the gate is also a spectacular sight at night. After viewing Heunginjimun, visitors may want to explore the Dongdaemun neighborhood and do some late-night shopping.', '-1063', 'Open 24 hours', '', '03119,  288, Jong-ro, Jongno-gu, Seoul)', 'Subway Lines 1/4  Dongdaemun Station  Exit 9,  74m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68287&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68288&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68289&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68290&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75277&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57089120, 127.01123220, 'ENP001999', NULL, NULL),
	(239, 'Hongjimun Gate and Tangchundaeseong Fortress', 'https://english.visitseoul.net/attractions/Hongjimun-Gate-and-Tangchundaeseong-Fortress/ENP004101', 'Tangchundaeseong Fortress was built in 1712 during the Joseon Dynasty to improve the defense of Hanyangdoseong, the Seoul City Wall, and the Bukhansanseong Fortress. Hongjimun Gate was built during the reign of King Sukjong, the 19th king of the Joseon Dynasty. Legend has it that King Sukjong wrote ??Hongjimun??on the gate\'s original name-board himself and the gate was called Hongjimun thereafter. After passing through Hongjimun Gate, Tangchundaeseong Fortress comes into view. These days, the Tangchundaeseong area offers one of the most beloved hiking trails in Seoul. The hiking trail has a gentle slope for leisurely walks.', '-40', 'Open 24 hours', '', '03021  212 Segeomjeong-ro, Jongno-gu, Seoul', 'subway line 3  Hongje Station  exit 1,   take the bus toward Sangmyung University, and get off in front of Sangmyung University.', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16353&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16354&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16355&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=16356&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75427&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.59901160, 126.95731820, 'ENP004101', NULL, NULL),
	(240, 'Changuimun Gate', 'https://english.visitseoul.net/attractions/Changuimun-Gate/ENP003266', 'Located in Buam-dong, Changuimun Gate is one of the four minor city gates of Seoul. It is also sometimes referred to as Bukmun (North Gate) or Jahamun. The gate was built by King Taejo, the first king of the Joseon Dynasty, when he constructed the fortifications surrounding the capital. In Korean history, Changuimun Gate is best known by Koreans as the gate that the rebellion faction used to enter Seoul in the Coup of 1623. A road was built to the west of the gate that accommodates traffic but Changuimun Gate itself is closed.', '-10574', '', '', '03020  118, Changuimun-ro, Jongno-gu, Seoul', 'subway line 3  Gyeongbokgung Station  exit 3,  take local bus 1020 or 7022, get off at Jahamun Pass/Yun Dong-ju Literature Museum, 51m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22976&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22977&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22978&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22979&fileTy=MEDIA&fileNo=1&thumbTy=L', 4, 37.59661490, 126.96776790, 'ENP003266', NULL, NULL),
	(241, 'Gyeongbokgung Palace', 'https://english.visitseoul.net/attractions/Gyeongbokgung/ENP000072', 'Gyeongbokgung Palace was the first and largest of the royal palaces built during the Joseon Dynasty. Built in 1395, Gyeongbokgung Palace was located at the heart of the newly appointed capital of Seoul (then known as Hanyang) and represented the sovereignty of the Joseon Dynasty. The largest of the Five Grand Palaces (the others being Gyeonghuigung Palace, Deoksugung Palace, Changgyeonggung Palace, Changdeokgung Palace), Gyeongbokgung served as the main palace of the Joseon Dynasty.                      The Korean government has invested much time and effort into rebuilding, restoring, and maintaining the palace for future generations. These efforts include work to rebuild and restore the buildings that were destroyed during the Japanese occupation. Visitors to Gyeongbokgung can also visit the National Palace Museum of Korea and the National Folk Museum of Korea as they are located on the palace grounds.                    To increase ease of accessibility from Gyeongbokgung Palace to Seochon and vice versa, the palace\'s western gate, Yeongchumun, was opened to the public on December 2018. For the past 43 years, there were only 3 entrances to Gyeongbokgung Palace - the southern gate Gwanghwamun, the northern gate Sinmumun, and the eastern entrance of National folk Museum of Korea. However, with the opening of the western gate Yeongchumun, entry to the palace from all directions has been now made possible.     Frequently Asked Questions about Gyeongbokgung Palace       When is Gyeongbokgung Palace closed?         Gyeongbokgung Palace is closed every Tuesday.If a public holiday and a closed day overlap, the doors will be opened. As a result, the first non-holiday following the open holiday will be the closed day. (As of 2025)         Can I visit Gyeongbokgung Palace for free if I wear a hanbok?         Yes, you can. You can enter Gyeongbokgung Palace for free if you wear a complete hanbok.Please refer to the guidelines regarding detailed hanbok regulations. (As of 2025)         How can I participate in the Gyeongbokgung Palace guided tour?         Groups of less than ten individuals can participate in the guided tour without reservation. Groups of 10 or more people need to make a reservation, and up to 30 people can participate in the tour. You can participate in the regular guided tour of Gyeongbokgung Palace without any reservations. During the tour, you\'ll hear the storyteller\'s narration as you explore the main pavilions of the palace. English tours are available daily at 11:00, 13:30, and 15:30 (except on Tuesdays.) (As of 2025)  Go to Gyeongbokgung Palace Management Office Guided Tour       { "@context": "https://schema.org", "@graph": [{ "@type": "FAQPage", "mainEntity": [{ "@type": "Question", "name": "When is Gyeongbokgung Palace closed?", "acceptedAnswer": { "@type": "Answer", "text": "<div>Gyeongbokgung Palace is closed every Tuesday. If a public holiday and a closed day overlap, the doors will be opened. As a result, the first non-holiday following the open holiday will be the closed day. (As of 2024)</div>" } }, { "@type": "Question", "name": "Can I visit Gyeongbokgung Palace for free if I wear a hanbok?", "acceptedAnswer": { "@type": "Answer", "text": "<div>Yes, you can. You can enter Gyeongbokgung Palace for free if you wear a complete hanbok. Please refer to the guidelines regarding detailed hanbok regulations. (As of 2024) <br><br>   <a href=\\"https://www.royalpalace.go.kr/content/guide/guide01_tab07.asp\\">Go to the hanbok guidelines.</a> </div>" } }, { "@type": "Question", "name": "How can I participate in the Gyeongbokgung Palace guided tour?", "acceptedAnswer": { "@type": "Answer", "text": "<div> Groups of less than ten individuals can participate in the guided tour without reservation. Groups of less than ten individuals can participate in the guided tour without reservation. Groups of 10 or more people need to make a reservation, and up to 30 people can participate in the tour. You can participate in the regular guided tour of Gyeongbokgung Palace without any reservations. During the tour, you\'ll hear the storyteller\'s narration as you explore the main pavilions of the palace. English tours are available daily at 11:00, 13:30, and 15:30 (except on Tuesdays.) (As of 2024) </div>" } }] }, { "@type": "LocalBusiness", "name": "Gyeongbokgung", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "10892" }, "review": { "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Leila M" }, "reviewBody": "Gyeongbokgung is a must-visit when in Seoul. This historic palace offers a fascinating glimpse into Korea\'s royal past, with its beautiful architecture, serene gardens, and rich history. The changing of the guard ceremony adds a unique cultural experience, and the palace grounds are perfect for a leisurely stroll. It\'s a place where history and beauty converge, making it a highlight of any trip to Seoul.", "datePublished": "2024-08-26" } }] }', '-7520', 'January & February: 09:00 - 17:00\nMarch - May: 09:00 - 18:00\nJune - August: 09:00 - 18:30 \nSeptember & October: 09:00 - 18:00\nNovember & December: 09:00 - 17:00\n*Last entry one hour before closing*', '', '03045  161, Sajik-ro, Jongno-gu, Seoul', 'Subway Line 5, Gwanghwamun Station, Exit 2,  471m\nSubway Line 3, Gyeongbokgung Station, Exit 5,  216m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65749&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65750&fileTy=MEDIA&fileNo=5&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=65751&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67732&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67733&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58084730, 126.97685150, 'ENP000072', NULL, NULL),
	(242, 'Sungnyemun Gate (Namdaemun)', 'https://english.visitseoul.net/attractions/Sungnyemun-Gate-Namdaemun-Gate/ENP022888', 'Sungnyemun Gate (Namdaemun) is one of Seoul\'s historic Four Great Gates and it was designated National Treasure no. 1 by the Korean government in 1962. Though its official name is Sungnyemun, it is also popularly known as Namdaemun Gate due to its location at what was once the southern end of Seoul. As the centuries passed, Seoul grew in size but Sungnyemun Gate has endured through the ages.         Construction on the gate was started in 1395 and completed in 1398. In 1447, Sungnyemun saw reconstruction work carried out. The gate is the largest city gate with an arched entrance in the city, and atop the gate\'s wooden base stands a 2-story wooden structure. The gate is Seoul\'s oldest wooden structure but on Feb. 10th, 2008, much of the gate\'s wooden structure was destroyed by fire. Following several years of restorative work, Sungnyemun Gate can now be enjoyed in all its glory.   ??,-9246,Tue-Sun 09:00-18:00,Monday,04528  40', ' Sejong-daero', ' Jung-gu', ' Seoul"', 'Subway Lines 1 / 4 / Gyeongui-Jungang Line/ Airport Railroad  Exit 4,  258m  \nSubway Line 4  Hoehyeon Station  Exit 5,  403m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68265&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68266&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68267&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73967&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73968&fileTy=MEDIA&fileNo=1&thumbTy=L', '5', 38, 99.99999999, 0.00000000, 'ENP022888', NULL, NULL),
	(243, 'Gyeongbokgung Stonewall Walkway', 'https://english.visitseoul.net/attractions/2024-gbgstonewall/ENPldz98j', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The Gyeongbokgung Stonewall Walkway is a walkway that surrounds Gyeongbokgung Palace. Centered around Gwanghwamun, to the left is the west gate of Gyeongbokgung, Yeongchumun; to the north is the north gate, Sinmumun; and to the right is the east gate, Geonchunmun. The left side of the Gyeongbokgung Stonewall Walkway connects to Seochon, while the north connects to the Blue House. The right side leads to Bukchon and Samcheong-dong, where visitors can also explore the National Museum of Modern and Contemporary Art and the National Folk Museum of Korea. The path is well-maintained, perfect for a stroll while experiencing the changing seasons. Walking along the Gyeongbokgung Stonewall Walkway offers a unique view that changes with the weather, whether it\'s raining or snowing.', '', '', '', '03045  161 Sajik-ro, Jongno-gu, Seoul', 'Subway Line 3, Gyeongbokgung Station, Exit 4, 430m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67939&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67940&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67941&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67942&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73580&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58084730, 126.97685150, 'ENPldz98j', NULL, NULL),
	(244, 'Changdeokgung Secret Garden', 'https://english.visitseoul.net/attractions/2024-cdggarden/ENPl8f5md', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The Secret Garden (Huwon) at Changdeokgung Palace, once used for royal entertainment and ceremonies, is a significant heritage site showcasing traditional landscaping. Covering around 446,943 square meters, this expansive royal garden still has restricted areas that remain inaccessible to the public. Historically, it was off-limits to commoners, reserved only for the Joseon royal family. Nestled against Maebong Peak of Bugaksan Mountain, the garden features several ponds, including Buyongji, home to Buyongjeong Pavilion, Aeryeonji, Jangbangji, and Banwolji. The arrangement of pavilions and buildings reflects traditional Korean architecture, demonstrating a masterful harmony between structures and nature.', '-5888', 'Korean\n- November to February: 10:00 ??15:00 (entry every hour)\n- March to October: 10:00 ??16:00 (entry every hour)\n\nEnglish\n- December to February: 10:30 / 11:30 / 14:3\n- March to November: 10:30 / 11:30 / 14:30 / 15:30\n\nJapanese\n- January to December: 13:30 (operates every Wednesday, Friday, and Sunday)\n\nChinese\n- January to December: 12:30 (operates every Tuesday, Thursday, and Saturday)\n\n*Admission is limited to 100 people per session by language (50 online reservations + 50 on-site ticketing).\n*Korean visitors are not allowed to enter the garden during foreign language tours except when accompanied by up to two foreign visitors.', 'Closed Mondays. (If the regular closure day falls on a public holiday or substitute holiday, the site will remain open, and the next non-holiday will be the regular closure day.)', '03072  99 Yulgok-ro, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 3,  389m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67916&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67917&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67918&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67919&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67920&fileTy=MEDIA&fileNo=3&thumbTy=L', 5, 37.58111610, 126.99279160, 'ENPl8f5md', NULL, NULL),
	(245, 'Gyeonghuigung Palace', 'https://english.visitseoul.net/attractions/Gyeonghuigung/ENP001159', 'One of the five grand palaces, Gyeonghuigung Palace was also called "Seogweol" (which means "palace of the west") because it\'s located west of the main palace, Gyeongbokgung. In its heyday, it was part of a vast complex, with 100 buildings in total, but most of these were destroyed during the Japanese occupation. Following intensive restoration work, it reopened to the public in 2002. On its grounds stand the Seoul Museum of History and the Gyeonghuigung Annex Building of the Seoul Museum of Art.    The palace was originally constructed by order of King Gwanghae, the fifteenth king of the Joseon Dynasty, and was completed in 1623. From the beginning, it was much-loved and served as a secondary palace for some ten kings of the Joseon Dynasty.     A variety of Korean art can also be seen in the Gyeonghuigung Annex building of the Seoul Museum of Art, which is situated on the Gyeonghuigung site. Also, the Seoul Museum of History, one of the foremost tourist attractions in the city, houses a permanent collection allowing visitors to see how Seoul has developed and transformed from prehistoric times to the present day.', '-918', 'Daily 09:00 - 18:00 KST *Closed Mondays*', 'January 1st', '03177  45, Saemunan-ro, Jongno-gu, Seoul', 'Subway Line 5  Gwanghwamun Station  Exit 1,  875m \nSubway Line 5  Seodaemun Station  Exit 4,  639m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68254&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68255&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68256&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68257&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68258&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57146560, 126.96841650, 'ENP001159', NULL, NULL),
	(246, '7th Royal Culture Festival', 'https://english.visitseoul.net/attractions/7thRoyalCultureFestival/ENP036912', 'This year\'s 7th Royal Culture Festival is slated to take place from May 1 (Saturday) to May 9 (Sunday) both on and offline! The festival will take place with several infamous sights set as the background, including Gyeongbokgung Palace, Changdeokgung Palace, Deoksugung Palace, Changgyeonggung Palace, Gyeonghuigung Palace, Jongmyo Shrine, and the Sajikdan Altar. Several culture and arts programming is in store, ranging from on and offline performances utilizing the aesthetic and historical significance of these sites, as well as exhibitions, experiential programs, ceremonial rituals, and more!Festival programming includes the following:An opening ceremony, palaces loved by artists, online children\'s royal culture festival, palace photo contest, royal guard exchange ceremony, saenggwabang, and other programs inclusive of the palace areas.', '-7814', '', '', '03045  161, Sajik-ro, Jongno-gu, Seoul', '* Subway Line 3, Gyeongbokgung Station* Subway Line 5, Gwanghwamun Station', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=39987&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=39988&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=39989&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=39990&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=39991&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.58084730, 126.97685150, 'ENP036912', NULL, NULL),
	(247, 'Deoksugung Palace', 'https://english.visitseoul.net/attractions/Deoksugung-Palace/ENP002046', 'Deoksugung Palace is unique among Korean palaces in having a modern seal engraving and a western style garden and fountain. Medieval and modern style architecture exists together in harmony in Deoksugung Palace. The Changing of the Royal Guard can be seen in front of Daehanmun (Gate) and is a very popular event for many visitors. During the Joseon Dynasty, the royal guard was responsible for opening and closing the palace gate as well as patrolling around the gate area. Outside the palace is a picturesque road flanked by a stone wall which is much loved by visitors.   Originally, Deoksugung Palace was not a palace. The Imjin War (the Japanese invasions in 1592) left all the palaces in Korea severely damaged. When King Seonjo (the fourteenth king of the Joseon Dynasty) returned to Seoul from his evacuation, the primary palace Gyeongbokgung Palace had been burnt to the ground and other palaces were also heavily damaged. A temporary palace was chosen from among the houses of the royal family. This is the origin of Deoksugung Palace. King Gwanghaegun (the fifteenth king of the Joseon Dynasty) named the palace Gyeongungung, formalizing it as a royal palace. Since then it has been used as an auxiliary palace by many Joseon kings. In 1897, Emperor Gojong (the twenty-sixth king of the Joseon Dynasty) stayed here and expanded it. The modern buildings such as Seokjojeon (Hall) were constructed during this period. In 1907, the palace was renamed Deoksugung.', '-10642', 'Daily 9:00 - 21:00 (Last entry 20:00)', 'Closed Mondays', '100-120  99 Sejong-daero, Jung-gu, Seoul', 'Subway Line 1/2 City Hall Station  Exit 1,  72m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67606&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67607&fileTy=MEDIA&fileNo=3&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67608&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67609&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=67610&fileTy=MEDIA&fileNo=2&thumbTy=L', 5, 37.56593600, 126.97503540, 'ENP002046', NULL, NULL),
	(248, 'Unhyeongung Palace', 'https://english.visitseoul.net/attractions/UnhyeongungPalace/ENP000471', 'Unhyeongung Palace is one of Seoul\'s smaller palaces and it is an important historic site that is open to the public. The palace was formerly the private residence of Emperor Gojong\'s father, the prince regent Heungseon Daewongun. The young Gojong lived here before he assumed the throne and his wedding to Myeongseong took place here. An annual re-enactment of the royal wedding ceremony between Emperor Gojong and Empress Myeongseong takes place here at the palace.      During the reign of Emperor Gojong, Unhyeongung was as grand as any other palace in Seoul, but over time, many of the palace buildings were heavily damaged and destroyed. Today, visitors can see what has been preserved of the palace and take part in traditional cultural activities and crafts experiences. On weekends, visitors can watch Seoulites get married in traditional Korean wedding ceremonies at the palace.', '-9776', 'Daily 09:00 - 19:00 KST (Last entry 18:30 KST ) *Closed Mondays*', 'Closed Mondays \n* Open on Mondays falling on public holidays', '03131  464, Samil-daero, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 4,  103m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68420&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68421&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68423&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68424&fileTy=MEDIA&fileNo=3&thumbTy=L', 4, 37.57639680, 126.98866560, 'ENP000471', NULL, NULL),
	(249, 'Changgyeonggung Palace', 'https://english.visitseoul.net/attractions/Changgyeonggung-Palace/ENP000297', 'Changgyeonggung Palace was built in 1483 by King Seongjong (the ninth king of the Joseon Dynasty) to take care of the wives of the preceding kings. Compared to other palaces, the size of the palace is compact and simple. Changgyeonggung Palaceis connected with Changdeokgung Palace. It\'s located east of the primary palace of Gyeongbokgung, so it is also referred to as "Donggwol," the "East Palace."Myeongjeongjeon is the main hall of the palace, where state affairs were held, such as meetings with officials and the reception of foreign envoys. In particular, Myeongjeongjeon represents an outstanding example of seventeenth century Joseon architectural style and is the oldest main hall of any palace. While visiting Changgyeonggung Palace, it is recommended you visit nearby Changdeokgung Palace as well.Most of the palace buildings were destroyed by the Japanese during the Japanese invasion of Korea in 1592. The main buildings such as Myeongjeongjeon, Munjeongjeon (council hall), Hwangyeongjeon (Hall), Inyangjeon (Hall), Gongsacheong, and Honghwamun (Gate) were rebuilt by King Gwanghaegun (the fifteenth king of the Joseon Dynasty). During the Japanese occupation, the Japanese built a zoo on the site and renamed the palace "Changgyeongwon," meaning "Changgyeong Garden." Since 1987, the palace has been reconstructed and now resembles its original form. { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Changgyeonggung Palace", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "765" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "MyNeoAj" }, "reviewBody": "I would recommend you to renting a hanbok before come here,It\'s a good experience you should do. Take a picture with the palace and Royal guard. Don\'t miss to see the Palace Royal Guard Changing Ceremony too.", "datePublished": "2022-11-25" }] }', '-5550', 'Daily 09:00 - 21:00 (Last entry at 20:00)', 'Closed Mondays', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul', 'Subway Line 4  Hyehwa Station  Exit 4,  779m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68030&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68031&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68032&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68033&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68034&fileTy=MEDIA&fileNo=3&thumbTy=L', 5, 37.58111610, 126.99279160, 'ENP000297', NULL, NULL),
	(250, 'Hyehwamun Gate', 'https://english.visitseoul.net/attractions/Hyehwamun-Gate/ENP023606', 'Hyehwamun Gate is one of Seoul\'s 4 minor city gates. It was built in 1397 along the famed Hanyangdoseong, Seoul City Wall along the Joseon-era eastern boundary of the city. Hyehwamun Gate was also known as Dongsomun Gate (Minor East Gate). Today, it is easily accessible on foot and it is a picturesque and historic Seoul attraction.', '-40', '', '', '03076  307, Changgyeonggung-ro, Jongno-gu, Seoul', 'Subway Line 4  Hansung University Station  Exit 5,  192m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22964&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22965&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22966&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22967&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22968&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22969&fileTy=MEDIA&fileNo=1&thumbTy=L', 6, 37.58776700, 127.00177900, 'ENP023606', NULL, NULL),
	(251, 'Hanyangdoseong (Seoul City Wall)', 'https://english.visitseoul.net/attractions/Seoul-City-Wall/ENP000090', 'The Seoul City Wall was originally built in 1396, surrounding Seoul (then known as  Hanyang) during the Joseon Dynasty (1392-1897). The wall stretches for 18.6km along the ranges of Bugaksan Mountain, Naksan Mountain, Namsan Mountain, and Inwangsan Mountain. The wall stands at average heights of 7 - 8 m high. Along the Seoul City Wall, there once stood eight gates that were originally built between 1396-1398, but only six remain standing. The North, South, East, and West gates of the wall are known as the ??Four Great Gates??(Sukjeongmun, Heunginjimun, Sungnyemun, Dongeuimun), while the Northwest, Northeast, Southwest, and Southwest gates are known as the ??Four Minor Gates??(Changuimun, Hyehwamun, Gwanghuimun, Soeuimun).        {  "@context": "https://schema.org",  "@type": "FAQPage",  "mainEntity": [{    "@type": "Question",    "name": "How long is the Seoul City Wall in kilometers?",    "acceptedAnswer": {      "@type": "Answer",      "text": "<div> The total length of the Seoul City Wall is 18.6 km. There are four main and four small gates, consisting of a total of 6 sections. </div>"    }  },{    "@type": "Question",    "name": "Is there a commentary program for the Seoul City Wall?",    "acceptedAnswer": {      "@type": "Answer",      "text": "<div> Yes, commentary programs are available and you can listen to various stories while walking. Each program has different times, routes, and reservation methods, so please check the website below for details.<br><br> <a href=\\"https://seoulcitywall.seoul.go.kr/content/131.do\\"style=\\"color:#0000EE;text-decoration:underline\\">Seoul City Wall Commentary Program Information</a> </div>"    }  },{    "@type": "Question",    "name": "I am curious about the procedure of getting the Seoul City Wall certificate of completion.",    "acceptedAnswer": {      "@type": "Answer",      "text": "<div> The procedure for getting the Seoul City Wall completion certificate is as follows. \'Get the map ??put the stamp ??take a certified photo ??apply for issuance ??validate the visit\'. Detailed step-by-step details can be found on the website below.<br><br> <a href=\\"https://seoulcitywall.seoul.go.kr/content/132.do\\"style=\\"color:#0000EE;text-decoration:underline\\">Guide to Issuing Certificate of Completion</a> </div>"    }  },{  "@type": "LocalBusiness",  "name": "Seoul City Wall",  "aggregateRating": {    "@type": "AggregateRating",    "ratingValue": "4.5",    "ratingCount": "174"  },  "review": {    "@type": "Review",    "reviewRating": {      "@type": "Rating",      "ratingValue": "5"    },    "author": {      "@type": "Person",      "name": "Gombung"    },    "reviewBody": "Nice fortress in the middle of a city!    The fortress itself is just okay.    But the specail thing is that it is inside the city circumsized with bulding forests.    Don\'t forget to visit and have a walk here.",    "datePublished": "2022-06-26"  }}]}', '-40', '', '', '03038  283, Yulgok-ro, Jongno-gu, Seoul (Jongno 6-ga, Seoul Design Support Center)', 'Subway Lines 1 / 4  Dongdaemun Station  Exit 1,  287m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68354&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68355&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68356&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68357&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68358&fileTy=MEDIA&fileNo=3&thumbTy=L', 5, 37.57195080, 127.00767980, 'ENP000090', NULL, NULL),
	(252, 'Changdeokgung Palace', 'https://english.visitseoul.net/attractions/Changdeokgung-Palace/ENP000295', 'Changdeokgung Palace is the second UNESCO World Heritage Site in Seoul. It was selected as a representative palace for its notable beauty in the history of palace architecture in East Asia and for its excellent arrangement with the surrounding naturalenvironment. Changdeokgung Palace was built by King Taejong in 1405.   During the Imjin War, Joseon lost both Gyeongbokgung Palace and Changdeokgung Palace. Reconstructed in the 2nd year of Gwanghaegun (1610), Changdeokgung was used as the royal palace of Joseon for about 270 years.    Changdeokgung Palace has two major tour programs. The first is the general tour, which is a basic tour that covers Injeongjeon (仁政???, the main hall, and Nakseonjae (樂善???. The second is a special tour of Howon, which runs from Buyongji, the entrance toHowon, to Okryucheon. The conservation of the ecosystem is absolutely stunning and includes various ponds and gardens.   { "@context": "https://schema.org", "@type": "LocalBusiness", "name": "Changdeokgung Palace", "aggregateRating": { "@type": "AggregateRating", "ratingValue": "4.5", "ratingCount": "4692" }, "review": [{ "@type": "Review", "reviewRating": { "@type": "Rating", "ratingValue": "5" }, "author": { "@type": "Person", "name": "Arielle P" }, "reviewBody": "I love the secret garden and it makes a really unique trip and special memories. We always love to visit in the fall!! The ginkgo trees are remarkable.", "datePublished": "2024-08-29" }] }', '-5888', 'February - May, 09:00 - 18:00 (Last entry at 17:00)\nJune - August, 09:00 - 18:30 (Last entry at 17:30)\nSeptember - October, 09:00 - 18:00 (Last entry at 17:00)\nNovember - January, 09:00 - 17:30 (Last entry at 16:30)', 'Closed Mondays', '03072  2-71, Waryong-dong, Jongno-gu, Seoul', 'Subway Line 3  Anguk Station  Exit 3,  389m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66705&fileTy=MEDIA&fileNo=7&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66706&fileTy=MEDIA&fileNo=6&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66707&fileTy=MEDIA&fileNo=4&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66708&fileTy=MEDIA&fileNo=5&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=66709&fileTy=MEDIA&fileNo=4&thumbTy=L', 5, 37.58111610, 126.99279160, 'ENP000295', NULL, NULL),
	(253, 'Chundangji Pond', 'https://english.visitseoul.net/attractions/Chundangji-Pond/ENP039629', 'On the rear garden grounds of Changgyeonggung Palace sits Chundangji Pond. It is known for its beautiful nature and fall foliage. Chundangji consists of two parts. The smaller upper half is the original location of the pond, while the lower half was initially used as a naenongpo , a place for the royal court to experiment with planting crops such as rice. However, during the Japanese occupation in 1909, the naenongpo was converted into a pond. In 1986, it was renovated into a traditional Korean style. Visitors can also see the seven-story pagoda, made in 1470, sitting on the shore of the pond.', '-5550', 'Daily 09:00 - 21:00 (Last entry at 20:00)', 'Every Monday (if the closed day falls on a public holiday, it will be closed the following day)', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul, Korea (??룡동, 창경???', 'Subway Line 4  Hyehwa Station  Exit 4,  994m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=48411&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=48412&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=48413&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75415&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=75416&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57881490, 126.99492980, 'ENP039629', NULL, NULL),
	(254, 'Gwanghuimun Gate', 'https://english.visitseoul.net/attractions/Gwanghuimun-Gate/ENP023605', 'Gwanghuimun Gate is one of the Seoul\'s 4 minor city gates. It is located along the southeastern boundary of Joseon-era Seoul. It was known by two other names throughout history, Sugumun Gate and Sigumun Gate. In 1719, it was officially named Gwanghuimun Gate and its name has been the same ever since. In 1975, the gate underwent successful restoration work. Visitors can stop by and see the gate as it is located near the modern Seoul landmark, Dongdaemun History and Culture Park.', '-9171', '', '', '04612  350 Toegye-ro, Jung-gu, Seoul', 'Subway Lines 2/4/5  Dongdaemun History and Culture Park Station   Exit 3,  143m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22959&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22960&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22961&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22962&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=22963&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.56403680, 127.01230620, 'ENP023605', NULL, NULL),
	(255, 'Grand Greenhouse Changgyeonggung Palace', 'https://english.visitseoul.net/attractions/GrandGreenhouseChanggyeonggungPalace/ENP037176', 'Changgyeonggung Palace, one of the four main historical palaces in Seoul, houses a greenhouse built in 1909. It is Korea\'s first greenhouse designed in a Western architectural style. Initially, there was a botanical garden and a zoo. In 2004, the building was restored, retaining the original appearance of the greenhouse, and is open to the public. Here you will find different types of plants, both local and imported from other countries.', '-10197', '09:00 - 20:45', 'Mondays', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul, Korea (창경???', 'Subway Line 4  Hyehwa Station  Exit 4,  779m', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40391&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40393&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=40555&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74820&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=74821&fileTy=MEDIA&fileNo=1&thumbTy=L', 5, 37.57881490, 126.99492980, 'ENP037176', NULL, NULL);
INSERT INTO `attraction_kcontents_data` (`attr_id`, `title`, `address`, `url`, `description`, `hours_of_operation`, `holidays`, `transportation`, `latitude`, `longitude`, `keyword`, `drama_name_en_list`, `drama_image`, `image_count`) VALUES
	(1, '63 Square', '07345  50, 63-ro, Yeongdeungpo-gu, Seoul, Korea', 'https://english.visitseoul.net/attractions/63-Square/ENP000210', 'The 63 Square skyscraper is a Yeouido landmark commanding spectacular views of the city. Standing 249 meters (817 ft) high and comprising of 60 floors and three basement levels, 63 Square is one of Korea??s tallest and most recognized buildings. The glass elevators which serve the viewing observatory ascend at a speed of 460 meters per minute, taking just 25 seconds to reach the top, giving passengers the sensation of a rocket-powered take-off as they enjoy breathtaking views. Aqua Planet 63, a major tourist attraction within 63 Square, ceased operations on June 30, 2024. Additionally, the observatory ??3 Art,??where visitors could enjoy views of Seoul and art pieces, also ceased operations on the same day. In 2025, the Centre Pompidou Hanwha Seoul is scheduled to open in 63 Square.', 'Temporarily closed', 'Temporarily closed', 'Subway Line 9/Sillim Line  Saetgang Station  Exit 3,  1.2km', 37.5189342, 126.9384617, '별에서 온 그대', 'My Love from the Star', NULL, 4),
	(2, 'Seoul Plaza', '100-101  110, Sejong-daero, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Plaza/ENP001538', 'Seoul Plaza refers to the square located in front of Seoul City Hall, which used to be widely used as a location for public rallies, protests, and events. In 2002 the roadway was completely transformed and grassed over, and the current lively Seoul Plaza with its artwork and culture was inaugurated in 2004. The plaza features a refreshing fountain in the summer and an outdoor ice rink in the winter.', NULL, NULL, 'Subway Line 1 /2  City Hall Station  Exit 5,  89m', 37.5665851, 126.9782038, NULL, 'City Hunter', NULL, 5),
	(3, 'Malli-dong', '04528  Manrijae-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Mallidong/ENP037156', 'The Malli-dong neighborhood, located near Seoul Station, has been gaining popularity ever since the opening of Seoullo 7071, a sky garden and pedestrian road. This historic district of Seoul is home to a variety of restaurants with delectable food and trendy coffee shops. This area dates back to the state of Joseon, so the locals associate it with the history of the city.', NULL, NULL, 'Subway Lines 1/4/Airport Railroad/Gyeongui-Jungang Line/GTX  Seoul Station  Exit 15, 300m', 37.5588758, 126.9759039, 'dramabackground', NULL, NULL, 3),
	(4, 'Seochon Hanok Village', '03037  45, Pilwoon-daero, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/SeochonHanokVillage/ENPhyd9ee', 'To the west of Gyeongbokgung Palace is a village where various middle-class officials such as court nobles and government officials lived during the Joseon Dynasty. This neighborhood has long been guarded by old shops and hanok houses, along with newly emerged stores, creating a harmonious blend of unique charm and simplicity that can be felt.', NULL, NULL, 'Subway Line 3  Gyeongbokgung Station  Exit 2,  617m', 37.5802493, 126.9673793, NULL, 'Personal Taste', NULL, 5),
	(5, 'Ikseon-dong Hanok Village', '03133  17, Donhwamun-ro 11ga-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/IkseongdongHanokVillage/ENP037008', 'The Ikseon-dong Hanok Village spans a length of around 801 m, connecting Ibis Ambassador, Insadong, and Nakwon Sanga, or Nakwon Music Market, and is home to all kinds of fusion-concept cafes, restaurants, and shops that contrast with the more traditional vibe of the neighboring Insadong area. In fact, it\'s one of the most popular sights for dating in the city! Despite the relatively narrow alleyways of the village, you are in for a treat during the winter season or night hours with the quaint, yet striking scenery all around.     ', NULL, NULL, 'Subway Lines 1 / 3 / 5, Jongno 3-ga Station, Exit 4,  141m', 37.5733903, 126.9897725, NULL, 'Do Do Sol Sol La La Sol"', NULL, 5),
	(6, 'Night Views at Banpodaegyo Bridge', '2085-14, Olympic-daero, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Night-Views-at-Banpodaegyo-Bridge/ENP016325', 'Banpodaegyo Bridge is a two level bridge that crosses the Hangang River. The Moonlight Rainbow Fountain display takes place at this bridge and it\'s often possible to see fireworks here as well. The area is a popular date spot and the view at night is beautiful. Bask in the atmosphere and the views of the Hangang River at Banpodaegyo Bridge.', NULL, NULL, 'Subway Lines 3/7/9  Express Bus Terminal Station  Exit 8-1,  850m', 37.5119827, 126.9934223, NULL, 'My Love from the Star', NULL, 4),
	(7, 'ParkNoSoo Museum', '03034  34, Ogin 1-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/ParkNoSoo-Museum/ENP042350', 'Pro-Japanesepolitician Yoon Deok-young built the house for his daughter in 1937, whichlater became painter Park No-soo??s house in 1973. Park No-soo, who devotedhimself to art over the 40 years he lived in this house, donated it back tosociety along with his artwork. The historical residence was reborn as an artmuseum in 2013 through the Jongno Cultural Foundation.  Despiteits long history of 80 years, this well-maintained building was recognized forits cultural value and was registered Cultural Heritage Material No. 1 of Seoulin 1991.', 'Daily 10:00 ~ 18:00', 'Closed Mondays', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  870m', 37.5813669, 126.9667492, NULL, 'Specific dramas are not widely known to have been filmed here, but it serves as a beautiful backdrop for art and culture-themed scenes.', NULL, 5),
	(8, 'Sungkyunkwan University', '03063  25-2, Sungkyunkwan-ro (Sungkyunkwan Univ.), Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Sungkyunkwan-University/ENP019656', 'Sungkyunkwan University was founded in 1398 and it is the oldest university in Asia. The university was founded by the first king of the Joseon Dynasty, King Taejo of Joseon. Sungkyunkwan University has two campuses, one located in Seoul and the other in the city of Suwon. The Seoul campus is located near Hyehwa Station and visitors can see historical buildings that date back to the Joseon era.', NULL, NULL, 'Subway Line 4  Hyehwa Station  Exit 4,  1.2km', 37.588227, 126.993606, NULL, 'Sungkyunkwan Scandal', NULL, 5),
	(9, 'Namsan Cable Car', '04630  83, Sopa-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Namsan-Cable-Car/ENP035015', 'The Namsan Cable Car is the most convenient and fun way to reach the summit of Namsan Mountain! In just a three-minute ride, you can reach the mountain peak up near the N Seoul Tower all the while enjoying a fantastic overlook of downtown Seoul. Not only can you experience the breathtaking view of the autumn foliage in the fall and snow-covered mountainside in the winter, but you can even catch a gorgeous aerial view of the city at night. Near the parking lot of the cable car, the surrounding neighborhood has a great selection of popular restaurants offering tasty menu items from tonkatsu (breaded pork cutlet) to vegetarian bibimbap and more! The 140-meter long Namsan outdoor elevator, Namsam Ormi, is also available for easy access to the cable car platform!', 'Daily 10:00 - 23:00 KST', NULL, 'Subway Line 4  Myeongdong Station  Exit 4,  571m', 37.5577327, 126.9849633, NULL, 'Boys Over Flowers', NULL, 3),
	(10, 'Bugak Skyway Octagonal Pavilion', '03010  267, Bugaksan-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/BugakSkywayPavilion/ENP011117', 'Bugak Skyway, which runs along the northeast ridge of Bugaksan (Mt.), has become known as the most beautiful driving route in Korea ever since it opened in September of 1968. The road is forested by thick greenery and leads to an octagonal pavilion (Palgakjeong) located at the top of the mountain, allowing visitors to appreciate a panoramic view of the whole city of Seoul. Ever since Palgakjeong and the surrounding areas underwent renovation and re-opened in April 2010, Bugak Skyway has grown to become a must for local residents and tourists alike. Palgakjeong is located at an elevation of 342 m, allowing visitors to appreciate not only the beauty of mother nature but also a panoramic view of the entire city. Visitors can enjoy a traditional plaza, a pagoda resting area, a wildflower garden and walking trails.     ', NULL, NULL, 'Subway Line 4  Hansung University Station  Exit 6,  take bus 1112 or 1111, get off at Seoul Dawon School or Han Yong-un Activity Center, 2.3 km.', 37.6069015, 126.9771509, NULL, 'Often used in dramas for its panoramic views of Seoul, providing a romantic and scenic backdrop.', NULL, 5),
	(11, 'Digital Media City', '366, World Cup buk-ro, Mapo-gu, Seoul', 'https://english.visitseoul.net/attractions/Digital-Media-City/ENP011142', 'Digital Media City (DMC) is an IT and media industry cluster located in Mapo-gu, housing numerous headquarters of major domestic corporations. Currently, it hosts the three major terrestrial broadcasters KBS, MBC, and SBS, along with cable channels like YTN, Channel A, and JTBC, and newspapers such as Dong-A Ilbo and JoongAng Ilbo. Additionally, the Korean Film Archive, the nation\'s only film archive equipped with Korean movie films and related materials, is located there. This makes DMC a hub for the production of Hallyu content. Furthermore, the area is surrounded by various renowned restaurants, making it a recommended tourist destination for those interested in K-media. ', NULL, NULL, 'Subway Line 6/Gyeongui-Jungang Line/Airport Railroad, Digital Media City Station, Exit 9, 520', 37.5777306, 126.8921152, NULL, 'My Love from the Star', NULL, 4),
	(12, 'Banpodaegyo Bridge Moonlight Rainbow Fountain', '06500  Banpo-dong, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Banpodaegyo-Bridge-Moonlight-Rainbow-Fountain/ENP002220', 'Banpodaegyo Bridge is a two-tiered bridge over the Han River that features the Moonlight Rainbow Fountain, (the world??s longest bridge fountain recognized by the Guinness Book of World Records) with 380 water jets and a dazzling array of multi-colored lights. The Moonlight Rainbow Fountain??s water jets are dynamic and can move in time to music creating spectacular ever-changing displays. Add to that the hundreds of rainbow-colored lighting combinations when night falls, and it is easy to see why Banpodaegyo Bridge is a magnet for tourists year round.   The Moonlight Rainbow Fountain operates from April to October every year, however the schedule of the fountain shows varies from month to month. ', '* Off Season [April - June & September - October]\n12:00, 19:30, 20:00, 20:30, 21:00 (20 mins)\n* Peak Season [July - August]\n12:00, 19:30, 20:00, 20:30, 21:00, 21:30 (20 mins)', NULL, 'Subway Lines 3/7/9  Express Bus Terminal Station  Exit 8-1,  1.1km', 37.5085863, 126.9902641, NULL, 'My Love from the Star', NULL, 3),
	(13, 'Jahamun Tunnel', '03022  219, Jahamun-ro, Jongno-gu, Seoul, Korea (Buam-dong)', 'https://english.visitseoul.net/attractions/Jahamun-Tunnel/ENP037158', 'Jahamun Tunnel is a tunnel connecting Cheongdong and Buam-dong in Seoul, and was featured as a filming site for the movie "Parasite." In the movie, this is where Ki-taek and his family pass through in the pouring rain. This small scene has caused Jahamun Tunnel to attract countless tourists and movie fans.', NULL, NULL, 'Subway Line 3 Gyeongbokgung Station Exit 3, take bus number 1020, 7022, or 7212, and get off at Buam Community Center,  650m', 37.591147, 126.9621099, NULL, 'Parasite', NULL, 5),
	(14, 'Seoullo 7017', '04509  432, Cheongpa-ro, Jung-gu, Seoul   (Bongnae-dong 2-ga, KORAIL Seoul Headquarters)', 'https://english.visitseoul.net/attractions/Seoullo-7017/ENP023496', 'Seoullo 7017 is an elevated sky garden that is a popular walking destination and tourist spot in the center of Seoul. Originally a highway overpass, it has since been transformed into a pedestrian walkway for the general public to enjoy. Seoullo\'s name is a nod to its original foundation in 1970 and its rebirth in 2017 as a sky garden. There are also 17 pedestrian pathways that allow visitors to walk through several local communities. Seoullo 7017 offers several rest areas, greenery, and cultural experiences at 1 kilometer above street-level.', 'Open 24 hours', 'Open year round', 'Subway Line 1/4/Gyeongui-Jungang Line/AREX, Seoul Station  Exits Exit 7,  148m', 37.5576741, 126.9697405, NULL, NULL, NULL, 5),
	(15, 'ChoiManLin Museum', '02708  23, Solsaem-ro 7-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/ChoiManLin-Museum/ENP042352', 'Theelegant two-story, Western-style building was built in the 1970s. Here,sculptor Choi Man Lin created his world of art for about 30 years from 1988. Evenwith all its traces of artistry intact, it eventually grew to become the ChoiMan Lin Museum with the help of the Seongbuk-gu District and EMA Architects. Reborn as an art museum in2019, this building contains the traces of sculptor Choi Man Lin, which werepreserved through a remodeling method that protects the appearance of theexisting building as much as possible. Thisbuilding, which shows off its architectural beauty while maximizing itsfunction as an art museum, won the Excellence Award at the 2020 Public BuildingAwards of Korea.', 'Daily 10:00 ~ 18:00\nClosed for exhibition preparation (July 1 - September 3)', 'Closed Sundays & Mondays', 'Subway Uisinseol   Bukhansanbogukmun Station Exit 2,  438m', 37.6106735, 127.0043219, NULL, NULL, NULL, 5),
	(16, 'Myeongdong Jaemi-ro', '04631  24, Toegye-ro 20-gil, Jung-gu, Seoul, Republic of Korea', 'https://english.visitseoul.net/attractions/2024-jaemiro/ENPhvgb2b', 'It\'s a themed street stretching approximately 450m from Exit 3 of Myeongdong Station to the former Seoul Animation Center, adorned with Korean comics, animations, characters, illustrations, and other content. Jaemi-ro, connecting the iconic tourist spots of Seoul, Myeongdong, and Namsan Mountain, offers a valuable experience where visitors can enjoy diverse cultural experiences within the heart of Seoul\'s downtown area.', NULL, NULL, 'Subway Line 3  Myeongdong Station  Exit 3,  196m', 37.5592279, 126.9855828, NULL, 'K-POP DEMON HUNTERS', NULL, 4),
	(17, 'Kim Joong-up House of Architectural Culture', '02755  11, Jangwi-ro 21na-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Kim-Joong-up-House-of-Architectural-Culture/ENP042446', 'Built in the 1970s, this two-story detached house was remodeled in 1986 by Kim Joong-up, who added exotic elements to every corner of the house based on traditional Korean architecture. This is a place where you can get a glimpse of the housing culture of the middle class at the time, and was designated as a Seoul Future Heritage in 2017. The KimJoong-up House of Architectural Culture harmoniously integrates Korean and Western architectural styles. The second-floor living room has an umul-maru, rafter structure, and windows covered with changhoji paper, which are mainly used in hanok, but with a modern interpretation. In contrast, the bathroom was designed in a European style. The dry bathroom with a dressing room attached, something that wasn??t common in Korea during the \'70s and \'80s, has a vintage jade-colored interior that stands out. Stepping out to the elegantly decorated garden, a water element, a characteristic of Kim Joong-up\'s architecture, is located on one side of the yard. Even equipped with its own small greenhouse, the Kim Joong-up House of Architectural Culture contains immense nature in the garden.', 'Daily 10:00 ~ 17:00', 'Closed Sundays & Mondays', 'Subway Line 6, Dolgoji Station, Exit 2,  1.5km', 37.6149824, 127.0440877, NULL, NULL, NULL, 5),
	(18, 'Night Views at Haneul Park', '03900  95, Haneulgongwon-ro, Mapo-gu, Seoul', 'https://english.visitseoul.net/attractions/NightViewsatHaneulPark/ENP016322', 'Of the five parks within the World Cup Park system in Mapo-gu, Haneul Park is the most beloved and popular. Haneul is the Korean word for "sky" and the park was dubbed Haneul Park because it has the highest elevation of the five parks. The area was once a landfill, but the park was subsequently transformed into an ecological park. Haneul Park is famous for its fields of tall pampas grass, sunset views, and night views of Seoul. The park is also popular as a date spot and as a location for photo shoots.', 'Daily, 05:00 to 20:30\n* For more details, please refer to our website', NULL, 'Subway Line 6  World Cup Stadium Station  Exit 1,  803m to the Toad Train Ticket Office. \nSubway Line 6  World Cup Stadium Station  Exit 1,  1.9 km to Sky Park.', 37.5671036, 126.8869296, NULL, 'The Legend of the Blue Sea', NULL, 4),
	(19, 'Gwanghwamun Square at Night', '03154  172, Sejong-daero, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/GwanghwamunSquareatNight/ENP016319', 'Gwanghwamun Square is located on Sejong-ro in Jongno-gu and is vast in size. Gwanghwamun Square stretches out from Gwanghwamun Gate, towards Cheonggyecheon Stream, and is divided into 6 sections: ??Recovering the History of Gwanghwamun Gate Plaza,????Reenacting Yukjo Street Plaza,????Korea Main Plaza,????Civil Participation Urban Culture Plaza,', NULL, NULL, 'Subway Line 5  Gwanghwamun Station  Exit 2,  235m', 37.5716917, 126.9776492, NULL, NULL, NULL, 4),
	(20, 'COEX', '06164  513, Yeongdeung-daero, Gangnam-gu, Seoul (COEX)', 'https://english.visitseoul.net/attractions/Coex-convention-center-en/ENP024663', 'COEX is renowned for hosting large-scale exhibitions, international conferences, global convention center operations, and digital media promotional consulting. It hosts various expos centered around food, culture and arts, global issues, energy, and mobility. Additionally, several major summits in Seoul are held at COEX, offering extensive services. The squares and indoor lobby spaces around COEX also conduct various promotions, providing diverse experiences for the foot traffic between Samseong Station and Bongeunsa Station, as well as for exhibitions, COEX Mall, and Parnas Mall visitors. ', NULL, NULL, 'Subway Line 2 Samseong Station Exit 6, 273m', 37.5116828, 127.059151, NULL, 'K-POP DEMON HUNTERS', NULL, 5),
	(21, 'Hyundai Card MUSIC LIBRARY,  Hyundai Card VINYL & PLASTIC', '04400  246, Itaewon-ro, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/hyundaicard-musiclibrary-hyundaicard-vinyl-and-plastic/ENPtvunyc', 'Hyundai Card MUSIC LIBRARY is a space to purchase over 10,000 vinyl records carefully selected by genre. It also features turntables and CD players, allowing visitors to listen to their chosen vinyl records on the spot.Hyundai Card VINYL & PLASTIC is an LP record store where you can buy LPs, CDs, and more. The store showcases turntables and CD players, providing a hands-on experience. Eight listening zone tables are available, allowing you to listen to three albums for 30 minutes on weekdays and two albums for 20 minutes on weekends. Keep this in mind when planning your visit.', 'Tuesday to Saturday: 12:00 ??21:00 / Sunday and Public Holidays: 12:00 ??18:00', 'Closed during the Lunar New Year and Chuseok holidays', 'Subway Line 6, Hangangjin Station, Exit 3,  411m', 37.535982, 127.0014043, NULL, 'Itaewon Class', NULL, 5),
	(22, 'Fall Foliage Road (World Cup-ro)', '03906  9-1, World Cup-ro 42-gil, Mapo-gu, Seoul   (Street Sales Stand 07)', 'https://english.visitseoul.net/attractions/Fall-Foliage-Road-World-Cup-ro/ENP038858', 'World Cup-ro, which stretches along Nanjicheon Park, is a great place to take a walk surrounded by endless trees and green park views on both sides. Especially in autumn, the colorful fall leaves starting from World Cup Stadium intersection to Guryong intersection make the road even more beautiful.', NULL, NULL, NULL, 37.579489, 126.8809456, NULL, NULL, NULL, 3),
	(24, 'Kim Geun-tae Memorial Library-Archives', '01301  14, Dobongsan-gil, Dobong-gu, Seoul', 'https://english.visitseoul.net/attractions/Kim-Geun-tae-Memorial-Library-Archives/ENP041903', 'Kim Geun-tae Memorial Library-Archives which is located at the corner of the way going to Bukhansan National Park, as a Larchiveum, it is a library to read a book but at the same time, it\'s a museum that has a story of democracy and human rights, and also an art gallery to appreciate art works. A courtyard, which was naturally made at the center which was created by connecting the both ends of the two buildings with the bridge, is the most opened space in Kim Geun-tae Memorial Library-Archives and it\'s a space where you can directly feel the sunlight and the wind. As a library and an art gallery, the installation work is located on the courtyard so you can see an art work in the nature. At the rooftop called \'Sanbaramgil\',  various plays and events will be held with the background of the nature.', 'Daily 09:00 ~ 20:00\nWeekends 09:00 ~ 17:00', 'Every Monday, National Holiday', 'Subway Line 1/7   Dobongsan Station  Exit 1,  300m', 37.6905052, 127.0423388, NULL, NULL, NULL, 5),
	(25, 'Bukchon Hanok Village', '03059  37, Gyedong-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Bukchon-Hanok-Village/ENP000261', 'Bukchon Hanok Village reflects 600 years of Seoul??s history. The village is situated between Gyeongbokgung Palace and Changdeokgung Palace, and its streets are lined with traditional hanok. Unlike other hanok villages (such as Namsangol Hanok Village), Bukchon was not created for tourists and it is a residential village inhabited by Seoulites. The best place within Bukchon to experience the old hanok atmosphere may be Gaehoe-dong. Here, hundreds of hanok sit shoulder to shoulder. Bukchon Hanok Village has been loved by many as a travel destination in Seoul as the charm of the traditional hanok is being rediscovered. There are also art galleries, traditional workshops, and restaurants that have been built out from from hanok, making these spaces both traditional and unique. In the Bukchon Hanok Village, which holds history and culture from time past in every alley, the Bukchon Cultural Center delivers information and cultural context for these traditional and historic spaces. ', '10:00 ~ 17:00 (Restricted Hours: 17:00 ~ 10:00 the following day; visitors are prohibited from entering restricted areas during these hours)\n(The Hanok Village is a residential space for local citizens before it is a tourist attraction.)', NULL, 'Subway Line 3  Anguk Station  Exit 3,  516m', 37.5783339, 126.9861363, NULL, 'Personal Taste', NULL, 5),
	(26, 'Namsan Seoul Tower', '04340  105, Namsangongwon-gil, Yongsan-gu, Seoul, Korea  (Yongsan-dong 2-ga, YTN Seoul Tower)', 'https://english.visitseoul.net/attractions/Namsan-Seoul-Tower/ENP000036', 'Namsan Seoul Tower, which has established itself as a romantic island in the heart of the city, is a 236.7-meter-tall tower located at the summit of Namsan Mountain (262m), a place long regarded as a site of good fortune for lifelong love. Offering a breathtaking 360-degree panoramic view of Seoul from an elevation of 480 meters above sea level, it boasts the best vantage point in the city. As a symbol of Seoul and the top tourist destination chosen by international visitors, it has become a romantic sanctuary for couples worldwide who dream of eternal love. Popular attractions for couples include the "Locks of Love" and "Heart Chair," which are widely appreciated.    Namsan Seoul Tower comprises two main sections: the Lower Seoul Tower Plaza and the Upper N Seoul Tower. The Seoul Tower Plaza spans from the 1st to the 4th floor and includes attractions such as Gallery K, the Bodyfriend Lounge, and the Game Plaza. Visitors can also enjoy media art installations on a large 55-inch OLED panel. From the 5th floor up to the T7 floor, the N Seoul Tower features observation decks, the N Gift Shop, and various restaurants and cafes, all open 365 days a year.', 'Weekdays 10:00-22:30, Weekends 10:00-23:00\n*Last entry 30 minutes before close', NULL, 'Subway Line 3/4 Chungmuro Station Exit 2,  take Bus 01 (Namsan Circular), get off at \'Namsan Seoul Tower\' stop, 357m\nSubway Line 3 Dongdaemun Station Exit 6,  take Bus 01 (Namsan Circular), get off at \'Namsan Seoul Tower\' stop, 357m', 37.5511694, 126.9882266, NULL, 'K-POP DEMON HUNTERS', NULL, 5),
	(27, 'National Assembly Building', '07233  1, Uisadang-daero, Yeongdeungpo-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Assembly-Building/ENP005763', 'The National Assembly Building houses Korea\'s legislative branch of government and it is located in Yeouido. The building represents the democracy and human rights of Korea. The National Assembly Library is located to the right of the main building, and the Assembly Members Office Building is located to the left. Free tours of the National Assembly are available, but reservations are required. Visitors must reserve a tour date at least three days in advance of the desired visit date.', 'Weekdays: 10:00 AM - 17:00 (Entry available at 10:00, 11:00, 14:00, 15:00, 16:00, and 17:00.; Maximum 150 people per session)  \nSaturdays: 10:00 - 12:00 (Entry available at 10:00, 11:00, and 12:00; Maximum 150 people per session)', 'Closed Sundays, holidays & May 31st', 'Subway Line 9  National Assembly Station  Exit 1,  438m', 37.5310582, 126.9153816, NULL, 'The King: Eternal Monarch', NULL, 5),
	(28, 'Dongdaemun Design Plaza (DDP)', '04566  281, Euljiro, Jung-gu, Seoul (Euljiro 7-ga)', 'https://english.visitseoul.net/attractions/Dongdaemun-Design-Plaza-en/ENP024679', 'The Dongdaemun Design Plaza (DDP), planned by Seoul City Hall in 2006, opened its doors on March 21, 2014. The purpose of DDP is to utilize design thinking for innovation and development. It also showcases global design trends and design innovation as a birthplace of creative knowledge in the 21st century. As a multi-purpose cultural space, Dongdaemun Design Plaza has been hosting various cultural events since its opening, including exhibitions, fashion shows, new product launches, forums, and conferences. Additionally, the seasonal Seoul Light event transforms DDP\'s exterior walls into a curved silver canvas, offering diverse scenery.', '10:00-20:00 KST (Vary by space, see the website)', NULL, 'Subway Lines 2/4/5, Dongdaemun History & Culture Park Station  Exit 1,  37m', 37.5660286, 126.9954924, '선재업고튀어  동대문디자인플라자  문화행사  야경  서울여행  KdramaTrip | 드라마촬영지,  스토리,  야경,  산책,  카페 | 동대문디자인플라자,  촬영지,  야경,  전시,  쇼핑,  식사 | 디자인플라자,  촬영지,  문화행사,  예술적분위기,  사진촬영,  전시', 'Let\'s carry Sunjae and run | Let\'s grab him by the collar | North Star | two or two', 'https://blog.kakaocdn.net/dna/cHzh74/btsGt9omBgJ/AAAAAAAAAAAAAAAAAAAAAF3rCKzBTv36qp1AYSW7n-bgBdJom3zcyABTGFDJwJmq/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=oz0aAk10sH39H2vW48m8q%2BrXWMw%3D | https://blog.kakaocdn.net/dna/bpYZzj/btsF56LOEfK/AAAAAAAAAAAAAAAAAAAAAPNJSes4-0Jrx0KhEeTYCVtDS-vXMufI5deD1-OYnps1/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=NQBkVgwUNAnCsjoou6JXIAzQ1Ig%3D | https://blog.kakaocdn.net/dna/pzpbh/btsQr3NdCgj/AAAAAAAAAAAAAAAAAAAAAHyvlP0qx07FCvSmixTXi3uMjiGrQHVArImxz3va6-28/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=O59876r66VSYuu0yCczh6u0P68s%3D | https://blog.kakaocdn.net/dna/cI1w09/btsyV0LOI8x/AAAAAAAAAAAAAAAAAAAAAKSfopKQZ_UYlsPly1sf5-e80dQHpS9O_wLLCIx-en22/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=nwIJN%2FZEPQYyu76t%2F4OKXUgc95Q%3D', 5),
	(29, 'Changsin-dong\'s Cliff Village', '03091  23-322 Changsin-dong, Dongdaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-changsincliff/ENPgvo4y2', 'It was a quarry village in the 1960s, a wooden village in the 1970s, a sewing factory in the 1990s, and finally a sewing village in the 2000s. It is situated around the rocky cliffs once used as the nation\'s only quarry. Changsin-dong Cliff Village is divided into densely packed, dilapidated, aged homes built on cliffs and precipices and homes formed beneath rocky hills.*Please Note: When visiting, please refrain from making excessive noise, as actual residents live there.', NULL, NULL, 'Subway Line 6  Changsin Station  Exit 1,  708m', 37.5785444, 127.0113671, 'KdramaTrip,  카페,  지옥에서온판사,  서울관광,  드라마촬영지', 'a judge from hell', 'https://blog.kakaocdn.net/dna/cpI9Uv/btsJPegykMq/AAAAAAAAAAAAAAAAAAAAAJrhJbMCfgmbuQanDFU-QMIxS0rBrUt9-SVrvUlQSSF_/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=YXTLIT0w%2FeJuYgGxUDeSskiLl0U%3D', 5),
	(30, 'Hangang River Bus', '05500  1-2 Jamsil-dong area, Jamsil Pier, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/HanRiverBus/ENPmluo32', 'Seoul City operates the Hangang River Bus, a differentiated transportation method that anyone can experience in daily life, newly introduced to ensure convenience and leisure for the future of Seoul. Hangang River Bus offers new water transportation that bypasses urban congestion, serving as both a means of transportation and a tourism attraction by providing opportunities to enjoy the Hangang River and connect with local attractions. To establish landmark positioning, we plan to organize and attract events that suit the seasonal and location specific characteristics. Please try the new Hangang River Bus, a public transportation service beloved by people worldwide. ?? For safety operation inspections, trial runs without passengers will be conducted for one month starting from September 29.', 'Weekdays (68 trips daily) 6:30 AM-10:30 PM / Weekends (48 trips daily) 9:30 AM-10:30 PM\nExpress route weekdays 16 trips daily *Weekday commute (6:30 AM-9:00 AM), after work (6:00 PM-8:30 PM)', NULL, 'Subway Line 2 Jamsil Saenae Station Exit 7, 1km\nLines 2/8 Jamsil Station Exit 5, 2km', 37.5200456, 127.0828214, NULL, 'My Love from the Star', NULL, 2),
	(31, 'Herb Astronomy Park', '134-060  86 Dunchon-dong, Gangdong-gu, Seoul, South Korea', 'https://english.visitseoul.net/attractions/HerbAstronomyPark/ENP037130', 'Iljasan Herb Astronomical Park, located in Dunchon-dong, Gangdong-gu, Seoul, is an intimate park that is popular for enjoying nature. There is an astronomical observatory that can be used 24 hours a day. Additionally, as the name may entail, there are fresh herbs that grow around the park making it a fragrant space where you can feel relaxed while walking or jogging along the well-maintained trails. After dark, you can see hundreds of tiny lights that illuminate the space, making it even more beautiful.', NULL, NULL, 'Subway Line 9  VHS Medical Center Station  Exit 3,  Take the blue bus 342 or the green bus 2312 ??get off at the Gildong Natural Ecology Park,  296m', 37.5302304, 127.1437603, NULL, NULL, NULL, 5),
	(32, 'N Seoul Tower at Night', '04340  105, Namsangongwon-gil, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/NSeoulToweratNight/ENP016321', 'N Seoul Tower is one of Seoul\'s most famous landmarks and one of the city\'s most beloved attractions. The views from the tower are beautiful but the night views are especially breathtaking. Visitors can take in incredible panoramic views of Seoul from the tower\'s observatory. The tower has been used as a filming location in many Korean TV shows and movies. One of the tower\'s attractions is the locks of love that visitors fasten to Namsan\'s iron railings.      For more information:    N    Seoul Tower     Namsan Park', '10:00-22:30', 'Open year round', 'Subway Lines 3/4  Chungmuro Station or Subway Line 3  Dongguk University Station. Take Circular Bus No. 01 (Namsan Circular) ??get off at the "Namsan Seoul Tower" stop ??walk 357m (8-minute walk)\n\nTake the Seoul City Tour Bus ??get off at the "N Seoul Tower" stop.', 37.5489419, 126.9894041, 'KdramaTrip,  카페,  서울,  낭만,  야경 K-POP DEMON HUNTERS', 'Welcome to Samdali', 'https://blog.kakaocdn.net/dna/dXnQ5W/btsBGvpmsKd/AAAAAAAAAAAAAAAAAAAAAI-O5V8qeZSatHeEkXO8EgDoUpncdqxaIVPIf3j3foWa/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=NdN%2FHY%2BAe%2BD%2FP%2B3AWqsYt5nr4DI%3D', 4),
	(33, 'Figure and Ground', '06036  53, Nonhyeon-ro 153-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Figure-and-Ground/ENP042255', 'Figure and Ground is dressed in red brick, a material commonly used in architecture, but the exterior is wrapped in thin strips going around the building that exudes intense sophistication. It is even more meaningful in that it is a reconstruction of the original form of the 30-something-year-old building that once stood in its place. With a cafe and a boutique on the lower floors and a shared office on the upper floors coexisting in one building, Figure and Ground is buzzing on weekdays and weekends, day and night.', 'Ground level café, Conflict Store : Daily 10:00 ~ 22:00', NULL, 'Subway Line 3/Shinbundang Line  Sinsa Station  Exit 8,  541m', 37.5201622, 127.0239488, NULL, NULL, NULL, 5),
	(34, 'Gwanghwamun Square', '03172  B 175, Sejong-daero, Jongno-gu, Seoul, Korea (??종??? ??종??야???', 'https://english.visitseoul.net/attractions/Gwanghwamun-Square/ENP001899', 'King Taejo of the Joseon Dynasty moved the capital to Hanyang in 1394 and built Gyeongbokgung Palace, the official residence of the Joseon Dynasty. In addition, on both sides of the road in front of the palace??s main gate, the Street of Six Ministries, including Uijeongbu (State Council), was built. It was the best road in Hanyang. In 2009, that road opened again. Gwanghwamun Square and Cheonggye Plaza were built. ', 'Open 24 hours a day, throughout the year, as a city square', 'Open year-around', 'Subway Line 5  Gwanghwamun Station  Exit 2,  235m', 37.5722356, 126.9759338, '보물섬  촬영지  설가온  드라마팬  산책  사진찍기 | 드라마촬영지,  세종문화회관,  문화예술,  산책,  서울,  협상의기술 | 촬영지  전통미  KdramaTrip  추억  설가온  문화체험 | 세종문화회관  건축미  공연  산책  서울  KdramaTrip', 'Treasure Island | the art of negotiation | That\'s a black dragon | Our movie', 'https://blog.kakaocdn.net/dna/UsDn3/btsMSm3Nx7R/AAAAAAAAAAAAAAAAAAAAAAChCwrY1CfhMPOZL_5o0QKWEQS1x5B2x7juV2KuJG8u/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=3dNq2drAvXtmgpovCtYKLMxkHaY%3D | https://blog.kakaocdn.net/dna/AoPkV/btsMLOTnv9Z/AAAAAAAAAAAAAAAAAAAAAElseYiVXw3_UYn2bUU2ua_-QEaaEnAvQxquG102qFgD/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=6toXdti%2BEC9i7gw3NpgHfhX2%2FzA%3D | https://blog.kakaocdn.net/dna/bDrKMs/btsMVyaLJnS/AAAAAAAAAAAAAAAAAAAAALJkO0iaznDI1Rc6Lm7HsxM-aGBhcNVUcECuXMS8p90r/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=%2BvwjvREVQdugl6%2BgQborB4N6cxs%3D | https://blog.kakaocdn.net/dna/csjGqE/btsPpSkTWhS/AAAAAAAAAAAAAAAAAAAAAM5a-AMAfsvh0hxtb8X1Y74fml8SD3luwwKBmMryjvNF/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=oHnPk9ksDdjnwq%2BISyjtW%2BfMF7c%3D', 4),
	(35, 'Seoul Sky', '05551  300, Olympic-ro, Songpa-gu, Seoul (117-123F)', 'https://english.visitseoul.net/attractions/SeoulSky/ENPowtoyc', 'Located on the top floor of Lotte World Tower in Jamsil, Seoul Sky (5th highest in the world, 500 M) is the highest point in South Korea that offers a 360-degree view of Seoul??s dazzling beauty. From 500 meters in the sky, visitors can admire the city??s diverse charms as they change from day to night and throughout the four seasons. Moreover, Seoul Sky also features thrilling experiential attractions, a variety of exhibition content, a café where visitors can relax with a cup of coffee, and a range of tower-themed souvenirs, making it an ideal spot to create lasting experiences and memories.', 'Sun-Thu: 10:30-22:00, Fri-Sat: 10:30-23:00 KST', NULL, 'Subway  Line 2/8  Jamsil Station   Exit 2,  311m', 37.5131008, 127.1034334, NULL, NULL, NULL, 5),
	(36, 'Graphic', '04344  33, Hoenamu-ro 39-gil, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/Graphic/ENP042288', 'The building is in the shape of white cylinders stacked in layers with some cut-out sections, alomost like a multi-tiered cake covered in whipped cream. It is almost impossible to guess the purpose of this three-story high windowless building just by looking at it from the outside. Despite the mysterious appearance from afar, with a closer look one can see the bumpy lines that run vertically along the structure\'s facade. These lines represent the grain of a book\'s pages, implying Graphic\'s identity as a bookstore. Just like the mysterious exterior, the interior is surrounded    by magnificent walls that makeit impossible to guess the interior space is also secretive. Approximately 100new books are brought in every month, providing a new experience each time you visit.    The fact that only adults overthe age of 19 are allowed to enter makes the space even more secretive. A spacewhere you can read books without time constraints becomes a haven for one toshake off the weariness of life while having a light drink with a book.', 'Tuesday to Friday: 13:00 -23:00 \nSaturday, Sunday: 11:00 - 23:00', 'Closed Mondays', 'Subway Line 6  Itaewon Station  Exit 2,  1.2km', 37.5409333, 126.9935374, NULL, NULL, NULL, 4),
	(37, 'Changsin-Sungin Quarry Observatory', '03091  51 Naksan 5-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-Chaeseokjangjeonmangdae/ENPauov7d', 'The quarry observatory is built atop the summit of Changsin-dong quarry, providing a panoramic view of the city and natural landscapes at a glance.During the Japanese colonial period, a quarry was located in Naksan, Changsin-dong, to supply stone for the exterior of large buildings such as the Government-General of Korea, the old Seoul Station, and the Bank of Korea. After the Korean War, the quarry\'s use was discontinued, but the quarry observatory was located where immigrants and refugees settled to form a village.From the quarry observatory, with nothing obstructing the view, you can enjoy the skyline of Seoul at a glance. The second floor houses a coffee shop (Café Nakta), and the third floor features an outdoor observation deck, allowing you to appreciate the scenery of Seoul\'s cityscape and nature from any vantage point. Especially renowned is the breathtaking view that unfolds alongside the sunset. Enjoy the best panoramic view, a reasonably priced cup of coffee, and homemade ggangjeong and Nakta rice cakes. Small music concerts featuring historical and cultural stories, exhibitions, and live guitar performances are held occasionally.', 'Tue-Fri 10:00 - 20:00 / Sat-Sun 10:00 - 22:00', 'Mondays', 'Subway Line 6, Changsin Station, Exit 1, 708m', 37.5785444, 127.0113671, 'KdramaTrip,  카페,  지옥에서온판사,  서울관광,  드라마촬영지', 'a judge from hell', 'https://blog.kakaocdn.net/dna/cpI9Uv/btsJPegykMq/AAAAAAAAAAAAAAAAAAAAAJrhJbMCfgmbuQanDFU-QMIxS0rBrUt9-SVrvUlQSSF_/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=YXTLIT0w%2FeJuYgGxUDeSskiLl0U%3D', 5),
	(38, 'Lotte World Tower', '05551  300, Olympic-ro (Sincheon-dong), Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Lotte-World-Tower/ENP021278', 'Lotte World Tower is one of Korea\'s architectural crown jewels. The tower symbolizes the meeting of the modern with the traditional, nature and cutting edge technology, and the accomplishments of man. Lotte World Tower contains everything that is necessary for modern urban living.      Soaring 555m into the air; with 123 stories, Lotte World Tower is home to Korea\'s tallest observation deck, (at 500m) Seoul Sky. Korea\'s newest luxury landmark hotel, Signiel Seoul is also located at Lotte World Tower. Also located in the tower is Podium, a multi-floor, multipurpose space where visitors will find a healthcare center, a fitness center, and a financial center.        The Lotte World Mall, a global fashion hub, also calls Lotte World Tower home, and visitors will also be able to shop at Korea\'s largest urban duty free store, Lotte Duty Free. Other features include the shopping mall Avenuel, Korea\'s best urban aquarium, a spectacular classical music hall, and Asia\'s largest multiplex. Experience the best of modern living in Seoul at the Lotte World Tower', 'Please refer to the website.', 'Open year round', 'Subway Lines 2/ 8  Jamsil Station  Exits 2,  29m', 37.5131008, 127.1034334, NULL, NULL, NULL, 5),
	(39, 'Cheongwadae', '03048  1, Cheongwadae-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Cheongwadae/ENP005538', 'Cheong Wa Dae, meaning "Blue House," was the official residence of the President of South Korea until it was opened to the public in June 2022, becoming a popular tourist destination. The main building features the president\'s office, reception rooms, and conference rooms, while auxiliary buildings include Chunchugwan, the State Guest House, and the rear garden. Cheong Wa Dae is closed every Tuesday, and tour reservations can be made on its official website.   A tour of the Cheong Wa Dae grounds, which encompasses Nokjiwon, Sangchunjae, the residence, the State Guest House, and the main building, typically takes around 1 hour and 30 minutes to 2 hours.   On rainy days, interior tours of key buildings like the main building and Chunchugwan may be restricted to prevent damage. In the event of natural disasters such as typhoons, tours of all or parts of Cheong Wa Dae may be suspended to ensure visitor safety.  ', 'March to November: 09:00 - 18:00 (Last entry 17:00 / Indoor entry closes at 17:30)\nDecember to February: 09:00 - 17:30 (Last entry 16:30 / Indoor entry closes at 17:00)\n*For more details, please refer to our website', 'Closed on Tuesdays (*However, if Tuesday falls on a public holiday or substitute holiday, it will be open as usual and closed the following day.)', 'Subway Line 3, Gyeongbokgung Station, Exit 3 (984m on foot, 16-minute walk)', 37.5862687, 126.9766037, '드라마촬영지,  청와대,  산책,  K드라마,  역사,  관광', 'North Star The President', 'https://blog.kakaocdn.net/dna/BCCx2/btsQt4KN5t2/AAAAAAAAAAAAAAAAAAAAAPa0TCEA6cf8bF3YdLIUG5gQzpXOvmwV_UD3gNH03IOZ/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=pZF9rWifk6GvmXpOQ98poOL1OGc%3D', 5),
	(40, 'Sebitseom (Sebitseom Island)', '06500  2085-14, Olympic-daero, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Sebitseom/ENP024645', 'Sebitseom, also known as Sebit Islets, with the meaning ??three shining islands brightening the Hangang River??is the world??s first floating cultural space. It is made up of four artificial islands with wedding halls, Italian restaurants, buffets and cafes, exhibitions, performances and it is used as a marina for yachts and boats!    The Some Sevit, known to be a popular spot for nightlife in South Korea, has colorful and beautiful LED lights that reflect off of the Hangang River, making it a popular filming location for various dramas and movies, such Avengers: Age of Ultron. Enjoy delicious meals and cultural experiences, and remember to bring a camera for the various photo spots at the Floating Island Convention center, the outdoor deck and the roof observatory.', 'Daily 11:00 - 22:00', NULL, 'Subway Lines 3/7/9, Express Bus Terminal Station, Exit 8-1,  650 m', 37.5119827, 126.9934223, NULL, NULL, NULL, 5),
	(41, 'Hangang Eland Cruise', '07337  Yeouido Dock: E-Land Cruise Ticket Office, 280 Yeouidong-ro, Yeongdeungpo-gu, Seoul / Jamsil Dock: Jamsil E-Cruise, 2 Baekjegobun-ro, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Hangang-Cruise/ENP002126', 'The ultimate way to experience the Hangang River is by embarking on a cruise. Feel the refreshing breeze as you enjoy the picturesque views along both banks. Various cruises are available day and night, allowing you to appreciate the river??s beauty in a different light. The "Hangang Tour Cruise" runs daily during the day, offering a chance to explore Seoul\'s cityscape while enjoying live entertainment. Every evening at 6 PM, the "Sunset Cruise" provides a romantic view of the setting sun. For those who prefer evening or night outings, the "Moonlight Music Cruise" and "Starlight Cruise" offer stunning nighttime views of the Hangang River. Special options like the "Fireworks Music Cruise," featuring dazzling displays, and the "Dinner Cruise," which includes a buffet or champagne, add an extra luxury to your river experience.Aboard the cruise, you can enjoy live music while soaking in the sights of Seoul\'s iconic landmarks, including Sebitseom Island, Nodeul Island, Yeouido, the National Assembly Building, and Jamsil. It??s an ideal way to spend quality time with a partner, friends, or family, and offers a serene setting for those who wish to enjoy some peaceful reflection alone. Since schedules and routes vary by course, checking the official website for detailed information is advisable.', '10:00 AM - 22:00 (Varies per course)\n- Duration may vary depending on the departure point and whether it\'s a round-trip or one-way route.  \n- For detailed schedule information, please refer to the website or call.', 'In case of natural disasters or severe weather conditions.', 'Yeouido Dock:  Subway Line 5  Yeouinaru Station  Exit 3,  613m  \nJamsil Dock:  Subway Line 2  Jamsilsaenae Station  Exit 6,  999m', 37.5248693, 126.9380629, NULL, 'My Love from the Star', NULL, 3),
	(42, 'Songwoldong', 'Songwol-dong, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Songwol-dong/ENP010567', 'Songwoldong is a neighborhood in northern Seoul that is home to many of the city\'s historic sites. Deoksugung Palace, the Seoul Museum of History, Gyeonghuigung Palace, Sungnyemun Gate, Seodaemun Prison History Hall and Dongnimmun Gate are all found in Songwoldong. Visitors to Seoul can experience Korean history through a visit to this beautiful and charming area. The area has also been used as a filming location for many Korean TV shows including "Rooftop Prince." Songwoldong is easily accessible by car or public transportation.', NULL, NULL, 'Subway Line 5  Seodaemun Station  Exit 3', 37.5700771, 126.9652153, NULL, NULL, NULL, 4),
	(43, 'Korea Central Mosque', '04405  39, Usadan-ro 10-gil, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Central-Mosque/ENP004863', 'Located in Hannam-dong, Yongsan-gu, Seoul, the Seoul Central Mosque is the first Islamic Mosque in Korea. It was established on May 21, 1976, after construction began in October 1974. The Korean government provided the site in May 1969 with approximately 4,958 square meters of land, and the construction costs were supported by Islamic countries worldwide, including Saudi Arabia. Situated between the Hangang River and Namsan Mountain, the mosque features prayer halls on the first and second floors, with ablution rooms for men and women in the basement of the annex building. The first floor of the annex houses classrooms, while the second floor has office spaces. The adjacent Islamic Center includes facilities such as an Islamic mission center for children, a Muslim congregation, a women\'s association, and a library. The exterior of the Seoul Central Mosque features a variety of amenities, including halal restaurants, a halal butcher shop, an Islamic bookstore, a halal supermarket, and a travel agency, making it convenient for Muslims and non-Muslims to visit. ', 'Prayer services differ depending on time of the sunrise. Please refer to the website.', NULL, 'Subway Line 6  Itaewon Station  Exit 3,  477m', 37.5338516, 126.9966179, NULL, NULL, NULL, 4),
	(44, 'Chungdong First Methodist Church', '04516  46 Jeongdong-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Chungdong-First-Methodist-Church/ENP002132', 'Chungdong First Methodist Church is Korea??s first Protestant church, established in 1885 by American Methodist missionary Henry Appenzeller. The church is Korea\'s representative Protestant church. Chungdong First Methodist operates many religious and missionary programs such as medical services, education services, and missionary training for dispatch to foreign countries.', 'Worship Services in English:  \n- Contemporary Worship:  Sundays, 9:30 KST (Bethel Chapel)\n- Traditional Worship with Holy Communion:  Sundays, 14:00 KST  (Main Sanctuary)\n\nThe Mangon Christian History Reference Room requires advance reservation to visit. \n- Tuesday to Friday: 10:00 - 17:00 KST\n- Saturday 10:00 - 14:00 KST', 'The Mangon Christian History Reference Room is closed Mondays and Sundays', 'Subway Lines 1/2  City Hall Station  Exit 10,  404m', 37.5653627, 126.9725559, NULL, 'Goblin', NULL, 3),
	(45, 'Jinkwansa Temple', '03308  73, Jingwan-gil, Eunpyeong-gu, Seoul', 'https://english.visitseoul.net/attractions/Jinkwansa-Temple/ENP006251', 'Jinkwansa Temple is a centuries-old temple located in Bukhansan National Park. The temple was built by order of King Hyeonjong of the Goryeo Dynasty in gratitude to the great Buddhist priest Jinkwan. History has it that Jinkwan saved King Hyeon-jong\'s life when he was young and the king repaid the priest by building the temple. Jinkwansa Temple is comprised of several buildings and some of the notable buildings include Daeungjeon Hall, Myeongbujeon Hall, and Nahanjeon Hall. The temple also operates temple stay programs where visitors can experience Buddhist culture firsthand. There are programs for groups, children, and youths.', NULL, NULL, 'Subway Line 3  Gupabal Station  Exit 3, take bus 7211 or 7723 and get off at Hanago Station,  853m\nSubway Lines 3/6  Yeonsinnae Station  Exit 3, take bus 701 or 7211 and get off at Hanago Station, 853m', 37.6381414, 126.9465791, NULL, NULL, NULL, 5),
	(46, 'Hwanghakjeong (Archery Field)', '03027  15-32 Sajik-ro 9-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Hwanghakjeong-Archery-Field/ENP029766', 'Hwanghakjeong is an archery field built by Emperor Gojong who strongly believed that archery was the best activity for training one\'s body and spirit. Originally located in Gyeonguigung Palace, this archery field was relocated here under Inwangsan Mountain during 1922. Known far and wide for its magnificent scenery, Hwanghakjeong is located next to Hwanghakjeong Korean Archery Gallery, allowing visitors to access all kinds of information about Korean archery in one place.', NULL, NULL, 'Subway Line 3  Gyeongbokgung Station  Exit 1,  750m', 37.5778438, 126.9642634, NULL, NULL, NULL, 2),
	(47, 'Daegaksa Temple', '03134  87, Yulgok-ro 10-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Daegaksa-Temple/ENP005015', 'Daegaksa Temple is a Buddhist temple founded in 1911 by Yongseong Seunim and located not far from Changdeokgung Palace. Yongseong Seunim was one of the 33 citizen representatives who took part in the March 1st Movement. He was active in the Korean independence movement and his legacy includes significant reforms of modern Buddhism in Korea. The temple was originally just a small hanok and in 1986 the temple was completely ry reconstructed. Today, Daegaksa has a main gate, belfry, and three-story temple.', 'Daily from sunrise to sunset.', 'Open year round', 'Subway Lines 1/3/5  Jongno 3(sam)-ga Station  Exit 8,  139m', 37.5736573, 126.9920769, NULL, NULL, NULL, 4),
	(48, 'Ehwajang (House)', '110-500  32, Ihwajang 1-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Ehwajang-House/ENP002481', 'Ehwajang was the residence of Korea\'s first president Rhee Syngman. The residence now functions as a memorial hall for President Rhee Syngman. Ehwajang is comprised of the Rhee Syngman Memorial Hall, Sajeokgwan Library, and Jogakdang. Jogakdang was once the president??s office where Rhee designed and formed the first Korean presidential cabinet.', NULL, NULL, 'Subway Line 4, Hyehwa Station, Exit 2 (15 mins on foot)', 37.5783429, 127.0064308, NULL, NULL, NULL, 4),
	(49, 'Segeomjeong Pavilion', '03018  244, Segeomjeong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Segeomjeong-Pavilion/ENP002395', 'Segeomjeong Pavilion is a well-known historic pavilion and was designated Monument of Seoul No. 4 in 1976. The pavilion itself and the surrounding area are both referred to as Segeomjeong. During the Coup of 1623, rebel forces passed through Changuimun Gate from Segeomjeong in order to attack the palace. In peaceful times during the Joseon Dynasty, guards and soldiers would rest here and clean their swords at the stream.', NULL, NULL, 'Subway Line 3, Hongje Station  Exits 1 / 2,  Take the 110A Korea University trunk bus from Yujin Shopping Center stop, get off at Segeomjeong/Sangmyung University stop, 85m', 37.6004321, 126.9615466, NULL, 'My Love from the Star', NULL, 4),
	(50, 'Deoksugung Stonewall Walkway', '04519  101 Sejong-daero, Jung-gu, Seoul, Deoksugung Stonewall Walkway (Underground)', 'https://english.visitseoul.net/attractions/Deoksugung-Stone-Wall-Path/ENP023563', 'The Deoksugung Stone Wall Path is a charming walkway that winds around Deoksugung Palace in Jung-gu, Seoul, bordered by a rustic stone wall. Here, you can experience a serene blend of Joseon-era architecture and modern Seoul, with the path at its most beautiful in spring and autumn, attracting many visitors. After touring Deoksugung Palace, it??s an ideal spot to unwind at nearby cafes or galleries. The path also connects to Jeongdong-gil and the Seoul Museum of Art, making it easy to explore these attractions together.', 'Open year round \n*Interior walking path open Tuesday ??Sunday 9:00 ??21:00*', NULL, 'Subway Lines 1 / 2, City Hall Station, Exit 1, 168m', 37.5656072, 126.9769446, NULL, NULL, NULL, 5),
	(51, 'Gilsangsa Temple', '68, Seonjam-ro 5-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Gilsangsa-Temple/ENP003255', 'Gilsangsa Temple was once one of the foremost yojeong, a place where powerful men used to convene behind the scenes.The temple is named after the woman who donated the buildings, a gisaeng (a female entertainer and/or courtesan) named Kim Yeong-han who had a change of heart after reading "Non-Possession" by Venerable Beopjeong Sunim. The monk initially denied her request, but in 1995 decided to turn the buildings into a temple.  As a result, the temple has a very unusual atmosphere because it kept many of its original features. The temple is highly regarded for its involvement in cultural exchanges with other religions, and its programs to help visitors experience Buddhism.', 'Opening hours vary depending on the ceremony and temple schedule. Please refer to the website.', NULL, 'Subway Line 4, Hansung Univ. Station, Exit 6, 65m', 37.5987021, 126.99345, NULL, NULL, NULL, 5),
	(52, 'Seodaemun Independence Park', '03732  251, Tongil-ro, Seodaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Seodaemun-Independence-Park/ENP001753', 'Seodaemun Independence Park is a park and important historic cultural site. During the Japanese colonial period, the park housed Seodaemun Prison. Japanese imperial authorities arrested and held political prisoners and independence activists here in brutal conditions before the liberation of Korea in 1945. Today, the park is home to a history museum and monuments to independence fighters.  At the Seodaemun Prison History Hall, visitors can learn about the history, struggles, and sacrifices made by Koreans during the colonial era. Visitors to the park can see the historic Dongnimmun Gate (Independence Gate), Independence Hall, and the March 1st Declaration of Independence Monument. There are several memorials and statues of patriots, such as a statue of Seo Jaepil (a Korean independence activist) and the Patriot Martyrs Monument.', 'Open 24 hours', NULL, 'Subway Line 3  Dongnimmun Station  Exits 4,  150m', 37.5744857, 126.9546572, NULL, 'My Love from the Star', NULL, 5),
	(55, 'Yonghakgeong (Mokdong Archery Club)', '07990  316-8, Mokdongdong-ro, Yangcheon-gu, Seoul', 'https://english.visitseoul.net/attractions/Yonghakgeong-Mokdong-Archery-Club/ENP002250', 'Yonghakgeong was once a military training ground, and is now known as the Mokdong Archery Club. The club has membership system but one-off lessons can be reserved in advance. After making a reservation, visitors can take archery lessons at the center. There is a pavilion, Western-style archery center (Yanggung Center) and Korean-style archery center (Gukgung Center). Visitors can choose from Western or Korean-style bows for their lessons.', 'Yanggung Center\'s Day Lessons: Tuesday & Wednesday 14:00 - 16:00\n* Please make reservations in advance online or by phone', NULL, 'Subway Line 5  Omokgyo Station  Exit 4,  538m', 37.5294289, 126.8807875, NULL, NULL, NULL, 4),
	(56, 'Hwagyesa Temple', '01095  117 Hwagyesa-gil, Gangbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Hwagyesa-Temple/ENP002021', 'Hwagyesa Temple is located in the Samgaksan Woods, at the foot of Samgaksan Mountain in Seoul. Since the temple is close to center of the city, many people visit to feel the nature. Hwagyesa Temple has established a reputation as a temple that brings Korean Buddhism to an international audience. The temple attracts many Zen masters from all over the world and in addition to Korean and expat Buddhists. Hwagyesa Temple also offers a range of temple stay programs that are open to the general public. Visitors can choose from a one day program, a meditation-focused program, and an activities-focused temple stay program.', 'Opening hours vary depending on what Buddhist ceremonies are taking place, and the temple schedule', NULL, 'Subway Ui-Sinseol Line  Hwagye Station  Exit 2,  922m', 37.6326087, 127.0073144, NULL, NULL, NULL, 5),
	(57, 'Bongwonsa Temple', '03721  75-66, Bongwonsa-gil, Seodaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Bongwonsa-Temple/ENP028339', 'Originally built on the site of Yonsei University by Queen Jinseong of the Shilla Dynasty in 889 A.D., Bongwonsa Temple was moved to its current site by King Yongjo of the Joseon Dynasty in 1748. The temple grounds holds a pond filled with lotus flowers. This attracts a lot of visitors, especially in the summer, as many gather to view the beautiful blooming flowers as they enjoy the festivities. It\'s the perfect place to visit for calming your mind and spirit.', NULL, NULL, 'Subway Line 2, Sinchon Station, Exit 4\nSubway Line 2, Dongnimmun Station, Exit 4', 37.5712944, 126.946117, NULL, NULL, NULL, 4),
	(58, 'Andong Presbyterian Church\'s Soheodang', '03061  57, Yunboseon-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Andong-Presbyterian-Churchs-Soheodang/ENP002010', 'Andong Presbyterian Church is located in Bukchon Hanok Village. The church dates back to the early 20th century. Most churches at the time were founded and built by Western missionaries. However, Andong is unique in that the church was founded by Koreans. Soheodang is part of the church complex and it is a rest area run by the church. Visitors to Soheodang are welcome to sit and rest while enjoying free tea provided by the church.', '* Operating hours vary according to the church\'s prayer service schedule. Please check the times on the church website before visiting.', NULL, 'Subway Line 3  Anguk Station  Exit 1,  305m', 37.5784044, 126.9831562, NULL, NULL, NULL, 3),
	(59, 'Chodae-gil Trail (Bugaksan Mountain)', '01013  114, 4.19-ro, Gangbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Chodae-gil-Trail-Bukhansan-Mountain/ENP027112', 'Chodae-gil Trail is a walking trail course created near the base of Bukhansan Mountain to commemorate the opening of the Modern History Memorial Hall. On this course, visitors can visit the tombs of prominent figures who played key roles in the founding of Korea\'s modern history. ', NULL, NULL, 'Subway Line 4, Suyu Station  Exit 4,  take Bus No. 01 (village) Gangbuk at Suyu Station Bus Stop ??Get off at Shinsung Villa Bus Stop, Modern and Contemporary History Museum', 37.6410665, 127.0004213, NULL, NULL, NULL, 3),
	(60, 'Cheongjeon Yi Sang-beom House', '03039  31-7 Pirundae-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-cjisbhouse/ENPlpqd8k', 'The house and studio of Cheongjeon Yi Sang-beom, an artist recognized for pioneering new directions in Korean Southern School painting, are located west of Gyeongbokgung in Nuha-dong. Built-in 1929, the Yi Sang-beom House is an urban hanok featuring an L-shaped main house and straight-line servant quarters. It is distinguished by its rare kitchen with a cool wooden floor. Yi lived in this small, renovated hanok in Nuha-dong for 43 years. In his studio, known as Cheongjeon Hwasuk, he produced many artworks and mentored exceptional students such as Bae Ryeom and Park No-soo.', 'March-October 09:00-18:00\nNovember-February 09:30-17:00', 'Mondays', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  619m', 37.5783914, 126.9681622, NULL, NULL, NULL, 5),
	(61, 'Jongmyo Shrine Stonewall Path', '03135  104-1 Gwonnong-dong, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-jongmyostonewall/ENP0wav1s', 'The Jongmyo Shrine Stonewall Path is a tranquil walkway that stretches along the western wall of Jongmyo Shrine, a UNESCO World Heritage site. Unlike well-known historical and cultural spots like Bukchon and Insadong, this pathway is a hidden gem that has recently gained popularity. Strolling along the pristine, elegant stone wall, visitors can leisurely explore nearby cafes, craft studios, and shops and cafes housed in renovated hanok buildings along the side alleys. The path is beautifully framed by the historic stone wall and lush trees, offering scenic views throughout the seasons. In spring, cherry blossoms and fresh leaves embrace the wall, creating a bright and cheerful atmosphere. In autumn, the wall is transformed into a picturesque setting draped in warm hues, perfect for a romantic walk. This peaceful spot offers an ideal escape from the busy pace of everyday life. Traditional architecture and nature are in harmonious balance, providing a calming ambiance. Jongmyo Stone Wall Path is a fantastic photo spot for capturing traces of Korea??s traditional culture. Walking along the path, visitors can conveniently explore nearby attractions, such as Changgyeonggung Palace, Changdeokgung Palace, Insadong, and Samcheong-dong, where tradition meets modernity, allowing for a well-rounded cultural experience.', NULL, NULL, 'Subway Line 5  Jongno 3-ga Station  Exit 7,  383m', 37.5755397, 126.9918242, NULL, NULL, NULL, 5),
	(62, 'Bonghwanggak Pavilion', '142-090  107-12, Samyang-ro 173-gil, Gangbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Bonghwanggak-Pavilion/ENP003305', 'Bonghwanggak Pavilion was constructed in 1912 by Son Byeonghui, the Korean independence activist. Bongwhanggak was built to be an educational facility that taught students the doctrines of Cheondogyo and educated leaders of the Korean independence movement. Cheondogyo is a Korean religion founded by Choe Je-U and its main tenet is that life and death are one, and all things in the universe repeat in an endless cycle. "Bonghwang" is the Korean word for the phoenix and it appeared often in Choe\'s writings, which is how the pavilion came to be named Bonghwanggak. The pavilion is considered the main shrine of Cheondogyo. In 1969, Bongwhanggak was designated Tangible Cultural Property No. 2 by the Seoul Metropolitan Government.', NULL, NULL, 'Subway Uisinseol Line Bukhansan Ui Station Exit 2, 659m', 37.6602922, 127.0062054, NULL, NULL, NULL, 5),
	(63, 'Samcheongdong', '110-260  Gahoe-dong, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Samcheong-dong/ENP002121', 'Samcheongdong is Seoul\'s most stylish neighborhood, located just past Gyeongbokgung Palace\'s stone wall lined street. The name "Samcheong" is derived from the words "sam" meaning ??three", and "cheong" meaning "fresh" or "pure", because the mountain, water and the heart of the people in this area are all very fresh and pure. Then it\'s not wonder why many artists have sought out Samcheong-dong over the years. Because of this, Samcheong-dong became known as an artistic area.      The area of Samcheongdong is actually made up of several neighborhoods: Anguk-dong, Sogyeok-dong, Hwa-dong, and Sagan-dong and ends at Samcheong Park. Samcheong-dong is dotted with various art museums, museums, art galleries, restaurants, cafés, and shops; some are traditional, some are modern, but all are unique and colorful.', NULL, NULL, 'Subway Line 3  Anguk Station  Exit 2,  780m', 37.5820119, 126.9864646, NULL, 'Goblin', NULL, 5),
	(64, 'Seoul Anglican Cathedral', '100-120  15, Sejong-daero 21-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Anglican-Cathedral/ENP002030', 'The Seoul Anglican Cathedral was built during the Japanese colonial era and it is located beside Deoksugung Palace. The cathedral was constructed under the direction of the Rt. Reverend Mark Trollope, the third bishop of the Anglican Church of Korea and British architect Arthur Dixon. Although construction was completed in 1926, the Anglican Church of Korea considers 1890 as the date of the cathedral\'s foundation, since this was the year when the first service of Holy Communion was held. The cathedral is the seat of the Seoul Anglican Diocese and Tangible Cultural Property of Seoul No. 35.', 'Daily 11:00 - 16:00', 'Closed Weekends', 'Subway Lines 1 & 2, City Hall Station, Exit 3 (195m, 3-minute walk)', 37.5671292, 126.9759112, NULL, NULL, NULL, 3),
	(65, 'Yanghwajin Foreign Missionary Cemetery', '04084  46, Yanghwajin-gil, Mapo-gu, Seoul', 'https://english.visitseoul.net/attractions/Yanghwajin-Foreign-Missionary-Cemetery/ENP001153', 'Yanghwajin Foreign Missionary Cemetery is the final resting place for Korea\'s western residents, including Dr. Horace Allen, the first director of Gwanghyewon, the first western-style hospital in Korea, founded in 1885. The cemetery is known as Foreign Missionary Cemetery because of the number of foreign missionaries buried here. Tombs and headstones were built in a western style creating an exotic atmosphere. The cemetery is located near the Hangang (River), an ideal spot for taking a pleasant stroll.      Yanghwajin Foreigners\' Cemetery is situated on the other side of Yanghwajin, opposite the martyrs??shrine. It is regarded as a Protestant shrine because many Protestant missionaries are buried there.  The ??00th Anniversary Memorial Church??was established in Yanhwajin by the ??Council for the 100th Anniversary of the Korean Church??to commemorate a century of missionary work in Korea.       Many of the foreigners who have contributed to the story of modern Korean history are buried in the Yanghwajin cemetery, such as Thomas Bethell, the founder of Daehan Maeil Sinbo (Newspaper); Mary Scranton, the founder of Ewha Hakdang (a mission school for girls, now Ewha Womans University); and Henry Appenzeller, the founder of Chungdong First Methodist Church.      A guided tour in English or Japanese is available in Yanghwajin Foreign Missionary Cemetery when booked in advance. These are conducted four times a day (10:00, 11:30, 14:00, 15:30) except during the New Year\'s holiday, Chuseok holiday and on Christmas day.       Yanghwajin Foreign Missionary Cemetery is located in Hapjeong-dong, Mapo-gu. It is a haven for foreign missionaries and their families who loved, and wished to lie in, Korea. The cemetery is managed by 100th Anniversary Memorial Church and contains Mission Memorial Hall.', 'Daily 10:00 - 17:00 (KST)', 'Closed Sundays\n??Guided tours are not offered on Sundays, Jan. 1st, Lunar New Year, Chuseok, and Christmas', 'Subway Lines 2 /6  Hapjeong Station  Exit 7,  319m', 37.547333, 126.9113563, NULL, NULL, NULL, 5),
	(66, 'Namsangol Hanok Village', '04626  28, Toegye-ro 34-gil, Jung-gu, Seoul  Namsangol Hanok Village', 'https://english.visitseoul.net/attractions/Namsangol-Hanok-Village/ENP000276', 'Namsangol Hanok Village is a collection of five hanok (traditional Korean houses) from the Joseon Dynasty (1392-1910), recovered from different parts of the city and relocated to the northern foot of Namsan Mountain. The interiors of each of these five houses reflect owners from different walks of life, from the middle class to high government officials, noblemen and aristocrats. At Namsangol Hanok Village, visitors can see the hanok of important figures from the Joseon era including the house of Queen Yun\'s parents, who was the Queen Consort to King Sunjong, the 27th king of the Joseon Dynasty; the jaesil (study) of Yun Taekyeong, King Sunjong\'s father-in-law; the house of Min Yeong-hui, a relative of Empress Myeongseong; the house of Lee Seungeop, who was in charge of constructing Gyeongbokgung Palace and the house of Kim Chunyeong, a military official of the Joseon Dynasty. At the hanok village, international visitors can participate in traditional Korean activities such as archery and enjoy traditional Korean performances as well. Anyone who is curious about Korean wedding culture should visit the village on the weekend when traditional wedding ceremonies take place.  ', 'Summer season (April to October) 09:00 - 21:00 KST\nWinter season (November to March) 09:00 - 20:00 KST', 'Closed Mondays', 'Subway Lines 3/4  Chungmuro Station  Exit 4,  120m', 37.559315, 126.994477, 'Personal Taste Moonlight Drawn by Clouds', NULL, NULL, 5),
	(67, 'Seoul National Cemetery', '06984  210, Hyeonchung-ro (Dongjak-dong), Dongjak-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-National-Cemetery/ENP001965', 'Seoul National Cemetery is the resting place of fallen Korean patriots. The cemetery was established to honor the loyalty and devotion of those who sacrificed and lived for their country. Facilities at the cemetary include the War History Museum, Memorial Tower, Memorial Hall, and the Altar to Patriots and Patriotic Martyrs. Memorial services are held yearly on June 6th, which marks the Korean Memorial Day holiday.', 'Daily 06:00 - 18:00 (Front gate, central gate, and other 5 gates)\n09:00 - 16:00 (Business facilities opening hours)', NULL, 'Subway Line 4/9  Dongjak Station  Exit 4,  62m', 37.5022627, 126.975733, NULL, NULL, NULL, 5),
	(68, 'Myeongdong Cathedral', '100-022  74, Myeongdong-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Myeongdong-Cathedral/ENP004036', 'Myeongdong Cathedral is the very first Roman Catholic parish church in Korea. It is also the first Gothic building ever built in Korea and was designated as Historic site No. 285 in Korea. On the basement floor, there is a small sanctuary where the remains of the martyrs are enshrined, and where visitors to the cathedral can pay their respects. Every May, Myeongdong Cathedral holds a cultural festival. The construction of the cathedral started in 1892 and was completed in 1898. Unlike most Gothic buildings, Myeongdong Cathedral was built with bricks instead of stones. It gives the cathedral a characteristic atmosphere. The splendid high ceilings inside the church and the arches in between the magnificent inner pillars show the beautiful Gothic style well. The basement contains the remains of nine saints and martyrs, who devoted their lives to the propagation of Catholicism in Korea. Behind the cathedral, Seongmo Dongsan (St. Mary\'s garden) is situated. During lunch hour, pipe organs are playing here. The garden offers a peaceful resting space after visiting the cathedral.', NULL, 'Closed Mondays', 'Subway Line 4, Myeong-dong Station, Exit 8, 590m\nSubway Line 2, Euljiro 1(il)-ga Station, Exit 5, 616m\nSubway Line 2, Euljiro 3(sam)-ga Station, Exit 12, 561m', 37.5630786, 126.9869944, NULL, NULL, NULL, 5),
	(69, 'An Jung-geun Memorial Hall', '04636  91, Sowol-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/An-Jung-geun-Memorial-Hall/ENP004281', 'The An Jung-geun Memorial Hall was established to memorialize the Korean patriot An Jung-geun. An fought for Korean independence from Japan and was ultimately executed by Japanese authorities for assassinating Ito Hirobumi in 1909. Ito was a major force behind the Japanese annexation of Korea. The memorial hall is composed of 12 exhibition halls and galleries, an auditorium, a reference library, and a rest area. In addition to exhibition information about An\'s life and some of his calligraphy, the memorial hall also hosts the An Jung-guen Academny and other events each year. Events include visits to historic sites abroad that were important to independence movements and calligraphy contests. Admission to the An Jung-geun Memorial Hall is free.', 'March to October: 10:00 - 18:00\nNovember to February: 10:00 - 17:00 (KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', 'Subway Line 4  Hoehyeon Station  Exit 3,  689m', 37.554261, 126.9813393, NULL, NULL, NULL, 5),
	(70, 'Hyosa-gil in Heukseok-dong', '06910   4, Hyosa-gil, 5-gil, Heukseok-dong, Dongjak-gu, Seoul', 'https://english.visitseoul.net/attractions/Hyosa-gil-in-Heukseok-dong-/ENP011112', 'Hyosa-gil in Heukseok-dong is a neighborhood where the architecture and atmosphere of 1960s and 1970s Korea is still intact. At the neighborhood\'s observatory, Seoul landmarks such as the Mapodaegyo Bridge, Hangangdaegyo Bridge, and Namsan Seoul Tower are visible. The observatory is a great vantage point for night views of Seoul and the annual Seoul International Fireworks Festival.', NULL, NULL, 'Subway Line 9  Heukseok Station  Exit 4,  702m', 37.5358564, 127.0015384, NULL, 'Strong Woman Do Bong-soon', NULL, 5),
	(71, 'Sukjeongmun Gate', '03049  1, Daesagwan-ro, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Sukjeongmun-Gate/ENP023760', 'Sukjeongmun Gate is one of Seoul??s four historic great city gates. It is the city\'s northern gate and it can be visited today along the Hanyangdoseong, Seoul City Wall. Cheong Wa Dae, the official residence of the South Korean president is located not far from the gate and city wall. For decades, public access to the gate and its section of the city wall was restricted for security reasons. In 2006, public access to this section of the Hanyangdoseong was restored and it is now a very popular hiking destination. On January 21st, 1963, Sukjeongmun was recognized as part of the Hanyangdoseong, Seoul City Wall and designated Historic Site No. 10.', '*March to October (Daily): 09:00 - 18:00 (Last entry at 16:00)\n*Daily - November to February (Daily): 10:00 - 17:00 (Last entry at 15:00)', 'Closed Mondays', 'Subway Line 3, Gyeongbokgung Station, exit 3, take Blue Bus 710 at the Seoul Police Agency/Gyeongbokgung Station stop. Get off at Korea National Open University/Ihwajang, stop, and transfer to Green Bus 2112. Get off at Seoul Dawon School/Han Yong-un Activity Site, stop,  820 m', 37.5994258, 126.9836806, NULL, NULL, NULL, 6),
	(72, 'Yeonghwiwon and Sunginwon Royal Tombs', '02456  90, Hongneung-ro, Dongdaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Yeonghwiwon-and-Sunginwon-Royal-Tombs/ENP004524', 'Yeonghwiwon and Sunginwon are the burial site of members of the Korean royal family and the site was designated Historic Site No. 361 in 1991. Yeonghwiwon is the royal tomb of Princess Consort Sunheon, wife of the 26th king of the Joseon Dynasty, Gojong. Sunginwon is the burial place of Crown Prince Yi Jin, grandson of King Gojong and Princess Consort Sunheon.       In Korea, tombs for kings and queens are traditionally called ??neung??and tombs of princes and royal consorts are called ??won?? Yeonghwiwon and Sunginwon were once known as Hongneung as Queen Myeongseong, the first wife of King Gojong was entombed here. The grave was moved to Geumgok-dong in the city of Namyangju in 1919 following the death of King Gojong. Since then, the site has been known as Yeonghwiwon and Sunginwon. Apart from its historic significance, the greenery and beautiful surroundings here have always attracted sightseers.', '* November to January: 09:00 - 17:30 (KST)\n(Ticket booth 09:00 - 16:30 (KST))\n* February-May & September-October: 09:00 - 18:00 (KST)\n (Ticket booth 09:00 - 17:00 (KST))\n* June-August: 09:00 - 18:30 (KST)\n(Ticket booth 09:00 - 17:30 (KST))', 'Closed Mondays', 'Subway Lines 1/ Gyeongui-Jungang Line/ Suin-Bundang Line  Cheongnyangni Station  Exit 2,  884m', 37.5900345, 127.045015, NULL, NULL, NULL, 4),
	(73, 'Guam Park', '07525  42, Heojun-ro 5-gil, Gangseo-gu, Seoul', 'https://english.visitseoul.net/attractions/Guam-Park/ENP002027', 'Guam Park is located in Gayang-dong, Seoul. The neighborhood is the birthplace of Heo Jun, a famous Joseon-era doctor and scholar. Next to the park is a museum dedicated to Heo Jun. His name is known in Korea to this day, more than 4 centuries after his death, in part because of his definitive text on Oriental medicine, "Dongui Bogam." There is a large, shrubby rock big enough to accomodate 20 people in the park. Known as Heogabawi Rock, during times of conflict such as the Imjin War and the Second Manchu Invasion of Korea, the rock was used as a refuge.', NULL, NULL, 'Subway Line 9 Gayang Station Exit 1 , 741m', 37.5677821, 126.8526597, NULL, NULL, NULL, 4),
	(74, 'Old Seoul Engineering School Main Hall', '03087  86, Daehak-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Old-Seoul-Engineering-School-Main-Hall/ENP003387', 'The Old Seoul Engineering School Main Hall (formerly known as the Central Laboratory Complex) was built in 1906 and designated Historic Site No. 289 in 1981. The building was designed by the national Architecture Bureau. While in use as a school, students were taught how to use modern technologies and skills such as dyeing, weaving, papermaking, goldsmithing and woodworking. The building now functions as a museum and is part of Korea National Open University.', 'Please refer to the website.', NULL, 'Subway Line 4  Hyehwa Station  Exit 2,  237m', 37.5788284, 127.0036426, NULL, NULL, NULL, 3),
	(75, 'Maehun Yun Bong-Gil Memorial Hall', '06773   99, Maeheon-ro, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Maehun-Yun-Bong-Gil-Memorial-Hall/ENP003759', 'The Maehun Yun Bong-Gil Memorial Hall is dedicated to the resistance fighter, Patriot Yun Bong-gil. Yun\'s pen name was Maehun and he was active in the Korean independence movement during the Japanese colonial era. Located in Seoul\'s Yangjae dong, the first floor of the memorial is an exhibition hall that displays relics and biographical information about Yun Bong-gil in chronological order. On the second floor, the exhibition hall contains photographs and other materials of the Korean independence movement organized by theme. Admission to the memorial hall is free.', '* April to October: 10:00 - 18:00\n* November to March: 10:00 - 17:00\n??Last entry is 30 mins prior to closing', 'Closed Mondays, New Year\'s Day, Lunar New Year??s Day & Chuseok', 'Subway Sinbundang Line  Yangjae Citizen\'s Forest Station  Exit 5,  179m', 37.4702204, 127.0377882, NULL, NULL, NULL, 5),
	(76, 'Baek In-je House', '03055  16, Bukchon-ro 7-gil (Gahoe-dong), Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Baek-Injes-House/ENP021128', 'The Baek Inje is House, located in Gahoe-dong, Bukchon, is a representative traditional house that well preserves the style of modern hanok architecture. Although built during the Japanese occupation period, it has been designated as a Seoul Metropolitan Folklore Cultural Heritage due to its good condition and its blend of traditional hanok beauty with modern adaptations. Situated on a plot overlooking Bukchon, the property features a spacious Anchae (main living quarters) and a large garden centered around the Sarangchae (men\'s quarters), with a small Byeoldangchae (detached quarters) on the highest point. In this quiet, traditional setting, visitors can glimpse the lifestyle of the wealthy class of that era and observe features that distinguish it from typical upper-class homes of the time. Detailed information on the Baek Inje??s House, including its history, context, and characteristics, is available in the Haengnangchae (servants\' quarters) and small Sarangbang (guest reception room). While general tours don\'t require reservations, entry to some areas like the Sarangchae and Byeoldangchae is only for those with guided tour bookings.   ??Baek In-je (1898 - Unknown): Baek In-je was a Korean patriot who fought for Korean independence during the Japanese colonial era. Baek was also a doctor who devoted much of his time to studying rickets and blood disorders. He made great contributions to the body of research on these medical issues.', '09:00-18:00 (Last entry at 17:30)\n??Visitors not on a guided tour may only tour the grounds \n??Fridays & Saturdays until 20:00 during August', 'Closed Mondays & New Year\'s Day', 'Subway Line 3  Anguk Station  Exit 2,  464m', 37.5808035, 126.9841622, '한옥  전통문화  정년이  촬영지  서울여행  평화로운시간', 'retirement age', 'https://blog.kakaocdn.net/dna/OJPvK/btsJ4QY2DBY/AAAAAAAAAAAAAAAAAAAAAFjQWCWYoarBfJiEUqPlM3MtO4roJuWhD0RtpY_SSG9Y/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=ffRvc254SEw64sTgq%2F51sDbV%2BHs%3D', 4),
	(77, 'Jeongdong-gil', '04516  2, Jeongdong-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Jeongdong-gil/ENP000889', 'Mentioning Jeongdong-gil brings up a couple of imageries: old town neighborhoods, relaxing streets not crowded with people, a peaceful place to take a stroll, and so on. While all the above are true, visitors should also be aware that Jeongdong-gil is full of many historic buildings that managed to survive through Korea\'s turbulent past. It is also a place close to a lot of embassies like the Russian Embassy, British Embassy, US Embassy, German Embassy, etc. Chungdong First Methodist Church and Ewha Girls\' High School are some of the facilities which were built in the earlier era. A century later, Jeongdong-gil has been reborn as a cultural street featuring Seoul Museum of Art, Jeongdong Theater, and many other historical and cultural facilities and attractions.', NULL, NULL, 'Subway Line 1/2  City Hall Station  Exit 12,  580m \nSubway Line 5  Seodaemun Station  Exits 5,  581m', 37.5680258, 126.9691942, NULL, NULL, NULL, 4),
	(78, 'April 19th National Cemetery', '01009  17, 4.19-ro 8-gil, Gangbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/April-19th-National-Cemetery/ENP027106', 'With Bukhansan Mountain as its backdrop, the April 19th National Cemetery is a memorial ground for the people who??ve lost their lives in the April 19th Revolution. Inside the cemetery, there??s a white memorial tower erected in memory of these people and an exhibition hall and memorial hall displaying the events of the April 19th Revolution.', 'National Cemetery\n* March - October 06:00 - 18:00\n* November - February 07:00 - 18:00\n\nMemorial Hall\n* March - October 09:30 - 17:30\n* November - February 09:30 - 16:30', '* National Cemetery: Open year round\n* Memorial Hall: Closed Mondays', 'Subway Line 4, Suyu Station, Exits 2 & 6', 37.6489355, 127.0091036, NULL, NULL, NULL, 4),
	(79, 'Gyeonggyojang', '03181  29, Saemunan-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gyeonggyojang/ENP001151', 'Gyeonggyojang is an historic site that was the headquarters of the Provisional Korean Government during the Japanese colonial era and the private residence of Kim Koo. Kim Koo was a writer (using the pen name Baekbeom), independence activist and politician who served as the last premier of the Provisional Korean Government. He lived, worked, and ultimately died at Gyeonggyojang at the hands of an assassin. Kim was an immensely influential figure in Korean history and remains deeply revered to this day. Visitors to Gyeonggyojang can learn more about Kim Koo and the Korean independence movement.', 'Daily 09:00 - 18:00 KST', 'Closed Mondays & January 1', 'Subway Line 5  Seodaemun Station  Exit 4,  325m', 37.5672915, 126.9672554, NULL, NULL, NULL, 4),
	(80, 'Jeon Tae-il Memorial Hall', '03191  105, Cheonggyecheon-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Jeon-Tae-il-Memorial-Hall/ENP034860', 'Having been built by the Seoul city government, the Jeon Tae-il Memorial Hall is a labor complex facility erected to illuminate upon the historical significance of Jeon Tae-il, whose self-sacrifice served as a pivotal point in time in the history of the Korean labor movement. The young man gave everything he had to create a world that centered itself around the mentality that workers are people that have the right to live, work, and study in good health. In order to help bring Jeon Tae-il\'s dream into fruition, the hall urges unity between the labor force, the youth of the country, and the public, brought together around the ideals of love and solidarity.', 'March - October 10:00 - 18:00\nNovember - February 10:00 - 17:30', 'Closed Mondays, January 1 & holidays', 'Subway Line 2/3  Euljiro 3(sam)-ga Station  Exit 2,  362m \nSubway Line 1/3/5  Jongno 3(sam)-ga Station  Exit 15,  373m', 37.5691598, 126.9886684, NULL, NULL, NULL, 5),
	(81, 'Dosan Park', '06020  20, Dosan-daero 45-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Dosan-Park/ENP001789', 'Dosan Park is a large public park that was established to commemorate Dosan Ahn Chang-ho. Ahn is widely revered in Korea for his patriotism and achievements as an educator. He wrote under the pen name Dosan and was an independence activist, political reformer, and educator. The park features a statue of Ahn Chang-ho as well as a memorial hall dedicated to his memory. At the Dosan Ahn Chang-ho Memorial Hall, visitors can learn more about the life, writings, and achievements of Ahn Chang-ho.    Dosan Park has become a must-visit destination in Gangnam. It is surrounded by numerous restaurants, cafes, galleries, and clothing shops. Additionally, the area features flagship stores of renowned international brands, making it an excellent spot for shopping.', 'Dosan Ahn Chang-ho Memorial Hall: Open daily from 10:00 to 18:00', NULL, 'Subway Line 3, Apgujeong Station, Exits 2 & 3, 882m', 37.5243895, 127.0351173, NULL, NULL, NULL, 5),
	(82, 'Sajikdan (Sajik Altar)', '03027  89, Sajik-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Sajikdan-Sajik-Altar/ENP001824', 'Sajikdan (Sajik Altar) is an altar built during Joseon Dynasty that was used to pray to the gods for a good harvest. The altar is located in Sajik Park and in addition to the altar, visitors can see the Hwanghakjeong Archery Range and the Dangunseongjeon Shrine. The Jongno Public Library and a children\'s library is also located nearby.', NULL, NULL, 'Subway Line 3  Gyeongbokgung Station  Exit 1,  337m', 37.5769686, 126.9667015, NULL, NULL, NULL, 5),
	(83, 'Seokguram', '03034  3-14, Ogin-dong, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-seokguram/ENPexzzw3', 'Seokguram Grotto is nestled halfway up Inwangsan Mountain, just below Chimabawi Rock, and can be reached via the Inwangsan Mountain Trail. Inside, you\'ll find the Three Buddha Statues, while the surrounding forest path features a Buddha statue and a Maitreya Buddha carved into the rocks. Above the main hall at Sanshingak Shrine, a large rock bears a painting of the Mountain Spirit and a tiger that guards Inwangsan. About 30 meters to the right of Seokguram, you can also visit the Cheonhyangam Hermitage. From Seokguram, you\'ll enjoy stunning panoramic views of Seoul, with Namsan Tower visible on the opposite mountain and, on clear days, even Lotte Tower. Below, Gyeongbokgung Palace and the Blue House come into view.', NULL, NULL, 'Subway Line 3  Gyeongbokgung Station  Exit 2,  1.7km', 37.5820832, 126.9662083, NULL, NULL, NULL, 5),
	(84, 'Site of Concubine Jang Huibin??s Well', '03702  74 Yeonhui-ro 15-gil, Seodaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-jangheebin/ENPcyd45f', 'The area of the Site of Concubine Jang Huibin??s Well has been associated with Yeonhui Palace, a detached palace since the early Joseon Dynasty. It has been associated with palace grounds, courtyards, main buildings, and the royal family\'s first mulberry orchard. It has been passed down by the name Seojamsil, known as the Site of Concubine Jang Huibin??s Well.The first palace in this area was used as a refuge palace by King Jeongjong, who abdicated the throne to his younger brother, King Taejong, in the 3rd year of King Jeongjong\'s reign (1400). Later, in August of the 7th year of King Sejong\'s reign (1425), the palace was renamed Yeonhui Palace. It is said that there were wells in various places within the palace grounds due to the presence of palace officials and palace women. Among them, the preserved well is called the Site of Concubine Jang Huibin??s Well.During the reign of King Sukjong (1674-1720), Huibin Jang (1659-1701), who followed Queen Inhyeon, who was deposed, briefly stayed at this place as a concubine, but there is no proof she drank from the well. Over time, oral tradition in Yeonhui-dong has perpetuated the belief that "this well is where Huibin Jang drank water," upheld by generations of elders. Consequently, it was chosen for restoration as a part of the community\'s treasure-hunting initiative.', NULL, NULL, 'Subway Line 2 / Gyeongui Central Line/ Airport Railroad  Hongik University Station  Exit3,  1.6km', 37.5710951, 126.9285641, NULL, NULL, NULL, 2),
	(85, 'Jeongneung (A Royal Tomb)', '136-100  116, Arirang-ro 19-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Jeongneung-A-Royal-Tomb1/ENP003459', 'Jeongneung is the royal tomb of Queen Sindeok. She was the second wife of King Taejo, the founder of the Joseon Dynasty. It is said that the tomb was originally located behind Deoksugong (Palace) but moved to the current location when a son of King Taejo\'s first wife, King Taejong ( the third king of the Joseon Dynasty) ascended the throne. The original scale of the tomb was reduced as well. Although it is a simple tomb without many of the stone figures traditionally placed before a royal tomb, it has historical interest as it has faithfully kept the style of an early Joseon period tomb. The tomb is in picturesque surrounds with Bukhansan National Park located nearby.', 'February - May & September - October 06:00 - 18:00\nJune - August 06:00 - 18:30\nNovember - January 06:30 - 17:30\n* Ticket booth closes 1 hour prior to closing.', 'Closed Mondays', 'Subway Ui-Sinseol Line  Jeongneung Station  Exit 2,  584m', 37.6012152, 127.006821, NULL, NULL, NULL, 5),
	(86, 'Seokpajeong', '03021  4-1 Changimun-ro 11-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Seokpajeong/ENP037164', 'The name of this historical complex, "Seokpachon," translates into English as "surrounded by water, soaring above the clouds" and was given in honor of the great Heungseon Daewongun, the regent of the Joseon Kingdom. The Seokpachon complex is more than 600 years old, but it has been able to maintain its original appearance through careful preservation. This place is remarkable for its extraordinary beauty and it displays a combination of traditional Korean and Chinese architecture. This historic garden is currently under the authority of the Seoul Museum, which celebrates traditional and contemporary Korean art throughout the world.', '10:00 - 18:00 (Admission closes at 16:00)', 'Monday and Tuesday\n(??Closed Feb 26-May 31 for internal construction and next exhibition.)', 'Subway Line 3   Gyeongbokgung Station  Exit 3,  take bus 1020, 1711, 7016, 7018, get off at Jahamun Tunnel Entrance', 37.5972158, 126.9608908, NULL, NULL, NULL, 3),
	(87, 'Gyeongbokgung Palace Jibokjae', '03045  161 Sajik-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-Jibokjae/ENPfk9nxi', 'This building is located to the west of Geoncheonggung in Gyeongbokgung Palace. It housed about 40,000 books on Western artifacts purchased from the Qing Dynasty and was mainly used as King Gojong??s private library. Additionally, it served as a venue for enshrining portraits of kings or receiving foreign envoys. Originally constructed as a secondary building of Hamnyeongjeon Hall in Changdeokgung, it was relocated to Gyeongbokgung in 1891. The building was opened to the public in 2006, and the books previously housed there are now kept at Seoul National University\'s Kyujanggak Institute for Korean Studies and the Jangseogak Archives of the Academy of Korean Studies. In 2016, Jibokjae was transformed into a library and opened to the public. It is open from April to October, except for July and August, making it a great place to visit if you\'re in Gyeongbokgung during this period.', '10:00 ~ 16:00', 'Tuesdays', 'Subway Line 3  Gyeongbokgung Station  Exit 5,  1.1km', 37.5808473, 126.9768515, '경복궁  역사  전통건축  드라마촬영지  산책  문화체험 | KdramaTrip  광화문  역사  도시풍경  사진명소  문화탐방 | 경복궁  전통  산책  촬영지  자연  역사 | 드라마촬영지,  광화문,  야경,  서울,  역사적인장소 | 혼례대첩  경복궁  전통문화  역사체험  드라마촬영지', 'a distant view | One day, the life of a major | The phone you\'re calling right now | the Battle of the Wedding', 'https://blog.kakaocdn.net/dna/bl6eGQ/btsLGhnjr6q/AAAAAAAAAAAAAAAAAAAAAFXAPN99lOa1an0qtZ2dRmhNKnV2LsxF2BSO2oytDm5O/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=cPTf7i8VaDaP%2F34v0GZo08nck3E%3D | https://blog.kakaocdn.net/dna/xhj40/btsNh06pJng/AAAAAAAAAAAAAAAAAAAAAMFhElpzprIZzhIdEq7asWXgAlTrcavNrRqNYRou_E71/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=x491oadmQCJ7uVxpolm3hxse%2B6o%3D | https://blog.kakaocdn.net/dna/bh5Wac/btsNLCXzzSq/AAAAAAAAAAAAAAAAAAAAAMXnHrX18BwhNYpEUkbcHp-vqKdyF3GF7mu89Wq8nRaw/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=ys%2B8xpOoqKINBDCebdbi3qrKQwI%3D | https://blog.kakaocdn.net/dna/bYzT5p/btsKS3LYj3Z/AAAAAAAAAAAAAAAAAAAAAOAjrESdppsHcai8Xy4O0y9_9StZj_K3I5xjoAYA4_I-/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=%2FLLytVpo39JBTHLX0ADEdlCYyhg%3D | https://blog.kakaocdn.net/dna/dBkP1p/btszpAfWpA3/AAAAAAAAAAAAAAAAAAAAAPDTbzc8z-CE1Rtpzh_6iGN_CHET_CLcZ02DR7YcjOqJ/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=E8yMvzaFzQbU5LYOpWKiZcfLK6g%3D', 4),
	(88, 'Salgoji Bridge (Jeongotgyo Bridge)', '61-1 Haengdang-dong, Seongdong-gu, Seoul', 'https://english.visitseoul.net/attractions/Salgoji-Bridge-Jeongotgyo-Bridge/ENP002372', 'Salgoji Bridge (Jeongotgyo Bridge) is a historic stone bridge that dates back to the Joseon Dynasty. It stands over point where Cheonggyecheon and Jungangcheon Streams meet the Hangang River. It is the longest bridge from the Joseon era and was first designated Historic Site No. 160 in 1967; then elevated to Treasure No. 1738 in 2011. The bridge stands not far from Hanyang University.', NULL, NULL, 'Subway Line 2  Hanyang University Station  Exit 3,  257m', 37.5540822, 127.0454691, NULL, NULL, NULL, 5),
	(89, 'Comfort Women Memorial', '04628  6, Toegye-ro 26ga-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Comfort-Women-Memorial/ENP019540', 'The Comfort Women Memorial is located in Namsan, Yejang-dong, Jung-gu, Seoul, and opened in 2016. It serves as a memorial park honoring the victims and survivors of the Japanese military??s wartime sexual slavery. The space is centered around their testimonies, records of victimization, and documentation of Japan??s war crimes, embodying the themes of human rights and peace.', NULL, NULL, 'Subway Line 4  Myeong-dong Station  Exit 1,  511m', 37.5584605, 126.9906136, NULL, NULL, NULL, 5),
	(90, 'Sungkyunkwan University\'s Myeongryundang Lecture Hall', '110-812  25-1, Sungkyunkwan-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Sungkyunkwan-Universitys-Myeongryundang-Lecture-Hall/ENP003176', 'Sungkyunkwan University was originally founded centuries ago during the Joseon Dynasty. Myeongryundang Lecture Hall is one of the Joseon era buildings that can still be seen at the university\'s Seoul campus. In the lecture hall\'s courtyard is a beautiful ginko tree that is thought to be more than 500 years old. The tree is known for its beauty and was designated Natural Monument No. 59. ', 'Summer (March - October): 09:00 - 18:00\n Winter (November - February): 09:00 - 17:00', NULL, 'Subway Line 4  Hyehwa Station  Exit 4,  833m', 37.588227, 126.993606, NULL, NULL, NULL, 5),
	(91, 'Shina Memorial Hall', '04518  33 Jeongdong-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-shina/ENPjkm9y3', 'Located in Jeong-dong, this building is notable for its uniquely stacked red bricks. It was constructed in the 1930s as a reinforced concrete building with one basement level and two above-ground floors. The structure, finishes, and facilities reflect its nearly 100-year history. Initially used as the Korean branch of the American sewing machine brand ??Singer,??it was purchased by Shina Ilbo, Korea\'s first commercial newspaper, in 1963. Shina Ilbo expanded the building by adding the third and fourth floors in 1975, using it as an annex. Following the forced shutdown of Shina Ilbo, the building was transformed into a memorial to commemorate the founder, Jang Ki-bong, and the newspaper. Today, it houses various businesses, including memorial halls, a café, and boutique shops, on each floor.', 'Vary by company', NULL, 'Subway Lines 1/2  City Hall Station  Exit 12,  507m', 37.5671228, 126.9715929, NULL, NULL, NULL, 4),
	(92, 'Jungnang Mang-u Space', '02178  2, Mangu-ro 91-gil, Jungnang-gu, Seoul', 'https://english.visitseoul.net/attractions/Jungnang-Mang-u-Space/ENP041904', 'Manguri, which was used as a cemetery for a long time, it was reborn as a Mang-U History & Culture Park to honor the spirits of the activists for independence such as Yu Gwan-sun, Han Yong-un, Ahn Chang-ho and Bang Jeong-hwan. Jungnang Mang-u Space is where the place newly created to honor a sublime meaning of great men by walking a calm nature of Mangusan Mountain. Jungnang Mang-u Space consists of the two buildings, a managing building and an exhibition building. A managing building administers the areas of grave and runs memorial ceremony. At an exhibition building, the works of literary people who are enshrined in Manguri, are being exhibited.', 'Monday to Friday 09:00-18:00', NULL, 'Subway Gyeongui-Jungang Line  Yangwon Station  Exit 2,  1.5km', 37.5970852, 127.114734, NULL, NULL, NULL, 5),
	(93, 'Bongeunsa Temple', '06087  531, Bongeunsa-ro, Gangnam-gu, Seoul, Korea', 'https://english.visitseoul.net/attractions/Bongeunsa/ENP000411', 'Bongeunsa is a Buddhist temple founded in 794 during the Silla (one of the Three Kingdoms of Korea) period. The temple has more than 1,000 years of history and has many interesting historic and cultural features, including woodblock carvings of the Avatamsaka Sutra (Flower Garland Sutra). The temple is also a very popular tourist destination, offering various programs relating to traditional Korean Buddhist culture, in a variety of languages.       Bongeunsa is more than a just temple. It provides a place to relax for busy city people and also gives people a chance to reflect upon themselves. The templestay program gives an opportunity to experience everyday life in the temple, which includes traditional Korean Buddhist culture and practices. Visitors can experience some simple Buddhist practices such as the daily dawn service, Korean Zen meditation, Dado (a tea drinking ceremony), and Balwoogongyang (a Buddhist meal with traditional bowls).  Every May on Buddha\'s birthday, Bongeunsa holds the Lotus Lantern Festival on nearby Samseong-don   g.', NULL, NULL, 'Subway Line 9  Bongeunsa Station  Exit 1,  135m', 37.5149022, 127.0584184, NULL, NULL, NULL, 5),
	(94, 'Pungnaptoseong Fortress', '05512  30, Hangaram-ro 20-gil, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Pungnaptoseong-Fortress/ENP001953', 'Pungnaptoseong Fortress is the site of earthen ramparts that date back to the Baekje period (18 BCE-660 AD). Because many pieces of pottery have been uncovered here during excavations, it is thought that the site may have been a residential area at one time. Another important Baekje site, Mongchontoseong Fortress is located nearby.', NULL, NULL, 'Subway Line 5/8  Cheonho Station  Exit 9,  127m', 37.5386899, 127.1209017, NULL, NULL, NULL, 5),
	(95, 'Bangi-dong Ancient Baekje Tombs', '05644  219, Ogeum-ro, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Bangi-dong-Ancient-Baekje-Tombs/ENP002544', 'The Bangi-dong Ancient Baekje Tombs are ancient tombs in located the Bangi-dong area that date back to the Hanseong Baekje era. The ancient Hanseong Baekje Kingdom was founded along the Hangang River in 18 BCE and lasted for nearly 5 centuries. The tombs were discovered in the 1970s during the Jamsil District Zoning Project and there are 8 tombs altogether. Unfortunately, most of the artifacts were stolen at some point in time, but the tombs themselves were preserved well. Visitors can observe the original structures of the tombs and learn more about Hanseong Baekje. These ancient tombs are an important historical site and the area around the tombs was made into a park. There are paths between the tombs and visitors can take a quiet walk around the park and observe the tombs while enjoying the park\'s fresh air and grass. The site holds the designation of Historic Site No. 270.', 'Daily 09:00 ??20:00\n* Winter Season 09:00 ??19:00', NULL, 'Subway Line 5 Bangi Station Exit 3, 600m\nSubway Line 9 Songpanaru Station Exit 3, 613m', 37.5083768, 127.1187791, NULL, NULL, NULL, 5),
	(96, 'Jogyesa Temple', '03144  55, Ujeongguk-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Jogyesa-Temple/ENP002586', 'Jogyesa Temple was established in 1910 under the name Gakhwangsa by monks who aspired for the independence of Korean Buddhism and the restoration of the national capital. At the time, Gakhwangsa was the first temple to be situated within the four main gates of Seoul. In 1937, efforts began to relocate Gakhwangsa to its present site, now known as Jogyesa. Positioned in the heart of Jongno, Seoul, it is the only traditional temple in the city center, offering a place for visitors to rest. The temple grounds are open 24/7, welcoming locals and foreigners anytime. The temple hosts a temple stay program and the annual Lotus Lantern Festival.', 'Opening hours vary depending on what Buddhist ceremonies are taking place and the temple schedule', NULL, 'Subway Line 1  Jonggak Station  Exit 2,  413m', 37.5740386, 126.9821297, NULL, NULL, NULL, 5),
	(97, 'Manhae Han Yong-Un Simujang', '02879  24, Seongbuk-ro 29-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Manhae-Han-Yong-Un-Simujang/ENP001399', 'Simujang, the residence of Manhae Han Yong-un, was built in 1933 during the Japanese occupation. Unlike typical hanok homes that face south, this house faces north. As an independence activist, Manhae chose a north-facing site on the hillside to avoid facing the Japanese Government-General of Korea. The house has a rectangular layout with a hip-and-gable roof and features four front rooms and two side rooms. Inside, you??ll find Manhae\'s personal room with preserved artifacts such as his calligraphy, research papers, and court records from his time in prison. After his death, his only daughter, Han Young-sook, lived there. However, when the Japanese Embassy moved across from the property, she relocated to Myeongnyun-dong, and Simujang was transformed into a research center dedicated to Manhae\'s philosophy.', 'Daily 09:00 - 18:00 (KST)', 'Open year round', 'Subway Line 4  Hansung University Station  Exit 6,  62 m  to the Samsun-gyo and Seongbuk Cultural Center bus stop. Take the Seongbuk 03 bus and get off at the Supermarket stop.  127m', 37.5936207, 126.9916993, NULL, NULL, NULL, 4),
	(98, 'Wonhyoro Catholic Church', '04361  49, Wonhyo-ro 19-gil, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/Wonhyoro-Catholic-Church/ENP001862', 'Wonhyoro Catholic Church is located beside Sacred Heart Girls\' High School (once the Yongsan Seminary) and was consecrated in 1902. The church is small in scale but notable for its French Gothic architecture. Visitors to Seoul can visit an important piece of modern Korean history with a stop at Wonhyoro Catholic Church.', 'Daily 09:00 - 17:00', 'Hours may vary according to the school\'s schedule', 'Subway Line 6/Gyeongui Central   Hyochang Park Station  Exit 4,  1.3km', 37.5343336, 126.9540334, NULL, NULL, NULL, 5),
	(99, 'A Look at Yonsei University\'s 3 Historic Halls', '03722  50, Yonsei-ro, Seodaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Yonsei-Universitys-Stimson-Hall--Underwood-Hall--Appenzeller-Hall/ENP002435', 'Yonsei University is one of Korea\'s best universities. Its history is deep and many of the buildings on the Yonsei campus have modern historical significance as they were built in the early years of the 20th century. Stimson Hall was the first building ever built on the Yonsei campus and it was constructed in 1920. The hall was designated Historic Site No. 275 in 1981. Underwood Hall, Historic Site No. 276, was the second building ever built at Yonsei University. Today the hall functions as a museum dedicated to the founder of Yonsei, Horace G. Underwood and the Underwood family. Appenzeller Hall was built in 1924 and holds the designation of Historic Site No. 277. The hall was built to commemorate Henry Appenzeller who established the famed Korean boys\' school, Paichai Hakdang.', 'Daily 09:00 - 17:00', NULL, 'Subway Line 2  Sinchon Station  Exits 2,  1.2km', 37.5646993, 126.9394972, 'KdramaTrip  Campus  연세대학교  디어엠  로맨틱  산책 | 연세대학교,  마녀,  캠퍼스,  드라마촬영지,  가을,  추억', 'Dear.M | Witch', 'https://blog.kakaocdn.net/dna/bExP4L/btsNlzUAirR/AAAAAAAAAAAAAAAAAAAAAAPdzL29ys5LqFIGiTCdV3ZDt0k3DlZz3n-PGmVTEwTi/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=AAc1PSV606r%2FbsRSxj%2FlWFt0Hao%3D | https://blog.kakaocdn.net/dna/nkovl/btsMsLJmoOe/AAAAAAAAAAAAAAAAAAAAAMRJ1RTCxb6wyOPh1VKmK-jfKLddCzHW34K8py_3izIq/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=TENkyxrb3DzWv5MIoKYhma5pajA%3D', 3),
	(100, 'Grand Greenhouse Changgyeonggung Palace', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul, Korea (창경???', 'https://english.visitseoul.net/attractions/GrandGreenhouseChanggyeonggungPalace/ENP037176', 'Changgyeonggung Palace, one of the four main historical palaces in Seoul, houses a greenhouse built in 1909. It is Korea\'s first greenhouse designed in a Western architectural style. Initially, there was a botanical garden and a zoo. In 2004, the building was restored, retaining the original appearance of the greenhouse, and is open to the public. Here you will find different types of plants, both local and imported from other countries.', '09:00 - 20:45', 'Mondays', 'Subway Line 4  Hyehwa Station  Exit 4,  779m', 37.5788149, 126.9949298, NULL, NULL, NULL, 5),
	(101, 'Taereung and Gangreung Royal Tombs', '01794  681, Hwarang-ro, Nowon-gu, Seoul', 'https://english.visitseoul.net/attractions/Taereung-and-Gangreung-Royal-Tombs/ENP002299', 'Taereung and Gangneung Royal Tombs are the burial sites of royalty from the Joseon Dynasty. Located in Hwarang-dong, Taereung and Gangneung sit next to each other. The Korea National Training Center for Sports sits between the two royal tombs and the center is operated by the Korean Olympic Committee. Taereung is the royal tomb of Queen Munjeong; the second wife of the 11th Joseon king, Jungjong. Gangneung is the royal tomb of the Queen Munjeong\'s son and the 13th Joseon king, Myeongjong and his wife, Queen Insun. In June 2009, all 40 of the royal tombs of the Joseon Dynasty were designated UNESCO World Heritage sites.', '* February to May, September & October: 09:00 - 18:00\n* June to August: 09:00 - 18:30\n* November to January: 09:00 - 17:30\n*Last entry 1 hour before closing', 'Closed Mondays', 'Subway Line 6  Hwarangdae Station  Exit 4,  1.6km', 37.6343679, 127.0995736, NULL, NULL, NULL, 3),
	(102, 'Bosingak Pavilion (Bell Ringing Ceremony)', '03189  54, Jong-ro, Jongno-gu, Seoul  (Bosingak Pavilion)', 'https://english.visitseoul.net/attractions/Bosingak-Pavilion-Bell-Ringing-Ceremony/ENP001904', 'Bosingak Pavilion, a bell tower located in Jongno 2-ga, Jongno-gu, was the original site of the Old Bronze Bell (Treasure No.2). Due to cracks that rendered the bell unringable, it is now housed at the National Museum of Korea in Yongsan. The current bell hanging in Bosingak Pavilion is a newly cast replica, funded through public donations. It was installed on August 14, 1985, and first rung the following day, August 15. Bosingak Pavilion is renowned for hosting Korea??s iconic New Year??s Eve bell-ringing ceremony, where the bell is struck 33 times at midnight on December 31. Additionally, the bell is rung 12 times daily at noon, except on Mondays.', 'Bosingak Pavillon Ringing Ceremony 11:00 ~ 12:30 (KST)\n* Reservation required for the bell ringing experience', 'Closed Mondays, March 1st, August 15th, and days with inclement weather', 'Subway Line 1  Jonggak Station  Exit 4,  63m', 37.5697599, 126.9836604, NULL, NULL, NULL, 5),
	(103, 'Yakhyeon Catholic Church', '04506  447-1, Cheongpa-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Yakhyeon-Catholic-Church/ENP001845', 'Yakhyeon Catholic Church was the first Western-style church ever built in Korea. Located in Jungnim-dong, the church can be seen from Seoullo 7017. Yakhyeon Catholic Church has historical significance as a religious site and its architecture was hugely influential on the architectural styles of other churches in Korea. The building was destroyed by fire in 1998 but it was subsequently restored.', '* Museum 09:00 - 18:00\n* Gallery 09 :00 - 18:00\n\n* Mass Schedule:\nMondays 06:00\nTuesdays 19:00\nWednesdays 10:00\nThursdays 10:00, 19:00\nFridays 10:00 (Mass at Hyeonyangtap at Seosomun Martyrs\' Shrine in Seosomun Park)\nSaturdays 18:00 \nSundays 09:30, 11:00, 18:00 (Elementary, middle school students) / 11:00 (General public) / 18:00 (Youth)\n\n\n** The church is closed to visitors during mass.', 'Museum: Closed Mondays, New Year\'s Day & Chuseok\nChurch: Closed to visitors during mass', 'Subway Lines 2 / 5   Chungjeongno Station  Exit 4,  481m', 37.5588543, 126.9674934, NULL, NULL, NULL, 4),
	(104, 'Wongudan Altar', '100-070  106, Sogong-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Wongudan-Altar/ENP004198', 'Wongudan was built during the Joseon Dynasty to be an altar for performing divine harvest rituals. Located in central Seoul right near City Hall, it was designated Historic Site No. 157 in 1967. Through the past few centuries the altar was once called Hwandan and more recently Hwangudan. Now officially known as Wongudan Altar, Wongudan is located in close proximity to other major Seoul tourist attractions so it\'s convenient and easy to add a stop to Wongudan on a Seoul travel itinerary. The current Hwangudan Altar is a complex established in 1897 on the site of the old Nambyeolgung Palace. Its altar was built for Emperor Gojong\'s enthronement ceremony and rituals. The Japanese demolished the original complex in 1913, and a railway hotel was built on the site, reducing its size. Today, only the Hwangungu, the stone drum, and a stone gate with three arches remain preserved within the grounds of the Joseon Hotel.', 'Daily 07:00 - 21:00', NULL, 'Subway Lines 1/2  City Hall Station  Exit 6,  157m', 37.5644378, 126.9800994, NULL, NULL, NULL, 5),
	(105, 'Seodaemun Prison History Hall', '120-080  251, Tongil-ro, Seodaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Seodaemun-Prison-History-Hall/ENP001831', 'Seodaemun Prison was used to intern Korean patriots during the Japanese occupation. Until the Liberation of Korea on August 15, 1945, it was known as a clandestine mecca for the anti-Japanese resistance fighters, where they were tortured and executed. The Seodaemun Prison History Hall opened in November 1998 in Seodaemun Independence Park to commemorate the patriots who sacrificed their lives in the fight for Korean independence during the Japanese occupation. It consists of a historic exhibition hall, a central prison, jail cells, a hospital, the patriot memorial, an execution room, a tunnel through which corpses were carried, a watchtower, and a basement jail cell where the female patriot, Yu Gwansun, was tortured and killed.', 'March - October 09:30 ??18:00\nNovember - February 09:30 ??17:00', 'Closed Mondays, Lunar New Year, January 1st & Chuseok', 'Subway Line 3  Dongnimmun Station  Exit 5,  209m', 37.5742169, 126.9561692, NULL, NULL, NULL, 5),
	(106, 'Uireung', '02789  146-37, Hwarang-ro 32-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Uireung/ENP005205', 'Uireung is the royal tomb of King Gyeongjong, the 20th king of the Joseon dynasty, and his wife Queen Seonui. Uireung is located inside the Korea National University of Arts campus in Seokgwan-dong, Seongbuk-gu. Most royal tombs are "ssangneung," tombs that are arranged with the king and queen next to each other. At Uireung, the tombs of the king and the queen are arranged front to back. The tomb in the front is Queen Seonui??s and the one in the back belongs to King Gyeongjong. Uireung is closed Mondays.', '* February - May & September - October 09:00 - 18:00 KST (Ticket office closes at 17:00 KST)\n* June - August 09:00 - 18:30 KST(Ticket office closes at 17:30 KST)\n* November - January 09:00 - 17:30 KST (Ticket office closes at 16:30 KST)', 'Closed Mondays', 'Subway Line 1  Sinimun Station  Exit 1,  945m', 37.6063236, 127.0569849, NULL, NULL, NULL, 5),
	(107, 'Heonilleung', '06795  36-10, Heonilleung-gil, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Heonilleung/ENP005240', 'Heonilleung is a UNESCO World Heritage Site and the final resting place of two pairs of the Joseon Dynasty\'s kings and queens. The name of the site is a combination of the names of the two separate tombs, Heonleung and Inleung. The tombs of Joseon\'s third king, Taejong (1367-1422), and his wife, Queen Wongyeong (1365-1420) are at Heonleung. Inleung is the resting place of Joseon\'s 23rd king, Sunjo (1790-1834), and his wife Queen Sunwon (1789-1857). Heonilleung is unique in that it houses two kings born 400 years apart. Visitors to the royal tombs can see examples of early and late Joseon Dynasty royal tombs and there is a weekly talk about the tombs every Saturday. On Lunar New Year\'s Day, traditional performances are held at Heonilleung for the public to enjoy.', '* February - May & September - October 09:00 - 18:00 KST\n* June - August 09:00 - 18:30 KST\n* November - January 09:00 - 17:30 KST', 'Closed Mondays', 'Subway Line 3, Yangjae Station, Exit 7. From the Yangjae Station - Seocho Cultural Arts Center bus stop 240m  board buses 440, 741, or 452 and get off at the Heonilleung??Gangnam Seocho Science Reserve Training Center stop. Heonilleung is 662m', 37.4704507, 127.0794016, NULL, NULL, NULL, 5),
	(108, 'Sodeokmun Gate (Seosomun)', '04513  100, Seosomun-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Site-of-Sodeokmun-Gate-Seosomun/ENP023758', 'Sodeokmun Gate was one of the 4 minor city gates of Seoul. It was constructed during the Joseon Dynasty in the reign of King Taejong. Sodeokmun was torn down in 1914 during the Japanese colonial period under the pretext of ??urban planning.??No traces of Sodeokmun Gate remain today but a plaque marks the site of the gate.', NULL, NULL, 'Subway Lines 1/2  City Hall Station  Exit 9,  300m', 37.5617752, 126.9740631, NULL, NULL, NULL, 5),
	(109, 'Sayuksin Park', '06902  191 Noryangjin-ro, Dongjak-gu, Seoul', 'https://english.visitseoul.net/attractions/Sayuksin-Park-EN/ENP004513', 'Sayuksin Park is located atop a hill between the Hangang River and Noryangjin Station. The park encompasses the historic Sayuksinmyo Tombs and the surrounding hilly area. The tombs hold the designation of Seoul Cultural Asset No. 8 and they are the burial site of seven Korean loyalists to the King Danjong, 6th king of the Joseon Dynasty. King Danjong was forced to abdicate by his uncle, who then assumed to the throne to become King Sejo. Seong Sam-Mun, Park Paeng-Nyeon, Ha Wi-Ji, Yi Gae, Yu Seong-Won, Yu Eung-Bu, and Kim Mun-Gi who opposed King Sejo and were buried here by the Hangang River.', 'Daily 09:00 - 18:00', NULL, 'Subway Line 9  Nodeul Station  Exit 1,  432m', 37.5138394, 126.9481858, NULL, NULL, NULL, 5),
	(110, 'Kyungguksa', '02705  113-10 Bogungmun-ro, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-kgtemple/ENPkxi16h', 'Gyeongguksa Temple, nestled on the eastern slopes of Samgaksan (now known as Bukhansan), is a historic temple founded in the late Goryeo period. Renowned for its scenic mountain surroundings and fresh spring water, it attracts many visitors. The temple complex has 17 buildings, including Geungnakbojeon (Hall of Supreme Bliss), Yeongsanjeon, Myeongbujeon, Gwaneumjeon, and Sibangseonwon. Geungnakbojeon houses the Amitabha Buddha triad, along with wooden Buddhist paintings (designated as Treasure No. 748), Shinjungtaenghwa, and Palsangtaenghwa. Sibangseonwon offers a weekly Sunday meditation session, and the temple also hosts temple stay programs at Hwanheodang and Manwoldang. As one of Seoul\'s significant temples, Gyeongguksa was frequently visited by former President Syngman Rhee. During his tenure as Vice President, Richard Nixon of the United States visited the temple and later described it as one of his most memorable experiences in his memoirs, even including a photograph of his visit.', NULL, NULL, 'Subway  Ui-Sinseol Line  Bukhansan Bogungmun Station  Exit 2,  252m', 37.6134248, 127.0044017, NULL, NULL, NULL, 5),
	(111, 'Donuimun Gate (Seodaemun)', '170 Sinmunno 2(i)-ga, Jongno-gu, Seoul, Republic of Korea', 'https://english.visitseoul.net/attractions/Site-of-Donuimun-Seodaemun/ENP023759', 'Donuimun Gate was one of the four minor city gates to Seoul and it stood at the Joseon-era western boundary to the city. Today, the area where the gate stood is now known as Seodaemun. The gate was constructed during the Joseon Dynasty and stood for centuries before being destroyed in 1915 during the Japanese colonial period.', '24 hours', 'Monday', 'Subway Line 5, Seodaemun Station, Exit 4, 262m', 37.5686212, 126.9684764, NULL, NULL, NULL, 4),
	(112, 'Jongmyo Shrine', '03135  157, Jong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Jongmyo/ENP000507', 'Jongmyo is a royal shrine dedicated to the performance of ancestral rites for the deceased kings and queens of the Joseon Dynasty. Being the place where the royal ancestral tablets are enshrined, Jongmyo\'s atmosphere is solemn and sacred rather than splendid like the royal palaces. The simple and elegant buildings of this shrine have faithfully kept their original forms since the 16th century. Jongmyo is made up of Jeongjeon (the main hall), Yeongnyeongjeon (the hall of eternal peace), and auxiliary buildings such as Jeonsacheong, Eosuksil, Hyangdaecheong and Sindang. Jeongjeon, the main hall of Jongmyo, is a place steeped in royal history and is highly esteemed for its outstanding architecture. It is said to be the world\'s longest single wooden structure with a length measures 109 meters. The main hall is an outstanding example of traditional Korean architecture. Jongmyo was designated as a UNESCO World Cultural Heritage site together with Jongmyo Jerye and Jongmyo Jeryeak. Jongmyo Jerye is the royal ancestral ritual and has been performed for 600 years. The court music performed during the ritual is the Jongmyo Jeryeak.  ', 'Monday, Wednesday to Friday: Timed Tours (Enter at designated times, accompanied by a guide, and exit together as a group)\n- Korean Guided Tour Times: 9:20 / 10:20 / 11:20 / 12:20 / 13:20 / 14:20 / 15:20 / 16:20 / (March to September) 16:40 *Duration: 1 hour\n- English Guided Tour Times: 10:00 / 12:00 / 14:00 / 16:00\n- Japanese Guided Tour Times: 09:30 / 11:40 / 13:40 / 15:40\n- Chinese Guided Tour Times: 11:00 / 15:00\n\nRegular Admission on Saturdays, Sundays, Public Holidays, and the last Wednesday of every month:\n- February to May, September to October: 09:00-18:00 (Last entry at 17:00)\n- June to August: 09:00-18:30 (Last entry at 17:30)\n- November to January: 09:30-17:30 (Last entry at 16:30)\n(??Please refer to the website for detailed information.)', 'Tuesdays', 'Subway Lines 1/3/5  Jongno 3-ga Station  Exit 8,  220m', 37.5725752, 126.9939103, NULL, NULL, NULL, 5),
	(113, 'Sulla-gil Road', '03134  Seosulla-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Sulla-gil-Road/ENP001932', 'Sulla-gil Road runs through Jongno-gu and is known as Seoul\'s Historical Literary Trail. Sulla-gil is divided into eastern and western sections. Dongsulla-gil is the eastern section and Seoseulla-gil is the street\'s western section.', NULL, NULL, 'Subway Lines 1/3/5, Jongno 3(sam)-ga Station  Exit 7,  471m', 37.5750015, 126.9917431, NULL, NULL, NULL, 5),
	(114, 'Seonjeongneung (Tomb)', '135-090  1, Seolleung-ro 100-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Seonjeongneung-Tomb/ENP001414', 'Seonjeongneung is the name of Seolleung and Jeongneung combined, and it refers to the royal tombs of King Seongjong (the 9th king of the Joseon Dynasty), Queen Jeonghyeon (the second wife of King Seongjong) and King Jungjong (a son of the two). Seonjeongneung was designated as a UNESCO World Heritage site in 2009, enhancing its status as historic remains. It is easily accessible as it is situated close to Seolleung Station, Subway Line 2. It makes an ideal place for the public to enjoy a stroll.    Seolleung, the tomb of King Seongjong (reigned 1469-1494) was built in 1495; subsequently, the tomb of Queen Jeonghyeon (1462-1530) was built on the east side of Seolleung in 1530. Jeongneung, which is the tomb of King Jungjong (the 11th king of the Joseon Dynasty, reigned 1506-1544), was built in 1544, and was moved from its original site in Wondang, Goyang-gun, Gyeonggi-do, to this current location in 1562 by Queen Munjeong (the second wife of King Jungjong, 1501-1565). Seonjeongneung is designated as Historic Site No. 199 as well as being a UNESCO World Heritage site.  ', 'March - October, Daily 06:00 - 21:00 \nNovember - January, Daily 06:00 - 17:30 \nFebruary, 06:00 - 18:00', 'Closed Mondays', 'Subway Line 2 / Suin-Bundang Line  Seolleung Station  Exit 10,  444m\nSubway Line 9 / Suin-Bundang Line  Seonjeongneung Station Exit 3,  1,000m', 37.5071535, 127.0494254, NULL, NULL, NULL, 5),
	(115, 'Seoul Museum of Craft', '03061  4, Yulgok-ro 3-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Museum-of-Craft/ENP038092', 'Seoul Museum of Craft Art aims to be an open space where traditional crafts and modern crafts can come together to share the value of crafts and to be the key to unlocking the future of crafts. The museum features galleries on the "beginning of crafts" from mankind long ago, when clay was molded, engraved, and baked, as well as galleries and exhibitions that focus in on the technical, practical, artistic, and cultural values of crafts throughout time and space.', '10:00 - 18:00 (Last admission at 17:30)\nFri 10:00 - 21:00', 'Mondays, January 1st, Open on Public Holidays', 'Subway Line 3  Anguk Station  Exit 1,  141m', 37.5768583, 126.9835802, NULL, NULL, NULL, 5),
	(116, 'Seosomun Shrine History Museum', '04510  5, Chilpae-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Seosomun-Shrine-History-Museum/ENP030804', 'Seosomun Shrine History Museum is a history museum where visitors can go see the history of Catholicism in the late Joseon Dynasty.Passing the inscription of Lee Seung-hoon\'s "Wolrakjaecheonsusangjijin" (Moon Falls on the Water) at the entrance, visitors are led to an open plaza. The displays of artworks leads into the library and seminar rooms on the first floor. The special exhibitionhalland small assembly hall is located on the B2 level while the Consolation Hall, permanent exhibition, and Sky Square is located on the third basement floor.The most popular spot inside this attraction is Sky Square. Constructed so that the ceiling connects to the ground level and opens itself up to the sky, this space clearly symbolizes the theme of Seosomun Martyrs\' Shrine and the open pathway betweentheearth and sky.', 'Tuesday ~ Sunday 09:30 - 17:30', 'Closed Mondays', 'Subway Line 2/5  Chungjeongno Station  Exit 4,  417m', 37.5604178, 126.9686249, NULL, NULL, NULL, 5),
	(117, 'Seoul Baekje Museum', '05540  71, Wiryeseong-daero, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Baekje-Museum/ENP011610', 'The Seoul Baekje Museum is a history museum that was established at the prehistoric site of Baekje-era ruins in Songpa-gu, Seoul. The museum preserves and studies the relics of Baekje and prehistoric Korea. Visitors can learn more about Korea\'s history at the museum\'s 4D theater and exhibition halls. The Seoul Baekje Museum has an extensive collection of artifacts and relics, and there are also educational programs to participate in and enjoy. Learn about Korean history and cultures at the museum!', 'Weekdays 09:00 - 19:00\n Fri 09:00~21:00\nWeekend (November - February 09:00 - 18:00) (KST)', 'Closed Mondays & New Year\'s Day\n(Museum opens on holidays that fall on a Monday)', 'Subway Line 9  Hanseong Baekje Station  Exit 2,  363m', 37.5190092, 127.121633, NULL, NULL, NULL, 5),
	(118, 'Seoul Yangnyeongsi Herb Medicine Museum', '02566  26, Yangnyeongjungang-ro, Dongdaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Yangnyeongsi-Herb-Medicine-Museum/ENP004632', 'The Seoul Yangnyeongsi Herb Medicine Museum was established to preserve and pass on the history and knowledge of traditional Korean medicine. Fittingly, the museum is located across from the Seoul Yangnyeong Market, one of the most famous oriental medicine markets in Korea from which approximately 70% of the nation\'s oriental medicine is distributed. The museum collects, manages, and stores many artifacts and materials to exhibit. Visitors will be able to see everything from the herbs and plants used in traditional medicine, to antique medical records and tools. Admission to the museum is free.', 'March - October 10:00 - 18:00\nNovember - February 10:00 - 17:00\n??Last entry is 30 min. before closing', 'Closed Mondays, New Year\'s Day & national holidays', 'Subway Line 1, Jegi-dong Station  Exit 2,  320m', 37.5806549, 127.0376267, '우주메리  한방  서울  전통문화  체험  드라마촬영지 | 한방  전통문화  서울  드라마촬영지  체험  관광', 'Cosmic Mary | Strong Woman Gangnam Soon', 'https://blog.kakaocdn.net/dna/ddzMGD/btsQ5Bu1nw1/AAAAAAAAAAAAAAAAAAAAAJ6GbmZPnWBwfca9bRwYdSbf5FZLzCdfX0P6P1sgNiLB/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=EPjV5pxMgj%2BcLURcA1bu8iAI2mo%3D | https://blog.kakaocdn.net/dna/T7pcV/btsyzcMxlcR/AAAAAAAAAAAAAAAAAAAAAHsr3eM5S_DopChgaR-pWKiyYJ67nZsSEien4lMoNuX9/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=MQ%2BwkBcQekRX6ZznBmA2fiXyTVw%3D', 5),
	(119, 'Kim Geun-tae Memorial Library-Archives', '01301  14, Dobongsan-gil, Dobong-gu, Seoul', 'https://english.visitseoul.net/attractions/Kim-Geun-tae-Memorial-Library-Archives/ENP041903', 'Kim Geun-tae Memorial Library-Archives which is located at the corner of the way going to Bukhansan National Park, as a Larchiveum, it is a library to read a book but at the same time, it\'s a museum that has a story of democracy and human rights, and also an art gallery to appreciate art works. A courtyard, which was naturally made at the center which was created by connecting the both ends of the two buildings with the bridge, is the most opened space in Kim Geun-tae Memorial Library-Archives and it\'s a space where you can directly feel the sunlight and the wind. As a library and an art gallery, the installation work is located on the courtyard so you can see an art work in the nature. At the rooftop called \'Sanbaramgil\',  various plays and events will be held with the background of the nature.', 'Daily 09:00 ~ 20:00\nWeekends 09:00 ~ 17:00', 'Every Monday, National Holiday', 'Subway Line 1/7   Dobongsan Station  Exit 1,  300m', 37.6905052, 127.0423388, NULL, NULL, NULL, 5),
	(120, 'SeMA Museum of Photography', '01411  SeMA Museum of Photography, 68 Madeul-ro 13-gil (Changdong), Dobong-gu, Seoul', 'https://english.visitseoul.net/attractions/SeMA-photo-museum/ENPl3j0oy', 'The SeMA Museum of Photography, newly opened in Changdong, Dobong-gu, Seoul, is a branch of the Seoul Museum of Art and the first and only public art museum in Korea specializing in photography, established after more than a decade of preparation. The museum plans to continue diverse activities to become a new center for photographic art in Korea and Asia through creative and experimental exhibitions and programs encompassing the entire photography culture and in-depth research, collection, and preservation activities.Notably, the museum is equipped with facilities where visitors can experience the influence and artistic value of photography, including exhibition halls, education rooms, darkrooms, a photo library, and a photobook café for educational programs covering all age groups.The architecture was designed by Austrian architect Mladen Jadric (representative of Jadric Architektur ZTGmbH) and 1990 Urban Architecture (representative Yoon Geun-ju), who visualized and implemented the pixel of photography, which is a picture drawn with light.', 'Tuesday-Friday 10:00 AM-8:00 PM\nSaturday, Sunday, Holidays\nSummer (March-October) 10:00 AM-7:00 PM\nWinter (November-February) 10:00 AM-6:00 PM\nCulture Day (last Wednesday of each month) 10:00 AM-10:00 PM', 'Closed on January 1 and every Monday * Open on Mondays that fall on holidays', 'Subway Line 1/4, Changdong Station, Exit 1, 264m', 37.6555398, 127.0488414, NULL, NULL, NULL, 5),
	(121, 'Kukje Gallery', '100-200  54, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Kukje-Gallery/ENP003241', 'The Kukje Gallery is one of Korea\'s major art galleries and visitors can see artworks from new and established artists. Founded in 1982, the Kukje Gallery exhibits works from prominent foreign artists, but the gallery also exhibits and fosters promising Korean artists. Enjoy incredible contemporary art at the Kukje Gallery.', '* Monday - Saturday 10:00 - 18:00 (KST)\n* Sundays & National Holidays 10:00 - 17:00 (KST)', NULL, 'Subway Line 3  Anguk Station  Exit 1,  812m', 37.5807226, 126.9808479, NULL, NULL, NULL, 5),
	(122, 'National Museum of Art at Deoksugung Palace', '04519  99, Sejong-daero, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Museum-of-Art-Deoksugung-Palace/ENP001707', 'The National Museum of Modern and Contemporary Art at Deoksugung opened in 1998 as an annex of the National Museum of Modern and Contemporary Art, Korea. The museum building, Seokjojeon Hall, is located at Deoksugung Palace. Seokjojeon Hall is an exquisite example of Western architecture from the early 20th century. It is the only Korean palace to have an outdoor garden and fountain designed in a Western style. The museum??s location inside the palace means that many visitors choose to combine their visit with a tour of Deoksugung. Jeongdong Park, the Seoul Museum of Art, and Namdaemun Market are some of the nearby tourist attractions. Admission fees vary depending on exhibition but visitors will be able to see beautiful works of art from Korean and international artists.', 'Tuesdays, Thursdays, Fridays & Sundays 10:00 - 19:00\nWednesdays & Saturdays 10:00 - 21:00\n* Last entry is 1 hour before closing.', 'Closed Mondays & New Year\'s Day', 'Subway Lines 1/2  City Hall Station  Exit 1,  72m', 37.5674022, 126.9754992, NULL, NULL, NULL, 5),
	(123, 'Seodaemun Museum of Natural History', '03718  51, Yeonhui-ro 32-gil, Seodaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Seodaemun-Museum-of-Natural-History/ENP002613', 'p { text-align: justify; word-spacing: 2px; }  The four-story building of the Seodaemun Museum of Natural History was the first public museum of natural history in Korea. Opened in 2003, the museum displays the origins of life on earth through a variety of real specimens of minerals, rocks and fossils, and through models, including life size models of dinosaurs, from all over the world. The museum is a fun and family-friendly attraction.', '* March to October \nWeekdays 09:00 ??18:00 & Weekends 09:00 ??19:00\n* November to February\nWeekdays 09:00 ??17:00 & Weekends 09:00 ??18:00\n\n(Last entry 1 hour before closing)', 'Closed Mondays, January 1st, Lunar New Year & Chuseok', 'Subway Line 2, Sinchon Station Exit 3, take Seodaemun 03 bus from Sinchon Station stop, get off at Seodaemun Natural History Museum Entrance stop, 283m', 37.576673, 126.9374741, NULL, NULL, NULL, 5),
	(124, 'Reopening of Dongdaemun History Museum Exhibition Hall', '04566  281, Eulji-ro, Jung-gu, Seoul  (Dongdaemun History & Culture Park)', 'https://english.visitseoul.net/attractions/exhibitionhallreopening/ENP026206', 'The Dongdaemun History Museum, operated under the Seoul Museum of History, reopened the doors to its permanent exhibition hall following the two-year renovation project on Tuesday, August 11, 2020. The entire, all-new remodeled interior floor is set with carvings and gobo projectors that capture the blueprint of the excavation site of historical remains by layer to emulate the historical, figurative layers that are stacked upon each other at this very geographical site. The exhibition is characterized into the following four different themes: I. Military Training Administration & Lower Directorate; II. City Wall Floodgates; III. Two Centuries of Change; and IV. Excavated History. There are also various, fun programs for children within the exhibition and hands-on space provided that feature sand-crafting, 3D photo zones, and more.', 'Daily 10:00 - 18:00', 'Closed Mondays & New Year\'s Day', 'Subway Lines 2/4/5  Dongdaemun History & Culture Park Station  Exits 1/2,  356m', 37.5660286, 126.9954924, '선재업고튀어  동대문디자인플라자  문화행사  야경  서울여행  KdramaTrip | 드라마촬영지,  스토리,  야경,  산책,  카페 | 동대문디자인플라자,  촬영지,  야경,  전시,  쇼핑,  식사 | 디자인플라자,  촬영지,  문화행사,  예술적분위기,  사진촬영,  전시', 'Let\'s carry Sunjae and run | Let\'s grab him by the collar | North Star | two or two', 'https://blog.kakaocdn.net/dna/cHzh74/btsGt9omBgJ/AAAAAAAAAAAAAAAAAAAAAF3rCKzBTv36qp1AYSW7n-bgBdJom3zcyABTGFDJwJmq/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=oz0aAk10sH39H2vW48m8q%2BrXWMw%3D | https://blog.kakaocdn.net/dna/bpYZzj/btsF56LOEfK/AAAAAAAAAAAAAAAAAAAAAPNJSes4-0Jrx0KhEeTYCVtDS-vXMufI5deD1-OYnps1/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=NQBkVgwUNAnCsjoou6JXIAzQ1Ig%3D | https://blog.kakaocdn.net/dna/pzpbh/btsQr3NdCgj/AAAAAAAAAAAAAAAAAAAAAHyvlP0qx07FCvSmixTXi3uMjiGrQHVArImxz3va6-28/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=O59876r66VSYuu0yCczh6u0P68s%3D | https://blog.kakaocdn.net/dna/cI1w09/btsyV0LOI8x/AAAAAAAAAAAAAAAAAAAAAKSfopKQZ_UYlsPly1sf5-e80dQHpS9O_wLLCIx-en22/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=nwIJN%2FZEPQYyu76t%2F4OKXUgc95Q%3D', 4),
	(125, 'Amore Pacific Museum of Art (APMA)', '04386  100, Hangang-daero, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/Amore-Pacific-Museum-of-Art-APMA/ENP030803', 'p{ text-align:justify; word-spacing:2px; }Amore Pacific Museum of Art (APMA) is a newly opened museum inside Amore Pacific\'s Yongsan headquarters. Aiming for "an open space to find beauty in the ordinary", this museum was established as a space for fostering open communication. To this end, the museum collects, studies, and exhibits anicent Korean and contemporary arts, also supporting researchers, academic societies, and young writers in the process. The basement floor features an exhibition showcasing ancient Korean art and contemporary art. Connecting the first three floors, the "Atrium" features the museum lobby, museum shop, another exhibition space called "APMA Cabinet," and a library for museums around the world (apLAP).', 'Daily 10:00 - 18:00', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok', 'Subway Line 4  Sinyongsan Station  Exit 1,  84m', 37.5289732, 126.9692655, NULL, NULL, NULL, 5),
	(126, 'Horim Museum', '06021  317, Dosan-daero, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Horim-Museum-Sinsa/ENP005546', 'The Horim Museum is a privately-run art museum in Korea. The museum is comprised of three buildings, and the museum\'s five-story building hosts much of the art collection. The second, third, and fourth floors display antique and modern art as well as special exhibitions. On the last Thursday of each month, admission to the Horim Museum is free.', '10:30 - 18:00 (Last entry 17:00)\n\n- Temporarily closed from 7/27 to 9/1 due to exhibition change at the Shinsa branch', 'Closed Mondays,Sundays, January 1st, Lunar New Year & Chuseok', 'Subway Suin-Bundang Line  Apgujeong Rodeo Station  Exit 5,  635m', 37.52297, 127.0354307, NULL, NULL, NULL, 5),
	(127, 'Alive Museum', '06221  218, Teheran-ro, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Alive-Museum-en/ENP024389', 'Firstly opened/introduced the illusive art museum in Korea, called ??Trick Art Museum??in 2009. Since then, with continuously have been developing innovative digital technologies, we launch trick art theme park, ??Alive Museum?? and operate several branches world-widely.', NULL, NULL, 'Subway Line 2, Yeoksam Station, Exit 1', 37.501436, 127.0409532, NULL, NULL, NULL, 2),
	(128, '2Gil29Gallery', '06034  35 Gangnam-daero 158-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-2Gil29Gallery/ENPrisi5i', 'Located in the vibrant Garosu-gil area of Sinsa-dong, Gangnam, where diverse interests and dynamic Seoul culture converge, 2Gil29 Gallery has been actively introducing contemporary art to the public since its opening in 2015. The gallery has fostered active exchanges with prominent Korean artists such as Hong Jung-hee, Choi Sun-ho, Nam June Paik, Lim Young-kyun, and Kang Suk-young while also showcasing works by artists like Kwon Young-ho and Charlie Han to diversify the Korean art market.The gallery??s curatorial approach is based on a wide range of creative works, fostering a more positive and progressive discourse on art. Through deeper communication and interaction with art, it transcends mere visual and auditory engagement, offering meaningful aesthetic and spiritual exchanges with artists. This, in turn, enhances the value of their creative endeavors.In addition, 2Gil29 Gallery is committed to discovering and nurturing emerging talents such as upcycling artist Hong Ji-hee, singer-turned-painter Yoo Hyun-suk, and Kwon Jae-hyuk, a graduate of the University of the Arts London (UAL).', '10:00-18:00', 'Closed on Sundays and Mondays  \nClosed for Chuseok holidays from September 16 to 18', 'Subway Line 3 /Shinbundang Line  Sinsa Station  Exit 8,  460m', 37.5197804, 127.0214744, NULL, NULL, NULL, 4),
	(129, 'Heo Jun Museum', '07525  87, Heojun-ro, Gangseo-gu, Seoul', 'https://english.visitseoul.net/attractions/Heo-Jun-Museum/ENP001403', 'The Heo Jun Museum commemorates the life and works of the renowned Joseon-era doctor and scholar, Heo Jun. The museum is located in Gayang-dong near Guam Park and the neighborhood is known as the birthplace of Heo Jun. Visitors can see a range of items relating to Oriental medicine, items once owned by Heo Jun, and medical books. Some of the books on display were written out by Heo Jun\'s hand. A writing model of his most famous work, "Dongui Bogam," is on display and it is still an influential medical tome in Oriental medicine today.', '* March - October Weekdays 10:00 - 18:00 & Weekends/Holidays 10:00 - 17:00\n* November - February Weekdays 10:00 - 17:00 & Weekends/Holidays 10:00 - 17:00 (KST)\n??Ticketing stops 1 hour prior to closing.', 'Closed Mondays, Jan. 1st, Lunar New Year\'s Day & Chuseok', 'Subway Line 9  Gayang Station  Exit 1,  736m\nSubway Line 5  Balsan Station Exit 3, take bus 6657, 6630, 1002 and get off at Hanbogu Ammaeul Apartment, 243m', 37.5668685, 126.8529582, NULL, NULL, NULL, 5),
	(130, 'National Hangeul Museum', '04383  139, Seobinggo-ro, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/NationalHangeulMuseum/ENP035405', 'The National Hangeul Museum was opened on October 9, 2014, to create and promote the literary and cultural value of Hangeul, the nation\'s most significant cultural heritage. The National Hangeul Museum investigates, collects, and researches materials scattered around the country and abroad and shows the cultural diversity and future value of Hangeul through exhibitions. It is a place where Hangeul culture blossoms through education that aims for communication and empathy across generations and nationalities.', '10:00 - 18:00\n- Closed for construction from October 2024 to October 8, 2025', 'January 1, Lunar New Year\'s Day, Chuseok\n* Closed days of the Hangeul Library: Saturdays, Sundays, and public holidays (except Hangeul Day)', 'Subway Line 4 / Gyeongui Central Line  Ichon Station  Exit 2,  500m', 37.5268614, 126.9807315, NULL, NULL, NULL, 5),
	(131, 'Gallery Mosoon', '04518  Shina Memorial Hall, Room 203, 33 Jeongdong-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-mosoon/ENPxua216', 'Located on Jeongdong-gil, within the 100-year-old modern cultural heritage site ??Shina Memorial Hall,??this gallery showcases Korean crafts and art. It was established with the hope that visitors traveling from afar will feel that their journey to and from the gallery is part of the exhibition experience itself. Unlike other spaces in Shina Memorial Hall, the gallery has been remodeled with white cube walls and ceilings to give it a more contemporary feel. With each changing exhibition, the gallery introduces new playlists, scents, and furniture, creating a fresh experience every time. Come and appreciate Korean crafts in this cozy and serene space.', '12:00~18:00', 'Sun-Mon', 'Subway Line 1/2  City Hall Station  Exit 12,  507m', 37.5662178, 126.9721631, NULL, NULL, NULL, 4),
	(132, 'PKM Gallery', '03049  40, Samcheong-ro 7-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/PKM-Gallery/ENP002885', ' The PKM Gallery was established in 2001 and a range of art from diverse mediums can be found on display. Exhibitions include paintings, sculptures, and videos, while the gallery\'s goal is to be known for its quality of art. Prominent Korean and foreign artists fill the gallery\'s rosters and some of the more prominent names are Lee Bul, Jorge Pardo, Michael Joo, and Stephen Prina.', 'Tuesday - Sunday 10:00 - 18:00 (KST)', 'Closed Mondays', 'Subway Line 3  Anguk Station  Exit 1,  1.2km', 37.5840668, 126.9800992, NULL, NULL, NULL, 5),
	(133, 'ChoiManLin Museum', '02708  23, Solsaem-ro 7-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/ChoiManLin-Museum/ENP042352', 'Theelegant two-story, Western-style building was built in the 1970s. Here,sculptor Choi Man Lin created his world of art for about 30 years from 1988. Evenwith all its traces of artistry intact, it eventually grew to become the ChoiMan Lin Museum with the help of the Seongbuk-gu District and EMA Architects. Reborn as an art museum in2019, this building contains the traces of sculptor Choi Man Lin, which werepreserved through a remodeling method that protects the appearance of theexisting building as much as possible. Thisbuilding, which shows off its architectural beauty while maximizing itsfunction as an art museum, won the Excellence Award at the 2020 Public BuildingAwards of Korea.', 'Daily 10:00 ~ 18:00\nClosed for exhibition preparation (July 1 - September 3)', 'Closed Sundays & Mondays', 'Subway Uisinseol   Bukhansanbogukmun Station Exit 2,  438m', 37.6106735, 127.0043219, NULL, NULL, NULL, 5),
	(134, 'Ilmin Museum of Art', '03187  152, Sejong-daero, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Ilmin-Museum-of-Art/ENP002251', 'Ilmin Museum of Art is a private art museum that mainly exhibits Korean contemporary art. It was originally established to commemorate Kim Sangman, former president of the Donga Ilbo, one of Korea\'s leading media outlets. The museum\'s name was taken from Kim\'s pen name, Ilmin (meaning ??one people??or ??a nation united??in Korean). The museum is run by the Ilmin Cultural Foundation and a variety of special exhibitions and art classes are held throughout the year. The museum has a cafe and restaurant on the first floor.', 'Daily 11:00 - 19:00 KST', 'Closed on Mondays', 'Subway Line 5  Gwanghwamun Station  Exit 5,  16m', 37.5696329, 126.9784716, NULL, NULL, NULL, 4),
	(135, 'Kim Chong Yung Museum', '110-848  30, Pyeongchang 32-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Kim-Chong-Yung-Museum/ENP002066', 'The Kim Chong Yung Museum was established to honor the legacy and art of the modern artist Kim Chong Yung and to provide support to young artists. Kim was a pioneer of modern scultpure and the museum\'s main hall has a permanent exhibition with Kim\'s works and the new hall showcases artwork from new artists. Art and cultural classes are offered at the museum in two semesters during the calendar year. Admission to the Kim Chong Yung Museum is free.', 'March - October 10:00 - 18:00\nDecember - February 10:00 - 17:00 (KST)\n*Café Samiru Operating Hours: 11:00 - 21:00', 'Closed Mondays', 'Subway Line 3 Gyeongbokgung Station Exit 3,  take Bus 1711 and get off at Lotte Apartment, 365m', 37.6130277, 126.9776487, NULL, NULL, NULL, 5),
	(136, 'Arario Gallery Seoul', '03058  85 Yulgok-ro, Jongno-gu, Seoul Arario Gallery', 'https://english.visitseoul.net/attractions/ArarioGallery/ENP002388', 'Over the years, Arario Gallery Seoul has led the way in curating a harmonic fusion and variety of different art forms in Korea\'s art community through bold collaborations with international artistry that have never been attempted before. Also, the gallery takes the forefront in introducing artwork from today\'s more modern Korean artists having implemented an ongoing and structured system of exclusively-contracted artists. Currently, a wide range of artworks from artists native to India and Southeast Asia, who have yet to come to Korea despite having already experienced China\'s art community, are finally getting some spotlight in Korea. What\'s better is that with the help of continued promotional activity, the search and funding for up-and-coming talent in the respective regions is ongoing as well. Thanks to the gallery\'s efforts grounded in a system of exclusive artists displaying excellence; various collaborations with other galleries, both at home and abroad; introductions of varied artworks from numerous places around the world; and more, the Arario Gallery is set to play out its role as Asia\'s signature gallery that expands upon the possibilities for the future of Korea\'s art community while leading the market as well.      ', 'Daily 11:00 - 18:00 (KST)', 'Closed Sundays & Mondays', 'Subway Line 3  Anguk Station  Exit 3,  180m', 37.577831, 126.9885008, NULL, NULL, NULL, 3),
	(137, 'Artside Gallery', '03044  15 Jahamun-ro 6-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-artside/ENP72zzo1', 'Opened in Insadong in 1999, Artside Gallery operates under the motto ??art is the constant centralization of the surroundings.??It aims to bridge artists and the art market by providing various creative directions to domestic and international artists. Based on its beliefs and perspectives, Artside Gallery has been at the forefront of introducing the diverse works and artistic worlds of talented artists from Korea, China, Asia, Europe, and beyond to the domestic and international art scene. Since relocating to Tongui-dong in 2010, the gallery has continued to curate exhibitions that reflect its distinct identity. Through its participation in various domestic and international art fairs, Artside Gallery has opened the door to the global art market and solidified its position as an internationally recognized gallery.', 'Tues-Sat 10:00-18:00', 'Closed Sundays and Mondays  \nClosed for Chuseok holidays from September 16 to 18', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  282m', 37.5780837, 126.9728828, NULL, NULL, NULL, 5),
	(138, 'Seoul Children\'s Museum', '04991,  216, Neungdong-ro, Gwangjin-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Childrens-Museum/ENP011669', 'The Seoul Children??s Museum is a multipurpose learning space filled with activities and experiences for children to enjoy. The museum\'s overall theme is "children designing happiness," and there are educational programs available for children according to both age and theme. The building spans three stories above-ground and an additional 3 stories underground. There is a performance hall, an experience hall, and educational facilities. Additional facilities include a cafe and a nursing room.', 'Tuesday to Sunday: 10:00 - 18:00 (Last entry at 17:00)', 'Closed Mondays, New Year\'s Day & holidays', 'Subway Line 7  Children\'s Grand Park Station  Exit 1,  326m', 37.5488498, 127.0817656, NULL, NULL, NULL, 5),
	(139, 'Museum of Korea Straw and Plants Handicraft', '03075  45, Sungkyunkwan-ro 4-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Museum-of-Korea-Straw-and-Plants-Handicraft/ENP003332', 'The Museum of Korea Straw and Plants Handicraft is a private museum that was founded in 1992. The museum promotes cultural awareness of straw and its importance as a raw material in Korea. Straw was used in many different ways and is still used today in folk art. The museum\'s exhibitions display thousands of items made from straw including arts and crafts, tools, relics, and toys. The museum operates various educational programs for laypeople and professionals as well as workshops and crafting classes.', '10:00 ??17:00 KST', 'Closed Sundays, Mondays, New Year\'s, Lunar New Year & Chuseok', 'Subway Line 4  Hyehwa Station  Exit 4,  315m', 37.5849188, 126.9998471, NULL, NULL, NULL, 5),
	(140, 'Chojun Textile & Quilt Art Museum', '04630  66, Toegye-ro 18-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Chojun-Textile-Art-Museum/ENP006463', 'The Chojun Textile & Quilt Art Museum was established in 1998 and specializes in textile and quiltworks. It is the only museum in Korea which is devoted entirely to textiles. Examples of traditional Korean embroidery are on display and museum-goers can also enjoy seeing royal clothing from the Joseon Dynasty. Learn about Eastern and Western textile history and methods at the Chojun Textile & Quilt Art Museum.', 'Mon-Fri 10:00-17:00 (Last entry is 30 mins prior to closing)', 'Closed  Saturdays ~ Sundays & national holidays', 'Subway Line 4  Myeongdong Station  Exit 3,  324m', 37.5581444, 126.9842582, NULL, NULL, NULL, 5),
	(141, 'Seoul Arts Center - Seoul Calligraphy Art Museum', '06757  2406 Nambusunhwan-ro, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/SeoulCalligraphyMuseum/ENPx6grff', 'Located within the Seoul Arts Center, the Seoul Calligraphy Art Museum opened in 1988 alongside the Music Hall as the first museum in Korea dedicated to calligraphy. The four-story building houses three exhibition halls across two floors and two storage rooms. Its collection includes historical Korean calligraphy literature such as Geun-yeok Seohwa-sa and more than 1,300 modern calligraphy works from Korea and East Asia. Through continuous exhibitions, the museum conveys the heritage and culture of South Korean calligraphy and painting to visitors.', 'Tues-Sun 10:00-19:00', 'Monday', 'Subway Line 3, Nambu Bus Terminal Station (Seoul Arts Center) Exi 5, 1.4km', 37.4784816, 127.0125833, NULL, NULL, NULL, 5),
	(142, 'Bank of Korea Money Museum', '100-794  39 Namdaemun-ro, Jung-gu, Seoul  (Bank of Korea Building)', 'https://english.visitseoul.net/attractions/Bank-of-Korea-Money-Museum/ENP002730', 'The main building of the Bank of Korea provides extensive information on the manufacturing process of money and the development of the Korean economy. The collections is vast and there are over 20,000 pieces of Korean and foreign banknotes, coins and tokens on display. The museum consists of four exhibition halls and an information reference library. Admission to the Bank of Korea Money Museum is free.', '10:00 - 17:00 (KST)', 'Mondays, Lunar New Year, Chuseok', 'Subway Line 4  Hoehyeon Station  Exit 7,  310m', 37.5621502, 126.9799919, 'KdramaTrip,  Museum,  한국은행,  화폐박물관,  역사,  체험', 'Good luck', 'https://blog.kakaocdn.net/dna/cZNOCw/btr7eaC6nZG/AAAAAAAAAAAAAAAAAAAAAA_-55D-j5Z8sQBYJBkvQmQO98M5zrHbOkZAi1FHO3tg/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=KOfs5vvnWHHO8N8qTQ5CjGb%2BWnY%3D', 5),
	(143, 'Gallery Hyundai', '03062  14, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gallery-Hyundai-EN/ENP001694', 'Gallery Hyundai is a famous gallery located on Sagandong Gallery Street. The street is known for its many galleries, hence the name, yet Gallery Hyundai stands out from the crowd. The gallery exhibits major contemporary Korean artists, such as Park Su-Geun and Lee Jung-Seob, as well as many major foreign artists. The gallery also has a superb restaurant with a great wine selection.', 'Daily 10:00 - 18:00', 'Closed Mondays', 'Subway Line 3  Anguk Station  Exit 1,  595m', 37.5776755, 126.9811494, NULL, NULL, NULL, 3),
	(144, 'National Museum Of Modern And Contemporary Art: Changdong Residency', '01469  257, Deongneung-ro, Dobong-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Museum-Changdong-Residency/ENP002285', 'The Changdong Residency of the National Museum of Modern and Contemporary Art (MMCA) is an arts and cultural space that is designed to allow visitors to get more familiar with modern art. The museum offers various exhibitions, region-linked programs and educational programs. The residency space also provides art studios for Korean and international artists.', 'Weekdays 09:00 - 18:00\n* Please refer to the website as hours may be subject to change.', NULL, 'Subway Line 4  Suyu Station  Exit 1,  Bus 1127 or 1138, get off at the Foreign Exchange Bank stop, 120 m\nSubway Lines 1/4  Changdong Station  Exit 2,   Bus 1157, get off at the Foreign Exchange Bank stop, 120 m', 37.6413414, 127.0382367, NULL, NULL, NULL, 4),
	(145, 'Seoul Museum of Art (Seosomun Main Building)', '04515  61, Deoksugung-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Museum-of-Art-Seosomun/ENP001525', 'The Seoul Museum of Art (SeMA) opened in 1988 and has earned a reputation as one of Korea??s leading art venues with a series of world-famous exhibitions. Situated in the center of Seoul, its convenient location and outstanding collections attract large numbers of locals and tourists. The specially-designed building features large windows that fill the interior with natural light. This attracts not only tourists but also artists and even movie directors, some of whom have used the location for filming.      Since it was established in 1988, the main museum building has been relocated to Seosomun-dong in Seoul. The museum has a variety of annexes such as SeMA Gyeonghuigung, located on the historic site of Gyeonghuigung Palace, and the Nam Seoul Annex Building, which is situated in a building that was once the Belgian Embassy. The museum also runs the Naji Art Studio which offers workshops and financial support to new generations of Korean artists to nurture their creativity.      The beautiful Renaissance façade which forms the entrance to the museum was originally part of the Supreme Court, built in 1928. Today it is better known as the iconic image of the Seoul Museum of Art. In March 2006, the arch and the beautifully constructed museum building were designated as Cultural Property No. 237 in recognition of their great historical and architectural value.', '(March - October) Tuesdays - Thursdays 10:00 - 20:00  / Friday 10:00-21:00 / Weekends 10:00 - 19:00\n(November - February) Tuesdays - Fridays 10:00 - 20:00 / Friday 10:00-21:00 / Weekends 10:00 - 18:00\n??Culture Day\n- Museum main building, Buk Seoul Museum: last Wednesday of the month 10:00 - 22:00 (KST)', 'New Years Day\nClosed on Mondays', 'Subway Lines 1/2  City Hall Station  Exit 10,  264m', 37.5640718, 126.9745477, NULL, NULL, NULL, 5),
	(146, 'Hakgojae Gallery', '110-200  50, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Hakgojae-Gallery/ENP001871', 'Hakgojae Gallery is a modern art gallery and its motto is ??creation of the new by understanding the old.??The architecture of the gallery reflects this motto. The main building of Gallery Hakgojae was designed to look like a hanok, (a traditional Korean house), while the new hall was designed in a modern, 21st-century style of architecture. Though the two architectural styles are different, they harmonize beautifully. Hakgojae Gallery also has a branch in the Shanghai art district of Moganshan Road. Admission to the gallery is free.', 'Daily 10:00 ??18:00', 'Closed Mondays', 'Subway Line 3, Anguk Station, Exit 1, 751m', 37.5803283, 126.9802958, '드라마촬영지,  산책,  정독도서관,  로맨틱,  가을단풍', 'That\'s a black dragon', 'https://blog.kakaocdn.net/dna/GvDiI/btsMA4udVHk/AAAAAAAAAAAAAAAAAAAAAJ9PtPhVmQ_lw_3zTdX1jK4kH-zniamB-_uOJ7d9R28c/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=Vms9dQwUtgThWjYnqxSQ8lqYFO4%3D', 4),
	(147, 'Pace Gallery Seoul', '04348  Pace Gallery, 267 Itaewon-ro, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/pacegallery/ENPet80lf', 'Pace Gallery is one of the world??s foremost contemporary art galleries, representing some of the most influential artists of our time. It has also maintained decades-long relationships with the estates of artists such as Alexander Calder, Jean Dubuffet, Agnes Martin, Louise Nevelson, and Mark Rothko. Since its early years, Pace has supported artists associated with Abstract Expressionism and those working with light and space, establishing itself as a uniquely distinguished gallery across the United States. Today, Pace operates exhibition spaces worldwide, including two galleries in Chelsea, New York, as well as in London, Geneva, Berlin, Hong Kong, Seoul, Los Angeles, and Tokyo.', '10:00-18:00', 'Closed every Sunday and Monday', 'Subway Line 6, Hangangjin Station, Exit 1, 185m', 37.5384336, 127.0013658, NULL, NULL, NULL, 5),
	(148, 'Cheonggyecheon Museum', '04704  530, Cheonggyecheon-ro, Seongdong-gu, Seoul', 'https://english.visitseoul.net/attractions/Cheonggyecheon-Museum/ENP004693', 'The Cheonggyecheon Museum documents the history of the Cheonggyecheon Stream area. The museum spans 6 floors, with several exhibition halls, education facilities, and an auditorium. The museum also offers educational classes for children on the history and ecology of the stream. The building itself is characterized by its long glass exterior, designed to symbolize the flowing waters of the Cheonggyecheon Stream. Admission to the Cheonggyecheon Museum is free.', 'Daily 09:00 - 18:00 (KST)', 'Closed Mondays & January 1st\n??November - February: Closed Weekends & Holidays', 'Subway Line 2  Yongdu Station  Exit 5,  497m', 37.5701477, 127.0354132, NULL, NULL, NULL, 5),
	(149, 'Arario Museum in Space', '03058  83, Yulgok-ro (Wonseo-dong), Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Arario-Museum-in-Space/ENP020731', 'The Arario Museum in Space is a modern art museum that was established by the chairman of the Arario Corporation, Chang-il Kim. The building that houses the museum was designed by the famed Korean architect Kim Swoo-geun. Until he passed away in 1986, the building served as Kim\'s office and home. Today, the Arario Museum in Space calls the building home and the spaces are full of incredible modern art. This historic building is one of the most unique cultural spaces in Seoul.', '10:00 - 19:00 \n(Last entry at 18:00)', 'Closed Mondays', 'Subway Line 3  Anguk Station  Exit 3,  181m', 37.577738, 126.9883615, '드라마촬영지,  굿파트너,  차분한분위기,  서울여행,  특별한경험', 'Good Partner', 'https://blog.kakaocdn.net/dna/kLJ7F/btsIOmGZE4R/AAAAAAAAAAAAAAAAAAAAAGTZfirxoaZIszx218kTwns0Vy7XNYUvi40kL2CB-q78/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=Z3kk8jvyeA62gRRxaTtlKqB7%2FQ0%3D', 5),
	(150, 'Kyung Hee University Natural History Museum', '02447  26, Kyungheedae-ro, Dongdaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/KyungheeUniversityHistoryMuseum/ENP006957', 'Upon opening its doors in 1978, the Kyunghee University Natural History Museum served as a little respite of nature in the city that boasted of a collection of nearly 90,000 specimen on display. The museum was initially founded upon the purpose of realizing the Kyungee University founding ideology of "Creating a world of culture" grounded in the results that had been obtained through several years of studying nature. The effort continues to approach the distancing relationship between nature and humankind amid rapid societal changes and urbanization with a "respite of nature in the city" that provides a sense of living in harmony with nature. All six floors of the museum display easy-to-understand exhibits capturing a comparison between the current state of evolution and the process of transformation up to the present-day with specimen of different plants and animals, as well as various rocks from sedimentary to igneous and metamorphic rocks that were used for research purposes by specialized teams of professors in various fields. There are courses and tour programs offered to help understand and practice nature preservation and the importance of life within the framework of these exhibited specimen. The Kyunghee University Natural History Museum has collected numerous specimen since the 1940s, while possessing a collection of more recent domestic specimen that have already become extinct or show signs of endangerment. The museum offers the opportunity for children and adults alike to more systematically learn about the classification and ecosystems of animals and plants and prioritizes itself with the fervor of exploring nature, as well as the awareness of nature protection.', 'Daily 10:00 - 17:00', 'Closed weekends & holidays', 'Subway Line 1, Foreign Language University Station Exit 1,  1.1km\nSubway Line 1, Hoegi Station Exit 1,  1.2km', 37.5967122, 127.0513948, '대학  캠퍼스  드라마촬영지  고딕건축  밤풍경  추억 | 캠퍼스,  드라마촬영지,  경희대학교,  멜로무비,  사진찍기좋은곳 | KdramaTrip  CityBuilding  경희대학교  촬영지  북극성  건축물', 'a hundred memories | Melo Movie | North Star', 'https://blog.kakaocdn.net/dna/7Robm/dJMb9Qywtzv/AAAAAAAAAAAAAAAAAAAAAM1jzM-2LPBwTKFehVV_vKikH2eKtPRnA8mm8KiAeXR3/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=9YconSXy%2BB1mAHjsh4DjX3L0n90%3D | https://blog.kakaocdn.net/dna/bJsnP3/btsMk0rCZH9/AAAAAAAAAAAAAAAAAAAAADTIvUsR4t554_M5jQQw0QDo3Zs7gznDKoIy79-Zlwpy/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=pcMYG2uLlK6Bfgqf%2BaOferwKEt8%3D | https://blog.kakaocdn.net/dna/ckdbGn/btsQthjyRWH/AAAAAAAAAAAAAAAAAAAAAHWn3wj8hL8lbx-DlZMB_-KNLM82aR7dmsxLz3Q4UjY_/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=zX5fpD10mtbHTFZUh71EdwSqLkM%3D', 5),
	(151, 'Total Museum of Contemporary Art', '03004  8, Pyeongchang 32-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Total-Museum-of-Contemporary-Art/ENP003085', 'Located in a secluded residential area of Pyeongchang-dong overlooking Bukhansan Mountain, the Total Museum exhibits the best of contemporary Korean art. An outdoor performance stage and outdoor exhibition spaces at the museum offers scenic views as well as a wide variety of cultural events such as lectures and performances. The permanent collection includes sculptures, prints, paintings, videos, and illustrated books ranging from modern art to old masterpieces. The museum also holds special events, such as seminars, concerts and educational programs. Admission fees vary by event.', 'Tue - Sun, 13:00 - 18:00 (last entry at 17:30)', 'Closed Mondays, holidays & days of exhibition installation', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  (Take bus nos. 1020 or 1711 ??Get off at Lotte-Samsung Apartments stop)\nSubway Line 4  Gireum Station  Exit 3,  (Take bus nos. 7211 or 110 ??Get off at Lotte-Samsung Apartments stop)', 37.612099, 126.9757337, NULL, NULL, NULL, 5),
	(152, 'Gahoe Museum', '03056  52, Bukchon-ro, Jongno-gu, Seoul, Korea', 'https://english.visitseoul.net/attractions/Gahoe-Museum-EN/ENP018912', '??성??식 최신??코드  The Gahoe Museum is Korean folk art museum established by Yoon Yeolsu. The museum\'s exhibits Director Yoon\'s private collection of folk paintings and folk religious amulets. There are more than 2,000 folk paintings and craftworks on display and the museum aims to showcase and preserve Korean folk art. Visitors can also take folk painting lessons at the museum.', '10:00 - 18:00 KST\n\n* Last entry is 40 min. before closing\n* For activities, last entry is 1 hr. before closing', 'Closed Mondays', 'Subway Line 3  Anguk Station  Exit 2,  496m', 37.5814088, 126.9859967, NULL, NULL, NULL, 4),
	(153, 'An Jung-geun Memorial Hall', '04636  91, Sowol-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/An-Jung-geun-Memorial-Hall/ENP004281', 'The An Jung-geun Memorial Hall was established to memorialize the Korean patriot An Jung-geun. An fought for Korean independence from Japan and was ultimately executed by Japanese authorities for assassinating Ito Hirobumi in 1909. Ito was a major force behind the Japanese annexation of Korea. The memorial hall is composed of 12 exhibition halls and galleries, an auditorium, a reference library, and a rest area. In addition to exhibition information about An\'s life and some of his calligraphy, the memorial hall also hosts the An Jung-guen Academny and other events each year. Events include visits to historic sites abroad that were important to independence movements and calligraphy contests. Admission to the An Jung-geun Memorial Hall is free.', 'March to October: 10:00 - 18:00\nNovember to February: 10:00 - 17:00 (KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', 'Subway Line 4  Hoehyeon Station  Exit 3,  689m', 37.554261, 126.9813393, NULL, NULL, NULL, 5),
	(154, 'Korean National Police Heritage Museum', '03166  162 Songwol-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Korean-National-Police-Heritage-Museum/ENP020549', 'Established Oct. 14, 2005, the Korean National Police Heritage Museum is the best place in Seoul to go to learn about the history of the police force in Korea. Museum-goers can try hands-on experiences of what the police do and aims to expand citizens understanding of and encourage children\'s dreams of becoming police officers. The Police Museum, which moved to it\'s new location in 2021, aims to become a window of communication between the police and the public with trendy exhibitions and hands-on experience facilities.', 'KST 09:30-17:30', 'Closed Mondays, New Year, Lunar New Year, and Chuseok holidays', 'Subway Line 3, Dongnipmun Station, Exit 3,  363m', 37.5722849, 126.9638862, NULL, NULL, NULL, 4),
	(155, 'Museum of Medicine', '03080  101, Daehak-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Museum-of-Medicine/ENP000846', 'The Museum of Medicine is a medical museum located at Seoul National University\'s medical school. The museum building was once a hospital (Daehanuiwon Hospital) and it dates back to the early 20th century. The building features a neo-baroque clock tower. The museum also houses research facilities that are used by the Seoul National University Hospital.', '* Weekdays 09:00 - 18:00 KST\n* Saturdays 10:00 - 15:00 KST\n* Group visits require advanced reservations via phone', 'Closed Sundays, national holidays, May 1 & October 15', 'Subway Line 4  Hyehwa Station  Exit 3,  452m', 37.5803846, 127.0005255, NULL, NULL, NULL, 4),
	(156, 'Seoul Metropolitan Archives', '03371  7, Tongil-ro 62-gil, Eunpyeong-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Metropolitan-Archives/ENP034857', 'As an public archive providing records services for the public, the Seoul Metropolitan Archives collects a number of records and memoirs tracing the history of the city government, as well as the residents of Seoul, and specializes in the preservation and management of such records. The SMA also plans and operates several public programs, including exhibitions, openings, and more.', 'Daily 10:00 - 17:00 (KST)', 'Closed Mondays', 'Subway Lines 3 / 6  Bulgwang Station  Exit 2,  370m', 37.6073832, 126.9347185, NULL, NULL, NULL, 4),
	(157, 'National Gugak Museum', '06757  2364, Nambusunhwan-ro, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Gugak-Museum/ENP011893', 'The National Gugak Museum is Korea\'s first dedicated gugak (traditional Korean music) museum. The museum collection has approximately 6,000 items that relate to gugak. Visitors can see musical instruments, photos, documents, and much more at the museum. There are six exhibition halls that are organized by theme and the displays showcase everything from videos to instruments.', 'Daily 10:00 - 18:00 (Last Entry at 17:30)', 'Closed Mondays & New Year\'s Day', 'Subway Line 3  Nambu Bus Terminal Station  Exit 5,  1.2km\nSubway Line 2  Bangbae Station, Exit 1,  1.5km', 37.4784816, 127.0125833, NULL, NULL, NULL, 5),
	(158, 'National Folk Museum of Korea', '03045  37, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Folk-Museum-of-Korea/ENP001644', 'The National Folk Museum of Korea displays the culture and folk history of the Korean people from prehistoric times to the end of the Joseon Dynasty. Since its establishment, the museum has dedicated itself to studying and researching the folk history of Korea, and collecting artifacts from different Korean regions in order to pass on an insight into the lifestyle and culture of Koreans. The museum achieves this by offering visitors various seminars, exhibitions, performance art, concerts and hands-on activities.      Located on the grounds of Gyeongbokgung Palace, the National Folk Museum of Korea is well known for its beautiful architecture. The building was constructed in the traditional Korean style comprising several stories with a pagoda on top. The three main exhibition halls at the museum cover different aspects of Korean life, as well as displaying various local costumes, musical instruments and festivals.', '09:00 - 18:00 from March to October \n09:00 - 17:00 from November to February \nExtended evening hours: 09:00 to 20:00 on Saturdays between March and October. \n(No extended evening hours from November to February)', NULL, 'Subway Line 3 Anguk Station Exit 2, 780m', 37.5780505, 126.977124, NULL, NULL, NULL, 4),
	(159, 'Gallery Art Zone at the National Museum of Modern and Contemporary Art', '03062  30, Samcheong-ro, (Sogyeok-dong) Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gallery-Art-Zone/ENP016792', 'The Gallery Art Zone is located on the 1st floor of MMCA and is about 570??in size There are three zones and five gallery spaces. The Gallery Art Zone was borne out of a collaboration with the National Museum of Modern and Contemporary Art (MMCA) and Hyundai Motor Company. The Gallery Art Zone??s aim is to expand the breadth of audiences when it comes to art. Art shouldn??t just be for walls and showcases. The works on display in the Gallery Art Zone can be bought, and regular visitors can bring a piece of art or design home. The Gallery Art Zone shows different aspects of Korean contemporary art and design in each zone. The first zone (Gallery 1) exhibits Korean design and sells works by promising artists, particularly those from the craft sector. The second zone (Galleries 2 and 3) exhibits and sells cultural products that were developed for MMCA, or on display at MMCA. The third zone (Galleries 4 and 5) displays and sells textiles, fashion products, and art books. Additionally, in part as a result of Hyundai Motor Company??s sponsorship, many art related events and special events will be held at the Gallery Art Zone.', '* Mondays, Tuesdays, Thursdays, Fridays & Sundays 10:00 - 18:00 \n* Wednesdays & Saturdays 10:00 - 21:00 (KST)', NULL, 'Subway Line 3, Anguk Station, Exit 1,  764m', 37.5796225, 126.9809343, NULL, NULL, NULL, 3),
	(160, 'Modern History Memorial Hall', '01013  114, 4.19-ro, Gangbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Modern-History-Memorial-Hall/ENP027105', 'Modern History Memorial Hall was built for the purpose of remembering and spreading awareness of Korean democracy and past independence movements. Spreading awareness of Korean forefathers who??ve valued and fought for ideals of freedom, equality, and democracy, the institution hopes to deliver a message that Korea is the land where forefathers dreamt of independence and achieved it.', '09:00~18:00(Last entry at 16:30)', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok\n(* If Monday falls on a public holiday, Tuesday is closed as well.)', 'Subway Line 4, Suyu Station Exit 4,  take (village) Gangbuk 01 ??Get off at Shinsung Villa stop', 37.6410665, 127.0004213, NULL, NULL, NULL, 4),
	(161, 'National Library of Korea', '06579  201, Banpo-daero, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Library-of-Korea-EN/ENP011010', 'The National Library of Korea collects and stores Korea\'s literary and intellectual heritage. Located by Seocho Park, the library has a main building and an annex. The library houses millions of volumes and visitors can learn more about the library through the visitor tour program.', 'Daily 09:00 - 18:00 (KST)\n* Night Hours 18:00 - 22:00 (KST)\n(Note: Hours may vary for different resource rooms)', 'Closed every 2nd/4th Monday & public holidays\n* Please refer to the website for more details.', 'Subway Line 3/7/9 Express Bus Terminal Station Exit 5, 812m\nSubway Line 2 Seocho Station Exit 6, 771m', 37.4970403, 127.0020168, NULL, NULL, NULL, 5),
	(162, 'Ground Seoul', '03145  26, Insadong 9-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-groundseoul1/ENP024613', 'Ground Seoul is a versatile cultural space spanning 4958 square meters. It features a distinctive underground layout that allows for beautiful natural lighting within the exhibition areas. This space is designed to seamlessly blend exhibitions, performances, events, and parties, making it a hub for artistic expression. Ground Seoul aims to establish itself as a landmark cultural venue in Insadong, where anyone can easily engage with and appreciate the arts.', '11:00~18:00 (Vary per exhibition)', 'Vary per exhibition', 'Subway Line 1, Jonggak Station, Exit 3-1, 301m', 37.5734665, 126.9836163, NULL, NULL, NULL, 5),
	(163, 'Kyung Hee University Central Museum', '02447  56-3 Kyungheedae-ro 1na-gil, Dongdaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Central-Museum-of-Kyunghee-University/ENP006924', 'Opened in 1955, the Kyunghee University Central Museum is the first archaeology and history museum of Korea. The museum emphasizes the importance of teaching, preserving, and recording historical artifacts. The museum is home to the country\'s finest Siberian artifacts collection. Admission to the museum is free and there are also regular cultural programs throughout the year.', 'Weekdays 10:00 - 17:00', 'Closed weekends, national holidays & May 18th (University founding day)', 'Subway Line 1 Hoegi Station Exit 1,  1.1km', 37.5936028, 127.0503564, NULL, NULL, NULL, 3),
	(164, 'Kyungin Museum of Fine Art', '03146  11-4 Insa-dong 10-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Kyung-In-Museum-of-Fine-Art/ENP002011', 'Founded in 1983 by Gyeongin Lee Geum-hong, Gyeongin Museum of Art is not only a cultural space for artists but also a widely known tourist attraction. The Gyeongin Museum of Art reflects the founder\'s desire to show that the museum is not the exclusive property of a particular group, but a place where people of all ages and backgrounds can feel at home. The interior consists of six exhibition halls, including an atelier, an outdoor garden, and a traditional tea garden, and concerts are held in the outdoor garden in spring and autumn.', '10:00~18:00', 'Closed on New Year??s Day, Lunar New Year??s Day, and Chuseok', 'Subway  Line 3  Anguk Station  Exit 5,  354m', 37.573207, 126.9865759, NULL, NULL, NULL, 5),
	(165, 'Korean Catholic Martyrs??Museum', '04085  6, Tojeong-ro, Mapo-gu, Seoul', 'https://english.visitseoul.net/attractions/Korean-Catholic-Martyrs%E2%80%99-Museum/ENP029394', 'To publicize the persecution of Catholic martyrs who lost their lives during the Byeongin Persecution back in 1866, Jeoldusan Matyrs\' Memorial Hall changed its name into Korean Catholic Martyrs??Museum. Its facilities include a pilgrimage church, a sacred r ??oom containing the remains of a martyr, a museum showcasing Catholic records, documents, and relics, and an outdoor exhibition.', 'Daily 09:30 - 17:00', 'Closed Mondays', 'Subway Line 2/6  Hapjeong Station  Exit 7,  500m', 37.5446232, 126.910816, NULL, NULL, NULL, 5),
	(166, 'Children\'s Museum of the National Museum of Korea', '04383  137, Seobinggo-ro, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/ChildrensMuseum/ENP020547', 'The Children\'s Museum of the National Museum of Korea showcases the cultural heritage of Korea. The Children\'s Museum is located within the National Museum of Korea.    Children can learn about the way of life and wisdom of people in ancient times through fun activities and exhibits. There is a reproduction of an ancient Korean house from the Goguryeo era and even a reproduction of a pottery workshop and kiln on display. Additionally, children can even try on historical clothing, accessories, and golden crowns.    The museum exhibits reproductions of artifacts that are on display in the National Museum of Korea. Children will be able to learn and gain a deeper understanding of Korean cultural heritage through fun, hands-on experiences.', 'Daily 10:00 - 18:00 (KST)\n* Limited extended hours (Last Wednesday of every month)', 'Closed New Year\'s Day, Lunar New Year & Chuseok', 'Subway Line 4 / Gyeongui Central Line  Ichon Station  Exit 2,  309m', 37.5268614, 126.9807315, NULL, NULL, NULL, 3),
	(167, 'Tteok Museum', '110-360  71, Donhwamun-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/The-Tteok-Rice-Cake-Museum/ENP002037', 'The Tteok Museum is a museum and experience center where visitors can learn about traditional Korean food. Permanent Exhibition Hall No. 1 showcases the different tteok (rice cakes) that were prepared and eaten on Korean holidays. Also on display are the various tools that were needed to create the tteok. Permanent Exhibition Hall No. 2 has displays on the tteok that were eaten during the daily life of a Korean person. From birth, to death, and all the occasions in between, the tteok that were or are served are on display at the Tteok Museum. The museum also offers classes on how to make tteok and other traditional Korean food.', 'Daily 10:00 - 18:00', 'Closed Sundays, Lunar New Year, Chuseok', 'Subway Lines 1/3/5  Jongno 3(sam)-ga Station  Exit 7,  286m', 37.5748919, 126.9906409, NULL, NULL, NULL, 4),
	(168, 'SJ. Kunsthalle', '06054  5, Eonju-ro 148-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/SJ-Kunsthalle-en/ENP024732', 'SJ. Kunsthalle was made as a cultural-artistic platform for meetings and discussions, providing everyday art linked programs, such as exhibitions, parties, performances, fashion shows, and workshops.', NULL, NULL, 'Subway Line 7/ Suin Bundang Line  Gangnam-gu Office Station  Exit 3,  1km', 37.5205498, 127.0348965, '하이라키  SJ쿤스트할레  촬영지  현대건축  예술전시  서울 | 지옥에서온판사,  촬영지,  SJ쿤스트할래,  서울여행,  K드라마팬', 'Hi-Laki | a judge from hell', 'https://blog.kakaocdn.net/dna/benuZ2/btsHRlWdzht/AAAAAAAAAAAAAAAAAAAAACtfdslPYDBek2WwnMEpgfrpWPEZdknFCoe_wfm4FB5U/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=TE0nyKFmYo%2Fv4hLcQotgIqN%2BgpE%3D | https://blog.kakaocdn.net/dna/bs3Ifr/btsKdDZzHfV/AAAAAAAAAAAAAAAAAAAAAHOTfHuC5Kc_WtNtQGVN-roXLDn8F2SmiCNFre-9XcMY/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=q4agzywqtn30TKkiOsdizrkFBh4%3D', 5),
	(169, 'Son Kee Chung Memorial Hall', '04501  101, Songijeong-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Son-Kee-Chung-Memorial-Hall/ENP006995', 'The Son Kee Chung Memorial Hall honors the athlete and gold medalist, Son Kee Chung. The memorial hall opened on October 14th, 2012, marking the centennial anniversary of Son\'s birth. The memorial hall was once a school and was in fact Son\'s alma mater. Son Kee Chung was a gold medalist in the 1936 Berlin Olympics Marathon. Though Son Kee Chung was registered as a Japanese athlete, due to the Japanese occupation of the Korean peninsula, his victory was cherished and praised by Korean nationals. Visit the memorial hall to learn more about Son\'s life and how he won his gold medal. Admission is free and there are sometimes special exhibitions.', '10:00 - 18:00 (KST)\n* Last entry is 1 hr. before closing time.', 'Closed Mondays & national holidays', 'Subway Line 2/5  Chungjeongno Station  Exit 5,  753m', 37.5555781, 126.9647417, NULL, NULL, NULL, 5),
	(170, 'The National Museum of Korea', '04383  137, Seobinggo-ro, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/NationalMuseumofKorea/ENP000433', 'As a living vestige of Korea\'s history and culture, The National Museum of Korea is home to today\'s best collection of history and culture deeply rooted within the Korean people. Regular exhibitions and education programming speak of the numerous anecdotes of the nearly 420,000 collected historical artifacts with thousands of years of history, while also offering realistic digital animations and VR technology to provide a more impactful experience. The museum includes everything from a simple hand axe of the Paleolithic Period and a magnificient golden crown of the Three Kingdoms Period to Goryeo Period celadons, or pottery, and paintings dating back to the Joseon Period, as well as pictures of modern-era Korea and a variety of other zones dedicated to different cultures throughout the globe. Bring your family, friends, or even that special someone over to the museum for a day of fascination amid a compilation of detailed and colorful history. ', '- Mon, Tues, Thur, Fri, Sunday 10:00 - 18:00 KST\n- Wed, Saturday 10:00 - 21:00 KST\n*  Outside exhibitions may be viewed from 07:00 KST', '* Closed on Mondays, January 1st, Lunar New Year\'s Day, Chuseok (Sept. 17)\n* Permanent exhibitions close every first Monday in April and October\n(2024 closure days: April 1 (Mon), Nov. 4 (Mon))\n??The special exhibition hall, children\'s museum, and outside', 'Subway Line 4/Gyeongui Central Line  Ichon Station  Exit 2,  309m', 37.5268614, 126.9807315, NULL, NULL, NULL, 5),
	(171, 'Gana Art Center', '03004  28, Pyeongchang 30-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gana-Art-Center/ENP002082', 'The Gana Art Center is a multipurpose art space that holds exhibitions, performances, classes, and auctions. The sprawling center was designed by the world-renowned architect Jean Michel Wilmotte. The Gana Art Center operates a convenient shuttle bus for visitors. The shuttle bus runs every day except Mondays and national holidays.', 'Tue-Sun 10:00 - 19:00 KST', 'Mondays', 'Subway Line 5 Gwanghwamun Station Exit 2 / Subway Line 3 Gyeongbokgung Station Exit 3, take bus 1020 or 1711 and get off at Lotte Apartment, 150m', 37.6122118, 126.9751774, 'KdramaTrip,  가나아트센터,  현대미술,  문화행사,  전시회,  7인의탈출 | 바니와오빠  가나아트센터  예술  현대미술  드라마촬영지  전시', 'the escape of seven people | Barney and brother', 'https://blog.kakaocdn.net/dna/mBR9L/btszlIKHdeh/AAAAAAAAAAAAAAAAAAAAAJSrA1cPaO6CbdqixN0HniiofNWPNb885c2FaJo3Q5pt/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=QRHHl3CBNUV3twnSR0ARXH60%2BeA%3D | https://blog.kakaocdn.net/dna/dbq6Mh/btsNsi6Lx95/AAAAAAAAAAAAAAAAAAAAAJJIJpsr_RHlrtjOKMOP3tagZmyDMyArrNAloDIcodEb/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=7WFr1J%2FFq89LvwpxOniI0rpONK4%3D', 4),
	(172, 'Museum Kimchikan', '03149  Insadong-gil 35-4 (Gwanhun-dong), Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Museum-Kimchikan/ENP019924', 'Museum Kimchikan is the place to go to learn about the many varieties of kimchi in the world. See real examples of different kimchi varieties and take part in fun activities! Museum Kimchikan is located in Insa-dong, but at one time, the center was located in Samseon-dong and named the Kimchi Museum. Following the move to Insa-dong, the museum underwent a redesign in addition to the name change.   At Museum Kimchikan, visitors can learn about kimchi in all its different forms as well as use microscopes to view the lactic acid bacteria that helps make kimchi so healthy. Visitors can learn and even taste samples of different varieties of kimchi during their time at the museum. The museum also holds kimchi-making activities and classes and visitors should join in to learn how to make delicious kimchi themselves!', 'Daily 10:00-18:00 (KST)', 'Closed Mondays, Lunar New Year, Chuseok & Christmas', 'Subway Line 3, Anguk Station, Exit 6, 394m', 37.5729872, 126.9844504, NULL, NULL, NULL, 4),
	(173, 'Seoul Art Space - Sindang Creative Arcade', '04571  87, Majang-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Sindang-Creative-Arcade/ENP005060', 'The Sindang Creative Arcade is a creative space for artists and an art market. The arcade was re-born into a space for the arts following renovation of empty storefronts at the Sindang Underground Shopping Center in the Jungang Market. The Jungang Market was established in 1917 and the renovation that created the Sindang Creative Arcade has revitalized the area. The creative arcade houses workshops and an art market. Dozens of artists create artworks and crafts in nearly every art medium there is. At the art market, shoppers can purchase unique artwork and items.', 'Artist Workshop 09:00 - 20:00 \nCommon Workshop & Photography Room 09:00 - 22:00', 'Art Market closed weekends', 'Subway Lines 2/6  Sindang Station  Exits 2,  336m', 37.5689608, 127.0180999, NULL, NULL, NULL, 4),
	(174, 'National Museum of Korean Contemporary History', '03141  198, Sejong-daero, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Museum-of-Contemporary-History/ENP006667', 'The National Museum of Korean Contemporary History houses exhibitions that span modern Korean history, from the first opening of Korea to outsiders in the late 19th century to today. The museum is the country\'s first national museum of contemporary history. The eight-story museum has many facilities: there are four permanent exhibition halls and two special exhibition halls, seminar rooms, lecture halls, a rooftop garden, a museum shop (that sells souvenirs), a cafe, and storage lockers. The four permanent exhibitions cover different periods of Korean history and there are over 1,500 artifacts and items here. Some of the displays are patriot Ahn Jung-Geun\'s last writings, the March 1st Declaration of Independence, belongings of fallen soldiers from the Korean War, and materials relating to democratic activism. The museum\'s first floor contains two special exhibition halls. Here, you will find a variety of limited-time exhibitions relating to Korean history, politics, society, and culture. Additionally, visitors can listen to, watch, and experience the modernization of Korea through state-of-the-art technology.', '10:00 - 18:00 (Wednesdays and Saturdays: 10:00 - 21:00) \n*Last entry 30 minutes before closing', 'Closed on New Year\'s Day & Chuseok', 'Subway Line 5  Gwanghwamun Station  Exit 2,  217m', 37.5740029, 126.977949, NULL, NULL, NULL, 5),
	(175, 'Nature Poem', '06011  461, Apgujeong-ro, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Nature-Poem-EN/ENP001439', 'Nature Poem is a six-story commercial gallery located in the heart of Gangnam\'s posh Cheongdam-dong neighborhood. Cheongdam-dong is famous for its abundance of premium designer stores. Nature Poem is located near many art galleries and high-end luxury stores, making a visit to Nature Poem a convenient starting point for a tour of Gangnam. Gallery GO, the Nam June Paik Museum and Gallery Jang are all nearby.', 'Daily 10:00 - 18:00', 'Closed Sundays', '* Bundang Line, Apgujeong Rodeo Station, Exit 2 (10 mins on foot)* Subway Line 7, Cheongdam Station, Exit 9 (20 mins on foot)', 37.5265758, 127.048272, NULL, 'K-POP DEMON HUNTERS', NULL, 4),
	(176, 'National Meteorological Museum of Korea', '03178  52, Songwol-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Meteorological-Museum-of-Korea-EN/ENP040770', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}It is the first meteorological science and history museum that researches and preserves the meteorological culture of Korea from the Joseon Dynasty to modern times. The museum owns the world\'s last surviving rain gauge instrument, known as the Rain Gauge of the Chungcheonggamyeong Provincial Office, Gongju, invented 200 years earlier than the West.The Seoul Meteorological Observatory (52 Songwol-gil, Jongno-gu, Seoul), where the National Meteorological Museum was established, is the center of Korea\'s modern and contemporary meteorological history. The modern meteorological observation started in Wonnam-dong, Gyeongseong, in 1907 and moved to Songwol-dong via Nakwon-dong. The building at the time of its establishment in 1932 and extension in 1939 have been maintained and served as the Korea Meteorological Administration until the administration moved to Dongjak-gu, Seoul, in 1998. For this continuity, it was selected as a ??00-year observatory??by the World Meteorological Organization in 2017. In 2016, when the museum was being built, the Seoul Meteorological Observatory was restored to its original form based on the architectural drawings of the 20th-century meteorological station kept at the National Archives. Please enjoy the change of weather and history at the National Meteorological Museum, the heart of Korea\'s meteorology.', '10:00  - 18:00', 'Mondays, January 1, Lunar New Year??s Day and Chuseok', 'Subway Line 5  Seodaemun Station  Exit 4,  860m', 37.570748, 126.9672224, NULL, NULL, NULL, 4),
	(177, 'Jong Ie Nara Paper Art Museum', '100-391  166, Jangchungdan-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Jong-Ie-Nara-Paper-Art-Museum/ENP005796', 'The Jongienara Museum opened in 1999 as a Paper Art Museum and was established to revive and recreate Korea\'s world-class paper, K origami, and paper culture. Reopened as the Jongienara Museum in 2008, it goes beyond researching and introducing Korea\'s outstanding origami and paper culture. It pays attention to the excellent role of paper as a craft and art object, presenting the development of a new cultural art genre and modern paper culture and art. The excellence and creativity of Korean origami and paper culture are known to the public through the discovery, exhibitions, and education of current cultural paper artworks.', 'Daily 09:30 - 18:00 \n(Last entry 30 mins prior to close)', 'Closed Sundays & Holidays', 'Subway Line 3, Dongguk Univ. Station, Exit 3,  55m', 37.5596792, 127.0062029, NULL, NULL, NULL, 3),
	(178, 'Sungshin Women\'s University Costume Museum and Natural History Museum', '01133  55, Dobong-ro 76ga-gil, Gangbuk-gu, Seoul  (Woonjung Green Campus, B1)', 'https://english.visitseoul.net/attractions/Sungshin-Womens-University-Costume-Museum-and-Natural-History-Museum/ENP033828', 'Opened on November 23, 2011, the Park Kwang Hoon Costume Museum is a special museum, displaying over 600 garments, which are currently designated as Seoul\'s Intangible Cultural Property No. 11, donated by the Master Artisan of Needlework, Park Kwang Hoon, as well as more than 2,000 pieces of fabrics and accessories. A variety of Korean attires and accessories are on display, from swaddling clothes and ordinary clothes as well as wedding clothes and royal ritual clothes to shrouds for the deceased.Located in the basement (B1) of the same building, the Natural History Museum exhibits as many as 135,000 samples collected for over 40 years since the 1970s under four themes of rocks, embryogenesis, plants and insects to help visitors learn and feel the nature around them.', 'Mon - Sat 10:00 - 17:00 (Closed Sundays and Legal Holidays)', NULL, 'Subway Line 4  Mia Station  Exit 1,  500m', 37.6319498, 127.027268, NULL, NULL, NULL, 6),
	(179, 'Culture Station Seoul 284', '04509  1, Tongil-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Culture-Station-Seoul-284/ENP000450', 'Culture Station Seoul 284 is a multipurpose arts and cultural complex. It was once known simply as Seoul Station and it was the city\'s biggest rail station. The station was built during the Japanese colonial era. The first floor is used as a space for performances and exhibitions. The second floor is used for exhibitions, seminars, and meetings. Though admission to Culture Station Seoul 284 is free, performances and exhibitions may charge admission.', NULL, NULL, 'Subway Line 1/4/Airport Railroad/Gyeongui-Jungang Line/GTX-A  Seoul Station Exit 1,  76m', 37.5575215, 126.9704401, NULL, NULL, NULL, 5),
	(180, 'Arko Art Center', '03087  3, Dongsung-gil, Jongno-Gu, Seoul', 'https://english.visitseoul.net/attractions/Arko-Art-Center/ENP018992', 'Arko Art Center is a public art gallery and art center in the Daehak-ro area. By curating temporary exhibitions, and creating a platform for emerging experimental artists, the gallery has successfully become a staple of the Korean contemporary art scene. The Arko Art Center is also home to INSA Art Space, an alternative space aimed at promoting upcoming artists, as well as maintaining archives and providing seminar rooms and project space. There is no admission fee for the center, but exhibitions may charge entry fees.', 'Daily 11:00 KST - 19:00 KST (Last entry at 18:30 KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year, Chuseok & Christmas', 'Subway Line 4  Hyehwa Station  Exit 2,  138m', 37.5788284, 127.0036426, NULL, NULL, NULL, 5),
	(181, 'The Hangsangsoo Embroidery', '02836  4-10 Seongbuk-ro, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Hansangoo-Embroidery-Museum/ENP003357', 'This unique space preserves all the traces of traditional Korean embroidery techniques that have been restored by collecting and analyzing artifacts from the 1960s to revive Korean embroidery, which was lost through the Korean Empire and Japanese occupation. The Korean Handicraft Institute, which opened in 1963, is the origin of the Hansangsu Embroidery Museum. It has been established as a complex cultural space to preserve and present Korean embroidery to the public. The eldest daughter of Han Sang-soo, a National Intangible Cultural Property embroiderer, has been running the museum as the second director and is preparing for the third succession.', 'Tuesday-Sunday 10:00~18:00\nBreak Time 12:00~13:00', 'Monday', 'Subway  Line 4  Hansung University Station  Exit 5,  719m', 37.5955256, 127.0005674, NULL, NULL, NULL, 5),
	(182, 'Leeum Museum of Art', '04348  60-16, Itaewon-ro 55-gil, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/Leeum-Samsung-Museum-of-Art/ENP001232', 'The Leeum Museum of Art is the perfect place to enjoy traditional and contemporary art created by Korean and international artists. Most of the exhibits on display at the museum are based on the large collection of the founder, the late Lee Byeong-cheol, once president of the Samsung Group. Three world-renowned architects, Maria Botta, Jean Nouvel, and Rem Koolhaas, were commissioned to design the outstanding museum complex. The name Leeum is the acronym of the family name of its founder, ??Lee??and an abbreviated word for museum, ??um?? The museum is composed of three individual buildings linked together as a composite complex. Museum 1 showcases traditional Korean arts and crafts such as calligraphy, ceramic arts and metal craft work, while Museum 2 displays dynamic modern and contemporary art by domestic and international artists, this section includes the Samsung Child Education & Cultural Center which offers cultural education for children.  In the museum basement, a sunken garden and Gabion wall, which is a cylindrical metal container filled with stones, can be found. Art, architecture and nature exist together in perfect harmony.           Frequently Asked Questions about Leeum Museum of Art         Do I need to make a reservation to visit the Leeum Museum of Art?         Leeum Museum of Art operates under a reservation system. Reservations can be made 14 days before the visit. The maximum number of people per reservation is four. On-site ticketing is possible and limited to remaining tickets per reservation time (As of 2025)          Is the Leeum Museum of Art digital guide available for free?         Digital guides that automatically provide explanations when one approaches the exhibits can be borrowed free of charge. The devices are available to elementary school students and anyone older. You must present an identification card such as a passport or resident registration card. The digital guide is available in Korean, English, Chinese, and Japanese. (As of 2025)          Can I visit the Leeum Museum of Art permanent exhibitions for free?         Yes. Permanent exhibitions are free. They are also operated under a reservation system, so please make a reservation before visiting. (As of 2025)', 'Tue-Sun 10:00 - 18:00', 'Closed Mondays, New Year\'s weekend, New Year\'s Day & Chuseok', 'Subway Line 6  Hangangjin Station  Exit 1,  399m', 37.537634, 126.9981748, NULL, NULL, NULL, 4),
	(183, 'Electricity Museum', '06732  60, Hyoryeong-ro 72-gil, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Electricity-Museum/ENP001958', 'The Electricity Museum is an educational museum located within the KEPCO Art Center. Visitors can learn about the history of electricity here through fun activities, photos, models, and illustrations.', 'Daily 10:00 - 18:00', 'Closed Mondays, Lunar New Year & Chuseok', 'Subway Line 3 & Shinbundang Line, Yangjae Station, Exit 1 (20 mins on foot)', 37.4856988, 127.0279981, NULL, NULL, NULL, 3),
	(184, 'Appenzeller Noble Memorial Museum', '04516  19, Seosomun-ro 11-gil, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Appenzeller-Noble-Memorial-Museum/ENP006430', 'Learn about the history of education in Korea at the Appenzeller Noble Memorial Museum. The museum is housed in what was once the Pai Chai Hakdang, which was Korea\'s first Western-style school. Currently, the school\'s classrooms have been repurposed and are used as a permanent exhibition hall, a special exhibition hall, an experience zone, and a seminar room. In the permanent exhibition hall, visitors can see what the Pai Chai Hakdang looked like in the 1930s at the hall\'s recreated historical classroom. Admission to the museum is free.', 'Daily 10:00 - 17:00', 'Closed Mondays, Sundays & Public Holidays', 'Subway Line 1 / 2  City Hall Station  Exit 10,  240m', 37.5637052, 126.9722864, NULL, NULL, NULL, 4),
	(185, 'National Museum of Modern and Contemporary Art, Seoul', '30, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Museum-of-Modern-and-Contemporary-Art-Seoul/ENP011658', 'The National Museum of Modern and Contemporary Art (MMCA), Seoul is the newest of the four branches. The Seoul branch focuses on introducing global contemporary art. Equipped with multiple facilities, including a library, theater, and a multipurpose hall, MMCA, Seoul strives to accommodate every mode of new artistic endeavors and communication with the public.', 'Mondays, Tuesdays, Thursdays, Fridays, and Sundays 10:00 - 18:00 (KST)\nWednesdays & Saturdays 10:00 - 21:00 (KST)\n* Special Night Exhibition 18:00 - 21:00 (KST)\n* Last Entry: 1 Hour Before Closing Time', 'New Year\'s Day, Lunar New Year\'s Day & Chuseok', 'Subway Line 3  Anguk Station  Exit 1,  764m', 37.5795117, 126.9805862, NULL, NULL, NULL, 5),
	(186, 'National Aviation Museum of Korea', '07505  177 Haneul-gil, Gangseo-gu, Seoul  (Gonghang-dong, National Aviation Museum of Korea)', 'https://english.visitseoul.net/attractions/National-Aviation-Museum-of-Korea/ENP038021', 'The National Aviation Museum of Korea, located at Gimpo Airport, is the first national museum in the aviation field established by the Ministry of Land, Infrastructure and Transport to organize Korea\'s aviation history and promote collective understanding of the aviation industry. The National Aviation Museum of Korea consists of the Aviation History Hall, where visitors can learn about the history of Korean aviation, the Aviation Industry Hall, where visitors can get a glimpse of the current state of the aviation industry, and the Aviation Future Hall, where visitors can see various aviation technologies, airplanes and models for the future. Additionally, there is a unique experience space for those who have always dreamed of flying. Here, visitors can experience aviation through five different spaces including the Black Eagle boarding experience, an in-flight training experience, a pilot control experience, the air sports experience, and the children\'s airport experience. ', 'Daily 10:00 - 18:00', 'Closed Mondays\nJanuary 1, Lunar New Year??s Day\n*If Monday is a public holiday, the museum will be open on that Monday and closed on Tuesday.*', 'Subway Line 5/9/Airport Railroad/Seohae Line/Gimpo Gold Line  Gimpo Airport Station Exit 4,  988m', 37.5567557, 126.8084734, NULL, NULL, NULL, 5),
	(187, 'Hangaram Art Museum', '06757  2406, Nambusunhwan-ro, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Hangaram-Art-Museum/ENP004325', 'Hangaram Art Museum is situated on the left side of the main front area of the Seoul Arts Center. It is integrated with various programs offered by the Seoul Arts Center. The museum includes exhibition halls, storage rooms, and an art shop, providing an optimal exhibition environment. It often hosts special exhibitions by world-renowned artists such as Edvard Munch, Bernard Buffet, and Pablo Picasso. Most exhibitions prohibit photography, and observing proper viewing etiquette is important. The outdoor stair plaza serves as an open space for art markets, outdoor festivals, and an outdoor café during the summer season. It also accommodates various public programs, offering a unique cultural experience.', '10:00 - 19:00 (KST)', 'Closed Mondays', 'Subway Line 3  Nambu Bus Terminal Station (Seoul Arts Center)  Exit 5,  695m', 37.4784816, 127.0125833, NULL, NULL, NULL, 5),
	(188, 'Seoul Book Bogo', '05507  1, Ogeum-ro, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Book-Bogo/ENP030789', 'Seoul Book Bogo is a new cultural space created by Seoul Metropolitan Government to house old, secondhand books they gathered from old bookstores around the city. Featuring an old secondhand bookstore, library, and cultural programs, Seoul Book Bogo is separated into 4 spaces for value, sharing, enjoyment, and experience. Visitors can feel the value of old books in the space for value, read books donated by famous intellectuals in the space for sharing, experience unique indie books in the space for enjoyment, and participate in various cultural book programs in the space for experience.', 'Weekdays 11:00 AM - 9:00 PM\nSaturdays 10:00 AM - 9:00 PM\nSundays 10:00 AM - 6:00 PM', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok', 'Subway Line 2, Jamsillaru Station, Exit 1,  160m', 37.5212666, 127.1080185, NULL, 'Record of Youth', NULL, 4),
	(189, 'Samseyoung', '03003  2 Pyeongchang 44-gil, Jongno-gu, Seoul  Samseyoung', 'https://english.visitseoul.net/attractions/2024-samsy/ENPzcpf02', 'Samseyoung aims to be a cultural and artistic space that embraces the past, present, and future. Opened in December 2021, Samseyoung reflects on the past through the collection of antique art that the founder has gathered over 20 years. It is also a space where contemporary cultural and artistic figures come together to engage with the present while looking forward to the future.', '11:00-18:00', 'Sun-Mon', 'Subway Line 3  Gyeongbokgung Station  Exit 3,  Take Bus 1711 and get off at Pyeongchang-dong Samsung Apartments. 301 m', 37.6136789, 126.9783261, 'KdramaTrip  국민사형투표  드라마촬영지  서울여행  삼세영앞  명장면', 'a referendum on the death penalty', 'https://blog.kakaocdn.net/dna/erF1cV/btsu9RrUyyU/AAAAAAAAAAAAAAAAAAAAAKhxcalCOsXoD85hD0uXAQcFIVuza6jjsDl0VGAh2EJ7/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=nMMCmjmxLSJTJQ3xB9Ah10TKhqo%3D', 5),
	(190, 'Space C', '06024  827, Eonju-ro, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Space-C/ENP001441', 'Space C is a venue created and run by Coreana, a Korean cosmetics company. It spans 10 levels comprising a museum, gallery, beauty shop, café, and rooftop garden. On the 5th and 6th floors, visitors will find Korea??s largest cosmetics museum where visitors can learn about the history and development of Korean cosmetics. Space C also houses a large number of cosmetics-related artworks and other artifacts.      The Cosmetics Museum is Space C??s main exhibition hall, presenting the history of Korean cosmetics through a collection of more than 5,300 beauty-related items used by women in the Joseon Dynasty (1392-1910). The C Gallery on the first basement level is a traditional exhibition hall that displays fine art while C Cube on the second basement level plays host to more experimental work. The museum café on the 1st floor reflects the nature of its setting with art exhibits created from everyday objects, giving visitors the chance to continue their cultural odyssey even as they relax. The Beauty Space on the 2nd to 4th floors is a peaceful haven where women can consult a beauty therapist in the skin clinic and indulge in a range of body treatments. The Outdoor Cosmetics Museum on the rooftop of Space C is a garden featuring a collection of important plants which provide key ingredients for the cosmetics industry. From here, visitors can also enjoy spectacular views of the Seoul skyline.', 'Tuesday - Friday - 11:00 AM - 6:00 PM', 'Saturday,Sunday, Monday, January 1, Lunar New Year & Chuseok holidays\n* Please refer to the website as opening hours may vary.', 'Subway Line 3, Apgujeong Station, Exit 3,  567m', 37.5231988, 127.0315632, NULL, NULL, NULL, 5),
	(191, 'Art Sonje Center', '03062  87, Yulgok-ro 3-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Art-Sonje-Center/ENP002405', 'Whereas the Sonje Museum of Art typically focuses exclusively on contemporary artwork, the Art Sonje Center has a multi-pronged focus on art. The museum exhibits art from various genres and the museum also hosts cultural events such as concerts, short film screenings, and performance arts shows by Korean and foreign artists. Major pieces in the museum\'s collection are  Wings of Jupiter by Kwak Hoon and Curtains by Hwang Kyu-Baik.', 'Daily 12:00 - 19:00 (KST)', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', 'Subway Line 3  Anguk Station  Exit 1,  709m', 37.5794223, 126.9818411, NULL, NULL, NULL, 2),
	(192, 'Seoul Science Museum', '01792  160, Hangeulbiseok-ro, Nowon-gu, Seoul', 'https://english.visitseoul.net/attractions/SeoulScienceMuseum/ENPn1ua1r', 'The Seoul Science Museum, located in Hageo-dong, Nowon-gu, opened its doors for the first time in Seoul in 2017. It was established to enhance science and cultural facilities in the Gangbuk area, aiming to bridge the gap in science and culture among different regions and promote balanced development across Seoul\'s districts. As a science experiential facility aimed at youth, it operates six permanent exhibition halls with 221 exhibits and a special rotating exhibition hall featuring exhibits related to the history of objects. It offers various educational programs and events, including family-friendly science-making experiences, group science classes for elementary, middle, and high school students, expert lectures, science experiments, and nature ecology programs that families can enjoy together.', 'Tue-Fri 09:30-17:30 KST', 'Closed every Monday, January 1st, and the day of Lunar New Year and Chuseok', 'Subway Subway  Line1  Hagye Station  Exit 2,  1km', 37.6414495, 127.0790575, NULL, NULL, NULL, 5),
	(193, 'Kumho Museum of Art', '110-061  18, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Kumho-Museum-of-Art/ENP003100', 'The Kumho Museum of Art showcases artwork from famous, established artists as well as works from outstanding new artists. The museum hosts a concert series in their recital hall called the Kumho Gallery Concert. The concerts take place every Tuesday, Thursday, and Friday at 20:00 in the evening. There are also presentations on the artists and artworks on exhibition at the museum. These sessions are opened to the public as part of the museum\'s Kumho Academy. The Kumho Museum of Art is located near Gyeongbokgung Palace.', 'Daily 10:00 - 18:00 (KST) (Last entry at 17:30)', 'Closed Mondays, Lunar New Year\'s Day & Chuseok', 'Subway Line 3  Anguk Station  Exit 1,  620m', 37.5774697, 126.9799083, NULL, NULL, NULL, 4),
	(194, 'The War Memorial of Korea', '04353  29, Itaewon-ro, Yongsan-gu, Seoul', 'https://english.visitseoul.net/attractions/WarMemorialofKorea/ENP000859', 'The War Memorial of Korea was established to remember the Korean War (6. 25. 1950 - 7. 27.1953) and to symbolize the desire for peaceful reunification of Korea. The museum consists of 6 individual exhibition halls and a combat experience room, a screening room and an outdoor exhibition area with memorial statues.    The Statue of Brothers located in the south-west corner of the outdoor exhibition area at the museum symbolizes the Korean War and the hope for reunification. The statue depicts a scene where a family??s oldest son, a South Korean soldier and his younger brother, a North Korean soldier meet on a battlefield. Their embrace expresses reconciliation, love and forgiveness.   There is also an extensive garden area around the memorial with an artificial waterfall, and a lake where visitors can picnic whilst enjoying the beautiful landscape. The museum houses more than 10,000 artifacts in the indoor and outdoor exhibition areas. It takes visitors about three hours to complete the tour. The first floor exhibition hall features a history of war from prehistoric times up to the Korean War. The combat experience room on the third floor offers visitors a special opportunity to experience a simulated life and death situation on the battlefield through special effects.', 'Tue-Sun 09:30 - 18:00 \n*For more details, please refer to our website.', 'Closed Mondays & the day following national holidays', 'Subway Line 4  Samgakji Station  Exits 11,  227m', 37.5396193, 126.9799854, NULL, NULL, NULL, 5),
	(195, 'Seoul Urban Life Museum', '01849  27, Dongil-ro 174-gil, Nowon-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Urban-Life-Museum/ENP038243', 'The Seoul Urban Life Museum is a modern life and history museum that focuses on exhibitions and programs that allow guests to reminisce and interact with the memories of Seoul\'s citizens. There are facilities for everyone to enjoy, such as the Living Seoul Exhibition Room, which features displays on the life and scenery of Seoul, the Children\'s Experience Room for kids and the Special Exhibition room where various exhibitions are held throughout the year.', 'Daily 09:00 - 18:00 *Closed Mondays* (KST)', 'monday', 'Subway Lines 6 / 7  Taereung Station  Exit 5,  320m', 37.6196117, 127.0767787, NULL, NULL, NULL, 5),
	(196, 'Songeun Art Cube', '06182  441, Dosan-daero, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Songeun-Art-Cube/ENP003778', 'Songeun Art Cube (formerly known as Songeun Gallery) is a space for new artists to exhibit their artworks. Operated by the Songeun Art Foundation, the space functions as a gallery but various arts events also take place here. Ever since it opened in 2002, Songeun Art Cube has held an annual arts award ceremony. Winners are sponsored by the foundation and receive support to exhibit their work.', 'Daily 11:00 - 18:30', 'Closed Sundays & holidays', 'Subway Suin Bundang Line  Apgujeong Rodeo Station  Exit 4,  637m', 37.5241746, 127.0440443, NULL, NULL, NULL, 5),
	(197, 'The Seoul Museum of History', '03177  55, Saemunan-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/The-Seoul-Museum-of-History/ENP002722', 'The Seoul Museum of History is the only museum in Korea that represents the city??s history and culture. Since its establishment on the former site of Gyeonghuigung Palace in 2002, the museum has offered visitors the chance to experience 600 years of Seoul??shistoryand culture through interactive exhibitions. The three-story museum is divided thematically into three exhibition areas, including a special exhibition area, a permanent exhibition area and a hall that exhibits collections donated by the public.      The museum offers accessible and interactive exhibitions to the public with various hands-on programs. For example, visitors are allowed to touch and explore the exhibits on display, which are replicas of originals in the museum. In addition, the museumoffersthe U-Exhibit Guidance System, an automatic translator (various languages are available) for visitors, which makes every tour convenient and interesting.', 'KST 09:00 - 18:00 (Last Entry: 17:30 )\nExtended Hours: Every Friday until 21:00 \n*For more details, please visit the website.', 'Closed Mondays & New Year\'s Day', 'Subway Line 5  Gwanghwamun Station  Exit 7,  462m\nSubway Line 5  Seodaemun Station  Exit 4,  641m', 37.5714656, 126.9684165, NULL, NULL, NULL, 5),
	(198, 'Maehun Yun Bong-Gil Memorial Hall', '06773   99, Maeheon-ro, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Maehun-Yun-Bong-Gil-Memorial-Hall/ENP003759', 'The Maehun Yun Bong-Gil Memorial Hall is dedicated to the resistance fighter, Patriot Yun Bong-gil. Yun\'s pen name was Maehun and he was active in the Korean independence movement during the Japanese colonial era. Located in Seoul\'s Yangjae dong, the first floor of the memorial is an exhibition hall that displays relics and biographical information about Yun Bong-gil in chronological order. On the second floor, the exhibition hall contains photographs and other materials of the Korean independence movement organized by theme. Admission to the memorial hall is free.', '* April to October: 10:00 - 18:00\n* November to March: 10:00 - 17:00\n??Last entry is 30 mins prior to closing', 'Closed Mondays, New Year\'s Day, Lunar New Year??s Day & Chuseok', 'Subway Sinbundang Line  Yangjae Citizen\'s Forest Station  Exit 5,  179m', 37.4702204, 127.0377882, NULL, NULL, NULL, 5),
	(199, 'The store from Tong-in', '03148  32 Insadong-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Tong-in-Shop/ENP025931', 'The oldest gallery specializing in antique art in Insadong, it was founded in 1924 as an antique art store representing Korea and became the backbone of culture and art during the turbulent times. The Tongin Gallery is located inside the Tongin Store and has become the center of Insadong as a complex cultural art space where ancient and contemporary art coexist. It is famous for its ancient art representing Korea and is a favorite place for world leaders. The tiger from a familiar folk tale is the representative character of Tongin Gallery.', 'Tue-Sat 10:30~18:30, Sun 12:00~17:00 KST', 'Mondays', 'Subway Line 1/3/5  Jongno 3-ga Station  Exit 5,  334m', 37.5738017, 126.9863669, NULL, NULL, NULL, 5),
	(200, 'Gongpyeong Historic Sites Museum', '03161  26, Ujeongguk-ro, Jongno-gu, Seoul  (B1, Centropolis)', 'https://english.visitseoul.net/attractions/Gongpyeong-Historic-Sites-Museum/ENP026675', 'Gongpyeong Historic Sites Museum was created when well preserved 16th century Joseon sites were dug up during redevelopment phases of Gongpyeong district 1, 2, and 4.  The museum is largely divided into 4 parts: ??Coexistence of Development and Preservation?? ??Gyeonpyeong-bang of the Joseon Dynasty Period?? ??Modern Gongpyeong-dong?? and ??Historic Sites Archives.?? The completed Gongpyeong Historic Sites Museum displays the various relics and building structures of a neighborhood which managed to remain undisturbed for over 600 years, allowing visitors a closer look at the daily lives of people who had lived back in the Joseon Dynasty.', 'Daily 09:00 - 18:00 (KST)', 'Closed Mondays', 'Subway Line 1  Jonggak Station  Exit 3-1,  69m', 37.5716155, 126.9833532, NULL, NULL, NULL, 5),
	(201, 'Platform-L Contemporary Art Center', '06053  11, Eonju-ro 133-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/PLATFORM-L/ENPn0wsm1', 'Platform-L Contemporary Art Center was established to provide audiences with diverse artistic experiences through the creative endeavors of contemporary artists and to contribute to a society enriched with imagination and inspiration. Since its opening in spring 2016, Platform-L has housed facilities including galleries, a live hall, an open courtyard, and lecture rooms. The center presents exhibitions, performances, and video works across a wide range of genres and media.', '11:00-20:00', 'Closed every Monday', 'Subway Line 7, Hakdong Station, Exit 10, 284m', 37.5160905, 127.0342929, NULL, NULL, NULL, 5),
	(202, 'Mokin Museum', '03022  46-1 Changuimun-ro 5-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Mokin-Museum/ENP001809', 'The Mokin Museum specializes in traditional wooden sculptures and woodwork. The museum is located in Insa-dong and consists of an underground lounge, an exhibition hall, and a rooftop garden. The museum collection includes traditional Korean wooden sculptures as well as traditional masks, staffs and wooden dolls from other parts of Asia. Mokin hosts various exhibitions and events throughout the year.', '* Summer Season 10:30 - 19:00 (Last entry at 18:00) \n* Winter Season 10:30 - 18:00 (Last entry at 17:00)', 'Closed Sundays, Mondays, New Year\'s Day, Lunar New Year & Chuseok', 'Subway Line 3  Gyeongbokgung Station  Exit 2,  1.9km\nGet off at Buam-dong Community Center and walk 500m', 37.5890069, 126.9632586, NULL, NULL, NULL, 5),
	(203, 'The replica of an old mayor??s office', '04524  110 Sejong-daero, Jung-gu, Seoul (Seoul Library 3rd floor)', 'https://english.visitseoul.net/attractions/formermayorsoffice/ENP678cv8', '.se-contents .se-scrollbox{overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;}.se-contents .se-scrollbox::-webkit-scrollbar{display: none;}.se-contents .se-responsive.se-image .se-caption{max-width: 100% !important;}.se-contents .se-responsive.se-image, .se-contents .se-responsive.se-video{max-width: 100%; height: auto !important;}.se-contents .se-responsive.se-image > img, .se-contents .se-responsive.se-video > *{max-width: 100%; min-width: 10px; height: auto !important;}.se-contents .se-responsive.se-video .se-video-wrapper{position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; display: block;}.se-contents .se-responsive.se-video .se-video-wrapper > iframe{width: 100% !important; height: 100% !important; position: absolute; left: 0px}The Reconstructed Former Mayor??s Office is a workspace used by former mayors of Seoul for over 60 years, from the post-liberation period until May 2008. Located at the center of the 3rd floor of the Seoul Metropolitan Library, this space comprises a planning room, reception room, and office, featuring faithfully restored furniture and office equipment from that time.', 'Every Tue-Sun, 09:00-18:00  (Closed on Mondays and public holidays)', 'Mondays and public holidays', 'Subway Lines 1 / 2  City Hall Station  Exit 5,  53m', 37.566257, 126.9778149, NULL, NULL, NULL, 5),
	(204, 'Seo Gallery', '06648  94, Banpo-daero, Seocho-gu, Seoul', 'https://english.visitseoul.net/attractions/Seo-Gallery/ENP001966', 'The Seo Gallery is an arts gallery in Banpo-dong, Seoul. Its exhibitions cover a wide variety of different mediums including, but not limited to, painting, sculpture, photography, architecture, design, and fashion. The gallery also provides various programs to support both older artists and to foster new artists.', '10:00 - 17:00 (KST)', 'Closed Weekends', 'Subway Line 2, Seocho Station, Exit 2', 37.4898114, 127.0098417, NULL, NULL, NULL, 4),
	(205, 'Donuimun Museum Village', '03178  14-3, Songwol-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Donuimun-Museum-Village/ENP023761', 'The Donuimun Museum Village is an outdoor village that consists of hanok (traditional Korean homes) and buildings that showcase historical eras of Seoul architecture. Visitors can see the architectural styles of the 1900s up to the 1980s at this special outdoor museum. Founded in September 2017, the museum village is conveniently located between the Gangbuk Samsung Hospital and the Seoul Museum of History.       Through urban regeneration efforts, Donuimun Museum Village has preserved 40 out of 63 houses in    Saemunan,    an old neighborhood district. Architecture from Korea\'s modern history era and Joseon Dynasty exist side by side in this newly developed cultural space.       The renovated houses were rehabilitated as exhibition and experience spaces.      ??An exhibition space where the history of Saemunan-dong and the sensibility of the analog generation are alive      - Donuimun Museum Village, Donuimun Club, Seoul Future Heritage Hall, 60s 80s emotional spaces (Citizens??Life History Hall, Saemunan Theater, Seodaemun Photo Studio, and more)', 'Tue-Sun 10:00 - 19:00 (KST)', 'Closed Mondays & New Year\'s Day', 'Subway Line 5, Seodaemun Station, Exit 4, 349m', 37.570748, 126.9672224, NULL, NULL, NULL, 4),
	(206, 'THEO', '06156  B1, 55-3 Bongeunsa-ro 68-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-THEO/ENP9q04ig', 'Gallery THEO, known for showcasing Korean art\'s broad spectrum and diversity, was established in 2020 by two directors with experience in the UK and the international art market. They aimed to introduce global expertise and networks to the Korean art scene. Located in front of the UNESCO World Heritage site Seonjeongneung, THEO is dedicated to supporting young and talented Korean artists, regardless of artistic genre, and uncovering the potential in their works. The gallery actively provides a platform for Korean artists to grow and thrive. In addition, THEO introduces international artists to the Korean and Asian art communities, fostering cross-cultural exchanges and expanding artistic discourse beyond national borders. THEO continues to host exhibitions featuring diverse artists worldwide. It aims to create a space where artists can coexist and flourish, driven by a commitment to challenging projects and artistic excellence.', '13:00~19:00', 'Monday, Sunday, and public holidays', 'Subway Line 9  Samsung Jungang Station  Exit 6,  539m', 37.5095206, 127.0535505, NULL, NULL, NULL, 4),
	(207, 'Seoul Baekje Children\'s Museum', '05540  Seoul Baekje Children\'s Museum, Olympic-ro 424, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/SeoulBaekjeChildrensMuseum/ENPeenv2i', 'Seoul Baekje Children\'s Museum is the only children\'s museum in the Gangnam area that exhibits and educates about the fact that Mongchontoseong was the royal fortress of the ancient kingdom of Baekje, Seoul\'s 2,000-year urban history, and the ancient culture of the Han River basin. Seoul Baekje Children\'s Museum is affiliated with Hanseong Baekje Museum and reopened in May 2024. It displays various artifacts excavated from Pungnap-dong Earthen Fortification, Mongchontoseong, and Seokchon-dong Ancient Tombs, which were Baekje\'s royal fortresses. The site offers a range of educational programs and cultural events, allowing visitors to experience and appreciate Seoul\'s rich ancient history and culture firsthand.', '[Weekdays] 9:00 AM - 6:00 PM (self-guided tour) *Entry closes at 5:30 PM\n[Weekends and holidays] 9:30 AM - 5:30 PM (reservation required)', 'Closed every Monday, January 1st\n*Open on Mondays that fall on holidays', 'Subway Lines 5/9 Olympic Park Station Exit 3, 1.6km / Line 8 Mongchontoseong Station Exit 1, 1.7km', 37.5238038, 127.1244332, NULL, NULL, NULL, 5),
	(208, 'Seoul Sewerage Science Museum', '04809  64, Jadongchasijang 3-gil, Seongdong-gu, Seoul (Seoul Sewerage Science Museum)  250-4, Yongdap-dong', 'https://english.visitseoul.net/attractions/Seoul-Sewerage-Science-Museum-1/ENP033825', 'Established in 2017 to promote the history and science of sewerage, the Seoul Sewerage Science Museum is the nation\'s first science museum specializing in sewerage. It was constructed at the site of the Cheonggyecheon Sewage Treatment Plant, the country\'s first sewage disposal plant, to continue the historical significance and values of the facility. The museum is also a space that is centered on on-site experience, comprised of a science exhibition hall that displays the history, technology, and future of domestic and overseas sewerage, as well as a water reclamation center where visitors can take a look around sewerage facilities. As the center of environmental education, the Seoul Sewerage Science Museum offers various programs to teach the process of sewage purification and the significance of water.', 'Tue - Sun 09:00 ??17:00 (Closed Mondays, New Year\'s Day, Lunar New Year\'s, and Chuseok)', NULL, 'Subway Line 5  Janghanpyeong Station  Exit 8,  1.2km', 37.5579563, 127.057839, NULL, NULL, NULL, 5),
	(209, 'Gallery Kong', '03049  38, Samcheong-ro 7-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gallery-Kong/ENP026676', 'Since its opening in 2005, Gallery Kong has showcased a wide range of globally famous photographers, greatly influencing the photography industry in Korea.    When the gallery moved into the newly built facility next to Cheongwadae??s Chunchugwan in Samcheong-dong, it expanded from being just a photo gallery to a multimedia gallery displaying all kinds of modern art, including communication arts, sculpture, video installations, etc.    By showcasing works of globally famous artists like Bernard Faucon (France), Chen Ruo Bing (China), Michael Kenna (UK), and Erwin Olaf (Netherlands), Gallery Kong is a gallery which shows the trend of contemporary art in 21st century Korea. This gallery also plays a very crucial role in helping Korean artists establish presence abroad by connecting them to galleries and shows outside Korea.', '* Tuesdays - Saturdays 10:00 - 18:00', 'Closed Mondays, Sundays', 'Subway Line 3, Anguk Station, Exit 1,  1.2 km\nSubway Line 3, Gyeongbokgung Station, Exit 5,  1.5 km', 37.584028, 126.9796759, NULL, NULL, NULL, 5),
	(210, 'Hwanghakjeong Korean Archery Gallery', '03027  15-32 Sajik-ro 9-gil, Jongno-gu, Seoul, Republic of Korea  Hwanghakjeong Archery Museum', 'https://english.visitseoul.net/attractions/Hwanghakjeong-Korean-Archery-Gallery/ENP029767', 'Hwanghakjeong Korean Archery Gallery is a place where visitors can go to learn about the history of archery in Korea and see the excellent quality of Korean bows. Made up of 5 different sections including exhibition halls, experience centers, and a permanent exhibition showcasing donated artifacts, this gallery is a great place for visitors to learn about traditional Korean archery and offers various programs where visitors can make arrows, try out archery, and more.', 'KST 10:00 - 17:00', 'Closed Monday, New Year\'s Day, Lunar New Year & Chuseok', 'Subway Line 3  Gyeongbokgung Station  Exit 1,  841m', 37.5770065, 126.9647898, NULL, NULL, NULL, 4),
	(211, 'Sungkok Art Museum', '03175  42, Gyeonghuigung-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Sungkok-Art-Museum/ENP001907', 'The Sungkok Art Museum was established in 1995 to promote and foster Korean arts. The museum also commemorates the late founder of the Ssangyong Group, Kim Sungkok, and the museum was built on the site of Kim Sungkok\'s house. Creative work from all artistic genres such as photography, design, and fashion, is showcased in various exhibitions. The museum typically hosts more than a dozen exhibitions each year. There are three exhibition halls and an outdoor sculpture garden.', 'Daily 10:00 - 18:00 (KST)\n* Last entry at 17:30 (KST)', 'Closed Sundays, Mondays & Holidays', 'Subway Line 3  Gyeongbokgung Station  Exit 7,  611m', 37.5722766, 126.9711879, NULL, NULL, NULL, 5),
	(212, 'Donuimun Museum', '03178  35-54, Saemunan-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Donuimun-Museum/ENP029381', 'Donuimun Museum is a new cultural space constructed from old restaurant buildings located in the old neighborhood of Saemunan. Originally built as residential homes back in 1960, these buildings were used as restaurants from 1990 to 2000, some of which included Italian restaurant AGIO and Korean restaurant Hanjeong. While preserving the architecture of the old structure, the buildings were reinforced for safety during their renovation into exhibition spaces.  Located in a central location within Saemunan surrounded by Seoul City Wall and the walls of Gyeonghuigung Palace, the spaces inhabited by AGIO and Hanjeong hold great historical and cultural value. When portions of Gyeonghuigung Palace Wall were discovered underground, the site has been transformed to preserve and display the remains. At Donuimun Museum, visitors can learn about the culture and history surrounding the area around it. ', 'Daily 09:00 - 18:00 (KST) (Last admission 17:30)', 'Closed Mondays & New Year\'s Day', 'Subway Line 5  Seodaemun Station  Exit 4,  400m', 37.570748, 126.9672224, NULL, NULL, NULL, 5),
	(213, 'Gallery Chosun', '03053  64, Bukchon-ro 5-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/gallerychosun/ENP5hau1h', 'Established in 2004, Gallery Chosun traces its roots to Chosun Gallery, which played a pioneering role by participating in international fairs such as ART COLOGNE in Germany, NICAF in Tokyo, and CIGE in Beijing, and organizing over 400 domestic exhibitions. Since its founding, Gallery Chosun has participated in Art Cologne and Art Basel Miami, focusing on contemporary art exhibitions to promote Korean contemporary art internationally.', '10:30-18:30', 'Closed every Monday', 'Subway Line 3, Anguk Station, Exit 2, 582m', 37.5799404, 126.9814744, NULL, NULL, NULL, 4),
	(214, 'Hohojae Seoul', '03054  71-7 Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/hohojae-seoul/ENPbnvhzx', 'Hohojae is a Hanok Gallery where the space and the artworks harmonize beautifully. Though the name uses the Chinese character ho (?? meaning butterfly, it also reflects the desire to create a place that brings a smile, like a cheerful ??hoho?? laugh. The exhibitions mainly feature works that are easy for the public to relate to. On the first floor, there is a cozy yard and a small flower bed, while the second floor offers a view of hanok rooftops in Palpan-dong through large windows, allowing visitors to fully enjoy the beauty of traditional Korean aesthetics.', 'Tuesday??Sunday 11:00??9:00', 'Every Monday', 'Subway Line 3, Anguk Station, Exit 2, 830 km', 37.5827948, 126.9807847, NULL, NULL, NULL, 4),
	(215, 'Hanji House', '03055  31-9 Bukchon-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/HanjiHouse/ENP6nkrnk', 'Hanji House is a space operated by the Korea Craft & Design Foundation to promote the excellence of hanji, a traditional heritage, and expand its use. Hanji House is a space where information on domestic hanji workshops and traditional paper is professionally collected, and it is also a hanji culture promotion center that promotes and exchanges hanji culture.', '10:00-19:00', 'Closed on Mondays', 'Subway Line 3 Anguk Station Exit 2, 355m', 37.5806135, 126.9838887, NULL, NULL, NULL, 5),
	(216, 'KCDF Gallery', '03145  8, Insadong 11-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/KCDFGallery/ENP037044', 'Located along the street of tradition itself, Insadong, KCDF Gallery is a space dedicated to the exhibition of crafts and was created to help promote the rise of the crafts industry, while contributing to a communicative platform for craftsmen and women, as well as the  dissessimation of the  consumer culture of crafts. The KCDF Library is also available, serving as a ground for  research activity that offers literature and various data on  a wide array of crafts designs along with  exhibitions, training programs, and  seminar spaces  for artists in the crafts design culture industry. On the first-floor shop of the gallery, visitors may also purchase premium crafts created by some of the finest specialists and artists in the country.* The Korea Craft & Design Foundation is a public government organization operated by the Ministry of Culture, Sports and Tourism that was established for the promotion of crafts, public design, and traditional & lifestyle culture. The foundation focuses on establishing a cultural identify of Korea through the  dissessimation  and promotion of crafts, design, and tradtional & lifestyle cultures , in addition to contributing to an improved quality of life by strengthening the country\'s compeitive capactiy.', '- Exhibition hall: Tue-Sun 10:00 - 18:00\n- Craft Garden: Tue-Sun 10:00 - 19:00\n(Break time 12:00 - 13:00)\n- KCDF Data Room: Tue-Fri 09:00 - 18:00 / Sat 10:00-19:00\n(Break time 12:00 - 13:00)', NULL, 'Subway Line 3  Anguk Station  Exit 6,  380m', 37.5740155, 126.9841199, NULL, NULL, NULL, 5),
	(217, 'The Museum of Korean Medical History', '130-050  26, Kyungheedae-ro, Dongdaemun-gu, Seoul', 'https://english.visitseoul.net/attractions/Museum-of-Korean-Medical-History-at-Kyung-Hee-University/ENP006886', 'The Museum of Korean Medical History at Kyung Hee University displays a wealth of information relating to medicine and history. Some of the artifacts on display are ancient medical books, medical records, and artifacts relating to traditional Korean medicine. Visitors can also learn about the development of traditional medicine in Korea throughout history and information is displayed by time period. The museum is open to the public.', 'Daily 10:00 - 16:00', 'Closed Weekends & Holidays', 'Subway Line 1  Hoegi Station  Exit 1,  1.2km', 37.5967122, 127.0513948, '대학  캠퍼스  드라마촬영지  고딕건축  밤풍경  추억 | 캠퍼스,  드라마촬영지,  경희대학교,  멜로무비,  사진찍기좋은곳 | KdramaTrip  CityBuilding  경희대학교  촬영지  북극성  건축물', 'a hundred memories | Melo Movie | North Star', 'https://blog.kakaocdn.net/dna/7Robm/dJMb9Qywtzv/AAAAAAAAAAAAAAAAAAAAAM1jzM-2LPBwTKFehVV_vKikH2eKtPRnA8mm8KiAeXR3/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=9YconSXy%2BB1mAHjsh4DjX3L0n90%3D | https://blog.kakaocdn.net/dna/bJsnP3/btsMk0rCZH9/AAAAAAAAAAAAAAAAAAAAADTIvUsR4t554_M5jQQw0QDo3Zs7gznDKoIy79-Zlwpy/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=pcMYG2uLlK6Bfgqf%2BaOferwKEt8%3D | https://blog.kakaocdn.net/dna/ckdbGn/btsQthjyRWH/AAAAAAAAAAAAAAAAAAAAAHWn3wj8hL8lbx-DlZMB_-KNLM82aR7dmsxLz3Q4UjY_/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=zX5fpD10mtbHTFZUh71EdwSqLkM%3D', 3),
	(218, 'Samsung Museum of Publishing', '03007  2-2, Bibong-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Samsung-Museum-of-Publishing/ENP003330', 'The Samsung Museum of Publishing is a private museum dedicated to all things related to printing and publishing. Located in Gugi-dong, Jongno-gu, visitors can see all manner of artifacts and historical items at the museum. Founded in 1990 by Kim Jonggyu of the Samsung Publishing Company, guided tours in Korean are available if reserved in advance.', 'Weekdays 10:00 - 17:00 (KST)', 'Closed weekends & holidays', 'Subway Lines 3 & 6, Bulgwang Station, Exit 2\n(Take bus nos. 7022 or  7211 ??Get off at Gugi Tunnel stop)\n Subway Line 3, Gyeongbokgung Station, Exit 3\n(Take bus nos. 7022 or 7212 ??Get off at Gugi Tunnel stop)', 37.6087042, 126.9570727, NULL, NULL, NULL, 5),
	(219, 'Kim Joong-up House of Architectural Culture', '02755  11, Jangwi-ro 21na-gil, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Kim-Joong-up-House-of-Architectural-Culture/ENP042446', 'Built in the 1970s, this two-story detached house was remodeled in 1986 by Kim Joong-up, who added exotic elements to every corner of the house based on traditional Korean architecture. This is a place where you can get a glimpse of the housing culture of the middle class at the time, and was designated as a Seoul Future Heritage in 2017. The KimJoong-up House of Architectural Culture harmoniously integrates Korean and Western architectural styles. The second-floor living room has an umul-maru, rafter structure, and windows covered with changhoji paper, which are mainly used in hanok, but with a modern interpretation. In contrast, the bathroom was designed in a European style. The dry bathroom with a dressing room attached, something that wasn??t common in Korea during the \'70s and \'80s, has a vintage jade-colored interior that stands out. Stepping out to the elegantly decorated garden, a water element, a characteristic of Kim Joong-up\'s architecture, is located on one side of the yard. Even equipped with its own small greenhouse, the Kim Joong-up House of Architectural Culture contains immense nature in the garden.', 'Daily 10:00 ~ 17:00', 'Closed Sundays & Mondays', 'Subway Line 6, Dolgoji Station, Exit 2,  1.5km', 37.6149824, 127.0440877, NULL, NULL, NULL, 5),
	(220, 'The Story of King Sejong ??The Story of Admiral Yi Sunshin', '03172  175, Sejong-daero, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/King-Sejong-and-Admiral-Yi-Sunshin/ENP005465', 'The Story of King Sejong and The Story of Admiral Yi Sunshin are exhibitions halls about two of Korea\'s national heroes, King Sejong and Admiral Yi. The exhibition halls are located on the B2 level of the Sejong Center for the Performing Arts. In addition to viewing the exhibitions, children can also experience traditional Korean culture and try on hanbok. For more information on these activities, please ask at the information desk.', 'Daily 10:00 - 18:30 (Last entry at 18:00 ) *Closed Mondays*', NULL, '* Subway Line 3, Gyeongbokgung Station, Exit 6   * Subway Line 5, Gwanghwamun Station, Exit 2 (30 m on foot)* Subway Line 1, Jonggak Station, Exit 1', 37.5727221, 126.9754023, NULL, NULL, NULL, 3),
	(221, 'Lotte World Folk Museum', '05554  240, Olympic-ro, Songpa-gu, Seoul', 'https://english.visitseoul.net/attractions/Lotte-World-Folk-Museum/ENP005815', 'The Lotte World Folk Museum highlights Korean folk culture through miniature displays. Located at Lotte World, visitors can enjoy seeing model villages from different periods of history. There is also a crafts room where visitors can see traditional crafts being made. The museum has a children\'s educational facility that runs various kid-friendly programs during school breaks.', '* Weekdays: 11:00 - 19:00 KST\n* Weekends: 11:00 - 20:00 KST\n??Last entry is 1 hour before closing.', 'Open year round', 'Subway Lines 2 / 8, Jamsil Station, Exit 2, 144m', 37.5112862, 127.0979392, '놀이공원,  데이트,  밤,  어트랙션,  킹더랜드,  서울 | 놀이공원,  가족,  모범택시2,  테마파크,  추억 | KdramaTrip,  닥터슬럼프,  호텔,  촬영지,  고급스러움,  서울 | 놀이공원,  테마파크,  가족,  친구,  정경,  강남순 | 롯데월드  테마파크  놀이기구  촬영지  가족  친구', 'King the Land | Model Taxi 2 | Dr. Slump | Strong Woman Gangnam Soon | Please take care of me this time, too', 'https://blog.kakaocdn.net/dna/LCPQv/btspmhjg2jV/AAAAAAAAAAAAAAAAAAAAAHcXdsuU1gudUZOE2agueQJEniRNnxVE2Y--Lb2I5twX/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=3lrQndyDTsjQYM1rTW6Y1bIFk50%3D | https://blog.kakaocdn.net/dna/uzCEj/btr1KwLasME/AAAAAAAAAAAAAAAAAAAAANrnd2t5QViMY33VTEke-EF6sQHIqNDEbaNWrjbwYKBL/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=ePex6eVuvBMoyii3EF3OtDlH9rM%3D | https://blog.kakaocdn.net/dna/b7DNt4/btsFm3RdLNC/AAAAAAAAAAAAAAAAAAAAAMRQUQeQHdLwT2tfSkhpmOCr3dQq2qmYoKBzAuCPZIHP/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=U6mBtKoAH%2F8nnRSWn0YCPs9FixU%3D | https://blog.kakaocdn.net/dna/r0OZc/btszknOq6uG/AAAAAAAAAAAAAAAAAAAAAPupEIxjVbt14WQUQXWDxlT2Xkxarv66hDhP3ossq0ym/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=Ziyoj7qompUc3YzHUiA2y1JSe4s%3D | https://blog.kakaocdn.net/dna/ErJMK/btsnGPhdbHs/AAAAAAAAAAAAAAAAAAAAADiK0om3be6HtZHU8K_5vUTvx6Hbe-wUgmoBQH-8SmjQ/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=4gFHB3sxT%2Fa0e7IZl1m22xnw80k%3D', 5),
	(222, 'Jeongdok Public Library', '03055  48, Bukchon-ro 5-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Jeongdok-Public-Library/ENP001596', 'The Jeongdok Public Library was established to provide Seoulites and visitors with a space to study and enjoy books. The library is affiliated with Yanbian Library in the Yanbian Korean Autonomous Prefecture of China and Japan\'s Tokyo Metropolitan Library. The Jeongdok Public Library is one of the major libraries of the city\'s public library system.', 'Study Rooms\n* Weekdays 07:00 - 22:00 (November - February 08:00 - 22:00)\n* Weekends 07:00 - 22:00 (November - February 08:00 - 22:00)', 'Closed on the 1st & 3rd Wednesday of the month, national holidays, and other days as designated by the library', 'Subway Line 3  Anguk Station  Exit 2,  720m', 37.5806135, 126.9838887, NULL, NULL, NULL, 5),
	(223, 'Gyeomjae Jeong Seon Art Museum', '07522  36, Yangcheon-ro 47-gil, Gangseo-gu, Seoul', 'https://english.visitseoul.net/attractions/Gyeomjae-Jeong-Seon-Art-Museum/ENP001961', 'The Gyeomjae Jeong Seon Art Museum is dedicated to the Joseon-era artist Jeong Seon. Located in Gangseo-gu, the museum has 4 levels. In addition to the special exhibition halls, there is a permanent memorial hall with information about the life and works of Jeong Seon. The museum\'s multipurpose facility can be used for lectures, seminars, and video screenings.', 'Tuesday to Friday: 10:00 ??18:00 \nSaturday and Sunday: 10:00 ??17:00 \nNational Holidays 10:00 - 17:00 \n??Last entry is 1 hour before closing.', 'Closed Mondays, New Year\'s Day, Lunar New Year\'s Day & Chuseok', 'Subway Line 9, Yangcheon Hyanggyo Station  Exit 1,  487m', 37.5722318, 126.838712, NULL, NULL, NULL, 5),
	(224, 'Gallery Jiwooheon', '03052  13, Bukchon-ro 11ra-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/GalleryJiwooheon/ENPxj9byw', 'Gallery Jiwooheon is an exhibition venue operated by Designhouse, Inc., located in Bukchon Hanok Village. It was selected as the 2016 Seoul Excellent Hanok for its distinctive structure remodeled from a hanok, which offers both trad itional aesthetics and contemporary convenience and has remarkable architectural beauty. It aspires to identify outstanding new artists at home and abroad while supporting the trend of contemporary art as a gallery with temporal and spatial qualities that shines a light on contemporary art in a space possessing the history of the past.', 'Tuesday-Saturday 10:00-18:00 KST (off-time 12:30~13:30)', 'Sunday, Monday, and public holidays', 'Subway Line 3  Anguk Station  Exit 2,  839m', 37.5832991, 126.9829449, NULL, NULL, NULL, 5),
	(225, 'Children\'s Folk Museum', '03045,  37, Samcheong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Childrens-Folk-Museum/ENP005130', 'Located at the National Folk Museum of Korea, the Children??s Folk Museum offers fun hands-on experiences relating to traditional Korean culture. The Children\'s Folk Museum charges no admission and it is located next to the second exhibition hall of the National Folk Museum of Korea. Capacity is limited and operating hours differ by month, so please check in hours advance. 50 people are admitted at a time, for thirty minutes sessions.', '09:30 - 17:00', 'Closed Mondays, January 1st, Lunar New Year & Chuseok', 'Subway Line 3 Anguk Station Exit 1, 900m', 37.5780505, 126.977124, NULL, NULL, NULL, 5),
	(226, 'Figure Museum W', '06014  3, Seolleung-ro 158-gil, Gangnam-gu, Seoul', 'https://english.visitseoul.net/attractions/Figure-Museum-W/ENP015863', 'The Figure Museum W is a museum dedicated to figurines and toys! Visitors to Seoul who have an interest in figurines, anime, and toys should make time to visit the museum. Exhibitions at the museum feature beloved superhero and animated figurines. Visitors can also purchase figures and souvenirs at the museum\'s gift shop.', 'Weekdays 13:00~17:00 Weekends 11:00~18:00', 'Closed Mondays, New Year\'s Day, Lunar New Year & Chuseok\n(If a holiday falls on a Monday, the museum opens on Monday and closes the following day.)', 'Subway Bundang Line  Apgujeong Rodeo Station  Exit 4,  103m', 37.5258005, 127.0403854, NULL, NULL, NULL, 7),
	(227, 'Korea University Main Hall & Old Main Library', '02841  145, Anam-ro, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Korea-University-Main-Hall--Old-Main-Library/ENP002962', 'Korea University is one of best universities in all of Korea. Visitors to Seoul can visit the Korea University Main Hall located in Anam-dong, Seoul. This beautiful three-story tall building was built in 1932 during the Japanese colonial period. In 1981 the hall was designated Historic Site No. 285 in 1981. The Old Korea University Main Library, located nearby, was designated Historic Site No. 286 in 1981.', 'Same hours as Korea University.', NULL, 'Subway Line 6  Anam Station  Exit 2,  527m', 37.5887496, 127.0323735, NULL, NULL, NULL, 3),
	(228, 'Shuim Museum', '03015  209-17, Segeomjeong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Shuim-Museum/ENP029578', 'Shuim Museum aims to preserve a forgotten culture by integrating it with contemporary culture and arts. Highlighting a heavy theme of life and death, the museum remodeled the founder\'s house as an exhibition venue and resting area. Holding exhibition on the museum\'s collection and various contemporary artists, Shuim Museum hopes to facilitate and encourage communications about art with its visitors.', '* Summer (Apr - Oct)\n- Tue - Sat 10:00 - 18:00 (KST)\n- Sun 14:00 - 19:00 (KST)\n\n* Winter (Nov - Mar)\n- Tue - Sat 10:00 - 17:00 (KST)\n- Sun 14:00 - 18:00 (KST)', NULL, 'Subway Line 3  Gyeongbokgung Station  Exit 3,  0212, 1020, 1711, 7016, 7018, 7022 (Get off at Sangmyung University Entrance). Subway Line 5  Gwanghwamun Station  Exit 3,  in front of Kyobo Building, 0212, 1020, 1711, 7016, 7018 (Get off at Sangmyung University Entrance).', 37.5994829, 126.9556748, NULL, NULL, NULL, 4),
	(229, 'National Palace Museum of Korea', '03045  12, Hyoja-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/National-Palace-Museum-of-Korea/ENP020550', 'The National Palace Museum of Korea showcases 500 years of history with roughly 45,000 artifacts from the Joseon Dynasty. Artifacts on display include texts and poems that were handwritten by kings of the past, robes worn by royalty, jewelry, and other items from the royal courts of Korea. Highlights from the museum collection are many, one highlight is the royal vehicle of Emperor Sunjong, the last king of the Joseon Dynasty. Another highlight of the colelction is the rain gauge pedestal. The rain gauge pedestal was an invention that dated back to the Joseon era.The museum also offers a learning program called "Experiencing Royal Culture;" the program is suitable for people of all ages. Spend time at the National Palace Museum of Korea to experience and learn about the grandeur and history of Korea\'s royalty.??Joseon Dynasty: The royal dynasty lasted from 1392 until 1910. The 518-year reign of the royal Lee family spanned 27 generations.??Rain Gauge Pedestal: The device was used to measure rainfall.??Royal Vehicle of Emperor Sunjong: The vehicle is a 1918 model of the General Motors Cadillac Limo usine.', 'Daily 10:00 - 18:00 \n* Wednesday · Saturday 10:00 - 21:00', 'Open year round', 'Subway Line 3  Gyeongbokgung Station  Exit 5,  135m', 37.5770207, 126.976631, NULL, NULL, NULL, 4),
	(230, 'Chung Won San Bang', '03056  27, Bukchon-ro 6-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Cheongwon-Sanbang/ENP004996', 'The name "Cheongwon Sanbang" is derived from Shim Yong-sik\'s carpenter\'s pen name "Cheongwon" and means "clear and round." Still making all the doors by hand in a traditional way, the center is dedicated to researching and preserving the window-knitting art, the face of hanok architecture. Shim Yong-sik, a craftsman who reinterprets traditional windows in a modern way and makes original windows, was selected as Seoul\'s Intangible Cultural Property No. 26 in 2006 in recognition of his achievements.', 'Saturday 10:00~17:00 (by appointment)', 'By reservation', 'Subway Line 3  Anguk Station  Exit 3,  430m', 37.5804268, 126.986364, NULL, NULL, NULL, 4),
	(231, 'Cheongwadae Sarangchae', '45, Hyoja-ro 13-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Cheongwadae-Sarangchae/ENP006007', 'Cheongwadae Sarangchae is a historical memorial museum where visitors can learn about the past, present, and future visions of Seoul and Korea. Originally the home of the public information hall of Cheongwadae (the Blue House, the Korean presidential residence) called ??Hyojadong Sarangbang?? it re-opened with its present name in January 2010 after extensive renovation. Cheongwadae Sarangchae is a two-story building, with exhibition halls, souvenir shops, a resting area on the first floor, and experience zones on the second floor.Cheongwadae Sarangchae features the Korea Hall, the Hi Seoul Hall, a traditional handicrafts demonstration room, a souvenir shop, and a café on the first floor. Various cultural events, such as demonstrations of traditional handicrafts and traditional Korean tea tasting, are held regularly in the lobby. The souvenir shop stocks Cheongwadae-themed goods and traditional Korean items. After viewing the exhibitions, it is pleasant to take a break at the café and enjoy a cup of traditional Korean tea.The Presidential Hall on the second floor displays material about the former presidents of Korea. Here visitors can explore the political and economic events of Korea from the past up to the present day via pictures and visuals. Visitors can also see at a glance a chronology of the past 60 years of Korean history, as well as the major events in the democratization and industrialization of Korea.', NULL, '- Closed Tuesdays (If a national holiday falls on Tuesdays, closed on the following weekdays)\n- On January 1st', 'Subway Line 3  Gyeongbokgung Station  Exit 4,  800m', 37.5826258, 126.9730991, NULL, NULL, NULL, 3),
	(232, 'Korea Furniture Museum', '02822  121, Daesagwan-ro, Seongbuk-gu, Seoul', 'https://english.visitseoul.net/attractions/Korea-Furniture-Museum/ENP003452', 'The Korea Furniture Museum is a unique museum that focuses only on traditional wooden furniture. The museum\'s collection boasts more than 2,500 pieces of traditional Korean furniture. Rather than exhibiting the collection behind glass in a regular museum set-up, the pieces are displayed in 10 hanok to show visitors how these pieces would have actually been used in daily life. Visitors must make reservations in advance to visit the museum. Reservations can be made online in English at the museum\'s website and the ticket includes a guided tour.', '*The museum is currently closed for renovation.', 'Closed Mondays, Sundays & Public Holidays', 'Subway Line 4, Hansung University Station Exit 6, take Bus No. 02 to Seongbuk and get off at the entrance of the Korea Furniture Museum, 196m', 37.5991431, 126.9894544, NULL, NULL, NULL, 3),
	(233, 'Bukchon Asian Cultural Art Museum', '03052  76, Bukchon-ro 11-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Bukchon-Asian-Cultural-Art-Museum/ENP005667', 'The Bukchon Asian Cultural Art Museum displays Korean and Asian artwork. The museum\'s founder, Kwon Youngdu, dedicated 30 years of his life to collecting art from Korea and other parts of Asia. Located in the Bukchon Hanok Village, the museum was constructed in the style of a traditional Korean hanok. The museum also offers activities programs such as folk painting and traditional cooking.', '10:00 - 18:30', NULL, 'Subway Line 3  Anguk Station  Exit 2,  903m', 37.5840252, 126.9834474, NULL, NULL, NULL, 4),
	(234, 'Seoul Metropolitan Library', '04524   110, Sejong-daero, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Seoul-Metropolitan-Library/ENP010231', 'The former Seoul City Hall has reopened its doors as the city\'s main public library. Seoul Metropolitan Library is the city\'s main public library and it\'s easily accessible from City Hall Station\'s exit 4 or 5. The "Tong Tong" Seoul City Walking Tour takes visitors through the library and the new Seoul City Hall building. Tours are free and led by a cultural tour guide.', '* Weekdays 09:00 - 21:00 KST\n* Weekends 09:00 - 18:00 KST', 'Closed Mondays', 'Subway Lines 1 / 2, City Hall Station, Exits 4,  126m', 37.5665851, 126.9782038, NULL, 'Vincenzo', NULL, 5),
	(235, 'Beautiful Tea Museum', '03162  19-11, Insadong-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Beautiful-Tea-Museum/ENP004467', 'The Beautiful Tea Museum collects and exhibits information and items related to tea. Located in an elegant Hanok in the Insa-dong area, visitors can learn about and sample a wide range of teas. There are also porcelain works on display and for purchase from talented ceramists. At the tea shop inside the museum, over 110 kinds of tea from around the world including Korea, China, Japan, and Europe are on offer. Admission to the museum is free.', 'Gallery 11:30 - 20:00 KST\n* Museum open year-round', 'Open year round', 'Subway Lines 1/3/5, Jongno 3(sam)-ga Station  Exit 5,  241m', 37.5722892, 126.9858284, NULL, NULL, NULL, 5),
	(236, 'Popcon D Square', '04377  55, Hangang-daero 23-gil, Yongsan-gu, Seoul  Hyundai I-Park Mall, Popcon D Square', 'https://english.visitseoul.net/attractions/Popcon-D-Square/ENP025768', 'Popcon D Square is a cultural space operated by Daewon Media, a company specializing in animation. Through spaces that reflect the imaginary more than reality, visitors will be sure to enjoy their experiences here.    A place that shows a wide range of exhibitions not limited to a country or genre, Popcon D Square continues to expand itself as a place where visitors can come to enjoy culture and content within the city.', 'Weekdays 10:30 - 20:30\nFridays & Weekends 10:30 - 21:00', NULL, 'Subway Line 4, Sinyongsan Station, Exit 2,  240m', 37.5287067, 126.9632193, NULL, NULL, NULL, 5),
	(237, 'Choonwondang Museum of Korean Medicine', '03139  27, Donhwamun-ro 9-gil, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Choonwondang-Museum-of-Korean-Medicine/ENP002637', 'The Choonwondang Museum of Korean Medicine first opened in 2008 and is dedicated to hanbang, also known as Oriental medicine. The museum spans 7 floors, from the B1 level to the 6th floor and there are exhibitions halls, a decocting room, a quality inspection facility, a cultural space, a doctor??s office and an infirmary. The museum\'s exhibition halls display various historical artifacts relating to Oriental medicine. Display pieces date from the Three Kingdoms era to the Joseon Dynasty. The museum is gaining popularity as a new cultural venue where people can learn about Korean culture and hanbang.', 'Mondays-Fridays 09:00 - 18:00 (KST)\nSaturdays 09:00 - 13:00 (KST)', 'Closed Sundays & national holidays', 'Subway Lines 1/3/5, Jongno 3(sam)-ga Station  Exit 5,  186m', 37.5715924, 126.9901734, NULL, NULL, NULL, 5),
	(238, 'Heunginjimun Gate (Dongdaemun)', '03119,  288, Jong-ro, Jongno-gu, Seoul)', 'https://english.visitseoul.net/attractions/Heunginjimun-Gate/ENP001999', 'Heunginjimun Gate is a major historical site in Seoul. More commonly known as Dongdaemun Gate (Great Eastern Gate), it was designated treasure no. 1 by the Korean government. During the Joseon Dynasty, Heunginjimun Gate was one of eight city gates along the historic Seoul City Wall and it served as the main gate for the eastern part of the city. Heunginjimun is known for its exquisite architecture and beauty; the gate is also a spectacular sight at night. After viewing Heunginjimun, visitors may want to explore the Dongdaemun neighborhood and do some late-night shopping.', 'Open 24 hours', NULL, 'Subway Lines 1/4  Dongdaemun Station  Exit 9,  74m', 37.5708912, 127.0112322, NULL, NULL, NULL, 5),
	(239, 'Hongjimun Gate and Tangchundaeseong Fortress', '03021  212 Segeomjeong-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Hongjimun-Gate-and-Tangchundaeseong-Fortress/ENP004101', 'Tangchundaeseong Fortress was built in 1712 during the Joseon Dynasty to improve the defense of Hanyangdoseong, the Seoul City Wall, and the Bukhansanseong Fortress. Hongjimun Gate was built during the reign of King Sukjong, the 19th king of the Joseon Dynasty. Legend has it that King Sukjong wrote ??Hongjimun??on the gate\'s original name-board himself and the gate was called Hongjimun thereafter. After passing through Hongjimun Gate, Tangchundaeseong Fortress comes into view. These days, the Tangchundaeseong area offers one of the most beloved hiking trails in Seoul. The hiking trail has a gentle slope for leisurely walks.', 'Open 24 hours', NULL, 'subway line 3  Hongje Station  exit 1,   take the bus toward Sangmyung University, and get off in front of Sangmyung University.', 37.5990116, 126.9573182, NULL, NULL, NULL, 5),
	(240, 'Changuimun Gate', '03020  118, Changuimun-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Changuimun-Gate/ENP003266', 'Located in Buam-dong, Changuimun Gate is one of the four minor city gates of Seoul. It is also sometimes referred to as Bukmun (North Gate) or Jahamun. The gate was built by King Taejo, the first king of the Joseon Dynasty, when he constructed the fortifications surrounding the capital. In Korean history, Changuimun Gate is best known by Koreans as the gate that the rebellion faction used to enter Seoul in the Coup of 1623. A road was built to the west of the gate that accommodates traffic but Changuimun Gate itself is closed.', NULL, NULL, 'subway line 3  Gyeongbokgung Station  exit 3,  take local bus 1020 or 7022, get off at Jahamun Pass/Yun Dong-ju Literature Museum, 51m', 37.5966149, 126.9677679, NULL, NULL, NULL, 4),
	(241, 'Gyeongbokgung Palace', '03045  161, Sajik-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gyeongbokgung/ENP000072', 'Gyeongbokgung Palace was the first and largest of the royal palaces built during the Joseon Dynasty. Built in 1395, Gyeongbokgung Palace was located at the heart of the newly appointed capital of Seoul (then known as Hanyang) and represented the sovereignty of the Joseon Dynasty. The largest of the Five Grand Palaces (the others being Gyeonghuigung Palace, Deoksugung Palace, Changgyeonggung Palace, Changdeokgung Palace), Gyeongbokgung served as the main palace of the Joseon Dynasty.The Korean government has invested much time and effort into rebuilding, restoring, and maintaining the palace for future generations. These efforts include work to rebuild and restore the buildings that were destroyed during the Japanese occupation. Visitors to Gyeongbokgung can also visit the National Palace Museum of Korea and the National Folk Museum of Korea as they are located on the palace grounds. To increase ease of accessibility from Gyeongbokgung Palace to Seochon and vice versa, the palace\'s western gate, Yeongchumun, was opened to the public on December 2018. For the past 43 years, there were only 3 entrances to Gyeongbokgung Palace - the southern gate Gwanghwamun, the northern gate Sinmumun, and the eastern entrance of National folk Museum of Korea. However, with the opening of the western gate Yeongchumun, entry to the palace from all directions has been now made possible.', 'January & February: 09:00 - 17:00\nMarch - May: 09:00 - 18:00\nJune - August: 09:00 - 18:30 \nSeptember & October: 09:00 - 18:00\nNovember & December: 09:00 - 17:00\n*Last entry one hour before closing*', NULL, 'Subway Line 5, Gwanghwamun Station, Exit 2,  471m\nSubway Line 3, Gyeongbokgung Station, Exit 5,  216m', 37.5808473, 126.9768515, '경복궁  역사  전통건축  드라마촬영지  산책  문화체험 | KdramaTrip  광화문  역사  도시풍경  사진명소  문화탐방 | 경복궁  전통  산책  촬영지  자연  역사 | 드라마촬영지,  광화문,  야경,  서울,  역사적인장소 | 혼례대첩  경복궁  전통문화  역사체험  드라마촬영지', 'a distant view | One day, the life of a major | The phone you\'re calling right now | the Battle of the Wedding', 'https://blog.kakaocdn.net/dna/bl6eGQ/btsLGhnjr6q/AAAAAAAAAAAAAAAAAAAAAFXAPN99lOa1an0qtZ2dRmhNKnV2LsxF2BSO2oytDm5O/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=cPTf7i8VaDaP%2F34v0GZo08nck3E%3D | https://blog.kakaocdn.net/dna/xhj40/btsNh06pJng/AAAAAAAAAAAAAAAAAAAAAMFhElpzprIZzhIdEq7asWXgAlTrcavNrRqNYRou_E71/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=x491oadmQCJ7uVxpolm3hxse%2B6o%3D | https://blog.kakaocdn.net/dna/bh5Wac/btsNLCXzzSq/AAAAAAAAAAAAAAAAAAAAAMXnHrX18BwhNYpEUkbcHp-vqKdyF3GF7mu89Wq8nRaw/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=ys%2B8xpOoqKINBDCebdbi3qrKQwI%3D | https://blog.kakaocdn.net/dna/bYzT5p/btsKS3LYj3Z/AAAAAAAAAAAAAAAAAAAAAOAjrESdppsHcai8Xy4O0y9_9StZj_K3I5xjoAYA4_I-/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=%2FLLytVpo39JBTHLX0ADEdlCYyhg%3D | https://blog.kakaocdn.net/dna/dBkP1p/btszpAfWpA3/AAAAAAAAAAAAAAAAAAAAAPDTbzc8z-CE1Rtpzh_6iGN_CHET_CLcZ02DR7YcjOqJ/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=E8yMvzaFzQbU5LYOpWKiZcfLK6g%3D', 5),
	(242, 'Sungnyemun Gate (Namdaemun)', 'Subway Lines 1 / 4 / Gyeongui-Jungang Line/ Airport Railroad  Exit 4,  258m  \nSubway Line 4  Hoehyeon Station  Exit 5,  403m', 'https://english.visitseoul.net/attractions/Sungnyemun-Gate-Namdaemun-Gate/ENP022888', 'Sungnyemun Gate (Namdaemun) is one of Seoul\'s historic Four Great Gates and it was designated National Treasure no. 1 by the Korean government in 1962. Though its official name is Sungnyemun, it is also popularly known as Namdaemun Gate due to its location at what was once the southern end of Seoul. As the centuries passed, Seoul grew in size but Sungnyemun Gate has endured through the ages.         Construction on the gate was started in 1395 and completed in 1398. In 1447, Sungnyemun saw reconstruction work carried out. The gate is the largest city gate with an arched entrance in the city, and atop the gate\'s wooden base stands a 2-story wooden structure. The gate is Seoul\'s oldest wooden structure but on Feb. 10th, 2008, much of the gate\'s wooden structure was destroyed by fire. Following several years of restorative work, Sungnyemun Gate can now be enjoyed in all its glory.   ??,-9246,Tue-Sun 09:00-18:00,Monday,04528  40', ' Jung-gu', ' Seoul"', 'https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68265&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68266&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=68267&fileTy=MEDIA&fileNo=2&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73967&fileTy=MEDIA&fileNo=1&thumbTy=L | https://english.visitseoul.net/comm/getImage?srvcId=MEDIA&parentSn=73968&fileTy=MEDIA&fileNo=1&thumbTy=L', 99.99999999, 0, NULL, NULL, NULL, 38),
	(243, 'Gyeongbokgung Stonewall Walkway', '03045  161 Sajik-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-gbgstonewall/ENPldz98j', 'The Gyeongbokgung Stonewall Walkway is a walkway that surrounds Gyeongbokgung Palace. Centered around Gwanghwamun, to the left is the west gate of Gyeongbokgung, Yeongchumun; to the north is the north gate, Sinmumun; and to the right is the east gate, Geonchunmun. The left side of the Gyeongbokgung Stonewall Walkway connects to Seochon, while the north connects to the Blue House. The right side leads to Bukchon and Samcheong-dong, where visitors can also explore the National Museum of Modern and Contemporary Art and the National Folk Museum of Korea. The path is well-maintained, perfect for a stroll while experiencing the changing seasons. Walking along the Gyeongbokgung Stonewall Walkway offers a unique view that changes with the weather, whether it\'s raining or snowing.', NULL, NULL, 'Subway Line 3, Gyeongbokgung Station, Exit 4, 430m', 37.5808473, 126.9768515, '경복궁  역사  전통건축  드라마촬영지  산책  문화체험 | KdramaTrip  광화문  역사  도시풍경  사진명소  문화탐방 | 경복궁  전통  산책  촬영지  자연  역사 | 드라마촬영지,  광화문,  야경,  서울,  역사적인장소 | 혼례대첩  경복궁  전통문화  역사체험  드라마촬영지', 'a distant view | One day, the life of a major | The phone you\'re calling right now | the Battle of the Wedding', 'https://blog.kakaocdn.net/dna/bl6eGQ/btsLGhnjr6q/AAAAAAAAAAAAAAAAAAAAAFXAPN99lOa1an0qtZ2dRmhNKnV2LsxF2BSO2oytDm5O/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=cPTf7i8VaDaP%2F34v0GZo08nck3E%3D | https://blog.kakaocdn.net/dna/xhj40/btsNh06pJng/AAAAAAAAAAAAAAAAAAAAAMFhElpzprIZzhIdEq7asWXgAlTrcavNrRqNYRou_E71/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=x491oadmQCJ7uVxpolm3hxse%2B6o%3D | https://blog.kakaocdn.net/dna/bh5Wac/btsNLCXzzSq/AAAAAAAAAAAAAAAAAAAAAMXnHrX18BwhNYpEUkbcHp-vqKdyF3GF7mu89Wq8nRaw/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=ys%2B8xpOoqKINBDCebdbi3qrKQwI%3D | https://blog.kakaocdn.net/dna/bYzT5p/btsKS3LYj3Z/AAAAAAAAAAAAAAAAAAAAAOAjrESdppsHcai8Xy4O0y9_9StZj_K3I5xjoAYA4_I-/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=%2FLLytVpo39JBTHLX0ADEdlCYyhg%3D | https://blog.kakaocdn.net/dna/dBkP1p/btszpAfWpA3/AAAAAAAAAAAAAAAAAAAAAPDTbzc8z-CE1Rtpzh_6iGN_CHET_CLcZ02DR7YcjOqJ/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=E8yMvzaFzQbU5LYOpWKiZcfLK6g%3D', 5),
	(244, 'Changdeokgung Secret Garden', '03072  99 Yulgok-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/2024-cdggarden/ENPl8f5md', 'The Secret Garden (Huwon) at Changdeokgung Palace, once used for royal entertainment and ceremonies, is a significant heritage site showcasing traditional landscaping. Covering around 446,943 square meters, this expansive royal garden still has restricted areas that remain inaccessible to the public. Historically, it was off-limits to commoners, reserved only for the Joseon royal family. Nestled against Maebong Peak of Bugaksan Mountain, the garden features several ponds, including Buyongji, home to Buyongjeong Pavilion, Aeryeonji, Jangbangji, and Banwolji. The arrangement of pavilions and buildings reflects traditional Korean architecture, demonstrating a masterful harmony between structures and nature.', 'Korean\n- November to February: 10:00 ??15:00 (entry every hour)\n- March to October: 10:00 ??16:00 (entry every hour)\n\nEnglish\n- December to February: 10:30 / 11:30 / 14:3\n- March to November: 10:30 / 11:30 / 14:30 / 15:30\n\nJapanese\n- January to December: 13:30 (operates every Wednesday, Friday, and Sunday)\n\nChinese\n- January to December: 12:30 (operates every Tuesday, Thursday, and Saturday)\n\n*Admission is limited to 100 people per session by language (50 online reservations + 50 on-site ticketing).\n*Korean visitors are not allowed to enter the garden during foreign language tours except when accompanied by up to two foreign visitors.', 'Closed Mondays. (If the regular closure day falls on a public holiday or substitute holiday, the site will remain open, and the next non-holiday will be the regular closure day.)', 'Subway Line 3  Anguk Station  Exit 3,  389m', 37.5811161, 126.9927916, NULL, 'Rooftop Prince', NULL, 5),
	(245, 'Gyeonghuigung Palace', '03177  45, Saemunan-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Gyeonghuigung/ENP001159', 'One of the five grand palaces, Gyeonghuigung Palace was also called "Seogweol" (which means "palace of the west") because it\'s located west of the main palace, Gyeongbokgung. In its heyday, it was part of a vast complex, with 100 buildings in total, but most of these were destroyed during the Japanese occupation. Following intensive restoration work, it reopened to the public in 2002. On its grounds stand the Seoul Museum of History and the Gyeonghuigung Annex Building of the Seoul Museum of Art.    The palace was originally constructed by order of King Gwanghae, the fifteenth king of the Joseon Dynasty, and was completed in 1623. From the beginning, it was much-loved and served as a secondary palace for some ten kings of the Joseon Dynasty.     A variety of Korean art can also be seen in the Gyeonghuigung Annex building of the Seoul Museum of Art, which is situated on the Gyeonghuigung site. Also, the Seoul Museum of History, one of the foremost tourist attractions in the city, houses a permanent collection allowing visitors to see how Seoul has developed and transformed from prehistoric times to the present day.', 'Daily 09:00 - 18:00 KST *Closed Mondays*', 'January 1st', 'Subway Line 5  Gwanghwamun Station  Exit 1,  875m \nSubway Line 5  Seodaemun Station  Exit 4,  639m', 37.5714656, 126.9684165, NULL, NULL, NULL, 5),
	(246, '7th Royal Culture Festival', '03045  161, Sajik-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/7thRoyalCultureFestival/ENP036912', 'This year\'s 7th Royal Culture Festival is slated to take place from May 1 (Saturday) to May 9 (Sunday) both on and offline! The festival will take place with several infamous sights set as the background, including Gyeongbokgung Palace, Changdeokgung Palace, Deoksugung Palace, Changgyeonggung Palace, Gyeonghuigung Palace, Jongmyo Shrine, and the Sajikdan Altar. Several culture and arts programming is in store, ranging from on and offline performances utilizing the aesthetic and historical significance of these sites, as well as exhibitions, experiential programs, ceremonial rituals, and more!Festival programming includes the following:An opening ceremony, palaces loved by artists, online children\'s royal culture festival, palace photo contest, royal guard exchange ceremony, saenggwabang, and other programs inclusive of the palace areas.', NULL, NULL, '* Subway Line 3, Gyeongbokgung Station* Subway Line 5, Gwanghwamun Station', 37.5808473, 126.9768515, '경복궁  역사  전통건축  드라마촬영지  산책  문화체험 | KdramaTrip  광화문  역사  도시풍경  사진명소  문화탐방 | 경복궁  전통  산책  촬영지  자연  역사 | 드라마촬영지,  광화문,  야경,  서울,  역사적인장소 | 혼례대첩  경복궁  전통문화  역사체험  드라마촬영지', 'a distant view | One day, the life of a major | The phone you\'re calling right now | the Battle of the Wedding', 'https://blog.kakaocdn.net/dna/bl6eGQ/btsLGhnjr6q/AAAAAAAAAAAAAAAAAAAAAFXAPN99lOa1an0qtZ2dRmhNKnV2LsxF2BSO2oytDm5O/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=cPTf7i8VaDaP%2F34v0GZo08nck3E%3D | https://blog.kakaocdn.net/dna/xhj40/btsNh06pJng/AAAAAAAAAAAAAAAAAAAAAMFhElpzprIZzhIdEq7asWXgAlTrcavNrRqNYRou_E71/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=x491oadmQCJ7uVxpolm3hxse%2B6o%3D | https://blog.kakaocdn.net/dna/bh5Wac/btsNLCXzzSq/AAAAAAAAAAAAAAAAAAAAAMXnHrX18BwhNYpEUkbcHp-vqKdyF3GF7mu89Wq8nRaw/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=ys%2B8xpOoqKINBDCebdbi3qrKQwI%3D | https://blog.kakaocdn.net/dna/bYzT5p/btsKS3LYj3Z/AAAAAAAAAAAAAAAAAAAAAOAjrESdppsHcai8Xy4O0y9_9StZj_K3I5xjoAYA4_I-/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=%2FLLytVpo39JBTHLX0ADEdlCYyhg%3D | https://blog.kakaocdn.net/dna/dBkP1p/btszpAfWpA3/AAAAAAAAAAAAAAAAAAAAAPDTbzc8z-CE1Rtpzh_6iGN_CHET_CLcZ02DR7YcjOqJ/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1764514799&allow_ip=&allow_referer=&signature=E8yMvzaFzQbU5LYOpWKiZcfLK6g%3D', 5),
	(247, 'Deoksugung Palace', '100-120  99 Sejong-daero, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Deoksugung-Palace/ENP002046', 'Deoksugung Palace is unique among Korean palaces in having a modern seal engraving and a western style garden and fountain. Medieval and modern style architecture exists together in harmony in Deoksugung Palace. The Changing of the Royal Guard can be seen in front of Daehanmun (Gate) and is a very popular event for many visitors. During the Joseon Dynasty, the royal guard was responsible for opening and closing the palace gate as well as patrolling around the gate area. Outside the palace is a picturesque road flanked by a stone wall which is much loved by visitors.   Originally, Deoksugung Palace was not a palace. The Imjin War (the Japanese invasions in 1592) left all the palaces in Korea severely damaged. When King Seonjo (the fourteenth king of the Joseon Dynasty) returned to Seoul from his evacuation, the primary palace Gyeongbokgung Palace had been burnt to the ground and other palaces were also heavily damaged. A temporary palace was chosen from among the houses of the royal family. This is the origin of Deoksugung Palace. King Gwanghaegun (the fifteenth king of the Joseon Dynasty) named the palace Gyeongungung, formalizing it as a royal palace. Since then it has been used as an auxiliary palace by many Joseon kings. In 1897, Emperor Gojong (the twenty-sixth king of the Joseon Dynasty) stayed here and expanded it. The modern buildings such as Seokjojeon (Hall) were constructed during this period. In 1907, the palace was renamed Deoksugung.', 'Daily 9:00 - 21:00 (Last entry 20:00)', 'Closed Mondays', 'Subway Line 1/2 City Hall Station  Exit 1,  72m', 37.565936, 126.9750354, NULL, NULL, NULL, 5),
	(248, 'Unhyeongung Palace', '03131  464, Samil-daero, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/UnhyeongungPalace/ENP000471', 'Unhyeongung Palace is one of Seoul\'s smaller palaces and it is an important historic site that is open to the public. The palace was formerly the private residence of Emperor Gojong\'s father, the prince regent Heungseon Daewongun. The young Gojong lived here before he assumed the throne and his wedding to Myeongseong took place here. An annual re-enactment of the royal wedding ceremony between Emperor Gojong and Empress Myeongseong takes place here at the palace.      During the reign of Emperor Gojong, Unhyeongung was as grand as any other palace in Seoul, but over time, many of the palace buildings were heavily damaged and destroyed. Today, visitors can see what has been preserved of the palace and take part in traditional cultural activities and crafts experiences. On weekends, visitors can watch Seoulites get married in traditional Korean wedding ceremonies at the palace.', 'Daily 09:00 - 19:00 KST (Last entry 18:30 KST ) *Closed Mondays*', 'Closed Mondays \n* Open on Mondays falling on public holidays', 'Subway Line 3  Anguk Station  Exit 4,  103m', 37.5763968, 126.9886656, '사극드라마', NULL, NULL, 4),
	(249, 'Changgyeonggung Palace', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Changgyeonggung-Palace/ENP000297', 'Changgyeonggung Palace was built in 1483 by King Seongjong (the ninth king of the Joseon Dynasty) to take care of the wives of the preceding kings. Compared to other palaces, the size of the palace is compact and simple. Changgyeonggung Palaceis connected with Changdeokgung Palace. It\'s located east of the primary palace of Gyeongbokgung, so it is also referred to as "Donggwol," the "East Palace."Myeongjeongjeon is the main hall of the palace, where state affairs were held, such as meetings with officials and the reception of foreign envoys. In particular, Myeongjeongjeon represents an outstanding example of seventeenth century Joseon architectural style and is the oldest main hall of any palace. While visiting Changgyeonggung Palace, it is recommended you visit nearby Changdeokgung Palace as well.Most of the palace buildings were destroyed by the Japanese during the Japanese invasion of Korea in 1592. The main buildings such as Myeongjeongjeon, Munjeongjeon (council hall), Hwangyeongjeon (Hall), Inyangjeon (Hall), Gongsacheong, and Honghwamun (Gate) were rebuilt by King Gwanghaegun (the fifteenth king of the Joseon Dynasty). During the Japanese occupation, the Japanese built a zoo on the site and renamed the palace "Changgyeongwon," meaning "Changgyeong Garden." Since 1987, the palace has been reconstructed and now resembles its original form.', 'Daily 09:00 - 21:00 (Last entry at 20:00)', 'Closed Mondays', 'Subway Line 4  Hyehwa Station  Exit 4,  779m', 37.5811161, 126.9927916, NULL, NULL, NULL, 5),
	(250, 'Hyehwamun Gate', '03076  307, Changgyeonggung-ro, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Hyehwamun-Gate/ENP023606', 'Hyehwamun Gate is one of Seoul\'s 4 minor city gates. It was built in 1397 along the famed Hanyangdoseong, Seoul City Wall along the Joseon-era eastern boundary of the city. Hyehwamun Gate was also known as Dongsomun Gate (Minor East Gate). Today, it is easily accessible on foot and it is a picturesque and historic Seoul attraction.', NULL, NULL, 'Subway Line 4  Hansung University Station  Exit 5,  192m', 37.587767, 127.001779, NULL, NULL, NULL, 6),
	(251, 'Hanyangdoseong (Seoul City Wall)', '03038  283, Yulgok-ro, Jongno-gu, Seoul (Jongno 6-ga, Seoul Design Support Center)', 'https://english.visitseoul.net/attractions/Seoul-City-Wall/ENP000090', 'The Seoul City Wall was originally built in 1396, surrounding Seoul (then known as  Hanyang) during the Joseon Dynasty (1392-1897). The wall stretches for 18.6km along the ranges of Bugaksan Mountain, Naksan Mountain, Namsan Mountain, and Inwangsan Mountain. The wall stands at average heights of 7 - 8 m high. Along the Seoul City Wall, there once stood eight gates that were originally built between 1396-1398, but only six remain standing. The North, South, East, and West gates of the wall are known as the ??Four Great Gates??(Sukjeongmun, Heunginjimun, Sungnyemun, Dongeuimun), while the Northwest, Northeast, Southwest, and Southwest gates are known as the ??Four Minor Gates??(Changuimun, Hyehwamun, Gwanghuimun, Soeuimun). ', NULL, NULL, 'Subway Lines 1 / 4  Dongdaemun Station  Exit 1,  287m', 37.5719508, 127.0076798, NULL, NULL, NULL, 5),
	(252, 'Changdeokgung Palace', '03072  2-71, Waryong-dong, Jongno-gu, Seoul', 'https://english.visitseoul.net/attractions/Changdeokgung-Palace/ENP000295', 'Changdeokgung Palace is the second UNESCO World Heritage Site in Seoul. It was selected as a representative palace for its notable beauty in the history of palace architecture in East Asia and for its excellent arrangement with the surrounding naturalenvironment. Changdeokgung Palace was built by King Taejong in 1405.   During the Imjin War, Joseon lost both Gyeongbokgung Palace and Changdeokgung Palace. Reconstructed in the 2nd year of Gwanghaegun (1610), Changdeokgung was used as the royal palace of Joseon for about 270 years.    Changdeokgung Palace has two major tour programs. The first is the general tour, which is a basic tour that covers Injeongjeon ', 'February - May, 09:00 - 18:00 (Last entry at 17:00)\nJune - August, 09:00 - 18:30 (Last entry at 17:30)\nSeptember - October, 09:00 - 18:00 (Last entry at 17:00)\nNovember - January, 09:00 - 17:30 (Last entry at 16:30)', 'Closed Mondays', 'Subway Line 3  Anguk Station  Exit 3,  389m', 37.5811161, 126.9927916, NULL, 'Kingdom', NULL, 5),
	(253, 'Chundangji Pond', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul, Korea (??룡동, 창경???', 'https://english.visitseoul.net/attractions/Chundangji-Pond/ENP039629', 'On the rear garden grounds of Changgyeonggung Palace sits Chundangji Pond. It is known for its beautiful nature and fall foliage. Chundangji consists of two parts. The smaller upper half is the original location of the pond, while the lower half was initially used as a naenongpo , a place for the royal court to experiment with planting crops such as rice. However, during the Japanese occupation in 1909, the naenongpo was converted into a pond. In 1986, it was renovated into a traditional Korean style. Visitors can also see the seven-story pagoda, made in 1470, sitting on the shore of the pond.', 'Daily 09:00 - 21:00 (Last entry at 20:00)', 'Every Monday (if the closed day falls on a public holiday, it will be closed the following day)', 'Subway Line 4  Hyehwa Station  Exit 4,  994m', 37.5788149, 126.9949298, NULL, 'Kingdom', NULL, 5),
	(254, 'Gwanghuimun Gate', '04612  350 Toegye-ro, Jung-gu, Seoul', 'https://english.visitseoul.net/attractions/Gwanghuimun-Gate/ENP023605', 'Gwanghuimun Gate is one of the Seoul\'s 4 minor city gates. It is located along the southeastern boundary of Joseon-era Seoul. It was known by two other names throughout history, Sugumun Gate and Sigumun Gate. In 1719, it was officially named Gwanghuimun Gate and its name has been the same ever since. In 1975, the gate underwent successful restoration work. Visitors can stop by and see the gate as it is located near the modern Seoul landmark, Dongdaemun History and Culture Park.', NULL, NULL, 'Subway Lines 2/4/5  Dongdaemun History and Culture Park Station   Exit 3,  143m', 37.5640368, 127.0123062, NULL, 'Hotel Del Luna', NULL, 5),
	(255, 'Grand Greenhouse Changgyeonggung Palace', '03072  185, Changgyeonggung-ro, Jongno-gu, Seoul, Korea (창경???', 'https://english.visitseoul.net/attractions/GrandGreenhouseChanggyeonggungPalace/ENP037176', 'Changgyeonggung Palace, one of the four main historical palaces in Seoul, houses a greenhouse built in 1909. It is Korea\'s first greenhouse designed in a Western architectural style. Initially, there was a botanical garden and a zoo. In 2004, the building was restored, retaining the original appearance of the greenhouse, and is open to the public. Here you will find different types of plants, both local and imported from other countries.', '09:00 - 20:45', 'Mondays', 'Subway Line 4  Hyehwa Station  Exit 4,  779m', 37.5788149, 126.9949298, NULL, 'Kingdom', NULL, 5);
