INSERT INTO `restaurant` (`restaurant_id`, `restaurant_name`, `place`, `image_path`, `description`, `Latitude`, `Longitude`, `price`, `near_subway`, `signature_menu`, `operatingday`, `website`, `type`, `notice`, `operatinghour`, `tel`, `holidays`) VALUES
	(1, '통인시장', '03036  서울 종로구 자하문로15길 18', 'images/통인시장_1.jpg', 'SBS [런닝맨], KBS [1박2일]의 촬영지이자, 엽전 도시락과 기름 떡볶이로 유명한 전통시장.\n\n세종마을은 추사 김정희 등 조선시대 예능인들이 모이는 중심지였으며 근대에도 이상 등 문인들이 활동하던 중심지였습니다. 일제강점기 일본인들을 위해 만들어진 공설시장이 모태이나 6.25이후 인구증가로 시장의 필요성이 높아져 현재처럼 물건을 사고파는 시장의 형태를 갖추게 되었습니다.  통인시장은 상권이 활성화된 곳으로 다른 전통시장의 벤치마킹 사례로 유명하며 특히 통인시장에서 자체 제작한 엽전은 통인시장만의 즐길 거리입니다. 엽전으로 환전함과 동시에 검은색 플라스틱 식판도 받게 되는데 이때부터 식판을 들고 다니면서 시장 곳곳을 다니며 음식을 먹을 수 있습니다. 단, 엽전은 가맹점에서만 사용 가능합니다.', 37.580755, 126.969996, '', '지하철 3호선 경복궁역 2번 출구, 515m', '', '', ' https://tonginmarket.modoo.at/', '음식점', '', '통인시장 영업시간 : 07:00 ~ 21:00\n※ 상점에 따라 상이하며, 정확한 개점, 폐점 시간은 없음\n\n도시락 카페 영업시간 화~금 11:00 ~ 16:00, 토~일 11:00 ~ 17:00\n※ 도시락 카페 엽전 판매는 평일 11:00 ~ 15:00, 주말 11:00 ~ 16:00까지', '02-722-0911', '통인시장 휴무일 : 매월 셋째주 일요일\n도시락 카페 휴무일 : 매주 월요일, 매월 셋째주 일요일'),
	(2, '삼청각', '02822  서울 성북구 대사관로 3 (성북동, 삼청각)', 'images/삼청각_2.png', '삼청각은 전통예술복합문화공간. 한국의 유명한 대목장 박광석과 대목수 조승원이 참가해서 지은 곳으로 1972년 7.4남북공동성명 대표단 만찬장소이자 서울시에서 지정한 근대문화유산 . 공연장, 한식당, 찻집, 객실 등으로 구성되어있으며 월요일을 제외하고는 연중 전통공연.\n\n삼청각은 여야 고위정치인의 회동과 남북적십자회담, 한일회담 협상 장소로 이용되었던 전통예술복합문화공간입니다. 공연장, 한식당, 찻집, 객실 등으로 구성되어있으며 월요일을 제외하고는 연중 전통공연이 열립니다. 삼청각에 있는 건물들은 한국의 건축미를 느낄 수 있는 한옥으로, 본채인 일화당과 동백헌, 유하정, 취한당, 천추당, 청천당 등 5개의 별채로 이루어져 있습니다. 이 중 일화당 1층에 삼청각 한식당이 있습니다. 삼청각 한식당은 고급한식을 자연의 풍류와 함께 즐길 수 있는 훌륭한 장소입니다.', 37.597400, 126.984141, '', '지하철 5호선 광화문역 교보문고 앞 셔틀버스 이용(10:00~21:00)', '산청(12만원), 인청(15만원), 수라(20만원)', '', ' http://www.samcheonggak.or.kr', '음식점', '', '12:00~22:00', '02-765-3700', '명절 당일 휴무'),
	(3, '카몽(KAMONG)', '06647  서울 서초구 서초대로42길 17 (서초동)', 'images/카몽(KAMONG)_3.jpg', '엑소의 멤버 ‘카이가 꿈을 꾸다’ 라는 뜻을 가진 카페 카몽은 카이의 누나가 운영하고 있는 곳으로 엑소 팬들의 아지트.\n\n엑소의 멤버 ‘카이가 꿈을 꾸다’라는 뜻을 가진 카페 카몽은 카이의 누나가 운영하고 있는 곳으로, 엑소 팬들의 아지트 같은 곳입니다. 인기 메뉴는 아이스크림과 신선한 과일을 곁들인 와플이며, 컵과 냅킨 등의 소품에서 카이가 직접 그린 그림과 메시지들을 발견할 수 있습니다. 카이가 엑소 멤버들과 방문하는 모습이 팬들에게 종종 포착되기도 합니다.', 37.491208, 127.008940, '', '2호선 서초역 1번 출구에서 약 120m (도보 1분)', '', '매일', ' http://instagram.com/kamong.coffee', '카페, 디저트', '*매월 첫째주 토요일은 와플을 판매하지 않습니다.', '월요일 ~ 금요일 08:30 ~ 22:00\n토요일 11:00 ~ 22:00\n일요일 11:00 ~ 22:30', '0507-1498-5951', ''),
	(4, '놀부유황오리진흙구이(잠실점)', '05549  서울 송파구 오금로 131 (방이동)', 'images/놀부유황오리진흙구이(잠실점)_4.jpg', '황토진흙으로 만든 토기에 유황오리를 넣고, 450。가마에서 3시간 동안 익힌 것.\n\n보약을 다리는 정성으로 구워내는 유황오리. 유황오리 진흙구이는 황토진흙으로 만든 토기에 유황오리를 넣고, 450。가마에서 3시간 동안 익힌 것으로 많은 시간과 정성이 담겨 있습니다. 유황오리 속에는 찹쌀과 흑미, 서리태로 지은 밥은 물론 당귀, 인삼, 녹각, 감초, 은행, 무화과, 잣 등의 보약재까지 넉넉하게 들어갑니다.', 37.511540, 127.109904, '', '지하철 9호선 송파나루역 2번 출구, 256m', '유황오리 진흙구이, 유황오리, 통오리훈제바베큐', '', '', '음식점', '', '11:30~22:00 (15:00~17:00 브레이크타임)', '0507-1383-5292', '연중 무휴'),
	(5, '클럽 NB2', '04041  서울 마포구 와우산로 72', 'images/클럽_NB2_5.png', '한류스타가 즐겨찾는 강남역 거리 및 홍대 클럽 거리에 위치한 대형 힙합댄스 클럽 YG엔터테이먼트의 대표이자 SBS 오디션 프로그램 [K팝스타] 심사위원으로 활약 중인 양현석이 운영하는 주점으로 유명\n\n강남역 거리 및 홍대 클럽 거리에 위치한 대형 힙합댄스 클럽입니다. ’99년 말 홍대에 첫선을 보인 클럽 nb는 이후 강남점, 홍대 2호점이 잇따라 문을 열며 클럽 붐을 일으켰습니다. 국내외 힙합 뮤지션 및 DJ의 공연을 즐길 수 있습니다. 유명인들이 자주 방문합니다.', 37.550910, 126.923345, '', '지하철 6호선 상수역 2번 출구, 341m', '', '월요일~일요일', ' https://www.instagram.com/clubnb_official', '술집, 바', '', '일요일~목요일 22:00~06:00, 금요일~토요일 21:30~07:00', '0507-1323-8213', ''),
	(6, '명동교자', '04537  서울 중구 명동10길 29', 'images/명동교자_6.jpg', '진하고 걸쭉한 칼국수의 맛. 입 안 가득 퍼지는 햇밀의 향기와 부드럽고 차진 면발. 깊고 진한 닭 뼈 육수.\n\n칼국수하면 떠오르는 원조 명동칼국수. 진하고 걸쭉한 칼국수의 맛이 그리울 땐‘명동교자’에 들러보세요. 입 안 가득 퍼지는 햇밀의 향기와 부드럽고 차진 면발은 오감(五感)을 만족시키기에 충분합니다. 닭 뼈를 장시간 푹 고아 우려 낸 육수는 한 번 맛을 들이면 다른 칼국수는 밋밋하게 느껴질 정도로 깊고 진합니다.', 37.562561, 126.985609, '1만원대', '지하철 4호선 명동역 8번 출구, 183m', '칼국수, 비빔국수, 만두', '', ' http://www.mdkj.co.kr', '음식점', '', '10:30~21:00', '0507-1366-5348', '추석 당일'),
	(7, '필경재', '06352  서울 강남구 광평로 205', 'images/필경재_7.jpg', '필경재는 서울 강남구 수서동에 있는 조선시대 전통가옥 한식당.\n\n필경재는 서울 강남구 수서동에 있는 조선시대 전통가옥입니다. 전주이씨 정안부정공의 종갓집으로 내려오는 종택이며 전통건조물 제1호로 지정되어있습니다. 1999년부터는 궁중음식 전문점으로 운영되고 있습니다.', 37.484905, 127.095242, '', '지하철 3호선 / 수인분당 / GTX-A 수서역 1번 출구, 616m', '미정식, 죽정식, 국화정식', '', ' http://www.philkyungjae.co.kr ', '음식점', '', '매일 12:00~15:00, 18:00~22:00', '02-445-2115', '명절 당일 휴무'),
	(8, '파미에스테이션', '06546  서울 서초구 신반포로 176 (센트럴시티)  파미에스테이션', 'images/파미에스테이션_8.jpg', '내로라하는 국내 맛집을 한곳에 모아놓은 전 세계 다양한 맛의 공간\n\n파미에스테이션은 내로라하는 국내 맛집을 한곳에 모아놓은 전 세계 다양한 맛의 공간입니다. 트렌드세터들이 찾는 핫플레이스로 소문난 맛집들과 건강한 식재료만을 고집하는 브랜드까지 새로운 맛과 멋을 경험할 수 있는 곳입니다. 뉴욕 그랜드 센트럴스테이션과 같은 전통적인 역사(驛舍)를 테마로 설계되어 전통과 모던함이 조화를 이룹니다. 총 3개 층으로 구성되어 있으며, 1층엔 국내외 소문난 맛집, 2층과 3층엔 뷰티 살롱 및 카페 등이 위치해 있습니다.', 37.503935, 127.002413, '', '지하철 3/7/9호선 고속터미널역 4번 출구, 64m', '', '', '', '음식점', '', '10:00~22:00\n일부 매장 브레이크타임(15:00~17:00)\n일부 매장 운영시간 상이 - 개별 페이지 참조', '02-6282-0114', ''),
	(9, 'BHC 사당점', '07015  서울 동작구 동작대로7길 16 (사당동)', 'images/BHC_사당점_9.jpg', 'BHC 사당점은 틴탑 리키의 부모님이 최근 오픈한 치킨 전문점. 지하 1층부터 옥상 테이블까지 자리가 넉넉하게 마련되어 있으며, 매장 곳곳에 리키와 틴탑 멤버들의 사진과 사인이 장식.\n\nBHC 사당점은 지하 1층부터 옥상 테이블까지 자리가 넉넉하게 마련되어 있습니다. 최근 인기를 얻고 있는 매운맛 치킨인 ‘맵스터’를 비롯해 인도 커리를 활용한 ‘커리치킨’, 해바라기유로 튀겨 고소한 식감이 일품인 ‘해바라기 프라이드치킨’ 등이 인기 메뉴입니다.', 37.479923, 126.980702, '', '지하철 2 / 4호선 사당역 10번 출구, 244m', '뿌링클, 맵스터, 커리치킨, 해바라기 프라이드치킨', '월 ~ 일', ' http://www.bhc.co.kr', '음식점', '', '12:00 - 02:00', '02-582-2004', '연중무휴'),
	(10, '씨제이더마켓 제일제당센터점', '04560  서울 중구 동호로 330 (쌍림동, 씨제이제일제당센터)  지하1층', 'images/씨제이더마켓_제일제당센터점_10.jpg', '특별한 미식과 새로운 라이프스타일, 식문화 트렌드를 경험할 수 있는 복합 식문화 공간.\n\n2018년 6월 1일에 문을 연 서울에서 가장 ‘핫’한 곳 중 하나. 특별한 미식과 새로운 라이프스타일, 식문화 트렌드를 경험할 수 있는 복합 식문화 공간입니다. CJ제일제당의 모든 가정 간편식 브랜드 제품부터 해외 유명 브랜드 식재료까지 한꺼번에 쇼핑하고, 즉석에서 맛도 볼 수 있습니다. 정문을 열고 들어갔을 때 왼쪽에는 브랜드 스토어인 ‘올리브 그로서리’가, 오른쪽에는 레스토랑인 ‘올리브 델리’가 있습니다. 올리브 그로서리에서는 CJ제일제당의 가정 간편식제품과 신선한 식재료들을 보고, 즐기고, 쇼핑할 수 있습니다. 올리브 델리에서는 전문 셰프가 CJ제일제당의 가정 간편식 제품에 제철 식재료를 더해 개발한 외식 메뉴를 맛볼 수 있습니다. 이곳의 또 다른 특징은 세련된 ‘토핑 바’이다. 조식시간에 방문하면 CJ가정간편식 자판기에서 햇반 컵반을 구매한 후 무료로 자신의 입맛에 맞게 계란지단, 콩나물, 대파 슬라이스 등 각종 토핑들을 햇반 컵반에 얹어 먹을 수 있습니다. CJ가정간편식 자판기도 지나쳐서는 안 됩니다. 흔히 볼 수 있는 햇반 컵반이 아닌 무려 ‘박보검 에디션’이라는 사실! 인스타그램에서 품절 여부를 따로 안내해줄 정도로 인기가 많으니, 헛걸음하지 않기 위해서는 미리 확인하도록 하세요.', 37.563974, 127.003253, '', '지하철 2/4/5호선 동대문역사문화공원역 6번 출구, 118m', '비비고 닭한마리 죽, 제주 오겹살과 멜젓소스가 만난 고기 쌈밥정식, 문어랑 해초랑 비빔밥', '매일', ' https://www.instagram.com/CJOlivemarket/', '음식점', '', '평일 09:00 - 21:00\n주말 11:00 - 21:00', '02-6740-7952', ''),
	(11, '삼거리포차', '04067  서울특별시 마포구 와우산로 70 (서교동)', 'images/삼거리포차_11.jpg', '20대에게 주로 인기가 많은 술집으로 통오징어 떡볶이가 유명, 7080의 감성.\n\n삼거리포차는 20대에게 주로 인기가 많은 술집으로 통오징어 떡볶이가 유명하며 복고 느낌의 인테리어를 통해 7080의 감성을 느낄 수 있습니다. 나이를 불문하고 신분증이 없을 시, 출입이 통제되므로 공적으로 인정받을 수 있는 신분증을 반드시 지참해야 합니다.', 37.550699, 126.923311, '', '지하철 6호선 상수역 2번 출구, 333m', '', '', '', '술집, 바', '', '17:00 ~ 05:30 (라스트오더 05:00)', '02-3144-6748', ''),
	(12, '패션파이브', '04399  서울특별시 용산구 이태원로 272 (한남동)', 'images/패션파이브_12.jpg', '한남동의 랜드마크. 인테리어, 맛, 데코까지 훌륭.\n\n한남동의 랜드마크. 인테리어, 맛, 데코까지 훌륭한 디저트 카페입니다. 가격은 다소 부담스럽지만 눈과 입이 즐거운 고급스런 빵을 맛볼 수 있는 특권을 누릴 수 있습니다.', 37.538712, 127.002075, '', '지하철 6호선 한강진역 3번 출구, 169m', '베이커리', '월요일 ~ 일요일', ' https://xn--5-bv4f396b.com/', '카페, 디저트', '', '07:30 ~ 22:00', '0507-1416-9505', '연중무휴'),
	(13, '지화자', '03031  서울 종로구 자하문로 125 (청운동)', 'images/지화자_13.jpg', '서울의 중심부에 위치한 고급 전통 한식당\n\n1991년부터 국가무형문화재가 직접 운영하는 지화자는 서울의 중심부에 위치한 고급 전통 한식당입니다. 지화자는 한국 음식 문화의 본질인 궁중음식을 선보이는 최고급 레스토랑으로 높은 평판을 얻었으며, 600년의 조선 왕조의 역사가 고스란히 담긴 정갈하고 품위 있는 음식을 선보입니다. MSG, 인공 향신료 등 어떠한 첨가물을 사용하지 않고 천연재료와 조선 왕실의 숙련된 조리법으로 내어지는 지화자의 요리는 매우 건강하고 영양이 풍부합니다. 지화자(Jiwhaja)는 3대에 걸쳐 전 세계에 한국의 전통 음식문화, 한국의 궁중음식을 홍보하기 위해 노력해왔고 앞으로도 계속 이어갈 것입니다.', 37.587097, 126.969416, '', '지하철 3호선 경복궁역 3번 출구, 1.2km', '● 풀코스\n-장금만찬\n- 진어별만찬\n- 진어만찬\n\n● 세트메뉴\n- 소갈비수라\n- 전복초수라\n- 해물신선로수라', '월요일, 수요일~일요일', ' http://www.jihwajafood.co.kr/', '음식점', '', '11:30~15:00, 17:00~21:30 (18:30 라스트오더)', '02-2269-5834', '매주 화요일은 정기휴일입니다.'),
	(14, '마복림 할머니 막내 아들네 떡볶이', '04611  서울특별시 중구 다산로 221 (신당동)', 'images/마복림_할머니_막내_아들네_떡볶이_14.jpg', '빨간 떡볶이의 원조 ‘신당동 떡볶이’를 만든 마복림 할머니의 막내아들이 비법을 전수받아 운영하는 떡볶이 전문점 정용화, 서현 커플이 출연한 MBC 예능 <우리 결혼했어요>촬영지\n\n빨간 떡볶이의 원조 \'신당동 떡볶이\'를 만든 마복림 할머니의 며느리가 비법을 전수받아 운영하는 떡볶이 전문점입니다. 신당동 떡볶이 타운 내에 위치하고 있습니다. 인기가 많아져 최근에는 택배 배송 서비스도 제공하고 있습니다.', 37.562923, 127.015091, '', '지하철 2 / 6호선 신당역 7번 출구 250m', '떡볶이', '', ' http://xn--220b9hl7b09cc7ibcj00gh4p49w8p4b.com/', '음식점', '', '24시간', '02-2253-1466', ''),
	(15, '더숲 초소책방', '03033  서울 종로구 인왕산로 172', 'images/더숲_초소책방_15.jpg', '책과 자연에 둘러싸여 쉬어가는 시간을 즐길 수 있는 초소 책방\n\n책과 자연에 둘러싸여 쉬어가는 시간을 즐길 수 있는 초소 책방은 인왕산 중턱에 자리 잡고 있습니다. 50년 넘게 청와대 방호를 위해 경찰 초소로 사용됐던 곳이며 2020년에 등산객, 시민들의 쉼터이자 책을 즐기는 공간으로 새롭게 태어났습니다. 특히 환경 문제를 중심으로 많은 책들이 초소 책방을 채우고 있어 녹색 책방이라고도 불립니다. 눈이 힐링 되는 인왕산의 풍경을 보며 잠시 여유를 가져보세요.  서울의 야경 명소로도 잘 알려져 있어 맛있는 음료와 함께 야경을 즐기는 것도 추천합니다.', 37.583341, 126.962708, '', '', '아메리카노 4,900원\n에스프레소 4,900원\n카페라떼 5,900원', '매일', ' https://deosup.com/42', '카페, 디저트', '', '08:00 ~ 22:00 (21:30 모든 주문 마감)', '02-735-0206', ''),
	(16, '켄싱턴 호텔 뉴욕뉴욕', '07238  서울 영등포구 국회대로76길 16  켄싱턴호텔 1층', 'images/켄싱턴_호텔_뉴욕뉴욕_16.jpg', '고급스러운 인테리어와 프라이빗 다이닝룸, 드라마 실내 촬영장소로 최다 이용\n\n켄싱턴 호텔의 양식 전문레스토랑 뉴욕뉴욕은 고급스러운 인테리어와 프라이빗 다이닝룸의 구비로 대한민국 국내 드라마의 실내 촬영장소로 최다 이용된 기록이 있습니다. 드라마 <솔 약국집 아들들>, <아내의 유혹>, <내조의 여왕>, <최고의 사랑> 등의 촬영에 이용된 바 있습니다.', 37.530289, 126.921969, '', '지하철 9호선 국회의사당역 1번 출구, 528m', '러브 인 뉴욕(1인 기준) - 159,000원', '매일', ' https://www.kensington.co.kr/hyd/dining/detail?idx=29', '음식점', '', '11:30 ~ 21:00 (16:00~18:00 브레이크타임)', '02-6670-7270', ''),
	(17, '통인시장 기름떡볶이', '03036  서울 종로구 자하문로15길 13 (통인동)', 'images/통인시장_기름떡볶이_17.jpg', '통인시장의 기름떡볶이는 외국인들도 즐겨 찾는 한국 대표 음식. 기름떡볶이는 가마솥 뚜껑에 양념한 떡을 노릇하게 볶아내는 것이 특징.\n\n통인시장의 기름떡볶이는 외국인들도 즐겨 찾는 한국 대표 음식입니다. 기름떡볶이는 가마솥 뚜껑에 양념한 떡을 노릇하게 볶아내는 것이 특징입니다. 종류는 기름과 간장을 혼합한 양념을 바르고 구운 흰 떡볶이와 고춧가루 양념을 바르고 볶은 빨간 떡볶이 두 종류가 있습니다. <통인시장의 대표 기름떡볶이집으로는 서울 떡볶이 3대 명가 중 한 곳으로 TV 미식 프로그램에 소개된바 있는 ‘원조 할머니 떡볶이집’과 지난 2014년 미국 존 케리 국무장관이 방한했을 때 다녀갔던 ‘효자동 옛날 떡볶이집’이 있습니다.', 37.580661, 126.970223, '', '지하철 3호선 경복궁역 2번 출구, 569m', '', '매일', ' https://mo1067.modoo.at/', '음식점', '재료 소진 시 영업 종료', '08:00 ~ 19:00 (점포별 상이)', '02-725-4870', '셋째 주 일요일 휴무'),
	(18, '음악의 숲', '04607  서울 중구 동호로 192 (신당동)', 'images/음악의_숲_18.jpg', '음악의 숲 카페 한쪽 벽면을 가득 채운 LP판들.\n\n음악의 숲 카페를 들어서면, 벽면을 가득 채운 LP판들이 제일 먼저 눈에 들어옵니다. 그러고 나면 벽에 그려져 있는 비틀즈의 그림과 턴테이블을 돌리고 있는 DJ이자 주인장이 보입니다. 과거에 그랬듯이 쪽지로 신청곡을 받아서 틀어주며 영화 <써니>의 촬영지입니다.', 37.555364, 127.010660, '', '지하철 3호선/6호선 약수역 2번 출구, 약 3m (도보 1분)', '', '', '', '술집, 바', '', '월요일~토요일 18:00~24:00', '02-2274-2254', '일요일'),
	(19, '어니언', '04797  서울 성동구 아차산로9길 8 (성수동2가)', 'images/어니언_19.jpg', '어니언은 70년대에 지어진 건물을 개조해 만든 카페. 그동안 슈퍼, 식당, 가정집 그리고 얼마 전까지 금속부품 공장으로 사용. 현재는 20여 종의 빵과 커피를 판매.\n\n70년대에 지어진 건물을 개조해 만든 카페입니다. 이 건물은 그동안 슈퍼, 식당, 가정집 그리고 얼마 전까지 금속부품 공장으로 사용되어 오래된 바닥과 벽면을 그대로 살려 세월의 흔적을 고스란히 느낄 수 있습니다. 이곳에서는 20여 종의 빵과 커피를 판매하고 베이커리의 경우 ‘앙버터의 달인’으로 TV에 소개된 바 있는 ‘브래드05’의 제품을 맛볼 수 있습니다.', 37.544761, 127.058199, '', '2호선 성수역 2번 출구에서 132m (도보 1분)', '', '매일 (명절 당일, 연휴 기간 정상 영업)', ' https://onionkr.com/#anchor2', '카페, 디저트', '', '월요일~금요일 08:00~22:00\n주말 09:00~22:00\n(21:30 라스트오더)', '0507-1386-3238', ''),
	(20, '효자베이커리', '03036  서울 종로구 필운대로 54', 'images/효자베이커리_20.jpg', '콘브레드가 유명한 서촌 1호 빵집\n\n청와대를 돌아 골목을 따라 내려가다 보면 통인시장 옆에 위치한 빵집을 만날 수 있습니다 . 1987 년부터 35 년을 이어오고 있는 효자베이커리는 간판부터 예스럽고 정겹습니다. 오랜 시간 방송과 매체를 통해 입소문이 난 서촌 1 호 빵집으로 단과자 , 도넛 , 고로케 등 옛날 빵집에서 맛볼 수 있던 빵들부터 요즘 인기 있는 발효빵과 베이글까지 준비되어 있어 선택의 폭이 넓습니다 . 워낙 유명하고 인기가 많은 곳이라 주말에는 품절 되는 것들도 많습니다 .', 37.580939, 126.968536, '', '3호선 경복궁역 2번 출구에서 697m (도보 10분)', '', '화요일~일요일', '', '카페, 디저트', '', '화요일~일요일 08:00 ~ 20:20\n* 준비된 상품 소진 시 조기 마감 됩니다.', '02-736-7629', '월요일'),
	(21, '황생가칼국수', '03053  서울 종로구 북촌로5길 78 (소격동)', 'images/황생가칼국수_21.jpg', '인기 메뉴는 왕만두가 들어간 버섯전골, 1인분에 왕만두 3개와 칼국수.\n\n황생가 칼국수(구 북촌칼국수)는 삼청동 대표 맛집으로 평양식 사골 칼국수 전문점입니다. 왕만두와 사골 칼국수는 사골에 우려낸 육수와 부드러운 면발이 더해져 깊고 깔끔한 맛을 냅니다. 대표 인기메뉴에는 9가지 야채와 쫄깃한 만두피로 만들어진 왕만두와 칼국수가 있습니다. 점심, 저녁시간대에는 항상 사람들로 북적거리므로 시간대를 피하는 것을 추천합니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.580079, 126.980669, '1만원대', '지하철 3호선 안국역 2번 출구, 649m', '사골칼국수, 버섯전골, 왕만두국, 왕만두', '', ' http://황생가칼국수.com/', '음식점', '', '매일 11:00 ~ 21:30 (20:40 라스트오더)', '02-739-6334', '명절 휴무'),
	(22, '오목집', '07997  서울특별시 양천구 목동서로 155 (목동)', 'images/오목집_22.jpg', '< 별에서 온 그대>의 천송이(전지현)가 늙지 않는 도민준(김수현)을 의식해 피부 관리 차원에서 찾아간 유명 족발집.\n\n< 별에서 온 그대>의 천송이(전지현)가 늙지 않는 도민준(김수현)을 의식해 피부 관리 차원에서 찾아간 유명 족발집입니다. 직접 담근 된장으로 삶은 족발을 전문으로 판매하고 있습니다. 가족 단위에서 맛있게 즐기기 좋으며, 소박하고 아늑한 인테리어가 따뜻한 분위기를 더합니다. 대표 메뉴인족발을 주문하면 해물냄비를 무료로 제공합니다.', 37.529996, 126.875072, '', '지하철 5호선 오목교역 2번 출구, 493m', '족발', '월요일~일요일', ' http://www.sgfco.kr/', '음식점', '', '14:00 ~ 23:00', '0507-1419-6692', '명절 당일'),
	(23, '오다리집', '04536  서울특별시 중구 명동8나길 28 (충무로1가)', 'images/오다리집_23.jpg', '오다리집은 명동에 위치한 간장게장 맛집으로, 중국인 관광객과 일본인 관광객의 가장 많이 즐겨 찾는 맛집\n\n오다리집은 명동에 위치한 간장게장 맛집으로, 중국인 관광객과 일본인 관광객의 가장 많이 즐겨 찾는 맛집으로 꼽히기도 했습니다. 전문성을 위해 양념게장이 아닌 간장게장만을 취급하며, 그 밖에 한우와 국내산 삼겹살도 판매합니다. 저녁 7시부터는 k-pop 라이브를 들으며 식사할 수 있습니다.', 37.561431, 126.983459, '3만원대', '지하철 4호선 명동역 5번 출구, 209m', '', '', ' http://www.odarijip.com', '음식점', '', '08:10 ~ 24:00', '0507-1412-6767', '연중무휴'),
	(24, '오장동함흥냉면', '04559  서울 중구 마른내로 108 (오장동, 오장동함흥냉면)', 'images/오장동함흥냉면_24.jpg', '매콤 새콤한 회무침이 별미인 함흥냉면\n\n오장동함흥냉면은 한혜선 사장이 한국전쟁 이후 오장동에서 시작한 냉면집으로, 함경도 사람들이 즐겨 먹던 함흥냉면을 전국적으로 알리게 된 곳입니다. 1970년대 이후, 재개발이나 시대적 흐름에 따라 오장동에 있던 많은 함흥식 냉면집이 사라졌지만, 오장동함흥냉면은 매콤한 소스와 신선한 회 고명, 얇은 면발맛의 깊이를 더하면서 설탕, 참기름, 식초의 조화로 감칠맛을 더한 매력적인 냉면을 만들어왔기에 지금까지 자리를 지키고 있습니다.', 37.564358, 126.999836, '1만원대', '지하철 2 / 5호선 을지로4가역 8번 출구, 356m', '냉면', '월요일, 수요일~일요일', ' https://ojangmyeonok.modoo.at/', '음식점', '', '11:00 ~ 20:00 (Break Time 15:30 ~ 17:00)', '02-2267-9500', '화요일, 명절 휴무'),
	(25, '마우스래빗', '05017  서울 광진구 능동로11길 10', 'images/마우스래빗_25.jpg', '슈퍼주니어의 예성과 그 동생이 운영하는 마니아층을 확보한 카페.\n\n흰색의 테라스가 인상적인 유럽풍 카페 마우스래빗은 슈퍼주니어의 멤버 예성과 그의 친동생이 운영하는 카페입니다. 서로 다른 분위기와 매력을 갖춘 3개 층의 매장은 취향에 맞는 층과 테이블을 선택하는 재미가 있습니다. ‘토끼굴’, ‘지하세계’로 불리는 지하 1층은 좌식형 테이블과 운치 있는 벽난로가 놓여 있고, 조도를 낮춰 더욱 편안하게 휴식을 취할 수 있습니다. 계산대와 야외테라스가 있는 1층과 아기자기한 소품과 피규어들로 장식된 매장과 야외 테라스가 있는2층까지세심한 손길로 구석구석 배치된 조명과 액자, 소품들이 돋보입니다. 마우스래빗이 직접 디자인하고 수작업으로 제작한 페이퍼토이, 핸드폰케이스, 머그컵, 에코백 등 다양한 아트상품들은 이미 마니아층을 확보할 만큼 인기가 많습니다.마우스래빗은 카페를 운영하는 예성과 그의 친동생이 각자의 띠를 상징하는 동물인 쥐와 토끼를 합쳐 마우스래빗으로 이름 붙였다고 하고 매장 안 쇼케이스 위에는 예성의 사진들이 가득하며 마우스래빗이 직접 제작하는 아트상품을 구매할 수도 있어 슈퍼주니어 팬들의 발길이 끊이지 않고 있습니다.', 37.541999, 127.070902, '', '지하철 2/7호선 건대입구역 3번 출구, 201m', '아메리카노, 레몬모히또, 딸기빙수, 초코빙수', '', ' http://www.instagram.com/mouserabbit_official', '카페, 디저트', '지하 1층은 좌식으로 벽난로가 있으며, 1층과 2층에는 테라스가 있다.', '매일 12:00 ~ 23:00', '02-462-4015', ''),
	(26, '수연산방', '02837  서울 성북구 성북로26길 8 (성북동, 상허 이태준 가옥)', 'images/수연산방_26.jpg', '단편소설가 이태준 씨의 집필 공간이었던 한옥의 고풍스러운 찻집\n\n전통산방으로, 한옥으로 되어 있어 전통스럽고 고풍스럽습니다. 우리나라 단편소설의 선구자인 이태준 씨의 집필 공간을 외종 손녀인 주인이 1998년부터 찻집으로 개방한 곳입니다. 전통 차와 함께 나오는 죽순 인절미, 죽순 찹쌀떡 등의 다과도 즐길 수 있고 단소, 소금 레슨을 원하면 문의 하세요.', 37.595053, 126.994836, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 1.3km', '대추차, 엄마손 순 단호박범벅, 생강차, 단호박빙수', '수요일 - 일요일', ' https://blog.naver.com/sooyeonsanbang1998', '카페, 디저트', '', '수요일~금요일 11:30 ~ 17:50\n토.일요일 11:30 ~ 19:50', '02-764-1736', '월요일·화요일 휴무'),
	(27, '라칸티나', '04523  서울 중구 을지로 19 (을지로1가, 삼성빌딩)  삼성빌딩 지하 1층', 'images/라칸티나_27.jpg', '우리나라 최초 이탈리안 레스토랑\n\n라 칸티나는 1960년대 삼성그룹 창립자 이병철 회장의 권유로 개업한 서울의 오랜 이탈리안 레스토랑으로, 한국의 정·재계 및 외교계 인사들이 즐겨 찾던 장소였습니다. 이탈리아어로 ‘지하의 포도주 창고’를 의미하는 이름처럼, 이탈리아의 와인 저장고를 연상케 하는 분위기를 제공하며, ‘스파게티 콘 레 봉골레’와 같은 한국식 이탈리안 음식을 개발했습니다. 또한, 이병철 회장이 즐겨 먹었던 ‘삼성세트’라는 특별 메뉴도 있습니다.', 37.566306, 126.979957, '', '지하철 2호선 을지로입구역 1-1번 출구, 100m', '쇠고기 소스 파스타, 버터와 로마노 치즈 파스타, 버섯소스 파스타', '', '', '음식점', '', '월~토 11:30 ~ 15:00 / 17:00 ~ 22:00\n공휴일 17:00 ~ 22:00', '02-777-2579', '매주 일요일'),
	(29, '우래옥', '04546  서울 중구 창경궁로 62-29 (우래옥)', 'images/우래옥_29.jpg', '불고기와 냉면이 유명. 쇠고기만으로 우려낸 육수의 담백한 풍미 . 60년 평양냉면의 전통을 지켜오는 동안 미국까지 진출하여 냉면의 세계화.\n\n불고기와 냉면이 유명합니다. 특히 냉면 맛에 정통한 손님들이 잊지 않고 찾는 이유는 쇠고기만으로 우려낸 육수의 담백한 풍미 때문입니다. 60년 평양냉면의 전통을 지켜오는 동안 미국까지 진출하여 냉면의 세계화를 꾀하고 있습니다.', 37.568216, 126.998815, '1만원대', '지하철 2 / 5호선 을지로4가역 4번 출구, 99m', '평양냉면, 순면, 불고기(150g)', '화요일~일요일', '', '음식점', '', '11:30 ~ 21:00 (20:40 라스트오더)', '02-2265-0151', '월요일, 명절 휴무'),
	(30, '무교동북어국집', '04522  서울특별시 중구 을지로1길 38 (다동)', 'images/무교동북어국집_30.png', '1968년부터 이어져 오는 북엇국 전문점. 냉동 황태가 아닌 단단하게 말린 북어로 끓인 것이 특징. 구수하고 담백한 맛의 뽀얀 국물에 반한 사람들이 점심때면 줄을 늘어섬. 리필이 가능.\n\n1968년부터 이어져 오는 북엇국 전문점. 2대째 가업이 이어지고 있습니다. 냉동 황태가 아닌 단단하게 말린 북어로 끓인 것이 특징이며, 구수하고 담백한 맛의 뽀얀 국물에 반한 사람들이 점심때면 줄을 늘어섭니다. 건더기나 국물 리필이 가능한 것도 매력적다입니다.', 37.567748, 126.979852, '1만원대', '지하철 1 / 2호선 시청역 4번 출구, 약 322m', '북어해장국', '매일', '', '음식점', '', '평일 07:00~20:00\n주말, 공휴일 07:00~15:00', '02-777-3891', '명절 휴무'),
	(32, '하하&김종국의 401 정육식당', '04043  서울 마포구 잔다리로 23 (서교동)', 'images/하하&김종국의_401_정육식당_32.jpg', '홍대에 위치한 하하&김종국의 401 정육식당\n\n홍대에 위치한 하하&김종국의 401 정육식당. 이미 홍대 맛집으로 소문난 이곳은 입구부터 줄을 서서 기다리는 손님들로 발 디딜 틈이 없습니다. 식당 벽에 붙어 있는 수많은 연예인들의 사인과 두 사장님의 사진을 구경하는 재미도 이곳의 매력 포인트 중 하나. 손님들이 가장 많이 찾는 메뉴는 오겹살, 목살, 항정살 등 여러 부위를 골고루 맛볼 수 있는 세트 메뉴로 인원수에 맞게 주문하면 됩니다.\n주문 시 같이 제공되는 멸치 액젓과 수제 소스에 육즙 가득한 고기를 찍어 먹으면 그 맛이 일품. 여기에 부드러운 감칠맛과 매콤한 입가심 역할을 할 차돌 된장찌개까지 곁들여 먹는다면 가장 완벽한 한 끼를 완성할 수 있습니다', 37.550740, 126.920239, '', '지하철 2/6호선 합정역 3번 출구, 495m', '', '매일', '', '음식점', '', '16:00 - 02:00', '02-325-0805', ''),
	(33, '앤트러사이트 합정점', '04073  서울 마포구 토정로5길 10 (합정동)', 'images/앤트러사이트_합정점_33.jpg', '오래된 신발공장을 개조. 커피와 케이크, 다양한 종류의 디저트를 만날 수 있음.\n\n오래된 신발공장을 개조해 만들었습니다. 낡은 외관을 그대로 살리고, 공장에서 사용하던 컨베이어벨트와 철대문 등을 테이블 등으로 활용했습니다. 커피와 맥주의 복합적인 풍미가 있는 대표 블렌딩 버터팻트리오(Butter Fat Trio)를 포함해 그 외 나쓰메 소세키, 파블로 네루다 등 작가의 이름을 딴 원두를 만날 수 있고  그외 파티시에가 직접 만드는 케이크, 피낭시에 등 다양한 종류의 디저트가 있습니다. 전시와 공연도 열립니다 .', 37.545819, 126.918434, '', '지하철 6호선 상수역 4번 출구, 556m', '에스프레소 5,500원\n카푸치노 6,000원\n아메리카노 5,500원', '매일', ' http://www.anthracitecoffee.com/', '카페, 디저트', '', '09:00 ~ 22:00 (21:30 라스트오더)', '02-336-7850', ''),
	(34, '유림면', '04515  서울 중구 서소문로 139-1 (서소문동)', 'images/유림면_34.jpg', '신안 소금과 봉평 메밀만을 사용해 맛있는 메밀국수\n\n유림면은 1960년에 개업해 3대째 운영 중인 국수 전문점으로, 서소문동에 위치해 한국의 전통과 역사를 느낄 수 있는 곳 입니다. 개업 당시 구호물자로 밀가루가 들어오자, 많은 사람이 저렴한 값에 한 끼를 즐길 수 있는 국수집을 시작했고, 지금은 가족 대대로 쌓은 노하우로 많은 이들에게 사랑받는 가게로 성장했습니다. 쫄깃한 식감을 위해 면을 미리 숙성시켜놓은 뒤, 주문이 들어오면 즉시 삶아내어 국수를 만들어 냅니다. 대표 메뉴는 비빔메밀국수로, 쫄깃한 면과 매콤달콤한 양념이 조화를 이루며, 신선한 고명과 고소한 깻가루가 풍미를 더해줍니다.', 37.564244, 126.976098, '1만원대', '지하철 1 / 2호선 시청역 12번 출구, 36m', '메밀국수, 냄비국수', '', '', '음식점', '', '월요일~금요일 11:00~21:00, 토요일 .일요일 11:00~20:00', '02-755-0659', ''),
	(35, '을지다방', '04550  서울 중구 을지로 124-1 2층', 'images/을지다방_35.jpg', 'BTS도 반한 특제 쌍화탕이 있는 찻집\n\n1985 년 문을 연 을지다방은 뉴트로 감성 물씬 풍기는 매력적인 카페입니다 . ‘ 먹는 것으로 절대 장난치지 않는다 ’ 는 사장님만의 신념으로 가게를 운영하고 계십니다 . 달걀노른자가 보름달처럼 담긴 쌍화차를 처음 접해보는 사람도 사장님의 친절한 설명에 금방 마니아가 되어버리죠 . 고층빌딩 사이에서 옛날 다방의 모습을 그대로 간직한 곳으로 이색적인 경험이 가능합니다 .', 37.566120, 126.991680, '', '2·3호선 을지로3가역 10번 출구에서 약 30m (도보 1분)', '', '매일', '', '카페, 디저트', '라면은 11시전까지만', '06:00 ~ 21:00', '02-2272-1886', '없음'),
	(36, '마포숯불갈비', '06048  서울 강남구 도산대로 232 (논현동, 청학아파트)  에이동', 'images/마포숯불갈비_36.jpg', '돼지뼈가 붙어 있는, 제대로 된 돼지갈비. 삼겹살, 소고기갈비살. 실내도 널찍하여 회식하기에도 좋은 곳.\n\n돼지뼈가 붙어 있는, 제대로 된 돼지갈비 맛이 좋습니다. 돼지갈비 외에도 삼겹살이나 소고기갈비살도 맛볼 만합니다. 실내도 널찍하여 회식하기에도 좋은 곳입니다​.', 37.520381, 127.032557, '', '지하철 3호선 압구정역 3번 출구, 810m', '돼지갈비, 한우차돌박이, 한우생등심, 소양념갈비', '', '', '음식점', '', '매일 11:00 ~ 06:00', '02-516-1522', '연중무휴'),
	(37, '하루앤원데이(Haru&Oneday)', '04782  서울 성동구 아차산로 92 (성수동2가, 광명타워)', 'images/하루앤원데이(Haru&Oneday)_37.jpg', '슈퍼주니어 동해와 그의 형이 함께 성수동에 오픈한 카페\n\n슈퍼주니어 동해와 그의 형이 함께 성수동에 오픈한 카페. 시선을 사로잡는 작은 테라스와 마치 갤러리를 닮은 듯한 실내 인테리어가 돋보입니다. 고객의 다양한 취향을 배려해 여러 가지 종류의 테이블과 편의시설을 있습니다. 새로운 원두와 미세한 우유 입자를 사용해 기존 카페라떼나 카푸치노보다 진한 커피 향과 부드러움을 즐길 수 있는 플랫화이트, 커피의 쌉싸래함과 생크림의 달콤한 맛이 어우러지는 비엔나커피가 하루앤원데이의 추천 메뉴입니다. 얼그레이밀크티와 얼그레이크림라떼 또한 대표 메뉴로 자리 잡고 있습니다. 매일 직접 구워내는 당근케이크, 베리베리케이크, 로투스 크럼블 케이크도 꼭 맛보아야 할 디저트 중에 하나. 평소 조용한 성격이라는 동해를 쏙 빼닮은 아늑한 휴식 공간으로 하루를 마무리하기에 모자람이 없는 곳입니다.', 37.544752, 127.054243, '', '2호선 성수역 4번 출구에서 약 56m (도보 1분)', '플랫화이트, 비엔나커피, 얼그레이밀크티, 얼그레이크림라떼, 당근케이크, 로투스크럼블케이크', '매일', ' http://www.instagram.com/cafe_haruoneday', '카페, 디저트', '', '평일 08:00 - 22:30\n주말 09:00 - 22:30', '02-499-9303', ''),
	(38, '텍사스 데 브라질', '06545  서울 서초구 사평대로 205 (CENTRALCITY반포천 복개주차장)', 'images/텍사스_데_브라질_38.jpg', '정통 미국 브라질리언 스타일의 \'슈하스코\' 전문 레스토랑\n\n텍사스 데 브라질은 텍사스의 너그러운 인심을 남부 브라질 요리에 접목한 정통 미국 브라질리언 스타일의 \'슈하스코 (Churrasco, 브라질 정통의 프리미엄 스테이크) \' 전문 레스토랑입니다.\n최고급 재료와 전문적인 조리법을 통하여 비교할수 없는 맛의 15가지 다양한 부위의 스테이크와 신선한 계절 샐러드바를 함께 즐길 수 있습니다. 다양한 스테이크를 슈하스코 그릴에서 직화로 구워 제공하며 인공 화학 감미료를 첨가하지 않아 건강한 자연의 맛을 그대로 느낄 수 있습니다.\n웨스턴 스타일의 고급스러운 분위기에서 카버가 직접 카빙하여 서빙해주는 슈하스코의 맛과 프리미엄 서비스를 경험할 수 있는 국내 유일의 브라질리언 정통 스테이크 하우스입니다.', 37.504013, 127.006662, '', '지하철 3/7/9호선 고속터미널역 3번 출구, 93m', '슈하스코 (브라질리언스테이크) , 피카냐 스테이크, 플랭크 스테이크', '매일', ' https://www.sunatfood.com/kr/brand/tb/story', '음식점', '', '매일 11:30~22:00 (16:00~17:00 브레이크 타임, 21:30 라스트오더)', '0507-1367-5031', '연중무휴'),
	(39, '평양면옥(논현점)', '06049  서울 강남구 논현로150길 6', 'images/평양면옥(논현점)_39.jpg', '장충동에 있는 유명한 평양냉면집의 강남 분점. 평양출신 할머니가 운영하고 있으며, 장충동 본점은 할머니의 아들이 운영.\n\n장충동에 있는 유명한 평양냉면집의 강남 분점. 평양출신 할머니가 운영하고 있으며, 장충동 본점은 할머니의 아들이 운영하고 있습니다. 그래서인지 본점보다 낫다는 사람도 있을 정도입니다. 평양식 물냉면에 평양만두나 수육 한 그릇을 곁들이면 좋습니다. 언제나 사람들이 많아 줄을 서야 합니다.', 37.518942, 127.029154, '1만원대', '지하철 7호선 학동역 8번 출구, 597m', '제육, 편육, 어복쟁반, 냉면', '', '', '음식점', '', '매일 11:00 ~ 21:30', '02-549-5378', '연중무휴'),
	(40, '파크 하얏트 서울 더라운지', '06174  서울 강남구 테헤란로 606 (호텔아이파크(주))', 'images/파크_하얏트_서울_더라운지_40.jpg', '6성급 호텔인 파크 하얏트 꼭대기 층에 있어서 전망과 야경이 뛰어난 라운지 바. 주스와 차, 음료와 와인, 칵테일 등의 주류를 비롯하여 한식 메뉴 및 디저트.\n\n6성급 호텔인 파크 하얏트 꼭대기 층에 있어서 전망과 야경이 뛰어난 라운지 바. 주스와 차, 음료와 와인, 칵테일 등의 주류를 비롯하여 한식 메뉴 및 디저트를 즐길 수 있는 곳입니다.  매일 오후 12시부터 오후 5시 30분까지는 애프터눈 티 세트를 이용할 수 있습니다.', 37.508734, 127.064282, '', '지하철 2호선 삼성역 2번 출구, 14m', '애프터눈티세트, 빙수 2인, 음료 및 디저트, 모던 한식 디너 세트', '매일', ' http://www.seoul.park.hyattrestaurants.kr/lounge/default-ko.html', '술집, 바', '', '11:00 ~ 22:00', '02-2016-1234', '연중무휴'),
	(41, '산모퉁이', '03020  서울 종로구 백석동길 153', 'images/산모퉁이_41.jpg', '경관이 아름답고, 카페 자체도 가꾸어져 있기 때문에 외국인 관광객들에게는 반드시 추천해주고 싶은 장소\n\n경관이 아름답고, 카페 자체도 가꾸어져 있기 때문에 외국인 관광객들에게는 반드시 추천해주고 싶은 장소입니다. 특히 야경이 아름다우며, 외국인들이 찾기에는 다소 힘들 수 있기 때문에 개인적으로 올라갈 때는 택시 등을 타는 것을 추천합니다. 주변 경관과 골목을 따라 옹기종기 모여 있는 카페와 레스토랑을 보는 것도 또 하나의 재미가 될 수 있습니다. 시끄럽고 번잡한 서울 도심과는 상반되는 한적하고 이국적인 풍경이 펼쳐집니다.', 37.597912, 126.964569, '', '지하철 3호선 경복궁역 3번 출구, 1020.7212.7022버스승차 부암동주민센터 하차, 700m', '음료(7천원~9천원), 쿠키(7천원), 조각케이크(7천원)', '', ' http://www.sanmotoonge.co.kr ', '카페, 디저트', '', '월~일 11:00 ~ 18:50\n18:20 라스트 오더', '02-391-4737', '명절 당일 휴무'),
	(42, '서촌전통순대국', '03027  서울 종로구 사직로9가길 8 (필운동)', 'images/서촌전통순대국_42.jpg', '드라마 <닥터스>에서 유혜정(박신혜)의 아버지가 운영하는 국밥집으로 등장했던 서촌전통순대국은 사골로만 24시간 우려낸 진한 육수로 소문난 맛집. 얼큰하고 구수한 순댓국도 일품이지만 식당에서 직접 담근 김치 역시 서울에서 가장 맛있는 김치 중 하나로 꼽힐 정도.\n\n드라마 <닥터스>에서 유혜정(박신혜)의 아버지가 운영하는 국밥집으로 등장했던 서촌전통순대국은 사골로만 24시간 우려낸 진한 육수로 소문난 맛집입니다. 예스러운 한옥과 정갈한 인테리어는 경복궁 주변 경관과도 조화를 이룹니다. 얼큰하고 구수한 순댓국도 일품이지만 식당에서 직접 담근 김치 역시 서울에서 가장 맛있는 김치 중 하나로 꼽힐 정도입니다. 식사를 마친 후에 지호-혜정 커플이 함께 국밥을 즐겼던 자리에서 잊지 말고 기념사진을 남겨보세요!', 37.576685, 126.969080, '1만원대', '지하철 3호선 경복궁역 1번 출구, 329m', '순대국, 뼈해장국, 모듬순대, 모듬전골', '매일', '', '음식점', '', '평일 10:30~21:00, 주말 10:30~20:00\n15:00~17:00 브레이크타임', '02-735-0122', '연중무휴'),
	(43, '서강8경', '04081  서울특별시 마포구 토정로 128 (상수동)  프렌치룸레스토랑8층, 홀 다이닝바9층', 'images/서강8경_43.jpg', '한강의 빼어난 경치와 함께하는 품격 있는 프렌치 레스토랑\n\n한강의 빼어난 경치와 함께 낮에는 다양한 음료 위주, 밤에는 와인, 위스키 등을 즐기는 품격 있는 레스토랑입니다. 입에는 프랑스를 선물하고, 눈에는 한강을 담아 준다는 모토로 관광객을 사로잡고 있으며 <야왕>, <돈의 화신> <별에서 온 그대>등의 드라마에서 한강의 멋진 야경을 선사했습니다. 8층은 6개 테마별 프라이빗 룸에서 한강의 야경과 함께 프렌치 코스요리를 즐길 수 있으며 9층은 와인, 칵테일, 위스키등을 즐길 수 있는 스카이 라운지로 꾸며져 있습니다. 방문 전 예약 필수.', 37.544937, 126.925338, '', '지하철 6호선 상수역 3번 출구, 463m', '', '', ' https://www.instagram.com/8kyoung_official/#', '음식점', '', '12:00~15:00 / 17:30~19:30 / 20:00~24:00', '02-334-1919', '연중무휴'),
	(44, '스타벅스 이대점', '03767  서울 서대문구 이화여대길 34 (대현동, 신흥빌딩)', 'images/스타벅스_이대점_44.jpg', '대한민국에 스타벅스가 가장 처음 생긴 지점\n\n대한민국에 스타벅스가 가장 처음 생긴 지점으로 총 3층으로 이루어져 공간이 넓어 좌석을 활용하기 좋습니다. 1999년 한국에 최초로 개점할 당시의 스타벅스 모습이 담긴 사진이 전시되어 있습니다.', 37.558453, 126.945944, '', '지하철 2호선 이대역 3번 출구, 157m', '', '매일', ' http://www.istarbucks.co.kr/index.do', '카페, 디저트', '', '월~목 08:00~20:00\n금~토 09:00~20:00', '1522-3232', ''),
	(45, '한남동 한방통닭', '04409  서울 용산구 대사관로34길 38 (한남동)', 'images/한남동_한방통닭_45.jpg', '전 피겨스케이팅 국가대표 김연아 선수, 배우 안성기, 이종석, 한효주, 안재욱을 비롯해 수많은 유명인사들이 사랑하는 통닭구이집.\n\n전 피겨스케이팅 국가대표 김연아 선수, 배우 안성기, 이종석, 한효주, 안재욱을 비롯해 수많은 유명인사들이 사랑하는 통닭구이집. 벽 한 면을 빼곡히 메운 연예인들의 사인을 보면 이곳이 얼마나 유명한지 알 수 있습니다. 튼실한 닭에 찹쌀과 알밤, 대추 넣은 찹쌀밥을 가득 채워 참나무에 굽습니다. 대표 메뉴인 장작구이 통닭은 기름기 쏙 빠진 껍질이 바삭하고 고소하며, 대추의 달콤한 향기가 스며든 속살은 담백하고 부드럽습니다. 함께 나오는 소금과 겨자소스를 찍어먹으면 되고 포장도 가능합니다.', 37.531565, 127.005552, '', '지하철 경의중앙선 한남역 1번 출구, 405m', '한방통닭, 바베큐모듬구이', '', ' https://www.instagram.com/hannamdonghanbangchicken/ ', '음식점', '', '월요일~목요일 16:10~00:30\n금요일~토요일 16:10~01:30', '02-797-8677', '일요일'),
	(46, '부산양곱창', '06147  서울 강남구 언주로98길 8-1 (역삼동)', 'images/부산양곱창_46.jpg', '비교적 저렴한 곱창, 숯불구이.\n\n비교적 저렴하게 곱창을 즐길 수 있다. 숯불구이라는 점이 장점입니다. 마늘 양념 된 신선하고 오동통한 곱창이 일품입니다. 마무리로 먹는 양김치볶음밥이 저렴하면서도 환상적인 맛을 자랑합니다. 곱창과 대창까지 푸짐하게 들어간 곱창전골도 인기가 있습니다.', 37.504747, 127.042631, '', '지하철 2호선 / 수인분당선 선릉역 5번 출구, 557m', '양구이, 대창구이, 곱창구이, 전골', '월요일~토요일', '', '음식점', '', '17:00~05:00', '02-554-7780', '일요일, 명절 휴무'),
	(47, '나폴레옹과자점', '02880  서울 성북구 성북로 7', 'images/나폴레옹과자점_47.jpg', '신안 천일염과 잣으로 유럽식 빵을 만드는 가게\n\n전국 5대 빵집이자, 서울 3대 빵집. 1968년 서울 성북구에서 개업하여 2대째 가업을 이어오고 있는 제과점입니다. 많은 이들이 이곳에서 제과 기술을 배워 가면서 한국제과업계에 많은 영향을 끼친 전통 있는 베이커리입니다. 서울 성북구 동소문동 삼선교 자리에서 처음 문을 연 나폴레옹과자점은 2007년 성북천 복개 공사로 인하여 본점의 위치를 100m 이동해 성북동 입구에 재개장했으며, 1층은 제과점, 2층은 카페로 구성된 베이커리 카페로 운영하고 있습니다.\n\n\n\n\n\n\n\n• 이곳은 \'서울미래유산\'으로 선정된 곳입니다. 서울의 근·현대 문화유산 중에서 미래 세대에게 전달할 만한 가치가 있는 유무형의 자산인 서울미래유산을 오래가게 여행에서 만나보세요.( https://futureheritage.seoul.go.kr)', 37.588925, 127.005071, '', '지하철 4호선 한성대입구역 5번 출구, 40m', '베이커리', '매일', ' https://napoleonbakery.co.kr', '카페, 디저트', '', '09:00~21:00', '02-742-7421', '없음'),
	(48, '장충동 족발골목', '04616  서울 중구 장충단로 175 (장충동1가)', 'images/장충동_족발골목_48.jpg', '장충동 족발골목은 서울에서 꼭 가봐야 할 먹거리 골목.\n\n장충동 족발골목은 서울에서 꼭 가봐야 할 먹거리 골목 중 하나입니다. 장충동이 족발로 유명해진 이유는, 당시 대부분의 스포츠 경기는 장충체육관에서 진행되었고, 경기나 공연이 끝난 후 바로 옆의 족발집으로 직행했다고 합니다. 장충체육관을 많은 이들이 찾으면서 족발골목이 더불어 활성화가 된 것입니다. 그때부터 지금까지 수십 년 동안 푸짐하고 맛 좋은 족발로 사람들의 변치 않는 사랑을 받고 있습니다. 족발 거리에서 족발과 함께 나오는 빈대떡과 파전 등 다른 음식도 즐겨보세요.', 37.560663, 127.005562, '', '지하철 3호선 동대입구역 3번 출구, 150m', '', '', '', '음식점', '', '', '', ''),
	(49, '신옛찻집', '03145  서울 종로구 인사동길 47-8 (관훈동)', 'images/신옛찻집_49.jpg', '속세를 벗어난 듯한 명상적인 분위기. 각종 동물과 새들이 카페를 지키고 있는 전통 찻집\n\n속세를 벗어난 듯한 명상적인 분위기의 찻집으로, 입구를 들어서면 새가 지저귀는 소리부터 들릴 정도로 각종 동물과 새들이 카페를 지키고 있는 전통 찻집입니다. 가지각색의 예쁜 떡이 차와 함께 나오고 자연에 온 느낌을 받을 만큼 시골스럽고 아늑합니다.', 37.574249, 126.983907, '1만원대', '3호선 안국역 6번 출구에서 약 306m (도보 4분)', '전통차, 전통술, 안주', '', ' https://www.instagram.com/shinoldtea/', '카페, 디저트', '', '월요일 10:00~20:00 / 화요일~금요일 10:00~21:00 / 토요일~일요일 10:00~22:00', '02-732-5257', '연중무휴'),
	(50, '구스토타코', '04049  서울특별시 마포구 와우산로 41 (상수동)', 'images/구스토타코_50.jpg', '뉴욕의 요리학교 출신 셰프가 만드는 따끈한 타코\n\n뉴욕의 요리학교 출신 셰프가 만드는 따끈한 타코를 맛볼 수 있습니다. 메뉴는 단출하지만 주문하면 즉시 만들어내기 때문에 약간 기다려야 합니다. 장소는 협소한 편. 테이크아웃 해가는 손님들이 많습니다.', 37.548148, 126.922832, '', '지하철 6호선 상수역 1번 출구, 37m', '타코, 퀘사디아, 부리토', '', ' http://gustotaco.com', '음식점', '', '화요일~토요일 11:30~21:00, 일요일 11:30~20:00', '02-338-8226', '매주 월요일'),
	(51, '피맛골', '03155  서울 종로구 종로3길 17', 'images/피맛골_51.jpg', '피맛골은 종로구 종로1가부터 6가까지 이어진 먹자골목\n\n피맛골은 종로구 종로1가부터 6가까지 이어진 먹자골목입니다. 조선 시대에는 하급 관료나 서민들이 큰길을 가다가 고관대작을 만나면 길가에 엎드려 예의를 표했는데, 이런 일이 빈번하자 번거로웠던 서민들은 아예 큰 길 양쪽 뒤편의 좁은 골목을 이용하게 되었습니다. 이 길을 따라 목로주점, 모주집, 장국밥집이 연이어져 서민들에게 사랑받는 장소가 되었고, 말을 피하는 골목이라 하여 피맛골이라 불렸습니다.', 37.570996, 126.978939, '', '지하철 5호선 광화문역 3번 출구, 250m', '', '점포별 상이', '', '음식점', '', '점포별 상이', '', ''),
	(52, '서강껍데기', '04035  서울특별시 마포구 월드컵로 36 (서교동)', 'images/서강껍데기_52.jpg', '서울에서 가장 맛있는 껍데기 집이라고 꼽힐 만큼 유명한 음식점인 서강껍데기는 가수 빅뱅이 데뷔 전 단골집으로 자주 찾던 곳.\n\n서울에서 가장 맛있는 껍데기 집이라고 꼽힐 만큼 유명한 음식점인 서강껍데기는 가수 빅뱅이 데뷔 전 단골집으로 자주 찾던 곳이라고도 합니다. 각종 돼지고기와 껍데기를 전문으로 판매하고 있으며, 소금구이도 유명합니다.', 37.552692, 126.912498, '', '지하철 2 / 6호선 합정역 9번 출구, 311m', '', '', ' https://www.instagram.com/west_river__official', '음식점', '', '16:00~03:30', '02-338-5541', '연중무휴'),
	(53, '모던눌랑', '06545  서울 서초구 사평대로 205 (반포동, CENTRALCITY반포천 복개주차장)', 'images/모던눌랑_53.jpg', '1930년 대 상하이 문화의 현대적인 신여성 컨셉의 로맨틱 & 모던 차이니즈 라운지\n\n모던눌랑은 1930년대 동양의 파리, 화려했던 상하이를 재해석하여 현대적인 신여성을 컨셉으로 만들어진 로맨틱하고 모던한 감성의 MODERN CHINESE LOUNGE입니다. 현대(MODERN)의 영문표기와 여성(NÜLANG) 중문표기의 합성어로 중국음식문화에 없었던 세련되고 로맨틱함을 모티브로 새로운 차이니즈 식사를 선보이고 있습니다.\n\n\n 가장 로맨틱한 상하이의 문화적인 경험을 식사와 함께 즐길 수 있는 공간으로, 모던눌랑은 시대를 앞서가는 여성들이 함께 모여 즐기는 이국적이고 하이파이한 문화공간을 지향하고 있습니다.', 37.504492, 127.007845, '', '지하철 3/ 7/ 9호선 고속터미널역 3번출구, 125m', '모던눌랑케이지, 모던눌랑 상하이롤 플래터, 크랩 타워 라이스', '', ' http://www.modernnulang.com/', '음식점', '18시 이후 13세이하 어린이출입제한', '매일 11:30 ~ 22:00 (Last Order 21:00)', '02-6282-5005', '연중무휴'),
	(54, '10꼬르소꼬모카페', '06015  서울 강남구 압구정로 416  Trinity 빌딩 지하1층', 'images/10꼬르소꼬모카페_54.jpg', '서울의 최신 트렌드가 궁금한 사람이라면 꼭 가봐야할 곳.\n\n서울의 최신 트렌드가 궁금한 사람이라면 꼭 가봐야할 곳. 밀라노 풍의 인테리어와 음악이 흐르는 카페 스타일의 레스토랑으로 캐주얼한 식사와 디저트를 즐길 수 있습니다. 원래 세계적인 편집샵으로 의류, 화장품, 가방, 서적 등을 파는 스토어가 함께 운영 중입니다.', 37.526933, 127.042434, '', '지하철 수인분당선 압구정로데오역 3번 출구, 120m', '후루티 디 마레 카펠리니, 딸리아딸레, 보따르가 파스타, 한우채끝 그릴', '', '', '음식점', '', '12:00~22:00 (16:30~18:00 브레이크타임)', '02-547-3010', ''),
	(55, '수담한정식', '06153  서울 강남구 봉은사로 418 (조양빌딩)', 'images/수담한정식_55.jpg', '정상급 기능장 쉐프가 신선한 재료를 사용하고 영양만점인 음식을 즐길 수 있는 맛집.\n\n소중한 분들과 함께하는 공간, 업계 최고의 전통 한정식 수담. 특별한 날, 더없이 소중한 분들과 함께할 수 있는 전통 한정식 맛집입니다. 26년 경력의 정상급 기능장 쉐프가 믿을 수 있는 신선한 재료를 사용하고 영양만점인 음식으로 가득합니다. 엄격하고 체계적인 관리를 하고 친환경 재료 엄선을 통해 차별화된 고급 한정식 맛집입니다.', 37.510511, 127.045979, '', '지하철 9호선/ 수인분당선 선정릉역 3번 출구, 100m', '진연상, 담정식, 선비상, 대감상', '매일', ' http://www.sudam.or.kr/', '음식점', '네비게이션\' 이용시 꼭 주소로 검색 바람(확장 이전으로 인해 기존 주소 안내할 수 있음)', '11:30~15:00, 17:30~22:00', '02-558-4900', '명절 당일 휴무'),
	(56, '단풍나무집(이태원점)', '04350  서울특별시 용산구 이태원로27가길 26 (이태원동)', 'images/단풍나무집(이태원점)_56.jpg', '와인바 같은 분위기에서 돼지고기나 소고기를 구워 먹을 수 있는 곳.\n\n와인바 같은 분위기에서 돼지고기나 소고기를 구워 먹을 수 있는 곳. 나무를 가득 세워 놓은 실내 인테리어가 고급스럽습니다. 천겹이라는 대표 메뉴는 돼지고기 항정살을 말하는 것입니다. 화력이 좋은 참숯에 구운 고기를 깻잎 장아찌에 싸 먹는 맛이 좋습니다.', 37.535091, 126.993808, '', '지하철 6호선 이태원역 1번 출구, 111m', '1++한우숙성등심, 양념갈비, 단풍 불고기, 우삼겹', '', '', '음식점', '', '평일 11:30 ~ 15:00 / 17:00 ~ 22:00\n주말 11:30 ~ 22:00', '02-790-7977', '명절 당일 휴무'),
	(57, '큰기와집', '03059  서울 종로구 북촌로 22 (재동 49-6) 1층', 'images/큰기와집_57.png', '반찬은 전라도식으로, 코스 요리는 평양도식으로 맛을 내는 한정식집. 계절의 신선한 재료들을 이용하여 다양하게 메뉴를 변화. 가장 유명한 것은 간장게장. 전통 한옥 기와집을 개조한 분위기도 고풍.\n\n반찬은 전라도식으로, 코스 요리는 평양도식으로 맛을 내는 한정식집입니다. 계절의 신선한 재료들을 이용하여 다양하게 메뉴를 변화시키고 있습니다. 가장 유명한 것은 간장게장입니다. 전통 한옥 기와집을 개조한 분위기도 고풍스럽습니다.', 37.578749, 126.985419, '', '지하철 3호선 안국역 2번 출구, 178m', '간장게장, 양념게장, 꽃게장 비빔밥, 인삼 갈비찜', '', ' https://blog.naver.com/keunkiwajip_0501', '음식점', '', '11:30 - 21:00 (20:00 라스트오더)\n15:00 - 17:30 (브레이크타임)', '02-722-9024', '매주 월요일, 추석 당일 및 연휴 휴무'),
	(58, '카페 꼼마 합정점', '04020  서울 마포구 포은로 49 (합정동)', 'images/카페_꼼마_합정점_58.png', '쉬어가는 공간, 카페 꼼마\n\n카페 꼼마는 한국을 대표하는 출판사의 하나인 문학동네가 경영하는 멋진 북 카페로, 벽 전체가 책장으로 되어있습니다. 영화에 나올만한 클래식한 매력을 갖는 책장에는 다양한 장르의 책이 소장되어 있고, 책과 문화가 가득한 공간에서 맛있는 음료와 함께 독서를 즐길 수 있습니다.', 37.551947, 126.906761, '', '6호선 망원역 2번 출구에서 약 670m (도보 10분)', '', '매일', ' https://www.instagram.com/cafecomma__official/', '카페, 디저트', '', '10:00 ~ 22:00', '070-4179-2205', ''),
	(59, '놋그릇가지런히 놋이', '03036  서울특별시 종로구 자하문로13길 3 (통인동)', 'images/놋그릇가지런히_놋이_59.jpg', '카페 놋그릇 가지런히 놋이에서는 두부자공방의 장인이 만든 유기그릇에 디저트가 담겨 나옴\n\n카페 놋그릇 가지런히 놋이에서는 두부자공방의 장인이 만든 유기그릇에 디저트가 담겨 나옵니다. 대표 메뉴로는 수박 셔벗, 홍시단팥 등이 있습니다. 아기자기하고 건강한 디저트들이 유기그릇에 담겨 나와 입맛을 자극하고 놋그릇들은 카페와 온라인 사이트에서 구매할 수 있습니다.', 37.579975, 126.970937, '', '지하철 3호선 경복궁역 2번 출구, 448m', '', '월요일~토요일', ' https://www.noshimall.co.kr/', '카페, 디저트', '', '10:00 ~ 19:00', '02-736-6262', '일요일 휴무'),
	(60, '[백년가게] 이문설렁탕', '03149  서울 종로구 우정국로 38-13 (견지동)', 'images/[백년가게]_이문설렁탕_60.jpg', '서울에서 현존하는 식당 중 가장 오래된, 1백여 년의 역사를 자랑하는 집으로, 1900년대 초엽부터 대를 물려가며 계승해 온 집. 1984년부터는 현재의 주방장이 설렁탕을 만들어냄. 고기와 사골을 충분히 곤 진한 설렁탕. 현재의 자리는 원래의 자리에서 약간 이전.\n\n서울에서 현존하는 식당 중 가장 오래된, 1백여 년의 역사를 자랑하는 집으로, 1900년대 초엽부터 대를 물려가며 계승해 온 집입니다. 1984년부터는 현재의 주방장이 설렁탕을 만들어내고 있습니다. 고기와 사골을 충분히 곤 진한 설렁탕을 맛볼 수 있습니다. 현재의 자리는 원래의 자리에서 약간 이전한 위치입니다.', 37.572761, 126.983898, '', '지하철 1호선 종각역 3-1번 출구, 175m', '설렁탕', '월요일~일요일', ' http://imun.modoo.at/', '', '', '평일 08:00 ~ 15:00, 16:30 ~ 21:00\n일요일 08:00 ~ 15:00, 16:30 ~ 20:00', '02-733-6526', '명절 휴무'),
	(61, '열차집', '03158  서울 종로구 종로7길 47 (공평동)', 'images/열차집_61.jpg', '빈대떡, 굴전 등과 막걸리 한 사발을 걸치는 대포집\n\n빈대떡, 굴전 등과 막걸리 한 사발을 걸치는 대포집입니다. 녹두를 맷돌에 직접 간 후 철판에 올려 놓은 다음 돼지고기 몇 점을 얹어 지져내는 빈대떡이 바삭하고 맛있습니다. 저녁이 되면 빈대떡에 막걸리 한 잔 하는 손님들로 가득합니다.', 37.571704, 126.982783, '1만원대', '지하철 1호선 종각역 2번 출구, 98m', '원조빈대떡, 굴전, 해물파전, 조개탕', '', ' http://trainhouse.blogspot.kr/ ', '음식점', '#NAME?', '평일 11:00~23:00, 토요일 14:00~22:30, 일요일 14:00~21:00', '0507-1440-2849', '명절 휴무'),
	(62, '조선옥', '04544  서울 중구 을지로15길 6-5', 'images/조선옥_62.jpg', '소갈비를 진간장, 참기름, 마늘, 설탕 등으로 맛을 낸 양념장에 하루 동안 재웠다가 연탄불에 굽는 옛날식 갈비구이.\n\n소갈비를 진간장, 참기름, 마늘, 설탕 등으로 맛을 낸 양념장에 하루 동안 재웠다가 연탄불에 굽는 옛날식 갈비구이입니다. 진하지 않은 달콤한 양념이 옛 갈비 맛의 추억을 되살려 줍니다. 6·25전쟁 이전에 문을 열어 70년대 중반까지만 하더라도 중국집 안동장, 설렁탕집 이남장과 더불어 을지로의 3대 식당으로 불리던 전통 있는 갈비집입니다.', 37.566774, 126.993425, '', '지하철 2/3호선 을지로 3가역 6번 출구, 67m', '양념소갈비, 갈비탕, 대구탕, 장국밥', '', '', '음식점', '', '월~토 11:30~14:30, 16:30~21:30', '02-2266-0333', '매주 일요일'),
	(63, '벽제갈비 타워팰리스점', '06294  서울 강남구 언주로30길 26 (타워팰리스)  VANNT 1층(도곡동)', 'images/벽제갈비_타워팰리스점_63.jpg', '세계 최고의 맛 아시안 월스트리트 저널 신문에서 아시아 5대 음식점으로 선정, 세계 27대 대도시 대표 음식점 50선. 맛있는 육즙을 가진 벽제 갈비의 설화한우를 .\n\n아시아를 대표하는 명품 갈비. 세계 최고의 맛 아시안 월스트리트 저널 신문에서 아시아 5대 음식점으로 선정, 세계 27대 대도시 대표 음식점 50선에 뽑힌 적도 있습니다. 맛있는 육즙을 가진 벽제 갈비의 설화한우를 맛볼 수 있습니다.', 37.487763, 127.052530, '', '지하철 3호선 / 수인분당선 도곡역 4번 출구, 488m', '설화생갈비, 설화꽃등심, 갈비탕', '매일', '  https://www.bjgalbi.com/index', '음식점', '', '매일 11:30~22:00\nBreak Time (평일 15:00~17:00, 주말공휴일 브레이크타임 없음)', '02-2058-3535', '연중 무휴'),
	(64, '산들해', '05544  서울 송파구 위례성대로 6 (방이동, 현대토픽스)', 'images/산들해_64.jpg', '한옥 기와 모양의 1, 2층 한정식집. 이천 쌀로 지은 돌솥밥과 간장게장, 생선모둠구이, 부침개, 보쌈, 잡채 등 20여 가지 반찬. 1층은 입식, 2층은 좌식으로 되어 있으며 이천 쌀과 김 판매.\n\n한옥 기와 모양의 1, 2층 한정식집. 이천 쌀로 지은 돌솥밥과 간장게장, 생선모둠구이, 부침개, 보쌈, 잡채 등 20여 가지 반찬이 한상 가득 나옵니다. 1층은 입식, 2층은 좌식으로 되어 있으며 이천 쌀과 김은 판매도 가능합니다.', 37.516842, 127.113151, '2만원대', '지하철 8호선 몽촌토성역 2번 출구에서 42m', '한정식, 돌솥돼지불고기, 돌솥 소불고기, 황태구이', '월화수목금토일', '', '음식점', '', '11:10 ~ 15:00 / 17:00 ~ 21:00', '02-448-3457', '연중무휴'),
	(65, '두가헌', '03062  서울특별시 종로구 삼청로 14 (사간동)', 'images/두가헌_65.jpg', '고풍스러운 한옥에서 정통 프랑스 요리를 즐길 수 있는 레스토랑.\n\n풍스러운 한옥에서 정통 프랑스 요리를 즐길 수 있는 레스토랑. 현대갤러리 뒷마당에 위치해 있어 미술 작품도 함께 감상할 수 있습니다. 스테이크가 특히 유명합니다.', 37.577320, 126.979833, '', '지하철 3호선 안국역 1번 출구, 615m', '', '화~토', ' http://www.dugahun.com', '음식점', '', '12:00 ~ 22:00', '02-3210-2100', '매주 월요일, 일요일 휴무'),
	(66, '삼거리푸줏간 센트럴시티점', '06545  서울 서초구 사평대로 205 (반포동, CENTRALCITY반포천 복개주차장)', 'images/삼거리푸줏간_센트럴시티점_66.jpg', 'YG엔터테인먼트에서 운영했던 고깃집\n\nYG엔터테인먼트에서 운영했던 고깃집으로, 홍대에서 센트럴시티로 확장 이전했습니다. YG 소속 연예인들뿐만 아니라 이승기, 이서진 등 인기 연예인들도 다녀갔습니다. 위너 등 YG 소속 아티스트들이 이곳에서 종종 파티를 열기도 한다고. 벽면에 걸린 연예인들의 기념 사진과 사인들을 찾아보는 재미도 쏠쏠합니다.\n자리는 바뀌었지만 맛은 한결같습니다. 대표메뉴 돼지갈비는 두툼한 두께를 자랑하며, 자극적이지 않은 은은한 단맛이 인기 요인. 한우로 맛을 낸 육수에 담백한 메밀면을 담아낸 평양냉면, 진한 맛이 일품인 한우된장말이밥도 별미입니다.', 37.504492, 127.007845, '', '지하철 3/ 7/ 9호선 고속터미널역 3번 출구, 300m', '푸줏간 양념 돼지갈비, 한우 된장말이 밥', '', ' https://www.instagram.com/3geori_butchers/', '음식점', '', '평일 11:30 - 15:00 / 16:00 - 22:00\n주말 11:30 - 22:00', '02-6052-0103', ''),
	(68, '고센인코퍼레이티드', '06014  서울 강남구 선릉로158길 18', 'images/고센인코퍼레이티드_68.jpg', '청담동 언덕에 자리잡은 카페로, 오래 전부터 청담동을 대표하는 카페. 당시에는 차별화된 분위기와 세련된 인테리어로 청담동 일대에서 입소문 났던 곳. 지금은 리모델링으로 새로운 분위기로 바뀜.\n\n담동 언덕에 자리잡은 카페로, 오래 전부터 청담동을 대표하는 카페. 당시에는 차별화된 분위기와 세련된 인테리어로 청담동 일대에서 입소문 났던 곳입니다. 지금은 리모델링으로 새로운 분위기로 바뀌었습니다.', 37.525584, 127.040819, '3만원대', '수인분당선 압구정로데오역 4번 출구에서 약 227m (도보 3분)', '', '', ' https://www.i-goshen.com/', '카페, 디저트', '', '매일 11:30~04:30', '02-515-1863', '연중무휴'),
	(69, '좋은세상만들기', '07212  서울 영등포구 선유로 248-13 (양평동4가)', 'images/좋은세상만들기_69.jpg', '엑소(EXO)의 멤버 찬열의 아버지가 운영하는 라이브카페\n\n한국 대표 아이돌그룹 엑소(EXO)의 멤버 찬열의 아버지가 운영하는 라이브 카페, 좋은세상만들기에서는 10대들이 좋아하는 K-POP부터 중장년층들의 향수가 담긴 올드팝까지 다양한 음악과 라이브 공연을 즐길 수 있습니다. 평일 저녁에는 라이브 가수 공연이, 토요일에는 밴드 공연이 펼쳐집니다. 실력 있는 아티스트들의 음악을 감상하고 수제버거와 치킨, 맥주, 음료 등 먹을거리를 즐기며 몸과 마음을 쉬어갈 수 있고 직장인밴드, 동아리 행사 등 대관도 가능합니다.\n\n엑소 멤버 찬열의 아버지가 운영하는 라이브 카페로 찬열이 직접 사용한 악기들이 전시되어 있어요. 찬열의 재능의 원천을 발견하고 간접적으로 소통할 수 있는 장소로 이름을 떨치며 많은 엑소 팬들의 방문 릴레이가 이어집니다. 실력 있는 아티스트들이 라이브로 들려주는 한중일 노래들을 감상할 수 있고, 크레용팝 등 동료 가수들의 팬미팅이 열리는 등 다양한 공연 및 이벤트 공간으로도 사랑받고 있습니다.', 37.534562, 126.897769, '', '지하철 2/ 9호선 당산역 12번 출구, 428m', '', '월요일 ~ 토요일', '', '카페, 디저트', '가수 공연시간 20:30~23:30, 토요일은 밴드공연', '17:30 ~ 23:50', '070-4412-5700', '일요일'),
	(70, '엔그릴', '04340  서울 용산구 남산공원길 105 (용산동2가, YTN서울타워)  7층', 'images/엔그릴_70.jpg', '남산 N서울타워 내에 있는 고급 레스토랑. 코스식 요리 전문\n\n남산 N서울타워 내에 있는 고급 레스토랑. 코스식 요리를 전문으로 하며, 애피타이저와 수프, 디저트 등을 3~4가지 메뉴 중에서 선택하게 되어 있습니다. 가격이 다소 높은 편이지만 서울의 야경이 한눈에 바라다보이는 아름다운 전망을 즐길 수 있어 기념일이나 특별한 날 연인과 함께 저녁 식사를 하기에 좋습니다. 예약은 필수. 교통이 약간 불편한 점이 아쉽지만, 남산케이블카를 이용하는 것도 한 가지 방법입니다.', 37.551123, 126.987868, '', '지하철 3/4호선 충무로역, 지하철 3호선 동대입구역, 순환버스 01번(남산순환) 탑승, \'남산서울타워\' 정류장 하차, 357m\n서울시티투어버스 탑승 후 \'N서울타워\' 정류장 하차', '', '', '', '음식점', '', '평일 12:00 - 16:00 / 17:00 - 22:00', '02-3455-9297', ''),
	(71, '카페 로쏘', '03054  서울 종로구 삼청로 81-12', 'images/카페_로쏘_71.jpg', '카페 로쏘는 삼청동에 위치한 예쁘고 조용한 카페로 이국적인 분위기.\n\n카페 로쏘는 삼청동에 위치한 예쁘고 조용한 카페로 이국적인 분위기를 띠고 있습니다. 빨간색 포인트 간판이 이 카페의 상징입니다. 브라질 파젠다 드립 커피와 달콤한 케이크들이 맛있고 조용히 커피나 차를 한 잔 마시며 디저트를 음미하고 싶다면 가보세요. 와인도 함께 판매합니다.', 37.582909, 126.981254, '', '지하철 3호선 안국역 2번 출구, 974m', '디저트카페', '', '', '카페, 디저트', '', '11:00~21:00', '0507-1418-2622', ''),
	(72, '송죽헌', '03131  서울 종로구 율곡로6길 17', 'images/송죽헌_72.jpg', '차분한 분위기에서 제대로 된 남도 음식을 맛볼 수 있는 곳\n\n20여 년 역사의 한정식집입니다. 구절판, 전복찜, 각종 전, 홍어찜, 은어구이, 장어구이를 주 메뉴로 하여 여러 가지 장아찌와 젓갈, 김치가 입맛을 돋웁니다. 차분한 분위기에서 제대로 된 남도 음식을 맛볼 수 있는 곳으로, 외국인 손님 대접에도 좋습니다. 음식은 그때그때 만들기 때문에 시간이 오래 걸리므로 예약은 필수입니다.', 37.576447, 126.989318, '', '지하철 3호선 안국역 4번 출구, 400m', '', '월요일~금요일', '', '음식점', '', '평일 12:00~22:00\n(Break time 14:00~18:00)', '02-763-4234', '주말, 공휴일 휴무'),
	(73, '영천영화식육식당', '06070  서울 강남구 도산대로90길 3 (상민빌딩)', 'images/영천영화식육식당_73.jpg', '대구에서 유명한 영천영화식당의 서울 분점. 적정하게 숙성시킨 한우. 반찬들도 맛깔스럽고 가격대비 만족도도 높은 편.\n\n대구에서 유명한 영천영화식당의 서울 분점입니다. 적정하게 숙성시킨 한우를 숯불에 구워 먹을 수 있습니다. 같이 나오는 반찬들도 맛깔스럽습니다. 가격대비 만족도도 높은 편입니다.', 37.523947, 127.049547, '', '지하철 7호선 청담역 9번 출구, 608m', '한우 육회, 한우 갈비살, 한우 안창살, 한우 꽃등심', '매일', ' http://www.ycyh.co.kr/default/', '음식점', '', '', '02-3442-0381', '명절 휴무'),
	(74, '사마리칸트', '04561  서울 중구 마른내로 159-10', 'images/사마리칸트_74.jpg', '러시아 요리에 바탕을 둔 우즈베키스탄 음식.\n\n러시아 요리에 바탕을 둔 우즈베키스탄 음식을 맛볼 수 있습니다. 요리사는 물론 종업원까지 모두 현지에서 왔습니다. 양고기와 소고기를 이용한 꼬치, 양고기 전골 츠예플라토를 비롯하여 타바카, 플로브, 슈르파 등 다양한 러시아, 중앙아시아 요리가 준비되어 있습니다. 추천 메뉴는 양고기와 소고기 샤슬릭입니다.', 37.565128, 127.005079, '', '지하철 2/4/5호선 동대문역사문화공원역 7번 출구, 192m', '양고기꼬치, 양고기샤브샤브', '', '', '음식점', '', '매일 11:00 ~ 23:00', '02-2277-4261', '연중무휴'),
	(75, '명동함흥면옥', '04537  서울 중구 명동10길 35-19 (명동2가)', 'images/명동함흥면옥_75.jpg', '고구마 전분을 사용해 보드라운 식감의 함흥냉면\n\n명동함흥면옥은 1970년대 말 명동에서 시작된 냉면 전문점으로, 고급스러운 실내장식과 에어컨을 갖추고, 음식 맛도 일품이었기에 \'명동파\'로 불리던 전문가와 예술가들 사이에서 인기를 끌었습니다. 1대 사장 부부는 황해도 출신으로, 함경도 풍의 회냉면이 유명합니다. 매콤한 생선회와 30가지 이상의 신선한 재료로 만든 무침 소스가 특징이며, 현대적인 감각과 전통의 맛이 어우러진 곳입니다.', 37.562770, 126.985686, '1만원대', '지하철 4호선 명동역 5번 출구, 337m', '회냉면, 물냉면, 비빔냉면, 홍어회', '월요일~토요일', '', '음식점', '', '11:00 ~ 20:00', '02-776-8430', '일요일, 명절 휴무'),
	(76, '란주라미엔', '04535  서울 중구 소공로 64 (충무로1가, 동남빌딩)', 'images/란주라미엔_76.jpg', '밀가루 반죽을 들고 칼로 썰어내는 도삭면으로 유명.\n\n밀가루 반죽을 들고 칼로 썰어내는 도삭면으로 유명합니다. 사천도삭면은 짬뽕 비슷한 맛이 나며 란주도삭면은 짜장 비슷한 소스를 얹어줍니다. 그 외에 칼국수, 보쌈, 샤부샤부 등의 한식 메뉴도 있습니다.', 37.560966, 126.982141, '1만원대', '지하철 4호선 명동역 5번 출구, 259m', '해물자장도삭면, 사천짬뽕도삭면, 해물볶음도삭면, 사천탕수육', '', '', '음식점', '', '매일 11:00 ~ 21:30', '02-779-4800', '연중무휴'),
	(77, '남포면옥(중구)', '04522  서울특별시 중구 을지로3길 24 (다동)', 'images/남포면옥(중구)_77.jpg', '동치미 국물 맛이 일품인 평양냉면과 따뜻한 어복쟁반\n\n1972년 개업한 남포면옥은 평안도 진남포 출신의 곽봉순 사장이 한국전쟁 이후 서울에 정착해 이북식 냉면을 선보인 곳으로, 현재 3대째 운영되고 있습니다. 평안도 방식 그대로 동치미를 땅속에 묻어 발효시킨 뒤 이를 육수로 사용하는 것이 이곳 평양냉면의 특징입니다. 역대 대통령들도 남포면옥의 냉면을 먹고자 즐겨 찾아왔다고 합니다.내부에는 양반다리로 앉는 전통 좌식 테이블도 있어, 한국의 전통 좌식 문화를 체험하면서 식사할 수도 있습니다.', 37.567146, 126.981676, '', '지하철 2호선 을지로입구역 1-1번 출구, 150m', '냉면, 갈비탕, 어복쟁반', '', '', '음식점', '', '월요일 ~ 금요일 11:30 ~ 22:00\n토요일 ~ 일요일 11:30 ~ 21:00', '02-777-2269', '명절 당일'),
	(78, '하누소(인사점)', '03163  서울 종로구 인사동4길 18 (낙원동, 로담코 인사빌딩)', 'images/하누소(인사점)_78.jpg', '전남 함평 초원에서 자란 최상등급의 한우 암소로 만든 요리를 중심으로 다양한 일품요리와 정통 한정식 코스요리.\n\n최상등급 한우 암소 요리 전문점 하누소\n하누소 인사점은 전남 함평 초원에서 자란 최상등급의 한우 암소로 만든 요리를 중심으로 다양한 일품요리와 정통 한정식 코스요리까지 맛볼 수 있습니다.', 37.572995, 126.987337, '', '지하철1/ 3/ 5호선 종로3가역 5번 출구, 150m', '왕갈비탕\n한우왕양념갈비\n한우꽃등심', '월요일~일요일', ' http://www.hanuso.com', '음식점', '', '11:00 - 21:30', '02-739-9990', '명절 당일 휴무'),
	(79, '낙원떡집', '03132  서울 종로구 삼일대로 438 (낙원동)', 'images/낙원떡집_79.jpg', '한국 떡의 본가라 해도 손색없는 100년 전통 떡집\n\n1920 년대부터 3 대에 걸쳐서 이어져 오는 90 년 전통을 가진 낙원떡집은 한국 떡의 본가라고 해도 손색이 없습니다 . 다양한 TV 매체를 통해 소개된 인증된 맛집으로 우리나라 전통음식인 떡 고유의 맛을 유지하기 위해 아직도 일일이 손으로 떡을 빚고 있어요. 대표적인 두텁떡은 고급진 맛으로 유명해요 . 원서동 출궁 궁녀로부터 전수받은 기술로 떡을 만드는 곳으로 ‘ 서울미래유산 ’ 으로도 지정되어 있습니다 .\n\n\n\n\n•  이곳은  \' 서울미래유산 \' 으로 선정된 곳입니다 .  서울의 근 · 현대 문화유산 중에서 미래 세대에게 전달할 만한 가치가 있는 유무형의 자산인 서울미래유산을 오래가게 여행에서 만나보세요 .  (서울미래유산 홈페이지)', 37.573788, 126.987908, '', '지하철 1/3/5호선 종로3가역 5번 출구, 202m', '두텁떡, 쑥떡, 모둠떡, 송편, 인절미', '매일', '', '카페, 디저트', '', '08:00~21:00', '02-732-5579', '없음'),
	(80, '울프강 스테이크 하우스', '06016  서울 강남구 선릉로152길 21 (청담동, 영인빌딩)', 'images/울프강_스테이크_하우스_80.jpg', '미국의 전통 있는 전세계 40개의 지점이 있는 최고의 스테이크하우스\n\n울프강 스테이크하우스는 미국의 전통 있는 스테이크하우스, 피터 루거 스테이크하우스에서 40여 년 간 헤드 웨이터로 근무했던 울프강\n즈위너가 지난 경험과 노하우를 살려 설립한 미국의 대표적인 스테이크하우스입니다. 미국 내에서 3%만 해당하는 최고급 소고기인 USDA 프라임 등급 블랙 앵거스 품종으로 28일간 드라이에이징으로 숙성된 스테이크만을 제공합니다.\n \n세계 총 13개 지점을 두고 있으며, 울프강 스테이크하우스 청담점은 총 225명 가량 수용이 가능합니다. 250평 규모로 1층은 테이블이 세팅된\n다이닝 홀과 바(Bar)가 있으며 1층과 2층에 총 7개의 프라이빗 룸이 있습니다. 룸은 6인부터 20인까지 수용 가능하며 비즈니스 미팅, 가족 모임\n또는 프라이빗 서비스가 가능합니다.', 37.524497, 127.041463, '', '지하철 수인분당선 압구정로데오역 4번 출구, 370m', '포터하우스 스테이크', '', ' http://www.wolfgangssteakhouse.co.kr/', '음식점', '', '매일 11:00 ~ 22:00', '0507-1486-8700', '연중무휴'),
	(81, '새벽집', '06013  서울 강남구 도산대로101길 6 (청담동)', 'images/새벽집_81.jpg', '다양한 메뉴. 고기나 선지, 콩나물 등이 들어간 따로국밥 해장. 육회 비빔밥을 시키면 선짓국이 서비스.\n\n다양한 메뉴를 갖추고 있어 24시간 사람들로 붐빕니다. 고기나 선지, 콩나물 등이 들어간 따로국밥 국물은 맛도 좋고 해장으로도 제격입니다. 육회 비빔밥을 시키면 선짓국이 서비스로 나옵니다. 샤부샤부도 가격대비 만족도가 높아 많이 찾는 메뉴. 아침에는 해장을, 저녁에는 고기를 구워 먹는 사람들로 가득합니다.', 37.525564, 127.052868, '', '지하철 7호선 청담역 13번 출구, 750m', '꽃등심, 양념갈비, 생고기, 불고기', '월요일~일요일', ' https://saebyukjip.modoo.at/', '음식점', '', '24시간 영업', '02-546-5739', '명절 휴무'),
	(82, '경인미술관 전통다원', '03146  서울특별시 종로구 인사동10길 11-4 (관훈동)  경인미술관', 'images/경인미술관_전통다원_82.jpg', '고택을 그대로 살려 한옥 특유의 운치가 돋보이는 공간. 예쁜 꽃과 나무로 치장된 정원과 다향.\n\n오래전부터 인사동을 상징하는 곳으로 존재해왔습니다. 태극기를 만든 인물로 우리에게 잘 알려진 박영효의 저택이 있던 곳으로, 고택을 그대로 살려 한옥 특유의 운치가 돋보이는 공간입니다. 예쁜 꽃과 나무로 치장된 정원을 보면서 다향에 취해 봅니다. 전통차를 시키면 한식 다과가 같이 나옵니다. 지금은 너무 알려진 탓인지 예전처럼 한가롭고 조용하게 차를 즐기기는 어려운 듯합니다.', 37.574484, 126.985432, '1만원대', '지하철 3호선 안국역 5번 출구 354m', '전통차, 잎차, 건강차, 미용차', '', ' http://www.kyunginart.co.kr', '카페, 디저트', '', '매일 11:00 ~ 21:20', '0507-1339-6305', '신정, 구정, 추석'),
	(83, '순희네 반찬', '03195  서울 종로구 창경궁로 88 1층 광장시장 65-1', 'images/순희네_반찬_83.jpg', '맛깔난 젓갈과 게장으로 유명한 광장시장 반찬가게\n\n사장님은 오빠의 장사 실패 후 직접 노점에서 반찬을 팔기 시작했다고 합니다. 노점에서 김치와 게장 등 맛 좋은 반찬을 팔며 입소문이 나고 광장시장 안에 처음으로 반찬가게를 내게 되었습니다. 가게 이름은 큰딸의 이름에서 따와 ‘ 순희네반찬 ’ 으로 짓게 되었습니다. 지금은 누구나 ‘ 순희 ’ 라는 이름을 쓰지만, 광장시장에서 원조 ‘ 순희 ’ 는 순희네반찬이라는 것이 사장의 자부심이고, 자랑거리입니다. 순희네반찬의 단골손님들은 이곳이 또 다른 친정 같다고 말합니다.', 37.570120, 126.999799, '', '지하철 1호선 종로5가역 8번 출구, 217m', '', '매일', '', '', '', '09:00~21:00', '02-2279-1885', '없음'),
	(84, '학림다방', '03079  서울 종로구 대학로 119 2층', 'images/학림다방_84.jpg', '예술인들에게 사랑받은 온 서울의 최고령 카페\n\n1956 년부터 60 년이 넘는 세월 동안 대학로에서 굳건하게 자리를 지키고 있는 학림다방은 혜화역 민주화운동을 주도했던 대학생들의 토론 장소는 물론 음악 , 미술 , 연극 , 문학 등 예술계 인사들의 단골다방으로 사랑받았습니다 . 지금은 서울에서 가장 오래된 카페로 , 매장 내부를 채운 LP 와 그림들이 예스러운 분위기를 물씬 자아냅니다 . 드라마 ‘ 별에서 온 그대 ’ 촬영지이기도 한 학림다방은 여전히 세대를 불문하고 많은 사랑을 받는 곳입니다 .\n\n \n\n• 이곳은 \' 서울미래유산 \' 으로 선정된 곳입니다 . 서울의 근 · 현대 문화유산 중에서 미래 세대에게 전달할 만한 가치가 있는 유무형의 자산인 서울미래유산을 오래가게 여행에서 만나보세요 .(https://futureheritage.seoul.go.kr)', 37.581930, 127.001677, '', '지하철 4호선 혜화역 3번 출구, 100m', '비엔나커피, 크림 치즈케익', '매일', '', '카페, 디저트', '', '10:00~23:00 (라스트오더 22:00)', '02-742-2877', '없음'),
	(85, '일품향', '04535  서울 중구 남대문로 52-13', 'images/일품향_85.jpg', '화교가 운영하는 유명한 중국 음식점. 저렴한 가격에 비해 훌륭한 수준의 중국 음식.\n\n화교가 운영하는 유명한 중국 음식점으로, 저렴한 가격에 비해 훌륭한 수준의 중국 음식을 내놓고 있습니다. 깐풍기, 탕수육 등의 튀김 요리가 맛있습니다. 향도 좋고 육질이 야들야들한 오향족발도 인기가 좋습니다.', 37.562064, 126.982246, '1만원대', '지하철 4호선 명동역 5번 출구, 337m', '잡채밥, 삼선우동, 짬뽕', '', '', '음식점', '', '11:00~14:30 / 16:30~21:00', '02-753-6928', '일요일'),
	(86, '산촌', '03148  서울특별시 종로구 인사동길 30-13 (관훈동)', 'images/산촌_86.jpg', '해초류등을 사찰음식으로 정성과 정갈, 청결하게 만들어 대중에게 알리는 음식점.\n\n산촌은 산과들에서 자라나는 산나물과 신선한 채소 바다에서 나오는 해초류등을 사찰음식으로 정성과 정갈, 청결하게 만들어 대중에게 알리는데 일익을 하는 음식점입니다. 특히 이곳 정산(김연식)스님은 동진 출가하여 원주스님 소임을 하면서 사라지는 사찰음식을 체계적으로 연구 보존하여 이를 후세에 알리는데 결정적인 역할을 하고 있습니다.', 37.573797, 126.986261, '', '지하철 3호선 안국역 6번 출구, 420m', '사찰음식(채식)', '', ' http://www.sanchon.com/index.php', '음식점', '', '매일 11:30~21:00', '02-735-0312', '명절'),
	(87, '대한곱창(장안점)', '02644  서울 동대문구 천호대로85길 21 (장안동, 동원빌딩)', 'images/대한곱창(장안점)_87.jpg', '실력파 걸그룹 마마무의 멤버 화사가 리얼리티 예능 <나 혼자 산다>에서 먹방을 선보인 후, 대한민국에 곱창 대란이 일어난 곳. 화사가 찾은 식당은 장한평역 근처에 위치한 대한곱창 장안점.\n\n실력파 걸그룹 마마무의 멤버 화사가 리얼리티 예능 <나 혼자 산다>에서 먹방을 선보인 후, 대한민국에 곱창 대란이 일어났습니다. 화사가 찾은 식당은 장한평역 근처에 위치한 대한 곱창 장안점. 방송이 나간 이후 너무 많은 사람들이 찾는 바람에 곱창이 다 떨어져 일찍 문을 닫을 정도로 문전성시를 이루고 있습니다.\n씹을수록 고소한 곱창, 쫄깃쫄깃한 식감이 매력적인 막창, 부드러운 대창까지 모두 맛볼 수 있는 모둠 곱창이 추천 메뉴. 대한 곱창만의 특제 소스와 양파, 치즈, 카레 시즈닝을 취향대로 골라 입맛대로 즐겨보세요. 화사처럼 볶음밥으로 마무리를 하면 이보다 완벽한 식사는 없을 것입니다.', 37.562986, 127.066292, '', '지하철 5호선 장한평역 3번 출구, 193m', '대한모듬곱창, 볶음밥', '', '', '음식점', '', '매일 15:00 - 01:00', '070-8285-6219', ''),
	(88, '갓잇 (God Eat)', '03980  서울 마포구 성미산로 161-13 (연남동, K&L)  1층', 'images/갓잇_(God_Eat)_88.jpg', '멕시코 현지에 온듯한 이국적인 분위기와 과카몰리와 살사소스 듬뿍 곁들인 멕시칸 푸드\n\n신이 먹을만큼 맛있고 건강한 음식-갓잇 (God Eat)\n\n도심 서울 속에서 잠깐의 식사시간이지만 편안한 휴양지에 온 듯한 느낌을 받는 식당입니다. 관광객이 한식을 많이 찾지만 가끔 고향의 맛이 그리울 때, 서양적인 맛과 한국적인 맛이 아름답게 조화되어 새로운 맛을 맛볼 수 있습니다. 또한 몸에 좋은 푸드로 자극적이지 않으며 신선합니다. 주문 후 빠르게 나오는 패스트푸드이지만 건강에 신경을 많이 쓰며 만든다. 전메뉴가 포장이 가능하며, 좋은 날씨에는 어느 곳에 가서도 먹기 편하게 포장됩니다.', 37.565232, 126.923611, '', '지하철 2호선/경의중앙선/공항철도 홍대입구역 3번 출구, 907m', 'GOD 보울, 브리또, 타코', '', ' https://app.catchtable.co.kr/ct/shop/goteat_yeonnam', '음식점', '', '평일 11:00~15:00, 16:30~21:30 / 주말 11:00~21:30', '0507-1312-9451', ''),
	(89, '형제갈비', '03776  서울 서대문구 명물1길 2 (창천동)', 'images/형제갈비_89.jpg', '40년 가까이 된 갈비 전문점. 신촌 일대에서는 예전부터 유명했던 집. 숯불에 구워 먹는 소갈비의 맛이 일품. 돌솥비빔밥, 갈비탕, 보리밥 등 저렴하게 한식을 즐길 수 있는 곳.\n\n40년 가까이 된 갈비 전문점. 신촌 일대에서는 예전부터 유명했던 집입니다. 숯불에 구워 먹는 소갈비의 맛이 일품입니다. 담백한 생갈비와 부드러운 양념갈비 모두 인기가 많습니다. 갈비를 전문으로 하지만 돌솥비빔밥, 갈비탕, 보리밥 등의 식사 메뉴도 있어 저렴하게 한식을 즐길 수 있는 곳입니다. 달달한 불고기도 갈비만큼 찾는 사람이 많은 인기 메뉴입니다. 층별로 갈비탕, 예약 손님, 숯불갈비, 불고기 등 메뉴에 따라 구분되어 있어 쾌적한 환경에서 음식을 즐길 수 있고 실내가 넓어 가족단위나 단체 손님도 많이 찾습니다. 또한 직원분들이 직접 고기를 구워주기 때문에 편리하게 식사를 할 수 있습니다.', 37.557839, 126.937350, '', '지하철 2호선 신촌역 3번 출구, 261m', '소고기구이', '', '', '음식점', '', '매일 11:00 ~ 22:00', '02-365-0001', '연중무휴'),
	(90, '한우리(본점)', '06054  서울특별시 강남구 도산대로 304 (논현동)', 'images/한우리(본점)_90.jpg', '순 한우 등심만을 고집하는 24년 전통의 샤브샤브 전문점. 전남 광주 농장에서 매일 직송되는 최고급 한우고기. 샤브샤브에 곁들여진 유기농 계절 채소와 손으로 만든 두부, 거기다 직접 뽑아낸 탄력있는 국수와 진한 육수가 일품.\n\n최고급 한우 정통 샤브샤브 전문점\n순 한우 등심만을 고집하는 24년 전통의 샤브샤브 전문점. 전남 광주 농장에서 매일 직송되는 최고급 한우고기가 군침을 돌게 합니다. 샤브샤브에 곁들여진 유기농 계절 채소와 손으로 만든 두부, 거기다 직접 뽑아낸 탄력있는 국수와 진한 육수가 일품입니다.', 37.521150, 127.034729, '', '지하철 7호선/ 수인분당선 강남구청역 3번 출구, 1.1km', '버섯쇠고기국수전골 로스편채 생샤브샤브', '월요일~일요일', ' http://www.hwrfood.com', '음식점', '', '평일 11:30~14:30, 17:30~22:00 / 주말 11:30~22:00', '02-545-3334', '명절 당일'),
	(91, '진주회관', '04513  서울특별시 중구 세종대로11길 26 (서소문동)', 'images/진주회관_91.jpg', '한국인들의 여름별미인 콩국수로 유명한 음식점. 밀가루에 감자가루, 견과류 등을 넣어 만든 면을 사용. 여름에는 진하고 고소한 콩국수가 최고 인기이고, 겨울에는 김치볶음밥이 인기.\n\n한국인들의 여름별미인 콩국수로 유명한 음식점입니다. 밀가루에 감자가루, 견과류 등을 넣어 만든 면을 사용합니다. 여름에는 진하고 고소한 콩국수가 최고 인기이고, 겨울에는 김치볶음밥이 인기입니다. 단골이 많아 늘 줄을 서야 합니다.', 37.562314, 126.974583, '1만원대', '지하철 1/2호선 시청역 9번 출구, 104m', '', '월요일~토요일', '', '음식점', '', '평일 11:00~14:00, 14:30~21:00\n토요일 11:00~14:00, 15:00~20:00', '02-753-5388', '휴무일: 일요일'),
	(92, '석파랑', '03021  서울특별시 종로구 자하문로 309 (홍지동)', 'images/석파랑_92.jpg', '흥선대원군의 별장 석파정의 부속 사랑채를 옮겨 꾸민 한정식 집\n\n맛과 정성이 깃든 정통 한정식 전문점\n\n\n흥선대원군의 별장 석파정의 부속 사랑채를 옮겨 꾸민 한정식 집. 수라상에 올리던 궁중음식이 고풍스러운 그릇에 담겨 나옵니다. 전통 죽으로부터 시작하는 코스 요리는 구절판, 안심 편채, 전복구이, 신선로 등으로 구성되어 있습니다.', 37.599256, 126.958750, '', '지하철 3호선 경복궁역 3번출구, 1711.7018.1020탑승, 상명대입구 하차 202m', '', '월,화,목,금,토,일', ' http://www.seokparang.co.kr', '음식점', '', '12:00 ~ 15:00 / 18:00 ~ 22:00', '02-395-2500', '매주 수요일 휴무'),
	(93, '바다식당', '04348  서울 용산구 이태원로 245 2층 (한남동)', 'images/바다식당_93.jpg', '부대찌개가 유명한 집. ‘존슨탕’이라 불리는 이 식당의 고유한 부대찌개는 육수에 소시지, 감자, 양배추, 고기 등과 함께 마지막에 치즈를 넣어 부드럽고 고소한 맛. 스테이크와 소시지 구이.\n\n부대찌개가 유명한 집. ‘존슨탕’이라 불리는 이 식당의 고유한 부대찌개는 육수에 소시지, 감자, 양배추, 고기 등과 함께 마지막에 치즈를 넣어 부드럽고 고소한 맛을 자랑합니다. 스테이크와 소시지 구이도 맛있습니다.', 37.536908, 127.000040, '', '지하철 6호선 한강진역 1번 출구, 400m', '존슨탕, 돼지갈비바베큐, 소갈비바베큐, 소고기쏘세지, 정통티본스테이크, 폭찹', '', '', '음식점', '', '매일 11:30 ~ 22:00', '0507-1376-1317', '첫째, 셋째 , 다섯째 주 월요일, 명절 휴무'),
	(94, '산동교자', '04535  서울 중구 남대문로 52-13 (명동2가)', 'images/산동교자_94.jpg', '허름한 외관을 하고 있으나 정통 중국 음식의 맛.\n\n허름한 외관을 하고 있으나 정통 중국 음식의 맛을 느낄 수 있습니다. 화교 부부가 주방을 맡고 모두 직접 손으로 만듭니다. 쫄깃쫄깃한 만두피에 중국 부추로 소를 채운 물만두와 오향장육이 유명합니다.', 37.562132, 126.982239, '1만원대', '지하철 4호선 명동역 5번 출구, 337m', '오향장육, 짜장면, 탕수육, 물만두', '', '', '음식점', '', '월~토 11:00~15:30 / 17:00~21:20', '02-778-4150', '매주 일요일, 명절 휴무'),
	(95, '진아춘 광화문점', '03186  서울 종로구 새문안로 92 (신문로1가, 광화문오피시아)', 'images/진아춘_광화문점_95.jpg', '옛 서울대의 추억이 깃든 혜화동 대표 중식당\n\n진아춘은 1925년 개업한 서울에서 가장 오래된 중국집으로, 일제 강점기부터 이어온 역사 깊은 장소입니다. 대학로에 위치해있으며, 1960-1970년대 서울대 학생들에게 인기 있던 곳으로, 돈이 부족했던 대학생들은 짜장면을 먹고자 손목시계를 담보로 맡길 정도였습니다. 대표 메뉴는 기본에 충실한 짜장면으로, 쫄깃한 면발과 소스의 조화가 일품입니다. 가게 내부에는 긴 역사와 관련된 사진들이 전시되어 있어, 식사 중에도 과거의 이야기를 엿볼 수 있습니다.', 37.569700, 126.974908, '1만원대', '지하철 5호선 광화문역 6번 출구, 192m', '짜장면, 고추간짜장, 삼선짜장, 볶음짜장', '', '', '음식점', '', '월요일~토요일 11:00 ~ 14:30 / 17:00 ~ 21:20', '02-720-0688', '매주 일요일, 명절 휴무'),
	(96, '두루', '06064  서울 강남구 선릉로148길 28 (청담동)', 'images/두루_96.jpg', 'EXO의 멤버 디오가 모 잡지에 추천한 식당\n\nEXO의 멤버 디오가 모 잡지에 추천한 식당. 디오 외에도 시우민, 세훈 등 EXO 멤버들이 자주 찾는다는 청담에 위치한 이 식당은 대한민국 레스토랑 가이드북인 <블루리본 서베이>에서 블루리본을 3개나 받았을 정도로 평이 좋습니다.\n깔끔하고 정갈한 분위기를 자랑하는 이 식당의 인기 메뉴는 디오가 추천한 낙지볶음과 주먹밥입니다. 깔끔하게 매운 낙지볶음과 함께 입안을 편안하게 진정시켜주는 고소한 주먹밥, 직접 담근다는 맛깔스러운 밑반찬의 조합이 일품입니다. 여기에 추천하는 메뉴가 한 가지 더 있는데, 바로 자색고구마 막걸리입니다. 발그스레한 두 뺨처럼 어여쁜 색을 띠는 이 자색고구마 막걸리는 낙지볶음과 합이 좋아 손님들이 자주 같이 찾습니다.', 37.522604, 127.041851, '', '지하철 수인분당선 압구정로데오역 4번 출구, 600m', '낙지볶음, 주먹밥', '', '', '음식점', '', '매일 11:00~21:00', '02-3443-8834', '연중무휴'),
	(97, '미성옥', '04534  서울 중구 명동길 25-11', 'images/미성옥_97.jpg', '1966년에 문을 연 곳으로, ‘명동의 설렁탕집’으로 유명. 설렁탕에는 양짓살만이 들어가는데 고기 질이 양호. 맑은 국물.\n\n1966년에 문을 연 곳으로, ‘명동의 설렁탕집’으로 유명합니다. 설렁탕에는 양짓살만이 들어가는데 고기 질이 양호합니다. 맑은 국물을 좋아하는 사람에게 좋습니다.', 37.564177, 126.983947, '1만원대', '지하철 2호선 을지로입구역 6번 출구, 364m', '설렁탕, 수육', '', '', '음식점', '', '매일 06:00 ~ 21:00', '02-776-8929', '연중무휴'),
	(98, '국화정원', '02838  서울특별시 성북구 성북로 154 (성북동)', 'images/국화정원_98.jpg', '전통 한식 코스 요리 전문점으로, 한 번에 한 상 가득 차려지는 것이 아니라 코스마다 특색 있는 요리. 전복초회, 전복구이, 일품 모둠생선회 등은 미리 예약. 1925년에 지어진 전통 기와 고택의 고풍스러움.\n\n전통 한식 코스 요리 전문점으로, 한 번에 한 상 가득 차려지는 것이 아니라 코스마다 특색 있는 요리를 선보입니다. 미리 예약하면 전복초회, 전복구이, 일품 모둠생선회 등도 준비된됩니다. 1925년에 지어진 전통 기와 고택의 고풍스러움을 그대로 살린 인테리어가 인상적입니다. 독립된 별채에서 식사하려면 미리 예약을 해야 합니다.', 37.594564, 126.992703, '3만원대', '지하철 4호선 한성대입구 5번 출구, 1.4km', '한정식', '월화수목금토일', '', '음식점', '', '12:00 ~ 15:00 / 17:00 ~ 21:30', '0507-1361-0159', '명절 휴무'),
	(99, '올댓재즈', '04404  서울 용산구 이태원로 216 (한남동)', 'images/올댓재즈_99.jpg', '우리나라 최초의 재즈 바. 2천여 장의 LP와 6백여 장의 CD를 보유하고 있는 우리나라 재즈의 산 역사의 장소.\n\n중국계 미국인 마명덕 씨가 1976년 이태원에 문을 연 재즈 클럽으로, 우리나라 최초의 재즈 바입니다. 또한, 2천여 장의 LP와 6백여 장의 CD를 보유하고 있는 우리나라 재즈의 산 역사의 장소이기도 합니다. 월요일부터 목요일까지는 별도의 입장료 없이 오천 원 정도의 음료만으로도 재즈를 감상할 수 있습니다. 최근 처음의 자리에서 해밀턴 호텔 부근으로 이전하였습니다. 이사한 이후 예전의 분위기는 퇴색한 느낌입니다.', 37.534687, 126.998137, '2만원대', '지하철 6호선 이태원역 3번 출구, 333m', '재즈바', '매일', '', '술집, 바', '', '일요일~목요일 18:00~24:00, 금요일~토요일 18:00~01:00', '02-795-5701', '연중무휴'),
	(100, '오세계향', '03146  서울 종로구 인사동12길 14-5 (관훈동)', 'images/오세계향_100.jpg', '인사동 오세계향은 일체의 동물성, GMO 원재료, MSG를 사용하지 않은 비건채식 레스토랑. 유기농 쌀과 친환경 농산물로 요리한 고급스럽고 맛있는 비건 요리.\n\n인사동 오세계향은 일체의 동물성, GMO 원재료, MSG를 사용하지 않은 비건채식 레스토랑입니다. 유기농 쌀과 친환경 농산물로 요리한 고급스럽고 맛있는 비건 요리를 맛 보실 수 있습니다.', 37.574680, 126.985267, '', '지하철 3호선 안국역 6번 출구, 224m', '불구이쌈밥, 두개장정식, 중화볶음우동, 순두부강된장비빔밥', '', ' http://www.go5.co.kr/ ', '음식점', '', '11:30~16:00, 17:00~21:00', '02-735-7171', '매주 목요일'),
	(101, '진주집 여의도점', '07331  서울 영등포구 국제금융로6길 33 (여의도동)', 'images/진주집_여의도점_101.jpg', '콩국수가 유명한 집. 진하고 담백하면서도 깊이 있는 맛. 콩국수 외에도 비빔국수, 닭칼국수도 인기메뉴. 인근의 회사원들이 많이 찾는, 서민적인 분위기의 음식점.\n\n콩국수가 유명한 집. 진하고 담백하면서도 깊이 있는 맛을 자랑합니다. 콩국수 외에도 비빔국수, 닭칼국수도 인기메뉴입니다. 인근의 회사원들이 많이 찾는, 서민적인 분위기의 음식점입니다.', 37.520771, 126.926595, '1만원대', '지하철 5/9호선 여의도역 5번 출구, 302m', '콩국수, 비빔국수, 닭칼국수, 냉콩국수, 육개장칼국수', '월요일~토요일', '', '음식점', '', '평일 10:00~20:00\n토요일 10:00~19:00', '02-780-6108', '매주 일요일, 공휴일 휴무'),
	(102, '필동면옥', '04624  서울특별시 중구 서애로 26 (필동3가)', 'images/필동면옥_102.jpg', '정통 평양식 냉면. 평안도식 만두나 제육과 함께. 뜨거운 육수 대신 사리 삶은 물(면수)을 주는 것이 특징. 을지면옥과 비슷한 맛을 내면서도 이상하게 호불호가 많이 갈리는 집.\n\n냉면은 정통 평양식 냉면을 선보입니다. 평안도식 만두나 제육과 함께 하면 제대로 된 맛을 즐길 수 있습니다. 뜨거운 육수 대신 사리 삶은 물(면수)을 주는 것이 특징입니다. 을지면옥과 비슷한 맛을 내면서도 이상하게 호불호가 많이 갈리는 집입니다.', 37.560393, 126.997004, '1만원대', '지하철 3/4호선 충무로역 1번 출구, 293m', '냉면', '월요일 ~ 토요일', '', '음식점', '', '11:00~16:00, 17:00~20:30', '02-2266-2611', '일요일, 명절 휴무'),
	(103, '도향촌', '04535  서울 중구 남대문로 52-13 (명동2가)  중정도서관빌딩 1층', 'images/도향촌_103.jpg', '천연 재료로 만들어진 중국전통과자점. 중국과자 특유의 향과 깊은 맛\n\n천연 재료로 만들어진 중국전통과자점으로, 중국과자 특유의 향과 깊은 맛을 느낄 수 있는 곳입니다. 월병 등 다양하게 준비된 중국 과자와 16가지 재료가 들어가는 재스민 차를 함께 먹으면 좋습니다. 10가지 과일이 들어갔다는 십경월병이 유명한데, 중국풍이어서 우리 입맛에는 잘 안 맞을 수도 있습니다.', 37.562132, 126.982239, '', '지하철 4호선 명동역 5번 출구, 337m', '편로수, 장원병, 산동팔보, 지마병, 천층수, 십경월병', '매일', ' http://www.dhcmooncake.com', '카페, 디저트', '', '월요일~토요일 10:00 ~ 20:00\n일요일 11:00 ~ 18:00', '02-776-5671', '명절 휴무'),
	(104, '북악정(이상갈비)', '03004  서울 종로구 평창36길 6 (북악정)', 'images/북악정(이상갈비)_104.jpg', '도심 속 푸른 자연을 만날 수 있는 곳. 26년의 노하우가 고루 밴 양념갈비의 맛과 계절별로 바뀌는 푸짐한 찬. 라운지를 무료로 제공.\n\n자연에 취하고 맛에 취하는 갈비의 명가\n\n\n도심 속 푸른 자연을 만날 수 있는 곳. 26년의 노하우가 고루 밴 양념갈비의 맛은 계절별로 바뀌는 푸짐한 찬과 어우러져 오감을 즐겁게 한다. 담소를 즐길 수 있는 라운지를 무료로 제공한다.', 37.611337, 126.977752, '', '지하철 4호선 길음역 5번출구, 163번. 7211번 버스환승 후 롯데아파트 하차', '북악정 양념갈비 생갈비 한우 꽃등심', '월화수목금토일', ' https://www.instagram.com/bugakjung/', '음식점', '', '매일 11:00 ~ 22:00', '02-394-2340', '연중무휴'),
	(105, '부민옥', '04522  서울 중구 다동길 24-12 (다동)', 'images/부민옥_105.jpg', '애주가들이 즐겨 찾는 양무침과 시원한 육개장\n\n부민옥은 1980-1990년대 직장인들의 사랑을 받았던 중구 다동에 위치한 육개장 전문점으로, 이북 출신 창업주가 한국전쟁 시절 부산 부민동에서의 장사 경험을 바탕으로 개업했습니다. 부민옥의 육개장은 큼직한 파와 소고기를 듬뿍 넣어 깔끔하고 담백한 맛이 특징이며, 저녁 시간에는 육개장과 소주를 곁들이려는 사람들이 많이 찾습니다. 넉넉한 테이블 배치로 편안한 식사 분위기를 제공합니다.', 37.567531, 126.980178, '', '지하철 2호선 을지로입구역 1번 출구, 300m', '육개장, 양곰탕, 복국, 선지국, 양무침', '', '', '음식점', '', '월요일~토요일 11:00 ~ 14:00 / 17:00 ~ 22:00', '02-777-2345', '일요일, 명절 휴무'),
	(106, '몰타참치', '06194  서울 강남구 삼성로85길 26 (대치동, V&S)  V&S빌딩 2층', 'images/몰타참치_106.jpg', '참치를 전문으로 내는 곳. 오도로와 참치배꼽살, 가마도로\n\n참치를 전문으로 내는 곳으로, 가격대는 높은 편이나 오도로와 참치배꼽살, 가마도로 등 최고 품질의 참치를 즐길 수 있습니다. 참치와 함께 계절별 생선회도 약간 곁들여집니다. 회를 찍어 먹으라고 나오는 간장게장 맛이 일품입니다.', 37.504967, 127.055039, '3만원대', '지하철 2호선/ 수인분당선 선릉역 1번 출구, 582m', '몰타정식, 가마도로 사시미', '월요일~토요일', '', '음식점', '', '11:30~15:00, 16:30~22:00', '02-508-7861', '매주 일요일, 명절휴무'),
	(107, '손가네곰국수', '02880  서울 성북구 성북로15길 8', 'images/손가네곰국수_107.jpg', '한우 생불고기와 곰국수(사골 국물 칼국수).\n\n한우 생불고기와 곰국수(사골 국물 칼국수)를 맛볼 수 있습니다. 이북식 왕만두도 인기 메뉴입니다. 한옥 분위기에서 담백한 주요리와 정갈한 반찬을 맛볼 수 있어 찾는 사람들이 많습니다.', 37.593125, 127.000425, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 717m', '곰국수, 소불고기, 설렁탕, 갈비탕', '', '', '음식점', '', '월요일~토요일 11:00~21:00', '02-743-8937', '매주 일요일'),
	(108, '대려도', '06251  서울 강남구 역삼로 118 (역삼동)', 'images/대려도_108.jpg', '한국인의 입맛에 맞는 정통 북경요리를 하는 곳.\n\n한국인의 입맛에 맞는 정통 북경요리를 하는 곳으로 냉채, 샥스핀, 죽순해삼, 새우, 북경요리, 식사 등 10가지 요리를 4~5만 원대에 즐길 수 있습니다.', 37.493432, 127.032180, '', '지하철 2호선/신분당선 강남역 4번 출구, 456m', '육품냉채, 간풍바다가재', '', ' http://www.daeryudo.com/', '음식점', '', '매일 11:30 ~ 15:00 / 17:30 ~ 22:00', '02-555-0550', '명절 휴무'),
	(109, '토담골49', '06070  서울 강남구 삼성로 766 (청담동, 유림빌딩)', 'images/토담골49_109.jpg', '토속적인 한식을 내는 집. 20여 종류의 산나물로 맛을 내는 토담골 정식이나, 취쌈과 호박쌈 등 시골 정취를 듬뿍 맛볼 수 있는 꽁보리밥이 인기 .\n\n토속적인 한식을 내는 집. 20여 종류의 산나물로 맛을 내는 토담골 정식이나, 취쌈과 호박쌈 등 시골 정취를 듬뿍 맛볼 수 있는 꽁보리밥이 인기 메뉴입니다. 점심 시간에는 산채비빔밥, 콩비지, 된장찌개, 김치찌개, 콩나물밥 등 특별 메뉴를 준비하고 있으며 저녁에는 손멧돌로 직접 갈아 만든 녹두전이나 제육 굴보쌈 등도 맛볼 수 있습니다.', 37.523233, 127.048223, '2만원대', '지하철 7호선 청담역 9번 출구, 471m', '토담골정식, 꽁보리밥, 꽁보리열무비빔밥, 돌솥곱창냉이찌개', '', ' https://www.instagram.com/todamgol49/#', '음식점', '', '11:30 ~ 15:00 / 17:00 ~ 22:00', '0507-1451-5122', '매주 일요일'),
	(110, '곽경찬의 시골밥상', '04348  서울 용산구 이태원로 235 (한남동)', 'images/곽경찬의_시골밥상_110.jpg', '시골스러운 인테리어. 여러 가지 반찬에 구수한 된장국이 나오는 한정식이 인기 .\n\n전라도가 고향인 주방 아주머니의 손맛이 일품인 곳입니다. 시골스러운 인테리어가 정감있습니다. 여러 가지 반찬에 구수한 된장국이 나오는 한정식이 인기 메뉴입니다.', 37.536155, 126.999500, '1만원대', '지하철 6호선 이태원역 2번 출구, 523m', '시골밥상, 굴비/갈치 각, 게장, 뚝불고기', '매일', '', '음식점', '', '10:30~20:00', '02-794-5072', '연중무휴'),
	(111, '신가예촌', '06733  서울 서초구 서운로 11 (서초동, 서초대우디오빌)', 'images/신가예촌_111.jpg', '고향의 정겨움이 깊이 묻어나는 곳 46년 외길 토속 한정식 총주방장과 호텔신라 지배인이 뭉친 토속 음식 전문점.\n\n고향의 정겨움이 깊이 묻어나는 곳\n46년 외길 토속 한정식 총주방장과 호텔신라 지배인이 뭉친 토속 음식 전문점입니다. 이곳에서 직접 담근 된장, 간장, 고추장에서 시골의 정겨운 맛을 진하게 느낄 수 있습니다. 시골 된장찌개, 해물 순두부찌개, 곱창 김치찌개, 콩비지 등 친환경 재료로 제대로 끓여낸 찌개류를 맛볼 수 있습니다.', 37.484995, 127.029113, '', '지하철 3호선/신분당선 양재역 1번 출구, 440m', '한정식', '월요일~일요일', '', '음식점', '', '평일 11:00 ~ 15:00 / 17:00 ~ 22:00\n주말 11:00 ~ 15:00 / 16:30 ~ 21:00', '0507-1321-0986', '연중무휴 ( 명정 당일만 쉼 )'),
	(112, '컨퍼런스하우스달개비', '04519  서울특별시 중구 세종대로19길 16 (정동)', 'images/컨퍼런스하우스달개비_112.jpg', '김치를 재료로 한 식문화를 경험할 수 있는 카페와 반찬샵으로 구성\n\n컨퍼런스하우스 달개비가 운영하는 ‘카페&반찬샵’은 김치를 재료로 한 식문화를 경험할 수 있는 카페와 반찬샵으로 구성돼 있습니다. 달개비김치 함순효 대표의 음식 철학을 경험할 수 있는 달개비 반찬샵 입니다.', 37.566723, 126.976533, '', '지하철 1 / 2호선 시청역 3번 출구, 132m', '', '월요일 ~ 토요일', '', '음식점', '', '평일 07:30 ~ 21:30\n토요일 10:00 ~ 21:30', '02-765-2035', '명절, 매주 일요일'),
	(113, '오미가(신사점)', '06032  서울 강남구 논현로 833 (재경빌딩)', 'images/오미가(신사점)_113.jpg', '어머니의 정성과 손맛 그대로 담은 토속한정식전문점\n\n어릴 적 어머니가 해주시던 그 맛 그대로 담아낸 오미가의 맛깔나는 한정식은 추억을 떠올리게 하는 맛입니다.', 37.522830, 127.027895, '', '지하철 3호선 압구정역 4번 출구, 323m', '오미가 한정식, 오미가 돌솥밥', '', '', '음식점', '', '매일 11:30~15:00, 17:30~21:30', '02-543-1145', '명절 휴무'),
	(114, '솔빈덕핫도그', '06018  서울 강남구 도산대로51길 40 (신사동)', 'images/솔빈덕핫도그_114.jpg', '슈퍼주니어의 희철이 몇 년째 단골이라는 곳. 희철이 즐겨 먹는 메뉴는 입술이 아릴만큼 매운 쓰벌덕.\n\n동남아와 중국에서 독보적인 인기를 구가하는 한류스타, 슈퍼주니어. 조각 같은 외모와 달변을 겸비한 슈퍼주니어의 ‘실세’, 희철은 미식가로 자자합니다. 입맛 까다로운 희철이 몇 년째 단골이라는 곳이 바로 압구정로데오의 명물, 솔빈덕입니다. 오후 6시부터 새벽 5시 30분까지 영업한다는 특수성 때문에 스케줄이 끝나고 요기를 하러 이곳을 찾는 연예인들이 심심찮게 목격되기도 합니다. 이곳의 메뉴는 크게 타코와 핫도그, 라이스보울의 세 종류. 희철이 즐겨 먹는메뉴는 입술이 아릴만큼 맵고, 밤마다 생각날 만큼 중독성 최고라는 쓰벌덕. 나초와 사워크림, 할라피뇨, 야채와 갈비를 밥과 함께 먹는 갈비라이스 역시 안 먹으면 후회할 이곳의 간판 메뉴입니다.', 37.525700, 127.038261, '', '지하철 수인분당선 압구정로데오역 5번 출구, 약 285m', '', '월요일~토요일', ' http://instagram.com/solbindog', '음식점', '', '18:00 - 05:30', '010-9466-3419', '일요일 휴무'),
	(115, '강강술래(상계점)', '01630  서울 노원구 동일로 1628 (상계동, 상계동강강술래)', 'images/강강술래(상계점)_115.jpg', '수락산과 도봉산의 수려한 산세를 병풍처럼 두른 곳. 인기 메뉴 한우 모듬구이는 한우 100%로 안창살, 토시살, 치맛살, 제비추리, 살치살과 함께 쇠고기의 최고 부위인 갈비살과 등심 중 당일 가장 신선하고 맛이 뛰어난 부위만 엄선하여 제공.\n\n세계에 보여주고 싶은 최고의 갈비전문점 \n\n 수락산과 도봉산의 수려한 산세를 병풍처럼 두른 곳. 인기 메뉴 한우 모듬구이는 한우 100%로 안창살, 토시살, 치맛살, 제비추리, 살치살과 함께 쇠고기의 최고 부위인 갈비살과 등심 중 당일 가장 신선하고 맛이 뛰어난 부위만 엄선하여 제공합니다.', 37.673843, 127.056030, '', '지하철 7호선 수락산역 3번 출구, 352m', '한우모둠구이, 한돈양념구이', '', ' http://www.sullai.com', '음식점', '', '월요일~금요일 11:00~22:20\n토요일~일요일 10:30~22:20', '02-935-9233', '연중무휴'),
	(116, '무궁화', '04533  서울 중구 을지로 30 (소공동, 롯데호텔)  38층', 'images/무궁화_116.jpg', '한국적인 감각을 살린 모던한 디자인에 한국 정통 반가 음식을 한정식\n\n한국적인 감각을 살린 모던한 디자인에 한국 정통 반가 음식을 한정식으로 새롭게 해석하였습니다. 한식과 어울리는 와인 40여 종과 10여 종의 전통차도 준비되어 있습니다. 전망도 아주 훌륭합니다.', 37.565346, 126.981008, '', '지하철 2호선 을지로입구역 8번 출구, 68m', '굴비구이반상, 전복구이반상, 한우등심구이반상, 보양식 런치', '', ' https://www.lottehotel.com/seoul-hotel/ko/dining/restaurant-mugunghwa', '음식점', '', '매일 11:30~14:30 / 17:30~21:30', '02-317-7061', '연중무휴'),
	(117, '자하손만두', '03020  서울 종로구 백석동길 12', 'images/자하손만두_117.jpg', '손만두 집이라고도 불리는 호두와 잣을 넣어 빚은 소만두, 버섯을 넣은 편수\n\n일명 손만두 집이라고도 불리는 곳으로, 호두와 잣을 넣어 빚은 소만두와 버섯을 넣은 편수 등을 맛볼 수 있습니다. 만둣국을 주문하면 분홍과 노랑, 파랑으로 빚어 내는 색동만두를 넣어줍니다. 담백한 맛의 삼색만두로 끓인 떡만둣국과 만두전골 등이 인기 메뉴입니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.593149, 126.966008, '', '지하철 3호선 경복궁역 3번 출구, 7022, 1020, 7212 버스 승차, 부암동사무소 하차', '만두국, 떡만두국, 만두전골', '', '', '음식점', '', '화~일 11:00~21:00', '02-379-2648', '매주 월요일'),
	(118, '콩지POT지', '03060  서울특별시 종로구 북촌로 21-15 (재동)', 'images/콩지POT지_118.jpg', '컨템포러리 레스토랑으로, 스타일리시하고 모던한 분위기\n\n삼청동 분위기와는 사뭇 다른 컨템포러리 레스토랑으로, 스타일리시하고 모던한 분위기에서 식사할 수 있습니다. 창밖으로는 아름다운 북촌의 한옥들이 보입니다. 레스토랑 건물 지하는 갤러리로 식사를 마친 후 둘러보기에도 좋습니다.', 37.578835, 126.984377, '', '지하철 3호선 안국역 2번 출구, 287m', '시그니처 새우오일파스타, 시그니처 최상급한우채끝살스테이크, 호두까르보나라', '', ' http://kongjipotji.fordining.kr/', '음식점', '', '11:30~21:30 (15:00~16:30 브레이크타임)', '02-745-2203', '연중무휴'),
	(119, '강강술래(역삼점)', '06257  서울 강남구 논현로 325 (강강술래)', 'images/강강술래(역삼점)_119.jpg', '기와와 원목을 이용한 인테리어로 전통적인 한국의 미(美)와 정감이 살아 숨 쉬는 한우 전문점.\n\n기와와 원목을 이용한 인테리어로 전통적인 한국의 미(美)와 정감이 살아 숨 쉬는 한우 전문점입니다. 강강술래의 한우 모둠은 가장 신선하고 맛이 뛰어난 부위만을 엄선하여 고객의 눈과 귀와 입을 즐겁게 해줍니다. 실내를 아름답게 감싸고 있는 설치 미술과 그림들을 보면서 모처럼의 여유를 누려보세요.', 37.494206, 127.039690, '', '지하철 2호선 역삼역 2번 출구, 765m', '한우꽃등심, 한우생등심, 한우육회비빔냉면, 한우육회', '', ' http://www.sullai.com ', '음식점', '', '매일 11:00~22:00', '02-567-9233', '연중무휴'),
	(120, '여의도따로국밥', '07333  서울 영등포구 여의대방로69길 28 (유성빌딩)', 'images/여의도따로국밥_120.jpg', '진한 국물의 국밥과 큼직한 사태가 들어 있는 따로국밥전문점. 꼬리수육도 인기. 여의도에 자리 잡은 지 30여 년 전통.\n\n진한 국물의 국밥과 큼직한 사태가 들어 있는 따로국밥전문점. 꼬리수육도 인기가 좋습니다. 여의도에 자리 잡은 지 30여 년 된 전통 있는 곳입니다.', 37.521399, 126.930233, '', '지하철 5/9호선 여의도역 5번 출구, 656m', '따로국밥, 콩나물국밥, 꼬리국밥, 버섯생불고기, 꼬리수육, 들판수육', '매일', '', '음식점', '', '07:00~22:00', '02-782-0047', '연중무휴'),
	(121, '구스테이크528', '06028  서울 강남구 압구정로 108 (신사동, 덕산빌딩)', 'images/구스테이크528_121.jpg', '숙성한 소고기 스테이크를 먹을 수 있는 곳\n\n숙성한 소고기 스테이크를 먹을 수 있는 곳으로 유명해졌습다니. 실내에 들어서면 저장고에서 숙성되고 있는 고기가 보이도록 진열되어 있습니다. 잘 숙성된 고기는 상태에 따라 그날의 시가가 결정되기 때문에 생각보다 높은 가격을 지급할 각오를 하고 가야 합니다.', 37.522889, 127.020600, '', '지하철 3호선/신분당선 신사역 6번 출구, 778m', '', '수요일~월요일', ' https://www.instagram.com/goostk/#', '음식점', '', '12:00 ~ 15:00 / 17:00 ~ 22:00', '02-511-0917', '매주 화요일'),
	(122, '오구반점', '04543  서울 중구 수표로 60', 'images/오구반점_122.jpg', '60년이 넘는 오랜 전통을 가진 화교 중식당.\n\n60년이 넘는 오랜 전통을 가진 화교 중식당입니다. 실내에서 볼 수 있는 낡은 탁자와 의자는 오랜 세월을 느끼게 해줍니다. 서비스 군만두가 아닌, 요리로서의 군만두를 맛볼 수 있기도 합니다. 오향장육, 튀김요리가 평균 이상의 맛을 내며, 볶음밥과 함께 나오는 계란탕에서 내공을 느낄 수 있는 중식당입니다.', 37.566548, 126.989829, '1만원대', '지하철 2/3호선 을지로3가역 2번 출구, 31m', '짜장면, 짬뽕, 간짜장, 울면', '', '', '음식점', '', '평일 11:00~15:00, 17:00~21:00 / 토요일 11:00~20:00', '02-2267-0516', '매주 일요일, 공휴일 휴무'),
	(123, '해주냉면', '05561  서울 송파구 백제고분로7길 8-16 (잠실동, 남광빌딩)', 'images/해주냉면_123.jpg', '냉면 하나로 30여 년간 명성을 날리고 있는 집.\n\n냉면 하나로 30여 년간 명성을 날리고 있는 집입니다. 맵기로 유명한 비빔냉면은 저렴한 가격으로도 유명합니다. 매운 것을 좋아하는 사람이라면 한 번 도전해 보세요. 식탁 위에 놓여 있는 설탕을 약간 넣어서 먹는 것이 맛의 비결이라면 비결. 식초와 겨자를 넉넉히 넣은 물냉면은 새콤함과 단맛이 어우러져 시원합니다.', 37.509653, 127.079773, '', '지하철 2/9호선 종합운동장역 9번 출구, 433m', '비빔냉면, 물냉면', '', ' https://www.instagram.com/haejoo1983/', '음식점', '', '월요일~토요일 11:30 ~ 21:00', '02-424-7192', '매주 일요일, 명절 당일 휴무'),
	(124, '벽제갈비', '05639  서울 송파구 양재대로71길 1-4 (벽제갈비)', 'images/벽제갈비_124.jpg', '갈비 맛이 서울에서 최고라고 정평이 나 있는 곳. 특등급 한우만을 쓴 양질의 고기를 4일에서 7일간 숙성시켜서 사용.\n\n갈비 맛이 서울에서 최고라고 정평이 나 있는 곳. 특등급 한우만을 쓴 양질의 고기를 4일에서 7일간 숙성시켜서 사용합니다. 일곱 가지 재료로 만든 칠미 소금과 간장, 물엿과 향신료 등을 넣은 벽제 소스가 맛의 비결입니다. 가격대는 아주 높은 편입니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.509982, 127.126213, '', '지하철 5호선 방이역 4번 출구, 176m', '설화 꽃등심, 특상한우 생등심, 봉피양냉면', '', ' https://www.bjgalbi.com/index', '음식점', '', '매일 11:30 ~ 22:00', '02-415-5522', '연중무휴'),
	(126, '태극당', '04617  서울 중구 동호로24길 7', 'images/태극당_126.jpg', '광복을 꿈꾸던 청년이 민족의 이상을 담아 만든 빵집\n\n1946 년부터 세대를 아우르는 서울 대표 빵집으로 자리매김하고 있는 곳입니다. 광복을 꿈꾸던 창업주가 민족의 이상을 담기 위해 무궁화 로고와 태극당이라는 이름을 지었어요. 유서 깊은 제과 명가로 수많은 종류의 빵을 개발하며 그 명성을 이어옵니다. 프랜차이즈가 되지 않길 바라는 창업주의 정신을 그대로 이어받아 맛의 변화가 없도록 신경을 써요. 어린아이부터 할머니의 입맛 모두를 사로잡는 빵들이 모여있는 곳입니다.', 37.561665, 127.005912, '', '지하철 3호선 동대입구역 2번 출구, 24m', '', '매일', ' http://www.taegeukdang.com/', '카페, 디저트', '', '08:00~21:00', '02-2279-3152', '없음'),
	(127, '성천막국수', '02614  서울 동대문구 답십리로48나길 2 (답십리동)', 'images/성천막국수_127.jpg', '동치미 국물만을 이용한 깔끔한 막국수를 내는 집. 메밀의 함량도 높은 막국수.\n\n동치미 국물만을 이용한 깔끔한 막국수를 내는 집입니다. 메밀의 함량도 높은 편이어서 수준 높은 막국수를 접할 수 있습니다. 막국수, 제육, 동치미 무를 세트로 묶은 정식이 인기메뉴. 오돌뼈가 박힌 제육을 양념한 동치미 무로 싸서 먹는 맛이 좋습니다.', 37.569894, 127.057810, '1만원대', '지하철 4호선 답십리역 4번 출구, 764m', '물막국수, 비빔막국수, 제육', '월요일~토요일', '', '음식점', '', '월요일 - 금요일 11:30 - 15:00 / 17:00 - 21:00 , 토요일 11:30 - 17:00', '0507-1329-5529', '매주 일요일, 명절 휴무'),
	(128, '홍능갈비집', '02470  서울 동대문구 제기로 85 (홍능갈비집)', 'images/홍능갈비집_128.jpg', '홍릉 일대에서 유명했던 30년 관록의 갈비구이. 양념 소갈비는 20여 가지의 각종 재료로 양념. 갈비에서 나온 뼈와 사골 등을 고아 만든 냉면 육수.\n\n홍릉 일대에서 유명했던 30년 관록의 갈비구이는 부드럽고 맛이 좋습니다. 양념 소갈비는 20여 가지의 각종 재료로 양념합니다. 갈비에서 나온 뼈와 사골 등을 고아 만든 냉면 육수도 좋습니다.', 37.586843, 127.042583, '', '지하철 6호선 고려대역 4번 출구, 742m', '한우생갈비, 양념갈비, 생갈비, 불고기', '', '', '음식점', '', '매일 11:30~21:30', '02-966-0420', '명절 당일 휴무'),
	(129, '영춘옥', '03139  서울 종로구 돈화문로5가길 13 (돈의동)', 'images/영춘옥_129.jpg', '소꼬리찜, 곰탕, 해장국이 유명한 집. 해방 직후 종로통 골목에서 시작함\n\n소꼬리찜, 곰탕, 해장국이 유명한 집. 해방 직후 종로통 골목에서 시작한 것이 오늘에까지 이르고 있습니다. 오후 3시부터 판매하는 따귀는 해장국 육수를 우려낸 뼈다귀를 뚝배기에 수북이 담아 주는 것으로, 하루에 40그릇 정도가 전부이기 때문에 일찍 소진됩니다.', 37.571359, 126.991528, '2만원대', '지하철 1/ 3/ 5호선 종로3가역 2-1번 출구, 100m', '꼬리곰탕, 곰탕, 해장국, 편육', '매일', '', '음식점', '', '24시간 영업', '02-765-4237', '명절 휴무'),
	(130, '고려삼계탕', '04516  서울 중구 서소문로11길 1 (서소문동)', 'images/고려삼계탕_130.jpg', '대한민국 최초의 삼계탕 전문점\n\n고려삼계탕은 1950년대 한국전쟁 직후 이상림 사장이 개업한 삼계탕 전문점으로, 오랜 전통과 노하우를 축적하며 특별한 음식으로 거듭났습니다. 7주간 키운 수평아리를 조리해 겉은 쫀득하고 속은 부드러운 식감을 제공하며, 진하고 깔끔한 국물로 깊은 맛을 냅니다. 또한 매장이 넓고 쾌적하여 편한 분위기에서 건강한 보양식을 경험할 수 있습니다. 2020년 미쉐린 가이드에 선정되었습니다.', 37.562999, 126.972912, '2만원대', '지하철1 / 2호선 시청역 10번 출구, 100m', '삼계탕, 산삼삼계탕, 전복삼계탕, 오골계탕', '', ' http://www.krsamgyetang.com', '음식점', '', '평일 10:30~21:00, 주말 10:30~20:30', '02-752-9376', '명절 당일'),
	(131, '도원', '04525  서울 중구 소공로 119 (서울프라자호텔)  더플라자호텔 3층', 'images/도원_131.jpg', '30여 년 역사의 호텔 중식당으로, 재벌 총수, 정치인들이 자주 찾는 곳으로도 유명.\n\n30여 년 역사의 호텔 중식당으로, 재벌 총수, 정치인들이 자주 찾는 곳으로도 유명하였던 곳입니다. 호텔 전체의 레노베이션을 거쳐 새로운 모습으로 바뀌면서 음식 스타일도 한층 트렌디하게 업그레이드 되었습니다. 분위기, 맛, 서비스 모두 나무랄 데가 없이 훌륭합니다.', 37.564664, 126.978090, '', '지하철 1/2호선 시청역 6번 출구, 87m', '약식동원, 츄셩뤄 수석 셰프, 특선', '', ' https://www.hoteltheplaza.com/kr/dining/taoyuen.jsp', '음식점', '', '11:30~14:30, 18:00~21:30', '02-310-7300', '연중무휴'),
	(132, '[백년가게] 삼원가든', '06023  서울 강남구 언주로 835 (삼원가든)', 'images/[백년가게]_삼원가든_132.jpg', '현지 레스토랑계의 장인으로, 1976년 처음 문을 열어 서울에서 가장 큰 식당으로서뿐만 아니라 질 높은 정통 한식 요리를 제공\n\n최대규모의 전통 한식 전문점\n\n30년이 넘는 전통을 자랑하는 대표적인 갈빗집. 신선하고 질 좋은 갈비로 훌륭한 요리를 선보입니다. 한국을 방문한 국빈들이 저녁 만찬을 즐기는 곳입니다. 한옥 스타일의 분위기도 좋고, 프라이빗 룸이 있어 모임에도 적합합니다.\n\n미쉐린 가이드 서울 2025에 선정되었습니다', 37.524930, 127.032530, '', '지하철 3호선 압구정역 3번 출구, 521m', '불고기 Bulgogi 勁肉/ 燒肉\n양념갈비 Grilled seasoned beef ribs 調味排骨/ 味付けカルビ\n생등심 Grilled fresh beef sirloin 新鮮里脊/ 生ロス', '', ' https://sgdinehill.co.kr/samwon-garden/', '음식점', '', '평일 11:30~14:30, 17:30~21:30\n주말 11:00~14:30, 17:00~21:00', '02-548-3030', '연중무휴'),
	(133, '한과채', '03146  서울 종로구 인사동10길 13', 'images/한과채_133.jpg', '한과채는 2004년 개업한 완전 채식식당.(Vegan) 반찬가지수는 한식 25~30가지 조미료 전혀 쓰지 않으며, 식재료를 원산지에서 공급.\n\n한과채는 2004년 개업한 완전 채식식당입니다.(Vegan) 반찬가지수는 한식 25~30가지 조미료 전혀 쓰지 않으며, 식재료를 원산지에서 공급받고 있습니다.', 37.574371, 126.985973, '', '지하철 3호선 안국역 6번 출구, 414m', '채식뷔페', '월요일~토요일', '', '음식점', '', '11:30~14:30', '02-720-2802', '매주 일요일'),
	(134, '안집', '03059  서울 종로구 북촌로 6-6', 'images/안집_134.jpg', '안방에서 식사하듯이 안락한 분위기에서 식사할 수 있는 곳. 각종 한식 코스 요리와 고기류, 안주류 . 된장찌개, 계란찜, 각종 나물, 육류, 해산물 등 16~18가지의 반찬.\n\n안방에서 식사하듯이 안락한 분위기에서 식사할 수 있는 곳입니다. 각종 한식 코스 요리와 고기류, 안주류 등을 맛볼 수 있다. 된장찌개, 계란찜, 각종 나물, 육류, 해산물 등 16~18가지의 반찬이 푸짐합니다.', 37.579939, 126.985032, '1만원대', '지하철 3호선 안국역 2번 출구, 56m', '점심정식, 저녁정식, 청국장정식, 된장찌개정식', '', '', '음식점', '', '10:30 ~ 21:00', '02-3672-7070', '매주 일요일, 명절 휴무'),
	(135, '서초 남순남순대국', '06258  서울 강남구 도곡로4길 12 (도곡동, 지엠빌딩)', 'images/서초_남순남순대국_135.jpg', '국물에서 노린내가 나지 않아 평소 순댓국을 좋아하지 않는 사람도 거부감 없음. 순댓국 안의 돼지고기 양 푸짐.\n\n국물에서 노린내가 나지 않아 평소 순댓국을 좋아하지 않는 사람도 거부감을 느끼지 않고 먹을 만합니다. 순댓국 안에 들어 있는 돼지고기의 양이 꽤 푸짐합니다. 새우젓, 다진 양념, 들깻가루, 후춧가루 등을 곁들여 먹으면 고소하면서도 얼큰한 순댓국이 됩니다.', 37.489190, 127.033426, '1만원대', '지하철 3호선/신분당선 양재역 3번 출구, 638m', '일반순대국, 일반순대, 토종순대국, 삼색순대', '월요일~토요일', '', '음식점', '', '월요일~토요일 10:00~21:30', '0507-1419-3227', '매주 일요일, 명절 휴무'),
	(136, '송파나루', '05610  서울 송파구 석촌호수로 234 (석촌동, 라품미빌딩)', 'images/송파나루_136.jpg', '갈치구이, 고등어구이, 가자미조림 등 생선 요리를 전문점. 곰치해장국 같이 서울에서 맛보기 어려운 생선도 취급, 은대구찜이 별미.\n\n갈치구이, 고등어구이, 가자미조림 등 생선 요리를 전문으로 하고 있습니다. 곰치해장국같이 서울에서 맛보기 어려운 생선도 취급하고 있으며 특히 은대구찜이 별미입니다. 해물파전이나 굴전 등을 곁들이면 더욱 좋습니다.', 37.507645, 127.102735, '', '지하철 8/9호선 석촌역 8번 출구, 552m', '곰치해장국, 갈치조림, 병어조림, 은대구조림', '', '', '음식점', '', '매일 10:00 ~ 22:00', '02-413-7080', '연중무휴'),
	(137, '오장동흥남집', '04559  서울 중구 마른내로 114 (흥남집)', 'images/오장동흥남집_137.jpg', '오장동 냉면집 중 가장 낫다는 평가를 받고 있으며 이북 출신들이 가장 많이 찾는 함흥식 냉면집.\n\n오장동 냉면집 중 가장 낫다는 평가를 받고 있으며 이북 출신들이 가장 많이 찾는 함흥식 냉면집입니다. 비빔냉면에는 소고기가 들어가고 회냉면에는 홍어회가 들어가는데, 섞음냉면에는 말 그대로 소고기와 홍어회가 함께 들어갑니다. 고구마 전분을 사용한 면발에 홍어회의 새콤한 맛이 독특합니다.', 37.564341, 127.000542, '1만원대', '지하철 2/5호선 을지로4가역 8번 출구, 411m', '회 비빔냉면, 고기비빔냉면, 섞임냉면, 물냉면', '목요일 ~ 화요일', ' http://www.xn--q20bn4dn1w9mbrxe3z4a.com/', '음식점', '', '11:00~20:30', '02-2266-0735', '수요일, 명절 휴무'),
	(138, '백년옥', '06719  서울 서초구 남부순환로 2407', 'images/백년옥_138.jpg', '두부로 만든 음식 전문으로 유명. 콩비지백반, 자연식순두부, 야채두부비빔밥.\n\n두부로 만든 음식 전문으로 유명합니다. 콩비지백반, 자연식순두부, 야채두부비빔밥 등이 대표 메뉴입니다. 자연식순두부백반은 조미를 하지 않은 순두부 덩어리가 따뜻한 물 속에 담겨져 나오고 양념장을 곁들여 먹습니다. 뚝배기맛순두부는 얼큰한 순두부찌개입니다. 여름에는 콩국수도 인기가 높습니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.481150, 127.013776, '', '지하철 3호선 남부터미널역 5번 출구, 581m', '자연식 순두부, 뚝배기 순두부, 팥동지죽, 팥칼국수', '', '', '음식점', '', '매일 11:00~21:00', '02-523-2860', '명절 휴무'),
	(139, '송림가', '08275  서울 구로구 경인로 398 (송림가든)', 'images/송림가_139.jpg', '시골 고향 같은 정겨움을 맛볼 수 있는 한정식과 갈비찜, 양념 갈비 등 최상의 고기.\n\n​정성이 가득한 한정식과 갈비\n\n시골 고향 같은 정겨움을 맛볼 수 있는 한정식과 갈비찜, 양념 갈비 등 최상의 고기를 맛볼 수 있습니다. 모든 요리에 조미료대신 발효 효소를 첨가하여 깔끔하고 깊은 맛을 느낄 수 있는데 푸짐한 정식메뉴를 주문하면 김치 종류만도 대여섯 가지가 나옵니다.', 37.496998, 126.864349, '', '지하철 1호선 구일역 2번 출구, 643m', '수라한정식, 숯불구이양념갈비, 한우꽃등심, 돼지갈비', '', ' http://www.songlimga.com', '음식점', '', '매일 11:30~15:00 / 17:00~21:30', '0507-1492-6020', '연중무휴'),
	(140, '뎁짜이', '03079  서울 종로구 대학로11길 41-4 (명륜4가)', 'images/뎁짜이_140.jpg', '신선한 생면과 진한 육수를 사용한 생면쌀국수를 하노이의 현지 조리방식으로 요리.\n\n신선한 생면과 진한 육수를 사용한 생면 쌀국수를 즐길 수 있으며, 베트남 하노이의 현지 조리방식으로 요리합니다. 하노이에서 맛볼 수 있는 다양한 요리를 뎁짜이에서 즐길 수 있습니다.\n\n※  뎁짜이: 베트남어로 잘생긴 남자라는 의미', 37.582392, 126.999218, '1만원대', '지하철 4호선 혜화역 4번 출구, 266m', '하노이쌀국수, 직화분짜, 반미 샌드위치', '', ' https://www.instagram.com/dep_trai_korea/', '음식점', '', '매일 11:00 - 22:00', '0507-1421-1915', '연중무휴'),
	(141, '두레미담(서울대점)', '08826  서울특별시 관악구 관악로 1 (신림동)', 'images/두레미담(서울대점)_141.jpg', '양껏 먹을 수 있는 자율 배식의 매력\n\n양껏 먹을 수 있는 자율 배식과 주문식 식사를 즐길수 있는 서울대 구내 식당', 37.464340, 126.954873, '', '지하철 2호선 낙성대 4번 출구, 02번 마을버스 승차 후 공동기기원 하차, 600m', '한식당', '월화수목금토일', '', '음식점', '', '11:00 ~ 14:00 / 17:00 ~ 19:00', '02-880-9358', '연중 무휴'),
	(142, '갈비명가 이상(본점)', '02807  서울 성북구 정릉로 364', 'images/갈비명가_이상(본점)_142.jpg', '갈비 전문점으로, 최고 품질이 인증된 최상급 갈비만을 엄선하여 변함없는 최고의 고기 맛.\n\n갈비가 생각날 땐 갈비명가 이상\n\n갈비 전문점으로, 최고 품질이 인증된 최상급 갈비만을 엄선하여 변함없는 최고의 고기 맛을 지키고 있습니다.', 37.601758, 127.023222, '', '지하철 4호선 길음역 2번 출구, 199m', '이상갈비, 왕본구이, 전복갈비탕, 갈비탕', '', ' http://esang.co.kr/', '음식점', '', '매일 11:00~22:00', '0507-1449-8701', '연중 무휴'),
	(143, '마포진짜원조최대포', '04213  서울 마포구 만리재로1길 1-2', 'images/마포진짜원조최대포_143.jpg', '60년 전통의 돼지고기집. 달콤한 돼지갈비나 담백한 소금구이로 시작해서 쫄깃쫄깃한 돼지껍데기로 마무리. 맥주보다는 소주가 제격인, 서민적인 분위기의 음식점.\n\n60년 전통의 돼지고기집. 달콤한 돼지갈비나 담백한 소금구이로 시작해서 쫄깃쫄깃한 돼지껍데기로 마무리하는 이 집만의 먹는 순서가 있습니다. 맥주보다는 소주가 제격인, 서민적인 분위기의 음식점입니다.', 37.544479, 126.952138, '1만원대', '지하철 5호선/6호선/경의중앙선/공항철도 공덕역 5번 출구, 66m', '돼지갈비 소금구이 갈매기살 껍데기', '월요일~일요일', ' https://www.instagram.com/choidaepo_official/#', '음식점', '', '11:00~22:50', '0507-1333-9293', '연중무휴'),
	(144, '카페 아르무아', '05017  서울 광진구 동일로22길 117-27 (화양동)', 'images/카페_아르무아_144.jpg', '슈퍼주니어의 예성이 ‘마우스래빗’에 이어 오픈한 카페\n\n슈퍼주니어의 예성이 ‘마우스래빗’에 이어 건대에 카페 ‘아르무아’를 오픈했습니다. 지난 8월에 오픈했지만 벌써 입소문이 자자해요. 카페 안으로 들어가면 앤틱 소품과 가구로 채워진 방이 나오지만 당황하지 마세요. 옷장 문을 열어야 진짜 카페로 들어설 수 있습니다. 오래된 전등, 예스러운 테이블과 의자, 낡은 오르간 등이 고풍스럽고 레트로한 분위기를 연출해 마치 나니아연대기 속 세상으로 들어온 듯합니다. 귀여운 모양의 치즈케이크 및 오리지널 우유와 각종 얼그레이티를 뜨겁게 우려낸 뒤 하루를 더 숙성시키는 24h 밀크티가 인기 메뉴입니다.', 37.541767, 127.070923, '', '지하철 2/7호선 건대입구역 2번 출구, 211m', '24h 밀크티, 생긴 것도 치즈케이크', '', ' http://www.instagram.com/cafe_armoire', '카페, 디저트', '', '매일 12:00 - 23:00', '02-463-9981', ''),
	(145, '노들강', '06120  서울 강남구 강남대로114길 21', 'images/노들강_145.jpg', '민어로 유명한 집으로, 민어를 적당히 숙성시켜 쫄깃한 맛. 민어회를 시키면 껍질과 부레, 뱃살이 함께 나옴 . 민어 외에도 홍어와 돼지고기, 신김치를 곁들인 삼합에다 동동주를 함께 먹는 홍탁삼합.\n\n민어로 유명한 집으로, 민어를 적당히 숙성시켜 쫄깃한 맛이 살아 있습니다. 민어회를 시키면 껍질과 부레, 뱃살이 함께 나옵니다. 민어탕은 민어살에 머리 부위와 곤이 등을 넣고 끓입니다. 민어 외에도 홍어와 돼지고기, 신김치를 곁들인 삼합에다 동동주를 함께 먹는 홍탁삼합도 있습니다.', 37.506177, 127.025965, '', '지하철 9호선/ 신분당선 신논현역 3번 출구, 274m', '민어탕 홍어탕 홍어삼합', '매일', ' http://www.노들강.com', '음식점', '', '11:30 ~ 22:00', '02-517-6044', '매주 일요일, 명절, 현충일'),
	(146, '레오니다스초콜릿카페', '04537  서울특별시 중구 명동길 62 (명동1가)', 'images/레오니다스초콜릿카페_146.jpg', '벨기에의 유명한 초콜릿 명가 레오니다스에서 오픈한 초콜릿 카페.\n\n벨기에의 유명한 초콜릿 명가 레오니다스에서 오픈한 초콜릿 카페. 천연 카카오 버터를 사용한 고급스러운 초콜릿을 맛볼 수 있습니다. 음료도 저렴한 편이예요.', 37.563855, 126.985817, '', '지하철 4호선 명동역 8번 출구, 386m', '초콜릿', '월요일~일요일', ' http://leonidas.kr', '카페, 디저트', '', '08:00~21:00', '02-318-1312', '연중무휴'),
	(147, '된장예술과술', '03190  서울 종로구 삼일대로15길 20 (관철동)', 'images/된장예술과술_147.jpg', '큰 대접에 나오는 구수한 된장비빔밥이 대표 메뉴로, 구수한 된장찌개와 부추를 듬뿍 넣어 비벼 먹는 된장비빔밥과 간장게장 밥.\n\n큰 대접에 나오는 구수한 된장비빔밥이 대표 메뉴로, 구수한 된장찌개와 부추를 듬뿍 넣어 비벼 먹는 된장비빔밥 맛이 좋습니다. 두 가지 식사 메뉴가 있는데, 나머지 하나는 간장게장 밥입니다.', 37.568921, 126.986395, '1만원대', '지하철 1호선 종각역 4번 출구, 352m', '된장정식, 순녹두빈대떡, 간장게장정식, 양념게장정식', '', '', '음식점', '', '월요일~금요일 11:00~15:00, 16:30~22:00', '02-733-4516', ''),
	(148, '봉래헌(메이필드호텔)', '07506  서울 강서구 방화대로 94 (메이필드호텔)', 'images/봉래헌(메이필드호텔)_148.jpg', '봉래헌은 그 외관만큼이나 맛깔스럽고 격조 있는 궁중 한정식 전문점.\n\n봉래헌은 그 외관만큼이나 맛깔스럽고 격조 있는 궁중 한정식 전문점입니다. 모든 음식에 천연재료를 사용함으로써 깔끔하고 정갈한 맛과 재료의 묘미가 그대로 살아 있는 궁중한정식으로 내·외국인 손님 접대에 많이 찾는 곳입니다.', 37.547940, 126.818341, '', '지하철 5/ 9호선 김포공항역 국내선 방면 8번 출구 Gate 7번 정류장- 호텔 무료 셔틀버스 환승', '', '화~일요일', ' http://www.mayfield.co.kr', '음식점', '', '11:30~14:30, 18:00~21:30', '0507-1420-9020', '월요일, 명절'),
	(149, '강강술래(신림본동점)', '08780  서울특별시 관악구 남부순환로 1660 (신림동)', 'images/강강술래(신림본동점)_149.jpg', '아담한 황토담과 원목 그대로의 모습을 살린 서까래, 시골의 넉넉한 풍경을 살린 인테리어가 정감있는 강강술래 신림점.\n\n따뜻한 마음과 풍류가 어우러지는 식문화 공간\n아담한 황토담과 원목 그대로의 모습을 살린 서까래, 시골의 넉넉한 풍경을 살린 인테리어가 정감있는 강강술래 신림점입니다. 인기 메뉴 한우 술래양념구이는 질좋은 국내산 한우만을 사용하며 술래갈비 양념의 그 맛을 그대로 느낄 수 있습니다.', 37.484572, 126.935033, '', '지하철 2호선/ 신림선 신림역 1번 출구, 413m', '한우 모둠구이 돼지 양념구이 술래정식', '매일', ' http://www.sullai.com', '음식점', '', '11:00 ~ 22:00', '02-886-9233', '연중무휴'),
	(150, '광장동가온', '04969  서울특별시 광진구 아차산로78길 75, 현대골든텔 106호 (광장동)', 'images/광장동가온_150.gif', '가온은 곰국시, 손만두 전문점으로 2008년 4월 오픈한 이래 맛집으로 입소문이 자자. 식당 바로 앞에 자리한 한강의 아름다운 풍경이 펼쳐지는 한식 레스토랑.\n\n가온은 곰국시, 손만두 전문점으로 2008년 4월 오픈한 이래 맛집으로 입소문이 자자합니다. 식당 바로 앞에 자리한 한강의 아름다운 풍경이 펼쳐지는 한식 레스토랑입니다.', 37.551597, 127.110985, '', '지하철 5호선 광나루역 2번 출구, 1.1km', '국수', '월요일~일요일', ' https://www.instagram.com/narugaon_food/', '음식점', '', '11:20 ~ 22:30', '0507-1363-7100', '8월1일, 명절 휴무'),
	(151, '봉피양(방이점)', '05639  서울 송파구 양재대로71길 1-4 (벽제갈비)', 'images/봉피양(방이점)_151.jpg', '돼지갈비로 유명한 봉피양의 방이동 분점. 소갈비로 유명한 벽제갈비에서 운영하는 브랜드. 돼지갈비치고는 가격대가 높은 편이지만 맛은 보장.\n\n돼지갈비로 유명한 봉피양의 방이동 분점. 소갈비로 유명한 벽제갈비에서 운영하는 브랜드이다. 돼지갈비치고는 가격대가 높은 편이지만 그만큼 맛도 보장합니다. 정통 평양냉면에 가깝다는 평을 받는 냉면도 인기가 좋습니다. 갈비와 냉면 또는 된장찌개가 나오는 점심세트가 실속 있습니다. 방이점을 제외한 봉피양 분점들에서는 냉면 맛이 떨어진다는 평도 있습니다. 2020년 미쉐린 가이드에 선정되었습니다.', 37.509982, 127.126213, '', '지하철 5호선 방이역 4번 출구, 197m', '돼지本갈비, 한우떡갈비, 평양냉면', '', ' https://www.bjgalbi.com/', '음식점', '', '매일 11:30~22:00', '02-415-5527', '연중무휴'),
	(152, '라메흐꺄도', '07280  서울 영등포구 선유로17길 24 (문래동6가, 신일아르디세)', 'images/라메흐꺄도_152.jpg', '가수 이하이의 부모님이 운영하는 음식점. 제철 꽃게를 비법 간장으로 절인 간장게장이 대표메뉴.\n\n‘바다의 선물’이라는 뜻의 한식 해산물 전문점. 외부에 장식된 현수막이 말해주듯, 가수 이하이의 부모님이 운영하는 음식점입니다. 인천에서 직송된 제철 꽃게를 비법 간장으로 절인 간장게장이 대표메뉴입니다. 간장게장 정식은 간장게장과 함께 소라, 전복, 미역과 다시마 등 싱싱하고 알 굵은 해산물을 이용한 반찬이 여럿 곁들여 나옵니다. 바비, 이수현 등 이하이와 한솥밥을 먹었던 YG엔터테인먼트 소속 연예인들이 남긴 메시지를 보는 재미도 쏠쏠합니다. 이하이가 눈감고도 엄마가 만든 것을 구분할 수 있을 만큼 좋아한다는 게장은 택배 주문도 가능합니다.', 37.521127, 126.887036, '', '지하철 5호선 양평역 2번 출구, 594m', '간장게장, 양념게장, 간장새우장', '', '', '음식점', '', '11:00~21:20 (브레이크 타임 15:30~16:30)', '0507-1379-5989', '매달 1, 3번째 월요일, 명절 휴무'),
	(153, '뜨락', '06075  서울 강남구 영동대로142길 13-3 (청담동)', 'images/뜨락_153.jpg', '청담동 골목길에 위치한 고깃집으로 참숯을 사용하여 고기를 굽는 곳.\n\n청담동 골목길에 위치한 고깃집으로 참숯을 사용하여 고기를 굽는 곳입니다. 대추, 감, 포도, 매실 나무 등이 어우러져 있는 정원에서 구워 먹는 고기 맛이 일품입니다.', 37.524421, 127.055586, '', '지하철 7호선 청담역 14번 출구, 503m', '안심, 등심, 안창살, 살치살', '매일', ' https://www.instagram.com/tteurak_jk/', '음식점', '', '월~토 11:30~23:00, 일 11:30~22:00', '02-543-2987', '명절 휴무'),
	(154, '장수갈비집본가', '04535  서울 중구 명동2길 54-1 (충무로1가)', 'images/장수갈비집본가_154.jpg', '숯불 맛이 느껴지는 명동의 양념 소갈비집\n\n장수갈비집본가는 1968년에 개업해 한국 갈비 문화에 혁신을 가져온 식당으로, 일본 여행 중 발견한 달콤한 양념에 영감을 받았고, 이를 기반으로 개발한 갈비 요리를 손님에게 선보였습니다. 명동 사보이 호텔 근처에서 시작해 지푸라기로 고기를 굽는 소박한 방식으로 시작했지만, 곧 대한민국 5위 매출을 기록했으며, 고기 맛을 인정받아 인파가 몰릴 정도였습니다. 장인의 손맛으로 구워지는 부드러운 갈비와 숯불 향이 특징이며, 1인 단위로 주문할 수 있어 혼자서도 부담 없이 즐길 수 있습니다.', 37.561010, 126.983127, '', '지하철 4호선 명동역 5번 출구, 160m', '한식(장수갈비,장수국밥)', '월요일~일요일', '', '음식점', '', '11:00 ~ 22:00 (라스트오더 21:15)', '02-775-9292', '명절 휴무'),
	(155, '하동관', '04538  서울 중구 명동9길 12 (명동1가)', 'images/하동관_155.jpg', '오랜 세월의 내공이 담겨 담백하고 깊은 곰탕 맛\n\n하동관은 1939년 수하동에서 개업해 3대째 이어져 온 곰탕 전문점으로, 창업주의 철학을 지켜 저녁 운영과 배달을 하지 않으며 준비된 음식이 모두 팔리면 문을 닫는 원칙을 고수하고 있습니다. 명동으로 이전한 이후에도 좋은 품질의 소고기를 사용해 오랜 시간 끓여 담백하고 깔끔한 서울식 곰탕을 제공하며, 곰탕과 수육 단 두 가지 메뉴만을 고집하고 있습니다. 전통 놋그릇에 음식을 담아내는 방식 또한 유지하며 한결같은 맛과 전통을 이어가고 있습니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.564434, 126.985031, '', '지하철 2호선 을지로입구역 4번 출구, 276m', '곰탕, 수육', '', ' http://www.hadongkwan.co.kr/', '음식점', '', '매일 07:00~16:00', '02-776-5656', '일요일, 명절 당일·다음날 휴무'),
	(156, '만복림', '04637  서울 중구 후암로 98 (남대문로5가, LG서울역빌딩)', 'images/만복림_156.jpg', '우리 입맛에 맞는 정통 중국 요리를 맛볼 수 있는 곳.\n\n우리 입맛에 맞는 정통 중국 요리를 맛볼 수 있는 곳으로, 얼마 전에 대우센터 빌딩에서 남산 STX 남산타워 아케이드로 이전하였습니다. 이전하여서도 변함없는 분위기와 맛을 유지하고 있습니다.', 37.553921, 126.974900, '2만원대', '지하철 1호선/ 4호선/ 공항철도/ 경의중앙선/GTX-A 서울역 10번 출구, 98m', '팔진초면, 청경채소고기야채볶음, 닭고기캐슈넛, 새우칠리소스', '', '', '음식점', '', '매일 11:30 ~ 22:00', '02-753-5693', '명절 휴무'),
	(157, '덕원꼬리곰탕방치탕', '07254  서울특별시 영등포구 버드나루로6길 6 (영등포동2가)', 'images/덕원꼬리곰탕방치탕_157.jpg', '방치탕(소 엉덩이뼈), 중토막(엉덩이뼈와 꼬리 사이) 등 소의 특수부위로 만든 탕. 깔끔하게 엉덩이뼈와 꼬리 토막만 넣어서 끓인 것이 특징.\n\n방치탕(소 엉덩이뼈), 중토막(엉덩이뼈와 꼬리 사이) 등 소의 특수부위로 만든 탕이 유명합니다. 깔끔하게 엉덩이뼈와 꼬리 토막만 넣어서 끓인 것이 특징입니다. 뼈에 푸짐하게 붙어 있는 살들을 뜯어 먹는 맛이 좋습니다.', 37.522294, 126.912035, '2만원대', '지하철 5호선 영등포시장역 2번 출구, 735m', '꼬리곰탕, 소머리수육, 중토막, 방치탕, 우족수육', '매일', '', '음식점', '', '평일 09:00~15:30, 17:00~21:00 / 주말 10:00~15:30, 17:00~20:00', '02-2634-8663', ''),
	(158, '동빙고', '04424  서울 용산구 이촌로 319 (이촌동, 현대아파트)', 'images/동빙고_158.jpg', '우유, 팥, 떡 등의 심플한 재료로도 최상의 맛을 내는 곳. 투박해 보이지만 굵은 팥과 깔끔한 단 맛이 금세 중독될 정도.\n\n우유, 팥, 떡 등의 심플한 재료로도 최상의 맛을 내는 곳. 투박해 보이지만 굵은 팥과 깔끔한 단 맛이 금세 중독될 정도로 맛있습니다.', 37.517963, 126.982327, '', '지하철 경의중앙선 서빙고역 1번 출구, 874m', '', '', '', '카페, 디저트', '', '매일 10:30 ~ 22:00', '02-794-7171', '연중무휴'),
	(159, '보노보노', '06178  서울 강남구 테헤란로 508 (해성2빌딩)', 'images/보노보노_159.jpg', '스시, 롤, 해산물, 철판요리, 튀김, 로스트비프 등 해산물 뷔페점.\n\n스시, 롤, 해산물, 철판요리, 튀김, 로스트비프 등을 한자리에서 즐길 수 있는 해산물 뷔페점. 비교적 고급스러운 식재료를 사용하고 있습니다.', 37.506807, 127.057975, '', '지하철 2호선 삼성역 4번 출구, 446m', '뷔페', '매일', ' http://bonobonopremium.com/', '음식점', '', '평일 11:30~15:00, 17:30~21:00 / 주말 12:00~15:00, 17:00~21:00', '0507-1472-8081', '명절 당일 휴무'),
	(160, '목란', '03703  서울 서대문구 연희로15길 21', 'images/목란_160.jpg', '블로거들 사이에서 큰 인기를 끄는 중식당으로 동파육이 유명\n\n고전적인 개념의 중국집으로, 탕수육과 짬뽕을 잘합니다. 만드는 데 오래 걸리는 동파육은 미리 예약해 놓는 것이 좋습니다. 요리는 전반적으로 두루두루 잘하는 편입니다. 블로거들 사이에서 큰 인기를 끈 곳입니다.', 37.570844, 126.927954, '', '지하철 2호선/경의중앙/공항철도 홍대입구역 5번 출구, 1.3km', '동파육, 칠리새우', '', '', '음식점', '', '화~일 11:30 ~ 15:00 / 17:00 ~ 21:20', '02-732-0054', '매주 월요일 휴무'),
	(161, '디마떼오', '03086  서울특별시 종로구 동숭길 29 (동숭동)', 'images/디마떼오_161.jpg', '전통 나폴리 피자를 맛볼 수 있는 곳\n\n전통 나폴리 피자를 맛볼 수 있는 곳으로, 개그맨 이원승 씨가 이탈리아에서 피자 만드는 법을 배워 와서 차린 곳입니다. 지금은 정통 이탈리아식 레스토랑이 흔해졌지만, 당시에는 맛보기 어려웠던 얇은 이탈리아식 피자로 인기가 좋았습니다. 선보이는 피자 종류만 해도 26가지나 되며, 같은 종류의 피자라 해도 이탈리아, 덴마크산 치즈를 따로 선택, 주문할 수 있어 그 종류는 사실 50여 가지가 넘습니다.', 37.580019, 127.003936, '', '지하철 4호선 혜화역 2번 출구, 297m', '스페셜 피자, 아로또라따 피자', '', ' https://www.dimatteo.co.kr/', '음식점', '', '평일 11:30 ~ 15:00 / 16:30 ~ 21:00\n주말 11:30 ~ 21:00', '02-747-4444', '월요일 휴무'),
	(162, '틈새라면', '04537  서울특별시 중구 명동10길 19-10 (명동2가)', 'images/틈새라면_162.jpg', '한국식 인스턴트 라면의 다양한 맛을 즐길 수 있는 곳. 주로 매운 맛 라면, 떡볶이, 김밥. 고춧가루와 계란, 떡 등을 넣은 얼큰한 국물의 빨계떡과 계란이 들어가 구수하고 부드러운 계떡이 인기.\n\n한국식 인스턴트 라면의 다양한 맛을 즐길 수 있는 곳. 주로 매운 맛을 내는 라면이 많으며 떡볶이나 김밥 등도 곁들일 수 있습니다. 고춧가루와 계란, 떡 등을 넣은 얼큰한 국물의 빨계떡과 계란이 들어가 구수하고 부드러운 계떡이 인기입니다. 아삭아삭한 열무와 살얼음이 떠있는 냉라면도 이색적입니다. 명동점은 빨계떡 메뉴만 주문가능합니다.', 37.563026, 126.985979, '1만원대', '지하철 4호선 명동역 8번 출구, 269m', '빨계떡, 계떡, 치즈빨계떡, 빨부대', '매일', ' http://www.teumsae.com', '음식점', '', '평일 10:00 ~ 20:00\n주말 11:00 ~ 20:00', '02-756-5477', '명절휴무'),
	(163, '세시셀라(도산공원점)', '06021  서울 강남구 도산대로45길 10-4  삼경빌딩 1층', 'images/세시셀라(도산공원점)_163.jpg', '도산공원 앞에 위치한 세시 셀라의 분점. 벨기에식 와플이 주 메뉴.\n\n도산공원 앞에 위치한 세시셀라의 분점입니다. 벨기에식 와플을 주메뉴로 하는 곳입니다. 유럽 지중해 풍의 인테리어가 발랄한 느낌이 들며 주말 브런치를 즐기기에도 좋습니요. 무선 인터넷 사용이 자유롭습니다.', 37.523031, 127.035791, '', '지하철 수인분당선 압구정로데오역 5번 출구, 699m', '음료, 당근케이크, 초콜릿케이크, 브런치세트', '', '', '카페, 디저트', '', '매일 11:30 - 22:00', '02-3448-7100', '명절 당일 휴무'),
	(164, '청수정', '03054  서울특별시 종로구 삼청로 91 (삼청동)', 'images/청수정_164.jpg', '조갯살 말린 것을 넣고 간장으로 간을 해 밥을 한 후 밥을 다시 참기름에 볶아낸 홍합밥. 일식 도시락 용기에 반찬 서너 가지를 깔끔하게 담아 내주는 홍합밥 도시락도 별미. 홍합밥 정식에는 10가지가 넘는 반찬. 뽈데기탕도 유명.\n\n조갯살 말린 것을 넣고 간장으로 간을 해 밥을 한 후 밥을 다시 참기름에 볶아낸 홍합밥이 이 집을 유명하게 만들었습니다. 일식 도시락 용기에 반찬 서너 가지를 깔끔하게 담아 내주는 홍합밥 도시락도 별미. 홍합밥 정식에는 10가지가 넘는 반찬이 깔립니다. 뽈데기탕도 유명합니다.', 37.583571, 126.981703, '', '지하철 3호선 안국역 1번 출구, 1km', '홍합밥정식, 홍합비빔밥, 홍합밥도시락, 불고기덮밥, 뽈데기탕', '', ' http://www.instagram.com/cheongsoojung', '음식점', '', '11:00 ~ 15:00 / 17:00 ~ 20:30', '0507-1366-8293', '공휴일 휴무'),
	(165, '남도식당', '03156  서울 종로구 종로3길 42', 'images/남도식당_165.jpg', '저렴한 가격에 푸짐하게 한 상 차려진 식사를 할 수 있는 곳. 몇십 년 전통의 고추장 양념 돼지고기 맛이 일품.\n\n저렴한 가격에 푸짐하게 한 상 차려진 식사를 할 수 있는 곳. 몇십 년 전통의 고추장 양념 돼지고기 맛이 일품입니다. 식사 시간이 되면 연탄불 석쇠에 구운 고기를 먹기 위해 찾아오는 손님들로 붐비는 곳 중 하나입니다. 한정식 외에도 혼자 온 고객들을 위해, 현미 백반이라는 상차림을 따로 마련해 두고 있습니다.', 37.571344, 126.979312, '', '지하철 5호선 광화문역 2번 출구, 253m', '연탄삼겹살, 연탄소불고기, 육회, 병어찜, 김치전골', '월요일~토요일', '', '음식점', '', '10:00 ~ 14:00 / 16:00 ~ 22:00', '02-734-0719', '매주 일요일, 명절 휴무'),
	(166, '우랑 청담점', '06013  서울 강남구 압구정로79길 79 (청담동)  JM빌딩 1층', 'images/우랑_청담점_166.jpg', '야키니쿠, 사시미 등과 이자카야 메뉴를 즐길 수 있는 곳.\n\n야키니쿠, 사시미 등과 이자카야 메뉴를 즐길 수 있는 곳. 야키니쿠를 시키면 조그만 화로가 나와 고기와 채소, 주먹밥 등을 구워 먹을 수 있습니다. 사케 한잔 곁들이기에도 좋습니다.', 37.526090, 127.053606, '', '지하철 7호선 청담역 13번 출구, 727m', '우랑나베, 대게샤브샤브, 야끼니꾸', '', '', '음식점', '', '월요일~금요일 11:30~14:00, 17:00~24:00\n토요일 17:00~23:00', '02-3445-4005', '매주 일요일'),
	(167, '양마니(청담점)', '06062  서울 강남구 도산대로56길 16', 'images/양마니(청담점)_167.jpg', '깔끔하고 쾌적한 분위기에서 곱창을 즐길 수 있는 곳. 양과 대창구이가 인기. 뉴질랜드산 소의 양과 국내산 한우의 대창을 사용.\n\n깔끔하고 쾌적한 분위기에서 곱창을 즐길 수 있는 곳으로, 양과 대창구이가 인기 있습니다. 뉴질랜드산 소의 양과 국내산 한우의 대창을 사용합니다. 우거지국에 양을 넣은 양우탕도 한번 맛볼 만합니다. 본점은 여의도에 위치해 있습니다.', 37.521909, 127.040295, '3만원대', '지하철 7호선/ 수인분당선 강남구청역 4번 출구, 635m', '특양구이, 양밥, 대창구이', '매일', '', '음식점', '', '24시간', '02-542-9263', '연중무휴'),
	(168, '목멱산방', '04629  서울 중구 퇴계로20길 71 (남산동2가)', 'images/목멱산방_168.jpg', '고풍스러운 한옥에서 정갈하게 차려지는 한식을 즐길 수 있는 곳. 메뉴는 비빔밥, 부추전, 도토리묵, 전통차.\n\n고풍스러운 한옥에서 정갈하게 차려지는 한식을 즐길 수 있는 곳입니다. 메뉴는 비빔밥, 부추전, 도토리묵, 전통차 등으로 단출한 편입니다. 이곳에서 판매하는 차는 직접 다려 만들었습니다.', 37.558115, 126.986902, '', '지하철 4호선 명동역 1번 출구, 433m', '일반한식', '월요일~일요일', ' https://mmmroom.co.kr/', '음식점', '', '11:00 ~ 20:00', '02-318-4790', '명절 휴무'),
	(169, '홈수끼 (Home Sukki)', '05638  서울 송파구 위례성대로 134 (방이동, 한스빌딩)', 'images/홈수끼_(Home_Sukki)_169.jpg', '태국의 수키와 일본의 샤부샤부를 혼합한 음식점.\n\n태국의 수키와 일본의 샤부샤부를 혼합한 음식점입니다. 코스 요리를 시키면 채소, 소고기 샤부샤부와 해물 죽을 즐길 수 있습니다. 샤부샤부를 먹은 후에는 칼국수와 죽을 끓여 먹습니다.', 37.512010, 127.126299, '2만원대', '지하철 5호선 방이역 4번 출구, 420m', '샤브샤브 코스', '연중무휴', '', '음식점', '', '매일 11:30 ~ 22:00', '0507-1404-4124', ''),
	(170, '팔선', '04605  서울 중구 동호로 249 (신라호텔)  2층', 'images/팔선_170.jpg', '광동식을 비롯하여 사천, 북경요리 등 수백 가지가 넘는 정통 중국요리.\n\n광동식을 비롯하여 사천, 북경요리 등 수백 가지가 넘는 정통 중국요리를 해낼 수 있는 곳입니다. 명성만큼이나 맛, 분위기, 서비스 좋다. 단골손님이 되면 개개인의 취향에 맞춘 요리를 제공해 주기도 합니다. 정, 재계의 유명 인사들이 많이 찾는 것으로도 유명합니다.', 37.557506, 127.007953, '', '지하철 3호선 동대입구역 5번 출구, 431m', '정 세트, 가 세트, 삼선짜장', '', ' http://www.shilla.net/seoul/dining/viewDining.do?contId=PAL#', '음식점', '', '매일 12:00 ~ 14:30 / 17:30 ~ 21:30', '02-2230-3366', '연중무휴'),
	(171, '선천집', '03146  서울특별시 종로구 인사동14길 5 (관훈동)', 'images/선천집_171.jpg', '40여 년 전통의 한정식 전문점\n\n40여 년 전통의 한정식 전문점이다. 평안도 음식을 중심으로 한정식 상차림을 내는데, 구절판과 회, 탕과 찜, 전, 꼬치 불고기와 제육 등 일품요리 10~13가지가 기본으로 나옵니다. 점심때는 한정식에 나오는 일품요리와 반찬을 간추려 내는 점심 정식이 인기가 있습니다.', 37.574957, 126.984425, '', '지하철 3호선 안국역 6번 출구, 174m', '', '월요일 - 토요일', '', '음식점', '', '11:00 ~ 21:00', '0507-1368-5674', '매주 일요일 휴무'),
	(172, '조개창고', '04715  서울 성동구 왕십리로 331 (공영빌딩)', 'images/조개창고_172.jpg', '당일 공수하는 신선한 키조개, 전복, 가리비 등 30가지의 조개류 무한리필\n\n매일 당일 공수하는 신선한 키조개, 전복, 가리비 등 30가지의 조개류를 무한리필로 먹을 수 있는 조개창고에는 20여 종의 다양한 사이드 메뉴가 있습니다. 단체 손님 전용룸을 보유하고 있어 직원 회식장소로도 적합하며, 고객이 원하는 메뉴를 직접 가져다 먹는 시스템으로 되어 있습니다. 시간제한이 없어 부담 없이 조개구이를 맛볼 수 있습니다.', 37.562636, 127.032802, '', '지하철 2/5호선/경의중앙선/수인분당선 왕십리역 11번 출구, 237m', '조개구이, 조개찜', '매일', '', '음식점', '', '평일 17:00~23:00\n주말 12:00~23:00', '010-4596-0449', '연중무휴'),
	(173, '스시 카이신', '06071  서울 강남구 도산대로100길 12 (청담동, 우리빌딩 2층)', 'images/스시_카이신_173.jpg', '일본셰프가 제공하는 고품격 일본식 전통 스시와 오마카세\n\n일본 긴자에서 접할 수 있는 작고 아담한 스타일의 고급 스시 전문점입니다. 식자재 구매부터 손질, 접객에 이르기까지 일본인 오너셰프 혼자서 전 과정을 준비, 진행하여 항상 일정한 수준과 맛을 유지할 수 있도록 소규모로 카운터 총 6석의 카운터 석만을 운영합니다. 1인부터 식사 가능하며, 소규모이므로 가능한 사전 예약을 추천합니다.', 37.523851, 127.051770, '', '지하철 7호선 청담역 11번 출구, 645m', '오마카세', '', ' https://www.facebook.com/SushiKaisin', '음식점', '예약제 운영', '매일 18:00~ 22:00 (예약 상황에 따라 오픈과 마감 시간이 상이)', '02-515-9855', '월 3회 휴무'),
	(174, '비원손칼국수', '03058  서울 종로구 창덕궁1길 9-1', 'images/비원손칼국수_174.jpg', '창경궁 부근에 있는 30년 된 칼국수 집. 한우 양지로 국물을 낸 국수가 담백. 만두전골도 별미인데 버섯과 속이 꽉 찬 만두.\n\n창경궁 부근에 있는 30년 된 칼국수 집입니다. 한우 양지로 국물을 낸 국수가 담백하고 맛있습니다. 만두전골도 별미인데 버섯과 속이 꽉 찬 만두입니다.', 37.579182, 126.988783, '1만원대', '지하철 3호선 안국역 3번 출구, 500m', '칼국수, 떡만두국, 왕만두, 만두전골', '', '', '음식점', '', '매일 11:00 ~ 21:00', '0507-1357-4849', '연중무휴'),
	(175, '감촌', '03157  서울특별시 종로구 종로 19 (종로1가)', 'images/감촌_175.jpg', '24시간 푹 고아 끓여낸 사골국물을육수로 사용하여, 다른 순두부찌개에 비해 국물이 걸쭉하고 힘이 있는 것이 특징. 인근 직장인들 뿐 아니라 외국인 단골이 굉장히 많은 곳.\n\n24시간 푹 고아 끓여낸 사골국물을육수로 사용하여, 다른 순두부찌개에 비해 국물이 걸쭉하고 힘이 있는 것이 특징입니다. 인근 직장인들 뿐 아니라 외국인 단골이 굉장히 많은 곳입니다.', 37.570844, 126.979924, '', '지하철 5호선 광화문역 4번 출구, 282m', '순두부찌개, 굴순두부, 순두부찌개특, 차돌순두부, 해물된장찌개, 버섯김치찌개', '월요일 ~ 토요일', '', '음식점', '', '09:30~22:00', '02-733-7035', '매주 일요일, 명절 휴무'),
	(176, '여수오동도', '06202  서울 강남구 삼성로71길 7', 'images/여수오동도_176.jpg', '여수식 회를 내는 집으로, 병어와 풍성한 채소를 초고추장에 무쳐 나오는 병어회가 유명. 저녁때는 식사와 술을 한꺼번에 해결. 여수 별미인 장어탕도과 여름에는 하모(갯장어).\n\n여수식 회를 내는 집으로, 병어와 풍성한 채소를 초고추장에 무쳐 나오는 병어회가 유명합니다. 저녁때는 식사와 술을 한꺼번에 해결하기에 좋습니다. 여수 별미인 장어탕도 맛볼 수 있으며, 여름에는 하모(갯장어)를 즐길 수 있습니다.', 37.502139, 127.057969, '', '지하철 2호선/ 수인분당선 선릉역 1번 출구, 1.2km', '갯장어, 병어, 전어', '', '', '음식점', '', '평일 11:00~15:00, 16:00~22:00 / 주말 11:00~22:00', '02-557-0039', '명절 당일 휴무'),
	(177, '세림', '04522  서울 중구 남대문로9길 24 (다동)', 'images/세림_177.jpg', '고기와 채소를 살짝 데쳐 먹은 후 국수를 끓여 먹는 국수전골이 유명한 집\n\n국수전골이 유명한 집. 고기와 채소를 살짝 데쳐 먹은 후 국수를 끓여 먹는데, 면은 쑥국수와 콩국수 중에서 선택할 수 있습니다. 국수를 먹고 나서 양이 부족하면 죽을 더 끓여 먹습니다.', 37.567141, 126.981133, '2만원대', '지하철 2호선 을지로입구역 1-1번 출구, 329m', '국수전골(1만5천원), 곱창전골 (1만 5천원)', '월요일 ~ 토요일', '', '음식점', '', '평일 10:00~15:00, 17:00~22:00 / 토요일 11:00~20:00', '02-319-4603', '매주 일요일, 명절 휴무'),
	(178, '내자땅콩', '03041  서울 종로구 사직로 111 (내자동)', 'images/내자땅콩_178.jpg', '매일 눈 깜짝할 새 완판돼 버리는 한정 수량 땅콩 전병\n\n내자땅콩은 지금 대표의 아버지께서 50 년 전인 스물여섯 살 때 시작한 가게로 , 땅콩전병을 만들던 친척에게 기술을 배워 가게를 열었습니다 . 반세기 넘게 전병을 구워내는 내자땅콩에 들어서면 입구 맞은편에 땅콩전병을 만드는 기계가 보입니다 . 연탄불에서 가스불로 바뀐 것 외에는 옛날 방식을 그대로 따르고 있어요. 두 번 구워진 땅콩이 큼지막하게 박혀 있어 씹을수록 고소해요. 하루에 약 130 봉지만 만드는 땅콩전병이 이곳의 대표 품목입니다 . 파래전병과 생강전병도 인기가 좋습니다 .', 37.576264, 126.971075, '', '지하철 3호선 경복궁역 1번 출구, 103m', '', '월요일~토요일', '', '카페, 디저트', '13:00~14:00 브레이크타임', '11:00 ~ 16:00 (소진시 영업 종료/브레이크타임 13:00 ~ 14:00)', '02-730-7239', '일요일'),
	(179, '인사동 항아리수제비', '03148  서울특별시 종로구 인사동8길 14-1 (관훈동)', 'images/인사동_항아리수제비_179.jpg', '항아리에 담겨 나오는 수제비 전문점. 굴이 들어간 얼큰한 수제비와 해물파전. 단골들은 개인 항아리를 갖고 있어 벽에 진열. 실내 분위기는 토속적.\n\n항아리에 담겨 있는 수제비 전문점으로 굴이 들어간 얼큰한 수제비와 해물파전이 유명합니다. 단골들의 개인 항아리가 벽에 진열되어 있는 걸 볼 수 있고 실내에서는 상당히 토속적인 분위기를 느낄 수 있습니다.', 37.574143, 126.986056, '1만원대', '지하철 3호선 안국역 5번 출구, 364m', '항아리수제비, 해물파전, 골뱅이', '', '', '음식점', '', '11:30~15:30, 17:00~20:50', '02-735-3361', '명절 휴무'),
	(180, '품서울', '06084  서울 강남구 삼성로126길 6 (삼성동) 6층', 'images/품서울_180.jpg', '조선시대의 양반음식을 현대적으로 재해석해서 선보이는 한정식집. 최상의 식재료를 선택해서 천연양념 사용. 제철의 식재료를 사용하기 때문에 계절에 따라 메뉴가 상이. 채끝등심숯불구이가 유명하고, 반드시 사전 예약.\n\n조선시대의 양반음식을 현대적으로 재해석해서 선보이는 한정식집. 최상의 식재료를 선택해서 천연양념만으로 맛을 냅니다. 제철의 식재료를 사용하기 때문에 계절에 따라 메뉴가 다릅니다. 채끝등심숯불구이가 유명하고, 반드시 사전 예약해야 합니다.', 37.517540, 127.051670, '', '지하철 7호선 청담역 6번 출구, 165m', '', '월요일 ~ 토요일', '', '음식점', '', '12:00 - 22:00', '02-777-9007', '매주 일요일 휴무'),
	(181, '페르시안궁전', '03074  서울특별시 종로구 성균관로6길 9 (명륜2가)', 'images/페르시안궁전_181.jpg', '이란식 매운 커리 전문점. 현지인이 직접 조리하는 매운 커리.\n\n이란식 매운 커리 전문점. 현지인이 직접 조리하는 매운 커리를 맛볼 수 있습니다. 양념에 사흘 동안 재어 놓은 양고기 커리가 대표 메뉴. 훈제치킨으로 만든 커리 닭도 추천할 만합니다. 페르시안 정식은 여러 가지 종류의 커리 소스에 닭 여섯 조각과 페르시안 쌀로 만든 이란식 떡이 나옵다. 커리 이외에도 이란식 빵, 이란식 요구르트, 이란식 술 등등 다양한 이국적인 음식들을 맛볼 수 있습니다.', 37.584911, 126.997564, '2만원대', '지하철 4호선 혜화역 4번 출구, 530m', '통닭카레정식, 페르시안케밥, 양갈비카레, 데히지킨카레', '', ' http://www.persianpalace.com', '음식점', '', '11:00~15:00, 16:00~21:10', '02-763-6050', '연중무휴'),
	(183, '이남장(삼성동점)', '06172  서울 강남구 봉은사로108길 21', 'images/이남장(삼성동점)_183.jpg', '을지로 뒷골목에서 30년 동안 똑같은 맛을 지켜오고 있는 설렁탕 전문점의 삼성동 분점.\n\n을지로 뒷골목에서 30년 동안 똑같은 맛을 지켜오고 있는 설렁탕 전문점의 삼성동 분점입니다. 꼬박 이틀을 고아낸 고깃국물은 진한 맛이 일품이며 고기가 굵고 좋습니다. 또한 특에 나오는 우설(소혓바닥)이 아주 부드럽습니다. 직접 담그는 김치와 깍두기는 판매도 하고 있습니다.', 37.513617, 127.064441, '', '지하철 9호선 봉은사역 5번 출구, 395m', '설렁탕, 내장탕, 우족탕', '매일', '', '음식점', '', '평일 10:00~22:00\n주말 10:00~21:00', '02-569-8726', '명절 휴무'),
	(184, '유진식당', '03140  서울 종로구 종로17길 40  탑골공원 정문 반대편(북문) 앞', 'images/유진식당_184.jpg', '나름대로 마니아층을 거느리고 있는 냉면집. 면은 메밀과 전분을 50:50으로 섞어서 직접 뽑아 메밀 비율이 상당히 높음. 소고기와 소고기 뼈로 육수.\n\n나름대로 마니아층을 거느리고 있는 냉면집. 면은 메밀과 전분을 50:50으로 섞어서 직접 뽑아 씁니다. 메밀 비율이 상당히 높은 편입니다. 육수는 소고기와 소고기 뼈로 뽑습니다.', 37.572046, 126.988333, '1만원대', '지하철 1/3/5호선 종로3가역 5번 출구, 63m', '설렁탕, 돼지머리국밥, 물냉면, 비빔냉면', '수요일~일요일', '', '음식점', '', '11:30~14:30 / 16:00~21:00', '02-764-2835', '월요일, 화요일, 명절 휴무'),
	(185, '가미분식', '03767  서울 서대문구 이화여대8길 2 무궁화상가아파트', 'images/가미분식_185.jpg', '이대 앞 추억의 한 끼 식사, 가미 우동과 주먹밥\n\n가미분식은 이대역 부근에서 1975년부터 40년 이상 운영 중인 분식집입니다. 이화여대를 졸업한 중년의 손님들이 추억 맛집으로 찾기도 하고 젊은이들이 ‘엄마의 단골집’이라며 찾기도 합니다. 이곳의 대표 메뉴인 \'가미 우동\'은 밀가루에 소금만 넣고 두 번 삶아 부드럽고 탱탱한 둥근 면발이 특징입니다. 가미우동과 주먹밥 하나면 한 끼 식사가 됩니다. 문을 여는 시간이 11시 30분인데 이 시간부터 벌써 줄을 서서 대기번호를 받아야 할 정도로 인기가 많습니다.', 37.558654, 126.945921, '', '지하철 2호선 이대역 3번 출구, 207m', '가미우동 7,500원', '월요일~화요일, 목요일~일요일', '', '음식점', '', '10:00~20:30', '02-364-3948', '수요일'),
	(186, '차마시는뜰', '03052  서울특별시 종로구 북촌로11나길 26 (삼청동)', 'images/차마시는뜰_186.jpg', '고즈넉한 고택에서 즐기는 전통차 한 잔. 분위기도 맛도 전통 그대로. 출출하면 즉석에서 만들어주는 달콤한 시루떡을 곁들임.\n\n고즈넉한 고택에서 즐기는 전통차 한 잔. 분위기도 맛도 전통 그대로를 느낄 수 있습니다. 출출하면 즉석에서 만들어주는 달콤한 시루떡을 곁들일 수 있어요.', 37.582219, 126.982274, '1만원대', '지하철 3호선 안국역 2번 출구, 790m', '전통 한옥을 개조', '수요일~월요일', '', '카페, 디저트', '', '수요일~월요일 10:00 ~ 19:00', '0507-1304-7029', '매주 화요일, 구정, 추석 당일'),
	(187, '혜화칼국수', '03076  서울특별시 종로구 창경궁로35길 13 (혜화동)', 'images/혜화칼국수_187.png', '30년 가까이 운영되고 있는 혜화동 토박이 음식점으로, 옛날 그대로의 모습을 간직하고 있는 곳.\n\n30년 가까이 운영되고 있는 혜화동 토박이 음식점으로, 옛날 그대로의 모습을 간직하고 있는 곳입니다. 사골 국물에 양지를 삶은 국물을 섞어서 24시간 동안 푹 끓여 깊은맛을 낸 국물에 가늘게 썬 칼국수 맛이 일품입니다. 칼국수 외에 소고기를 얇게 저며서 불고기 양념을 해서 석쇠에 구운 바짝불고기와 생선튀김, 문어 등도 있습니다.', 37.586567, 127.001507, '', '지하철 4호선 혜화역 4번 출구, 403m', '', '월요일 ~ 일요일', ' https://www.instagram.com/hyehwanoodlehouse', '음식점', '', '11:00~21:00 (브레이크타임 15:00~16:00 / 라스트오더 20:30)', '0507-1428-8214', '명절 휴무'),
	(188, '정식당', '06014  서울 강남구 선릉로158길 11 (청담동)', 'images/정식당_188.jpg', '뉴코리안이라는 새로운 콘셉트로 오픈하자마자 유명세를 탄 레스토랑. 뉴코리안이란 한식을 프렌치적인 시각에서 해석. 비주얼은 아방 가르드하면서도 식재료와 한식과 양식을 넘나드는 조리기법.\n\n뉴코리안이라는 새로운 콘셉트로 오픈하자마자 유명세를 탄 레스토랑다입니다. 뉴코리안이란 한식을 프렌치적인 시각에서 해석한 것입니다. 비주얼은 아방 가르드하면서도 식재료와 조리 기법은 한식과 양식을 넘나듭니다. 수비드(저온조리법) 같은 분자요리 기법도 응용하고 있습니다. 점심, 저녁 모두 프리 픽스로 운영하고 있으며 각 코스 별로 2~3가지 중에서 선택할 수 있게 되어 있습니다. 도산공원 옆에 위치해 있어 최강의 전망을 자랑하지만 이 전망을 즐기려면 점심 때 가야 한다는 점. 2025년 미쉐린 가이드에 선정되었다.', 37.525658, 127.041081, '', '지하철 수인분당선 압구정로데오역 4번 출구, 171m', '점심코스, 저녁코스', '매일', ' http://www.jungsik.kr/', '음식점', '', '12:00~15:00, 17:30~22:00', '02-517-4654', '명절 당일 휴무'),
	(189, '행화촌', '04535  서울 중구 남대문로 52-5 (대한문화예술공사)', 'images/행화촌_189.jpg', '화상이 경영하는 중식당.\n\n화상이 경영하는 중식당. 이 골목에서 가장 원형에 가까운 한국식 중국 요리를 내는 집입니다. 오리지널 흰 짬뽕인 해물이 듬뿍 들어간 삼선짬뽕으로 유명합니다.', 37.562120, 126.981717, '1만원대', '지하철 4호선 명동역 5번 출구, 420m', '탕수육, 간짜장, 양장피', '', '', '음식점', '', '매일 11:00~21:30', '02-771-0172', '명절, 공휴일 휴무'),
	(190, '청진옥', '03156  서울 종로구 종로3길 32 (청진동, 청진빌딩)  1층', 'images/청진옥_190.jpg', '청진동 골목의 해장국 대명사\n\n청진옥은 1937년 평화관이라는 이름으로 시작해 나무꾼들이 찾던 작은 해장국집으로, 해방 이후 청진옥으로 상호를 바꾸며 서울 해장국의 대명사로 자리 잡았습니다. 24시간 동안 소뼈를 고아낸 육수에 된장, 양곱창, 선지 등 다양한 재료를 넣어 깊고 고소한 맛을 자랑하는데, 90년 가까이 해장국 하나로 장사를 해온 만큼 맛은 확실히 보장할 수 있습니다. 내부는 넓고 깔끔하며, 청진옥의 역사를 담은 사진들이 벽면에 전시되어 있습니다.', 37.571730, 126.979463, '', '지하철 1호선 종각역 1번 출구, 397m\n지하철 5호선 광화문역 3번 출구, 294m', '해장국, 안주국, 모듬수육', '월요일~일요일', ' http://www.cheongjinok.com/', '음식점', '', '06:00~22:00', '02-735-1690', '연중무휴'),
	(191, '멘야산다이메', '04039  서울 마포구 홍익로5안길 24', 'images/멘야산다이메_191.jpg', '일본 정통 라멘집. 돈코쓰 라멘.\n\n일본 정통 라멘집. 돈코쓰 라멘을 전문으로 내는데 면과 국물을 따로 내는 쓰케멘이 추천메뉴입니다. 실내는 작고 아담하지만 깔끔한 일본풍을 느낄 수 있습니다. 재료가 떨어지면 문을 닫습니다.', 37.553699, 126.921426, '1만원대', '지히철 2호선/ 경의중앙선/ 공항철도 홍대입구역 9번 출구, 385m', '츠케멘, 마제소바, 돈코츠라멘', '', '', '음식점', '', '매일 11:30 ~ 22:00 (재료 소진 시 종료)', '02-332-4129', '명절 휴무'),
	(192, '여자만', '03146  서울 종로구 인사동14길 24-2 (관훈동)', 'images/여자만_192.jpg', '전라남도 고흥과 여수 사이에 있는 ‘여자만’이라는 지명에서 이름을 따온 남도음식 전문주점. 꼬막정식이 인기. 여성 영화감독 이 미례 씨가 운영하는 곳으로도 유명.\n\n전라남도 고흥과 여수 사이에 있는 ‘여자만’이라는 지명에서 이름을 따온 남도음식 전문주점입니다. 꼬막정식이 인기가 있습니다. 여성 영화감독 이 미례 씨가 운영하는 곳으로도 유명합니다.', 37.574886, 126.985351, '3만원대', '지하철 3호선 안국역 6번 출구, 211m', '벌교참꼬막, 양념참꼬막, 정식, 모둠전', '월요일~일요일', '', '음식점', '', '평일 11:30~21:20, 주말 11:30~20:30', '02-723-1238', '명절휴무'),
	(193, '강남교자', '06612  서울 서초구 강남대로69길 11 (서초동, 삼미빌딩)  2층', 'images/강남교자_193.jpg', '명동교자에서 30년간 근무한 조리장이 독립하여 낸 칼국수 전문점.\n\n명동의 유명한 칼국숫집인 명동교자에서 30년간 근무한 조리장이 독립하여 낸 칼국수 전문점. 닭뼈 육수를 베이스로 한 칼국수를 맛볼 수 있습니다. 사리와 밥은 무제한으로 제공되며, 만두와 비빔국수도 추천 메뉴입니다. 테이크 아웃도 가능합니다.', 37.501475, 127.024267, '1만원대', '지하철 9호선 / 신분당선 신논현역 7번 출구, 270m', '칼국수, 교자만두, 얼큰칼국수, 완당떡국', '', ' http://gangnamgyoja.com/', '음식점', '', '매일 10:30~21:00', '02-536-4133', '명절 당일 휴무'),
	(194, '깃대봉냉면', '03108  서울 중구 청계천로 400 베네치아메가몰 2층 2038호', 'images/깃대봉냉면_194.jpg', '40여 년 전통의 냉면 전문점. 매콤한 비빔냉면으로 유명한 집\n\n40여 년 전통의 냉면 전문점. 매콤한 비빔냉면으로 유명한 집입니다. 정통 이북식 냉면에 비하면 다소 분식집스럽다는 평도 있지만, 나름대로 열성팬들을 가지고 있습니다. 매운맛, 덜 매운 맛, 안 매운맛 등을 고를 수 있습니다.', 37.570811, 127.021464, '', '지하철 1/2호선/우이신설선 신설동역 10번 출구, 620m', '냉면, 만두', '화수목금토일', '', '음식점', '', '11:00 ~ 20:30', '02-762-4407', '매주 월요일 정기 휴무, 명절 휴무'),
	(196, '버드나무집', '06729  서울 서초구 효령로 434 (버드나무집)', 'images/버드나무집_196.jpg', '한번 맛보면 잊을 수 없어 다시 찾게 된다는 30년 전통의 한우 요리 전문점. 균일하게 자리잡은 마블링이 예술의 경지.\n\n30년 전통의 한우 요리 전문점\n\n한번 맛보면 잊을 수 없어 다시 찾게 된다는 30년 전통의 한우 요리 전문점. 균일하게 자리잡은 마블링이 가히 예술의 경지를 보는 듯합니다. 사랑하는 가족과의 기념일이나 귀한 손님을 대접할 이상적인 음식점을 찾는다면 이만한 곳이 또 있을까요?', 37.489099, 127.031276, '', '지하철 신분당선/ 3호선 양재역 2번 출구, 500m', '갈비정식, 주물럭, 양념갈지, 생등심', '', '', '음식점', '', '매일 11:00~21:30', '02-3473-4167', '연중무휴'),
	(197, '대동문', '07328  서울 영등포구 국제금융로6길 30 (백상빌딩)  백상빌딩 2층', 'images/대동문_197.jpg', '고향이 평양인 할머니와 아들, 며느리가 운영하는 20여 년 역사의 음식점으로, 어복쟁반, 만둣국, 콩비지, 녹두지짐 등의 평양 전래음식을 옛날 그대로 재현.\n\n고향이 평양인 할머니와 아들, 며느리가 운영하는 20여 년 역사의 음식점으로, 어복쟁반, 만둣국, 콩비지, 녹두지짐 등의 평양 전래음식을 옛날 그대로 재현하고 있습니다.', 37.521724, 126.926604, '', '지하철 5/9호선 여의도역 5번 출구, 320m', '어복쟁반, 평양손만두국', '', ' http://www.daedongmun.kr/', '음식점', '', '평일 10:00~15:00, 17:00~22:00', '02-782-1780', '매주 토요일, 일요일, 공휴일 휴무'),
	(198, '한남북엇국', '04419  서울특별시 용산구 독서당로 65-7 (한남동)', 'images/한남북엇국_198.jpg', '북어국 외에도 안줏거리가 많아 술 한잔하기 좋은 곳. 다양한 종류의 전이랑, 수육.오징어무침이 인기 메뉴.\n\n북어국 외에도 안줏거리가 많아 술 한잔하기 좋은 곳입니다. 다양한 종류의 전이랑, 수육이 인기 메뉴이며 오징어무침도 괜찮습니다.', 37.533942, 127.008072, '', '지하철 경의중앙선 한남역 1번 출구, 623m', '한남북엇국 차림, 묵은지돼지찜, 민육전, 영덕 홍게장 비빔밥 차림', '', '', '음식점', '', '월요일~토요일 08:00 ~ 15:00 / 17:00 ~ 23:00\n일요일 08:00 ~ 15:00 / 17:00 ~ 21:00', '02-2297-1988', ''),
	(199, '강서면옥', '04513  서울 중구 세종대로11길 35', 'images/강서면옥_199.jpg', '남북 적십자 회담 당시 북측 대표들에게 제공된 냉면으로 유명. 50년 동안 평양냉면의 전통계승.\n\n50년 한결같은 맛의 3대를 잇는 냉면\n\n남북 적십자 회담 당시 북측 대표들에게 제공된 냉면으로 유명합니다. 50년 동안 평양냉면의 전통을 이어오고 있습니다. 강원도 토종 메밀과 전분을 알맞게 섞어 만든 구수한 면발과 양지고기를 푹 고은 국물과 동치미를 섞어 시원한 맛을 내는 육수가 일품입니다.', 37.562008, 126.975425, '', '지하철 1/2호선 시청역 9번 출구, 159m', '평양물냉면, 함흥비빔냉면, 삼겹살', '', '', '음식점', '', '매일 11:00~15:00, 17:00~22:00', '02-752-1945', '명절 연휴'),
	(200, '노랑저고리 (강남점)', '06616  서울특별시 서초구 서초대로73길 9, 타임빌딩 5층 (서초동)', 'images/노랑저고리_(강남점)_200.jpg', '전통 한옥의 고풍스런 분위기. 전통 한옥의 풍경 너른 앞마당과 뒤뜰, 그리고 사랑채에서 정겨운 식사. 종갓집 새댁의 마음으로 정성스럽게 차려내는 10여 가지의 요리와 갖가지 토속반찬.\n\n오감의 행복이 담긴 소박한 한정식집\n\n복잡한 도심 속 전통 한옥의 고풍스런 분위기가 그윽한 노랑 저고리. 이곳에 들어서면 귀한 손님 대접을 제대로 받는 느낌이 듭니다. 전통 한옥의 풍경 너른 앞마당과 뒤뜰, 그리고 사랑채에서 정겨운 식사를 즐길 수 있습니다. 종갓집 새댁의 마음으로 정성스럽게 차려내는 10여 가지의 요리와 갖가지 토속반찬이 맛깔스럽습니다.', 37.498308, 127.025228, '', '지하철 2호선/ 신분당선 강남역 9번 출구, 183m', '보리굴비한상, 새댁 회 코스', '', '', '음식점', '', '매일 11:30 ~ 21:30', '02-534-5300', '명절당일'),
	(201, '소선재', '03049  서울특별시 종로구 삼청로 113-1 (삼청동)', 'images/소선재_201.jpg', '야생초를 사용한 건강 식단을 맛볼 수 있는 곳. 정식코스에는 근채쌈, 민들레와 야생초 샐러드, 야생초 야채전, 장김치 보쌈, 두부소박이와 식사.\n\n야생초를 사용한 건강 식단을 맛볼 수 있는 곳입니다. 정식코스에는 근채쌈, 민들레와 야생초 샐러드, 야생초 야채전, 장김치 보쌈, 두부소박이와 식사 등이 나옵니다. 가격에 따라 닭고기 샐러드, 메로구이 등이 추가되기도 합니다. 한옥을 개조해서 만든 열 개 테이블 정도의 작은 공간입니다.', 37.585538, 126.981790, '', '지하철 3호선 안국역 1번 출구, 1.3km', '떡갈비와 식사, 장아찌 보쌈과 식사, 보리굴비와 식사, 간장게장과 식사', '', '', '음식점', '', '평일 11:30~14:30, 17:00~21:00 / 주말 11:30~14:30, 17:30~21:00', '02-730-7002', '명절 휴무'),
	(202, '단미그린비', '06364  서울 강남구 밤고개로14길 13-50', 'images/단미그린비_202.jpg', '자연과 즐기는 싱그러운 정찬\n\n\'단미그린비\'는 사랑스런 여인과 그리운 선비가 만나 화목한 가정을 꾸민다는 의미입니다. 대모산 끝자락에 위치하여 자연을 바라보며 식사를 할 수 있는 전원 한정식당으로 여러가지 코스 음식을 즐길 수 있습니다.', 37.480461, 127.103523, '', '지하철 GTX-A / 분당선 / 3호선 수서역 5-2번 출구, 812m', '자연정찬, 귀연정찬', '', '', '음식점', '', '화~일 11:30~15:00, 17:30~21:00', '02-445-2100', '매주 월요일'),
	(203, '창고43', '07331  서울 영등포구 국제금융로6길 33  M2층', 'images/창고43_203.jpg', '부드러운 파 채 무침과 함께 먹는 질 좋은 소고기의 맛이 일품인 곳. 고기를 다 먹은 후 깍두기 국물에 볶은 밥이 인기. 예약 필수.\n\n부드러운 파 채 무침과 함께 먹는 질 좋은 소고기의 맛이 일품인 곳. 고기를 다 먹은 후 깍두기 국물에 볶은 밥이 인기입니다. 예약 손님이 대부분이라 예약을 하는 것이 좋습니다.', 37.520791, 126.926912, '', '지하철 5/9호선 여의도역 5번 출구, 295m', '소고기구이', '월요일~일요일', ' http://www.changgo43.co.kr/', '음식점', '', '11:30~15:00, 17:30~22:00', '0507-1499-4557', '연중무휴'),
	(204, '갈비명가이상(길음신관)', '02734  서울 성북구 정릉로 395 (하월곡동, 이상빌딩)', 'images/갈비명가이상(길음신관)_204.jpg', '갈비 전문점으로, 최고 품질이 인증된 최상급 갈비만을 엄선하여 변함없는 최고의 고기 맛.\n\n갈비 전문점으로, 최고 품질이 인증된 최상급 갈비만을 엄선하여 변함없는 최고의 고기 맛을 지키고 있습니다.', 37.603891, 127.025747, '', '지하철 4호선 길음역 10번 출구, 60m', '돼지갈비', '월요일~일요일', '', '음식점', '', '11:00~22:00', '0507-1410-8004', '연중 무휴'),
	(205, '티앙팡오후의홍차', '03767  서울 서대문구 이화여대길 34 (대현동, 신흥빌딩) 2층', 'images/티앙팡오후의홍차_205.jpg', '10여 개국에서 직접 수집해 온 4백여 종의 차가 있는 차 전문점. 3명의 티 마스터 상주. 티앙팡은 중국말로 금상첨화란 뜻으로, 뜨거운 물을 부으면 국화꽃이 피어나듯 부풀어 오르고 녹차 같으면서도 은은한 국화 향이 감도는 맛이 남.\n\n10여 개국에서 직접 수집해 온 4백여 종의 차가 있는 차 전문점입니다. 3명의 티 마스터가 상주해 있습니다. 티앙팡은 중국말로 금상첨화란 뜻으로, 뜨거운 물을 부으면 국화꽃이 피어나듯 부풀어 오르고 녹차 같으면서도 은은한 국화 향이 감도는 맛이 납니다.', 37.558453, 126.945944, '', '지하철 2호선 이대역 3번 출구, 약 175m', '아이스 차이, 바닐라 차이, 아이스 로열 밀크티', '', '', '카페, 디저트', '', '매일 12:00 ~ 22:30', '0507-1378-4196', '연중무휴'),
	(206, '두바이', '04406  서울 용산구 이태원로 192', 'images/두바이_206.jpg', '이라크인이 직접 운영하고 있는 곳으로, 중동 지역의 아랍식 음식.\n\n이라크인이 직접 운영하고 있는 곳으로, 중동 지역의 아랍식 음식을 즐길 수 있습니다. 다양한 종류의 커리, 케밥을 비롯하여 호무스, 팔라펠 등의 애피타이저도 준비되어 있습니다. 식사 후에는 물담배도 피워볼 수 있는데, 사과, 민트, 딸기, 장미 등 여덟 종류 향의 물담배가 있습니다.', 37.534380, 126.995424, '2만원대', '지하철 6호선 이태원역 3번 출구, 88m', '양고기 립 스테이크, 쉬시 타욱, 양고기 캅사, 필라펠', '', '', '음식점', '', '화요일~일요일 12:00 ~ 23:00', '02-798-9277', '매주 월요일'),
	(207, '지대방', '03149  서울 종로구 인사동길 33 2층', 'images/지대방_207.jpg', '주인이 직접 재배한 차로 맛을 내는 전통차 전문점\n\n지대방은 차를 마시며 담소를 나누는 인사동의 전통찻집입니다 . 이곳에서 즐길 수 있는 전통차의 종류는 무려 60 가지가 넘는데 , 직접 수확하거나 자연 재배된 차만을 사용하기 때문에 신선한 전통차를 제대로 즐겨볼 수 있습니다 . 차를 주문하면 다기 세트에 뜨거운 물이 담긴 보온병을 내어주는데 직접 우려 마실 수 있게 사장님이 친절하게 안내해 주십니다 . 내부는 자연적인 느낌이 들며 , 40 년의 전통이 물씬 느껴집니다 . 복잡한 인사동 골목에서 조용한 쉼터 같은 이곳은 내외국인 , 남녀노소 관계없이 모두에게 사랑받는 곳입니다.', 37.573482, 126.985509, '', '지하철 1/3/5호선 종로3가역 5번 출구, 351m', '', '매일', '', '카페, 디저트', '', '월요일~토요일 10:30~22:30\n일요일 11:00~22:00', '02-738-5379', '없음'),
	(208, '부다스벨리', '04345  서울특별시 용산구 녹사평대로40길 48 (이태원동)', 'images/부다스벨리_208.jpg', '간편하게 태국 음식을 즐길 수 있는 곳. 향신료의 양을 적절하게 조절.\n\n간편하게 태국 음식을 즐길 수 있는 곳. 태국 현지인 요리사가 주문에 따라 향신료의 양을 적절하게 조절해 줍니다. 메뉴판에 없는 음식도 별도 주문하면 만들어 줍니다. 런치 세트는 3가지 메뉴를 고르면, 밥과 함께 한 접시에 담겨 나옵니다. 1호점은 테이블이 3개밖에 없는 작은 규모이지만, 이태원 해밀턴호텔 뒷길 2호점에서는 더욱 넓고 쾌적한 분위기에서 리조트 풍의 태국 음식을 맛볼 수 있습니다.', 37.534392, 126.988377, '2만원대', '지하철 6호선 녹사평역 1번 출구, 248m', '푸님 팟 퐁 커리, 팟타이, 겡키완', '', ' https://www.instagram.com/buddhasbelly_official/', '음식점', '', '일요일~목요일 11:30~15:00, 16:30~22:00\n금요일~토요일 11:30~15:00, 16:30~22:30', '1666-2753', '연중무휴'),
	(209, '성북동누룽지백숙', '02879  서울 성북구 성북로31길 9', 'images/성북동누룽지백숙_209.jpg', '메밀수제비 집으로 시작한 곳으로, 들깨 메밀수제비와 누룽지 백숙이 인기\n\n원래는 메밀수제비 집으로 시작한 곳으로, 들깨 메밀수제비와 누룽지 백숙이 인기 메뉴입니다. 하얀 외관이 깔끔한 인상을 주며 식사를 마친 후에는 2층에 마련되어 있는 조그만 테라스에서 성북동의 전경을 바라보며 후식도 즐길 수 있습니다.', 37.594571, 126.990463, '', '지하철 4호선 한성대입구역 6번 출구, 1.7km', '성북동누룽지백숙, 들깨메밀수제비, 메밀전', '화요일~일요일', '', '음식점', '', '11:30 ~ 21:00 (Last Oder 20:00)', '02-764-0707', '월요일, 명절 휴무'),
	(210, '소공죽집', '04515  서울 중구 서소문로 139', 'images/소공죽집_210.jpg', '북창동 내에서 유명한 죽집으로, 10가지가 넘는 다양한 종류의 죽이 있어 각자의 입맛에 따라 선택. 굴과 대하가 들어 있는 영양 솥밥으로도 유명.\n\n북창동 내에서 유명한 죽집으로, 10가지가 넘는 다양한 종류의 죽이 있어 각자의 입맛에 따라 선택하여 먹기에 좋습니다. 굴과 대하가 들어 있는 영양 솥밥으로도 유명합니다.', 37.564106, 126.976164, '', '지하철 1, 2호선 시청역 12번 출구, 25m', '', '월화수목금토일', '', '음식점', '', '평일 08:00 ~ 20:00\n주말 08:00 ~ 15:00', '0507-1419-6401', '연중무휴'),
	(211, '타셴', '06643  서울 서초구 효령로 317 (서초동, 대한건축사협회)  1층', 'images/타셴_211.png', '아트 북카페. 독일의 유명 출판사인 타셴의 각종 예술 서적을 진열, 판매. 15종류의 샌드위치와 커피, 음료를 독서와 함께 . 타셴 출판사의 미술 관련 책도 판매.\n\n아트 북카페로, 독일의 유명 출판사인 타셴의 각종 예술 서적을 진열, 판매하며 15종류의 샌드위치와 커피, 음료를 독서와 함께 즐길 수 있습니다. 타셴 출판사의 미술 관련 책도 판매합니다.', 37.485997, 127.018727, '', '지하철 3호선 남부터미널역 2번 출구, 약 200m', '샌드위치', '', ' https://siginis.com/2024/caftaschen_a/', '카페, 디저트', '', '평일 08:00 ~ 20:00\n주말 10:00 ~ 20:00', '070-8876-5555', '연중무휴'),
	(212, '희정식당', '07336  서울 영등포구 여의나루로 117  지하', 'images/희정식당_212.jpg', '푸짐한 소시지와 햄 사리의 부대찌개 전문점. 얼큰하고 걸쭉한 국물. 인근 여의도 직장인들에게 많이 알려진 곳. 저녁때는 푸짐한 T본 모둠스테이크도 인기.\n\n푸짐한 소시지와 햄 사리의 부대찌개 전문점입니다. 얼큰하고 걸쭉한 국물도 얼큰하고 좋습니다. 인근 여의도 직장인들에게 많이 알려진 곳입니다. 저녁때는 푸짐한 T본 모둠스테이크도 인기가 있습니다.', 37.526230, 126.931054, '', '지하철 5호선 여의나루역 1번 출구, 155m', '특.희정부대찌개, 티본모듬스테이크, 등심스테이크', '', '', '음식점', '', '월요일~토요일 11:30~23:00', '02-784-9213', '매주 일요일, 명절 휴무'),
	(213, '더블린테라스', '06130  서울 강남구 강남대로94길 27-15 (태리빌딩)', 'images/더블린테라스_213.jpg', '기네스 생맥주를 즐기기에 좋은 아이리시 펍.\n\n이름에서도 연상되듯이 아이리시 펍입니다. 기네스 생맥주를 즐기기에 좋은 곳. 매년 3월에는 아일랜드의 성 패트릭스데이를 기념하는 홀리나이트 파티가 열리기도 합니다. 이날은 오후 7시부터 다음날 새벽 1시 30분까지 기네스를 포함한 모든 음식들을 무제한 즐길 수 있습니다.', 37.500696, 127.029101, '', '지하철 2호선/신분당선 강남역 11번 출구, 374m', '치즈볼 모듬나쵸, 치킨 앤 칩스', '', '', '술집, 바', '', '월, 화, 수, 목 : 14:00~01:00\n금, 토 : 14:00~02:00\n일요일 : 14:00~23:00', '02-555-2553', '연중무휴'),
	(214, '마담밍', '06192  서울 강남구 선릉로86길 5-4 (대치동)  1층', 'images/마담밍_214.jpg', '북경식과 사천식 음식을 비교적 대중적인 가격에 맛볼 수 있는 중식당.\n\n북경식과 사천식 음식을 비교적 대중적인 가격에 맛볼 수 있는 중식당으로, 여름에는 매우면서도 시원한 짬뽕냉면이 인기 메뉴입니다. 짬뽕, 짜장면, 게살볶음밥 등은 모든 면과 밥이 무제한 리필이 가능합니다. 역삼점을 오픈하면서 선릉역 본점보다 역삼점이 낫다는 평도 있습니다.', 37.503462, 127.050239, '1만원대', '지하철 2호선/ 수인분당선 선릉역 2번 출구, 140m', '쟁반 짜장, 짬뽕 냉면, 중국 냉면', '월요일~토요일', '', '음식점', '', '11:30 ~ 15:00, 17:00 ~ 21:00', '02-567-6992', '매주 일요일, 명절 휴무'),
	(215, '황태본가', '07327  서울 영등포구 국제금융로2길 37 (여의도동, 에스트레뉴)', 'images/황태본가_215.jpg', '황태 요리로 유명한 집. 메뉴는 황태구이와 황태국, 시래깃국. 황태구이 정식에는 고추장 양념에 하루 정도 재워둔 황태를 불판에 올려놓고 알맞게 구운 다음, 파와 깨를 골고루 뿌려 먹음직스러움.\n\n황태 요리로 유명한 집. 메뉴는 황태구이와 황태국, 시래깃국입니다. 황태구이 정식에는 고추장 양념에 하루 정도 재워둔 황태를 불판에 올려놓고 알맞게 구운 다음, 파와 깨를 골고루 뿌려 먹음직스럽게 내옵니다. 오징어무침, 멸치볶음 등 반찬도 정갈합니다.', 37.522945, 126.924286, '1만원대', '지하철 5/9호선 여의도역 3번 출구, 12m', '황태구이, 황태찜', '월요일~토요일', '', '음식점', '', '평일 06:30~22:00', '02-786-8307', '일요일, 명절 휴무'),
	(216, '단풍나무집', '03053  서울 종로구 삼청로 130', 'images/단풍나무집_216.jpg', '분위기 있게 고기를 먹을 수 있는 곳. 천겹이라는 대표 메뉴는 돼지고기 항정살. 화력이 좋은 참숯에 구운 고기를 깻잎 장아찌에 싸 먹는 곳.\n\n분위기 있게 고기를 먹을 수 있는 곳. 천겹이라는 대표 메뉴는 돼지고기 항정살을 말하는 것입니다. 화력이 좋은 참숯에 구운 고기를 깻잎 장아찌에 싸 먹는 맛이 좋습니다.', 37.586872, 126.981969, '2만원대', '지하철 3호선 안국역 1번 출구, 1.4km', '한우 숙성 등심, 양념갈비, 단풍 불고기, 오겹살', '', ' http://www.mapletreehouse.co.kr/', '음식점', '', '월요일~일요일 11:30~22:00 (Last Order 21:30)\n월~금 브레이크타임 15:00~17:00', '02-730-7461', ''),
	(217, '대방골', '07238  서울 영등포구 국회대로 800 (진미파라곤)  지하 1층', 'images/대방골_217.jpg', '정성과 깊은 맛으로 감동을 전하는 한정식\n\n대방골 한정식집에서는 잘 말려서 짭짤한 굴비를 녹차물에 말아먹는 별미는 물론, 무안 뻘낙지, 흑산도 홍어, 흑산도 전복도 즐길 수 있습니다.', 37.530929, 126.921084, '', '지하철 9호선 국회의사당역 1번 출구, 358m', '대방골정식, 솔잎찜보리굴비한정식, 연포탕한정식, 솔잎찜보리굴비매생이정식', '매일', ' https://www.instagram.com/daebanggol_official/', '음식점', '', '평일 11:20~14:30, 17:00~22:00 / 주말 11:20~21:00', '02-783-4999', '연중무휴'),
	(218, '철철복집', '04522  서울특별시 중구 을지로3길 29 (다동)', 'images/철철복집_218.jpg', '생 복을 석쇠 위에 올려 직화로 구워 먹는 복불고기\n\n생 복을 석쇠 위에 올려 직화로 구워 먹는 복불고기가 독특합니다. 복국도 해장에 좋습니다. 싱싱한 복을 사용하는 만큼 가격대는 다소 높습니다.', 37.567361, 126.981338, '', '지하철 2호선 을지로입구역 1-1번 출구, 184m', '복어요리', '월화수목금토', '', '음식점', '', '11:30 ~ 14:30 / 16:30 ~ 22:00', '02-776-2418', '매주 일요일, 명절 휴무'),
	(219, '해동복국', '07333  서울 영등포구 여의대방로67길 22 (여의도동, 태양빌딩)  1층', 'images/해동복국_219.jpg', '콩나물을 듬뿍 넣고 끓여 뚝배기에 내오는 얼큰한 복국. 매운탕이나 담백한 지리도 훌륭한 맛. 고급 복요리집은 아니지만, 대중적인 복 요리를 내는 곳.\n\n콩나물을 듬뿍 넣고 끓여 뚝배기에 내오는 복국이 얼큰합니다. 매운탕이나 담백한 지리도 훌륭한 맛을 냅니다. 고급 복요리집은 아니지만, 대중적인 복 요리를 내는 곳입니다.', 37.520701, 126.929998, '', '지하철 9호선/신림선 샛강역 1번 출구, 470m', '복국지리, 복국매운탕, 복튀김, 복수육', '', '', '음식점', '', '매일 09:00~22:00', '02-783-6011', '명절 휴무'),
	(220, '곰국시집', '04521  서울 중구 무교로 24  무교동파이낸스빌딩 뒤에 위치', 'images/곰국시집_220.jpg', '직접 뽑은 국시의 쫄깃함과 양지머리 육수의 깊은 맛이 일품인 곰국시, 한우 양지머리를 푹 삶아 미각을 당기는 수육이 별미. 감칠맛 나는 입소문이 국내는 물론 일본까지 꼬리를 물고 연일 문전성시.\n\n자부심으로 잇는 대가의 전통직접 뽑은 국시의 쫄깃함과 양지머리 육수의 깊은 맛이 일품인 곰국시, 한우 양지머리를 푹 삶아 미각을 당기는 수육이 별미입니다. 감칠맛 나는 입소문이 국내는 물론 일본까지 꼬리를 물고 연일 문전성시를 이룹니다. 함께 곁들여지는 맛깔스런 밑반찬을 먹는 즐거움도 빼놓을 수 없습니다.', 37.568104, 126.979478, '', '지하철 1/2호선 시청역 4번 출구, 333m', '곰국시\n전골국수', '월요일~토요일', '', '음식점', '', '평일 11:00 ~ 14:00 / 17:00 ~ 21:30\n토요일 11:00 ~ 14:30 / 17:00 ~ 20:30', '02-756-3249', '매주 일요일, 명절 휴무'),
	(221, '기욤', '06014  서울 강남구 선릉로152길 17 (인성빌딩)', 'images/기욤_221.jpg', '정통 프렌치 베이커리. 바게트 외에도 마카롱, 머랭, 에클레르도 인기. 간단한 식사. 1층은 컨트리 하우스 풍, 2층은 파리 상류층 아파트 풍의 색다른 분위기.\n\n정통 프렌치 베이커리. 바게트 외에도 마카롱, 머랭, 에클레르도 인기입니다. 간단한 식사도 겸하고 있습니다. 1층은 컨트리 하우스 풍, 2층은 파리 상류층 아파트 풍으로 색다른 분위기도 느낄 수 있습니다.', 37.524371, 127.041029, '', '지하철 수인분당선 압구정로데오역 4번 출구, 약 400m', '', '매일', '', '카페, 디저트', '', '평일 11:00~24:00, 주말 10:00~24:00', '0507-1407-6703', '명절'),
	(222, '흑돈가', '06163  서울특별시 강남구 봉은사로86길 14 (삼성동)', 'images/흑돈가_222.jpg', '제주에 본점이 있는 흑돼지 전문점.\n\n제주에 본점이 있는 흑돼지 전문점. 흑돼지는 일반적인 삼겹살보다 훨씬 더 쫄깃하고 맛이 고소하면서도 담백합니다. 고기를 두툼하게 구워 진한 감칠맛이 나는 제주식 멸치 젓갈 소스에 찍어 먹습니다.', 37.512516, 127.056316, '', '지하철 9호선 삼성중앙역 4번 출구, 311m', '흑돼지생구이, 흑돼지양념구이, 된장찌개', '월화수목금토일', '', '음식점', '', '평일 11:30 ~ 15:00 / 17:00 ~ 22:00\n주말 11:30 ~ 22:00', '02-2051-0008', '연중무휴'),
	(223, '스시조', '04533  서울 중구 소공로 106 (소공동, 서울 웨스틴조선호텔)', 'images/스시조_223.jpg', '서울 최고의 일식당 중의 하나로 꼽히는 곳.\n\n서울 최고의 일식당 중의 하나로 꼽히는 곳. 일본에서 공수해 오는 신선한 재료에 국내 최대의 길이를 자랑하는 히노키 다이가 유명합니다. 도쿄의 전설적인 스시 집 큐베이 출신의 일본인이 조리장을 맡고 있습니다. 2020년에 미쉐린 가이드에 선정되었습니다.', 37.564484, 126.980185, '', '지하철 1/2호선 시청역 6번 출구, 341m', '', '', ' https://www.josunhotel.com/hotel/westinSeoul.do', '음식점', '', '매일 12:00~15:00, 17:30~22:00', '02-317-0373', '연중무휴'),
	(224, '비금도', '06015  서울 강남구 압구정로80길 26 (청담동, 노아빌딩)', 'images/비금도_224.jpg', '육전과 남도 음식을 즐길 수 있는 한식집. 전 요리를 다 먹으면 찐 밥과 남도 반찬 10가지, 국, 누룽지가 제공. 깻잎장아찌, 전복 내장, 갓김치 등의 남도식 반찬.\n\n육전과 남도 음식을 즐길 수 있는 한식집. 전 요리를 다 먹으면 찐 밥과 남도 반찬 10가지, 국, 누룽지가 제공됩니다. 깻잎장아찌, 전복 내장, 갓김치 등의 남도식 반찬이 깔끔하고 맛깔납니다.', 37.524799, 127.044611, '', '지하철 수인분당선 압구정로데오역 4번 출구, 642m', '비금도코스요리, 육전, 삼합, 산낙지탕', '', '', '음식점', '', '월요일~금요일 11:30~22:00\n토요일 17:00~23:00', '02-512-1714', '일요일, 명절 휴무'),
	(225, '봉산옥', '06716  서울 서초구 반포대로8길 5-6 (조강빌딩)', 'images/봉산옥_225.jpg', '황해도 봉산식 음식을 선보이는 곳.\n\n황해도 봉산식 음식을 선보이는 곳. 배추와 숙주, 두부, 소고기, 돼지고기 등을 넣은 황해도식 손만두를 맛볼 수 있습니다. 김치 해장국, 김치말이국수도 별미입니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.483382, 127.012453, '1만원대', '지하철 3호선 남부터미널역 5번 출구, 421m', '봉산 만두국, 김치말이국수, 열무회국수, 양푼열무비빔밥', '월요일~토요일', '', '음식점', '', '평일 11:00~14:30 / 17:00~21:20\n토요일 11:00~14:30 / 17:00~20:00', '02-525-2282', '매주 일요일 휴무'),
	(226, '양마니', '07238  서울 영등포구 국회대로74길 20 맨하탄21상가 2층', 'images/양마니_226.jpg', '소의 위를 뜻하는 양을 먹을 수 있는 곳. 신선도와 육질이 특히 뛰어남. 자체 개발한 소스에 24시간 재웠다가 구워먹는데 담백하고 고소한 맛이 일품.\n\n소의 위를 뜻하는 양을 먹을 수 있는 곳. 신선도와 육질이 특히 뛰어납니다. 자체 개발한 소스에 24시간 재웠다가 구워먹는데 담백하고 고소한 맛이 일품입니다. 양 외에도 한우나 전골을 맛볼 수 있습니다.', 37.529606, 126.921553, '2만원대', '지하철 9호선 국회의사당역 2번 출구, 435m', '특양구이, 대창구이, 한우등심', '월요일~일요일', '', '음식점', '', '매일 10:00~14:30, 16:30~22:00', '0507-1421-9282', '명절 휴무'),
	(227, '더 그린테이블', '03058  서울 종로구 율곡로 83 (원서동)  5층', 'images/더_그린테이블_227.jpg', '캐주얼한 비스트로 스타일의 프랑스 음식점\n\n세 자매가 운영하고 있는 세미 비스트로이다. 캐주얼한 비스트로 스타일의 프랑스 음식을 맛볼 수 있습니다. 다양한 그릇과 파스텔 톤의 색감으로 실내를 꾸민 것이 특징입니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.577762, 126.988358, '', '지하철 3호선 안국역 3번 출구, 218m', '계절코스', '', ' https://www.instagram.com/restaurant_thegreentable/#', '음식점', '', '평일 12:00 ~ 15:00 / 18:00 ~ 22:00\n일요일 12:00 ~ 15:00 / 18:00 ~ 21:30', '02-591-2672', '매주 월요일 ,화요일, 명절 휴무'),
	(228, '외백', '04172  서울 마포구 도화2길 4', 'images/외백_228.jpg', '화상이 하는 중식당. 전반적으로 신선한 재료와 불 맛 잘 살린 요리.\n\n화상이 하는 중식당. 전반적으로 신선한 재료와 불 맛 잘 살린 요리들은 탄탄한 기본기로 실망시키는 요리가 없는 편입니다.', 37.538957, 126.949336, '2만원대', '지하철 5호선 마포역 3번 출구, 266m', '탕수육, 자장면, 짬뽕, 삼선간짜장', '', '', '음식점', '', '월요일~토요일 11:00~14:30, 16:30~21:40', '02-712-0985', '일요일 휴무'),
	(229, '황소집', '04557  서울특별시 중구 충무로2길 2 (충무로3가)', 'images/황소집_229.jpg', '40여 년 전통의 도가니탕 전문점. 무쇠솥에 끓인 도가니탕을 먹기 위해서는 줄을 서야 할 정도. 저녁 때는 돌판에 나오는 도가니찜에 소주를 곁들임. 돌판 밑 숯불이 온도유지.\n\n40여 년 전통의 도가니탕 전문점. 무쇠솥에 끓인 도가니탕을 먹기 위해서는 줄을 서야 할 정도다입니다. 저녁 때는 돌판에 나오는 도가니찜에 소주를 곁들이는 사람들이 많습니다. 돌판 밑에는 숯불을 받쳐줘 다 먹을 때까지 계속 따끈하게 즐길 수 있습니다.', 37.562518, 126.993321, '1만원대', '지하철 3/4호선 충무로역 7번 출구, 156m', '도가니탕, 도가니찜, 숯불 생등심', '월요일~토요일', '', '음식점', '', '08:00~22:00', '02-2273-0969', '매주 일요일, 명절 휴무'),
	(230, '피양콩할마니', '06196  서울 강남구 삼성로81길 30 (대치동)', 'images/피양콩할마니_230.jpg', '된장찌개, 콩비지찌개, 순두부찌개, 콩국수 등 콩으로 만든 음식을 취급.\n\n된장찌개, 콩비지찌개, 순두부찌개, 콩국수 등 콩으로 만든 음식을 취급합니다. 비지찌개에는 콩비지, 김치콩비지, 무콩비지, 버섯콩비지 등 네 가지가 있습니다. 피양만두는 크기가 약간 작지만, 이북식으로 만든 것입니다. 생만두는 포장 가능하며 콩국물도 1.5L 페트병으로 판매다합니다. 2020년 미쉐린 가이드에 선정되었습니다.', 37.504110, 127.055241, '', '지하철 2호선/수인분당선 선릉역 1번 출구, 632m', '콩비지, 들깨수제비, 만두국, 콩비지전골, 피양접시만두', '', ' https://piyang.modoo.at/', '음식점', '', '매일 11:30~22:00', '02-508-0476', '명절 휴무'),
	(231, '한국의집 고호재', '04626  서울 중구 퇴계로36길 10 (필동2가, 한국의집)', 'images/한국의집_고호재_231.jpg', '한국의집 궁중 다과 \'고호재(古好齋)\'\n\n고호재(古好齋)는 \'옛 것을 좋아하는 이들의 집\'이란 뜻으로 한국의집에서 선보이는 프리미엄 궁중다과 브랜드입니다. 사전 예약제로 진행되는 고호재 프로그램은 봄, 여름, 가을, 겨울의 제철재료로 빚은 전통병과로 오직 한 사람만을 위한 1인 다과상을 선보입니다. 한국의 전통문화와 음식을 경험할 수 있는 복합문화공간 \'한국의집\'에서 궁중 다과와 고즈넉한 한옥의 멋을 즐겨보길 바랍니다.', 37.560203, 126.994684, '', '지하철 3/ 4호선 충무로역 3번 출구, 54m', '', '', ' http://www.koreahouse.or.kr', '음식점', '캐치테이블 사전 예약\n예약링크 : https://app.catchtable.co.kr/ct/shop/koreahouse_kohojae\n\n시즌별 운영 일정 상이/주차가능', '*휴관안내 25년7월1일~26년3월2일\n\n1부 11:00~13:00 / 2부 13:30~15:30 / 3부 16:30~18:30 / 각 세션당 120분', '02-2266-9101', '매주 월요일, 설날 및 추석 당일'),
	(232, '꽁시면관', '04536  서울특별시 중구 명동2길 45 (충무로1가)', 'images/꽁시면관_232.jpg', '상해식 국물 만두인 샤오룽바오(소롱포)가 주력 메뉴.\n\n상해식 국물 만두인 샤오룽바오(소롱포)를 주력 메뉴로 하고 있습니다. 돼지갈비를 쪄서 옷을 입혀 튀겨 독특한 중국 향신료 맛과 갈빗살 맛이 잘 어우러진 마늘갈비도 인기입니다. 메뉴에 오므라이스가 있는 것이 특이한데, 일본식이 아니라 가지볶음, 좌종당계, 깐풍새우 등을 얹어내는 것이 특징입니다. 다른 소롱포 전문점에 비하여 가격이 비교적 저렴한 것이 장점.', 37.561400, 126.983219, '1만원대', '지하철 4호선 명동역 5번 출구, 192m', '', '월요일~일요일', ' http://instagram.com/ggongci_ggongci', '음식점', '', '10:30 ~ 22:00', '0507-1370-8863', '연중무휴'),
	(233, '쟈니덤플링', '04391  서울 용산구 보광로59길 33 (이태원동)', 'images/쟈니덤플링_233.jpg', '입안에 육즙이 가득 터지는 맛있는 만두전문점.\n\n입안에 육즙이 가득 터지는 맛있는 만두전문점. 한 면은 굽고 한 면은 찐 군만두, 새우와 고기가 가득 들어간 새우물만두 등 다양한 메뉴의 수제만두들이 있습니다. 채식주의자들을 위한 만두메뉴도 있습니다.', 37.533825, 126.992129, '1만원대', '지하철 6호선 이태원역 4번 출구, 204m', '군만두 반달, 송이물만두, 새우물만두', '', '', '음식점', '', '매일 11:30 ~ 20:30', '02-790-8831', '명절 휴무'),
	(234, '청담복집', '06072  서울특별시 강남구 영동대로 725 (청담동)', 'images/청담복집_234.jpg', '고급스러운 복 전문점. 복 사시미 코스가 있음. 활복을 쓰는 것이 맛의 비결이며 다른 집보다 가격이 높은 편.\n\n고급스러운 복 전문점. 복 사시미 코스에는 복사시미, 고니갈비, 복불고기, 복튀김, 스이모노(복지리) 순서로 나오고, 식사 메뉴로 복죽과 후식이 제공됩니다. 활복을 쓰는 것이 맛의 비결인데, 비싼 재료를 사용하는 만큼 다른 집보다 가격이 높은 편입니다.', 37.522460, 127.055152, '', '지하철 7호선 청담역 13번 출구, 277m', '복지리, 복매운탕', '월요일~토요일', '', '음식점', '', '11:00 ~ 14:30 / 17:00 ~ 22:00', '02-512-1888', '매주 일요일, 명절 휴무'),
	(235, '어양', '05545  서울 송파구 위례성대로 14 (한미타워)  지하 1층', 'images/어양_235.jpg', '해산물 요리에 강한 곳으로, 주방 한쪽에 커다란 수족관 보유.\n\n해산물 요리에 강한 곳으로, 주방 한쪽에 커다란 수족관이 있어 우럭, 돔 등의 생선을 즉석에서 잡아서 요리하는데, 중국 본토처럼 새우나 고기 요리에 다양한 소스를 택할 수 있게 합니다. 돼지다리를 한약재와 함께 곤 후 다시 쪄낸 어양 두반주스도 유명합니다.', 37.516593, 127.113956, '', '지하철 8호선 몽촌토성역 2번 출구, 137m\n지하철 9호선 한성백제역 1번 출구, 101m', '청증우럭찜/탕수우럭, 해물 누룽지, 새우 마요네즈소스, 삼선자장면, 두반주스, 런치코스, 디너코스', '', ' http://www.a-yang.co.kr', '음식점', '', '평일 11:30~15:00 / 17:30~22:00, 주말 11:30~15:00 / 17:30~21:30', '02-422-8886', '명절 휴무'),
	(236, '광화문집', '03183  서울특별시 종로구 새문안로5길 12 (당주동)', 'images/광화문집_236.jpg', '김치찌개로 유명한 식당. 묵은 김치와 생목살을 넣고 끓인 김치찌개는 얼큰하면서도 시원. 매운맛을 완화시켜줄 메뉴는 고소한 계란말이. 오래된 음식점 특유의 편안한 분위기.\n\n김치찌개로 유명한 식당. 묵은 김치와 생목살을 넣고 끓인 김치찌개는 얼큰하면서도 시원합니다. 매운맛을 완화시켜줄 메뉴는 고소한 계란말이로 함께 시켜 먹기 좋습니다. 오래된 음식점 특유의 편안한 분위기가 있습니다.', 37.571374, 126.974983, '1만원대', '지하철 5호선 광화문역 8번 출구, 60m', '김치찌개, 계란말이, 김치찌개, 제육볶음', '월요일~일요일', '', '음식점', '', '09:00 ~ 22:00', '02-739-7737', '명절 휴무'),
	(237, '순희네빈대떡', '03195  서울특별시 종로구 종로32길 5 (종로5가)', 'images/순희네빈대떡_237.jpg', '매장 한 쪽에서 맷돌을 사용하여 녹두가루를 만드는 녹두빈대떡\n\n매장 한 쪽에서 맷돌을 사용하여 녹두가루를 만들어 부치어 더욱 고소합니다. 녹두빈대떡과 고기완자 메뉴가 있습니다.', 37.570627, 127.000734, '', '지하철 1호선 종로5가역 8번 출구, 136m', '빈대떡', '수요일 ~ 월요일', ' http://빈대떡.kr/', '음식점', '', '11:00~21:00', '02-2264-5057', '화요일, 명절 휴무'),
	(238, '더레스토랑', '03053  서울특별시 종로구 삼청로 54 (소격동)', 'images/더레스토랑_238.jpg', '일본식 프랑스 요리를 맛볼 수 있는 곳으로 깔끔한 맛과 데코레이션으로 유명\n\n일본식 프랑스 요리를 맛볼 수 있는 곳으로 깔끔한 맛과 데코레이션으로 유명합니다. 경복궁이 내려다 보이는 창가 자리는 관광객뿐만 아니라 한국인들에게도 인기가 습니높다. 디저트 카페를 함께 합니다.', 37.580721, 126.980574, '', '지하철 3호선 안국역 2번 출구, 789m', '시푸드토마토파스타, 그린티케이크', '', ' http://therestaurant.co.kr/', '음식점', '1층 카페는 주말에만 브레이크 타임이 있습니다 (브레이크타임 15:00~18:00)', '매일 10:00 ~ 22:00 1F 카페\n매일 12:00 ~ 15:00 / 18:00 ~ 22:00 2F 레스토랑', '02-735-8441', '매주 일,월'),
	(239, '대장장이화덕피자집', '03056  서울 종로구 북촌로 42-4 (가회동)', 'images/대장장이화덕피자집_239.jpg', '화덕에 구운 담백한 피자 맛으로 유명세를 타는 곳.\n\n화덕에 구운 담백한 피자 맛으로 유명세를 타는 곳. 좋은 재료를 아낌없이 듬뿍 담은 피자를 맛볼 수 있습니다. 주말과 공휴일은 하루 전에 예약해야 합니다.', 37.580563, 126.985348, '', '지하철 3호선 안국역 2번 출구, 424m', '마르게리따, 고르곤졸라, 루꼴라 피자, 감베리 피자', '', '', '음식점', '', '평일 11:30~15:00, 17:00~21:00 / 주말 11:30~15:00, 16:30~21:00', '0507-1315-4298', ''),
	(240, '여의도양지탕', '07238  서울특별시 영등포구 국회대로70길 7 (여의도동)', 'images/여의도양지탕_240.jpg', '양지 고기를 넣고 끓인 양지설렁탕이 유명한 집. 김치 맛도 일품.\n\n양지 고기를 넣고 끓인 양지설렁탕이 유명한 집입니다. 김치 맛도 일품이며 국수사리는 무한 리필됩니다. 수육을 곁들이면 더욱 좋으며, 삼겹살 구워 먹기에도 좋습니다.', 37.529995, 126.919907, '', '지하철 9호선 국회의사당역 1번 출구, 244m', '한식(양지탕,모듬수육,삼겹살)', '매일', '', '음식점', '', '09:00~21:00', '02-784-0065', '명절 휴무'),
	(241, '목련식당', '06049  서울 강남구 도산대로30길 15', 'images/목련식당_241.jpg', '20년 넘게 누룽지 정식을 파는 곳으로, 가정식 백반, 누룽지 정식, 고기. 곁들여 나오는 20여 가지의 찬. 점심시간에는 밥과 죽을 함께.\n\n20년 넘게 누룽지 정식을 파는 곳으로, 가정식 백반, 누룽지 정식, 고기류 등이 유명합니다. 곁들여 나오는 20여 가지의 찬이 모두 맛있습니다. 점심시간에는 밥과 죽을 같이 줍니다.', 37.518215, 127.030097, '1만원대', '지하철 7호선 학동역 8번 출구, 598m', '누룽지정식, 오징어볶음, 굴전', '매일', '', '음식점', '', '', '02-541-5858', '연중무휴'),
	(242, '은주정', '04546  서울 중구 창경궁로8길 32 (주교동)', 'images/은주정_242.jpg', '삼겹살을 구워 먹으면 김치찌개를 푸짐하게 갖다 주는 것이 특징. 메뉴는 두 가지. 푸짐하게 나오는 쌈 채소와 칼칼한 김치.\n\n삼겹살을 구워 먹으면 김치찌개를 푸짐하게 갖다 주는 것이 특징입니다. 메뉴는 두 가지뿐입니다. 푸짐하게 나오는 쌈 채소와 칼칼한 김치가 괜찮습니다.', 37.568682, 126.999757, '1만원대', '지하철 2/5호선 을지로4가역 4번 출구, 222m', '삼겹살\n생고기김치찌개\n생삼겹살', '월요일 ~ 토요일', ' https://www.instagram.com/eunjujeong1986', '음식점', '', '10:00 ~ 22:00', '0507-1406-4669', '매주 일요일 휴무, 명절 휴무'),
	(243, '서린낙지', '03157  서울특별시 종로구 종로 19 (종로1가)', 'images/서린낙지_243.jpg', '매운 맛을 즐기는 사람이라면 도전해볼만한 낙지전문점.\n\n매운 맛을 즐기는 사람이라면 도전해볼만한 곳입니다. 낙지볶음이 너무 맵다면, 낙지 국물에 베이컨과 소시지를 철판에 익혀먹는 베이컨소시지를 추천합니다. 파전, 달걀말이, 조개탕 등 매운 맛을 완화시켜주는 다양한 메뉴도 마련되어 있습니다.', 37.570844, 126.979924, '', '지하철 1호선 종각역 1번 출구, 282m', '', '월화수목금토일', '', '음식점', '', '11:30 ~ 15:00 / 17:00 ~ 21:30', '02-735-0670', '매달 2,4번째 일요일 & 1,3번째 월요일 정기 휴무'),
	(244, '그릴아지사이', '06133  서울 강남구 테헤란로13길 8-10 (동영빌딩)', 'images/그릴아지사이_244.jpg', '일본인 조리장이 만들어 내는 일본 본토식 요리.\n\n일본인 조리장이 만들어 내는 일본 본토식 요리를 맛볼 수 있는 곳으로 큰 인기를 끌고 있습니다. 돈가스, 스키야키, 오므라이스 등의 점심 메뉴도 주변 직장인들에게 인기가 있어 점심때는 줄을 서야 합니다. 저녁때 이자카야 삼아 사케를 즐기기에 좋습니다.', 37.500356, 127.033248, '2만원대', '지하철 2호선 역삼역 4번 출구, 239m', '간바레오또상SET, 시로미, 돈샤브 샐러드, 가이센동', '월요일~금요일', '', '음식점', '', '11:30~14:00, 17:30~23:00', '02-565-7442', '매주 토요일, 일요일'),
	(245, '청담골', '06064  서울 강남구 선릉로148길 48 (청담동, 미준빌딩)', 'images/청담골_245.jpg', '구수한 누룽지 백반으로 이름난 곳. 김치찌개, 계란찜, 게장, 나물 등 10가지가 넘는 밑반찬.\n\n구수한 누룽지 백반으로 이름난 곳입니다. 큼직한 대접에 가득 담겨 나오는 누룽지는 적당히 끓여져 나옵니다. 김치찌개, 계란찜, 게장, 나물 등 10가지가 넘는 밑반찬도 훌륭합니다. 밥집을 찾기 어려운 청담동에서 편하게 식사할 수 있는 곳입니다.', 37.522768, 127.043406, '', '지하철 7호선/수인분당선 강남구청역 4번 출구, 797m', '일반한식', '월요일~일요일', '', '음식점', '', '10:30 ~ 16:00 / 17:00 ~ 21:50', '02-543-1252', '명절 휴무'),
	(246, '파크루안 역삼점', '06223  서울특별시 강남구 논현로 430 (역삼동)  아세아빌딩 지하 1층', 'images/파크루안_역삼점_246.jpg', '현대적인 것과 고풍스러운 느낌이 잘 어우러진 분위기. 격조 있는 정통 중국 요리.\n\n현대적인 것과 고풍스러운 느낌이 잘 어우러진 분위기에서 격조 있게 정통 중국 요리를 즐길 수 있는 곳입니다. 가족 모임이나 손님 접대에도 좋습니다.', 37.499001, 127.038355, '2만원대', '지하철 2호선 역삼역 1번 출구, 189m', '웰빙삼선콩자장면, 왕갈비짬뽕, 찹쌀탕수육, 잡채밥', '', ' http://www.parkruan.com/', '음식점', '', '매일 11:30 ~ 22:00\n(평일 Break time 15:00 ~ 17:30)', '0507-1424-5565', '연중무휴'),
	(247, '성산왕갈비', '03936  서울특별시 마포구 월드컵북로 233 (성산동, 성산시영아파트)', 'images/성산왕갈비_247.jpg', '푸짐한 생돼지갈비로 유명. 돼지갈비 맛도 좋으며 양도 푸짐하여 인기있는 곳. 갈비와 함께 먹는 계란찜과 된장찌개도 별미.\n\n푸짐한 생돼지갈비로 유명합니다. 돼지갈비 맛도 좋으며 양도 푸짐하여 인기있는 곳입니다. 갈비와 함께 먹는 계란찜과 된장찌개도 별미입니다.', 37.569732, 126.903136, '', '지하철 6호선 월드컵경기장역 2번 출구, 435m', '', '매일', '', '음식점', '', '평일 12:00~15:00, 17:00~21:00 / 주말 12:00~21:00', '02-306-2001', '연중무휴'),
	(248, '영양센터', '04535  서울 중구 명동2길 52 (충무로1가, 대용빌딩)', 'images/영양센터_248.jpg', '전기구이 통닭의 원조. 전기구이로 기름기를 뺀 통닭은 겉은 바삭하게 구워져 고소하고 속은 담백.\n\n전기구이 통닭의 원조라 할만한 음식점. 전기구이로 기름기를 뺀 통닭은 겉은 바삭하게 구워져 고소하고 속은 담백하면서도 부드럽습니다. 식사로도 좋지만 맥주와 함께 먹는 것을 추천합니다.', 37.561111, 126.983123, '1만원대', '지하철 4호선 명동역 5번 출구, 171m', '전기구이통닭', '월요일~일요일', '', '음식점', '', '10:30 ~ 22:30', '02-776-2015', '명절 휴무'),
	(249, '파올로데마리아', '03723  서울 서대문구 연희로26길 24 (연희동)  1층', 'images/파올로데마리아_249.jpg', '이탈리안 레스토랑 보나세라의 총괄 셰프가 자신의 이름을 걸고 오픈한 레스토랑\n\n이탈리안 레스토랑 보나세라의 총괄 셰프였던 파울로 데 마리아가 자신의 이름을 걸고 오픈한 첫 번째 레스토랑입니다. 파인 트라토리아를 표방하고 있습니다. 셰프의 섬세함이 담겨 있는 요리와 디저트 등이 만족스럽습니다. 테라스도 딸린 실내 분위기가 모던합니다. 코스 외에 단품도 많이 준비되어 있습니다.', 37.572756, 126.936891, '', '', '레몬크림 새우 가레띠 생면파스타, 갑오징어 딸리아텔레, 카라바조코스', '', ' https://blog.naver.com/paolodemaria3', '음식점', '', '11:30~15:00, 17:30~22:00', '0507-1312-9936', ''),
	(250, '가미우동', '04055  서울 마포구 홍익로2길 23 (서교동)', 'images/가미우동_250.jpg', '가게에서 직접 손으로 우동면을 뽑아서 쓰는 우동전문점.\n\n가게에서 직접 손으로 우동면을 뽑아서 쓰는 우동전문점. 수타면의 쫄깃한 식감과 시원한 국물맛으로 유명합니다. 바삭하게 튀겨낸 닭튀김과 우동이 함께 나오는 세트는 매우 든든한 한 끼를 맛볼 수있습니다. 실내는 깔끔하고 모던합니다.', 37.554688, 126.923862, '1만원대', '지하철 2호선/ 경의중앙선/ 공항철도 홍대입구역 9번 출구, 269m', '붓가께 우동, 새우튀김, 가께우동 와카메우동', '', '', '음식점', '', '화요일~일요일 11:15 ~ 15:00 / 17:00 ~ 20:30', '02-322-3302', '매주 월요일 휴무'),
	(251, '무등산', '06062  서울 강남구 선릉로146길 3 (청담동, 승봉빌딩)', 'images/무등산_251.jpg', '소고기 구이로 유명한 고기집. 메뉴가 다양하고 전체적으로 맛이 좋지만 특히 꽃등심이 인기.\n\n소고기 구이로 유명한 고기집. 메뉴가 다양하고 전체적으로 맛이 좋지만 특히 꽃등심이 인기입니다. 질 좋은 고기를 엄선해서 부드러운 고기 맛을 유지하는 것이 인기비결. 반찬과 냉면도 맛있고, 분위기도 좋습니다.', 37.521962, 127.039943, '', '지하철 7호선/수인분당선 강남구청역 3-1번 출구, 541m', '', '월요일~토요일', ' http://www.moodeungsan.com', '음식점', '', '월요일~토요일 10:00~24:00', '0507-1409-4017', '매주 일요일 ,연중무휴'),
	(252, '뱃고동', '06018  서울 강남구 언주로172길 54 (신사동)', 'images/뱃고동_252.jpg', '오징어 불고기의 원조격으로, 평일에도 줄 서서 기다려야 할 정도로 인기 있는 곳. 매콤하면서도 달콤한 낙지와 오징어. 다 먹은 후에는 볶음밥.\n\n오징어 불고기의 원조격으로, 평일에도 줄 서서 기다려야 할 정도로 인기 있는 곳입니다. 매콤하면서도 달콤한 낙지와 오징어의 맛이 좋습니다. 다 먹은 후에는 밥을 볶아 먹습니다.', 37.526843, 127.038033, '1만원대', '지하철 수인분당선 압구정로데오역 5번 출구, 264m', '오징어불고기백반\n낙지불고기백반\n낙지전골\n오징어전골', '', ' http://www.batgodong.co.kr/', '음식점', '', '11:30 ~ 21:30', '02-514-8008', '명절 휴무'),
	(253, '경기떡집', '04013  서울 마포구 동교로9길 24 (망원동)', 'images/경기떡집_253.jpg', '최연소 떡 명장이 개발한 이북식 인절미, 이티떡\n\n1958년부터 종로 흥인제분소에서 시작된 가게의 역사가 망원동으로 이전해 이어지고 있습니다. 경기떡집의 창업주인 아버지의 떡 제조 기술을 이어받은 그의 아들들이 2대째 운영 중이며, 아들 중 한 명은 최연소 떡 명장 타이틀을 갖고 있습니다. 대표상품은 ‘이티떡’이로 이북식 인절미인데, 앙금이 떡을 두르고 있는 독특한 모양이 인상적입니다. 전통을 고수하고 이어가는 것을 목표로 현대인이 가볍게 즐길 수 있는 건강한 디저트로 떡을 연구하고 있습니다.', 37.555044, 126.910304, '', '지하철 6호선 망원역 2번 출구, 170m', '이티떡, 흑임자인절미, 설기', '월요일~토요일', ' https://www.kricecake.com/', '카페, 디저트', '', '07:00~18:00', '02-333-8880', '일요일'),
	(254, '이비스스타일 앰배서더 명동 르스타일 레스토랑&바', '04553  서울 중구 삼일대로 302 (충무로2가)  21층', 'images/이비스스타일_앰배서더_명동_르스타일_레스토랑&바_254.jpg', '도심 전경과 석양, 야경을 한눈에 담아내는 루프탑\n\n이비스스타일 앰배서더 명동 르스타일 레스토랑&바는 도심 전경과 석양, 야경을 한눈에 담아내는 루프탑 공간으로, 서울의 매력을 가장 생생하게 느낄 수 있습니다.', 37.561682, 126.989389, '', '지하철 4호선 명동역 10번 출구, 161m', '', '', ' https://www.ambatel.com/ibisstyles/myeongdong/ko/main.do', '음식점', '', '조식 07:30~ 10:00\n중식 12:00 ~ 14:30\n석식 18:00 ~ 22:30', '02-6020-8880', ''),
	(255, '전골목', '04214  서울 마포구 만리재로 19 (공덕동, 공덕시장)', 'images/전골목_255.jpg', '공덕시장 내 족발골목 바로 옆에 위치한 전골목은 MBC 예능 프로그램 <무한도전>에 나온 이후 더욱 유명.\n\n공덕시장 내 족발골목 바로 옆에 위치한 전골목은 MBC 예능 프로그램 <무한도전>에 나온 이후 더욱 유명해졌습니다. 진열된 전과 튀김을 바구니에 담아 무게만큼 돈을 지급한 후 안쪽의 자리에 앉아 식사할 수 있습니다. 시중에서 흔히 볼 수 있는 튀김을 비롯해 대하튀김, 감자말이새우튀김, 새우부추전, 표고전 등 다양한 튀김과 전을 판매합니다.', 37.544795, 126.953258, '', '지하철 5호선/6호선/공항철도/경의중앙선 공덕역 4번 출구, 195m', '', '', '', '음식점', '', '점포별 상이', '', ''),
	(256, '나리의집', '04348  서울 용산구 이태원로 245 (한남동)', 'images/나리의집_256.jpg', '삼겹살과 청국장이 맛있기로 유명한 곳. 특히 삼겹살과 함께 먹는 파절이의 맛이 일품.\n\n삼겹살과 청국장이 맛있기로 유명한 곳. 특히 삼겹살과 함께 먹는 파절이의 맛이 일품입니다. 점심, 저녁시간에는 항상 사람들로 붐비기 때문에 여유있게 먹고 싶다면 식사시간을 피해 가는 곳이 좋습니다.', 37.536908, 127.000040, '1만원대', '지하철 6호선 한강진역 1번 출구, 414m', '삼겹살, 청국장', '월요일~일요일', '', '음식점', '', '월요일~토요일 14:00 ~ 24:00\n일요일 16:00 ~ 24:00', '02-793-4860', '매월 둘째, 넷째 일요일 및 명절 휴무'),
	(257, '나마스테', '03114  서울특별시 종로구 지봉로 18 (숭인동)', 'images/나마스테_257.jpg', '네팔과 인도 음식 전문점. 채식주의자를 위한 베지런치 메뉴.\n\n네팔과 인도 음식 전문점. 채식주의자를 위해믹스 베지커리나 팔락파니르를 맛볼 수 있는 베지런치 메뉴가 있습니다. 인도레스토랑 중 비교적 가격이 저렴한 편입니다.', 37.571740, 127.015984, '1만원대', '지하철 1/6호선 동묘앞역 5번 출구, 14m', '커리, 탄두리치킨, 라씨, 램마크니, 달밧탈커리', '', '', '음식점', '', '매일 11:00 ~ 23:00', '02-2232-2286', '연중무휴'),
	(258, '사랑방칼국수', '04555  서울 중구 퇴계로27길 46', 'images/사랑방칼국수_258.jpg', '50년 역사의 칼국숫집. 멸치 육수에 말아내는 칼국수. 통닭백숙은 닭고기를 특제 소스에 찍어 먹는 맛이 일품.\n\n50년 역사의 칼국숫집. 멸치 육수에 말아내는 칼국수가 옛맛을 느끼게 해 줍니다. 통닭백숙은 닭고기를 특제 소스에 찍어 먹는 맛이 일품입니다. 백숙백반을 주문하면 저렴한 가격에 백숙, 국물, 밥까지 먹을 수 있습니다.', 37.563258, 126.991335, '1만원대', '지하철 3/4호선 충무로역 6번 출구, 336m', '칼국수, 닭곰탕, 백숙백반, 통닭 백숙', '', '', '음식점', '', '평일 10:30~21:40\n토요일 10:30~21:00\n일요일 10:30~16:00', '02-2272-2020', '매달 첫번째 일요일'),
	(259, '뉘조', '03146  서울 종로구 인사동14길 27', 'images/뉘조_259.jpg', '야생초에 화학조미료를 쓰지 않고 요리하는 약선음식 전문점\n\n야생초에 화학조미료를 쓰지 않고 요리하는 약선음식 전문점입니다. 각종 나물을 효소에 절인 생감자에 싸먹는 근채쌈, 연근, 고구마, 단호박을 갈아 뽕잎에 싸먹는 뿌리범벅 등 메뉴들로 이뤄져 있습니다.', 37.575138, 126.985353, '', '지하철 3호선 안국역 6번 출구, 188m', '우슬초, 익모초, 구절초, 싱아', '', ' http://www.newijo.com/', '음식점', '', '화요일~금요일 11:30~15:30, 17:00~21:30 / 토요일~일요일 11:30~21:00', '0507-1497-9303', '매주 월요일'),
	(260, '아티제 삼성타운점', '06620  서울 서초구 서초대로74길 11 (서초동, 삼성전자빌딩)', 'images/아티제_삼성타운점_260.jpg', '유럽형 카페 베이커리 아티제의 도산공원 분점. 유러피안 스타일의 빵과 간단한 샐러드와 파스타. 이탈리아의 파니니, 치아바타 샌드위치와 프랑스의 바게트 샌드위치.\n\n유럽형 카페 베이커리 아티제의 삼성타운점. 유러피안 스타일의 빵과 간단한 샐러드와 파스타를 즐길 수 있습니다. 이탈리아의 파니니, 치아바타 샌드위치와 프랑스의 바게트 샌드위치가 준비되어 있습니다.', 37.496633, 127.026915, '', '지하철 2호선 /신분당선 강남역 6번 출구, 113m', '', '', ' https://www.cafeartisee.com/', '카페, 디저트', '', '토요일~일요일 09:00~21:00', '02-598-0017', '명절 휴무'),
	(261, '할머니칼국수', '03133  서울특별시 종로구 돈화문로11다길 14-2 (돈의동)', 'images/할머니칼국수_261.jpg', '멸치 육수를 사용한 칼국수로 유명한 집. 저렴한 가격. 칼국수에 수제비를 약간 넣어주는 것이 특징. 칼제비라고 칼국수와 수제비가 섞어서 나오는 메뉴.\n\n멸치 육수를 사용한 칼국수로 유명한 집. 저렴한 가격으로 더 유명합니다. 칼국수에 수제비를 약간 넣어주는 것이 특징입니다. 칼제비라고 칼국수와 수제비가 섞어서 나오는 메뉴(칼제비)도 있습니다.', 37.572837, 126.990783, '1만원대', '지하철 1/3/5호선 종로3가역 6번 출구, 83m', '칼국수', '매일', '', '음식점', '', '11:00 ~ 20:00 (재료 소진 시 마감)', '02-744-9548', '명절 휴무'),
	(262, '대련집', '03191  서울 종로구 종로16길 37 (관수동)', 'images/대련집_262.jpg', '사골로 우려낸 진한 칼국수가 주메뉴이지만 보쌈, 홍어찜, 파전 등 다양한 한식 . 내국인, 외국인 모두에게 인기.\n\n사골로 우려낸 진한 칼국수가 주메뉴이지만 보쌈, 홍어찜, 파전 등 다양한 한식 메뉴도 구비하고 있습니다. 내국인, 외국인 모두에게 인기가 좋습니다. 술과 각종 안주률 곁들인 후 칼국수로 깔끔하게 마무리하는 코스가 가장 무난합니다.', 37.568432, 126.989092, '', '지하철 1/ 3/ 5호선 종로3가역 15번 출구, 405m', '칼국수, 생배추보쌈, 모듬전, 홍오찜', '월요일~토요일', '', '음식점', '', '11:00~14:30, 17:00~21:30', '02-2265-5349', '일요일 휴무'),
	(263, '역삼동북어집', '06237  서울 강남구 논현로85길 5-14 (역삼동)', 'images/역삼동북어집_263.jpg', '맵고 칼칼한 북어찜을 맛볼 수 있는 곳. 점심때는 북어찜 백반. 국물이 많은 북어찜 스타일로, 해장용.\n\n맵고 칼칼한 북어찜을 맛볼 수 있는 곳. 점심때는 북어찜 백반 한 가지만 가능합니다. 국물이 많은 북어찜 스타일로, 해장용으로도 많이 찾습니다. 가격도 비교적 저렴한 편. 저녁때는 북어찜이나 북어구이를 안주 삼아 술 한잔하기 좋습니다.', 37.498589, 127.036730, '1만원대', '지하철 2호선 역삼역 3번 출구, 312m', '북어찜, 북어구이, 북어찜백반', '화요일 ~ 일요일', '', '음식점', '', '화요알~금요일 10:00~20:30, 토요일~일요일 08:40~20:00', '02-558-6605', '매주 월요일'),
	(264, '레더라', '04520  서울 중구 세종대로 136 (파이낸스빌딩)  지하 1층', 'images/레더라_264.jpg', '80년 역사의 스위스 초콜릿의 서울 분점. 다양한 필링을 넣어 만든 초콜릿은 물론, 무설탕 초콜릿도 준비. 가격이 다소 높긴 하지만 제대로 된 초콜릿을 즐길 수 있는 곳.\n\n80년 역사의 스위스 초콜릿의 서울 분점. 다양한 필링을 넣어 만든 초콜릿은 물론, 무설탕 초콜릿도 준비되어 있습니다. 가격이 다소 높긴 하지만 제대로 된 초콜릿을 즐길 수 있는 곳입니다.', 37.568423, 126.978257, '1만원대', '지하철 5호선 광화문역 5번 출구, 169m', '초콜릿', '월요일~일요일', ' https://kr.laderach.com/', '카페, 디저트', '', '평일 9:00~22:00\n주말,공휴일 11:30~22:00', '02-3789-3245', '명절 휴무'),
	(265, '용금옥', '03036  서울특별시 종로구 자하문로 41-2 (통인동)', 'images/용금옥_265.jpg', '미쉐린 가이드 서울 2022에 등재된 추어탕 맛집 용금옥.\n\n1932년에 영업을 개시한 오랜 전통의 추어탕 전문점 용금옥. 서울식 통추어탕과 삶은 미꾸라지를 갈아 넣은 남도식 추어탕을 판매하며, 좋은 재료로 정성껏 준비하는 모든 음식에는 용금옥 주인장의 애정 어린 손맛이 고스란히 담겨있습니다.', 37.579773, 126.970907, '1만원대', '지하철 3호선 경복궁역 2번출구, 398m', '서울추어탕, 미꾸라지부침, 모둠전, 추어튀김, 탕평채', '월요일~토요일', ' http://www.yonggeumok.co.kr', '음식점', '', '월요일~금요일 11:30 ~ 15:00 / 17:00 ~ 21:05\n토요일 11:30 ~15:00/17:00~ 20:00', '02-777-4749', '일요일'),
	(266, '란나타이', '07333  서울 영등포구 국제금융로 86 (여의도동, 롯데캐슬 아이비)', 'images/란나타이_266.jpg', '저렴하면서도 깔끔한 태국 음식을 즐길 수 있는 곳.\n\n저렴하면서도 깔끔한 태국 음식을 즐길 수 있는 곳. 태국 현지인이 주방을 맡고 있으며 실내 인테리어도 깨끗합니다.', 37.520206, 126.931800, '1만원대', '지하철 9호선/신림선 샛강역 2번 출구, 381m', '팟시유, 카오 팟 푸, 톰양쿵', '', '', '음식점', '', '월요알~토요알 11:30~15:00, 17:00~21:30', '02-782-8284', '매주 일요일 휴무'),
	(267, '대치정육식당', '06201  서울 강남구 역삼로 450 (대치동)', 'images/대치정육식당_267.jpg', '정육점을 겸한 식당으로, 제비추리, 안창살, 토시살과 치마살이나 안창살 맛이 일품.\n\n정육점을 겸한 식당으로, 제비추리, 안창살, 토시살 등이 나오는 특수 부위가 권할 만하며, 그 외에도 치마살이나 안창살 맛이 일품입니다. 돼지고기로는 가브리살, 항정살 등이 좋습니다. 다른 반찬들은 거의 없이 고기로만 승부하는 집입니다.', 37.502217, 127.056438, '', '지하철 2호선/ 수인분당선 선릉역 1번 출구, 889m', '생등심, 육회, 특수부위, 차돌박이', '', '', '음식점', '', '매일 11:30 ~ 22:30', '02-557-0883', ''),
	(268, '오선채', '06738  서울특별시 서초구 남부순환로 2634-8 (양재동)  단성빌딩', 'images/오선채_268.jpg', '어릴 적 어머니가 해주시던 그 맛 그대로 담아낸 오선채의 맛깔나는 한정식은 추억을 떠올리게 하는 맛.\n\n어릴 적 어머니가 해주시던 그 맛 그대로 담아낸 오선채의 맛깔나는 한정식은 추억을 떠올리게 하는 맛입니다.', 37.484565, 127.038638, '', '지하철 3호선/신분당선 양재역 5번 출구, 327m', '오선채 한정식, 오선채 돌솥밥 한정식, 오선채 간장게장정식', '', '', '음식점', '', '매일 11:30~15:00 / 17:00~21:00', '02-578-9411', '명절 휴무'),
	(269, '한일관', '06023  서울특별시 강남구 압구정로38길 14 (신사동)', 'images/한일관_269.jpg', '종로에서 불고기 전문점으로 이름을 날렸던 곳으로, 현재는 한정식집.\n\n종로에서 불고기 전문점으로 이름을 날렸던 곳으로, 현재는 한정식도 겸하고 있습니다. 불고기나 갈비 등의 점심 세트메뉴가 경쟁력 있습니다.', 37.527783, 127.032497, '', '지하철 3호선 압구정역 2번 출구, 459m', '점심상차림 전통구이상차림 큰상차림', '월요일~일요일', ' http://www.hanilkwan.co.kr', '음식점', '', '평일 11:30 ~ 21:30\n주말 11:00 ~ 21:30', '1577-9963', '명절 당일 휴무'),
	(270, '백암왕순대', '03703  서울 서대문구 증가로 13-6', 'images/백암왕순대_270.jpg', '평안도식 순대를 맛볼 수 있는 곳.\n\n평안도식 순대를 맛볼 수 있는 곳. 이북 지방에서 순대를 만들 때 흔히 쓰는 선지 대신 당면과 두부, 고사리 등 30여 가지 다양한 채소를 넣어 만듭니다. 돼지 한 마리에 한 접시 분만 나오는 막창을 사용해 만든 왕순대가 있으며, 소장을 쓴 토종순대는 곱창을 이용해서 껍질이 얇고 가늡니다. 왕순대에 머리 고기를 섞은 모둠순대는 술안주로 좋습니다.', 37.569373, 126.931072, '1만원대', '지하철 2호선/경의중앙선/공항철도 홍대입구역 3번 출구, 7612번 ,7734번, 7739번 버스 탑승, \'연희동자치회관\'하자, 187m', '순대국, 모둠수육, 왕순대, 얼큰이탕', '', '', '음식점', '', '매일 09:30~20:30(브레이크타임 16:00~17:00)', '02-337-7894', '명절 당일 휴무'),
	(271, '하나로회관', '03162  서울 종로구 인사동5길 25 (인사동, 하나로빌딩)', 'images/하나로회관_271.jpg', '우리민족 고유의 전통 음식을 지켜가고자 하는 하나로회관은 종로구 인사동에서 2대째 이어온 28년 전통의 한정식집.\n\n우리민족 고유의 전통 음식을 지켜가고자 하는 하나로회관은 종로구 인사동에서 2대째 이어온 28년 전통의 한정식 한식집입니다.', 37.572102, 126.985422, '', '지하철 1호선 종각역 3번 출구, 287m', '', '월요일~토요일', '', '음식점', '', '11:30 ~ 15:00 / 17:00 ~ 21:00', '02-732-7451', '매주 일요일 휴무'),
	(272, '마전터', '02880  서울 성북구 혜화로 82-2', 'images/마전터_272.jpg', '예전부터 인기 좋은 소고기국반(육개장)집. 보리밥, 보쌈. 마전터는 성북동의 옛 이름.\n\n예전부터 인기 좋은 소고기국반(육개장)집. 보리밥, 보쌈도 인기가 좋습니다. 마전터는 성북동의 옛 이름. 추운 날에 따뜻하고 시원한 국물의 국밥을 맛볼 수 있습니다. 신선하고 질 좋은 양지머리에 콩나물을 듬뿍 넣어 시원한 맛을 냅니다.', 37.592510, 126.998774, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 822m', '쇠고기국밥, 간장꽃게장과 알밥', '', '', '음식점', '', '월요일~금요일 10:00~24:00\n토요일 10:00~21:00', '02-765-7575', '매주 일요일'),
	(273, '케익하우스윈 (윈제과점)', '06067  서울 강남구 삼성로 719 (청담동, 경덕빌딩)', 'images/케익하우스윈_(윈제과점)_273.jpg', '20년 넘은 역사를 지닌 한국의 옛날 빵들을 맛볼 수 있는 가게. 아이스크림 모나카도 인기.\n\n20년 넘은 역사를 지닌 가게로 한국의 옛날 빵들을 맛볼 수 있습니다. 아이스크림 모나카도 인기가 많습니다.', 37.519985, 127.049268, '', '지하철 7호선 청담역 8번 출구, 114m', '베이커리', '월요일~일요일', '', '카페, 디저트', '', '08:00 ~ 22:00', '02-546-1585', '연중무휴'),
	(274, '오월의종', '04348  서울 용산구 이태원로45길 34 (한남동)', 'images/오월의종_274.jpg', '천연발효종을 사용한 빵으로 유명. 적당한 가격에 질과 양 모두를 만족. 이태원에 있는 많은 레스토랑이 이 가게의 빵을 신뢰함.\n\n천연발효종을 사용한 빵으로 유명합니다. 적당한 가격에 질과 양 모두를 만족시킵니다. 이태원에 있는 많은 레스토랑이 이 가게의 빵을 사용할 정도로 신뢰받고 있습니다.', 37.536610, 126.997846, '', '지하철 6호선 이태원역 2번 출구, 655m', '베이커리', '화요일~토요일', '', '카페, 디저트', '', '11:00 ~ 18:00', '0507-1332-9481', '매주 일요일, 월요일, 명절 휴무'),
	(275, '풀향기손칼국수', '07328  서울 영등포구 여의나루로 42 (여의도종합상가)', 'images/풀향기손칼국수_275.jpg', '20여 년 전통의 손칼국수 집. 손으로 직접 썰어서 만든 칼국수 면이 부들부들하면서도 쫄깃.\n\n20여 년 전통의 손칼국수 집. 손으로 직접 썰어서 만든 칼국수 면이 부들부들하면서도 쫄깃합니다. 새우살과 조갯살이 듬뿍 든 해물파전도 추천 메뉴입니다. 매일 담그는 보쌈김치가 곁들여져 나오는 돼지고기 보쌈도 별미입니다.', 37.521435, 126.924922, '', '지하철 5/9호선 여의도역 5번 출구, 12m', '바지락칼국수, 해물파전, 풀향기보쌈, 모둠보쌈', '', '', '음식점', '', '10:00~14:30, 16:30~22:00', '02-761-0357', '주말, 명절 휴무'),
	(276, '능라밥상', '03026  서울 종로구 사직로2길 14 (행촌동, 권율장군집터)', 'images/능라밥상_276.jpg', '능라밥상은 북한에서 남한으로 넘어온 사장님이 직접 운영하는 북한음식 전문점.\n\n능라밥상은 북한에서 남한으로 넘어온 사장님이 직접 운영하는 북한음식 전문점입니다. 한국에서는 상대적으로 덜 알려진 개성무찜, 어복쟁반, 평양온반등 북한의 음식문화를 대중에게 알리기 위해 문을 열었다고 합니다.', 37.572941, 126.964004, '', '지하철 3호선 독립문역 3번 출구, 553m', '평양냉면, 평양온반, 어복쟁반,', '', ' https://blog.naver.com/reeran2000', '음식점', '', '11:00-15:00, 16:00-21:00', '02-747-9907', ''),
	(277, '진사댁', '04536  서울특별시 중구 명동길 30-1 (명동2가)', 'images/진사댁_277.gif', '번화가의 분주함들 사이에 한옥을 머리에 이고 하늘과 조화를 이루고 있는 진사댁은, 각 지방의 대표적인 전통 음식을 경험할 수 있는 한국 전통음식점.\n\n번화가의 분주함들 사이에 한옥을 머리에 이고 하늘과 조화를 이루고 있는 진사댁은, 각 지방의 대표적인 전통 음식을 경험할 수 있는 한국 전통음식점입니다.', 37.563470, 126.984038, '', '지하철 4호선 명동역 6번 출구, 347m', '한정식', '월요일~일요일', '', '음식점', '', '11:30 ~ 22:00', '02-774-9605', '명절 휴무'),
	(278, '소문난집추어탕(소문난 해장국)', '03140  서울특별시 종로구 수표로 131 (낙원동)', 'images/소문난집추어탕(소문난_해장국)_278.jpg', '해장국 하나만으로 50여 년 동안 명성을 이어가는 곳.\n\n소문난집추어탕에는 추어탕이 없습니다. 해장국 하나만으로 50여 년 동안 명성을 이어가는 곳. 예전에는 추어탕도 팔았지만, 지금은 상호와 상관없이 해장국인 우거지 얼큰탕만 팔고 있습니다. 들어가면 주문도 필요없이 사람 숫자만 말하면 음식이 나옵니다.', 37.572494, 126.988260, '1만원대', '지하철 1/3/5호선 종로3가역 5번 출구, 62m', '우거지얼큰탕 3,000', '월요일~일요일', '', '음식점', '', '04:20~21:30', '02-742-1633', '명절 휴무'),
	(279, '백리향', '07345  서울 영등포구 63로 50 (63한화생명빌딩)  57층', 'images/백리향_279.jpg', '초고층 전망과 고급스러운 실내 장식. 정중한 서비스의 정통 스타일 중식.\n\n초고층의 빼어난 전망과 고급스러운 실내 장식, 그리고 정중한 서비스는 식사의 분위기를 높여 줍니다. 정통 스타일의 중식을 즐길 수 있는 곳으로 비즈니스나 상견례 장소로도 인기가 높습니다.', 37.519664, 126.939909, '', '지하철 9호선 샛강역 3번 출구, 1.2km', '', '', ' https://www.63restaurant.co.kr/introduction/introduction.r63?shop_idrest=31020', '음식점', '', '매일 11:30 ~ 15:00 / 17:30 ~ 21:30', '0507-1333-5741', '연중무휴'),
	(280, '라쿠치나', '04346  서울 용산구 회나무로44길 10 (라쿠치나)', 'images/라쿠치나_280.jpg', '고급스러운 인테리어가 돋보이는 곳. 한국에 정통 이탈리안 스타일을 처음 도입한 곳\n\n고급스러운 인테리어가 돋보이는 곳. 한국에 정통 이탈리안 스타일을 처음 도입한 곳으로 유명합니다. 격식 있는 코스요리를 즐길 수 있습니다. 남산 올라가는 길에 있어서 주변 풍경도 근사합니다. 2020년에 미쉐린 가이드에 선정되었습니다.', 37.540531, 126.996484, '', '지하철 6호선 이태원역 2번 출구, 1km', '', '월요일~토요일', ' http://www.la-cucina.co.kr', '음식점', '', '12:00~15:00, 17:00~21:30 19:30 라스트오더', '02-794-6006', '일요일'),
	(281, '일미장어', '04324  서울 용산구 후암로57길 35-15 (부곡목욕탕)', 'images/일미장어_281.jpg', '숯불에 구워 먹는 소금구이 장어만을 내는 곳\n\n연기와 냄새가 심해 보통 숯불을 쓰는 장어집이 드문데도 불구하고 숯불에 구워 먹는 소금구이 장어만을 내는 곳. 장어와 부추 절임, 양념장을 넣고 비벼 먹는 밥도 일품입니다. 손님이 항상 북적거리고 줄을 서는 곳이라 친절한 서비스는 기대하기 어렵습니다.', 37.552143, 126.974411, '3만원대', '지하철 1/ 4호선/공항철도/ 경의중앙선 서울역 12번 출구, 209m', '장어정식, 장어덮밥', '', '', '음식점', '', '월요일~토요일 11:30 ~ 13:30 / 17:30~21:00', '02-777-4380', '일요일, 명절 휴무'),
	(282, '태림산채정식', '01442  서울특별시 도봉구 노해로60길 32 (쌍문동)', 'images/태림산채정식_282.jpg', '건강식 산채나물과 뿌리 음식인 더덕, 도라지로 승부하는 집. 산채정식과 더덕구이 상차림에 함께 나옴.\n\n산채나물과 더덕 향기가 가득한 집\n\n건강식 산채나물과 뿌리 음식인 더덕, 도라지로 승부하는 집입니다. 산채정식과 더덕구이 상차림에 함께 나오는 목살구이와 산채나물을 함께 쌈 싸 먹으면 깊은 맛을 느낄 수 있습니다. 약수물로 담근 물김치는 톡 쏘는 맛이 일품입니다.', 37.649981, 127.034247, '', '지하철 4호선 쌍문역 4번 출구, 154m', '산채정식\n더덕구이\n태림특정식', '월요일 ~ 토요일', '', '음식점', '', '11:00 ~ 15:00 / 17:00 ~ 21:00', '02-998-5468', '일요일, 명절 당일'),
	(283, '목포자매집', '06107  서울 강남구 언주로115길 14', 'images/목포자매집_283.jpg', '해남 출신의 네 자매가 운영하는 남도 음식 전문점. 해남에서 올라오는 자연산 재료를 사용한 남도식 반찬. 점심때는 짱뚱어탕이 유명.\n\n해남 출신의 네 자매가 운영하는 남도 음식 전문점. 해남에서 올라오는 자연산 재료를 사용한 남도식 반찬이 맛있습니다. 점심때는 짱뚱어탕이 유명합니다.', 37.510085, 127.035333, '', '지하철 7호선 학동역 1번 출구, 640m\n지하철 9호선 언주역 3번 출구, 388m', '짱뚱어탕, 매생이국, 병어조림, 낙지연포탕, 민어, 병어', '월요일~토요일', '', '음식점', '', '평일 11:30 ~ 22:00\n토요일 11:30 ~ 21:00', '02-543-0729', '매주 일요일, 명절 휴무'),
	(284, '라세느', '04533  서울특별시 중구 을지로 30 (소공동)  롯데호텔서울 본관 1층', 'images/라세느_284.jpg', '새롭게 리뉴얼 오픈하면서 폭발적인 인기를 끄는 뷔페 레스토랑.\n\n새롭게 리뉴얼 오픈하면서 폭발적인 인기를 끄는 뷔페 레스토랑. 해산물 종류가 충실하고 즉석에서 구워주는 양갈비 스테이크 등 기존 호텔 뷔페 레스토랑과 비교하면 참신한 메뉴들이 돋보입니다.', 37.565346, 126.981008, '', '지하철 2호선 을지로입구역 8번 출구, 67m', '', '매일', ' https://www.lottehotel.com/seoul-hotel/ko/dining/restaurant-la-seine', '음식점', '', '07:00~21:30', '02-317-7171', '연중무휴'),
	(285, '쌍다리돼지불백', '02879  서울 성북구 성북로23길 4', 'images/쌍다리돼지불백_285.jpg', '2대째 운영하는 30여 년 전통의 식당. 연탄불에 구워져 나오는 고기.\n\n2대째 운영하는 30여 년 전통의 식당. 연탄불에 구워져 나오는 고기를 먹고자 많은 사람이 찾아옵니다. 자신이 직접 구워 먹는 맛을 즐길 수 없다는 것이 단점이기는 하지만, 오랜 시간 기다리지 않고 저렴한 가격에 즐길 수 있다는 것이 장점입니다.', 37.592266, 126.990294, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 1.1km', '돼지불백, 낚지볶음, 돼지불백비빔', '', ' https://www.instagram.com/ssangdari/', '음식점', '', '매일 09:00 - 21:00', '02-743-0325', '매주 월요일'),
	(286, '영동설렁탕', '06525  서울 서초구 강남대로101안길 24 (잠원동)', 'images/영동설렁탕_286.jpg', '30년 전통 손맛을 자랑하는 집. 설렁탕 한 그릇으로 승부하는 곳으로, 설렁탕 외의 메뉴는 수육 한 가지. 기름기가 싫거나 다이어트 중인 사람은 주문할 때 기름빼기 설렁탕을 주문.\n\n30년 전통 손맛을 자랑하는 집. 설렁탕 한 그릇으로 승부하는 곳으로, 설렁탕 외의 메뉴는 수육 한 가지뿐입니다. 기름기가 싫거나 다이어트 중인 사람은 주문할 때 기름빼기 설렁탕을 주문하면 됩니다.', 37.516153, 127.017366, '1만원대', '지하철 3호선/ 신분당선 신사역 5번 출구, 260m', '설렁탕, 수육', '매일', '', '음식점', '', '00:00~24:00', '02-543-4716', '연중무휴'),
	(287, '하쯔호', '07345  서울특별시 영등포구 여의동로 213 (여의도동)  지하1층', 'images/하쯔호_287.jpg', '좋은 재료를 사용하여 정성껏 만들어 내는 초밥.\n\n값비싼 생선을 사용한 초밥은 아니지만 좋은 재료를 사용하여 정성껏 만들어 내는 초밥을 맛볼 수 있습니다. 아홉 석의 카운터 자리와 세 개의 테이블이 전부로, 예약은 필수입니다. 코스 외에 단품도 여러 가지 준비되어 있습니다.', 37.518595, 126.939630, '', '지하철 9호선/신림선 샛강역 3번 출구, 1.2km', '스시, 오마카세', '', '', '음식점', '', '화요일~토요일 11:30~15:00, 17:30~21:30', '02-780-1634', '월요일, 일요일, 명절 휴무'),
	(288, '가양칼국수버섯매운탕', '07333  서울 영등포구 국제금융로 78 (홍우빌딩)  지하 1층', 'images/가양칼국수버섯매운탕_288.jpg', '시원한 버섯매운탕이 유명한 집으로, 매운탕이 끓기 시작하면 느타리버섯과 미나리를 살짝 익혀서 건져 먹고 여기에 칼국수를 넣어 끓여 먹은 후 달걀, 다진 채소를 넣어 영양밥도 볶음. 버섯, 칼국수와 영양밥은 무제한 리필.\n\n시원한 버섯매운탕이 유명한 집으로, 매운탕이 끓기 시작하면 느타리버섯과 미나리를 살짝 익혀서 건져 먹습니다. 여기에 칼국수를 넣어 끓여 먹은 후 달걀, 다진 채소를 넣어 영양밥도 볶아 줍니다.', 37.520872, 126.931298, '1만원대', '지하철 9호선/신림선 샛강역 2번 출구, 546m', '가양칼국수버섯매운탕, 샤브샤브, 버섯초회', '', '', '음식점', '', '매일 11:30 ~ 21:30 (Last order 20:30)', '0507-1399-0438', '명절 휴무'),
	(289, '낙원(메이필드호텔)', '07506  서울 강서구 방화대로 94 (외발산동, 메이필드호텔, 낙원가든)', 'images/낙원(메이필드호텔)_289.jpg', '30여년 전통의 한식 전문점. 아름다운 조경과 정갈한 한식\n\n30여년 전통의 한식 전문점. 자연이 주는 여유로움과 편안함을 느낄 수 있는 아름다운 조경과 맛깔스럽고 정갈한 한식의 미학을 경험할 수 있습니다. 찬 한 가지라도 정성스럽게 내놓는 손끝에서 건강이 묻어납니다.', 37.547896, 126.819507, '', '지하철5호선 김포공항역 국내선 터미널 8번게이트 7번 승강장 셔틀버스 이용', '한우꽃등심 한우특선대갈비 한우특선양념대갈비', '월화수목금토일', ' http://www.mayfield.co.kr/kor/subPage.asp?subCode=RESTAURANTS&subStep=1', '음식점', '', '11:30~14:30, 17:30~21:30', '0507-1432-9011', '연중무휴'),
	(290, '남서울민물장어', '06121  서울 강남구 봉은사로 137 (상원빌딩)', 'images/남서울민물장어_290.jpg', '소금구이의 담백한 매력의 장어,먹장어요리\n\n오미장어를 미리 구워 놓지 않고, 손님이 주문하면 그때부터 굽습니다. 장어뼈 튀김, 장어 죽, 소스가 먼저 나오고 막 잡은 장어를 불판에 올려놓고 앞뒤로 뒤집어 가며 양념장을 다섯 번 정도 발라 30분가량 굽습니다. 장어 뼈를 대여섯 시간 끓인 후 배추와 된장으로 맛을 낸 구수한 장엇국도 별미입니다.', 37.506282, 127.029525, '', '지하철 9호선 언주역 1번 출구, 316m', '장어구이, 장어고추장구이, 장어덮밥', '월요일~일요일', '', '음식점', '콜키지 가능(유료)', '월요일~일요일 12:00~21:30 (라스트오더 20:30)', '02-544-1010', '명절 휴무'),
	(291, '자인뭉티기', '06735  서울 서초구 강남대로37길 24-7 (호원빌딩)', 'images/자인뭉티기_291.jpg', '경북 경산시 자인면에서 키운 일 등급 한우만을 사용하는 곳.\n\n경북 경산시 자인면에서 키운 일 등급 한우만을 사용하는 곳. 뭉티기란 한우의 우둔살을 뭉텅이로 썰어서 그냥 날로 먹는 것을 의미합니다. 뭉티기 스시는 밥 위에 뭉티기를 놓고 소스를 얹어 먹는 것입니다. 육회도 한 번 맛볼 만합니다.', 37.485235, 127.032119, '', '지하철 3호선/ 신분당선 양재역 2번 출구, 185m', '육회, 명품구이, 뭉티기초밥', '월요일~금요일', '', '음식점', '', '평일 11:00~14:30, 16:30~22:00', '02-597-2158', '토요일, 일요일, 명절 휴무'),
	(292, '문화옥', '04546  서울 중구 창경궁로 62-5 (주교동)', 'images/문화옥_292.jpg', '3대가 대를 잇는 50년 전통의 설렁탕 전문집. 사골과 양지로 낸 육수.\n\n3대가 대를 잇는 50년 전통의 설렁탕 전문집. 사골과 양지 살로 낸 육수로 설렁탕 국물의 색깔이 진합니다. 보통과 특이 있는데, 양지가 듬뿍 든  실한 느낌입니다. 족탕은 설렁탕의 육수에 잘 삶긴 도가니가 들어가서 설렁탕과 비슷합니다.', 37.568114, 126.998397, '1만원대', '지하철 2/5호선 을지로4가역 4번 출구, 62m', '설렁탕', '월요일~일요일', '', '음식점', '', '06:00 ~ 21:00', '02-2265-0322', '매달 4번째 일요일 정기휴무, 명절 휴무'),
	(293, '내고향식당', '04528  서울특별시 중구 남대문시장길 18-3 (남창동)', 'images/내고향식당_293.jpg', '남대문 갈치조림 전문점 중 대표적 맛집. 뚝배기에 담아 갖은 양념과 함께 센 불에 끓여 내는 갈치조림이 얼큰. 갈치 꼬리 부분을 튀겨 서비스로 올리는 것도 별미.\n\n남대문 갈치조림 전문점 중 대표적 맛집으로 꼽히는 곳입니다. 뚝배기에 담아 갖은 양념과 함께 센 불에 끓여 내는 갈치조림이 얼큰합니다. 갈치 꼬리 부분을 튀겨 서비스로 올리는 것도 별미. 좁고 허름한 공간이지만 점심때가 되면 줄을 서서 먹어야 할 정도입니다.', 37.559925, 126.977038, '1만원대', '지하철 4호선 회현역 5번 출구, 241m', '갈치조림', '월요일~토요일', '', '음식점', '', '매일 07:00 ~ 19:30', '02-752-7954', '매주 일요일, 명절 휴무'),
	(294, '명품잔치국수', '04004  서울 마포구 동교로 103', 'images/명품잔치국수_294.jpg', '시원한 국물의 잔치국수와 새콤한 맛의 비빔국수가 인기인 국수전문점.\n\n시원한 국물의 잔치국수와 새콤한 맛의 비빔국수가 인기인 국수전문점. 저렴한 가격에 양도 푸짐하여 식사 시간에는 줄을 서서 기다려야 할 정도입니다.', 37.554067, 126.910563, '1만원대', '지하철 6호선 망원역 1번 출구, 379m', '잔치국수, 비빔국수, 왕만두, 유부국수', '', '', '음식점', '', '월요일~토요일 10:00~22:00', '0507-1399-2008', '매주 일요일 휴무'),
	(295, '할머니현대낙지집', '06029  서울 강남구 압구정로14길 11', 'images/할머니현대낙지집_295.jpg', '매운 양념의 낙지로 유명한 집. 간장게장과 푸짐하게 나오는 감자탕 맛도 일품.\n\n매운 양념의 낙지로 유명한 집. 간장게장과 푸짐하게 나오는 감자탕 맛도 일품입니다. 맛은 좋지만, 가격대는 비교적 높은 편입니다.', 37.521628, 127.023377, '', '지하철 3호선 압구정역 5번 출구, 597m', '낙지볶음, 세발낙지볶음, 감자탕', '', '', '음식점', '', '월요일~토요일 11:30~15:00, 17:00~21:30', '02-544-8020', '매주 일요일 휴무'),
	(296, '야래향', '04634  서울특별시 중구 퇴계로10길 14 (회현동1가)', 'images/야래향_296.jpg', '중국 음식은 불 맛이라고도 하는데 불을 잘 다루기로 유명.\n\n중국 음식은 불맛이라고도 하는데, 이 집의 주인 겸 주방장은 불을 잘 다루기로 유명합니다. 탕수육, 깐풍게살 등 튀김 요리에 강합니다. 대형화된 이후에는 맛이 평범해졌다는 평들이 많습니다.', 37.558703, 126.980149, '2만원대', '지하철 4호선 회현역 1번 출구, 75m', '광동식하얀굴짬뽕, 탕수육, 오향장육, 해삼전복, 전가복, 깐풍가지, 유니간짜장', '', '', '음식점', '', '매일 11:00 ~ 22:00 (월~금 : 브레이크타임 14:30~16:30)', '02-752-3991', '명절 휴무'),
	(297, '로마네꽁띠', '03053  서울 종로구 북촌로5나길 83-6', 'images/로마네꽁띠_297.jpg', '와인과 그에 어울릴 만한 다양한 프랑스 요리들을 맛 볼 수 있는 곳\n\n180여 가지의 와인과 그에 어울릴 만한 다양한 프랑스 요리들을 맛 볼 수 있습니다. 프랑스 가정에서 즐기는 닭고기 요리를 그대로 재현한 코코뱅이 추천 메뉴입니다. 전통 한옥을 개조해서 여러 명의 단체 손님들을 맞을 수 있도록 바깥채 사랑방을 꾸며 놓았습니다.', 37.584361, 126.982375, '', '지하철 3호선 안국역 1번 출구, 177m', '알리오올리오 파스타, 꼬꼬뱅, 등심스테이크', '', ' https://www.instagram.com/romaneeconti_samcheongdong', '음식점', '', '화요일~일요일 11:00~21:30', '02-722-1633', '매주 월요일'),
	(298, '평가옥(양재점)', '06775  서울 서초구 논현로 69 (양재동, 상호빌딩)', 'images/평가옥(양재점)_298.jpg', '이북 음식 전문점인 분당 평가옥의 양재동 분점. 어복쟁반, 평양냉면이 인기 메뉴.\n\n이북 음식 전문점인 분당 평가옥의 양재동 분점입니다. 어복쟁반, 평양냉면이 인기 메뉴입니다. 냉면은 소고기, 돼지고기, 닭고기, 꿩완자까지 올려져 있는 꾸미가 화려하며 소고기와 꿩고기로 낸 육수의 맛이 감칠맛이 납니다. 평양식 만두와 녹두전도 많이 찾는 메뉴입니다.', 37.476179, 127.045719, '', '지하철 신분당선 양재시민의숲(매헌)역 2번 출구, 1km', '냉면', '월요일~일요일', '', '음식점', '', '11:00 ~ 21:30', '02-3462-1577', '명절 휴무'),
	(299, '평래옥', '04550  서울특별시 중구 마른내로 21-1 (저동2가)', 'images/평래옥_299.jpg', '닭으로 육수를 내는 초계탕이 유명한 집.\n\n닭으로 육수를 내는 초계탕이 유명한 집. 꿩냉면은 일반 냉면과 육수는 똑같은 것을 쓰지만, 꿩고기 완자를 넣어줍니다. 고소한 녹두전의 맛도 좋고 제육도 맛있습니다. 손님들 평균 연령이 높은 곳 중의 하나입니다.', 37.564911, 126.990388, '', '지하철 2/3호선 을지로 3가역 11번 출구, 177m', '초계탕', '월요일 ~ 일요일', '', '음식점', '', '11:00 ~ 15:30 / 17:00 ~ 22:00', '02-2267-5892', '명절 휴무'),
	(300, '비언유주얼 강남점', '06153  서울 강남구 선릉로108길 5 (삼성동)  지하 1층', 'images/비언유주얼_강남점_300.jpg', '국내 최초 3D 맵핑 레스토랑\n\n비언유주얼은 영상으로 요리하는 레스토랑으로 테마파크의 비일상적인 즐거움을 제공하고 있습니다. 세계 최초, 국내 최초 3D 맵핑 영상 메뉴로 AR+VR 경험하면서 식사할 수 있습니다.  약 1시간 30분 동안 3D 맵핑 영상 메뉴로 진행되는 테마 식사를 즐길 수 있습니다. 순수 예약제로 운영되며 요리별 영상이 준비되어 있어 계절별 1가지로 정해진 코스요리가 함께 제공됩니다.  예약은 네이버 예매 로만 가능하며, 100% 예약제로 진행되어 사전예약금을 지급한 사람에 한하여 예약이 확정됩니다.', 37.509575, 127.044610, '', '지하철 수인분당선/9호선 선정릉역 3번 출구, 180m', '', '화요일~일요일', ' http://beunusual.co.kr	', '음식점', '100% 사전예약제', '11:00~15:00, 17:00~20:30', '0507-1428-7828', '매주 월요일'),
	(301, '평안도 족발집', '04606  서울특별시 중구 장충단로 174-6 (장충동1가)', 'images/평안도_족발집_301.jpg', '족발로 유명한 장충동에서도 명성을 얻고 있는 집.\n\n족발로 유명한 장충동에서도 명성을 얻고 있는 집입니다. 보기 좋게 가지런히 썰어낸 족발이 쟁반에 담겨 나옵니다. 야들야들하고, 쫄깃쫄깃한 족발 맛이 일품입니다. 하루 판매할 분량의 족발만 당일에 삶아냅니다.', 37.560262, 127.006049, '', '지하철 3호선 동대입구역 3번 출구, 138m', '족발, 녹두빈대떡, 막국수', '화요일~일요일', '', '음식점', '', '11:00~21:00', '02-2279-9759', '월요일, 명절 휴무'),
	(302, '조금', '03146  서울 종로구 인사동길 60 (관훈동)', 'images/조금_302.jpg', '일본식 솥밥과 우동으로 유명한 일식집.\n\n일본식 솥밥과 우동으로 유명한 곳. 채소, 버섯, 은행 등이 들어가 있는 세 종류의 솥밥 중 해물을 얹은 조금솥밥이 가장 유명합니다. 깔끔하고 일본식 인테리어와 조용한 실내 분위기가 특징입니다.', 37.575279, 126.983635, '', '지하철 3호선 안국역 6번 출구, 136m', '조금솥밥, 전복솥밥, 양송이솥밥, 숯불꼬치구이', '', '', '음식점', '', '평일 10:30~15:00, 17:00~20:10 / 주말 10:30~15:00, 16:30~20:10', '02-734-0783', '명절 휴무'),
	(303, '모녀김밥', '03195  서울 종로구 동호로 403-23 (예지동)', 'images/모녀김밥_303.jpg', '광장시장을 가야 하는 이유 중의 하나가 된 겨자소스와 곁들여 먹는 김밥의 원조집.\n\n광장시장을 가야 하는 이유 중의 하나가 된 겨자소스와 곁들여 먹는 김밥의 원조집. 수많은 김밥집이 원조라는 간판을 내세우고 있지만, 이 집은 40년이 넘게 김밥을 말아온 곳입니다. 속은 당근과 단무지만 들어 있어 심플하지만 겨자장에 찍어 먹는 맛이 중독성이 있습니다. 1호점은 광장시장 중앙부가 아닌 변두리 쪽에 있으며 2호점이 중앙부에 있습니다.', 37.570283, 127.001121, '1만원대', '지하철 1호선 종로5가역 7번 출구, 99m', '김밥', '', '', '음식점', '', '매일 09:00 ~ 21:00', '02-2273-8330', '명절 휴무'),
	(304, '피터팬1978', '03698  서울 서대문구 증가로 10', 'images/피터팬1978_304.jpg', '프랑스·일본 장인의 기술이 녹아 있는 베이커리\n\n피터팬1978은 2대에 걸쳐 40년 이상 운영하고 있는 제과점입니다. 더 맛있는 빵에 대한 연구를 위해 프랑스와 일본의 장인들에게 기술을 배우고, 프랑스에서 가져온 천연발효종을 사용해 빵을 만들고 있습니다. 유기농 호밀, 비정제 설탕 등 좋은 재료를 사용하여 빵을 만들며, ‘아기궁댕이’, ‘장발장이 훔친 빵’ 등 독특한 이름과 건강한 맛으로 인기가 높습니다. 내국인은 물론 외국인도 자주 찾는 빵집입니다.', 37.569375, 126.931657, '', '연희초등학교에서 234m', '', '매일', ' https://smartstore.naver.com/peterpanbakery', '카페, 디저트', '', '08:00~21:00', '02-336-4775', '없음'),
	(305, '아리아께', '04605  서울 중구 동호로 249 (신라호텔)  2층', 'images/아리아께_305.jpg', '재료의 선도가 좋기로 유명한, 서울에서 손꼽히는 일식집.\n\n재료의 선도가 좋기로 유명한, 서울에서 손꼽히는 일식집 중의 하나입니다. 담백하고 정갈한 90여 가지의 정통 관서 지방의 요리를 선보입니다. 흑과 백이 조화로운 품위 있고 현대적인 실내 분위기로 4~10명 정도를 수용하는 별실도 있습니다.', 37.557506, 127.007953, '', '지하철 3호선 동대입구역 5번 출구, 429m', '스키야키, 사치 스시 코스', '', ' http://www.shilla.net/seoul/dining/viewDining.do?contId=ARI#ad-image-0', '음식점', '', '매일 12:00 ~ 14:30 / 17:30 ~ 21:30', '02-2230-3356', '연중무휴'),
	(306, '워킹온더클라우드', '07345  서울특별시 영등포구 63로 50 (여의도동)  59층', 'images/워킹온더클라우드_306.jpg', '63빌딩 내에 자리한 유럽식 레스토랑으로 정찬 및 일품요리\n\n서울에서 가장 높은 곳에 위치한 식당. 63빌딩 내에 자리한 유럽식 레스토랑으로 정찬 및 일품요리를 맛볼 수 있습니다. 맛있는 요리와 함께 한강과 함께 펼쳐지는 서울의 풍경을 감상할 수 있습니다.', 37.519664, 126.939909, '', '지하철 9호선 샛강역 3번 출구, 1.2km', '', '', ' https://www.63restaurant.co.kr/introduction/introduction.r63?shop_idrest=31040', '음식점', '', '평일 11:30 ~ 15:00 / 17:30 ~ 22:00\n주말 11:00 ~ 15:00 / 17:30 ~ 21:30', '0507-1400-5904', '연중무휴'),
	(307, '닭진미', '04528  서울 중구 남대문시장길 22-20 (남창동)', 'images/닭진미_307.jpg', '오래된 닭곰탕 집으로, 맑게 국물을 낸 닭곰탕이 아는 사람들에게는 이미 유명\n\n오래된 닭곰탕 집으로, 맑게 국물을 낸 닭곰탕이 아는 사람들에게는 이미 유명합니다. 50여 년에 가까운 역사를 자랑하는 집이기도 합니다.', 37.559596, 126.977065, '1만원대', '지하철 4호선 회현역 5번 출구, 196m', '닭곰탕', '월화수목금토', '', '음식점', '', '08:00 ~ 20:30', '02-753-9063', '매주 일요일'),
	(308, '신림동 순대타운', '08776  서울 관악구 신림로59길 14 (신림동, 민속순대타운)', 'images/신림동_순대타운_308.jpg', '서울에서 꼭 가봐야 할 먹거리 타운으로 유명한 신림동 순대타운.\n\n서울에서 꼭 가봐야 할 먹거리 타운으로 유명한 신림동 순대타운에서는 어디와도 비교할 수 없는 고유의 순대를 맛볼 수 있습니다. 많은 직장인이 회식 장소로 신림동 순대타운을 찾고 주변엔 쇼핑, 영화관 등 다양한 문화시설이 있어 연인들의 데이트 코스로도 인기 있습니다.', 37.483290, 126.928776, '', '지하철 2호선/ 신림선 신림역 3번 출구, 168m', '', '', '', '음식점', '', '', '', ''),
	(309, '신안촌', '03169  서울특별시 종로구 사직로12길 8 (내자동)', 'images/신안촌_309.jpg', '대통령 단골집으로 유명한 전라도 토속 음식 전문점\n\n신안촌은 전라남도 신안 지역의 전통 요리와 식문화를 반영한 토속 음식 전문점으로, 창업주 이금심이 고향의 식재료를 활용하여 개발한 낙지꾸리와 연포탕이 대표 입니다. 낙지꾸리는 신선한 산낙지를 참기름 양념에 구워 담백하고 고소한 맛을 자랑하며, 시원한 국물이 매력적인 연포탕도 제공합니다. 생선회와 탕이 포함된 코스 요리도 있으며, 한국적인 음식과 한옥의 따뜻한 분위기를 함께 즐길 수 있는 곳입니다.', 37.575619, 126.970878, '', '지하철 3호선 경복궁역 7번 출구, 130m', '', '월요일~토요일', '', '음식점', '', '평일 11:30 ~ 15:00 / 17:00 ~ 22:00\n토요일 11:30 ~ 20:00', '0507-1418-7744', '매주 일요일, 명절 휴무'),
	(310, '훼드라', '03789  서울 서대문구 연세로5길 32', 'images/훼드라_310.jpg', '이한열 열사를 기리는 청양고추 팍팍 최루탄 라면. 해장라면이 유명.\n\n‘훼드라’라는 이름은 초대 사장님이 ‘당장 죽어도 여한이 없다’라는 뜻의 영화 제목에서 따온 말로, 70~80년대 정치적 탄압에 맞서 민주주의를 부르짖으며 학생운동을 전개하였던 당시의 시대 정신을 고스란히 간직하고 있습니다. 훼드라는 ‘독수리다방’과 함께 연세대 학생들의 대표 아지트로 꼽힙니다. 대표 메뉴인 최루탄 해장라면은 최루탄에 숨진 이한열 열사를 기리는 것으로 청양고추가 듬뿍 들어가 눈물 콧물 쏟으며 먹어야 하는 중독적인 매운맛이 특징입니다.', 37.556486, 126.935642, '1만원대', '지하철 2호선 신촌역 1번 출구, 170m', '', '매일', '', '음식점', '', '12:00~02:00', '02-323-3201', '없음'),
	(311, '원할머니본가 본점', '04573  서울 중구 난계로 201 (황학동, 황학동 원할머니보쌈 사옥)', 'images/원할머니본가_본점_311.jpg', '깐깐하게 재료를 고르고 다듬던 야무진 손 맛을 살려낸 30년 전통의 보쌈 전문.\n\n깐깐하게 재료를 고르고 다듬던 야무진 손 맛을 현대에 살려낸 30년 전통의 보쌈 전문집입니다. 신선한 굴을 넣어 매일매일 담궈내는 겉절이 김치는 구수한 고기 맛과 어우러져 입맛을 돋웁니다. 단아하고 정갈한 인테리어는 서까래를 활용하여 古家의 정겨운 마루 문화를 연상케 합니다.', 37.569629, 127.023206, '3만원대', '지하철 2/6호선 신당역 2번 출구, 641m', '한돈 맛보쌈, 한돈 모둠보쌈, 한바탕 세트, 부드러운 족발', '', ' http://www.bossam.co.kr ', '음식점', '', '매일 11:30~22:30', '02-2232-3232', '명절 당일'),
	(312, '동표골뱅이', '04534  서울 중구 명동9길 43 (을지로2가)', 'images/동표골뱅이_312.jpg', '명동 골뱅이 골목에서 동해골뱅이와 함께 원조격인 집\n\n명동 골뱅이 골목에서 동해골뱅이와 함께 원조 격인 집입니다. 많은 양과 푸짐한 인심으로 유명합니다. 고춧가루와 다진 마늘, 생파 등으로 무친 양념 맛이 자극적입니다. 골뱅이를 시키면 계란말이를 기본적으로 서비스로 내줍니다. 동표골뱅이를 사용한다는 점이 장점입니다.', 37.565699, 126.983962, '', '지하철 2호선 을지로입구역 5번 출구, 120m', '골뱅이, 계란말이, 노가리, 먹태', '월요일~토요일', '', '음식점', '', '평일 16:00 - 01:00\n토 16:00 - 23:30', '02-778-1322', '매주 일요일, 명절 휴무'),
	(313, '원대구탕(삼각지역)', '04382  서울 용산구 한강대로62가길 8', 'images/원대구탕(삼각지역)_313.jpg', '얼큰한 국물과 담백한 대구 맛으로 30년이 넘는 전통을 이어온 집\n\n얼큰한 국물과 담백한 대구 맛으로 30년이 넘는 전통을 이어온 집입니다. 매일 아침 대구와 야채를 구입하며 2백 인분까지 끓일 수 있는 큰 솥에 한꺼번에 넣고 끓여 깊은맛이 납니다. 얼큰한 국물은 숙취 해소에 좋습니다. 예약을 받지 않아 줄을 서서 기다려야 합니다.', 37.534528, 126.974420, '1만원대', '지하철 4/6호선 삼각지역 1번 출구 , 70m', '대구탕, 내장탕, 맑은탕, 대가리탕', '', '', '음식점', '', '화~토 10:00~22:00 / 일 10:00~21:50', '02-797-4488', '월요일 휴무'),
	(314, '이태원숯불구이', '04390  서울 용산구 녹사평대로32길 41-5', 'images/이태원숯불구이_314.jpg', '가격은 비싸지만 질 좋은 한우 소고기구이를 먹을 수 있는 정육점식당.\n\n가격은 비싸지만 질 좋은 한우 소고기구이를 먹을 수 있는 정육점식당. 숯불 위에 석쇠를 올려 고기를 구워먹습니다. 특등심은 수량이 적어 미리 주문전화를 해야 합니다.', 37.532136, 126.991024, '', '지하철 6호선 이태원역 4번 출구, 434m', '특등심, 일반등심, 곰탕', '', '', '음식점', '', '매일 11:30~22:00', '02-797-7777', '둘째, 넷째 주 일요일 휴무'),
	(315, '양촌리 화로숯불구이', '06296  서울 강남구 남부순환로 2720', 'images/양촌리_화로숯불구이_315.jpg', '참숯에 구워 먹는 삼겹살이 유명한, 깔끔한 분위기의 고깃집.\n\n참숯에 구워 먹는 삼겹살이 유명한, 깔끔한 분위기의 고깃집. 저녁에는 참숯 화로에 구워 먹는 생 삼겹살이 좋으며, 점심 시간에는 김치전골과 순두부 등도 맛볼 수 있습니다. 전골과 찌개류도 참숯에 끓여 먹을 수 있는 것이 특징입니다. 확 트인 1, 2층이 시원한 느낌이 들고 독립된 야외 테라스도 있습니다.', 37.485777, 127.043442, '', '지하철 3호선 매봉역 4번 출구, 282m', '양촌리 돼지갈지, 양촌리 삼겹살, 옛날식 김치지개, 양푼비빔밥', '매일', '', '음식점', '', '이용시간 00:00~24:00', '0507-1413-1284', '연중무휴'),
	(316, '까델루뽀', '03042  서울 종로구 자하문로16길 5-5 (효자동)', 'images/까델루뽀_316.jpg', '한옥집을 레노베이션하여 만든 이탈리아 레스토랑\n\n한옥집을 레노베이션하여 만든 이탈리아 레스토랑. 분위기 있는 한옥에서 편안하게 식사를 즐길 수 있는 곳입니다. 코스 가격은 적당한 편이며, 아담하고 독채로 된 별실을 예약하면 더욱 좋습니다.', 37.581796, 126.971374, '', '지하철 3호선 경복궁역 3번 출구, 674m', '', '', ' https://blog.naver.com/zerv0', '음식점', '', '월~금 12:00~14:50, 18:00~21:30 / 토요일 12:00~14:50, 18:00~21:00', '0507-1412-5233', '매주 일요일'),
	(317, '오우가', '04537  서울 중구 명동8가길 42 (충무로2가)', 'images/오우가_317.png', '고기구이 전문점. 돼지고기와 소고기.\n\n고기구이 전문점. 돼지고기와 소고기를 함께 즐길 수 있습니다. 반찬은 야채를 많이 사용한 건강식단이 나옵니다. 먹고 난 대나무 밥통은 가져갈 수도 있습니다.', 37.561694, 126.987397, '', '지하철 4호선 명동역 9번 출구, 132m', '대나무쌈밥 정식, 녹차대나무식사, 생갈비정식, 삼겹살정식', '', '', '음식점', '', '매일 11:00~22:00', '02-753-7533', '명절 연휴 휴무'),
	(318, '나무사이로', '03169  서울특별시 종로구 사직로8길 21', 'images/나무사이로_318.jpg', '광화문 일대에서 조용하고 분위기 있게 커피를 마실 수 있는 곳. 여름에는 실내 공간보다는 테라스. 핸드드립 커피는 다른 종류로 리필 가능.\n\n광화문 일대에서 조용하고 분위기 있게 커피를 마실 수 있는 곳입니다. 여름에는 실내 공간보다는 테라스가 좋습니다. 핸드드립 커피는 다른 종류로도 리필이 가능합니다.', 37.574682, 126.970991, '', '지하철 3호선 경복궁역 7번 출구, 270m', '', '', ' https://www.namusairo.com/', '카페, 디저트', '', '09:30~20:30', '070-7590-0885', '명절 휴무'),
	(319, '은호식당', '04528  서울특별시 중구 남대문시장4길 28-4 (남창동)', 'images/은호식당_319.jpg', '70년 전 남대문시장에 좌판을 펴고 꼬리곰탕을 만들기 시작해 3대에 걸친 꾸준한 맛.\n\n70년 전 남대문시장에 좌판을 펴고 꼬리곰탕을 만들기 시작해서 지금까지 3대에 걸쳐 꾸준히 그 맛을 이어 오고 있습니다. 꼬리곰탕 이외에도 도가니탕, 설렁탕, 수육 등도 맛볼 수 있습니다.', 37.559002, 126.977071, '', '지하철 4호선 회현역 5번 출구, 115m', '한식(해장국,꼬리곸탕)', '월요일~일요일', ' http://xn--ok1b941aijd7tt.com/', '음식점', '', '평일 06:00 ~ 21:00\n주말 06:00 ~ 16:00', '02-753-3263', '명절 휴무'),
	(320, '술탄케밥', '04406  서울특별시 용산구 보광로 126 (이태원동)', 'images/술탄케밥_320.jpg', '터키인이 직접 만드는 터키식 케밥.\n\n터키인이 직접 만드는 터키식 케밥을 맛볼 수 있습니다. 닭고기, 양고기 등의 고기로 만들어지는 케밥은 한 끼 식사로도 손색없습니다. 간편하게 앉아서 먹을 수 있는 좌석이 마련되어 있고, 테이크아웃도 가능합니다.', 37.534038, 126.994243, '1만원대', '지하철 6호선 이태원역 3번 출구, 67m', '터키 케밥 치킨, 터키 케밥 램, 케밥 박스 믹스', '매일', '', '음식점', '', '', '0507-1331-3890', '연중무휴'),
	(321, '지노스 뉴욕 피자', '04345  서울 용산구 녹사평대로40길 46 (이태원동)  2층', 'images/지노스_뉴욕_피자_321.jpg', '도끼를 단골손님에서 사장으로 거듭나게 한 피자 맛집.\n\n모든 피자는 가공하지 않은 원재료를 빚어 만듭니다. 간이 강한 오리지널 피자부터 한국인의 입맛에 고안된 담백한 피자까지 다양한 종류의 피자를 즐길 수 있습니다. 메인 메뉴는 토마토소스 베이스의 ‘브룩클린스 베스트’와 알프레도 소스 베이스의 ‘트러플 슈룸’. 트러플 오일을 넣어 담백하고 풍미가 깊은 ‘트러플 슈룸’은 도끼를 단골손님에서 사장으로 거듭나게 한 이유이기도 합니다. 지노스 피자는 격식 없이 즐길 수 있는 피자가 생각날때 언제든 편하게 찾을 수 있는 식당입니다.', 37.534399, 126.988211, '', '지하철 6호선 녹사평역 1번 출구, 236m', '브루클린스베스트, 시금치 알프레도, 뉴욕슈프림', '', ' https://www.instagram.com/ginospizza/', '음식점', '', '평일 11:30 - 15:00 / 17:00 - 22:00\n토요일 11:30 - 22:00 / 일요일 11:30 - 21:00', '0507-1403-2234', ''),
	(322, '성북동돼지갈비집', '02879  서울 성북구 성북로 115 (성북동)', 'images/성북동돼지갈비집_322.jpg', '30년이 넘은, 성북동 일대에서 유명한 연탄불 돼지갈비집.\n\n30년이 넘은, 성북동 일대에서 유명한 돼지갈비집. 연탄불에 구워내는 돼지갈비구이 백반이 일품입니다. 돼지갈비가 연탄불 향이 약간 배면서 기름기도 빠져 쫄깃한 맛이 일품입니다.', 37.593287, 126.996071, '', '지하철 4호선 한성대입구역 5번 출구, 1.1km', '돼지갈비, 불고기백반', '', '', '음식점', '', '09:00 ~ 20:30', '02-764-2420', '매주 화요일'),
	(323, '진동둔횟집', '06530  서울특별시 서초구 강남대로91길 18 (잠원동)', 'images/진동둔횟집_323.jpg', '잡어 회와 세꼬시를 즐길 수 있는 곳. 대부분 모둠이나 세꼬시 주문.\n\n잡어 회와 세꼬시를 즐길 수 있는 곳. 대부분 모둠이나 세꼬시를 주문합니다. 세꼬시는 광어, 도다리, 가자미 등을 섞어서 회를 뜹니다. 회를 먹을 때 나오는 생선미역국이 개운하고 맛있습니다. 모둠에는 우럭, 방어, 볼락, 감성돔, 전어, 도미, 학꽁치 등 다양한 생선들이 계절에 따라 바뀌어 나옵니다. 가격대는 좋은 편이나 실내가 아주 시끄럽다는 점은 감안해야 합니다.', 37.512273, 127.019642, '', '지하철 7호선/ 신분당선 논현역 8번 출구, 159m', '전어 멸치 세꼬시', '월화수목금토', '', '음식점', '', '12:00 ~ 22:00 (21:00 라스트오더)', '02-544-2179', '매주 일요일'),
	(324, '부산갈매기', '04526  서울특별시 중구 남대문로 25-20 (북창동)', 'images/부산갈매기_324.jpg', '걸쭉하고 진한 맛의 생태탕. 애, 알, 곤이 등 내장이 듬뿍 들어가 국물.\n\n걸쭉하고 진한 맛의 생태탕이 자랑입니다. 애, 알, 곤이 등 내장이 듬뿍 들어가 국물 맛이 걸쭉하고 구수하며 부드러운 생태 살과 부드러운 내장의 조화가 일품입니다.', 37.562109, 126.978357, '3만원대', '지하철 1/2호선 시청역 7번 출구, 365m', '생대구탕, 생태매운탕, 홍어무침', '월요일~토요일', '', '음식점', '', '평일 11:00 ~ 21:30\n토요일 11:00 ~ 21:00', '02-773-8146', '매주 일요일, 명절 휴무'),
	(325, '발우공양', '03145  서울 종로구 우정국로 56 (견지동)', 'images/발우공양_325.jpg', '발우공양은 대한불교 조계종에서 유일하게 직접 운영하는 사찰 음식 전문점.\n\n발우공양은 대한불교 조계종에서 유일하게 직접 운영하는 사찰 음식 전문점으로, 미쉐린 가이드에 소개되기도 했습니다. 발우공양의 다양한 메뉴는 사찰에서 전승되고 있는 전통적인 조리법으로 만들어진 사찰음식의 원형을 간직하고 있습니다. 발우공양에서는 음식과 더불어 사찰음식의 전통과 문화를 함께 음미할 수 있습니다.', 37.573936, 126.983186, '', '지하철 3호선 안국역 6번 출구, 273m', '선식, 원식, 마음식', '', ' http://balwoo.or.kr/', '음식점', '', '점심 1부 – 11:30 ~ 13:20\n점심 2부 – 13:30 ~ 14:50\n저녁시간 – 18:00 ~ 21:00\n(주문마감 19:40)', '02-733-2081', '일요일, 1월 1일, 설날, 추석 휴무'),
	(326, '어반가든', '04516  서울특별시 중구 정동길 12-15 (정동)', 'images/어반가든_326.jpg', '각종 허브와 꽃향기의 옥상 정원이 자랑거리인 이탈리아 정통 레스토랑\n\n각종 허브와 꽃향기가 맴도는 옥상 정원이 자랑거리. 옥상정원은 자연의 신선한 향과 푸른색으로 지쳐 있는 마음을 다독이는 ‘힐링 가든(치유 정원)’과 상추와 치커리 등이 심어진 ‘키친 가든’으로 나뉘어 있습니다. 일본 후쿠오카의 이탈리아식 정통 레스토랑 출신 셰프가 가정식 메뉴를 선보입니다.', 37.567433, 126.969204, '', '지하철 5호선 서대문역 5번 출구, 470m', '', '월요일~일요일', ' https://urbangarden.co.kr/', '음식점', '', '11:00~22:00', '02-777-2254', '명절 당일'),
	(327, '오발탄', '05654  서울 송파구 위례성대로 206', 'images/오발탄_327.jpg', '양, 대창구이가 맛있는 집. 양념 양곱창을 숯불에 구워 먹는 것이 특징.\n\n양, 대창구이가 맛있는 집이다. 양념에 재어서 나오는 양곱창을 숯불에 구워 먹는 것이 특징입니다. 대파와 감초 등을 넣고 달인 간장에 고춧가루, 파인애플, 마늘과 생강, 설탕, 물엿 등을 넣고 만드는 양념이 맛의 비결이라고 합니다. 구수한 청국장과 누룽지로 마무리하면 좋습니다. 점심에는 곱창전골과 양을 썰어서 철판에 볶은 양밥이 추천합니다.', 37.509027, 127.133411, '', '지하철 5호선 방이역 1번 출구, 826m', '대창구이 특양구이 양밥', '월요일~일요일', ' http://www.hiobaltan.com', '음식점', '', '11:30 ~ 22:00', '02-404-0090', '연중무휴'),
	(328, '송옥', '04526  서울 중구 남대문로1길 11', 'images/송옥_328.jpg', '40여 년 전통의, 메밀국수를 전문으로 하는 집\n\n40여 년 전통의, 메밀국수를 전문으로 하는 집입니다. 진하게 우려낸 가쓰오부시와 간장이 감칠맛 있습니다. 일식이라기보다는 한국식 메밀국수라 할 수 있습니다. 우동도 면발이 쫄깃하고 맛있습니다.', 37.562362, 126.977988, '1만원대', '지하철 4호선 회현역 5번 출구, 370m', '메밀국수, 유부우동, 튀김우동, 돌냄비우동, 메밀비빔국수, 메밀송옥국수', '', '', '음식점', '', '월~토 11:00~20:00, 일요일 11:00~18:00', '02-752-3297', '명절 휴무'),
	(329, '스탠딩커피', '04345  서울특별시 용산구 녹사평대로 224-1 (이태원동)', 'images/스탠딩커피_329.jpg', '테이크아웃 커피전문점. 좋은 원두를 쓰는 것이 커피 맛의 비법. 여름엔 블루큐라소 시럽을 넣어에메랄드 색을 내는 레몬에이드가 단연 인기.\n\n테이크아웃 커피전문점. 좋은 원두를 쓰는 것이 커피 맛의 비법입니다. 여름엔 블루큐라소 시럽을 넣어 에메랄드 색을 내는 레몬에이드가 단연 인기입니다.', 37.537886, 126.986908, '', '지하철 6호선 녹사평역 2번 출구, 370m', '커피전문점', '월요일~일요일', ' https://smartstore.naver.com/standing_coffee', '카페, 디저트', '', '평일 07:00 ~ 20:00\n주말 09:00 ~ 20:00', '0507-1423-0427', '명절 휴무'),
	(330, '원조할머니떡볶이집', '03036  서울특별시 종로구 자하문로15길 13 (통인동)', 'images/원조할머니떡볶이집_330.jpg', '통인시장에서 기름떡볶이로 유명해진 집. 양념에 볶듯이 해서 나오는 스타일.\n\n통인시장에서 기름떡볶이로 유명해진 집. 일반 떡볶이처럼 국물이 있는 것이 아니라 양념에 볶듯이 해서 나오는 스타일입니다. 튀김이 아닌 전을 같이 파는 점도 독특합니다.', 37.580661, 126.970223, '1만원대', '지하철 3호선 경복궁역 2번 출구, 569m', '기름떡볶이, 빈대떡, 모둠전', '', ' https://mo1067.modoo.at/', '음식점', '', '매일 08:00~20:00 재료 소진 시 영업 종료', '02-725-4870', '셋째 주 일요일 휴무'),
	(331, '의정부평양면옥', '06530  서울특별시 서초구 강남대로93길 28 (잠원동)', 'images/의정부평양면옥_331.jpg', '메밀을 직접 빻아서 은은하고 구수한 풍미가 입 안 가득 감돌고 삼삼하지만 깊은 맛의 육수.\n\n평양면옥의 평양냉면은 메밀을 직접 빻아서 은은하고 구수한 풍미가 입 안 가득 감돌고 삼삼하지만 깊은 맛의 육수가 일품입니다.', 37.512945, 127.018937, '1만원대', '지하철 7호선/ 신분당선 논현역 8번 출구, 264m', '냉면', '월~토', '', '음식점', '', '월요일~금요일 11:00~21:00 (15:00~17:00 브레이크 타임)\n토요일 11:00~20:40 (15:00~17:00 브레이크 타임)', '02-547-6947', '매주 일요일 휴무'),
	(332, '너비집', '04534  서울 중구 명동9길 37-8 (을지로2가)', 'images/너비집_332.jpg', '소갈비를 매운 양념에 잘 재워서 떡과 함께 즉석에서 찜을 해 먹는 매운갈비찜.\n\n소갈비를 매운 양념에 잘 재워서 떡과 함께 즉석에서 찜을 해 먹는 매운갈비찜으로 유명한 집. 명동 일대의 일본관광객들에게도 인기가 높습니다. 생갈비와 야채전골도 훌륭하며 육회도 즐길 수 있습니다.', 37.565530, 126.983776, '', '지하철 2호선 을지로입구역 6번 출구, 102m', '생왕갈비 매운갈비찜', '월요일~토요일', '', '음식점', '', '11:00 ~ 21:30', '02-756-4084', '매주 일요일, 명절 휴무'),
	(333, '진도울돌목가는길', '06656  서울 서초구 서초대로40길 41  대호IR빌딩', 'images/진도울돌목가는길_333.jpg', '싱싱한 바다 음식과 토속음식이 어우러진 한정식전문점.\n\n바다에서 방금 건진 토속 바다 한정식\n\n싱싱한 바다 음식과 토속음식이 어우러진 한정식전문점. 비타민, 미네랄, 식이섬유가 풍부한 참전복, 세꼬시, 세발낙지 등 산지에서 바로 공급받는 모든 재료에 신선함이 살아 넘칩니다. 우엉을 잘게 썰어 무친 우엉잡채와 코다리찜은 보는 것만으로도 입맛을 당깁니다.', 37.489840, 127.008014, '2만원대', '지하철 2호선 서초역 2번 출구, 175m', '울정식, 돌정식, 목정식', '', ' https://wooldolmok.modoo.at/', '음식점', '', '평일 11:30 ~ 15:00 / 17:00 ~ 22:00\n주말 11:30 ~ 15:00 / 17:00 ~ 21:00', '0507-1311-6032', '연중 무휴'),
	(334, '호수삼계탕', '07397  서울특별시 영등포구 도림로 276 (신길동)', 'images/호수삼계탕_334.jpg', '들깨로 낸 삼계탕 국물이 걸쭉. 주변에 유사 호수삼계탕집이 많아 본점을 찾는 데 유의.\n\n들깨로 낸 삼계탕 국물이 걸쭉하고 차진 것이 특징입니다. 주변에 호수삼계탕이라고 상호를 내건 집이 많아서 본점을 찾는 데 유의해야 합니다.', 37.502648, 126.904373, '', '지하철 7호선 신풍역 4번 출구, 528m', '삼계탕', '매일', '', '음식점', '', '11:00 ~ 21:30 (주문시간 21:00 까지)', '02-848-2440', '명절 휴무'),
	(335, '수빈떡갈비', '03699  서울특별시 서대문구 연희로25길 29 (연희동)', 'images/수빈떡갈비_335.gif', '떡갈비와 간장게장 등 주 메뉴를 비롯한 나물과 반찬은 계절별 재료 사용\n\n떡갈비와 간장게장 등 주 메뉴를 비롯한 나물과 반찬은 계절별 재료를 사용하고, 모든 김치류도 직접 담그는 등 전통한식의 맛을 유지하고 있습니다.', 37.572005, 126.934232, '', '지하철 2호선 신촌역 3번출구, 3번마을버스 한성화교중고등학교 하차', '한정식', '', '', '음식점', '', '11:30~15:00, 17:00~21:00', '02-307-9979', '매주 화요일'),
	(336, '손칼국수감자수제비', '06054  서울 강남구 언주로150길 9', 'images/손칼국수감자수제비_336.jpg', '손 반죽을 냉장고에 숙성시킨 다음 즉석에서 끓여내는데 쫄깃쫄깃한 맛.\n\n손 반죽을 한 밀가루 반죽을 냉장고에 숙성시킨 다음 즉석에서 끓여내는데 쫄깃쫄깃한 맛이 좋습니다. 두세 명이 가면 수제비와 칼국수를 주문해서 골고루 맛볼 수 있습니다. 밥풀 양념을 쓰는 경상도식 김치 겉절이도 일품입니다.', 37.521117, 127.035115, '1만원대', '지하철 수인분당선 압구정로데오역 5번 출구, 902m', '손칼국숙, 수제비, 콩국수', '', '', '음식점', '', '평일 10:00~20:00, 토요일 10:00~17:00', '02-542-6808', '매주 일요일, 명절 휴무'),
	(337, '프리모바치오바치', '04055  서울 마포구 와우산로23길 44 (서교동)', 'images/프리모바치오바치_337.jpg', '홍대 앞에서 가장 유명세를 타고 있는 파스타 전문점.\n\n홍대 앞에서 가장 유명세를 타고 있는 파스타 전문점. 항상 한 시간 이상 줄을 서야 먹을 수 있을 정도입니다. 예약은 받지 않습니다. 가격도 저렴한 편입니다.', 37.554791, 126.923697, '', '지하철 2호선/ 경의중앙선/ 공항철도 홍대입구역 9번 출구, 159m', '빠네 파스타, 고르곤졸라 피자, 할라피뇨 폴로', '', ' https://www.instagram.com/primo_baciobaci/', '음식점', '', '매일 11:00~22:00 (라스트오더 21:30)', '02-323-0098', '명절 당일'),
	(338, '궁', '03146  서울특별시 종로구 인사동10길 11-3 (관훈동)', 'images/궁_338.jpg', '30년 이상 전통 개성만두의 맛을 지키는 곳\n\n30년 이상 전통 개성만두의 맛을 지키는 곳입니다. 전통 있는 개성 만두와 고소한 사골 국물의 조화가 일품입니다. 다양한 전통주도 맛볼 수 있어 식사와 함께 곁들이면 좋습니다.', 37.574269, 126.985409, '1만원대', '지하철 3호선 안국역 5번 출구, 370m', '만두', '월화수목금토일', ' http://www.koong.co.kr/', '음식점', '', '월,화 11:30~15:00, 16:00~20:00 / 수,목,금 11:30~15:00, 16:00~21:30 / 토 11:30~21:30 / 일 11:30~20:00', '02-733-9240', '명절 휴무'),
	(339, '개화', '04535  서울 중구 남대문로 52-5 (명동2가)', 'images/개화_339.jpg', '3대째 40여 년 전통을 이어오는 중식집. 짜장면이 맛있는 집으로도 유명\n\n3대째 40여 년 전통을 이어오는 중식집. 짜장면이 맛있는 집으로도 유명합니다. 감자와 양파, 당근, 돼지고기를 넣어 볶은 짜장에 직접 뽑은 면발 맛이 좋습니다. 홍합을 듬뿍 넣은 홍합짬뽕, 깐쇼새우, 난자완스 등도 추천할 만합니다.', 37.562120, 126.981717, '', '지하철 4호선 명동역 5번 출구, 420m', '짜장면, 짬뽕, 볶음밥, 탕수육', '일~금, 5주차 토요일', '', '음식점', '', '11:30 ~ 22:30', '02-776-0508', '1, 2, 3, 4주 토요일 휴무, 명절 휴무'),
	(340, '라미띠에', '06015  서울 강남구 도산대로67길 30 (청담동)  2층', 'images/라미띠에_340.jpg', '셰프가 손님을 직접 응대하고 친절하게 메뉴 설명도 해주는 프렌치 레스토랑\n\n셰프가 손님을 직접 응대하고 친절하게 메뉴 설명도 해주는 프렌치 레스토랑입니다. 정통 프랑스식 음식을 맛볼 수 있고, 특히 푸아그라가 맛있기로 유명합니다. 테이블은 2~3개뿐인 작은 공간이라 더욱 특별한 대접을 받는 느낌입니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.525965, 127.044573, '', '지하철 수인분당선 압구정로데오역 3번 출구, 398m', '점심코스, 저녁코스', '', '', '음식점', '', '12:00 ~ 15:00 / 17:00 ~ 22:00', '02-546-9621', '매주 화요일'),
	(341, '왕성식당', '04528  서울 중구 남대문시장길 18-2 (남창동)', 'images/왕성식당_341.jpg', '경상도 풍의 뚝배기 갈치조림으로 유명한 집\n\n경상도 풍의 뚝배기 갈치조림으로 유명한 집. 남대문시장의 갈치골목이 생긴 유래가 된 원조집이기도 합니다. 점심 시간에는 줄을 서야 할 정도로 뜨거운 뚝배기에 끓여져서 나오는 갈치조림이 일품입니다. 남대문 시장 안의 좁은 골목에 있어 찾기가 어려우니 미리 연락해서 위치를 알아두는 것이 좋습니다.', 37.559975, 126.976979, '1만원대', '지하철 4호선 회현역 5번 출구, 242m', '생선조림', '월요일~토요일', '', '음식점', '', '07:00 ~ 19:00', '02-752-9476', '매주 일요일'),
	(342, '와라쿠', '06028  서울 강남구 압구정로4길 13-7', 'images/와라쿠_342.jpg', '정통 일본식 쿠시야키를 맛볼 수 있는 곳.\n\n정통 일본식 쿠시야키를 맛볼 수 있는 곳. 다양한 꼬치류를 안주 삼아 술 마시기에 좋습니다. 최근 우후죽순으로 생긴 수많은 이자카야 중에서 제대로 된 꼬치구이를 내고 있다는 평을 받고 있습니다.', 37.522125, 127.020788, '', '지하철 3호선/ 신분당선 신사역 6번 출구, 721m', '네기마, 쇼우니꾸, 돈도로, 규단', '', ' https://www.instagram.com/waraku_sinsa', '술집, 바', '', '매일 18:00~01:00', '0507-1416-2295', ''),
	(343, '봉자네', '04427  서울특별시 용산구 이촌로 182 (이촌동)', 'images/봉자네_343.jpg', '이촌동에서 20여 년간 자리를 지키는 포장마차. 근처 일식집이나 카페에서 술을 먹다가 이곳으로 와서 마무리하는 곳.\n\n이촌동에서 20여 년간 자리를 지키는 포장마차입니다. 근처 일식집이나 카페에서 술을 먹다가 이곳으로 와서 마무리하는 곳이기도 합니다. 대표 메뉴는 매콤한 주꾸미볶음입니다.', 37.521230, 126.967374, '', '지하철 4호선 / 경의중앙선 이촌역 4번 출구, 691m', '', '월화수목금토', '', '술집, 바', '', '평일 16:00 ~ 01:00\n토요일 16:00 ~ 24:00', '02-790-8636', '매주 일요일 휴무'),
	(344, '텐카이', '04347  서울 용산구 소월로 322 (한남동, 하얏트호텔)  LL층', 'images/텐카이_344.jpg', '꼬치구이를 즐길 수 있는 일본식 정통 야키도리 전문점.\n\n꼬치구이를 즐길 수 있는 일본식 정통 야키도리 전문점. 모든 테이블이 다다미로 꾸며져 있어 아늑하고 편안합니다. 육류, 가금류, 해산물과 야채류 등 제철 재료를 이용한 약 40여 가지가 넘는 꼬치구이를 맛볼 수 있으며 일본식 사케부터 소주, 과실주까지 다양하게 갖추고 있습니다. 밤늦게까지 하지 않는 것이 아쉽습니다.', 37.539763, 126.996241, '3만원대', '지하철 6호선 한강진역 1번 출구, 887m', '덴카이세트, 시그니처 메뉴, 야키토리', '', ' https://seoul.grand.hyatt.com/ko/hotel/dining.html', '음식점', '', '매일 12:00~15:00, 18:00~22:00', '02-797-1234', '명절 휴무'),
	(345, '스페인클럽', '06028  서울 강남구 압구정로10길 26', 'images/스페인클럽_345.jpg', '타파스 바 스타일의 스페인 음식 전문점. 다양한 지중해풍의 요리\n\n타파스 바 스타일의 스페인 음식 전문점. 다양한 지중해풍의 요리들을 작은 접시로 여러 가지 즐길 수 있는 것이 큰 장점입니다. 상그리아를 곁들이면 더욱 좋습니다. 와인은 스페인산만 준비되어 있습니다.', 37.521885, 127.021871, '', '지하철 3호선/신분당선 신사역 8번 출구, 690m', '빠에야 데 마리스코스, 하몽, 오징어튀김, 감바스', '', ' http://www.spainclub.co.kr/', '음식점', '', '월~목 12:00 ~ 15:00 / 17:00 ~ 22:00\n금요일 12:00 ~ 15:00 / 17:00 ~ 23:00\n토요일 12:00 ~ 23:00 / 일요일 12:00 ~ 22:00', '0507-1496-1191', '명절 당일 휴무'),
	(346, '설매네', '06022  서울 강남구 압구정로30길 23', 'images/설매네_346.jpg', '평양식 만두전골이 유명한 곳. 돼지고기 보쌈과 탕평채가 유명.\n\n평양식 만두전골이 유명한 곳. 숙주나물과 돼지고기를 넣은 만두가 담백하며 이외에도 돼지고기 보쌈과 탕평채가 유명합니다.', 37.524828, 127.029110, '1만원대', '지하철 3호선 압구정역 3번 출구, 44m', '칼국수, 만두국, 매운갈비찜, 보쌈', '', '', '음식점', '', '매일 11:30~15:00 / 17:00~21:30', '0507-1351-0117', '명절 휴무'),
	(347, '해랑', '06119  서울 강남구 봉은사로1길 39 (논현동, 유성빌딩) 2층', 'images/해랑_347.jpg', '180석의 좌석을 보유한 대형 음식점. 신선한 제철 해산물을 가득 넣은 해물탕.\n\n강남구 모범음식점으로 선정된 업소\n\n해랑은 120평 규모 180석의 좌석을 보유한 대형 음식점이다. 신선한 제철 해산물을 가득 넣은 해물탕을 주메뉴로 판매한다. 해물탕과 함께 랍스타 사시미를 추가하면 더욱 배부른 식사를 할 수 있다. 사이드 메뉴로 대하구이, 석화, 소라숙회 등 가장 신선한 해산물을 드실 수 있다. 랍스타 사시미는 랍스타를 회와 탕으로 동시에 먹을 수 있으며 해물탕 주문시 추가가 가능하다. 해물탕에는 전복, 꽃게, 산낙지, 가리비, 키조개,갑오징어, 새우, 아구, 왕소라와 각종 조개들이 푸짐하게 들어있다.', 37.507277, 127.023888, '', '지하철 9호선/ 신분당선 신논현역 3번 출구, 321m', '해물탕, 랍스타사시미', '매일', '', '음식점', '', '주중 11:30~23:00\n주말 11:30~22:00', '02-544-7270', ''),
	(348, '강남원주추어탕', '06123  서울 강남구 강남대로110길 6', 'images/강남원주추어탕_348.jpg', '집에서 만들어 4년 이상 숙성시킨 고추장 국물을 육수로 쓰는 추어탕 전문점.\n\n집에서 만들어 4년 이상 숙성시킨 고추장 국물을 육수로 쓰는 것이 특징인 추어탕 전문점입니다. 양지머리나 곱창을 삶은 국물을 사용하기 때문에 미꾸라지 냄새가 별로 안 나고 육개장에 가까운 얼큰한 맛을 냅니다. 미꾸라지를 갈아 만든 ‘갈아서 추어탕’과 통째로 집어넣고 끓인 ‘통마리 추어탕’ 중에 선택할 수 있습니다. 식탁 위에서 직접 끓여 먹는 것이 특징입니다.', 37.504045, 127.025238, '1만원대', '지하철 9호선/ 신분당선 신논현역 5번 출구, 59m', '전복 추어탕, 갈아서 추어탕, 통마리 추어탕', '월요일~토요일', '', '음식점', '', '10-:00~22:00', '02-557-8647', '일요일, 명절 휴무'),
	(349, '채선당(신내점)', '02068  서울 중랑구 용마산로 623 (신내동, 삼부그린스포츠센터)', 'images/채선당(신내점)_349.png', '‘채소가 신선한 집’이란 뜻의 채선당. 한국식 샤브샤브와 태국식 수끼(샤브)의 조화.\n\n유기농 야채와 천연재료를 사용한 샤브샤브\n\n채선당 샤브샤브의 큰 특징은 기능성 건강 채소로 구성된 10가지 유기농 야채와 천연재료를 사용한 자체개발 육수와 소스, 각종 독소를 제거해주는 황동냄비 등을 통한 건강식으로 영양 섭취가 부족한 현대인들에게 사랑받는 대표적인 슬로우 푸드 샤브샤브입니다.', 37.606729, 127.100477, '1만원대', '지하철 6호선 /경춘선 신내역 1번출구, 843m', '월남쌈샤브, 월남쌈한우샤브, 해물샤브, 스페셜모듬샤브', '', ' http://www.chaesundang.co.kr ', '음식점', '', '매일 11:00 ~ 22:00', '02-3421-0313', '연중 무휴'),
	(350, '해초록', '06177  서울특별시 강남구 영동대로 336 (대치동)', 'images/해초록_350.jpg', '남해 청정지역을 그대로 옮겨온 자연산 활어 전문점.\n\n초록빛 바다를 그대로 옮겨온 자연산 활어 전문점\n\n남해 청정지역을 그대로 옮겨온 자연산 활어 전문점. 봄-‘도다리 (포, 세꼬시)’, 여름-‘돌돔, 광어’, 가을-‘전어, 감성돔’, 겨울- ‘돌가자미’로 이어지는 제철 활어를 맛볼 수 있습니다. 차별화된 서비스와 분위기를 제대로 갖추고, 고객 한분 한분을 소중히 대접하는 넉넉한 마음을 만날 수 있습니다.', 37.504783, 127.065920, '', '지하철 2호선 삼성역 2번 출구, 485m', '회정식 세꼬시정식 자연산 모듬회', '월요일~일요일', ' http://www.haechorok.co.kr/', '음식점', '', '12:00~22:00\n휴게시간 15:00~17:00', '02-554-5522', '명절 당일, 현충일 휴무'),
	(351, '손맛김밥', '03036  서울 종로구 자하문로15길 18', 'images/손맛김밥_351.jpg', '2대째 통인시장을 지켜온 인기 만점 김밥\n\n1980 년 문을 연 ‘ 할머니 김밥 ’ 을 어머니에게서 이어받은 지금의 사장님이 ‘ 손맛김밥 ’ 으로 다시 문을 열어 2 대 걸쳐 통인시장에서 자리를 지키고 있습니다 . 어머니의 요청으로 갓 대학에 들어간 이래로 매일 김밥 장사를 도왔던 것이 손맛김밥의 시작이었습니다 . 둘째 딸은 “ 엄마의 손맛이 좋으니 ‘ 할머니 김밥 ’ 이 아닌 ‘ 손맛김밥 ’ 으로 하자 ” 고 제안하였고 , 지금의 이름이 지어졌습니다 . 통인시장만의 독특한 화폐인 엽전으로 김밥을 구매하여 도시락 카페를 이용하는 이색 체험도 운영하고 있습니다', 37.580755, 126.969996, '', '지하철 3호선 경복궁역 2번 출구, 600m', '', '평일', ' https://mo1022.modoo.at/', '음식점', '', '07:00~18:00', '02-722-8389', '주말'),
	(352, '궁나라냉면묵밥', '03109  서울 종로구 지봉로12길 6 (숭인동, 등원빌딩)', 'images/궁나라냉면묵밥_352.jpg', '도토리묵과 육수, 여기에 양념을 한 후, 밥을 말아 먹는 것이 묵밥.\n\n도토리묵과 육수, 여기에 양념을 한 후, 밥을 말아 먹는 것이 묵밥. 메밀묵 대신 직접 쑨 도토리묵을 사용하는 것이 이곳만의 특징입니다. 미끈미끈 숟가락을 피해 도망가는 묵을 입 안에 넣으면 씹을 틈도 주지않고 스르르 목으로 넘어가 버립니다.', 37.576902, 127.015883, '1만원대', '지하철 6호선 창신역 4번 출구, 290m', '묵밥\n물냉면\n왕만두', '월요일~일요일', '', '음식점', '', '10:00~20:00', '02-744-4701', '명절'),
	(353, '문타로', '04400  서울특별시 용산구 이태원로 230-1 (한남동)', 'images/문타로_353.jpg', '닭고기, 삼겹살 등의 재료를 꼬치로 구워 내주는 집. 일본식 숯불 꼬치. 아늑한 선술집 .\n\n닭고기, 삼겹살 등의 재료를 꼬치로 구워 내주는 집. 일본식 숯불 꼬치에 술 한 잔이 부드럽게 넘어갑니다. 아늑한 선술집 분위기로 부담 없이 찾기 좋습니다.\n\n\n\n\n이전으로 휴무: 2025.04.12. ~ 2025.06.30.', 37.535520, 126.999342, '', '지하철 6호선 이태원역 2번 출구, 484m', '사시미, 굴후라이, 유린기, 가리비완자구이', '매일', '', '술집, 바', '', '평일 18:00 ~ 02:30\n주말 18:00 ~ 04:30', '02-796-7232', '명절 휴무'),
	(354, '된장예술툇마루', '03148  서울특별시 종로구 인사동4길 5-26 (인사동)', 'images/된장예술툇마루_354.jpg', '전라도에서 직접 담근 된장으로 만든 된장찌개와 된장비빔밥 전문점\n\n된장 비빔밥 전문점이다. 전라도에서 직접 담근 된장으로 만든 된장찌개를 맛볼 수 있습니다. 인사동에 있는 음식점답게 토속적이고 전통적인 인테리어입니다.', 37.573376, 126.986453, '', '지하철 1/3/5호선 종로3가역 5번 출구, 329m', '게장', '월화수목금토', '', '음식점', '', '11:30 ~ 22:30', '02-739-5683', '매주 일요일'),
	(355, '영덕회식당', '04558  서울특별시 중구 창경궁로1길 6 (충무로4가)', 'images/영덕회식당_355.jpg', '미주구리회로 막회의 원조 격인 된 20년 전통의 집.\n\n미주구리회로 서울 시내에서 채소와 초고추장에 비벼 먹는 막회의 원조 격인 된 20년 전통의 집. 겨울에는 과메기가 별미이며 식사로는 물회, 회덮밥 등이 좋습니다.', 37.562958, 126.998005, '2만원대', '지하철 3/4호선 충무로역 8번 출구, 316m', '', '', '', '음식점', '', '평일 12:00 ~ 20:50\n토요일 12:00 ~ 16:50', '02-2267-0942', '매주 일요일, 공휴일 휴무'),
	(356, '[백년가게] 역전회관', '04155  서울특별시 마포구 토정로37길 47 (염리동)', 'images/[백년가게]_역전회관_356.gif', '1929년을 시작으로 1958년까지 29년간 순천의 영동에서 상호명 \'호삼식당\', 그 후 2대째 1962년 서울 용산에 터를 잡고 역전식당이라는 상호명으로 영업을 시작, 1990년 지금의 역전회관으로 개명 후 3대째 역사와 전통 그리고 맛을 지켜오고 있으며 서울의 역사가 오래된 가족과 외식하기 좋은 맛집.\n\n1929년을 시작으로 1958년까지 29년간 순천의 영동에서 상호명 \'호삼식당\', 그 후 2대째 1962년 서울 용산에 터를 잡고 역전식당이라는 상호명으로 영업을 시작, 1990년 지금의 역전회관으로 개명 후 3대째 역사와 전통 그리고 맛을 지켜오고 있으며 서울의 역사가 오래된 가족과 외식하기 좋은 맛집입니다.', 37.542938, 126.947017, '3만원대', '지하철 5호선 / 6호선 / 경의중앙선 / 공항철도 마포역 2번 출구, 459m', '소고기구이', '', ' http://www.yukjeon.com', '음식점', '', '월~금 11:00~15:00, 17:00~22:00\n주말 11:00~15:00, 16:30~21:30', '0507-1392-0248', '명절 당일 휴무'),
	(357, '무샤', '06576  서울 서초구 서래로 33 (반포동)', 'images/무샤_357.jpg', '일본식 이자카야. 도미머리조림, 닭연골튀김, 고노와다, 간 마와 연어알과 참치가 같이 나오는 참치 도로로 우니 이쿠라 아에 등이 추천 메뉴.\n\n일본식 이자카야. 도미머리조림, 닭연골튀김, 고노와다, 간 마와 연어알과 참치가 같이 나오는 참치 도로로 우니 이쿠라 아에 등이 추천 메뉴입니다. 오픈 주방으로 되어 있으며 입구 쪽에는 다다미 석이 마련되어 있고 야외 테이블도 갖추어져 있습니다.', 37.498122, 126.998168, '', '지하철 9호선 신반포역 4번 출구, 752m', '무샤모듬사시미, 닭목살숯불구이와미나리, 닭연골튀김', '', '', '술집, 바', '', '월요일~금요일 11:00-15:00, 17:00~02:00\n토요일 17:00-02:30\n일요일 16:00-01:00', '0507-1410-8886', '명절 휴무'),
	(358, '비꼴로', '04536  서울 중구 명동6길 8 (명동2가)', 'images/비꼴로_358.jpg', '명동에서 제대로 된 파스타를 맛볼 수 있는 곳\n\n명동에서 제대로 된 파스타를 맛볼 수 있는 곳 중의 하나입니다. 담백한 피자와 부드러운 티라미수도 좋습니다. 아기자기한 분위기에 가격대비 만족도도 높습니다.', 37.562946, 126.984065, '', '지하철 4호선 명동역 6번 출구, 266m', '까르보나라, 리키토니 크림파스타, 루꼴라 프루슈토 피자', '월요일~금요일', '', '음식점', '', '11:30~15:00, 17:00~22:00', '02-756-0908', '매주 토요일, 일요일 휴무'),
	(359, '라그릴리아', '06737  서울 서초구 남부순환로 2620 (강남피타워)', 'images/라그릴리아_359.jpg', '고온의 참숯불 그릴에 익힌 요리를 선보이는 이탈리아 레스토랑\n\n고온의 참숯불 그릴에 익힌 요리를 선보이는 이탈리아 레스토랑입니다. 디저트 바에서는 셰프가 매일 만드는 20여 가지의 홈메이드 디저트를 맛볼 수 있습니다.', 37.484523, 127.037325, '', '지하철 3호선/신분당선 양재역 5번 출구, 199m', '파스타&스테이크 세트, 홈다이닝 세트, 무화가 프로슈토 플랫피자', '', ' http://dining.spc.co.kr/m/menu/lagrillia.do', '음식점', '', '매일 11:00 ~ 21:00', '02-553-9192', ''),
	(360, '서초갈비', '06719  서울 서초구 반포대로 12', 'images/서초갈비_360.jpg', '숯불에 구운 왕갈비, 생등심 구이.\n\n숯불에 구운 왕갈비, 생등심 구이를 맛볼 수 있는 집. 양옥 5층 건물로 대형화되었지만 나름대로 맛을 유지하고 있는 편입니다. 친절함이 돋보입니다.', 37.481805, 127.012920, '2만원대', '지하철 3호선 남부터미널역 5번 출구, 584m', '양념갈비, 한우불고기, 한우육회, 한우갈비살', '', ' http://blog.naver.com/baboatom17', '음식점', '', '매일 11:00-21:30', '02-582-2988', '연중무휴'),
	(361, '진진만두', '07331  서울 영등포구 국제금융로8길 34 (여의도동, 오륜빌딩)  3층', 'images/진진만두_361.jpg', '여의도의 유명한 만두집. 진한 국물과 맛있는 만두가 들어 있는 만둣국\n\n여의도의 유명한 만두집. 진한 국물과 맛있는 만두가 들어 있는 만둣국을 먹을 수 있는 곳입니다. 점심때가 되면 복도 끝까지 줄이 서 있습니다.', 37.520236, 126.927238, '', '지하철 9호선 샛강역 1번 출구, 353m\n지하철 5호선 여의도역 5번 출구, 300m', '', '월~금', '', '음식점', '', '11:00 ~ 15:00 / 17:00 ~ 21:00', '02-780-7867', '매주 토요일, 일요일'),
	(362, '한강생태', '04375  서울특별시 용산구 백범로 400 (한강로1가)', 'images/한강생태_362.jpg', '여러 가지 해물로 육수를 끓여낸 생태 매운탕이 유명한 곳. 삼겹살도 유명.\n\n여러 가지 해물로 육수를 끓여낸 생태 매운탕이 유명한 곳. 여기에 고추장을 풀고 고춧가루와 마늘을 넣어 얼큰하게 만듭니다. 동태찌개 외에 삼겹살도 유명합니다. 손님이 많아 점심때도 예약해야 합니다.', 37.535762, 126.973017, '', '지하철 4/6호선 삼각지역 8번 출구, 35m', '생태매운탕\n마늘먹은목살', '월요일~일요일', '', '음식점', '', '10:00 ~ 22:00', '02-716-7452', '연중무휴'),
	(363, '독수리다방', '03776  서울 서대문구 연세로 36 독수리빌딩 8층', 'images/독수리다방_363.jpg', '소설가 성석제, 시인 기형도가 사랑했던 아지트\n\n독수리다방은 1970~80년대 인근 대학생들의 아지트로 만남의 장소이자 공론의 장이었습니다. 본래 음악다방으로 시작해 소설가 성석제, 시인 기형도 등의 문인들에게 사랑받은 공간입니다. 커피숍이 성황을 이루면서 경영난에 빠진 독수리다방은 2005년 문을 닫았다가 2013년 선대 창업자의 손자인 대표님이 독수리다방의 역사와 정체성을 계승하겠다며 다시 문을 열었습니다. 독수리 다방에는 메모를 주고받으며 소식을 전했던 다방 게시판과 다방의 역사를 담긴 옛 사진들이 전시되어 있습니다.\n\n \n\n• 이곳은 \'서울미래유산\'으로 선정된 곳입니다. 서울의 근·현대 문화유산 중에서 미래 세대에게 전달할 만한 가치가 있는 유무형의 자산인 서울미래유산을 오래가게 여행에서 만나보세요.(https://futureheritage.seoul.go.kr)', 37.558784, 126.937240, '', '지하철 2호선 신촌역 3번 출구, 360m', '', '매일', ' https://www.instagram.com/dokdabang/#', '카페, 디저트', '', '11:00~23:30', '02-363-1222', '없음'),
	(364, '만두집', '06018  서울 강남구 압구정로 338 (신사동)', 'images/만두집_364.jpg', '큼직한 크기의, 속이 꽉 찬 평양식 만두로 20년 넘게 한 곳에서 장사\n\n큼직한 크기의, 속이 꽉 찬 평양식 만두로 20년 넘게 한 곳에서 장사하고 있는 집. 평양 출신인 할머니가 문을 연 후 2대째 그 손맛을 유지하고 있습니다. 간단한 메뉴 구성이지만 만두전골이나 만둣국이 실속 있습니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.527925, 127.038878, '', '지하철 수인분당선 압구정로데오역 6번 출구, 108m', '만둣국, 만두전골, 콩비지, 빈대떡', '월~토', '', '음식점', '', '12:00 ~ 20:00(브레이크타임 15:00~17:30)', '02-544-3710', '매주 일요일 휴무'),
	(365, '피겨앤그라운드', '06036  서울 강남구 논현로153길 53 (신사동, 피겨앤그라운드)', 'images/피겨앤그라운드_365.jpg', '지하부터 지상까지, 건물 전체가 안과 밖으로 이어진 피겨앤그라운드\n\n‘피겨앤그라운드’는 건축에서 흔히 사용되는 재료인 적벽돌옷을 입고 있지만 얇은 띠를 두른 듯한 외관이 강렬한 세련미를 내뿜습니다. 지어진 지 30여 년이 넘은 오래된 건축물의 특색을 남긴 채 재구성하여 리모델링 했다는 점에서 더 의미가 있습니다. 저층부에는 카페와 편집숍이, 상층부에는 공유 오피스가 한 건물에 함께 공존하는 ‘피겨앤그라운드’는 평일과 주말, 낮과 밤 모두 활기를 갖습니다.', 37.520162, 127.023902, '', '지하철 3호선/ 신분당선 신사역 8번 출구, 541m', '', '', '', '', '', '1층 카페(컨플릭트스토어) 매일 10:00 ~ 22:00', '', ''),
	(366, '명화당', '04536  서울특별시 중구 명동4길 30 (명동2가)', 'images/명화당_366.jpg', '30년이 넘는 오랜 전통을 자랑하는 전설적인 김밥집. 떡볶이와 비빔쫄면.\n\n30년이 넘는 오랜 전통을 자랑하는 전설적인 김밥집입니다. 김밥 외에도 떡볶이, 비빔쫄면의 맛이 환상적입니다. 떡볶이와 김밥 위주로 팔던 초창기와는 달리 지금은 만두, 우동 등의 메뉴가 다양해졌습니다. 가격대 만족도도 높은 편입니다.', 37.562374, 126.983826, '', '지하철 4호선 명동역 6번 출구, 246m', '쫄볶이 냄비국수 비빔쫄면\n손만두 김밥', '월요일 ~ 일요일', '', '음식점', '', '09:00 ~ 22:30', '02-777-7317', '명절 당일 휴무'),
	(367, '막내횟집', '04528  서울특별시 중구 남대문시장2가길 2 (남창동)', 'images/막내횟집_367.jpg', '두툼하게 썬 완도산 회 맛을 느낄 수 있는 곳. 현지에서 활어를 직송.\n\n두툼하게 썬 회 맛을 느낄 수 있는 곳. 회는 모두 완도산으로, 이틀에 한 번 현지에서 활어를 직송해 하루 정도 수족관에 보관해 놓고 선어로 적정 숙성시켜 식탁 위에 올립니다. 회덮밥을 시키면 매운탕에 고등어조림이 함께 나옵니다. 가격 대비 만족도가 높은 곳 입니다.', 37.559375, 126.976726, '', '지하철 4호선 회현역 5번 출구, 210m', '생선회', '월요일~일요일', '', '음식점', '', '09:00~22:00', '02-755-5115', '연중무휴'),
	(368, '뿌자', '03104  서울 종로구 종로 327 (창신동)', 'images/뿌자_368.jpg', '인도 네팔 정통음식을 우리 입맛에 맞게 변형시킨 인도, 네팔 요리 전문점.\n\n인도 네팔 정통음식을 우리 입맛에 맞게 변형시킨 인도, 네팔 요리 전문점입니다. 기름기 없는 담백한 맛의 난과 한국인 입맛에 맞게 변형시킨 전통 커리 등을 맛볼 수 있습니다. 뿌자란 힌두어로 기도라는 뜻입니다.', 37.572743, 127.013967, '1만원대', '지하철 1/6호선 동묘앞역 8번 출구, 102m', '버터치킨, 치킨티카 마살라, 머턴 마살라', '', '', '음식점', '', '매일 11:00~23:00', '02-744-2199', ''),
	(369, '골드피쉬 딤섬퀴진', '06018  서울특별시 강남구 압구정로48길 35 (신사동)  2층', 'images/골드피쉬_딤섬퀴진_369.jpg', '중국, 홍콩에서 살다가 건너온 셰프가 새로 문을 연 딤섬 전문점.\n\n중국, 홍콩에서 살다가 건너온 셰프가 새로 문을 연 딤섬 전문점. 딤섬 전문점답게 속이 꽉 차 있고 식감이 좋은 딤섬을 맛볼 수 있습니다. 볶음밥이나, 국수 같은 다른 메뉴들도 추천합니다.', 37.526071, 127.037107, '1만원대', '지하철 수인분당선 압구정로데오역 5번 출구, 411m', '새우딤섬, 구채교, 무떡볶음, 새우춘권, 시그니처볶음밥', '', '', '음식점', '', '11:30 ~ 15:00 / 17:30 ~ 21:40', '0507-1345-5266', ''),
	(370, '난향', '03787  서울 서대문구 신촌로 67 (거촌빌딩)', 'images/난향_370.jpg', '1993년 10월 개업 \'맛있고 깨끗한 집\'으로 선정된 중국 음식 전문점.\n\n1993년 10월 개업 이래 한국관광공사 등 여러 기관으로부터 \'맛있고 깨끗한 집\'으로 선정된 중국 음식 전문점으로서 엄선된 식자재만을 사용하여 고객의 건강을 먼저 생각하고 있습니다. 또한, 170여 평의 넓은 실내공간을 갖춘 고급 중식당으로 돌잔치, 상견례, 기업모임 등 각종 연회 및 가족모임이 가능합니다.', 37.556503, 126.934042, '', '지하철 2호선 신촌역 1번 출구, 243m', '난 (런치코스), 자장면, 전복삼선짬뽕, 탕수육', '', ' http://www.nanhyang.co.kr/', '음식점', '', '매일 11:30 ~ 15:00, 17:00 ~ 21:30', '02-322-6900', '매달 2번째 월요일, 명절 휴무'),
	(371, '미우미우', '05638  서울 송파구 양재대로71길 2-27 (방이동, 인택파크랜드)  2층', 'images/미우미우_371.jpg', '한우를 전문으로 하는 곳. 도자기 화로에 내오는 참숯.\n\n한우를 전문으로 하는 곳입니다. 도자기 화로에 내오는 참숯에 고기를 구워 먹습니다. 고기와 함께 즐길 수 있는 와인도 몇 종류 갖추고 있으며, 인테리어도 모던한 분위기입니다.', 37.511370, 127.127023, '', '지하철 5호선 방이역 4번 출구, 339m', '한우1++채끝등심, 한우1++안심, 한우1++살치살', '', ' http://blog.naver.com/suck102', '음식점', '', '평일 11:30 ~ 15:00 / 17:00 ~ 22:00\n토요일 11:30 ~ 22:00', '0507-1495-2587', '일요일, 명절 휴무'),
	(372, '사프란', '04542  서울 중구 삼일대로 362 (장교동, 롯데시티호텔 명동)  2층', 'images/사프란_372.jpg', '아랍 음식 전문점. 이슬랍 율법대로 도축한 고기 이용.\n\n아랍 음식 전문점. 인도음식과 비슷해 보이지만 이슬람 율법대로 도축한 고기만을 이용합니다. 몸안에 있는 피를 모두 빼낸 고기인 할랄은 누린내가 없어 맛이 좋습니다.', 37.565160, 126.980850, '', '지하철 2/ 3호선 을지로 3가역 1번 출구, 169m', '치킨한디, 램브한디, 홈모스', '', '', '음식점', '', '11:30 ~ 22:30', '02-6361-8644', '격주 월요일 휴무'),
	(373, '함평면옥', '03721  서울 서대문구 성산로 527 (대신동, 하늬솔빌딩)', 'images/함평면옥_373.jpg', '푸짐한 만두전골과 김치말이 국시로 유명한 집.\n\n푸짐한 만두전골과 김치말이 국시로 유명한 집입니다. 버섯만두전골은 소고기 육수에 갖가지 버섯과 김치 만두를 끓인 것으로 고기와 국수사리를 곁들여 먹는 맛이 일품입니다. 인기 메뉴인 김치말이국시는 뚝배기에 시원한 김칫국물에 면을 말아 내옵니다.', 37.563775, 126.944090, '1만원대', '지하철 경의중앙선 신촌역 2번 출구, 562m\n지하철 2호선 이대역 2번 출구, 1.2km', '만두전골, 어복쟁반, 갈비탕, 냉면', '', '', '음식점', '', '평일 11:00 ~ 21:00\n토요일 11:00 ~ 15:00', '02-392-3516', '매주 일요일, 명절 휴무'),
	(374, '당고집', '04073  서울특별시 마포구 어울마당로3길 5 (합정동)', 'images/당고집_374.jpg', '일본의 당고라는 떡꼬치의 일종을 한국식으로 만드는 곳. 둥근 모양의 떡을 꼬치에 끼운 후 단팥이나 녹차 팥, 딸기 팥 등의 고물로 장식. 일본식 카레와 오니기리.\n\n일본의 당고라는 떡꼬치의 일종을 한국식으로 만드는 곳. 둥근 모양의 떡을 꼬치에 끼운 후 단팥이나 녹차 팥, 딸기 팥 등의 고물을 올려 즐깁니다. 그 외에도 일본식 카레와 오니기리도 맛볼 수 있습니다.', 37.547234, 126.919320, '', '지하철 6호선 상수역 4번 출구, 347m', '벚꽃당고, 간장당고, 단팥당고, 명란버터밥', '', ' http://instagram.com/the_dangojip', '카페, 디저트', '', '화요일~일요일 12:00 ~ 21:00', '070-7573-3164', '매주 월요일, 명절 휴무'),
	(375, '일품당', '03183  서울 종로구 세종대로23길 25', 'images/일품당_375.jpg', '신선한 샤브샤브와 스키야키를 맛볼 수 있는 곳으로 가쓰오부시와 다시마로 뽑은 육수.\n\n일본식 샤부샤부와 스키야키를 맛볼 수 있는 곳으로 가쓰오부시와 다시마로 뽑은 육수가 감칠맛 납니다. 직접 만드는 스키야키 소스, 간장폰즈 등도 독특한 맛을 살려줍니다. 식사로는 면이나 죽이 나옵니다. 현대적이고 깔끔한 인테리어에 일 인분씩 서빙되기 때문에 손님을 모시기에도 좋습니다.', 37.571490, 126.975013, '2만원대', '지하철 5호선 광화문역 8번 출구, 41m', '일품샤브샤브, 일품스키야끼, 해물샤브샤브, 일품와규샤브샤브', '', ' https://ilpumdang.modoo.at/', '음식점', '', '매일 11:30~15:00 / 17:00~22:00', '02-733-4949', '명절 휴무'),
	(376, '타지', '04538  서울특별시 중구 명동길 73 (명동1가)   YWCA연합회 2F', 'images/타지_376.jpg', '인도에서 공수된 재료와 인도인 셰프가 인도 북부의 음식을 재현\n\n인도에서 공수된 재료와 인도인 셰프가 인도 북부의 음식을 재현합니다. 모든 메뉴가 채식과 채식이 아닌 메뉴로 나누어져 있어 취향에 따라 선택할 수 있습니다. 인도 사람들은 주로 채식을 하기 때문에 채식 마니아를 위한 커리와 탄두 요리가 다양하며 인기가 좋습니다. 고급스러운 인테리어에서 인도 음식을 즐길 수 있는 곳입니다', 37.564390, 126.986231, '', '지하철 2호선 을지로입구역 5번 출구, 487m', '치킨커리, 오늘의채식커리', '화 ~ 일요일', ' https://www.instagram.com/welcometo_taj/', '음식점', '', '평일 11:30 ~ 15:00 / 17:30 ~ 22:00\n주말 11:30 ~ 22:00', '0507-1410-0677', '매주 월요일'),
	(377, '충무김밥', '04536  서울 중구 명동10길 16 (명동2가)', 'images/충무김밥_377.jpg', '통영의 할매김밥을 서울에 소개하여 충무김밥의 열풍을 몰고 왔던 원조집.\n\n통영의 할매김밥을 서울에 소개하여 충무김밥의 열풍을 몰고 왔던 원조집입니다. 밥만 들어 있는 조그만 김밥을 대충 썬 깍두기, 오징어 무침과 먹는 것이 별미입니다. 오징어 무침과 깍두기인 유일한 반찬은 계속해서 리필이 가능합니다. 다만 충무에서 맛본 그 맛을 기대하고 오는 사람이라면 약간 실망할 수도 있습니다.', 37.563138, 126.985197, '1만원대', '지하철 4호선 명동역 8번 출구, 252m', '충무김밥', '월요일~일요일', '', '음식점', '', '평일 09:30 ~ 22:00\n주말 09:00 ~ 22:00', '02-755-8488', '명절휴무'),
	(378, '국시집', '02880  서울특별시 성북구 창경궁로43길 9 (성북동1가)', 'images/국시집_378.jpg', '깔끔한 손칼국수 집. 양지머리 국물에 국수와 양념장.\n\n깔끔한 음식으로 알려진 손칼국수 집. 미리 예약을 해 놓지 않으면 자리 차지하기가 어렵습니다. 정오부터 2시경까지 예정량을 팔고 나면 더는 팔지 않습니다. 양지머리 국물에 국수와 양념장뿐인데, 면발이 하늘하늘하면서 부드러운 스타일입니다.', 37.588428, 127.004307, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 191m', '국시, 전, 문어', '', '', '음식점', '', '11:30 ~ 14:30 / 17:00 ~ 21:00', '02-762-1924', '매주 월요일, 명절 휴무'),
	(379, '카페 할아버지공장', '04781  서울 성동구 성수이로7가길 9 (성수동2가)  카페 할아버지공장', 'images/카페_할아버지공장_379.jpg', '성수동에 핫플레이스로 자리 잡은 카페 할아버지 공장은 볼거리가 많은 대형카페. 드라마 빈센조, 예능 놀면 뭐 하니의 싹쓸이편 촬영지로도 유명한 곳.\n\n성수동에 핫플레이스로 자리 잡은 카페 할아버지공장은 볼거리가 많은 대형카페입니다. 드라마 빈센조, 예능 놀면 뭐하니의 싹쓸이편 촬영지로도 유명한 곳입니다. 공장을 개조하여 재탄생한 카페로 낡은 외관의 모습과 내부의 감각적인 인테리어가 빈티지한 분위기를 느낄 수 있게 합니다. 큰 카페인만큼 단체석, 테라스 공간, 계단 의자 등 다양한 공간에 좌석이 구비되어 있습니다. 커피와 에이드뿐만 아니라 브런치, 파스타, 피자, 맥주 등 다양한 음료와 식사도 함께 할 수 있습니다. 1층에도 테라스가 있지만 3층 야외 옥상도 있어 날씨가 좋은 날 방문하면 바깥 풍경과 함께 예쁜 카페 할아버지공장의 내. 외부를 즐길 수 있습니다.', 37.541175, 127.054960, '', '지하철 2호선 성수역 3번 출구, 412m', '커피 6,000원~8,000원\n에이드/칵테일 8,000원~13,000원\n파스타 19,000원~23,000원', '매일', ' http://gffactory.co.kr', '카페, 디저트', '', '11:00 - 22:00', '0507-1317-2301', ''),
	(380, '동경식당', '07320  서울특별시 영등포구 여의대로 8 (여의도동)', 'images/동경식당_380.jpg', '모던일식을 내세우는 일식 가정식 전문점.\n\n모던일식을 내세우는 일식 가정식 전문점. 일본풍이면서도 모던한 실내 분위기에서 깔끔한 일식을 맛볼 수 있습니다. 직접 만드는 수제 오뎅이 유명하며 저녁때 사케를 즐기기에도 좋습니다. 가격대는 좀 높은 편입니다.', 37.521218, 126.918584, '', '지하철 5/ 9호선 여의도역 1번 출구, 578m', '찌라시스시, 동경식당초밥, 해물우동, 돈까스덮밥', '', ' https://www.instagram.com/tokyomc786/#', '음식점', '', '11:00 - 22:00\n14:00 - 17:30 (브레이크타임)', '02-786-7220', '일요일, 명절 당일 휴무'),
	(381, '을밀대', '04138  서울 마포구 숭문길 24', 'images/을밀대_381.jpg', '40여 년 역사의 평양식 냉면집. 서울 3대 평양냉면중 하나.\n\n40여 년 역사의 평양식 냉면집. 직접 눌러서 만든 냉면 사리에 살짝 얼음이 언 육수를 끼얹어 나옵니다. 반죽에 전분이 많이 들어가는 편으로, 냉면 스타일이 호불호가 극명하게 갈리는 집 중의 하나입니다. 차돌로 만든 수육도 일품입니다. 다만 최근 확장을 거듭하고 있다는 점에 불안해하는 팬들도 많이 있습니다.', 37.547475, 126.945481, '1만원대', '지하철 6호선 대흥역 2번 출구, 408m', '물냉면, 회냉면, 녹두전, 수육', '', '', '음식점', '', '매일 11:00~22:00', '02-717-1922', '명절 휴무'),
	(382, '싱카이 역삼점', '06141  서울 강남구 논현로 508 (역삼동, GS강남타워)  지하 1층', 'images/싱카이_역삼점_382.jpg', '1930년대 상하이의 고급 레스토랑 분위기를 주는 곳, 광동식 사천요리.\n\n1930년대 상하이의 고급 레스토랑 분위기를 주는 곳. 광동식과 매콤한 사천식 요리를 주로 선보이며, 신선한 활어 및 해산물을 강한 불에 빠르게 볶아내는 조주식 요리와 타이, 말레이시아의 영향을 받은 오리엔탈 요리도 맛볼 수 있습니다.', 37.501995, 127.037336, '2만원대', '지하철 2호선 역삼역 7번 출구, 183m', '비즈니스 코스, 점심 코스, 유린기, 싱카이 냉채, 중화 칠리 쉬림프, 팔보라조', '월요일~토요일', ' http://www.ourhomehospitality.com/brand/brandBranch.do?brandSeq=11&branchSeq=68', '음식점', '', '11:30~14:30, 17:30~21:30', '02-2005-1003', '일요일'),
	(383, '기소야', '06168  서울 강남구 삼성로92길 13 (삼성동)', 'images/기소야_383.jpg', '삼성동 본점 일식 우동.소바 전문점.\n\n한때 장안의 화제가 될 정도로 많은 분점을 거느리고 있기도 했던 기소야는 역시 삼성동 본점의 맛이 최고입니다. 다른 분점과는 다른 독특한 분위기가 살아 있습니다. 일식 우동에 김치나 고춧가루 등의 한국적인 맛을 절묘하게 조화시켰습니다. 다양한 종류의 정식이 있으며 모두 우동이 곁들여집니다.', 37.508002, 127.057579, '1만원대', '지하철2호선 삼성역 5번 출구, 485m', '김치우동정식, 돈까스자루소바, 가쯔나베정식', '', ' http://www.kisoya.co.kr/', '음식점', '', '매일 11:00~20:30', '02-554-7077', '명절 휴무'),
	(384, '삼호복집', '03789  서울특별시 서대문구 연세로5다길 10 (창천동)', 'images/삼호복집_384.jpg', '복어 하나로 30여 년 동안 변함없이 사랑받는 곳. 탕 요리가 일품.\n\n복어 하나로 30여 년 동안 변함없이 사랑받는 곳. 신선한 복과 싱싱한 채소, 시원하고 개운한 국물 맛을 내는 탕 요리가 일품입니다. 얇게 저민 복어 살로 버섯과 채소를 돌돌 말아 살짝 익혀 먹는 복어 샤브샤브도 인기가 있습니다. 이 외에도 복스시, 버섯찜, 된장 뚝배기 등도 먹을 만합니다.', 37.556524, 126.934996, '', '지하철 2호선 신촌역 1번 출구, 204m', '복매운탕\n맑은뚝배기\n복고니', '월요일~토요일', '', '음식점', '', '11:30~21:30', '02-337-9019', '매주 일요일'),
	(385, '백제삼계탕', '04536  서울 중구 명동8길 8-10 (명동2가)', 'images/백제삼계탕_385.jpg', '40여 년 동안 대를 이어 한결같은 전통의 맛을 지켜온 삼계탕집.\n\n40여 년 동안 대를 이어 한결같은 전통의 맛을 지켜온 곳. 육질이 부드러운 웅추(어린 장닭)만을 골라 오랜 시간 마늘과 파, 생율, 인삼, 대추 등을 넣어 푹 고아 만듭니다. 삼계탕에 곁들이는 김치, 깍두기, 마늘무침과 찹쌀밥도 맛이 좋으며 통닭 또한 인기 있습니다. 손님의 절반 이상이 일본인 관광객입니다.', 37.563372, 126.984101, '1만원대', '지하철 4호선 명동역 5번 출구, 420m', '삼계탕\n통닭\n전복죽', '월요일~일요일', '', '음식점', '', '09:00~22:00 (21:00 라스트오더)', '02-776-3267', '연중무휴'),
	(386, '돈수백', '04051  서울 마포구 홍익로6길 74 (동교동)', 'images/돈수백_386.gif', '부산 정통 돼지국밥 전문점\n\n믿을 수 있게 조리된 돼지고기를 먹고 백세까지 건강한 삶을 누리자"라는 철학을 담은 돼지국밥 전문점입니다.', 37.556948, 126.925284, '', '지하철 2호선/ 공항철도/경의중앙선 홍대입구역 8번 출구, 129m', '돼지국밥', '월화수목금토일', '', '음식점', '', '24시간 영업', '02-324-3131', '연중무휴'),
	(387, '리베르떼', '06300  서울 강남구 논현로26길 55  1층', 'images/리베르떼_387.jpg', '셰프가 그날 장을 봐서 메뉴를 구성하는 코스로만 운영\n\n셰프가 그날 장을 봐서 메뉴를 구성하는 코스로만 운영되며 애피타이저부터 디저트까지 10가지 정도가 나옵니다. 당일 예약은 받지 않으므로 적어도 전날까지는 예약을 해야 코스를 즐길 수 있습니다.', 37.484385, 127.046297, '', '지하철 3호선 매봉역 4번 출구, 320m', '', '', ' https://app.catchtable.co.kr/ct/shop/liberte', '음식점', '', '매일 12:00 ~ 15:00 / 18:00 ~ 22:00', '02-577-1044', ''),
	(388, '춘천집닭갈비막국수', '03789  서울 서대문구 연세로5가길 1 (창천동)', 'images/춘천집닭갈비막국수_388.jpg', '닭갈비 고기에 매운 양념을 하여 철판에 볶아 먹는 닭갈비집.\n\n닭갈비 고기에 매운 양념을 하여 철판에 볶아 먹는 곳. 닭갈비에 뼈를 발라내어 먹기 좋습니다. 곁들여지는 마카로니와 김치는 계속 리필 가능합니다.', 37.557051, 126.936097, '', '지하철 2호선 신촌역 1번 출구 210m', '닭갈비', '화,수,목,금,토,일', '', '음식점', '', '11:00~15:00, 16:00~22:30', '0507-1303-2361', '매주 월요일'),
	(389, '아따블르', '03054  서울 종로구 팔판길 36 (팔판동)', 'images/아따블르_389.jpg', '편하고 세련된 프랑스 밥상을 선보이는 프랑스식 레스토랑.\n\n편하고 세련된 프랑스 밥상을 선보이는 프랑스식 레스토랑. 그날 장 본 재료를 사용하여 오늘의 메뉴를 짭니다. 주문은 코스로만 할 수 있으며 메인 메뉴는 소고기 안심, 등심 스테이크, 양 갈비 등에서 선택하게 되어 있습니다. 양 갈비를 선택하면 5천 원이 추가됩니다. 예약은 필수입니다.', 37.583355, 126.981341, '', '지하철 3호선 안국역 1번 출구, 1.1km', '', '', ' https://www.instagram.com/atable_restaurant_officiel/#', '음식점', '', '화요일 12:00~15:00\n수요일~토요일 12:00~15:00 / 18:00~21:00', '02-736-1048', '매주 일요일, 월요일, 명절 휴무'),
	(390, '레드마블하우스', '06224  서울 강남구 논현로 408', 'images/레드마블하우스_390.jpg', '고급스러운 분위기에서 한우 1++ 등급의 최상급 고기를 즐길 수 있는 곳.\n\n고급스러운 분위기에서 한우 고기를 즐길 수 있는 곳입니다. 한우 1++ 등급의 최상급 고기를 사용합니다. 고기구이를 시키면 한정식 수준의 반찬들이 정갈하게 깔립니다. 배기 조절도 테이블에서 직접 할 수 있는 등 첨단 설비가 돋보입니다.', 37.496686, 127.039165, '', '지하철 2호선 역삼역 1번 출구, 449m', '레드마블 명품 살치살, 로스편채, 레드마블 한우국수전골', '일요일', ' http://www.redmarble.co.kr/', '음식점', '', '평일 11:30~14:30 / 17:30~22:00\n토요일 11:30~22:00', '1644-3392', '명절 휴무'),
	(391, '강가 잠실점', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰)  6층', 'images/강가_잠실점_391.jpg', '2000년 신사본점을 시작으로 전국에 매장을 두고 있는 인도 정통요리 전문점\n\n강가는 2000년 신사본점을 시작으로 전국에 매장을 두고 있는 인도 정통 요리 전문점입니다. 인도 경력 20년 이상된 인도 요리 전문 셰프가 각 매장을 주기적으로 체크하며 모든 메뉴는 MSG를 사용하지 않고 약 20여 가지의 향신료 만으로 맛을 냅니다.', 37.513713, 127.104302, '', '지하철 2/8호선 잠실역 10번 출구, 22m', '탄두리 치킨 26,500원\n비프 도 피아자 24,500원\n강가 셰프 코스 49,000원\n치킨 마크니 23,500원', '매일', '', '음식점', '', '10:30~22:00', '02-3213-4635', ''),
	(392, '황우양곱창', '06147  서울 강남구 언주로98길 5 (역삼동)', 'images/황우양곱창_392.jpg', '질 좋은 원재료를 잘 손질해서 내는 양곱창집. 메뉴는 양곱창 한 가지\n\n질 좋은 원재료를 잘 손질해서 내는 양곱창집. 메뉴는 양곱창 한 가지이지만 양념을 한 것과 안 한 것 중에 선택할 수 있습니다. 드럼통 석쇠에 구워 먹는 곱창집으로, 매일 마장동 도축장에서 가져오는 신선한 재료를 사용합니다.', 37.505177, 127.042176, '', '지하철 2호선/수인분당선 선릉역 5번 출구, 605m', '', '월화수목금토', '', '음식점', '', '11:30 ~ 23:00', '02-554-8539', '매주 일요일, 명절 휴무'),
	(393, '청송옥', '04515  서울 중구 서소문로11길 14 (서소문동)', 'images/청송옥_393.jpg', '서소문에서 장터 국밥으로 유명한 집.\n\n서소문에서 장터 국밥으로 유명한 집. 소고기와 무가 들어 있는 사골국물로 된 장터 국밥에 국수를 말아 먹습니다. 해장에도 좋습니다.', 37.563524, 126.973056, '', '지하철 1/2호선 시청역 10번 출구, 170m', '소고기국밥', '월요일~토요일', '', '음식점', '', '주중 10:00~14:30, 16:30~22:00\n토 10:00 - 21:30', '02-754-1547', '매주 일요일, 명절 휴무'),
	(394, '장사랑', '06023  서울 강남구 언주로165길 7-4 (신사동)', 'images/장사랑_394.jpg', '가야금 산조를 들으면서 곤드레 솥밥, 묵사발, 들깨 수제비 등을 맛볼 수 있는 곳.\n\n가야금 산조를 들으면서 곤드레 솥밥, 묵사발, 들깨 수제비 등을 맛볼 수 있는 곳입니다. 곤드레 솥밥은 주문하면 밥을 짓기 시작하므로 시간이 좀 걸리는 것을 고려하여야 합니다. 묵사발과 바싹불고기가 특히 인기있으며, 검은콩 막걸리도 이 집만의 특색 있는 메뉴입니다.', 37.525579, 127.032308, '', '지하철 3호선 압구정역 3번 출구, 443m', '곤드레솥밥,바싹불고기정식,들깨수제비, 고등어구이', '', '', '음식점', '', '매일 11:00 ~ 16:00 / 17:00 ~ 21:00', '02-546-9994', '명절 휴무'),
	(395, '나인스게이트그릴', '04533  서울특별시 중구 소공로 106  (소공동)', 'images/나인스게이트그릴_395.jpg', '우리나라에서 가장 오래된 프랑스 요리 전문 레스토랑\n\n우리나라에서 가장 오래된 프랑스 요리 전문 레스토랑으로, 2011년 5월에 그동안의 전통적인 모습에서 탈피하여 캐주얼한 브라스리 콘셉트로 재오픈하였습니다. 인테리어가 발랄해진 만큼 좀 더 부담없이 즐길 수 있도록 가격대도 다양해지고 선택의 폭이 넓어졌습니다. 다양한 부위와 그램으로 준비된 한우 스테이크 메뉴가 기대됩니다. 2025년에 미쉐린 가이드에 선정되었습니다.', 37.564484, 126.980185, '', '지하철 1/2호선 시청역 6번 출구, 340m', '블랙트러플로 향을 낸 포치니 버섯 소스의 카바텔리, 허브와 레드 와인에 숙성한 양갈비 구이와 작두콩', '', ' https://app.catchtable.co.kr/ct/shop/theninthgate?from=share', '음식점', '', '평일 : 07:00 ~ 10:00 / 12:00 ~ 15:00 / 18:00 ~ 22:00\n주말,공휴일 : 12:00 ~ 15:00 / 18:00 ~ 22:00', '02-317-0366', '연중무휴'),
	(396, '보건옥', '04546  서울 중구 창경궁로8길 12 (주교동)', 'images/보건옥_396.jpg', '김치찌개와 삼겹살로 유명한 을지로4가 방산시장에 있는 숨은 맛집.\n\n김치찌개와 삼겹살로 유명한 곳으로, 을지로4가 방산시장에 있는 숨은 맛집입니다. 이 외에도 가격대비 질 좋은 소 불고기를 맛볼 수 있습니다. 김치찌개는 점심때만 합니다.', 37.568528, 126.998756, '1만원대', '지하철 2/ 5호선 을지로4가역 4번 출구, 122m', '', '월요일~토요일', '', '음식점', '', '10:30~21:30', '02-2275-3743', '매주 일요일, 명절 휴무'),
	(397, '우미각', '06050  서울 강남구 언주로141길 6  백향빌딩 1층', 'images/우미각_397.jpg', '한우 암소 생등심전문점. 고기는 마블링 좋으며 연한 편\n\n한우 암소 생등심전문점. 고기는 마블링 좋으며 연한 편입니다. 버섯, 가래떡과 같이 구리 불판 위에 올려 숯불에 구워 먹습니다. 샤부샤부도 인기가 좋으며 반찬과 찌개 맛도 좋습니다.', 37.518844, 127.034219, '', '지하철 7호선 학동역 10번 출구, 629m', '한우특생등심, 보리굴비정식, 한우 특꽃등심', '', '', '음식점', '', '월~금 11:00~15:00, 16:30~21:30', '0507-1415-8802', '매주 토요일, 일요일'),
	(398, '신미식당', '06023  서울 강남구 압구정로 214 (현대종합상가빌딩)', 'images/신미식당_398.jpg', '20여 년의 역사. 감자탕과 삼겹살, 매운 돼지갈비 숯불구이.\n\n20여 년의 역사. 감자탕과 삼겹살, 매운 돼지갈비 숯불구이가 맛있습니다. 푸짐하게 나오는 갈비의 양이 만족도를 높입니다. 평일에는 자리가 없을 정도입니다.', 37.527994, 127.030735, '1만원대', '지하철 3호선 압구정역 2번 출구, 210m', '생삼겹살, 감자탕, 부대찌개, 북어탕', '일요일~금요일', '', '음식점', '', '11:00 ~ 15:00 / 17:00 ~ 22:00', '02-516-4900', '매주 토요일, 명절 휴무'),
	(399, '강남따로국밥', '06526  서울 서초구 신반포로47길 118 (잠원동, 근생빌딩)  2층', 'images/강남따로국밥_399.jpg', '선지따로국밥 한 가지 메뉴로 20년 넘게 지켜온 전통의 맛\n\n선지따로국밥 한 가지 메뉴로 20년 넘게 지켜온 전통의 맛입니다. 국밥에는 콩나물, 대파, 선지, 소고기 등이 들어가 있어 푸짐하며, 대파와 소고기를 많이 넣고 우려낸 진한 소고기 향의 국물이 담백하면서 시원합니다.', 37.515568, 127.018826, '', '지하철 3호선/신분당선 신사역 4번 출구, 123m', '선지따로국밥, 수육', '', '', '음식점', '', '평일 07:00~15:30, 17:00~21:00 / 주말 07:00~21:00', '02-543-2527', '명절 휴무'),
	(400, '최대감네', '03148  서울 종로구 인사동8길 12-3 (경운동)', 'images/최대감네_400.jpg', '한옥 7채를 터서 만든 큰 규모. 주먹밥을 얹은 상추와 고기, 육수가 나오는 상추샤브샤브.\n\n인사동 골목 끝에 있지만, 입구에 들어서면 한옥 7채를 터서 만든 큰 규모의 한옥 건물이 자리 잡고 있습니다. 점심 메뉴로 동그란 주먹밥을 얹은 상추와 고기, 육수가 나오는 상추샤부샤부가 인기 있습니다. 돼지갈비와 소고기도 좋습니다.', 37.574061, 126.986113, '3만원대', '지하철 3호선 안국역 5번 출구, 376m', '연잎쌈정식, 상추쌈밥, 연잎 불고기 정식', '', '', '음식점', '', '매일 11:30 ~ 21:00', '0507-1401-9355', '명절 당일 휴무'),
	(401, '마포옥', '04165  서울특별시 마포구 토정로 312 (용강동)', 'images/마포옥_401.gif', '60년 전통의 설렁탕집. 차돌박이 진한 국물에 양지 등의 고기가 푸짐한 설렁탕.\n\n60년 전통의 설렁탕집. 차돌박이를 넣은 진한 국물에 양지 등의 고기가 푸짐하게 들어간 설렁탕이 대표 메뉴. 배추김치, 깍두기, 파김치 등의 다양한 김치가 함께 곁들어지는 것도 특징입니다.', 37.539874, 126.943351, '3만원대', '지하철 5호선 마포역 1번 출구, 263m', '양지설렁탕\n차돌탕\n차돌수육', '월요일~일요일', '', '음식점', '', '평일 07:00 ~ 21:00\n주말 07:00 ~ 17:00', '02-716-6661', '연중무휴'),
	(402, '베이징코야', '03143  서울 종로구 율곡로2길 25 (수송동, 연합뉴스빌딩) 지하 1층', 'images/베이징코야_402.jpg', '서울에서는 보기 드문 북경오리를 전문으로 하는 곳.\n\n서울에서는 보기 드문 북경오리를 전문으로 하는 곳. 중국 전취덕에서 기술을 전수받은 정통 북경오리를 선보입니다. 오리 고기 조각을 전병에 올려 오이, 쪽파 썬 것을 얹고 다크플럼 소스를 넣어서 먹는 맛이 일품입니다. 오리를 썰고 남은 뼈를 하루 정도 푹 곤 다음 한약재와 복분자, 구기자를 넣고 끓여낸 육골즙이 담백하고 고소합니다. 북경 오리 외의 일반 중식 요리도 기본 이상은 합니다.', 37.574364, 126.980517, '3만원대', '지하철 5호선 광화문역 2번 출구, 527m\n지하철 3호선 안국역 6번 출구, 453m', '북경오리구이, 오리고기 마늘소스 볶음, 돼지고기 탕수육', '', ' http://www.베이징코야.com/', '음식점', '', '평일 11:30~15:00, 17:00~21:30\n주말 11:30~21:00', '02-313-5292', '명절 휴무'),
	(403, '비스트로드욘트빌', '06014  서울 강남구 선릉로158길 13-7 (청담동)  이안빌딩 1층', 'images/비스트로드욘트빌_403.jpg', '캐주얼한 분위기의 프렌치 레스토랑. 정통 프렌치 비스트로를 즐길 수 있는 곳\n\n캐주얼한 분위기의 프렌치 레스토랑. 정통 프렌치 비스트로를 즐길 수 있는 곳입니다. 코스 메뉴는 가격이 높지만 훌륭한 단품 메뉴도 잘 갖추어져 있습니다. 코스를 주문할 경우 원하는 디저트를 선택해서 먹을 수 있습니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.526074, 127.041233, '', '지하철 수인분당선 압구정로데오역 4번 출구, 234m', '런치 클래식, 디너 트래디션', '', ' https://www.instagram.com/yountvillebistro/', '음식점', '', '11:30~15:00, 18:00~22:00', '0507-1448-1552', '매주 월요일'),
	(404, '허형만의압구정커피집', '06001  서울 강남구 압구정로 151 (현대아파트)', 'images/허형만의압구정커피집_404.jpg', '전국에서 손꼽히는 커피 명가. 유명 로스터 허형만 씨가 내려주는 질 좋은 커피. 아담한 공간이라 테이크아웃 추천.\n\n전국에서 손꼽히는 커피 명가. 유명 로스터 허형만 씨가 내려주는 질 좋은 커피를 맛볼 수 있습니다. 아담한 공간이라 테이크아웃을 추천합니다.', 37.526786, 127.024455, '', '지하철 3호선 압구정역 6번 출구, 268m', '', '월요일~토요일', ' https://smartstore.naver.com/hcoffee', '카페, 디저트', '', '평일 08:00 ~ 19:00, 토요일 08:00 ~ 18:00', '0507-1367-5078', '매주 일요일, 공휴일 휴무'),
	(405, '눈나무집', '03050  서울특별시 종로구 삼청로 136-1 (삼청동)', 'images/눈나무집_405.jpg', '시원한 김치말이국수. 달콤하고 담백한 떡갈비와 고소한 녹두빈대떡과 함께.\n\n주 메뉴는 시원한 김치말이국수. 달콤하고 담백한 떡갈비와 고소한 녹두빈대떡은 함께 곁들이기 좋습니다. 깔끔한 실내 분위기와 적당한 가격, 그리고 누구나 좋아할만한 맛으로 항상 손님이 많습니다.', 37.587491, 126.981899, '1만원대', '지하철 3호선 안국역 1번 출구, 1.5km', '떡갈비, 녹두빈대떡, 두부김치, 평양만두, 김치말이국수', '월요일~일요일', '', '음식점', '', '11:00 ~ 21:00', '02-739-6742', '명절 휴무'),
	(406, '만족오향족발', '04514  서울특별시 중구 서소문로 134-7 (서소문동)', 'images/만족오향족발_406.jpg', '마니아를 많이 거느리는 전설적인 오향 족발집.\n\n마니아를 많이 거느리는 전설적인 오향 족발집. 오향을 사용하여 비린내를 없앤 족발이 인기가 좋습니다. 식사로는 만둣국이 기본으로 나옵니다. 4시에 영업을 시작하지만, 저녁 늦게 가면 족발이 다 떨어질 수도 있으므로 서둘러야 합니다. 간판에는 족발만두라고만 쓰여 있으므로 잘 찾아야 합니다. 미쉐린 가이드 서울 2025에 선정.', 37.563258, 126.976014, '', '지하철 1/2호선 시청역 8번 출구, 70m', '', '매일', ' http://www.manjok.net/', '음식점', '', '평일 11:30 ~ 22:00\n주말 12:00 ~ 22:00', '02-753-4755', '명절 휴무'),
	(407, '성민촌', '07327  서울 영등포구 여의나루로 71 (여의도동, 동화빌딩)  지하 1층', 'images/성민촌_407.jpg', '20년 전통의 샤브샤브 전문점. 매일 여수에서 직송 받는 해물이 신선.\n\n20년 전통의 샤부샤부 전문점. 매일 여수에서 직송 받는 해물이 신선합니다. 점심에는 국수전골이나 만두전골이 인근 직장인들에게 인기가 있습니다.', 37.523781, 126.926874, '', '지하철 9호선/ 5호선 여의도역 5번 출구, 333m', '해물국수전골, 소고기국수전골, 만두전골', '', '', '음식점', '', '10:00~22:00', '02-780-6262', '추석 휴무'),
	(408, '앵콜칼국수', '06719  서울 서초구 효령로52길 69 (서초동)', 'images/앵콜칼국수_408.jpg', '두부로 유명한 백년옥에서 낸 백년옥 별관 겸 칼국수집. 매생이칼국수와 팥칼국수.\n\n두부로 유명한 백년옥에서 낸 백년옥 별관 겸 칼국수집. 백년옥의 인기 메뉴였던 매생이칼국수와 팥칼국수를 맛볼 수 있습니다. 매생이와 굴을 넣고 끓인 매생이 칼국수에 매생이 굴전을 곁들이면 좋습니다. 현재 이름은 목천집이지만, 옛날 이름인 앵콜칼국수로도 많이 알려져 있습니다.', 37.481299, 127.013408, '1만원대', '지하철 3호선 남부터미널역 5번 출구, 600m', '옛날칼국수, 팥칼국수, 매생이굴전, 냉콩국수, 팥죽', '월화수목금토일', '', '음식점', '', '11:00 ~ 21:00', '02-525-8418', '명절휴무'),
	(409, '백원', '07241  서울 영등포구 여의공원로 101 (여의도동, C.C.M.M빌딩)  12층', 'images/백원_409.jpg', '중국 4대 지방의 요리를 골고루 맛볼 수 있는 곳.\n\n불도장과 상어지느러미찜, 북경식 오리껍질 요리, 전가복, 죽생 제비집 등 중국 4대 지방의 요리를 골고루 맛볼 수 있습니다. 여의도 공원 및 한강을 볼 수 있는 뛰어난 전망을 자랑합니다. 다양한 크기의 별실이 준비되어 있어 비즈니스 모임에도 좋습니다.', 37.529272, 126.924893, '', '지하철 9호선 국회의사당역 3번 출구, 700m', '불도장, 상어지느러미찜, 오늘의특선', '평일', ' https://www.instagram.com/whitegarden1998/', '음식점', '', '11:00 ~ 14:00 / 17:30 ~ 22:00', '02-784-6161', '주말, 명절 휴무'),
	(410, '두오모', '03042  서울특별시 종로구 자하문로16길 5 (효자동)', 'images/두오모_410.jpg', '이탈리아 가정식 브런치 카페.\n\n이탈리아 가정식 브런치 카페. 이탈리아 시골 농가의 소박한 가정식과 와인, 핸드 드립 커피를 맛볼 수 있으며 쿠킹에 관련된 세계 각국의 다양한 책도 만날 수 있습니다. 오후 2시에서 6시 사이는 음료만 가능합니다.', 37.581652, 126.971560, '', '지하철 3호선 경복궁역 3번 출구, 663m', '두오모수프, 실버니들 티, 제주 레몬 소금의 담백한 하얀콩 새우 파스타', '화요일~토요일', ' https://www.instagram.com/hyojadongduomo/', '음식점', '', '12:00~15:00, 18:00~21:00', '02-730-0902', '일요일, 월요일 휴무'),
	(411, '섭지코지', '02837  서울특별시 성북구 성북로 118-5 (성북동)', 'images/섭지코지_411.jpg', '제주도에서 직접 공수해 오는 자연산 전복요리와 제주 향토 음식 전문점.\n\n자연산 전복요리와 제주 향토 음식을 전문으로 하는 곳입니다. 제주도에서 직접 공수해 오는 자연산 전복을 사용합니다. 그 외에 갓돔, 자리구이, 다금바리 등 제주산 생선회를 맛볼 수 있습니다. 실내 분위기도 일식집 스타일로 깔끔합니다.', 37.593842, 126.996286, '', '지하철 4호선 한성대입구역 5번 출구, 1.2km', '회코스, 옥돔구이, 복탕, 민어탕', '', '', '음식점', '', '매일 11:00 ~ 22:00', '02-3673-5600', '명절 휴무'),
	(412, '삼정복집', '06170  서울 강남구 봉은사로 626 (세헌빌딩)  1층', 'images/삼정복집_412.jpg', '국내 최초 복코스요리 정착화에 성공한 소문난 복집 .\n\n자타가 공인하는 복요리의 최고봉\n\n국내 최초 복코스요리 정착화에 성공한 소문난 복집 ‘복’이라는 한 가지 테마를 식사 개념에서 종합 요리로 승화시켰으며 일본 현지의 유명 업소와의 메뉴개발과 연구 활동도 활발하다. 특히 살아 있는 복어를 5분 안에 제독 처리하여 그 자리에서 바로 맛볼 수 있는 즐거움을 선사한다.', 37.514627, 127.063913, '', '지하철 9호선 봉은사역 5번 출구, 250m', '참복활어 런치세트, 참복A코스, 참복B코스, 장어코스, 활복지리, 매운탕', '', ' http://www.samjungbok.com/', '음식점', '', '11:30~15:00, 17:00~22:00', '02-3447-3030', '매주 일요일'),
	(413, '타코아미고', '04343  서울 용산구 회나무로 13 (이태원동)  2층, 3층', 'images/타코아미고_413.jpg', '저렴한 가격의 멕시칸 음식 전문점.\n\n경제적인 가격에 멕시코 음식을 맛볼 수 있는 곳입니다. 타코, 퀘사디아, 브리또, 파히타 등 종류도 다양하고 속 재료는 소시지, 소고기, 닭가슴살, 치즈 등에서 선택할 수 있습니다.', 37.538853, 126.988275, '', '지하철 6호선 녹사평역 2번 출구, 467m', '타말레, 타코도라도, 께사디아, 파히타', '매일', '', '음식점', '', '월 16:00 ~ 21:30 / 화 ~ 일 11:30 ~ 21:30', '02-749-5253', ''),
	(414, '고모네원조콩탕황태탕', '05376  서울특별시 강동구 풍성로57길 13 (성내동)', 'images/고모네원조콩탕황태탕_414.jpg', '100% 국산콩을 사용. [포두부, 건두부]로 웰빙식탁. 방자유기그릇.\n\n콩요리 40년의 노하우를 지닌 고모네는 100% 국산콩을 사용, <포두부, 건두부>로 웰빙식탁을 건강하게 가꾸어 나가기 위해 노력하고 있습니다. 중요무형문화재 77호 이봉주 공방에서 만든 방자유기그릇에 요리를 담아 건강을 전하고 있습니다.', 37.529660, 127.135931, '', '지하철 5호선 둔촌동역 4번 출구, 200m', '콩국물, 콩탕, 청국장, 포두부쌈', '', '', '음식점', '', '화요일~토요일 11:00~14:30, 17:00~20:30', '02-485-4675', '일요일, 월요일, 명절 당일'),
	(415, '폴앤폴리나', '03703  서울특별시 서대문구 연희로11길 56', 'images/폴앤폴리나_415.jpg', '유럽식 빵집으로 식사용으로 좋은 담백하고 고소한 빵. 최소한의 재료로 오랜 시간 발효한 건강빵. 시식용 빵이 준비되어 있어 맛보고 고를 수 있는 것도 장점.\n\n유럽식 빵집으로 식사용으로 좋은 담백하고 고소한 빵을 만듭니다. 최소한의 재료로 오랜 시간 발효한 건강빵들이며 시식용 빵이 준비되어 있어 맛보고 고를 수 있는 것도 장점입니다.', 37.568170, 126.929428, '', '지하철 2호선 / 공항철도 홍대입구역 9번 출구, 1.4km', '베이커리', '', ' https://www.instagram.com/paul.and.paulina', '카페, 디저트', '', '매일 11:00 ~ 18:00', '02-333-0185', '매주 화요일, 명절 휴무'),
	(416, '그랑씨엘', '06021  서울 강남구 도산대로45길 16-6 (신사동)  1층', 'images/그랑씨엘_416.jpg', '이탈리아 가정식을 표방는 샌드위치와 허브 샐러드, 다양한 파스타, 브런치\n\n이탈리아 가정식을 표방하고 있으며 독일식 효모 빵을 이용한 오픈 샌드위치와 허브 샐러드, 다양한 파스타 등의 메뉴를 갖추고 있습니다. 옐로 컬러의 외벽과 오픈된 테라스가 유럽의 노천 레스토랑에 온 듯한 느낌입니다. 주말에는 가볍게 브런치를 즐기려는 젊은이들로 북적거립니다.', 37.523390, 127.035837, '', '지하철 수인분당선 압구정로데오역 5번 출구, 703m', '엔초비오일 파스타, 해산물 빠에야, 머쉬룸 샐러드', '매일', ' https://www.instagram.com/grandciel.official/#', '음식점', '', '평일 10:00~15:00,17:00~22:00\n주말 10:00~22:00', '02-548-0283', ''),
	(417, '반포치킨', '06593  서울 서초구 방배중앙로27길 2   1층 103호', 'images/반포치킨_417.jpg', '오래된 치킨 전문점으로, 대표 메뉴인 전기구이 마늘치킨.\n\n오래된 치킨 전문점으로, 대표 메뉴인 마늘 치킨은 전기구이로 기름을 뺀 후 그 위에 마늘 양념을 발라 오븐에 돌려나옵니다. 생닭에 마늘을 넣고 굽기 때문에 마늘의 맛과 향이 진합니다. 일반 전기구이 치킨도 맛볼 수 있습니다. 생맥주는 없고, 병맥주만 판매하고 있습니다.', 37.495390, 126.985652, '1만원대', '지하철 9호선 구반포역 1번 출구, 803m', '', '', '', '음식점', '', '매일 17:00~24:00', '02-599-2825', '명절 휴무'),
	(418, '삼학도', '06643  서울 서초구 효령로57길 4 (서초동)', 'images/삼학도_418.png', '전라남도 목포 삼학도 스타일의 남도 음식을 접할 수 있는 곳.\n\n전라남도 목포 삼학도 스타일의 남도 음식을 접할 수 있는 곳. 목포에서 매일 직송해 오는 신선한 재료를 사용하고 있습니다. 민어, 낙지, 홍어를 전문으로 하고 있으며 잘 삭은 김치를 곁들인 홍어 삼합이 추천 메뉴입니다.', 37.485419, 127.017065, '', '지하철 3호선 남부터미널역 2번 출구, 73m', '삼학정식, 민어회, 홍어삼합, 민어탕', '월~금', ' https://cafe.naver.com/shdfood', '음식점', '', '월~금 11:00~15:00, 17:00~21:30', '02-584-4700', '매주 토요일, 일요일, 공휴일 휴무'),
	(419, '우정낙지', '03189  서울 종로구 삼일대로17길 46 (관철동, 신양빌딩) 2층', 'images/우정낙지_419.jpg', '감칠맛 나는 매운 낙지볶음. 매운 맛을 즐기는 사람이라면 꼭 한번 가봐야할 곳.\n\n매운 맛을 즐기는 사람이라면 꼭 한번 가봐야할 곳. 이 집의 낙지볶음은 지나치게 맵다는 평이 있을 정도로 먹고 나면 입안이 얼얼해집니다. 매운 맛을 달래기 위해 콩나물과 조개탕을 함께 먹습니다. 저녁이면 인근의 회사원들이 식사와 술 한잔을 겸하기 위해 많이 찾습니다.', 37.569328, 126.984937, '1만원대', '지하철 1호선 종각역 4번 출구, 194m', '낙지', '월화수목금토일', '', '음식점', '', '10:00~22:00', '02-720-7991', '연중무휴'),
	(420, '코리아하우스', '06013  서울 강남구 압구정로79길 56 (아름다운빌딩)', 'images/코리아하우스_420.jpg', '질이 좋은 소고기를 능숙한 서빙을 받으면서 즐길 수 있는 곳.\n\n질이 좋은 소고기를 능숙한 서빙을 받으면서 즐길 수 있는 곳입니다. 숯불에 구워 먹는 안창살, 마블링이 좋은 꽃등심 등의 질이 수준급입니다.', 37.525333, 127.051781, '', '지하철 7호선 청담역 12번 출구, 938m', '꼬냑등심, 스페셜 등심, 갈낙탕, 마른보리굴비 정식', '월요일~일요일', ' http://www.koreahouse.co.kr/', '음식점', '', '11:30~22:00', '02-543-8888', '명절 휴무'),
	(421, '불이아(강남점)', '06050  서울 강남구 언주로 711 (논현동, 건설회관)  지하 1층', 'images/불이아(강남점)_421.jpg', '홍대앞에서 훠궈로 유명한 불이아의 강남 분점.\n\n홍대앞에서 훠궈로 유명한 불이아의 강남 분점. 훠궈만을 전문으로 하는 본점과는 달리 중국 요리도 깔끔하게 내고 있습니다.', 37.517078, 127.033430, '3만원대', '지하철 7호선 학동역 10번 출구, 408m', '불이아정식, 소고기정식, 양고기정식, 해물정식', '', '', '음식점', '', '매일 11:00 - 23:00', '02-517-6689', '연중 휴무'),
	(422, '딸기골분식', '03721  서울 서대문구 연대동문길 29 (대신동)', 'images/딸기골분식_422.jpg', '40년 동안 이대 학생들에게 저렴한 가격으로 인기 있는 분식집.\n\n40년 동안 이대 학생들에게 저렴한 가격으로 인기 있는 분식집. 다양한 한식을 맛볼 수 있으며, 불고기돌솥밥과 순두부찌개가 인기가 있습니다', 37.563917, 126.943833, '', '지하철 경의중앙선 신촌역 2번 출구, 577m', '육개장, 불고기돌솥밥, 돌솥제육덮밥, 뚝배기부대찌개, 순두부백반', '월요일~토요일', '', '음식점', '', '07:00 ~ 21:30', '02-363-5563', '일요일'),
	(423, '진어참치', '03988  서울특별시 마포구 연남로3길 34 (연남동)', 'images/진어참치_423.jpg', '참치와 더불어 30여 년을 살아온 사장은 자타 공인 참치 박사.\n\n참치와 더불어 30여 년을 살아온 사장은 자타 공인 참치 박사로, 카운터에서 주문을 하면 자세한 설명과 함께 다양한 참치를 맛볼 수 있습니다. 가격대비 만족도가 높은 편입니다. 카운터에는 일곱 자리밖에 없으므로 예약 필수입니다.', 37.560745, 126.920766, '', '지하철 2호선/ 경의중앙선/ 공항철도 홍대입구 2번 출구, 570m', '참치회', '', ' https://app.catchtable.co.kr/ct/shop/Jinuhtuna', '음식점', '', '매일 16:30 ~ 22:00', '0507-1345-7412', '매달 3번째 화요일, 명절 휴무'),
	(424, '신성각', '04190  서울 마포구 임정로 55-1', 'images/신성각_424.jpg', '수타면으로 만든 짜장면을 맛볼 수 있는 곳.\n\n수타면으로 만든 짜장면을 맛볼 수 있는 곳. 중식당이지만 술은 팔지 않습니다. 요리 메뉴는 취급하지 않고 면 요리 몇 가지와 탕수육, 잡채만 합니다. 짬뽕은 홍합, 조개, 호박, 배추, 양배추, 표고버섯 등을 넣어 매콤한 맛을 냅니다.', 37.544525, 126.957794, '1만원대', '지하철 5호선/ 6호선/ 경의중앙선/ 공항철도 공덕역 7번 출구, 800m', '짜장면, 간짜장, 만두, 탕수육', '월요일~토요일', '', '음식점', '', '11:35 - 16:00 (재료 소진 시 마감)', '02-716-1210', '매주 일요일, 명절, 1월 1일'),
	(425, '라싸브어', '06577  서울 서초구 서래로 24 (반포동, 다솜빌딩)  5층', 'images/라싸브어_425.jpg', '오랫동안 서래마을에서 정통 프랑스 요리를 내고 있는 곳.\n\n오랫동안 서래마을에서 정통 프랑스 요리를 내고 있는 곳. 부르고뉴식 달팽이 요리, 거위 간 요리, 디종식 등심요리 등 클래식한 프랑스 요리를 맛볼 수 있습니다. 제주산 뿔소라를 허브와 버터로 양념한 전채요리와 한우를 사용한 안심스테이크가 추천 메뉴입니다.', 37.497072, 126.998453, '', '지하철 9호선 신반포역 4번 출구, 883m', '달팽이, 프렌치어니언스프, 스테이크', '', ' https://www.instagram.com/lasaveur_seoul/', '음식점', '', '매일 11:30 ~ 15:00 / 17:30 ~ 22:00', '0507-1331-6713', ''),
	(426, '소호정', '06783  서울 서초구 논현로 27 (소호정)', 'images/소호정_426.jpg', '경상도 안동 지방의 반가 음식인 안동 국시의 맛을 느껴볼 수 있는 곳.\n\n경상도 안동 지방의 반가 음식인 안동 국시의 맛을 느껴볼 수 있는 곳입니다. 국시 외에도 다양한 한식 메뉴가 있습니다. 고기와 묵, 전, 국수까지 조금씩 모두 맛볼 수 있는 특선 정식이 실속 있습니다.', 37.473278, 127.048669, '', '지하철 신분당선 양재시민의숲역 3번 출구, 1.1km', '안동국시, 국밥, 수육, 전', '', ' http://www.sohojung.com/default/', '음식점', '', '매일 11:00~21:00', '02-579-7282', '명절 당일 휴무'),
	(427, '압구정서서갈비', '06018  서울 강남구 압구정로50길 22 (신사동)', 'images/압구정서서갈비_427.jpg', '원조신촌연남식당의 45년 전통의 요리법대로 압구정로데오거리의 연탄갈비 전문점.\n\n원조신촌연남식당의 45년 전통의 요리법대로 압구정로데오거리에 1998년 3월에 창업한 연탄갈비 전문점입니다. 의성에서 직접 담가 가져오는 된장은 매일 동이 날 정도로 인기가 좋습니다. 직접 재배한 배추로 담은 배추김치도 입맛을 돋웁니다.', 37.526859, 127.037696, '', '지하철 수인분당선 압구정로데오역 6번 출구, 333m', '한식', '월화수목금토일', '', '음식점', '', '16:00 - 23:00', '02-516-4482', '연중무휴'),
	(428, '언양불고기', '06110  서울 강남구 학동로2길 15', 'images/언양불고기_428.jpg', '30여 년간 언양식 불고기를 해온 집. 메뉴는 등심과 언양불고기\n\n30여 년간 언양식 불고기를 해온 집. 메뉴는 등심과 언양불고기 단 두 종류입니다. 주문이 들어오면 한우 등심만을 사용하는 고기를 양념에 버무려 즉석에 제공하며, 석쇠에 얹어 구어 들기름 참기름을 혼합한 소스에 찍어 먹습니다.', 37.509493, 127.023061, '', '지하철 7호선/신분당선 논현역 3번출구, 119m', '등심\n불고기', '월화수목금토일', '', '음식점', '', '12:00 ~ 22:00 (브레이크타임 15:00~16:30)', '02-548-2684', '명절 휴무'),
	(429, '충무로 부산복집 (오금역)', '05661  서울 송파구 중대로27길 9-1 (오금동, 동호빌딩)', 'images/충무로_부산복집_(오금역)_429.jpg', '시원하고 담백한 맛이 일품인 복요리 전문점\n\n시원하고 담백한 맛이 일품인 복요리 전문점\n\n신선한 생복을 재료로 35년 동안 사랑 받아온 전통 복요리 전문점. 아삭하고 수분이 많은 무와 대파, 다시마로 우려낸 시원하고 담백한 국물맛은 잊을 수 없는 여운으로 남습니다. 찾는 손님이 많아 겨울철에는 예약을 하는 것이 좋습니다.', 37.503829, 127.127556, '', '지하철 3/5호선 오금역 1번 출구, 224m', '생복매운탕/지리, 생복불고기, 참복샤브샤브', '', '', '음식점', '', '매일 11:00 ~ 21:30', '02-404-3227', ''),
	(430, '까치네', '04352  서울특별시 용산구 한강대로84길 11-16 (남영동)', 'images/까치네_430.jpg', '닭볶음탕이 유명.이 집의 또 다른 별미인 계란범벅.\n\n닭볶음탕이 유명합니다. 닭볶음탕은 시간이 조금 걸리기 때문에 그전에 이 집의 또 다른 별미인, 소시지를 넣어 전처럼 부쳐내는 계란범벅을 곁들여도 좋습니다.', 37.544386, 126.973243, '1만원대', '지하철 4호선 숙대입구역 5번 출구, 108m', '닭볶음탕, 계란말이, 계란범벅, 두부김치, 김치찌개, 동태찌개, 참치찌개, 부대찌개, 오징어볶음, 오징어덮채, 골뱅이무침, 닭볶음탕', '', '', '음식점', '', '월요일~토요일 17:00~23:00', '02-798-4668', '매주 일요일'),
	(431, '수정생태', '07341  서울 영등포구 국제금융로7길 32 (여의도동, 장미아파트) 2층', 'images/수정생태_431.jpg', '생태찌개를 전문으로 하는 곳으로, 곤이와 애를 듬뿍 넣은 생태탕 맛이 일품\n\n생태찌개를 전문으로 하는 곳으로, 곤이와 애를 듬뿍 넣은 생태탕 맛이 일품입니다. 점심때에는 줄을 서야 할 만큼 인기입니다.', 37.523309, 126.933882, '1만원대', '지하철 5호선 여의나루역 4번 출구, 443m', '생태찌개백반, 제육볶음, 오징어볶음', '월요일~토요일', '', '음식점', '', '평일 11:00~15:00, 17:00~21:30\n토요일 12:00~18:00', '02-784-4745', '매주 일요일, 공휴일, 명절 휴무'),
	(432, '평안도만두집', '03173  서울특별시 종로구 새문안로3길 30 (내수동)', 'images/평안도만두집_432.jpg', '집에서 직접 빚은 듯한 평양 만두 전문점. 생굴과 파무침의 보쌈.\n\n집에서 직접 빚은 듯한 평양 만두 전문점. 만두 이외에도 생굴과 파무침 등이 푸짐한 속과 함께 나오는 보쌈이 인기가 좋습니다. 녹두를 곱게 갈아 만든 진한 녹두전도 별미입니다. 맛이 담백하여 자극적인 것에 익숙한 젊은 사람들의 입맛에는 안 맞는다는 평도 있습니다.', 37.572737, 126.973281, '', '지하철 5호선 광화문역 1번 출구, 155m', '', '월요일~토요일', '', '음식점', '', '11:00~15:30, 17:00~21:00', '02-723-6592', '매주 일요일, 명절 휴무'),
	(433, '봉산집', '04382  서울 용산구 한강대로62나길 24', 'images/봉산집_433.jpg', '맛있는 차돌박이와 특제 양념소스의 조화로운 노포맛집.\n\n차돌박이가 유명한 집. 간장, 설탕, 식초, 파, 양파, 고추 등을 적절히 배합하여 만드는 소스가 맛의 비결입니다. 차돌박이와 함께 시골풍의 된장찌개가 유명합니다.', 37.534323, 126.974418, '2만원대', '지하철 4/ 6호선 삼각지역 13번 출구, 123m', '차돌박이, 차돌막장찌개', '월요일~일요일', '', '음식점', '', '11:30~21:30', '02-793-5022', '명절 휴무'),
	(434, '아르모니움', '04401  서울 용산구 대사관로 33 (한남동)', 'images/아르모니움_434.jpg', '정성스러운 이탈리아 요리를 편안하고 고급스러운 분위기를 느낄 수 있는 곳.\n\n한남동에 위치한 아르모니움에서는 편안하고 고급스러운 분위기를 느낄 수 있으며 정성스러운 이탈리아 요리를 맛볼 수 있습니다. 아르모니움은 이탈리안 다이닝 레스토랑으로, 한국의 제철 식재료와 이탈리안 조리법으로 이탈리아 요리를 선보입니다. 테라스, 정원, 프라이빗 룸이 준비되어 있어 가벼운 식사뿐만 아니라 비즈니스 모임에도 적합한 레스토랑입니다. \n\n※ 아르모니움: 라틴어로 조화(harmony)라는 의미', 37.533847, 127.001750, '', '지하철 6호선 이태원역 3번 출구, 733m', '무크림 소스의 지중해식 문어구이, 이베리코 스테이크', '', ' https://www.instagram.com/harmonium_seoul/#', '음식점', '', '11:30~15:00, 17:30~22:00', '0507-1400-3972', ''),
	(435, '명동부대찌개', '04534  서울 중구 명동길 25-7 (명동1가)', 'images/명동부대찌개_435.jpg', '생삽겹을 햄, 소시지와 함께 얼큰하고 시원한 부대찌개가 유명한 집.\n\n생삽겹을 햄, 소시지와 함께 넣어서 부대찌개를 끓이는 것이 맛의 비결입니다. 얼큰하고 시원한 국물 맛의 찌개가 양도 푸짐하게 나옵니다. 원래 부대찌개로 유명해진 집이지만 삼겹살도 맛있습니다.', 37.564142, 126.983799, '1만원대', '지하철 2호선 을지로입구역 6번 출구, 355m', '사골부대찌개', '', '', '음식점', '', '매일 10:00 ~ 22:00', '02-752-6800', '명절 휴무'),
	(436, '슈치쿠', '07345  서울 영등포구 63로 50 (여의도동, 63한화생명빌딩)  58층', 'images/슈치쿠_436.jpg', '신선한 재료의 맛을 살린 스시와 사시미를 맛볼 수 있는 곳.\n\n63빌딩 식당가를 레노베이션하면서 새로 오픈한 곳입니다. 신선한 재료의 맛을 살린 스시와 사시미를 맛볼 수 있습니다. 58층에서 내려다보는 스시 카운터의 전망은 서울 최고라고도 할 수 있습니다.', 37.519664, 126.939909, '', '지하철 9호선/ 신림선 샛강역 3번 출구, 1.2km', '스시, 사시미', '', ' http://www.63restaurant.co.kr/', '음식점', '', '월요일~토요일 11:30 ~ 15:00 / 17:30 ~ 22:00\n일요일 11:30 ~ 15:00 / 17:10 ~ 21:30', '0507-1401-5751', '연중무휴'),
	(437, '카나디안랍스터', '06711  서울특별시 서초구 남부순환로 2385 (서초동)  3층', 'images/카나디안랍스터_437.jpg', '바닷가재 사시미, 버터구이, 칠리, 찜, 그라탱 등 다양한 요리\n\n바닷가재 사시미, 버터구이, 칠리, 찜, 그라탱 등 다양한 요리를 선보입니다. 코스를 시키면 사시미와 찜 중에서 선택하게 되어 있고 두 가지 구이 요리가 나옵니다. 캐나다 노바 스코샤 앞바다 북대서양에서 자라는 자연산 바닷가재를 수입하여 사용합니다.', 37.480170, 127.011410, '', '지하철 3호선 남부터미널역 5번 출구, 800m', '랍스타 F세트, 랍스타 A세트', '', '', '음식점', '', '12:00 ~ 15:00 / 17:00 ~ 21:00', '02-585-9624', ''),
	(438, '산호', '06028  서울 강남구 논현로175길 111 (신사동 만수빌딩)', 'images/산호_438.jpg', '한식을 안주로 술을 즐길 수 있는 한식주점. 현대화된 한식.\n\n한식을 안주로 술을 즐길 수 있는 한식 주점. 정통 한식이라기보다는 깔끔하게 현대화된 한식을 맛볼 수 있습니다.', 37.522327, 127.020400, '', '지하철 3호선/ 신분당선 신사역 6번 출구, 728m', '', '', ' http://instagram.com/sanho_sinsa', '음식점', '', '11:30 ~ 23:00', '02-517-0035', '매주 일요일'),
	(439, '이즈미', '06023  서울 강남구 언주로 857 (신사동)', 'images/이즈미_439.jpg', '신선한 회와 스시를 즐길 수 있는 곳.\n\n신선한 회를 즐길 수 있는 곳. 20~30여 가지의 스시를 준비하는 보통의 일식집에 비해 60여 종의 생선과 해산물로 만들어 내놓는 스시도 빠뜨릴 수 없는 메뉴입니다.', 37.527021, 127.032982, '', '지하철 3호선 압구정역 3번 출구, 523m', '모듬사시미, 초밥', '', '', '음식점', '', '월요일~금요일 11:30~15:00 / 17:30~22:00\n토요일~일요일 11:30~15:00 / 17:30~21:00', '02-542-7171', '명절 휴무'),
	(440, '꽃지', '06170  서울 강남구 봉은사로 610 (삼성동, 수도빌딩)', 'images/꽃지_440.jpg', '서산에서 가져온 꽃게로 만든 게장과 꽃게 요리가 정갈하게 나오는 곳.\n\n서산에서 가져온 꽃게로 만든 게장과 꽃게 요리가 정갈하게 나오는 곳. 간장을 사용하지 않고 어리굴젓을 숙성시켜서 담근 꽃게장의 향이 독특합니다. 게장 외에도 꽃게찜, 산 낙지, 박속낙지탕 등 서해안의 명물들을 맛볼 수 있습니다. 반찬으로 나오는 어리굴젓 맛도 일품입니다. 1인당 게가 반 마리씩 나오는 2인용 세트메뉴가 있어 게장을 저렴하게 맛볼 수 있다는 것이 장점입니다.', 37.514221, 127.061618, '', '지하철 9호선 봉은사역 5번 출구, 33m', '간장게장정식, 대하구이, 양념게장, 게살비빔밥, 뚝배기 꽃게탕', '', ' https://kkotji.modoo.at/', '음식점', '', '매일 11:30~21:30\n(Break Time 15:00~17:00)', '02-561-8788', '매주 일요일'),
	(441, '쯔루하시 후게츠', '04536  서울 중구 명동8길 21-5 (명동2가)  2층', 'images/쯔루하시_후게츠_441.jpg', '재료를 반죽과 한꺼번에 섞어 철판에 지져 먹는 오사카식 오코노미야키\n\n재료를 반죽과 한꺼번에 섞어 철판에 지져 먹는 오사카식 오코노미야키 체인의 한국 분점입니다. 인기가 좋은 모던야키는 오코노미야키에 쫄깃쫄깃한 굵은 야키소바 면을 얹은 것입니다. 개인 테이블마다 설치된 철판에 직접 재료를 얹어 만들어줍니다.', 37.562841, 126.985031, '1만원대', '지하철 4호선 명동역 6번 출구, 230m', '오코노미야키, 야끼소바, 일품요리', '', ' http://www.fugetsu.co.kr ', '음식점', '', '매일 11:30 ~ 14:30, 17:00 ~ 21:30', '0507-1340-5920', '명절 휴무'),
	(442, '마키노차야 블랙31 롯데월드타워점', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰) 31층', 'images/마키노차야_블랙31_롯데월드타워점_442.png', '롯데월드타워 31층 프리미엄 뷔페 레스토랑\n\n마키노차야 블랙 31은 유명 뷔페 레스토랑인 마키노차야의 프리미엄 매장으로 롯데월드타워 31층에 위치해 있어, 한강, 석촌호수를 비롯한 서울의 아름다운 풍경을 파노라마로 즐길 수 있습니다. 양갈비를 비롯한 다양한 바비큐 라이브와 테이블당 제공되는 스페셜메뉴, 특급호텔 경력 쉐프들이 선보이는 시그니처 메뉴들로 한단계 더 높은 미각적 만족을 제공합니다. 마키노차야 블랙31을 이용하려면 사전예약이 필요하며, 롯데월드타워 입장객 방문 규정 상 EAST GATE 입구에 있는 안내데스크에서 출입증을 발급 후 출입이 가능합니다.', 37.513713, 127.104302, '', '지하철 2/8호선 잠실역 2번 출구, 29m', '', '', ' https://makinochaya.co.kr', '음식점', '사전 예약 필수', '평일 11:30~15:00, 18:00~21:00 / 주말 11:30~16:00, 17:00~21:30', '070-5224-0866', ''),
	(443, '차이797', '06585  서울 서초구 동광로 78  방배빌딩 2,3층', 'images/차이797_443.jpg', '분위기 있는 중국 음식과 타이 음식 전문점.\n\n중국 음식과 타이 음식을 전문으로 하고 있습니다. 입구에는 딤섬 키친도 마련되어 있고, 한쪽에서는 꽃도 전시하여 판매하고 있습니다. 실내 분위기도 모던하며 의자와 쿠션이 독특하면서도 편안합니다.', 37.492849, 126.991101, '', '지하철 7호선 내방역 7번 출구, 630m', '', '매일', ' http://www.chai797.co.kr', '음식점', '', '평일 11:30 ~ 15:00 / 17:30 ~ 22:00\n주말 12:00 ~ 16:00 / 17:00 ~ 22:00', '02-537-7972', '명절 휴무'),
	(444, '남문토방', '04529  서울 중구 남대문시장길 45-3 (남창동) 지하 1층', 'images/남문토방_444.jpg', '경상도식 추어탕과 통미꾸라지 튀김. 유황오리 샤브샤브와 전골.\n\n국산 미꾸라지를 갈아 제대로 만든 경상도식 추어탕과 통미꾸라지 튀김을 맛볼 수 있습니다. 유황을 먹여 키운 오리를 훈제하여 채소와 곁들인 유황오리 샤브샤브와 유황오리 전골도 구수하고 시원한 맛을 담고 있습니다', 37.560542, 126.978379, '', '지하철 4호선 회현역 7번 출구, 303m', '유황오리훈제샤브샤브, 유황오리더덕주물럭, 추어탕, 미꾸라지튀김', '월요일~일요일', '', '음식점', '', '10:00 ~ 22:00', '02-778-6727', '명절 휴무'),
	(445, '광진구 인덱스숍', '05071  서울 광진구 아차산로 200 (자양동)  커먼그라운드 3층', 'images/광진구_인덱스숍_445.jpg', '책에 집중하며 맛있는 음료를 즐길 수 있는 곳\n\n커먼그라운드에 위치한 북카페 인덱스숍은 특별한 큐레이팅 특징을 지니고 있는 서점이자 카페입니다. 햇살 아래 혼자만의 시간을 가질 수 있는 공간이며, 조용한 분위기 속에 책에 집중하며 맛있는 음료를 즐길 수 있는 곳입니다. 책 진열은 알파벳 순서로 되어 있으며 인덱스숍만의 분류 방식으로 되어 있어 매력적인 곳입니다. 매거진, 다양한 장르의 서적, 굿즈 등 힙하고 독특한 물품들도 만나볼 수 있습니다.', 37.541057, 127.065669, '', '지하철 2/ 7호선 건대입구역 6번 출구, 200m', '아인슈페너 6,500원\n인덱스 블렌드 6,000원', '매일', ' https://www.instagram.com/indexshop.kr/', '카페, 디저트', '', '11:00 ~ 22:00', '02-2122-1259', ''),
	(446, '김용안과자점', '04376  서울 용산구 한강대로 155-1 (한강로2가)', 'images/김용안과자점_446.jpg', '옛 방식으로 정성껏 만드는 전병\n\n1967 년부터 유지해온 김용안과자점은 삼각지의 전병 가게입니다 . 김용안 창업자의 노하우가 담긴 과자 틀은 오늘날까지 맛있는 전병을 즐길 수 있게 해주었습니다 . 일제강점기 시절 먹고살기 위해 일본인의 과자 기술을 따라 만든 것이 센과자라고 하지만 사장님의 손길로 재탄생했기에 분명한 차별점이 있습니다 . 오픈 이래 좋은 재료로 아버지에서 아들까지 장인정신을 담아 맛을 유지하고 있는 가게에서 오늘도 계란향이 배어나는 고소하고 바삭한 과자가 생산됩니다 .', 37.533075, 126.971257, '1만원대', '지하철 4 / 6호선 삼각지역 4번 출구 , 70m', '품목별 상이', '', '', '카페, 디저트', '', '월요일~토요일 10:00~17:00(소진시 마감)', '02-796-6345', '일요일'),
	(447, '안동장', '04550  서울특별시 중구 을지로 124 (을지로3가)', 'images/안동장_447.jpg', '현존하는 가장 오래된 중식당, 1948년부터 내려오는 옛 맛.\n\n현존하는 가장 오래된 중식당으로, 1948년부터 내려오는 옛 맛입니다. 굴짬뽕이 맛있는 곳으로 유명한데, 시원한 굴짬뽕과 매운 굴짬뽕으로 나누어져 있어 입맛에 따라 선택할 수 있습니다.', 37.566113, 126.991580, '1만원대', '지하철 2/3호선 을지로3가역 10번 출구, 70m', '굴짬뽕, 삼선짬뽕, 기스면', '매일', '', '음식점', '', '평일 11:30 ~ 21:00\n주말 11:30 ~ 20:00', '02-2266-3814', '명절 휴무'),
	(448, '도림', '05554  서울 송파구 올림픽로 240 (잠실동, 롯데월드)  32층', 'images/도림_448.jpg', '모던한 분위기에서 품격있게 중국요리를 즐길 수 있는 곳.\n\n모던한 분위기에서 품격있게 중국요리를 즐길 수 있습니다. 주말 점심에는 냉채, 수프, 요리, 후식에 원하는 딤섬을 선택할 수 있는 딤섬테이블이 마련되어 있습니다. 30종 이상의 중국 차를 티 소믈리에의 설명을 들으면서 즐길 수 있습니다.', 37.511310, 127.098142, '', '지하철 2, 8호선 잠실역 3번 출구, 53m', '한우자장면, 통전복 해물 짬뽕, 홀 메뉴, 룸 메뉴', '', ' https://www.lottehotel.com/world-hotel/ko/dining/restaurant-toh-lim', '음식점', '', '11:30 ~ 14:30 / 18:00 ~ 21:30', '02-411-7800', '연중무휴'),
	(449, '타니넥스트도어', '04533  서울 중구 남대문로 73 (AVENUEL)  9층', 'images/타니넥스트도어_449.jpg', '도심 속의 리조트를 콘셉트로 하는 퓨전 레스토랑.\n\n도심 속의 리조트를 콘셉트로 하는 퓨전 레스토랑. 발리에 온 것 같은 야외 방갈로가 여름에는 인기가 좋습니다. 퓨전 일식에 가까운 요리를 맛볼 수 있습니다.', 37.563994, 126.981495, '', '지하철 2호선 을지로입구역 7번 출구, 177m', '런치세트, 디너코스', '', ' http://www.taninextdoor.com/', '음식점', '', '매일 11:00~15:00 / 17:00~21:00', '0507-1433-6100', '백화점 휴일'),
	(450, '바이킹스워프 코엑스점', '06164  서울 강남구 영동대로 513 (삼성동, 코엑스)  코엑스 컨벤션센터 2층', 'images/바이킹스워프_코엑스점_450.jpg', '국내 최초 랍스터 무한리필 뷔페 레스토랑\n\n[바이킹스워프 장점 및 이용꿀팁]\n\n오직 바이킹스워프에서만 누릴 수 있는 특별한 가치를 위해 바이킹스워프는 최상의 식재료만을 고집합니다. \n\n\n\n\n1. 캐나다에서 직접 랍스터를 확인 후 초이스! 바이킹스워프는 매년 직접 캐나다로 건너가 현지에서 직접 어획 과정을 살펴보며, 가공 방식, 냉동 방식, 수율, 맛, 식감, 향, 조리 전후 차이 등을 다각도에서 세심하게 테이스팅합니다. 이때, 5성급 호텔 출신의 바이킹그룹 총괄 전문 셰프가 직접 맛보며 확인하고요. 바이킹스워프의 랍스터는 이렇게 까다로운 익스펙션을 통과하여 선택된 특별한 랍스터입니다.\n\n\n\n\n2. 랍스터로 이렇게 많은 요리가? 그것도 무제한! 특급 쉐프의 손길에서 특별한 날에만 먹을 수 있던 랍스터를 무제한으로 드실 수 있습니다. 살아있는 랍스터를 즉석에서 손질하여 통째로 쪄내는 찜 요리, 랍스터구이뿐 아니라 스프요리인 랍스터 비스큐, 베이크 랍스터, 랍스터 케이크, 랍스터 세비체, 랍스터 망고 타워 등랍스터를 주제로 다양한 요리들이 있습니다. \n\n\n\n\n3. 신선한 바다를 테이블로 배달해드립니다. 방금 잡은 제철 해산물도 무제한으로 즐길 수 있습니다. 삼배체굴, 전복, 석화, 가리비, 멍게, 키조개, 피조개, 돌문어, 참소라, 낙지, 바지락, 해삼, 대합 등 수십 가지 제철 해산물을 수족관에서 고르면 즉석에서 손질하여 제공해드립니다. 도미, 광어, 황새치, 참치, 연어, 홍민어, 초새우 등도 골라만 주세요. 즉석에서 스시나 초밥으로 손질해서 드려요. \n\n\n\n\n4. 그릴 요리를 꼭 드셔보세요. 베이크 랍스터, 왕갈비, 새우, 전복, 그릴 치킨, 미니 연어 스테이크 등을 그릴에 구워 제공해드립니다. 바이킹스워프는 무제한 랍스터 뷔페로 유명하지만, SNS상에서는 갈비 맛집으로도 유명하답니다. \n\n\n\n\n5. 프리미엄 브랜드의 디저트까지 바이킹스워프는 생수도 특별합니다. 미슐랭 스타 레스토랑에서 찾아볼 수 있는 이탈리아 프리미엄 생수인 아쿠아파나 워터와 산 펠레그리노 탄산수를 제공하거든요. 건강에 좋은 100% 착즙 주스 휴롬 주스를 마실 수도 있고요. \n\n\n\n\n아무리 배불러도 후식은 꼭 드시고 가야 해요. 쟁쟁한 브랜드들로 알차게 구성되어 있으니까요. 1880년부터 시작된 이탈리아 정통 젤라또 브랜드인 G.FASSI 젤라또, 세계적인 TEA 브랜드인 TWG 홍차, 폴바셋 커피, 압구정 3대 베이커리로 꼽히는 노아 베이커리 등이 있어요. 자몽, 파인애플, 망고 등의 과일들도 준비되어 있는데, 망고는 즉석에서 썰어드립니다.', 37.511824, 127.059159, '', '지하철 2호선 삼성역 6번 출구, 273m', '랍스터, 씨푸드, 회&초밥, 그릴 등', '매일', ' http://www.ivikings.co.kr/akg/ko/storetype/wharf.asp', '음식점', '코엑스점 단독 모엣&샹동을 무제한으로 즐길 수 있는 모엣룸 $160\n*환율에 따라 이용금액이 매일 변동 및 적용됩니다.', '월요일~금요일-2부제, 토요일~일요일-4부', '1644-4446 (모엣룸 패스트라인 1644-4391)', ''),
	(451, '홍연', '04533  서울특별시 중구 소공로 106  (소공동)', 'images/홍연_451.jpg', '홍콩식(광동식) 중식을 맛볼 수 있는 곳.\n\n홍콩식(광동식) 중식을 맛볼 수 있습니다. 콩짜장소스로 버무린 활 바닷가재 요리가 추천 메뉴입니다. 오후에는 입구에 마련된 티하우스에서 정통 중국 차도 즐길 수 있습니다. 내부는 붉은색 카펫과 검은 기둥과 테이블로 되어 있어 강렬한 느낌을 줍니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.564484, 126.980185, '', '지하철 1/2호선 시청역 6번 출구, 341m', '런치코스, 디너코스, 딤섬', '', ' https://www.josunhotel.com/hotel/westinSeoul.do', '음식점', '', '매일 12:00 ~ 15:00 / 18:00 ~ 22:00', '02-317-0494', '연중무휴'),
	(452, '하누소', '01405  서울 도봉구 노해로 327', 'images/하누소_452.jpg', '전남 함평 초원에서 자란 최상급의 한우 암소1++만을 엄선한 한우집.\n\n초원의 청정함이 살아 있는 갈비의 명가\n\n전남 함평 초원에서 자란 최상급의 한우 암소1++만을 엄선하여 15년 경력을 가진 조리 명장의 솜씨로 최고의 요리와 정성스런 서비스를 선보입니다. 현대적 감각의 모던한 인테리어가 돋보이며, 단체 연회와 50여대의 동시 주차가 가능합니다.', 37.651478, 127.044819, '3만원대', '지하철 1/4호선 창동역 2번 출구, 301m', '왕갈비탕, 한우왕양념갈비, 한우꽃등심', '', ' http://www.hanuso.com', '음식점', '', '매일 11:00~21:30', '02-900-9800', '명절 당일'),
	(453, '로씨니', '03059  서울 종로구 북촌로 18', 'images/로씨니_453.jpg', '여러 가지 파스타와 스테이크를 이탈리아 북부 지방 스타일로 맛볼 수 있는 곳\n\n여러 가지 파스타와 스테이크를 이탈리아 북부 지방 스타일로 맛볼 수 있는 곳입니다. 화려한 맛은 없으나 정통 이탈리아 요리를 내고 있습니다. 분위기도 조용한 편입니다.', 37.585009, 126.985663, '', '지하철 3호선 안국역 2번 출구, 136m', '안심스테이크, 양갈비석쇠구이', '', '', '음식점', '', '평일 12:00 ~ 15:00 / 18:00 ~ 22:00', '02-766-8771', '주말'),
	(454, '에반스', '04049  서울 마포구 와우산로 63 (서교동)', 'images/에반스_454.jpg', '홍대 앞에서 가장 오래된 클럽 중의 하나. 재즈 밴드의 라이브 공연.\n\n홍대 앞에서 가장 오래된 클럽 중의 하나. 칵테일이나 맥주 등을 공연과 함께 즐길 수 있습니다. 재즈 밴드의 라이브 공연은 저녁 9시가 넘어야 시작합니다. 매일 다른 프로그램을 선보이며 매달 뮤지션이 교체됩니다.', 37.550273, 126.922879, '2만원대', '지하철 6호선 상수역 1번 출구, 279m', '재즈바', '매일', ' http://www.clubevans.com/', '술집, 바', '', '19:00~22:10', '02-337-8361', '명절 휴무'),
	(455, '가람국시', '06053  서울 강남구 언주로135길 13 (논현동)', 'images/가람국시_455.jpg', '깔끔한 경상도식 국수(국시)를 전문으로 하는 곳.. 소고기국시와 멸치국시.\n\n깔끔한 경상도식 국수(국시)를 전문으로 하는 곳입니다. 소고기국시와 멸치국시가 인기가 있고, 콩국수와 만두도 괜찮습니다.', 37.516787, 127.034095, '1만원대', '지하철 7호선 학동역 10번 출구, 381m', '칼국수, 콩국수, 접시만두, 해물파전, 녹두전', '월요일~일요일', '', '음식점', '', '11:00~15:00, 17:00~21:30', '02-541-8200', '명절 연휴 휴무, 1월1일'),
	(456, '스시미치루', '03152  서울 종로구 종로1길 42 (수송동, 이마빌딩)  지하 1층', 'images/스시미치루_456.jpg', '가격대비 만족도 높은 스시를 내놓는 곳으로 인기가 올라가고 있는 집.\n\n가격대비 만족도 높은 스시를 내놓는 곳으로 인기가 올라가고 있는 집. 스시의 네타가 크고 길게 나오는 스타일입니다. 사케를 곁들여도 좋습니다. 자리가 적으므로 예약 필수입니다.', 37.573903, 126.978984, '', '지하철 5호선 광화문역 2번 출구, 331m', '오마카세, 후토마키', '', ' https://app.catchtable.co.kr/ct/shop/sushimichiru', '음식점', '', '월요알~토요일 12:00 ~ 14:30 / 17:30 ~21:30', '02-761-4090', '일요일'),
	(457, '정동국시', '04518  서울특별시 중구 정동길 5 (정동)', 'images/정동국시_457.jpg', '담백하고 깔끔한 맛의 칼국수와 만두로 정동 일대에서는 꽤 유명한 집.\n\n담백하고 깔끔한 맛의 칼국수와 만두로 정동 일대에서는 꽤 유명한 집입니다. 사골 국물을 쓰는 것이 특징이며, 반찬으로 나오는 백김치와 빨간 김치는 이 집의 별미입니다. 고랭지배추를 사용하고 있고, 양념도 자극적이지 않아 국수와 궁합이 잘 맞습니다. 국밥과 보쌈도 맛이 좋습니다.', 37.567861, 126.969912, '', '지하철 5호선 서대문역 5번 출구, 370m', '국수', '월요일~토요일', '', '음식점', '', '평일 11:30 ~ 14:00 / 16:00 ~ 20:30\n토요일 11:30 ~ 19:00', '02-732-0114', '매주 일요일, 명절'),
	(458, '코키펍 홍대점', '04041  서울 마포구 와우산로21길 19-8 (서교동, 태경빌딩)  1층 COCKYPUB', 'images/코키펍_홍대점_458.jpg', '홍대 정문 앞에 위치한 코키펍은 아메리칸 스타일의 BAR Food를 즐길 수 있는 스포츠펍.\n\n홍대 정문 앞에 위치한 코키펍은 아메리칸 스타일의 BAR Food를 즐길 수 있는 스포츠펍입니다. 간단한 스낵부터 한 끼 식사로 충분한 메인요리까지 서빙합니다. 매일 다양한 스포츠 경기를 관전할 수 있으며 큰 경기가 있는 날에는 오픈 시간을 조정할 정도로 스포츠 팬들의 발길이 잦은 곳입니다. 스포츠 경기를 놓칠 수 없는 골수팬들에게는 오아시스 같은 존재로 거듭나고 있으며 다트, 비어퐁, 셔플보드 등 매장 내에서 게임이 가능해 스포츠를 좋아하지 않는 사람도 즐길 수 있습니다. 국내 거주 중인 외국인 단골층이 많고 주변 대학교 교환학생들이 많이 찾는 명소입니다.', 37.552080, 126.922689, '', '지하철 2호선 / 경의중앙선 / 공항철도 홍대입구역 9번 출구, 331m', '수제버거, 프라이, 맥앤치즈', '', ' https://www.instagram.com/cockypubseoul/', '술집, 바', '※ 전 직원 모두 영어응대 가능, 영어메뉴판 구비', '일요일~목요일 17:00~02:00 (라스트 오더 01:00), 금요일~토요일 17:00~04:00 (라스트 오더 02:00)', '02-322-7900', ''),
	(459, '사발', '03174  서울특별시 종로구 사직로8길 34, 경희궁의아침3단지 1층 142호 (내수동)', 'images/사발_459.jpg', '카페 같은 인테리어의 국수 전문점. 전통 국수를 현대적으로 변형시킨 퓨전 스타일.\n\n카페 같은 인테리어의 국수 전문점. 전통 국수를 현대적으로 변형시킨 퓨전 스타일입니다. 대표 메뉴는 닭 육수에 닭고기가 얹어 나오는 닭국수와 황태가 올려진 황태비빔국수입니다. 그릇들도 예쁘고 정갈합니다.', 37.573588, 126.972426, '', '지하철 3호선 경복궁역 7번 출구, 234m', '퓨전한식( 능이버섯닭곰탕, 흑임자 콩국수, 닭국수)', '월요일~일요일', ' http://sabal.modoo.at/', '음식점', '', '평일 11:30 ~ 21:00 (브레이크타임 15:00~17:00)\n주말, 공휴일 11:30 ~ 20:00(브레이크타임 15:00~16:30)', '0507-1317-4845', '명절 휴무'),
	(460, '아카사카', '06621  서울특별시 서초구 서초대로74길 23  서초타운트라팰리스 지하 1층', 'images/아카사카_460.jpg', '서울 시내에서 손꼽히는 일식집 중의 하나.\n\n서울 시내에서 손꼽히는 일식집 중의 하나다입니다. 데판야키 바와 스시 바가 따로 설치되어 있습니다. 사케 리스트가 좋기로도 유명합니다. 하얏트호텔 수영장과 한강을 바라볼 수 있어 전망이 좋습니다.', 37.495612, 127.027091, '', '지하철 2호선/ 신분당선 강남역 6번 출구, 150m', '스페셜사시미, 활복코스요리, 아카사카 풀코스 요리', '', ' http://www.akasaka.co.kr/', '음식점', '', '월~금 11:00~14:30, 16:30~22:00 / 토요일 11:00~14:30, 16:30~21:00', '02-585-1145', '일요일 휴무'),
	(461, '슬런치 팩토리', '04074  서울 마포구 와우산로3길 38 (상수동)', 'images/슬런치_팩토리_461.jpg', '채식을 기반으로 이탈리안 비건식과 한국 비건식. 다이어트 도시락.\n\n다이어트 도시락을 전문으로 하는 곳. 다이어트를 콘셉트로 하는 만큼 조미료가 들어가지 않고 건강한 한 끼를 먹을 수 있습니다. 매일 메뉴가 달라져서 다양한 메뉴도 맛볼 수 있습니다.', 37.545866, 126.920835, '2만원대', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 3번 출구, 909m', '버섯 두유 크림 리조또, 버섯고르곤졸라 피자', '', ' https://www.instagram.com/slunch_factory/', '음식점', '', '매일 12:00~22:30', '02-325-8843', '연중 무휴'),
	(462, '동아냉면', '04401  서울 용산구 대사관로 45-1 (한남동)', 'images/동아냉면_462.jpg', '30여 년 전통의 냉면 전문점.\n\n30여 년 전통의 냉면 전문점. 주문하면 기본적으로는 매운맛을 내오고 있지만 안 맵게, 안 시게, 달지 않게 따로 주문할 수 있습니다. 포장도 가능한데, 삶은 것과 삶지 않은 것을 선택할 수 있습니다. 분식집 스타일의 냉면이지만 나름대로 마니아를 거느리는 곳입니다.', 37.533710, 127.003260, '', '지하철 6호선 이태원역 3번 출구, 870m', '물냉면, 비빔냉면, 만두', '', '', '음식점', '', '10:00 ~ 20:30', '02-796-7442', '매주 월요일'),
	(463, '도봉산갈비', '01302  서울 도봉구 도봉로 919 (도봉동)', 'images/도봉산갈비_463.jpg', '30년 전통 명품 갈비집의 명가\n\n도봉산갈비는 역사와 전통이 흐르는 도봉산 자락 앞에 자리 잡은 30년 전통의 갈비집으로, 최상의 고기와 국내산 부자재로 맛있는 식사를 즐길 수 있습니다.', 37.686465, 127.045657, '', '지하철 1/7호선 도봉산역 1번 출구, 319m', '돼지왕갈비, 돼지갈비무한리필, 소왕갈비', '', '', '음식점', '', '매일 11:00 ~ 22:00', '02-955-8668', '연중 무휴'),
	(464, '따뚱', '06524  서울특별시 서초구 강남대로107길 6 (잠원동)  본관 2층', 'images/따뚱_464.jpg', '베이징의 유명한 북경오리 전문점의 서울 분점.\n\n베이징의 유명한 북경오리 전문점의 서울 분점입니다. 현지에서 직접 초빙한 주방장이 화덕에서 직접 구워내는 정통 북경오리를 맛볼 수 있습니다. 오픈된 주방이 시원한 느낌이 들으며 북경오리 외에도 북경식 중국요리가 다양하게 준비되어 있습니다.', 37.518569, 127.018084, '', '지하철 3호선/신분당선 신사역 5번 출구, 241m', '상견례코스, 베이징덕, 런치코스', '', ' http://www.riversidehotel.co.kr/pages/res02.php', '음식점', '', '매일 12:00~15:00 / 18:00~22:00', '02-6710-1888', '연중무휴'),
	(465, '남도미락', '06578  서울 서초구 사평대로 150 (반포동, 궁전상가)', 'images/남도미락_465.jpg', '전라도식 음식을 맛볼 수 있는 곳. 홍어삼합과 갈치 조림이 인기.\n\n전라도식 음식을 맛볼 수 있는 곳. 홍어삼합과 갈치 조림이 인기 있습니다. 홍어의 삭힘 정도는 골라서 주문할 수 있습니다. 갓김치 등의 밑반찬도 내공이 느껴지는 맛입니다. 20여 년이 넘는 역사를 자랑하는 곳으로, 몇 년 전에 레노베이션을 거쳐 실내 분위기도 현대적이고 깔끔하여 손님을 모시기에도 좋습니다. 가격대는 비교적 높은 편입니다.', 37.500742, 127.000730, '', '지하철 3/7/9호선 고속터미널역 9번 출구, 362m', '육낙무침, 홍어전', '월요일~일요일', '', '음식점', '', '11:00 ~ 22:00', '02-595-6060', '명절 휴무'),
	(466, '까발로비안코', '06165  서울 강남구 삼성로104길 9 (삼성동)', 'images/까발로비안코_466.jpg', '이탈리안 코스요리를 전문점, 펍도 함께 운영\n\n이탈리안 코스요리를 전문으로 하고 있으며, 다양한 프라이빗룸도 갖추고 있어 미리 예약을 하면 좋습니다. 1, 2층에는 모두 테라스가 있으며 1층에서는 라이브 공연을 합니다. 단, 일요일은 공연이 없습니다.', 37.510995, 127.055392, '', '지하철 9호선 삼성중앙역 5번 출구, 289m', '마르게리따 피자, 까르보나라, 스테이크 샐러드', '일요일~금요일', '', '음식점', '', '월요일~금요일 17:00 ~ 01:00\n일요일 18:00 ~ 24:00', '02-562-9262', '매주 토요일'),
	(467, '[백년가게] 참누렁소', '01830  서울 노원구 공릉로63길 13 (유토피아빌딩)', 'images/[백년가게]_참누렁소_467.jpg', '칼끝 하나로 이룬 소고기 음식 문화\n\n참누렁소는 한우꽃등심과 특수부위(살치살, 안창살) 그리고 한우양념갈비를 메인메뉴로 균형 잡힌 사이드메뉴를 맛볼 수 있습니다.', 37.634884, 127.070524, '3만원대', '지하철 7호선 하계역 3번 출구, 467m', '돼지갈비, 생갈비, 살치살, 육회비빔밥정식', '', '', '음식점', '', '매일 11:00 ~ 22:00', '02-979-6400', '명절 휴무'),
	(468, '언노운다이너', '06300  서울특별시 강남구 논현로28길 42 (도곡동)  2층', 'images/언노운다이너_468.jpg', '한적한 곳에 위치한, 분위기 있는 이탈리아 레스토랑.\n\n한적한 곳에 위치한, 분위기 있는 이탈리아 레스토랑. 파스타, 피자 등을 부담없이 즐길 수 있습니다. 점심 런치 세트가 경쟁력이 있으며 저녁때는 파스타를 안주 삼아 와인 한잔하기에도 좋습니다.', 37.484186, 127.045489, '', '지하철 3호선 매봉역 4번 출구, 364m', '2인스테이크쉐어코스, 1++한우채끝스테이크200G, 알리오올리오 스파게티', '', ' https://www.instagram.com/unknown_diner/', '음식점', '', '11:30 ~ 15:00 / 17:30 ~ 22:00', '0507-1485-6674', '매주 일요일'),
	(469, '남매집', '04526  서울특별시 중구 남대문로1길 41 (북창동)', 'images/남매집_469.jpg', '북창동 골목에서 30년째 고추장 양념구이를 하는 집.\n\n북창동 골목에서 30년째 고추장 양념구이를 하는 집. 고추장 양념을 한 뒤 숯불에 굽습니다. 동그랑땡이라고 불리는 고추장 양념 돼지고기가 유명한데, 동그랑땡은 돼지등심을 동그랗게 썰어 양념한 것입니다.', 37.562876, 126.977201, '', '지하철 1/2호선 시청역 7번 출구, 191m', '곰장어구이, 돼지고추장구이', '', '', '음식점', '', '매일 12:30 ~ 23:00', '02-777-0735', '명절 휴무'),
	(470, '비원떡집', '03055  서울 종로구 북촌로 33-1 (가회동)', 'images/비원떡집_470.jpg', '조선 마지막 상궁에게 비법을 전수 하여 만든 궁중떡\n\n1949년, ‘ 홍 할머니네 떡집 ’ 으로 알려진 비원떡집이 처음 문을 열었습니다. 광복 이후 혼란기이자 6·25 전쟁이 일어나기 전, 홍간난 할머니가 창덕궁 낙선재에서 선보인 떡을 당시 조선왕조 마지막 궁중음식 기능 보유자인 한희순 상궁이 그녀를 눈여겨보고, 직접 홍 할머니에게 궁중 떡 비법을 전수해준 것이 시작이었습니다. 창덕궁 인근 살림집에서 떡을 만들어 팔던 가게는 지금까지도 임금님 상에 올리는 궁중떡 레시피 그대로 최고급 재료 선정부터 떡 제작까지 모든 과정을 100% 수작업으로 진행하고 있습니다.\n\n \n\n•  이곳은  \' 서울미래유산 \' 으로 선정된 곳입니다.  서울의 근 · 현대 문화유산 중에서 미래 세대에게 전달할 만한 가치가 있는 유무형의 자산인 서울미래유산을 오래가게 여행에서 만나보세요.  (서울미래유산 홈페이지)', 37.579778, 126.984878, '', '지하철 3호선 안국역 2번 출구, 324m', '두텁떡, 쌍개피, 잣설기, 약식, 쑥찹쌀떡', '매일', ' http://www.biwon.net/', '카페, 디저트', '', '매일 10:00 ~ 17:00\n*떡 소진시 조기 마감 (일요일은 예약떡만 제조 후 마감)', '02-765-4928', '없음'),
	(471, '불이아', '03995  서울특별시 마포구 동교로 182-6 (동교동)', 'images/불이아_471.jpg', '중국 본토 훠궈보다는 덜 맵게 중국식 훠궈를 먹을 수 있는 곳.\n\n중국식 훠궈를 먹을 수 있는 곳. 한국인의 입맛에 맞춰 중국 본토 훠궈보다는 덜 맵습니다. 쇠고기, 양고기, 각종 채소, 버섯 등 다양한 토핑을 듬뿍 넣은 정식이 대표적인 메뉴입니다.', 37.556585, 126.922001, '2만원대', '지하철 경의중앙선/ 공항철도/ 2호선 홍대입구역 1번 출구, 88m', '불이아정식, 쇠고기정식, 양고기정식, 해물정식', '', ' https://app.catchtable.co.kr/ct/shop/bulia', '음식점', '', '매일 11:00 ~ 23:00', '02-335-6689', '연중무휴'),
	(472, '스시겐', '04037  서울 마포구 양화로7길 6-12 (서교동, 삼이빌딩)', 'images/스시겐_472.jpg', '동교동의 숨은 일식 맛집. 그릇에 담긴 밥 위에 생선을 올린 지라시 초밥.\n\n동교동의 숨은 일식 맛집. 밥알에 생선을 올리는 일반 초밥와 달리 그릇에 담긴 밥 위에 생선을 올린 지라시 초밥을 간판 메뉴로 내세우는 곳입니다. 참치, 연어, 장어, 광어, 도미, 오징어, 조개관자, 성게 알 등이 푸짐하게 들어 있습니다. 저녁에는 안주를 겸해 따끈하게 맛볼 수 있는 창코나베(냄비요리)가 독특합니다. 신선한 재료를 사용하여 정갈하게 음식을 내옵니다.', 37.551632, 126.915641, '3만원대', '지하철 2/6호선 합정역 2번 출구, 125m', '정식코스, 모듬초밥', '월요일~토요일', '', '음식점', '', '11:30 ~ 15:00 / 17:00 ~ 22:00', '02-3144-7733', '매주 일요일 휴무'),
	(473, '카페 무자비', '04352  서울 용산구 한강대로84길 11-18 (남영동)', 'images/카페_무자비_473.jpg', '블락비 멤버 비범이 운영하는 카페.\n\n블락비 멤버 비범이 운영하는 카페. 4호선 숙대입구역 근처에 있으며, 단층으로 된 심플한 외관에 걸맞게 내부 인테리어도 깔끔하고 차분한 느낌을 줍니다. 스케줄이 없는 시간에 틈틈이 비범이 방문해 팬들과 함께 찍은 인증샷이나 사인을 SNS에서 어렵지 않게 찾을 수 있습니다.\n대표 메뉴는 에스프레소와 초콜릿, 스팀 우유로 만들어 달곰쌉쌀한 맛이 독특한 ‘무자비라테’. 음료 외에도 당근 케이크를 비롯한 케이크 메뉴가 구비되어 있으며, 카페 이름이 프린팅된 휴대폰 케이스와 티셔츠 등을 기념품으로 판매합니다.', 37.544454, 126.973203, '', '지하철 4호선 숙대입구역 5번 출구, 99m', '무자비라테, 말차라테', '', ' http://www.instagram.com/mujabee_official', '카페, 디저트', '', '매일 12:00~23:00', '0507-1432-1314', '휴무시 웹사이트 공지'),
	(474, '샘라이언스', '04350  서울 용산구 이태원로27가길 50 (이태원동)  2층', 'images/샘라이언스_474.jpg', '이태원 중심에 위치한 웨스턴 스타일 스포츠펍. 스포츠 채널과 함께 음식과 맥주를 즐길 수 있는 곳.\n\n샘라이언 이태원은 이태원 중심에 위치한 웨스턴 스타일 스포츠펍으로 다양한 스포츠 채널과 함께 음식과 맥주를 즐길 수 있는 곳입니다.  \n\n \n\n 이태원의 대표적인 스포츠 펍으로 다양한 스포츠 경기를 즐길 수 있고, 비어퐁, 배틀샷, 셔플보드, 스핀 등의 게임 공간도 준비되어 있습니다. 합리적인 가격으로 맥주와 함께 간단한 스낵 메뉴와 메인 메뉴를 즐길 수 있는 곳이며, 한국인은 물론 국내 거주 중인 외국인 모두에게 인기 있는 곳입니다.', 37.535068, 126.992556, '', '지하철 6호선 이태원역 1번 출구, 141m', '페퍼로니 피자, 마르게리따 피자', '', ' https://www.instagram.com/samryans.itaewon/', '술집, 바', '※ 전 직원 모두 영어응대 가능, 영어메뉴판 구비', '월요일~목요일 15:00~01:00\n금요일 15:00~03:00\n토요일 14:00~04:00\n일요일 14:00~02:00', '02-795-7933', ''),
	(475, '사동면옥', '03148  서울 종로구 인사동8길 9 (관훈동)', 'images/사동면옥_475.jpg', '황해도식 만두.어른 주먹보다 큰 황해도식 만두는 만두를 찌지 않고 삶아내는 것이 특징.\n\n황해도식 만두를 하는 곳입니다. 어른 주먹보다 큰 황해도식 만두는 만두를 찌지 않고 삶아내는 것이 특징입니다. 도가니탕과 녹두전, 파전이 빼놓을 수 없는 추천메뉴. 북한에 고향을 둔 이들이 고향의 맛을 찾을 수 있는 곳으로 옛날 한옥과 같은 실내 분위기가 운치 있습니다.', 37.574095, 126.985731, '', '지하철 1/3/5호선 종로3가역 5번 출구, 421m', '회냉면\n만둣국\n녹두전\n해물파전\n모둠전', '월요일~일요일', '', '음식점', '', '10:00 ~ 21:00', '02-725-1211', '명절 휴무'),
	(476, '중국', '03031  서울특별시 종로구 자하문로33길 2 (청운동)', 'images/중국_476.jpg', '자그마한 집이지만 짬뽕, 짜장면, 탕수육 등이 맛있는 집.\n\n자그마한 집이지만 짬뽕, 짜장면, 탕수육 등이 맛있는 집으로 소문난 집입니다.', 37.586194, 126.969724, '1만원대', '지하철 3호선 경복궁역 2번 출구, 1.1km', '짜장면, 짬뽕, 탕수육, 짬뽕밥', '월요일~토요일', '', '음식점', '', '10:00 ~ 13:00', '02-737-8055', '매주 일요일 휴무'),
	(477, '알라딘의양고기', '05559  서울 송파구 백제고분로7길 42-16 (정빌딩)', 'images/알라딘의양고기_477.jpg', '아랍식 양고기를 먹을 수 있는 곳. 아랍식으로 양념한 고기를 숯불에 구워 먹는 것이 특징.\n\n아랍식 양고기를 먹을 수 있는 곳. 아랍식으로 양념한 고기를 숯불에 구워 먹는 것이 특징입니다. 피타 빵에 싸 먹으면 색다른 맛을 느낄 수 있습니다.', 37.510125, 127.083710, '', '지하철 2호선 잠실새내역 3번 출구, 353m', '양꼬치살, 양갈비살, 불고기 양갈비', '', '', '음식점', '', '평일 16:00 ~ 24:00\n토요일 14:00 ~ 24:00\n일요일 14:00 ~ 22:00', '0507-1337-5534', '명절 당일 휴무'),
	(478, '춘천손칼국수', '04550  서울특별시 중구 마른내로 23 (저동2가)', 'images/춘천손칼국수_478.jpg', '여름에는 막국수, 겨울에는 칼국수가 인기있는 30년 전통의 면요리 전문점.\n\n여름에는 막국수, 겨울에는 칼국수가 인기있는 30년 전통의 면요리 전문점입니다. 칼국수에는 고명으로 닭고기와 땅콩가루가 뿌려져 있습니다. 육수는 닭을 삶은 육수이며, 면은 직접 반죽하여 사용하고 있습니다. 화가 출신의 주인이 직접 그린 그림들로 실내를 꾸민 것이 인상적입니다.', 37.564898, 126.990587, '1만원대', '지하철 2/3호선 을지로3가역 11번 출구, 200m', '', '월화수목금일', '', '음식점', '', '11:00 ~ 21:00', '02-2279-9885', '매주 토요일, 명절 휴무'),
	(479, '부산아구', '06038  서울 강남구 강남대로150길 10 (논현동)', 'images/부산아구_479.jpg', '아삭한 콩나물, 얼큰하지만 자극적이지 않은 쫀득한 아귀찜 맛이 일품\n\n아삭한 콩나물, 얼큰하지만 자극적이지 않은 쫀득한 아귀찜 맛이 일품입니다. 잘 숙성시킨 간장게장도 맛이 담백해서 인기 메뉴 중의 하나입니다.', 37.515778, 127.020703, '3만원대', '지하철 3호선/신분당선 신사역 3번 출구, 101m', '아구찜, 아구꽃게섞어찜, 꽃게찜, 낙지찜', '', '', '음식점', '', '월 ~ 토 10:00~15:00, 16:00 ~ 01:00\n일 10:00~15:00, 16:00 ~ 23:00', '02-546-9947', '명절 휴무'),
	(480, '속초생태집', '04526  서울특별시 중구 남대문로 25-17 (북창동)', 'images/속초생태집_480.jpg', '재료에 따라 그날 가능한 메뉴. 점심에는 주로 생태탕, 저녁에는 자연산 회와 매운탕.\n\n고정 메뉴가 없이 매일 매일 들어오는 재료에 따라 그날 가능한 메뉴와 가격을 적어 놓습니다. 점심에는 주로 생태탕을, 저녁에는 자연산 회와 매운탕을 냅니다. 임연수어 회, 갯상어 회, 청어회무침, 가자미 회, 보리새우 회 등의 회와 물곰, 도치, 삼숙이 등으로 끓인 매운탕도 맛볼 수 있습니다.', 37.562031, 126.978168, '', '지하철 1/2호선 시청역 7번 출구, 368m', '', '월화수목금토', '', '음식점', '', '월요일~금요일 10:30 ~ 21:00\n토요일 10:30 ~ 20:00', '0507-1404-8944', '매주 일요일, 명절 휴무'),
	(481, '황톳길', '04142  서울 마포구 마포대로11길 15-7', 'images/황톳길_481.jpg', '항아리 수제비와 산채비빔밥을 전문으로 하는 곳.\n\n항아리 수제비와 산채비빔밥을 전문으로 하는 곳입니다. 산채비빔밥은 취나물, 도라지, 고비, 숙주, 무생채, 애호박, 표고버섯과 유부를 넣어 비벼 먹습니다. 봄에는 냉이와 달래 등을 첨가합니다. 수제비는 콩가루, 땅콩가루 등을 밀가루에 섞어 2~3일 숙성시킨 반죽을 사용합니다.', 37.548939, 126.952894, '', '지하철 5/ 6호선/ 경의중앙선/ 공항철도 공덕역 3번 출구, 458m', '해물파전, 산채비빔밥, 불낙전골', '', '', '음식점', '', '월요일~토요일 11:30~22:00\n브레이크타임 15:00~17:00', '02-3272-9240', '매주 일요일, 명절 휴무'),
	(483, '한성칼국수', '06057  서울 강남구 언주로148길 14 (논현동, 청호불교문화원) 가동 2층', 'images/한성칼국수_483.jpg', '강남에서는 꽤 오래된 유명한 칼국숫집으로, 20년 전통을 자랑.\n\n강남에서는 꽤 오래된 유명한 칼국숫집으로, 20년 전통을 자랑합니다. 전반적으로 음식은 깔끔하고 담백한 편입니다. 날씨가 추워지면 싱싱한 굴을 넣고 지진 굴전이 일품입니다. 사골 국물로 낸 칼국수는 꼭 한 번 먹어볼 만합니다. 제육, 빈대떡, 굴전 등 술안주로 먹을 만한 메뉴가 많아 술자리로도 많이 이용됩니다.', 37.520630, 127.036163, '', '지하철 7호선/ 수인분당선 강남구청역 3-1번 출구, 869m', '칼국수, 만두국, 수육, 낙지볶음', '일요일~금요일', '', '음식점', '', '일요일~금요일 11:30~14:00, 17:00~20:00', '02-544-0540', '토요일 휴무'),
	(484, '부산식당', '03145  서울특별시 종로구 인사동11길 12 (관훈동)', 'images/부산식당_484.jpg', '집에서 먹는 음식 같이 간편한 백반이 나오는 집. 생태탕 추천.\n\n집에서 먹는 음식 같이 간편한 백반이 나오는 집. 부산 출신의 사장이 집에서 직접 띄운 된장으로 국물 맛을 냅니다. 주문을 하고 30분 정도 기다리면 방금 지은 콩밥이 제공됩니다. 생태찌개가 유명하며 두부도 맛있습니다.', 37.573898, 126.983996, '1만원대', '지하철 3호선 안국역 6번 출구, 377m', '생대구탕\n생두부', '월요일~토요일', '', '음식점', '', '11:00 ~ 21:30', '02-733-5761', '매주 일요일, 명절 휴무'),
	(485, '미피아체', '06064  서울 강남구 도산대로70길 34 (청담동)  1층', 'images/미피아체_485.jpg', '청담동에서 가장 오래된 레스토랑 중의 하나로, 오랫동안 변함없는 맛을 유지\n\n청담동에서 가장 오래된 레스토랑 중의 하나로, 오랫동안 변함없는 맛을 유지하고 있습니다. 정통 이탈리아식에 프랑스풍이 가미된 홈메이드 스타일의 요리를 선보입니다. 인테리어와 테이블웨어, 소품 등이 예쁘고 깔끔합니다. 전채, 메인, 디저트 모두 손색없이 훌륭하며 계절에 따라, 트렌드에 따라 메뉴가 자주 바뀌어 다양한 즐거움을 줍니다. 예약은 필수입니다.', 37.521469, 127.044873, '3만원대', '지하철 7호선/수인분당선 강남구청역 4번 출구, 629m', '스페인산 이베리코 하몽, 매콤한 닭 그릴, 어란 오일 파스타, 성게알 로제 파스타', '', ' https://www.instagram.com/restaurant_mipiace/', '음식점', '', '12:00 ~ 15:00 / 18:00 ~ 21:30', '02-516-6317', '명절 휴무'),
	(486, '개화옥', '06018  서울 강남구 압구정로50길 7 (정동상가)  1층', 'images/개화옥_486.jpg', '전통 한식을 가볍고 트렌디하게 재해석해서 선보이는 한식 레스토랑.\n\n전통 한식을 가볍고 트렌디하게 재해석해서 선보이는 한식 레스토랑. 메인 메뉴인 불고기 외에도 다양한 한식을 맛볼 수 있습니다. 건강야채구이와 된장국수는 이 집만의 별미입니다. 모든 음식이 한국의 전통 도자기에 담겨져나와 보는 즐거움을 더합니다.', 37.527741, 127.038594, '', '지하철 수인분당선 압구정로데오역 6번 출구, 145m', '소불고기, 보쌈, 차돌박이와 채소무침, 떡갈비, 김치말이국수', '', ' https://blog.naver.com/koreafood_gaewhaok', '음식점', '', '월요일~토요일 11:00~23:00', '02-549-1459', '매주 일요일, 연중무휴'),
	(487, '옛골', '06125  서울 강남구 봉은사로24길 12', 'images/옛골_487.jpg', '묵은 김치와 꽁치 통조림을 넣은 김치찌개가 별미\n\n묵은 김치와 꽁치 통조림을 넣은 김치찌개가 별미입니다. 새콤하면서도 시원한 전통 김치찌개의 맛을 냅니다. 충청도에서 직접 담가 숙성시켜 가져오는 김치를 갖은 재료와 양념을 한꺼번에 넣고 센 불에 끓여냅니다.', 37.505046, 127.032358, '', '지하철 9호선 언주역 8번 출구, 182m', '꽁치찌개, 김치/된장 찌개, 제육/오징어 볶음', '월~토', '', '음식점', '', '08:00 ~ 20:50 (브레이크타임 16:00~17:00)', '02-561-0591', '매주 일요일, 명절 휴무'),
	(488, '늘푸른목장', '05563  서울특별시 송파구 백제고분로9길 34 (잠실동)', 'images/늘푸른목장_488.jpg', '갈빗살을 전문으로 하는 곳. 메뉴는 갈비살과 육회.\n\n갈빗살을 전문으로 하는 곳. 메뉴는 갈비살과 육회 두 가지뿐입니다. 참숯불에 약간 양념을 한 갈빗살을 구워 먹는 맛이 일품. 가격대비 만족도도 높습니다. 줄을 서서 기다려야 할 정도로 손님이 많습니다.', 37.509588, 127.082650, '', '지하철 2호선 잠실새내역 4번 출구, 411m', '한우, 된장찌개, 갈비살, 육회, 생갈비', '월요일~일요일', '', '음식점', '', '12:00~24:00', '02-3431-4520', '연중무휴'),
	(489, 'MK2', '03043  서울특별시 종로구 자하문로10길 17 (창성동)', 'images/MK2_489.jpg', '커피와 함께 인테리어 소품들을 즐길 수 있는 곳. 소품들 판매. 조용한 주변 분위기.\n\n커피와 함께 인테리어 소품들을 즐길 수 있는 곳. 소품들은 판매도 겸하고 있습니다. 주변 분위기가 조용합니다.', 37.579510, 126.972519, '', '지하철 3호선 경복궁역 3번 출 , 472m', '', '', '', '카페, 디저트', '', '매일 12:00 - 21:00', '02-730-6420', '명절'),
	(490, '명동돈가스', '04534  서울특별시 중구 명동3길 8 (명동1가)', 'images/명동돈가스_490.png', '한국 최초로 두툼한 일본식 돈가스를 선보인 곳. 30여 년의 전통의 명동 터줏대감.\n\n한국 최초로 두툼한 일본식 돈가스를 선보인 곳. 30여 년의 전통을 자랑하는 명동의 터줏대감입니다. 1층 테이블 바에서는 튀겨지는 돈가스를 바로 맛볼 수 있습니다. 로스가스를 얇게 펴서 채소와 피자치즈를 넣어 함께 튀긴 코돈브로가 인기메뉴입니다.', 37.564027, 126.983575, '1만원대', '지하철 2호선 을지로입구역 6번 출구, 244m', '돈가스', '월요일 ~ 일요일', '', '음식점', '', '11:00 ~ 21:00', '02-775-5300', '명절 휴무'),
	(491, '대문', '01316  서울 도봉구 시루봉로 139-6', 'images/대문_491.jpg', '정갈하고 맛있는 음식이 가득한 쾌적한 한정식집.\n\n수라상이 부럽지 않은 대문정식\n\n대문정식에는 곱게 채쳐 고명을 올린 고소한 탕평채, 과일소스로 맛을 낸 야채 샐러드, 자연색소로 색을 낸 오리오색전, 해파리 냉채가 입맛을 살려줍니다. 주요리를 먹고 나면 불고기와 시래기 된장 무침 등 토속적이면서도 맛깔진 밑반찬에 된장찌개와 돌솥밥이 나옵니다.', 37.664577, 127.027976, '', '지하철 4호선 쌍문역 2번출구, 2.3km (7번 마을버스타고 방학동 성당하차)', '간장게장정식, 대문특정식, 백합정식', '', '', '음식점', '', '매일 11:30~15:00, 17:00~21:00', '0507-1359-0843', ''),
	(492, '전주설렁탕', '05557  서울 송파구 백제고분로7길 33 (잠실동)', 'images/전주설렁탕_492.jpg', '30년 전통의 한우 설렁탕집. 설렁탕, 도가니탕, 수육, 선지해장국.\n\n30년 전통의 한우 설렁탕집. 설렁탕 외에도 도가니탕도 많이 찾는 메뉴입니다. 수육도 한 접시 곁들이면 좋습니다. 24시간 영업에 선지해장국도 있어 해장하려는 사람들도 많이 찾습니다.', 37.510934, 127.082608, '', '지하철 2호선 잠실새내역 4번 출구, 268m', '도가니탕, 설렁탕, 곰탕, 우족수육', '매일', '', '음식점', '', '24시간 영업', '02-412-7495', '연중무휴'),
	(493, '부산갈비', '04547  서울특별시 중구 마른내로 107-1 (오장동)', 'images/부산갈비_493.jpg', '40년 가까이 되는 역사를 가진 갈빗집. 일대에서는 맛집으로 소문이 난 곳.\n\n40년 가까이 되는 역사를 가진 갈빗집. 일대에서는 맛집으로 소문이 난 곳입니다. 갈비를 먹고 난 후에는 냉면으로 식사하면 좋습니다. 점심에만 선보이는 버섯생불고기와 갈비탕, 냉면세트는 인근 직장인들에게 인기가 좋습니다.', 37.564652, 126.999906, '', '지하철 2/ 5호선 을지로4가역 8번 출구, 347m', '', '화요일~일요일', '', '음식점', '', '10:00~23:00', '02-2279-5821', '월요일, 명절 휴무'),
	(494, '파주옥', '04555  서울특별시 중구 마른내로2길 23 (초동)', 'images/파주옥_494.jpg', '족과 꼬리 등을 대형 가마솥에 넣고 5시간 이상 푹 끓여낸 진한 국물 맛.\n\n족과 꼬리 등을 대형 가마솥에 넣고 5시간 이상 푹 끓여낸 국물 맛이 진합니다. 겉절이도 설렁탕만큼이나 알려져 있습니다. 원래는 평택에서 시작하여 서울에까지 분점을 냈습니다.', 37.563419, 126.991895, '1만원대', '지하철 3/ 4호선 충무로역 6번 출구, 311m', '꼬리곰탕', '월요일~토요일', '', '음식점', '', '11:00 ~ 21:00\n브레이크타임 15:00~17:00', '02-2267-6149', '일요일'),
	(495, '김영모과자점', '06295  서울특별시 강남구 언주로30길 10 (도곡동)', 'images/김영모과자점_495.jpg', '대한민국 제과 명장인 김영모 대표가 운영하는 가게로 30여 년 동안 꾸준하게 사랑 받는 몇 남지 않은 개인 빵집. 특히 결을 따라 빙글빙글 돌려먹는 몰블랑은 별미.\n\n대한민국 제과 명장인 김영모 대표가 운영하는 가게로 30여 년 동안 꾸준하게 사랑 받는 몇 남지 않은 개인 빵집입니다. 특히 결을 따라 빙글빙글 돌려먹는 몰블랑은 입안에서 사르르 녹습니다.', 37.487339, 127.051554, '1만원대', '지하철 3호선 매봉역 3번 출구, 562m', '베이커리', '매일', ' http://k-bread.com/', '카페, 디저트', '', '08:00 ~ 22:30', '0507-1426-2005', '연중무휴'),
	(496, '뽐모도로', '03183  서울특별시 종로구 새문안로9길 19-1 (당주동)', 'images/뽐모도로_496.jpg', '광화문에서 한 시간씩 줄 서서 먹어야 하는 스파게티집\n\n파스타가 그리 흔하지 않았던 시절에 광화문에서 한 시간씩 줄 서서 먹어야 하는 스파게티집으로 유명해진 곳입니다. 즉석에서 만들어주는 파스타 소스가 여전히 인기가 좋습니다.', 37.571121, 126.975663, '', '지하철 5호선 광화문역 7번 출구, 142m', '로마풍 스파게티, 새우와 마늘 크림소스의 스파게티', '월요일~토요일', ' https://www.instagram.com/pomodoro_1994', '음식점', '', '평일 11:20 ~ 21:00\n(Break Time 15:00 ~ 17:00)', '02-722-4675', '일요일, 공휴일 휴무'),
	(497, '텀블러비어', '06236  서울특별시 강남구 테헤란로20길 15 (역삼동)', 'images/텀블러비어_497.jpg', '유럽식 펍 같은 분위기. 오후 5시에서 8시까지는 생맥주 무한리필 행사. (단, 금, 토, 일 제외)\n\n유럽식 펍 같은 분위기에서 맥주와 나쵸 등의 안주를 즐기기에 좋습니다. 오후 5시에서 8시까지는 생맥주 무한리필 행사도 하고 있어 젊은이들이 많이 찾습니다. (단, 금, 토, 일 제외)', 37.498747, 127.034760, '', '지하철 2호선 역삼역 3번 출구, 256m', '독일식치킨, 모둠소시지', '월요일~토요일', '', '술집, 바', '', '월~금 16:00~04:00\n토 16:00~24:00', '02-538-6665', '일요일'),
	(498, '정감어린', '04336  서울특별시 용산구 후암로 4 (후암동)', 'images/정감어린_498.gif', '맛\'으로 기억되기 위해 30년 동안 모든 메뉴에 정성을 쏟는 고기 맛집.\n\n\'맛\'으로 기억되기 위해 30년 동안 모든 메뉴에 정성을 쏟아오고 있습니다. 까다롭게 엄선된 재료와 비법이 담긴 메뉴가 정감어린을 빛냅니다.', 37.546254, 126.978689, '2만원대', '지하철 4호선 숙대입구역 2번 출구, 581m', '돼지갈비\n소갈비\n불고기', '화요일~일요일', '', '음식점', '', '평일 11:30~14:30, 17:00~21:30\n토요일 12:00 ~ 21:30\n일요일 12:00 ~ 21:00', '0507-1404-4389', '월요일, 명절 휴무'),
	(499, '첨벙아구찜', '06038  서울특별시 강남구 강남대로150길 12 (논현동)', 'images/첨벙아구찜_499.jpg', '콩나물이 듬뿍 들어간 쫄깃한 아귀찜.\n\n콩나물이 듬뿍 들어간 쫄깃한 아귀찜이 유명합니다. 잘게 부순 김에 밥을 동그랗게 묻혀낸 못난이 주먹밥도 이 집의 명물. 매운 아귀찜을 먹을 때 곁들여서 먹으면 좋습니다. 짜지 않고 슴슴하게 만든 간장게장을 먹으려고 오는 손님들도 많습니다. 신사동의 아귀찜 골목의 원조로 꼽힙니다.', 37.515853, 127.020918, '', '지하철 3호선/ 신분당선 신사역 1번 출구, 89m', '꽃게탕,꽃게범벅, 낙지찜, 아귀찜, 간장게장, 홍어찜', '월요일~일요일', '', '음식점', '', '11:00 ~ 15:00 / 16:00 ~ 04:00', '02-543-8873', '명절 휴무'),
	(500, '대우부대찌개', '06131  서울 강남구 테헤란로25길 34', 'images/대우부대찌개_500.jpg', '우리식 부대찌개를 맛볼 수 있는 곳. 햄, 소시지, 다진 고기와 떡, 국수사리 등이 주재료.\n\n우리식 부대찌개를 맛볼 수 있는 곳. 햄, 소시지, 다진 고기와 떡, 국수사리 등이 주재료로 들어갑니다. 느타리, 양송이, 미나리, 쑥갓 등 채소 종류도 풍부합니다. 실내가 쾌적하면서도 널찍하여 회식 자리로도 좋습니다.', 37.502676, 127.035215, '', '지하철 2호선 역삼역 6번 출구, 269m', '부대찌개, 김치찌개, 스테이크', '일요일~금요일', '', '음식점', '', '평일 11:00 ~ 15:00 / 17:00 ~ 21:00\n일요일 11:30 ~ 15:00 / 17:00 ~ 21:00', '02-552-1663', '매주 토요일'),
	(501, '여수동촌', '06195  서울 강남구 삼성로75길 9 (대치동)', 'images/여수동촌_501.jpg', '여수식을 표방하는 해산물집. 새조개, 키조개가 대표 메뉴.\n\n남도식 중에서도 여수식을 표방하는 곳으로, 여수식 삼합(새조개, 키조개, 돼지고기)과 새조개, 키조개가 대표 메뉴입니다. 여름에는 하모(갯장어)샤브샤브가 권할 만합니다. 점심때는 멍게비빔밥, 돌게장 등의 메뉴를 즐길 수도 있습니다. 가격이 다소 비쌉니다.', 37.503368, 127.057475, '', '지하철 2호선/ 수인분당선 선릉역 1번 출구, 1km', '새조개 샤브샤브(겨울~봄), 하모 샤브샤브(여름~가을)', '매일', '', '음식점', '', '10:00 - 14:00 / 16:00 - 22:00\n주말 11:00 - 22:00', '02-556-0530', ''),
	(502, '한추', '06029  서울 강남구 논현로175길 68 (신사동)', 'images/한추_502.jpg', '외국인들이 가장 좋아하는 한국 음식 중의 하나인 치킨이 대표 메뉴. 서민적인 분위기로 퇴근 후 가볍게 맥주를 즐기는 곳.\n\n외국인들이 가장 좋아하는 한국 음식 중의 하나인 치킨이 대표 메뉴인 곳. 서민적인 분위기로 퇴근 후 가볍게 맥주를 즐기는 이들로 저녁 때면 북적거립니다. 프라이드 치킨, 양념 치킨이 메인 메뉴지만 바삭하고 알싸한 고추튀김도 꼭 맛봐야 합니다.', 37.524082, 127.023449, '', '지하철 3호선 압구정역 5번 출구, 544m', '후라이드치킨\n고추튀김\n계란말이', '월화수목금토', '', '술집, 바', '', '월~목 14:00~24:00, 금~토 14:00~01:00', '02-541-0969', '매주 일요일, 명절 휴무'),
	(503, '온마을', '03049  서울 종로구 삼청로 127 (삼청동)', 'images/온마을_503.jpg', '두부 요리 전문점. 서리태 두부와 두부젓국찌개.\n\n두부 요리 전문점. 서리태로 만든 고소한 서리태 두부와 명란젓으로 간을 한 두부젓국찌개가 인기 메뉴로, 놋수저와 놋그릇에 담겨 나옵니다.', 37.586683, 126.981559, '1만원대', '지하철 3호선 안국역 1번 출구, 1.4km', '두부버섯전골, 두부김치전골, 콩두부젓국찌개, 제육볶음', '', '', '음식점', '', '매일 11:00~21:00', '02-738-4231', '명절 휴무'),
	(504, '막내회센타', '07315  서울특별시 영등포구 도신로53길 7 (신길동)', 'images/막내회센타_504.jpg', '농어, 전어, 방어, 도치, 숭어 등 쉽게 접하기 어려운 자연산 잡어들을 제공.\n\n농어, 전어, 방어, 도치, 숭어 등 쉽게 접하기 어려운 자연산 잡어들을 제공합니다. 코스로 주문하면 고등어조림, 해삼, 참새우, 민어, 잡어 등 다양하게 맛볼 수 있습니다. 단골이 되면 여러 가지 친절한 서비스를 받을 수 있기 때문에 열광하는 손님들이 많습니다. 새로 이전한 곳은 더욱 넓고 쾌적한 분위기입니다. 방문하기 전 예약은 필수.', 37.511909, 126.914401, '', '지하철 1/ 5호선 신길역 1번 출구, 705m', '', '월~토', ' https://www.siksinhot.com/P/254921', '음식점', '', '11:00 - 22:00', '02-844-6150', '일요일 휴무'),
	(505, '레트로오븐', '06097  서울 강남구 봉은사로55길 25', 'images/레트로오븐_505.jpg', '한적한 주택가에 있는 빵집. 빵 맛이 좋기로 유명한 곳. 많은 속 재료를 넣어 만들기보다는 치아바타나 올리브빵 같이 빵 자체의 맛에 중점.\n\n한적한 주택가에 있는 빵집으로, 빵 맛이 좋기로 유명한 곳입니다. 많은 속 재료를 넣어 만들기보다는 치아바타나 올리브 빵 같이 빵 자체의 맛에 중점을 둡니다. 부드러우면서 쫄깃한 식감이 뛰어나며 오후가 되면 빵 대부분이 떨어지기 때문에 일찍 가거나 전화로 빵이 남았는지 문의한 후 가보는 것이 좋습니다.', 37.512071, 127.043935, '1만원대', '지하철 9호선 / 수인분당선 선정릉역 2번 출구, 284m', '베이커리', '', ' http://instagram.com/retrooven2008', '카페, 디저트', '', '수~토 13:00 ~ 19:00', '02-544-9045', '일~화'),
	(506, '어바웃샤브', '03086  서울특별시 종로구 대학로12길 61 (동숭동)', 'images/어바웃샤브_506.jpg', '가볍게 즐길 수 있는 한국식 샤브샤브 전문점. 홍탕, 백탕, 해탕의 3가지 육수.\n\n가볍게 즐길 수 있는 한국식 샤브샤브 전문점입니다. 매운맛의 홍탕, 사골육수인 백탕, 가다랭이 육수인 해탕의 3가지 육수에 싱싱한 야채와 고기, 해산물을 데쳐 칠리소스, 레몬소스와 함께 먹습니다.', 37.581425, 127.004017, '', '지하철 4호선 혜화역 2번 출구, 244m', '쇠고기샤브칼국수, 쇠고기샤브세트, 우삼겹철판구이', '월요일~일요일', '', '음식점', '', '10:30 ~ 22:00 (Last Order 21:00까지)', '02-747-7730', '명절휴무'),
	(507, '전주청국장집', '06526  서울특별시 서초구 나루터로 70 (잠원동)', 'images/전주청국장집_507.jpg', '청국장 냄새가 진하지 않으면서도 특유의 구수함이 살아 있는 청국장 전문점.\n\n청국장 냄새가 진하지 않으면서도 특유의 구수함이 살아 있습니다. 곁들여 나오는 콩나물, 무생채 등의 밑반찬들과 비벼 먹으면 맛이 좋습니다. 간장게장도 유명합니다.', 37.515353, 127.017752, '', '지하철 3호선/신분당선 신사역 4번 출구, 154m', '청국장, 오징어볶음, 된장찌개, 제육볶음, 간장게장', '', '', '음식점', '', '평일 10:00~16:00, 17:00~22:00\n주말 07:00~16:00, 17:00~22:00', '02-541-3579', '연중무휴'),
	(508, '왕가', '01002  서울특별시 강북구 삼양로 681 (우이동)', 'images/왕가_508.jpg', '왕가는 자연경관이 수려한 삼각산 밑에 위치한 한우전문 음식점이다.\n\n왕가는 자연경관이 수려한 삼각산 밑에 위치한 한우전문 음식점입니다. 최고의 품질과 저렴한 가격으로 한우를 즐길 수 있습니다.', 37.663429, 127.012024, '', '지하철 우이신설선 북한산우이역 2번 출구, 71m', '소고기 구이', '월화수목금토일', '', '음식점', '', '11:00~ 22:00', '02-908-9277', '연중 무휴'),
	(509, '몽중헌', '06015  서울 강남구 도산대로 445 (청담동, M빌딩)  지하 1층', 'images/몽중헌_509.jpg', '광동식 중식과 홍콩식 딤섬, 콘지 등을 맛볼 수 있는 곳.\n\n광동식 중식과 홍콩식 딤섬, 콘지 등을 맛볼 수 있는 곳입니다. 입구에 있는 주방에서는 딤섬을 만드는 광경이 보입니다. 실내 분위기도 고급스럽고 서빙도 만족스러운 편입니다. 위치가 청담동인 만큼 가격대는 높은 편입니다.', 37.524335, 127.044788, '2만원대', '지하철 수인분당선 압구정로데오역 3번 출구, 621m', '시그니처 딤섬, 광동식 전가복, 유린기, 후난식 볶음밥', '', ' http://www.mongjungheon.co.kr/', '음식점', '', '평일 11:30~15:00, 17:30~22:00, 주말 11:30~15:00, 17:30~21:30', '02-3446-7887', '연중무휴'),
	(510, '충무로쭈꾸미불고기', '04554  서울특별시 중구 퇴계로31길 11 (필동1가)', 'images/충무로쭈꾸미불고기_510.jpg', '30여 년 동안 꾸준히 사랑을 받는 매콤한 양념 주꾸미를 숯불에 구워 먹는 곳.\n\n30여 년 동안 꾸준히 사랑을 받는 곳으로, 매콤한 양념이 되어 있는 주꾸미를 숯불에 구워 먹습니다. 주꾸미 하나를 시키는 것보다는 주꾸미, 낙지, 키조개가 같이 나오는 모둠을 시키는 편이 좋습니다. 주꾸미볶음을 먹을 후 볶아 먹는 야채볶음밥도 별미입니다.', 37.561762, 126.992203, '2만원대', '지하철 3/4호선 충무로역 5번 출구, 124m', '주꾸미', '월요일~토요일', ' https://jjubulgogi.modoo.at/', '음식점', '', '12:00 ~ 22:00\n토요일 12:00 ~ 21:30', '02-2279-0803', '매주 일요일, 명절 휴무'),
	(511, '램랜드', '04159  서울 마포구 토정로 255', 'images/램랜드_511.jpg', '뉴질랜드산 양고기를 한국식이나 중국식으로 요리.\n\n뉴질랜드산 양고기를 한국식이나 중국식으로 요리합니다. 양 갈비를 철판에 직접 구워 마늘, 김치, 오이 등을 곁들여 먹습니다. 양고기 튀김은 중국식 요리법을 따릅니다. 양갈비는 샐러드와 올리브 들깻가루와 레몬이 첨가된 머스터드소스와 함께 걸레빵에 싸 먹으면 제맛입니다. 걸레빵은 인도 요리에서 먹는 난과 비슷한 것입니다. 머튼에 가까운 양고기를 사용하기 때문에 양고기 특유의 냄새가 강한 편입니다.', 37.543354, 126.938877, '2만원대', '지하철 5호선 마포역 1번 출구, 807m\n지하철 6호선 대흥역 3번출구, 619m', '삼각갈비, 수육, 전골, 용봉탕', '', ' http://www.lambland.kr/', '음식점', '', '11:30~15:00, 16:30~22:00', '02-704-0223', '명절 휴무'),
	(512, '장원북어국', '07333  서울특별시 영등포구 국제금융로8길 11 (여의도동)', 'images/장원북어국_512.jpg', '여의도 일대에서는 알아주는 북엇국 집. 뽀얀 국물에 두부와 달걀을 풀어낸 국물이 시원 담백.\n\n여의도 일대에서는 알아주는 북엇국 집. 뽀얀 국물에 두부를 가늘게 썰어 놓고 달걀을 풀어낸 국물 맛이 시원 담백합니다.', 37.521100, 126.929734, '', '지하철 9호선/ 신림선 샛강역 2번 출구, 566m', '북어국, 콩나물김칫국, 육개장, 동태탕', '월요일~금요일', '', '음식점', '', '평일 06:30 ~ 15:00', '02-784-0639', '주말, 명절 휴무'),
	(513, '라룬비올렛', '03992  서울특별시 마포구 월드컵북로4길 25 (동교동)', 'images/라룬비올렛_513.jpg', '비스트로 개념의 프랑스 요리를 비교적 저렴한 가격으로 맛볼 수 있는 곳\n\n비스트로 개념의 프랑스 요리를 비교적 저렴한 가격으로 맛볼 수 있는 곳입니다. 패스트리 위에 달팽이를 얹은 에스카르고, 닭다리살을 동그랗게 말아 만든 발로틴 등이 독특합니다. 가니미소파스타도 인기 메뉴. 진하면서도 무게 있는 맛의 요리가 와인을 부릅니다.', 37.557589, 126.920915, '', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 1번 출구, 261m', '에스카르고, 관자브릿지, 수비드 꼬숑, 라따뚜이', '', ' https://www.instagram.com/la_lune_violette/', '음식점', '', '11:30 ~ 15:30 / 17:30 ~ 22:00', '0507-1337-9463', ''),
	(514, '커피투어', '03175  서울특별시 종로구 경희궁2길 12 (내수동)', 'images/커피투어_514.jpg', '직접 로스팅한 원두를 사용하는 핸드드립 커피 전문점. 아담하고 좁은 공간이지만 커피 맛이 뛰어나 단골로 찾는 손님들이 많음. 커피 관련 각종 기구도 판매.\n\n직접 로스팅한 원두를 사용하는 핸드드립 커피 전문점. 아담하고 좁은 공간이지만 커피 맛이 뛰어나 단골로 찾는 손님들이 많습니다. 커피 관련 각종 기구도 판매하고 있습니다.', 37.572857, 126.971422, '', '지히철 5호선 광화문역 1번 출구, 200m', '', '일요일~금요일', ' http://www.coffeetour.co.kr/', '카페, 디저트', '', '월요일~금요일 08:00 ~ 17:00 / 일요일 09:00 ~ 18:00', '02-733-6611', '매주 토요일, 명절 휴무'),
	(515, '마미청국장', '03085  서울특별시 종로구 동숭4나길 2 (동숭동)', 'images/마미청국장_515.jpg', '대학로에서 청국장으로 유명한 집.\n\n대학로에서 청국장으로 유명한 집. 청국장과 같이 나오는 반찬들도 무난한 편입니다. 청국장 전문점답게 종류도 다양합니다. 샤브샤브도 많이 찾는 메뉴입니다.', 37.583182, 127.004235, '', '지하철 4호선 혜화역 1번 출구, 266m', '청국장, 버섯청국장, 김치청국장, 버섯불고기, 버섯모둠', '월화수목금토일', '', '음식점', '', '07:30 ~ 22:30', '02-765-0842', '명절 휴무'),
	(516, '카페먼데이투선데이', '06016  서울특별시 강남구 도산대로67길 13-3 (청담동)', 'images/카페먼데이투선데이_516.jpg', '유명 가구 디자이너들의 의자를 만나볼 수 있는 카페. 벽돌 외벽을 하얗게 칠해 깔끔하고 빈티지한 느낌. 커피와 음료뿐 아니라 와플, 브런치, 파스타, 와인도 준비.\n\n유명 가구 디자이너들의 의자를 만나볼 수 있는 카페. 벽돌 외벽을 하얗게 칠해 깔끔하고 빈티지한 느낌을 줍니다. 커피와 음료뿐 아니라 와플, 브런치, 파스타, 와인도 겸하고 준비되어 있습니다.', 37.524790, 127.044133, '', '지하철 수인분당선 압구정로데오역 3번 출구, 571m', '카페', '', ' https://www.instagram.com/diningbar_mondaytosunday', '음식점', '', '월요일~목요일 09:00 ~ 24:00\n금요일·토요일, 일요일 11:00 ~ 24:00', '0507-1353-2217', '연중무휴'),
	(517, '서초장어타운', '06645  서울 서초구 반포대로28길 77 (큰대문집)', 'images/서초장어타운_517.jpg', '살아 있는 장어를 숯불에 구워 먹는 맛이 일품\n\n살아 있는 장어를 숯불에 구워 먹는 맛이 일품입니다. 참숯을 사용하며 양념구이는 없고, 소금구이로만 즐길 수 있습니다. 절인 깻잎에 싸 먹으면 느끼한 맛이 가십니다. 채소는 셀프로 무제한 리필이 가능합니다.', 37.491926, 127.012399, '', '지하철 2/3호선 교대역 14번 출구, 149m', '장어, 장어탕, 잔치국수, 메밀국수', '매일', '', '음식점', '', '평일 11:30~15:00 / 16:30 ~22:00\n토, 일요일 12:00~15:00 / 16:30 ~21:00', '0507-1325-6934', '명절 휴무'),
	(518, '팬케이크오리지널스토리', '04419  서울특별시 용산구 독서당로 67 (한남동)', 'images/팬케이크오리지널스토리_518.jpg', '팬케이크와 토스트 등 브런치를 즐길 수 있는 브런치 카페. 부드러우면서도 식감이 좋은 팬케이크가 인기. 오믈렛, 팬케이크 세트 등 다양한 메뉴 판매\n\n팬케이크와 토스트 등 브런치를 즐길 수 있는 브런치 카페입니다. 부드러우면서도 식감이 좋은 팬케이크가 인기이며, 오믈렛, 팬케이크 세트 등 다양한 메뉴를 판매하고 있습니다.', 37.533869, 127.008154, '', '지하철 경의중앙선 한남역 1번 출구, 609m', '오리지널버터밀크팬케익, 초콜릿이퐁당 초콜릿팬케익, 바나나가듬뿍 팬케익', '매일', ' https://www.instagram.com/pancakesstory_hannam', '카페, 디저트', '', '평일 08:00~15:00 Last Order 14:00\n주말 09:00~16:00 Last Order 15:00\n(재료소진 시 조기마감)', '02-794-0508', '명절 휴무'),
	(519, '리북손만두', '04520  서울 중구 무교로 17-13 (무교동)', 'images/리북손만두_519.jpg', '시원하고 깔끔한 김치말이밥, 접시만두, 만둣국이 유명한 곳.\n\n시원하고 깔끔한 김치말이밥이 유명한 곳. 담백하고 고소한 접시만두나 만둣국도 인기 메뉴로, 어른 주먹만 한 만두 3개가 1인분입니다. 숙주나물과 갖가지 고기를 넣어 빚어낸 만두는 풍부하면서도 깔끔한 맛입니다. 점심때는 줄을 서야 할 정도입니다.', 37.567252, 126.978543, '', '지하철1/2호선 시청역 4번 출구, 219m', '만두국, 접시만두, 김치말이밥, 김치말이국수', '', '', '음식점', '', '평일 11:00~21:00, 주말 10:30~20:00\n14:30~17:00 (브레이크타임)', '02-776-7361', '명절 휴무'),
	(520, '아리랑', '04532  서울 중구 남대문로7길 23 (소공동, 전통한국식당)', 'images/아리랑_520.jpg', '직구매한 최상급 한우를 사용하여 참숯의 향과 어우러진 최고의 갈비.\n\n아리랑에서는 직구매한 최상급 한우만을 사용하여 참숯의 향과 어우러진 최고의 갈비 맛을 즐길 수 있습니다.', 37.563885, 126.980587, '', '지하철 2호선 을지로입구역 7번 출구, 349m', '숯불왕생갈비, 숯불왕양념갈비, 꽃등심, 육회', '월화수목금토', ' https://www.instagram.com/a.r.i.rang/', '음식점', '', '11:30 ~ 22:00', '02-752-1342', '매주 일요일, 명절 당일 휴무'),
	(521, '동강', '04427  서울특별시 용산구 이촌로 182 (이촌동)', 'images/동강_521.jpg', '유린기 맛집으로 작은 중식당이지만 깔끔한 맛으로 인기.\n\n테이블이 몇 개 없는 작은 중식당이지만 깔끔한 맛으로 인기가 좋습니다. 부귀새우는 저민 딸기와 튀긴 새우가 레몬즙을 뿌려 만든 담백한 화이트소스에 버무려져 나옵니다. 유린기는 닭가슴살이 아닌 닭다리살로 만들어 부드러운 것이 특징입니다. 짜장면은 돼지고기가 아니라 소고기를 사용하여 부드러운 맛입니다.', 37.521230, 126.967374, '1만원대', '지하철 4호선/ 경의중앙선 이촌역 4번 출구, 691m', '유린기, 게살스프, 사품냉채, 산라탕, 사천탕면', '', '', '음식점', '', '11:30 ~ 14:00 / 17:00 ~ 20:30', '02-794-1033', '월요일, 명절 휴무'),
	(522, '이노시시', '03981  서울 마포구 성미산로 197', 'images/이노시시_522.jpg', '신선한 회와 저렴한 가격으로 연남동 일대에서 이미 유명해진 이자카야. 최근에는 예약제로 바꾸어 6~7시에 한 타임, 9시에 한 타임 오마카세로 진행. 당일 예약 없이 갈 경우에는 3만원과 5만원 사시미코스 중 선택.\n\n신선한 회와 저렴한 가격으로 연남동 일대에서 이미 유명해진 이자카야입니다. 최근에는 예약제로 바꾸어 6~7시에 한 타임, 9시에 한 타임 오마카세로만 진행합니다. 당일 예약 없이 갈 경우에는 3만원과 5만원 사시미코스 중에 선택할 수 있습니다.', 37.562807, 126.926509, '', '지하철 2호선 / 공항철도 / 경의중앙선 홍대입구역 3번 출구, 574m', '초특급 오마카세, 특선사시미, 금태소금구이, 이베리코 스테이크', '', ' https://poingapp.page.link/inosisi', '술집, 바', '', '19:00 ~ 23:00', '070-4242-7307', '매주 일요일, 월요일, 명절 휴무'),
	(523, '장원족발', '03157  서울 종로구 종로 19 (르메이에르종로타운)  1층', 'images/장원족발_523.jpg', '족발과 빈대떡을 맛볼 수 있는 곳. 회사원들이 많아 점심 메뉴 추가.\n\n족발과 빈대떡을 맛볼 수 있는 곳. 피맛골에서 오랫동안 인기를 끌던 곳으로, 재개발과 함께 이전하였습니다. 이전한 르메이에르 점은 회사원들이 많아 점심 메뉴를 추가했습니다.', 37.570844, 126.979924, '', '지하철 1호선 종각역 1번 출구, 236m', '돌솥비빔밥, 오징어볶음, 떡만두국, 족발, 감자탕', '', '', '음식점', '', '매일 07:00~24:00', '02-734-7230', '명절 당일 휴무'),
	(524, '레스쁘아 뒤 이부', '06016  서울 강남구 도산대로56길 10 2층', 'images/레스쁘아_뒤_이부_524.jpg', '프랑스 본토의 맛을 즐길 수 있는 레스토랑.\n\n프랑스 본토의 맛을 즐길 수 있는 레스토랑. 특히 오리 다리 콩피와 양파 수프는 쉐프가 추천하는 이 집의 대표 메뉴입니다. 와인도 곁들일 수 있는데 하프보틀로 준비되어 있어 부담없이 즐길 수 있습니다. 넓은 실내에 여유롭게 식사할 수 있고 디저트 메뉴도 훌륭합니다. 2025년 미쉐린 가이드에 선정되었습니다.', 37.522444, 127.040059, '', '지하철 수인분당선 압구정로데오역 3번 출구, 479m', '킹크랩과 엔다이브 샐러드, 푸아그라', '', ' https://app.catchtable.co.kr/ct/shop/lespoir?from=share', '음식점', '', '매일 12:00 ~ 22:00\n(Break Time 15:00 ~ 17:30)', '02-517-6034', '매주 화요일'),
	(525, '파낙스', '07332  서울 영등포구 여의대방로65길 17 (여의도동, 서린빌딩)', 'images/파낙스_525.jpg', '15년 넘는 경력의 단순하고 깔끔한 옛 맛이 나는 삼계탕.\n\n단순하고 깔끔한 옛 맛이 나는 삼계탕을 맛볼 수 있습니다. 15년이 넘는 경력을 자랑하며 삼계탕과 함께 나오는 인삼주가 입맛을 돋웁니다. 한방삼계탕과 전복이 든 삼계탕도 맛볼 수 있습니다. 포장도 가능합니다.', 37.519707, 126.929229, '', '지하철 9호선/ 신림선 샛강역 2번 출구, 345m', '찰흑미삼계탕, 녹각삼계탕, 들깨삼계탕', '', '', '음식점', '', '매일 11:00~20:30', '02-780-9037', '명절 휴무'),
	(526, '샘밭막국수', '06633  서울 서초구 서초중앙로24길 27 G5센트럴프라자 지하1층', 'images/샘밭막국수_526.jpg', '3대째 이어 오는 춘천의 샘밭막국수의 서울 분점.\n\n3대째 이어 오는 춘천의 샘밭막국수의 서울 분점. 메밀을 80% 사용한 면을 사용합니다. 직접 뽑은 면발이 냉면에 비해 쫄깃함은 덜하지만, 툭툭 끊기는 맛이 부드럽습니다. 감자전, 돼지고기 보쌈도 추천 메뉴. 새우, 새송이버섯, 고기산적, 호박과 생선전 등을 부쳐낸 모둠전도 좋습니다. 다만, 춘천에서 맛보던 막국수를 기대하고 가면 실망할 수도 있습니다', 37.495411, 127.016402, '1만원대', '지하철 2/3호선 교대역 4번 출구, 157m', '', '월요일~일요일', '', '음식점', '', '11:30 ~ 21:00', '02-585-1702', '명절 휴무'),
	(527, '미진', '03157  서울특별시 종로구 종로 19 (종로1가)', 'images/미진_527.jpg', '60년 전통의 메밀국수 전문점. 한국적인 메밀국수 맛\n\n60년 전통의 메밀국수 전문점. 주인은 여러 번 바뀌었지만 오랜 기간 한국적인 메밀국수 맛을 내는 곳입니다. 가쓰오부시를 사용하는 일본식과 멸치를 사용하는 한국식을 절충하여 달착지근하면서도 담백하고 구수한 뒷맛이 좋습니다. 미쉐린 가이드 서울 2025에 선정되었습니다.', 37.570844, 126.979924, '', '지하철 1호선 종각역 1번 출구, 245m', '메밀국수', '월화수목금토일', '', '음식점', '', '10:30 ~ 21:00', '02-730-6198', '명절 휴무'),
	(528, '동북화과왕', '03119  서울 종로구 종로46길 11', 'images/동북화과왕_528.png', '조선족을 위한 연변식 중국요리. 양꼬치와 훠궈.\n\n조선족을 위한 연변식 중국요리를 하는 곳으로, 양꼬치와 훠궈가 주메뉴입니다. 탕수육만 해도 중국식, 광동식, 케첩, 파인애플, 레몬탕수육 등이 있을 정도로 다양한 메뉴를 자랑합니다. 가격도 저렴한 편입니다.', 37.571028, 127.010821, '2만원대', '지하철 1/4호선 동대문역 6번 출구, 87m', '양꼬치, 양갈비살, 훠궈', '', '', '음식점', '', '매일 11:30~24:00', '02-742-5168', '연중무휴'),
	(529, '라칼라스', '06719  서울특별시 서초구 반포대로 8 (서초동)  1층', 'images/라칼라스_529.jpg', '가볍게 이탈리아 요리를 즐길 수 있는 곳.\n\n가볍게 이탈리아 요리를 즐길 수 있는 곳. 안티 파스티(전채), 샐러드, 메인 디시, 피자, 디저트 외에 다양한 런치 세트와 디너 세트도 준비되어 있습니다. 내부 공간은 소프라노 마리아 칼라스를 모티브로 하여 꾸몄습니다.', 37.481505, 127.013045, '', '지하철 3호선 남부터미널역 5번 출구, 633m', '뽀모도로, 알리오올리오, 만조피자, 채끝등심스테이크', '', '', '음식점', '', '화요일~금요일 11:00~15:00 / 16:00~21:30\n토요일~일요일 11:00~15:30 / 16:30~22:00', '02-521-3325', '매주 월요일'),
	(531, '반짝반짝빛나는', '03148  서울특별시 종로구 인사동길 28-1 (관훈동)', 'images/반짝반짝빛나는_531.jpg', '전통과 현대의 퓨전식 카페. 유기농 재료로 오랜 시간 달인 전통차. 식혜나 수정과가 특히 인기. 전통공예 소품이 전시.\n\n전통과 현대의 퓨전식 카페. 유기농 재료로 오랜시간 달인 전통차를 맛볼 수 있습니다. 식혜나 수정과가 특히 인기. 전통공예 소품이 전시되어 있어 함께 즐기기에 좋습니다.', 37.573283, 126.986110, '1만원대', '지하철1/3/ 5호선 종로3가역 4번 출구, 190m', '카페', '매일', '', '카페, 디저트', '', '12:00 - 23:00', '02-738-4525', '연중무휴'),
	(532, '한강치킨', '04423  서울특별시 용산구 이촌로75길 12 (이촌동)', 'images/한강치킨_532.jpg', '프라이드 치킨의 튀김옷이 맛있는 집. 간단하게 맥주 한잔할 수 있는 동네 치킨집 분위기. 손님이 많아서 맥주의 소비율이 높아 생맥주가 신선.\n\n프라이드 치킨의 튀김옷이 맛있는 집. 간단하게 맥주 한잔할 수 있는 동네 치킨집 분위기로, 손님이 많아서 맥주의 소비율이 높아 생맥주가 신선합니다.', 37.520424, 126.974264, '', '지하철 4호선 / 경의중앙선 이촌역 3-1번 출구, 226m', '', '월요일~일요일', '', '술집, 바', '', '12:00 ~ 02:00', '02-795-2668', '연중무휴'),
	(533, '비타민카페&펍', '06166  서울 강남구 삼성로100길 23-5 (삼성동)', 'images/비타민카페&펍_533.jpg', '상호와 노란색으로 칠해진 외관부터 상큼한 느낌. 건강, 미용을 콘셉트로 하는 카페로, 비타민을 모든 음료에 넣어주고 실내 인테리어도 칼라풀한 소품을 사용. 싱그러운 야외의 테라스와 나무들.\n\n상호와 노란색으로 칠해진 외관부터 상큼한 느낌을 줍니다. 건강, 미용을 콘셉트로 하는 카페로, 비타민을 모든 음료에 넣어주고 실내 인테리어도 칼라풀한 소품을 사용하고 있고 야외의 테라스와 나무들도 싱그럽습니다.', 37.510391, 127.057074, '', '지하철 2호선 삼성역 5번 출구, 669m', '카페&펍', '매일', '', '술집, 바', '', '18:00~02:00', '02-566-2367', ''),
	(534, '서대문곱창', '04556  서울 중구 충무로2길 35 (충무로4가)', 'images/서대문곱창_534.jpg', '30년 전통의 철판구이 곱창집.\n\n30년 전통의 곱창집. 감자, 양파 등과 함께 철판에 구워 먹는 곱창 맛이 일품입니다. 곱창이 다 익으면 마지막에 소주를 뿌려 불 쇼로 마무리해줍니다.', 37.562418, 126.995130, '', '지하철 3/4호선 충무로역 8번 출구, 130m', '양곱창', '월요일~토요일', '', '음식점', '', '17:00 ~ 22:30', '02-2266-4345', '일요일, 명절 휴무'),
	(535, '옴', '03183  서울 종로구 새문안로 103 (신문로1가, 선광빌딩)', 'images/옴_535.jpg', '네팔관광청 소장이 운영하는 네팔/인도 요리 전문점.\n\n네팔관광청 소장이 운영하는 네팔/인도 요리 전문점. 인도전통 향신료에 하루 동안 재운 후 화덕에 구운 탄두리 치킨과 다양한 종류의 커리를 맛볼 수 있습니다. 인도요리 특유의 향이 나긴 하지만 많이 강하지 않은 편입니다.', 37.570529, 126.976089, '2만원대', '지하철 5호선 광화문역 7번 출구, 69m', '모듬탄두리바비큐, 옴미니세트, 양고기티카, 치킨멀라이케밥', '', ' http://www.omfood.kr', '음식점', '', '매일 11:00 ~ 22:00', '02-723-4848', '연중무휴'),
	(536, '잼배옥', '04513  서울특별시 중구 세종대로9길 68-9 (서소문동)', 'images/잼배옥_536.jpg', '3대째 이어오는 설렁탕집. 모둠 수육이 인기 메뉴.\n\n3대째 이어오는 설렁탕집. 머리 고기, 차돌박이, 양지, 우설, 아롱사태, 지라 등을 맛볼 수 있는 모둠 수육이 인기 메뉴입니다. 1933년 서울역에서 시작하여 근래 시청 쪽으로 이전했습니다.', 37.562498, 126.973729, '', '지하철 1/2호선 시청역 9번 출구, 155m', '설렁탕', '월요일~토요일', '', '음식점', '', '월요일~금요일 10:00~21:30, 토요일 11:00~15:00', '02-755-8106', '매주 일요일, 공휴일 휴무'),
	(537, '커피친구', '03150  서울특별시 종로구 삼봉로 81 (수송동)', 'images/커피친구_537.jpg', '직접 원두를 볶아 손으로 내린 핸드 드립 커피를 맛볼 수 있는 곳.\n\n직접 원두를 볶아 손으로 내린 핸드 드립 커피를 맛볼 수 있는 곳으로, 다양한 원두커피를 즐길 수 있습니다. 갓 볶은 원두는 판매도 합니다. 에스프레소를 좋아하는 사람은 에스프레소 베이스 커피도 준비되어 있습니다.', 37.572470, 126.981643, '1만원대', '지하철1호선 종각역 2번 출구, 235m', '커피전문점\n스트레이트커피(5천원~6천원), 더치커피(7천원)', '월요일~토요일', '', '카페, 디저트', '', '평일 10:00 ~ 20:30\n토요일 12:00 ~ 17:30', '02-725-0179', '매주 일요일 휴무'),
	(538, '라본느타르트', '03721  서울 서대문구 연대동문길 29 (대신동)  1층', 'images/라본느타르트_538.jpg', '집에서 직접 만든 듯한 타르트를 먹을 수 있는 곳. 호두, 호두크림치즈, 호두 초코칩, 고구마, 호박, 초콜릿, 사과, 블루베리치즈 파이. 차를 곁들일 수 있는 카페.\n\n집에서 직접 만든 듯한 타르트를 먹을 수 있는 곳. 호두, 호두크림치즈, 호두 초코칩, 고구마, 호박, 초콜릿, 사과, 블루베리치즈 등의 파이가 있습니다. 차를 곁들일 수 있는 카페를 겸하고 있습니다.', 37.563917, 126.943833, '', '지하철 경의중앙선 신촌역 2번 출구, 582m', '디저트카페', '월요일~토요일', ' https://www.instagram.com/labonnetarte_official/', '카페, 디저트', '', '평일 08:00 ~ 20:00\n토요일 09:00 ~ 17:00', '02-393-1117', '일요일,명절 휴무'),
	(539, '산띠', '04053  서울 마포구 와우산로27길 70', 'images/산띠_539.jpg', '인도, 네팔 음식을 저렴하게 즐길 수 있는 곳.\n\n인도, 네팔 음식을 저렴하게 즐길 수 있는 곳입니다. 대체로 네팔 음식이 인도 음식보다 순하다고 하는데, 이곳 사장은 네팔 출신이라 전체적으로 맛이 부드러운 편입니다.', 37.555547, 126.924967, '1만원대', '지하철 2호선/ 경의중앙선/ 공항철도 홍대입구역 9번 출구, 241m', '탄두리치킨, 치킨머라이카밥, 치킨세쿠와', '', ' https://blog.naver.com/shantifood/223293566337', '음식점', '', '월~금 11:30~15:30, 16:30~22:00\n주말 11:30~22:00', '02-6052-3989', ''),
	(540, '루나바인', '06040  서울 강남구 논현로149길 13 (예진빌딩)   1층', 'images/루나바인_540.jpg', '가볍게 즐길 수 있는 퓨전 한식으로, 모던 코리안 퀴진을 표방.\n\n가볍게 즐길 수 있는 퓨전 한식으로, 모던 코리안 퀴진을 표방하고 있습니다. 점심 세트 메뉴를 시키면 다양한 맛을 한번에 즐길 수 있습니다. 5가지 이상의 메인 요리와 디저트를 3가지 코스로 분류하여 저렴한 가격으로 여러 가지 음식을 맛볼 수 있습니다. 보쌈, 항정살 조림, 로스트비프, 메로구이 등의 한식을 현대적으로 해석합니다.', 37.518345, 127.027423, '', '지하철 7호선 학동역 7번 출구, 600m', '채끝등심 스테이크', '월요일~토요일', ' https://www.instagram.com/luna_vine_/', '음식점', '', '월요일~금요일 16:00~24:00, 토요일 17:00~23:00', '0507-1424-3381', '매주 일요일 휴무'),
	(541, '안성또순이', '03175  서울특별시 종로구 경희궁길 18 (신문로2가)', 'images/안성또순이_541.jpg', '생태찌개 전문점. 두부, 파, 미나리, 생태내장의 칼칼한 국물.\n\n생태찌개 전문점. 두부, 파, 미나리, 생태내장 등을 넣어 냄비 가득 끓여 나오는 칼칼한 국물 맛이 좋습니다. 그 밖에 제육보쌈, 삼합 등도 많이 찾는 인기 메뉴입니다.', 37.571684, 126.971594, '', '지하철 5호선 광화문역 1번 출구, 636m', '일반한식', '월요일~토요일', '', '음식점', '', '평일 11:00~15:00, 17:00~21:00 / 토요일 11:00~20:00', '0507-1483-5670', '매주 일요일, 명절 휴무'),
	(542, '열해', '04426  서울특별시 용산구 이촌로 248 (이촌동)', 'images/열해_542.jpg', '정통 사시미를 맛볼 수 있는 아담한 일식집.\n\n정통 사시미를 맛볼 수 있는 아담한 일식집입니다. 일반 횟집과 달리 활어가 아닌, 선어를 사용합니다. 일본풍의 단아하고 소박한 분위기가 특징입니다.', 37.519341, 126.975117, '', '지하철 4호선/ 경의중앙선 이촌역 3-1번 출구, 316m', '열해정식, 새우튀김정식, 모둠생선회, 덮밥류', '', '', '음식점', '', '11:30~15:00 / 17:30~22:00', '02-793-1188', '명절, 일요일 휴무'),
	(543, '장추 민물장어', '04554  서울 중구 수표로4길 7 (충무로3가)', 'images/장추_민물장어_543.jpg', '부담없는 가격의 민물장어 전문점.\n\n부담없는 가격의 민물장어 전문점. 영산강 하구의 구진포에서 장어를 공급받고 있습니다. 초벌구이를 해서 불판 위에 올려주기 때문에 먹기에도 편합니다. 정식에는 밥과 함께 뚝배기에 끓인 구수한 추어탕이 함께 나옵니다.', 37.562574, 126.990890, '', '지하철 3/4호선 충무로역 6번 출구, 311m', '장어구이, 장어정식, 장어덮밥', '월요일~금요일', '', '음식점', '', '평일 11:30 ~ 15:00, 17:00 ~ 21:00', '02-2274-8992', '매주 토요일, 일요일, 명절 휴무'),
	(544, '쉐플로', '06296  서울 강남구 논현로36길 29', 'images/쉐플로_544.jpg', '서래마을에서 프렌치 퓨전으로 이름을 알린 키친 플로에서 새로 오픈한 프렌치 선술집.\n\n서래마을에서 프렌치 퓨전으로 이름을 알린 키친 플로에서 새로 오픈한 프렌치 선술집. 프렌치 스타일의 음식과 더불어 일본 스타일의 음식도 만나볼 수 있습니다. 비교적 저렴한 분위기에서 가볍게 한잔하기에 좋은 곳입니다.', 37.485156, 127.044267, '', '지하철 3호선 매봉역 4번 출구, 289m', '다양한 올리브와 파르미지아노 레지아노, 동해산 피문어 카르파치오', '월요일~토요일', '', '술집, 바', '', '18:00~24:00', '02-574-7010', '매주 일요일'),
	(545, '포탈라', '03191  서울 종로구 청계천로 99 (관철동, 수표교빌딩)', 'images/포탈라_545.jpg', '티베트인이 만드는 티베트 음식을 전문으로 하는 곳.\n\n티베트인이 만드는 티베트 음식을 전문으로 하는 곳. 뚝바는 수제비 비슷한 면요리, 모모는 만두와 비슷한 음식입니다. 실내는 티베트 전통식으로 꾸몄습니다. 웹사이트에서 할인 쿠폰을 다운받을 수 있습니다.', 37.568401, 126.988658, '1만원대', '지하철 2/ 3호선 을지로3가역 2번 출구, 410m', '툭빠, 데룩, 탈라 누들, 덴툭, 초우만', '', ' https://blog.naver.com/potalawin', '음식점', '', '평일 11:00~15:00, 17:00~22:00 / 주말 11:00~22:00', '0507-1421-0094', ''),
	(546, '동경전통육개장', '06130  서울 강남구 테헤란로7길 22 (역삼동, 과학기술회관)', 'images/동경전통육개장_546.jpg', '강남 육개장으로 유명한 집. 얼큰한 맛이 일품.\n\n강남 부근에서 오랫동안 육개장으로 유명한 집입니다. 이 집의 육개장은 다른 육개장들에 비하여 고사리가 덜 들어가긴 하였지만 얼큰한 맛이 일품이어서 사람들이 많이 찾습니다. 기본 찬들도 깔끔하게 나와 육개장의 맛을 더해준다는 평입니다.', 37.500722, 127.030769, '', '지하철 2호선/ 신분당선 강남역 12번 출구, 348m', '전통육개장, 갈비육개장, 사골갈비탕', '매일', '', '음식점', '', '평일 09:00 ~ 15:00 / 17:00 ~ 21:00\n주말 09:30 ~ 15:00', '02-566-9779', '명절 당일 휴무'),
	(547, '송림원', '02833  서울 성북구 동소문로 25-2', 'images/송림원_547.jpg', '산동 출신 화교가 운영하는 곳. 허름하나 맛은 수준급.\n\n산동 출신 화교가 운영하는 곳으로, 허름하고 가격도 저렴하지만, 맛만은 수준급인 50년 전통의 중식당입니다. 7~80년대 서울식 중국 요리를 먹을 수 있습니다.', 37.589104, 127.007766, '1만원대', '지하철 4호선 한성대입구역 7번 출구, 219m', '짜장면, 간짜장, 쟁반짜장, 짬뽕', '', '', '음식점', '', '매일 11:30 ~ 15:30, 17:00 ~ 21:00 KST', '02-764-7970', '명절 휴무'),
	(548, '풍요람', '03739  서울특별시 서대문구 통일로 107-17 (미근동)', 'images/풍요람_548.jpg', '한자리에서 30년이 넘게 운영하고 있는 고깃집.\n\n한자리에서 30년이 넘게 운영하고 있는 고깃집. 원래 ‘서대문집’이었는데 풍요람으로 상호 명을 바꾸었습니다. 흔히 등심집이라고도 불리는 곳으로, 소 등심, 돼지갈비 등이 전문입니다. 소 등심을 시키면 깍두기 모양으로 썬 등심에 맛보기 차돌박이를 3~4점 섞어 내놓습니다. 고기를 먹고 나면 철판에 볶아 주는 밥맛이 고소하며 양이 넉넉합니다.', 37.564363, 126.967153, '', '지하철 5호선 서대문역 7번 출구, 170m', '', '월요일~금요일', '', '음식점', '', '11:30 ~ 14:30 / 17:00 ~ 22:00', '02-362-4203', '매주 토요일, 일요일 휴무'),
	(549, '오아시스', '06014  서울특별시 강남구 도산대로55길 20 (청담동)', 'images/오아시스_549.jpg', '호주식 브런치를 전문으로 하는 카페. 오믈렛, 에그 베네딕트\n\n호주식 브런치를 전문으로 하는 카페. 오믈렛, 에그 베네딕트 등이 인기 메뉴입니다. 이태원에서 이미 브런치로 인기를 끌었던 더 프라잉팬에서 오픈한 곳입니다.', 37.524777, 127.040604, '', '지하철 수인분당선 압구정로데오역 4번 출구, 247m', '머쉬룸 크림 파스타, 햄 치즈 토마토 오믈렛, 에그베네딕트햄', '', ' http://www.instagram.com/oasisbrunch', '음식점', '', '09:00~18:00', '02-548-8859', ''),
	(550, '송죽', '04554  서울 중구 수표로6길 31 1층', 'images/송죽_550.jpg', '참기름에 볶은 멥쌀을 푹 삶은 사골 국물에 넣고 끓여 만든 죽.\n\n참기름에 볶은 멥쌀을 푹 삶은 사골 국물에 넣고 끓여 만듭니다. 버섯굴죽을 비롯해 전복 내장까지 함께 끓이는 전복죽 등이 인기 있습니다.', 37.563042, 126.992028, '1만원대', '지하철 3/4호선 충무로역 6번 출구, 220m', '죽', '월화수목금토일', '', '음식점', '', '평일 07:00~19:00, 주말 07:00~13:00', '0507-1309-5129', '명절 휴무'),
	(551, '외고집설렁탕', '06155  서울 강남구 삼성로 555 (삼성동)', 'images/외고집설렁탕_551.jpg', '강남에서 유명한 설렁탕집. 횡성 한우와 국산재료 사용.\n\n강남에서 유명한 설렁탕집. 횡성 한우를 사용한 설렁탕과 국산재료(배추, 무, 고춧가루, 천일염)를 사용하여 다른 설렁탕집과 차별화시키고 있습니다. 미쉐린 가이드 서울2025에 선정되었습니다.', 37.511016, 127.053901, '1만원대', '지하철 9호선 삼성중앙역 6번 출구, 191m', '한식(설렁탕,수육)', '월요일~토요일', ' https://oegojip.modoo.at/', '음식점', '', '11:00 ~ 21:00', '02-567-5225', '매주 일요일, 명절 휴무'),
	(552, '설담재설렁탕', '01426  서울 도봉구 도봉로 562 (창동)', 'images/설담재설렁탕_552.jpg', '진한 사골국물에 갓 지은 밥과 칼칼한 김치의 조합. 3대를 이어온 설렁탕 맛집.\n\n뜨끈한 국물이 간절히 생각나는 날, 설담재의 설렁탕 한 그릇은 오가는 이의 마음을 훈훈하게 해줍니다. 진한 사골국물에 갓 지은 밥을 말아 칼칼한 김치를 곁들여 먹노라면 국물 한 방울 남김 없이 어느새 뚝딱! 친절한 서비스와 주인장의 넉넉한 인심이 정겹습니다.', 37.654843, 127.039125, '1만원대', '지하철 1/4호선 창동역 2번 출구, 847m', '설렁탕, 갈비탕, 도가니탕', '', ' http://www.suldamjae.com/ ', '음식점', '', '08:30 ~ 21:50 (라스트오더 21:20)', '02-998-0202', '명절 휴무'),
	(553, '한스케익', '06031  서울 강남구 논현로167길 21 (신사동)', 'images/한스케익_553.jpg', '모양과 맛이 뛰어나 인지도를 높이고 있는 한국형 케이크 전문점. 독창적이고 심플한 디자인으로 고급 제품을 대중적으로 어필. 품격에 맞는 맞춤형 케이크도 주문 가능. 진한 치즈 향이 돋보이는 치즈케이크와 무스케이크가 주력 상품.\n\n모양과 맛이 뛰어나 인지도를 높이고 있는 한국형 케이크 전문점. 독창적이고 심플한 디자인으로 고급 제품을 대중적으로 어필하고 있습니다. 품격에 맞는 맞춤형 케이크도 주문 가능합니다. 진한 치즈 향이 돋보이는 치즈케이크와 무스케이크가 주력 상품입니다.', 37.524541, 127.026298, '3만원대', '지하철 3호선 압구정역 4번 출구, 315m', '베이커리', '매일', ' http://www.hanscake.co.kr/', '카페, 디저트', '', '월요일~토요일 09:30 ~ 22:00\n일요일 09:30 ~ 21:00', '02-515-4677', ''),
	(554, '웨스턴차이나', '04419  서울 용산구 독서당로 73 (한남동, 성아맨숀)', 'images/웨스턴차이나_554.jpg', '정통 딤섬을 맛볼 수 있는 곳으로 중식요리와 여러 종류의 딤섬이 주메뉴\n\n정통 딤섬을 맛볼 수 있는 곳. 세트메뉴는 중식요리와 여러 종류의 딤섬을 즐기기 좋습니다. 단품도 비교적 저렴해 푸짐하게 먹을 수 있습니다. 또 채소, 과일 샐러드는 무제한으로 제공합니다.', 37.534216, 127.008422, '1만원대', '지하철 경의중앙선 한남역 1번 출구, 663m', '깐풍기, 찹쌀탕수육, 새우수정딤섬, 소룡포', '', '', '음식점', '', '매일 11:30 ~ 23:30', '02-795-3654', '연중무휴'),
	(555, '목포집', '03131  서울 종로구 삼일대로32길 55-4 (운니동)', 'images/목포집_555.jpg', '홍어회, 홍어찜, 떡갈비, 낙지요리, 연포탕, 가정식 백반 등 남도음식 전문점.\n\n홍어회, 홍어찜, 떡갈비, 낙지요리, 연포탕, 가정식 백반 등 남도음식 전문점으로, 목포 지방의 맛을 잘 재현하고 있다는 평가를 받고 있습니다.', 37.575846, 126.989930, '', '지하철 1/ 3/ 5호선 종로3가역 6번 출구, 393m', '삼합\n홍어회\n홍어튀김', '월화수목금토', '', '음식점', '', '월~금 10:00~15:00, 17:00~22:00 / 토요일 10:00~20:00', '02-722-0976', '매주 일요일, 공휴일, 명절 휴무'),
	(556, '스타쉐프', '06296  서울특별시 강남구 논현로38길 38-6 (도곡동)', 'images/스타쉐프_556.jpg', '신라호텔 출신 오너 셰프의 맛깔스러운 퓨전음식.\n\n신라호텔 출신 오너 셰프가 맛깔스러운 퓨전음식을 냅니다. 테이블이 12개밖에 없어 예약하고 가는 것이 좋습니다. 최상급 소고기를 사용한 등심스테이크샐러드와 소고기탕수육이 인기 메뉴입니다. 저녁 늦게까지 술 마시기에 좋은 분위기여서 2차 장소로도 많이 이용됩니다.', 37.485237, 127.044883, '3만원대', '지하철 3호선 매봉역 4번 출구 3호선 매봉역 4번 출구, 217m', '지중해식문어요리, 놀라운농어요리, 버섯크림요리와 빵, 키조개관자샐러드', '', '', '음식점', '', '월요일~토요일 17:00~24:00', '02-529-8248', '매주 일요일, 명절 휴무'),
	(557, '비양도', '02838  서울 성북구 성북로 158 (성북동)', 'images/비양도_557.jpg', '생선회 정식코스와 제주도 토속 음식을 전문으로 하는 곳.\n\n생선회 정식코스와 제주도 토속 음식을 전문으로 하는 곳입니다. 토종 제주도산 흑돼지의 오겹살을 한방 재료와 함께 솔잎에 쪄 만든 돔베고기가 독특한 메뉴입니다. 정원에서 식사하는 것도 분위기가 있습니다.', 37.594564, 126.992306, '', '지하철 4호선 한성대입구역 5번 출구, 1600m', '런치코스, 주말정식, 식사메뉴', '', '', '음식점', '', '매일 11:30 ~ 15:00 / 17:00 ~ 22:00', '0507-1397-1588', '연중무휴'),
	(558, '트라토리아모로', '06154  서울특별시 강남구 봉은사로68길 21 (삼성동)', 'images/트라토리아모로_558.jpg', '그안의 셰프가 독립한 곳. 파스타 등 다양한 종류의 메인 요리 준비\n\n그안의 셰프가 독립한 곳. 파스타 맛이 좋으며, 다양한 종류의 메인 요리도 준비되어 있습니다.', 37.510743, 127.050820, '', '지하철 9호선 삼성중앙역 7번 출구, 452m', '해물스파게티, 크림소스리조또, 시저샐러드', '', '', '음식점', '', '11:30~15:00, 17:30~22:00', '02-556-6997', '매주 일요일'),
	(559, '프레스카 29', '06301  서울 강남구 논현로28길 29 (토펙빌딩)', 'images/프레스카_29_559.jpg', '도곡동 일대에서 커피 맛이 좋기로 유명한 카페. 테라스와 오픈된 공간. 직접 원두를 로스팅해서 사용& 커피 강좌.\n\n도곡동 일대에서 커피 맛이 좋기로 유명한 카페입니다. 테라스와 오픈된 공간이 시원하게 느껴집니다. 직접 원두를 로스팅해서 사용하며 커피 강좌도 열리고 있습니다.', 37.483889, 127.044459, '1만원대', '지하철 3호선 매봉역 4번 출구, 416m', '카페', '', '', '카페, 디저트', '', '매일 08:00 ~ 18:00', '0507-1414-2558', '연중무휴'),
	(560, '차만다 서울숲점', '04768  서울 성동구 서울숲2길 28-12 (성수동1가)', 'images/차만다_서울숲점_560.jpg', '영국 가정식을 전문으로 하는 서울숲에 위치한 차만다 레스토랑\n\n서울숲에 위치한 차만다 레스토랑은 영국 가정식을 전문으로 하는 곳입니다. 영국 미슐렝 레스토랑 출신 셰프가 운영하며 치킨 티카 마살라, 피쉬 & 칩스, 셰퍼드파이 등 다양하고 맛있는 영국 음식들을 맛볼 수 있습니다. 아늑하고 따듯한 분위기의 인테리어와 서울숲이 보이는 창이 있어 분위기 좋은 데이트 장소로 사랑받고 있는 곳입니다. 사계절 언제 방문해도 아름다운 차만다 레스토랑에서 신선하고 맛있는 영국 가정식에 빠져보세요.', 37.546625, 127.041406, '', '지하철 수인분당선 서울숲역 5번 출구, 500m', '셰퍼드파이 24,000원\n피쉬&칩스 32,000원', '매일', ' https://www.instagram.com/charmandre_official/', '음식점', '', '평일 11:30 ~ 21:30 (Break Time 15:00 ~ 17:30)\n주말 12:00 ~ 21:30 (Break Time 15:00 ~ 17:00)\n공휴일 12:00 ~ 21:30 (Break Time 15:00 ~ 17:00)', '02-6448-0812', ''),
	(561, '맘마키키', '06577  서울 서초구 서래로10길 9 (반포동, 서래)', 'images/맘마키키_561.jpg', '편안한 분위기에서 와인을 즐길 수 있는 와인 선술집.\n\n편안한 분위기에서 와인을 즐길 수 있는 와인 선술집. 기본 안주로 삶은 계란이 나오며 삼겹살, 연어 등 퓨전 안주가 일품입니다. 3만~4만원대 와인을 많이 갖추고 있습니다. 추천 안주는 와사비소스 삼겹살. 저녁때는 자리가 꽉 차는데 예약도 받지 않습니다.', 37.499539, 126.998876, '', '지하철 3 / 7 / 9호선 고속터미널역 5번 출구, 620m', '치즈모둠, 카프레제, 펜네 파스타', '', '', '술집, 바', '', '매일 18:00 ~ 01:00', '02-537-7912', '매주 일요일, 명절'),
	(562, '서울 커피 익선점', '03133  서울 종로구 수표로28길 33-3 (익선동)', 'images/서울_커피_익선점_562.jpg', '현재와 과거가 공존하는 서울에서 가장 오래된 한옥마을에 위치한 서울커피 익선점\n\n현재와 과거가 공존하는 서울에서 가장 오래된 한옥마을에 위치한 서울커피 익선점은 옛 기억을 떠올릴 수 있는 다양한 메뉴와 한국적이고 편안한 분위기의 카페입니다. 비엔나커피와 밀크티, 단호박 식혜, 인절미티라미슈, 초코꽈배기 등 재해석된 한국적인 메뉴와 특이한 조합의 메뉴들로 많은 사람들의 사랑을 받고 있습니다.', 37.573280, 126.990121, '', '지하철1/3/5 호선 종로 3가역 4번 출구, 150m', '앙버터식빵 4,500원\n비엔나 밀크티 7,000원', '', ' https://www.instagram.com/seoulcoffee1945/', '카페, 디저트', '', '매일 11:00 ~ 22:00 (21:30 주문 마감)', '0507-1404-4890', '연중무휴 (설날/ 추석 당일 늦은 오후 오픈)'),
	(563, '오수흑두부', '03148  서울 종로구 인사동8길 12-2 (관훈동)', 'images/오수흑두부_563.jpg', '검정깨와 콩을 이용해 손수 만든 건강식 두부를 이용한 요리.\n\n검정깨와 콩을 이용해 손수 만든 건강식 두부를 이용한 요리가 주종을 이룹니다. 따끈한 돌솥밥에 돼지고기 수육과 흑두부를 얹어 김과 배춧잎에 싸 먹는 흑두부보쌈 맛이 일품입니다.', 37.573934, 126.986101, '', '지하철 3호선 안국역 5번 출구, 370m', '흑두부 보쌈, 오수한정식', '', '', '음식점', '', '매일 12:00 ~ 22:00', '02-735-5255', '명절 휴무'),
	(564, '도이치하우스', '04402  서울 용산구 대사관로 46 (한남동, 서울빌딩)', 'images/도이치하우스_564.jpg', '독일 풍의 소시지 요리, 아이스바인(족발), 코돈브로(돈가스)와 함께 흑맥주를 비롯한 다양한 유럽 맥주가 있는 곳.\n\n독일 생맥주집으로, 독일풍의 소시지 요리, 아이스바인(족발), 코돈브로(돈가스)와 함께 흑맥주를 비롯한 다양한 유럽 맥주를 부담 없이 즐길 수 있습니다. 독일에서 직수입한 브라드버스터, 그릴 소시지, 포크 소시지, 후레시 소시지, 화이트 소시지 등이 다양하게 갖추어져 있습니다. 독일 분위기를 느끼고 싶어 하는 외국인들도 많이 찾는 곳입니다.', 37.533306, 127.003049, '', '지하철 6호선 이태원역 3번 출구, 854m', '예딩거 둔켈, 신데렐라, 모둠소시지, 안심찹스테이크', '', '', '술집, 바', '', '매일 11:30 ~ 02:00', '02-794-1313', '연중무휴'),
	(565, '야마모토스시', '06294  서울 강남구 언주로30길 26 (타워팰리스)  상가 1층', 'images/야마모토스시_565.jpg', '경력 40년 스시 명인 야마모토 스다오 씨가 만드는 정통 스시.\n\n경력 40년을 자랑하는 스시의 명인 야마모토 스다오 씨가 만드는 정통 스시를 맛볼 수 있는 곳입니다. 한때는 서울 시내 최고의 스시라고도 불렸습니다. 매일 혼마구로 최고의 부위를 선별해서 따로 숙성시키며, 오도로를 잘게 저민 후 실파와 김을 얹어서 생 와사비와 함께 먹는 네기도로 등이 이곳이 자랑하는 메뉴입니다.', 37.487763, 127.052530, '', '지하철 3호선/ 수인분당선 도곡역 4번 출구, 587m', '스시정식, 사시미정식, 야마모토코스', '', '', '음식점', '', '매일 11:30 ~ 15:00 / 17:30 ~ 21:00', '0507-1422-0362', '명절 휴무'),
	(566, '길손', '06030  서울특별시 강남구 논현로175길 40 (신사동)', 'images/길손_566.jpg', '압구정동에서 오랫동안 자리를 지키는 로바다야키. 닭날개, 가이바시라 등의 꼬치구이, 야키 오니기리.\n\n압구정동에서 오랫동안 자리를 지키는 로바다야키. 닭날개, 가이바시라 등의 꼬치구이와 술 한잔하기에 좋습니다. 야키 오니기리도 이 집에서 인기 있는 메뉴입니다.', 37.525073, 127.025318, '', '지하철 3호선 압구정역 4번 출구, 286m', '닭날개꼬치, 모둠꼬치', '', '', '술집, 바', '', '매일 18:00 ~ 01:00', '02-546-1247', '첫째, 셋째 주 일요일 , 명절 휴무'),
	(567, '신계치', '03776  서울특별시 서대문구 명물길 47 (창천동)', 'images/신계치_567.jpg', '25년이 넘는 한국식 인스턴트 라면전문점. 특허 받은 신계치라면(신라면+계란+치즈(치즈라면)).\n\n생긴 지 25년이 넘는 라면전문점. 일본식 라멘이 아니라 한국식 인스턴트 라면을 전문으로 합니다. 특허까지 받은 신계치라면(신라면+계란+치즈(치즈라면))이 인기가 있습니다.', 37.558866, 126.938781, '1만원대', '지하철 경의중앙선 신촌역 1번 출구, 393m', '라면', '월요일~금요일', '', '음식점', '', '11:00 ~ 22:00', '02-3147-1021', '주말'),
	(568, '참나무숯불에닭이만나는순간(희래)', '06786  서울특별시 서초구 동산로6길 37 (양재동)', 'images/참나무숯불에닭이만나는순간(희래)_568.jpg', '철판에 볶아먹는 닭갈비가 아니라가 숯불에 직접 구워 먹는 방식.\n\n철판에 볶아먹는 닭갈비가 아니라 숯불에 직접 구워 먹는 방식입니다. 마늘, 고춧가루, 생강, 설탕, 간장 등 10여 가지의 재료가 들어간 소스에 닭갈비를 3일간 재워 숙성시킨 후 주문이 들어오면 바로 구워주는데 육질이 부드럽고 고소합니다. 쟁반막국수, 춘천막국수, 닭칼국수, 닭막국수 등의 메뉴도 있습니다.', 37.469672, 127.044667, '', '지하철 신분당선 양재시민의 숲역(매헌) 3번 출구, 154m', '닭갈비', '화요일~일요일', '', '음식점', '', '15:00 ~ 24:00', '0507-1443-6616', '월요일, 명절 휴무'),
	(569, '별난오리', '03119  서울 종로구 종로46길 12 (창신동)  2층', 'images/별난오리_569.jpg', '별난오리는 동대문에 위치한 오리요리 전문점.\n\n별난오리는 동대문에 위치한 오리요리 전문점입니다. 메뉴로는 전기훈제오리구이, 별난오리탕 두 가지가 있으며, 각각 반마리씩 섞어서 주문하는 것도 가능합니다. 마지막으로는 볶음밥도 먹을 수 있습니다.', 37.571065, 127.010600, '', '지하철 1/4호선 동대문역 7번 출구, 77m', '오리구이, 별난오리탕, 전기훈제오리구이', '토요일 11:00~21:00', ' http://instagram.com/ddmspecialduck', '음식점', '', '월요일~금요일 11:00~22:00\n브레이크타임 15:00~17:00', '-5977', '일요일, 명절 휴무'),
	(570, '연지얼큰한동태국', '03129  서울특별시 종로구 종로31길 8-1 (종로5가)', 'images/연지얼큰한동태국_570.jpg', '무, 파, 콩나물에다 곤이와 내장을 듬뿍 넣고 끓여 시원한 동태탕.\n\n무, 파, 콩나물에다 곤이와 내장을 듬뿍 넣고 끓여 시원합니다. 동태국은 솥에 끓여 놓았다 한 그릇씩 떠주며, 저녁때 술 손님에게 내놓는 동태찌개는 즉석에서 끓여줍니다. 곤이, 애, 내장은 추가 주문이 가능하며 곤이 내장국도 맛볼 수 있습니다. 점심때는 일찌감치 가서 줄을 서야 먹을 수 있습니다.', 37.571500, 127.000262, '1만원대', '지하철 1호선 종로5가역 1번 출구, 182m', '한식(동태국)', '월요일~토요일', '', '음식점', '', '11:00 ~ 22:00', '02-763-9397', '매주 일요일, 명절 당일 휴무'),
	(571, '갤러리소연카페', '03134  서울 종로구 서순라길 149 (권농동)  1층', 'images/갤러리소연카페_571.jpg', '종묘 서쪽의 순라길인 서순라길의 돌담길에 위치한 운치 있는 카페\n\n종묘 서쪽의 순라길인 서순라길의 돌담길을 따라 걷다 보면 갤러리소연카페를 만날 수 있습니다. 따듯한 티와 음료, 음식을 같이 즐길 수 있는 곳이며, 주얼리와 금속공예 작품들을 구경할 수 있는 작은 전시장도 마련되어 있습니다. 잘 가꾸어진 화단과 운치 있는 분위기의 카페는 작은 자연에서 만나는 공방 작가들의 작품들을 보며 조용한 시간을 갖기에 좋은 장소입니다.', 37.576834, 126.991586, '1만원대', '지하철1/3/5 호선 종로 3가역 7번 출구, 527m', '소연팥빙수 15,000원\n소연자몽실론티 6,500원\n소연단팥죽(계절메뉴) 8,000원\n아메리카노 5,000원', '', '', '카페, 디저트', '', '평일 10:00 ~ 22:00\n토요일 11:00 ~ 22:00\n일요일 11:00 ~ 18:00', '0507-1347-2498', ''),
	(572, '감꽃당', '03133  서울 종로구 돈화문로11다길 38 (익선동)  감꽃당', 'images/감꽃당_572.jpg', '카페 감꽃당은 한옥의 아름다움과 오래된 감나무를 살리는 인테리어로 많은 사랑을 받음. 대표메뉴: 애플파이, 발효버터를 사용한 스콘, 에그타르트\n\n카페 감꽃당은 한옥의 아름다움과 오래된 감나무를 살리는 인테리어로 많은 사랑을 받고 있습니다. \n\n대표메뉴로 애플파이, 발효버터를 사용한 스콘, 에그타르트 등이 있습니다.', 37.573803, 126.990131, '', '지하철1/3/5호선 종로3가역 4번 출구, 209m', '에그타르트 4,500원', '매일', '', '카페, 디저트', '', '10:30 ~ 22:00', '02-747-3999', ''),
	(573, '현대칼국수', '04526  서울 중구 세종대로 76 (청남빌딩)', 'images/현대칼국수_573.jpg', '점심 시간에 길게 줄을 서야만 먹을 수 있는 칼국수 맛집.\n\n점심 시간에 길게 줄을 서야만 먹을 수 있는 칼국수 맛집. 멸치를 기본으로 다시마, 마른 새우, 북어 등 7가지 재료로 만드는 육수는 시원하면서 개운합니다. 국수사리와 공깃밥은 무제한으로 제공됩니다. 여름에는 콩국수도 좋습니다.', 37.562895, 126.976871, '1만원대', '지하철 1/2호선 시청역 7번 출구, 180m', '칼국수, 섞어칼국수, 물만두, 현대 콩국수', '월요일~토요일', '', '음식점', '', '평일 09:00~21:00\n토요일 09:00~19:00', '02-752-9504', '매주 일요일, 공휴일, 명절 휴무'),
	(574, '서글렁탕', '07343  서울 영등포구 여의대방로 394 (여의도동, 우정빌딩)', 'images/서글렁탕_574.jpg', '여의도에서 20여 년이 훨씬 넘게 인기를 누려 온 숯불 소스 삼겹살 구이점.\n\n여의도에서 20여 년이 훨씬 넘게 인기를 누려 온 숯불 소스 삼겹살 구이점. 한약재를 넣은 간장 양념에 재워서 숯불에 구워 먹는 삼겹살은 돼지 냄새가 나지 않고 독특한 맛이 납니다. 소 잡뼈를 우려낸 국물에 선지, 우거지, 시래기, 콩나물을 넣어 끓인 해장국도 인기가 좋습니다. 저녁에는 자리 잡기 어려울 정도로 분주합니다.', 37.519370, 126.932749, '1만원대', '지하철 9호선/ 신림선 샛강역 3번 출구, 385m', '삼겹살', '', '', '음식점', '', '매일 12:00~15:00, 17:00~22:00', '02-780-8858', '명절 휴무'),
	(575, '고향집', '06061  서울 강남구 언주로134길 17 1층', 'images/고향집_575.jpg', '20년 내력의 소박한 청국장 집. 보쌈, 청국장, 제육 등 노포 분위기의 동네 맛집.\n\n20년 내력의 소박한 집으로, 청국장, 보쌈, 황태요리, 칼국수, 만둣국이 인기 메뉴로 손꼽히고 있습니다. 육수 비법이 특별나거나 화려한 고명 같은 꾸밈은 없지만, 집에서 먹는 듯한 칼국수 맛이 좋습니다.', 37.516935, 127.037015, '', '지하철 7호선/ 수인분당선 강남구청역 3번 출구, 382m', '일반한식', '월요일~토요일', '', '음식점', '', '월요일~금요일 11:00~14:30, 17:00~22:00 / 토요일 11:00~15:00', '02-543-6363', '매주 일요일 휴무'),
	(576, '예빈당', '04782  서울 성동구 성수이로 87 (성수동2가, 성문빌딩)  1층', 'images/예빈당_576.jpg', '예빈당은 성수동에 위치한 한국 전통 디저트 카페.\n\n예빈당은 성수동에 위치한 한국 전통 디저트 카페입니다. 궁중에서 내려오는 우리나라 전래떡인 두텁떡, 꽃송편, 설기가 유명합니다.', 37.542731, 127.056212, '1만원대', '지하철 2호선 성수역 3번 출구, 172m', '두텁떡, 꽃송편, 설기,흑임자조각케이크,', '매일', ' https://www.instagram.com/yebindang_cafe', '카페, 디저트', '', '평일 8:00 - 21:30\n토, 일요일 09:00 - 21:30', '02-3443-5542', ''),
	(577, '장수식당', '05566  서울특별시 송파구 삼전로 95 (잠실동)', 'images/장수식당_577.jpg', '김치삼겹살, 부대찌개가 인기가 좋은 곳.\n\n김치삼겹살이 인기가 좋은 곳. 김치삼겹살을 시키면 가운데에 김치를 놓고 삼겹살이 빙 둘러서 나옵니다. 불판에 김치와 함께 삼겹살을 익히다가 깻잎과 파, 양념 등을 넣고 볶아서 먹는 맛이 별미입니다. 고기를 다 먹은 후에는 밥을 볶아 먹기도 합니다.', 37.507036, 127.089907, '', '지하철 9호선 삼전역 1번 출구, 357m', '돼지고기구이\n김치삼겹(1만2천원),두루치기(1만2천원), 오삼불고기(1만2천원), 볶음밥(2천원)', '월요일~토요일', '', '음식점', '', '11:00 ~ 15:00 / 17:00 ~21:50', '02-415-4148', '일요일, 공휴일, 명절 휴무'),
	(578, '구마산', '07333  서울특별시 영등포구 국제금융로 70 (여의도동)', 'images/구마산_578.jpg', '여의도에서 오랜 기간 유명세를 치르고 있는 추어탕 및 소갈비 전문점.\n\n여의도에서 오랜 기간 유명세를 치르고 있는 추어탕 및 소갈비 전문점. 주방에서 구워져서 나오는 갈비가 다소 달게 느껴질수 있습니다.', 37.521407, 126.930602, '', '지하철 9호선/ 신림선 샛강역 2번 출구, 544m', '소갈비', '월요일~토요일', '', '음식점', '', '11:30 ~ 15:00 / 17:00 ~ 21:00', '02-782-3269', '매주 일요일, 명절 휴무'),
	(579, '다락정', '03049  서울 종로구 삼청로 131-1', 'images/다락정_579.jpg', '된장국물에 끓인 만두전골을 맛볼 수 있는 집.\n\n된장국물에 끓인 만두전골을 맛볼 수 있는 집. 된장에 해물, 만두가 푸짐하게 들어갑니다. 구수하면서도 시원한 맛이 특징입니다. 그밖에 만둣국, 전, 불고기 등을 맛볼 수 있습니다. 좌식, 테이블식 모두 마련되어 있습니다.', 37.587255, 126.981518, '1만원대', '지하철 안국역 1번 출구, 1500m', '김치만두전골, 토장만두전골, 만두국, 비지정식', '', '', '음식점', '', '매일 11:00~21:30', '02-725-1697', '명절 휴무'),
	(580, '남미플랜트랩', '06677  서울 서초구 방배천로4안길 55 (방배동, 일신빌딩)  2층', 'images/남미플랜트랩_580.jpg', '남미플랜트랩은 콜롬비아 출신 주인이 운영하는 100% 비건 음식점\n\n남미플랜트랩은 콜롬비아 출신 주인이 운영하는 100% 비건 음식점입니다. 싱싱한 재료들로 건강한 맛을 낸다. 다양한 야채 요리를 선보이며, 치즈 야채 피자와 스피니치 크림 라자냐 같은 이탈리안 메뉴가 특히 맛있습니다. 이 메뉴를 맛보려고 멀리서 찾아오는 손님들도 많을 만큼, 맛이 보장된 곳입니다. 또한 반려동물과 함께할 수 있어, 반려동물과의 여행 중에도 편안하게 방문할 수 있다. 채식의 매력을 직접 느껴보고 싶다면 방문을 추천합니다.', 37.480609, 126.983230, '', '지하철 2/4호선 사당역 11번 출구, 378m', '치즈야채 피자 17,000원\n파스타베르데 15,000원', '매일', ' http://instagram.com/nammiplantlab', '음식점', '', '12:00 ~ 16:00 / 17:30 ~ 21:00', '02-522-1276', ''),
	(581, '명동곰돌이', '06604  서울특별시 서초구 서초대로55길 11 (서초동)', 'images/명동곰돌이_581.png', '20여 년을 명동에서 영업하다가 서초동에 재오픈한 참국수와 치킨.\n\n20여 년을 명동에서 영업하다가 2000년 문을 닫고 서초동에 재오픈한 곳. 진한 멸치 국물에 샤브샤브용 고기와 쑥갓이 들어간 국수 맛이 좋습니다. 치킨과 국수의 독특한 조합이 입맛을 당깁니다.', 37.495634, 127.015372, '', '지하철 2/3호선 교대역 4번 출구, 202m', '참국수, 참모밀국수, 치킨소스, 국수전골', '', '', '음식점', '', '매일 11:30~14:30, 17:00~20:00', '02-594-3989', '명절 휴무'),
	(582, '하코야 역삼세무서점', '06227  서울 강남구 논현로72길 16 (역삼동, 초원빌딩)', 'images/하코야_역삼세무서점_582.jpg', '다양한 종류의 일식 라멘, 우동, 소바 등을 전문으로 하는 곳.\n\n다양한 종류의 일식 라멘, 우동, 소바 등을 전문으로 하는 곳입니다. 하카다식 돈코쓰 라멘, 홋카이도식 쇼유라멘 등 일본 각 지역 고유의 라멘을 선보이고 있습니다. 면은 일본에서 생산된 것을 직수입하여 사용하고 있습니다.', 37.495662, 127.040910, '1만원대', '지하철 2호선 역삼역 1번 출구, 737m', '냉소바, 뼈감자탕라멘, 하코야탄탄멘, 매콤소보루라멘', '', '', '음식점', '', '11:00 ~15:00, 17:00~ 22:00', '02-554-5580', '토요일,일요일'),
	(583, '저스트스테이크', '06021  서울 강남구 언주로152길 11-7 (신사동)', 'images/저스트스테이크_583.jpg', '한우로 만든 드라이 에이징 스테이크를 전문으로 하는 곳.\n\n한우로 만든 드라이 에이징 스테이크를 전문으로 하는 곳. 거품을 쫙 뺀 가격이 눈에 들어옵니다. 스테이크와 곁들이는 와인도 합리적인 가격으로 매칭해서 즐길 수 있습니다.', 37.523149, 127.034393, '', '지하철 3호선 압구정역 3번 출구, 820m', '티본스테이크, 그릴에 구운 야채, 볼로네제', '', '', '음식점', '', '매일 11:30 ~ 22:00 (Last Order 21:00)', '02-544-9357', '매주 월요일'),
	(584, '희락', '04528  서울특별시 중구 남대문시장길 22-6 (남창동)', 'images/희락_584.jpg', '찌그러진 양은냄비 집으로 유명한 남대문 갈치조림 집.\n\n찌그러진 양은냄비 집으로 유명한 갈치조림 집. 냄비에 듬성듬성 썬 무를 바닥에 깔고 물과 양념장, 갈치를 넣고 끓였다가 조금 후에 이를 다시 한 번 끓여서 반쯤 졸입니다. 그리고 주문이 들어오면 완전히 익혀서 서빙합니다. 씨를 빼 직접 빻아서 쓰는 고춧가루도 이 집의 자랑거리입니다. 밥은 무한정 리필됩니다. 남대문시장 갈치골목의 원조집입니다.', 37.559903, 126.977077, '', '지하철 4호선 회현역 6번 출구, 294m', '갈치조림', '월요일~토요일', '', '음식점', '', '07:00 ~ 21:00', '02-755-3449', '매주 일요일, 명절 휴무'),
	(585, '부원면옥', '04529  서울 중구 남대문시장4길 41-6 (남창동)', 'images/부원면옥_585.jpg', '남대문 시장 내에서 50여 년간 자리를 지켜온 평양냉면 집.\n\n남대문 시장 내에서 50여 년간 자리를 지켜온 평양냉면 집. 이북 출신이 많이 찾는 곳입니다. 닭무침과 빈대떡도 인기 메뉴입니다.', 37.558438, 126.977607, '1만원대', '지하철 4호선 회현역 5번 출구, 64m', '냉면', '월화수목금토', '', '음식점', '', '월~토 11:00 ~ 20:00', '02-753-7728', '매주 일요일'),
	(586, '평양집', '04382  서울특별시 용산구 한강대로 186 (한강로1가)', 'images/평양집_586.jpg', '숯불에 굵은 철근으로 된 석쇠를 올리고 구워 먹는 차돌박이가 인기 메뉴.\n\n숯불에 굵은 철근으로 된 석쇠를 올리고 구워 먹는 차돌박이가 인기 메뉴입니다. 고기를 찍어 먹는 새콤 달콤한 양념장이 맛이 좋으며 양곱창도 인기. 밑반찬은 양배추와 생마늘 뿐입니다. 식사 메뉴도 양을 썰어 넣고 깍두기와 볶는 양밥 뿐이지만 맛은 일품입니다. 새벽에 문을 열며 내장탕을 아침으로 먹을 수 있습니다.', 37.534833, 126.973983, '2만원대', '지하철 4/6호선 삼각지역 14번 출구, 36m', '양곱창', '화요일~일요일', '', '음식점', '', '07:00 ~ 22:00', '02-793-6866', '매주 월요일, 명절 휴무'),
	(587, '연희동칼국수', '03703  서울 서대문구 연희맛로 37', 'images/연희동칼국수_587.jpg', '한여름에도 칼국수만을 고집하는 곳. 열두 시간 우려낸 사골 국물의 칼국수.\n\n한여름에도 칼국수만을 고집하는 곳. 열두 시간 우려낸 사골 국물의 칼국수입니다. 그 외에 수육도 같이 먹어볼 만합니다. 담백한 맛을 좋아하는 사람들에게 추천할 만합니다.', 37.568194, 126.930777, '1만원대', '지하철 2호선/경의중앙선/공항철도 홍대입구역 3번 출구, 1.3km', '칼국수, 수육', '', '', '음식점', '', '화요일~일요일 11:00~20:30', '02-333-3955', '월요일, 명절 휴무'),
	(588, '평양면옥', '04615  서울특별시 중구 장충단로 207 (장충동1가)', 'images/평양면옥_588.jpg', '3대째 전통을 이어오는 냉면집. 어복쟁반도 인기 메뉴.\n\n3대째 전통을 이어오는 냉면집. 간이 심심하면서도 깊은 맛을 느낄 수 있습니다. 쇠고기 편육을 놋쟁반에 담아 여럿이 먹기 좋은 어복쟁반도 인기 메뉴입니다. 미쉐린 가이드 서울 2025에 선정되었습니다.', 37.563030, 127.006470, '', '지하철 2/ 4/ 5호선 동대문역사문화공원역 5번 출구, 184m', '편육, 제육, 냉면', '', ' https://pyungyangmyunok.modoo.at/', '음식점', '', '매일 11:00 ~ 21:30', '02-2267-7784', '연중무휴'),
	(589, '목로', '06030  서울 강남구 압구정로28길 18 (신사동)', 'images/목로_589.jpg', '평양만두 전문점. 맑고 시원한 국물과 커다람 만두.\n\n양식 만두 전문점. 만둣국을 시키면 양지로 만든 맑은 육수에 잘게 찢어 양념한 양지가 고명으로 올라간 큼직한 평양만두가 담아져 나옵니다. 국물이 맑고 시원합니다. 또 다른 별미인 녹두 빈대떡도 추천할 만합니다. 그 외에도 국수, 비빔밥 등 다양한 식사 메뉴가 있습니다.', 37.525460, 127.027573, '', '지하철 3호선 압구정역 4번 출구, 62m', '버섯만두전골\n찐만두\n목로탕\n만두국\n목로전', '', '', '음식점', '', '월요일~금요일 10:00~20:00\n일요일 09:30~20:00', '02-548-7500', '토요일, 명절 휴무'),
	(590, '만수의정원', '03053  서울특별시 종로구 북촌로5가길 35-2 (소격동)', 'images/만수의정원_590.jpg', '비빔밥, 떡갈비 등의 한식을 즐길 수 있는 곳. 저녁 시간에는 반주와 함께.\n\n비빔밥, 떡갈비 등의 한식을 즐길 수 있는 곳입니다. 간단한 식사를 하거나 저녁 시간에는 반주와 함께 먹기에도 좋습니다.', 37.581051, 126.981404, '', '지하철 3호선 안국역 1번 출구, 740m', '일반한식', '수요일~월요일', '', '음식점', '', '11:00 ~ 21:00', '02-720-8900', '매주 화요일, 명절 휴무'),
	(591, '파파호', '06072  서울 강남구 영동대로137길 3 (청담동)', 'images/파파호_591.jpg', '정통 베트남 쌀국수와 반세오 전문점.\n\n정통 베트남 쌀국수와 반세오 전문점. 저렴하고 편안한 분위기에서 베트남 음식을 맛볼 수 있는 곳입니다. 소고기와 여러 가지 향신료가 들어간 국물이 일품인 쌀국수와 저민 돼지고기, 목이버섯, 당면을 볶아 속을 채워 튀긴 바삭한 쌀 피 튀김인 차조가 추천 메뉴입니다.', 37.521794, 127.055342, '1만원대', '지하철 7호선 청담역 13번 출구, 238m', '베트남 쌀국수, 반세오, 베트남식 돈등심구이, 태국식 치킨 복음밥', '', '', '음식점', '', '평일 11:00 ~ 14:30 / 17:00 ~ 21:00\n주말 11:00 ~ 14:30 / 17:00 ~ 20:30', '02-543-6885', '명절 당일 휴무'),
	(592, '베이스이즈나이스 (base is nice)', '04171  서울 마포구 도화2길 20 (도화동)', 'images/베이스이즈나이스_(base_is_nice)_592.jpg', '채소 본연의 맛을 전하고 있는 채소 친화적 식당\n\n베이스이즈나이스 (base is nice)는 \'채소\'를 주인공으로 삼아 식재료 본연의 맛을 전하고 있는 채소 친화적 식당입니다. 계절마다 달라지는 채소의 매력을 담아 만들어진 다양한 메뉴들을 만나 볼 수 있습니다. 특히 홍고추 퓌레의 구운 두부 밥은 베이스이즈나이스 (base is nice)의 시그니처 메뉴입니다. 신선하고 맛있는 채소 식사로 속도 편안하고 잊지 못할 한 끼를 경험 해보세요. 미쉐린 가이드 서울2025에 선정되었습니다.', 37.539625, 126.949106, '', '지하철 5호선 마포역 3번 출구, 354m', '바삭 청무와 옥수수 밥 23,000원\n알배기배추복숭아주스 7,500원\n발효버터 우엉구이 밥 23,000원\n유기농케일애플망고주스 7,500원\n홍고추 퓨레의 구운 두부 밥 23,000원', '화요일~일요일', ' https://www.instagram.com/baseisnice_seoul/', '음식점', '캐치테이블\' 앱을 통해 예약 필수', '11:00 ~ 15:00', '0507-1306-6724', '월요일'),
	(593, '리샨', '06620  서울 서초구 서초대로74길 11 (서초동, 삼성전자빌딩)', 'images/리샨_593.jpg', '미국 차이나타운 스타일의 퓨전 중식을 하는 곳.\n\n미국 차이나타운 스타일의 퓨전 중식을 하는 곳으로, 신세대 스타일 키친과 바를 내세우는 곳입니다. 수족관이 따로 있어 신선하고 맛있는 해산물을 골라 먹을 수 있습니다. 새우 와사비 크림소스가 인기 메뉴입니다.', 37.496633, 127.026915, '2만원대', '지하철 2호선/ 신분당선 강남역 7번 출구, 109m', '중새우와사비크림소스, 전복스테이크, 깐풍기, 해물누룽지탕', '월요일~토요일', '', '음식점', '', '평일 11:00~15:00, 16:20~21:40\n토 11:00~20:30', '02-587-6700', '일요일 휴무'),
	(594, '르포트13', '06028  서울 강남구 압구정로4길 13-13', 'images/르포트13_594.jpg', '분당에서 인기를 끈 브런치 카페의 서울 분점. 파스타와 브런치로 인기\n\n분당에서 인기를 끈 브런치 카페의 서울 분점. 파스타와 브런치로 인기를 끌고 있으며 다양한 세트 메뉴를 갖추고 있습니다. 와인도 150여 종 갖추고 있어 와인을 즐기기에도 좋습니다.', 37.521649, 127.020344, '', '지하철 3호선/신분당선 신사역 8번 출구, 768m', '프랑스식해물찜, 버섯크림리조또, 스파이시봉골레, 빠에야', '매일', '', '음식점', '', '월~토 11:30 - 23:30\n일 12:30 - 22:00', '0507-1376-1533', ''),
	(595, '완차이', '03777  서울특별시 서대문구 명물길 50-7 (창천동)', 'images/완차이_595.jpg', '저녁 무렵이면 골목까지 줄을 서는 신촌 일대에서는 유명한 중식당.\n\n규모는 작지만, 저녁 무렵이면 골목까지 줄을 서는 신촌 일대에서는 유명한 중식당입니다. 독특한 메뉴와 저렴한 가격으로 인기가 높습니다. 매콤한 홍콩식 홍합 요리가 유명하며 그 외에도 사천식 매운 요리를 잘합니다.', 37.558722, 126.939375, '1만원대', '지하철 경의중앙선 신촌역 1번, 276m', '매운홍합, 짜장면, 짬뽕', '', '', '음식점', '', '11:00 ~ 21:00', '0507-1441-0302', '매주 월요일'),
	(596, '대여', '07333  서울 영등포구 여의대방로67길 22 (여의도동, 태양빌딩)', 'images/대여_596.jpg', '30년 가까이 죽 한 가지만으로 여의도 증권가에서 오랫동안 명성을 유지하는 곳.\n\n30년 가까이 죽 한 가지만으로 여의도 증권가에서 오랫동안 명성을 유지하고 있는 곳입니다. 신선하고 제철에 나는 재료로 음식을 만들어 고소하고 깔끔한 맛이 일품입니다.', 37.520701, 126.929998, '1만원대', '지하철 9호선/ 신림선 샛강역 2번 출구, 468m', '버섯굴죽, 전복죽', '매일', ' http://www.02-783-6023.kti114.net/idx.htm', '음식점', '', '평일 07:30 ~ 21:00\n주말 08:30 ~ 20:00', '02-783-6023', '명절 휴무'),
	(597, '마당', '06021  서울 강남구 도산대로45길 7 (신사동, 에르메스도산파크)', 'images/마당_597.jpg', '에르메스 도산파크 건물 내의 중심부에 위치. 에르메스의 식기와 소품들을 사용하여 격조 있는 분위기에서 최상의 서빙을 받으면서 식사할 수 있는 품격 있는 공간. 마당이라는 이름이 있지만, 에르메스 카페라고도 불림.\n\n에르메스 도산파크 건물 내의 중심부에 정원이 있고 카페는 그 정원을 둘러싸고 있습니다. 에르메스의 식기와 소품들을 사용하여 격조 있는 분위기에서 최상의 서빙을 받으면서 식사할 수 있는 품격 있는 공간입니다. 마당이라는 이름이 있지만, 에르메스 카페라고도 부릅니다. 에르메스와 신라호텔이 공동 운영하고 있습니다.', 37.522786, 127.035346, '3만원대', '지하철 3호선 압구정역 3번 출구, 783m\n지하철 수인분당선 압구정로데오역 5번 출구, 730m', '카페', '월화수목금토일', '', '카페, 디저트', '', '월요일~토요일 11:00~19:00\n일요일 12:00~19:00', '02-546-3643', ''),
	(598, '고래불', '06239  서울 강남구 논현로79길 62 (역삼동)', 'images/고래불_598.jpg', '고래 고기를 전문으로 하지만 그 외 과메기 같은 동해안 지역의 향토 음식.\n\n신선한 제철재료와 생각치 못한 재료의 신선한 궁합을 통해 우리바다의 맛이 얼마나 풍성하고 깊은 것인지를 보여줍니다.  고래 고기를 전문으로 하지만 그 외에도 과메기 같은 동해안 지역의 향토 음식을 맛볼 수 있습니다. 세꼬시회, 물곰국, 전복회 등이 좋으며 식사 메뉴로 회막국수, 도루묵조림, 회비빔밥, 참가자미구이, 가자미식해 등도 맛볼 수 있습니다. \'바다풍경\', \'바다이야기\', \'바다속으로\'와 같은 코스메뉴가 있고 이 외에도 런치메뉴와 식사메뉴도 있습니다.', 37.496263, 127.033946, '', '지하철 2호/ 신분당선 강남역 4번 출구, 542m', '바다풍경, 바다물곰탕, 고래고기', '', ' http://koraebul.com', '음식점', '', '평일 11:30 ~ 14:30 / 17:00 ~ 22:00\n주말 11:30 ~ 21:00', '0507-1416-3677', '공휴일, 명절 휴무'),
	(599, '족발골목', '04214  서울 마포구 만리재로 19 (공덕동, 공덕시장)', 'images/족발골목_599.jpg', '공덕시장 내에 있는 족발 골목.\n\n공덕시장 내에 있는 족발 골목으로, 30년 전 시장 한쪽에 자리 잡은 2평짜리 식당이 족발골목의 뿌리입니다. 당시 팍팍한 삶을 달랠 술안주로 족발과 순댓국을 만들어 먹었고, 이후 손님이 늘어나며 족발골목이 형성되었습니다. 골목에는 대를 이어 30년 이상 운영하는 족발집이 여러 곳 있습니다.', 37.544795, 126.953258, '', '지하철 5/6호선/경의중앙선/공항철도 공덕역 5번 출구, 50m', '', '', '', '음식점', '', '점포별 상이', '', ''),
	(600, '금성스테이크', '06017  서울 강남구 언주로174길 26 (신사동, 남강빌딩) 1층 2호', 'images/금성스테이크_600.jpg', '압구정 일대에서 햄, 소시지, 김치 등을 넣어서 끓이는 부대찌개가 유명한 곳.\n\n오랫동안 압구정 일대에서 명소로 자리잡고 있는 곳으로 햄, 소시지, 김치 등을 넣어서 끓이는 부대찌개가 유명한 곳입니다. 묵은지를 사용하여 끓이는 부대찌개 맛이 칼칼합니다. 스테이크, 베이컨, 햄, 소시지와 야채 등을 철판에 볶아 먹는 모둠구이를 곁들이면 든든한 식사가 됩니다.', 37.527968, 127.035856, '', '지하철 수인분당선 압구정로데오역 6번 출구, 449m', '등심스테이크, 베이컨구이, 소시지전골', '월요일~토요일', '', '음식점', '', '11:30~22:00', '02-547-4872', '일요일, 명절 휴무'),
	(601, '장수원', '06558  서울특별시 서초구 방배중앙로 153 (방배동)', 'images/장수원_601.jpg', '방배동 카페 골목에 있는 불고기&냉면 전문점.\n\n방배동 카페 골목에 있는 불고기&냉면 전문점입니다. 평양냉면은 면은 좀 얇은 편이지만 메밀이 많이 들어갑니다. 양지머리를 우려낸 육수도 평양냉면에 가깝습니다. 불고기도 안정된 맛을 냅니다.', 37.492863, 126.986351, '2만원대', '지하철 4/7호선 총신대입구(이수역) 1번 출구, 740m', '소불고기', '', '', '음식점', '', '매일 10:30~21:30', '02-532-2225', '명절 휴무'),
	(602, '명륜손칼국수', '03068  서울특별시 종로구 혜화로 45-5 (명륜1가)', 'images/명륜손칼국수_602.jpg', '사골 육수로 만든 칼국수의 맛이 일품인 곳. 양지 수육이 유명.\n\n사골 육수로 만든 칼국수의 맛이 일품인 곳. 수육 또한 맛있는 곳으로, 두툼한 양지 수육이 유명합니다. 부드럽게 삶은 문어 수육도 맛이 좋으며, 수육과 문어를 반반씩 주문할 수도 있습니다. 저녁때는 영업하지 않으며, 재료가 떨어지면 일찍 문을 닫습니다.', 37.589432, 126.998870, '', '지하철 4호선 한성대입구역 5번 출구, 802m', '손칼국수 수육 문어 설렁탕', '월요일~금요일', '', '음식점', '', '11:30 - 13:30', '02-742-8662', '토요일, 일요일, 명절휴무'),
	(603, '주빌리쇼콜라띠에', '07325  서울 영등포구 국제금융로2길 24 (삼성생명(주)여의도빌딩)', 'images/주빌리쇼콜라띠에_603.jpg', '수제 초콜릿 전문점. 초콜릿과 케이크 와 에스프레소. 초콜릿 음료와함께. 초콜릿 음료의 농도는 취향에 따라 선택.\n\n수제 초콜릿 전문점. 초콜릿과 케이크, 에스프레소, 초콜릿 음료와 곁들여도 좋습니다. 초콜릿 음료의 농도는 취향에 따라 선택할 수 있게 되어 있습니다.', 37.524305, 126.924840, '1만원대', '지하철 5/9호선 여의도역 3번 출구, 280m', '카페', '', ' http://www.jubileechocolatier.com', '카페, 디저트', '', '평일 07:00~17:00', '0507-1372-7221', '토요일, 일요일'),
	(604, '두꺼비정육점식당', '06197  서울 강남구 역삼로 421', 'images/두꺼비정육점식당_604.jpg', '한우 1++ 등급 전문업소를 표방하고 있는 정육점 식당.\n\n한우 1++ 등급 전문업소를 표방하고 있는 정육점 식당. 참숯불에 구리 석쇠를 올려서 질 좋은 한우를 구워 먹을 수 있는 곳입니다. 고기를 정육점에서 산 후 채소 값 3천 원을 따로 내고 구워 먹는 정육식당 시스템입니다.', 37.501455, 127.053071, '', '지하철 2호선/ 수인분당선 선릉역 1번 출구, 569m', '설렁탕, 불고기뚝배기, 육회비빔밥, 불고기전골', '', '', '음식점', '', '평일 11:00~22:00, 주말 11:00~21:00', '02-445-8742', '명절 휴무'),
	(605, '더블린', '06123  서울 강남구 강남대로 442 (역삼동)', 'images/더블린_605.jpg', '기네스 생맥주를 마실 수 있어 인기있는 아이리시 펍.\n\n기네스 생맥주를 마실 수 있어 인기있는 아이리시 펍. 병맥주가 아니라 직접 수입한 생맥주로, 신선한 맛을 즐길 수 있습니다. 기네스 생맥주 외에도 호가든, 킬케니, 에딩거, 삿뽀로 등 다양한 생맥주와 병맥주가 준비되어 있습니다. 넓은 실내는 아일랜드 술집처럼 꾸며져 있습니다.', 37.502062, 127.026081, '', '지하철 9호선/신분당선 신논현역 6번 출구, 218m', '아이리쉬 쇠고기 스튜, 리코타 치즈 샐러드, 고르곤졸라 피자', '', '', '술집, 바', '', '월~목 15:00~01:00, 금 15:00~02:00, 토 14:00~02:00, 일 14:00~24:00', '02-561-3281', '연중무휴'),
	(606, '마오', '06062  서울 강남구 도산대로56길 17 (청담동)', 'images/마오_606.jpg', '트렌디한 중국 본토의 분위기. 저렴한 가격의 북경 오리.\n\n내부는 팝아트적인 마오의 초상화 등으로 트렌디 하면서도 중국 본토의 분위기가 나도록 꾸며져 있습니다. 서울에서는 몇 안되는, 비교적 저렴한 가격으로 북경 오리(카오야)를 즐길 수 있는 곳입니다.', 37.521975, 127.040542, '2만원대', '지하철 7호선/ 수인분당선 강남구청역 4번 출구, 634m', '북경오리, 소고기 훠궈, 자장면, 마오면', '', '', '음식점', '', '매일 11:30~22:00', '02-514-8803', '명절 당일 휴무'),
	(607, '영락골뱅이', '04550  서울 중구 수표로 52 (을지로3가)', 'images/영락골뱅이_607.jpg', '을지로 골뱅이 골목에서 옆집 영동골뱅이와 함께 원조집으로 군림하고 있는 집.\n\n을지로 골뱅이 골목에서 옆집 영동골뱅이와 함께 원조집으로 군림하고 있는 집. 저렴하면서도 양이 많아 맥주 안주하기에 좋습니다. 서비스로 내오는 계란말이도 맛있습니다.', 37.565771, 126.989973, '2만원대', '지하철 2/3호선 을지로 3가역 11번 출구, 60m', '골뱅이무침', '', '', '음식점', '', '매일 13:00 ~ 02:00', '02-2264-9489', '명절 휴무'),
	(608, '할랄가이즈 이태원점', '04350  서울 용산구 이태원로 187 (이태원동)  2층', 'images/할랄가이즈_이태원점_608.jpg', '뉴욕의 푸드트럭으로 시작한 브랜드. 간편하면서도 영양소를 고루 갖춘 플래터와 샌드위치\n\n할랄푸드 브랜드 할랄가이즈는 뉴욕의 푸드트럭으로 시작한 브랜드인 만큼 간편하면서도 영양소를 고루 갖춘 플래터와 샌드위치 메뉴를 선보이고 있습니다. 한국으로 들어온 할랄가이즈는 모두 할랄 인증을 받았으며, 미국에서 공수한 할랄 재료들로 만들어집니다.', 37.534728, 126.994783, '', '지하철 6호선 이태원역 2번 출구, 51m', '콤보 플래터, 치킨 플래터, 콤보 샌드위치', '', ' http://thehalalguys.co.kr/', '음식점', '', '11:00~22:00', '02-794-8309', ''),
	(609, '아야진생태찌개', '06165  서울특별시 강남구 삼성로108길 8 (삼성동)', 'images/아야진생태찌개_609.jpg', '곤이가 푸짐하게 들어 있는 생태찌개가 유명한 곳.\n\n곤이가 푸짐하게 들어 있는 생태찌개가 유명합니다. 양은냄비에 생태를 통째로 넣어 푹 끓였습니다. 국물이 칼칼하면서도 간이 잘되어있어 생태찌개 하나만으로도 푸짐한 식사를 할 수 있습니다.', 37.511785, 127.054760, '', '지하철 9호선 삼성중앙역 5번 출구, 142m', '생태찌개, 내장추가, 콩나물북어찜', '', '', '음식점', '', '매일 11:00~15:00, 17:00~22:00', '02-555-2680', '명절 휴무'),
	(610, '삼각정', '04376  서울 용산구 한강대로 151 (한강로2가)', 'images/삼각정_610.jpg', '편안한 분위기에서 질 좋은 삼겹살을 맛 볼 수 있는 서민적인 분위기.\n\n삼겹살 구이로 유명한 집. 편안한 분위기에서 질 좋은 삼겹살을 맛 볼 수 있는 서민적인 분위기로 인기가 좋습니다. 항정살의 일종인 모소리살이 유명합니다. 바짝 구워 먹는 돼지껍데기도 많이 찾습니다.', 37.532815, 126.971105, '', '지하철 4/ 6호선 삼각지역 4번 출구, 104m', '갈매기살, 모소리, 목살, 삼겹살', '', '', '음식점', '', '월~토 17:00 ~ 22:30', '02-798-3666', '매주 일요일 휴무'),
	(611, '남한강 매운탕', '05295  서울 강동구 양재대로 1594 (명일동)', 'images/남한강_매운탕_611.jpg', '경기도 양평에서 양식한 메기, 강원도 양구군의 자연산 민물고기로 만든 매운탕집.\n\n어부가 직접 잡은 메기, 쏘가리, 빠가사리, 민물참게로 도심에서 즐기는 칼칼하고 시원한 민물매운탕\n\n \n\n강동구 맛집으로 소문난 남한강 매운탕은 경기도 양평에서 양식한 메기 및 강원도 양구군에서 어부가 직접 잡은 자연산 민물고기와 및 민물참게를 넣은 칼칼하고 시원한 매운탕을 맛볼 수 있는 곳입니다. 남한강 매운탕은 국립한국교통대학교 식품공학과 교수와 공동 개발한 시즈닝을 사용하여 각종 성인병을 예방할 수 있는 건강에 좋은 매운탕을 제공하며 민물고기를 즐겨 먹는 세계 여러 관광객의 입맛을 사로잡아 한국을 알릴 수 있는 대한민국 고유의 음식입니다.', 37.547679, 127.143728, '', '지하철 5호선 굽은다리역 3번 출구, 216m', '', '', '', '음식점', '중국어/베트남어 메뉴판 구비', '매일 11:00 ~ 21:30', '02-481-7779', ''),
	(612, '마츠에라멘', '04030  서울 마포구 동교로 126 (서교동, 광남벨라스아파트)', 'images/마츠에라멘_612.jpg', '재첩으로 육수를 내는 일본 마쯔에 지방식 라멘을 하는 곳.\n\n재첩으로 육수를 내는 일본 마쯔에 지방식 라멘을 하는 곳입니다. 면을 직접 뽑아서 사용하는 것이 특징. 역시 직접 만들어 구워내는 야키교자 맛도 수준급이며 저녁 때는 이자카야 메뉴도 준비됩니다.', 37.554741, 126.916201, '1만원대', '지하철 2/6호선 합정역 2번 출구, 614m', '마츠에라멘, 시지미라멘, 도쿠마츠라멘', '월요일~토요일', '', '음식점', '', '11:30~23:00', '02-323-6877', '일요일, 설, 추석 당일 휴무'),
	(613, '니와', '04423  서울 용산구 이촌로75길 22', 'images/니와_613.jpg', '이촌동 중앙재래시장 안에 있는 아담한 이자카야. 일본식 가정요리를 안주 삼아 가볍게 사케 한잔하기 좋은 곳.\n\n이촌동 중앙재래시장 안에 있는 아담한 이자카야. 일본식 가정요리를 안주 삼아 가볍게 사케 한잔하기 좋은 곳입니다.', 37.520780, 126.974503, '', '지하철 4호선 / 경의중앙선 이촌역 3--1번 출구, 206m', '오코노미야끼, 가오리구이, 수제고로케', '', '', '술집, 바', '', '17:00 ~ 24:00', '02-790-0917', '매주 화요일, 명절 휴무'),
	(614, '충무상회', '06022  서울 강남구 언주로167길 38 (신사동)', 'images/충무상회_614.jpg', '강남에서 20년간 한자리를 지키고 있는 통영 향토 음식점.\n\n20년간 한자리를 지키고 있는 통영 향토 음식점으로, 주메뉴는 세꼬시와 생선구이. 이 밖에도 마른 가자미구이, 충무식 가오리찜, 멸치회 등의 메뉴가 있습니다. 해장국으로 인기가 좋은 물메기탕도 이 집에서 맛볼 수 있는 별미입니다. 모든 음식에는 생선회 뼈를 우려낸 국물에 잡어의 생선 살을 넣고 끓인 서덜 미역국이 함께 나옵니다.', 37.526610, 127.030110, '', '지하철 3호선 압구정역 2번 출구, 183m', '생선회', '월요일~일요일', '', '음식점', '', '11:30 ~ 22:00', '02-515-6395', '매주 일요일, 공휴일 휴무'),
	(615, '안동뭉티기와 투뿔구이', '06114  서울특별시 강남구 학동로2길 35 (논현동)', 'images/안동뭉티기와_투뿔구이_615.jpg', '안동에서 올라온 한우를 사용하는 육사시미 맛이 일품인 곳.\n\n안동에서 올라온 한우를 사용하는 육사시미 맛이 일품인 곳입니다. 경상도식으로 만든 양념장에 찍어 먹습니다.', 37.509171, 127.023308, '', '지하철 7호선/신분당선 논현역 3번 출구, 125m', '한우 육사시미, 한우 미니파육회, 한우 특등급 생등심', '', '', '음식점', '', '월요일~토요일 15:00~01:00', '02-542-9085', '일요일, 명절 당일 휴무'),
	(616, '소도', '07332  서울 영등포구 의사당대로1길 11 (여의도동, 메종리브르오피스텔)', 'images/소도_616.jpg', '여의도에서 고급스럽게 일식을 즐길 수 있는 곳.\n\n여의도에서 고급스럽게 일식을 즐길 수 있는 곳. 저녁 사시미코스가 훌륭하게 나오며 점심회정식도 괜찮은 편입니다. 손님을 모시는 장소로도 좋습니다.', 37.519212, 126.928582, '', '지하철 9호선 /신림선 샛강역 1번 출구, 210m', '점심회정식, 저녁코스', '', '', '음식점', '', '월~토 11:30 ~ 22:30', '02-783-3155', '매주 일요일'),
	(617, '일상', '02837  서울 성북구 성북로 106 (성북동)', 'images/일상_617.jpg', '핸드 드립 커피전문점. 한쪽 벽면 가득한 국내외 책자들을 읽으면서 여유롭게 훌륭한 커피를 즐길 수 있는 곳. 커피에 대한 애정이 깊으신 사장님의 핸드 드립 커피 무료 특강.\n\n핸드 드립 커피전문점입니다. 한쪽 벽면 가득한 국내외 책자들을 읽으면서 여유롭게 훌륭한 커피를 즐길 수 있는 곳입니다. 커피에 대한 애정이 깊으신 사장님의 핸드 드립 커피 무료 특강이 있습니다.', 37.593084, 126.997208, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 1km', '오늘의커피, 카페모카, 카페라떼', '', '', '카페, 디저트', '', '수요일~일요일 12:00~18:00', '02-762-3114', '매주 월요일, 화요일 휴무'),
	(618, '금홍', '04387  서울 용산구 서빙고로 17 (한강로3가)  해링턴스퀘어 1층 32호', 'images/금홍_618.jpg', '검은색으로 내부를 꾸민 일본풍의 작은 차이니스 레스토랑.\n\n검은색으로 내부를 꾸민 일본풍의 작은 차이니스 레스토랑. 기름기가 적고 담백한 맛이 특징이다. 중하를 사용한 간소새우와 사천탕면이 인기 메뉴입니다.', 37.526906, 126.966566, '', '지하철 4호선 신용산역 2번 출구, 346m', '깐쇼새우, 사천탕면, 유린기', '', '', '음식점', '', '11:00~15:00, 16:30~21:00', '02-796-0995', '명절 휴무'),
	(619, '굴비마을', '06019  서울 강남구 도산대로49길 10-8 (신사동, 신사동 K 빌딩)', 'images/굴비마을_619.jpg', '굴비구이를 전문으로 하며, 해산물, 홍어 등도 맛볼 수 있는 곳.\n\n굴비구이를 전문으로 하며, 해산물, 홍어 등도 맛볼 수 있습니다. 보리에 묻어 한 달 정도 숙성시킨 짭조름한 굴비를 냉 녹차에 말은 밥과 같이 먹는 보리굴비정식이 권할 만합니다. 묵은지에 싸 먹는 삭은 홍어회와 홍어애 탕 맛도 좋습니다.', 37.523756, 127.038030, '3만원대', '지하철 수인분당선 압구정로데오역 5번 출구, 432m', '굴비', '월요일~토요일', '', '음식점', '', '11:30 ~ 22:00', '02-518-4424', '일요일, 명절 휴무'),
	(620, '부흥동태', '07331  서울특별시 영등포구 국제금융로8길 34 (여의도동)', 'images/부흥동태_620.jpg', '여의도에서 오래된 동태탕 집. 직장인들에게 꾸준히 사랑 받는 곳.\n\n여의도에서 오래된 동태탕 집입니다. 여의도 직장인들에게 꾸준히 사랑 받는 곳으로 조금만 늦게 가면 줄을 설 각오를 해야 합니다. 재료와 양념을 아끼지 않고 넣어 진하고 얼큰하면서도 깔끔한 뒷맛의 동태탕을 먹을 수 있습니다.', 37.520281, 126.927220, '', '지하철 5/9호선 여의도역 5번 출구, 385m', '동태내장전골\n동태알탕\n동태탕', '월요일~토요일', '', '음식점', '', '평일 09:00 ~ 22:00\n토요일 11:00 ~ 15:00', '02-782-7707', '매주 일요일 휴무'),
	(621, '플로리안', '05718  서울특별시 송파구 송파대로28길 27 (가락동)', 'images/플로리안_621.jpg', '원두커피 전문점. 그 날 볶은 커피는 따로 칠판에 적어 놓기 때문에 신선한 원두를 맛볼 수 있음. 커피를 시키면 즉석에서 원두를 갈아서 내리기 때문에 조금 기다려야 함.\n\n원두커피 전문점. 그날 볶은 커피는 따로 칠판에 적어 놓기 때문에 신선한 원두를 맛볼 수 있습니다. 커피를 시키면 즉석에서 원두를 갈아서 내리기 때문에 조금 기다려야 합니다. 두꺼운 식빵으로 만든 토스트 세트도 추천 메뉴입니다. 실내 분위기도 아기자기하고 커피잔 등의 그릇도 고급을 사용하고 있어 주인의 손길이 느껴집니다.', 37.494812, 127.120133, '1만원대', '지하철3/8호선 가락시장역 4번 출구, 326m', '', '월요일~토요일', '', '카페, 디저트', '', '11:00~22:00', '02-403-1248', '매주 일요일 휴무'),
	(622, '광양불고기', '07928  서울특별시 양천구 남부순환로 531 (신월동)', 'images/광양불고기_622.jpg', '광양불고기 본가의 전통맥을 이어가는 특유의 양념 맛으로, 육질이 연하고 담백.\n\n3대를 잇는 명성과 변함없는 맛\n\n불고기는 전국 어디에서나 있는 흔한 음식이지만 광양불고기는 본가의 전통맥을 이어가는 특유의 양념 맛으로, 육질이 연하고 담백해 독특한 맛을 자랑합니다. 불고기 뿐만 아니라 함께 곁들여 지는 밑반찬도 정갈하고 맛깔스럽습니다.', 37.521316, 126.837968, '', '지하철 5호선 신정역 5번 출구, 1.5km', '광양불고기, 꽃등심', '월요일~일요일', '', '음식점', '', '11:00~21:30', '02-2697-9999', '연중무휴 ( 명절 당일만 쉼 )'),
	(623, '한우집위', '07333  서울특별시 영등포구 국제금융로 86 (여의도동)', 'images/한우집위_623.jpg', '한우 1+, 1++ 만을 사용. 한우등심, 안심, 된장찌개, 깍두기밥이 골고루 나오는 점심특선 메뉴.\n\n한우 1+, 1++ 만을 사용하는 것으로 유명해진 집. 한우등심, 안심, 된장찌개, 깍두기밥이 골고루 나오는 점심특선 메뉴도 인기가 있습니다. 동그란 철판에 소기름을 두르고 고기를 구워 먹는 방식입니다. 다 먹은 다음에는 깍두기와 밥을 넣어서 볶아 먹습니다.', 37.520059, 126.932022, '', '지하철 9호선/ 신림선 샛강역 2번 출구, 381m', '소고기구이', '월요일~토요일', '', '음식점', '', '11:00 ~ 22:00', '02-780-2528', '매주 일요일, 명절 당일 휴무'),
	(624, '주', '06561  서울특별시 서초구 동광로19길 16 (방배동)', 'images/주_624.jpg', '조선호텔 호경전 창립 멤버인 주덕성 셰프가 운영하는 중식당.\n\n조선호텔 호경전 창립 멤버인 주덕성 셰프가 운영하는 곳입니다. 불을 잘 사용하여 원재료의 맛을 잘 살려냈습니다. 테이블이 4개, 룸이 하나 정도 있는 작은 규입니다.', 37.493209, 126.989338, '2만원대', '지하철 7호선 내방역 6번 출구, 726m', '삼선짜장면, 삼선짬뽕, 전가복, 팔보채', '', '', '음식점', '', '화요일~금요일 11:30 ~ 15:00 / 17:00 ~ 21:30\n주말 11:30 ~ 21:30', '010-5836-3374', '매주 월요일 휴무'),
	(625, '부림정 숯불갈비', '05082  서울특별시 광진구 뚝섬로 476-7 (자양동)', 'images/부림정_숯불갈비_625.gif', '생고기를 양념에 숙성시켜 갈비의 맛을 살린 숯불갈비와 생오겹살, 갈비탕.\n\n주인이 직접 구입한 얼리지 않는 생고기에 신선한 배, 사과, 양파 등 각종 야채와 과일을 갈아서 숙성시켜 갈비의 맛을 살린 돼지갈비와 생오겹살, 갈비탕 등을 맛볼 수 있습니다.', 37.536351, 127.062721, '', '지하철 7호선 자양역 1번 출구, 764m', '돼지갈비', '월요일 ~ 일요일', '', '음식점', '', '10:00 - 22:00', '02-463-5455', '연중 무휴'),
	(626, '코끼리분식', '04172  서울 마포구 도화2길 3 (도화동)', 'images/코끼리분식_626.jpg', '공덕동에서 3대째 이어지고 있는 떡볶이 맛집\n\n공덕동 즉석 떡볶이 거리에서 유명한 맛집 중 한 곳으로, 3대째 운영 중입니다. 많은 사람에게 맛을 인정받아 대한민국 레스토랑 가이드북 <블루리본 서베이>에 2017년, 2018년 2년 연속 소개되었습니다. 즉석떡볶이를 다 먹고 난 후 그 양념으로 밥을 볶아 먹는 것도 별미입니다. 떡볶이와 튀김 모두 저렴한 가격을 오랫동안 유지하고 있습니다.', 37.540336, 126.948796, '', '지하철 5호선 마포역 3번 출구, 270m', '즉석떡볶이, 김밥, 참치주먹밥', '매일', ' https://www.instagram.com/koggiri_mapo_line5/', '음식점', '', '09:30~21:00(라스트오더 20:30)', '02-717-9061', '매달 1, 3번째 월요일 정기휴무'),
	(627, '마포나루', '04172  서울특별시 마포구 삼개로 11 (도화동)', 'images/마포나루_627.jpg', '다양한 요리와 풍성한 안주를 즐길 수 있는 옛날 주막 분위기의 토속음식 전문점\n\n전골류, 보쌈, 파전, 쌈밥 등 다양한 요리와 풍성한 안주를 즐길 수 있는 옛날 주막 분위기의 토속음식 전문점입니다. 식사를 겸할 수 있는 메뉴가 많아 가족 모임과 회식 장소로도 좋습니다.', 37.539367, 126.947760, '', '지하철 5호선 마포역 3번 출구, 192m', '', '월요일~토요일', ' https://www.maponaru.com/', '음식점', '', '11:00 - 22:00\n*Break time 15:00 - 17:00', '02-711-5959', '일요일'),
	(628, '리치몬드 제과점 더현대서울점', '07335  서울 영등포구 여의대로 108 (여의도동, 파크원)   더현대서울 지하 1층', 'images/리치몬드_제과점_더현대서울점_628.jpg', '1979년 마포구에서 시작해 지금까지 오랜 역사를 가지고 있는 리치몬드 제과점\n\n1979년 마포구에서 시작해 지금까지 오랜 역사를 가지고 있는 리치몬드 제과점을 더현대서울 식품관 테이스티서울에서 만나볼 수 있습니다. 리치몬드 제과점의 고소하고 달콤한 밤이 알알이 가득 들어있는 밤파이는 많은 사람들에게 사랑받는 디저트입니다. 이뿐만 아니라 촉촉한 빵에 밤이 박힌 밤식빵과 꾸덕한 크림이 흘러나오는 슈크림도 먹어보기를 추천합니다!', 37.525191, 126.929113, '', '지하철5호선 여의나루역 1번 출구, 312m', '', '매일', '', '카페, 디저트', '', '월요알~토요일 10:30 ~ 20:00\n일요일 10:30 ~ 20:30', '02-3277-0798', '더현대서울(백화점) 휴무일'),
	(629, '금강바베큐치킨', '06542  서울특별시 서초구 사평대로 349 (반포동)', 'images/금강바베큐치킨_629.jpg', '바비큐 치킨과 마늘 치킨이 대표 메뉴. 숯불에 굽는 바비큐 치킨은 숯향이 배어 있어 별미.\n\n생맥주와 치킨을 저렴하게 먹을 수 있는 곳. 다양한 종류의 치킨이 있지만 바비큐 치킨과 마늘 치킨이 대표 메뉴입니다. 숯불에 굽는 바비큐 치킨은 숯향이 배어 있어 별미입니다. 계란말이는 서비스로 제공됩니다.', 37.503811, 127.021293, '', '지하철 9호선 / 신분당선 신논현역 1번 출구, 237m', '치킨', '매주 일요일', '', '술집, 바', '', '월요일~토요일 15:30~23:55', '02-511-0976', '명절 당일 휴무'),
	(630, '시실리', '06577  서울 서초구 서래로 26 (반포동)', 'images/시실리_630.jpg', '커피 맛이 훌륭하기로 인정받고 있는 핸드 드립 커피 전문점. 몬순, 디카페인 원두 판매. 식사류로는 파스타도 즐길 수 있으며 샐러드, 빵, 커피가 같이 나옴. 실내 분위기는 클래식하면서 편안.\n\n커피 맛이 훌륭하기로 인정받고 있는 핸드 드립 커피 전문점. 몬순, 디카페인 등 생두를 볼 수 있으며 원두는 판매도 가능합니다. 식사류로는 파스타도 즐길 수 있으며 샐러드, 빵, 커피가 같이 나옵니다. 실내 분위기는 클래식하면서 편안합니다.', 37.497337, 126.998502, '1만원대', '지하철3/7/9호선 고속터미널역 5번 출구, 918m', '커피전문점', '매일', '', '카페, 디저트', '', '12:00 ~ 22:00', '02-591-1929', ''),
	(631, '이쯔모', '04419  서울 용산구 독서당로 67 (한남동)', 'images/이쯔모_631.jpg', '다양한 일식 안주를 맛볼 수 있는 곳. 두부튀김, 문어초회, 나가사키짬뽕을 추천.\n\n다양한 일식 안주를 맛볼 수 있는 곳으로 두부튀김, 문어초회 등이 폰즈 소스와 어울립니다. 식사로는 나가사키짬뽕을 권할 만한데, 채소를 센 불에 볶은 후 돼지뼈를 우려낸 육수를 부은 것으로, 국물 맛이 시원하고 개운합니다.', 37.533869, 127.008154, '', '지하철 경의중앙선 한남역 1번 출구, 609m', '문어와 마 초미소 무침, 모듬회 3점세트', '', '', '술집, 바', '', '월요일~토요일 17:00~01:00', '02-796-8743', '매주 일요일, 공휴일 휴무'),
	(632, '쯔꾸시', '04352  서울 용산구 한강대로76길 3 (남영동)', 'images/쯔꾸시_632.jpg', '일본 가정식과 사시미, 안주류와 일본 사케를 맛볼 수 있는 일식집.\n\n다양한 안주류와 일본 사케를 맛볼 수 있는 일식 주점입니다. 점심 시간에 내는 쯔꾸시 짬뽕(나가사키짬뽕)은 돼지사골을 푹 곤 진국물에 해물과 신선한 채소를 얹어내는데, 다소 굵은 면발이 고소한 국물과 함께 인기를 얻고 있습니다. 소박한 일본 가정식 안주와 사시미 등을 맛볼 수 있습니다.', 37.541594, 126.973358, '2만원대', '지하철 1호선 남영역 1번 출구, 252m', '장어덮밥, 치라시스시, 쯔쿠시 짬뽕', '월요일~토요일', '', '음식점', '', '월요일~금요일 10:00~14:00 / 16:00~22:00\n토요일 14:00~21:00', '02-790-5602', '매주 일요일, 명절 휴무'),
	(633, '마노디셰프', '06169  서울특별시 강남구 테헤란로87길 21 (삼성동)', 'images/마노디셰프_633.jpg', '피자와 파스타를 부담없이 즐길 수 있는 이탈리안 비스트로.\n\n피자와 파스타를 부담없이 즐길 수 있는 이탈리안 비스트로. 블루베리 피자가 유명하며 먹물로 된 도우에 나오는 고르곤졸라 피자도 독특한 메뉴 중의 하나입니다. 와인도 250여 종 갖추고 있어서 와인과 같이 즐기기에도 좋습니다.', 37.509053, 127.058250, '', '지하철 2호선 삼성역 5번 출구, 439m', '마노디셰프 품격코스, 봉골레 알리 올리오 파스타, 로제 씨푸드 파스타', '매일', ' http://www.manodichef.co.kr/', '음식점', '', '평일 11:00 ~ 15:00 / 17:00 ~ 22:00\n토요일 11:00 ~ 15:50 / 17:00 ~ 22:00\n일요일 11:00 ~ 15:50 / 17:00 ~ 21:00', '02-561-9011', ''),
	(634, '은성집', '04352  서울특별시 용산구 한강대로84길 11-16 (남영동)', 'images/은성집_634.jpg', '채소와 함께 볶아 먹는 스테이크, 소시지 요리.\n\n채소와 함께 볶아 먹는 스테이크, 소시지 요리 등을 주 메뉴로 갖추고 있습니다. 햄, 소시지, 베이컨, 안심, 양파, 감자 등을 넣고 후춧가루를 조금 뿌린 뒤 익혀 먹는 소시지 모둠 구이도 별미입니다. 피클 대신 알타리 무가 나오는 것도 재미있습니다. 부대찌개도 유명합니다.', 37.544386, 126.973243, '', '지하철 4호선 숙대입구역 5번 출구, 109m', '스테이크,부대찌개', '', '', '음식점', '', '11:30 ~ 13:30 / 16:30 ~ 22:00', '02-797-2855', '주말'),
	(635, '케르반 베이커리', '04405  서울 용산구 이태원로 208 (제임스클럽)', 'images/케르반_베이커리_635.jpg', '케르반 베이커리는 터키 출신 파티셰가 전통 터키식 디저트를 만들어 파는 곳.\n\n케르반 베이커리는 터키 출신 파티셰가 전통 터키식 디저트를 만들어 파는 곳입니다. 로쿰, 바클라바 등 입안에서 살살 녹는 디저트부터 터키식 젤리, 푸딩, 잼까지 평소에 접하지 못했던 디저트와 다양한 빵이 가판대를 채우고 있습니다.', 37.534541, 126.997056, '', '지하철 6호선 이태원역 3번 출구, 242m', '로쿰, 바클라바, 쿠키, 푸딩,', '매일', ' https://www.instagram.com/kervanbakery/', '카페, 디저트', '', '일요일~목요일 10:00~22:30\n금요일~토요일 10:00~06:00', '0507-1387-5585', ''),
	(636, '포항식당', '03139  서울 종로구 돈화문로5가길 31-1 (돈의동)', 'images/포항식당_636.jpg', '포항에서 직송으로 가져오는 과메기를 사용하는 과메기 전문점.\n\n포항에서 직송으로 가져오는 과메기를 사용하는 과메기 전문점입니다. 과메기 자체의 비린내가 별로 나지 않아 과메기를 처음 먹어보는 사람들도 부담 없이 즐길 수 있습니다. 과메기 외에 돌문어와 아귀수육도 준비되어 있습니다.', 37.572221, 126.991216, '2만원대', '지하철 1/3/5호선 종로3가역 3번 출구, 52m', '일반한식', '월요일~토요일', '', '음식점', '', '15:00 ~ 24:00', '02-765-6487', '명절 휴무,일요일 휴무'),
	(637, '시루케이크', '04073  서울 마포구 어울마당로1길 18 (합정동, 합정주택)', 'images/시루케이크_637.jpg', '시루케이크는 상수에 위치한 떡 디저트 카페.\n\n시루케이크는 상수에 위치한 떡 디저트 카페입니다. 국내산 쌀과 우유, 생크림만을 사용한 떡을 선보입니다. 감각 있는 한국식 디저트를 찾는 사람이라면 꼭 들러야 할 곳입니다. 떡케이크 판매와 함께 강습도 있어서 원데이, 단기, 장기 수강도 가능합니다.', 37.546785, 126.918270, '1만원대', '지하철 2/6호선 합정역 7번 출구, 556m', '설기케이크, 떡케이크, 크림대추라떼', '', ' https://www.instagram.com/siroocake/?igshid=aywpoidg5w2n', '카페, 디저트', '', '월,화,목,금 11:00~20:00\n토,일 11:00~19:30', '0507-1338-0190', '매주 수요일'),
	(638, '카페 하이웨스트 익선점', '03133  서울 종로구 돈화문로11다길 18 (돈의동)', 'images/카페_하이웨스트_익선점_638.jpg', '아기자기하고 따듯한 분위기의 예쁜 디저트 카페\n\n익선동에 위치한 카페 하이웨스트는 흰색 인테리어와 한옥 건물이 만나 이색적인 모습을 보여주는 카페입니다. 아기자기하고 따듯한 분위기로 예쁜 디저트 카페, 데이트 장소로 많은 사람들이 찾는 곳입니다. 동화 속 공간같이 꾸며진 카페 내부와 귀엽고 알록달록한 비주얼의 베이커리들이 눈길을 사로잡습니다. 클래식 버터 스콘, 더블 초콜릿 스콘 등 다양한 스콘 종류와 귀여운 강아지 모습이 그려진 퍼피 케이크, 크림치즈크림과 초콜릿 으로 만들어진 리치 초코 케이크를 만날 수 있습니다.', 37.573132, 126.990683, '', '지하철1/3/5호선 종로3가역 6번 출구, 119m', '브레드 스콘 4,700원\n테디 스콘 5,300원\n초콜릿 테디 스콘 5,800원\n바질페스토 크림치즈 스콘 5,500원\n당근케이크 8,000원\n빅토리아케이크 8,000원\n쥬시 레몬케이크 8,300원', '매일', ' https://instagram.com/cafe_highwaist?utm_medium=copy_link', '카페, 디저트', '', '09:00 ~ 22:00', '', ''),
	(639, '타워차이', '06294  서울특별시 강남구 언주로30길 26 (도곡동)', 'images/타워차이_639.jpg', '샥스핀 전문 중식당. 수프, 찜 등 샥스핀을 이용한 다양한 요리.\n\n샥스핀 전문 중식당. 일반적인 중식 요리들도 내고 있지만, 주력 메뉴는 샥스핀으로 수프, 찜 등 샥스핀을 이용한 다양한 요리를 맛볼 수 있습니다. 보통 사용하는 가공된 냉동 샥스핀이 아니라 직접 남태평양산 화이트 샤크 샥스핀을 가공하여 들여온 것을 사용하고 있습니다.', 37.487749, 127.052507, '2만원대', '지하철 3호선/ 수인분당선 도곡역 4번 출구, 488m', '홀샥스핀탕 S, 올리브유 짜장면, 송이덮밥', '', ' http://www.towerchai.com/', '음식점', '', '매일 11:30 ~ 15:00 / 17:30 ~ 22:00', '02-2057-7007', '명절 당일 휴무'),
	(640, '콰이19', '06032  서울 강남구 도산대로25길 16 (신사동)  1층', 'images/콰이19_640.jpg', '기름을 최소화하여 요리. 전복수프와 유린기를 추천.\n\n기름을 최소화하여 요리하는 것이 특징입니다. 신선한 전복과 죽순이 들어가 단백하면서 깔끔한 전복수프와 양상추 위에 바삭하게 튀긴 닭다리와 매운 고추 소스를 올린 유린기를 추천합니다. 복숭아색을 주 칼라로 사용한 인테리어가 인상적입니다.', 37.520915, 127.027300, '2만원대', '지하철 3호선 압구정역 4번 출구, 565m', '등갈비 깐풍소스, 매운 고추 닭날개, 오향장육, 중국식냉면', '월요일~토요일', ' https://www.instagram.com/kuai_china_flavor/?igshid=llol1ut93c8z', '음식점', '', '평일 11:30 ~ 15:00 / 17:30 ~ 22:00\n토요일 11:30 ~ 16:00', '02-540-4155', '일요일, 명절 휴무'),
	(641, '주빈', '07331  서울특별시 영등포구 의사당대로 127 (여의도동)', 'images/주빈_641.jpg', '아담한 공간의 핸드드립 커피 전문점. 커피를 산지별로 15가지 이상 갖추어 두고 있으며, 로스팅을 직접 하기 때문에 항상 신선한 커피를 맛볼 수 있음.\n\n아담한 공간의 핸드드립 커피 전문점. 커피를 산지별로 15가지 이상 갖추어 두고 있으며, 로스팅을 직접 하기 때문에 항상 신선한 커피를 맛볼 수 있습니다. 갓 볶은 커피를 가장 좋은 맛으로 내리기 위해 융을 이용한 추출을 하는 것이 특징입니다.', 37.520316, 126.926539, '1만원대', '지하철5/9호선 여의도역 5번 출구, 234m', '', '월요일~금요일', ' http://www.jubean-coffee.com', '카페, 디저트', '', '월요일~금요일 10:00~19:30', '0507-1309-7970', '토요일 일요일'),
	(642, '카페 레이어드 안국점', '03059  서울 종로구 북촌로2길 2-3 (재동)', 'images/카페_레이어드_안국점_642.jpg', '담백하게 구워낸 다양한 종류의 스콘으로 유명한 카페 레이어드 본점\n\n담백하게 구워낸 다양한 종류의 스콘으로 유명한 카페 레이어드의 본점을 안국에서 만나 볼 수 있습니다. 눈길을 사로잡는 예쁜 진열과 먹음직스러운 스콘, 베이커리, 케이크들은 저절로 카메라를 들게 합니다. 카페 레이어드만의 분위기 있는 진열 소품들과 조명이 디저트들의 비주얼을 더욱 높여줍니다. 바삭한 반죽 안에 크림치즈로 가득한 크랜베리 크림치즈 스콘, 흑임자와 앙버터가 만나 색다른 맛을 느끼게 해주는 흑임자 앙버터 스콘 등 스콘의 담백함을 만끽할 수 있는 다양한 메뉴들이 있습니다.', 37.577737, 126.985932, '', '지하철3호선 안국역 2번 출구, 64m', '플레인 홈메이드 스콘 4,800원\n딸기 스콘 5,200원\n얼그레이 스콘 5,200원\n블루베리 스콘 5,200원', '', ' https://www.instagram.com/cafe_layered', '카페, 디저트', '', '매일 08:00 ~ 22:00', '', ''),
	(643, '비하인드', '04048  서울특별시 마포구 어울마당로5길 18 (서교동)', 'images/비하인드_643.jpg', '온, 오프라인으로 프리 마켓도 열고 종종 전시회도 여는 홍대앞스러운 곳. 이탈리아 원두 몰리나리를 사용하여 갓 뽑아낸 에스프레소를 바닐라 아이스크림에 부어 떠먹는 아포가토 알 카페가 독특한 메뉴. 분위기가 좋아 연인들의 데이트 장소로도 유명.\n\n온, 오프라인으로 프리 마켓도 열고 종종 전시회도 여는 홍대앞스러운 곳입니다. 이탈리아 원두 몰리나리를 사용하여 갓 뽑아낸 에스프레소를 바닐라 아이스크림에 부어 떠먹는 아포가토 알 카페가 독특한 메뉴입니다. 분위기가 좋아 연인들의 데이트 장소로도 유명합니다.', 37.549304, 126.919660, '1만원대', '지하철 6호선 상수역 1번 출구, 436m', '', '월요일~일요일', '', '카페, 디저트', '', '13:00~22:00', '02-3141-7212', '명절 휴무'),
	(644, '콜린', '04048  서울 마포구 어울마당로 45 (서교동)', 'images/콜린_644.jpg', '꽃향기와 달달한 디저트 냄새로 가득한 플라워 카페 콜린. 향기로운 꽃과 맛있는 디저트를 함께 즐기고 싶다면 콜린을 추천.\n\n꽃집을 함께 운영하는 플라워 카페답게 들어가는 입구부터 꽃향기가 가득한 카페 콜린.\n다양한 꽃과 식물들로 몸과 마음을 힐링을 하였다면 콜린의 시그니처 메뉴인 대왕 솜사탕이 올라간 코튼 라떼와, 다양한 빙수들로 입 안도 힐링 해보세요.', 37.549224, 126.920419, '1만원대', '지하철6호선 상수역 1번 출구, 392m', '', '매일', ' https://www.instagram.com/colline_cafe/', '카페, 디저트', '', '일요일~목요일 10:30 ~ 23:00\n금요일~토요일 10:30 ~ 24:00', '0507-1335-1119', ''),
	(645, '로즈힐', '06236  서울 강남구 테헤란로 152 (강남파이낸스센터)  지하 1층', 'images/로즈힐_645.jpg', '등심과 갈비구이를 중심으로 하는 퓨전 한식 레스토랑.\n\n등심과 갈비구이를 중심으로 하는 퓨전 한식 레스토랑을 표방하고 있습니다. 30여 가지 단품 메뉴와 정식 코스요리가 준비되어 있으며 그중 코냑 등심은 한국식 등심구이에 코냑 소스가 결합한 독특한 메뉴입니다. 와인 바를 연상시키는 모던하고 세련된 인테리어가 돋보입니다.', 37.500024, 127.036509, '3만원대', '지하철 2호선 역삼역 2번 출구, 27m', '코스 10만원~15만원 외', '월요일~금요일', ' http://www.irosehill.co.kr', '음식점', '', '11:30 ~ 15:00 / 17:00 ~ 22:00', '0507-1383-2091', '토요일, 일요일 휴무'),
	(646, '뚜르뒤뱅', '06576  서울 서초구 사평대로22길 55 (반포동, 대선빌딩)', 'images/뚜르뒤뱅_646.jpg', '5백여 종의 와인과 치즈, 샐러드, 스파게티가 준비되어 있는 곳. 시중에서 만나볼 수 없는 이색적인 와인.\n\n5백여 종의 와인과 치즈, 샐러드, 스파게티가 준비되어 있는 곳으로, 시중에서 만나볼 수 없는 이색적인 와인이 꽤 있습니다. 옆에는 테이블이 있어 직접 고른 와인을 바로 마실 수 있습니다.', 37.497083, 126.997797, '', '지하철 9호선 신반포역 4번 출구, 862m', '와인바', '월화수목금토일', '', '술집, 바', '', '월~토 13:00 ~ 01:00 / 일 13:00 ~ 22:00', '02-6941-1846', '명절 당일'),
	(647, '와플하우스', '04313  서울 용산구 청파로45길 37 (청파동2가)', 'images/와플하우스_647.jpg', '15년이 넘게 와플과 빙수를 만들어 내는 곳. 대표 메뉴는 와플.\n\n15년이 넘게 와플과 빙수를 만들어 내는 곳. 대표 메뉴는 와플. 기본 재료 12가지 이상을 섞어서 만들어내 도톰하고 촉촉합니다. 매시드 포테이토와 식빵 한쪽에 피망, 양파, 소고기 등으로 속을 넣고 반으로 접어 오븐에 구워낸 볼 샌드 등도 별미입니다.', 37.544461, 126.968543, '1만원대', '지하철 4호선 숙대입구역 9번 출구, 337m', '와플', '월화수목금토일', '', '카페, 디저트', '', '11:30~22:30', '02-711-2649', '연중무휴'),
	(648, '줄라이', '06589  서울 서초구 동광로 164 (줄라이빌딩)', 'images/줄라이_648.jpg', '신선한 한식 재료와 정통 프렌치 음식이 조화를 이루는 레스토랑.\n\n신선한 한식 재료와 정통 프렌치 음식이 조화를 이루는 레스토랑. 고급재료인 달팽이, 도미, 한우 안심 등을 이용한 요리와 은은한 조명이 잘 어우러진 곳으로 맛, 서비스, 분위기 모두 최상입니다. 2025년에 미쉐린 가이드에 선정되었습니다.', 37.494728, 126.999977, '', '지하철 2호선 서초역 5번 출구, 834m', '', '', ' https://catchtable.co.kr/july', '음식점', '', '12:00~15:00, 18:00~22:00', '02-534-9544', '매주 일요일, 월요일'),
	(649, '램하우스', '06596  서울특별시 서초구 법원로2길 15 (서초동)', 'images/램하우스_649.jpg', '양고기 전문점. 양 갈비구이, 양 곰탕, 수육, 전골 등.\n\n양고기 전문점으로, 육질이 부드러운 어린 양을 잘 숙성시켜 양 갈비구이, 양 곰탕, 수육, 전골 등으로 냅니다. 들깻가루를 듬뿍 넣은 양 곰탕과 수육은 식사로도 좋습니다. 매장이 아담하고 깔끔한 느낌입니다.', 37.494171, 127.012399, '', '지하철 2/3호선 교대역 10번 출구, 146m', '양갈비, 램꽃등심, 전골', '', '', '음식점', '', '평일 10:00~22:00 토요일 10:00~21:00', '02-3476-0678', '매주 일요일, 명절 휴무'),
	(650, '헤르지아', '04630  서울 중구 소파로 97 (예장동)', 'images/헤르지아_650.jpg', '스페인어로 해바라기라는 뜻의 이탈리안 레스토랑.\n\n스페인어로 해바라기라는 뜻의 이탈리안 레스토랑. 등심, 해물, 야채를 한데 섞어 소스를 넣고 볶은 데판야키도 좋습니다. 지하 1층은 커플석으로 되어 있고 롤 스크린을 치면 방해받지 않고 식사도 가능합니다. 2층은 명동, 남산의 야경을 즐기기에 좋습니다.', 37.556857, 126.985504, '', '지하철 4호선 명동역 3번 출구, 517m', '베이컨 까르보나라, 왕돈까스, 매운치즈돈까스, 함박스테이크', '연중무휴', '', '음식점', '', '매일 10:30 ~ 21:00', '02-319-5150', ''),
	(651, '손칼국수', '03076  서울 종로구 혜화로 10-5', 'images/손칼국수_651.jpg', '허름한 가정집 방안에 앉아 집에서 만든 듯한 칼국수를 맛보는 곳.\n\n가정집 방안에 앉아 집에서 만든 듯한 칼국수를 맛볼 수 있습니다. 사골 국물을 베이스로 한 칼국수에 전을 곁들이면 더욱 좋습니다. 저녁 6시면 영업을 하지 않으므로 가기 전에 확인이 필요합니다.', 37.587647, 126.999833, '1만원대', '지하철 4호선 혜화역 4번 출구, 393m', '칼국수, 생선전, 고추전, 빈대떡', '월요일~금요일', '', '음식점', '', '월요일~금요일 12:00~14:00', '02-764-7947', '주말, 명절 휴무'),
	(652, '뀌쏭82', '06302  서울 강남구 양재천로 167  아성빌딩 1층', 'images/뀌쏭82_652.jpg', '소프트 프렌치 퀴진을 콘셉트로 내세운 프랑스 레스토랑\n\n소프트 프렌치 퀴진을 콘셉트로 내세운 프랑스 레스토랑입니다. 서울에서 손꼽는 레스토랑에서 경력을 쌓은 김영원 셰프가 문을 연 곳으로, 프랑스 가정집에 온 듯한 편안한 공간에서 정통 프랑스 가정식을 즐길 수 있습니다. 프렌치 비스트로를 표방하면서도 가격이 저렴한 편이어서 오픈하자마자 많은 인기를 얻고 있습니다.', 37.481621, 127.044693, '', '지하철 3호선 매봉역 4번 출구, 741m', '암돼지삼겹살, 퐁피두(광어와 루꼴라)', '', '', '음식점', '', '화요일 17:50~22:00\n수요일~토요일 11:50~22:00\n일요일 11:50~21:30', '02-529-3582', '매주 월요일'),
	(653, '삼호짱뚱이', '06049  서울 강남구 도산대로34길 11', 'images/삼호짱뚱이_653.jpg', '남도 음식을 제대로 맛볼 수 있는 곳. 젓갈을 많이 쓰고 간이 센 남도의 맛.\n\n남도 음식을 제대로 맛볼 수 있는 곳으로, 젓갈을 많이 쓰고 간이 센 남도의 맛을 지키고 . 있습니다. 짱뚱어를 뼈째 갈아 우거지 등을 넣고 탕으로 끓여 먹거나, 통째로 끓이는 매운탕이 인기가 있습니다.', 37.519650, 127.031046, '', '지하철 7호선 학동역 10번 출구, 607m', '민도정식, 남도정식, 병어조림', '', ' http://삼호짱뚱이.kr/', '음식점', '', '매일 11:00 ~ 22:00\n(Break time 15:00~17:00)', '02-547-1416', '명절 휴무'),
	(654, '상락원', '06806  서울 서초구 원터길 23 (원지동)', 'images/상락원_654.jpg', '잔디밭과 정원이 어우러진 도심 속 고품격 한정식 전문점.\n\n도심 속 한국의 멋, 고품격 휴식 공간\n\n잔디밭과 정원이 어우러진 도심 속 고품격 한정식 전문점. 조용하고 넓은 정원, 가정집 같은 분위기에 엄마의 손맛을 느낄 수 있는 포근함이 있는 곳입니다. 산지에서 직송해오는 무공해 재료를 맛깔스런 손맛으로 버무려 전통 한정식의 진가를 높입니다.', 37.443141, 127.056146, '', '지하철 신분당선 청계산입구역 2번 출구, 618m', '청계밥상, 시래기돌솥밥, 돌솥밥, 고등어 정식', '', '', '음식점', '', '매일 09:00 ~ 21:00', '0507-1329-5220', '명절휴무'),
	(655, '더킹스', '04618  서울 중구 동호로 287 (장충동2가, 그랜드앰배서더서울)', 'images/더킹스_655.jpg', '150여 가지의 음식을 즉석에서 서빙해주는 뷔페\n\n라이브 쿠킹 개념을 도입하여 딤섬, 북경오리구이, 바비큐 등 150여 가지의 음식을 즉석에서 서빙해주는 뷔페입니다. 랍스터 등 신선한 해산물의 사용이 돋보입니다.', 37.560716, 127.002066, '', '지하철 3호선 동대입구역 6번 출구, 396m', '뷔페', '매일', ' https://www.instagram.com/theambassador_thekings/', '음식점', '', '아침 06:30 ~ 10:00\n점심 12:00 ~ 14:30\n저녁 18:00 ~ 21:30\n토요일 디너 1부 17:30 ~ 19:30, 2부 20:00 ~ 22:00', '02-2270-3121', '연중무휴'),
	(656, '극락돈 회기점', '02446  서울특별시 동대문구 회기로28길 8 (휘경동)', 'images/극락돈_회기점_656.jpg', '편백찜이 무료인 프리미엄 정육식당 극락돈\n\n무항생제 사료로 직접 키우고 직접 도축 가공하여 배송하는 최고의 위생관리 시스템 인증 HACCP을 보유한 극락돈에서 최고품질의 고기를 저렴한 가격으로 맛보세요', 37.589461, 127.055945, '', '지하철 1호선/경의중앙선/경춘선 회기역 1번 출구, 153m', '소고기구이', '월화수목금토일', '', '음식점', '', '11:00 ~ 22:00', '02-957-2266', '연중무휴'),
	(657, '갯마을', '04388  서울 용산구 서빙고로 56 (한강로3가)', 'images/갯마을_657.jpg', '이촌동에서는 꽤 유명해진 만두집. 개운한 김치만두가 유명.\n\n이촌동에서는 꽤 유명해진 만두집. 하루 동안 숙성시킨 김치를 넣은 개운한 맛의 김치만두가 유명합니다. 만두는 한입에 넣을 만큼 작게 만듭니다. 맷돌에 간 녹두에 김치, 야채 등을 넣어 바삭하게 구운 녹두부침도 맛있습니다. 친절함이 돋보입니다.', 37.523042, 126.970305, '1만원대', '지하철 4호선/ 경의중앙선 이촌역 5번 출구, 227m', '만두, 녹두부침개, 만둣국, 떡만둣국, 모둠전, 만두전골', '월요일~일요일', '', '음식점', '', '09:30 ~ 15:00 / 17:00 ~ 21:00', '02-795-2277', '명절 당일 휴무'),
	(658, '함초간장게장', '04537  서울 중구 명동8가길 27 (충무로2가)  지하 1층', 'images/함초간장게장_658.jpg', '다양한 방송매체에 소개된 간장게장, 해물요리 한식당.\n\n다양한 방송매체에 소개된 간장게장, 해물 요리 한식당입니다. 함초를 발효시켜 만든 간장을 사용한 간장 게장이 인기메뉴입니다. 매장은 한국적인 분위기로, 외국인 관광객도 많이 찾아 메뉴판에 중국어, 일본어 음식 표기와 영어 음식 설명이 되어 있습니다.', 37.562001, 126.986564, '', '지하철 4호선 명동역 9번 출구, 139m', '전복장, 간장게장정식', '', ' https://www.hamchogejang.com/', '음식점', '', '매일 11:30 ~ 22:00', '02-318-1624', ''),
	(659, '미엘', '06016  서울특별시 강남구 도산대로67길 13-12 (청담동)', 'images/미엘_659.jpg', '미술전시관과 카페가 만난 스타일리시한 카페. 화이트를 소재로 한 실내 분위기가 밝고 멋스러움. 와플, 샌드위치 등의 가벼운 디저트 류도 인기.\n\n미술전시관과 카페가 만난 스타일리시한 카페. 화이트를 소재로 한 실내 분위기가 밝으면서도 멋스럽습니다. 와플, 샌드위치 등의 가벼운 디저트 류도 인기가 있습니다.', 37.525258, 127.043625, '3만원대', '지하철 수인분당선 압구정로데오역 3번 출구, 453m', '', '월요일~일요일', ' https://www.instagram.com/miel07_official', '음식점', '', '10:00~23:50', '0507-1351-2395', '연중무휴'),
	(660, '신흥정육식당', '06199  서울 강남구 역삼로 406', 'images/신흥정육식당_660.jpg', '대치사거리 정육 식당 골목에서 가볼 만한 곳.\n\n대치사거리 정육 식당 골목에서 가볼 만한 곳. 등심을 전문으로 하며 철판을 달구어 우지를 넣은 후 고기를 굽는 것이 특징입니다. 공간은 협소하지만, 회식자리로도 많이 찾는 곳입니다.', 37.499555, 127.047845, '2만원대', '지하철 2호선/ 수인분당선 선릉역 2번 출구, 480m', '등심, 육회, 차돌백이, 제육볶음', '', '', '음식점', '', '월요일~토요일 12:00 ~ 22:00', '02-555-8157', '매주 일요일, 명절 휴무'),
	(661, '와세다야', '04425  서울특별시 용산구 이촌로88길 3 (이촌동)', 'images/와세다야_661.jpg', '일본식 숯불구이인 야키니쿠 전문점.\n\n일본식 숯불구이인 야키니쿠 전문점. 야키니쿠는 한국의 불고기를 일본인 입맛에 맞게 변형시킨 것입니다. 다진 파와 참기름, 소금을 얹은 우설구이와 파, 참기름, 소금으로만 무친 처녑 사시미가 추천 메뉴. 꽃등심, 갈비, 생등심, 항정살 등도 맛볼 수 있습니다.', 37.518029, 126.978695, '', '지하철 4호선/ 경의중앙선 이촌역 3-1번 출구, 654m', '특상우설, 천엽사시미, 안심, 항정살소금구이', '', ' http://wasedaya.co.kr/', '음식점', '', '월요일~토요일 16:30~23:00, 일요일 16:00~22:00', '02-796-0608', '명절 휴무'),
	(662, '설눈', '06647  서울 서초구 서초대로46길 20-7 (서초동, 영토빌딩)', 'images/설눈_662.jpg', '설눈은 한국의 전통 음식 평양냉면 전문점\n\n설눈은 한국의 전통 음식 평양냉면 전문점입니다. 북한에서 이주해 온 평양 고려호텔 요리사가 직접 음식을 만들어 서울에서 북한 음식을 즐길 수 있습니다. 평양냉면 외에도 만두, 녹두전, 수육 등은 이미 맛있기로 소문나 있으며 티비 프로그램에 소개된 바도 있습니다.', 37.491233, 127.009768, '', '지하철 2호선 서초역 1번 출구, 206m', '고려 물냉면, 평양온반, 평양육개장, 소고기 수육, 왕만두', '일요일~금요일', '', '음식점', '외국어 해설 가능', '매일 11:00 ~ 15:00 / 17:00 ~ 21:00', '02-6959-9339', '토요일'),
	(663, '와인나라', '06577  서울 서초구 서래로8길 1 (반포동)', 'images/와인나라_663.jpg', '프리미엄 와인 셀렉샵, 지하 1층 와인 클래스 및 공간대여 가능\n\n서래마을 초입에 있는 프리미엄 와인 셀렉샵, 지하 1층 와인 클래스 및 공간대여가 가능합니다.', 37.498746, 126.998572, '', '지하철 3/7/9호선 고속터미널역 5번 출구, 779m', '와인바', '', ' http://www.winenara.com/', '술집, 바', '', '월요일~금요일 10:00 ~ 21:00\n토요일 11:00 ~ 20:00\n일요일 11:00~19:00', '02-592-9035', ''),
	(664, '차크라', '04419  서울특별시 용산구 독서당로 83 (한남동)', 'images/차크라_664.png', '탄두리 치킨, 양고기 케밥, 5가지 종류의 커리등 인도 정통식.\n\n탄두리 치킨, 양고기 케밥, 5가지 종류의 커리와 무한 리필되는 난과 쌀밥 등을 맛볼 수 있습니다. 빈대떡처럼 팬에 지져 먹는 우타팜과 도사를 인도 정통식으로 먹을 수 있습니다. 바삭한 맛의 삼발 반다도 인기 메뉴. 직장인들을 위한 점심 뷔페도 마련되어 있습니다.', 37.534497, 127.009684, '2만원대', '지하철 경의중앙선 한남역 1번 출구, 758m', '치킨 마크니, 탄두리 세트, 야채 커리', '', ' http://www.chakraa.co.kr/', '음식점', '', '주중 11:30~16:00, 17:00~22:00\n주말 11:30~22:00', '02-796-1149', '연중무휴'),
	(665, '부산복집', '04554  서울 중구 수표로2길 25 (충무로3가)', 'images/부산복집_665.jpg', '저렴하면서도 각별한 맛을 내는 곳으로 소문이 난 복집.\n\n저렴하면서도 각별한 맛을 내는 곳으로 소문이 난 곳입니다. 미나리와 콩나물을 듬뿍 넣고 마늘을 많이 넣은 얼큰한 국물 맛이 좋습니다. 저녁에는 복불고기에 소주 한 잔도 좋습니다. 30년 전통을 자랑합니다.', 37.562296, 126.991943, '2만원대', '지하철 3/4호선 충무로역 6번 출구, 188m', '복매운탕, 복지리, 복불고기', '', '', '음식점', '', '평일 10:00~21:30 (브레이크타임 15:00~17:00)\n주말 10:00~21:00', '0507-1317-6334', ''),
	(666, '삼일정육식당', '06775   서울 서초구 언남17길 14', 'images/삼일정육식당_666.jpg', '신선한 고기를 바로 구워서 먹는 곳. 소고기, 돼지불백.\n\n신선한 고기를 바로 구워서 먹는 곳. 저녁때는 차돌박이, 등심 등 소고기를 구워 먹기에 좋고 점심때는 돼지불백이 인기가 높습니다.', 37.475909, 127.045344, '2만원대', '지하철 신분당선 양재시민의숲역 2번 출구, 935m', '등심, 차돌박이, 삼겹살, 목살', '', '', '음식점', '', '월요일~토요일 11:00~22:00', '02-576-8592', '일요일 휴무'),
	(667, '흥진옥', '03156  서울특별시 종로구 종로5길 19-12 (청진동)', 'images/흥진옥_667.jpg', '청진동을 대표하는 해장국집. 40년 전통의 경상도식 해장국.\n\n청진동을 대표하는 해장국집중 하나로, 40년 전통의 경상도식 해장국을 맛볼 수 있습니다. 처녑, 내포, 선지가 가득 들어가 있고, 소뼈를 우려낸 국물에 배추와 우거지, 콩나물 등이 가득 들어가 있어 묵직하면서도 시원스러운 맛이 나는 스타일의 해장국입니다. 깔끔한 맛은 아니어도 깊고 진한 맛을 냅니다.', 37.571399, 126.980273, '1만원대', '지하철 1호선 종각역 1번 출구, 282m', '선지해장국', '월화수목금토', '', '음식점', '', '평일 10:00 ~ 15:00 / 17:00 ~ 21:00\n토요일 10:00 ~ 17:00', '02-732-2214', '일요일 휴무'),
	(668, '르브런쉭', '06028  서울 강남구 강남대로162길 41-22 (신사동)', 'images/르브런쉭_668.jpg', '브런치를 즐길 수 있는 프랑스 레스토랑. 편안한 분위기에서 수준급의 브런치.\n\n브런치를 즐길 수 있는 프랑스 레스토랑. 편안한 분위기에서 수준급의 브런치를 먹을 수 있습니다.', 37.522071, 127.021067, '', '지하철 3호선/신분당선 신사역 6번 출구, 742m', '에그 베네딕트, 아보카도에그슬럿, 프렌치 토스트, 만조리가토니', '매일', '', '음식점', '', '10:00~20:30', '0507-1399-1985', '명절 당일'),
	(669, '사리원', '06296  서울특별시 강남구 남부순환로 2712 (도곡동)', 'images/사리원_669.jpg', '당뇨병으로 고생하던 남편을 위해 할머니가 손수 개발한 불고기를 맛볼 수 있는 곳.\n\n3대째 내려오는 손맛과 최첨단 시설과의 조화\n\n\n당뇨병으로 고생하던 남편을 위해 할머니가 손수 개발한 불고기를 맛볼 수 있는 곳. 설탕과 조미료를 넣지 않고 12가지의 과일과 채소즙(파인애플, 사과, 오렌지, 샐러리, 양파, 키위, 배즙 등)으로 만든 소스에 찍어 먹는 고기의 맛이 입안에서 살살 녹습니다.', 37.485404, 127.042646, '3만원대', '지하철 3호선 매봉역 4번 출구, 324m', '사리원 불고기, 등심 양념불고기, 불고기 쌈밥정식', '', ' http://www.sariwon.co.kr/', '음식점', '', '매일 11:30~21:30', '02-573-2202', '연중무휴'),
	(670, '참설농탕', '06729  서울특별시 서초구 효령로 424 (서초동)', 'images/참설농탕_670.jpg', '국내산 냉장 양지와 사골을 12시간 이상 우려낸 후 양지 삼겹을 고아 맛이 부드럽고 깔끔.\n\n국내산 냉장 양지와 사골을 12시간 이상 우려낸 후 엄선된 양지 삼겹 부위를 숙성시킨 후 6시간 동안 정성스럽게 고아 맛이 부드럽고 깔끔합니다. 꼬리는 얇게 쪼개지 않고 토막으로 나오는데 그 맛 또한 일품입니다.', 37.488783, 127.030276, '1만원대', '지하철 3호선/ 신분당선 양재역 2번 출구, 620m', '설렁탕', '월요일~일요일', '', '음식점', '', '24시간 영업', '02-3471-2488', '연중 무휴'),
	(671, '마리모', '06019  서울특별시 강남구 도산대로49길 10-1 (신사동)', 'images/마리모_671.jpg', '두부요리를 전문으로 하는 이자카야로, 가볍게 사케를 즐길 수 있는 곳\n\n두부요리를 전문으로 하는 이자카야로, 가볍게 사케를 즐길 수 있는 곳입니다. 기본적인 메뉴들의 맛이 훌륭하며, 항상 새로운 프로모션을 진행하고 있어 사람들이 많이 찾고 있습니다.', 37.523779, 127.037536, '', '지하철 수인분당선 압구정로데오역 5번 출구, 480m', '교자탕, 오뎅탕, 알탕, 회덮밥', '', '', '음식점', '', '매일 18:00 ~ 04:00', '02-545-5885', '명절 휴무'),
	(672, '테이블에이', '04059  서울 마포구 와우산로 146 (창전동, 그레이스빌딩)', 'images/테이블에이_672.jpg', '귀여운 동물들을 직접 만져볼 수 있는 카페\n\n홍대에서 이색데이트를 즐길 수 있는 이곳은 귀여운 동물들을 직접 만질 수 있는 카페입니다.고양이, 라쿤, 미어캣 등 여러 동물들이 있으며 파충류들도 직접 만져볼 수 있습니다.', 37.554061, 126.929517, '', '지하철2호선/ 공항철도/경의중앙선 홍대입구역 6번 출구 , 470m', '', '', ' https://tableazoo.modoo.at/', '카페, 디저트', '', '매일 12:00 ~ 22:00', '02-324-5542', ''),
	(673, '리틀사이공', '06017  서울특별시 강남구 언주로174길 26 (신사동)', 'images/리틀사이공_673.jpg', '소고기가 들어간 진한 국물에 쌀국수를 넣은 베트남 쌀국수를 맛볼 수 있는 곳.\n\n소고기가 들어간 진한 국물에 쌀국수를 넣은 베트남 쌀국수를 맛볼 수 있는 곳. 신선한 속 재료가 푸짐하게 나오는 월남 쌈과, 쌀 피에 돼지고기와 채소를 넣고 말아낸 것을 기름에 튀겨낸 차조가 인기 메뉴입니다. 국물이 없는 요리는 포장도 가능합니다.', 37.527968, 127.035856, '1만원대', '지하철 수인분당선 압구정로데오역 6번 출구, 449m', '고이꾸온, 짜죠, 꼼징능주, 분짜', '', ' http://littlesaigon.co.kr/', '음식점', '', '월요일~일요일 11:30~22:00', '02-547-9050', '명절 휴무'),
	(674, '카페 레이어드 더현대서울점', '07335  서울 영등포구 여의대로 108 (여의도동, 파크원)  더현대서울 지하 1층', 'images/카페_레이어드_더현대서울점_674.jpg', '담백하게 구워낸 다양한 종류의 스콘으로 유명한 카페 레이어드\n\n담백하게 구워낸 다양한 종류의 스콘으로 유명한 카페 레이어드는 더현대서울 식품관 테이스티서울에서 만나 볼 수 있습니다. 눈길을 사로잡는 예쁜 진열과 먹음직스러운 스콘, 베이커리, 케이크들은 저절로 카메라를 들게 합니다. 카페 레이어드만의 분위기 있는 진열 소품들과 조명이 디저트들의 비주얼을 더욱 높여줍니다. 바삭한 반죽 안에 크림치즈로 가득한 크랜베리 크림치즈 스콘, 흑임자와 앙버터가 만나 색다른 맛을 느끼게 해주는 흑임자 앙버터 스콘 등 스콘의 담백함을 만끽할 수 있는 다양한 메뉴들이 한가득합니다.', 37.525191, 126.929113, '', '지하철5호선 여의나루역 1번 출구 , 312m', '바질 스콘 5,300원\n갈릭 크림 스콘 5,500원\n딸기 스콘 5,200원', '매일', ' https://www.instagram.com/cafe_layered/', '카페, 디저트', '', '월요일-목요일 10:30 ~ 20:00\n금요일-일요일 10:30 ~ 20:30', '02-3277-8551', ''),
	(675, '히말라야 종각점', '03189  서울 종로구 종로8길 5 (관철동)  2층', 'images/히말라야_종각점_675.jpg', '히말라야는 캐주얼한 인도요리 전문점.\n\n히말라야는 캐주얼한 인도요리 전문점입니다. 인도, 네팔음식을 먹을 수 있으며 향신료를 많이 사용하는 인도, 네팔 음식이지만 한국인들도 부담 없이 먹을 수 있는 곳입니다.', 37.569765, 126.984087, '', '지하철 1호선 종각역 4번 출구, 44m', '난, 커리', '매일', ' https://www.instagram.com/_himalaya.official', '음식점', '', '매일 10:00 ~ 22:00\n(15:00~ 17:00 휴게시간)', '02-720-4786', ''),
	(676, '마차횟집', '04077  서울 마포구 토정로 155 (하중동)', 'images/마차횟집_676.jpg', '가격대비 만족도가 높은 자연산 회와 해물을 즐길 수 있는 곳.\n\n자연산 회와 해물을 즐길 수 있는 곳. 고급스러운 분위기는 아니지만, 가격 대비 만족도가 높습니다. 실내는 넓지는 않지만 깔끔한 편이며, 메뉴는 양식과 자연산으로 나뉘어 있는데 약간의 가격 차가 납니다.', 37.545789, 126.928274, '', '지하철 6호선 광흥창역 6번 출구, 375m', '잡어모둠\n오늘의 활어(1인)\n정식', '월요일~일요일', '', '음식점', '', '평일 11:30 ~ 13:30 / 17:00 ~ 22:00\n주말 11:30 ~ 22:00', '02-323-6735', '명절 휴무'),
	(677, '깔리', '03079  서울 종로구 대학로11길 43 (명륜4가)  2층', 'images/깔리_677.jpg', '깔리는 인도에서 직접 초빙한 현지인 요리사들이 조리하는 인도 음식 전문점.\n\n깔리는 인도에서 직접 초빙한 현지인 요리사들이 조리하는 인도 음식 전문점입니다. 브레이크 타임 직후에 가도 웨이팅이 있을 정도로 인기를 자랑합니다.   수년간 직접 인도, 네팔, 티벳을 배낭여행하며 모았다는 장식물들로 꾸며져 있어 이국적인 느낌을 줍니다.', 37.582462, 126.999237, '', '지하철 4호선 혜화역 4번 출구, 273m', '', '', '', '음식점', '', '매일 11:30 ~ 15:40 / 17:00 ~ 21:10', '02-747-5050', ''),
	(678, '신사면옥', '06054  서울 강남구 도산대로46길 11 (논현동, 논현오피스텔)', 'images/신사면옥_678.jpg', '매콤달콤한 양념과 쫄깃한 면발로 사랑받는 냉면 전문점.\n\n매콤달콤한 양념과 쫄깃한 면발로 사랑받는 냉면 전문점입니다. 중독성 강한 맛으로 단골이 많아 점심 시간에는 기다려야 하는 일도 종종 있습니다. 푸짐한 만두와 불고기도 맛있습니다.', 37.521274, 127.036644, '2만원대', '지하철 7호선/ 수인분당선 강남구청역 3-1번 출구, 794m', '한우암소생등심, 한우암소생등심불고기, 한우갈비탕, 참숯불돼지갈비, 회냉면', '', '', '음식점', '', '매일 11:00 ~ 22:00', '02-518-7228', '연중무휴'),
	(679, '삼오쭈꾸미', '03739  서울특별시 서대문구 통일로 107-19 (미근동)', 'images/삼오쭈꾸미_679.jpg', '30년 넘은 주꾸미 요리. 고추장 양념에 버무려 불판에 구워 먹는 주꾸미.\n\n30년 가까이 주꾸미 요리를 내놓는 집입니다. 주꾸미는 벌교 출신의 주인이 남해안에서 가져옵니다. 고추장 양념에 버무려 불판에 구워 먹는 주꾸미가 고소하면서도 쫄깃합니다. 저렴한 가격에 만족도가 높습니다.', 37.564240, 126.967121, '1만원대', '지하철 5호선 서대문역 7번 출구, 181m', '', '월요알~금요일', '', '음식점', '', '11:30 ~ 14:00 / 17:00 ~ 22:00', '02-362-2120', '매주 토요일, 일요일, 공휴일 휴무'),
	(680, '영월', '03708  서울 서대문구 연희로 81-21 (정암빌딩)', 'images/영월_680.jpg', '낙지와 새우가 들어간 해물찜 형식의 낙새찜이 인기메뉴.\n\n가격대비 담백하고 깔끔한 음식들이 괜찮습니다. 낙지와 새우가 들어간 해물찜 형식의 낙새찜이 인기메뉴입니다. 칼국수, 수제비, 보리밥도 간단한 식사로 괜찮습니다.', 37.565839, 126.928938, '1만원대', '지하철 2호선 홍대입구역 3번 출구, 1km', '수제비,감자옹심이,아귀탕, 보쌈', '', '', '음식점', '', '매일 11:00 ~ 22:00', '02-323-4256', '명절 휴무'),
	(681, '강가 무교점', '04520  서울 중구 세종대로 136 (태평로1가, 파이낸스빌딩)', 'images/강가_무교점_681.jpg', '강가는 정통 인도 레스토랑.\n\n강가는 정통 인도 레스토랑입니다. 20년 이상 정통 인도 요리 경력을 가지고 있는 일류 요리사들이 최고의 인도 요리를 선사하며, 편리한 접근성으로 많은 사랑을 받고 있습니다.', 37.568354, 126.978018, '', '지하철 5호선 광화문역 5번 출구, 172m', '탄두리 치킨 26,500원\n팔락 파니르 24,500원\n치킨 마크니 23,500원\n프로운 칠리 25,500원', '매일', ' http://www.ganga.co.kr', '음식점', '', '평일 11:30~15:00, 17:00~21:0\n주말 11:30~15:00, 17:00~20:30', '02-3783-0610', ''),
	(682, '벨라프라하', '03766  서울특별시 서대문구 이화여대길 77 (대현동)', 'images/벨라프라하_682.jpg', '핸드드립 커피와 뜨르들르를 맛볼 수 있는 것으로 명소가 된 곳. 에스프레소, 핸드드립, 융드립, 싸이폰, 더치커피 등 취향대로 커피 스타일을 정할 수 있는 것이 장점. 뜨르들르는 밀가루 반죽을 쇠로 된 봉에 감아서 불에 구워낸 빵의 일종. 체코에서 가져온 아기자기한 소품.\n\n핸드드립 커피와 뜨르들르를 맛볼 수 있는 것으로 명소가 된 곳. 에스프레소, 핸드드립, 융드립, 싸이폰, 더치커피 등 취향대로 커피 스타일을 정할 수 있는 것이 장점입니다. 뜨르들르는 밀가루 반죽을 쇠로 된 봉에 감아서 불에 구워낸 빵의 일종입니다. 체코에서 가져온 아기자기한 소품이 눈길을 끌어요.', 37.559068, 126.944150, '1만원대', '지하철 2호선 이대역 2번 출구, 385m', '', '월요일~토요일', '', '카페, 디저트', '', '11:00 ~ 22:00', '0507-1319-3559', '매주 일요일, 명절 휴무'),
	(683, '우리밀국시', '02880  서울 성북구 혜화로 84-2 (성북동)', 'images/우리밀국시_683.jpg', '사골칼국수 전문점으로, 한우 사골로 우려낸 국물 맛이 일품.\n\n사골칼국수 전문점으로, 한우 사골로 우려낸 국물 맛이 좋습니다. 일반 칼국수보다 가는 면발은 쫄깃한 맛을 느낄 수 있습니다. 양지머리와 애호박을 고명으로 올린 칼국수에 매콤한 양념장을 얹어 먹습니다.', 37.592700, 126.998449, '1만원대', '지하철 4호선 한성대입구역 5번 출구, 840m', '칼국수', '매일', '', '음식점', '', '월요일~일요일 10:00~21:00 (16:00~17:00 브레이크타임)', '02-745-3764', '명절 휴무'),
	(684, '청', '04419  서울특별시 용산구 한남대로20길 47-24 (한남동)  리플레이스 D동 2층', 'images/청_684.jpg', '중식을 기본으로 하고 서양식 터치를 가미한 퓨전 중식.\n\n중식을 기본으로 하고 서양식 터치를 가미한 퓨전 중식을 냅니다. 흑식초 안심 스테이크 등이 독특한 메뉴입니다.', 37.535367, 127.010053, '', '지하철 경의중앙선 한남역 1번 출구, 902m', '해삼탕, 왕새우, 삼선 자장면', '', ' https://www.instagram.com/chung.hannam?igsh=bHhoc2hlZm9yODNr', '음식점', '', '매일 11:30~15:00 (Last order 14:30) / 17:30~22:00 (Last order 21:30)', '02-720-3396', '명절 휴무'),
	(685, '차이린', '06086  서울특별시 강남구 삼성로112길 10 (삼성동)', 'images/차이린_685.jpg', '깨끗한 실내 분위기에 음식도 전반적으로 깔끔한 중식당.\n\n깨끗한 실내 분위기에 음식도 전반적으로 깔끔한 편입니다. 동네 중식당이라기에는 한층 업그레이드된 곳입니다. 단품으로 간단하게 먹는 것도 좋지만, 코스요리가 더 인기있습니다.', 37.514649, 127.053294, '', '지하철 9호선 삼성중앙역 3번 출구, 116m', '마파두부, 꿔바로우, 양장피, 구수계', '매일', '', '음식점', '', '평일 11:30~15:00 / 17:00~21:30\n주말 11:30~21:30', '02-543-2847', '연중무휴'),
	(686, '영동족발', '06738  서울특별시 서초구 남부순환로 2628-18 (양재동)', 'images/영동족발_686.jpg', '30여 년 전통의 족발 집. 놀부만두, 성수족발과 서울의 3대 족발 집.\n\n30여 년 전통의 족발 집. 놀부만두, 성수족발과 함께 서울의 3대 족발 집 중 하나도 불립니다. 짭조름하면서 부드럽고, 두툼한 고기가 맛있습니다.', 37.484235, 127.038322, '2만원대', '지하철 3호선/ 신분당선 양재역 5번 출구, 375m', '', '매일', '', '음식점', '', '평일 12:00~23:00, 토요일 11:30~22:00, 일요일 11:30~21:00', '0507-1426-0250', ''),
	(687, '송백식당', '03173  서울특별시 종로구 새문안로5길 37 (도렴동)', 'images/송백식당_687.jpg', '햄과 소시지가 푸짐하게 들어가 있는 부대찌개 맛집\n\n부대찌개로 유명한 곳. 다른 부대찌개 식당보다 햄과 소시지가 푸짐하게 들어가 있으며 밥, 라면은 무제한 리필됩니다. 콩나물을 넣어 개운한 맛을 더했습니다. 버터를 녹인 철판에 소시지, 햄, 베이컨을 신김치와 함께 볶아 먹는 것도 별미입니다.', 37.573678, 126.974179, '', '지하철 5호선 광화문역 1번 출구, 204m', '부대찌개, 모듬 철판요리, 스테이크', '월~토', '', '음식점', '', '매일 11:00 ~ 21:30', '02-738-1386', '일요일, 명절 휴무'),
	(688, '아지겐', '04423  서울 용산구 이촌로75길 22 (이촌동)', 'images/아지겐_688.jpg', '일식 튀김과 오뎅에 술 한잔을 걸치기 좋은 곳. 일본인이 운영하는 식당.\n\n일식 튀김과 오뎅에 술 한잔을 걸치기 좋은 곳. 일본인이 운영하는 식당으로, 일본인들이 주 고객입니다. 닭고기를 바삭하게 튀긴 치킨 가라아게나 녹말 옷을 입혀 살짝 튀긴 두부에 간장 소스를 끼얹은 아게다시도후 같은 튀김 요리가 일품입니다.', 37.520780, 126.974503, '2만원대', '지하철 4호선/ 경의중앙선 이촌역 3-1번 출구, 206m', '게살오믈렛, 두부튀김, 카타야끼소바, 부추고기볶음', '', '', '음식점', '', '11:30 ~ 14:30 / 17:30 ~ 21:30', '02-794-8177', '매주 일요일'),
	(689, '마도', '07332  서울 영등포구 의사당대로1길 11 (여의도동, 메종리브르오피스텔)', 'images/마도_689.jpg', '다양한 볶음우동으로 유명한 곳.\n\n다양한 볶음우동으로 유명한 곳입니다. 볶을 때 들어가는 재료에 따라 해물 볶음우동, 소고기 볶음우동 등이 있습니다. 마늘, 양파, 대파를 굽고 다시마와 무 등으로 진하게 끓여낸 소스와 가쓰오부시, 우동 면발이 조화를 이룹니다.', 37.519212, 126.928582, '1만원대', '지하철 9호선/ 신림선 샛강역 1번 출구, 210m', '해물야끼우동, 소고기야끼우동, 알밥', '', '', '음식점', '', '매일 11:30 ~ 22:00', '02-784-2660', '공휴일 휴무'),
	(690, '청일집', '03345  서울 은평구 통일로 850 (불광동, 연서시장)  연서시장 A동 1층 24호', 'images/청일집_690.jpg', '바삭바삭한 빈대떡과 족발이 유명.\n\n바삭바삭한 빈대떡과 족발이 유명합니다. 녹두 간 것을 먼저 철판 위에 올린 후 고기, 김치 등의 재료를 고명처럼 얹어내는 것이 특징입니다.', 37.619320, 126.921445, '2만원대', '지하철 3/6호선/gtx a 연신내역 2번 출구, 12m', '빈대떡', '월요일~일요일', '', '음식점', '', '평일 10:00~23:00\n주말 11:00~23:00', '02-732-2626', '명절 휴무'),
	(691, '서석대', '06631  서울특별시 서초구 서초대로 346, 동아빌라드 1층 (서초동)', 'images/서석대_691.jpg', '서석대\'는 광주 무등산 정상에 있는 바위이름. 전라도 한우 생고기 참숯불 전문점.\n\n\'서석대\'란, 광주 무등산 정상에 있는 바위이름입니다. 전라도산 한우 생고기를 직접 배송하여 참숯불에 직접 굽기에 고기 특유의 고소한 맛과 향을 느낄 수 있습니다.', 37.495098, 127.019422, '3만원대', '지하철2/3호선 교대역 1번 출구, 406m', '한우꽃등심, 한우육회, 갈낙탕, 서석대정식', '월요일~일요일', ' http://www.seoseokdae.com', '음식점', '', '평일 11:30 ~ 15:00 / 17:00 ~ 22:00\n주말 11:30 ~ 22:00', '02-537-0077', '명절 당일 휴무'),
	(692, '카페 봇봇봇', '04797  서울 성동구 아차산로9길 8 (성수동2가)', 'images/카페_봇봇봇_692.jpg', '사람과 로봇이 함께하는 감성테크 플레이스\n\n로봇이 드립 커피를 내려주고, 내가 선택한 그림을 케이크 위에 그려주고, 시그니처 칵테일도 만들어 줍니다. 로봇뿐만 아니라 벽면을 가득 채운 미디어아트까지 더해져 봇봇봇만의 감성과 볼거리를 제공합니다. 넓은 실내 공간은 물론 테라스, 루프탑 야외 공간까지 있어 다양한 분위기를 느낄 수 있습니다.', 37.544761, 127.058199, '', '지하철 2호선 성수역 2번 출구, 158m', '로맨슈페너 BOT 6,500원\n라임 모히또 BOT 9,000원\n아이스 아메리카노 5,000원\n트리플 치즈 크로와상 10,000원', '임시휴업', ' http://www.instagram.com/_bot.bot.bot/', '카페, 디저트', '', '임시휴업', '02-499-9219', ''),
	(693, '라스텔라', '04168  서울특별시 마포구 마포대로 58 (도화동)  가든호텔', 'images/라스텔라_693.jpg', '한식, 중식, 일식, 양식 등의 고품격 요리를 맛볼 수 있는 뷔페 레스토랑\n\n한식, 중식, 일식, 양식 등의 고품격 요리를 맛볼 수 있는 뷔페 레스토랑입니다. 다양한 스테이크와 이탈리아 파스타 요리를 선보이며 2백여 종의 와인을 보유하고 있는 와인 바입니다. 바닷가재, 홍합, 대합, 오징어, 도미살 등 다양한 해산물이 풍부하게 들어가 있는 모둠 해산물 전채 요리가 추천 메뉴. 가든호텔 시절부터 이탈리아 현지인 주방 스태프들이 프레시면으로 만든 파스타를 선보이고 있습니다.', 37.540684, 126.948361, '', '지하철 5호선 마포역 3번 출구, 192m', '뷔페', '', ' http://seoulgarden.co.kr/', '음식점', '', '아침 07:00 - 09:30\n점심 11:30 - 14:00\n저녁 18:00 - 21:00', '0507-1448-7272', '연중무휴'),
	(694, '고바우', '03776  서울특별시 서대문구 명물1길 22 (창천동)', 'images/고바우_694.jpg', '한우나 돼지고기에 소금을 뿌려 숯불에 구워 먹는 곳.\n\n예전에는 연탄불 위에 철판을 놓고 고기를 구워 먹었으나 지금은 한우나 돼지고기에 소금을 뿌려 숯불에 구워 먹는 곳으로 유명합니다. 저녁때면 술 한잔 걸치려는 사람들로 붐비며, 신촌 대학가의 낭만을 반영하는 곳이기도 합니다.', 37.558404, 126.937326, '2만원대', '지하철 2호선 신촌역 3번 출구, 342m', '돼지소금구이, 돼지갈비, 한우, 껍데기', '', '', '음식점', '', '16:00 ~ 23:00', '02-393-2576', '매주 일요일, 명절 휴무'),
	(695, '송아저씨빈대떡', '03788  서울특별시 서대문구 연세로7안길 29 (창천동)', 'images/송아저씨빈대떡_695.jpg', '모둠전, 해물야채전과 막걸리를 즐길 수 있는 한식 주점.\n\n모둠전, 해물야채전과 막걸리를 즐길 수 있는 주점입니다. 가게 내부의 천장이며 바닥, 벽이 모두 나무 또는 대나무로 장식되어 있어 운치가 있습니다. 동동주나 계란찜도 대나무에 담겨서 나옵니다. 하루11접시만을 판매하는 모둠전이 인기가 좋습니다.', 37.558047, 126.935172, '2만원대', '지하철 2호선 신촌역 2번 출구, 426m', '한식주점', '매일', '', '음식점', '', '16:00 ~ 02:30', '02-338-4919', ''),
	(696, '오엔', '06000  서울 강남구 압구정로11길 37-30', 'images/오엔_696.jpg', '복합 레크리에이션 장소인 오엔은 질 높은 식음료 서비스뿐 아니라 연회를 제공\n\n복합 레크리에이션 장소인 오엔은 질 높은 식음료 서비스뿐 아니라 연회를 제공하려는 목적으로 만들어졌습니다. 3개 층으로 이뤄져 있는데, 전 연령대에 적합한 다양한 메뉴 선택과 현장의 최고 요리사 덕분에 세련되고 편안한 분위기에서 훌륭한 식사를 즐길 수 있습니다.', 37.525317, 127.021433, '', '지하철 3호선 압구정역 6번 출구, 1.3km', 'T-bone Set', '', ' http://www.onriver.co.kr/', '음식점', '', '매일 11:00 - 05:00', '0507-1400-1582', ''),
	(697, '이닝', '06062  서울 강남구 도산대로58길 14', 'images/이닝_697.jpg', '서구적인 인테리어에 사천식과 광동식 등 정통 중국 요리.\n\n블랙을 위주로 사용한 미니멀한 분위기의 서구적인 인테리어에 사천식과 광동식 등 정통 중국 요리를 전문으로 합니다. 생강 채와 파 채, 고수로 장식한 우럭찜이 인기 메뉴이며 그 외에도 가지새우, 발채찜 등 창조적인 요리들을 맛볼 수 있습니다. 변화가 잦은 청담동에서 비교적 오래 자리를 지키고 있는 곳 중의 하나입니다.', 37.522352, 127.041272, '3만원대', '지하철 7호선/ 수인분당선 강남구청역 4번 출구, 733m', '멘보샤, 어향동고, 동파육, 북경오리', '월~토', ' http://www.yining.kr/', '음식점', '', '11:30~14:30, 17:30~22:00', '02-547-7444', '매주 일요일, 명절 휴무'),
	(698, '느린마을 양조장 강남점', '06616  서울 서초구 서초대로73길 7 (서초동)  우승빌딩 지하 1층', 'images/느린마을_양조장_강남점_698.jpg', '전통주와 함께 특별한 안주를 맛볼 수 있는 국내 최초의 도심 속 양조장\n\n숙성 일자에 따라 봄-여름-가을-겨울 맛으로 나뉘는 부드러운 생막걸리와 생약주 등 다양한 전통주와 함께 환상적인 궁합을 자랑하는 특별한 안주를 맛볼 수 있는 국내 최초의 도심 속 양조장입니다. 제대로 된 막걸리를 가장 신선하게 맛 보여드리고 싶은 마음으로 시작한 국내 최초 도심형 막걸리 양조장. 하루하루 숨 가쁘게 달려가고 있는 현대인의 일상에 느림의 쉼표를 더해주고자 배상면주가에서 만든 \'도심형 막걸리 푸드\' 느린마을 양조장. 매일 정성스럽게 손으로빚은 생막걸리와 다양한 안주를 만나 볼 수 있습니다.', 37.498131, 127.025279, '', '지하철 2호선 / 신분당선 강남역 9번 출구, 189m', '느린마을 막걸리, 모듬전, 느린마을 수육', '매일', ' https://www.slowbrewpub.com/', '술집, 바', '', '월요일~토요일: 17:00 - 24:00 / 일요일: 16:00~23:00', '0507-1473-7720', ''),
	(699, '브루스리', '06746  서울 서초구 양재천로 147-1 (양재동)', 'images/브루스리_699.jpg', '북경오리 전문점 마오에서 운영하는 딤섬과 국수 전문점.\n\n북경오리 전문점 마오에서 운영하는 딤섬과 국수 전문점. 캐주얼하게 즐길 수 있는 서민 중식을 표방하고 있습니다.', 37.479774, 127.042865, '1만원대', '지하철 3호선/ 신분당선 양재역 8번 출구, 915m', '삼선 찐만두, 우육면, 돼지고기부추무침, 완탕', '', '', '음식점', '', '매일 11:30 ~ 22:00', '02-576-8845', '명절 당일 휴무'),
	(700, '서궁', '07333  서울 영등포구 국제금융로 86 (여의도동, 롯데캐슬 아이비)  지하 1층', 'images/서궁_700.jpg', '군만두를 제대로 만들어 파는 집.\n\n군만두 제대로 하는 중국집이 흔치 않은 요즘, 군만두를 제대로 만들어 파는 집입니다. 돼지고기가 아니라 소고기를 쓰는데, 생강 향이 적당히 배어나는 맛이 훌륭합니다.', 37.520206, 126.931800, '2만원대', '지하철 9호선/신림선 샛강역 2번 출구, 381m', '오향장육, 소고기군만두, 삼선볶음밥, 탕수육', '월요일~토요일', '', '음식점', '', '월요일~금요일 11:00 ~ 15:00 / 16:30 ~ 22:00\n토요일 11:00 ~ 15:30 / 16:30 ~ 21:00', '02-780-7548', '일요일 휴무'),
	(701, '삼성원조양곱창', '06075  서울 강남구 학동로101길 7', 'images/삼성원조양곱창_701.jpg', '속이 꽉 찬 곱창구이를 맛볼 수 있는 집. 볶음밥이 일품.\n\n속이 꽉 찬 곱창구이를 맛볼 수 있는 집. 다 먹고 남은 철판에 비벼 먹는 볶음밥 또한 일품입니다. 곁들여 먹는 구수하고 걸쭉한 청국장의 맛이 언제나 한결같습니다.', 37.520891, 127.057709, '3만원대', '지하철 7호선 청담역 14번 출구, 124m', '양곱창', '월화수목금토', '', '음식점', '', '16:00 ~ 23:00', '02-545-8895', '매주 일요일, 명절 휴무'),
	(702, '스시히로바 삼성동본점', '06085  서울 강남구 삼성로 620 (삼성동, 블래스톤리조트)', 'images/스시히로바_삼성동본점_702.jpg', '스시히로바는 국내 순수 브랜드이자, 국내 최대 회전초밥 전문점.\n\n스시히로바는  국내 순수 브랜드이자, 국내 최대 회전초밥 전문점입니다.  한국인의 입맛에 꼭 맞는 원조 꽃등심 초밥,  원조 광어김치 초밥 등  일식과 한식의 조화를 선보입니다.', 37.514965, 127.052623, '', '지하철 9호선 삼성중앙역 3번 출구, 165m', '다이어트 세트, 광어 초밥, 장어 초밥, 연어 초밥', '매일', '', '음식점', '', '평일 11:30 - 14:30 / 17:00 - 21:00\n주말 11:30 - 21:00', '0507-1448-5511', ''),
	(703, '강가 역삼점', '06141  서울 강남구 논현로 508 (역삼동, GS강남타워)', 'images/강가_역삼점_703.jpg', '인도 정통의 맛을 선보이는 정통 인도 레스토랑.\n\n강가는 인도 정통의 맛을 선보이는 정통 인도 레스토랑입니다. 모든 메뉴는 인도 정통 요리로, 한국인들의 입맛에 잘 맞아 큰 사랑을 받고 있으며 요리와 더불어 이국적이며 현지화된 분위기를 가지고 있습니다.', 37.501995, 127.037336, '', '지하철 2호선 역삼역 7번 출구, 149m', '치킨 마크니 23,500원\n탄두리 치킨 26,500원\n탄두리 프로운 32,000원', '', ' http://www.ganga.co.kr/', '음식점', '', '평일 11:00 - 14:30 / 17:00 - 21:00\n주말 11:30 - 15:00 / 17:00 - 21:00', '02-2005-0610', ''),
	(704, '만발', '06588  서울 서초구 서초대로29길 32 (방배동)', 'images/만발_704.jpg', '전라도 함평과 충청도 홍성에서 가져오는 한우 전문점.\n\n전라도 함평과 충청도 홍성에서 가져오는 한우 전문점입니다. 진공 포장한 등심을 수족관에서 숙성시킵니다. 질 좋은 등심을 숯불에 구워 먹는 맛이 일품입니다. 정갈하게 나오는 밑반찬도 수준급. 주택을 개조하여 작은 정원이 있는 공간이 아담합니다.', 37.489632, 126.995044, '2만원대', '지하철 7호선 내방역 8번 출구, 290m', '서리꽃등심\n한우불고기전골\n국밥', '매일', '', '음식점', '', '11:30 ~ 22:00\n* Break time 15:00 ~ 17:00', '02-535-7456', '명절 휴무'),
	(705, '구르카 인도레스토랑', '04536  서울 중구 명동10길 16-1  5층', 'images/구르카_인도레스토랑_705.jpg', '현지인이 직접 운영하며, 조리하는 인도, 네팔 전통음식 전문점.\n\n구르카 인도레스토랑은 현지인이 직접 운영하며, 조리하는 인도, 네팔 전통음식 전문점입니다. 커리, 난, 탄두리치킨, 라씨는 물론 그 외 인도와 네팔의 특별함을 느낄 수 있는 다른 요리들도 판매합니다.', 37.563068, 126.985185, '2만원대', '지하철 4호선 명동역 8번 출구, 246m', '', '', '', '음식점', '', '11:00~23:00', '02-775-8860', ''),
	(706, '미스터케밥 이태원본점', '04406  서울 용산구 이태원로 192 (이태원동)', 'images/미스터케밥_이태원본점_706.jpg', '미스터케밥 이태원본점은 프랑스, 중국과 세계 3대 요리로 꼽히는 터키 요리를 한국에서도 즐길 수 있는 곳.\n\n미스터케밥 이태원본점은 프랑스, 중국과 세계 3대 요리로 꼽히는 터키 요리를 한국에서도 즐길 수 있는 곳입니다. 숙련된 현지 요리사의 손맛과 신선한 재료로 본연의 맛을 잃지 않는 웰빙 레시피로 다양한 터키 전통음식을 제공하고 있으며 정식 할랄 인증을 받아 외국인 무슬림도 안심하고 먹을 수 있습니다.', 37.534367, 126.995372, '', '지하철 6호선 이태원역 3번 출구, 88m', '닭고기 터키 케밥, 양고기 터키 케밥', '', '', '음식점', '', '', '0507-1393-2005', ''),
	(707, '스퀘어가든', '06575  서울특별시 서초구 서래로5길 26 (반포동)', 'images/스퀘어가든_707.jpg', '서래마을에서 핸드드립커피가 유명한 곳. 식사로 먹을 수 있는 수제홈버거와 퀘사디아의 맛도 일품. 4개의 테이블로 된 작은 공간이지만, 아기자기하게 꾸며져 있어 사람의 아지트 역할.\n\n서래마을에서 핸드드립커피가 유명한 곳. 식사로 먹을 수 있는 수제홈버거와 퀘사디아의 맛도 일품입니다. 4개의 테이블로 된 작은 공간이지만, 아기자기하게 꾸며져 있어 많은 사람의 아지트 역할을 하고 있는 곳입니다.', 37.497975, 126.996863, '1만원대', '지하철3/7/9호선 고속터미널역 5번 출구, 849m', '카페', '', ' https://www.instagram.com/squaregarden.coffee/', '카페, 디저트', '', '월요일~금요일 08:30 ~ 20:00\n토요일 10:00 ~ 20:00\n일요일 12:00 ~ 20:00', '0507-0289-3105', '매달 5번째 일요일,명절 당일 휴무'),
	(708, '일도씨닭갈비 광화문점', '04520  서울 중구 세종대로 136 (태평로1가, 파이낸스빌딩)  지하 1층', 'images/일도씨닭갈비_광화문점_708.jpg', '일도씨닭갈비는 세련된 레스토랑과 같은 분위기의 닭갈비 음식점.\n\n일도씨닭갈비는 세련된 레스토랑과 같은 분위기의 닭갈비 음식점입니다. 치즈 닭갈비, 콩나물닭갈비 등 다양한 닭갈비 종류를 판매하여 인기를 끌고 있습니다.', 37.568423, 126.978257, '1만원대', '지하철 5호선 광화문역 5번 출구, 172m', '', '', ' https://www.instagram.com/ildossifamily', '음식점', '', '매일 10:00 - 21:30\n(20:30 주문 마감)', '02-3789-9007', ''),
	(709, '워너커피', '06035  서울특별시 강남구 압구정로2길 59 (신사동)', 'images/워너커피_709.jpg', '저렴한 가격에 커피를 마실 수 있는 곳. 가격대비 진하고 부드러운 커피. 실내가 아담하여 편안히 오랜 시간 앉아 있기보다는 테이크아웃 추천.\n\n저렴한 가격에 커피를 마실 수 있는 곳. 가격 대비 진하고 부드러운 커피를 마실 수 있습니다. 실내가 아담하여 편안히 오랜 시간 앉아 있기보다는 테이크아웃을 추천합니다.', 37.518117, 127.021583, '', '지하철 3호선/ 신분당선 신사역 8번 출구, 204m', '와플\n생과일주스\n샌드위치세트', '매일', '', '카페, 디저트', '', '평일 07:00 - 24:00\n주말 08:00 - 24:00', '02-512-2285', '명절 휴무'),
	(710, '부일갈비', '06725  서울 서초구 서초중앙로2길 42', 'images/부일갈비_710.jpg', '부산에서 유명한 갈빗집의 서울 분점. 소금구이.\n\n부산에서 유명한 갈빗집의 서울 분점. 살짝 얼려서 얇게 썬 등심을 계란 노른자로 만든 장에 찍어 먹는 소금구이가 대표 메뉴입니다. 고기를 먹은 후에는 냉면으로 입가심합니다. 점심때는 육개장, 갈비탕 등이 인기 있습니다.', 37.484077, 127.019611, '', '지하철 3호선 남부터미널역 4-1번 출구, 234m', '소금구이, 생등심, 갈비살, 양념갈비, 생갈비', '', ' http://www.booilgalbi.com', '음식점', '', '매일 11:00~22:00', '02-3482-3112', '명절 휴무'),
	(711, '할랄가이즈 강남점', '06611  서울 서초구 강남대로69길 8 (서초동)', 'images/할랄가이즈_강남점_711.jpg', '할랄푸드 브랜드 할랄가이즈는 뉴욕의 푸드트럭으로 시작한 브랜드. 간편하면서도 영양소를 고루 갖춘 플래터와 샌드위치 메뉴.\n\n할랄푸드 브랜드 할랄가이즈는 뉴욕의 푸드트럭으로 시작한 브랜드인 만큼 간편하면서도 영양소를 고루 갖춘 플래터와 샌드위치 메뉴를 선보이고 있습니다. 한국으로 들어온 할랄가이즈는 모두 할랄 인증을 받았으며, 미국에서 공수한 할랄 재료들로 만들어집니다.', 37.501844, 127.024653, '', '지하철 9호선 / 신분당선 신논현역 6번 출구, 254m', '콤보 플래터, 콤보 샌드위치', '', ' http://www.instagram.com/thehalalguyskorea/', '음식점', '', '매일 11:00~22:00', '02-595-1800', ''),
	(712, '연남 5701', '03991  서울 마포구 동교로23길 64 (연남동)  지하', 'images/연남_5701_712.jpg', '라이브 재즈 공연을 곁들인 연남 와인바.\n\n다양한 음식과 와인을 즐길 수 있는 재즈바입니다. 다른 재즈바들과는 조금 다르게 \'연남 5701\'은 라이브 공연에만 집중할 수 있는 곳과 식사를 하면서 공연을 즐길 수 있는 곳이 각각 마련되어 있습니다. 공연 라인업은 \'연남 5701\' 인스타그램과 페이스북에서 확인 할 수 있습니다.', 37.558556, 126.918928, '', '지하철 2호선 / 경의중앙선 / 공항철도 홍대입구역 1번 출구, 625m', '', '', ' https://app.catchtable.co.kr/ct/shop/yeonnam5701 ', '술집, 바', '', '목요일 ~ 일요일 : 18:30 ~ 23:00', '0507-1344-8161', '매주 월요일~수요일'),
	(713, '리치몬드 과자점 성산본점', '03978  서울 마포구 월드컵북로 86 (성산동, 리치몬드빌딩)', 'images/리치몬드_과자점_성산본점_713.jpg', '1979년 마포구에서 시작해 지금까지 오랜 역사를 가지고 있는 리치몬드 과자점 성산본점\n\n1979년 마포구에서 시작해 지금까지 오랜 역사를 가지고 있는 리치몬드 과자점은 성산이 본점이며 수요미식회에서 소개된 서울 3대 빵집으로 알려져 있습니다. 리치몬드 과자점 성산본점의 고소하고 달콤한 밤이 알알이 가득 들어있는 밤 파이는 많은 사람들에게 사랑받는 디저트입니다. 이뿐만 아니라 촉촉한 빵에 밤이 박힌 밤식빵과 꾸덕한 크림이 흘러나오는 슈크림도 먹어보기를 추천합니다!', 37.561414, 126.915620, '', '지하철 2호선/경의중앙선/공항철도 홍대입구역 1번 출구, 1km', '', '월요일, 수요일~일요일', ' https://www.instagram.com/richemont_patisserie/', '카페, 디저트', '', '08:00 ~ 22:00', '02-325-0221', '화요일'),
	(714, '펫사운즈', '04343  서울 용산구 회나무로 21 (이태원동) 3층', 'images/펫사운즈_714.jpg', '록, 인디, 얼터네이티브 음악 팬들을 위한 바\n\n과거 레트로 음악들과 포스트 펑크, 헤비 메탈, 드림 팝 등 수많은 음악 장르의 공연을 마주할 수 있는 곳입니다. 피자, 닭 윙, 감자튀김과 맛있는 칵테일로 고픈 배를 채우며 음악을 즐겨보세요.', 37.539221, 126.989007, '', '지하철 6호선 녹사평역 2번 출구, 549m', '피자, 칠리치즈프라이, 치킨텐더', '매일', ' https://www.instagram.com/petsoundsmusicpub/', '술집, 바', '', '월요일~목요일 17:30 ~ 02:00\n금요일~일요일 17:00 ~ 03:00', '070-8648-3650', ''),
	(715, '케르반 이태원점', '04406  서울 용산구 이태원로 192 (이태원동)  혜문빌딩 1층', 'images/케르반_이태원점_715.jpg', '케르반 이태원점은 정식 할랄 인증을 받은 레스토랑으로 터키 요리사가 직접 요리.\n\n케르반 이태원점은 정식 할랄 인증을 받은 레스토랑으로 터키 요리사가 직접 요리합니다. 분위기가 좋아 이태원 데이트코스로도 인기가 많습니다.', 37.534367, 126.995372, '2만원대', '지하철 6호선 이태원역 3번 출구, 97m', '믹스 피데, 믹스 싀시 케밥 & 버팔로윙', '', ' https://www.instagram.com/kervankorea', '음식점', '', '매일 11:00~06:00', '02-792-4767', '연중무휴'),
	(716, '서촌 대하식당', '03040  서울 종로구 자하문로7길 27 (체부동)', 'images/서촌_대하식당_716.jpg', '세종마을 음식문화거리에 위치한 신선한 돼지고기구이집\n\n세종마을 음식문화거리에 위치한 서촌 대하식당은 신선한 돼지고기구이집으로 유명한 음식점입니다. 외관과 내부 모두 옛날부터 이어온 맛집 분위기를 지니고 있으며 메뉴판과 삼겹살 제조법 등 전부 손글씨로 적혀 있어 노포 느낌의 더욱 매력적인 공간입니다. 또한 대하식당만의 특별한 점은 솥뚜껑 불판에 김치, 파채, 마늘 등을 함께 구워 풍성하고 노릇노릇 한 삼겹살을 맛볼 수 있습니다. 특히 인왕산과 가까워 등산 후에 허기진 배를 맛있는 고기로 채울 수 있는 곳입니다.', 37.578942, 126.970483, '2만원대', '지하철 3호선 경복궁역 2번 출구, 352m', '삼겹살 600g 40,000원', '', '', '음식점', '', '월요일~토요일 16:00 ~ 22:00 (오후 8시에 입장 마감하며, 재료 소진 시 더 빨리 마감합니다.)', '02-734-9503', '일요일'),
	(717, '명가떡집', '05564  서울 송파구 석촌호수로12길 7 (잠실동)', 'images/명가떡집_717.jpg', '24시간 숙성하고 8시간 삶아 만든 팥소로 만든 떡\n\n1980년, 고모로부터 물려받은 레시피를 통해 2대째 이어져 오는 떡집입니다. 현재 사장님이 14살일 때 아버지가 돌아가시면서 어머니와 떡집 일을 시작하였급니다. 매일 새벽 2시부터 떡을 만들기 위한 준비를 하며, 떡 제조는 옛날 방식을 그대로 이어가고 있습니다. 명가떡집의 팥소는 무, 뽕잎 등을 넣어 24시간 숙성시키고, 8시간 동안 삶아 만듭니다. 찹쌀떡이 가장 유명하고 희귀한 떡도 만들어 팝니다.', 37.509021, 127.085614, '', '지하철 2호선 잠실새내역 3번 출구 , 359m', '', '매일', ' http://haneulchae.114kr.kr/', '카페, 디저트', '', '매일 07:00 ~ 22:00', '02-416-9669', '없음'),
	(718, '정애맛담', '06997  서울 동작구 동작대로29나길 10', 'images/정애맛담_718.jpg', '서울 남성시장에 위치한 정애맛담은 한국의 전통음식인 떡에 현대적인 감각을 더한 퓨전 떡집.\n\n서울 남성시장에 위치한 정애맛담은 한국의 전통음식인 떡에 현대적인 감각을 더한 퓨전 떡집입니다. 고물을 묻혀 먹는 말랑 인절미와 빵 대신 담백한 설기에 팥앙금과 버터를 넣은 앙버떡이 인기 메뉴입니. 이외에도 매일 아침 좋은 재료로 만드는 수많은 종류의 신선한 떡을 생산하여 판매하기 때문에 다양하게 맛볼 수 있습니다.', 37.489037, 126.980605, '1만원대', '지하철 4 / 7호선 총신대입구(이수)역 14번 출구, 197m', '말랑인절미, 앙버떡', '', ' https://www.jeongaematdam.com/', '카페, 디저트', '', '이용시간: 06:00 - 19:30 또는 20:00', '0507-1355-9096', '휴무일: 인스타그램 (@anyjeongdam) 안내'),
	(719, '두르가 본점', '03157  서울 종로구 종로 19 (종로1가, 르메이에르종로타운 1 B1)', 'images/두르가_본점_719.jpg', '두르가는 정통 인도&네팔 전문 음식점.\n\n두르가는 정통 인도앤네팔 전문 음식점입니다. 인도, 네팔 음식의 맛과 질을 느낄 수 있는 70여가지의 음식을 제공하는 요리사가 있으며, 매장 내부는 네팔과 인도의 두가지 느낌을 동시에 느낄 수 있는 인테리어로 이색적인 분위기를 가집니다.', 37.570844, 126.979924, '', '지하철 1호선 종각역 1번 출구, 256m\n지하철 5호선 광화문역 4번 출구, 200m', '', '', ' http://www.durga.co.kr/', '음식점', '', '매일 10:00 ~ 15:00 / 17:00 ~ 22 :00 (21:00 주문 마감)', '02-733-4786', ''),
	(720, '무네이 카페', '04556  서울 중구 마른내로4길 11 (인현동1가)', 'images/무네이_카페_720.jpg', '예술가들이 모여 만든 무네이 카페\n\n힙하고 개성 넘치는 카페들이 많은 을지로에서 돋보기 카페로 유명해진 무네이 카페는 힙하고 독특한 분위기로 카페 투어를 좋아하는 사람들에게 인기가 많은 곳입니다. 카페와 와인을 함께 즐길 수 있는 곳으로 낮에는 카페 밤에는 조명이 켜지며 분위기 좋은 와인바를 만나 볼 수 있습니다. 한쪽에는 악세서리, 향수, 컵, 원두 등 판매하는 물품들이 진열되어 있습니다. 무네이 카페의 시그니처는 무네이라떼이며 무네이 카페에서 유명한 디저트는 아이스톤으로 팝핑 캔디가 뿌려진 쫀득한 브라우니와 그 위에 올려진 부드러운 바닐라 아이스크림입니다. 카페의 분위기에 취하고 맛있는 음료를 즐기면서 예술가들이 모여 만든 공간인 무네이에 빠져보세요.', 37.563732, 126.993876, '', '지하철 2 / 3호선 을지로3가역 8번출구 , 225m', '무네이라떼 6,000원\n아이스톤 7,000원\n브루잉 6,000원', '매일', ' https://www.instagram.com/munei_cafe/#', '카페, 디저트', '', '12:00~21:00', '070-7769-0331', ''),
	(721, '한국의집', '04626  서울 중구 퇴계로36길 10 (필동2가, 한국의집)', 'images/한국의집_721.jpg', '전통 복합문화공간 \'한국의집\'\n\n한국의집은 전통문화의 보존과 보급을 목적으로 만들어진 복합문화공간으로 궁중음식, 전통예술공연, 전통혼례 등 다양한 전통문화체험을 즐길 수 있는 한국 대표 전통문화공간입니다. 1957년 국내외 귀빈을 위한 영빈관의 목적으로 지어진 한국의집은 대대적인 개보수와 생생한 역사의 현장을 거치며 현재는 한국의 아름다운 전통문화를 보존 및 보급하기 위한 고품격 복합문화공간으로 다시 태어났습니다. 또한 궁중다과 체험인 \'고호재\' 프로그램과 인기 예능 프로그램, 영화, 드라마의 촬영 장소로 각광받고 있습니다.', 37.560203, 126.994684, '', '지하철 3/ 4호선 충무로역 3번 출구, 263m', '', '', ' http://www.koreahouse.or.kr', '음식점', '캐치테이블 사전 예약\n예약링크 : https://app.catchtable.co.kr/ct/shop/koreahouse', '오찬 12:00 ~ 15:00 (주문마감 13:00)\n만찬 18:00 ~ 22:00 (주문마감 19:30)\n프로그램별 상이', '02-2266-9101', '매주 월요일, 설날 및 추석 당일'),
	(722, '케르반 코엑스점', '06164  서울 강남구 봉은사로 524 (삼성동, 코엑스인터콘티넨탈서울)  B1 H105', 'images/케르반_코엑스점_722.jpg', '삼성동 코엑스 맛집으로 유명한 케르반은 정식 할랄 인증을 받은 터키 레스토랑.\n\n삼성동 코엑스 맛집으로 유명한 케르반은 정식 할랄 인증을 받은 터키 레스토랑입니다. 한국에서 접하기 어려운 터기 음식을 맛볼 수 있고 가게 내부 또한 터키 문화를 그대로 옮겨놓은 화려한 조명과 타일로 꾸며져 있어 구경하는 재미가 있습니다.', 37.512953, 127.057116, '2만원대', '지하철 2호선 삼성역 5번 출구, 319m\n지하철 9호선 봉은사역 7번 출구, 10m', '믹스 쉬시 케밥, 양고기 쉬시 케밥, 닭고기 쉬시 케밥', '', ' https://www.instagram.com/kervankorea/', '음식점', '', '평일 11:00 - 15:00 / 16:30 - 22:00\n주말 11:00 - 22:00', '0507-1326-4767', ''),
	(723, '한강주조', '04776  서울 성동구 둘레15길 12 (성수동2가, 서울학원)  2,3층 한강주조', 'images/한강주조_723.jpg', '과거의 전통과 문화를 현재에 어울리게 표현한 주조장\n\n서울, 한강 그리고 성수동에서 단절된 우리 술의 부흥과 정체성을 알리기 위한 양조장, 한강주조입니다. 서울의 주요 공업지역인 성수동은 공장, 카페, 상업지역과 다양한 부류의 사람들 등 과거와 현재가 공존하는 지역으로 한강주조가 추구하는 비전을 가장 잘 표현해 주는 지역입니다. 한강주조는 막걸리라는 매개체를 이용하여 과거의 전통과 문화를 현재에 어울리게 표현하여 과거와 현재를 연결하고자 합니다.', 37.535786, 127.055724, '', '지하철 2호선 성수역 3번출구, 1.1km', '', '', ' https://hangangbrewery.com/', '', '', '월~금 09:00~17:00', '070-8836-1115', ''),
	(724, '케르반 파미에스테이션', '06545  서울 서초구 사평대로 205 (반포동, CENTRALCITY)  파미에스테이션 2층 216호', 'images/케르반_파미에스테이션_724.jpg', '케르반은 \'허락된 음식\'이라는 의미의 할랄푸드를 메인으로 하는 브랜드\n\n케르반은 \'허락된 음식\'이라는 의미의 할랄푸드를 메인으로 하는 브랜드입니다. 할랄푸드 전문점으로 터키 요리사가 직접 만든 터키 음식을 먹을 수 있으며 인테리어 소품도 터키식으로 꾸며져 있어 이색적인 분위기를 연출합니다.', 37.504492, 127.007845, '', '지하철 3/7/9호선 고속터미널역 3/7번 출구, 78m', '치킨 케밥, 닭고기 덮밥, 치킨 케밥 박스, 양고기 덮밥', '', '', '음식점', '', '매일 11:00 - 21:00', '02-6282-4767', ''),
	(725, '함스브로트과자점', '01443  서울 도봉구 도봉로 483 (쌍문동)', 'images/함스브로트과자점_725.jpg', '국내 단 14명뿐인 제과 명장이 만드는 꽃다발 케이크\n\n1999년부터 대한민국 제과 명장 8호의 역사가 시작된 곳으로 꽃다발 케이크가 유명합니다. 빵집 순례자들의 성지이자 옛날 동네 빵집의 개성을 고스란히 간직하고 있는 제과점입니다. 몸에 좋은 빵을 만들기 위해 이스트가 아닌 천연발효종을 사용합다. 독보적인 케이크 장식의 대가인 대표는 한국의 꽃을 장식으로 올리는 기술을 보유하고 있습니다. 단순한 케이크가 아닌 한국의 미(美)를 엿볼 수 있는 예술작품을 보고 싶다면 방문해 보세요.', 37.648939, 127.034535, '', '지하철 4호선 쌍문역 4번 출구, 14m', '꽃다발 케이크, 마늘빵, 통밀깜파뉴', '매일', '', '카페, 디저트', '', '월요일~토요일 09:00~21:40\n일요일 11:00~18:00', '02-996-4488', '명절 당일'),
	(726, '봄베그릴 이태원점', '04405  서울 용산구 우사단로10길 11 (이태원동)', 'images/봄베그릴_이태원점_726.jpg', '인도음식 전문점. 현지인셰프가 직접 음식을 조리.\n\n서울시 용산구에 위치한 봄베그릴 이태원점은 인도 음식 전문점으로, 현지인 셰프가 직접 음식을 조리하여 인도 음식 본연의 맛을 즐길 수 있습니다. 건강한 음식문화를 만들어가기 위해 신선한 재료만을 사용하며 편안하고 즐거운 식사를 즐길 수 있도록 최상의 서비스를 제공합니다.', 37.533201, 126.996233, '2만원대', '지하철 6호선 이태원역 3번 출구, 353m', '치킨마크니 달콤한맛 세트, 치킨타카마살라 매콤한맛 세트', '', ' http://bombaygrilll.itrocks.kr/', '음식점', '', '매일 11:00~22:00', '0507-1328-7155', ''),
	(727, '봉화묵집', '02813  서울 성북구 아리랑로19길 46-2', 'images/봉화묵집_727.jpg', '포근한 가정집 분위기를 느끼며 맛보는 묵밥과 만두\n\n1982년부터 정릉 옆을 지키는 손맛 좋은 묵밥과 만두 맛집입니다. 경북 봉화 출신의 시어머니로부터 며느리로 가업이 승계되어 운영되고 있습니다. 수제 가정식 음식으로 된장과 간장까지 직접 제조하며 음식을 가지고 손님을 속이지 않는다는 철학을 이어가고 있습니다. 옛날 가정집을 개조하여 마치 집에 온 듯한 분위기를 풍기며, 정갈한 음식이 일품인지라 멀리서도 오랜 시간 꾸준히 찾는 단골손님이 많습니다.', 37.601236, 127.008820, '1만원대', '지하철 우이신설선 정릉역 2번 출구, 247m', '', '화요일~일요일', '', '음식점', '', '화요일~일요일 11:00~20:00', '02-918-1668', '매주 월요일 정기휴무'),
	(728, '애플하우스', '07008  서울 동작구 동작대로27다길 29 (사당동, 서광시티뷰)  2층', 'images/애플하우스_728.jpg', '연예인들도 잊지 못하고 찾아오는 즉석 떡볶이 맛집\n\n1987년 반포에서 포장마차로 시작된 애플하우스는 입소문이 퍼지면서 손님들이 몰려 가게를 차리게 됐습니다. 2022년 재개발로 인해 반포에서 이수로 자리를 이전하게 되었습지다. 현재 2대째 장사를 이어가기 위해 딸에게 비법을 전수 중입니다. 사장님은 지금까지 가게가 이어질 수 있었던 것은 ‘변화 없는 맛’ 때문이라고 합니다. 단골들은 옛날 맛 그대로라며 기뻐하고 젊은 고객들은 옛날 맛을 찾아옵니다.', 37.486285, 126.980663, '1만원대', '지하철 4/ 7호선 이수역 10번 출구, 158m', '떡볶이, 무침군만두', '매일', '', '음식점', '', '10:30~21:00', '02-595-1629', '없음'),
	(729, '깔리 사당점', '06692  서울 서초구 방배천로 21 (방배동)  동화빌딩 4층', 'images/깔리_사당점_729.jpg', '인도에서 초빙한 쉐프가 직접 조리해 이국적인 맛 선사.\n\n인도에서 초빙한 쉐프가 직접 조리해 이국적인 맛을 선사합니다. 코스 메뉴부터 단품 메뉴까지 다양한 인도 음식과 마실 거리가 있습니다.', 37.478469, 126.982282, '', '지하철 2 / 4호선 사당역 11번 출구, 35m', '', '매일', '', '음식점', '', '11:30 ~ 22:00', '02-581-2855', ''),
	(730, '델리인디아', '04048  서울 마포구 독막로9길 8 (서교동)  2층', 'images/델리인디아_730.jpg', '델리인디아는 인도인이 직접 운영하는 퓨전 인도음식점이다.\n\n델리인디아는 인도인이 직접 운영하는 퓨전 인도 음식점이다. 사모사, 인도식 볶음밥, 볶음면 등 여러 가지 인도 음식을 경험할 수 있는 곳이다.', 37.548690, 126.919744, '', '지하철 2,6호선 합정역 6번 출구, 564m', '', '', ' http://www.instagram.com/delhi_india_seokyo', '음식점', '', '매일 11:00 ~ 22:00', '02-2631-2109', ''),
	(731, '카페 새싹', '03930  서울 마포구 성암로13길 66 (상암동)', 'images/카페_새싹_731.jpg', '반려동물 동반이 가능한 카페 새싹\n\n반려동물 동반이 가능한 카페 새싹은 맛있는 커피와 샐러드로 유명합니다. 신선하고 다양한 야채들로 이루어진 샐러드와 건강한 음료 그리고 고소한 커피를 비교적 착한 가격으로 즐길 수 있어 많은 사람들에게 사랑받고 있는 카페입니다. 카페 메뉴의 맛뿐만 아니라 아늑하고 분위기 좋은 공간에서 반려동물과 함께 시간을 보낼 수 있습니다.', 37.575354, 126.897822, '', '지하철 6호선 / 경의중앙선 / 공항철도 디지털미디어시티역 8번 출구, 259m', '소불고기 샐러드 9,900원\n아메리카노 3,000원', '매일', ' http://www.instagram.com/saessaaack_cafe', '카페, 디저트', '', '08:00-19:00 (월요일-목요일)\n08:00-17:00 (금요일)\n11:00-17:00 (토.일요일)', '02-2135-9296', ''),
	(732, '로야디', '06670  서울 서초구 반포대로21길 57 (서초동)  1층 로야디', 'images/로야디_732.jpg', '카페 로야디는 한국 전통요소를 응용해 퓨전 디저트를 만드는 수제 디저트 전문점 .\n\n카페 로야디는 한국 전통요소를 응용해 퓨전 디저트를 만드는 수제 디저트 전문점입니다. 미니 떡 케이크와 설기 마들렌이 인기 메뉴이며 아침 식사용으로 좋은 떡 샌드위치를 판매해 바쁜 직장인들에게 좋은 반응을 얻고 있습니다.', 37.486250, 127.008015, '1만원대', '지하철 2호선 서초역 3번 출구 , 626m', '떡마들렌, 떡케이크, 떡샌드위치', '월요일~토요일', ' https://www.instagram.com/cafe_royad/', '카페, 디저트', '', '11:00 - 19:00', '02-2055-0403', '매주 일요일'),
	(733, '꾸스꾸스', '03040  서울 종로구 자하문로5길 16-2 (체부동)', 'images/꾸스꾸스_733.jpg', '꾸스꾸스는 북아프리카 튀니지 전통음식을 파는 서촌 맛집.\n\n꾸스꾸스는 북아프리카 튀니지 전통음식을 파는 서촌 맛집입니다. 흔치 않은 튀니지 가정식 요리를 맛볼 수 있는 곳으로, 색다른 맛을 경험해보고 싶은 사람에게 추천합니다. 16,000원 ~ 35,000원의 가격대에서 다양한 튀니지안 세트를 제공합니다.', 37.577861, 126.971150, '', '지하철3호선 경복궁역 2번 출구, 252m', '', '', '', '음식점', '', '매일 11:30 - 23:00', '0507-1382-5762', '화요일 휴무'),
	(734, '이승남의꽃과빵', '06004  서울 강남구 압구정로29길 68 (압구정동, 현대아파트)  현대상가 지하 1층', 'images/이승남의꽃과빵_734.jpg', '케이크에 생화를 사용하여 화제가 되었던 곳. 다양한 종류의 컵케이크. 생화 케이크는 하루 전 예약.\n\n케이크에 생화를 사용하여 화제가 되었던 곳. 다양한 종류의 컵케이크도 맛볼 수 있습니다. 생화 케이크는 하루 전 예약하고 찾아가야 합니다.', 37.532536, 127.029187, '2만원대', '지하철 3호선 압구정역 1번 출구, 579m', '케이크', '월요일~토요일', ' https://www.instagram.com/leesfnb/', '카페, 디저트', '', '10:00 - 19:00', '02-516-3971', '일요일 휴무'),
	(735, 'PB플러스', '04406  서울 용산구 우사단로 19-1  1층', 'images/PB플러스_735.jpg', '이란인 주인이 할랄 인증 재료를 이용한 버거와 피자.\n\nPB플러스는 이란인 주인이 할랄 인증 재료를 이용한 버거와 피자를 선보이는 집입니다. 저렴한 가격과 푸짐한 양, 뛰어난 맛에 많은 사람이 즐겨 찾습니다. 이곳의 대표 메뉴인 스페셜 비프 슬라이스 버거는 자주 먹어도 질리지 않는 담백함이 있습니다.', 37.532036, 126.996110, '1만원대', '지하철 6호선 이태원역 3번 출구, 390m', '', '', '', '음식점', '', '매일 13:00~23:00', '0507-1369-4883', '연중무휴'),
	(736, '더베이커스테이블 (The Baker\'s Table)', '04343  서울 용산구 녹사평대로 244-1 (이태원동)', 'images/더베이커스테이블_(The_Baker\'s_Table)_736.jpg', '마치 유럽에 온 착각에 빠지게 만드는 \'더베이커스테이블\' 분위기만큼이나 맛있는 독일식 빵.\n\n이태원 경리단길에 위치한 독일식 빵을 파는 베이커리. 독일식 빵을 파는 베이커리답게 들어가는 순간 독일에 온 것 같은 착각에 빠지게 만드는 곳입니다. 빵뿐만 아니라 스프 등 다른 메뉴들도 맛있으니 이곳에 방문하였다면 다양한 메뉴를 함께 즐겨보면 좋을 것 같습니다.', 37.539449, 126.987467, '1만원대', '지하철 6호선 녹사평역 2번 출구 , 454m', '', '', ' http://www.thebakerstable.co.kr ', '카페, 디저트', '', '월요일~금요일 08:00~21:00, 토요일~일요일 08:00~20:00', '0507-1461-3503', ''),
	(737, '깃털', '03994  서울 마포구 동교로 212-2 (동교동)  2층', 'images/깃털_737.jpg', '혼술러들의 성지, 연남동 혼술 Bar 깃털\n\n연남동 공원길에 위치한 bar 깃털은 혼술을 마음 편히 즐길 수 있는 곳입니다. \n\n열린 마음과 매너만 장착하면 새로운 친구 사귀기 좋고 다양한 위스키와 합리적인 가격의 칵테일이 준비되어 있습니다. 운이 좋다면 간헐적으로 열리는 파티나 전시에 참여할 수도 있습니다. 설이나 추석 등 명절 연휴에는 포트락 파티가 열립니다.  가족과 함께 아니더라도 새로운 친구들과 음식을 나누며 따듯한 명절을 보내 보세요.  친구도 부르기 애매한 늦은 시간, 술이 한잔하고 싶다거나 적막한 도시의 밤, 혼자 넷플릭스 보기는 지겹다면 깃털로 가보세요.', 37.559116, 126.923950, '', '지하철 2호선 / 경의중앙선 / 공항철도 홍대입구역 3번 출구, 219m', '칵테일', '매일', ' https://www.instagram.com/gitteol_hongyang', '술집, 바', '', '18:00 - 익일 5:00', '070-4090-1162', ''),
	(738, '이드', '04408  서울 용산구 우사단로10길 15 (한남동)', 'images/이드_738.jpg', '이슬람사원 근처에 있는 곳으로, 한국이슬람중앙회에서 할랄 인증을 받은 유일한 한식당.\n\n이슬람사원 근처에 있는 곳으로, 한국이슬람중앙회에서 할랄 인증을 받은 유일한 한식당입니다. 기본으로 제공되는 반찬 세 가지와 국은 주인 내외가 매일 직접 만듭니다. 친환경 채소를 사용하고 인공 첨가물을 사용하지 않아 맛이 깔끔합니다.', 37.533264, 126.996418, '1만원대', '지하철 6호선 이태원역 3번 출구, 363m', '비빔밥, 소불고기, 소고기김치볶음밥, 오미자차', '', '', '음식점', '', '매일 12:00 ~ 21:00', '070-8899-8210', ''),
	(739, '루나아시아', '06166  서울 강남구 삼성로100길 15 (삼성동, 명당빌딩)', 'images/루나아시아_739.jpg', '루나아시아는 인도쉐프가 요리하는 전통 인도 요리 전문점.\n\n루나아시아는 인도쉐프가 요리하는 전통 인도 요리 전문점입니다. 100% 천연 향신료를 이용하여 전통 커리를 만들고, 화덕 안에서 난을 노릇하게 구워냅니다. 탄두리치킨과 프라운빈달루가 대표메뉴입니다.', 37.509901, 127.056634, '', '지하철 2호선 삼성역 5번 출구, 706m\n지하철 9호선 삼성중앙역 5번 출구, 487m', '', '', ' http://lunaasia.modoo.at/', '음식점', '', '평일 11:00 - 22:00 (Break time 14:30 -17:00)\n주말 12:00 - 21:00\n공휴일 12:00 - 21:00', '-8474', ''),
	(740, '시간을 들이다', '07053  서울 동작구 보라매로 80 (신대방동) 1층', 'images/시간을_들이다_740.jpg', '바삭한 페스츄리 안에 다양한 크림으로 바삭함과 부드러움의 조화를 이루는 크로와상 맛집 시간을 들이다 본점\n\n시간을 들이다는 바삭한 페스츄리 안에 다양한 크림으로 바삭함과 부드러움의 조화를 이루는 크로와상 맛집으로 알려져 있습니다. 기본 중의 기본! 꾸덕한 생초콜릿 느낌이 나는 초코크림 크로와상, 팥과 버터의 고소한 풍미가 가득한 앙버터 페스츄리, 고소한 팥과 담백한 우유로 이루어진 팥 우유크림 크로와상 등 정성이 가득한 디저트들을 만나볼 수 있습니다.', 37.496509, 126.928029, '', '지하철7호선 신대방삼거리역 2번 출, 344m', '슈크림크로와상 4,600원\n앙버터페이스트리 4,600원\n초코크로와상 4,600원', '', ' http://www.instagram.com/si_gan_eul_deul_i_da', '카페, 디저트', '', '08:00~20:00', '02-812-2158', '매주 수요일'),
	(742, '[백년가게] 청수장', '02710  서울 성북구 정릉로 237-2 (정릉동)', 'images/[백년가게]_청수장_742.jpg', '1984년 개업한 정릉 최고의 돼지갈비 맛집\n\n청수장은 1984년에 개업한 정릉 최고의 맛집입니다. 청수장의 대표 메뉴는 단연 “청수돼지갈비”! 요리법(料理法)과 먹는 법이 일반 돼지갈비와는 다릅니다. 보통 돼지갈비는 고기를 양념에 재워 숙성하는데 이때 고기 본연의 식감과 풍미가 약해집니다. \n\n청수장은 식감과 풍미를 지키기 위해 고기를 특제 “검정양념”에 무쳐 재우지 않고 바로 굽습니다. 구워진 고기를 다시 이 “검정양념”에 푹 찍어 먹습니다. 이 양념은 오직 청수장에서만 맛볼 수 있는데, 짠맛과 매콤함이 부드럽게 미각을 자극하고 달콤함과 씁쓸함이 감질나게 입안을 맴돕니다. 생고기의 아삭한 식감(食疳), 그윽한 지방의 풍미(風味), 그리고 오묘한 양념의 맛으로 많은 이의 대를 이어 사랑받고 있습니다.', 37.605320, 127.010787, '', '지하철 우이신설선 정릉역 2번 출구, 425m', '돼지갈비, 냉면 등', '', ' https://www.instagram.com/chungsoojang/', '음식점', '', '매일 11:30~21:30', '0507-1323-6176', ''),
	(743, '신흥상회', '07299  서울 영등포구 도림로126길 1 (문래동3가)', 'images/신흥상회_743.jpg', '문래창작촌에서 콩나물 라면과 함께 즐기는 가맥\n\n1975년부터 자리를 지켜온 문래창작촌 대표 슈퍼 콩나물라면집입니다. 안주와 해장라면이 공존하는 가맥집이면서 상점으로 동네 사랑방 역할을 톡톡히 하고 있습니다. 일찍 일하는 철공소 사람들을 위해 새벽 출근도 마다하지 않은 사장님의 마음이 전해져 손님들에겐 이웃사촌처럼 편안한 방문이 되었습니다. 한 철 장사가 아니라 면발처럼 가늘고 길게 오랜 시간 이어온 가게라는 자부심이 느껴지는 한 그릇은 오늘도 따뜻한 온기를 남깁니다.', 37.513979, 126.896507, '', '지하철 2호선 문래역 7번 출구, 515m', '콩나물라면, 두부김치, 스팸구이, 아메리카노', '매일', '', '음식점', '', '월요일~금요일 06:00~23:00\n토요일~일요일 10:00~22:00', '0507-1386-4461', '없음'),
	(745, '1인1잔', '03308  서울 은평구 연서로 534 (진관동)', 'images/1인1잔_745.jpg', '은평 한옥마을과 북한산이 보이는 한옥 카페\n\n날씨 좋은 날, 아름다운 뷰와 커피를 함께 즐기고 싶다면 1인 1잔을 방문해보세요. 한국적인 멋과 맛을 갖춘 디저트와 음료가 당신을 기다리고 있습니다.', 37.640941, 126.937865, '', '지하철 3호선/ 6호선 연신내역 3번출구, 100m 직진- 7211, 701번 버스 승차- \'하나고, 진관사, 삼천사 입구\'에서 하차 후 도보 150m', '', '화요일~일요일', ' https://www.instagram.com/1in_official/', '카페, 디저트', '월요일이 공휴일인 경우 정상 영업', '1, 2, 3, 6층 10:00 ~ 21:00\n4, 5층 11:00 ~ 20:00', '0507-1487-1270', '매주 월요일'),
	(746, '만나당', '06029  서울 강남구 논현로175길 61 (신사동)  1층 101호 만나당', 'images/만나당_746.jpg', '궁중에서 먹던 한과를 만나볼 수 있는 가게\n\n1991년 개업한 궁중병과점으로 궁중병과를 연구 및 생산하고 계신 장인과 더불어 후계자가 가업을 잇는 중입니다. 조청 넣은 풍미 만점 약과가 대표상품입니다. 만나당은 궁과 양반가에서 잔치 때 올리는 상차림, 떡, 한과를 전수·계승 받아 지금까지 전통의 맛을 지키고 있습니다. 전통적인 상차림에 들어가는 궁중 떡, 궁중 한과 등을 생산하여 판매까지 하는 곳은 서울시 내에 이곳이 유일합니다.', 37.524153, 127.024073, '', '지하철3호선 압구정역 5번 출구, 498m', '궁중병과', '', '', '카페, 디저트', '', '월요일-토요일 10:00-18:00', '0507-1327-3312', '일요일'),
	(747, '케르반 반포점', '06546  서울 서초구 신반포로 176 (반포동, 센트럴시티)  신세계백화점 강남점 지하 1층', 'images/케르반_반포점_747.jpg', '케르반 반포점은 신세계몰에 위치한 할랄 음식점.\n\n케르반 반포점은 신세계몰에 위치한 할랄 음식점입니다. 터키인 요리사가 직접 음식을 준비하고 다양한 디저트도 함께 즐길 수 있는 레스토랑입니다. 인테리어 소품도 터키식으로 꾸며져 있어 이색적인 분위기를 연출합니다.', 37.503935, 127.002413, '', '지하철 3 / 7 / 9호선 고속터미널역 8번 출구, 42m', '', '', '', '음식점', '', '매일 08:00 ~ 20:00', '02-797-2356', ''),
	(749, '듀이커피', '03930  서울 마포구 성암로15길 56 (상암동)', 'images/듀이커피_749.jpg', '상암동의 분위기 좋은 카페\n\n상암동의 분위기 좋은 카페를 찾는다면 디저트 카페인 듀이커피를 추천한다. 카페 내부는 모던한 느낌이면서도 따듯한 분위기로 이루어져 있다. 듀이커피만의 감성적인 느낌이 담긴 달콤한 쿠키, 고소한 스콘과 다양한 커피 종류들이 있다. 특히 강아지와 함께 즐길 수 있는 반려동물 동반이 가능한 카페이다. 카페의 외부, 내부 모두 분위기 가득한 곳에서 티타임을 즐겨보자.', 37.576505, 126.896470, '', '디지털미디어시티역 9번 출구에서244m', '핸드드립 5,500원\n오레그랏세 6,500원\n콜드브루 5,000원\n카페라떼 5,000원', '매일', ' https://instagram.com/dewey_coffee', '', '', '11:00 ~ 20:00', '010-6256-9955', '토요일, 공휴일'),
	(750, '술마켓 군자 본점', '04920  서울 광진구 천호대로 515 (중곡동)', 'images/술마켓_군자_본점_750.jpg', '최대 규모, 최다 품목을 자랑하는 대한민국 전통주 보틀숍\n\n전통주 온라인 쇼핑몰 술마켓에서 운영하는 보틀숍으로 전통주 보틀숍 중 최대 규모, 최다 품목을 자랑하며 구매한 전통주를 지하 공간에서 바로 마실 수 있는 BAR 운영 중입니다. \'Bring your food\'를 슬로건으로 외부 음식을 반입할 수 있는 자유로운 음주 공간을 지향합니다.', 37.558888, 127.075958, '', '지하철 5 / 7호선 군자역 1번 출구, 312m', '막걸리, 약주, 청주, 증류주 등 다양한 전통주 완비', '월~토', ' https://www.soolmarket.com/', '술집, 바', '영어 응대 가능', '12:00 ~ 24:00', '0507-1425-8844', '매주 일요일'),
	(751, '비스트로 멕시 (bistro MEXI)', '04350  서울 용산구 이태원로 191 (이태원동) 2층', 'images/비스트로_멕시_(bistro_MEXI)_751.png', '서울의 중심 이태원에서 즐기는 멕시칸 바이브, 비스트로 멕시(bistro MEXI)\n\n‘비스트로 멕시 (bistroMEXI)\'는 카리브 해를 연상시키는 푸른 에메랄드빛, 라틴아메리카의 열정을 담은 붉은 색채, 그리고 아즈텍 문양에서 영감을 얻은 공간을 조성했습니다. 이러한 공간에 펼쳐진 10m 폭 초대형 미디어월의 NFT 아티스트 작품을 통해  전통과 현대가 공존하는 신개념 멕시칸 타파스 라운지를 경험하실 수 있습니다. \n\n‘흥겨운 라틴 바이브 속으로’\n삼면이 통유리로 펼쳐져 있어, 탁 트인 이태원 거리를 한눈에 담아 실내에선 느낄 수 없는 시원한 개방감을 선사합니다. 여기에 국내외 유명 DJ들의 이국적 정취가 느껴지는 라틴, 아프리칸 월드 뮤직을 기반으로 Pop, Hip Hop, Disco 등의 장르를 더해 흥겨운 분위기를 연출합니다. \n\n‘ 정통 멕시칸 타파스와 함께’\n6가지 이상의 다양한 타코와 각종 파히타가 준비되어 있고, 멕시만의 스타일로 재해석한 케르비안 칵테일과 쉽게 접할 수 없는 하이 퀄리티 논께 알콜 칵테일, 그리고 국내 최다 데킬라와 메즈칼 셀렉션은 오직 비스트로 멕시에서만 느낄 수 있는 특별한 경험입니다.', 37.534856, 126.995247, '', '지하철 6호선 이태원역 2번 출구, 79m', 'Fajita (Chicken & Shrimp & Steak), Tacos (6 kinds), Mango Caesar Salad', '매일', ' https://www.instagram.com/mexiseoul/', '술집, 바', '밤이 되면 라틴, 아프리칸 등 월드 뮤직을 기반으로 한 House, Disco, Funk 장르의 라이브 디제잉 쇼가 펼쳐집니다', '일~수 17:00 ~ 02:00 / 목요일 17:00 ~ 03:00\n금~토 17:00 ~ 04:00', '0507-1384-6855', '연중무휴'),
	(752, '부기우기', '04343  서울 용산구 회나무로 21 (이태원동) 2층', 'images/부기우기_752.jpg', '환상적인 라이브 재즈 공연을 즐길 수 있는 바\n\n강하고 빠른 비트의 피아노 공연, 재즈 음악을 좋아한다면 꼭 가봐야 할 라이브 바입니다. 금요일 밤, 흥겨운 음악으로 주말을 시작하고 싶다면 부기우기로 가보세요.', 37.539221, 126.989007, '', '지하철 6호선 녹사평역 2번 출구, 549m', '', '매일', ' https://www.instagram.com/boogiewoogieseoul/', '술집, 바', '예약시 세트 할인 및 선호도가 높은 좌석 우선 배정', '17:30~00:30', '010-2396-3050', ''),
	(753, '우부래도', '06968  서울 동작구 상도로37길 3 (상도1동)', 'images/우부래도_753.jpg', '우부래도의 빵은 알레르기를 일으킬 수 있는 계란, 우유, 버터를 사용하지 않고 빵을 만들고 국내산 쌀, 현미, 유기농 우리밀 등 건강한 재료를 사용하는 것이 특징.\n\n우부래도의 빵은 알레르기를 일으킬 수 있는 계란, 우유, 버터를 사용하지 않고 빵을 만들고 국내산 쌀, 현미, 유기농 우리 밀 등 건강한 재료를 사용하는 것이 특징입니다. 밀가루 없이 국내산 백미와 흑미로 만든 반죽에 단호박 푸;레와 팥앙금으로 속을 채우고, 아몬드 소보로로 마무리한 \'단호박 큐브\'가 시그니처 빵입니다.', 37.503172, 126.948655, '', '지하철7호선 상도역 5번 출구, 74m', '', '', ' https://smartstore.naver.com/oohbreado', '카페, 디저트', '', '매일 10:00~22:00', '0507-1428-0599', ''),
	(755, '수유어묵공장', '01117  서울 강북구 도봉로67길 18', 'images/수유어묵공장_755.jpg', '날씨를 고려해 어육 살을 배합하는 장인의 전통 어묵\n\n어묵 공장장 출신 사장님이 수유시장에 작은 평수로 수유어묵공장을 시작했는데 지금은 아들이 아버지에게 기술을 배우며 대를 잇고 있습니다. 사장님은 어육 살을 배합할 때 날씨까지 고려할 정도로 정성을 기울입니다. 이 가게에는 어묵바와 야채 사각 어묵이 유명합니다. 특히 야채 사각 어묵은 손도 많이 가고 섬세한 기술이 필요해서 만들어 파는 곳이 드물어 더 인기입니다.', 37.630730, 127.022616, '', '지하철 4호선 미아역 8번 출구, 530m', '수제어묵', '매일', '', '음식점', '', '08:00~21:00', '02-980-7488', '없음'),
	(756, '터방내', '서울 동작구 흑석로 101-7', 'images/터방내_756.jpg', '80년대 감성을 간직한 사이폰 커피와 프라페\n\n1983년부터 ‘중대다방’이라 불리며 사이폰 커피 맛을 지켜오고 있는 흑석동 대표 카페입니다. 80년대의 인테리어를 그대로 유지하고 있는지라 그 당시 청춘이었던 중년들과 그 시절 감성을 체험하고픈 젊은이들이 공존하는 풍경이 인상적입니다. 사이폰 커피는 역사가 오래된 커피 추출방식으로 원두마다 로스팅 기법이 달라 특별한 커피를 맛볼 수 있습니다. 세월의 흐름에도 꾸준히 값싼 가격을 유지하는 사장님의 마음에서 단골손님을 향한 애정과 그동안의 노고를 느낄 수 있습니다.', 37.507798, 126.961369, '', '지하철 9호선 흑석역 4번 출구, 322m', '사이폰커피, 비엔나커피, 카페로얄', '월요일~토요일', ' https://caucafe.modoo.at/', '카페, 디저트', '', '11:00~24:00', '02-813-4434', '일요일'),
	(757, '모퉁이집', '06129  서울 강남구 테헤란로1길 20 (역삼동)', 'images/모퉁이집_757.jpg', '강남의 변천사를 함께한 라면 맛집\n\n모퉁이집은 강남 번화가가 주택가였을 시절부터 이름에 걸맞게 건물 모퉁이에 자리를 잡은 분식집입니다. 본래는 ‘소문난국수집’이라는 상호로 도서실을 다니는 학생들을 대상으로 멸치국수를 판매하였다고 합니다. 모퉁이집에서 가장 잘 팔리는 메뉴는 떡라면과 오뎅김밥으로, 외국인 관광객들에게 ‘강남의 라면 맛집’으로 입소문이 나 지도 어플과 번역기를 켜고 물어물어 찾아온다고 합니다.', 37.499663, 127.027811, '1만원대', '지하철 신분당선/2호선 강남역 11번 출구, 168m', '떡라면, 오뎅김밥, 수제비', '없음', '', '음식점', '', '10:00~23:00', '02-562-5948', '매일'),
	(758, '아쿠아가든카페', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰)  지하1층 아쿠아가든카페', 'images/아쿠아가든카페_758.jpg', '물멍이 가능한 이색 카페, 아쿠아가든카페\n\n아쿠아가든카페는 아쿠아리움과 카페가 합쳐진 곳으로, 물속 풍경을 감상하며 커피를 즐길 수 있는 이색적인 공간입니다. 자연 그대로의 수중 생태계를 생생하게 재현한 대형 수조가 매장 전체를 둘러싸고 있어, 방문객들은 어디에서나 풍부한 볼거리를 즐길 수 있습니다. 유목과 수초로 꾸며진 수조 속에는 수십가지의 다양한 어종이 헤엄치고 있으며, 물이 흐르는 소리와 조명은 신비로운 분위기를 자아냅니다. 남녀노소 할 것 없이 누구든 충분히 쉼을 누리고 갈 수 있어 꾸준히 인기가 많은 곳. 카페 내부에는 아이들을 위한 유아의자가 준비되어 있습니다. 또한 작은 매장이 함께 위치해 있어, 물고기나 수조 용품, 미니 테라리움 등을 구매할 수 있습니다. 음료 값에 입장료가 포함되어있기 때문에 다른 카페에 비해 가격대가 있는 편입니다.', 37.513713, 127.104302, '', '지하철 2 / 8호선 잠실역 11번 출구, 308m', '', '매일', ' https://www.aquagarden.or.kr/', '카페, 디저트', '자세한 정보는 인스타그램 @aquagarden_korea 을 참고하시길 바랍니다.', '매일 10:00 ~ 22:00 (21:00 주문 마감)\n*설날, 추석 당일에만 정오 12시 오픈', '0507-1469-8440', ''),
	(759, '동부고려제과', '02163  서울 중랑구 망우로 388', 'images/동부고려제과_759.jpg', '만주와 생도너츠로 유명한 중랑구 대표 베이커리\n\n1974년 개업 이래로 보기 좋은 빵보다는 맛있는 빵을 만들겠다는 전통을 이어가고 있습니다. 70년대 경마장을 찾은 손님들을 위해 슈퍼마켓 같은 제과점을 운영했던 풍습이 남아 있어 이색적인 풍경을 만들어냅니다. 만주와 생도너츠 같은 옛날 빵부터 마늘 크림빵과 치아바타까지 다양한 종류의 수제 빵이 가게 안을 가득 채웁니다. 지금까지 오래도록 사랑받는 가게가 될 수 있었던 비법은 천연발효로 만들어 소화가 잘되는 덕분이라고 사장님은 전합니다.\n\n \n\n• 이곳은 \'서울미래유산\'으로 선정된 곳입니다. 서울의 근·현대 문화유산 중에서 미래 세대에게 전달할 만한 가치가 있는 유무형의 자산인 서울미래유산을 오래가게 여행에서 만나보세요.(https://futureheritage.seoul.go.kr)', 37.598505, 127.095145, '', '지하철 경의중앙/경춘선 망우역 1번 출구, 309m', '', '매일', ' https://tjwhdgur567.modoo.at', '카페, 디저트', '', '06:30~00:30', '02-433-1783', '매월 1, 3번재 화요일'),
	(760, '사하라', '04214  서울 마포구 만리재로 15 제일빌딩 지하1층 2호', 'images/사하라_760.jpg', '음악과 영화, 열정과 낭만이 서린 7080 라이브 주점\n\n모든 게 변하는데 사하라 사막은 변함이 없으니 그 이름을 걸고 오랜 세월 인생사를 담겠다는 생각으로 만든 가게가 바로 라이브술집 사하라입니다. 사하라는 민주화운동 시기에 시위 대학생들이 숨을 수 있게 공간을 내어주기도 했는데, 그 인연을 맺은 학생들이 어른이 된 후에도 계속 찾는 단골집입니다. 사하라는 술집이자 사랑방 같아서 모르는 사람끼리도 금세 웃음을 나누고, 혼자 온 사람들도 쉽게 사람들과 어울리게 되는 곳입니다.', 37.544585, 126.952768, '', '지하철 5 / 6호선 / 공항철도 / 경의중앙선 공덕역 5번 출구, 100m', '', '월요일 ~ 토요일', '', '술집, 바', '', '17:30~02:00', '02-719-8338', '일요일, 공휴일'),
	(761, '[백년가게] 3대 삼계장인', '06646  서울 서초구 반포대로28길 56-3 (서초동, 한라빌딩)   1층', 'images/[백년가게]_3대_삼계장인_761.jpg', '시루에서 찐 닭부터 수비드를 이용한 닭으로 만드는 삼계탕 맛집\n\n사시사철, 육수 끓는 소리와 진한 육수 냄새가 끊이지 않습니다. 3대 삼계장인은 1973년 서초 1동에서 개업한 ‘불로집’입니다. 3일 동안 육수를 정성껏 끓여서 만들어낸 삼계탕이 손님에게 큰 반향을 얻고 삼계탕 맛집이 되었습니다. 맛집의 반열에 오르고 나서도 완벽한 삼계탕을 만들기 위한 노력은 멈추지 않았습니다. \n\n\n\n\n고기를 물에 넣어서 끓이면 편하고 경제적이지만 식감과 맛을 살리기 위해 1991년에는 닭고기를 시루에 쪄서 삼계탕을 만들었고 잣 삼계탕과 쑥 삼계탕을 최초로 개발하여 30년 동안 승승장구했습니다. 최근에는 고기를 저온으로 익히는 수비드 기계를 사용해 닭의 퍽퍽한 식감을 없애고 부드러운 식감을 살려내어 조리하는 방식에 성공했습니다. 수비드 기계 또한 최적의 상태를 유지하기 위해 부품을 사와 직접 만들었는데 최고의 삼계탕을 향한 열정으로 가능한 일이었습니다. 그 외 각종 소스, 닭도리탕용 고추장 등 모든 양념도 직접 개발하고 만들어 3대 삼계장인 만의 고유한 맛을 창조하고 있습니다.', 37.491303, 127.011591, '2만원대', '지하철 2 / 3호선 교대역 14번 출구에서 277m', '삼계탕, 닭볶음탕', '', ' https://www.instagram.com/cangweon9366', '음식점', '', '10:50~22:00', '02-522-2270', '없음'),
	(762, '휘가로', '08814  서울 관악구 신림로11길 20 (신림동)', 'images/휘가로_762.jpg', '안주 하나에 4천원 덤 안주가 있는 가성비 호프집\n\n녹두거리라 불리는 서울대 옆 고시촌의 터줏대감과 같은 호프집입니다. 휘가로를 모르면 서울대생이 아니라고 할 만큼 오랫동안 학생들의 단골집으로 자리를 지켜왔습니다. 변함없이 저렴한 가격 덕분에 주머니가 가벼운 학생들과 고시생들에게는 언제나 고마운 가게입니다. 녹두거리에서 학생운동이 한창이던 시절에는 시위 중인 학생들이 이곳에 몸을 숨기기도 했습니다. 휘가로는 당시 학생들이 울분을 삭이고 스트레스를 풀기 위해 찾던 장소였습니다.', 37.469593, 126.938725, '', '지하철 신림선 서울대벤처타운역 2번 출구, 617m', '맥주, 볶음밥, 해물전', '매일', '', '술집, 바', '', '16:00~손님들이 원하는 시간까지', '02-889-1722', '없음'),
	(763, '[백년가게] 군산오징어', '05602  서울 송파구 삼학사로 101 (삼전동, 군산오징어)  4층', 'images/[백년가게]_군산오징어_763.jpg', 'Since 1988, 군산오징어는 석촌호수 서호사거리에 위치한 오징어 불고기 전문점. 천연 재료로 만든 군산오징어만의 비법양념장은 알싸한 감칠맛이 일품, 캡사이신이 들어있지 않아 깔끔하고 기분 좋은 매운맛.\n\n1988년 서울 석촌동에서 테이블 7개로 출발한 군산오징어의 시작은 거창하지 않았습니다. 원가절감보다 내 가족의 식탁에 올릴 수 있는 건강한 재료들로 넉넉한 양을 제공한다는 기본 원칙으로 이어지고 있습니다. 군산오징어만의 차별화된 기분 좋은 매운맛은 인위적인 캡사이신을 포함하지 않고 천연재료로 만든 비법소스로 알싸한 감칠맛과 깔끔한 맛이 일품이며 창업 때부터 지금까지 이어온 군산오징어만의 고집이며 자부심입니다.\n\n\n\n\n군산오징어는 집에서도 손쉽게 만나실 수 있도록 가정간편식을 온라인에서 구매할 수 있으며 해외시장에도 진출하여 한식의 우수성을 널리 전하고 있습니다.', 37.506283, 127.097002, '3만원대', '지하철 9호선 석촌고분역 1번 출구에서 약 428m (도보 6분)', '오징어불고기, 오삼불고기, 오낙불고기, 낙곱새(낙지+곱창+새우), 갑오징어불고기', '매일', ' http://www.sanmoori.co.kr/', '음식점', '', '매일 11:30 ~ 22:30', '02-413-2046', ''),
	(764, '잉꼬네떡볶이', '02060  서울 중랑구 용마산로120길 43', 'images/잉꼬네떡볶이_764.jpg', '온·오프라인을 주름잡는 망우동 떡볶이 맛집\n\n1978년부터 변함없는 맛으로 망우동 떡볶이 강자의 자리에 오른 곳입니다. 7개 학교가 모여있어 떡볶이 포장마차촌이 형성되었던 시절부터 지금까지 많은 이들의 추억 속에 남아 있는 분식집입니다. 시어머니에게서 며느리로, 그리고 이제는 아들로 3대째 가업 계승에 있습니다. 다른 첨가물 없이 1대 사장님의 가르침과 똑같이 우직하게 만드는 떡볶이엔 손님을 향한 예의가 담겨 있습니다. 얼큰하고 칼칼한 떡볶이를 한입 먹으니 학교 앞에서 먹던 옛날 맛 그대로가 느껴집니다.', 37.602209, 127.101148, '', '지하철 경의중앙선 양원역 2번 출구, 815m', '', '', '', '음식점', '', '평일 11:30~18:00\n토,일요일 10:30~17:00', '02-2207-3603', '화요일'),
	(765, '효성한의원', '02569  서울 동대문구 약령중앙로 5 (제기동, 대산빌딩)', 'images/효성한의원_765.jpg', '체질 맞춤 진료와 한방차를 함께 즐길 수 있는 곳\n\n40년 전통의 효성한의원은 한의원과 ‘다미가(茶美家)’라는 한방카페를 함께 운영하고 있다는 점이 특이합니다. 한의학에서 사람의 체질은 태양인, 태음인, 소음인, 소양인 4가지로 나누는데 간단한 체질 문답 테스트를 통해 자기 체질에 맞는 한방차를 알려줍니다. 차의 종류는 6가지가 있는데 효능도 다이어트, 원기회복, 혈액순화, 호흡기정화, 간기능보호, 스트레스 등 다양합니다. 한의원에는 체질약물을 사용한 한방차의 제조방법과 특허증이 보도된 기사가 진열되어 있습니다.', 37.578834, 127.036595, '', '지하철 1호선 제기동역 2번 출구, 104m', '', '화, 목, 토, 일', ' https://blog.naver.com/cjswldls60', '', '', '11:00~17:00', '02-961-5544', '월, 수, 금'),
	(766, '[백년가게] 블랑제리(르팡)', '06574  서울 서초구 방배로 268 (방배동, 방배삼호상가)  102호', 'images/[백년가게]_블랑제리(르팡)_766.jpg', '41년의 제빵 외길 인생의 걸음과 원칙을 투영하는 웰빙빵집\n\n블랑제리 르팡은 28년 가까이 지역을 대표하는 빵집으로 거듭난 백년가게입니다. 41년 동안 제과, 제빵 외길을 걸어오고 있는 창업주의 기술력으로 100% 유기농 밀가루, 천연버터, 천일염, 천연발효종을 사용해 숙성시킨 웰빙빵을 만들어내고 있습니다. \n\n\n\n\n블랑제리 르팡의 시그니처 메뉴는 국산 공주밤을 듬뿍 넣어 만든 공주알밤식빵과 오징어 먹물, 크림치즈, 견과류로 만든 먹물크림치즈빵입니다. 여느 빵집에나 있는 흔한 빵이지만, 블랑제리 르팡의 밤빵과 크림치즈빵은 심혈을 기울인 정성과 재료에 대한 진심이 가미되어 특별한 빵으로 거듭나고 있습니다. 반죽 하나를 만들 때도 완두콩, 코코넛 워터, 조청, 완두콩즙, 천일염 등 수많은 천연 재료가 들어가고, 무수한 실패 끝에 완성해 낸 조리법으로 빵이 만들어집니다. 재료 역시 언제나 최고급만을 활용합니다. \n\n\n\n\n국내에서 가장 상품성이 뛰어난 공주알밤을 사용하고, 오징어 먹물은 최고급으로 인정받는 스페인산을 쓰며 치즈는 필라델피아산을 사용합니다. 좋은 빵은 최고의 재료와 장인의 정성에서 비롯된다는 블랑제리 르팡만의 원칙 때문입니다.', 37.496686, 126.988421, '', '지하철 9호선 구반포역 1번 출구, 727m', '베이커리, 공주밤빵, 먹물식빵, 완두만주', '', ' http://instagram.com/lepain__', '카페, 디저트', '', '07:30 ~ 22:30', '02-533-4600', '일요일 정기휴무'),
	(767, '서울리즘', '05620  서울 송파구 백제고분로 435 (송파동, 예스빌딩) 6층', 'images/서울리즘_767.png', '잠실 롯데월드타워와 서울 시내를 한 눈에 볼 수 있는 전망 좋은 곳\n\n롯데월드타워를 배경으로 아름다운 인생샷을 남길 수 있는 서울리즘입니다.', 37.509796, 127.111536, '', '지하철 9호선 송파나루역 1번 출구, 62m', '', '', ' https://www.instagram.com/seoulism_official/', '음식점', '', '화~일 12:00~01:00', '02-412-0812', '월요일'),
	(768, '3대삼계장인', '06646  서울 서초구 반포대로28길 56-3 (서초동, 한라빌딩) 1층', 'images/3대삼계장인_768.jpg', '30년 이상 명맥을 유지하면서 오랫동안 사람들의 사랑을 받아온 백숙, 삼계탕 전문점\n\n1973년 가게 문을 연 이래 3대째 대를 이어 내려오고 있는 삼계탕집, 3대삼계장인. 잣, 녹두, 쑥 세 종류의 삼계탕과 수비드 닭볶음탕을 판매하고 있습니다. 더위에 지친다면, 3대삼계장인에서 뜨거운 삼계탕 한 그릇으로 든든한 기운을 얻어보세요.', 37.491303, 127.011591, '', '지하철 2/3호선 교대역 14번 출구, 277m', '', '', '', '음식점', '', '매일 10:50~22:00', '0507-1465-2294', ''),
	(769, '[백년가게] 풍남골뱅이', '04550  서울 중구 수표로 50-1 (을지로3가)', 'images/[백년가게]_풍남골뱅이_769.jpg', '서울의 정겨움이 남아있는 을지로 한 켠에 새콤한 골뱅이무침.\n\n서울의 정겨움이 남아있는 을지로 한 켠에 새콤한 골뱅이무침 냄새가 퍼집니다. 풍남골뱅이는 을지로의 골뱅이 골목에서 가장 오래된 전통을 자랑하는 골뱅이 맛집입니다. 1984년에 부모님이 시작한 가게를 자녀가 승계한 풍남골뱅이는 전통의 맛을 유지하기 위해 끊임없는 발전을 도모하고 있는 백년가게입니다. \n\n주요 메뉴인 골뱅이무침은 어릴 적부터 부모님 밑에서 가업을 승계한 2대 대표와 창업주만이 조리해 품질을 유지하고 있고, 모든 식재료는 직접 눈으로 보고, 확인한 후 구매합니다. 골뱅이무침의 맛을 좌우하는 국수는 제면소에서 뽑아오고, 골뱅이는 창업주나 2대 대표가 직접 맛을 본 신선한 국내산 제품을 선별해 공급받습니다. 고춧가루와 들기름 등의 식자재 역시 30년 넘게 거래하고 있는 들기름 전문업체에서 제공받아 신선한 음식을 만듭니다. 맛이 탁월해 프랜차이즈 제안도 많았으나, 음식의 퀄리티가 저하될 것을 우려해 거절한 풍남골뱅이는 골뱅이 골목에서 40년 넘게 전통의 맛을 지켜나가고 있는 골뱅이 전문점으로 고객들의 사랑을 한 몸에 받고 있는 백년가게입니다.', 37.565674, 126.989983, '', '지하철 2 / 3호선 을지로3가역 11번 출구, 65m', '골뱅이, 계란말이 등', '', '', '음식점', '', '월요일~토요일 15:30~23:30', '02-2265-2336', '일요일 정기휴무'),
	(770, '평택쌀상회', '08568  서울 금천구 독산로40길 27-5', 'images/평택쌀상회_770.jpg', '햇살과 바람으로 자연 건조해 만드는 국수\n\n30년째 옛 방식 그대로 국수를 만들어 파는 곳입니다. 이곳에서는 공장에서 열풍기로 건조하는 국수가 아니라 햇살과 바람 속에서 자연 건조되는 국수를 만나볼 수 있는 곳입니다. 기계가 아닌 사람과 자연이 빚은 국수입니다. 일반 국수뿐만 아니라, 단호박국수, 보리국수, 쑥국수, 백년초국수 등 다양한 색의 소면들을 만날 수 있으며, 소면, 중면, 대면 등 다양한 굵기의 국수를 만듭니다. 옛날에는 쌀도 판매했지만 국수를 찾는 사람들이 훨씬 많아 지금은 국수만 제조합니다.', 37.461044, 126.907474, '', '지하철 1호선 금천구청역 1번 출구, 1.4km', '소면, 중면, 대면', '매일', '', '음식점', '', '08:00~20:00', '02-895-4825', '없음'),
	(771, '서우제과', '06680  서울 서초구 방배중앙로 50', 'images/서우제과_771.jpg', '마늘빵과 연유 맛이 나는 특별한 뻥튀기\n\n1980년부터 지금까지 고소한 뻥튀기 냄새가 가실 날이 없었던 곳입니다. 뻥튀기 장사를 해오시던 아버지와 기계공학 및 물리학을 전공하던 아들의 협업으로 뻥튀기 기술을 활용한 누룽지 과자를 개발하였습니다. 쌀로 만든 뻥튀기에 마늘 바게트 맛과 연유 맛을 입힌 누룽지 과자가 탄생하였고, 가게의 대표상품이 되었습니다. 손님마다 입을 모아 ‘뻥튀기 맛의 표준은 서우제과다’라고 말하기에 오늘도 가게의 문은 활짝 열려있습니다.', 37.490424, 126.987202, '', '지하철 7호선 내방역 4번 출구, 599m', '', '월요일~토요일', ' https://smartstore.naver.com/seowoonrg', '카페, 디저트', '', '월요일~토요일 09:00~19:00', '02-522-5633', '일요일'),
	(772, '[백년가게] 나주곰탕우정집', '06130  서울 강남구 강남대로94길 57 (역삼동, 역삼동빌딩)  1층', 'images/[백년가게]_나주곰탕우정집_772.jpg', '맑은 국물에 파와 계란지단이 올라간 나주곰탕과 잡내를 완벽히 제거한 양곰탕 맛집.\n\n나주곰탕우정집은 다니던 직장을 그만둔 창업주가 1989년, 대전에서 양곰탕을 창업하면서 시작되었습니다. 철저한 분석과 체계적인 경영으로 대전에서 노하우를 쌓은 창업주는 2009년 서울로 올라와 지금의 나주곰탕우정집을 오픈, 오늘에 이르고 있습니다. 특별한 기술이 없었기에 1대 이완구 대표는 전국의 수많은 유명 음식점을 다니며 맛과 경영 방식을 벤치마킹했고, 이 같은 노력으로 나주곰탕우정집의 성공을 이룩할 수 있었습니다. 나주곰탕우정집의 대표메뉴인 나주곰탕은 파와 계란지단을 얹은 맑은 국물이 특징으로 음식맛을 위한 창업주의 고뇌와 노력이 엿보이는 음식입니다. \n\n매일 아침마다 마장동에서 들여오는 신선한 고기를 사용하고, 월계수, 소주, 마늘, 양파 등을 활용해 국물을 냅다. 양곰탕 역시 정성이 가득 들어갑니다. 소의 위에서 나는 특유의 냄새를 잡기 위해 찬물로 20회 이상 세척해 냄새를 잡고, 반찬도 여력이 될 때는 무조건 직접 담아 제공하고 있습니다.', 37.500600, 127.031890, '1만원대', '지하철2호선 역삼역 4번 출구, 339m', '나주곰탕, 삼겹살', '', '', '음식점', '', '월요일~금요일 11:00~15:00, 17:00~23:00', '0507-1431-6611', '토요일~일요일'),
	(774, '공항칼국수', '07622  서울 강서구 공항대로 18-1 (공항동, 이스카이오피스텔)  지하 1층', 'images/공항칼국수_774.jpg', '한우 육수에 얼큰한 양념장을 넣은 버섯칼국수\n\n1979년 개업 후 대를 이어 45년간 운영하는 공항칼국수는 김포공항 앞 소문난 맛집입니다. 푹 고아 낸 한우 육수에 얼큰한 양념장을 넣은 버섯칼국수의 칼칼한 국물 때문에 45년간 손님들의 발걸음이 끊이지 않습니다. 칼국수를 다 먹고 난 뒤 그 국물에 볶음밥을 만들어 먹는 것 또한 별미입니다. 가게에서 먹는 그대로 집에서 요리할 수 있게 만든 밀키트도 판매합니다.', 37.560960, 126.809129, '1만원대', '지하철 5호선 송정역 4번 출구, 180m', '버섯칼국수, 내장칼국수', '매일', '', '음식점', '', '09:30~22:00 (라스트오더 21:20)', '02-2664-9748', '없음'),
	(775, '미림분식', '서울 관악구 호암로 553', 'images/미림분식_775.jpg', '8090 학창시절 향수가 있는 여고 앞 즉석 떡볶이\n\n1988년부터 미림여고 옆을 지키고 있는 떡볶이 분식집. 제대로 된 간판은 없지만 오랜 세월 변함없는 모습으로 학창시절의 추억을 고스란히 간직한 곳입니다. 당면, 만두, 라면, 어묵 등 입맛에 따라 골라 넣은 미림분식의 시그니처 메뉴는 즉석 떡볶입니다. 영화 <불한당> 주인공 배우 설경구가 떡볶이를 먹는 장면을 이곳에서 촬영해서 영화명소로 찾는 사람도 있습니다.', 37.459053, 126.927666, '', '지하철 신림선 서울대벤처타운역 2번 출구, 608m', '고추장 떡볶이, 짜장 떡볶이', '매일', '', '음식점', '', '11:30~20:00', '02-888-8567', '없음'),
	(776, '목구멍 홍대입구역점', '03992  서울 마포구 월드컵북로4길 8 (동교동)', 'images/목구멍_홍대입구역점_776.jpg', '홍대에 위치한 솥뚜껑 고깃집\n\n홍대입구역에 위치한 목구멍은 삼겹살, 갈비, 목살 등 다양한 고기를 솥뚜껑에 구워 먹을 수 있는 고깃집입니다. 특히 삼겹살과 미나리를 함께 구워 먹는 것이 이곳의 매력입니다. 목구멍 홍대입구역점에서는 직원들이 직접 고기를 구워주기 때문에 고기 본연의 맛을 느낄 수 있고 직원들이 매장을 돌아다니며 부족한 야채를 리필해주어 친절한 서비스를 경험할 수 있습니다. 또한 회냉면, 비빔면, 찌개류 등 다양한 사이드 메뉴도 제공되어 고기와의 다채로운 조합을 즐길 수 있습니다. 넓고 쾌적한 매장과 가게 앞에 주차도 가능해 단체로 방문하기에도 좋은 식당입니다.', 37.556734, 126.920510, '2만원대', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 1번 출구, 379m', '', '매일', ' https://www.moggumung.com/', '음식점', '가게 앞 주차 6대까지 가능', '매일 12:00 ~24:00 (라스트오더 23:30)', '0507-1418-2930', ''),
	(777, '연과점 하루', '04029  서울 마포구 동교로16길 12 (서교동) 1층', 'images/연과점_하루_777.png', '지역특산물로 만든 고급 선물용 K-디저트를 맛 볼 수 있는 곳\n\n연과점 하루는 조선시대 문헌에 기록된 간식인 \'연과\'를 현대인의 입맛에 맞게 재해석한 디저트를 맛볼 수 있는 곳입니다. 재료 본연의 맛과 특별한 식감을 표현하기 위해 매일 한정 수량을 수제로 생산합니다. 외국인을 위한 영어 메뉴판과, 휠체어나 유모차를 이용하는 고객도 편히 접근이 가능한 유니버셜디자인(Universal design)으로 기획하여 다양한 고객에게 편의를 제공하는 곳입니다.', 37.554286, 126.915355, '', '지하철 2 / 6호선 합정역 2번 출구, 500m', '연과', '화요일~토요일', ' https://www.instagram.com/projectharu.kr/', '카페, 디저트', '휠체어와 유모차 접근 가능', '11:00~18:00', '0507-1402-7706', '일요일, 월요일'),
	(778, '마키노차야 마포점', '04168  서울 마포구 마포대로 92 (도화동, 효성해링턴 스퀘어) A동 9층(L층)', 'images/마키노차야_마포점_778.png', '"나의바다에서 당신의 식탁까지" 프리미엄 뷔페 레스토랑\n\n마키노차야 마포점은 \'나의 바다에서 당신의 식탁까지\' 라는 슬로건으로, 한식, 양식, 중식, 일식, 디저트 등 프리미엄 메뉴만을 엄선하여 고객님께 제공해 드리는 프리미엄 뷔페 레스토랑입니다. 단순한 \'뷔페\' 레스토랑이 아닌 음식을 통해 일상의 \'가치\'있는 \'경험\'을 제공하며, 화려하고 트렌디한 곳이기 보다는 정직하고 담백하게 \'본질에 충실한 음식\'을 엄선해서 소개하고, 고객이 원하는 음식을 보다 \'위생적이고 안전하게\' 드실 수 있는 환경을 만들기 위해 노력하고 있습니다.', 37.542931, 126.951246, '', '지하철 5호선/6호선/공항/경의중앙선 공덕역 9번 출구, 15m', '', '', ' https://makinochaya.co.kr', '음식점', '사전 예약 필수', '11:30~21:00 (15:00~18:00 브레이크 타임)', '02-565-1116', ''),
	(779, '위드달걀빵', '04313  서울 용산구 청파로47가길 5 (청파동3가)  1층 위드달걀빵', 'images/위드달걀빵_779.jpg', '숙대입구역에 위치한 명물 계란빵\n\n숙대의 유명한 명물 빵, 위드달걀빵. 한국의 길거리 음식으로 유명한 \'계란빵\'을 다양한 맛으로 변형시켰습니다. 깔끔한 매장에서 즐기는 계란빵은 지역의 유명한 명물. 방송에도 등장할 정도로 한국 디저트로서 개성과 정체성을 두루 갖추고 관심을 받고 있습니다.', 37.544687, 126.966973, '', '지하철 4호선 숙대입구역 9번 출구, 495m', '', '매일', ' https://www.instagram.com/with_dalgyalbbang/', '카페, 디저트', '택배 주문 가능', '평일 09:00~22:30\n주말 12:00~22:00', '0507-0284-4304', ''),
	(780, '등촌 최월선칼국수', '07571  서울 강서구 화곡로64길 68 (등촌동)', 'images/등촌_최월선칼국수_780.jpg', '30년 전통의 버섯매운탕\n\n주택가 작은 골목, 세련된 간판 대신 오래된 문 위에 ‘칼국수’, ‘버섯매운탕’이라고 투박하게 쓰인 글씨가 정겨운 식당입니다. 이곳의 유일한 식사 메뉴는 버섯매운탕. 매운탕을 주문하면 칼국수, 볶음밥까지 함께 나오기 때문에 착한 가격으로 푸짐한 한 끼를 즐길 수 있습니다. 탕에는 신선한 마늘과 느타리버섯, 미나리가 듬뿍 들어가며, 칼국수보다는 우동 면에 가까운 쫄깃하고 통통한 면발을 사용하는 것이 특징입니다.', 37.556043, 126.856708, '1만원대', '지하철 9호선 증미역 4번 출구, 580m', '버섯매운탕', '매일', '', '음식점', '', '평일 11:30~15:00, 16:00~21:30 / 주말 11:30~16:00, 17:00~21:30', '02-3661-2744', '없음'),
	(781, '삼우치킨센타', '07442  서울 영등포구 시흥대로 671 (대림동)', 'images/삼우치킨센타_781.jpg', '어린 시절 아버지가 퇴근길에 사 오시던 통닭\n\n1972년부터 아버지가 연 가게를 아들이 물려받아 2대째 이어오고 있는 통닭집입니다. 7080세대의 유년 시절 감성을 자극하는 맛으로 한곳에서 오래도록 유지한 터라 3대째 찾는 손님들도 있습니다. 그 시절의 인테리어를 그대로 유지한 가게 내부는 단골손님들의 추억이 깃든 장소입니다. 매일 정성이 담긴 재료 손질과 직접 담근 치킨 무, 고소하고 바삭한 프라이드와 쫄깃한 전기 통닭구이의 맛은 앞으로도 변함없이 계속될 것입니다.', 37.491643, 126.908158, '1만원대', '지하철 2호선 신대방역 4번 출구, 814m', '후라이드 치킨, 전기구이 치킨, 골뱅이소면', '매일', '', '음식점', '', '12:00~24:00', '02-844-9292', '없음'),
	(782, '[백년가게] 뚱뚱이할머니집', '04606  서울 중구 장충단로 174-1 (장충동1가)', 'images/[백년가게]_뚱뚱이할머니집_782.jpg', '장충동 원조 족발집중 하나이며, 3대 거쳐 계승된 족발 맛집.\n\n기름진 족발이 가게 앞을 수놓고 있습니다. 수많은 족발들이 고객을 유혹하는 대한민국 족발 1번지, 장충동에서 원조 족발집으로 유명한 곳 중 하나가 뚱뚱이할머니집입니다. 1대 전숙렬 창업주는 60년대 어머니가 해준 족발의 맛을 떠올려 뚱뚱이할머니집을 시작하게 되었습니다. 족발 맛이 입소문이 나면서 자연스럽게 주변에 족발집들이 생겨났고 지금의 장충동 족발 골목이 탄생했습니다. 이후 2대 며느리 김명숙 대표와 3대 손녀 김송현 이사가 뚱뚱이할머니집의 전통을 이어나가고 있습니다. \n\n\n\n\n뚱뚱이할머니집은 즐비한 족발집들 사이에서 단연 돋보입니다. 경쟁업체들이 모두가 가격을 인상할 때 유일하게 가격을 유지하며 고객들의 만족도를 지켰습니다. 또한, 1인 메뉴 및 세트메뉴를 개발하고 배달 서비스와 다양한 프로모션을 도입하는 등 신속하게 트렌드를 반영하고 있습니다. 이는 대부분의 노포들이 새로운 트렌드의 반영이 늦은 점에서 매우 높은 차별성을 가집니다.', 37.560413, 127.005895, '', '지하철 3호선 동대입구역 3번 출구, 156m', '족발, 쟁반국수, 파전 등', '', ' https://blog.naver.com/kimsh00921', '음식점', '', '10:00~23:00', '02-2279-2714', '화요일'),
	(783, '옛날집낙원아구찜', '03133  서울 종로구 삼일대로 436 (낙원동)', 'images/옛날집낙원아구찜_783.jpg', '부드럽고 매콤한 아구살이 특징인 낙원동 터줏대감\n\n낙원아구찜은 서울식 아귀찜의 원조임을 자신하는 오래가게이자 백년가게로 1977년부터 40년 가까이 한 자리에서 영업을 이어가고 있는 아귀찜 가게입니다. 낙원아구찜을 창업한 부모님은 해안가에서 아귀를 말려 조리하는 마산식 아귀찜을 요리하겠다는 포부로 상경했지만, 서울에서는 아귀를 건조할 장소가 없어 어쩔 수 없이 생물 아귀를 바로 손질해 만드는 서울식 아귀찜을 개발해 서비스하게 되었습니다. 서울식 아귀찜은 고객들의 호평을 받으며 낙원아구찜의 주요 메뉴로 자리 잡게 되었습니다. 가업을 승계한 2대 대표는 서울식 아귀찜의 원조라는 타이틀과 원조의 맛을 지키기 위해 언제나 신선한 식재료를 공수하는 데 최선의 노력을 다합니다. 매일 새벽에 직접 노량진 시장에서 생물 아귀를 공수하며 양념은 국산재료만을 사용합니다. \n\n\n\n\n한때 프랜차이즈 제안까지 받았을 정도로 음식의 맛은 뛰어나지만, 일정치 않은 생물 아귀의 수급을 이유로 거절했습니다. 어떤 경우에도 타협할 수 없는 음식의 맛을 지키기 위한 결단이었습니다. 전통을 지켜나가려는 2대 대표자의 노력 덕에 낙원아구찜은 2019년에 서울 미래유산에 선정되어 근현대 문화유산 인증서를 받으며 전통의 위엄을 선보인 바 있습니다.', 37.573500, 126.988001, '', '지하철 1 / 3 / 5호선 종로3가역 5번 출구, 167m', '아귀찜, 아귀탕, 해물찜, 해물탕 등', '', '', '음식점', '', '11:30 ~ 22:00', '02-741-3621', ''),
	(784, '도산정육 청담본점', '06018  서울 강남구 선릉로155길 12 (신사동, 웬즈데이빌딩) 1층', 'images/도산정육_청담본점_784.png', '도산근원 근처 맛있고 찰기있는 숙성돼지고기를 맛볼 수 있는 곳\n\n도산정육 본점은 고기의 본질을 1순위로 생각하는 도산 대표 맛집입니다. 도산정육만의 체계적인 숙성과정을 통해 찰기있고 응축된 고기맛을 느껴보세요!', 37.525600, 127.038827, '2만원대', '지하철 수인분당선 압구정로데오역 5번 출구, 246m', '한우물회 18,000원 / 제주꽃목살 19,000원 / 제주오겹살 19,000원 / 제주삼겹살 19,000원', '', '', '음식점', '태블릿주문(영어,일본어 언어 지원)', '월요일~금요일 11:30~01:00 (15:00~17:00 브레이크타임)\n토요일~일요일 12:00~01:00 (15:00~17:00 브레이크타임)', '02-546-9206', ''),
	(785, '안동집 손칼국시', '02571  서울 동대문구 고산자로36길 3 (제기동, 경동시장)  신관 지하1층', 'images/안동집_손칼국시_785.png', '흑백요리사 이모카세 1호가 운영하는 칼국수 전문점\n\n안동집 손칼국시는 경동시장에 위치한 칼국수 전문점으로, 넷플릭스 요리 경연 프로그램 흑백요리사에서 ‘이모카세 1호’로 유명한 김미령 셰프가 운영하는 곳입니다. 이곳은 밀가루 대신 40%의 콩가루를 섞어 만든 반죽을 얇게 밀어 직접 썰어내며, 부드러운 면발과 고소한 국물 맛이 특징입니다.\n\n\n\n\n대표 메뉴는 손칼국시로, 맑고 깊은 멸치 육수에 담긴 면발과 함께 파릇한 배추가 어우러져 깔끔한 맛을 즐길 수 있습니다. 간장 양념, 청양고추, 다진 마늘을 곁들여 각자의 취향대로 맛을 조절할 수 있습니다. 함께 제공되는 배춧잎과 된장으로 조를 넣어 지은 밥을 싸먹는 것도 별미.\n\n\n\n\n칼국시 외에도 쫄깃한 수육과 바삭한 배추전이 인기 메뉴로, 다양한 요리를 함께 즐길 수 있습니다. 손칼국시의 정성스러운 맛과 함께 전통의 풍미를 느낄 수 있는 안동집 손칼국시에서 특별한 한 끼를 경험해 보세요.', 37.579038, 127.039143, '1만원대', '지하철 1호선 제기동역 2번 출구, 328m', '', '월~일', '', '음식점', '', '월~금 10:00 ~18:00\n토 10:00 ~ 17:00', '02-965-3948', '매달 2,4번째 일요일 정기 휴무'),
	(786, '[백년가게] 고려정', '07328  서울 영등포구 국제금융로6길 30 (여의도동, 백상빌딩)  116호', 'images/[백년가게]_고려정_786.jpg', '35년의 손맛이 담긴 된장과 소스와 고기의 조화로움을 경험 할 수 있는 식당\n\n고려정은 35년 가까이 한 자리에서 한식을 서비스하고 있는 가게입니다. 고려정은 왕갈비탕, 우거지내장탕, 양곰탕, 선지해장국, 오차돌솥밥, 매장에서 직접 제조한 된장으로 조리한 차돌된장찌개 등의식사류와 차돌박이, 치맛살, 소막창 등의 육류를 전문으로 서비스하고 있는데, 이중 고객들의 반응이 가장 뜨거운 것은 단연 차돌박이와 된장찌개입니다. 30년을 이어온 창업주의 손맛이 깃든 특제소스와 고려정만의 전통 된장기법으로 만든 된장찌개가 고기의 풍미를 더욱 살려주며 호평을 이끌어내고 있습니다.\n\n\n\n\n 육류 외에 고려정의 모든 메뉴에는 어린 시절 누구나 한 번쯤은 느꼈던 어머니의 깊은 손맛이 묻어있습니다. 창업주와 2대째 가업 계승자가가 직접 제조에 참여하여, 균일한 품질의 음식을 고객에게 오랜 기간 동안 제공합니다.', 37.521724, 126.926604, '2만원대', '지하철 5 / 9호선 여의도역 5번 출구, 313m', '차돌박이, 갈비살', '', '', '음식점', '', '10:00~22:00', '0507-1337-0093', '토요일, 일요일 정기휴무'),
	(787, '더브레드블루 신촌본점', '04057  서울 마포구 신촌로12다길 3 (노고산동)  1층', 'images/더브레드블루_신촌본점_787.jpg', '비건 베이커리 더브레드블루\n\n더브레드블루는 100% 식물성 재료만으로 맛있는 빵을 만드는 비건 베이커리입니다. 직접 배양한 천연발효종을 사용하여 만든 쌀눈유, 두유, 콩 단백질 등의 건강한 식물성 재료가 들어간 다양한 베이커리 제품들을 만나 볼 수 있습니다.', 37.555154, 126.932786, '', '지하철 2호선 신촌역 8번출구, 350m', '베이커리 제품', '', ' https://www.thebreadblue.com', '카페, 디저트', '', '매일 12:00~19:30', '0507-1425-0723', ''),
	(788, '[백년가게] 장군갈비', '04931  서울 광진구 용마산로 11 (중곡동, 장군갈비)', 'images/[백년가게]_장군갈비_788.jpg', '가성비와 맛 두 마리 토끼를 다 잡은 41년 된 갈비집\n\n장군갈비는 1980년 창업 이후 41년 동안 ‘정직한 음식’이라는 원칙을 철저하게 실천해오고 있는 고기, 갈비탕 전문점입니다. 83년부터 장군갈비에서 지배인으로 종사해 온 대표자는 타고난 근면, 성실함으로 창업주의 신뢰를 얻었고, 2011년부터 점포를 양도받아 운영해 오고 있습니다. \n\n언제나 정직한 음식을 제공하기 위해 노력하는 장군갈비는 높은 원가율을 감안하면서도  항상 고객들에게 푸짐한 음식을 선사합니다. 고기는 일부 수입산을 제외하면 한우1++ 등급을 유지하고 있으나 다른 경쟁업체에 비해 양은 많고, 가격은 낮게 책정해 고객들이 더 많은 고기를 드실 수 있도록 배려하고 있습니다. 사골과 양지, 사태를 삶은 옛 방식으로 끓인 육수가 인상적인 냉면은 32년을 함께해 온 주방장이 직접 제조합니다. 장군갈비에서 소비되는 모든 반찬은 사지 않고 직접 만들고 있으며 재료는 충남 보령에서 농사를 짓는 누님이 보내준 것을 활용하고 있습니다.', 37.554718, 127.088120, '3만원대', '지하철5호선 아차산역 1번 출구, 335m', '한우생갈비, 한우양념갈비, 꽃등심,한우불고기, 갈비탕', '매일', '', '음식점', '', '11:00~21:00', '02-447-3479', '없음'),
	(789, '[백년가게] 섬진강민물장어', '01038  서울 강북구 한천로 1151 (수유동)', 'images/[백년가게]_섬진강민물장어_789.jpg', '산지작송의 장어와 신선한 야채와 약재로 우려낸 소스 그리고 40년의 정으로 조리한 민물장어 맛집.\n\n섬진강 민물장어는 1984년 개업한 이래 최고의 장어요리와 서비스를 제공하며 40여 년을 이어온 강북구 수유동의 대표적인 외식 명소입니다. 모든 재료는 직접 산지에서 공수하며 품질과 신선도를 관리합니다. 장어는 통째로 수급하여 주문이 들어오면 신선한 생물을 꺼내어 사용 하고, 여기에 고유한 비법에 따라 신선한 야채와 약재 넣어 10시간을 우려낸 소스와 양념장을 곁들여 조리합니다. 밑반찬 역시 매일 아침 국내산 재료로 손수 만들어 풍성함을 더합니다. \n\n단골에게는 다양한 추가 서비스를 아끼지 않고 예약 손님에게는 직접 손 편지를 쓰는 등 정감 있는 고객 서비스를 제공하는 점 역시 섬진강식당이 오랫동안 사랑받아온 비결입니다.', 37.646612, 127.017099, '', '지하철 우이신설선 4.19민주묘지역 1번 출구, 491m', '민물장어, 장어솥밥, 장어탕 등', '', '', '음식점', '', '월요일~일요일 11:30~21:30 (15:00~17:00 브레이크 타임)', '02-993-9545', ''),
	(790, '[백년가게] 민정식당', '05054  서울 광진구 아차산로42길 41-4 (자양동)', 'images/[백년가게]_민정식당_790.jpg', '5대째 자양동에서 산 토박이가 30년째 운영하는 한식집\n\n5대째 자양동에서 살고 있는 토박이가 지역 주민들을 위해 만드는 다양한 음식으로 유명한 민정식당은 1995년에 창업해 30년 가까이 명성을 이어오고 있는 백년가게입니다. 항상 최고의 식재료를 직접 구매, 조리해 내놓는 민정식당은 고객을 마치 집에 오신 손님처럼 접대하며 친절한 서비스를 자랑합니다. 설렁탕과 수육, 돈까스가 주 메뉴로 손님들의 연령대에 따라 달라지는 입맛과 니즈를 거의 완벽히 충족하고 있다고 자신합니다. 매일 식재료를 구입, 당일 소진하여 신선함을 유지하고 있으며 건강한 식당이라는 입소문으로 인해 방문하는 고객이 매일 조금씩 늘어나고 있습니다.  자택의 1층에서 식당을 운영하고 있어 마치 초대받은 집에서 식사하는 기분을 선사하고, 조용하고 소박한 인테리어로 인해 과거 할머니 집, 혹은 친구 집에 방문한 듯한 느낌을 줍니다.', 37.535576, 127.079022, '1만원대', '지하철 2호선 구의역 4번 출구, 680m', '모듬수육, 수제돈까스', '', '', '음식점', '', '11:00~15:00, 16:30~22:00', '02-452-3574', '일요일 정기휴무'),
	(791, '주신당', '04570  서울 중구 퇴계로 411 (흥인동)', 'images/주신당_791.jpg', '신당동에 위치한 독특한 컨셉의 칵테일바\n\n12지신을 테마로 운영되고 있는 독특한 컨셉의 칵테일바인 \'주신당\'은 신당동에서 시작된 오리엔탈 스피크이지바(Speakeasy Bar)입니다. 신당동은 현재에는 지명의 한자가 변경되었지만 과거에는 \'신을 모시는 동네\'라는 뜻과 함께 광희문을 중심으로 많은 무당들이 모여살게 되어 생긴 지명입니다. 예로부터 전해져오는 장소적 특성과 신당이 가진 의미를 12지신을 통해 재해석 하여 주신당만의 신비로움을 품은 공간으로 연출되었습니다. 주신당에서는 전통주를 활용한 \'12지신 시그니처 칵테일\'과 다양한 위스키, 한국의 식재료와 조리 기법을 오랜시간동안 연구하고 개발하여 주신당만의 스타일을 가진 다이닝 메뉴도 만나볼 수 있습니다.', 37.565934, 127.017211, '', '지하철 2 / 6호선 신당역 12번 출구, 108m', '', '월요일 ~ 일요일', ' https://www.instagram.com/zoosindang/', '술집, 바', '자세한 사항은 인스타그랩을 참고해주세요. @zoosindang', '평일 18:00 ~ 02:00, 주말 17:00 ~ 02:00 (요리 라스트오더 23:30, 주류 라스트오더 01:00)', '02-2231-1806', ''),
	(792, '[백년가게] 엘리제과자점', '01674  서울 노원구 동일로 1538 (상계동, 12단지 종합상가)  12단지 종합상가', 'images/[백년가게]_엘리제과자점_792.jpg', '월드대회 한국대표 경력이 있는 제빵사가 38년간 운영한 과자점\n\n엘리제과자점은 21세에 제빵계에 입문해 38년간 경쟁력을 키워온 제과 국가대표의 모든 역량이 총동원된 제빵 전문점입니다. 창업주인 최형일 1대 대표는 나폴레옹과자점에서 보조부터 시작해 생산차장까지 올라간 인물로 2002년 제과기능장을 취득했고, 2011년에는 제과 국가대표로 월드 대회에 출전한 경력이 있는 제과제빵 전문가입니다. 엘리제과자점은 본점과 2개의 분점으로 이루어져 있습니다. 끊임없는 제과, 제빵 연구로 탄생한 200여 가지의 빵과 쿠키가 고객의 선택을 기다리고 있으며 모든 빵은 밀가루와 쌀, 동물성 생크림 등 고급재료를 사용해 만들어져 트랜스지방 안심 제과점 인증을 받은 바 있습니다.', 37.666237, 127.057865, '', '지하철 7호선 마들역 1번 출구, 89m', '단호박 브레드, 크림치즈소보루 등', '', '', '카페, 디저트', '', '06:30 ~ 24:00', '02-936-2733', ''),
	(793, '글램 라운지 (Glam Lounge)', '04350  서울 용산구 이태원로27가길 26 (이태원동, 해밀톤호텔 별관) 2층', 'images/글램_라운지_(Glam_Lounge)_793.png', '글램 라운지는 국내 최초 대형 라운지 클럽으로 독보적인 컨셉과 스타일로 오랜 시간 이태원 뿐만 아니라 대한민국의 명소.\n\n글램 라운지는 국내 최초 대형 라운지 클럽으로 독보적인 컨셉과 스타일로 오랜 시간 이태원 뿐만 아니라 대한민국의 명소로 자리매김하고 있습니다. 이국적인 소품들과 고풍스러운 아치형 창문이 독창적인 조화를 이루면 절제된 화려한이 돋보이고, 미드 센추리 모던 스타일의 간결하고 감각적인 실내 인테리어와 이를 더욱 화려하게 뒷받침해주는 트렌디한 라운지 음악은 한정되지 않은 다양한 매력의 분위기를 선사합니다. 글램 라운지는 일식을 기반으로 다양한 아시아 음식을 접목시켜 메뉴를 개발하고, 매 시즌 어울리는 제철 생선을 이용한 스시와 사시미 메뉴를 구성하여 일반적인 라운지에서 경험하기 어려운 미식의 경험을 선사합니다. 또한 이와 조화를 이룰 수 있는 세분화된 시그니처 칵테일 메뉴와 트렌디한 와인 리스트를 구성하고 매년 업데이트 하여 트렌디한 소비자들에게 최상의 서비스를 제공합니다.', 37.535106, 126.993789, '', '지하철 6호선 이태원역 1번 출구, 111m', 'White Ragu Pasta 19,000원 | Poke 23,000원 | Futomaki (Half / While) 15,000원 / 28,000원 (매주 일-목요일까지 OPEN -~19:00 음식 20% Happy Hour)', '', ' https://www.districtglam.com/', '술집, 바', '미성년자 출입금지, 흡연 가능, 연중무휴', '일요일~목요일 19:00~03:00\n금요일~토요일 19:00~05:00', '02-796-6853', ''),
	(794, '눕카페&피자펍', '04337  서울 용산구 신흥로26길 20 (용산동2가)  해방타워 5', 'images/눕카페&피자펍_794.jpg', '남산타워의 풍경이 한눈에 들어오는 앤티크한 분위기의 카페&펍\n\n눕카페&피자펍은 해방촌에 위치한 500평 이상의 초대형 카페이자 펍으로, 특히 N서울타워가 보이는 탁트인 뷰로 유명합니다. 앤틱한 실내에서는 포켓볼을 즐기거나, 통창 앞에 놓여진 빈백에 누워 경치를 감상할 수 있습니다. 위층의 루프탑 공간에는 인조잔디, 스윙베드, 썬배드 등이 구비되어 있어 해가 저무는 시간대에는 마치 휴양지에 와있는 듯한 느낌입니다. 야외 테라스에서 N서울타워 뷰를 바라보며 시원한 생맥주와 맛있는 안주를 즐기고, 인생샷도 남겨보세요.', 37.545104, 126.983886, '', '지하철 4호선 숙대입구역 3번 출구, 1.3km', '', '매일', ' https://www.instagram.com/noopcafe/', '술집, 바', '', '매일 11:30 ~ 23:50', '02-790-0789', ''),
	(795, '옥류헌릴렉스', '01000  서울 강북구 삼양로181길 142 옥류헌릴렉스', 'images/옥류헌릴렉스_795.png', '북한산 자락의 계곡 옆 감성 카페\n\n북한산 파라스파라 근처에 자리한 옥류헌릴렉스는 도심 속 번잡함을 피해 자연과 함께 쉬어갈 수 있는 특별한 공간입니다. 단독주택을 개조해 만든 이곳은 사계절 내내 아름다운 풍경을 자랑하며, 여름이면 계곡에 발을 담그고 시원한 여유를 즐기기 좋습니다.\n\n6개의 대형 홀로 구성된 실내는 각기 다른 매력을 지녀 취향에 따라 머물 수 있는 재미가 있습니다. 조용한 휴식을 원하는 고객을 위한 노키즈존과 가족 단위 방문객을 위한 패밀리존이 마련되어 있어 누구나 편안한 시간을 보낼 수 있습니다. 직접 만든 신선한 음료와 건강한 베이커리, 브런치를 제공해 자연 속에서 맛있는 한 끼를 즐기기에 충분합다.\n\n주차 공간이 넓어 방문이 편리하며, 계절마다 달라지는 경관이 색다른 감동을 선사합다. 번잡한 일상을 벗어나 조용한 힐링을 원한다면 옥류헌릴렉스에서 자연이 주는 여유를 만끽해 보세요.', 37.669695, 127.008247, '', '지하철 우이신설역 북한산우이역 1번 출구, 824m', '', '매일', ' https://www.instagram.com/cafe_relax._', '카페, 디저트', '반려동물 동반 불가', '11:00 ~ 21:30', '0507-1334-1829', ''),
	(796, '프로스트 펍앤그릴 (Prost Pub & Grill)', '04350  서울 용산구 이태원로27가길 26 (이태원동, 해밀톤호텔 별관) 1층', 'images/프로스트_펍앤그릴_(Prost_Pub_&_Grill)_796.png', '프로스트 펍앤그릴은 이태원만이 가지고 있는 자유로운 분위기와 여유로음이 느껴지는 유러피안 스타일의 펍.\n\n프로스트 펍앤그릴은 이태원만이 가지고 있는 자유로운 분위기와 여유로음이 느껴지는 유러피안 스타일의 펍입니다. 프로스트만의 감각적인 모던함을 더한 이국적인 인테리어는 글로벌하고 다양한 문화로 구성된 고객들을 매료시키기에 흠잡을 곳이 없습니다. 시간에 따라 다르게 연출되는 프로스트만의 특별한 분위기는 본연의 자유로움과 스포티함을 동시에 느낄 수 있어 늦은 밤 새로운 에너지를 느끼기에 더없이 좋은 공간입니다. 프로스트는 유러피안 스타일의 다양한 음식에 아시아풍의 소스를 더한 이국적인 음식을 맛볼 수 있고, 맥주와 곁들이기 좋은 아메리칸 스타일의 수제버거를 빵까지 직접 만들어 서빙합니다. 이와 한께 즐길 수 있는 세계 각국의 맥주와 다양한 락테일로 이태원의 새로운 밤을 열어줍니다.', 37.535106, 126.993789, '', '지하철 6호선 이태원역 1번 출구, 111m', 'Shrimp Burger 16,000원 | Prost Salsa Nachos 20,000원 | Sambal Soft Crab 16,000원', '', ' https://www.prostseoul.com/', '술집, 바', '예약불가, 미성년자 출입 불가, 연중무휴', '월 18:00~01:00, 화 18:00~03:00 수.목.일 18:00~04:00, 금.토 18:00~06:00', '문의: 02-796-6854 / 이벤트, 촬영 및 대관: 02-797-3245', ''),
	(797, '[백년가게] 삼천포식당', '01054  서울 강북구 한천로 1052', 'images/[백년가게]_삼천포식당_797.jpg', '30년간 냉동 대패 삼겹살을 직접 만들어서 돌판에 굽는 삼겹살 맛집.\n\n달궈진 돌판 위에 고기가 올라서면 옅은 연기, 치이익 소리와 함께 기분 좋은 냄새가 코를 휘어잡습니다. 창업주 배우자의 고향인 삼천포의 이름을 딴 삼천포 식당은 30년 간 흉내내지 않은 삼겹살 맛을 추구하며 뚝심을 지켜오고 있는 돌구이 삼겹살 전문점입니다. 삼천포식당의 주방을 도맡고 있는 창업주의 배우자는 창업을 위해 3년간 돼지갈비, 설렁탕, 도가니탕 등의 음식점에서 일하며 기술을 배웠고, 수도요리학원을 수석으로 이수하여 조교 권유를 받았을 정도로 높은 요리실력을 보유하고 있습니다. 처음에는 해물탕 집으로 시작했으나 얼마 지나지 않아 삼겹살로 아이템을 바꾸었고, 그때 우연히 접한 돌판구이에 매력을 느껴 전문적으로 파고들기 시작했습니다. 삼천포식당의 주요 메뉴는 얇게 썬 돌구이 냉동 삼겹살입니다. \n한때 화제가 되었던 저가 수입산의 냉동 대패 삼겹살과는 육질부터 다른 돌구이 냉동 삼겹살은 너무 크지 않은 60~90kg의 암퇘지를 공급받아 만들어집니다. 고기가 들어오면 자체 냉장고에서 24시간 숙성, 잠깐 상온 노출 후 당일 온도, 계절에 따라 얇게 썰어서 급랭해 내놓고 있습니다. 까다로운 과정을 거쳐 만들어지는 삼겹살과 마찬가지로 비법 김치 역시 젓갈은 일체 넣지 않고, 모든 양념은 계량화 해 체계적으로 만들어집니다. 탁월한 요리실력으로 만들어지는 삼천포식당의 전통은 6년 전부터 경영에 참여하고 있는 아들에게 이어지고 있습니다.', 37.639509, 127.027537, '', '지하철 4호선 수유역 8번 출구, 374m', '삼겹살, 목살 등', '', '', '음식점', '', '매일 12:00 ~ 23:00', '02-998-3447', ''),
	(798, '청기와타운 홍대점', '04038  서울 마포구 양화로 128 (서교동) 1층', 'images/청기와타운_홍대점_798.jpg', '청기와타운은 코리안 비비큐 레스토랑.\n\n날개모양처럼 생긴 대표메뉴 수원왕갈비를 필두로 LA갈비, 빗살로스가 있고 와인콜키지프리입니다. LA 한인타운 컨셉 인테리어로 이목을 끌며 영어 응대가 가능하므로 외국인 분들도 편하게 방문할 수 있습니다.', 37.554350, 126.921000, '3만원대', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 9번 출구, 271m', '', '', ' http://xn--ok0b996b7jax7rctf.com/', '음식점', '영어 응대 가능', '월요일~금요일 11:30~15:00 / 17:00~22:00, 토요일~일요일 11:30~22:00', '0507-1340-8145', ''),
	(799, '[백년가게] 포도나무', '03169  서울 종로구 사직로 108-3 (내자동)', 'images/[백년가게]_포도나무_799.jpg', '짱뚱어탕,홍어삼합등 남도 토속음식을 즐길 수 있는 25년 된 식당\n\n포도나무는 대표적인 남도 토속음식 중 하나인 짱뚱어탕을 25년째 고수하고 있는 짱뚱어탕 전문점입니다. \n\n짱뚱어는 청정갯벌에서만 살아 개체 수가 적어 접하기 힘든 음식으로, 예로부터 ‘바다의쇠고기’라 불리울 정도로 풍부한 아미노산과 타우린이 함유되어 있으며, 특히 불포화 지방산이 많아 항산화 작용 및 피부미용, 간 기능 개선에 효능이 있어 남녀노소를 불문하고 즐길 수 있는 스태미너 보양식입니다. 여기에 갓 지은 냄비밥과 그리고 손으로 쭉쭉 찢은 생김치를 곁들인 한상차림은 보기만 해도 고향의 집밥을 떠올리게 하는 정겨운 맛입니다. 뿐만 아니라, 4년 이상 된 묵은 김치와 홍어 삼합, 낙지전 등 다양한 요리와 음식들도 있어 어느 메뉴를 골라도 탁월한 남도 본토의 맛을 느낄 수 있습니다.', 37.575768, 126.970820, '', '지하철 3호선 경복궁역 7번 출구, 125m', '짱뚱어탕, 매생이+낙지, 낙지전 등', '', '', '음식점', '', '11:30 ~ 21:20\n14:00 ~ 17:30 (브레이크타임)', '0507-1493-1225', '토요일, 일요일'),
	(801, '다락', '04172  서울 마포구 도화2길 8 (도화동, 에어몰 빌딩)', 'images/다락_801.jpg', '한옥에서 느껴보는 떡볶이와 소주의 궁합\n\n떡볶이 달인으로 TV 프로그램에 소개될 만큼 ‘다락’은 즉석 떡볶이로는 서울 장안에서 유명한 맛집입니다. 쟁반과 전골, 두 가지 방식으로 떡볶이를 제공하며 기본 재료 외에도 다양한 사리를 추가로 선택할 수 있습니다. 가게 벽에는 이곳을 다녀간 손님들의 이름과 방문 날짜가 빼곡하게 쓰여 있습니다. 그저 세월만 지나온 게 아니라 푸짐하지만 저렴하고, 소박하지만 정겨운 추억의 맛을 나눠왔다는 사실을 고스란히 느낄 수 있습니다.', 37.540070, 126.948762, '', '지하철 5호선 마포역 3번 출구, 297m', '쟁반떡볶이, 즉석떡볶이', '매일', '', '음식점', '', '09:30~22:00', '02-706-0519', '매달 1, 3번째 일요일 정기휴무'),
	(802, '천년동안도', '03133  서울 종로구 수표로 134 (낙원동)  2층', 'images/천년동안도_802.jpg', '수많은 국내외 재즈 아티스트들이 라이브 공연을 해온 명소. 매일 저녁 로맨틱하고 흥겨운 재즈 밴드의 라이브 공연.\n\n\'천년동안\' 계속 재즈 공연이 계속 되는 섬이라는 뜻을 가진 천년동안도. 1996년 처음 문을 연 이후부터 지금까지 사람들에게 멋진 재즈 라이브 공연을 사람들에게 보여주고 있습니다. 1996년 당시 불법이던 일반음식점 내 밴드공연을 허용 가능하게 만든 클럽으로 지금도 여전히 재즈 문화 발전을 위해 끊임없이 노력하고  있는 곳입니다.', 37.572981, 126.988440, '', '지하철 1 / 3 / 5호선 종로3가역 5번 출구, 68m', '', '', ' http://www.chunnyun.com/', '술집, 바', '', '매일 18:00 ~ 23:00', '0507-1388-5562', ''),
	(803, '[백년가게] 동흥관', '08614  서울 금천구 시흥대로63길 20 (시흥동, 동흥관)', 'images/[백년가게]_동흥관_803.jpg', '화교출신의 쉐프로부터 그의 손자까지 계승이 된, 한국 최고( 古）의 중식당.\n\n70년 동안 한 자리에서 지켜온 세월의 무게가 매장 곳곳 켜켜히 쌓여있습니다. 화교 출신의 아버지가 창업한 동흥관은 아들을 거쳐 손자에게로, 70년 동안 대를 이어 승계되고 있습니다. 동흥관은 아직 전쟁의 화마가 채 가시지 않았던 1951년 창업된 중화요리 전문점이고 실제 사업자 등록증은 1950년에 교부 받은 것으로 서울시 자료에 기록되어있으며 중화요리로는 서울에서 제일 오래된 사업자 등록입니다. 동흥관은 한국직원 없이 전원 중국, 화교 출신의 쉐프로 구성되어 중국과 대만의 현지 조리 방식을 그대로 유지해 차별화를 꾀하고 있으며 끊임없이 한국인의 입맛에 맞는 전통 중국음식을 개발하기\n\n위해 노력하고 있는 백년가게입니다. 짜장면, 짬뽕, 탕수육 등 중국음식점의 전통메뉴를 기반으로 딤섬 등의 시그니처 메뉴를 제공하고 있으며 각종 소스는 기성품을 사용하지 않고 직접 제조하여 동흥관만의 품질을 유지하고 있습니다. \n\n\n\n\n70년 동안 한자리에서 영업을 계속해온 탓에 금천의 랜드마크로 거듭난 동흥관은 아이가 아버지가 되고 할아버지가 되어 손자 손을 잡고 다시 방문하는 추억 속에 백년가게로 굳건히 자리를 지키고 있습니다.', 37.455224, 126.898598, '', '지하철 1호선 금천구청역 1번 출구, 387m', '짜장면, 짬뽕, 탕수육, 각종 중식', '', '', '음식점', '', '11:00 ~ 21:30', '02-803-3759', ''),
	(804, '[백년가게] 종가집', '03162  서울 종로구 인사동길 15-13 (인사동)', 'images/[백년가게]_종가집_804.jpg', '20년 넘게 곱창의 맛을 탐구하는 곱창전문점\n\n구불구불 이어진 인사동 좁은 골목을 들어가다 보면 고즈넉하면서도 정겨움이 넘쳐나는 가게가 등장합니다. 종가집은 인사동 좁은 골목에서 20년 넘게 영업을 이어오고 있는 서울 토박이 음식점 중 하나인 곱창전골집입니다. 전 국민이 어려움을 겪었던 IMF, 광우병 사태, 코로나도 무사히 견뎌내며 나날이 성장하고 있는 종가집은 언제나 변함없는 맛과 정직함을 유지하기 위해 다양한 노력을 기울이고 있습니다. \n\n고객들에게 민감하게 받아들여질 수 있는 곱창 특유의 냄새를 잡고, 신선한 경험을 제공하겠다는 목적으로 고온의 불판에서 소주를 부어 연출하는 불쇼는 종가집에서만 볼 수 있는 독특한 풍경입니다. 모든 재료는 신선해야 한다는 철학을 바탕으로 매일 마장동에서 싱싱한 곱창을 공수하며 전골에 들어가는 불고기와 야채 역시 청량리 시장에서 직접 매입하고 있습니다. 종가집의 주요 메뉴인 곱창구이, 전골은 넉넉한 양과 차별화된 맛으로 고객들의 호평을 받고 있습니다.', 37.572004, 126.985899, '', '지하철 1호선 종각역 3번 출구, 320m', '한우등심, 곱창구이, 곱창전골 등', '', ' https://www.instagram.com/insajonggajib/', '음식점', '', '11:00 ~ 22:00', '02-733-2135', '일요일 정기휴무'),
	(805, '우물집', '03091  서울 종로구 창신길 200 (창신동)', 'images/우물집_805.png', '글로우서울이 만든 프라이빗한 공간에서 고즈넉한 풍경과 함께 즐기는 전골, 솥밥 요리 전문점\n\n글로우서울이 만든 프라이빗 공간에서 고즈넉한 풍경과 함께 즐기는 전골, 솥밥 요리 전문점입니다. 100년 된 우물을 중심으로 오래된 건물을 인테리어하여 한국적이고, 감각적인 분위기를 만끽할 수 있습니다. 참다랑어를 우린 맑은 국물에 신선한 채소, 프리미엄 한우 차돌박이를 넣어 끓여먹는 전골과 솥밥, 그리고 한우 차돌박이 삼합을 맛볼 수 있습니다.', 37.579662, 127.009923, '', '지하철 6호선 창신역 2번 출구, 861m', '', '', ' https://www.instagram.com/woomoolzip/?hl=ko', '음식점', '예약제로 운영되고 있습니다.', '매일 11:00 ~ 21:00 (라스트오더 14:00, 20:00)\n*브레이크타임 15:00 ~ 17:00', '0507-1318-7500', ''),
	(806, '청년밥상문간', '02709  서울 성북구 보국문로11길 18-2 (정릉동, 황내과의원) 2층', 'images/청년밥상문간_806.png', '얼큰한 김치찌개를 삼천 원에 맛볼 수 있는 아름다운 식당\n\n청년밥상 문간은 인기 예능프로 유퀴즈에도 출연한 이문수 신부님의 주도로 글라렛 선교수도회에서 젊은 청년들에게 따뜻한 밥 한 끼를 제공하겠다는 목적으로 차린 식당입니다. 가성비 식당으로 소문난 이곳은 후원자들의 지원과 자원봉사로 운영되는 아름다운 식당입니다. 김치찌개의 맛을 더해 줄 사리와 메인 재료인 두부와 고기는 추가 비용 지불 후 더 먹을 수 있으며 공깃밥은 무한 리필로 제공됩니다.', 37.608861, 127.009099, '', '지하철 우이신설선 북한산보국문역 1번 출구, 433m', '김치찌개 3,000원', '', ' https://www.instagram.com/youthmungan/', '음식점', '', '11:00~14:30, 17:00~20:30', '0507-1349-6952', '매주 일요일, 명절, 공휴일 휴무'),
	(807, '성수동 대림창고 갤러리', '04784  서울 성동구 성수이로 78 (성수동2가, 대림창고)', 'images/성수동_대림창고_갤러리_807.jpg', '옛 정미소를 개조하여 높은 천장과 개방감 있는 공간의 성수동 대형 카페\n\n대림창고는 박공지붕, 붉은 벽돌, 철제 기둥 등 1970년대 옛 정미소 건축물의 기존 마감을 그대로 살려 정미소에서 성수동을 대표하는 복합 문화공간으로 자리매김하고 있습니다. 커피 외 주류, 음식, 갤러리가 함께하는 공간으로 대림창고가 주최, 주관하는 기획 전시를 볼 수 있으며, 카페 오픈 시간에 전시관람이 가능합니다.', 37.541825, 127.056459, '', '지하철 2호선 성수역 3번출구, 304m', '', '', ' https://www.instagram.com/daelimchanggo_gallery', '', '*유료 표기된 주차라인의 노상주차장(점포, 지정 표기된 주차라인은 주차불가)\n*한라시그마밸리 유료 지하주차장 이용', '매일 11:00-22:00', '0507-1390-9669', ''),
	(808, '파이키', '03134  서울 종로구 서순라길 81 (권농동, 금보빌딩)  파이키', 'images/파이키_808.jpg', '책과 음료를 즐기는 탐험가들을 위한 북카페 파이키\n\n파이키는 서순라길에 위치한 북카페입니다. \'책과 음료를 즐기는 탐험가들의 베이스캠프\' 로써 운영되며, 파이키를 찾은 방문객(finders)에게 도심 속 작은 아지트를 제공합니다. 방문객들은 음료와 케잌 등 주전부리를 곁들이며 공간 곳곳의 책과 이야기를 자유롭게 탐험할 수 있습니다. 커다란 창 밖으로 보이는 돌담길이 아름다운 이 곳에서, 일상 속 자신만의 탐험을 떠나보기를 추천합니다.\nfinders keepers, FIKEE\n\'파인더스 키퍼스\'는 \'찾는 사람이 임자\'라는 의미의 영어 속담입니다.', 37.573851, 126.992335, '', '지하철1/3/5호선 종로 3가역 7번 출구, 273m', '', '매일', ' https://www.instagram.com/fikee.seoul', '카페, 디저트', '자세한 사항은 인스타그램 @fikee.seoul 참고 부탁드립니다.', '월 10:00~19:00 (라스트오더 18:00)\n화-일 10:00~22:00 (라스트오더 21:00)', '', ''),
	(809, '오파토 O\'pato', '04339  서울 용산구 신흥로12길 4 (용산동2가) 1층', 'images/오파토_O\'pato_809.jpg', '해방촌에 위치한 소금빵이 유명한 브런치 카페\n\n오파토는 직접 만든 빵으로 아침을 요리하는 브런치 & 베이커리 매장입니다. 아침 8시 오픈하며 매일 바뀌는 데일리 스프와 갓 구운 빵으로 만드는 다양한 샌드위치 및 브런치 메뉴를 경험해 볼 수 있습니다. 빵이 나오고 판매되는 공간인 "오파토"와 브런치를 파는 공간인 "Ori"로 나뉘어져 있습니다. 매장 근처 총 3대의 주차 전용공간이 있으며 키즈 동반 가능 매장입다.', 37.543340, 126.987941, '', '지하철 6호선 녹사평역 2번 출구, 873m', '', '정확한 영업일 정보는 인스타그램 @opato_08am을 참고해주세요.', ' https://www.instagram.com/opato_08am/', '카페, 디저트', '자세한 사항은 인스타그램 @opato_08am을 참고해주세요.', '매일 08:00~16:30 (라스트오더 16:00)', '0507-1361-4890', ''),
	(811, '[백년가게] 진성식당', '06074  서울 강남구 학동로81길 7 (청담동)', 'images/[백년가게]_진성식당_811.jpg', '청담에서 30년동안 자리를 지켜온 노포. 칼국수와 왕만두가 주력.\n\n서울의 중심이라 일컬어지는 청담동에서 30년 가까이 칼국수를 판매하고 있는 진성식당은 1990년 창업 이후 꾸준한 맛을 위해 노력해 왔습니다. 경험이 일천해 창업 초창기에는 무수히 많은 실패를 맛봤으나 전국 유명 음식점을 찾아다니며 벤치마킹하고, 직접 음식의 맛을 개선하려는 노력을 통해 지금의 진성식당이 탄생할 수 있었습니다. \n\n\n\n\n대표메뉴인 칼국수는 사골과 잡뼈를 아침부터 저녁까지 8시간 이상 끓여 낸 국물에 표고와 홍고추 등을 얹어 맛을 내고 있습니다. 왕만두 역시 인근 가락시장에서 사 온 신선한 재료로 매일 아침과 오후에 빚어서 소비하고 있습니다. 여름에는 100% 국산 콩으로 매일 아침 맷돌로 갈아서 만드는 콩국수가 별미입니다.', 37.519544, 127.050691, '', '지하철 7호선 청담역 10번 출구, 105m', '칼국수, 보쌈', '', '', '음식점', '', '11:00 ~ 22:00', '02-511-8157', '없음'),
	(812, 'ium 1966', '04053  서울 마포구 와우산로29바길 15 (서교동)', 'images/ium_1966_812.jpg', '1966년에 지어진 한옥을 개조한 카페, ium 1966\n\nium 1966 카페는 1966년에 지어진 오래된 한옥을 빈티지한 감성으로 재탄생시킨 공간입니다. 서까래와 아궁이, 중정과 툇마루가 그대로 남아있어 고즈넉한 옛 한옥의 감성을 느낄 수 있습니다. 뿐만 아니라, 오래된 스피커와 전축, 솥, 항아리 등 빈티지한 소품들이 곳곳에 배치되어 있어 구경할 거리도 쏠쏠합니다. 마당부터 다락방, 지하까지 조화롭게 꾸며진 다양한 공간이 마련되어있어 한국의 멋이 가득한 사진을 남기기에도 제격입니다. 연꽃과 연잎으로 즐기는 연꽃차와 함께 망개떡, 제주 쑥 팥빵 등 전통적인 식음료들이 준비되어있습니다. 힙한 감성이 가득한 홍대에서, 정감 넘치는 한국의 미를 경험할 수 있는 곳입니다.', 37.555706, 126.926085, '', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 7번 출구, 229m', '', '', ' https://www.instagram.com/ium1966', '카페, 디저트', '영업시간은 인스타그램(@ium1966)을 참고해주시길 바랍니다.', '월요일 ~ 토요일 12:00 ~ 20:00', '0507-1421-1966', '매주 일요일'),
	(813, '[백년가게] 꾸이꾸이 돼지촌 쭈꾸미', '07606  서울 강서구 초원로 77 (방화동)', 'images/[백년가게]_꾸이꾸이_돼지촌_쭈꾸미_813.jpg', '탱탱한 쭈꾸미와 향긋한 부추의 조화가 매력인 쭈꾸미 맛집\n\n강서구 방화동에서 부추꾸미로 유명한 꾸이꾸이돼지촌쭈꾸미는 1994년 문을 열었습니다. 꾸이꾸이돼지촌쭈꾸미의 매력은 국산 쭈꾸미를 사용, 쭈꾸미의 부드럽고 탱탱한 식감을 살려 신선한 부추와 어우러져 슴슴하고 건강한 맛에 있습니다. 가장 유명한 메뉴인 부추꾸미는 박춘례 대표가 직접 개발한 메뉴로 국산 쭈꾸미를 익힌 뒤에 양념된 부추를 쭈꾸미 위에 수북이 얹어 먹는 것으로 쭈꾸미와 부추의 궁합이 절묘하여 꾸이꾸이돼지촌쭈꾸미를 방문한다면 반드시 맛봐야 할 음식입니다. \n\n\n\n\n지역주민에게 많은 사랑을 받았고, 입소문이 퍼져 전국 각지에서 손님이 찾아옵니다. 2019년에 장남과 차남이 가게 운영에 참여하여 27년 전통을 이어갈 준비를 하고 있습니다.', 37.567678, 126.814124, '1만원대', '지하철 9호선 신방화역 1번 출구, 182m', '부추쭈꾸미, 삼겹살', '', ' https://www.instagram.com/gguigguijjuggumi', '음식점', '', '월~토 11:30~23:00, 일 11:30~22:00', '02-2662-3450', ''),
	(814, '도넛정수', '03091  서울 종로구 창신12길 40 (창신동)', 'images/도넛정수_814.jpg', '서울 시티 뷰와 도넛을 함께 즐기는 한국식 도넛 전문 카페\n\n창신동 절벽마을에 위치한 도넛정수는 서울 시티 뷰와 도넛을 함께 즐길 수 있는 카페입니다. 주택을 개조하여 고즈넉하고 평화로운 분위기를 느낄 수 있으며, 통창으로 남산 뷰와 아름다운 서울 시티 뷰를 만나볼 수 있습니다. 도넛정수는 한국식 도넛 전문 카페로 옥수수 도넛, 쑥 초코 도넛 등 특별한 한국적인 도넛을 맛볼 수 있습니다.', 37.578292, 127.010865, '', '지하철 6호선 창신역 1번 출구, 749m', '', '', ' https://www.instagram.com/donutjungsu_changsin/', '카페, 디저트', '', '매일 11:30 ~ 21:00', '0507-1386-5775', ''),
	(815, '[백년가게] 프랑세즈과자점', '08547  서울 금천구 남부순환로 1392 (독산동)', 'images/[백년가게]_프랑세즈과자점_815.jpg', '30년간 제과제빵연구소에서 개발한 독자적인 빵들을 맛볼 수 있는 빵집.\n\n프랑세즈과자점은 1994년부터 독산동 같은 자리에서 고객들에게 건강하고 신선한 빵을 제공하고 있는 빵집입니다. 30년 동안 제과제빵업에 종사하며 빵에 대한 열정을 불태우고 있는 창업주는 프랑세즈과자점의 경쟁력을 위해 제과점 옆 건물을 임차해 제과제빵연구소를 설립했으며, 이곳에서 신메뉴개발과 후학들을 위한 교육, 훈련을 실시하고 있습니다. \n\n\n\n\n프랑세즈과자점의 주요 메뉴는 제과제빵연구소의 연구를 거쳐 탄생한 독특합니다. 고구마찰빵, 양파빵, 현미빵 등 다양한 빵들이 개발되었으며 모든 빵은 인위적 이스트가 아닌 천연발효종을 사용하여 소화가 잘 되고, 빵의 맛과 영양을 고스란히 느낄 수 있습니다. 수많은 빵 중 가장 인기가 좋은 시그니처 메뉴는 호박빵과 호두파이. 국내산 호박을 사용해 프랑세즈과자점만의 특별한 기술로 만들어진 호박빵은 담백하면서도 부드러운 식감을 자랑합니다. 호두사장이 만든 호두파이로 유명한 호두파이는 견과류임에도 부드러운 식감과 두툼한 두께로 선물용으로도 인기 있습니다. 이 외에도 양파빵과 고구마찰빵 등이 고정 매니아층을 형성하며 고객들에게 좋은 반응을 이끌어 내고 있습니다.', 37.479873, 126.905419, '', '지하철 2호선 구로디지털단지역 6번 출구, 974m', '육쪽마늘빵, 호두파이, 크림치즈모카빵, 양파빵', '', '', '카페, 디저트', '', '매일 07:30 ~ 24:00', '02-854-1213', ''),
	(816, '한쿡', '04340  서울 용산구 남산공원길 105  N서울타워 한쿡(전망대 T3층)', 'images/한쿡_816.jpg', '해발 400M 남산에서 즐기는 다채로운 한식 다이닝, 한쿡\n\n한쿡은 한국의 맛과 멋을 담은 한우 그릴 코스 Korean Grill & Dine 식당입니다. 서울이 한눈에 내려다 보이는 남산, N서울타워 전망층에 위치한 한식 레스토랑으로 파노라마 처럼 펼쳐진 풍경을 바라보며 잊지 못할 식사를 즐길 수 있습니다.\n이곳의 대표 메뉴는 한우 그릴 코스로 참숯에 구워 스모크 우드칩, 솔잎 향을 겹겹이 레이어링 한 한쿡만의 섬세한 그릴 방식으로 제공되어 한우의 풍미가 극대화된 것이 특징입니다. 이외에도 모던하고 품격있는 플레이팅을 선보이는 다채로운 코스가 준비되어있으니 이곳에서 한쿡만의 정취를 경험해보길 바랍니다.', 37.551123, 126.987868, '', '지하철 3호선 동대입구역 6번 출구, 128m 01A버스 탑승 후 남산서울타워 정류장에서 하차 후 360m', '', '매일', ' https://www.nseoultower.co.kr/visit/restaurant2.asp', '음식점', '※ 주말 및 공휴일은 코스 메뉴만 이용 가능합니다.\n※ 한쿡 사전 예약 시 전망대 엘레베이터 티켓을 무료로 발권해드립니다. (성인 21,000원 / 소인 16,000원)\n※ 캐치테이블, 네이버, 전화를 통해 예약 하실 수 있습니다.', '매일 12:00 ~ 22:00\n(브레이크타임 16:00 ~ 17:00 / 라스트오더 20:00)', '02-3455-9292', ''),
	(817, '성원전주콩나물국밥', '04537  서울 중구 명동10길 19-10 (명동2가)', 'images/성원전주콩나물국밥_817.jpg', '명동의 인기 만점 전주식 콩나물국밥\n\n성원전주콩나물국밥은 1937년 창업주 김소선 사장이 개업한 콩나물국밥 전문점으로, 명동에서 시작해 오랜 역사를 자랑합지다. 김소선 사장은 전쟁 격동 속에서도 가족을 위해 식당을 개업했습니다. 식전 제공되는 바삭한 김치전이 입맛을 돋워주며, 본식인 콩나물국밥 또한 각종 재료가 어우러져 얼큰하고 시원한 맛이 일품입니다. 다국어로 표기된 메뉴판 덕분에 해외 관광객들도 쉽게 방문할 수 있습니다', 37.563026, 126.985979, '1만원대', '지하철 4호선 명동역 8번 출구, 269m', '콩나물국밥, 모주, 막걸리', '매일', '', '음식점', '', '11:00~22:00', '02-777-4284', ''),
	(818, '미로식당', '04059  서울 마포구 와우산로30길 80 (창전동)', 'images/미로식당_818.jpg', '홍대에 위치한 한식주점\n\n홍대에 위치한 \'미로식당\'은 한식을 안주로 즐길 수 있는 한식 주점입니다. 소갈비찜, 소금 갈비, 한우육회, 오징어볶음 등 다양한 종류의 한식과 전통주를 즐길 수 있습니다. 운이 좋으면 메뉴에는 없는 떡볶이를 맛볼 수 있습니다. 깔끔하고 고급스러운 음식이 준비되어 있어 크지 않은 식당에 손님이 빠질 날이 없습니다. 음식들과 함께 나오는 정갈하게 썰린 채소들을 구경하는 것도 미로식당의 묘미입니다. 좋은 재료를 고수하고 칼질에 신경을 많이 쓰는 사장님이 주문과 동시에 메뉴에 들어가는 채소들이 썰어서 내주는데 그 식감과 맛이 평소와는 새삼 다르게 느껴집니다.', 37.552050, 126.927886, '', '지하철2호선 / 공항철도 / 경의중앙선 홍대입구역 9번 출구, 826m', '', '수요일 ~ 토요일', '', '음식점', '예약이 가능하다.', '18:00 ~ 23:00 (라스트오더 22:00)', '0507-1412-3777', '일요일 ~ 화요일'),
	(819, '모와 MOWa', '04535  서울 중구 명동8나길 38 (충무로1가) 지하 1층', 'images/모와_MOWa_819.jpg', '명동 중심가에 위치한 샵 앤 와인 다이닝 매장.\n\n와인에 대한 좋은 기억, 추억을 가질 수 있는 공간을 만들겠다는 포부를 담은 MOWa. 다양한 와인들이 있는 와인 터널과 함께 절제된 분위기의 \'비움\' 공간과 프라이빗하고 컴피한 \'채움 공간. 눈과 입 모두를 즐겁게 하는 특별한 컨템프러리 퀴진을 지금 모와에서 즐겨보세요. 명동 기념일 데이트를 하거나, 프라이버시가 중요한 미팅, 모임 등에 최적의 장소인 와인의 추억, 그리고 나만의 해석으로 완성하는 와인 다이닝, 모와 입니다.\n\n[다채로운 맛의 변주]\n익숙한 재료로 만들어내는 새로운 맛의 조화.\n컴템포러리 맛집 \'모와\'에서는 한식을 베이스로한 다양한 변주를 통해 색다른 퓨전식을 즐길 수 있습니다.\n\'사브서울\', \'고메트리\', \'밍글스\' 등 국내 유수의 레스토랑에서 경력을 쌓은 실력파 \'문원기\' 헤드셰프가 주방을 이끕니다.\n\n[깊이가 다른 와인]\n명동 술집 \'모와\'는 1000여 종의 와인 외에도 30여 종의 위스키, 칵테일, 논알콜칵테일 등으로 다양한 선택지를 제공합니다. 종류별로 맛을 끌어올리는 최적의 잔으로, 와인 및 주류의 풍미를 더욱 살립니다.\n\n[예술적인 공간과 분위기]\n1000여 종의 다양한 와인으로 채운 50m 규모의 와인터널, 오묘한 분위기를 자아내는 녹색조명 등 색다른 분위기 맛집 모와는 인테리어 그 자체로 예술이 됩니다. 넓은 간격의 테이블, 적절하게 구분된 공간, 프라이빗한 룸으로 구성하여 기념일 데이트를 하거나, 프라이버시가 중요한 미팅, 모임 등에 최적의 장소입니다.', 37.561709, 126.982675, '', '지하철 4호선 명동역 5번 출구, 221m', '타르트 - 20,000원\n육회 - 24,000원\n라비올리 - 27,000원\n양갈비 - 48,000원\n진갈비 - 62,000원', '월요일~토요일', ' https://www.winenara.com/shop/company/fnb_view?no=97', '술집, 바', '', '11:30~23:00 (브레이크 타임 15:00~17:30)', '02-753-5008', '일요일'),
	(820, '능동미나리', '04386  서울 용산구 한강대로40길 28 (한강로2가)  1층, 2층', 'images/능동미나리_820.png', '맛있는 곰탕을 맛볼 수 있는 신용산역 곰탕맛집 능동미나리\n\n청도 화악산에서 충분한 일조량과 청정 지하수를 먹고 자라 연한 줄기에 미나리 향이 가득한 한재 미나리를 사용해 미나리 수육전골, 미나리 꼬리찜, 미나리 육회의 환상적인 궁합을 맛볼 수 있습니다. 부드러운 육질과 감칠맛이 뛰어난 최고급 한우암소를 사용해 담아낸 맑은 고기국물에 밥과 함께 나오는 능동 곰탕을 먹을 수 있습니다. 자극적이지 않고 담백하고 깔끔한 음식의 맛이 사람들의 발걸음을 이끌고 있습니다. 정갈한 음식과 직원분들의 친절한 응대로 한번 다녀온 사람들이라면 모두 칭찬을 서슴치 않습니다. 웨이팅은 필수이지만 평일에 방문한다면 주말보다 빨리 입장이 가능합니다.', 37.530091, 126.970820, '2만원대', '지하철 4호선 신용산역 1번 출구, 221m', '', '매일', ' https://www.instagram.com/ndminari', '음식점', '단체 이용 가능, 예약 가능', '월요일 ~ 금요일 11:00 ~ 23:00 (라스트오더 21:50)\n토요일 ~ 일요일 10:30 ~ 23:00 (라스트오더 21:50)', '0507-1388-1035', ''),
	(821, '꼬숑돈까스', '03776  서울 서대문구 명물1길 2 (창천동)', 'images/꼬숑돈까스_821.png', '삼천 원에 1끼를 먹을 수 있는 신촌의 돈까스 가게\n\n신촌역 3번 출구, 현대백화점 근처에 위치한 꼬숑 돈까스는 가성비는 물론 맛도 뛰어나기로 소문난 곳입니다. 오로지 돈까스 한 가지만 판매하는 곳으로 기본 메뉴를 주문하면 돈까스 한장과 밥, 장국, 샐러드로 구성된 알찬 메뉴가 제공됩니다. ‘바삭’한 튀김 옷으로 식욕을 자극하는 꼬숑 돈까스에서 가성비 넘치는 식사를 경험해 보세요.', 37.557839, 126.937350, '', '지하철 2호선 신촌역 3번 출구, 261m', '돈가스 3,000원 / 트루 꼬숑 돈가스 5,000원 / 레알 꼬숑 돈가스 7,000원', '', '', '음식점', '', '11:00~20:00 (16:00~17:00 브레이크타임)', '', ''),
	(822, '빈브라더스 커피하우스', '04075  서울 마포구 토정로9길 2 (상수동)  6층, 7층', 'images/빈브라더스_커피하우스_822.jpg', '다채로운 커피 경험을 선사하는 곳, 빈브라더스 커피하우스\n\n빈브라더스 커피하우스는 상수에 위치한 커피 전문 카페입니다. 다양한 원두가 준비되어있어 테이스팅 노트를 참고하여 누구나 취향에 맞는 커피를 즐길 수 있습니다. 무엇보다 이곳의 특징은 커피의 맛을 한층 더 돋보이게 하는 탁 트인 한강뷰입니다. 넓은 통창으로 서강대교와 밤섬, 국회의사당을 한 눈에 볼 수 있습니다. 커피의 맛과 어우러지는 이곳만의 분위기에 언제나 사람들의 발길이 끊이지 않는니 곳입다. 6층에 위치한 커피 바는 빈브라더스의 시즈널 커피를 다채롭게 경험해 볼 수 있는 공간입니다. 서로 다른 산지의 커피 세 가지를 테이스팅해보는 \'커피 플라이트\' 부터 이달의 커피, 커피 칵테일까지 다양하고 특별한 시즈널 커피를 맛 볼 수 있습니다. 다만, 시즈널 커피 바는 예약제로 운영되어 방문 전 예약이 필수입니다.', 37.545396, 126.924456, '', '지하철 6호선 상수역 3번 출구, 358m', '', '', ' http://www.beanbrothers.co.kr/', '카페, 디저트', '자세한 사항은 인스타그램 (@bean_brothers)을 참고해주시길 바랍니다.', '매일 10:00 ~ 22:00 (21:00 라스트오더)', '0507-1322-2012', ''),
	(823, '홍스쭈꾸미 홍대본점', '04053  서울 마포구 어울마당로 146 (서교동)', 'images/홍스쭈꾸미_홍대본점_823.jpg', '18년 홍대 대표 쭈꾸미 맛집 홍스쭈꾸미\n\n홍대에서 오랫동안 자리잡은 쭈꾸미 맛집인 만큼 내국인, 외국인 상관없이 손님이 많습니다. 그럼에도 불구하고 매장이 넓어 줄이 금방 줄어듭니다. 대표메뉴인 쭈꾸미와 이외에도 쭈꾸미+삼겹살, 쭈꾸미+새우, 쭈꾸미+차돌 등 다양한 메뉴를 즐길 수 있습니다. 맵기정도를 선택할 수 있어 매운걸 잘 먹지 못하는 사람도 얼마든지 식사가 가능합니다. 또한 매운맛을 중화시켜주는 사이드메뉴도 종류가 다양하고 쭈꾸미와 함께 먹기에 조합이 좋습니다. 식사를 마치고 나서 쭈꾸미를 먹으면 무료로 먹을 수 있는 볶음밥이 별미입니다. 영어로 된 메뉴판이 준비되어 있어 외국인들도 편하게 주문이 가능합니다.', 37.556216, 126.926117, '1만원대', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 7번 출구, 171m', '', '매일', '', '음식점', '예약, 포장, 단체 이용 가능', '매일 11:30 ~ 02:00', '0507-1407-7943', ''),
	(824, '라프레플루트', '04768  서울 성동구 서울숲2길 8-8 (성수동1가) 2층', 'images/라프레플루트_824.jpg', '다양한 과일을 쉽고 간편하게 접할 수 있는 프리미엄 과일가게 라프레 플루트.\n\n프리미엄 과일로 과일 천연의 맛을 느낄 수 있는 과일가게 라프레 플루트. 모든 메뉴에는 냉동 과일과 과일 시럽을 쓰지 않고, 모든 과일 주스에는 설탕 대신 사탕수수 시럽을 사용합니다. 빙수, 스무디, 케이크, 아이스크림 등 과일로 만든 다양한 디저트를 맛보고 싶다면 라프레 플루트로 가보세요.', 37.547252, 127.039443, '', '지하철 2호선 뚝섬역 8번 출구, 667m', '', '', ' http://instagram.com/rafre_fruit', '카페, 디저트', '', '월~금 13:00~19:00\n토~일 13:00~20:30', '0507-1383-7415', ''),
	(825, '한옥찻집', '03146  서울 종로구 인사동14길 12 (관훈동)', 'images/한옥찻집_825.jpg', '마당이 있는 인사동 한옥 전통찻집, 한옥찻집\n\n한옥 찻집은 인사동에 위치한 전통 찻집입니다. 한옥을 개조해 만들어진 카페인 만큼, 특유의 따뜻하고 편안한 분위기를 자아냅니다. 카페 가운데에는 아기자기한 마당이 위치해있고, 내부는 한옥과 잘 어우러지는 인테리어로 꾸며져 있습니다. 또한 한옥 홀의 일반 테이블 뿐만 아니라, 전통 온돌방에는 좌식 형태의 테이블도 마련되어있어 보다 편안하게 휴식을 취할 수 있습니다.   \n전통 찻집답게, 긴 시간 동안 정성으로 직접 끓인 깊은 맛의 전통차가 이곳의 대표메뉴입니다. 이외에도 곶감, 인절미, 꿀호떡, 백설기, 약과 등 한국의 다양한 전통 디저트들도 준비되어있습니다. 여름에는 팥빙수와 망고 빙수도 함께 판매합니다.', 37.574720, 126.984763, '', '지하철 3호선 안국역 6번 출구, 165m', '', '매일', ' https://www.instagram.com/hanok.cafe_insadong', '카페, 디저트', '자세한 소식은 인스타그램 @hanok.cafe_insadong을 통해 확인하시길 바랍니다.', '매일 12:00~21:50 ( 21:00 라스트오더)', '0507-1330-0538', ''),
	(826, '[백년가게] 평양옥', '03739  서울 서대문구 통일로 107-23 (미근동)', 'images/[백년가게]_평양옥_826.jpg', '가마솥에 약재와 닭을 넣어 고아서, 채수를 추가해 끓이는 닭곰탕 맛집\n\n평양옥은 맑고 깊은 닭곰탕으로 서대문을 대표하는 맛집입니다. 대표자가 어머님에게 물려받은 전통방식으로 가마솥에서 닭곰탕을 2대째 끓여 오셨습니다. 매일같이 새벽 3시가 되면 가마솥에 물을 올리는 일로 하루가 시작됩니다. 1차로 약재를 달이고, 2차로 닭뼈와 닭고기를 끓인 뒤, 3차로 채수를 추가해 끓여 내야 하기 때문입니다. 이렇게 가마솥에서 깊게 우려낸 육수는 잘 삶아낸 토종닭과 어우러져 최고의 맛을 냅니다. 당일 구매한 재료는 당일에 모두 판매 소진한다는 원칙을 고집해, 음식에 신선도를 유지한다는 것도 대표자의 소신입니다.', 37.564275, 126.966963, '', '지하철 5호선 서대문역 7번 출구, 179m', '닭곰탕, 해신탕, 백숙', '', '', '음식점', '', '월요일~금요일 11:00~14:00 / 17:00~22:00\n토요일 11:00~22:00', '02-363-7058', '일요일'),
	(827, '[백년가게] 싸리골', '03336  서울 은평구 서오릉로 160 (갈현동)  1층', 'images/[백년가게]_싸리골_827.jpg', '손수 칼로 썬 생삽겹과 31년의 역사가 농축된 국물갈비가 주력인 가게.\n\n국물에 잠긴 갈비와 맛있게 익어가는 생삼겹살이 고객의 젓가락을 유혹합니다. 1990년 개업한 후 집에서 먹는 밥 한 끼를 대접 한다는 마음으로 지금까지 31년을 이어온 맛집입니다. 대표 메뉴인 ‘국물 갈비’는, 신선한 한 돈 갈빗살과 목살을 열 가지 넘는 양념에 잰 후 숙성시켜 조려먹는 갈비로 손님들이 많이 찾습니다. \n\n\n\n\n신선도와 씹는 맛을 위해 얼리지 않은 한 돈 생 삼겹살을 기계를 사용하지 않고 직접 칼로 썹니다. 김치와 무생채에 반해 다시 찾는 손님도 많습니다. 김치는 국산 재료로 개업 초기부터 지금까지 직접 만들고 있습니다. 기교를 부리지 않고 기본의 충실하게 제공 하는 것을 운영 원칙으로 삼고 있어 수많은 단골손님이 찾는 싸리골은 1주일에 두 번 이상 오는 손님도 상당수일 뿐 아니라, 한 번 방문했던 손님은 거의 다시 온다고 할 정도로 칭찬이 자자합니다.', 37.612683, 126.915633, '', '지하철 6호선 구산역 4번 출구, 183m', '생삼겹살, 국물돼지갈비', '', '', '음식점', '', '11:00~22:30', '0507-1339-3086', ''),
	(828, '[백년가게] 르네상스베이커리', '04152  서울 마포구 큰우물로 39 (대흥동, 르네상스 베이커리)', 'images/[백년가게]_르네상스베이커리_828.jpg', '어린아이가 부모가 되어도 찾아오는 추억이 담긴 빵집.\n\n아이의 손을 잡고 매장에 들어서는 부모님은 어렸을 적, 르네상스 제과점의 단골이었던 손님입니다. 아이가 부모가 되어 다시 찾아오는 추억이 담긴 빵집, 르네상스제과점은 마포 터주대감으로 1982년에 문을 연 오래된 빵집입니다. 남녀노소 할 것 없이 언제든 방문해 먹을 수 있는 친근한 빵집을 만드는 것을 목표로, 최상의 기술력과 최고의 질 및 다양성을 유지하기 위해 노력해 왔습니다. 특히 청정지역에서 재배하는 신선한 재료 및 유기농 밀가루, 또한 유럽 최상의 식재료를 고집합니다. 르네상스 제과점은 각종 추억의 빵들부터 현대 젊은 층의 니즈를 만족시키는 트렌디한 빵에 이르기까지 다양하고 맛있는 제품들을 제공하고 있습니다. 1982년 시작한 동네빵집이 2대째 가업을 이어감으로써 앞으로 진정한 100년을 맞이할 것입니다.', 37.543145, 126.943335, '', '지하찰 5호선 마포역 2번 출구, 511m', '빵과 과자, 커피', '', '', '카페, 디저트', '', '08:30~21:00', '02-716-2808', '일요일'),
	(829, '설빙', '04050  서울 마포구 홍익로6길 15 (동교동, 삼주빌딩)  2층 설빙 홍대입구역점', 'images/설빙_829.jpg', '한국의 전통 디저트 카페 브랜드, 설빙\n\n설빙은 한국의 전통 디저트 카페 브랜드로서, 다양한 한국식 디저트를 사계절 내내 선보이는 곳입니다. 이곳의 대표 메뉴는 전통 재료 혹은 제철 과일을 곁들인 다양한 빙수입니다. 우유 얼음을 갈아 만든 달달하고 시원한 빙수는 무더운 여름의 별미로, 잠시나마 더위를 잊게 해줍니다. 그중에서도 고소한 콩고물과 쫄깃한 인절미 떡이 들어간 인절미 설빙은 남녀노소 모두에게 인기있는 베스트 셀러 메뉴입니다. 빙수 이외에도 치즈 가래떡, 꿀호떡, 떡볶이 등 다양한 한국식 디저트들이 판매되고 있습니다. 전통적이고 창의적이며 대중적인 디저트들로 한국인 뿐만 아니라 외국인들의 입맛까지 사로잡고 있는 디저트 카페입니다.', 37.555358, 126.922709, '', '지하철 2호선/경의중앙선 홍대입구역 9번 출구, 197m', '', '매일 (홍대입구역점)\n*지점별로 운영 정보가 상이하니 방문 전 홈페이지에서 확인 바랍니다.', ' https://sulbing.com/bbs/board.php?bo_table=store', '카페, 디저트', '', '매일 12:00 ~ 24:00 (홍대입구역점)\n*지점별로 운영 정보가 상이하니 방문 전 홈페이지에서 확인 바랍니다.', '02-323-3287 (홍대입구역점)', ''),
	(830, '[백년가게] 시골감자국', '03478  서울 은평구 응암로 174 (응암동)  1층, 2층', 'images/[백년가게]_시골감자국_830.jpg', '진하고, 구수한 국물과 부드러운 고기로 은평구에서 33년 가까이 자리를 지켜온 감자탕집 .\n\n김이 모락모락 나는 국물에서는 진한 육수만의 깊은 맛과 구수한 향이 코를 자극하며 부드럽고 감칠맛이 나는 고기는 먹는 이의 혀를 간지럽힙니다. 은평구에서 33년 가까이 변함없는 맛의 감자탕을 만들고 있는 시골감자국의 대표메뉴는 바로 우거지 감자탕입니다. \n\n\n\n\n시골감자국은 은평구의 토박이 음식점으로 지정된 은평구의 대표 감자탕집입니다. 현재 아들과 딸, 사위가 함께 분담하여 식당을 경영하고 있으며 거리가 조금 멀더라도 언제 어디서든 따뜻한 음식을 맛 볼 수 있도록 포장 및 배달서비스를 함께 운영하며 인지도를 높여나가고 있습니다. 또한 시골 감자국의 유일한 메뉴이자 시그니처 메뉴인 감자탕은 국내산 돼지등뼈를 핏물 제거와 손질을 통하여 4시간 동안 푹 익히고, 통감자, 우거지를 넣고 다시 끓여 내놓습니다. 메뉴는 단순하지만 감자탕 한 그릇을 내놓기 위해 쏟은 정성과 노력은 결코 단순하지 않습니다.', 37.587472, 126.916787, '', '지하철 6호선 새절역 2번 출구, 751m', '감자탕, 뼈찜 등', '', ' https://www.instagram.com/sigol.gamjatang', '음식점', '', '24시간 영업', '0507-1432-8489', '연중 무휴'),
	(831, '디도 재즈 라운지', '05044  서울 광진구 자양로18길 56 (구의동, 거송빌딩)', 'images/디도_재즈_라운지_831.jpg', '디도 재즈 라운지에서 음식과 와인의 맛을 더 풍성하게 만들어 줄 라이브 재즈 공연과 함께 분위기 있는 식사.\n\n라이브 재즈 공연과 함께 맛있는 음식과 와인을 즐길 수 있는 복합 문화 공간. 매일 라이브 공연이 진행되며, 공연 라인업 등 관련 정보는 디도 재즈 라운지 인스타그램에서 확인 가능합니다.', 37.537972, 127.086647, '', '지하철 2호선 구의역 2번 출구, 111m', '', '', ' https://www.instagram.com/dido_jazz_lounge/', '술집, 바', '', '화~일 19:00 ~ 24:00', '070-8621-7869', '매주 월요일'),
	(832, '삼청동 수제비', '03049  서울 종로구 삼청로 101-1 (삼청동)', 'images/삼청동_수제비_832.jpg', '항아리에 담겨 나오는 손 수제비\n\n삼청동 수제비는 한기영 사장이 1980년대 삼청동의 작은 분식집에서 시작해, 손님의 요구에 따라 손수 빚은 수제비로 명성을 얻었습니다. 1982년에 본격 수제비 전문점으로 개업했으며, 다른 수제비 전문점과 다르게 항아리에 담겨 나옵니다. 감자, 애호박, 김가루를 올려 간결한 재료로 담백하고 고소한 맛을 살리고 있습니다. 현재도 많은 추억의 맛을 찾는 한국인과 관광객이 방문하는 인기 있는 식당입니다.', 37.584542, 126.981935, '1만원대', '지하철 3호선 안국역 1번 출구, 1,2km', '수제비, 찹쌀새알옹심이, 감자전, 동동주', '매일', ' https://www.xn--2q1bp1re1b2wb9ypllh.kr/', '음식점', '', '11:00~20:00', '02-735-2965', ''),
	(833, '오얏꽃 카페', '03133  서울 종로구 돈화문로11다길 15 (돈의동)', 'images/오얏꽃_카페_833.jpg', '익선동에 위치한 고즈넉한 한옥 카페, 오얏꽃 카페\n\n오얏꽃 카페는 익선동에 위치한 한옥 카페로, 고즈넉한 분위기 속에서 맛있는 디저트와 핸드드립 커피를 즐길 수 있는 곳입니다. 조용한 공간과 예쁜 인테리어로 데이트를 하거나 가족끼리 방문하기에 제격이예요. 야외에는 처마 밑 마루에 걸터 앉을 수 있는 좌석과 오붓한 좌식 테이블이 마련되어 있어 한껏 운치를 느낄 수도 있습니다. \n이곳에는 케이크, 크로플, 와플 등 다양한 디저트가 준비되어 있지만, 그중에서도 빙수가 제일 유명합니다. 우유와 특제소스로 만들어진 고운 얼음 위에 과일 토핑과 퓨레, 수제 팥이 함께 제공되며 대표 메뉴는 자몽 빙수. 이외에도 전통팥빙수, 딸기빙수, 애플망고빙수 등 계절에 따라 다른 종류의 빙수가 제공됩니다.', 37.573053, 126.990551, '', '지하철 1 / 3 / 5 호선 종로3가역 6번 출구, 115m', '', '연중무휴로 공휴일, 연휴에도 정상 영업', ' https://www.instagram.com/oyatt_kkot', '카페, 디저트', '자세한 소식은 인스타그램 @oyatt_kkot을 통해 확인하시길 바랍니다.', '매일 11:00~22:00 (21:30 라스트오더)', '', ''),
	(834, '또또', '03700  서울 서대문구 홍제천로6길 2 (연희동)  1층', 'images/또또_834.jpg', '홍제천에 위치한 한국식 선술집 또또\n\n또또는 홍제천 앞에 위치한 정겨운 분위기의 한국식 선술집이다. 정갈한 음식과 깔끔한 공간으로 동네 주민들에게도 인기가 많은 곳입니다. 한식 주점답게 기본 찬으로 잡채가 제공되며, 다양한 종류의 전통주들이 준비되어있어 입맛에 맞춰 골라 마실 수 있습니다. 특히나 안주가 맛있기로 유명하며, 대표메뉴로는 민자 부대찌개가 있습니다.', 37.573626, 126.924822, '', '지하철 경의중앙선 가좌역 4번 출구, 1.2km', '', '', ' https://www.instagram.com/ddoddo.seoul', '술집, 바', '자세한 사항은 인스타그램 @ddoddo.seoul 을 참고하시길 바랍니다.', '화요일~금요일 17:00~24:00\n토요일 16:00~24:00\n일요일 16:00~23:00', '0507-1358-7312', '월요일'),
	(835, '[백년가게] 진미식당', '04369  서울 용산구 백범로90길 46 (문배동)', 'images/[백년가게]_진미식당_835.jpg', '신선한 콩으로 45년간 청국장과 콩국수를 만드는 한식당.\n\n진미식당은 용산구 문배동 귀퉁이에서 45년째 정성 가득한 콩국수를 서비스하고 있는 한식가게입니다. 45년 전 서울로 상경해 콩국수와 라면 등을 만들어 팔았던 창업주는 진미식당을 창업해, 운영해 왔습니다. 부모님에게서 아들로 이어진 진미식당만의 전통은 언제나 신선한 지역 식재료만을 사용한다는 것입니다. \n\n\n\n\n지금도 경북 문경에서 구매한 왕태만을 사용해 직접 메주를 띄우고 발효시켜 청국장을 만들고 있으며 여름에는 별미인 콩국수를 서비스합니다. 비린 냄새가 없고 건강에 좋은 왕태콩으로 만든 청국장과 콩국수는 담백하고 깊은 맛으로 고객들의 호평을 받습니다. 매일 당일 사용할 재료만 구매해 당일에 모두 소진하는 진미식당 만의 규칙은 45년이 지난 지금도 철저히 유지되고 있습니다.', 37.536696, 126.970178, '', '지하철 4 / 6호선 삼각지역 8번 출구, 381m', '콩국수, 청국장 등', '', ' https://munbaejinmi.modoo.at', '음식점', '', '월요일~금요일 09:30~16:00, 17:30~20:30\n토요일 10:00~19:00, 일요일 11:00~15:30', '02-703-6842', ''),
	(836, '도수향', '06018  서울 강남구 선릉로161길 21-4 (신사동)', 'images/도수향_836.jpg', '거피 팥고물로 만든 이북식 인절미 전문점\n\n이북식 인절미 전문점인 도수향은 서울3대 떡집으로 팥 껍질을 벗긴 \'거피\' 팥고물로 만든 인절미로 유명합니다. 당일 생산, 당일 판매를 원칙으로 판매하고 있어 사전 예약이 필수입니다. 연예인들이 직접 선물용으로 구매한것이 소개 되기도 하면서 입소문이 난 한국 전통 떡 기념품 가게입니다. 사이즈는 소, 중, 대로 나뉘어 있고 고급스러운 보자기(한국전통) 포장을 선택할 수 있어 고급스러운 선물로도 제격입니다.', 37.527205, 127.038471, '', '지하철 수인분당선 압구정로데오역 6번출구, 224m', '', '', '', '', '', '월~토 : 08:30~19:00', '02-540-2939', '매주 일요일'),
	(837, '어필남산', '04346  서울 용산구 회나무로42길 36 (이태원동) 2층', 'images/어필남산_837.jpg', '남산타워 뷰 분위기 좋은 경리단길 와인바\n\n경리단길 오르막길 끝자락에 위치한 캐주얼 다이닝 바. 경치좋은 이 곳에서 맛있는 음식과 함께 분위기 있는 식사를 즐겨보세요.', 37.540077, 126.994298, '', '지하철 6호선 이태원역 2번 출구, 980m', '어필 스테이크, 트러플 치즈 파스타, 팟 카프라오 파스타, 그릴드 샐러드', '', ' https://app.catchtable.co.kr/ct/shop/uphill.namsan', '음식점', '캐치테이블\' 어플에서 예약 가능', '평일 18:00~22:30\n주말 15:00~22:30', '0507-1481-2001', ''),
	(838, '비채나', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰) 81층', 'images/비채나_838.png', '서울의 스카이라인을 바꾼 롯데월드타워 81층 한식 레스토랑.\n\n비채나는 한국의 아름다운 도자기에 정갈한 한식을 담아내고, 우리 술과 함께 최고의 한식 경험을 제공하는 한식 레스토랑입니다. 비채나는 ‘한식 세계화’라는 목표를 가지고, 한국의 전통과 현대를 조화롭게 담아낸 한식을 선보이고 있습니다.', 37.513713, 127.104302, '', '지하철 2/8호선 잠실역 2번 출구, 29m', '', '', ' https://www.bicena.com/', '음식점', '', '11:30~15:00, 18:00~22:00', '02-3213-1261', ''),
	(839, '라연', '04605  서울 중구 동호로 249 (장충동2가)', 'images/라연_839.png', '라연은 한국을 대표하는 한식 레스토랑으로, 미쉐린 스타를 획득.\n\n서울 신라호텔 23층에 위치한 한식 레스토랑 라연은 남산의 아름다운 경치를 감상하며 한국의 전통과 현대의 세련됨을 동시에 느낄 수 있는 곳입니다. 한국의 전통 문양을 활용한 인테리어와 조선백자를 형상화한 식기, 전국 각지에서 공수한 제철 식재료 등은 라연의 정통성과 품격을 더했습니다. 라연의 음식은 한국의 맛을 섬세한 조리법으로 현대적으로 재해석해 냈으며, 와인과도 잘 어울려 특별한 미식 경험을 선사합니다.', 37.557397, 127.006274, '', '지하철 3호선 동대입구역 5번 출구, 429m', '', '', ' https://www.shilla.net/seoul/dining/viewDining.do?contId=KRN#ad-image-0', '음식점', '', '매일 12:00~14:30, 17:30~21:30', '02-2230-3367', ''),
	(840, '우리술집 다람쥐', '03134  서울 종로구 서순라길 101 (권농동) 1층', 'images/우리술집_다람쥐_840.jpg', '서순라길에 위치한 전통주점\n\n맛있는 술과 음식, 대화의 시간이 있는 편안한 저녁식사를 즐길 수 있는 공간으로 서순라길 종묘 담벼락 앞에 자리잡고 있습니다.\n전통주점인 우리술집 다람쥐에서는 다양한 전통주를 취급합니다. 주류주문이 필수이고, 일반 소주와 맥주는 없다. 매장내에 재밌는 오브제들도 배치되어 있어 입과 더불어 눈도 재미를 느낄 수 있습니다.', 37.574746, 126.991731, '', '지하철 1 / 3 / 5호선 종로3가역 7번 출구, 325m', '', '수-일', '', '술집, 바', '모든 문의는 3시 이후 매장 전화로 문의', '수-금 17:00-23:30 (라스트오더 22:30)\n토-일 16:00-23:30 (라스트오더 22:30)', '070-4258-8880', '월,화 휴무'),
	(841, '제일제면소 명동점', '04534  서울 중구 명동7길 13 (명동1가, 명동증권빌딩) 호텔28 2층', 'images/제일제면소_명동점_841.jpg', '제일제면소의 퀄리티 있는 별미국수와 샤브샤브, 한식 일품요리를 제공하는 한식 캐주얼 다이닝\n\n서울의 중심이자 대표 상권인 명동에서 제일제면소의 노하우와 비법이 담긴 별미국수와 샤브샤브, 한식을 재해석한 특색 있는 일품요리, 다양한 전통주를 선사하는 캐주얼 다이닝입니다. 한국적인 요소가 반영된 인테리어와 통창이 있는 쾌적한 매장 공간에서 한식을 즐길 수 있으며, 아늑한 룸 공간도 조성되어 있어 프라이빗한 모임 장소로도 제격입니다. 매장 내부 조도 조절을 통해 낮과 밤의 다른 분위기를 자아내어, 점심에는 면 요리와 곁들임 메뉴를 통해 든든한 식사가 가능하고, 저녁에는 일품요리와 전통주를 포함한 다양한 주류를 함께 즐기며 분위기있는 식사나 모임이 가능합니다.', 37.564353, 126.983969, '2만원대', '지하철 2호선 을지로입구역 5번 출구, 219m', '', '매일', ' https://m.cheiljemyunso.co.kr/', '음식점', '다양한 언어로 안내 가능한 메뉴판 보유', '11:00 ~ 23:00', '070-4110-6088', ''),
	(842, '무교주가 제일제면소', '04521  서울 중구 무교로 28 (무교동, 시그너스빌딩)  1층', 'images/무교주가_제일제면소_842.jpg', '낮에는 샤브샤브를, 저녁에는 한식과 전통주를 즐길 수 있는 한식 다이닝.\n\n무교주가 제일제면소는 낮에는 푸짐하고 든든하게 담아내는 샤브샤브와 국수, 저녁에는 한식을 기반으로 풀어내는 다양한 별미요리와 트렌디한 전통주를 선사하는 한식 다이닝 브랜드입니다. 식당 내부가 넓고 실내좌석과 함께 야외좌석도 준비되어 있습니다. 점심에는 점심메뉴인 샤브샤브와 함께 여러 사이드메뉴들도 즐길 수 있어 직장인들도 많이 찾습니다. 또한 정갈한 식사메뉴와 쾌적한 내부환경으로 가족단위손님과 단체손님들이 많이 찾습니다.', 37.568469, 126.979584, '2만원대', '지하철 5호선 광화문역 5번 출구, 295m', '', '월~일', ' http://www.cheiljemyunso.co.kr/the_end.asp', '음식점', '단체 여행객을 위한 룸(20석), 테라스(22석) 좌석 사용 가능(총 98석)', '월~금 11:00~23:00 (브레이크타임 14:30~16:00 / 라스트오더 22:00)\n토요일 11:00~22:00 (라스트오더 21:00)\n일요일 11:00~21:00 (라스트오더 20:00)', '02-318-1865', ''),
	(843, '[백년가게] 향호면옥', '05656  서울 송파구 마천로 79 (오금동)', 'images/[백년가게]_향호면옥_843.jpg', '강릉시 최북단의 향과 맛을 옮겨온 칼국수 맛집\n\n강릉시 최북단, 향긋한 바다 내음과 아름다운 풍경이 조화를 이룬 곳, 향호면옥은 이기창 대표 부친의 고향인 주문진 향호마을의 이름에서 유래된 상호입니다. \n\n\n\n\n향호면옥에서는 ‘맛과 가격이 경쟁력이다’라는 경영철학을 바탕으로 식재료는 모두 국내 산지에서 공수해오며 국수는 주문 즉시 제면기로 뽑아 조리합니다. 만두 역시 한식 조리사 자격증을 보유하신 어머니가 매일 새벽 당일 사용할 양만을 빚어 활용합니다. 야채와 고춧가루는 매일 직접 가락시장에서 구매하고 있으며 겉절이 역시 국산 재료로 매일 담그고 있습니다. 부모님의 땀이 서린 가게를 2대 이기창 대표가 승계해 경영전반을 운영하고 있습니다. 1인 손님이라도 배부르게 먹고 갔으면 좋겠다는 마음으로 보리밥을 서비스로 선사하고 있습니다. 찾아올 고객을 생각하며 매일 새벽에 빚어내는 향호면옥의 만두와 국수는 입소문을 타고 지역의 명물입니다.', 37.507479, 127.129208, '1만원대', '지하철 5호선 방이역 1번 출구, 332m', '바지락칼국수, 왕만두', '', '', '음식점', '', '11:00 ~ 21:30 (14::30~16:00 브레이크 타임)', '02-406-0422', '일요일 정기휴무'),
	(844, '챔프커피 제3작업실', '04545  서울 중구 을지로 157 (산림동, 대림상가) 라열 3층 381호', 'images/챔프커피_제3작업실_844.jpg', '챔프커피의 3번째 커피샵이자, 을지로의 커피 맛집\n\n을지로 중심의 세운상가에 자리한 챔프커피. 챔프커피 사장님들이 직접 경험하고 고민해서 만든 시그니처 커피는 사람들의 발길을 끊임없이 이어집니다.', 37.567146, 126.995451, '', '지하철 2/3호선 을지로 4가역 1번출구, 186m', '', '매일', ' https://www.instagram.com/champcoffee_official', '카페, 디저트', '', '11:00~19:00', '010-8943-4516', ''),
	(845, '진미식당', '04207  서울 마포구 마포대로 186-6', 'images/진미식당_845.png', '미쉐린 가이드 서울 2025에 등록된 게장맛집\n\n서해에서 잡은 꽃게로만 담근 간장게장 메뉴를 선보이고 있는 진미식당은 꽃게 철인 6월과 12월에 대량 구입하여 섭씨 마이너스 35도에서 급속 냉각, 보관한 꽃게만을 사용합니다. 따라서 꽃게 철이 아니어도 항시 신선하고 맛있는 게를 먹을 수 있고, 암게를 사용해 보다 맛있는 게장을 먹을 수 있다는 것이 장점입니다.  진미식당에서 먹을 수 있는 간장게장은 서산 생강을 넣고 삭힌 간장에 3일 동안 숙성시켜 손님상에 올라갑니다. 함께 나오는 뚝배기 계란찜과 게국지, 어리굴젓, 감태(해조류) 등 10여 가지의 곁들임 반찬이 나와 다양한 반찬을 맛볼 수 있습니다. 많은 연예인들과 유명 인사들도 많이 방문하는 장소입니다.', 37.550585, 126.955800, '', '지하철 5호선 애오개역 4번 출구, 282m', '', '월요일 ~ 토요일', ' https://thejinmi.modoo.at/ ', '음식점', '예약 후 방문을 추천한다.', '월요일 ~ 토요일 12:00 ~ 20:00 (브레이크타임 15:30~17:00)', '02-3211-4468', '일요일 정기휴무'),
	(846, '이다 (IDA)', '03134  서울 종로구 서순라길 153 (권농동)', 'images/이다_(IDA)_846.jpg', '한식 재료를 이용한 창의적인 요리를 선보이는 컨템포러리 레스토랑\n\n한식 재료를 이용해 창의적인 요리를 선보이는 컨템포러리 레스토랑으로 서순라길 끝자락에 위치해 산책하기 좋은 곳에 자리잡고 있습니다. 시기에 맞는 신선한 재료들로 계절을 한껏 느낄 수 있는 음식들이 준비되어 있습니다. 계절별로 바뀌는 메뉴들이 이 레스토랑의 매력입니다. 또한 종묘와 계절마다 특색있는 경치를 자랑하는 창덕궁이 바로 옆에 위치해 있어 산책하기 매우 좋은 위치에 있습니다.', 37.577024, 126.991714, '', '지하철 3호선 안국역 4번 출구, 560m', '', '매일', ' https://www.instagram.com/ida_seoul/', '음식점', '주차공간이 없으니 근처 유료 주차장을 이용해주세요.', '매일 12:00~22:00 (브레이크타임 15:00~17:00 / 라스트오더 21:00)', '0507-1334-3979', ''),
	(847, '수수커피브루잉', '03134  서울 종로구 서순라길 97 (권농동)', 'images/수수커피브루잉_847.jpg', '서순라길에 위치한 핸드드립 카페 수수커피브루잉\n\n수수커피브루잉은 서순라길에 위치한 잔잔한 분위기의 감성 카페입니다. 이곳의 커피는 오로지 핸드드립 커피로만 제공되며, 상세한 설명이 적힌 다양한 종류의 원두가 준비되어있습니다. 논커피 메뉴들과 간단한 디저트도 있으니, 창 밖의 풍경을 바라보며 여유를 즐기고 싶다면 이곳이 제격.\n가죽공방을 함께 운영하며 카페 한켠에서 가죽 제품들을 판매중이니 참고바랍니다.', 37.574570, 126.991866, '', '지하철1/3/5호선 종로 3가역 7번 출구, 299m', '', '내·외부 사정으로 유동적 - 인스타그램 프로필에 매주 공지', '', '카페, 디저트', '이용시간과 영업일은 @susu_coffeebrewing 에 매주 공지되오니, 방문 전 꼭 참고하시길 바랍니다.', '내·외부 사정으로 유동적 - 인스타그램 스토리에 매일 공지', '', ''),
	(848, '신당동 떡볶이 타운', '04611  서울 중구 다산로35길 5 (신당동)', 'images/신당동_떡볶이_타운_848.jpg', '한국 분식 문화의 역사와 전통을 느낄 수 있는 즉석떡볶이 거리\n\n서울 중구 신당동에 위치한 신당동 떡볶이 타운은 테이블에서 직접 조리해 먹는 즉석떡볶이 문화가 시작된 곳입니다. 1953년 마복림 할머니가 시작한 즉석 떡볶이 가게를 기점으로 골목 전체에 떡볶이 전문점들이 밀집해 있습니다. 한국 분식 문화의 역사와 전통을 느낄 수 있는 장소로, 다양한 맛과 추억을 함께 즐길 수 있는 곳입니다. 해물, 짜장, 닭발 등 다양한 변형 메뉴도 맛볼 수 있으며, 대표 맛집으로는 마복림 떡볶이, 아이러브신당동, 삼대할먼네 등이 있습니다. 최근에는 방문객 수가 이전보다 줄었지만 여전히 한국 대표 분식 거리로 분식 애호가와 여행객들에게 있기 있는 명소입니다.', 37.563221, 127.015116, '', '지하철 2호선/6호선 신당역 8번출구 242m', '', '상점마다 상이함', '', '', '', '상점마다 상이함', '', ''),
	(850, 'SAMSAMSAM 롯데월드몰점', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰) 5층', 'images/SAMSAMSAM_롯데월드몰점_850.png', '미국음식을 즐길 수 있는 미국식 레스토랑\n\n쌤쌤쌤 롯데월드몰점은 용리단길에 위치한 쌤쌤쌤 본점을 기반으로 한 곳입니다. 이곳은 미국 현지 미슐랭 3스타에서 근무한 경험을 가진 셰프들이 제공하는 파스타, 샐러드, 리조또, 라자냐 등 최고의 맛과 서비스를 자랑하고 있습니다. 특히, 롯데월드몰점에서만 맛볼 수 있는 라자냐, 샘 하우스 스테이크, 잠봉베르 파스타, 포르치니 뇨끼, 쉬림프 오일 파스타 등 다양한 특별 메뉴가 있어 많은 사람들이 찾고 있습니다. 인테리어는 감성적이고 동화 같은 분위기를 자아내며, 넓은 매장과 테이블 간 간격이 넉넉해 쾌적하고 편안한 식사를 즐길 수 있으며 롯데월드몰 아쿠아리움 쪽 엘리베이터를 이용하면 더욱 편리하게 방문할 수 있습니다.', 37.513713, 127.104302, '', '지하철 2/8호선 잠실역 10번 출구, 22m', '', '매일', ' https://www.instagram.com/samsamsam.kr/', '음식점', '', '매일 10:30~22:00 (라스트오더 21:00)', '0507-1433-4540', ''),
	(851, '진고개 동대문점', '03106  서울 종로구 종로 301-1 (창신동)', 'images/진고개_동대문점_851.jpg', '고풍스러운 분위기에 전통과 맛을 살린 한식당\n\n진고개 동대문점은 1974년 전국요식물경연대회에서 최우수상을 수상한 한식 전문점으로, 갈비찜, 전골, 게장, 불고기 등 다양한 한식을 선보입니다. 특히 갈비찜은 한약재와 함께 오랜 시간 조리해 깊은 향미와 부드러운 식감을 자랑하며, 남녀노소 모두에게 사랑받는 메뉴입니다. 동대문역 인근에 위치해 한양도성 산책과 함께 즐길 수 있습니다.', 37.572187, 127.011162, '', '지하철 1/4호선 동대문역 1번 출구, 57m', '불갈비, 갈비찜정식, 곱창전골, 어복쟁반 (2인 이상 주문 가능)', '매일', '', '음식점', '', '월요일~금요일 11:00~21:30\n토요일~일요일 11:00~21:00', '02-763-3565', ''),
	(852, '가봉루', '03182  서울 종로구 새문안로5길 5-27 (당주동, 당주빌딩)', 'images/가봉루_852.jpg', '고기튀김이 매력적인 광화문 중화요리 맛집\n\n가봉루는 한국식 중식의 매력을 느낄 수 있는 곳으로, 50년 이상의 역사를 자랑하고 있습니다. 소박한 인테리어와 과거의 정겨운 분위기가 특징입니다. 음식은 재료를 아낌없이 쓰며, 기본에 충실한 맛을 강조합니다. 다른 중국집에서는 흔히 볼 수 없는 고기튀김은 소금과 후추로 간을 맞춰 담백하고 깔끔한 풍미를 자랑하는 가봉루의 대표 메뉴이며, 짬뽕, 탕수육, 짜장면의 맛 역시 일품입니다.', 37.571027, 126.974572, '', '지하철 5호선 광화문역 8번 출구, 109m', '고기튀김, 짜장면, 삼선짬뽕, 라조위', '월요일-토요일', '', '음식점', '', '11:30~21:00', '02-736-8100', '일요일'),
	(853, '파스텔커피웍스', '04083  서울 마포구 성지길 58 (합정동, 노박빌딩)  1층, 지하1', 'images/파스텔커피웍스_853.jpg', '스페셜티 커피 전문 로스팅 기업 파스텔커피웍스\n\n2011년, 10평 남짓한 작은 카페로 시작하여 오직 맛있는 커피와 전문가 라는 두 단어에 집중한 커피 전문회사입니다.\n전 세계 커피를 테스팅하며 섬세한 로스팅 프로파일을 연구해 훌륭한 커피를 제공합니다. 파스텔커피웍스는 획일적인 대량생산이 아닌 섬세하고 정교한 기술로 작품을 완성하는 아티산 로스터리를 지향합니다.', 37.546270, 126.912618, '', '지하철 2/6호선 합정역 7번 출구, 326m', '', '월-일', ' https://pastelcoffee.com/?NaPm=ct%3Dlvai81fm%7Cci%3Dcheckout%7Ctr%3Dds%7Ctrx%3Dnull%7Chk%3D9624cd012ab7986520e3932ea4d06a26a26909db', '카페, 디저트', '공식 홈페이지에서 원두 구매 및 커피와 관련된 상품들의 구매가 가능합니다.', '월-금 8:30-18:00 (라스트오더 17:30)\n토-일 09:30-18:30 (라스트오더 18:00)', '02-322-7549', ''),
	(854, 'The Queen’s Guard 퀸즈가드', '03134  서울 종로구 서순라길 115 (권농동)   1층/ B1', 'images/The_Queen’s_Guard_퀸즈가드_854.jpg', '서순라길에 위치한 영국식 펍 퀸즈가드\n\n퀸즈가드(The Queen’s Guard)는 서순라길에 위치한 영국식 펍입니다. 영국식 담금주(Infused Gin), 다양한 런던 드라이진, 브리티쉬 비어, 사이더 등 잘 알려지지 않았던 영국의 술과 음식을 판매하고 있습니다. 돌담길을 바라보며 운치를 즐길 수 있는 테라스 좌석이 매우 인기있습니다. 인기가 많은 펍으로 오픈 전부터 웨이팅이 긴 편입니다. 매년 정기적으로 크리스마스 이벤트를 예약제 선착순으로 진행하고 있습니다.', 37.575407, 126.991443, '', '지하철 1 / 3 / 5 종로3가역 7번 출구, 360m', '', '', '', '술집, 바', '후불제로 운영됩니다.\n자세한 사항은 인스타그램 @thequeens_guard을 참고하시길 바랍니다.', '14:00 ~ 23:00', '', ''),
	(855, '안녕브릭샌드', '03145  서울 종로구 인사동길 49 (관훈동) 안녕인사동 1층', 'images/안녕브릭샌드_855.jpg', '브릭샌드는 벽돌모양 디자인에 좋은 재료로 만든 건강한 디저트입니다.\n\n브릭샌드는 벽돌모양 디자인에 좋은 재료로 만든 건강한 디저트입니다. 좋은 재료에서 나오는 신선함, 겉은 바삭하고 속은 촉촉한 환상적인 식감, 현장에서만 느낄 수 있는 생동감. 달콤하고 부드러운 브릭샌드 한 입에 커피나 차 한잔을 곁들여 보세요. 소중한 지인들을 위한 근사한 디저트 선물로도 제격입니다. 정직하고 좋은 재료로 매일 정성스럽게 만듭니다.', 37.574467, 126.983552, '', '지하철 3호선 안국역 6번 출구 , 229m', '달콤브릭(2600원), 다크브릭(2600원), 호랑브릭(2800원), 아메리카노 (5000원)', '', ' https://www.instagram.com/happybricksand/', '카페, 디저트', '100평 규모의 넓은 홀 매장 이용 가능', '09:30~20:30', '0507-1333-4974', ''),
	(856, '신당동 천팥죽', '04577  서울 중구 다산로44길 33 (신당동)', 'images/신당동_천팥죽_856.jpg', '팥죽과 팥칼국수를 전문으로하는 신당동 천팥죽\n\n신당동 천팥죽은 우리나라 전통 음식인 팥죽과 팥칼국수를 전문으로 하는 음식점입니다. 메뉴가 팥죽과 팥칼국수 단 두 개 뿐인 데에서 사장님의 음식에 대한 자부심을 엿볼 수 있습니다. 주문하는대로 바로 끓여 나오기때문에, 진한 팥 향과 쫄깃한 옹심이를 맛볼 수 있습니다. 그 부드럽고 진한 맛을 잊지 못해 다시 찾는 단골 손님들이 많습니다. 만약 간이 부족하다면, 테이블 위에 놓인 설탕과 소금을 넣어 입맛에 맞게 맟춰 먹으면 됩니다. 친절한 사장님과 밑반찬까지 맛있는 음식으로 남녀노소 모두에게 사랑받는 곳입니다. 속이 든든해지는 따뜻한 팥죽 한 그릇은 특히 날이 쌀쌀한 겨울에 잘 어울리는 음식이니, 동짓날에는 이곳을 방문해보는 것을 추천합니다.', 37.565164, 127.018750, '1만원대', '지하철 2/6호선 신당역 4번 출구, 78m', '', '매일', '', '음식점', '', '매일 10:30 ~ 20:00 (라스트오더 19:30)', '02-2237-6385', ''),
	(857, 'gaga 가가', '03059  서울 종로구 계동길 5 (계동)', 'images/gaga_가가_857.jpg', '300년된 한옥에서 즐기는 테라스가 있는 한식 와인바\n\n300년된 한옥에서 즐기는 테라스가 있는 한식 와인바로, 최정숙 오너쉐프가 직접 정하는 메뉴로 운영되는 프라이빗 레스토랑입니다. Gaga bar는 손님이 원하는 메뉴를 시켜 여러팀이 한 개의 테이블에서 즐기는 bar 입니다. 외부에 마련된 테라스 좌석은 예외입니다. 조리되는 음식들은 소스를 잘 사용해 음식별로 느껴지는 다양한 풍미가 일품입니다.', 37.577399, 126.986348, '', '지하철 3호선 안국역 3번 출구, 19m', '', '화-토', ' https://www.instagram.com/gagabar_seoul', '술집, 바', '자세한 사항은 인스타그램을 참고해주세요.', '화~금 17:00 ~ 24:00 (라스트오더 23:15)\n토 15:00 ~ 24:00 (라스트오더 23:15)', '010-5246-2441', '월요일,일요일'),
	(858, '별미곱창', '03041  서울 종로구 자하문로1길 50 (필운동)', 'images/별미곱창_858.png', '허영만의 백반기행에 출연한 서촌의 곱창 맛집, 별미곱창\n\n서촌 먹자골목 근처에 위치한 별미곱창은, 아는 사람은 일찍부터 대기한다는 서촌의 대표 곱창 맛집입니다. 한국의 대표 맛집 소개 프로그램인 \'식객 허영만의 백반기행\'에 출연하여 서촌 대표 맛집임을 다시 한 번 입증했습니다. 이곳은 돼지곱창 야채볶음 단일 메뉴이며, 볶음밥 추가가 가능합니다.  자극적이지 않고 부담스럽지 않은 매운맛에 한국을 대표하는 고추장 양념이 돼지곱창 속에 가득 배어들어 계속해서 끊임없이 먹게 됩니다. 맥주 혹은 소주를 곁들이면 최고의 한 끼 식사를 경험할 수 있습니다. 매장 안은 테이블이 5개 정도로 작은 편이기 때문에, 식사 시간보다 일찍 방문하는 것을 추천합니다.', 37.576923, 126.969707, '1만원대', '지하철 3호선 경복궁역 1번 출구, 288m', '', '월요일~일요일', '', '음식점', '-2인분 이상 주문 필수\n-야채 리필 1회 가능\n-돼지곱창 1/4 정도를 남겨야 볶음밥 조리 가능', '12:00~22:00 (재료 소진 시 영업 종료)', '02-737-1320', ''),
	(859, '퍼멘츠', '04379  서울 용산구 한강대로7길 22 (한강로3가)', 'images/퍼멘츠_859.png', '비건 발효 음식을 내추럴 와인, 수제 Raw 콤부차와 함께 제공\n\n퍼멘츠는 2021년 서교동에서 콤부차 전문 매장으로 시작하여, 현재는 용산에서 비건 음식점으로 운영되고 있는 곳입니다. 화학조미료 및 인공첨가물을 일체 사용하지 않고 직접 발효한 식물성 재료들을 기반으로 건강한 음식을 제공하는 것이 퍼멘츠만의 독특한 특징입니다. 이곳은 12시부터 17시까지는 키친&카페로 운영하며, 17시부터는 분위기있는 키친&와인바로 변신합니다. 옥상엔 야외테라스가 위치하여 날씨가 좋은 날이면 도심을 바라보며 와인을 즐길 수 있습니다. 가게 안쪽으로 들어가면 커다란 책장을 빼곡하게 채운 책과 DVD,  아기자기한 소품들이 즐비해있어 인테리어를 즐기기에도 더할 나위 없는 장소입니다.  간혹 열리는 <퍼멘츠 데이드림>날이면 다양한 아티스트들의 공연을 보며 식사를 할 수 있기 때문에 음악과 내추럴와인을 사랑한다면 꼭 들러봐야 하는 장소 중 하나입니다.', 37.524775, 126.961848, '', '지하철 1호선/ 경의중앙선 용산역 1번 출구, 636m', '', '매일', ' https://www.instagram.com/ferments.seoul', '음식점', '#NAME?', '월요일~목요일, 일요일 11:30 - 23:00\n금요일~토요일 11:30 - 24:00', '0507-1340-6687', ''),
	(860, '클럽 에스프레소', '03020  서울 종로구 창의문로 132 (부암동)', 'images/클럽_에스프레소_860.jpg', '대통령 커피 문블렌드로 유명한 부암동 카페\n\n1990년부터 영업을 시작해온 클럽 에스프레소는 부암동의 터줏대감 카페입니다. 커피 맛이 좋기로 유명해 현재까지도 많은 사랑을 받고있습니다. 클럽블렌드와 문블렌드 커피가 대표 메뉴이며, 이외에도 다양한 메뉴와 시음코너가 준비되어 있어 입맛에 맞게 선택하여 즐길 수 있습니다. 가게 곳곳에 놓인 오랜 세월의 흔적을 찾아보며, 커피 한 잔과 함께 고즈넉한 운치를 만끽하길 바랍니다. 카페 내부와 온라인 홈페이지에서 다양한 원두와 드립백, 각종 커피용품들을 판매 중입니다.', 37.592689, 126.965979, '', '지하철 3호선 경복궁역 3번 출구, 7212, 7022,1020 버스 탑승, 부암주민센터 앞 하차', '', '', ' https://www.clubespresso.co.kr/', '카페, 디저트', '자세한 사항은 인스타그램 @clubespresso_1990을 참고하시길 바랍니다.', '매일 09:00~19:00\n라스트오더 18:50', '02-764-8719', ''),
	(861, '거울한옥 미러룸', '03053  서울 종로구 삼청로2길 40 (소격동)', 'images/거울한옥_미러룸_861.jpg', '100년된 한옥을 현대적으로 재해석한 카페, 거울 한옥 미러룸\n\n삼청동에 위치한 거울한옥 미러룸은 100년 된 장승업 생가터를 현대적으로 해석한 한옥 카페입니다. 넓직한 내부에는 서까래가 그대로 남아있고, 야외 테라스에는 앉을 수 있는 툇마루가 있어 한옥의 멋과 고즈넉함을 느낄 수 있습니다. 이곳의 가장 큰 특징은 내부 벽면이 거울로 이루어졌다는 것. 푸른 식물이 보이는 통창과 어우러진 거울 벽은 한층 더 넓고 청량한 공간을 제공합니다. 밤이면, 카페 곳곳의 조명이 거울에 반사되어 만들어지는 아름다운 풍경도 또다른 볼거리입니다. \n자연주의를 표방하는 카페답게, 생재료로 직접 만든 메뉴들을 맛볼 수 있습니다. 애플티, 매실, 오미자 등의 과실차와 과실주가 있으며 사과나무 크로플같은 디저트 메뉴들도 준비되어있습니다.', 37.580059, 126.981109, '', '지하철 3호선 안국역 1번 출구, 642m', '', '', ' https://www.instagram.com/cafe.mirrorroom/', '카페, 디저트', '자세한 소식은 인스타그램 @cafe.mirrorroom을 통해 확인하시길 바랍니다.', '매일 11:30~22:00', '02-6085-3900', ''),
	(863, '업스탠딩 Upstanding coffee', '04337  서울 용산구 신흥로 99-11 (용산동2가)', 'images/업스탠딩_Upstanding_coffee_863.jpg', '특색있는 계단이 있는 해방촌 시장 속 카페\n\n해방촌에서 빼놓을 수 없는 핫플레이스 답게, 카페 업스탠딩에서는 특색있는 인테리어를 만나 볼 수 있습니다. 낙후되고 오래된 동네시장에서 힙하고 감성있는 공간으로 대변신하며, 나선형의 내부계단이 있는 멋스러운 공간으로 재탄생했습니다. 가족, 친구, 연인등의 다양한 모임으로 방문하여 편안하게 커피 한잔하기 좋은 곳입니다.', 37.544960, 126.984968, '', '지하철 4호선 숙대입구역 5번 출구 정류장에서 용산 02 버스 탑승, 해방촌오거리 정류장에서 하차 후 도보 2분', '', '매일 (자세한 영업일은 인스타그램 @upstanding_coffee을 참고해주세요.)', ' https://www.instagram.com/upstanding_coffee/?hl=ko', '카페, 디저트', '', '월-일 10:00-20:00 (라스트오더 19:30)', '0502-1917-8727', ''),
	(864, '멕시타이거', '06129  서울 강남구 테헤란로1길 42 B1층 1호', 'images/멕시타이거_864.png', '산 크리스토발 칸티나를 모티브로 완성한 터프한 매력의 멕시칸 차이니즈 데낄라펍\n\n멕시타이거는 멕시코 히피들의 도시입니다.  산 크리스토발 칸티나를 모티브로 완성한 터프한 매력의 멕시칸 차이니즈 데낄라펍입니다. 맥시코 고유의 짙은 무드를 담고 있어 입구를 들어오는 순간부터 그 분위기에 압도됩니다. \n\n\n\n\n주황빛 불길이 일렁이는 어둡고 비밀스런 호랑이 소굴에는 끈적한 눈빛과 호탕한 건배소리가 가득합니다. 지하엔 붉게 번지는 네온사인아래, 거침없는 이야기를 나누는 공간. 데낄라 라운지가 펼쳐집니다.\n\n\n\n\n타코, 퀘사디야. 나초등 아니코닉한 멕시칸 요리에 차이니즈의 킥을 더한 특색있는 메뉴들. 300도의 대형화덕에서 펼쳐지는 데낄라 글레이징 퍼포먼스까지 빼놓을 것이 없는 강남 대표 미식공간입니다.', 37.501130, 127.027149, '', '지하철 2호선/신분당선 강남역 11번출구, 299m', '지미추리 치킨몰레 / 지미추리 소스를 듬뿍 올린 멕시칸 간장치킨과 녹진한 버터몰레 (45,800원)\n하바네로 치킨몰레/ 하바네로 핫소스와 살사크런치로 화끈하게 매운 치킨과 부드러운 버터몰레 (45,800원)\n당근 데낄라세트 / 달달한 당근쥬스로 만든 데낄라 칵테일 세트 (18,900원)\n피쉬타코(바삭한 감자전 퀘사디야에 마라라구와 치폴레마요를 곁들인 요리) 18,900원\n빠빠스 (바삭한 알감자에 마라라구, 할라피뇨를 곁들인 멕시코 요리) 13,900원', '', ' http://www.nakedtiger.co.kr/', '', '외국어 메뉴판 (한/중/일/영)', '매일 17:00 - 01:00', '0507-1425-9866', ''),
	(865, '레이지버거클럽 부암점', '03022  서울 종로구 창의문로 137 (부암동) 2층', 'images/레이지버거클럽_부암점_865.jpg', '분위기부터 맛까지 완벽한 부암동 수제버거\n\n레이지버거클럽은 부암동의 수제버거 맛집으로 유명합니다. 2층에 위치한 매장은 미국 모티브의 깔끔하고 쾌적한 분위기로, 한쪽에는 넓게 트여있는 창이 있습니다. 화창한 날, 부암동 뷰를 바라보며 여유롭게 햄버거를 즐기고 싶다면 이곳이 최적입니다. \n특히 레이지버거클럽은 입맛에 맞게 햄버거를 만들어 먹을 수 있다는 장점이 있습니다. 고기의 중량을 선택할 수 있고, 패티, 치즈, 베이컨 등의 토핑을 추가할 수 있기 때문에 맞춤식 햄버거를 즐길 수 있습니다.', 37.592529, 126.965291, '', '지하철 3호선 경복궁역 3번 출구, 77022, 7212, 1020 버스 탑승 후 부암동 주민센터에서 하차', '', '매일', ' https://www.instagram.com/lazyburgerclub/', '음식점', '자세한 사항은 인스타그램 @lazyburgerclub을 참고하시길 바랍니다.', '매일 : 11:00 - 20:00\n브레이크타임: 15:00 - 16:30\n라스트오더: 19:30', '0507-1329-2547', ''),
	(866, '그문화다방', '04074  서울 마포구 와우산로3길 49 (당인동)', 'images/그문화다방_866.jpg', '뱅쇼가 아주 맛있는 상수동 카페\n\n상수동 그문화다방은 정성스러운 시음을 통해 고집스레 선별한 200여종 와인과 잘 어울리는 음식이 있어 가게를 찾는 사람들에게 특별한 날을 더욱 의미있게 만들어줍니다. 와인의 특징을 설명하며 정성껏 안내해 주기 때문에 와인 초보자도 몇 번 방문하면 어느덧 와인을 더욱 재미있게 즐길 수 있습니다. 주간에는 다방으로 야간에는 싸롱으로 운영되기 때문에 다양한 홍대 예술가의 아지트로 사랑받고 있습니다. 조용한 분위기의 와인바로, 데이트 장소로도 좋습니다.', 37.545491, 126.920313, '', '지하철 6호선 상수역 4번 출구, 404m', '', '', ' https://blog.naver.com/gmh774 ', '음식점', 'https://blog.naver.com/gmh774 블로그에서 소식을 확인해보세요', '월요일,수요일~금요일 12:00~01:00\n토요일 14:00~01:00 / 일요일 14:00~22:30', '0507-1306-1429', '화요일 정기휴무'),
	(867, '손가네닭한마리', '03115  서울 종로구 종로66가길 10 (숭인동, 유림빌딩)', 'images/손가네닭한마리_867.jpg', '진한 국물이 맛있는 숭인동 골목 닭한마리집\n\n손가네닭한마리는 서울 전통 요리인 닭한마리를 전문으로 하는 식당입니다. 닭과 채소를 끓인 국물에 양념을 찍어 먹으며, 취향에 따라 담백하게 먹거나, 매콤하게 먹을 수 있습니다. 남은 국물에 칼국수나 죽을 추가해 즐길 수 있습니다. 마늘이 듬뿍 들어간 진한 국물이 특징입니다. 창업주는 청계천에서 백반집을 운영하다가 단골의 권유로 닭한마리를 추가한 후 단일 메뉴 가게로 발전시켰습니다. 가게 내부는 아늑하고, 다국어 메뉴판과 외국인 식사법 안내가 있어 관광객들에게 적합합니다.', 37.573693, 127.021385, '1만원대', '지하철 1/2/우이신설선 신설동역 11번 출구, 392m', '닭한마리 (2인 이상 주문 가능)', '', '', '음식점', '', '월요일~금요일 12:00~22:00\n토요일 12:00~21:00\n(15:00~17:00 브레이크타임)', '0507-1345-9065', '일요일'),
	(868, '북촌막국수', '03049  서울 종로구 삼청로 141 (삼청동)', 'images/북촌막국수_868.png', '대한민국 강원도 봉평 메밀 100%로 직접 뽑아 만든 막국수\n\n100% 순메밀로 만들어 쫄깃하고 건강한 맛의 막국수를 맛볼 수 있는 곳입니다. 막국수뿐만 아니라 칼국수, 메밀 굴림 만두 등도 별미입니다.', 37.587916, 126.981501, '1만원대', '지하철 3호선 안국역 1번 출구, 1.5km', '들기름 막국수, 비빔막국수, 물막국수 13,000원\n순메밀 칼국수 14,000원\n메밀 굴림 만두 6,000원', '', '', '음식점', '', '10:00~20:30 (라스트오더 20:00)', '02-737-4111', ''),
	(869, '메일룸', '04576  서울 중구 퇴계로83길 10-7 (황학동)', 'images/메일룸_869.jpg', '색다른 경험을 해볼 수 있는 메일함 컨셉의 에스프레소 바, 메일룸\n\n신당동 시장 골목에 위치한 \'메일룸\'은 이색적인 경험을 해볼 수 있는 메일함 컨셉의 에스프레소 바입니다. 이곳에서는 원하는 메뉴를 종이에 적어내면, 번호가 적힌 메일함 열쇠를 건네줍니다. 메뉴가 준비되면, 해당 번호가 적힌 메일함을 열어 편지를 받듯이 메뉴를 받아볼 수 있습니다. 이 특별한 주문방식은 편지함을 열 때의 설레는 마음을 커피로 전달드리고자 고안된 방식이라고 합니다. 이처럼 메일룸에서는 커피를 마시고 편지를 쓰며, 누구나 각자의 방식대로 설레는 시간을 보낼 수 있습니다. 또한, 메일룸은 빈티지한 인테리어와 분위기로 데이트 코스로도 인기가 많은 핫플레이스. 대표메뉴는 에스프레소 커피와 에스프레소가 들어간 칵테일이며, 커피와 잘 어울리는 다양한 디저트들도 준비되어있습니다.', 37.566250, 127.018890, '', '지하철 2/ 6호선 신당역 1번 출구, 77m', '', '매일', ' https://www.instagram.com/mailroom_sindang/', '카페, 디저트', '테이크아웃 이용 시 메뉴판 금액에서 1,000원씩 할인되는 점 참고 부탁드립니다.\n매장 건물에 별도의 주차공간이 없어 주변 공영주차장이나 유료주차장을 이융해주시길 바랍니다.', '평일 12:00 ~ 00:00, 주말 11:00 ~ 00:00 (라스트 오더 23:30)', '0507-1431-3124', ''),
	(870, '커피한약방 혜화점', '03085  서울 종로구 동숭2길 9 (동숭동)', 'images/커피한약방_혜화점_870.png', '빈티지한 분위기를 즐길 수 있는 핸드드립 커피 맛집\n\n커피한약방 혜화점은 커피한약방이 을지로를 벗어나 새롭게 문을 연 공간으로 다양한 원두를 선보이며 핸드드립 방식의 필터 커피를 제공합니다. 원두마다 특성이 보기 편하게 정리되어 있어 취향에 맞는 원두를 선택해 커피를 맛볼 수 있습니다. 커피 외에도 밀크티와 에이드 등 음료가 훌륭한 맛을 자랑합니다. 또한 혜민당에서 만든 디저트와 빵을 함께 맛볼 수 있는데 계절별로 특색 있는 재료를 사용한 디저트가 별미입니다. 앤틱한 가구들과 나무 소재의 가구들로 꾸며진 내부 인테리어가 카페의 멋스러운 분위기를 더욱 살려주고 내부에 위치한 큰 어항이 커피한약방 혜화점의 시그니처 포토스팟으로 자리 잡고 있습니다.', 37.580889, 127.004817, '', '지하철 4호선 혜화역 2번 출구, 297m', '', '월요일~일요일', ' https://smartstore.naver.com/coffeehanyakbang', '카페, 디저트', '', '일요일~목요일 12:00~21:00\n금요일~토요일 12:00~22:00\n(영업종료 30분 전 라스트오더)', '070-4200-4242', ''),
	(871, '마복림 할머니집', '04611  서울 중구 다산로35길 5 (신당동)', 'images/마복림_할머니집_871.jpg', '며느리도 모르는 맛, 신당동 떡볶이의 원조\n\n마복림 할머니집은 1953년에 개업한 신당동 떡볶이 골목의 시작점으로, 떡볶이를 단순한 간식을 넘어서 요리로 자리매김하게 만든 전설적인 장소입니다. 마복림 사장이 개발한 비법은 고추장과 춘장을 섞은 소스로, 달콤한 맛이 특징입니다. 테이블에서 직접 떡볶이를 끓여 먹는것이 매력 포인트이며, 다양한 사리를 추가해 나만의 맞춤형 떡볶이를 즐길 수 있습니다.  마복림 사장은 타계 5년 전 비법을 며느리에게 전수해, 지금도 그 맛을 이어가고 있습니다.', 37.563221, 127.015116, '', '지하철 2/ 6호선 신당역 7번 출구, 232m', '즉석떡볶이 2인 세트, 3인 세트, 4인 세트 (2인 이상 주문 가능)', '매일', '', '', '', '09:00~22:50', '02-2232-8930', '매달 2·4번째 월요일 휴무'),
	(872, '쌍문동커피', '01454  서울 도봉구 도봉로116길 5 (창동)', 'images/쌍문동커피_872.jpg', '40년 된 주택을 개조해 지어진 쌍문동의 카페.\n\n아지트 느낌 물씬, 아늑한 산장에 온 듯 감성적인 쌍문동의 커피 맛집 \'쌍문동 커피\'. 레트로한 소품과 사장님의 작명 센스가 가미된 특별한 커피, 디저트들을 만나봐요!', 37.648206, 127.035708, '', '지하철 4호선 쌍문역 2번 출구, 218m', '', '', '', '카페, 디저트', '', '평일 10:00~23:00, 주말 11:00~23:00', '070-7786-1509', ''),
	(873, '봉이밥 인사동점', '03132  서울 종로구 삼일대로 446-34 (낙원동, 미르빌딩)  1층 봉이밥 인사동점', 'images/봉이밥_인사동점_873.jpg', '한식과 전통적인 내부 인테리어를 함께 즐길 수 있는 곳\n\n봉이밥은 입에서 입으로 전해지는 맛을 선보이는 한식 전문 구전음식점입니다. 빠르게 변화하는 현대 외식 문화 속에서, 봉이밥은 한국적이고 대중적이면서도 특별한 맛과 합리적인 가격으로 우리세대, 다음세대가 사랑할 수 있는 음식을 만드는 것을 목표로 합니다.\n\n\n한식 전문점 답게, 한국의 전통적인 미를 한껏 살린 인테리어가 이곳의 특징입니다. 또한 영문 메뉴판도 제공되기 때문에, 한국인 뿐만 아니라 외국인들도 이곳에서 한국의 맛과 멋을 함께 느껴볼 수 있습니다.', 37.574994, 126.988076, '1만원대', '지하철 3호선 안국역 4번 출구, 321m', '', '매일', ' https://bong2bab.com/', '음식점', '테이블 오더의 영어 번역본 제공\n인스타그램 : @bong_ee_bab', '매일 11:00 ~ 21:00 (브레이크타임 15:00 ~ 17:00)', '0507-1454-0331', ''),
	(874, '이프차 ifcha', '04337  서울 용산구 신흥로 95-21 (용산동2가)  2층', 'images/이프차_ifcha_874.jpg', '해방촌에 위치한 현대식 찻집 이프차\n\n이프차(ifcha)는 남산 아래 해방촌에 위치한 현대식 찻집이다. 차 산업 전공자와 F&B 메뉴 개발자가 만나 차의 다양한 매력을 알리기 위해 시작된 곳이다.\n이프차에서 취급하는 차의 품질은 엄선한 과정을 통해 선별한 다음 소개되고있다. 판매되고 있는 음료와 디저트 또한 모두 자체 개발된 메뉴이다. 시그니처 메뉴는 밀크티로, 당일 제조를 원칙으로 만들어지고 있다. 이외에도 빙수와 차, 커피, 디저트 등 다양한 메뉴가 준비되어있으니 현대와 전통이 어우러진 경험을 원한다면 이곳을 방문하길 바란다.', 37.545055, 126.985023, '', '6호선 녹사평역 2번 출구에서 용산02버스를 타고 해방촌 오거리 하차', '', '당분간 휴업', ' https://smartstore.naver.com/ifcha', '', '자세한 사항은 인스타그램 @ifchq를 참고하시길 바랍니다.', '당분간 휴업', '0507-1440-2826', '당분간 휴업'),
	(875, '법원', '03058  서울 종로구 창덕궁1길 33 (계동)', 'images/법원_875.jpg', '독특한 위스키를 맛볼 수 있는 창덕궁 근처 아늑한 술집\n\n법원은 헌법 재판소 근처에 위치한 위스키를 주로 판매하는 가게입니다. 가게는 바가 없는 바 형태로 되어있으며, 다다미방 구조로 나뉘어 있습니다. 방문하는 손님들에게 새로운 위스키 경험을 선사할 수 있도록 공간과 메뉴를 면밀하게 준비하는 이 곳은, 위스키 이외에도 와인, 맥주, 칵테일 등의 다양한 주류를 구비하고 있습니다. 가게의 대표메뉴인 딸기 위스키, 쑥 위스키, 목밀 위스키는 직접 인퓨징하여 만들었기 때문에 위스키를 처음 접하는 사람들도 부담없이 즐길 수 있는 대표메뉴입니다. 이 밖에도 떡과 약과, 체리치즈케이크, 바질페스토 파르페 등 위스키와 잘 어울릴 음식을 심사숙고하여 만들어 손님들의 눈과 입을 즐겁에 만드는 장소입니다.', 37.579272, 126.987364, '', '지하철 3호선 안국역 3번 출구, 320m', '', '월요일~일요일', ' https://www.instagram.com/bourbon.bar/ ', '술집, 바', '주차 불가\n금요일, 주말, 공휴일, 공휴일 전날 예약 불가', '월~목 16:00~01:00\n금~일 14:00 ~ 01:00', '02-745-1933', ''),
	(876, '해방촌닭', '04337  서울 용산구 신흥로 97-5 (용산동2가)  1층', 'images/해방촌닭_876.jpg', '해방촌 오거리 신흥시장 안에 위치한 해방촌닭\n\n해방촌 신흥시장에 위치한 해방촌닭은 기존의 기름에 튀긴 짜고, 맵고, 달고, 시고, 자극적인 치킨과는 달리 신선한 국내산 닭 배 속에 금산 인삼, 대추, 찹쌀을 넣어 1시간 30분 동안 기름을 쫙 뺀 건강하고 맛있는 슬로우 치킨입니다. 전기구이 한방 통닭은 너무 심심하다고 생각 할 수 있겠지만 직접 개발한 겨자 소스와 요거트 소스로 부드러운 닭의 풍미를 더합니다. 또한 매주 정성 들여 직접 담그는 해방통닭만의 대파 김치는 닭 속 찹살밥과 찰떡 궁합입니다.', 37.545228, 126.984882, '', '지하철 4호선 숙대입구역 5번 출구, 용산 02 버스 탑승, 해방촌오거리 정류장 하차', '', '월-일', ' https://www.instagram.com/haebangchondak ', '음식점', '자세한 사항은 인스타그램을 참고해주세요.', '월-금 16:00-23:00\n토-일 13:00-23:00', '0507-1399-2037', ''),
	(877, '통영굴밥', '03170  서울 종로구 사직로 130 (적선동, 적선현대빌딩) 지하 1층', 'images/통영굴밥_877.png', '서울에서 맛볼 수 있는 통영 굴의 신선함, 통영굴밥\n\n경복궁역 지하와 적선 현대빌딩 지하가 연결되는 아케이드에 위치한 통영굴밥은 근처 회사인들에게도 소문이 자자한 맛집입니다. 대표메뉴로는 통영굴밥과 매생이 굴국밥, 굴정식, 굴전 등이 있습니다. 이외에도 쭈구미, 꼬막, 전복 등 해산물이 들어간 다양한 요리들을 선보이고 있습니다. 신선한 굴과 자극적이지 않고 담백한 맛에 사람들은 반복해서 이곳을 찾습니다. 통영에서 직접 공수해서 가져온 굴을 사용하기 때문에, 서울에선 맛보지 못하는 통영의 신선함을 대신해서 느낄 수 있습니다. 또한 급속 냉동을 통해 신선도를 유지하여 겨울뿐만 아니라 여름에도 싱싱한 굴을 맛볼 수 있는 곳입니다.', 37.575368, 126.973322, '1만원대', '지하철 3호선 경복궁역 6번 출구, 10m', '', '월요일 ~ 토요일', '', '음식점', '', '월요일 ~ 금요일 11:00~20:30 (브레이크타임 15:00~17:00)\n토요일 14:00', '02-736-0559', '매주 일요일'),
	(878, '타이티 플래그십스토어', '06325  서울 강남구 선릉로18길 4 (개포동) 1층', 'images/타이티_플래그십스토어_878.jpg', '대익 보이차로 만든 다양한 메뉴를 즐길 수 있는 티카페.\n\n타이티 플래그십 스토어는 넓고 편안한 매장에서 대익의 다양한 보이차를 개완과 자사호 등의 차 도구로 직접 우려 마셔볼 수 있는 곳입니다. 또한 시판 중인 대익차와 다구도 구매 가능합니다. 차를 우리는 방법을 전혀 몰라도 카페의 직원들이 우림법을 설명해주어, 직원들의 설명에 따라 차근차근 따라해보면 누구라도 보이차를 쉽게 즐길 수 있습니다. 차우림 메뉴 외에도 타이티 카페 전용 에스프레소 머신을 통해, 차를 압착 추출하는 보이차 킹푸레소와 티에이드, 티스무디 등의 베리이션 음료, 밀크티 빙수와 같은 다양한 한국식 카페 디저트도 함께 준비되어 있습니다.', 37.483965, 127.059552, '', '지하철 수인분당선 구룡역 5번 출구, 340m', '', '매일', ' http://taetea.co.kr/board/index.php?db=basic_3&no=572&mari_mode=view%40view', '카페, 디저트', '카페 이용에 관한 최신 정보는 매장 유선 전화 또는 인스타그램 @taetea_café을 참고해주시길 바랍니다.', '매일 10:00 - 20:00', '02-3463-7542', ''),
	(879, '무위낙원', '03133  서울 종로구 수표로28길 17-25 (익선동)', 'images/무위낙원_879.jpg', '브런치 먹기 좋은 익선동 루프탑 한옥카페\n\n익선동에 위치한 브런치하기 좋은 루프탑 한옥카페로 계절에 맞는 재료로 만든 다양한 브런치 메뉴와 함께 곁들일 수 있는 와인들이 준비되어 있t습니다. 100년된 고택의 기와와 덴마크 빈티지가구와 페브릭 등으로 꾸며진 루프탑 공간도 이용가능합니다. 내부에도 다양한 좌석들이 준비되어 있어 원하는 분위기에 맞게 이용이 가능합니다.', 37.573450, 126.989459, '', '지하철 1/3/5호선 종로3가역 4번 출구, 124m', '', '월 ~ 일', ' https://app.catchtable.co.kr/ct/shop/mooweenakwon', '음식점', '반려동물 동반가능, 루프탑 이용은 네이버 예약을 이용해주세요.\n(https://m.booking.naver.com/booking/6/bizes/695467/items/4429887?area=plt)', '월~토 11:30 ~ 23:00 (브레이크 타임 15:00~17:00 / 라스트오더 14:30)\n일요일 11:30 ~ 16:00 (라스트오더 15:00)', '0507-1360-0670', ''),
	(880, 'aff seoul', '04550  서울 중구 수표로 42-21 (저동2가)  4층, 5층', 'images/aff_seoul_880.jpg', 'Asian Funky Flavor 의 약자.아시안 로컬 베이스의 dining & Wine Bar\n\naff seoul 엪 서울은 Asian Funky Flavor의 약자로, 아시안 로컬 베이스의 dining & Wine Bar입니다. 내추럴 와인을 즐기고 싶을 때 찾기 좋은 을지로에 위치한 레스토랑입니다. 계절에 맞는 다양한 음식과 함께 와인을 즐길 수 있습니다. 3층과 4층 루프탑으로 이루어져 있습니다. 와인을 잘 알지 못해도 취향에 맞게 추천해 주는 소믈리에도 계시니 걱정하지 않아도 됩니다. 특히 aff seoul에서 맛볼 수 있는 그린 카레가 일품입니다.', 37.565042, 126.990455, '', '지하철 2/3호선 을지로3가역 11번 출구, 168m', '', '', ' https://www.instagram.com/aff_seoul', '술집, 바', '자세한 사항은 인스타그램 계정을 참고해주세요.', '화 ~ 금 17:30 ~ 23:50 / 토 17:00 ~ 23:50', '0507-1345-5032', '일,월'),
	(881, '하우스오브바이닐 연희점', '03707  서울 서대문구 연희맛로 17-43 (연희동)', 'images/하우스오브바이닐_연희점_881.png', '연희동의 LP카페, <하우스 오브 바이닐 연희점>\n\n눈길을 끄는 하얀 세련된 건물, 음악 소리를 따라 들어가면 공간감 있는 내부가 우리를 반겨줍니다. 하얀 벽으로 이루어진 공간에 잘 배치된 우드, 블랙 색상의 가구와 조명, 모던하지만 편안한 분위기를 자아냅니다. 밖을 비추는 큰 창과, 2층과 이어져 있는 1층의 높은 층고는 찾는이로 하여금 숨통이 트이는, 개방감을 느끼게 합니다. 매장 구석구석까지 닿는 음악은 LP 플레이어로 직접 튼 것으로, LP의 특성인 약간의 잡음소리와 함께 이 곳의 감성을 더욱 증폭시킵니다. 머랭 위에 크림이 올라간 파블로바와, 취향에 맞게 고를 수 있는 다양한 원두의 필터커피와 함께 이 공간의 아름다운 분위기를 즐겨보세요.', 37.566816, 126.928654, '', '지하철 2호선 / 공항철도 / 경의중앙선 홍대입구역 3번 출구, 1.1km', '', '매일', '', '카페, 디저트', '노키즈존', '11:00~22:00', '0507-1459-9557', ''),
	(882, '[백년가게] 초롱이고모부대찌개', '05264  서울 강동구 상암로11길 4 (암사동)   1층', 'images/[백년가게]_초롱이고모부대찌개_882.jpg', '고랭지 배추와 한우사골 국물 배이스에 미나리와 숙주가 포인트인 부대찌개 집\n\n초롱이고모 부대찌개는 1990년 개업한 이래 30여 년간 신뢰를 쌓아 온 전통의 부대찌개 전문점입니다. 최상의 재료와 조리법으로 독창적인 맛을 이어오고 있습니다. \n\n직접 제조하는 김치는 고랭지 배추를 이용해 모두 국산 재료로 만들고 저온으로 오랫동안 숙성해 사용합니다. 여기에 표고버섯을 직접 건조하여 사용하여 감칠맛을 더하고, 100% 한우사골과 인삼으로 우려낸 육수로 깊은 맛을 냅니다. 최상의 햄과 소시지를 다양하게 사용하고 미나리 숙주 등 다른 부대찌개와 차별화된 재료로 시원하고 깔끔한 맛이 탁월합니다. \n\n\n\n\n‘오래된 맛집’, ‘단골이 인정하는 맛집’으로 친절하고 정감 있는 식당으로 인지도를 높여가는 것. 그리고 맛의 일정함을 유지하기 위해 노력하고, 부대찌개라는 단순한 메뉴가 아닌 다양한 사람들이 찾고 즐길 수 있는 색깔 있는 전문성 있는 음식으로 더 발전하기 위해 많은 노력을 지속하고 있습니다.', 37.549913, 127.128819, '1만원대', '지하철 8호선 암사역 1번 출구, 142m', '부대전골, 부대찌개, 햄찜', '', '', '음식점', '', '11:00~15:00, 16:00~21:00', '02-442-3546', '화요일 정기휴무'),
	(883, 'NOR', '06047  서울 강남구 도산대로 220 (논현동, 엠포리아 빌딩) 지하 1층', 'images/NOR_883.jpg', 'Immersive dining experience! 특별한 미식여행을 만들기 위해 모든 감각을 자극하는 미디어아트와 함께하는 크랩다이닝입니다.\n\n서울에 위치한 NOR은 혁신적인 요리 경험을 제공하는 첫 번째 레스토랑으로 미디어아트 프로젝션 매핑과 크랩 다이닝의 매력이 조화롭게 어우러진 곳입니다. 이 곳에서는 아침 해가 떠오를 때부터 은하수의 창조까지 초월적인 항해를 할 수 있는 독특한 \'LIFE\'컨셉으로 고객들을 맞이합니다. 색다른 미식여행 (Gastronomic Journey)을 원하시는 분들에게 추천드립니다.', 37.520274, 127.031119, '', '7호선 학동역 8번 출구에서 약 882m (도보 13분)', '크랩코스요리 280,000원', '', ' https://nor.seoul.kr/ ', '', '', '월요일~금요일 18:30~22:00\n토요일~일요일 12:00~22:00 (15:00~18:00 브레이크 타임)', '010-2371-6215', ''),
	(884, '블그레', '06028  서울 강남구 논현로175길 101-4 (신사동) 4', 'images/블그레_884.png', '현대적인 방식으로 재해석한 한식 & 와인바\n\n블그레(Blgre)는 빛의 3원색인 블루(Blue), 그린(Green), 레드(Red)의 첫 글자를 조합하여 만든 이름입니다. 빛의 3원색을 교집합인 화이트가 가진 의미처럼 열린 마음으로 한국식 퀴진을 새롭게 표현한다는 의미를 담았습니다. 화이트 톤의 실내공간은 인테리어에 계절감을 나타내는 미디어아트를 전시해 역동성을 부여했습니다. 타파스 형태로 제공되는 요리는 옛 문헌 속 레시피를 토대로 하되, 현대적인 터치를 더해 재해석했습니다. 파주 장단콩으로 만든 간장과 된장, 김치 등 발효식재료를 활용하고, 식재로 본연의 풍미를 살리는 요리를 합니다. 다양한 한국술과 와인이 준비되어 있어 한식타파스와 페어링이 가능합니다.', 37.522465, 127.021082, '', '지하철 3호선/ 신분당선 신사역 8번 출구, 792m', '', '', ' https://www.instagram.com/lounge_by_blgre/', '음식점', '영어 해설 가능 / 영어 메뉴판 보유', '10:00~22:00', '02-547-7940', ''),
	(886, '자연도소금빵in성수', '04781  서울 성동구 연무장길 56-1 (성수동2가) , 1층', 'images/자연도소금빵in성수_886.jpg', '하루 7천개씩 판매하는 풍부한 버터 풍미가 가득한 소금빵집\n\n100가지의 재료 테스트와 1천번의 구움 테스트를 마쳐 3가지의 특별한 재료와 기다림만을 담은 소금빵을 만나볼 수 있습니다. 단일 메뉴로 소금빵만 판매하며, 웨이팅이 있을 수 있으나 테이크 아웃하는 방식입니다. 하루에 6번만 갓 구워 판매하니 빵 나오는 시간을 참고하여 방문해보세요. (오전9:00/오후 12:30/오후2:00/오후3:30/오후5:00/오후6:30)', 37.542305, 127.055466, '', '지하철 2호선 성수역 3번출구, 285m', '', '', ' https://www.instagram.com/saltbread.in.seaside', '', '', '매일 9:00-22:00', '02-463-2245', ''),
	(887, '북해빙수', '04569  서울 중구 다산로47길 28 (흥인동)', 'images/북해빙수_887.jpg', '신당동의 눈꽃빙수 맛집, 북해빙수\n\n북해빙수는 신당동에 위치한 카페로, 고운 입자의 눈꽃빙수가 특히 유명한 곳압니다. 대표메뉴는 눈꽃 우유빙수이며 이외에도 눈꽃 딸기빙수, 눈꽃 오레오빙수 등 다양한 빙수들이 준비되어있다. 빙수는 모두 1인용으로 제공되어 혼자 방문하기에도 좋고, 여러 명이서 다양한 맛을 시켜먹기에도 좋다. 팥이 따로 나오기 때문에, 조금씩 덜어 빙수와 함께 먹으면 고소하면서도 달달한 맛을 느낄 수 있다. 금요일과 토요일을 제외하고는 늦은 새벽까지 운영하므로, 심야시간에도 빙수를 즐길 수 있는 곳이다. 빙수 뿐만 아니라, 커피와 다양한 음료, 디저트도 판매하고 있다. 엔틱한 분위기의 매장은 넓고 쾌적하기 때문에 무더운 여름 밤 더위를 식히러 방문하기에 좋다.', 37.566691, 127.014489, '', '지하철 2 / 6호선 신당역 10번 출구, 177m', '', '일요일 ~ 금요일', '', '카페, 디저트', '', '일요일~목요일 00:00~24:00\n금요일 00:00~22:00', '02-2235-1005', '토요일'),
	(888, '공간', '03061  서울 종로구 율곡로3길 66-4 (안국동)', 'images/공간_888.jpg', '북촌에 위치한 아늑한 공간의 바\n\n북촌에 위치한 바(Bar)로 다양한 콘셉트의 칵테일들을 직접 만들어 선보입니다. 가게 내부에 중정이 있어 낮, 밤 상관없이 공간의 다채로운 매력을 느낄 수 있고, 또한 종종 열리는 게스트바텐딩으로 세계 각지에서 유명한 바텐더들의 칵테일을 즐길 수 있습니다. 안국역의 한적한 골목길에 매장이 위치해 있으며, 한옥을 현대적으로 개조하여 독특한 분위기의 칵테일 바입니다. 매장 컨셉에 맞게 한국스러운 이름의 시그니처 칵테일이 준비되어 있습니다. 예약 및 단체 이용이 가능하며 반려동물 동반 가능합니다.', 37.578539, 126.982349, '', '지하철 3호선 안국역 1번 출구, 471m', '', '화 ~ 일', ' https://www.instagram.com/gong_gan_anguk', '술집, 바', '', '화~일 16:00 ~ 02:00 (라스트오더 01:30)', '0507-1404-6444', '월요일'),
	(889, '이미 커피', '03992  서울 마포구 동교로25길 7 (동교동)', 'images/이미_커피_889.jpg', '맛있는 디저트와 그에 맞는 커피를 즐길 수 있는 카페\n\n페어링을 주제로 좋아하는 디저트를 고르면 그에 맞는 커피가 준비됩니다. 로스터는 커피의 맛과 향을 찾아내고 파티쉐는 커피에 어울리는 디저트를 만들며 바리스타가 디저트에 딱 맞는 커피를 준비합니다. 디저트는 보통 제철과일을 사용한 디저트가 준비되고 당도를 세심하게 체크하며 손님들이 최상의 상태를 맛볼 수 있도록 하는 것이 특징입니다. 청결하고 분위기 좋은 매장에서 디저트와 함께 페어링되는 커피를 맛보면 즐거움이 배가 되는 경험을 할 수 있습니다. 계절마다 달라지는 디저트를 맛보는 재미가 있어 찾아오다보면 단골이 되어버린 사람들이 아주 많습니다. 그만큼 인기가 많다보니 예약은 필수입니다.', 37.557475, 126.921916, '', '지하철 2호선/ 공항철도/ 경의중앙선 홍대입구역 1번 출구, 242m', '', '수요일 ~ 월요일', ' https://www.instagram.com/imi.coffee', '카페, 디저트', '자세한 사항은 인스타그램 (@imi.coffee)을 참고해주세요.', '12:00 ~ 21:00 (라스트오더 20:30)', '', '화요일'),
	(890, 'Titch', '03660  서울 서대문구 홍제천로 186 (연희동)  1층 titch', 'images/Titch_890.jpg', '홍제천에 위치한 샌드위치 카페, 티치 titch\n\nTitch는 홍제천에 위치한 조용한 분위기의 카페로, 샌드위치가 맛있기로 입소문이 난 곳이다. 대표 메뉴로는 양파 처트니 샌드위치가 있으며, 채식주의자들을 위한 비건 아보카도 샌드위치도 준비되어있다. 홍제천이 근처에 있어, 샌드위치를 포장해 피크닉을 즐기거나 식사 후 산책을 하기에도 좋은 곳이다.', 37.578564, 126.933549, '', '지하철 3호선 홍제역 4번 출구, 7713,7738 버스 탑승 후 서대문구청.서대문구의회 하차. titch까지 약 249m', '', '매일', ' https://www.instagram.com/shop.titch', '카페, 디저트', '자세한 사항은 인스타그램 @shop.titch 을 참고하시길 바랍니다.', '월요일~일요일 09:00~16:00\n(재료 소진 시 조기 마감합니다.)', '0507-1349-9573', ''),
	(891, '트래버틴', '04379  서울 용산구 한강대로7길 18-7 (한강로3가)', 'images/트래버틴_891.png', '용산 은행나무길의 힙한 카페 트래버틴\n\n카페 트래버틴은 용산 은행나무길에 위치한 분위기와 커피가 특징적인 카페입니다. 과거 주택의 모습에서 드러나는 고즈넉함과 리모델링으로 추가된 요소들의 세련됨이 공존하는 이 공간에서, 고객들은 테라스는 물론, 마당의 책상, 구석의 쇼파 등, 방문한 그 날의 무드에 따라 좌석 역시 선택하여 시간과 분위기를 취향대로 즐길 수 있습니다. 덴마크 스페셜티 브랜드, 라 카브라 커피의 한국 공식 파트너인만큼 수준급의 커피 메뉴들을 선보이나, 그중에서도 가장 눈에 띄는 것은 대표 메뉴인 핸드드립 필터커피입니다. 커피가 부담스러운 사람들을 위해 밀크티나 레몬 마테차와 같은 논-커피 메뉴 역시 준비되어있습니다.', 37.524875, 126.962078, '', '지하철 1호선/ 경의중앙선 용산역 1번 출구, 580m', '', '월요일~일요일', ' https://www.instagram.com/travertine_cafe/ ', '카페, 디저트', '#NAME?', '11:00~20:30 (라스트 오더 20:00)', '070-8862-6003', ''),
	(892, '칙바이칙 선릉역점', '06149  서울 강남구 선릉로 523 (역삼동)', 'images/칙바이칙_선릉역점_892.png', '역사적 장소에서 치킨, 그 이상의 맛.“치킨의 새로운 경험, 칙바이칙”\n\n칙바이칙은 매장에서 닭다리살 원육을 불에 직접 구운 직화 그릴드 치킨과 그릴드 킹프론으로 만든 버거, 라이스볼, 스페셜티치킨의 메뉴구성으로 보다 더 건강하고 다양한 치킨 메뉴를 합리적인 가격에 즐길 수 있는 치킨 패스트 캐주얼 브랜드입니다.', 37.506201, 127.047797, '', '지하철 2호선/수인분당선 선릉역 7번 출구, 170m', '치킨버거, 치킨라이스볼, 스페셜티치킨', '', ' https://www.chickbychick.com', '음식점', '식약처 인증 위생등급 매우우수 음식점', '매일 08:30~22:00', '02-6953-7827', ''),
	(893, '로우키', '04779  서울 성동구 뚝섬로1나길 5 (성수동1가, 헤이그라운드(HEYGROUND))', 'images/로우키_893.png', '서울을 기반으로 스페셜티 커피를 다루고 있는 로스터리\n\n로우키는 서울을 기반으로 스페셜티 커피를 다루고 있는 로스터리입니다. 2010년부터 로스팅과 원두납품을 하고 있으며 서울에서 총 4개의 매장을 운영하고 있습니다. 커피의 품질을 최우선으로 생각하고 필요한 양만큼 소량씩 로스팅하여 신선하고 맛이 가장 좋을 때 커피를 제공합니다. 또한 커피가 가지고 있는 맛과 스토리가 온전히 전해질 수 있도록 노력하고 있습니다. 매장을 들려 로우키가 제공하는 최상의 커피맛을 즐겨보세요. 또한 로우키에서는 간편하게 커피를 내려마실 수 있는 드립백, 커피를 내리는데 필요한 모든 커피용품들, 커피와 함께 즐기기 좋은 커피 간식들과 로우키만의 감성을 담고있는 의류 등 다양한 제품들을 선보이고 있습니다. 그리고 커피를 좋아하는 사람이라면 로우키에서 제공하는 원두 구독서비스를 신청해보는 것도 좋습니다.', 37.544472, 127.047779, '', '지하철 2호선 뚝섬역 6번 출구, 360m', '', '월요일~일요일', ' https://www.instagram.com/lowkey_coffee/', '카페, 디저트', '반려동물 동반가능', '월요일~일요일 09:00~18:00 (라스트오더 17:40)', '070-8824-2010', ''),
	(894, '퍼스트바이쓰리', '03660  서울 서대문구 홍제천로 206 (연희동)  1층', 'images/퍼스트바이쓰리_894.jpg', '홍제천 뷰의 감각적인 카페, 퍼스트바이쓰리\n\n퍼스트바이쓰리는 그래픽 디자인 스튜디오 TRIANGLE-STUDIO 의 첫 번째 공간으로, 카페 곳곳의 감각적인 소품과 인테리어가 눈에 띄는 곳입니다. 큰 통창으로 보이는 홍제천과 마을 풍경은 이곳의 평화롭고 아늑한 분위기를 한껏 고취시킵니다. 대표메뉴로는 아리라떼, 앙팡라떼, 판나코타 복숭아 우유푸딩 등이 있습니다.', 37.579383, 126.935684, '', '지하철 3호선 홍제역 4번 출구, 7713,7738 버스 탑승 후 동신병원 하차. 퍼스트바이쓰리까지 184m', '', '화요일 ~ 토요일', ' https://www.instagram.com/firstbythree', '카페, 디저트', '자세한 사항은 인스타그램 @firstbythree 을 참고하시길 바랍니다.', '화요일~토요일 10:00~19:00', '', '일요일 ~ 월요일'),
	(895, '관호 광화문점', '04519  서울 중구 세종대로 135-7 (태평로1가) 2층', 'images/관호_광화문점_895.png', '광화문 내에 위치한 양갈비 화로구이 전문점. 할랄(Halal)인증.\n\n양갈비 화로구이 전문점 관호 광화문점입니다. 최고급 프리미엄 양갈비(뉴질랜드, 호주산)을 사용하여 최상의 서비스를 제공하는 램스토랑입니다. 저희는 처음부터 끝까지 드시기 편하게 고기를 구워드리며 굽기 또한 손님의 입맛에 맞추어 구워드려 맛있게 드실 수 있습니다. 저희 관호는 할랄(halal) 인증을 받은 양고기를 사용하고 있으며 이슬람 교도 분들도 편하게 드실 수 있습니다. 또한 프라이빗한 룸이 완비되어 있어 단체로 방문해주셔도 조용한 공간을 제공해드릴 수 있습니다.', 37.568423, 126.976247, '3만원대', '지하철 5호선 광화문역 6번 출구, 226m', '양갈비 볏짚구이(할랄), 프랜치랙(할랄), 양갈비 전골(할랄)', '매일', ' https://app.catchtable.co.kr/ct/shop/kwanho_gwanghwa', '음식점', '', '평일 : 11:30~14:30, 16:30~22:30\n주말 및 공휴일 : 16:00~22:00', '02-735-5821', ''),
	(896, '코타티 해방촌', '04339  서울 용산구 신흥로12길 7 (용산동2가, 진흥푸르지오)', 'images/코타티_해방촌_896.jpg', '해방촌에 위치한 내추럴 젤라또 샵\n\n해방촌에 위치한 내추럴 젤라또 샵 코타티는 인공색소와 합성향료 없이 순수한 자연식품을 사용하여 만든 젤라또를 판매합니다. 각 메뉴 고유의 맛을 살려 만든 젤라또를 맛 볼 수 있으며 시기마다 새로운 맛의 젤라또를 만나 볼 수 있습니다. 반려견을 위한 아이스크림도 마련되어 있으며, 애견동반이 가능한 매장입니다. 컵이나 콘으로 포장이 불가하며, 2가지 맛 / 3가지 맛 / 4가지 맛으로 고를수 있습니다.  아이스크림 포장시 최대 이동 가능시간은 1시간 30분입니다.', 37.543475, 126.988172, '', '지하철 6호선 녹사평역 2번 출구, 888m', '', '', ' https://www.instagram.com/gelateria.cotati/', '카페, 디저트', '자세한 사항은 인스타그램을 참고해주세요.', '화-일 12:00-22:00', '070-4042-0228', '월요일'),
	(897, 'HHSS House', '03963  서울 마포구 월드컵로 113 (망원동)  3층 303호', 'images/HHSS_House_897.png', '망원동에 위치한 디자인 사무실 겸 카페\n\n망원동에 위치한 디자인 사무실 겸 카페 \'hhss house\'는 작업을 하다가 고개를 들면 나무가 눈앞에 있으면 좋겠다는 생각으로 꾸린 공간입니다. 내부에 들어서면 일렬로 늘어선 좌석들이 넓은 창문 밖으로 보이는 나무들을 바라보고 있고 내부를 가득 채우고 있는 인센스 스틱의 향이 마음을 편안하게 만들어줍니다. 판매하는 메뉴는 다양한 음료들과 귀여운 디저트들이 있고 저녁에는 주류도 판매하고 있습니다. 우연히 들어가기는 힘든 카페이지만 작업을 하기에도, 혼자 방문하기도 좋은 카페입니다. 큰 대로변이 아닌 건물 뒤쪽에 출입구가 있습니다. 3층으로 올라가 빨간색 테이프로 \'H\'가 쓰여있는 문을 찾아 열고 들어가는 순간 \'HHSS HOUSE\'가 선사하는 색다른 분위기를 느낄 수 있습니다.', 37.558422, 126.907614, '', '지하철 6호선 망원역 2번 출구, 370m (도보 5분)', '', '매일', ' https://www.instagram.com/hhss.house/', '카페, 디저트', '자세한 사항은 인스타그램을 참고해주세요.\n신발을 벗고 입장합니다.', '월요일~목요일 11:00~21:00\n금요일~일요일 11:00~22:00', '', ''),
	(898, '시노라 서촌점', '03047  서울 종로구 자하문로 116 (청운동)', 'images/시노라_서촌점_898.png', '서촌에 위치한 프렌치토스트가 맛있는 카페\n\n시노라 서촌은 경복궁 돌담길을 따라 서촌으로 쭉 걷다보면 나오는 카페로 서촌과 북촌으로 지점이 나누어져 있습니다. 내부에 들어가는 순간 느껴지는 고즈넉하고 아늑한 분위기는 시노라만의 감성을 즐기기에 안성맞춤입니다. 곳곳에 보이는 빈티지한 소품들이 눈을 즐겁게 해주고 잔잔하게 흘러나오는 LP소리와 조용한 분위기가 집중하기 좋은 환경을 만들어줍니다. 시노라의 드립커피를 먹기위해 찾는 사람도 있을 만큼 맛있는 커피를 맛볼 수 있고 브런치 메뉴들도 모두 훌륭한 맛을 자랑합니다. 특히 부드러운 프렌치토스트를 먹기위해 방문하는 사람들이 많은 장소입니다.', 37.586256, 126.970122, '', '지하철 3호선 경복궁역 3번 출구, 1.1km', '', '월요일~일요일', ' https://smartstore.naver.com/cafesinola', '카페, 디저트', '노키즈존', '월요일 ~ 일요일 09:00~19:00 (라스트오더 18:00)', '02-733-9249', ''),
	(899, '라운지 희움', '06127  서울 강남구 봉은사로18길 15-5 (역삼동)  201호', 'images/라운지_희움_899.jpg', '국내 최초 파인드링크 오마카세 카페 라운지 희움.\n\n카페 라운지 희움은 김지희 작가의 작품으로 출발한 국내 최초의 파인 드링크 오마카세 카페입니다. 예술작품을 제작하듯 성심을 담은 아트 브루 오마카세 코스를 통해 애호가분들을 위한 가치 있는 휴식을 제안합니다. 갤러리 뒤에서 작품을 제작하며 닫혀 있던 스튜디오의 작은 공간을 열어 작품 <트렁크 시리즈>의 모티브가 된 19세기 빈티지 유럽 기차 내부를 모던하게 구현하였습니다. 미지의 캔버스를 향한 여행의 공기를 맛과 향, 작품과 공간으로 담아낸 라운지 희움은 시즌 별 큐레이션을 통해 생동하며 특별한 경험을 선물합니다. 조금은 우아하게, 조금은 자유롭게 우리를 품어내는 라운지 희움의 시간이 무심히 흘러가는 일상의 감각을 잠시 깨우는 의미 있는 경험이 되길 바랍니다.', 37.505037, 127.030782, '', '지하철 9호선 언주역 8번 출구, 436m', '', '화요일 ~ 토요일', ' https://www.instagram.com/lounge_heeum', '카페, 디저트', '외국어(영어) 해설 가능', '화요일 ~ 토요일 12:00~20:00 ( 브래이크타임 17:30~18:30)', '0507-1432-1294', '월요일, 일요일'),
	(900, '이도림블로트커피X베이크', '03036  서울 종로구 자하문로 43 (통인동)', 'images/이도림블로트커피X베이크_900.jpg', '블루리본9년연속 획득한 인증된 서촌커피맛집.스페셜티 커피와 비건 베이커리,인스타 감성의 포토존까지 볼거리 가득한 디저트카페\n\n경복궁역 도보5분거에 위치한 서촌 커피맛집 이도림블로트커피X베이크.한국적인 스타일과 현대적 인테리어가 만나 내국인 뿐 아니라 외국인 관광객까지 입소문 난 카페입니다. 1~3층까지 쾌적한 환경과 루프탑에서 보이는 인왕산의 절경이 감성을 자극합니자. 오전8시에 오픈으로 간단한 아침식사를 해결하고 관광투어를 시작할 수 있습니다. 스페셜티 원두의 커피와 매일 아침 굽는 베이커리를 분위기 좋은 공간에서 함께 할 수 있습니다.', 37.579932, 126.971079, '1만원대', '지하철 3호선 경복궁역 2번출구, 400m', '', '월요일~일요일', ' https://www.leedorim.com', '카페, 디저트', '외국인 응대 가능', '08:00 ~ 20:00', '02-2135-9714', ''),
	(901, '연희동 라이라이 본점', '03703  서울 서대문구 연희로15길 27 (연희동), 1층', 'images/연희동_라이라이_본점_901.png', '연희동에 위치한 칠리가지가 맛있는 중식당\n\n연희동에 위치한 라이라이는 다양한 중국음식을 즐길 수 있는 중식당입니다. 특히 칠리가지가 대표메뉴로 유명한데 이는 다른 곳에서 맛볼 수 없는 바삭함과 마늘향을 풍기는 칠리소스의 궁합이 조화로워 라이라이를 방문하는 이들이라면 꼭 시켜야 하는 메뉴 중 하나입니다. 그뿐만 아니라 중식당에서 흔히 접할 수 있는 짜장면과 짬뽕부터 시작해 싼라탕, 라조기밥 등 다양한 중국음식들도 맛볼 수 있는 곳입니다. 깔끔하지만 풍미가 가득한 맛의 짬뽕과 부드럽고 고소한 탕수육도 꼭 먹어봐야 하는 메뉴입니다. 내부는 홀과 방으로 나누어져 있어 조용한 식사를 원한다면 예약을 통해 내부 이용이 가능합니다.', 37.568590, 126.930437, '2만원대', '지하철 2호선/ 경의중앙선/ 공항철도 홍대입구역 3번 출구, 1.4km', '', '목요일~화요일', '', '음식점', '예약, 포장, 배달, 단체이용 가능', '목요일~화요일 11:30~22:00 (라스트오더 21:20)', '0507-1311-3203', '수요일'),
	(902, '이오이 서울', '03060  서울 종로구 북촌로5길 3 (재동)', 'images/이오이_서울_902.jpg', '북촌 한옥마을에 자리잡은 한국적 해석을 담은 커피와 차, 그리고 디저트 페어링을 위한 공간.\n\n북촌에 위치한 디저트 카페로 전국 각지에서 유명한 재료를 사용한 디저트들을 맛볼 수 있습니다. 인테리어 또한 한국의 정서를 담은 단청색의 인테리어를 즐길 수 있습니다. 이오이 서울에 시그니처 메뉴라고 할 수 있는 기와휘낭시에는 한국적 식재료에서 영감을 받아 시기별로 새로운 맛을 선보이고 있습니다. 숙성된 보리 우유를 사용해 만든 이오이커피와 시즈널 티가 별미입니다.', 37.579178, 126.984698, '', '지하철 3호선 안국역 2번 출구, 271m', '', '월요일~일요일', ' https://www.instagram.com/eoeseoul', '카페, 디저트', '', '월요일~금요일 10:00~18:00\n토요일~일요일 11:00~19:00', '0507-1429-3620', ''),
	(903, '커피휘엘 (Coffee Fiel)', '06039  서울 강남구 논현로149길 62 (논현동)', 'images/커피휘엘_(Coffee_Fiel)_903.jpg', '예술적 공간에서 경험하는 특별한 커피! 서울 5대 로스터리 카페, 커피휘엘\n\n커피휘엘(Coffee Fiel)의 전 세계 유명 농장에서 직접 선별한 생두 직수입을 시작으로 국가대표 심사를 담당하고 있는 로스터가 직접 로스팅을 하여 고객들에게 진심이 담긴 커피를 제공합니다. 매 시즌 다양한 산지별로 맛볼 수 있는 스페셜티 커피 뿐만 아니라 파티쉐가 직접 만드는 디저트들을 즐기실 수 있습니다. 매장에서 최상급 원두 구매 또한 가능하며 매일매일 신선한 커피를 경험하실 수 있습니다. 유명 아티스트와 콜라보하여 커피휘엘에 오시는 고객분들이 이 공간에서만 느낄 수 있는 특별한 예술적 경험도 하실 수 있습니다. 이러한 예술적 공간 인테리어로 인기 쇼핑몰의 촬영 장소로도 유명합니다. 스페인어로 FIEL은 \'충실한, 성실한\'이라는 뜻으로 커피에 대한 충실함과 믿음을 표현하였으며 \'커피휘엘\' 이라는 이름에 부끄럽지 않은 커피를 제공하고자 하는 마음을 담았습니다.', 37.516985, 127.023587, '', '지하철 3호선 신사역 1번 출구, 302m', '', '월요일 ~ 일요일', ' https://www.coffeefiel.com/', '카페, 디저트', '외국어 응대 가능', '월요일~금요일 08:30 ~ 20:30\n토요일~일요일 11:00 ~ 20:00', '02-6215-8138', ''),
	(904, '호밀밭', '03777  서울 서대문구 신촌역로 43 (창천동)', 'images/호밀밭_904.jpg', '이대와 신촌 사이에 위치한 달콤한 팥빙수집\n\n이대와 신촌 사이 신촌 기차역 부근에서 10년이 넘도록 영업하고 있는 빙수 전문점입니다. 부드럽고 달콤한 우유 빙수에 직접 삶은 부드러운 팥과 떡을 곁들여 먹는게 매력입니다. 대표메뉴인 팥빙수와는 또 다른 매력을 느낄 수 있는 녹차빙수와 커피빙수도 준비되어 있습니다. 또한 전체적으로 저렴한 가격으로 다양한 메뉴를 즐길 수 있습니다. 커피와 티도 판매하고 있어 차가운 빙수를 먹고 속을 달래주기도 좋습니다. 벽돌과 나무로 인테리어 되어있어 따뜻하고 아늑한 분위기가 빙수의 맛을 더욱 살려줍니다. 또한 빙수 한 그릇 당 한 번씩 팥과 떡이 리필 되는 것도 이곳의 특징입니다.', 37.558948, 126.940636, '', '지하철 경의중앙선 신촌역 1번 출구, 230m', '', '월요일 ~ 일요일', '', '카페, 디저트', '', '월요일 ~ 일요일 12:00 ~ 22:00 (21:30 라스트오더)', '02-392-5345', ''),
	(905, '데케드', '03040  서울 종로구 자하문로7길 43 (누하동)', 'images/데케드_905.png', '서촌에서 유럽 스타일의 브런치와 디너를 맛볼 수 있는 공간\n\n서촌에서 유럽 스타일의 브런치와 디너를 맛볼 수 있는 공간으로 낮에는 데케드의 시그니처 팬케이크를 비롯한 다양한 브런치 메뉴를 즐길 수 있으며, 저녁에는 정성스럽게 준비한 제철 메뉴와 다양한 주류를 함께 곁들일 수 있는 공간입니다. 계절이 바뀜과 동시에 선보이는 시즌별 메뉴들은 계절의 변화를 느낄 수 있어 좋고 야외테이블도 준비되어 있어 좋은 날씨와 함께 메뉴를 맛보는 것이 데케드만의 매력입니다. 저녁에는 적당한 조도로 서촌의 밤 분위기도 마음껏 즐길 수 있습니다. 또한 직원들의 서비스와 친절함이 방문하는 이들의 기분도 좋게 만들어주는 장소입니다.', 37.579290, 126.969632, '', '지하철 3호선 경복궁역 3번 출구, 442m', '', '화요일~일요일', ' https://www.instagram.com/dekad.kafeteria/', '음식점', '콜키지 가능, 노키즈존, 반려동물 동반 가능', '화요일~일요일 11:30~23:00 (브레이크타임 15:00~17:00)', '0507-1350-5845', '월요일'),
	(906, '이석덕생면파스타', '03777  서울 서대문구 명물길 16 (창천동) 2층', 'images/이석덕생면파스타_906.png', '단 돈 삼천 구백 원으로 즐기는 이탈리아 정통 파스타\n\n이탈리아 요리 학교를 졸업한 이석덕 쉐프가 운영하는 식당으로 매일 생면을 직접 뽑아 전국으로 납품할 정도로 높은 퀄리티를 자랑합니다. 보통 파스타 가격은 만원이 넘지만 이곳의 화이트와인오일파스타 가격은 삼천 구백 원입니다. 저렴한 가격으로 이태리 정통 파스타를 맛보고 싶다면 이석덕생면파스타로 가보세요.', 37.557589, 126.937791, '', '지하철 2호선 신촌역 3번 출구, 270m', '화이트와인오일파스타 3,900원 / 감베리 비스큐로제 뇨끼 9,500원', '', ' https://www.instagram.com/lsd_pasta/', '음식점', '', '11:00~15:00, 17:00~22:00', '0507-1491-0905', ''),
	(907, '연희동 국화빵', '03707  서울 서대문구 연희맛로 17-21 (연희동)', 'images/연희동_국화빵_907.png', '두 자매가 운영하는 둥네 명물 붕어빵 테이크 아웃 카페\n\n연희동 국화빵은 연희동 골목길에서 두 자매가 운영하는 동네 명물 디저트 카페입니다.\n\n모든 반죽, 슈크림, 팥은 사장님이 직접 만들어 신선함과 높은 품질을 자랑하며, 계절마다 바뀌는 앙꼬로 국화빵의 색다른 매력을 선보입니다. \n슈크림, 얼그레이, 말차, 피넛버터 등 독특한 속재료가 더해진 국화빵은 익숙한 길거리 간식을 새로운 차원으로 끌어올렸습니다. 겨울철 대표 간식인 국화빵과 더불어 아이스크림도 판매하며 따뜻함과 차가움을 동시에 즐길 수 있는 매력적인 조화를 제공합니다. \n화려한 공간이나 패키지가 없음에도 줄 서서 먹는 이유는 바로 매번 새롭게 변신하는 메뉴와 엄선된 재료로 만든 높은 품질의 맛. 팝업 및 플리마켓 일정으로 인한 휴무가 있을 수 있어 방문 전 인스타그램 확인하세요.', 37.566632, 126.928807, '', '지하철 2호선 / 경의중앙선 / 공항철도 홍대입구역 3번 출구, 1.1km', '', '수 ~ 일', ' https://www.instagram.com/yhd_kukhwabbang', '카페, 디저트', '', '수 ~ 금 12:00 ~ 19:00\n토 ~ 일 13:00 ~ 18:00', '0507-1325-5391', '월,화'),
	(908, '아크페브 해방촌 akfebinhbc', '04339  서울 용산구 신흥로 62 (용산동2가)  1층', 'images/아크페브_해방촌_akfebinhbc_908.jpg', '음료와 디저트 모두 맛있는 해방촌에 자리잡은 아담한 카페\n\n해방촌에 위치한 아담한 카페 아크페브 해방촌은 해당 카페에서만 맛볼 수 있는 시그니처 음료와 다양한 여러 음료들, 디저트들로 손님들의 발걸음을 끌어당깁니다. 매력적인 인테리어와 소품들로 매장에서도 즐거운 시간을 보낼 수 있습니다. 아크페브 라떼와 메이플 시럽과 핑크솔트가 같이 나오는 아크페브만의 독특한 프렌치토스트가 매우 인기가 많습니다. 주차는 불가능.', 37.543839, 126.987413, '', '지하철 6호선 녹사평역 2번 출구, 928m', '', '화요일~일요일', ' https://www.instagram.com/akfebinhbc/', '카페, 디저트', '', '화요일~일요일 12:00~20:00 (19:15 라스트오더)', '0507-1480-9203', '월요일'),
	(909, '스태픽스', '03027  서울 종로구 사직로9길 22 (필운동) 102호', 'images/스태픽스_909.png', '커다란 나무와 푸른 정원이 있는 서촌의 카페\n\n서촌에 위치한 스태픽스는 자연적이고 아름다운 야외 테라스가 돋보이는 카페입니다. 높은 지대에 위치해있기 때문에 종로의 거리가 한 눈에 내려다보입니다. 정원에 있는 커다란 은행나무는 이곳을 방문하는 사람들의 인기 포토스팟. 가을이 되면 이곳의 노랗게 물든 은행나무를 떠올리며 다시 찾는 사람들이 많습니다. 풍미 깊은 커피와 달콤한 파운드케이크가 유명한 맛집으로, 가게 안에는 다양하고 아기자기한 소품들이 전시되어있습니다. 편집샵도 겸하고 있기 때문에 레트로한 소품들을 구경하며 눈이 즐거워지는 카페입니다. 또한 2층에는 분위기 있는 서점이 위치해있어, 카페를 방문할 때 같이 살펴보는 것을 추천합니다.', 37.577473, 126.967882, '', '지하철 3호선 경복궁역 1번 출구, 501m', '', '월요일~일요일', '', '카페, 디저트', '', '10:00~21:00', '010-2243-2712', '매월 마지막주 월요일 휴무'),
	(910, '어사출또 종로3가점', '03139  서울 종로구 돈화문로5길 24 (돈의동, 하늘빌딩)', 'images/어사출또_종로3가점_910.jpg', '가성비 좋게 해산물을 마음껏 맛볼 수 있는 곳.\n\n가성비 좋게 해산물을 마음껏 맛볼 수 있어 항상 인기 있는 장소입니다. 서울 곳곳에서 만날 수 있는 프랜차이즈이며, 특히 두툼하게 썰어 나오는 계절 회를 모둠으로 즐길 수 있는 메뉴가 있어 선택하기 어려운 여행객들에게 만족스러운 선택지를 제공합니다. 또한, 다양한 횟감이 들어간 물회는 새콤달콤한 맛이 일품입니다.', 37.570784, 126.990703, '', '지하철 1/3/5호선 종로3가역 1번 출구, 104m', '모듬회 중, 수제활어물회', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 22:00', '-6972', ''),
	(911, 'Ongoing', '03036  서울 종로구 자하문로 49-1 (통인동)', 'images/Ongoing_911.png', '서촌에 위치한 작지만 따뜻한 카페. 맛있는 커피가 기다리는 카페 Ongoing\n\n서촌 토박이인 사장님이 운영하는 카페 Ongoing은 전체적으로 부드러운 맛의 음료와 디저트를 맛볼 수 있다. 시그니처 음료인 \'온고잉라떼\'는 미숫가루와 아이스크림이 에스프레소와 배합하여 만들어졌다. 온고잉라떼 고소하고 풍미가 깊으며 많이 달지 않아 이색적인 커피를 경험하고 싶은 사람들에게 안성맞춤이다. 또 다른 대표메뉴인 군고구마 브륄레는 한 번이라도 먹어본 사람이라면 그 맛을 잊지 못해 다시 찾는다고 한다. 뿐만 아니라 바스크 치즈 케이크, 휘낭시에, 사브레쿠키 등 달콤한 디저트들은 온고잉의 커피와 최고의 조합이라고 할 수 있다. 내부 인테리어는 애정을 가득 담아 섬세하게 신경 쓴 흔적이 보인다. 창 밖의 아기자기한 서촌의 거리를 바라보며 커피 한 잔으로 여유로운 휴식시간을 보낼 수 있는 카페이다.', 37.580452, 126.970931, '', '3호선 경복궁역 2번 출구에서 약 472m (도보 6분)', '', '', ' https://www.instagram.com/cafe_ongoing', '', '-1인 1메뉴 주문 필수\n-평일 12:00~13:00 모든 음료 10% 할인\n-외부음식 취식 금지\n-매장이 만석일 경우, 이용시간 90분으로 제한', '주중 07:30~18:00\n주말 09:30~20:00', '0507-1341-6598', '매월 휴무일 상이. 인스타그램 공지 확인 요망'),
	(912, 'VIEW376', '135898    서울 강남구 압구정동 376-1', 'images/VIEW376_912.jpg', '탁트인 한강뷰와 분위기 있는 인테리어가 어우러진 압구정동에 위치한 한강 선상카페\n\n압구정로데오역에서 도보로 가능한 한강 선상카페입니다. 탁 트인 한강뷰로 도심속에서 힐링이 가능하며 루프탑이 있어 밤에는 멋진 야경을 감상하기에 제격입니다. 오전10시~오후4시까지 브런치 메뉴를 즐길 수 있으며 커피 및 다양한 음료와 몇가지 디저트가 준비되어 있습니다. 실내공간은 좌석 수가 많고 테이블간의 간격이 넓어 쾌적하며 조용히 대화를 나누기 좋습니다. 반려동물 동반이 가능하며 3층 루프탑 이외에 2층 테라스 좌석도 이용이 가능합니다.', 37.530043, 127.031335, '', '지하철 수인분당선 압구정로데오역, 1번출구, 465m', '', '', '', '', '주차가 불가하니 대중교통을 이용해 주세요', '매일 10:00~02:00', '0507-1387-7941', ''),
	(913, '피즈소셜클럽', '04546  서울 중구 을지로35길 51-4 (주교동), 4층', 'images/피즈소셜클럽_913.png', 'LP를 통해 재즈를 들을 수 있는 편안한 감성의 카페\n\n피즈소셜클럽은 을지로 방산시장 근처, 카페가 있을 것이라 상상하기 어려운 건물 4층에 위치해 있습니다. 높은 계단을 올라 갈 때 잘 찾아가고 있는지 의문이 들지만, 재즈 음악이 흘러나오기 시작하면 그 의문은 사라집니다. 투박한 철문을 열고 들어서면, 겉과는 다른 아늑한 분위기가 맞이합니다. LP로 트는 재즈와 함께 좋은 드립 커피를 즐길 수 있는 이곳은 예상치 못한 색다른 경험을 선사합니다. 음악과 커피가 완벽하게 어우러지는 을지로의 숨겨진 카페, 피즈소셜클럽입니다.', 37.569063, 127.001359, '1만원대', '지하철 1호선 종로5가역 7번 출구, 250m', '', '화요일~일요일', ' https://app.catchtable.co.kr/ct/shop/fizzsocialclub', '카페, 디저트', '노키즈존, 5인 이상 입장 불가', '11:30~20:00 (19:30 라스트오더)', '0507-1377-4315', '월요일'),
	(914, '퍼블릭가든', '03195  서울 종로구 청계천로 199 (예지동, 세마빌딩), 4층', 'images/퍼블릭가든_914.png', '아늑한 실내와 탁 트인 루프탑을 가진 서울 한복판의 브런치 카페\n\n서울 한가운데 숨어 있는 브런치 루프탑 카페, 퍼블릭 가든. 광장시장의 원단 매장 사이 골목을 따라 계단을 올라가면 햇살이 비추는 화사한 분위기의 브런치 카페가 우리를 맞이합니다. 샌드위치와 파스타는 물론, 아란치니와 로스트 치킨 등 수준 높은 맛있는 음식들이 준비되어 있으며, 좋은 맥주와 와인도 함께 즐길 수 있습니다. 카페 메뉴와 디저트도 다양하게 준비되어 있어, 도시에 지친 현대인들에게 한 틈의 여유를 제공하는 공간입니다. 오후 해가 저물어가는 시간에는 루프탑에서 예쁜 하늘을 더 잘 즐길 수 있으니 방문해 보세요', 37.569655, 126.999698, '', '지하철 2 / 5호선 을지로4가역 4번 출구, 300m', '', '월요일~일요일', ' https://www.instagram.com/publicgarden.seoul/', '카페, 디저트', '좌석에 콘센트 없음, 영유아 입장 불가', '월요일~일요일 10:00~19:30', '0507-1375-3402', ''),
	(915, '카페 트마리', '03134  서울 종로구 서순라길 107-1 (권농동)', 'images/카페_트마리_915.png', '종묘가 보이는 한옥 루프탑 카페이자 와인바\n\n카페 트마리는 종묘돌담길 옆 서순라길에 위치한 매력적인 한옥 카페이자 와인바입니다. 좁은 골목 사이에 숨겨진 이 곳은 조선시대의 한옥 공간을 리모델링한 곳으로 아늑하지만 독특한 분위기를 자아냅니다. 1층과 2층은 따뜻한 나무의 감성이 돋보이는 편안한 공간으로 꾸며져 있으며, 좁고 가파른 계단을 올라가면 탁 트인 종묘 돌담길의 뷰를 만끽할 수 있는 루프탑 공간이 기다리고 있습니다. 카페 트마리에서는 정성스럽게 내린 커피와 다양한 디저트를 맛볼 수 있을 뿐만 아니라, 맥주와 와인, 간단한 안주도 마련되어 있어 친구들, 연인 그리고 가족과의 여유로운 수다를 즐기기에 안성맞춤입니다. 감성적인 분위기 속에서 편안한 시간을 보내며, 특별한 순간을 만들어보세요.', 37.574966, 126.991578, '', '지하철 1 / 3 / 5호선 종로3가역 7번 출구, 300m', '', '월요일~일요일', ' https://www.instagram.com/teumari_cafe/', '카페, 디저트', '주차 불가', '월요일~토요일 : 11:00~23:00\n일요일 : 11:00~22:00', '0507-1368-6798', ''),
	(916, '필담', '04018  서울 마포구 동교로 55  2층', 'images/필담_916.png', '아늑한 분위기를 느낄 수 있는 레트로한 망원동 카페\n\n망원동에 위치한 필담은 내부에 들어섬과 동시에 아늑한 분위기를 느낄 수 있습니다. 또한 안쪽 벽면에 잔뜩 꽂혀져 있는 CD 들과 앤틱한 가구들, 레트로한 소품들로 가득 차 있어 방문하는 손님들에게 보다 편안한 분위기를 제공합니다. 창밖으로 보이는 푸릇한 나무들이 작업에 더 집중할 수 있게 도와주고 사장님이 직접 내리시는 핸드드립 커피향이 공간을 향기롭게 만들어주는 장소입니다. 여럿이 앉을 수 있는 좌석들과 홀로 자신만의 시간을 보낼 수 있는 좌석이 나누어져 있어 누구나 편안하게 방문하기 좋습니다. 커피뿐만 아니라 위스키, 칵테일과 같은 주류도 판매하고 있으니 저녁에 방문한다면 주류를 주문해 보세요.', 37.553330, 126.908382, '', '지하철 6호선 망원역 2번 출구, 514m', '', '', ' https://www.instagram.com/lounge_continuum/', '카페, 디저트', '자세한 사항은 인스타그램을 참고해주세요. (휴무공지 포함)', '매일 12:00 ~ 22:30', '', '인스타그램을 참고해주세요.'),
	(917, '카페 폭포', '03653  서울 서대문구 연희로 262-24 카페폭포', 'images/카페_폭포_917.jpg', '도심 속 폭포를 바라보며 힐링할 수 있는 서대문구에 위치한 카페\n\n‘서울형 수변감성도시 1호’로 홍제천 인공폭포 주변에 조성된 수변노천카페로 높이 25m, 폭 60m의 인공폭포를 감상하며 휴식할 수 있는 공간입니다. 서대문구는 지난 2023년 개장한 카페 폭포 수익금으로 청년희망드림기금을 조성하여 학생들의 꿈을 위해 장학금을 지원하고 있습니다. 외국인 관광객들도 많이 방문하는 곳으로 폭포수 떨어지는 소리를 들으며 차 한잔의 여유를 즐겨보시길 바랍니다.', 37.581295, 126.937020, '', '지하철 3호선 홍제역 3번출구, 1.2km', '', '', ' https://www.instagram.com/cafe.pokpo', '', '', '10:00-21:00', '02-3140-8302', ''),
	(918, '뽀빠이분식', '05504  서울 송파구 올림픽로35길 104 (신천동, 장미아파트)', 'images/뽀빠이분식_918.png', '잠실에 위치한 오래된 떡볶이 맛집\n\n1983년부터 운영되고 있는 잠실의 오래된 떡볶이 맛집으로, 현재는 장미상가의 터줏대감으로 자리잡고 있습니다. 이곳은 떡볶이보다 \'떡쫄라\'가 더 유명한데, 떡볶이에 쫄면과 라면사리가 추가된 메뉴입니다. 볶음밥도 별미로, 2인이 방문할 경우 떡쫄라와 볶음밥을 함께 주문하면 적당히 만족스러운 식사를 할 수 있습니다. 오랜 시간 동안 운영되어, 어릴 적 추억을 되새기기 위해 찾는 사람들도 많고, 노포 분위기를 즐기려는 젊은 사람들도 자주 방문합니다. 또한, 가성비 좋은 가격으로 점심시간에는 많은 회사원들이 찾기도 합니다. 방문객들 대부분은 어린 시절 학교 앞에서 먹었던 추억의 떡볶이 맛을 느낀다고 평하고 있습니다.', 37.519817, 127.099298, '', '지하철 2호선 잠실나루역 3번 출구, 527m', '', '매일', '', '음식점', '', '매일 11:00~21:00', '02-416-7235', ''),
	(919, '연백냉면', '05799  서울 송파구 새말로12길 7 (문정동)', 'images/연백냉면_919.png', '고급 냉면집 못지않은 깊은 맛을 자랑하는 냉면집\n\n연백냉면은 얇은 면발과 깊은 육수로 유명한 냉면집입니다. 연백냉면의 면발은 쫄깃하면서도 부드러운 식감이 일품이며, 육수는 소의 잡뼈와 사골을 8가지 비법 재료와 함께 끓여내어 깊은 풍미를 자랑합니다. 서울에 들렀다면 연백냉면에서 시원한 냉면 한 그릇 먹어보는 것을 추천합니다.', 37.482668, 127.129353, '', '지하철 8호선 장지역 1번 출구, 556m', '물냉6,000원 / 비빔냉면6,000원', '', '', '음식점', '', '11:00~20:00', '02-409-5054', '매달 2, 4번째 일요일 정기 휴무'),
	(920, '무에', '03056  서울 종로구 북촌로8길 28 (계동)', 'images/무에_920.jpg', '부드러운 커피와 계절별 디저트를 즐길 수 있는 조용하고 차분한 북촌카페, 무에(mueh)\n\n카페 무에(mueh)는 북촌에 위치한 로스터리 카페입니다. 적당한 산미와 좋은 단맛, 여운이 남는 커피를 내리기 위해 시그니처 블랜드로 매일 직접 로스팅하여 커피를 내립니다. 조용하고 차분한 분위기를 가진 카페로, 계절마다 디저트 메뉴가 바뀌기 때문에 다양하고 독특한 디저트를 맛볼 수 있습니다. 특별함보다는 편안함을 추구하는 이 장소에서 맛볼 수 있는 커피는 누구나 편하게 즐기기 좋은 부드러운 커피 맛을 가지고 있습니다. 카페 무에(mueh)를 찾는 사람들은 무에만이 가지고 있는 분위기와 커피의 맛, 계절에 걸맞는 디저트의 매력에 반해 다시 한 번 방문하게 됩니다. 모던한 인테리어와 미니멀한 분위기 덕분에 아늑하고 작은 공간에 집중하며, 책을 읽거나 공부를 하기에도 좋은 장소입니다.', 37.580863, 126.986647, '', '지하철 3호선 안국역 3번 출구, 479m', '', '월요일 ~ 일요일', ' https://www.instagram.com/cafe_mueh/ ', '카페, 디저트', '주차 불가, 반려동물 동반 가능', '월요일 10:00~19:00\n화요일 ~ 일요일 10:00~20:00', '0507-1389-9260', ''),
	(921, '코블러 연희', '03703  서울 서대문구 연희맛로 31-9 (연희동)', 'images/코블러_연희_921.png', '메뉴판 없이 바텐더와 함께 주문하는 연희동의 분위기 좋은 칵테일 바\n\n연희동 주택가의 한 건물, 담장 밖에서 겉으로 보면 그냥 주택처럼 보이지만, 초록색 대문을 열고 들어가면 정원에 마련된 야외 좌석이 찾는 이를 반깁니다. 과거 거주용으로 사용되었던 주택을 개조해 만들어진 위스키/칵테일 바 <코블러 연희>. 이 곳은 메뉴판이 존재하지 않습니다. 전문적인 바텐더와 대화를 통해 주류를 주문하는 방식, 자신도 몰랐던 자신의 취향과 음료를 발견할 수 있는 기회이기도 합니다. 물론 특정한 음료를 지정하는 것도 가능합니다. 바텐더들의 조주 실력은 모두 믿을 만 하니 분위기 좋은 이 곳을 찾을 이유는 충분합니다.', 37.568154, 126.930164, '', '지하철2호선 / 공항철도 / 경의중앙선 홍대입구역 3번 출구, 1.3km', '', '', ' https://app.catchtable.co.kr/ct/shop/cobbler_yeonhee', '술집, 바', '', '19:00~03:00 (02:30 라스트오더)', '010-4045-6421', ''),
	(922, '양상블', '07288  서울 영등포구 도림로141가길 36 (문래동4가) 1층', 'images/양상블_922.png', '양상블은 양고기를 뜻하는 양과 조화로운, 어울림을 뜻하는 프랑스어 앙상블의 합성어로 양고기와 프렌치 비스트로를 의미합니다. 즉석 화로구이로 양고기를 즐기고 프렌치와 한식의 조화를 느낄 수 있는 공간입니다.\n\n양상블은 양고기와 한식과 프렌치의 어울림으로 새로운 방향을 제시하는 이색적인 양고기 비스트로입니다. 1년 미만의 어린양(램)을 선별하여 프렌치랙, 숄더랙, 등심, 갈비살 로 나누어 직접 교차숙성 후 제공됩니다. 대표 요리로는 양고기를 다져 넣은 라구소스에 가지,토마토,호박을 곁들여 먹는 양상블 시그니처 메뉴인 라따뚜이와 얼큰한 국물이 일품인 양마라전골, 양수육쌀국수, 양떡갈비 등이 있으며 여기에 어울리는 와인, 하이볼, 전통주 까지 겸비하여 소중한 사람들과 편안한 휴식과 미식을 느낄수 있는 문래동 맛집 양상블입니다.', 37.516365, 126.889577, '', '2호선 문래역 1번 출구에서 약 570m (도보 9분)', '양상블양갈비세트(2인) 46,000원', '', ' https://www.instagram.com/yangsemble_moollae', '', '', '월요일 ~ 금요일 17:00~22:30\n토요일 ~ 일요일 15:00~22:30', '02-2637-7776', ''),
	(923, '서울래빗', '03041  서울 종로구 자하문로 19-1 (체부동) 1층', 'images/서울래빗_923.jpg', '서울래빗은 서촌을 찾는 여행자들과 서촌주민들을 위한 당근주스 전문점.\n\n서울래빗은 서촌을 찾는 여행자들과 서촌주민들을 위한 당근주스 전문점입니다. 대표적인 상품으로는 당근주스가 있으며 당근주스가 재료로 들어간 음료들을 우리나라에서 가장 많이 개발했습니다. 100% 당근주스, 당근커피, 마시는 당근케이크라고 할 수 있는 당케주스, 비타민 C를 강화한 오렌지 당근 생강주스, 레몬을 넣어서 더운 여름 날에 좋은 댕근레몬소다 등이 우리가 만들어 판매하는 상품들입니다.\n\n당근이 건강에 좋다는 것은 많이 알려져 있지만 대부분 반찬으로만 생각합니다. 저희는 당근을 맛있고 편하게 먹는 방법이 주스라고 생각합니다. 하지만 당근은 호불호가 강한 재료라는 사실은 외면할 수가 없었습니다. 그래서 당근에 거부감이 있는 분들에게 어떻게 하면 당근을 받아들이게 할 수 있을까 고민하다 보니 다양한 음료 메뉴가 탄생하게 되었습니다.\n\n당근주스 외에도 건강에 좋은 인삼을 마시기 쉽게 ‘인삼요거트스무디’를 만들었습니다. 한국의 인삼을 찾아온 외국인 여행자들에게 반응이 아주 좋습니다. 저희 매장 앞의 대형 토끼벽화 또한 당근에 대한 거부감을 느끼지 않고 친근함을 느꼈으면 하는 마음으로 제작했습니다. 이제는 서울에 방문한 것을 인증하고 싶은 여행자들의 포토스팟으로 인기입니다.', 37.577799, 126.971761, '1만원대', '지하철 3호선 경복궁역 2번 출구, 173m', '', '수요일~월요일', ' https://www.instagram.com/seoul.x.rabbit', '카페, 디저트', '', '10:00 - 18:00', '010-2656-1890', '화요일'),
	(924, '종로 선비옥', '03191  서울 종로구 종로16길 23 지상1층(관수동)', 'images/종로_선비옥_924.jpg', '종로에서 돼지갈비와 시원한 냉면을 즐길 수 있는 곳\n\n전라남도 광주 도축장에서 직송된 신선한 고기로 만든 수제 돼지갈비와 함께 직접 반죽해서 뽑은 면으로 만든 냉면을 맛있게 즐길 수 있습니다.  탑골공원 돌담을 따라 늘어선 야외좌석이 있어 종로만의 분위기를 제대로 느끼고 싶은 사람들이 많이 찾습니다. 또한 내부에도 좌석이 있으니 여름에도 쾌적하게 이용할 수 있습니다.', 37.568937, 126.988843, '3만원대', '지하철 1/3/5호선 종로 3가역 15번 출구, 383m', '', '월요일-일요일', '', '음식점', '예약, 단체이용 가능', '월요일~토요일 11:00 ~ 23:00\n일요일 13:30 ~ 23:00', '02-764-2214', ''),
	(925, '앤트러사이트 연희점', '03699  서울 서대문구 연희로 135 (연희동)', 'images/앤트러사이트_연희점_925.png', '무게감 있는 인테리어의 카페 <앤트러사이트 연희점>\n\n\'무연탄\'이라는 뜻을 가지고 있는, 연희동의 무게감 있는 인테리어의 카페 <앤트러사이트 연희점>. 빛과 어둠의 대비가 강조되는 인테리어, 입구를 들어서 어두운 복도를 따라 걸어가면 한 면 전체를 채우고 있는 통창이 있는 밝은 공간이 방문한 사람들을 마중합니다. 2층에는 거대한 테이블과 많은 좌석이 있어 작업하기 좋은 공간이기도 합니다. 다양한 종류의 디저트와 커피 뿐만 아니라 와인과 허브티도 준비되어 있습니다. 별도의 진동 벨 없이 직원이 테이블로 음료를 가져다주는 것 역시 특징. 주차 공간이 마련되어 있다는 점도 눈여겨볼 점입니다.', 37.569693, 126.932837, '1만원대', '지하철 2호선 / 공항철도 / 경의중앙선 홍대입구역 3번 출구, 1.5km', '', '매일', ' https://anthracitecoffee.com/', '카페, 디저트', '반려동물 동반 가능', '09:00~22:00 (21:30 라스트오더)', '02-332-7650', ''),
	(926, '베이징덕', '06022  서울 강남구 논현로 874 (신사동, 진성빌딩)  1층', 'images/베이징덕_926.jpg', '30년 경력의 합리적인 가격으로 즐길 수 있는 중국전통북경오리 전문점.\n\n30년 경력의 중국 전통 북경오리 요리를 합리적인 가격으로 즐길 수 있는 북경오리 전문점입니다. 담백하고 고소하며 부드러운 식감의 북경오리는 고소한 밀전병에 파와 춘장과 함께 싸서 먹으면 북경오리의 참맛을 제대로 느낄 수 있습니다. 또한, XO게살볶음밥을 북경오리와 함께 곁들여 먹으면 더욱 든든하고 풍성한 식사를 경험할 수 있습니다.', 37.526560, 127.028842, '', '지하철 3호선 압구정역 2번 출구, 50m', '베이징덕 구이 반마리, 쯔란 베이징덕 볶음', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 22:00 (15:00 - 16:00 브레이크타임, 21:30 라스트오더)', '-7089', ''),
	(927, '휘뚜루', '04779  서울 성동구 왕십리로2길 38 (성수동1가)', 'images/휘뚜루_927.png', '맛있는 어묵요리와 술 한잔 즐기기 딱 좋은 성수동 오뎅바, 휘뚜루\n\n휘뚜루는 오뎅바와 일본식 튀김요리인 쿠시카츠, 꼬치요리 등 일식을 맛볼 수 있는 이자카야로 일본의 분위기를 마음껏 즐길 수 있습니다. 최근 넷플릭스에서 방영된 흑백 요리사에 출연한 흑수저 사장님이 운영하는 식당으로 맛도 보장되어 있다고 볼 수 있습니다. 또한 가끔씩 열리는 팝업스토어로 다양하고 새로운 음식들을 선보이고 있어 보다 색다른 경험을 하기에 좋은 가게입니다. 특히 추운 겨울, 따뜻한 오뎅과 함께 시원한 생맥주를 즐기기 안성맞춤인 곳입니다. 가게에 들어서면 다른 손님들과 둘러앉을 수 있는 좌석, 일행과 마주 보고 앉을 수 있는 좌석 등 다양한 좌석이 마련되어 있고 내부 곳곳에 보이는 인테리어와 컨셉에서 세심한 디테일을 엿볼 수 있습니다.  \n\n휴무일 : 07월10일~7월30일', 37.542600, 127.048747, '', '지하철 수인분당선 서울숲역 1번 출구, 439m', '', '월요일 ~ 일요일', ' https://www.instagram.com/whitturu.oden/', '음식점', '캐치테이블을 이용하면 보다 편하게 웨이팅이 가능합니다.', '17:30 ~ 01:00 (00:00 라스트오더)', '070-4833-1345', '휴무일 : 07월10일~7월30일'),
	(928, 'murmur', '05612  서울 송파구 삼학사로18길 5 (석촌동, 나이스빌) 1층', 'images/murmur_928.png', '석촌호수 산책하다가 들리기 좋은 디저트 맛집\n\n석촌호수를 산책하다가 들리기 좋은 디저트 맛집 murmur는 디저트 맛집으로 유명한 곳입니다. 아기자기한 카페 분위기와 시즌에 맞는 제철 과일들로 출시되는 케이크와 샤를로트, 다양한 종류의 디저트들과 더불어 친절한 사장님까지 한번 가본 사람이라면 누구나 재방문 의사를 밝히는 곳입니다. 가장 유명한 딸기 샤를로트와 바스크 치즈 초코케이크 등 다양한 디저트들을 최상급 재료만을 사용해 선보이고 있습니다. 디저트뿐만 아니라 커피와 음료 메뉴들까지 훌륭한 맛을 자랑합니다. 특히 연말시즌이 되면 머머의 시그니처인 딸기 샤를로트 예약을 받고 있으니 참고하세요.', 37.504469, 127.097770, '1만원대', '지하철 9호선 석촌고분역 2번 출구, 243m', '', '수요일~월요일', ' https://www.instagram.com/cafe.murmur', '카페, 디저트', '', '평일 11:30~20:00\n주말 11:30~19:00', '0507-1311-4967', '화요일'),
	(929, '예나떡방', '02571  서울 동대문구 고산자로36길 29 (제기동)', 'images/예나떡방_929.png', '청량리 경동시장 내 영광 모시떡 전문점\n\n경동시장 내 위치한 예나떡방은 영광모시떡 전문점 입니다. 앙금은 팥, 흑임자 두가지 맛의 소가 너무 달지 않아 남녀노소 모두 인기가 많습니다. 매일 갓 만든 떡을 판매하고 있고 떡이 나올 때마다 손님들로 북적이는 핫플레이스. 경동시장 방문을 계획중이라면 간식으로 한번 맛보시길 추천합니다.', 37.579320, 127.040145, '', '지하철 1호선/경의중앙/경춘/수인분당 청량리역 1번출구, 316m', '', '', '', '', '', '매일 09:00~18:00', '070-4671-0313', ''),
	(930, '카페 레이어드 연남', '03980  서울 마포구 성미산로 161-4', 'images/카페_레이어드_연남_930.jpg', '맛있는 스콘과 예쁜 인테리어가 어우러진 공간\n\n카페 레이어드 연남점은 서울 마포구 연남동에 위치한 베이커리 카페로 유럽의 가정집같은 따뜻한 인테리어와 다양한 스콘과 케이크가 유명합니다. 내부는 앤티크한 소품과 예술 작품들로 꾸며져 있어 런던과 파리의 빈티지한 무드를 자아냅니다. 2층과 3층에는 햇살이 잘 드는 창가 좌석과 테라스가 마련되어 있습니다.', 37.564985, 126.924188, '', '지하철2호선/경의중앙/공항철도 홍대입구역 3번 출구, 838m', '', '', ' https://www.instagram.com/cafe_layered', '', '', '매일 10:00-22:00', '0507-1320-6219', ''),
	(931, '프로퍼커피바 2호점', '05647  서울 송파구 오금로31가길 20 (방이동, 대림가락) 1층', 'images/프로퍼커피바_2호점_931.png', '방이역 인근 브런치&베이커리 맛집\n\n방이역 인근에 위치한 프로퍼커피바 2호점은 브런치와 베이커리 맛집으로 많은 사람들에게 사랑받고 있는 곳입니다. 다양한 종류의 베이커리와 브런치 메뉴, 계절에 맞춰 변경되는 오늘의 스프 라인업까지, 취향에 맞는 음식을 자유롭게 고를 수 있습니다. 넓은 매장과 깔끔한 인테리어가 돋보이며, 곳곳에서 세심한 서비스가 제공됩니다. 특히, 야외에 위치한 넓은 테라스석은 날씨가 따뜻할 때 인기가 많습니다. 또한, 매장에서 판매하는 콜드브루는 커피를 좋아하는 이들이라면 추천할 만한 메뉴. 프로퍼커피바 2호점은 많은 사람들이 찾는 장소이다 보니 주말과 공휴일에는 이용 시간이 2시간으로 제한되어 있으니 참고하세요.', 37.507338, 127.123156, '1만원대', '지하처 5호선 방이역 3번 출, 427m', '', '월요일~토요일', '', '카페, 디저트', '- 주말 및 공휴일 이용시간 2시간\n- 4인석은 2인 이상 이용 가능합니다.', '09:00~22:00', '0507-1389-0716', '일요일'),
	(932, '정동추어탕', '04516  서울 중구 새문안로 30 (충정로1가, 삼성화재)', 'images/정동추어탕_932.png', '추어탕을 맛볼 수 있는 정동의 추어탕맛집\n\n정동에 위치한 정동추어탕은 점심시간이 되면 근처 회사원들로 북적입니다. 추어탕은 미꾸라지를 주재료로 한 국물 요리로, 미꾸라지와 다양한 채소, 양념을 넣고 끓여내어 깊고 진한 맛을 자랑합니다. 정동추어탕의 특별한 점은 추어탕과 솥밥이 함께 나와 마지막에 먹을 수 있는 누룽지를 즐길 수 있습니다. 또한 소면을 함께 제공해 추어탕에 소면과 준비되어 있는 각종 소스들을 넣어 먹어도 좋습니다. 추어를 잘 못먹는 사람은 돼지고기가 함께 들어간 돈추탕과 우삼겹 추어탕, 소고기 뚝배기 불고기도 있어 기호에 맞는 메뉴를 선택하면 됩니다. 각 메뉴들과 곁들여 먹을 수 있는 추어튀김, 추어만두도 추천합니다. 날씨가 춥거나 해장 또는 기력보충이 필요할때 들리기 좋은 식당입니다.', 37.567824, 126.969106, '1만원대', '지하철 5호선 서대문역 5번 출구, 266m', '', '월요일~토요일', '', '음식점', '', '월요일~금요일 09:30~20:30\n토요일 10:00~19:30', '0507-1362-8886', '일요일'),
	(933, '적당', '04523  서울 중구 을지로 29 (을지로1가, 더존을지타워)  1층 후문', 'images/적당_933.png', '팥을 전문으로하는 을지로 대표 양갱카페\n\n카페 적당은 팥을 중심으로 한 음료와 디저트를 선보이며 많은 사람들에게 사랑받는 한식 디저트 전문 브랜드입니다. 팥라떼, 팥차 등 다양한 음료를 제공하며, 첨가물 없이 건강한 재료로 만든 밤양갱을 포함해 총 9가지 맛의 양갱을 즐길 수 있습니다. 백설기 앙버터, 약과 모나카 등 전통 디저트도 함께 만나볼 수 있어 선택의 폭이 넓습니다. \n\n매장은 나무 재질의 아치형 프레임 공간과 모래정원이 있는 대리석 공간으로 구성되어 있어 독특하면서도 분위기가 좋은 카페입니다. 선물용 디저트가 필요한 사람들은 스마트 스토어를 통해 구매도 가능합니다.', 37.566488, 126.981025, '', '지하철 2호선 을지로입구역 1-1 출, 23m', '', '매일', ' http://www.instagram.com/euljiro.jeokdang', '카페, 디저트', '', '10:00 ~ 21:30\n*연휴 일정은 인스타그램 안내를 참고해주세요.', '0507-1312-8928', ''),
	(934, '오설록 티하우스 북촌점', '03055  서울 종로구 북촌로 45 (가회동)', 'images/오설록_티하우스_북촌점_934.jpg', '한옥 마을이 한눈에 내려다 보이는 북촌 찻집\n\n1층은 차와 간식 또는 기념품을 판매하는 공간으로, 손님들은 현장에서 차를 맛보고 마실 수 있습니다. 2층에 있는 찻집은 넓은 창문을 통해 북촌 한옥마을의 옥상 풍경을 한눈에 볼 수 있습니다. 3층에는 오설록만의 특별한 차 시음 공간이 있으며 계절 메뉴에 따라 업데이트됩니다. 계절에 따른 차에 영감을 받아 티 칵테일, 티 케이크, 티 스파클링 워터 및 기타 티 스낵을 선보일 예정입니다. 차 시음 체험은 예약제이며, 공식 홈페이지 또는 현장에서 예약 방법을 미리 확인해주세요.', 37.580999, 126.984601, '', '지하철 3호선 안국역 2번출구, 447m', '', '', ' https://www.osulloc.com/kr/ko', '', '매장 주변에는 주차가 불가한 관계로 대중교통을 이용해주세요', '월-목 11:00-20:00 , 금-일 11:00-21:00', '070-4121-2019', ''),
	(935, '사오월수라상', '06243  서울 강남구 역삼로7길 17 (역삼동, 네스빌) 1층', 'images/사오월수라상_935.jpg', '조선시대 왕실 수라상 조리비법 그대로 재현한 강남역 간장게장 맛집\n\n짜지 않고 큰 게장이 특징인 간장게장/양념게장과 궁실 전통 조리법으로 만든 궁중 소갈비살, 8시간을 우려 낸 소 사골 국물과 국산 시레기와 한우 고기로 만든 소고기 성주탕 등 푸짐하고 맛있는 궁중 수라상의 맛을 느낄 수 있습니다. 단체석 및 예약이 가능하며 주차는 2시간 제공됩니다.', 37.495148, 127.032568, '', '지하철 2호선 강남역 4번출구, 500m', '', '', ' https://lrl.kr/cgTj7', '', '단체석 및 예약 가능', '매일 10:00-22:00 (15:00-17:00 브레이크타임)', '0507-1365-9762', ''),
	(936, '수도원', '03085  서울 종로구 동숭3길 16 (동숭동)', 'images/수도원_936.png', '붉은 벽돌 건물의 지하, 중세시대 수도원이 연상되는 바\n\n혜화에 위치한 수도원은 붉은 벽돌 건물의 지하에 자리한 바로, 마치 중세시대 수도원이 연상되는 공간의 바입니다. 수도원 맥주를 비롯해 여러 종류의 병맥주와 생맥주 2종, 와인과 칵테일, 위스키 등 다양한 술을 맛볼 수 있습니다. 메뉴판에는 맥주와 와인에 대한 상세한 설명이 제공되어 취향에 맞는 음료를 선택하기 좋습니다. 또한, 여러 가지 플레이트와 안주가 준비되어 있어 술과 함께 곁들여 먹을 수 있습니다. 벽돌로 꾸며져있는 내부 공간과 나무 소재의 가구들로 수도원의 분위기를 마음껏 느낄 수 있으며 함께 흘러나오는 재즈와 어두운 조명으로 공간의 특색을 더욱 돋보이게 만들어줍니다.', 37.581731, 127.004767, '', '지하철 4호선 혜화역 2번 출구, 340m', '', '월요일~일요일', ' https://www.instagram.com/soodowon', '술집, 바', '', '월요일~금요일 17:00~01:00\n토요일~일요일 16:00~01:00', '02-747-1933', ''),
	(937, '일편등심 홍대본점', '04050  서울 마포구 홍익로6길 52 (동교동)  3층', 'images/일편등심_홍대본점_937.jpg', '서울 곳곳에 위치한 소고기 전문 프랜차이즈 식당.\n\n서울 곳곳에 위치한 소고기 전문 프랜차이즈 식당으로, 호평 가득한 방문객 리뷰로 꽉 찬 곳입니다. 그만큼 질 높은 퀄리티와 서비스를 자신 있게 선보이는 곳입니다. 등심, 안심, 새우살 등 다양한 부위가 마련되어 있어 각자의 취향에 맞게 즐길 수 있습니다.식당에서는 직접 고기를 구워주며, 고급스럽고 모던한 분위기로 분위기 있는 식사를 제공합니다.', 37.556312, 126.924404, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 8번 출구, 116m', '1++ 명품SET, 1++ 일편SET', '', ' https://www.instagram.com/ilpyeon__offical/#', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 24:00 (15:00 - 17:00 브레이크타임)', '-2920', ''),
	(938, '펍휘트니', '05557  서울 송파구 올림픽로10길 9 (잠실동, 진영빌딩) 1층', 'images/펍휘트니_938.jpg', '실내에서 야구 관람이 가능한 대형 스크린이 있는 펍\n\n펍 휘트니는 야구 팬들 사이에서 성지로 소문난 수제 맥주&칵테일 전문점입니다.\n\n1990년대 고급 카페였던 휘트니는 소개팅의 성지였고, 2010년대 중반까지 24시간 운영하는 카페로 취객들의 안식처였습니다. 이후 다양한 맥주의 맛을 즐길 수 있는 펍으로 바뀌었지만, ‘휘트니’라는 이름을 그대로 사용하고 있습니다. 많은 종류의 이색적이고 시원한 세계 맥주와 다양한 위스키, 음식과 분위기 하나 놓치지 않고 리스트 업 된 와인, 100여 가지 이상의 칵테일과 술을 안 먹는 분들을 위한 다양한 음료와 논알코올 칵테일까지 즐길 수 있습니다.', 37.510804, 127.081241, '', '지하철 2호선/9호선 종합운동장역 9번출구, 419m', '', '', '', '', '', '매일 17:00-05:00', '0507-1387-2727', ''),
	(940, '푸드떼', '03062  서울 종로구 율곡로1길 40-37 (사간동)', 'images/푸드떼_940.png', '시즌별로 변경되는 시그니처 메뉴 파르페와 엄선한 동서양의 차, 차와 어울리는 차과자를 선보이는 티 아뜰리에\n\n푸드떼는 현대미술관 서울관 뒷편과 안국역 1번 출구 사이 송현열린공원 사잇길에 위치한 한옥 티 아뜰리.입니다\n\n이곳은 시즌별로 바뀌는 시그니처 파르페와 엄선된 동서양의 차, 그리고 차와 잘 어울리는 차과자를 선보이는 곳입니다. 예스러운 한옥의 정취 속에서 비건 메뉴도 만나볼 수 있으며, 단체 이용이 가능하지만 주차는 현대미술관 서울관 또는 정독도서관 주차장을 이용해야 합니다.\n\n프라이빗한 시간을 원하는 분들을 위해 한식 차실과 명상실로 구성된 프라이빗 룸도 예약제로 운영되며, 문의는 카카오톡 채널이나 인스타그램을 통해 가능합니다.\n\n바 좌석, 테이블, 좌식 및 평상 좌석이 마련된 실내 공간과 졸졸 물소리가 흐르는 작은 정원을 바라보며 차를 즐길 수 있는 외부 소반 좌석까지, 다양한 형태의 좌석에서 편안히 머물 수 있습니다.\n\n국내외 엄선된 차와 차과자, 그리고 차와 어우러지는 아름다운 도자기를 통해 고요한 차의 풍류를 느낄 수 있는 곳입니다.', 37.577983, 126.981371, '1만원대', '지하철 3호선 안국역 1번 출구, 600m', '', '화 ~ 일', ' https://www.instagram.com/foudethe_seoul/', '카페, 디저트', '', '화~금 13:00 ~ 19:00\n토~일 11:00 ~19:00', '0507-1319-7729', '월'),
	(941, '종로삼계탕', '03189  서울 종로구 종로8길 21 (관철동)  1층', 'images/종로삼계탕_941.jpg', '2대째 운영하는 삼계탕 전문점으로 깊은 맛을 내는 삼계탕.\n\n2대째 운영하는 삼계탕 전문점으로 깊은 맛을 내는 삼계탕을 좋아하는 단골이 많은 식당입니다. 닭고기는 부드럽고 국물을 깊고 시원해 그 맛의 조화가 좋습니다. 기본찬으로 나오는 깍두기도 삼계탕과 잘 어울립니다. 전복 삼계탕, 한방 삼계탕, 들깨 삼계탕 등 다양한 삼계탕 메뉴가 있습니다.', 37.569074, 126.984123, '', '지하철 1호선 종각역 4번 출구, 124m', '삼계탕, 들깨 삼계탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00-21:00 (15:00-17:00 브레이크타임, 20:15 라스트오더)', '0507-1322-8761', ''),
	(942, '로이정원', '03134  서울 종로구 서순라길 57 한옥', 'images/로이정원_942.jpg', '종묘 돌담길 옆에 위치한 분위기 좋은 야장 술집 와인, 위스키, 맥주펍\n\n돌담길이 유명한 서순라길에 위치한 한옥 술집으로 돌담뷰와 함께 고즈넉한 분위기를 느낄 수 있습니다. 1,2층 창가에서 바라보는 돌담뷰도 좋지만 날씨가 좋다면 야장에서 돌담을 그대로 느끼며 맛있는 음식과 술을 드시는 것을 추천합니다. 와인이랑 즐기기에 좋은 안주 메뉴들과 글라스 와인, 하이볼, 맥주, 위스키, 전통주까지 종류가 다양합니다.', 37.573048, 126.992950, '', '지하철 1호선/3호선/5호선 종로3가역 8번출구, 147m', '', '', '', '', '', '월-금 17:00-23:00, 토-일 15:00-23:00 (라스트오더 22:00)', '0507-1305-7827', ''),
	(943, '쎈느 Scene', '04782  서울 성동구 연무장5길 20 1층', 'images/쎈느_Scene_943.jpg', '탁트인 개방감과 여유로움이 느껴지는 성수동 대형 카페\n\n성수동 카페거리에 있는 쎈느(Scene)는 팝업스토어 임대공간으로도 활용되어 많은 사람들이 방문하며, 1층에는 카페, 2층에는 편집샵으로 운영되고 있습니다. 날씨가 좋을 때 야외 테이블에 앉아 커피를 즐길 수 있으며, 반려동물 동반이 가능한 카페입니다.', 37.544893, 127.053446, '', '지하철 2호선 성수역 4번출구, 189m', '', '', ' https://www.sceneseoul.com/', '', '', '매일 8:30-22:00', '0507-1493-2127', ''),
	(944, '성수다락', '04784  서울 성동구 뚝섬로9길 20 2층', 'images/성수다락_944.jpg', '성수동 카페거리에 있는 오므라이스&파스타 전문점\n\n입구를 찾는 즐거움부터 다락방 계단으로 올라가는 비밀스럽고 특별한 경험, 달그락거리며 만든 맛있는 음식, 햇살이 가득한 따뜻하고 아늑한 감성까지 느낄 수 있는 양식당입니다. 파스타 뿐만 아니라 성수다락의 시그니처 오므라이스를 경험해보세요. 웨이팅이 많은 식당이라 미리 예약하면 기다리지 않고 입장 가능합니다.', 37.539929, 127.056231, '', '지하철 2호선 성수역 3번출구, 577m', '', '', ' http://www.instagram.com/seongsudarak', '', '', '매일 11:30-21:15', '0507-1349-9197', ''),
	(945, '춘천숯불닭갈비 강남역점', '06129  서울 강남구 강남대로96길 11-4 (역삼동)  2층', 'images/춘천숯불닭갈비_강남역점_945.jpg', '깊은 맛이 나는 닭갈비를 선사하며 쫄깃한 닭고기와 풍부한 양념.\n\n깊은 맛이 나는 닭갈비를 선사하는 이곳은, 쫄깃한 닭고기와 풍부한 양념이 어우러져 특별한 풍미를 자랑합니다. 간장 양념과 고추장 양념 닭갈비도 훌륭하지만, 이곳에서만 맛볼 수 있는 허브 닭갈비는 은은한 허브 향이 더해져 특별한 풍미를 선사합니다. 3가지 맛을 동시에 즐기고 싶다면 동시 주문도 가능합니다.  매콤한 닭갈비를 다 먹은 후, 메밀 면발에 시원한 육수를 더한 감칠맛 나는 막국수로 마무리하는 것 또한 추천합니다.', 37.500104, 127.028055, '', '지하철 2호선/신분당선 강남역 11번 출구, 212m', '허브닭갈비(330g), 숯불 닭목살(250g)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '17:00 - 22:00', '-10313', ''),
	(946, '에베레스트 레스토랑 동대문역사문화공원점', '04564  서울 중구 장충단로 247 (을지로6가, 굿모닝시티쇼핑몰)  지하 3층', 'images/에베레스트_레스토랑_동대문역사문화공원점_946.jpg', '네팔 부부가 운영하는 이 네팔 음식 전문점.\n\n네팔 부부가 운영하는 이 네팔 음식 전문점은 다양한 향신료로 발효한 치킨을 탄두리에서 익혀낸 치킨 티카, 치즈, 크림, 토마토를 넣어 만든 치킨 마크니 커리가 인기 메뉴입니다. 이곳은 다양한 조리 방식의 네팔 요리를 제공하며, 그 독특한 맛으로 유명한 곳입니다.', 37.566802, 127.007358, '', '지하철 2/4/5호선 동대문역사문화공원역 14번 출구, 121m', '탄두리 치킨, 머턴 쎄꾸와', '', ' http://www.everestfood.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '0507-1426-8938', ''),
	(947, '용용선생 마라도원', '04797  서울 성동구 아차산로11길 3 (성수동2가)', 'images/용용선생_마라도원_947.png', '마라인들을 위한 무릉도원\n\n용용선생 마라도원은 마라인들을 위한 무릉도원입니다. 마라와 고량주에 진심인 용용선생의 장인정신을 담은 차이니즈 노포컨셉의 플래그쉽 매장이며, 숯불향이 진하게 느껴지는 진한 직화마라탕과 특별한 퍼포먼스존을 함께 경험할 수 있는 새로운 미식공간입니다.', 37.544070, 127.058966, '', '지하철 2호선 성수역 2번출구, 259m', '직화마라탕(2인) 직화불맛이 깊게 묻어난 마라육수와 특제 마라장으로 구워낸 풍미가 매력적인 마라탕 - 19,900원\n고추바삭유림기 36시간 마리네이드한 바삭한 닭튀김에 상큼한 레몬소스와 양상추를 곁들인 용용선생 스테디셀러 - 15,900원', '', '', '', '외국어 메뉴판 (한/중/일/영)', '매일 16:00 - 23:00', '02-462-0999', ''),
	(948, '필요의 방', '04547  서울 중구 을지로 192 (을지로4가), 3층', 'images/필요의_방_948.png', '조명 가게들 사이 숨겨져 있는 보석같은 카페\n\n조명 가게들이 모여있는 건물 3층, 간판 없이 숨어있는 카페. 작은 공간이지만 독특하게 꾸며진 인테리어와 창문을 통해 들어오는 햇볕, 그리고 잘 구성된 스피커에서 나오는 잔잔한 음악이 이 곳을 어디에도 존재하지 않는 개성있는 공간으로 만듭니다. 인도식 밀크티인 짜이와 스웨덴의 빵 카다멈 번, 체다치즈 미트파이 등 이곳만의 특별한 음료와 디저트들이 방문하는 이들을 기다리고 있습니다. 특히 매 달 새로운 스페셜티 원두로 바뀌는 필터 커피는 사람들을 이 곳으로 주기적으로 찾게 만듭니다. 입구가 어디인지 찾기 힘들지만, 이 사실 마저 방문객들에겐 재미있는 수수께끼로 다가옵니다.', 37.566524, 126.999351, '1만원대', '지하철 2 / 5호선 을지로4가역 7번 출구, 72m', '', '', ' https://www.instagram.com/room.rqmnt/', '카페, 디저트', '', '월요일, 화요일, 목요일 12:00~19:00\n금요일~일요일 12:00~20:00', '', '수요일'),
	(949, '히포 브런치하우스', '03974  서울 마포구 성미산로17길 85', 'images/히포_브런치하우스_949.jpg', '건강한 식재료로 즐거운 먹거리를 만드는 연남동 브런치 카페\n\n히포 브런치하우스는 호텔부터 미슐랭 레스토랑까지 다양한 경력을 쌓은 쉐프진들로 전문성을 가진 연남동 브런치 카페입니다. 신선하고 안전한 식재료로 드레싱과 소스를 직접 만들고 히포 컨셉처럼 크고 푸짐한 음식을 제공하고 있습니다. 넓은 공간의 대형 카페로 반려견과 함께, 아이들과 함께 방문하기에 좋습니다.', 37.564141, 126.917535, '', '지하철 경의중앙선 가좌역1번출구, 493m', '', '', ' https://www.instagram.com/brunchhaus_hippo/', '', '주차불가, 공영주차장을 이용해 주세요.', '매일 09:00-21:00', '0507-1320-6219', ''),
	(950, '창동 포차거리', '01414  서울 도봉구 마들로11길 73 (창동)', 'images/창동_포차거리_950.jpg', '창동역 근처 빨간 포차들이 줄지어 있는 창동 포차거리\n\n창동 포차거리는 창동역 1번 출구 근처에 빨간 포차들이 나란히 줄지어 형성되어 있으며, 오랜 시간 자리를 지킨 포차 거리입니다. 깔끔하고 쾌적하게 정리되어 있어 이용하기 편리하며, 야장 분위기 속에서 포장마차의 다양한 메뉴를 즐길 수 있습니다.', 37.653257, 127.049061, '', '지하철 1호선/4호선 창동역 1번출구, 36m', '', '', '', '', '', '가게별 상이(17:00-2:00)', '', '일요일'),
	(951, '꽃살집 홍대점', '03994  서울 마포구 동교로 212-2 (동교동)  1층', 'images/꽃살집_홍대점_951.jpg', '72시간 저온 숙성하여 더욱 부드럽고 풍미 가득한 최상급 소고기.\n\n소고기의 깊은 향과 맛을 위해 72시간 저온 숙성하여 더욱 부드럽고 풍미 가득한 최상급 소고기를 맛볼 수 있습니다. 이 소고기는 입 안에서 살살 녹는 부드러운 식감과 진한 육즙이 특징으로, 천연 조미료를 사용하여 곁들임 음식부터 찬거리까지 재료 본연의 맛을 살리며 조화를 이룹니다. 주문과 동시에 지어지는 갓 지은 솥밥은 이곳에서 빠뜨릴 수 없는 메뉴 중 하나로, 고기와 함께 즐기면 더욱 맛있습니다.', 37.559116, 126.923950, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 3번 출구, 209m', '갈비상, 눈꽃살', '', ' https://www.instagram.com/marbling_house', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '13:00 - 02:00 (01:00 라스트오더)', '-10387', ''),
	(952, '신이도가', '04042  서울 마포구 잔다리로 20-12', 'images/신이도가_952.png', '신이도가는 전통 한옥의 아름다움을 살린 개방감 있는 공간과 다양한 커피, 차를 즐길 수 있는 분위기 좋은 카페.\n\n합정과 홍대 사이에 위치한 신이도가는 전통 한옥의 아름다움을 느낄 수 있는 분위기 좋은 카페입니다. 가운데 마당을 둘러싼 통창을 통해 개방감 있는 공간을 자랑하며, 마당 가운데에는 따뜻한 모닥불이 피워져 있어 아늑한 분위기를 더합니다. 천장 서까래가 그대로 드러난 구조로 한옥의 고유한 미를 감상할 수 있습니다. 커피는 물론 다양한 종류의 차도 제공되어, 취향에 맞는 음료를 선택할 수 있습니다. 고즈넉한 분위기 속에서 여유로운 시간을 보내기에 완벽한 장소입니다.', 37.551416, 126.920906, '', '지하철 2 / 6호선 합정역 3번 출구, 576m', '', '매일', '', '카페, 디저트', '', '11:00 ~ 22:00', '', ''),
	(953, '목포항 간장게장 아구찜', '06526  서울 서초구 신반포로47길 107 (잠원동)', 'images/목포항_간장게장_아구찜_953.jpg', '깊고 담백한 간장게장이 인기 메뉴. 양념게장, 산꽃게찜 등 다양한 꽃게 요리.\n\n하루 두 번, 오랜 손맛과 듬뿍 넣은 양념으로 만든 깊고 담백한 간장게장이 인기 메뉴입니다. 이곳에서는 간장게장뿐만 아니라 양념게장, 산꽃게찜 등 다양한 꽃게 요리를 즐길 수 있습니다. 또한, 10여 가지 양념과 콩나물, 미나리를 곁들여 푹 쪄 만든 아귀찜은 부드러운 살과 중독성 있는 양념 맛이 일품으로, 입에서 사르르 녹는 듯한 식감을 제공합니다.', 37.515070, 127.018627, '', '지하철 3호선/신분당선 신사역 4번 출구, 107m', '간장게장, 아귀찜', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '00:00 - 24:00', '-1722', ''),
	(954, '영삼이네 우정소갈비 강남역점', '06612  서울 서초구 서초대로77길 31 (서초동)', 'images/영삼이네_우정소갈비_강남역점_954.jpg', '시그니처 메뉴는 양념 정갈비와 양념 우갈비\n\n서울 곳곳에 위치한 프랜차이즈 식당입니다. 이곳의 시그니처 메뉴는 양념 정갈비와 양념 우갈비입니다. 양념 정갈비는 지방이 섞여 있어 고소하고 씹는 식감이 뛰어나며, 양념 우갈비는 지방이 거의 없어 담백하고 부드러운 식감을 제공합니다. 고기와 함께 꼭 맛봐야 하는 냉면도 있으며, 단돈 3,000원에 판매되는 순두부찌개는 가성비가 뛰어나 추천할 만한 메뉴입니다.', 37.500619, 127.025376, '', '지하철 2호선/신분당선 강남역 10번 출구, 300m', '양념 정갈비, 양념 우갈비', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 03:00(02:20 라스트오더)', '0507-1387-3193', ''),
	(955, '남산산채집', '04630  서울 중구 소파로 95 1층', 'images/남산산채집_955.png', '남산산채집은 30년 전통을 자랑하는 남산 대표 맛집으로, 건강한 재료와 깊은 맛, 남산 뷰를 함께 즐길 수 있는 안심 먹거리 명소이다.\n\n남산산채집은 30년 전통을 자랑하는 수요미식회 맛집으로, 남산의 진짜 맛집으로 손꼽힌다. 최고 위생등급을 받은 안심음식점이자 착한음식점으로, 건강하고 깔끔한 맛을 추구한다. 대표 메뉴인 남산돈까스는 무항생제 한돈과 대한민국 최장수 레스토랑 ‘촛불1978’의 50년 비법 레시피로 만들어 깊은 풍미가 일품이다. \n\n\n\n산채비빔밥은 저온 압착 들기름과 직접 담근 시골간장으로 무친 나물을 사용해 정성스러운 맛을 더한다. 부추전, 생선까스, 도토리묵 등 원재료의 이력이 명확해 믿고 먹을 수 있다. 남산타워와 남산케이블카 탑승장에서 100m 거리에 위치해 남산을 마주하는 뷰 맛집으로도 유명하다. 가족모임, 단체모임, 외국인 관광객, 수학여행 단체가 자주 찾는 인기 맛집이다.', 37.556813, 126.985348, '', '4호선 명동역 3번 출구에서 약 552m (도보 11분)', '', '매일', ' https://www.instagram.com/sanchaizip/', '', '', '10:50 ~ 21:00', '0507-1434-1978', ''),
	(956, '한국집(롯데백화점 잠실점)', '05554  서울 송파구 올림픽로 240 (잠실동, 롯데월드)', 'images/한국집(롯데백화점_잠실점)_956.jpg', '전주에서 유명한 전주 비빔밥 전문점의 서울 지점.\n\n전주에서 유명한 전주 비빔밥 전문점의 서울 지점으로, 전주까지 가지 않아도 전주식 비빔밥을 맛볼 수 있는 곳입니다. 많은 관광객들이 찾는 인기 명소로, 미리 비벼 나오는 전주식 비빔밥과 육회가 곁들여진 육회비빔밥이 대표 메뉴입니다. 백화점 안에 위치해 찾기 쉽고 쾌적한 분위기에서 식사를 즐길 수 있습니다.', 37.511499, 127.098239, '', '지하철 2/8호선 잠실역 3번 출구, 53m', '육회비빔밥, 전주비빔밥', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:30 - 22:00', '-3862', ''),
	(957, '중앙갈치식당', '04528  서울 중구 남대문시장길 22-12 (남창동)', 'images/중앙갈치식당_957.jpg', '남대문시장 갈치골목에 위치한 갈치조림 전문 한식당\n\n남대문시장 갈치골목에 위치한 이 갈치조림 전문 한식당은 TV 맛집 프로그램에 여러 차례 소개된 인기 맛집입니다. 식사 시간에 방문하면 종종 줄을 서서 들어가야 할 정도로 인기가 많은 곳입니다. 이곳에서 제공하는 갈치조림은 자작한 국물에 부드럽고 살이 꽉 찬 갈치가 조리되어 나옵니다. 한 냄비에 가득 담긴 갈치조림은 밥과 함께 먹기에 최적이며, 공깃밥 2공기도 거뜬히 소화할 수 있는 양입니다.', 37.559788, 126.977079, '', '지하철 4호선 회현역 5번 출구, 210m', '갈치조림, 모듬생선구이', '', ' http://cityfood.co.kr/h9/jung-angsigdang', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '08:30 - 21:00', '-3564', ''),
	(958, '해목(롯데월드몰점)', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰)  6층', 'images/해목(롯데월드몰점)_958.jpg', '부산이 원조인 장어덮밥이 일품인 식당\n\n부산이 원조인 장어덮밥이 일품인 식당이다. 외관과 음식 담김새가 일본에 온 듯한 착각을 불러일으킬 만큼 일본 분위기를 재현하는 데 충실하다. 장어는 일본 전통 방식으로 구워내어 부드럽고 고소하며, 간이 적당해 끝까지 질리지 않고 맛있다. \n\n장어덮밥에는 고소한 장어와 함께 새콤달콤한 간장 소스가 어우러져 깊은 맛을 낸다. 식사는 정갈하게 담긴 장어와 함께 신선한 채소와 밥이 조화롭게 제공되며, 일본의 전통적인 맛을 그대로 느낄 수 있다.', 37.513713, 127.104302, '', '지하철 2/8호선 잠실역 10번 출구, 13m', '특 히츠마부시, 히츠마부시', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:30 - 22:00', '-6479', ''),
	(959, '잠두봉더나인', '04085  서울 마포구 마포나루길 582 (C& 한강랜드 잠두봉 유람선 선착장)', 'images/잠두봉더나인_959.jpg', '한강 위에서 이색적으로 즐기는 삼겹살 맛집\n\n과거 한강 선착장을 개조해 만든 마포구에 위치한 바비큐 레스토랑입니다. 서울 도심 한가운데에서 한강을 바라보며 대표메뉴인 삼겹살과 떡갈비를 즐길 수 있습니다. 여러 방송 매체에서 소개되면서 외국인 손님이 많이 방문하며, 가족단위로도 즐겨찾는 한강의 이색적인 맛집입니다. 한강위에서 노을을 바라보며 바비큐를 즐길 수 있는 이곳에서 특별한 추억을 경험해 보세요.', 37.545105, 126.908460, '', '지하철2호선/6호선 합정역7번출구, 804m', '', '', ' https://blog.naver.com/the9bongbong', '음식점', '', '매일 12:00-22:00', '0507-1385-8903', ''),
	(960, '최가네 샤브버섯칼국수 성수점', '04768  서울 성동구 서울숲6길 12 (성수동1가)  1층', 'images/최가네_샤브버섯칼국수_성수점_960.jpg', '다양한 버섯이 들어가는 버섯 샤브샤브 전문 식당\n\n다양한 버섯이 들어가는 버섯 샤브샤브 전문 식당입니다. 20년 전통의 3대째 내려오는 조리법으로 구수하고 진한 육수, 부드러운 고기, 신선한 버섯의 조화가 일품입니다. 특히 고기를 먹지 않는 사람들을 위해 버섯만으로 준비된 샤브샤브 메뉴도 제공됩니다.', 37.547564, 127.042925, '', '지하철 2호선 뚝섬역 8번 출구, 382m', '스페셜 샤브샤브, 버섯매운탕칼국수', '', ' https://www.instagram.com/choigane_seongsu', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00 (15:00 - 17:00 브레이크타임, 20:20 라스트오더)', '-3998', ''),
	(961, '헤비스테이크 안국역점', '03059  서울 종로구 율곡로 67 (계동)  1층', 'images/헤비스테이크_안국역점_961.jpg', '양이 푸짐한 직화 비프 스테이크를 합리적인 가격으로 제공.\n\n서울 곳곳에 자리한 스테이크 전문 프랜차이즈입니다. 양이 푸짐한 직화 비프 스테이크를 합리적인 가격으로 제공해 많은 이들이 찾는 곳입니다. 이 식당은 프리미엄 신선 냉장육을 직수입하여 자사 정육 공장 시스템으로 관리해 고품질 스테이크를 가성비 좋게 제공합니다. 또한, 혼밥하기에도 적합해 혼자 여행하는 여행객들도 부담 없이 이용할 수 있습니다.', 37.577334, 126.986647, '', '지하철 3호선 안국역 3번 출구, 32m', '비프 스테이크, 치킨 스테이크', '', ' http://www.heavysteak.co.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00', '-3974', ''),
	(962, '서울원조아구찜', '03133  서울 종로구 삼일대로 436-1 (낙원동)', 'images/서울원조아구찜_962.jpg', '낙원 아귀찜 거리에서 유명한 곳 중 하나\n\n낙원 아귀찜 거리에서 유명한 곳 중 하나입니다. 담백하면서 칼칼한 소스의 아귀찜과 재료가 아낌없이 들어간 깊은 국물의 꽃게탕이 시그니처 메뉴입니다. 기본찬으로 나오는 북엇국이 아귀찜과 잘 어울립니다. 아귀찜을 먹고 난 후에는 고소한 맛과 풍부한 양념이 특징인 볶음밥으로 마무리하는 것이 이 식당을 완벽하게 즐기는 방법입니다.', 37.573602, 126.988019, '', '지하철 1/3/5호선 종로3가역 5번 출구, 221m', '아구찜, 해물찜, 꽃게탕 소, 해물파전', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00-24:00 (23:30 라스트오더)', '-4891', ''),
	(963, '1994 SEOUL', '03979  서울 마포구 성미산로23안길 20-12 (1994서울)', 'images/1994_SEOUL_963.jpg', '전통 절기별 다과의 정갈한 맛과 아름다운 기물의 조화\n\n1994 SEOUL은 우리 전통의 떡과 과자를 기반으로 만드는 음식들과 계절의 차를 제공하는 다과코스 전문점입니다. 연남동의 한적한 골목길에 위치한 1994 SEOUL은 세련된 바 카운터에서 \'절기별 다과 코스\'를 예약제로 운영됩니다. 우리나라 절기와 세시풍속, 명절을 주제로 전개되는 다과코스는 2달마다 새로운 주제로 진행됩니다. 계절을 오감으로 느낄 수 있는 메뉴로 구성되어 있고 코스는 약 80분으로 하루 4회 시간대로 나뉘어 제공되며, 2인부터 예약이 가능합니다.', 37.565821, 126.921485, '', '지하철 경의중앙선, 가좌역 4번 출구, 702m', '', '', '', '', '* 예약제로 운영중입니다', '수요알~월요알 : 12:00~19:00', '0507-1361-6088', '매주 화요일'),
	(964, '희락갈치', '04528  서울 중구 남대문시장길 22-6 (남창동)', 'images/희락갈치_964.jpg', '남대문시장 갈치골목의 가장 오래된 터줏대감으로 매콤하면서도 달콤한 갈치조림\n\n남대문시장 갈치골목의 가장 오래된 터줏대감, 희락갈치는 매콤하면서도 달콤한 갈치조림으로 유명합니다. 큼직하게 썬 무와 함께 나오는 갈치조림은 오랜 장사의 노하우가 묻어나며, 밥 한 숟갈과 함께 먹으면 깊은 맛을 느낄 수 있습니다. 일행이 있다면 갈치조림과 함께 갈치구이를 시켜 나눠 먹는 것도 추천합니다. 푸짐한 양과 맛으로 식사하는 동안 만족감을 높일 수 있습니다.', 37.559903, 126.977077, '', '지하철 4호선 회현역 5번 출구, 221m', '갈치조림, 모듬생선구이', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '07:00 - 21:00', '-4124', '매주 일요일'),
	(965, '노랑통닭 서울상암점', '03930  서울 마포구 성암로15길 39 (상암동)  1층', 'images/노랑통닭_서울상암점_965.jpg', '마니아층이 두터운 한국의 치킨 브랜드로,  프랜차이즈 치킨 전문점.\n\n마니아층이 두터운 한국의 치킨 브랜드로, 서울 곳곳에서 만날 수 있는 프랜차이즈 치킨 전문점입니다. 가마솥에 튀겨 바삭한 치킨과 중독성 강한 마늘소스의 조화가 독특하며, 이 조화는 유일무이합니다. 한국의 기본 후라이드 치킨을 이미 경험했다면, 노랑통닭의 알싸한 마늘치킨에 도전해보는 것도 좋습니다. K-CHICKEN을 대표하는 메뉴 중 하나로, 깊은 맛과 풍미를 제공하는 치킨을 경험할 수 있습니다.', 37.577106, 126.896521, '', '지하철 6호선/공항철도/경의중앙선 디지털미디어시티역 9번 출구, 154m', '노랑통닭 콤보, 3종 세트', '', ' http://norangtongdak.co.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '17:00 - 24:00', '-10106', '일요일'),
	(966, '포틀러', '04778  서울 성동구 왕십리로 82-20 (성수동1가)', 'images/포틀러_966.png', '포틀랜드 감성을 담은 수제 디저트 스모어 전문 브랜드, 포틀러\n\n포틀러는 포틀랜드의 자연, 예술, 독특한 식문화를 담아낸 브랜드로, 자연 속 아웃도어 라이프를 즐기는 이들을 위해 시작된 소울 디저트입니다. 프리미엄 재료로 직접 만든 마시멜로, 크래커, 초콜릿으로 완성된 스모어는 가족, 친구, 연인과의 특별한 순간을 더욱 빛나게 합니다. 성수동 매장에서는 포틀랜드 바이브의 LP 음악과 스모어, 커피를 즐길 수 있으며, 크래커부터 마시멜로까지 수제로 만들어 아이들도 안심하고 먹을 수 있습니다. 반려동물 동반이 가능하며, 락토프리 펫 밀크와 퍼푸치노도 제공됩니다.', 37.544865, 127.045716, '', '지하철 수인분당선 서울숲역 1번 출구, 71m', '', '화 ~ 일', ' https://www.instagram.com/potler_seoul/', '카페, 디저트', '', '화 ~ 목 12:00 ~ 20:00\n금 ~ 토 12:00 ~ 23:00', '0507-1345-4600', '월'),
	(967, '앤더슨씨', '04782  서울 성동구 성수일로6길 36 1층', 'images/앤더슨씨_967.png', '빈티지 가구에 둘러싸인 여유롭고 고급스러운 카페\n\n한국 셀럽들도 즐겨 찾는 빈티지 가구 갤러리 Anderson C는, 거리 쪽의 카페 공간과 안쪽에 펼쳐진 갤러리 내 카페까지 두 가지 공간으로 구성되어 있습니다. 음료 한 잔만 주문하면, 감각적으로 전시된 방대한 빈티지 가구들이 가득한 갤러리 입장 티켓을 받을 수 있습니다.가구는 모두 오너의 뛰어난 안목으로 선택된 고급스러운 아이템들로만 구성되어 있습니다. 실제로 앉아보거나 만져보며 여유롭게 즐기는 카페 타임은, 인테리어를 좋아하는 이들에게 더없이 특별한 경험이 되어줍니다.', 37.544209, 127.053984, '', '지하철 2호선 성수역 4번출구, 178m', '', '', ' https://www.instagram.com/andersonc_design', '', '', '매일 11:00-18:00', '0507-1364-0865', ''),
	(968, '카페진정성 한강편 커피하우스', '07200  서울 영등포구 선유로 313 (당산동, 양화대교 전망카페)', 'images/카페진정성_한강편_커피하우스_968.png', '한강을 바라보며 티타임을 가질 수 있는 양화대교 위 카페\n\n김포 한강신도시의 작은 카페로 출발해 인천, 광주, 제주로 진출한 카페 진정성이 2024년  10월 양화대교 위에 들어섰습니다. \'진정성\'이라는 이름에 맞게 유기농 제품을 사용하며, 건강한 음료로 입소문이 난 곳입니다. 양화대교 남단에 들어선 카페 진정성은 동편의 티하우스와 서편의 커피하우스로 나뉩니다. 티하우스는 우리나라 전통 우전 녹차와 매장에서 직접 갈아낸 말차 등 바리스타가 직접 블렌딩해주며, 커피하우스는 시그니처 메뉴인 밀크티와 커피를 맛볼 수 있습니다.', 37.540119, 126.900869, '', '지하철 9호선 선유도역 4번출구, 885m', '', '', ' https://www.cafejinjungsung.com/', '', '양화한강공원 2주차장 또는 양화한강공원 1주차장을 이용해주세요.', '매일 10:00-21:00', '02-2633-9507', ''),
	(969, '우거데칸몽골레스토랑', '04561  서울 중구 마른내로 159 (광희동1가)  2층', 'images/우거데칸몽골레스토랑_969.jpg', '몽골 현지 음식을 재현한 맛으로 잘 알려져 있는 몽골 음식 전문점\n\n몽골 현지 음식을 재현한 맛으로 잘 알려져 있는 몽골 음식 전문점입니다. 몽골의 문화를 느낄 수 있는 인테리어는 마치 몽골에 온 듯한 착각을 불러일으킵니다. 시그니처 메뉴인 몽골식 만두 요리와 몽골식 볶음면은 가성비 좋은 가격대에 푸짐하게 제공됩니다. 진정한 몽골의 맛과 분위기를 동시에 즐길 수 있는 곳입니다.', 37.564823, 127.005748, '', '지하철 2/4/5호선 동대문역사문화공원역 7번 출구, 141m', '몽골만두, 몽골 볶음면', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00', '-6451', ''),
	(970, '강가 무교점', '04520  서울 중구 세종대로 136 (태평로1가, 파이낸스빌딩)', 'images/강가_무교점_970.jpg', '인도인도 인정할 만큼 정통성을 자랑하는 인도 음식 전문 레스토랑 프랜차이즈 식당.\n\n인도 현지 음식을 그대로 재현해, 인도인도 인정할 만큼 정통성을 자랑하는 인도 음식 전문 레스토랑 프랜차이즈 식당입니다. 서울 곳곳에서 만나볼 수 있으며, 인도 커리와 탄두리 치킨 등 다양한 인도 요리를 제공합니다. 인테리어 또한 인도의 분위기를 물씬 풍겨, 마치 현지에서 식사를 하는 듯한 느낌을 줍니다.', 37.568354, 126.978018, '', '지하철 5호선 광화문역 5번 출구, 169m', '탄두리 치킨, 치킨 마크니', '', ' http://www.instagram.com/ganga.official', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:30-21:30 (15:00-17:00 브레이크타임)', '-4313', ''),
	(971, '장위동유성집 용산서울역점', '04320  서울 용산구 한강대로 385 (동자동)  1층', 'images/장위동유성집_용산서울역점_971.jpg', '40년 전통의 장위동 유성집은 토종 한우만을 엄선하여 산지 직송.\n\n40년 전통의 장위동 유성집은 토종 한우만을 엄선하여 산지 직송으로 제공하는 프랜차이즈 식당입니다. 최고의 맛과 서비스를 유지하기 위해 끊임없이 노력하며, 특히 한우 등심과 함께 제공되는 별미 국수는 풍부한 맛의 조화를 자랑합니다. 깊고 진한 풍미와 뛰어난 품질 덕분에 한 번 맛보면 잊을 수 없는 식사의 즐거움을 선사하는 곳입니다.', 37.552804, 126.972249, '', '지하철 1/4호선/공항철도/경의중앙선/GTX-A 서울역 13번 출구, 28m', '한우등심, 별미국수', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:40 (21:10 라스트오더, 매주 일요일 휴무)\n토 12:00 - 21:00 (20:30 라스트오더)', '-11119', ''),
	(972, 'BBQ치킨앤비어 명동스타점', '04536  서울 중구 명동4길 2 (명동2가)  2층', 'images/BBQ치킨앤비어_명동스타점_972.jpg', 'Best of the Best Quality를 뜻하는 BBQ는 대한민국을 대표하는 치킨 브랜드\n\nBest of the Best Quality를 뜻하는 BBQ는 대한민국을 대표하는 치킨 브랜드 중 하나입니다. 한국 드라마에서 자주 보던 그 치킨집을 찾는다면 단연 BBQ가 제격입니다. 신선한 올리브유에서 튀겨낸 황금올리브치킨은 부동의 1위 메뉴로, 바삭하고 풍부한 튀김옷이 일품입니다. BBQ의 치킨은 독특한 풍미와 식감으로 어디에서도 찾아볼 수 없는 특별한 맛을 자랑합니다.', 37.563450, 126.983438, '', '지하철 4호선 명동역 7번 출구, 400m', '황금올리브치킨, 단짠갈릭', '', ' https://bbq.co.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 24:00', '-9047', ''),
	(973, '삼미정', '04545  서울 중구 을지로19길 32-6 (산림동)', 'images/삼미정_973.jpg', '노포 야장 분위기의 을지로 삼겹살 맛집\n\n노포 야장 분위기로 유명한 을지로의 낡은 건물 사이에 위치해 있는 삼미정은 내부 외부로 나눠져있는데 야장 분위기를 느끼기 위해 외부에 자리를 잡는 고객들이 대부분입니다. 메인 메뉴는 삼겹살 단일 메뉴이며, 된장찌개와 볶음밥을 추가할 수 있습니다. 을지로 야장 삼겹살 운영 가게 중 유일하게 볶음밥 히든 메뉴가 있는 곳이라 삽겹살을 먹은 후 추가로 드셔보길 추천합니다. 을지로 핫플로 웨이팅이 있습니다.', 37.568022, 126.995909, '', '지하철 2호선/5호선 을지로4가역 1번출구, 343m', '', '', '', '', '', '매일 11:00-21:30', '', ''),
	(974, '물고기자리 상암점', '03930  서울 마포구 월드컵북로48길 14-6 (상암동)  1층', 'images/물고기자리_상암점_974.jpg', '최상급 생선만을 취급하는 식당으로, 숙성회가  일품\n\n최상급 생선만을 취급하는 식당으로, 숙성회는 숙성 과정을 거쳐 쫀득하고 찰진 식감이 일품입니다. 숙성회 모듬은 1인분부터 판매하여 혼자 방문해도 부담이 없습니다. 회를 모두 즐긴 후에는 매운탕에 라면과 떡사리를 추가해 마무리하는 것이 이곳의 추천 코스입니다.', 37.576647, 126.894656, '', '지하철 6호선 /공항철도/경의중앙선 디지털미디어시티역 9번 출구, 318m', '숙성회모듬, 매운탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '16:30 - 23:00', '-8400', '매주 일요일'),
	(975, '카페 그레이랩', '04083  서울 마포구 토정로3길 16 (합정동)', 'images/카페_그레이랩_975.jpg', '벚꽃시즌, 벚꽃 아래서 커피를 마실 수 있는 SNS에서 핫한 합정 카페\n\n합정에 위치한 그레이랩은 서울 벚꽃카페로 유명한 핫플레이스로 봄 시즌이되면 테라스에서 벚꽃뷰와 함께 커피뿐만 아니라 다양함 음료와 디저트를 즐길 수 있습니다. 특히 2층 포토존에서 벚꽃과 함께 사진 한 컷은 필수로 추천합니다. 벚꽃 명소인 만큼 원할한 이용을 위해 한 팀당 2시간 이내로 이용하는 시간 제한이 있습니다.', 37.546284, 126.914442, '', '지하철 2/6호선 합정역 7번출구 300m', '', '매일', '', '카페, 디저트', '', '월-일 10:00-22:00', '02-333-5694', ''),
	(976, '해목 논현점', '06055  서울 강남구 선릉로145길 14 (논현동)', 'images/해목_논현점_976.jpg', '부산에서 유래된 장어덮밥의 진수를 맛볼 수 있는 식당\n\n부산에서 유래된 장어덮밥의 진수를 맛볼 수 있는 식당입니다. 외관과 음식 플레이팅 모두 일본 분위기를 충실히 재현하여, 마치 일본에 온 듯한 착각을 불러일으킵니다. 장어는 일본 전통 방식으로 구워 부드럽고 풍미 가득하며, 간이 세지 않아 끝까지 맛있게 즐길 수 있습니다. 일본식 정통 장어덮밥을 원한다면, 이곳에서 진정한 일본의 맛을 경험해보길 추천합니다.', 37.521531, 127.038296, '', '지하철 7호선/수인분당선 강남구청역 3-1번 출구, 600m', '특 히츠마부시, 히츠마부시', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (15:00 - 17:00 브레이크타임, 21:00 라스트오더)', '-2168', ''),
	(977, '한정선 (韓貞仙)', '04782  서울 성동구 연무장길 43-1 1층', 'images/한정선_(韓貞仙)_977.jpg', '줄서서 포장해서 먹는 생과일 찹쌀떡 디저트 맛집\n\n쫀득쫀득한 찹쌀떡 안에 생과일이 들어있어 겉은 쫀득, 속은 상큼달콤한 디저트입니다. 생과일 이외에도 홍시, 앙버터, 두바이 스타일의 찹쌀떡을 만나볼 수 있습니다. 포장 전문 매장이라 앉아서 먹을 수 있는 테이블은 없으며, 웨이팅은 있지만 회전이 빠른편입니다. 들어온 복을 담는 의미로 복주머니 느낌의 포장은 선물용으로 구매하기에도 좋습니다.', 37.542931, 127.054178, '', '지하철 2호선 성수역 4번출구, 243m', '', '', ' https://www.instagram.com/han.jung.sun/', '', '', '매일 10:30-22:00', '', ''),
	(978, '아빠호떡', '04528  서울 중구 남대문시장2가길 6-8 (남창동)', 'images/아빠호떡_978.png', '남대문에서 오랜 전통의 아궁이 호떡을 만드는 담백한 맛의 호떡집\n\n아빠호떡은 1972년부터 오랜 전통을 자랑하며 많은 사람들에게 사랑받아온 호떡 전문점입니다. 이곳의 가장 큰 특징은 일반적인 불판이 아닌 아궁이 형식의 기기에서 호떡을 구워내어 기름기 없이 담백한 맛을 선사한다는 점입니다. 특히 아궁이 호떡은 바게트의 겉부분처럼 쫄깃한 식감과 고소한 맛이 매력적이며, 꿀호떡은 반죽이 조금 더 촉촉하여 부드럽고 빵 같은 식감을 자랑합니다.\n\n이곳은 KBS2TV의 인기 프로그램 ‘신상출시 편스토랑’에서 개그우먼 이영자가 방문해 화제가 되었고, 방송 이후 더욱 많은 이들의 발길을 끌고 있습니다. 방송을 통해 소개된 뒤에도 단순한 인기뿐 아니라 오랜 세월 이어져온 전통과 맛으로 꾸준히 사랑받는 명소로 자리 잡았습니다.\n\n아궁이에서 구워내는 독특한 조리 방식 덕분에 기름진 맛 없이 깔끔한 풍미를 느낄 수 있으며, 두 가지 메뉴 모두 각자의 매력을 지니고 있어 다양한 취향을 만족시킵니다. 담백하면서도 고소한 맛을 좋아하는 이들에게 특히 추천할 만한 곳입니다. 50년이 넘는 역사가 녹아 있는 아빠호떡은 담백한 맛과 정겨운 전통의 조화를 느끼고 싶은 사람들에게 특별한 경험을 선사합니다.', 37.559189, 126.976822, '', '지하철 4호선 회현역 5번 출구, 148m', '', '월 ~ 토', '', '음식점', '', '10:30 ~ 재료소진시까지\n* 첫 호떡은 11시 판매', '', '일'),
	(979, '신진도간장게장', '03995  서울 마포구 월드컵북로2길 41 (동교동)', 'images/신진도간장게장_979.jpg', '푸짐한 양에 짜지 않은 맛으로 외국인들이 많이 찾는 간장게장 식당\n\n푸짐한 양에 짜지 않은 맛으로 외국인들이 많이 찾는 간장게장 식당입니다. 정식을 주문하면 게국지와 계란찜, 각종 반찬까지 든든한 한 끼를 맛볼 수 있습니다. 자연산 꽃게탕도 얼큰한 국물에 속이 꽉 찬 게살이 일품입니다. 여럿이 방문한다면 게장과 꽃게탕을 함께 주문해보세요.', 37.557032, 126.922791, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 1번 출구, 101m', '간장게장정식, 자연산꽃게탕(중)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (15:00 - 17:00 브레이크타임)', '-1471', ''),
	(980, '에베레스트 레스토랑 동대문점', '03105  서울 종로구 종로51가길 2-1 (창신동)', 'images/에베레스트_레스토랑_동대문점_980.jpg', '네팔 부부가 운영하는 이 네팔 음식 전문점.\n\n네팔 부부가 운영하는 이 네팔 음식 전문점은 다양한 향신료로 발효한 치킨을 탄두리에서 익혀낸 치킨 티카와, 치즈, 크림, 토마토를 넣어 만든 치킨 마크니 커리가 인기 메뉴입니다. 이곳은 다양한 조리 방식의 네팔 요리를 제공하며, 그 독특한 맛으로 유명한 곳입니다.', 37.572570, 127.012504, '', '지하철 1/4호선 동대문역 3번 출구, 98m', '탄두리 치킨, 치킨 마크니', '', ' http://www.everestfood.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-9536', ''),
	(981, '이드', '04405  서울 용산구 우사단로10길 15 (이태원동)  1층', 'images/이드_981.jpg', '할랄 한식당으로, 전통 한식을 할랄 방식으로 제공.\n\n할랄 한식당으로, 전통 한식을 할랄 방식으로 제공하여 무슬림 관광객들 사이에서 꾸준히 인기를 끌고 있는 곳입니다. 특히 삼계탕, 비빔밥, 소불고기 등 다양한 한식 메뉴와 제철 음식을 시기에 맞춰 선보입니다. 가성비가 뛰어나 가격 부담 없이 한식을 즐길 수 있으며, 후식으로는 오미자차와 매실차가 준비되어 있어 식사를 상큼하게 마무리할 수 있습니다.', 37.533264, 126.996418, '', '지하철 6호선 이태원역 3번 출구, 361m', '비빔밥, 소불고기', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '12:00 - 21:00', '-17097', ''),
	(982, '북앤레스트', '06166  서울 강남구 삼성로104길 22 예림빌딩 1층', 'images/북앤레스트_982.png', '도심 속에서 책을 통한 쉼의 시작, 프라이빗한 공간까지 제공하는 북카페\n\n사람들마다 다른 쉼의 모습에 따라 스테이존,레스트존,프라이빗룸으로 공간을 나누어 각자가 원하는 방법으로 편하게 시간을 보낼 수 있도록 공간에 힘을 주었습니다. 1인실 프라이빗 룸은 시간제로 운영되어 조용히 나만의 공간에서 휴식을 취하거나 업무 또는 회의를 할 수 있습니다. 해당 공간 이용 시 시간당 추가 비용 별도 발생됩니다.', 37.510941, 127.056586, '', '지하철 9호선 삼성중앙역 5번출구, 395m', '', '', ' https://www.instagram.com/booknrest', '카페, 디저트', '', '월-금 7:30-21:00 / 토,일 12:00-20:00', '0507-1341-2356', ''),
	(983, '파일드', '02582  서울 동대문구 천호대로7길 17 (신설동)  1층', 'images/파일드_983.png', '깊은 맛의 에스프레소와 화사한 향미의 필터커피, 감각적인 인테리어, 디저트로 특별한 커피 경험을 제공하는 카페\n\n신설동역 인근에 위치한 카페 파일드는 고소하고 진한 맛의 에스프레소 음료와 밝고 화사한 향미가 돋보이는 필터커피를 제공하는 곳입니다. 에스프레소 기반 음료는 강배전 원두로 깊은 여운을 남기며, 필터커피는 붉은 과일, 베르가못, 라벤더의 향미를 중심으로 주기적으로 새로운 라인업을 선보이고 있습니다. 인스타그램을 통해 원두 정보를 확인할 수 있으며, 커피와 어울리는 맛있는 디저트도 준비되어 있습니다. 우드와 플랜트를 활용한 개성 있는 인테리어가 감각적인 분위기를 더해주는 공간입니다.', 37.574784, 127.027681, '', '지하철 1 / 2호선 / 우이신설 신설동역 8번 출구, 204m', '', '월 ~ 토', ' https://www.instagram.com/piled.coffee', '카페, 디저트', '', '월 - 금 8:00~17:30\n토 , 공휴일 10:00~19:00', '0507-1376-7246', '일'),
	(984, '사프란 레스토랑', '04542  서울 중구 삼일대로 362 (장교동, 롯데시티호텔 명동)  롯데시티호텔명동 2F', 'images/사프란_레스토랑_984.jpg', '이슬람 율법에 따라 도축한 고기만을 사용하는 아랍 음식 전문점. 고급스럽고 화려한 인테리어. 미자나, 치킨 한디 등 특색 있는 할랄 음식을 선보여, 전통 아랍의 풍미를 경험.\n\n이슬람 율법에 따라 도축한 고기만을 사용하는 아랍 음식 전문점입니다. 고급스럽고 화려한 인테리어로 세련된 분위기를 자아내며, 특별한 식사 시간을 선사합니다. 미자나, 치킨 한디 등 특색 있는 할랄 음식을 선보여, 전통 아랍의 풍미를 경험할 수 있습니다. 소중한 사람과 함께 특별한 시간을 보내고 싶을 때, 정갈한 분위기와 맛있는 음식이 어우러지는 이곳을 방문해 보세요.', 37.566949, 126.988088, '', '지하철 2 / 3호선 을지로3가역 1번 출구, 169m', '미자, 사프란 특선 모듬케밥', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:30 - 22:30 (21:30 라스트오더)', '-10408', ''),
	(986, '생곱창집 상암직영점', '03927  서울 마포구 매봉산로2길 15 (상암동, 효인빌딩)  1층', 'images/생곱창집_상암직영점_986.jpg', '초벌 없이 신선한 생 곱창구이를 즐길 수 있는 흔치 않은 곱창 전문점\n\n초벌 없이 신선한 생 곱창구이를 즐길 수 있는 흔치 않은 곱창 전문점이다. 직접 손질한 소곱창을 사용해 잡내 없이 깔끔하고 고소한 맛을 자랑하며, 특히 곱창구이는 철판에서 직접 구워내, 바삭하면서도 속은 촉촉한 식감이 일품이다. 소곱창 애호가들 사이에서는 상암동에서 가장 맛있는 소곱창 집으로 손꼽히며, 양도 푸짐하여 든든하게 배를 채울 수 있다.', 37.578527, 126.894978, '', '지하철 6호선/공항철도/경의중앙선 디지털미디어시티역 9번 출구, 263m', '생곱창구이(200g, 1인), 모듬구이(200g, 1인)', '', ' https://www.instagram.com/sa_realgob', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '15:00 - 23:00 (22:00 라스트오더, 매주 일요일 휴무)', '-11219', ''),
	(987, '유목민몽골', '04561  서울 중구 을지로44길 19 (광희동1가)', 'images/유목민몽골_987.jpg', '몽골의 로컬푸드를 즐기고 싶다면 몽골 전통 요리 음식점 유목민 몽골\n\n몽골의 로컬푸드를 즐기고 싶다면 몽골 전통 요리 음식점인 이곳이 제격입니다. 몽골식 요리뿐만 아니라 게르를 연상케 하는 인테리어로 몽골 여행을 온 듯한 경험을 제공합니다. 대표 메뉴로는 나담(몽골식 바비큐)과 호쇼르(몽골식 만두)가 있으며, 이 외에도 다양한 몽골 전통 요리를 맛볼 수 있습니다. 가격대가 저렴해 부담 없이 다양한 요리를 주문해 맛볼 수 있으며, 몽골의 정통 맛을 경험할 수 있는 좋은 기회를 제공합니다.', 37.565189, 127.006567, '', '지하철 2/4/5호선 동대문역사문화공원역 8번 출구, 136m', '나담 튀김만두(3개), 저친 호쇼르', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00', '-8858', ''),
	(988, '한국집(롯데월드몰점)', '05551  서울 송파구 올림픽로 300 (신천동, 롯데월드타워앤드롯데월드몰)  5층', 'images/한국집(롯데월드몰점)_988.jpg', '전주에서 유명한 전주 비빔밥 전문점의 서울 지점\n\n전주에서 유명한 전주 비빔밥 전문점의 서울 지점입니다. 전주까지 가지 않아도 전주식 비빔밥을 맛볼 수 있어 많은 관광객들이 찾는 곳입니다. 대표 메뉴로는 미리 비벼 나오는 전주식 비빔밥과 육회가 곁들여진 육회비빔밥이 있습니다. 롯데월드몰 안에 위치해 찾기 쉽고, 쾌적한 분위기에서 식사를 즐길 수 있습니다.', 37.513713, 127.104302, '', '지하철 2/8호선 잠실역 10번 출구, 330m', '육회비빔밥, 전주비빔밥', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:30 - 22:00', '-6418', ''),
	(989, '비건키친', '04629  서울 중구 퇴계로20길 21 (남산동2가)  1층', 'images/비건키친_989.jpg', '서울에서 유명한 비건 레스토랑\n\n서울에서 유명한 비건 레스토랑 중 하나로, 여행 중 비건이 동행한다면 꼭 방문할 만한 곳입니다. 특히 비건 한식 메뉴로는 담백하고 맛있는 잡채와 철판에서 직접 조리한 순두부덮밥이 인기 메뉴입니다. 잡채는 다양한 채소와 버섯이 조화를 이루며, 철판순두부덮밥은 깊은 맛과 풍미를 자랑합니다. 이곳에서 비건 식사를 즐기며 건강한 한 끼를 경험해 보는 것을 추천합니다.', 37.559260, 126.985976, '', '지하철 4호선 명동역 3번 출구, 189m', '아보카도 포케, 치킨 포케', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:30 - 22:00 (21:30 라스트오더)', '-9516', ''),
	(990, '인생횟집 종각본점', '03189  서울 종로구 우정국로2길 29 (관철동)', 'images/인생횟집_종각본점_990.jpg', '신선한 해산물을 모둠. 서더리탕에 라면과 수제비 사리를 넣어 마무리.\n\n신선한 해산물을 모둠으로 다양하게 먹을 수 있습니다. 회를 다 먹고 나면 서더리탕에 라면과 수제비 사리를 넣어 마무리하면 좋습니다. 서더리탕은 회를 먹은 후 육수에 다양한 재료를 넣어 끓인 해물탕으로, 깊고 진한 맛이 특징입니다.', 37.569670, 126.984637, '', '지하철 1호선 종각역 4번 출구, 112m', '모듬회, 막회 물회', '', ' https://blog.naver.com/min53545', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 05:00', '-6006', ''),
	(991, '소문난성수감자탕', '04782  서울 성동구 연무장길 45 (성수동2가)', 'images/소문난성수감자탕_991.jpg', '푸짐한 양과 기본에 충실한 맛을 느낄 수 있는 성수 감자탕집\n\n식당 내부는 2곳으로 운영되어 자리는 많지만 웨이팅 있는 맛집으로 번호표나 대기표가 없어 대기석에 앉아 있으면 순서대로 안내합니다. 혼밥이 가능한 좌석이 따로 마련되어 있어 혼자인 경우 줄 서지 않고 바로 카운더로 가서 자리를 받을 수 있습니다. 연중무휴 24시간 영업이라 언제든지 식사를 할 수 있으며, 포장도 가능합니다.', 37.542883, 127.054408, '', '지하철 2호선 성수역 4번출구, 229m', '', '', '', '', '웨이팅 유의사항 : 일행 모두 오셔야 입장 가능\n식당 주차 가능 (차량 관리비 2,000원 ※식사시간만 사용가능) 또는 공영주차장 사용', '매일 00:00 - 24:00', '02-465-6580', ''),
	(992, '풍조미역 성수본점', '04794  서울 성동구 성수일로8길 60 (성수동2가)  1층', 'images/풍조미역_성수본점_992.jpg', '대표 메뉴인 미역국은 진하고 깊은 맛의 국물과 신선한 미역이 특징\n\n대표 메뉴인 미역국은 진하고 깊은 맛의 국물과 신선한 미역이 특징으로, 풍부한 미역의 맛과 쇠고기나 멸치로 우린 국물의 깊은 풍미가 식사에 든든함을 더합니다. 고소하고 담백한 맛으로 다양한 취향의 사람들에게 인기가 높으며, 특히 건강식으로 널리 사랑받습니다. 미역국은 전통 한식의 정수를 느낄 수 있는 메뉴로, 낯선 외국인 관광객도 부담 없이 즐길 수 있습니다.', 37.544875, 127.056818, '', '지하철 2호선 성수역 2번 출구, 80m', '가자미미역국, 미주구리물회', '', ' https://www.instagram.com/pungjo_seongsu', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00 (22:00 라스트오더),\n토 - 일 11:30 - 22:00 (21:00 라스트오더)', '-8559', ''),
	(993, '우월소곱창 마포직영점', '04157  서울 마포구 마포대로 73 (도화동, 에스케이허브그린)  1층', 'images/우월소곱창_마포직영점_993.jpg', '맛있는 곱창과 유명한 마늘통곱창\n\n곱창구이는 한국의 인기 있는 고기 요리로, 특히 소곱창을 구워서 즐기는 것이 특징입니다. 꽉 차고 부드러운 마늘곱창을 제공하며, 쾌적하고 청결한 공간에서 식사를 즐길 수 있습니다. 궁합 좋은 사이드 메뉴와 함께 곱창의 풍부한 맛을 더욱 잘 느낄 수 있습니다. 다양한 방송에 소개되어 늘 손님으로 붐비는 인기 있는 곳입니다.', 37.542323, 126.948978, '', '지하철 5/6호선/공항철도/경의중앙선 공덕역 1번 출구, 225m', '수제한우마늘곱창\n오색볶음밥', '', ' http://pf.kakao.com/_uWUaG', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '14:30 - 23:00 (22:00 라스트오더)', '-4149', ''),
	(995, '육전국밥 대학로점', '03086  서울 종로구 동숭길 117 (동숭동, 한석빌딩)  3층', 'images/육전국밥_대학로점_995.jpg', '소고기 국밥, 곰탕, 막국수, 1인 육전이 포함된 정식\n\n서울 곳곳에 자리한 인기 프랜차이즈 식당으로, 부담 없이 맛있는 한 끼를 즐기기 좋은 곳입니다. 국밥과 막국수 같은 든든한 메뉴뿐만 아니라, 얇게 썬 고기를 계란 반죽에 살짝 입혀 노릇하게 구운 육전을 활용한 다양한 요리가 이곳의 자랑입니다. 특히, 육전은 바삭하면서도 부드러운 식감으로 많은 사랑을 받고 있습니다.', 37.583162, 127.003475, '', '지하철 4호선 혜화역 1번 출구, 194m', '육전국밥, 육전비빔막국수', '', ' https://yukjeonuniv.jalib.site/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:30', '-2797', ''),
	(996, '케르반 코엑스몰점', '06164  서울 강남구 봉은사로 524   코엑스몰 B1 H105', 'images/케르반_코엑스몰점_996.jpg', '전통 방식으로 튀르키예 음식을 선보이는 곳, 진정한 튀르키예의 맛을 경험.\n\n전통 방식으로 튀르키예 음식을 선보이는 곳으로, 진정한 튀르키예의 맛을 경험할 수 있는 장소입니다. 셰프들 모두 튀르키예 출신으로, 현지의 정통 요리를 그대로 재현해 마치 튀르키예를 여행하는 듯한 느낌을 줍니다. 정성 가득한 요리들이 준비되어 있으며, 다양한 메뉴를 주문해 튀르키예의 다채로운 맛을 즐겨보세요.', 37.512953, 127.057116, '', '지하철 9호선 봉은사역 7번 출구 9m', '치킨 스테이크, 리치 피데', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 22:00 (15:00 - 16:30 브레이크타임)', '-6518', ''),
	(997, '트로이 케밥', '06129  서울 강남구 테헤란로1길 16 (역삼동)', 'images/트로이_케밥_997.jpg', '튀르키예 현지인이 운영하는 정통 튀르키예 케밥 전문 음식점\n\n튀르키예 현지인이 운영하는 정통 튀르키예 케밥 전문 음식점입니다. 토르티야에 싸서 먹는 케밥부터 라이스 케밥까지 다양한 종류의 케밥을 선보이며, 메뉴를 선택하는 재미도 있습니다. 맵기 조절이 가능해 매운 맛을 선호하는 경우 셰프에게 별도 요청도 가능합니다. 양이 푸짐한 데다 가격도 합리적이어서 더욱 만족스럽습니다.', 37.499433, 127.027938, '', '지하철 2호선 /신분당선 강남역 11번 출구, 105m', '닭고기 케밥', '', ' https://www.instagram.com/', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '10:00 - 03:00', '-8660', ''),
	(998, '갯벌의조개', '08807  서울 관악구 남현1길 68-6 (남현동)', 'images/갯벌의조개_998.jpg', '비주얼로 압도당할 만큼 화려한 조개전골이 대표 메뉴\n\n비주얼로 압도당할 만큼 화려한 조개전골이 대표 메뉴인 이곳은, 인원수에 따라 주문할 수 있는 대왕조개전골이 특징입니다. 해물육수와 얼큰해물육수 두 가지 육수 맛 중에서 선택할 수 있으며, 시원한 맛을 원하면 해물육수를, 매콤하면서도 깊은 맛을 원하면 얼큰해물육수를 추천합니다. 찾기 쉬운 위치에 자리 잡고 있어, 맛있는 조개전골을 간편하게 즐길 수 있는 곳입니다.', 37.475548, 126.981087, '', '지하철 2/4호선 사당역 5번 출구, 110m', '대왕조개전골', '', ' https://www.instagram.com/getbeoljogae_official/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '월~금 14:00~22:30\n토~일 11:30 - 22:30', '-4784', ''),
	(999, '바다회사랑', '03990  서울 마포구 동교로27길 60 (연남동)', 'images/바다회사랑_999.jpg', '싱싱하고 두툼한 방어회로 유명한 집.\n\n싱싱하고 두툼한 방어회로 유명한 집입니다. 방어는 지방이 풍부하고 고소한 맛이 특징이며, 입안에서 살살 녹는 식감이 일품입니다. 여름철에는 민어회가 인기인데, 민어는 담백하면서도 부드러운 식감과 깔끔한 맛이 특징입니다. 가을에는 전어회와 생새우회도 즐길 수 있으며, 전어는 쫄깃하고 고소하며, 생새우는 신선하고 단맛이 살아 있는 식감이 일품입니다.', 37.560415, 126.921061, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 2번 출구, 539m', '광어', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '15:00 - 23:00', '-1130', ''),
	(1000, '송정민물장어구이', '04561  서울 중구 을지로38길 11 (광희동1가)', 'images/송정민물장어구이_1000.jpg', '오래된 노포로 비법 간장소스로 구워내는 장어가 대표 메뉴.\n\n오래된 노포의 외관과 단조로운 메뉴판이 신뢰를 주는 이곳은 비법 간장소스로 구워내는 장어가 대표 메뉴입니다. 장어는 촉촉하면서도 달큰한 맛으로 많은 이들의 사랑을 받고 있으며, 기력 회복에 특히 좋습니다. 또한, 장어와 함께 곁들이기 좋은 불향이 가득한 쭈꾸미 볶음도 강력히 추천합니다. 쭈꾸미 볶음의 매콤하고 고소한 맛이 장어와 잘 어울려 식사의 만족도를 높입니다.', 37.566065, 127.003856, '', '지하철 2/4/5호선 동대문역사문화공원역 7번 출구, 196m', '장어한마리, 장어정식', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:00', '-2780', ''),
	(1001, '문래포차1422', '07290  서울 영등포구 도림로137길 3 1층, 옥상층', 'images/문래포차1422_1001.jpg', '중식경력만 30년 이상, 문래동 공장 사장님들이 인정한 안주 맛집\n\n루프탑 포차로 유명한 문래포차1422는 루프탑에서 야장의 낭만을 즐길 수 있습니다. 중식경력만 30년 이상 있는 주방장의 중식 뿐만 아니라 다양한 메뉴를 맛볼 수 있습니다. 키오스크 선결제 시스템으로 운영되어, 인원수에 맞는 테이블 선택해 앉고 테이블 번호로 키오스크 결제 후 주문한 술, 음료, 가스버너, 테이블세팅은 셀프로 챙기는 방식입니다.', 37.514147, 126.894156, '', '지하철 2호선 문래역 7번출구, 487m', '', '', '', '', '', '매일 15:00-02:00', '0507-1428-1434', ''),
	(1002, '오리마당', '04525  서울 중구 세종대로 92 (태평로2가, 한화금융센터 태평로)', 'images/오리마당_1002.jpg', '오리훈제는 정성스럽게 훈제하여 부드럽고 고소한 맛을 자랑\n\n오리훈제는 정성스럽게 훈제하여 부드럽고 고소한 맛을 자랑하며, 찰밥찜은 쫄깃하면서도 풍미가 가득한 찰진 밥과 함께 제공합니다. 또한, 진한 국물 맛의 오리탕은 영양가가 높아 별미 음식이자 보양식으로 분류합니다. 오리 요리를 맛보고 싶을 때, 이곳에서 다양한 오리 요리의 풍미를 경험해 보는 것을 추천합니다.', 37.564233, 126.977572, '', '지하철 1/2호선 시청역 7번 출구, 4m', '오리훈제찰밥찜, 능이한방오리백숙', '', ' http://www.foodsidae.com/orimadang', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-11493', '매주 일요일'),
	(1003, '탄두르', '04561  서울 중구 을지로42길 15 (광희동1가)', 'images/탄두르_1003.jpg', '우즈베키스탄 레스토랑으로, 화덕에서 구워내는 솜사와 샤슬릭.\n\n동대문 중앙아시아 거리에 위치한 우즈베키스탄 레스토랑으로, 화덕에서 구워내는 솜사와 샤슬릭의 비주얼이 매우 먹음직스럽습니다. 솜사는 양고기와 다양한 채소를 함께 구워내는 우즈베키스탄식 만두로, 화덕에서 조리하여 육즙이 가득하고 향긋한 맛이 일품입니다. 샤슬릭은 양념에 재운 고기를 화덕에서 구워내는 전통 몽골식 꼬치 요리로, 겉은 바삭하고 속은 부드러우며 풍미가 깊습니다.', 37.565507, 127.005857, '', '지하철 2/4/5호선 동대문역사문화공원역 12번 출구, 228m', '감자 솜사, 우즈벨 필라프, 양고기 샤슬릭', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 22:00 (21:05 라스트오더)', '', ''),
	(1004, '팔각도 성수역점', '04794  서울 성동구 성수일로8길 53 (성수동2가, 성수동복합시설)  성수동복합시설 1층 105호, 106호', 'images/팔각도_성수역점_1004.jpg', '숯불 닭갈비가 기본 메뉴인 이 프랜차이즈 식당\n\n숯불 닭갈비가 기본 메뉴인 이 프랜차이즈 식당은 특히 닭목살 요리로 주목받았습니다. \n\n닭갈비는 숯불에서 구워 풍부한 숯향과 함께 겉은 바삭하고 속은 촉촉한 식감을 자랑합니다. 매콤달콤한 양념이 잘 배어 있어 식사에 풍미를 더합니다. 특히 닭목살은 일반 닭갈비보다 더 부드럽고 육즙이 가득해 한층 더 맛있습니다. 직원이 직접 고기를 구워주는 서비스 덕분에 관광객들도 걱정 없이 편안하게 즐길 수 있습니다.', 37.545284, 127.056450, '', '지하철 2호선 성수역 1번 출구, 155m', '숯불 닭갈비, 쫄깃쫄깃 닭 목살', '', ' https://8gakdo.co.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 22:30 (21:30 라스트오더)', '-8916', ''),
	(1005, '쓰윗 Thweet', '04782  서울 성동구 연무장3길 12 B1층', 'images/쓰윗_Thweet_1005.jpg', '어른들을 위한 쓰고 달콤한 프리미엄 위스키 아이스크림바\n\n쓰윗(Thweet)은 커피는 가볍고, 낮술을 부담될 때 어른들을 위한 감도 높은 디저트 공간입니다. 위스키가 들어간 프리미엄 아이스크림과 다양한 디저트를 고급스러운 분위기의 아이스크림바에서 즐겨볼 수 있습니다. 색다른 디저트를 맛보고 싶다면 방문해보길 추천하며, 디저트 아이스크림바이지만 시그니처 메뉴가 위스키 아이스크림인 만큼 성인만 입장 가능합니다.', 37.544655, 127.051779, '', '지하철 2호선 성수역 4번출구, 378m', '', '', ' https://www.instagram.com/thweet19', '', '', '12:00-24:00', '070-4099-7408', '매주 월요일'),
	(1006, '박소베조 명동', '04629  서울 중구 퇴계로20길 21 (남산동2가)  2층', 'images/박소베조_명동_1006.png', '인도네시아 음식 전문점으로 한국에서 진정한 인도네시아 음식을 경험\n\n인도네시아 음식 전문점으로 한국에서 진정한 인도네시아 음식을 경험할 수 있는 곳입니다. 인도네시아의 전통 요리를 충실히 재현하여, 향을 맡는 것만으로도 묘하게 익숙한 맛을 느낄 수 있습니다. 이름만으로는 상상하기 어려운 독특한 메뉴들이 기다리고 있으며, 색다른 미식 경험을 원하는 이들에게 추천합니다.', 37.559260, 126.985976, '', '지하철 4호선 명동역 3번 출구, 189m', '렌당, 오승 머콘', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '12:00 - 20:00 (19:40 라스트오더)', '-4651', ''),
	(1007, '도야집', '04382  서울 용산구 한강대로52길 27 (한강로1가)', 'images/도야집_1007.jpg', '돼지고기를 제대로 즐길 수 있는 용산 돼지고기 전문점\n\n40년 넘게 가정집이었던 공간에 돼지고기전문점을 만들고, 돼지의 옛말인 도야지 와 가정집을 합쳐 \'도야집\'이라 이름지었습니다. 용산 삼겹살 맛집이지만 도야집 대표 메뉴는 뼈오겹살과 목살이며 육즙 가득찬 고기의 본연의 맛을 함께 느껴보시길 바랍니다. 단품으로 부위별 주문도 가능하며, 콜키지(유료) 가능합니다.', 37.531805, 126.972633, '', '지하철 4호선/6호선 삼각지역 3번출구, 256m', '', '', ' https://www.instagram.com/doyajib_', '', '매장 출입구 앞에 1대 주차 가능(무료),\n이용중이라면 삼각지임시공영주차장(유료)을 이용해주세요.', '월-금 11:30-22:00 / 14:50-16:30 브레이크타임 / 14:10, 20:50 라스트오더\n토,일 12:00-22:00 / 20:50 라스트오더', '0507-1335-8521', ''),
	(1008, '사찰음식 전문점 발우공양', '03145  서울 종로구 우정국로 56 (견지동)  템플스테이 통합정보센터 5층', 'images/사찰음식_전문점_발우공양_1008.jpg', '전통적인 조리법으로 사찰음식의 원형을 그대로 간직한 요리\n\n전통적인 조리법으로 사찰음식의 원형을 그대로 간직한 요리를 선보이며, 사찰음식의 깊은 전통과 문화를 체험할 수 있습니다. 다양한 색깔의 재료들이 정갈하게 준비되어 있으며, 각 요리에는 정성과 섬세함이 담겨 있습니다. 이러한 식사는 먹는 이로 하여금 자연스럽게 마음이 차분해지고 경건해지는 경험을 선사합니다.', 37.573936, 126.983186, '', '지하철 1호선 종각역 3-1번출구, 300m\n지하철 3호선 안국역 6번출구, 250m', '선식, 원식', '', ' http://balwoo.or.kr/', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:30-21:00 (15:00-18:00 브레이크타임, 19:40 라스트오더)', '02-733-2081', ''),
	(1009, '빵 어니스타 이태원점', '04391  서울 용산구 보광로55길 3 (이태원동)  1층, 2층', 'images/빵_어니스타_이태원점_1009.jpg', '비건을 위한 디저트 카페로, 비건 전용 빙수를 판매하여 비건들의 마음을 사로잡고 있다. 특히 제철 과일을 활용한 무화과 빙수가 가장 인기 많다, 이외에도 비건 발로나 초코 떠먹케, 비건 넛츠 초코칩 쿠키 등 다양한 비건 디저트를 선보이고 있다. 비건 디저트를 찾는 이들이 꼭 가봐야 할 장소다.\n\n비건을 위한 디저트 카페로, 비건 전용 빙수를 판매하여 비건들의 마음을 사로잡고 있다. 특히 제철 과일을 활용한 무화과 빙수가 가장 인기 많다, 이외에도 비건 발로나 초코 떠먹케, 비건 넛츠 초코칩 쿠키 등 다양한 비건 디저트를 선보이고 있다. 비건 디저트를 찾는 이들이 꼭 가봐야 할 장소다.', 37.532984, 126.994127, '', '', '비건 무화과빙수, 비건 발로나초코 떠먹케', '', '', '', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '12:00 - 20:00', '-9529', ''),
	(1010, '도토리 용산점', '04382  서울 용산구 한강대로52길 25-6 1층', 'images/도토리_용산점_1010.jpg', '도토리 모양 마들렌이 달콤하게 유혹하는 카페\n\n용산 용리단길에 위치한 동화 속 오두막집을 연상케 하는 매력적인 베이커리 카페 용산 도토리입니다. 용산카페 도토리는 애니메이션에서 튀어나온 듯한 아기자기한 분위기와 포근한 숲속의 따뜻한 느낌을 자아내며, 방문객들에게 편안하고 아늑한 시간을 제공합니다. 용산 도토리는 키즈존이며 가족단위 방문객들도 편안하게 이용하실 수 있습니다. 또한, 케이지와 함께 애견동반이 가능합니다.', 37.531901, 126.972797, '', '지하철 4호선/6호선 삼각지역 3번출구, 270m', '', '', ' https://www.instagram.com/dotori__seoul', '', '', '매일 09:00 - 23:00', '02-797-0225', ''),
	(1011, '명동삼계탕', '04537  서울 중구 명동8가길 43 (충무로2가)', 'images/명동삼계탕_1011.jpg', '삼계탕은 물론, 닭볶음탕 등 다양한 전통 한식 메뉴\n\n삼계탕은 물론, 닭볶음탕 등 다양한 전통 한식 메뉴를 즐길 수 있는 이곳은 K-FOOD를 체험하고자 하는 여행객들에게 인기가 많은 맛집입니다. 삼계탕은 인삼과 찹쌀로 속을 채운 닭을 끓인 요리로, 깊고 진한 국물 맛이 특징인 음식입니다. 닭볶음탕은 매콤하고 달콤한 양념에 닭과 다양한 채소를 함께 조리하여 맛과 식감을 한층 풍부하게 만들어 줍니다.', 37.561938, 126.987436, '', '지하철 4호선 명동역 10번 출구, 96m', '한방삼계탕, 전기구이통닭', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 22:00', '-12991', ''),
	(1013, '계단집', '04635  서울 중구 퇴계로6길 35 (회현동1가)', 'images/계단집_1013.png', '계단집은 도시재생으로 살아난 적산가옥 카페이다.\n\n남대문 시장 근처에 위치한 1935년 근대가옥의 멋스러움을 간직한 스페셜티 커피 카페입니다. 23년부터 25년까지 3년 연속 블루리본 서베이에 선정될 만큼 맛과 분위기를 인정받고 있습니다. 1층은 따스한 카페 공간으로, 다양한 디저트와 함께 스페셜티 커피를 즐길 수 있고  2층은 다다미 바닥으로 이루어진 좌식 자리로 내 집 같은 편안함 속에서 느긋하게 시간을 보낼 수 있는 것이 특징입니다. \n\n\n\n\n또한 소규모 모임이나 전시 등을 위한 공간 대관이 가능해 특별한 시간을 보낼 수 있습니다. 바쁜 도심 속 여유를 찾고 싶다면 이곳을 방문해보세요. 자세한 내용은 홈페이지와 네이버 예약을 통해 확인할 수 있습니다.', 37.556950, 126.979247, '', '지하철 4호선 회현역 3번출구, 192m', '', '화 ~ 일', ' https://www.instagram.com/cafe_stairs_/', '카페, 디저트', '', '평일: 10:00 ~ 20:00\n주말: 10:00 ~ 20:00', '070-4419-7776', '월'),
	(1014, '홍대간장게장 홍일품', '04048  서울 마포구 독막로 47-1 (합정동)', 'images/홍대간장게장_홍일품_1014.jpg', '꽃게 선별부터 게장 소스, 꽃게탕 육수까지 주인장이 직접 만들고 준비\n\n꽃게 선별부터 게장 소스, 꽃게탕 육수까지 주인장이 직접 만들고 준비합니다. 시판 소스를 사용하는 집과는 달리 과일 원액과 한약재로만 만들어 짜지 않고 삼삼한 맛이 특징입니다. 여러 방송에 소개되며 정성과 맛이 인증된 곳으로 믿고 방문해도 좋습니다.', 37.548076, 126.918724, '', '지하철 6호선 상수역 1번 출구, 361m', '암게무한리필, 암게200g+양념+새우장+알밥+꽃게탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:30 (15:00 - 16:30 브레이크타임)', '-2086', '매주 월요일'),
	(1015, '고수닭갈비', '06129  서울 강남구 강남대로96길 12 (역삼동)', 'images/고수닭갈비_1015.jpg', '매콤달콤한 닭갈비와 풍성하게 얹어진 치즈, 감칠맛 넘치는 볶음밥\n\n매콤달콤한 닭갈비와 풍성하게 얹어진 치즈, 감칠맛 넘치는 볶음밥까지, 시작부터 끝까지 푸짐하고 맛있는 향연에 빠질 수 있는 곳입니다. 닭갈비는 매콤한 양념이 닭고기에 깊이 배어 있어, 씹을수록 맛이 살아나고 치즈는 폭포수처럼 흐르며 닭갈비의 매운맛과 달콤함을 부드럽게 감싸줍니다. 볶음밥은 남은 양념에 잘 볶아져 감칠맛을 더하며, 한 끼 식사로서 완벽한 마무리를 제공합니다.', 37.499739, 127.028073, '', '지하철 2호선/신분당선 강남역 11번 출구, 196m', '눈꽃송이치즈닭갈비, 닭갈비', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 22:00', '-4746', ''),
	(1016, '봉추찜닭 명동중앙우체국점', '04535  서울 중구 명동8나길 47 (충무로1가)  1층', 'images/봉추찜닭_명동중앙우체국점_1016.jpg', '찜닭 프랜차이즈점으로, 전통 안동 찜닭을 현대인의 입맛에 맞게 업그레이드.\n\n봉추찜닭은 서울 곳곳에서 만날 수 있는 찜닭 프랜차이즈점으로, 전통 안동 찜닭을 현대인의 입맛에 맞게 업그레이드한 퓨전 건강식을 제공합니다. 찜닭은 부드럽고 담백한 닭고기와 쫄깃한 당면, 그리고 각종 채소를 진한 양념과 함께 조리한 요리합니다. \n\n봉추찜닭의 특징은 동치미 국물로 조리해 시원하고 깔끔한 맛을 더하는 데 있습니다. 이곳은 전통적인 찜닭의 맛을 현대적으로 재해석하여 풍부한 맛을 즐길 수 있는 곳입니다.', 37.561064, 126.982277, '', '지하철 4호선 명동역 5번 출구, 272m', '봉추찜닭(소, 2인), 봉추찜닭(중, 3인)', '', ' http://www.bongchu.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:30', '-13090', ''),
	(1017, '큐스닭강정', '04011  서울 마포구 망원로8길 27 (망원동)', 'images/큐스닭강정_1017.jpg', '망원시장에서  문전성시하는 가게. 다양한 소스로 버무려진 닭강정\n\n망원시장에서 늘 문전성시하는 가게 중 하나로, 다양한 소스로 버무려진 닭강정이 인기입니다. 달콤 소스, 치즈 소스, 땅콩버터 소스 등 다양한 맛을 자랑하며, 바삭한 식감이 일품입니다. 매일 신선한 재료로 조리된 닭강정은 풍부한 소스와 함께 풍미가 뛰어나며, 포장 판매만 하여 웨이팅이 금방 줄어듭니다. 망원시장을 방문할 때 꼭 맛볼 만한 메뉴로, 포장이 부담스러우면 닭강정 컵으로 간편하게 즐길 수 있습니다.', 37.556303, 126.906263, '', '지하철 6호선 망원역 2번 출구, 474m', '닭강정 1마리, 닭강정 컵', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '09:30 - 20:30', '-8640', ''),
	(1018, '강구미주구리', '03044  서울 종로구 자하문로2길 5 (통의동)', 'images/강구미주구리_1018.jpg', '영덕 부근 지역의 명물 곰치를 끓여내는 곰치탕이 유명한 횟집.\n\n영덕 부근 지역의 명물 곰치를 주 식재료로 사용해 무, 두부, 파를 넣어 끓여내는 곰치탕이 유명한 횟집입니다. 경북 영덕군의 마을 이름인 강구와 돌가자미라는 뜻의 미주구리를 조합해 식당 이름을 지었습니다. 회덮밥과 물회는 맛과 양이 적당해 한 끼 식사로 제격입니다. 유명 방송에 소개되면서 인기를 끌어, 가끔 대기 줄이 생길 정도로 방문객이 많습니다.', 37.576590, 126.973030, '', '지하철 3호선 경복궁역 3번 출구, 79m', '곰치탕, 물회정식', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00-22:30 (15:00-17:00 브레이크타임)', '-8541', '매주 일요일'),
	(1019, '꾸스꾸스', '03040  서울 종로구 자하문로5길 16-2 (체부동)', 'images/꾸스꾸스_1019.jpg', '서촌에 위치한 북아프리카 튀니지 전통 음식을 맛볼 수 있는 맛집\n\n서촌에 위치한 이 식당은 북아프리카 튀니지 전통 음식을 맛볼 수 있는 맛집입니다. 튀니지 음악을 들으며, 튀니지 사진을 감상하고, 튀니지에 관한 이야기를 나눌 수 있는 한국 유일의 튀니지 음식점으로, 마치 튀니지에 온 듯한 기분을 느낄 수 있습니다. 새로운 튀니지 음식이지만 맛이 뛰어나 어느새 그릇을 다 비우고 있는 자신을 발견하게 될 것입니다.', 37.577861, 126.971150, '', '지하철 3호선 경복궁역 2번 출구, 262m', '튀니지안세트 A, 튀니지안세트 B', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 23:00', '-7569', '매주 화요일'),
	(1020, '킹케밥 이태원점', '04350  서울 용산구 이태원로 185 (이태원동)', 'images/킹케밥_이태원점_1020.jpg', '튀르키예 셰프가  손수 만들어 제공하는 케밥 전문 식당\n\n튀르키예 셰프가 직접 빵부터 소스까지 모든 것을 손수 만들어 제공하는 케밥 전문 식당입니다. 튀르키예 케밥의 정수라는 자신감이 가득하며, 건강한 할랄 음식을 즐길 수 있습니다. 24시간 운영되므로, 언제든지 풍미 가득한 케밥을 맛볼 수 있습니다.', 37.534725, 126.994596, '', '지하철 6호선 이태원역 2번 출구, 33m', '킹케밥', '', ' http://www.instagram.com/kingkebab.korea', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '00:00 - 24:00', '-5522', ''),
	(1021, '두바이레스토랑', '04406  서울 용산구 이태원로 192 (이태원동)', 'images/두바이레스토랑_1021.jpg', '현지인이 운영하는 이슬람 음식 전문점으로, 아랍식 에피타이저, 커리, 바비큐\n\n현지인이 운영하는 이슬람 음식 전문점으로, 아랍식 에피타이저, 커리, 바비큐 등 다양한 메뉴가 준비되어 있습니다. 현지인이 운영하는 만큼 아랍 문화를 진하게 느낄 수 있으며, 다른 식당에 비해 가격대가 저렴해 가성비 좋은 식당으로 알려져 있습니다. 후식으로 아랍 커피까지 제공되어, 식사 마무리까지 한 곳에서 완벽하게 즐길 수 있습니다.', 37.534367, 126.995372, '', '지하철 6호선 이태원역 3번 출구, 90m', '램 갑사, 치킨 만디', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '12:00 - 23:00 (22:30 라스트오더, 매주 월요일 휴무)', '-9995', ''),
	(1022, '치킨락', '03993  서울 마포구 동교로27길 8-3 (동교동)  2층', 'images/치킨락_1022.jpg', '신선하고 육질 좋은 한국식 치킨을 맛볼 수 있는 노포 치킨집.\n\n한국산 생닭만을 사용하여 신선하고 육질 좋은 한국식 치킨을 맛볼 수 있는 노포 치킨집. 오랜 전통을 자랑하는 이곳에서는 직접 만든 치킨무와 유기농 재료로 만든 토핑들이 감칠맛을 더하며, 조리사의 정성과 실력을 한입에 느낄 수 있습니다. 특히 양파링 토핑은 단골들의 필수 주문 메뉴로, 고소하고 바삭한 식감이 일품이니 꼭 맛보길 추천합니다.', 37.559032, 126.923043, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 2번 출구, 302m', '', '', ' https://www.instagram.com/yeonnam_chickenrock/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '16:00 - 24:00 (23:40 라스트오더)', '-2899', ''),
	(1023, '델리 압구정점', '06018  서울 강남구 압구정로46길 5-10 (신사동, 압구정로데오스타)  로데오스타 빌딩 B동 105호', 'images/델리_압구정점_1023.jpg', '1984년 압구정동 로데오거리에 오픈하여 40여 년 동안 변치 않는 커리 전문점\n\n한국 고유의 브랜드이자 커리의 대명사인 델리는 1984년 압구정동 로데오거리에 오픈하여 40여 년 동안 변치 않는 맛을 지켜온 커리 전문점입니다. 인도와 미국에서 직접 들여오는 23종의 스파이스와 허브, 다양한 야채와 과일, 와인 등을 사용하여 정통 커리의 깊고 풍부한 맛을 그대로 재현하는 델리는 커리 애호가라면 꼭 방문해야 하는 식당입니다.', 37.527920, 127.037498, '', '지하철 수인분당선 압구정로데오역 6번 출구, 423m', '안심비트 커리세트 B, 해산물 리조또', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00 (20:30 라스트오더)', '-8010', '');
INSERT INTO `restaurant` (`restaurant_id`, `restaurant_name`, `place`, `image_path`, `description`, `Latitude`, `Longitude`, `price`, `near_subway`, `signature_menu`, `operatingday`, `website`, `type`, `notice`, `operatinghour`, `tel`, `holidays`) VALUES
	(1024, '더키친아시아 홍대점', '04055  서울 마포구 와우산로23길 35-6 (서교동)', 'images/더키친아시아_홍대점_1024.jpg', '100% 할랄 음식을 판매하는 인도 요리 전문점.\n\n100% 할랄 음식을 판매하는 인도 요리 전문점으로, 홍대와 대학로 두 곳에 위치하고 있습니다. 홍대점은 이미 많은 외국인 관광객들이 찾는 곳입니다. 정갈하고 맛있는 인도 음식을 맛볼 수 있으며, 세트 구성이 알찹니다. 특히 평일 런치 메뉴는 구성도 좋고 가격도 저렴하니 평일 점심에 방문해 보세요.', 37.554577, 126.923315, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 9번 출구, 229m', '치킨 티카 마살라 커리(매운맛)+버터난, 평일 런치 커플 세트메뉴', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (21:30 라스트오더)', '-5016', ''),
	(1025, '스타벅스 경동 1960점', '02571  서울 동대문구 고산자로36길 3 (제기동, 경동시장)', 'images/스타벅스_경동_1960점_1025.png', '경동극장을 리모델링한 영화관 컨셉의 특별한 스타벅스\n\n스타벅스 경동1960점은 경동시장 내에 위치하고 있으며 1960년에 지어진 경동극장을 리모델링 해 계단식 좌석과 무대공간을 그대로 유지한 영화관 분위기의 카페입니다. 주문번호를 한쪽 벽에 띄워주고, 천장에 독특한 인테리어들이 소소한 재미를 더해줍니다. 주말에는 사람이 많아 대기할 수 있으니 평일에 방문하는것을 추천합니다.', 37.579038, 127.039143, '', '지하철 1호선 제기동역 2번출구, 298m', '', '', '', '', '', '매일 09:00~22:00', '1522-3232', ''),
	(1026, '현선이네 용산본점', '04376  서울 용산구 한강대로39길 2-13 (한강로2가)', 'images/현선이네_용산본점_1026.jpg', '서울 용산구 대표 떡볶이 맛집\n\n찾아라! 맛있는 TV에서 서울 5대 떡볶이 맛집으로 소개되어 더 유명해진 현선이네는 2004년 포장마차로 시작한 용산구 대표 떡볶이 맛집으로 건물 또한 포장마차를 연상케합니다. 세트메뉴, 단품메뉴, 즉석떡볶이로 나눠져 있으며, 포장과 배달 모두 가능합니다.떡볶이는 매운맛, 중간맛, 순한맛 중에서 선택할 수 있습니다.', 37.531151, 126.969218, '', '지하철 4호선 신용산역 6번출구, 180m', '', '', ' https://www.instagram.com/hyunsunine_', '', '', '매일 11:00-24:00 라스트오더 22:40', '0507-1361-8901', ''),
	(1027, '덴푸라감춘', '05552  서울 송파구 잠실로 209 (신천동, KT송파타워)  지하1층 B103호', 'images/덴푸라감춘_1027.jpg', '서울에서 보기 힘든 튀김 코스 요리를 맛볼 수 있는 일식당\n\n서울에서 보기 힘든 튀김 코스 요리를 맛볼 수 있는 식당입니다. 고급스러운 분위기와 더불어 바삭하게 튀겨진 다양한 종류의 튀김을 한 번에 먹어볼 수 있는 장점이 있습니다. 모든 메뉴는 코스로 이뤄져 있으며 특히 점심 코스가 가성비가 좋습니다. 튀김 요리와 어울리는 다채로운 요리가 중간 중간 코스에서 마련되니 든든하게 식사를 즐길 수 있습니다.', 37.513865, 127.106100, '', '지하철 2/8호선 잠실역 10번 출구, 319m', '런치A코스, A코스', '', ' https://www.instagram.com/gamchun_official', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '월 - 금 11:00 - 23:00 (14:30 - 17:00 브레이크타임, 21:00 라스트오더)\n토 - 일 11:30 - 23:00 (15:00 - 17:30 브레이크타임, 21:00 라스트오더)', '-4903', ''),
	(1028, '명인등심 마포공덕 직영점', '04212  서울 마포구 마포대로 144 (공덕동, 마포T타운)  B1', 'images/명인등심_마포공덕_직영점_1028.jpg', '한우 특등심이 좋은 집\'으로 한우 특등심 전문점\n\n\'한우 특등심이 좋은 집\'을 슬로건으로 내걸고 2009년부터 운영 중인 한우 특등심 전문점입니다. 경북 안동의 대형 목장에서 1++ 한우를 직거래로 공급받아, 좋은 퀄리티의 원육과 식재료를 합리적인 가격으로 제공합니다. 맛집 소개 방송에도 다수 소개된 만큼, 맛이 보장된 곳입니다.', 37.547001, 126.953757, '', '지하철 5/6호선/공항철도/경의중앙선 공덕역 4번 출구, 291m', '1++ 한우등심스페셜, 한우육회', '', ' https://www.instagram.com/myeongin_deungsim/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (14:30 - 17:00 브레이크타임/ 월 - 금)', '0507-1387-2589', ''),
	(1029, '훈육', '04337  서울 용산구 소월로20길 38 1층', 'images/훈육_1029.png', '숙성삼겹살로 유명한 아늑한 한국식 바비큐 식당\n\n해방촌 신흥시장 안쪽에 위치한 훈육은 숙성 돼지고기 전문점입니다. 숙성 돼지고기의 고소함과 부드러운 육질을 느낄 수 있습니다. 목살이 가장 인기 메뉴이며 고기당 1인분씩 주주문이 가능합니다. 만석 시 이용시간은 1시간 30분이며 콜키지 병당 2만원입니다. 웨이팅이 있을 수 있어 미리 가서 예약 후 신흥시장 구경하길 추천드립니다.', 37.544917, 126.985164, '', '지하철 4호선 숙대입구역 2번출구, 1.3km / 6호선 녹사평역 2번출구, 1.4km', '', '', ' https://www.instagram.com/hoonyook6/', '', '공용주차장 만차시 주차 어려우니 대중교통 권장드립니다', '화-금 16:00-24:00 / 토,일 15:00-24:00 (라스트오더 23:00) ※재료 소진시 조기마감', '02-3789-6282', '매주 월요일'),
	(1030, '페트라', '04345  서울 용산구 녹사평대로40길 33 (이태원동)', 'images/페트라_1030.jpg', '2004년, 한국인들에게 요르단 음식과 문화를 소개하기위해 오픈.\n\n2004년, 한국인들에게 요르단 음식과 문화를 소개하기 위해 이태원에 첫 문을 열었다. 할랄 의식을 거친 육류와 신선한 재료만을 사용하여 최상의 맛과 서비스를 제공한다. 특히 후무스와 팔라펠은 꼭 먹어봐야 할 베스트 조합 메뉴로 손꼽히며, 정성이 담긴 요리로 많은 사랑을 받고 있다.', 37.534705, 126.987710, '', '지하철 6호선 녹사평역 1번 출구, 180m', '후무스, 미자, 임나잘라, 팔라펠', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:30 - 21:00', '-5143', ''),
	(1031, '리틀인디아서울', '04405  서울 용산구 우사단로10길 21 (이태원동)', 'images/리틀인디아서울_1031.jpg', '이태원에서 인도 현지 커리를 진정으로 경험할 수 있는 맛집\n\n이태원에서 인도 현지 커리를 진정으로 경험할 수 있는 맛집입니다. 부드럽고 감칠맛 나는 탄두리 치킨과 깊고 풍부한 치킨 커리가 이곳의 대표 메뉴로, 현지인이 운영하는 만큼 인도 현지의 맛을 그대로 재현하고 있습니다. 세트 메뉴는 훌륭한 구성과 가성비를 자랑하므로, 여럿이 함께 방문한다면 세트 메뉴를 선택하는 것이 좋습니다. 이곳에서 진정한 인도 음식의 매력을 느껴보세요.', 37.533291, 126.996709, '', '지하철 6호선 이태원역 3번 출구, 370m', '사모사 2인 세트, 치킨 커리 세트', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 22:00 (15:00 - 16:30 브레이크타임)', '-6129', ''),
	(1032, '봉추찜닭 압구정로데오점', '06018  서울 강남구 선릉로157길 20-5 (신사동, 신사빌딩)  2층', 'images/봉추찜닭_압구정로데오점_1032.jpg', '봉추찜닭은 서울 곳곳에서 만날 수 있는 찜닭 프랜차이즈점\n\n봉추찜닭은 서울 곳곳에서 만날 수 있는 찜닭 프랜차이즈점입니다. 찜닭은 전통적으로 안동 지방에서 오랜 기간 전해 내려온 전통 음식으로, 부드러운 닭고기와 당면, 각종 채소를 간장과 다양한 양념으로 조리하여 깊은 맛을 내는 요리입니다. 닭고기의 담백함, 당면의 쫄깃함, 동치미 국물의 시원함이 어우러져 특별한 맛을 자랑하며, 찜닭 애호가라면 꼭 방문해야 할 식당입니다.', 37.526548, 127.038220, '', '지하철 수인분당선 압구정로데오역 5번 출구, 288m', '찜닭(소, 1~2인), 누룽지볶음밥', '', ' https://www.instagram.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00 (22:20 라스트오더)', '-8751', ''),
	(1033, '장수한방삼계탕', '04157  서울 마포구 마포대로 63-8 (도화동, 삼창주택)', 'images/장수한방삼계탕_1033.jpg', '맑은 국물의 기본 삼계탕 외에도 한방 삼계탕, 들깨 삼계탕\n\n맑은 국물의 기본 삼계탕 외에도 한방 삼계탕, 들깨 삼계탕 등 다양한 특색 있는 삼계탕을 맛볼 수 있는 곳입니다. 푹 삶은 부드러운 닭고기와 고소한 들깨 국물의 조화는 환상적입니다. 추워지기 시작할 때면 이곳의 국물을 찾는 이들이 끊이질 않습니다. 특히 들깨 삼계탕은 고소한 맛이 일품으로, 깊은 맛과 따뜻한 국물로 겨울철 별미로 추천됩니다.', 37.542260, 126.947815, '', '지하철 5/6호선/공항철도/경의중앙선 공덕역 1번 출구, 439m', '한방삼계탕, 들깨삼계탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 20:30 (15:00 - 17:00 브레이크타임)', '-7134', '일요일'),
	(1034, '함바그 요시', '04768  서울 성동구 서울숲6길 22 (성수동1가)  1층', 'images/함바그_요시_1034.jpg', '일본식 함바그 요리 전문 식당\n\n일본식 함바그 요리 전문 식당으로, 당일 생산된 신선한 재료를 사용하여 육즙이 가득한 함바그를 제공합니다. 기본 함바그도 훌륭하지만, 와규 함바그는 깊고 부드러운 맛이 특히 일품입니다. 밥과 된장국이 함께 제공되는 세트 메뉴가 인기를 끌며, 이 조합은 식사의 만족도를 높여줍니다.', 37.547282, 127.043842, '', '지하철 2호선 뚝섬역 8번 출구, 284m', '기본 함바그세트, 우설 함바그세트', '', ' https://www.instagram.com/hamburgyoshi_korea', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:00 (20:00 라스트오더)', '-3870', ''),
	(1035, '코스모스상점 성수', '04780  서울 성동구 성수이로7길 27 (성수동2가, 서울숲코오롱디지탈타워)  서울숲코오롱디지털타워2차 1층 106-2호', 'images/코스모스상점_성수_1035.jpeg', '비건 브런치 카페와 비건 그로서리 제품을 제공하는 비건 복합 공간.\n\n비건 브런치 카페와 비건 그로서리 제품을 제공하는 이곳은 꽃이 함께하는 비건 복합 공간으로, 건강한 음식과 동식물이 조화를 이루는 편안한 분위기를 자랑합니다. 이곳의 철학은 건강한 식사와 자연 친화적인 환경을 통해 모두에게 만족스러운 경험을 제공하는 것입니다. 세계 최대 규모의 비건 앱인 \'해피카우\'에서 성동구 랭킹 3위를 기록한 비건 명소로, 비건 식사를 원하는 이들에게 추천할 만한 장소입니다.', 37.541574, 127.053439, '', '지하철 2호선 성수역 4번 출구, 460m', '크리스피 두부 텐더 랩, 코코넛라떼, 미숫가루', '', ' https://www.instagram.com/cosmos_grocery_', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00 (20:20 라스트오더)\n일 - 화 11:00 - 20:00 (19:20 라스트오더)', '-9705', ''),
	(1036, '소담상회 with idus place 서교점', '04039  서울 마포구 홍익로5길 31 1층', 'images/소담상회_with_idus_place_서교점_1036.jpg', '카페, 캐주얼 다이닝과 K-Handmade를 함께 즐길 수 있는 공간\n\n아시아 NO.1 핸드메이드 플랫폼 idus가 운영하는 캐주얼 다이닝&핸드메이드샵입니다. 조미료 없이 한국의 재료를 살려 만든 음식과 다채로운 K-Handmade 작품을 만나볼 수 있어서 눈과 입이 모두 만족되는 곳입니다. 카페만 이용하는 것도 가능하니 여행 중 휴식이 필요할 때 편하게 들려봐도 좋을 듯 합니다. 이 공간은 중소벤처기업부, 중소벤처기업유통원과 함께 대한민국 소상공인을 지원을 위해 운영 중입니다.', 37.553632, 126.920929, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 9번출구, 560m', '', '', ' https://www.instagram.com/idusplace.seogyo?igsh=YjFoNXp6eGVmbmIw', '', 'Handmade / 영문 작품 설명 有', '수~일 11:00-21:00 / 라스트오더 20:30', '02-1668-3650', '월,화 휴무'),
	(1037, '스시지현', '03989  서울 마포구 동교로 227-7 (연남동)  1층', 'images/스시지현_1037.jpg', '한번 방문한 사람은 긴 웨이팅을 해서라도 다시 찾게 만드는 퀄리티가 있는 초밥집\n\n한번 방문한 사람은 긴 웨이팅을 해서라도 다시 찾게 만드는 퀄리티가 있는 초밥집입니다. 자리가 협소한 편이므로 원격 대기 앱을 통해 방문하는 것이 좋습니다. 특히 다양한 생선을 한꺼번에 맛볼 수 있는 모둠 초밥이 인기입니다. 초밥 외에도 모둠 사시미와 연어 사시미 등 다양한 메뉴가 마련되어 있어 골고루 맛보는 것을 추천합니다.', 37.560667, 126.923602, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 3번 출구, 290m', '모듬초밥C, 모듬사시미', '', ' https://www.instagram.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:30 (15:00 - 17:00 브레이크타임, 20:30 라스트오더)', '-3920', '매주 화요일'),
	(1038, '잘루스', '04561  서울 중구 을지로44길 12 (광희동1가, 뉴금호타워)  뉴금호타워 3층', 'images/잘루스_1038.jpg', '현지인들이 자주 찾는 몽골 요리 전문점.\n\n현지인들이 자주 찾는 몽골 요리 전문점으로, 한국에서 찾기 힘든 진정한 몽골 요리를 제공합니다. 저렴한 가격에 푸짐한 몽골 음식을 즐길 수 있으며, 양고기 국밥, 우유죽, 양배추 볶음 등이 시그니처 메뉴로 알려져 있습니다. 양고기 국밥은 진한 육수와 부드러운 양고기 조각이 특징이며, 깊은 풍미와 고소한 맛이 어우러집니다.', 37.565589, 127.006334, '', '지하철 2/4/5호선 동대문역사문화공원역 12번 출구, 106m', '양고기국밥, 우유죽, 양배추볶음', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 22:00', '02-2277-5418', ''),
	(1039, '소바마에 니고', '04782  서울 성동구 연무장길 39-15 (성수동2가)  지1층', 'images/소바마에_니고_1039.jpg', '전통 일본식 소바 요리를 전문적으로 하는 집.\n\n전통 일본식 소바 요리를 전문으로 하는 이 식당은 깊고 진한 소바 국물로 일본 음식 애호가들 사이에서 높은 평가를 받고 있습니다. 특히, 부드러운 육질과 고소한 감칠맛이 돋보이는 오리고기가 곁들여진 카모 세이로가 시그니처 메뉴로 인기가 많습니다. 소바와 함께 제공되는 튀김 요리도 훌륭하며, 소바와의 조화가 일품입니다. 이곳에서 진정한 일본식 소바의 맛을 경험하고 싶다면, 카모 세이로와 튀김을 함께 즐기는 것이 좋습니다.', 37.543341, 127.053890, '', '지하철 2호선 성수역 4번 출구, 244m', '카모세이로, 니쿠소바(따뜻한)', '', ' https://www.instagram.com/sobamae_nigo', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '화~금 11:30 - 21:00 (15:00 - 17:00 브레이크타임, 20:30 라스트오더)\n토 - 일 11:30 - 20:30 (20:00 라스트오더)', '-10215', '매주 월요일'),
	(1040, '청화초밥', '05548  서울 송파구 오금로13길 14 (방이동)  1층', 'images/청화초밥_1040.jpg', '방이먹자골목에 오랜 역사를 가진 초밥집으로, 대기 줄이 긴 식당.\n\n방이먹자골목에 오랜 역사를 가진 초밥집으로, 대기 줄이 긴 식당으로 유명합니다. 회가 두툼하고 신선하여 맛이 뛰어나며, 사이드로 제공되는 묵은지 생선조림이 독특한 맛을 더합니다. 다양한 생선회를 즐길 수 있는 모둠 사시미와 스페셜 초밥이 인기 메뉴로, 부드러운 식감의 회가 초밥과 잘 어울립니다.', 37.513374, 127.109328, '', '지하철 9호선 송파나루역 2번 출구, 542m', '모듬 사시미, 스페셜 초밥', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:10 (15:00 - 16:10 브레이크타임, 21:10 라스트오더)', '-5513', '매주 일요일'),
	(1041, '독립한우 자인 정육식당', '04169  서울 마포구 새창로 20-1 (도화동)', 'images/독립한우_자인_정육식당_1041.jpg', '신선한 한우를 사용하여 감칠맛 나는 특수 부위\n\n신선한 한우를 사용하여 감칠맛 나는 특수 부위를 즐길 수 있는 곳입니다. 알등심살, 갈비살, 깍둑꽃살 등 다양한 소고기 부위를 판매하며, 취향에 맞게 골라볼 수 있습니다. 불필요한 부속물과 지방을 최대한 제거하고 섬세하게 정육한 고기를 제공하며, 육회(소고기회)도 별미로 추천합니다.', 37.541896, 126.952188, '', '지하철 5/6호선/공항철도/경의중앙선 공덕역 10번 출구, 93m', '알등심살, 갈비살', '', ' http://instagram.com/dongniphanwoo', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (14:00 - 16:00 브레이크타임)', '-1823', ''),
	(1042, '더키친아시아 대학로점', '03078  서울 종로구 대명길 27 (명륜4가)  2층, 3층', 'images/더키친아시아_대학로점_1042.jpg', '홍대와 대학로에 위치한 더키친아시아는 인도 음식을 다채롭게 즐길 수 있는 곳\n\n홍대와 대학로에 위치한 더키친아시아는 인도 음식을 다채롭게 즐길 수 있는 곳이다. 인도 음식의 대표적인 요리인 커리는 향신료를 듬뿍 사용해 깊고 풍부한 맛을 자랑한다. 인도의 전통 빵인 난과 함께 커리와 치킨을 곁들여 먹으면 그 맛을 더욱 잘 느낄 수 있다. 특히 매운맛을 좋아하는 사람이라면, 진한 향신료와 매운맛이 조화를 이룬 양고기 빈달루를 추천한다.', 37.583147, 127.000086, '', '지하철 4호선 혜화역 4번 출구, 118m', '난과 치킨티카 마살라커리, 난과 버터치킨 커리', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (21:30 라스트오더)', '-11993', ''),
	(1043, '망원닭강정', '04011  서울 마포구 망원로8길 21 (망원동)', 'images/망원닭강정_1043.jpg', '망원 전통시장 안에 위치. 신선한 닭강정을 제공.\n\n망원 전통시장 안에 위치한 이곳은 매일 아침 직접 재료를 손질하고 숙성 과정을 거쳐 신선한 닭강정을 제공합니다. 바삭한 튀김옷과 촉촉한 속살이 어우러진 닭강정은 매콤달콤한 소스와 함께 조리되어 깊고 풍부한 맛을 자랑합니다. 다양한 소스와 토핑 옵션으로 취향에 맞게 즐길 수 있으며, 바삭함과 함께 달콤하고 매콤한 맛이 조화롭게 어우러져 입맛을 사로잡습니다.', 37.556493, 126.906180, '', '지하철 6호선 망원역 2번 출구, 432m', '닭강정 한마리, 닭강정 컵', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:00 - 21:30', '02-3142-9952', '매주 화요일'),
	(1044, '홍대수산 오징어이야기', '04039  서울 마포구 홍익로5길 43 (서교동)', 'images/홍대수산_오징어이야기_1044.jpg', '홍대 대학가에 오랜 기간 자리 잡고 있는 해산물 전문점\n\n홍대 대학가에 오랜 기간 자리 잡고 있는 해산물 전문점으로, 저렴한 가격에 신선한 활어회를 즐길 수 있습니다. 회는 생선이나 해산물을 얇게 썰어 생으로 먹는 한국의 전통 요리로, 광어나 우럭 등 익숙하지 않은 외국인 관광객들도 부담 없이 맛볼 수 있도록 다양한 기본 메뉴가 마련되어 있습니다.', 37.553265, 126.920330, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 9번 출구, 455m', '광어 中, 광어+우럭', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '17:00 - 08:00 (06:00 라스트오더)', '-6257', ''),
	(1045, '타지팰리스 이태원점', '04406  서울 용산구 우사단로 39 (이태원동)', 'images/타지팰리스_이태원점_1045.jpg', '커리, 난, 탈리 등 다양한 인도 요리 메뉴와 채식 메뉴.\n\n커리, 난, 탈리 등 다양한 인도 요리 메뉴와 코스 메뉴, 그리고 베지테리언을 위한 채식 메뉴가 준비한 식당입니다. 주말에는 뷔페식으로 운영되어 다양한 음식을 마음껏 즐기고 싶은 손님들로 북적입니다. 현지의 맛을 그대로 느낄 수 있어 인도 음식 애호가들 사이에서 많은 사랑을 받고 있는 곳입니다.', 37.533699, 126.995445, '', '지하철 6호선 이태원역 3번 출구, 194m', '탄두리 치킨, 버터 치킨 카레', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 21:30', '-6496', ''),
	(1046, '헬로인디아 홍대점', '04053  서울 마포구 와우산로29길 59 (서교동)  2층', 'images/헬로인디아_홍대점_1046.jpg', '인도 커리 입문자라면 추천하는 곳\n\n인도 커리 입문자라면 추천하는 곳입니다. 양고기 커리, 채소 커리, 콩 커리 등 특색 있는 커리부터 차우멘, 바스마티 인도 라이스 등 폭넓고 맛있는 인도 음식을 맛볼 수 있습니다. 특히 커리는 적당한 매운맛으로 조리되어, 매운 맛을 좋아하는 사람은 물론, 그렇지 않은 사람도 모두 맛있게 즐길 수 있습니다.', 37.555953, 126.926809, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 7번 출구, 175m', '탄두리 치킨', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 23:00 (22:00 라스트오더)', '-8680', ''),
	(1047, '진교동찜닭 신촌점', '03787  서울 서대문구 연세로5나길 47 (창천동)  1층 102호', 'images/진교동찜닭_신촌점_1047.jpg', '자극적이지 않으면서 손맛이 느껴지는 찜닭\n\n자극적이지 않으면서 손맛이 느껴지는 찜닭을 맛볼 수 있습니다. 찜닭은 부드러운 닭고기와 풍부한 양념이 어우러져 깊은 맛을 자랑하며, 다양한 채소가 함께 들어 있어 식감과 영양이 풍부합니다. 한국의 매운 맛에 익숙한 관광객이라면 레드크림 로제찜닭으로 색다른 찜닭을 추천합니다. 로제찜닭은 크림과 매운 소스의 조화로 부드럽고 크리미한 맛을 제공하며, 독특하면서도 매력적인 풍미를 자랑합니다.', 37.557235, 126.933514, '', '지하철 2호선 신촌역 1번 출구, 408m', '순살찜닭(1인), 순살찜닭(소)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 23:00 (22:50 라스트오더)', '010-2938-5578', ''),
	(1048, '매화양꼬치 명동점', '04629  서울 중구 퇴계로20길 15 1층', 'images/매화양꼬치_명동점_1048.jpg', '냄새가 적고 육질이 부드러운 1년 미만의 어린 양고기만을 제공\n\n냄새가 적고 육질이 부드러운 1년 미만의 어린 양고기, 즉 \'램\'만을 제공하는 이곳은 색다른 양고기 요리를 찾는다면 딱 맞는 장소입니다. 특히 매화양꼬치는 풍미가 뛰어나며 양고기의 부드러운 맛을 한층 살려 조리한 음식입니다. 매운 맛과 독특한 향이 조화를 이루는 마라 요리와, 깊은 맛의 어향가지, 신선한 향라새우 등 다양한 중식 요리를 함께 주문해 나눠 먹는 것도 좋습니다.', 37.559498, 126.985880, '', '지하철 4호선 명동역 3번 출구, 171m', '고급양갈비구이, 마라롱샤', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:20', '-9981', ''),
	(1049, '높은산', '04776  서울 성동구 성수이로 18-1 (성수동2가)', 'images/높은산_1049.png', '높은산은 성수에서 전통 마살라 차이를 즐길 수 있는 이국적 분위기의 차이 전문 카페.\n\n높은산은 성수에 위치한 따뜻하고 이국적인 분위기의 차이(Chai) 전문 카페입니다. 인도, 네팔, 파키스탄 등지에서 즐겨 마시는 전통 마살라 차이를 맛볼 수 있는 곳으로, 기존의 달콤한 밀크티와는 다른 진한 향신료의 풍미가 매력적입니다. 이곳의 차이는 주문 즉시 끓여 제공되며, 정성스러운 과정 덕분에 5분에서 10분 정도가 소요됩니다.\n\n아담한 규모의 아늑한 공간에서 천천히 시간을 보내며 차이를 음미하기에 제격입니다. 카페에서는 마실 수 있는 차이 외에도 티백 제품도 판매해 집에서도 그 특별한 맛을 즐길 수 있습니다. 높은산은 일상 속에서 여행처럼 이국적이고 따뜻한 순간을 선사하는 차이 카페입니다.', 37.536854, 127.054148, '', '지하철 2호선 성수역 3번출구, 861m', '', '목 ~ 화\n* 자세한 사항은 홈페이지를 참고해주세요', ' https://www.instagram.com/noppensan', '카페, 디저트', '', '10:00 ~ 18:00\n*자세한 사항은 홈페이지를 참고해주세요', '0507-1328-8194', '수'),
	(1050, '차차이테', '04400  서울 용산구 이태원로54길 74 (한남동) 2층', 'images/차차이테_1050.jpg', '찻자리의 작은 호사, 차를 위한 디저트와 함께 즐기는 티코스\n\n동서양의 디저트 문화를 경험할 수 있는 한남동 작은 찻집입니다. 처음 맛보는 디저트 다과들이 준비되어 있으며 선물용으로 구매도 가능합니다. 티룸에서 즐기는 호사로운 티타임은 예약이 필요합니다. 2층에는 국내외에서 수집한 감각적인 다기들이 진열되어 있어 구경하는 재미까지 더한 차차이테에서 연인들끼리 친구끼리 특별한 시간을 가져보세요.', 37.535244, 127.000980, '', '지하철 6호선 한강진역 3번출구, 609m', '', '', '', '', '* 주차공간이 없으니 대중교통을 이용해 주세요', '화~토 : 11:00~19:00', '0507-1347-7594', '매주 일, 월요일'),
	(1051, '카페 타자기', '04337  서울 용산구 신흥로 97-5 (신흥시장 안) 2층', 'images/카페_타자기_1051.png', '해방촌 신흥시장 노을뷰 카페\n\n빈티지 감성이 물씬 풍기는 이 카페는 멋진 전망과 함께 타자기, 레트로 포스터, 그리고 은은하게 흐르는 음악 등 독특한 분위기를 자아냅니다. 넓은 창문으로 들어오는 햇살과 갓 내린 커피 향이 은은하게 퍼지는 공간은 고요하고 우아한 분위기를 자아냅니다. 하지만 진정한 보물은 바로 전망입니다. 테이블 옆에서 서울의 스카이라인이 한눈에 들어오는 탁 트인 전망을 감상할 수 있습니다. 시간이 느리게 흐르고 세상이 기분좋게 아날로그적인 느낌을 주는 곳입니다.', 37.545228, 126.984882, '', '지하철 4호선 숙대입구역 2번출구, 1.3km / 6호선 녹사평역 2번출구, 1.4km', '', '', ' https://www.instagram.com/cafe_tajagi', '', '', '매일 12:00 - 22:00', '0507-1324-2286', ''),
	(1052, '사마르칸트', '04561  서울 중구 마른내로 159-21 (광희동1가)  1층', 'images/사마르칸트_1052.jpg', '우즈베키스탄 현지인이 직접 운영하는 대한민국 최초의 실크로드 음식 전문점\n\n우즈베키스탄 현지인이 직접 운영하는 대한민국 최초의 실크로드 음식 전문점입니다. 한국인뿐만 아니라 서울 거주 현지인들도 많이 찾는 곳으로, 모두의 입맛을 사로잡는 음식을 경험할 수 있습니다. 양고기 샤슬릭은 특제 양념에 재운 양고기를 화덕에서 구워내어 겉은 바삭하고 속은 부드러운 요리입니다. 플로프는 우즈베키스탄의 전통 볶음밥으로, 양고기와 다양한 채소, 향신료가 조화를 이루며 깊은 풍미와 풍부한 맛을 제공합니다.', 37.565148, 127.005811, '', '지하철 2/4/5호선 동대문역사문화공원역 8번출구, 130m', '양고기 샤슬릭, 플로프 전통 볶음밥', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '10:00 - 22:00 (21:00 라스트오더)', '-6041', '격주 화요일'),
	(1053, '팔민물장어직판장', '03995  서울 마포구 월드컵북로2길 25 (동교동, 한국심리상담연구소)', 'images/팔민물장어직판장_1053.jpg', '국내산 장어 직판장으로, 민물장어를 저렴한 가격에 맛볼 수 있는 곳\n\n국내산 장어 직판장으로, 민물장어를 매우 저렴한 가격에 맛볼 수 있는 곳입니다. 주인장의 오랜 노하우로 참숯에 구운 장어는 육즙이 풍부하고 겉은 바삭하게 구워져 맛이 훌륭합니다. 또한, 함께 나오는 반찬들은 장어의 느끼함을 잡아주는 조화로운 맛을 제공하며, 이로 인해 고객들의 칭찬이 이어집니다.', 37.556464, 126.922094, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 1번 출구, 73m', '장어정식, 민물장어 대 2마리', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00', '-9550', ''),
	(1054, '돈화문닭한마리', '03139  서울 종로구 돈화문로9길 17 (돈의동)', 'images/돈화문닭한마리_1054.jpg', '닭한마리는 한국의 전통 음식 중 하나로 한마리를 사용하여 만든 요리\n\n닭한마리는 한국의 전통 음식 중 하나로, 한 마리의 통닭을 사용하여 만든 요리입니다. 일반적으로 국물과 함께 조리되며, 국물은 깔끔하고 시원한 맛이 특징입니다. 혼자 여행하는 경우에는 점심시간에 방문해 점심 메뉴를 즐기는 것이 좋습니다. 특히, 한방약재를 넣어 푹 끓여 만든 황칠 삼계탕은 원기 회복에 최상의 선택입니다.', 37.571632, 126.990827, '', '지하철 1/3/5호선 종로3가역 2-1번 출구, 184m', '닭한마리 2인, 황칠 삼계탕', '', ' https://www.instagram.com/dondak2015', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00-21:00 (15:00-17:00 브레이크타임)', '-2694', ''),
	(1055, '바이두부', '04328  서울 용산구 소월로20길 10 (용산동2가)', 'images/바이두부_1055.jpg', '식물성 재료를 사용하여 신선한 메뉴를 제공\n\n폐목재를 활용한 인테리어로 독특하고 새로운 가치를 더한 이곳은 최대한 식물성 재료를 사용하여 신선한 메뉴를 제공합니다. 두부를 활용한 상상하기 어려운 색다른 요리를 선보이며, 비건이 아니더라도 두부를 좋아하는 많은 방문객들이 찾는 장소입니다.', 37.546075, 126.985198, '', '지하철 3호선 녹사평역 2번출구, 1.3km', '브로콜리 두부강정 샐러드, 계란없는 계란 샌드위치', '', ' http://www.instagram.com/bytofu_hbc', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '09:00 - 19:30 (15:00 - 17:00 브레이크타임, 18:40 라스트오더)', '-8822', '매주 화 - 수 휴무'),
	(1056, '이프타르', '03994  서울 마포구 동교로 212-22 (동교동)', 'images/이프타르_1056.jpg', '할랄 한식 전문 레스토랑으로, 불고기, 닭볶음탕, 오징어볶음 등 대표 한식 메뉴\n\n할랄 한식 전문 레스토랑으로, 불고기, 닭볶음탕, 오징어볶음 등 대표 한식 메뉴를 할랄 푸드로 요리하여 무슬림 관광객이 부담 없이 한식을 즐길 수 있는 곳입니다. 불고기는 달콤하고 짭조름한 양념이 깊게 밴 소고기로, 입안에서 살살 녹는 부드러운 식감이 일품입니다. 닭볶음탕은 매콤하고 진한 국물에 부드러운 닭고기와 다양한 채소가 어우러져 푸짐한 한 끼를 제공합니다.', 37.559270, 126.924391, '', '지하철 3호선 경복궁역 1번 출구, 295m', '불고기 비빔국수, 닭볶음탕', '', ' https://www.instagram.com/iftar_halal_kr/#', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:30 - 19:30 (15:00 - 16:00 브레이크타임, 20:30 라스트오더)', '0507-1486-8015', ''),
	(1057, '구르카 인도레스토랑', '04536  서울 중구 명동10길 16-1 (명동2가)  5층', 'images/구르카_인도레스토랑_1057.jpg', '현지인이 직접 운영하는 인도 및 네팔 레스토랑\n\n현지인이 직접 운영하는 인도 및 네팔 레스토랑입니다. 음식만으로도 그 나라들의 진정한 맛을 느낄 수 있는 곳입니다. 특히 런치세트와 탈리세트는 맛과 구성이 뛰어나, 다양한 요리를 한 번에 즐길 수 있는 대표 메뉴입니다. 이곳에서는 머튼 커리와 말라이 코프타 커리와 같은 독특한 요리를 제공하며, 다른 인도 식당에서는 보기 힘든 메뉴들로 색다른 미식 경험을 제공합니다.', 37.563068, 126.985185, '', '지하철 4호선 명동역 8번 출구, 248m', '머튼 커리, 말라이 코프타 커리', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00 (21:30 라스트오더)', '-9555', ''),
	(1058, '마지', '03041  서울 종로구 자하문로5길 19 (체부동)', 'images/마지_1058.jpg', '한국 전통 채식밥상으로 발효식이고 자연식 비건 식당\n\n속 편하고 건강한 사찰 음식을 선보이는 비건 식당. 한국전통채식을 선보이는 이곳은 우엉잡채, 배 냉면 등 채소 본연의 맛을 살리면서도 특색 있는 메뉴들이 눈길을 끕니다. 부드럽고 담백한 음식 속에서도 깊이 느껴지는 감칠맛이 돋보입니다. 특히 런치 디너 세트는 푸짐한 한식 한 상을 가성비 좋은 가격에 즐길 수 있습니다.', 37.577610, 126.970805, '', '지하철 3호선 경복궁역 2번 출구, 268m', '런치디너세트, 오늘의 마지', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 20:00 (15:00-17:30 브레이크타임)\n일 요일11:300 - 15:00', '02-536-5228', '월요일 화요일'),
	(1059, '아트스시', '06241  서울 강남구 테헤란로4길 46 (역삼동, 쌍용플래티넘밸류)  B125호', 'images/아트스시_1059.jpg', '정성 들여 만든 밥과 신선한 재료가 어우러져 예술 같은 맛을 자랑하는 스시 전문점\n\n정성 들여 만든 밥과 신선한 재료가 어우러져 예술 같은 맛을 자랑하는 스시 전문점입니다. 사장님의 정성이 담긴 스시는 입안에서 살살 녹는 부드러운 식감과 풍부한 맛이 특징입니다. 혼자 여행하는 관광객에게 혼밥하기 좋은 아늑한 공간으로 구성되어 있습니다. 가성비가 뛰어난 가격대에 고품질 스시를 제공하여 강남역 인근에서 맛있고 합리적인 가격에 스시를 즐기고 싶다면 이곳을 추천합니다.', 37.495548, 127.030065, '', '지하철 2호선/신분당선 강남역 4번 출구, 189m', '모듬초밥 A(8P), 모듬초밥 B(10p)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:00 (15:00 - 17:30 브레이크타임, 20:30 라스트오더)', '-8002', '매주 토 - 일'),
	(1060, '어부의딸', '07008  서울 동작구 동작대로25길 9-6 (사당동)', 'images/어부의딸_1060.jpg', '산꼼장어 구이와 산쭈꾸미 구이가 대표 메뉴\n\n산꼼장어 구이와 산쭈꾸미 구이가 대표 메뉴입니다. 산꼼장어와 산쭈꾸미는 제철이 아닐 때에는 찾기 어려운 해산물이지만, 이곳은 신선한 재료를 사용하여 그 맛을 최상의 상태로 제공합니다. 산꼼장어는 부드럽고 풍부한 맛을 자랑하며, 산쭈꾸미는 탱글탱글한 식감과 강렬한 불향이 특징인 음식으로 많은 사람들이 찾는 인기 있는 곳입니다.', 37.486183, 126.981390, '', '지하철 4/7호선 총신대입구(이수)역 13번 출구, 108m', '산꼼장어 구이, 산쭈꾸미 구이', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '13:00 - 24:00 (매주 일요일 휴무)', '-5839', ''),
	(1061, '룻 root', '03062  서울 종로구 율곡로1길 54-1 (사간동)', 'images/룻_root_1061.jpg', '새롭게 재해석한 한식과 국내 최다 150여 종의 전통주를 페어링할 수 있는 레스토랑\n\n식문화에 대한 깊은 이해와 재해석을 지향합니다. 룻은 ㅅㅜㄹ(술)의 한글 배열을 거꾸로 쌓아 올린 형상입니다. 모든 식(食)에 대한 근원을 탐구하며, 익숙한 식문화를 재조명하여 새로운 관점으로 바라봅니다. 대표메뉴는 항정쌈, 숯불구이육회, 한입거리, 전통주 150 종이 있어 다양한 음식과 전통주를 즐겨볼 수 있습니다.', 37.578289, 126.981001, '', '지하철 3호선 안국역 1번출구, 575m / 5호선 광화문역 2번출구, 877m', '', '화-일', ' https://restaurantroot.com/', '', '영어 응대 가능\n매장 예약 시 룻의 인스타그램 다이렉트 메시지 또는 캐치테이블 이용', '런치 11:30-15:00 / 디너 17:00-22:00', '070-4740-2370', '매주 월요일'),
	(1062, '잠수교집 성수 직영점', '04797  서울 성동구 아차산로 137 (성수동2가, 승림빌딩)  1층 잠수교집', 'images/잠수교집_성수_직영점_1062.png', '잠수교집 성수 직영점은 냉동 삼겹살과 다양한 밑반찬을 제공하며, 직원이 구워주는 삼겹살과 함께 풍성한 식사를 즐길 수 있는 맛집이다.\n\n잠수교집 성수 직영점은 냉동 삼겹살의 편견을 깨고 새로운 맛을 선보이는 맛집이다. \n\n이곳의 특징은 직원이 구워주는 삼겹살로, 신선한 냉동 삼겹살의 맛을 그대로 느낄 수 있다. 다양한 밑반찬이 함께 제공되며, 김치, 백김치, 달걀 마리, 파절임, 무채나물 등 13가지 반찬이 컬러풀한 쟁반에 담겨 나온다. 또한, 청국장, 얼큰순두부, 명란탕 등 다양한 식사 메뉴가 함께 제공되어 더욱 풍성한 식사를 즐길 수 있다. 잠수교집 성수점은 성수역 2번 출구 부근에 위치해 있으며, 매장 앞에 주차장이 있지만 협소하므로 대중교통 이용을 권장한다. 식사 시간은 2시간으로 제한되어 있으며, 웨이팅이 있을 수 있으니 참고해야 한다. 주변의 성수동 구두 테마공원이나 가중나무공원에서 식사 전후 산책을 즐길 수 있다.', 37.543811, 127.059368, '', '2호선 성수역 2번 출구에서 약 220m (도보 3분)', '', '매일', ' https://www.instagram.com/jamsugyojib_2918/', '', '', '11:30 ~ 04:30', '0507-1326-0434', ''),
	(1063, '마를리', '04782  서울 성동구 연무장길 47 1층', 'images/마를리_1063.jpg', '케이크와 스콘이 맛있는 대형 디저트 카페\n\n140여평 규모의 1,2층으로 나뉘어져 있는 대형 카페로 성수동 카페거리에 위치해 있습니다. 채광이 잘 들어오는 넓은 창문과 곳곳에 놓여진 오브제, 감각적인 인테리어는 마치 갤러리에 온 듯한 느낌을 들게 합니다. 케이크와 스콘 전문점으로 커피와 함께 디저트를 즐길 수 있습니다.', 37.542799, 127.054734, '', '지하철 2호선 성수역 4번출구, 292m', '', '', ' https://www.instagram.com/marly.official_', '', '홀케이크 주문은 최소 2~3일전까지 문의', '매일 09:00-23:00', '02-467-0303', ''),
	(1064, '백제삼계탕', '04536  서울 중구 명동8길 8-10 (명동2가)', 'images/백제삼계탕_1064.jpg', '전통 제조 방식을 50여 년째 유지하는 깊고 맑은 국물의 삼계탕.\n\n인삼, 대추, 찹쌀, 마늘만을 사용한 전통 제조 방식을 50여 년째 유지하고 있으며, 깊고 맑은 국물이 일품다입니다. 이곳의 삼계탕은 일본, 중국, 동남아 등의 TV 방송에 소개된 바 있으며, 전통의 맛을 그대로 살린 삼계탕으로 많은 관광객들이 찾는 명소입니다. 오랜 역사와 전통을 자랑하는 명동 백제삼계탕에서 진정한 삼계탕의 깊은 맛을 경험해 볼 수 있습니다', 37.563372, 126.984101, '', '지하철 4호선 명동역 6번 출구, 317m', '삼계탕, 오골계탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '09:00 - 22:00 (21:00 라스트오더)', '-3963', ''),
	(1065, '사마르칸트', '04561  서울 중구 마른내로 159-10 (광희동1가)', 'images/사마르칸트_1065.jpg', '우즈베키스탄 정통 현지 음식을 맛볼 수 있는 곳. 현지인들에게도 인기 있는 식당\n\n우즈베키스탄 정통 현지 음식을 맛볼 수 있는 이곳은 한국인뿐만 아니라 현지인들에게도 인기 있는 식당입니다. 특히 우즈베키스탄 전통 꼬치 요리인 샤슬릭은 향긋한 양념에 재워 구워낸 고기로, 입안에서 풍미가 가득 느껴지며 부담 없이 즐기기 좋습니다. 이곳의 전통 우즈베키스탄 음식들은 독특한 향신료와 조리법으로 현지의 맛을 그대로 재현하여, 새로운 미식 경험을 선사합니다.', 37.565038, 127.005922, '', '지하철 2/4/5호선 동대문역사문화공원역 7번 출구, 192m', '양고기꼬치, 양고기샤브샤브', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 23:00', '-6458', ''),
	(1066, '술탄케밥', '04406  서울 용산구 보광로 126 (이태원동)', 'images/술탄케밥_1066.jpg', '이태원에서 가장 먼저 시작된 케밥 매장, 24시간 영업.\n\n이태원에서 가장 먼저 시작된 케밥 매장으로, 닭고기와 양고기 케밥, 팔라펠 등 튀르키예 전통 요리를 캐주얼하게 즐길 수 있습니다. 오랜 시간 동안 변하지 않는 맛으로 많은 단골들이 찾는 곳이며, 24시간 영업하여 늦은 밤에도 출출한 배를 채울 수 있는 완벽한 장소입니다.', 37.534038, 126.994243, '', '지하철 6호선 이태원역 3번 출구, 67m', '치킨 케밥', '', ' http://www.instagram.com/sultankebab2007/', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '00:00 - 24:00', '-5646', ''),
	(1067, '지코바치킨 홍대서교점', '04039  서울 마포구 홍익로5안길 43 (서교동)  1층', 'images/지코바치킨_홍대서교점_1067.jpg', '기름기 없이 담백한 K-CHICKEN의 대표 브랜드, 지코바치킨.\n\n기름기 없이 담백한 K-CHICKEN의 대표 브랜드, 지코바치킨. 튀기지 않고 구워 촉촉하고 담백한 맛이 돋보이는 이 프랜차이즈는 K-CHICKEN의 새로운 기준을 제시합니다. 한국의 먹거리 트렌드인 치밥(치킨+밥)의 대표적인 메뉴로, 흰 쌀밥과 함께 맛보는 것을 추천합니다. 치밥에 특히 잘 어울리는 메뉴는 순살 양념구이 치킨으로, 간편하면서도 깊은 맛을 자랑합니다', 37.552906, 126.920687, '', '지하철 2호선 /공항철도/경의중앙선 홍대입구역 9번 출구, 503m', '순살소금구이, 순살양념구이치킨', '', ' http://www.gcova.co.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:10 - 23:55 (23:45 라스트오더)', '-9478', ''),
	(1068, '별난오리', '03119  서울 종로구 종로46길 12 (창신동)  2층', 'images/별난오리_1068.jpg', '두 가지 요리를 함께 즐기는 오리구이와 오리탕 세트.\n\n오리구이와 오리탕을 반씩 제공하는 메뉴로 두 가지 요리를 모두 즐길 수 있어 선택의 재미가 있습니다. 오리구이는 촉촉하고 풍미 깊은 훈제오리로, 바삭한 껍질과 부드러운 속살이 조화롭습니다. 오리탕은 진한 국물 맛과 함께 오리 고기의 부드러움이 특징입니다. 특히 훈제오리와 갖가지 채소절임을 함께 먹으면 신선한 채소의 아삭함과 오리의 풍미가 잘 어울립니다.', 37.571065, 127.010600, '', '지하철 1/4호선 동대문역 7번 출구, 77m', '훈제오리 반마리+탕반마리, 전기훈제오리구이 한마리', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (15:00 - 17:00 브레이크타임 )\n토 11:00 - 21:00', '-5977', '일요일'),
	(1069, '옴레스토랑 마포공덕점', '04157  서울 마포구 마포대로 73 (도화동, 에스케이허브그린)  201호', 'images/옴레스토랑_마포공덕점_1069.jpg', '한국에서 현지 인도 커리의 맛으로 인정받고 있는 가게\n\n한국에서 현지 인도 커리의 맛으로 인정받고 있는 가게입니다. 마포공덕을 비롯해 광화문과 광교에도 지점이 있습니다. 다양한 세트 메뉴로 스프, 탄두리 치킨, 커리, 난, 라씨 등 인도 음식을 한 상에서 제대로 즐길 수 있습니다. 또한 인도식 볶음밥인 브리야니도 제공하므로 독특한 음식을 원한다면 한 번 시도해보세요.', 37.542323, 126.948978, '', '지하철 5/6호선 /공항철도/경의중앙선 공덕역 1번 출구, 225m', '브리야니, 오늘의 탈리세트', '', ' http://www.omfood.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-5493', ''),
	(1070, '인현골방', '04556  서울 중구 마른내로 60-1 2층', 'images/인현골방_1070.png', '분위기 있는 음악과 독특한 컨셉의 만남이 있는 뮤직바\n\n복잡한 하루 음악의 위로가 필요할 때 조용히 음악 즐기기 좋은 을지로에 위치한 뮤직바입니다. 편안한 리클라이너 소파에 앉아 내가 직접 만드는 선곡표, 그리고 취향대로 선택하는 하이볼~위스키를 즐기며 음악감상을 할 수 있는 바입니다. 음악감상에 집중하기 위해 일행간의 대화는 불가합니다. 지친 하루를 음악으로 위로받고 싶다면 혼술하기 좋은 인현골방을 추천합니다.', 37.564168, 126.994512, '', '지하철 2호선/3호선, 을지로3가역 8번출구, 235m', '', '', ' https://www.instagram.com/inhyungolbang/', '', '', '월,수,일 : 17:00~23:00\n화, 목, 금, 토 : 17:00~01:00', '0507-1419-8720', ''),
	(1071, '이태리이층집', '04382  서울 용산구 한강대로48길 15 2층 이태리이층집', 'images/이태리이층집_1071.jpg', '파스타가 맛있는 용리단길 퓨전 양식 레스토랑\n\n양식 전문 30년 경력 셰프님의 노하우가 있는 퓨전 양식 레스토랑으로 용산 주민들 사이에는 다 아는 용리단길 맛집입니다. 미녀와 야수 한 장면을 그대로 담아온 인테리어로 로맨틱하고 고급스러운 분위기 속에서 부담스럽지 않는 가격으로 이탈리아 퓨전 양식을 맛보실 수 있습니다.', 37.531620, 126.971464, '', '지하철 4호선/6호선 삼각지역 3번출구, 274m', '', '', ' https://www.instagram.com/a_twostory_italy/', '', '콜키지 가능(유료), 반려동물 동반 가능', '화~일 11:30-22:00 / 15:00-17:00(화~금), 15:30-17:00(토,일) 브레이크타임 / 21:00 라스트오더', '0507-1471-8027', '매주 월요일'),
	(1072, '이모네골뱅이전문점', '02446  서울 동대문구 회기로28길 7 (휘경동, 휘경동 코업레지던스)', 'images/이모네골뱅이전문점_1072.jpg', '포장마차 분위기의 골뱅이 요리 전문점\n\n포장마차 분위기의 골뱅이 요리 전문점으로, 신선한 통골뱅이를 쪄서 그대로 제공하는 곳입니다. 골뱅이 무침은 통조림이 아닌 신선한 재료로 만들어져 제대로 된 맛을 즐길 수 있습니다. 홍합탕과 계란말이도 함께 맛보는 것을 추천하며, 전체적으로 푸짐하고 맛있는 한 끼를 제공하는 식당입니다.', 37.589569, 127.056441, '', '지하철 1호선/경의중앙선/경춘선 회기역 1번 출구, 163m', '통골뱅이(대), 골뱅이무침', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '13:00 - 02:00', '-10083', ''),
	(1073, '우살롱', '06022  서울 강남구 압구정로32길 24 (신사동)  지하1층', 'images/우살롱_1073.jpg', '최고급 1++ 한우와 독창적인 음식을 즐길 수 있는 프리미엄 레스토랑\n\n최고급 1++ 한우와 독창적인 음식을 즐길 수 있는 프리미엄 레스토랑입니다. 한우 불고기를 돌솥에 정성스럽게 조리한 한우 뚝배기 불고기와 신선한 한우 육회와 함께 각종 채소와 양념이 어우러진 한우 육회 비빔밥은 한우의 풍미를 가성비 좋게 즐길 수 있는 메뉴입니다. 또한 이곳의 대표 메뉴인 우살롱 한우 모듬은 한우 등심, 안심, 살치살, 안창살, 차돌과 계절 야채를 모둠으로 제공하여 다양하고 풍부한 맛을 경험할 수 있습니다.', 37.526180, 127.029771, '', '지하철 3호선 압구정역 3번 출구, 196m', '우살롱 한우모듬, 한우뚝배기불고기세트, 한우곰탕한상 (점심메뉴)', '', ' https://www.instagram.com/woosalon_apgu/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 22:30 (14:00 - 17:00 브레이크타임, 21:30 라스트오더)', '-6509', '매주 일요일'),
	(1074, '케르반 베이커리&카페', '04405  서울 용산구 이태원로 208 (한남동, 제임스클럽)', 'images/케르반_베이커리&카페_1074.jpg', '튀르키예식 디저트와 홍차, 커피. 로쿰과 바게트.\n\n이태원에서 만날 수 있는 작은 튀르키예라고 할 수 있는 이곳은, 튀르키예식 디저트와 홍차, 커피를 즐기며 마치 튀르키예 여행을 떠난 듯한 기분을 선사합니다. 또한, 튀르키예에서만 맛볼 수 있는 로쿰과 바게트 등도 판매하고 있어, 포장해 숙소에서 여유롭게 즐기기에도 좋습니다.', 37.534541, 126.997056, '', '지하철 6호선 이태원역 3번 출구, 242m', '두바이 초콜릿, 카이막 1인세트', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '10:00 - 22:30\n금, 토 10:00 - 06:00', '-7397', ''),
	(1075, '형제육회 본점', '03195  서울 종로구 종로 200-1 (종로4가)', 'images/형제육회_본점_1075.jpg', '육회 골목에 위치한 이 육회 전문점은 한국 전통 요리인 육회를 주로 제공\n\n육회 골목에 위치한 이 육회 전문점은 한국 전통 요리인 육회를 주로 제공하는 곳입니다. 육회는 신선한 소고기를 얇게 썰어 양념과 함께 제공하는 요리로, 고소하고 부드러운 맛이 특징입니다. 특히 점심과 저녁 식사 시간에는 대기 줄이 길어질 수 있지만, 신선한 육회와 다양한 고기 요리를 고려하면 충분히 기다릴 가치가 있는 곳입니다.', 37.570618, 127.000044, '', '지하철 1호선 종로5가역 8번 출구, 162m', '육회, 육회 비빔밥', '', ' http://www.yukhoe.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '09:30 - 22:50', '-8703', '매주 수요일'),
	(1076, '구덴구덴', '04633  서울 중구 퇴계로8길 49-27 (회현동1가)', 'images/구덴구덴_1076.png', '구덴구덴은 회현역 근처 조용한 골목에 자리한 아늑한 카페로, 커피와 간단한 식사를 즐기며 여유를 만끽할 수 있는 공간이다.\n\n구덴구덴은 회현역 근처 조용한 골목에 자리한 작은 카페로, 마치 일본 시골 어딘가에 있을 법한 아늑한 분위기를 자랑한다. 아담한 공간 속 따뜻한 감성이 가득한 이곳에서는 필터커피, 머신커피, 꽃차 같은 다양한 음료와 티라미수, 간단히 배를 채우기 좋은 오늘의 식사를 선보인다. 여유로운 한때를 보내기에 좋은 구덴구덴은 은은한 조명과 소박한 인테리어로 편안함을 더한다. 애견 동반이 가능해 반려견과 함께 시간을 보낼 수 있는 것도 이곳의 매력이다. 커피 한 잔과 함께 일상의 소소한 여유를 즐기기 좋은 곳이다.', 37.556830, 126.980669, '', '4호선 회현역 3번 출구에서 약 358m (도보 7분)', '', '화 ~ 일', ' https://www.instagram.com/cafegudenguden', '', '', '화 ~ 금 10:00 - 19:00\n주말 11:00 - 20:00', '0507-1474-3488', '월'),
	(1077, '델리인디아', '04048  서울 마포구 독막로9길 8 (서교동)  2층', 'images/델리인디아_1077.jpg', '인도인이 직접 운영하는 퓨전 인도 음식점\n\n인도인이 직접 운영하는 퓨전 인도 음식점입니다. 전통 인도요리가 초보자에게는 다소 부담스러울 수 있지만, 델리인디아의 요리는 초보자도 부담 없이 즐길 수 있는 맛입니다. 푸짐한 양으로 늘 손님들이 끊이지 않는 편이며, 특히 버터 치킨은 진한 커리가 부담스러운 사람들을 위해 연한 치킨커리로 선보이는 인기 메뉴입니다.', 37.548690, 126.919744, '', '지하철 2/6호선 합정역 6번 출구, 564m', '델리인디아 A 세트, 버터치킨', '', ' http://www.instagram.com/delhi_india_seokyo', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-3938', ''),
	(1078, '앤티크커피 연남점', '03985  서울 마포구 연희로 25-1 1층 앤티크커피', 'images/앤티크커피_연남점_1078.png', '맛있는 케이크와 디저트가 반짝이는 예쁜 공간\n\n앤티크커피는 이름 그대로 깊어지는 순간의 가치를 전달하고자 하는 커피&디저트카페 브랜드입니다. 매일 전문 바리스타와 파티셰가 세련되고 맛있는 최상의 커피와 디저트를 만들어 제공합니다. 대표메뉴로는 더티앤크림커피, 체리 쇼콜라 케이크, 더티앤크림 크로아상 등이 있습니다. 실내 곳곳에 화사한 꽃들로 앤틱하면서 중후한 분위기를 느낄 수 있습니다.', 37.561268, 126.926563, '', '지하철 2호선/경의중앙/공항철도, 홍대입구역 3번출구, 384m', '', '', '', '', '', '매일 10:00~22:00', '0507-1401-0508', ''),
	(1079, '뉴델리', '02453  서울 동대문구 경희대로6길 5 (회기동)  2층', 'images/뉴델리_1079.jpg', '인도 요리의 진수를 경험할 수 있는 전문 레스토랑\n\n주방장의 오랜 경험에서 우러나오는 깊고 오묘한 인도 요리의 진수를 경험할 수 있는 전문 레스토랑입니다. 탄두리 치킨과 치킨 마크니는 인도 현지 스타일로 조리된 대표 메뉴로, 그 특유의 맛을 엄선된 재료로 완벽하게 재현합니다. 이외에도 다양한 인도 요리가 준비되어 있어, 진정한 인도 미식을 한 자리에서 즐길 수 있습니다.', 37.593379, 127.053143, '', '지하철 1호선/ 경의중앙선/ 경춘선 회기역 1번 출구, 712m', '탄두리 치킨, 치킨 마카니', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00', '-9789', ''),
	(1080, '어메이징 브루잉컴퍼니 성수 브루펍', '04780  서울 성동구 성수일로4길 4 (성수동1가)', 'images/어메이징_브루잉컴퍼니_성수_브루펍_1080.jpg', '직접 양조한 50가지의 신선한 크래프트 비어를 마실 수 있는 펍\n\n어메이징브루잉컴퍼니 성수 브루어리는 2016년 어메이징브루잉컴퍼니가 시작한 곳으로, 성수동을 대표하는 문화공간입니다. 연 60톤을 생산할 수 있는 브루펍에서 양조한 약 50가지의 신선한 크래프트 비어와 함께, 직접 만든 도우로 굽는 화덕피자를 즐겨보실 수 있습니다.', 37.542853, 127.049366, '', '지하철 2호선 뚝섬역 5번출구, 447m', '', '', ' http://www.amazingbrewing.co.kr', '', '근처 공영주차장을 이용해주세요.', '평일 17:00-24:00\n토 15:00-24:00 / 일 14:00-23:00', '0507-1401-5208', ''),
	(1081, '카페 시바', '04352  서울 용산구 한강대로 276-1 (남영동)  1층', 'images/카페_시바_1081.jpg', '다양한 시그니처 비건 음식과 음료\n\nSIVA는 Serve International Vegan Awareness의 약자로 TriYoga International 산하의 Vegan 활동단체의 약자입니다. 이곳은 다양한 시그니처 비건 음식과 음료를 선보이며, 편안하고 뜻깊은 시간을 함께 나눌 수 있는 공간을 제공합니다. 비건과 요가를 사랑하는 사람들이 많이 찾는 장소로, 건강한 라이프스타일을 추구하는 이들에게 최적의 환경을 제공합니다.', 37.542959, 126.972822, '', '지하철 4호선 숙대입구역 6번 출구, 97m', '슈프림 양념 푸라이드, 김치나베카츠파스타', '', ' http://www.instagram.com/cafe.siva', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:00 (15:00 - 17:00 브레이크타임, 14:00, 20:00 라스트오더)', '-3116', ''),
	(1082, '소살리토바닷가재', '03162  서울 종로구 인사동길 15-3 (인사동)  1층', 'images/소살리토바닷가재_1082.jpg', '바닷가재요리 전문점, 비주얼부터 압도적인 로브스터 한 상을 추천\n\n색다른 음식을 원한다면, 비주얼부터 압도적인 로브스터 한 상을 추천합니다. 푸짐한 바닷가재와 깔끔한 플레이팅이 돋보이는 이 레스토랑은 미식가들에게 강력히 추천할 만한 장소입니다. 고급스러운 분위기와 세심한 서비스가 어우러져 특별한 식사 경험을 제공합니다. 특히 찜과 버터 오븐구이 세트 메뉴는 많은 고객들에게 사랑받고 있으며, 풍미 가득한 바다가재의 맛을 다양한 방식으로 즐길 수 있습니다.', 37.572136, 126.986517, '', '지하철 1/3/5호선 종로3가역 5번 출구, 276m', '찜&버터 오픈구이, 버터오븐구이', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 21:30(14:30~17:00 브레이크타임)', '-6904', '매주 일요일'),
	(1083, '발리인망원', '04017  서울 마포구 포은로 67 (망원동)  1층', 'images/발리인망원_1083.png', '신선한 재료로 발리 현지의 맛을 재현한 곳.\n\n신선한 재료로 발리 현지의 맛을 재현하는 이곳은 발리 분위기가 물씬 나는 인테리어로 유명합니다. 미고랭과 나시고랭은 인도네시아와 발리에서 인기 있는 대표적인 요리로, 신선한 재료와 독특한 소스가 조화를 이루는 것이 특징입니다. 현지의 분위기를 물씬 느낄 수 있는 대표적인 메뉴로 이외에 어떤 음식을 주문해도 맛있게 먹을 수 있는 곳입니다.', 37.553290, 126.906036, '', '지하철 6호선 망원역 2번 출구, 519m', '미고랭, 나시고랭', '', ' http://www.instagram.com/bali_in_mangwon', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:00 (15:00 - 17:00 브레이크타임, 20:00 라스트오더)', '-2357', '매주 일요일'),
	(1084, '파르투내', '04560  서울 중구 마른내로 154 (광희동1가)  1, 2층', 'images/파르투내_1084.jpg', '중앙아시아 음식을 제공.러시아 가정식부터 최고급 우즈베키스탄 요리\n\n한국에서 보기 드문 중앙아시아 음식을 제공하며, 처음 방문한 손님들로부터 호평을 받고 있습니다. 러시아 가정식부터 최고급 우즈베키스탄 요리까지 다양하게 선보이며, 특히 우즈베키스탄의 대표 요리인 샤슬릭(그릴에 구운 양고기)과 슈르파(진한 국물의 양고기 스튜)는 풍미가 깊고 독특합니다. 이국적인 맛과 풍부한 향을 경험할 수 있는 특별한 식사 장소입니다.', 37.564601, 127.005094, '', '지하철 2/4/5호선 동대문역사문화공원역 6번 출구, 128m', '샤슬릭, 슈르파', '', ' https://www.instagram.com/restaurant_fortune_food', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓞ', '10:00 - 23:00', '-4555', ''),
	(1085, '케르반 레스토랑', '04406  서울 용산구 이태원로 192 (이태원동)', 'images/케르반_레스토랑_1085.jpg', '다양한 방송에서 소개된 튀르키예 전문 레스토랑\n\n다양한 방송에서 소개된 튀르키예 전문 레스토랑으로, 튀르키예에서 직접 공수해온 인테리어 소품들이 이국적인 분위기를 자아냅니다. 튀르키예 케밥, 피데, 디저트 등 다양한 전통 음식을 제공하며 튀르키예의 풍부한 문화를 경험할 수 있는 곳입니다. 현지인이 직접 요리하여 전통적인 조리법으로 맛을 낸 바비큐는 진정한 튀르키예의 맛을 그대로 재현하며, 구워진 고기와 향신료의 조화가 일품입니다.', 37.534367, 126.995372, '', '지하철 6호선 이태원역 3번 출구, 97m', '치킨커리런치세트, 양고기커리런치세트', '', ' https://www.instagram.com/kervankorea', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 06:00', '-6604', ''),
	(1086, '백년토종삼계탕', '04038  서울 마포구 양화로 118 (서교동)  1층', 'images/백년토종삼계탕_1086.jpg', '30년 전통의 삼계탕 전문점. 닭볶음탕과 후라이드 치킨도 별미.\n\n30년 전통의 삼계탕 전문점으로, 조미료 없이 인삼, 대추, 마늘 등 푸짐한 재료가 어우러져 담백하고 깊은 맛을 자랑합니다. 이곳의 삼계탕은 원기 회복에 탁월하여, 한번 방문한 사람은 삼계탕 생각이 날 때마다 늘 이곳을 찾는다고 할 정도로 믿음직한 식당입니다. 삼계탕 외에도 닭볶음탕과 후라이드 치킨도 별미로, 다양한 메뉴를 함께 맛보는 것도 좋습니다.', 37.553826, 126.920232, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 9번 출구, 396m', '토종삼계탕, 닭볶음탕', '', ' https://100tojong.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '09:00 - 22:00', '-5271', ''),
	(1087, '마히나 비건 테이블', '06029  서울 강남구 논현로175길 75 (신사동)  2층', 'images/마히나_비건_테이블_1087.jpg', '동물성 재료를 전혀 사용하지 않고, 식물성 재료만을 이용해 만든 요리\n\n비건 음식은 동물성 재료를 전혀 사용하지 않고, 식물성 재료만을 이용해 만든 요리를 말합니다. 이곳은 동물성 재료를 사용하지 않는 비건 식당으로 건강하고 신선한 재료를 사용합니다. 번, 파스타 소스, 빵 등 모든 메뉴는 매장에서 직접 만들어 더욱 풍부한 맛과 높은 퀄리티를 자랑합니다. 비건이라면 꼭 들러야 할 장소입니다.', 37.523657, 127.023049, '', '지하철 3호선 압구정역 5번 출구, 585m', '그릴드 컬리플라워 스테이크, 버섯 바질 파스타', '', ' http://mahinavegan.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 21:00 (16:00 - 17:00 브레이크타임, 20:20 라스트오더)', '-7127', ''),
	(1088, '보름쇠', '06167  서울 강남구 테헤란로81길 36 (삼성동)', 'images/보름쇠_1088.jpg', '미쉐린 가이드 서울 2024에 실린 소고기 구이 레스토랑\n\n미쉐린 가이드 서울 2024에 실린 소고기 구이 레스토랑입니다. 특히 점심시간에만 제공되는 버섯 생불고기 메뉴는 소고기 본연의 맛을 살린 세지 않은 양념에 다양한 종류의 신선한 버섯이 함께 제공되는 것이 특징입니다. 소고기 구이는 다양한 부위로 준비되어 있어 취향에 맞게 선택할 수 있습니다.', 37.509315, 127.056632, '', '지하철 9호선 삼성중앙역 5번 출구, 497m', '버섯 생불고기 점심특선, 흑우 구이정식 점심특선', '', ' https://www.instagram.com/boreum_sae', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '월~금 11:30 - 22:00 (15:00 - 17:00 브레이크타임, 21:00 라스트오더)\n토~일 11:30~22:00', '02-569-9967', ''),
	(1089, '타쉬켄트케밥', '04561  서울 중구 을지로42길 8 (을지로6가)', 'images/타쉬켄트케밥_1089.jpg', '촉촉한 패티의 식감과 풍미가 호평받는 이곳의 케밥은 묵직한 한 끼로 충분\n\n촉촉한 패티의 식감과 풍미가 호평받는 이곳의 케밥은 묵직한 한 끼로 충분합니다. 세트로 제공되는 감자튀김도 별미로, 함께 맛보는 것을 추천합니다. 특히, 서울에서는 보기 드문 피시 케밥은 신선한 생선으로 만들어져 독특한 맛과 식감을 제공하며, 색다른 케밥을 경험하고 싶은 사람에게 강력히 추천합니다.', 37.565881, 127.005701, '', '지하철 2/4/5호선 동대문역사문화공원역 12번 출구, 168m', '논케밥M. 도너케밥M. 피쉬 케밥', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00~01:00', '-9142', ''),
	(1090, '에삐 EPI', '06161  서울 강남구 선릉로 518 1층', 'images/에삐_EPI_1090.png', '분위기 좋은 선릉역 베이커리 카페\n\n선릉역 주위에 위치한 에삐는 베이커리 카페로 다양한 빵 종류를 맛보실 수 있습니다. 바게트, 소금빵, 치아바타, 구움과자류가 메인 제품이며, 중남미로 구성된 풍부한 견과류의 고소함과 은은한 산미의 밸런스가 특징인 스페셜티커피를 제공합니다. 매주 빵 종류별 나오는 시간 공지를 확인하고 시간에 맞춰 갓나온 맛있는 빵을 즐겨보시길 바랍니다.', 37.505842, 127.048604, '', '지하철 2호선/수인분당선 선릉역 8번출구, 100m', '', '', ' https://www.instagram.com/epi.kr', '', '반려동물 동반가능', '07:00-21:00', '0507-1308-3035', ''),
	(1091, '조개꽃천지 마포공덕점', '04211  서울 마포구 마포대로10길 12 (공덕동, 트레퍼빌딩)  B1', 'images/조개꽃천지_마포공덕점_1091.jpg', '살아있는 문어와 전복, 가리비, 키조개 등 다양한 해산물이 가득 담긴 푸짐한 해신탕\n\n살아있는 문어와 전복, 가리비, 키조개 등 다양한 해산물이 가득 담긴 푸짐한 해신탕이 시선을 사로잡습니다. 특제 육수에 익혀 해산물의 깊은 맛을 한껏 느낄 수 있으며, 몸보신 효과도 덤으로 챙길 수 있습니다. 이곳의 해신탕은 각종 해산물이 골고루 들어가 있어 풍성한 맛과 식감을 자랑하며, 진한 국물 맛이 해산물 본연의 맛을 더욱 돋보이게 합니다.', 37.547048, 126.954292, '', '지하철 5/6호선/공항철도/경의중앙선 공덕역 4번 출구, 313m', '황후 해신탕, 황후조개꽃문어', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00', '-6410', '매주 일요일'),
	(1092, '스시한판 스타필드코엑스몰점', '06164  서울 강남구 봉은사로 524 (삼성동, 코엑스인터콘티넨탈서울)  L129', 'images/스시한판_스타필드코엑스몰점_1092.jpg', '신선한 해산물과 다양한 재료로 만들어진 스시 모둠 한 판\n\n관광명소인 코엑스를 방문할 때 식사 시간에 방문하는 것이 좋습니다. 다양한 모둠 메뉴들이 준비되어 있어 일행과 함께 여러 가지 음식을 시켜 즐기기 좋습니다. 특히, 신선한 해산물과 다양한 재료로 만들어진 스시 모둠 한 판은 입맛을 돋우기에 최적입니다. 각종 스시가 조화롭게 배열된 모둠 한 판을 통해 다양한 맛을 한 번에 경험할 수 있습니다.', 37.512953, 127.057116, '', '지하철 9호선 봉은사역 7번 출구, 191m', '모듬한판, 참치한판', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '02-6002-3838', ''),
	(1093, '집밥김선생', '04390  서울 용산구 녹사평대로32길 3 (이태원동)  1층', 'images/집밥김선생_1093.jpg', '할랄 한식을 전문으로 선보이는 이곳은 잡채, 김치찌개, 치킨 등 대표적인 한식 메뉴\n\n할랄 한식을 전문으로 선보이는 이곳은 잡채, 김치찌개, 치킨 등 대표적인 한식 메뉴를 할랄 방식으로 제공합니다. 할랄 한식의 중요성을 알리기 위해 운영되는 이 식당은 깔끔한 분위기에서 다양한 반찬이 곁들어진 한 상을 차려줍니다. 진정한 한식의 맛을 경험하고 싶다면 이곳이 제격입니다.', 37.533676, 126.989018, '', '지하철 6호선 녹사평역 3번 출구, 264m', '누들스테이크, 불고기 한상', '', ' http://www.starcatering.co.kr/', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:30 - 21:30 (14:00~15:00 브레이크타임 21:00 라스트오더)', '-5543', '매주 일요일'),
	(1094, '차칸스시', '02452  서울 동대문구 회기로25길 52 (이문동)  1층', 'images/차칸스시_1094.jpg', '신선한 활어를 사용하는 이곳은 깔끔하고 맛있는 초밥을 제공\n\n신선한 활어를 사용하는 이곳은 깔끔하고 맛있는 초밥을 제공합니다. 차칸이라는 이름에 걸맞게 정성을 다해 내놓는 음식들로 기분이 좋아질 수밖에 없는 곳입니다. 특선 초밥이나 셰프 초밥은 다양한 생선을 모둠으로 제공하며, 가성비가 좋아 많은 사람들이 찾는 인기 메뉴입니다.', 37.591987, 127.056688, '', '지하철 1호선/경의중앙선/경춘선 회기역 1번 출구, 396m', '특선초밥(12p), 셰프 초밥(12p)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (15:30 - 17:00 브레이크타임, 22:30 라스트오더)', '-2764', ''),
	(1095, '서울삼계탕', '04526  서울 중구 남대문로1길 57-1 (태평로2가)', 'images/서울삼계탕_1095.jpg', '2대에 걸쳐 운영되고 있는 전통 있는 삼계탕 전문점\n\n2대에 걸쳐 운영되고 있는 전통 있는 삼계탕 전문점으로, 삼계탕과 전복삼계탕이 대표 메뉴입니다. 진한 국물 맛과 함께 담백하고 부드러운 닭고기의 조화가 일품입니다. 전복삼계탕은 전복 내장을 갈아 넣은 육수에 신선한 전복을 추가하여 깊은 맛을 더합니다. 전복의 풍미가 국물에 스며들어 더욱 풍부하고 고급스러운 맛을 느낄 수 있습니다.', 37.563646, 126.977568, '', '지하철 1/2호선 시청역 7번 출구, 139m', '삼계탕, 전복삼계탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '09:30 - 21:30 (15:00 - 17:00 브레이크타임)\n토 10:00 - 21:00 (15:00 - 17:00 브레이크타임)', '-10009', '일요일'),
	(1096, '초월', '04158  서울 마포구 마포대로 49 성우빌딩 지하상가 B116호', 'images/초월_1096.jpg', '한국 최남단 땅끝 해남쌀을 이용해 건강하게 만들어지는 전통방식 무감미료 수제 막걸리, 도심 속 양조장\n\n막걸리를 초월하다, 마포역과 공덕역 사이에 위치한 도심 속 양조장 \'초월\' 초월은 쌀, 누룩, 물만을 이용하는 전통방식을 추구하며, 비옥한 평야에서 해풍이 기른 대한민국 최남단 땅끝 해남쌀을 사용 막걸리를 통해 과거와 현재를 잇고, 농촌과 도시를 이어갑니다.', 37.540869, 126.946895, '', '지하철 5호선 마포역 2번출구, 117m / 6호선 공덕역 1번출구, 500m', '초월 6.9 (무감미료 막걸리, 삼양주)', '연중무휴', ' https://www.chowolhada.com', '', '외국어 해설 가능, 초월 가이드 구글맵 링크 제공', '11:30-14:00 /14:00-17:00 Break Time/ 17:00-19:30', '0507-1317-3176', ''),
	(1097, '스타사마르칸트', '04561  서울 중구 을지로42길 14 (을지로6가)', 'images/스타사마르칸트_1097.jpg', '우즈베키스탄 음식점을 대표. 다양한 중앙아시아 요리를 제공.\n\n우즈베키스탄 음식점을 대표하는 이곳은 다양한 중앙아시아 요리를 제공합니다. 우즈베키스탄 전통 요리를 맛볼 수 있는 명소로 유명하며, 특히 중앙아시아의 전통적인 조리법을 그대로 재현한 요리를 선보입니다. 이곳의 음식은 특유의 깊은 맛과 진한 풍미로 많은 사람들에게 인기가 많습니다.', 37.565696, 127.005633, '', '지하철 2/4/5호선 동대문역사문화공원역 12번 출구, 191m', '플로프, 샤슬릭', '', ' https://youtu.be/Xp5XlhAtZ_c?si=B96CFXVm0Vm4hbWV', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '10:00 - 23:00 (22:30 라스트오더)', '-9665', '격주 화요일'),
	(1098, '타코로코', '03787  서울 서대문구 연세로7안길 37 (창천동)  1층', 'images/타코로코_1098.jpg', '다양한 메뉴와 푸짐한 양으로 근방 타코 요리 중 상위권에 꼽히는 곳\n\n다양한 메뉴와 푸짐한 양으로 근방 타코 요리 중 상위권에 꼽히는 곳입니다. 특히 부리또는 부드러운 토르티야에 풍성한 고기와 신선한 채소, 소스를 가득 채운 메뉴로 만족감을 주며, 엔칠라다는 진한 소스와 함께 조리된 타코 속 재료의 조화가 뛰어난 메뉴입니다. 두 가지 메뉴 모두 풍부한 맛과 양으로, 무엇을 먹을지 고민된다면 꼭 추천할 만합니다.', 37.558115, 126.934631, '', '지하철 2호선 신촌역 1번 출구, 468m', '치킨 부리또, 비프 부리또', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '주중 10:30~21:30\n주말 11:00 - 21:30', '-6722', ''),
	(1099, '홍수계찜닭 코엑스점', '06164  서울 강남구 테헤란로87길 46 (삼성동, 호텔오크우드프리미어)  오크우드프리미어호텔 컨벤션별관 지하2층', 'images/홍수계찜닭_코엑스점_1099.jpg', '서울 곳곳에서 만날 수 있는 찜닭 전문 프랜차이즈 식당\n\n서울 곳곳에서 만날 수 있는 찜닭 전문 프랜차이즈 식당입니다. 점심, 저녁 식사시간이면 언제나 붐비는 인기 많은 곳으로 다양한 찜닭 요리를 선보이고 있습니다. 간장 소스가 기본인 일반 찜닭 요리는 물론 해물이 가득 들어간 해물찜닭, 치즈가 얹어져 고소한 맛이 일품인 치즈찜닭 등이 마련돼 있습니다.', 37.510982, 127.058206, '', '지하철 9호선 삼성중앙역 4번 출구, 574m', '찜닭 소, 해물찜닭', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-7479', ''),
	(1100, '모센즈 스위트 대학로점', '03085  서울 종로구 동숭길 84-1 (동숭동)', 'images/모센즈_스위트_대학로점_1100.jpg', '서울 곳곳에서 만날 수 있는 디저트 프랜차이즈 카페로, 특별하고 달콤한 디저트\n\n서울 곳곳에서 만날 수 있는 디저트 프랜차이즈 카페로, 특별하고 달콤한 디저트를 경험하기에 좋은 곳입니다. 부드럽고 크리미한 맛으로 천상의 디저트라 불리는 카이막과 중동에서 인기 있는 고급 디저트 쿠나파가 이곳의 시그니처 메뉴입니다. 커피도 맛있기로 소문나 있어, 식사 후 커피와 함께 달콤한 디저트를 즐기기 딱 좋은 장소입니다.', 37.581989, 127.004253, '', '지하철 4호선 혜화역 2번 출구, 351m', '카이막, 쿠나파', '', ' https://www.instagram.com/mohssen.s_sweets/#', '카페, 디저트', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '12:00 - 21:00 (20:30 라스트오더)', '-2472', ''),
	(1101, '양식당 더램키친', '06028  서울 강남구 압구정로8길 5 (신사동)  2층', 'images/양식당_더램키친_1101.jpg', '숯불 위 불판에서 구워내는 한국적인 양고기를 맛볼 수 있는 곳.\n\n유명 식도락 방송에서도 소개될 만큼 인기를 끌고 있는 이곳에서는 숯불 위 불판에서 구워내는 한국적인 양고기를 맛볼 수 있습니다. 한국식 양고기 스타일이 궁금한 관광객들에게 특히 인기가 많으며, 파절이, 완자, 오이소박이 등 한국식 곁들임 메뉴들과 함께 육즙 가득한 양고기를 한국 스타일로 즐길 수 있습니다.', 37.523024, 127.021354, '', '지하철 3호선 압구정역 5번 출구, 746m', '양갈비(250g) , 양등심(180g)', '', ' https://www.instagram.com/thelambkitchen_official', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '17:00 - 23:00 (22:00 라스트오더)\n토 - 일 12:00 - 23:00 (22:00 라스트오더)', '-11206', ''),
	(1102, '머노까머나 대학로점', '03079  서울 종로구 창경궁로 236 (명륜4가, 이화빌딩)  2층', 'images/머노까머나_대학로점_1102.jpg', '많은 사람들로 붐비는 인도 현지인 요리사가 직접 만드는 인도 전문 레스토랑\n\n언제나 많은 사람들로 붐비는 이 인도 전문 레스토랑은 인도 현지인 요리사가 직접 만드는 정통 인도 요리를 자랑합니다. 대학로에서 오랫동안 사랑받아온 이곳은 인도 요리의 진수를 경험할 수 있는 장소입니다.  특히, 치킨 마크니는 매운맛이 부드럽고 풍미가 가득해 어린이들도 부담 없이 즐길 수 있는 인도 요리로 어린이와 함께 방문한다면 이 메뉴를 추천합니다.', 37.582644, 126.998834, '', '지하철 4호선 혜화역 4번 출구, 251m', '탄두리 치킨(Full), 빨락빠니르(시금치커리)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:30', '-10722', ''),
	(1103, '유숙단부자낙지', '04550  서울 중구 수표로 50-1 (을지로3가)', 'images/유숙단부자낙지_1103.jpg', '다양한 낙지 요리를 선보이는 낙지 전문 식당.\n\n다양한 낙지 요리를 선보이는 이 낙지 전문 식당은 매콤한 낙지볶음을 콩나물과 함께 밥에 비벼 먹으면 입맛이 확 살아나는 곳입니다. 조개탕과 신선한 산낙지를 서비스로 제공하여 푸짐한 인심을 느낄 수 있습니다. 산낙지는 외국인 관광객이 거부감 없이 즐길 수 있도록 신선하게 준비되어 있습니다. 낯선 음식이지만, 걱정하지 말고 도전해보는 것 또한 추천합니다.', 37.565674, 126.989983, '', '지하철 2/3호선 을지로3가역 11번 출구, 65m', '연포무침, 낙지볶음', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00~23:00 (브레이크타임 14:00~16:30)', '-2261', '토요일, 일요일'),
	(1104, '에빠', '04768  서울 성동구 왕십리로5길 19 Etba seoul', 'images/에빠_1104.png', '이태리 감성 가득한 성수 에스프레소 바\n\n이태리 감성 가득한 엔틱한 분위기로 꾸며진 에빠(etba)는 성수에 위치한 에스프레소 바입니다. 원두 블렌딩 연구 과정부터 직접 참여하고, 자체 로스터리에서 로스팅 한 원드를 사용하여 커피의 풍부한 맛을 느낄 수 있습니다. 메뉴는 에스프레소 바답게 에스프레소를 메인으로한 음료 메뉴가 많으며, 논커피 메뉴와 디저트도 있으니 커피를 못 마셔도 에빠의 분위기를 즐길 수 있습니다.', 37.547734, 127.043683, '', '지하철 2호선 뚝섬역 8번출구, 254m', '', '', ' https://www.instagram.com/etba.seoul', '', '', '월,수,목,금 08:00-19:00 토,일 10:00-19:00 (라스트오더 18:30)', '0507-1491-1296', '매주 화요일'),
	(1105, '전주집', '07250  서울 영등포구 영등포로 219 14호', 'images/전주집_1105.jpg', '저렴한 가격에 집밥 먹는 듯한 가성비 좋은 노포 맛집\n\n시장 안 골목에 자리한 전주집은 메뉴부터 가격까지 찐노포 분위기가 물씬 느껴집니다. 흔히 포장마차에서 먹어볼법한 음식 안주류, 식사류, 면류 다양하게 볼 수 있으며, 특히 닭볶음탕, 삼겹살이 인기 메뉴입니다. 선선한 날씨에 도심 한복판 야외에서 맛있는 음식과 술을 함께 즐길 수 있는 로컬 술 문화인 야장 문화를 경험할 수 있습니다.', 37.520144, 126.905750, '', '지하철 5호선 영등포시장역 3번출구, 397m', '', '', '', '', '', '매일 12:00-23:00', '0507-1445-7966', ''),
	(1106, '룸비니 레스토랑', '03104  서울 종로구 종로 333 (창신동)', 'images/룸비니_레스토랑_1106.jpg', '인도 현지 음식과 네팔 현지 음식을 같이 맛볼 수 있는 식당\n\n인도 현지 음식과 네팔 현지 음식을 같이 맛볼 수 있는 식당입니다. 다양한 종류의 커리가 준비되어 있어 골라 먹는 재미가 있습니다. 특히 난이 바삭바삭하고 크기가 커서 푸짐하다는 평을 많이 받습니다. 닭고기를 캐슈넛, 치즈, 크림, 향신료 소스에 절여 구운 연한 바베큐 요리인 치킨 멀러이 케밥도 시그니처 메뉴입니다.', 37.572904, 127.014512, '', '지하철 1/6호선 동묘앞역 8번 출구, 40m', '탄두리 치킨, 달 머커니', '', ' http://www.lumbinifood.com/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-10784', ''),
	(1107, '아마 홍대점', '04038  서울 마포구 양화로16길 10 (서교동)  2층', 'images/아마_홍대점_1107.jpg', '현지에서 직접 공수한 32가지 재료로 인도의 맛을 재현\n\n현지에서 직접 공수한 32가지 재료로 인도의 맛을 재현해내는 아마 홍대점은 15년 전통의 인도 요리 전문점입니다. 인테리어는 인도 현지 분위기가 물씬 느껴져, 마치 인도에서 식사하는 듯한 기분을 만끽할 수 있습니다. 진정한 인도 요리의 맛과 분위기를 그대로 담아낸 이곳은 인도 음식 애호가들에게 추천하는 장소입니다.', 37.553506, 126.920266, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 9번 출구, 406m', '런치커리정식 1인 혼밥 세트, 런치 2인 세트', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-10157', ''),
	(1108, '피크니크 선유도한옥점', '07206  서울 영등포구 양평로22길 2-1 1층', 'images/피크니크_선유도한옥점_1108.png', '피크니크의 시작점, 선유도공원 인근 유일한 한옥 카페\n\n피크니크는 피크닉(Picnic)과 유니크(Unique)의 합성어로, 이곳에서 누리는 모든 순간이 특별한 피크닉처럼 느끼길 바라는 마음으로 지은 이름입니다. 피크니크 선유도한옥점은 피크니크 본점으로 2018년 낡은 한옥을 새단장하여 만들어진 카페입니다. 100년 가까이 된 한옥으로 영등포 지역에서도 손꼽히는 아주 오래된 한옥으로 한옥이 주는 고즈넉한 정취 속에 달콤한 디저트를 음미하며 여유로은 시간을 보내시길 바랍니다.', 37.538009, 126.894368, '', '지하철 9호선 선유도역 3번출구, 26m', '', '', ' https://www.picniq.kr/', '', '', '매일 10:00-21:30', '0507-1314-5784', ''),
	(1109, '케르반 카페, 디저트&브런치', '04405  서울 용산구 우사단로10길 17 (이태원동, 청원탕)  1층', 'images/케르반_카페,_디저트&브런치_1109.jpg', '서울에서 튀르키예의 매혹적인 분위기를 만끽할 수 있는 대표적인 카페\n\n서울에서 튀르키예의 매혹적인 분위기를 만끽할 수 있는 대표적인 카페가 있습니다. 이곳에서는 튀르키예식 독특한 커피와 홍차를 즐길 수 있습니다. \n\n\n부드러운 카이막, 요거트와 비슷한 카이막 무할래비, 터키쉬 쿠키, 바클라바 등 입맛을 사로잡는 다양한 간식이 기다리고 있습니다. 서울에서 가장 현지 맛에 가까우면서도 풍성한 양을 자랑하는 이 카페에서, 진정한 튀르키예의 맛을 경험해 보세요.', 37.533300, 126.996534, '', '지하철 6호선 이태원역 3번 출구, 361m', '카이막2인세트, 메네멘 set', '', ' https://www.instagram.com/kervancafe_itaewon', '카페, 디저트', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '08:00 - 22:00', '-3988', ''),
	(1110, '팔판동꼬마김밥 앤 토스트', '03054  서울 종로구 팔판길 36 1층', 'images/팔판동꼬마김밥_앤_토스트_1110.png', '옛날 조선시대 여덟 명의 판서가 살아 붙여진 팔판동의 김밥이 유명한 분식집\n\nTV 예능 프로그램 <유 퀴즈 온 더 블럭>에 소개되기도 한 팔판김밥은 줄 서서 먹는 맛집입니다. 메뉴는 김밥과 토스트, 어묵이 있으며, 대표 메뉴 팔판김밥은 밥 양이 적고 속이 푸짐해 재료 본연의 맛을 느낄 수 있습니다. 좌석은 4명이 앉을 수 있는 바 테이블로 되어 있고, 방문 포장 손님이 대부분입니다.', 37.583355, 126.981341, '', '지하철 3호선 안국역 1번출구, 1.3km', '', '', '', '', '', '화-일 09:00-19:00', '02-3210-2554', '매주 월요일'),
	(1111, '거북이', '06691  서울 서초구 방배천로4안길 48 (방배동)', 'images/거북이_1111.jpg', '비건 카페지만 비건 디저트라는 느낌이 전혀 들지 않는 메뉴 구성이 매력적인 곳\n\n비건 카페지만 비건 디저트라는 느낌이 전혀 들지 않는 메뉴 구성이 매력적인 곳입니다. 딸기 쇼트케이크, 피스타치오 라즈베리 케이크, 팥빙수, 망고 빙수 등 다양한 디저트가 준비되어 있어, 비건이 아니어도 건강한 맛을 추구하는 방문객들이 끊이지 않습니다. 특별하고 맛있는 디저트를 찾는 모든 이들에게 만족을 선사하는 카페입니다.', 37.480203, 126.983417, '', '지하철 2/4호선 사당역 11번 출구, 395m', '피스타치오 라즈베리 케이크, 팥빙수', '', ' http://www.instagram.com/_cafe_turtle_', '카페, 디저트', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 22:00', '-9317', ''),
	(1112, '포시즌스 호텔 서울 찰스 H.', '03183  서울 종로구 새문안로 97 LL층', 'images/포시즌스_호텔_서울_찰스_H._1112.jpg', '전설적인 미국 작가 이름을 딴 이색적인 칵테일 바\n\n전설적인 미국 작가인 찰스 H. 베이커의 이름을 딴 찰스 H. 바는 이국적이고 화려한 매력이 가득한 공간으로, 칵테일 애호가들에게 완벽한 메뉴를 제공하며 지하의 비밀 통로를 통해 연결됩니다. 오직 이곳에서만 즐길 수 있는 한국의 제철 재료를 활용한 독창적인 칵테일과 세심하게 페어링된 메뉴를 만나보세요.', 37.570698, 126.975398, '', '지하철 6호선 광화문역 7번출구, 136m', '', '', ' https://www.instagram.com/charleshseoul/', '', '- 2022 아시아 50 베스트 바 7위 (국내 1위)\n- 2021 월드 50 베스트 바 42위 (국내 1위)', '18:00-01:30', '02-6388-5500', ''),
	(1113, 'OMOT 오므오트', '04768  서울 성동구 서울숲2길 12 (성수동1가) 지하1층', 'images/OMOT_오므오트_1113.jpg', '성수동 서울숲에 위치한 한국차 전문 티카페\n\n성수동 서울숲에 위치한 한국차 전문 티카페 (티하우스)입니다. 시즈너리한 차와 다식을 스토리텔링 티코스로 프라이빗하게 예약제로 운영됩니다. (네이버 톡톡, 인스타그램DM으로 문의해 주세요 / 단품은 워크인으로 이용가능) 도심속 가까운 곳에서 새로운 차문화를 통해 온전히 나만의 시간을 만나 힐링하면서 건강하고 가치있는 라이프 스타일을 공유합니다. 오므오트에서 시그니처 니치 티 라인 및 싱글 오리진 티, 테이블 웨어, 공예품 구입도 가능합니다.', 37.547229, 127.039948, '', '지하철 2호선, 뚝섬역 8번출구, 617m', '', '', '', '', '티세레모니 예약 시간은 12시, 2시, 4시, 7시 입니다', '수~월 : 12:00~17:30 / 18:30~20:30', '1024259192', '매주 화요일'),
	(1114, '뿌자2 인도 할랄 음식점', '04564  서울 중구 을지로43길 13 (을지로6가, 대화빌딩)  4층', 'images/뿌자2_인도_할랄_음식점_1114.jpg', '인도에서 30년 경력을 쌓은 주방장이 업그레이드된 맛을 내는 인도음식점.\n\n일반인들이 신과의 소통을 위해 매일 행하는 기도 의식인 \'뿌자\'에서 영감을 받아 식당 이름을 지었으며, 경건한 마음으로 음식을 준비하는 인도 음식점입니다. 인도에서 30년 경력을 쌓은 주방장을 초빙하여 더욱 업그레이드된 맛과 분위기를 선보입니다. 인도 맛의 진수를 경험하고 싶은 이들에게 추천합니다.', 37.566898, 127.006808, '', '지하철 2/4/5호선 동대문역사문화공원역 13번 출구, 125m', '탄두리 치킨, 커리 종류', '', ' http://pooja.fordining.kr/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓞ', '10:00 - 21:00 (15:00 - 17:00 브레이크타임 / 월 - 금)\n토 - 일 10:00 - 22:00', '-4759', ''),
	(1115, '릭십 lick sip', '04400  서울 용산구 이태원로54길 16-5 1층', 'images/릭십_lick_sip_1115.jpg', '커피부터 위스키, 와인, 맥주까지 다양하게 즐길 수 있는 카페&바\n\n릭십(lick sip)은 위스키 아이스크림을 맛볼 수 있는 어른들을 위한 카페&바이며, 위스키 아이스크림, 와인 스무디 등 어른들을 위한 디저트의 색다른 매력을 느낄 수 있습니다. 한적하고 엔틱한 분위기의 공간으로 가볍게 혼자서도 부담없이 가기에 좋습니다. 위스키 아이스크림 외에도 커피, 위스키, 와인, 맥주까지 다양한 음료를 즐길 수 있습니다.', 37.537421, 127.002527, '', '지하철 6호선 한강진역 3번출구, 345m', '', '', '', '', '', '화,수 18:00-24:00 / 목 12:00-24:00 / 금,토 12:00-01:00 / 일 13:00-23:00', '0507-1390-7841', '매주 월요일'),
	(1116, '원주추어탕', '06023  서울 강남구 압구정로 224 (신사동, 우미빌딩)  우미빌딩', 'images/원주추어탕_1116.jpg', '들깨의 고소함이 더해진 특별한 추어탕\n\n추어탕은 깊고 진한 국물이 특징인 전통 음식으로, 미꾸라지를 주재료로 하여 만든 국물 요리입니다. 이곳에서는 통추어탕부터 만두추어탕, 추어튀김, 추어만두 등 다양한 추어 요리를 맛볼 수 있어, 추어 요리가 낯선 사람도 부담 없이 먹을 수 있습니다. 또한, 추어탕 외에도 한방삼계탕과 해물부추전도 준비되어 있어 다양한 메뉴를 즐기기에 좋은 장소입니다.', 37.528563, 127.032149, '', '지하철 3호선 압구정역 2번 출구, 360m', '추어탕, 통추어탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '08:30 - 20:30 (15:30 - 17:00 브레이크타임)', '-488', '일요일'),
	(1117, '초록뜰식당', '02499  서울 동대문구 망우로18길 36 (휘경동)', 'images/초록뜰식당_1117.jpg', '한식 메뉴를 채식으로 제공하여 채식 한식의 매력을 느낄 수 있는 곳\n\n한식 메뉴를 채식으로 제공하여 채식 한식의 매력을 느낄 수 있는 곳입니다. 버섯만두전골은 풍부한 버섯 향과 깊은 국물 맛이 조화를 이루며, 채식주의자도 만족할 수 있는 담백하고 맛있는 전골입니다. 들깨칼국수는 고소한 들깨의 풍미가 가득한 국물과 쫄깃한 칼국수가 어우러져 진한 맛을 자랑합니다. 다양한 채식 만두 요리도 준비되어 있어, 고기만두가 부담스러운 이들에게 특히 인기가 많습니다.', 37.588539, 127.062823, '', '지하철 1호선/경의중앙선 /경춘선 회기역 2번 출구, 603m', '쌀국수, 묵밥, 버섯만두전골', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:00 - 20:00', '-9896', '매주 토요일'),
	(1118, '제주미향해장', '02573  서울 동대문구 경동시장로10길 46 1층', 'images/제주미향해장_1118.png', '청량리 경동시장 소고기 해장국 맛집\n\n몇 시간 동안 푹 고아낸 진한 육수에 푸짐한 선지와 신선한 우거지가 듬뿍 담긴 해장국으로 유명한 경동시장 내 맛집입니다. 상인들 뿐 아니라 지역 주민들, 그리고 청량리를 찾는 MZ세대들도 입소문을 타고 찾는 이곳은 제주도 스타일답게 몸국와 보말국 그리고 제주식 소고기 해장국이 대표적입니다. 한 그릇 가득 담긴 국밥은 양도 많고, 먹고 나면 속이 든든해지는 기분까지! 그 맛을 경험해 보세요', 37.581276, 127.043234, '', '지하철 1호선/경의중앙/경춘/수인분당 청량리역 1번출구, 262m', '', '', ' https://www.jejumihyang.co.kr/', '', '', '매일 00:00~24:00', '0507-1462-3370', '매주 수요일 (24:00~06:00) 매장 점검 시간휴무'),
	(1119, '더래빗', '06691  서울 서초구 방배천로4안길 38 (방배동)  1층', 'images/더래빗_1119.jpg', '순 식물성 식재료로 정성껏 만든 쫄깃한 베이글.\n\n순 식물성 식재료로 정성껏 만든 쫄깃한 베이글과 고소한 크림치즈가 가득한 이곳은, 맛의 조화가 매력적인 특별한 공간입니다. 어니언, 와인 무화과, 메이플 피칸, 레몬딜 등 다양한 크림치즈와 이태리, 옥수수럼블, 매쉬포테이토 등 여러 종류의 베이글이 준비되어 있어, 각기 다른 조합으로 새로운 맛의 즐거움을 선사합니다.', 37.479691, 126.983405, '', '지하철 2/4호선 사당역 11번 출구, 292m', '어니언부추크림치즈, 이태리베이글', '', ' https://instagram.com/gourmet.the.rabbit', '카페, 디저트', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 20:00', '-9625', ''),
	(1120, '반카페', '07222  서울 영등포구 당산로47길 20 1층 반카페', 'images/반카페_1120.png', '자전거 라이더도 좋아하는 한강 근처 대형 카페\n\n당산역 근처에 위치한 반카페는 힙한 감성 카페로 한강 자전거 라이더들도 편히 방문할 수 있는 대형 카페입니다. 커피, 디저트 뿐만 아니라 자전거 용품도 판매하고 있습니다. 자전거 라이더 손님을 위해 실내 거치 및 공기 주입이 가능한 펌프, 간단한 파츠 조정을 위한 육각렌치가 구비되어 있으며, 외부 자전거 무게 측정을 위한 저울도 자유롭게 이용 가능합니다. 매장에서 직접 정성껏 반죽한 수제 스콘과 시그니처 메뉴인 반치즈라떼와 반아몬드크림라떼도 함께 즐겨보세요.', 37.535772, 126.902664, '', '지하철 2호선/9호선 당산역 3번출구, 91m', '', '', ' https://www.instagram.com/ban_coffee.shop', '', '', '월-금 8:00-20:00 / 토,일 11:30-20:00 (라스트오더 19:30)', '070-7780-7914', ''),
	(1121, '넥타이맨갈치동태', '04528  서울 중구 남대문시장길 18-9 (남창동)', 'images/넥타이맨갈치동태_1121.jpg', '남대문시장 갈치골목에 위치한 갈치조림 전문점. 저렴한 가격에 푸짐한 양\n\n남대문시장 갈치골목에 위치한 이 갈치조림 전문점은 저렴한 가격에 푸짐한 양과 정성스러운 밑반찬으로 유명합니다. 특히 갈치조림은 깊고 진한 국물과 함께 매콤하게 조리된 갈치가 특징입니다. 갈치는 부드럽고 살이 꽉 차 있으며, 매운 양념이 잘 배어 있어 밥과 함께 먹기 좋습니다. 이곳의 갈치조림은 신선한 재료로 정성스럽게 조리되며, 한국 전통의 맛을 그대로 느낄 수 있습니다.', 37.559668, 126.977018, '', '지하철 4호선 회현역 5번 출구, 213m', '국산갈치조림, 힘나는 동태탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '07:30 - 20:00', '-10479', '격주 일요일'),
	(1122, '루티드', '05549  서울 송파구 오금로17길 7 (방이동)  1층', 'images/루티드_1122.jpg', '비건 카페로 제철 비건요리와 음료 제공.\n\n누룽지 후무스 플래터는 바삭하게 구운 누룽지와 크리미한 후무스의 조화로, 풍부하고 고소한 맛이 입 안에서 부드럽게 어우러집니다. 수박 튜나 써머 샐러드는 시원하고 달콤한 수박과 상큼한 튜나가 어우러져 여름의 신선함을 한껏 담아냅니다. 두 메뉴 모두 비건 요리에서 새로운 맛의 경험을 선사하며, 식사를 더욱 풍성하게 만들어줍니다.', 37.511475, 127.111440, '', '지하철 9호선 송파나루역 2번 출구, 170m', '누룽지 후무스 플래터, 수박 튜나 써머 샐러드', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '11:00 - 20:00 (19:45 라스트오더)', '-7997', '매주 일 - 월 휴무'),
	(1124, '사마르칸트시티', '04561  서울 중구 마른내로 159-4 (광희동1가)', 'images/사마르칸트시티_1124.jpg', '우즈베키스탄 전통 꼬치 요리인 샤슬릭\n\n우즈베키스탄 정통 현지 음식을 맛볼 수 있습니다. 한국인뿐 아니라 현지인들도 많이 찾는 곳으로 색다른 미식 경험을 하고 싶다면 방문해보세요. 특히 우즈베키스탄 전통 꼬치 요리인 샤슬릭을 부담 없이 먹기 좋습니다. 가격대도 부담 없으니 마음껏 주문해 다양한 맛의 꼬치를 즐겨보세요.', 37.564837, 127.005957, '', '지하철 2/4/5호선 동대문역사문화공원역 5번 출구, 114m', '샤슬릭, 우즈벡전통볶음밥', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '10:00 - 23:00', '-4425', ''),
	(1125, '더닝', '04382  서울 용산구 한강대로 126-1 1층, 2층', 'images/더닝_1125.jpg', '케이크가 맛있는 용리단길 디저트 카페\n\n무방부제 시트를 직접 굽고, 천연 동물성 생크림과 제철 생과일을 사용해 만드는 100% 수제 케이크로 더욱 건강하고 맛있게 케이크를 만드는 케이크에 진심인 용리단길 디저트 카페입니다. 홀케이크 주문은 미리 예약하면 편리하며, 당일 예약도 가능합니다.', 37.530601, 126.969798, '', '지하철 4호선 신용산역 1번출구, 124m', '', '', ' http://instagram.com/dawnin9_', '', '', '12:00-21:00 / 금,토 12:00-22:00', '0507-1462-0236', '임시휴뮤는 인스타그램 공지 참고'),
	(1126, '포탈라 종로', '03191  서울 종로구 청계천로 99 (관철동, 수표교빌딩)', 'images/포탈라_종로_1126.jpg', '티베트인이 직접 운영하는 이 식당은 티베트 전통 음식 전문점.\n\n티베트인이 직접 운영하는 이 식당은 티베트 전통 음식 전문점으로, 할랄 인증을 받은 재료를 엄선하여 풍미 가득한 요리를 선보입니다. 무슬림 손님뿐만 아니라 일반 방문객들도 만족할 수 있는 메뉴를 제공하며, 다양한 방송에 소개되었습니다. 특히 티베트식 툭바(티베트식 국수)와 샤박레(티베트식 양고기 만두) 등 독특한 티베트 음식을 경험할 수 있습니다.', 37.568401, 126.988658, '', '지하철 2/3호선 을지로3가역 2번 출구, 410m', '툭빠, 난', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '주중 11:00-22:00 (15:00-17:00 브레이크타임)\n주말 11:00~22:00', '-1940', ''),
	(1127, '기후', '04784  서울 성동구 성수이로 66 서울숲드림타워 1층 106호', 'images/기후_1127.jpg', '사계절의 제철 음식을 담은 성수 오마카세 레스토랑\n\n계절이 바뀌면 메뉴도 업데이트 되며, 기후에서는 봄, 여름, 가을, 겨울의 계절을 한 끼 식사로 표현합니다. 이름에서 알 수 있듯이, 기후는 계절마다 셰프가 계절 재료를 중심으로 신중하게 만든 계절 메뉴만을 제공합니다. 일본 스타일을 기반으로 한국적 요소를 접목한 오마카세 요리를 선보입니다.', 37.540619, 127.056132, '', '지하철 2호선 성수역 3번출구, 408m', '', '', ' https://www.instagram.com/kihoo_official', '', '예약제 레스토랑으로, 네이버, 전화, 캐치테이블을 통해 사전 예약을 권장합니다.', '매일 11:30-22:00', '02-466-7079', ''),
	(1128, '온달집 본점', '06035  서울 강남구 강남대로152길 30 1층 온달집', 'images/온달집_본점_1128.jpg', '숯불에 구워 먹을 수 있는 닭다리살, 무뼈닭발, 꼼장어, 닭똥집 등이 대표적인 메뉴\n\n숯불에 구워 먹을 수 있는 닭다리살, 무뼈닭발, 꼼장어, 닭똥집 등이 대표적인 메뉴입니다. 특히, 숯불에 구운 닭다리살은 겉은 바삭하고 속은 촉촉하며, 무뼈닭발은 매콤하면서도 쫄깃한 식감이 일품입니다. 포차 분위기의 인테리어와 함께 K-DRAMA 속 한 장면에 들어온 듯한 느낌을 받을 수 있습니다. 구이 요리뿐만 아니라 간장 마요밥과 치즈 떡볶이도 꼭 맛봐야 할 곁들임 메뉴입니다.', 37.517658, 127.021838, '', '지하철 3호선/신분당선 신사역 8번 출구, 179m', '닭다리살, 무뼈닭발', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '17:00 - 04:00', '02-545-5557', ''),
	(1129, '사델스 앳 키스 서울', '04784  서울 성동구 연무장길 70 3층', 'images/사델스_앳_키스_서울_1129.png', '뉴욕의 인기 브런치 레스토랑\n\nKITH 서울 3층에 위치한 Sadelle’s는 뉴욕에서 시작된 인기 브런치 레스토랑입니다. 베이글, 훈제 연어, 프렌치토스트 등 정통 브런치 메뉴를 세련된 공간에서 즐길 수 있습니다. 넓은 창을 통해 자연광이 가득 들어오는 매장 내부는, 뉴욕 감성을 느낄 수 있는 아치형 창문과 고급스러운 바 카운터가 인상적입니다. 또한, 서울의 녹음을 바라볼 수 있는 테라스 좌석도 마련되어 있어 여유롭고 쾌적한 시간을 보낼 수 있습니다.', 37.541786, 127.057020, '', '지하철 2호선 성수역 3번출구, 328m', '', '', ' https://www.instagram.com/sadelleskith', '', '', '매일 10:00-20:00', '0507-1492-1443', ''),
	(1130, '차니오뎅', '03086  서울 종로구 대학로8가길 48 (동숭동)  1층', 'images/차니오뎅_1130.jpg', '전통 어묵을 새롭게 재해석한 메뉴들로 유명한 오뎅 꼬치전문점.\n\n독특한 어묵 요리를 선보이는 이 식당은 전통 어묵을 새롭게 재해석한 메뉴들로 유명합니다. 돌절구로 간 생선살에 오징어와 야채를 섞어 튀긴 오징어 오뎅카츠는 바삭하면서도 촉촉한 시그니처 메뉴입니다. 또, 얇게 저민 어묵에 초생강과 야채를 곁들인 오뎅타코 와사비는 일본식 낙지젓갈과 함께 제공되어, 담백한 어묵과 알싸한 와사비의 조화가 매력적인 특별한 메뉴입니다.', 37.582936, 127.002422, '', '지하철 4호선 혜화역 1번 출구, 119m', '오징어오뎅카츠, 새우오뎅카츠', '', ' https://www.instagram.com/chani__oden/#', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '16:00 - 24:00', '-1881', ''),
	(1131, '속초집', '04634  서울 중구 퇴계로6길 3-6 (회현동1가)  지하', 'images/속초집_1131.jpg', '계절에 따라 다양한 해산물 요리. 계절의 특성을 살린 메뉴를 제공.\n\n계절에 따라 다양한 해산물 요리를 선보이는 이 전문점은 계절의 특성을 살린 메뉴를 제공합니다. 생태탕은 신선한 생태를 푹 끓여 시원하면서도 매콤한 국물 맛이 일품인 음식입니다. 황태구이는 황태를 바삭하게 구워내어 고소한 맛이 풍부하며, 간단한 밑반찬으로도 훌륭합니다. 북어찜은 부드럽게 찐 북어에 다양한 채소와 양념이 어우러져 감칠맛을 더해줍니다.', 37.557842, 126.978636, '', '지하철 4호선 회현역 3번 출구, 69m', '생태탕, 황태해장국', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 21:00', '-2921', ''),
	(1132, '미스터케밥', '04406  서울 용산구 이태원로 192 (이태원동)  1층', 'images/미스터케밥_1132.jpg', '튀르키예 전통 방식을 고수하는 케밥과 샐러드.\n\n튀르키예 전통 방식을 고수하며 케밥과 샐러드 등 다양한 메뉴를 맛볼 수 있는 이곳은 현지의 정통 맛을 그대로 재현합니다. 가성비가 뛰어나고 간편하게 식사할 수 있어, 근처 주민들이 자주 찾는 곳입니다. 이태원 여행 중 식사에 부담을 느낄 때나 출출할 때, 가볍게 맛있는 한 끼를 즐기기에 완벽한 장소입니다.', 37.534367, 126.995372, '', '지하철 6호선 이태원역 3번 출구, 100m', '터키 케밥 닭고기, 바클라와 대 팩', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '00:00 - 24:00', '0507-1393-2005', ''),
	(1133, '이노참치', '03190  서울 종로구 삼일대로15길 20-1 (관철동)', 'images/이노참치_1133.jpg', '35년 경력의 오너 셰프가 제공하는 고급 참다랑어 일식집\n\n35년 경력의 오너 셰프가 제공하는 고급 참다랑어는 대뱃살의 깊고 진한 풍미를 시작으로, 중뱃살, 볼살, 배꼽살 등 다양한 특수 부위와 세심하게 준비된 특제 초밥까지 폭넓은 선택을 자랑합니다. 가성비와 품질 모두를 탁월하게 만족시키며, 회와 초밥 모두 그 뛰어난 맛으로 인정받고 있다. 20년 넘게 단골들이 계속 찾는 맛집입니다.', 37.568921, 126.986333, '', '지하철 1호선 종각역 4번 출구, 348m', '스페셜정식, 이노초밥', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00-23:30', '-5782', '매주 일요일'),
	(1134, '진어참치', '03988  서울 마포구 연남로3길 34 (연남동)', 'images/진어참치_1134.jpg', '고급 참치의 신선한 맛과 각기 다른 식감과 풍미\n\n문 한쪽의 블루리본 스티커들이 가게의 인기를 증명해줍니다. 블루리본 스티커는 해당 식당의 뛰어난 품질과 고객 만족도를 인증하는 상징으로, 업계 전문가들에 의해 선정된 결과물입니다. 다양한 가격대에 따라 구성된 참치회 플래터를 제공하여 고급 참치의 신선한 맛과 각기 다른 식감, 풍미를 즐길 수 있습니다.', 37.560745, 126.920766, '', '지하철 2호선/공항철도/경의중앙선 홍대입구역 2번 출구, 569m', '참치회', '', ' https://app.catchtable.co.kr/ct/shop/Jinuhtuna', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '16:30 - 22:00', '-9182', '매달 3번째 화요일'),
	(1135, '대복', '04526  서울 중구 세종대로14길 22 (북창동)  1층', 'images/대복_1135.jpg', '1970년대부터 복지리의 참맛을 전파해온 전통 복어요리 전문점\n\n1970년대부터 복지리의 참맛을 전파해온 전통 복어요리 전문점입니다. 이곳의 복지리는 깊고 시원한 국물 맛과 쫄깃하면서도 담백한 복어의 풍미를 자랑합니다. 복어의 부드러운 식감과 매콤한 양념이 어우러져 깊은 맛을 느낄 수 있습니다. 복지리에 사용되는 복어는 신선하게 준비되어 풍미가 살아 있으며, 국물은 오랜 시간 동안 끓여내어 맛이 진하고 깊습니다. 한국식 복어요리를 제대로 경험하고 싶다면, 장인의 손길로 준비된 복지리를 추천합니다.', 37.562800, 126.977931, '', '지하철 1/2호선 시청역 7번 출구, 235m', '복매운탕, 참복지리, 된장지리, 활복탕+회', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 22:00 (15:00 - 17:00 브레이크타임)\n토 10:00 - 22:00', '02-755-0189', '일요일'),
	(1136, '소바마에', '04778  서울 성동구 왕십리로4길 26-20 (성수동1가)  지층', 'images/소바마에_1136.jpg', '소바 달인이 직접 운영하는 우동, 소바 전문점\n\n소바 달인이 직접 운영하는 이곳은 정말 매력적인 곳입니다. 니쿠소바는 진한 국물 맛이 일품이며, 소고기의 깊은 맛을 한층 더 느낄 수 있습니다. 자루 소바는 소바 본연의 향과 맛을 제대로 즐길 수 있습니다. 그리고 카케소바의 가쯔오부시 국물도 일품이니 국물의 깊은 맛을 즐기고자 하는 이라면 추천합니다. 게다가, 튀김이 글루텐 프리로 제공된다는 점도 건강을 고려하는 이들에게 좋은 소식입니다.', 37.546808, 127.047007, '', '지하철 2호선 뚝섬역 7번 출구, 87m', '니쿠소바, 자루소바', '', ' https://www.instagram.com/soba_mae/', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00  (15:00 - 17:00 브레이크타임, 20:30 라스트오더)\n토 - 일 11:00 - 20:30 (20:00 라스트오더)', '-8082', '매주 월요일'),
	(1137, '라자트', '04406  서울 용산구 우사단로 37 (이태원동)', 'images/라자트_1137.png', '이국적인 분위기의 우즈베키스탄 요리 전문점\n\n이국적인 분위기의 우즈베키스탄 요리 전문점으로, 현지 출신의 서버들과 독특한 인테리어가 마치 우즈베키스탄에 여행 온 듯한 느낌을 줍니다. 입맛을 제대로 돋우는 국물 만두, 양갈비 수프, 우즈베크 라그만이 대표 메뉴입니다. 가성비가 좋은 요리가 많아 다양한 요리를 시켜 맛보는 것도 추천합니다.', 37.533532, 126.995439, '', '지하철 6호선 이태원역 3번 출구, 212m', '국물만두, 양갈비수프, 우즈베크 라그만', '', ' https://www.facebook.com/lazzatuz', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '12:00 - 22:00', '-7720', '매주 월요일'),
	(1138, '온미관 안국', '03059  서울 종로구 북촌로2길 5-4 (재동)', 'images/온미관_안국_1138.jpg', '종로 올드타운의 감성을 살린 정갈한 분위기의 한옥 식당\n\n온미관은 전통의 거리에서 써내려가는 새로운 한식의 역사, 맛으로 온기를 전하는 안국역 맛집입니다. 자극적인 맛이 아닌 은은한 온기로 맛을 전하는 정직한 전통 한식의 맛을 느낄 수 있습니다. 비법육수를 부어 소 특수부위와 채소를 우려 먹는 담백하고 슴슴한 맛의 평양식 전통 전골 요리인 어복쟁반 시그니처 메뉴를 즐겨보시길 바랍니다.', 37.578043, 126.986090, '', '지하철 3호선 안국역 2번출구, 112m', '', '', ' https://www.instagram.com/onmigwananguk/', '', '', '11:00-22:00', '0507-1371-0394', ''),
	(1139, '신라인도레스토랑', '03189  서울 종로구 종로12길 6 (관철동, 시사일본어학원)', 'images/신라인도레스토랑_1139.jpg', '경험 많은 셰프들이 만드는 전통 인도 요리를 맛볼 수 있는 곳.\n\n경험 많은 셰프들이 만드는 전통 인도 요리를 맛볼 수 있는 이곳은, 잘 꾸며진 분위기에서 정갈한 커리와 난을 합리적인 가격에 제공합니다. 특히 1인 세트가 마련되어 있어 혼자서 방문하기에도 좋습니다. 서울에서 1만 원 이하로 가성비 좋은 런치 세트를 즐길 수 있으니 점심시간에 가기 좋은 곳입니다.', 37.569832, 126.985565, '', '지하철 1호선 종각역 4번 출구, 182m', '런치세트, 치킨 커리', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 23:00', '-7962', ''),
	(1140, '원주추어탕', '04520  서울 중구 무교로 17-27 (태평로1가, 대원빌딩)', 'images/원주추어탕_1140.jpg', '국내산 미꾸라지로 끓인 추어탕과 매일 담그는 신선한 겉절이.\n\n국내산 미꾸라지로 끓인 추어탕과 매일 담그는 신선한 겉절이가 특징인 이 식당은 한국 전통 음식을 경험할 수 있는 곳입니다. 추어탕은 뜨끈하고 칼칼한 국물에 듬뿍 들어간 시래기가 더해져 깊고 풍부한 맛을 자랑합니다. 낯선 음식일 수 있지만, 한국에서의 특별한 식사를 원한다면 도전을 추천합니다. 추어튀김도 인기 있는 메뉴로, 바삭한 튀김옷과 고소한 미꾸라지 속살이 어우러져 한국 사람들에게 사랑받는 별미입니다.', 37.567453, 126.978395, '', '지하철 1/2호선 시청역 4번 출구, 170m', '추어탕, 추어튀김', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '주중 09:30 - 21:00\n토 10:00 - 19:00', '-9851', '일요일'),
	(1141, '향동가 한남별관', '04419  서울 용산구 독서당로 65-1 1층', 'images/향동가_한남별관_1141.jpg', '한우 육수의 육향과 순메밀의 곡향이 물드는 곳, 평양냉면 전문점\n\n평양냉면으로 유명한 향동가 한남별관은 한옥의 전통스러운 분위기와 현대적인 깔끔한 인테리어가 조화롭게 느껴집니다. 맷돌제분의 뚝뚝 끊기는 메밀의 거친 면발속 부드러운 여운을 남기는 진한 한우 육수를 바탕으로 깊은 설렘을 담은 한그릇을 즐겨보세요. 평양냉면 초보 입문자도 육향이 입혀진 육수의 맛과 함께 호불호 없이 즐길 수 있습니다.', 37.533832, 127.007746, '', '지하철 경의중앙선 한남역 1번출구, 593m', '', '', '', '', '', '11:00-21:30 브레이크타임 15:00-17:00 라스트오더 21:00', '0507-1346-7995', '매주 일요일'),
	(1142, '다르샨나마스테', '03106  서울 종로구 종로 309 (창신동)', 'images/다르샨나마스테_1142.jpg', '전통 인도 요리 레스토랑으로 전통 식자재와 국내 신선한 재료를 엄선하여 조리\n\n전통 인도 요리 레스토랑으로, 인도 원산지에서 수입한 전통 식자재와 국내 신선한 재료를 엄선하여 조리합니다. 한국에 거주하는 인도 사람들에게는 향수를 달래는 장소로 알려져 있으며, 관광객들에게도 큰 인기를 끌고 있습니다. 특히, 현지식과 유사한 커리 요리가 돋보이며, 진정한 인도 전통의 맛과 풍미를 경험할 수 있습니다.', 37.572233, 127.011952, '', '지하철 1/4호선 동대문역 3번 출구, 8m', '달 마카니', '', ' https://www.facebook.com/darshanamaste.np?fref=ts', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-5407', ''),
	(1143, '뉴델리', '06022  서울 강남구 논현로176길 28 (신사동)', 'images/뉴델리_1143.jpg', '천연 재료만으로 맛을 내는 정통 인도 요리 전문점\n\n조미료 사용 없이 건강하고 품질 좋은 천연 재료만으로 맛을 내는 정통 인도 요리 전문점입니다. 뉴델리의 시그니처 메뉴인 탄두리 치킨 샐러드와 탄두리 치킨은 풍부한 맛과 향으로 꼭 한 번 맛봐야 할 요리입니다. 또한, 치킨 마크니는 밥이나 난이 포함되어 있어 훌륭한 가성비를 자랑하며, 함께 즐기면 더욱 만족스러운 식사를 경험할 수 있습니다.', 37.527505, 127.030631, '', '지하철 3호선 압구정역 2번 출구, 229m', '치킨 마카니(난 또는 밥 포함), 탄두리 치킨 샐러드, 탄두리치킨 full', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-9761', ''),
	(1144, '방울과꼬막', '04402  서울 용산구 대사관로30길 11-5 1층', 'images/방울과꼬막_1144.jpg', '제철 해산물과 포장마차 메뉴 전문 용산 한식주점\n\n방울과 꼬막은 가성비 좋은 해산물 포차 입니다. 퀄리티 좋은 제철 해산물을 맛볼 수 있어 해산물을 좋아하는 사람이라면 추천합니다. 야외 테이블에 앉으면 마치 포장마차에 온 것 같은 분위기를 느낄 수 있으며, 웨이팅이 있는 편이지만 캐치테이블로 미리 예약할 수 있습니다.', 37.532689, 127.005766, '', '지하철 경의중앙선 한남역 1번출구, 658m\n지하철 6호선 이태원역 3번출구, 1.2km', '', '', ' https://www.instagram.com/banggopocha/', '', '캐치테이블 예약 가능\n이용제한 시간 : 주중 최대 3시간, 주말/공휴일 최대 2시간', '월-수 17:00-00:30 / 목,금 17:00-02:00 / 토 15:00-02:00', '0507-1339-1019', '매주 일요일'),
	(1145, '니로사 레스토랑', '03086  서울 종로구 동숭길 43 (동숭동)', 'images/니로사_레스토랑_1145.jpg', '20년 경력의 인도 및 네팔 현지 요리사가 정통 인도의 맛을 선사\n\n20년 경력의 인도 및 네팔 현지 요리사가 정통 인도의 맛을 선사하는 이곳은, 합리적인 가격에 맛과 서비스를 모두 만족시킬 수 있도록 노력하는 곳입니다. 신선하고 향긋한 난과 다양한 커리의 조화를 경험할 수 있으며, 특히 2인 커플 세트는 양이 넉넉하여 두 사람이 충분히 만족할 수 있는 메뉴입니다. 이곳의 음식은 정통 인도의 맛을 그대로 느낄 수 있도록 정성껏 준비되며, 전통적인 요리법과 신선한 재료로 깊고 풍부한 맛을 자랑합니다.', 37.580228, 127.004293, '', '지하철 4호선 혜화역 2번 출구, 301m', '스페셜 런치 세트, 치킨 마크니', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 22:00', '-10765', '2, 4번째 월요일'),
	(1146, '램캠프', '04630  서울 중구 퇴계로20길 46 (남산동2가)', 'images/램캠프_1146.jpg', '냄새가 없고 부드러운 양고기를 즐기는 양고기 레스토랑.\n\n냄새가 없고 부드러운 양고기 품질로, 양고기를 처음 접하는 사람도 부담 없이 즐길 수 있는 양고기 레스토랑입니다. 특히, 수제로 만든 특제 소스와 토르티야에 싸서 먹으면 양고기의 풍미를 더욱 풍부하게 경험할 수 있습니다. 이곳에서 제공하는 된장찌개는 구수하고 진한 맛이 특징입니다. 전통적인 한국 된장으로 끓여내며, 다양한 채소와 두부가 함께 들어가 깊은 풍미와 함께 건강한 맛을 제공합니다.', 37.558262, 126.986365, '', '지하철 4호선 명동역 3번 출구, 298m', '양고기 반마리(400g), 양고기 한마리(700g)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-2032', '일요일'),
	(1147, '자프란', '04407  서울 용산구 우사단로10길 36 (한남동)', 'images/자프란_1147.png', '인도 현지인이 운영하는 인도 요리 전문점\n\n인도 현지인이 운영하는 인도 요리 전문점으로, 부드러운 탄두리 치킨과 큼지막한 고기가 듬뿍 들어간 커리가 가장 인기 있는 메뉴입니다.  인기 메뉴들을 한 번에 맛볼 수 있는 세트 메뉴가 특히 인기가 많습니다. 현지인이 운영하는 만큼 진짜 인도 현지의 맛을 보장합니다', 37.533002, 126.997568, '', '지하철 6호선 이태원역 3번 출구, 449m', '치킨 커리', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '12:00 - 22:00', '-4284', ''),
	(1148, '깔리', '03079  서울 종로구 대학로11길 43 (명륜4가)  2층', 'images/깔리_1148.jpg', '혜화 인도 커리 맛집으로 인도, 네팔, 티벳을 배낭여행하며 모은 예쁜 장식\n\n수년간 인도, 네팔, 티베트를 여행하며 모은 예쁜 소품들로 꾸며진 대학로의 작은 인도 깔리는 인도에서 직접 초빙한 현지 요리사들이 선보이는 정통 인도 요리를 맛볼 수 있는 곳입니다. 특히 탄두리 치킨을 포함한 런치 세트는 구성도 알차고 양도 푸짐하여 만족스러운 식사를 기대할 수 있습니다. 아늑한 분위기 속에서 진정한 인도 미식을 경험할 수 있는 좋은 장소입니다.', 37.582462, 126.999237, '', '지하철 4호선 혜화역 4번 출구, 265m', '인도 요리 탄두리 치킨, 양고기 빈달루', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 21:10 (15:40 - 17:00 브레이크타임)', '-5717', '매주 월요일'),
	(1149, '이태원키친', '04405  서울 용산구 우사단로 34 (이태원동)  2층', 'images/이태원키친_1149.jpg', '쿠비데 케밥은 이란 현지의 맛과 동일하다는 평을 받는 곳.\n\n현지 맛에 가까운 요리를 선보여 많은 현지인들이 찾는 이곳의 쿠비데 케밥은 이란 현지의 맛과 동일하다는 평을 받습니다. 이 외에도 나시르막과 반다리 소시지, 샌드위치가 시그니처 메뉴로 인기를 끌고 있습니다. 혼자 여행하는 관광객들도 편안하게 한 끼를 해결할 수 있는 곳입니다.', 37.533228, 126.995700, '', '지하철 6호선 이태원역 3번 출구, 261m', '나시르막, 할랄푸드(피자 / 샌드위치) 변동', '', ' http://www.instagram.com/itaewon_kitchen', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 24:00', '-4219', ''),
	(1150, '액트커피', '06691  서울 서초구 방배천로4안길 40 (방배동, 해정빌딩)', 'images/액트커피_1150.jpg', '아늑하면서도 힙한 인테리어가 매력적이며 분위기와 맛을  만족.\n\n아늑하면서도 힙한 인테리어가 매력적인 이 카페는 분위기와 맛 모두를 완벽하게 만족시킵니다. 브라운치즈폭탄 크로플과 액틀리라떼는 이곳의 대표 메뉴로, 무엇을 주문할지 고민된다면 이 두 가지는 꼭 맛보아야 할 선택. 고유의 아름다운 인테리어와 맛있는 음식 덕분에 많은 방문객들이 기념 사진을 찍고, 인스타그램에 공유하는 곳입니다.', 37.479817, 126.983412, '', '지하철 2/4호선 사당역 11번 출구, 305m', '브라운치즈폭탄 크로플 세트, 액틀리라떼', '', ' https://www.instagram.com/a.c.t_coffee/#', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '12:00 - 22:00 (21:15 라스트오더)', '-5967', ''),
	(1152, '경성고기꾼', '02453  서울 동대문구 회기로21길 8 (회기동)  1층', 'images/경성고기꾼_1152.jpg', '착한 가격에 질 좋은 소고기를 숯불에 구워 맛보는 재미를 제공\n\n착한 가격에 질 좋은 소고기를 즐길 수 있는 곳입니다. 다양한 부위를 숯불에 구워 맛보는 재미를 제공하며, 소고기뭇국은 고기가 푸짐하게 들어가 깊고 풍부한 맛을 자랑합니다. 육회비빔밥은 신선한 육회와 함께 비벼 먹는 비빔밥으로, 고소하고 부드러운 육회의 맛이 일품입니다. 바질된장술밥은 바질과 된장이 조화를 이루어 독특한 맛을 더합니다.', 37.591823, 127.053254, '', '지하철 1호선/경의중앙선/경춘선 회기역 1번 출구, 529m', '소한마리, 갈비꽃살+안창살', '', ' https://www.instagram.com/gogikun', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:55 - 24:00 (23:00 라스트오더)', '-11259', ''),
	(1153, '훼미리손칼국수보쌈', '04789  서울 성동구 왕십리로 134 (성수동1가)', 'images/훼미리손칼국수보쌈_1153.png', '뚝섬역 훼미리손칼국수보쌈은 깊은 국물의 칼국수와 부드러운 보쌈을 합리적인 가격에 즐길 수 있는 가성비 맛집이다.\n\n뚝섬역 훼미리손칼국수보쌈은 가성비 좋은 맛집으로, 깊고 진한 국물 맛의 칼국수와 부드럽고 야들야들한 보쌈이 대표 메뉴이다. \n\n바삭한 감자전까지 곁들이면 풍성한 한 끼 식사를 즐길 수 있다. 보쌈정식은 보쌈, 알배추, 김치, 칼국수, 공기밥이 포함되어 푸짐한 구성이 특징이다. 웨이팅이 잦은 인기 식당으로 별도의 예약 시스템은 없으며, 현장에서 줄을 서야 한다. 주차 공간은 따로 마련되어 있지 않지만, 뚝섬역에서 가까워 접근성이 좋다. 부담 없는 가격과 정성스러운 맛으로 남녀노소 모두에게 사랑받는 뚝섬의 숨은 보물 같은 식당이다.', 37.549526, 127.044630, '', '2호선 뚝섬역 1번 출구에서 약 255m (도보 3분)', '', '매일', '', '', '', '11:30 ~22:00', '02-463-5036', ''),
	(1154, '인디카', '04419  서울 용산구 한남대로20길 47-24 (한남동)  지하1층', 'images/인디카_1154.jpg', '인도 전통 요리의 진수를 맛볼 수 있는 고급 레스토랑\n\n인도 전통 요리의 진수를 맛볼 수 있는 고급 레스토랑입니다. 하나의 예술작품이라 부를 수 있을 만큼 정성 들여 준비된 인도 요리가 돋보입니다. 다른 인도 레스토랑에 비해 가격대가 높은 편이지만, 그 품질과 독창성 덕분에 경험할 가치가 충분합니다. 특별한 식사를 원한다면 이곳의 고급스러운 인도 요리를 꼭 한번 경험해보는 것이 좋습니다.', 37.535367, 127.010053, '', '지하철 경의중앙선 한남역 1번 출구, 902m', '마스 커리, 커리 리브 치킨', '', ' http://www.instagram.com/indica_seoul', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '12:00 - 22:30 (15:00 - 17:30 브레이크타임)', '-4634', '월요일'),
	(1156, '어사출또', '07008  서울 동작구 동작대로27나길 21 (사당동, 두원빌라및상가)', 'images/어사출또_1156.jpg', '다양한 해물 요리와 푸짐한 회가 대표 메뉴\n\n다양한 해물 요리와 푸짐한 회가 대표 메뉴입니다. 신선한 회는 입안에서 살살 녹는 부드러운 식감과 깊은 맛을 자랑하며, 여러 해물과 함께 제공됩니다. 특히, 눈꽃 황제물회는  새콤달콤한 양념과 함께 푸짐하게 올라간 회가 특징입니다. 이 메뉴는 시각적으로도  즐거움을 주며, 회의 신선함과 양념의 조화로 입맛을 사로잡습니다. 신선한 회와 해물  요리를 맛보며 특별한 미식을 경험해 보세요.', 37.486593, 126.980660, '', '지하철 4/7호선 이수역 13번 출구, 173m', '어사실속세트, 눈꽃 황제물회', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30 - 02:00', '-7238', ''),
	(1157, '케밥 인', '05018  서울 광진구 아차산로 221 (화양동)', 'images/케밥_인_1157.jpg', '튀르키예 전통 방식으로 구운 다양한 케밥을 맛볼 수 있는 식당\n\n튀르키예 전통 방식으로 구운 다양한 케밥을 맛볼 수 있는 식당이다. 양고기, 소고기, 닭고기로 만든 케밥은 각기 다른 맛과 풍미를 자랑합니다. 케밥과 함께 제공되는 신선한 야채와 향긋한 소스는 맛의 풍미를 더욱 돋웁니다. 튀르키예 전통 디저트인 카이막은 고소하고 크리미한 맛으로 식사를 완성합니다. 신선하고 풍미 가득한 메뉴들로 전통적인 튀르키예 요리를 제대로 경험할 수 있습니다.', 37.541036, 127.068223, '', '지하철 2/7호선 건대입구역 1번 출구, 82m', '카이막, 치킨케밥', '', ' https://www.instagram.com/kebabinn/#', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '10:30 - 01:00', '-9616', ''),
	(1158, '케르반 파미에 스테이션', '06545  서울 서초구 사평대로 205 (반포동, CENTRALCITY 반포천 복개주차장)  2층 에프피 216호', 'images/케르반_파미에_스테이션_1158.jpg', '튀르키예 전통 방식으로 음식을 만드는 곳으로, 진정한 튀르키예 음식을 경험\n\n튀르키예 전통 방식으로 음식을 만드는 곳으로, 진정한 튀르키예 음식을 경험할 수 있습니다. 셰프를 포함한 모든 직원이 튀르키예 국적을 가진 만큼, 진짜 튀르키예의 맛을 그대로 재현합니다. 정성 가득한 전통 튀르키예 음식으로 마치 튀르키예 여행을 떠난 듯한 기분을 느낄 수 있습니다. 다양한 요리를 주문해 그 풍미를 느껴보길 추천합니다.', 37.504492, 127.007845, '', '지하철 3/7/9호선 고속터미널역 3번 출구, 78m', '치킨 스테이크 (런치 세트), 리치피데 (런치 세트)', '', ' https://www.instagram.com/kervankorea/', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 21:00', '-6508', ''),
	(1160, '동양찻집 수락산점', '01630  서울 노원구 동일로 1642 (상계동)', 'images/동양찻집_수락산점_1160.png', '전통과 현대가 완벽하게 조화를 이룬 카페\n\n고즈넉하고 세련된 분위기와 함께 한약방 느낌이 어우러진 동양찻집은 한국 전통차인 쌍화차를 비롯해 커피, 다양한 허브차까지 판매하고 있습니다. 시그니처 메뉴인 쌍화차는 취향에 맞게 진한 맛과 부드러운 맛을 선택할 수 있습니다. 또한 인기 메뉴로는 많이 달지않아 담백한 팥과 인절미 토핑으로 사계절 즐길 수 있는 전통팥빙수가 있습니다. 함께 나오는 고소한 씨앗과 미숫가루, 연유를 추가해서 드시면 더욱 맛있게 즐길 수 있습니다.', 37.674939, 127.055567, '', '지하철 7호선 수락산역 3번출구, 220m', '', '', ' https://www.instagram.com/dongyang.tea_official/', '', '', '10:00-21:30', '02-6494-1100', ''),
	(1161, '메밀향그집', '03078  서울 종로구 대학로11길 18 (명륜4가)', 'images/메밀향그집_1161.jpg', '깊은 손맛으로 인정받는 한식 전문점으로, 폭탄 치즈 순살 닭갈비가 시그니처 메뉴\n\n깊은 손맛으로 인정받는 한식 전문점으로, 폭탄 치즈 순살 닭갈비가 시그니처 메뉴입니다. 매콤한 양념에 부드러운 닭고기와 듬뿍 올려진 치즈의 조화가 일품이며, 식사의 마무리로 볶아먹는 짜파게티는 놓칠 수 없는 별미입니다. 인기가 많은 곳이라 언제나 긴 줄이 늘어서 있지만, 기다림의 보람을 느낄 수 있습니다.', 37.582372, 127.000663, '', '지하철 4호선 혜화역 4번 출구, 195m', '불큼파스타, 폭치순(폭탄치즈순살)', '', ' https://www.instagram.com/memilhyang_zip', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (21:30 라스트오더)', '-5466', ''),
	(1162, '참말로좋수닭273', '02460  서울 동대문구 회기로 160 (회기동)  1층', 'images/참말로좋수닭273_1162.jpg', '순살 치킨을 가슴살, 다리살 등 원하는 부위별로 취향에 맞게 선택\n\n담백하고 바삭한 튀김옷이 매력적인 이곳에서는 순살 치킨을 가슴살, 다리살 등 원하는 부위별로 취향에 맞게 선택할 수 있습니다. 깨끗한 기름에 갓 튀겨내어 바삭하게 완성된 치킨은 겉은 바삭하고 속은 촉촉하여 입안에서 살살 녹습니다. 동네 사람들 사이에서 꾸준히 인기 있는 이유를 직접 느껴보길 추천합니다.', 37.590725, 127.053645, '', '지하철 1호선/경의중앙선/경춘선 회기역 1번 출구, 370m', '참말로후라이드(크리스피), 참말로후라이드 양념', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '월~토 15:30 - 01:00\n일 14:00 - 22:00', '-2017', ''),
	(1163, '아리계곡 종각점', '03189  서울 종로구 우정국로2길 41 1층', 'images/아리계곡_종각점_1163.jpg', '계곡에서 백숙을 즐기는 듯한 분위기의 닭요리 전문 한식 주점\n\n아리계곡은 전통의 정서를 현대적인 감각으로 풀어낸 한식주점입니다. 고유의 정서를 지닌 우리 음식과 전통주를, 익숙하면서도 새롭게 느껴지도록 구성하였습니다. 자연석과 원목, 절제된 조명과 고전적인 디테일이 어우러진 공간은 도심 한가운데서도 마치 계곡에 머무는 듯한 고요함을 선사합니다.', 37.569666, 126.985389, '', '지하철 1호선 종각역 4번출구, 188m', '', '', ' https://arivalley.com/', '', '', '매일 16:30-02:00', '0507-1455-0837', ''),
	(1164, '작은인디아', '03149  서울 종로구 인사동길 27 (인사동)', 'images/작은인디아_1164.jpg', '인도에서 직접 공수한 재료로 정성껏 요리한 전통 인도 음식\n\n가게 이름처럼 인도를 축소해 놓은 듯한 작은인디아는 주인 내외가 수년간 여행하며 수집한 아기자기한 소품과 직접 그린 벽화들로 꾸며져 있어 인도에 온 듯한 착각을 불러일으킵니다. 인도에서 직접 공수한 재료로 정성껏 요리한 전통 인도 음식들은 인도에 대한 향수를 자아내며, 이곳에서 진정한 인도 미식을 경험해 보기를 추천합니다.', 37.573067, 126.985999, '', '지하철 1/3/5호선 종로3가역 5번 출구, 296m', '커리, 사모사', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:30 - 23:30', '-6178', ''),
	(1165, '장안삼계탕', '04526  서울 중구 세종대로18길 8 (태평로2가)', 'images/장안삼계탕_1165.jpg', '전복 삼계탕과 전복 오골계는 이곳의 시그니처 메뉴로, 특히 오골계를 사용한 삼계탕은 다른 집에서는 보기 힘든 독특한 메뉴입니다.\n\n전복 삼계탕과 전복 오골계는 이곳의 시그니처 메뉴로, 특히 오골계를 사용한 삼계탕은 다른 집에서는 보기 힘든 독특한 메뉴입니다. 오골계의 깊고 진한 맛이 국물에 스며들어 한층 더 풍부한 맛을 제공합니다. 오랜 역사를 자랑하는 만큼 단골손님이 많습니다. 건강하고 맛있는 삼계탕을 경험하고 싶다면 이곳에서 특별한 삼계탕을 맛보는 것을 추천합니다.', 37.563709, 126.977511, '', '지하철 1, 2호선 시청역 7번 출구, 88m', '삼계탕, 전복삼계탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '09:00 - 21:00 (20:30 라스트오더)', '-7561', ''),
	(1166, '내림손삼계탕 을지로점', '04539  서울 중구 남대문로10길 30 (수하동)', 'images/내림손삼계탕_을지로점_1166.jpg', '신선한 닭고기와 인삼을 푹 고아 만든 시원한 국물로 남녀노소 모두가 즐겨 찾는 보양식 삼계탕 전문점 입니다.\n\n오랜 기간 사랑받고 있는 전통 삼계탕 전문점이다. 신선한 닭고기와 인삼을 푹 고아 만든 시원한 국물로 남녀노소 모두가 즐겨 찾는 보양식인 삼계탕이 대표 메뉴입니다. 여러 명이 함께 방문하기 좋은 식당으로, 삼계탕을 포함한 다양한 닭 요리를 맛볼 수 있습니다.', 37.567482, 126.984388, '', '지하철 2호선 을지로입구역 3번 출구, 190m', '삼계탕, 닭한마리(중)', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓧ', '10:00-22:00 (브레이크타임 15:00-17:00, 매주 일요일 휴무)', '-4644', ''),
	(1167, '페트라 팰리스', '04351  서울 용산구 녹사평대로40길 43 (이태원동)  1층', 'images/페트라_팰리스_1167.png', '건강한 맛을 살린 터키. 중동식 요리를 선보이는 곳\n\n건강한 맛을 살린 중동식 요리를 선보이는 이곳은 퀄리티 높은 음식 비주얼과 맛이 돋보이는 곳입니다. 특히 후무스와 팔라펠 등이 함께 제공되는 메자 플래터가 시그니처 메뉴로 유명합니다. 지중해와 중동식의 특색 있는 음식을 경험하고 싶다면 이곳은 꼭 방문해야 할 곳입니다.', 37.534581, 126.988192, '', '지하철 6호선 녹사평역 1번 출구, 282m', '메자플래터, 와락다왈리', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:30 - 20:30', '-9998', '매주 수요일'),
	(1168, '양푼이', '07014  서울 동작구 사당로30길 81 (사당동)', 'images/양푼이_1168.jpg', '매콤하면서도 시원한 국물의 생대구탕과 깊고 풍부한 맛의 생태찌개.\n\n매콤하면서도 시원한 국물의 생대구탕과 깊고 풍부한 맛의 생태찌개, 어느 것 하나도 놓치기 아쉬운 곳입니다. 두 가지 맛이 각각의 매력을 지니고 있어 선택이 어렵습니다. 가격도 저렴해 부담 없이 한 끼 식사로 훌륭하고, 편안하게 즐길 수 있는 곳입니다.', 37.481191, 126.980923, '', '지하철 2/4호선 사당역 10번 출구, 395m', '생대구탕, 생태탕', '', '', '', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00', '-8808', ''),
	(1169, '루바브 Rhubarb', '03981  서울 마포구 연희로 47 2층 201호', 'images/루바브_Rhubarb_1169.jpg', '당근파스타가 맛있는 연남동 브런치 카페\n\n연남동에 위치한 루바브는 신선한 재료로 건강하게 즐길 수 있는 브런치 카페입니다.  대표 메뉴로는 명란과 당근 라페가 올라간 당근 파스타이며, 특색있는 브런치 메뉴를 찾으신다면 가장 인기있는 당근 파스타를 맛보시길 추천합니다. 1인 1식사 메뉴가 필수이며, 식사메뉴 주문시 모든 음료는 할인받을 수 있습니다.', 37.562958, 126.927740, '1만원대', '지하철 2호선/공항철도/경의중앙 홍대입구역 3번출구, 608m', '파스타', '월,수,목,금,토,일', ' https://map.naver.com/p/search/%EB%A3%A8%EB%B0%94%EB%B8%8C%20Rhubarb/place/1124107346?placePath=/home?entry=pll&from=map&fromNxList=true&fromPanelNum=2&timestamp=202509031014&locale=ko&svcName=map_pcv5&searchText=%EB%A3%A8%EB%B0%94%EB%B8%8C%20Rhubarb&searchType=place&c=15.00,0,0,0,dh', '음식점', '매주 화요일 휴무', '8:30-17:00', '070-7543-2628', '매주 화요일'),
	(1170, '봉이전', '08745  서울 관악구 봉천로 473-5 1층', 'images/봉이전_1170.jpg', '관악산 등산 후 들르기 좋은 전집\n\n막걸리와 전은 예로 부터 한국인들이 즐기던 찰떡 궁합으로 등산 후 하산하며 찾는 등산객들이 많습니다. 관악산을 등산 후 전집을 찾는다면 서울대입구 방향으로 하산하여 봉이전에 방문하길 추천합니다. 봉이전 메뉴에는 전류 뿐만아니라 다양한 종류의 막걸리와 안주류, 탕류들이 있습니다.', 37.482603, 126.952707, '', '지하철 2호선 서울대입구역 6번출구, 165m', '', '', '', '음식점', '', '월~금 14:00-01:00 / 토,일 13:00-01:00', '02-874-5577', ''),
	(1171, '육회 by 유신 망원본점', '03964  서울 마포구 망원로11길 29 (망원동)  1층 3호', 'images/육회_by_유신_망원본점_1171.jpg', '한우 암소 1+ 육회와 노량진 새벽시장에서 직접 공수해오는 연어를 독특한 방식으로 숙성시켜 제공하는 식당입니다.\n\n한우 암소 1+ 육회와 노량진 새벽시장에서 직접 공수해오는 연어를 독특한 방식으로 숙성시켜 제공하는 식당입니다. 숙성된 육회와 연어를 사용하여 육회초밥과 연어초밥을 만들어내며, 품질 높은 재료와 정성으로 만든 초밥이 시그니처 메뉴로 인기가 있습니다. 이곳의 육회와 연어 사시미도 훌륭한 평가를 받고 있으며, 뛰어난 맛을 자랑합니다.', 37.558961, 126.906323, '', '지하철 6호선 마포구청역 5번 출구, 516m', '연어사시미. 육회', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '17:00 - 01:00 (매주 일요일 휴무)', '-15332', ''),
	(1172, '봄베그릴', '04405  서울 용산구 우사단로10길 11 (이태원동)', 'images/봄베그릴_1172.jpg', '인도 음식 전문점으로, 현지인 셰프가 직접 조리\n\n인도 음식 전문점으로, 현지인 셰프가 직접 조리하여 인도 음식 본연의 맛을 즐길 수 있는 곳입니다. 신선한 재료만을 사용하여 건강한 음식 문화를 만들어가며, 편안한 식사를 위한 세심한 서비스를 제공합니다. 다양한 런치 세트가 가성비 좋은 가격으로 구성되어 있어 점심시간에 방문하기에 특히 좋습니다.', 37.533201, 126.996233, '', '지하철 6호선 이태원역 3번 출구, 335m', '치킨커리런치세트, 양고기커리런치세트', '', ' http://bombaygrilll.itrocks.kr/', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:00 - 22:00', '-8908', ''),
	(1173, '심퍼티쿠시 용산점', '04382  서울 용산구 한강대로52길 17-3 1층', 'images/심퍼티쿠시_용산점_1173.jpg', '유러피언 요리를 아시안 스타일로 풀어낸 파인캐주얼 레스토랑\n\n용리단길 핫플레이스 중심에 위치한 심퍼티쿠시 용산점은 유러피언 요리를 아시안 스타일로 풀어낸 파인캐주얼 레스토랑입니다. 감각적이면서도 편안한 공간에서 수준 높은 요리를 합리적인 가격에 제공함으로써 한 번의 식사가 사랑하는 사람과 함께 나누는 소중한 순간이 되도록 노력하고 있습니다. 전문적으로 큐레이팅 된 와인 바틀샵이 있어 다양한 종류의 와인을 합리적인 가격에 구매할 수 있습니다.', 37.532187, 126.972073, '', '지하철 4호선/6호선 삼각지역 3번출구, 179m', '', '', ' https://www.instagram.com/szimpatikus.seoul/', '', '*캐치테이블 예약 가능\n*예약금 : 방문 시 전액 환불 처리됩니다.\n*콜키지 : Bottle 당 20,000원입니다. (주종 무관)\n*웰컴키즈존 : 유아동용 의자, 식기, 컵 등이 구비되어 있습니다.\n*매장에는 주차가 불가능하여 근처 유료 공영주차장을 이용해주세요.', '매일 11:30-22:00 브레이크타임 15:30-17:00 라스트오더 14:30, 21:00', '0507-1433-2056', ''),
	(1174, '룸템퍼레이쳐', '04775  서울 성동구 성덕정9가길 6 (성수동1가)  1층', 'images/룸템퍼레이쳐_1174.png', '룸템퍼레이쳐는 비건 및 유기농 메뉴를 제공하는 비건 브런치 카페\n\n룸템퍼레이쳐는 서울의 비건 브런치 카페로, 유기농과 비건 메뉴를 중심으로 건강한 식사를 제공합니다. 북유럽풍 인테리어가 돋보이는 아늑한 공간에서, 편안하게 식사를 즐길 수 있습니다.\n\n카페에는 야외 테라스 자리가 마련되어 있어 맑은 날씨에 자연을 느끼며 브런치를 즐기기에 좋습니다. 또한, 테이크아웃 할인 혜택이 제공되며, 반려동물 동반도 가능해 반려견과 함께 방문할 수 있습니다. 건강한 먹거리와 함께 여유로운 시간을 보내기에 완벽한 장소입니다.', 37.539298, 127.050537, '', '지하철 수인분당선 서울숲역 2번 출구, 766m', '', '화~ 일', ' https://www.instagram.com/roomtemperature.kafeteria', '음식점', '', '11:00 ~ 18:00', '0507-1483-0246', '월'),
	(1175, 'Summer Lane 서머레인', '04348  서울 용산구 이태원로55가길 49 1층 summerlane', 'images/Summer_Lane_서머레인_1175.png', '호주식 브런치 문화를 맛볼 수 있는 카페\n\n노란색 차양과 해변, 바다를 그린 대형 그림이 시선을 사로잡는 에너지 가득한 공간은 한국 현지인도 좋아할 만큼 웨이팅 있는 호주식 브런치 카페입니다. 오픈 시간이 오전 7시 30분으로 여행 중 이른 아침 시간을 활용하고 싶은 분들에게 딱 좋은 장소입니다. 시그니처 메뉴인 크로아상 프렌치토스트와 와플 에그 베네틱트로 브렌치의 품격을 만끽해보시길 바랍니다.', 37.536328, 126.999307, '', '지하철 6호선 한강진역 1번출구, 563m', '', '', ' http://instagram.com/summerlane_brunch', '', '', '07:30-18:00', '02-792-8114', ''),
	(1176, '찰나', '04148  서울 마포구 백범로 170 (공덕동, 공덕더샵아파트)  102동 1층 11호', 'images/찰나_1176.jpg', '모던한 분위기의 일본식 소고기 화로구이 전문점\n\n모던한 분위기의 일본식 소고기 화로구이 전문점으로, 일본의 야키니쿠 문화를 한국적인 맛과 감성으로 재해석한 곳입니다. 고급스러운 분위기 속에서 질 좋은 소고기를 즐길 수 있으며, 고기 모듬과 전골을 함께 맛볼 수 있는 메뉴가 시그니처입니다.', 37.544269, 126.949281, '', '지하철 5/6호선/공항철도/경의중앙선 공덕역 1번 출구, 143m', '고기모듬+전골', '', ' https://www.instagram.com/_c_h_a_l_n_a_/#', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '주중 17:00 - 23:00 (22:00 라스트오더)\n토~일 13:00~22:00', '-7376', ''),
	(1177, '니르바나', '03146  서울 종로구 인사동길 58 (관훈동)  2층', 'images/니르바나_1177.jpg', '인도 전통 방식으로 조리된 요리들은 인도 음식을 그리워하는 이들에게 큰 인기\n\n인도 현지 풍의 화려한 인테리어가 인상적인 이 식당은, 스태프가 현지인들로 구성되어 있어 더욱 진한 현지 분위기를 자아냅니다. 인도 전통 방식으로 조리된 요리들은 인도 음식을 그리워하는 이들에게 큰 인기를 끌고 있으며, 맛과 친절한 서비스 모두에서 높은 평가를 받고 있습니다. 특히 버터 치킨 커리가 그 맛으로 유명하며, 많은 사람들이 이곳을 찾는 이유 중 하나입니다.', 37.575129, 126.983767, '', '지하철 3호선 안국역 6번 출구, 164m', '탄두리 치킨 반마리, 버터 치킨 커리', '', ' https://www.instagram.com/nirvana.seoul/#', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:30-21:00 (15:00-17:00 브레이크타임, 14:30, 20:30 라스트오더)', '-2550', ''),
	(1178, '찐우', '03930  서울 마포구 월드컵북로48길 38 (상암동, 상암주택)  1층', 'images/찐우_1178.jpg', '숙성 소고기 전문점으로 1++ 최상급 한우를 내놓는 곳으로 갓 지은 솥밥이나 차돌된장라면 등 직접 만든 사이드 메뉴에서 정성이 느껴집니다.\n\n숙성 소고기 전문점으로 1++ 최상급 한우를 내놓는 곳입니다. 갓 지은 솥밥이나 차돌된장라면 등 직접 만든 사이드 메뉴에서 정성이 느껴집니다. 특히 소고기의 최상급 특수부위인 한우 새우살을 선보여, 특별한 한우를 맛보려면 꼭 방문해야 할 곳입니다. 찐우에서는 만족스러운 퀄리티의 제대로 된 한 끼를 즐길 수 있습니다.', 37.577344, 126.895627, '', '지하철 6, 공항철도, 경의중앙선 디지털미디어시티역 9번 출구, 189m', '15:00 - 23:00 (22:00 라스트오더, 매주 일요일 휴무)', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '15:00 - 23:00 (22:00 라스트오더, 매주 일요일 휴무)', '-12477', ''),
	(1179, '소소정', '06997  서울 동작구 동작대로31길 32 (사당동)', 'images/소소정_1179.jpg', '대형 가마솥에서 끓인 왕갈비탕이 시그니처 메뉴\n\n대형 가마솥에서 끓인 왕갈비탕이 시그니처 메뉴입니다. 왕갈비탕은 소갈비를 푹 끓여서 만든 요리로 보양식으로도 잘 알려져 있습니다. 뜨끈한 국물과 야들야들한 갈비살의 조화가 일품입니다. 또 육회비빔밥은 가성비가 좋아 점심식사 메뉴로 좋습니다. 둘 다 맛보고 싶은 여행객이라면 금액 부담이 크지 않으니 둘 다 시켜도 좋습니다.', 37.489112, 126.980727, '', '지하철 4/7호선 총신대입구(이수)역 14번 출구, 181m', '갈비탕, 육회비빔밥', '', ' https://blog.naver.com/jin508815_', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 21:00 (20:45 라스트오더)', '-10387', '매주 수요일'),
	(1180, '육즙당 광화문점', '03183  서울 종로구 새문안로5길 10-1 2층', 'images/육즙당_광화문점_1180.jpg', '한돈, 한우, 지리산 흑돼지를 함께 맛볼 수 있는 숙성고기 전문점\n\n숙성고기 전문점으로 한돈 백돼지의 단백한 맛, 100% 지리산 흑돼지의 쫄깃쫄깃한 맛과 진한 육향을 즐길 수 있으며, 참숯의 향을 입은 최상급 자랑하는 1++한우를 맛보실길 추천합니다. 약 1주일에서 5주정도 습식숙성을 거쳐 육즙을 보존하고 육질이 부드럽게 하며, 건조숙성을 거쳐 드립현상을 최대한 줄여 최고의 맛을 제공하려 노력하고 있습니다.', 37.571253, 126.975032, '', '지하철 5호선 광화문역 8번출구, 65m', '', '', ' https://www.instagram.com/yukzupdang_official', '', '와인 콜키지 무료, 캐치테이블 예약 가능', '매일 11:00-22:00 / 브레이크타임(월-금) 14:30-16:00 / 라스트오더 21:15', '0507-1423-1821', ''),
	(1181, '남원골', '03927  서울 마포구 월드컵북로44길 68 (상암동)', 'images/남원골_1181.jpg', '뜨끈한 삼계탕 한 그릇에 영양과 기운을 제대로 보충할 수 있는 식당입니다.\n\n뜨끈한 삼계탕 한 그릇에 영양과 기운을 제대로 보충할 수 있는 식당입니다.  닭 요리 외에도 염소, 오리 요리 등 다양한 보양식 메뉴가 가득 채워져 있습니다. 특히, 능이 닭백숙은 능이 버섯의 독특한 맛과 푹 고아서 만든 닭의 부드러운 살이 조화를 이루어 일품이다. 한국식 보양식을 맛보고 싶다면 남원골을 놓치지 마세요.', 37.577531, 126.894124, '', '지하철 6, 공항철도, 경의중앙선 디지털미디어시티역 9번 출구, 358m', '능이 닭백숙, 깻잎 닭도리탕', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 22:30', '-9144', ''),
	(1182, '이코노스시 본점', '03766  서울 서대문구 신촌역로 14 (대현동)', 'images/이코노스시_본점_1182.jpg', '오랜 시간 한 자리를 지키고 있는 회전초밥집으로, 회전초밥을 즐기거나 모듬 초밥을 주문할 수 있습니다.\n\n오랜 시간 한 자리를 지키고 있는 회전초밥집으로, 회전초밥을 즐기거나 모듬 초밥을 주문할 수 있습니다. 깔끔한 맛의 초밥 외에도 회덮밥이나 알탕도 함께 먹기 좋다. 초밥 외에도 모듬회를 판매하여 다양한 해산물 요리를 한 자리에서 맛볼 수 있는 장점이 있습니다.', 37.557843, 126.943056, '', '지하철 경의중앙선 신촌역 1번 출구, 202m', '모듬초밥, 모듬회', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (매주 일요일 휴무)', '-9281', ''),
	(1183, '남산술클럽', '04345  서울 용산구 녹사평대로 228-2 1층', 'images/남산술클럽_1183.jpg', '100가지의 전통주를 잔술로 경험할 수 있는 전통주 바\n\n남산술클럽은 외국인이 운영하는 전통주바로 전통주 소믈리에의 큐레이팅과 함께 100가지의 전통주를 잔술로 경험할 수 있습니다. 손님 취향에 맞춰 추천해주는 방식이며, 전통주를 몰라도 부담없이 즐길 수 있습니다. 마실 때마다 술에 어울리는 술잔에 따라 마실 수 있어 술잔을 보는 재미도 느껴보시길 바랍니다.', 37.538039, 126.987041, '', '지하철 6호선 녹사평역 2번출구, 311m', '', '', ' https://www.instagram.com/namsansoolclub', '', '반려동물 동반 가능', '18:00-01:00', '0507-1326-3921', '매주 화요일'),
	(1184, '루나 아시아', '06166  서울 강남구 삼성로100길 15 (삼성동, 명당빌딩)', 'images/루나_아시아_1184.jpg', '인도 요리사들이 선사하는 전통 인도 요리를 맛볼 수 있다. 100% 천연 향신료를 이용한 정통 커리와 화덕에서 구운 난으로 인도 전통의 맛과 향을 경험할 수 있습니다.\n\n인도 요리사들이 선사하는 전통 인도 요리를 맛볼 수 있다. 100% 천연 향신료를 이용한 정통 커리와 화덕에서 구운 난으로 인도 전통의 맛과 향을 경험할 수 있습니다. 특히, 탄두리 치킨과 프라운 빈달루는 대표 메뉴로, 꼭 한 번 맛봐야 할 요리입니다.', 37.509901, 127.056634, '', '지하철 9호선 삼성중앙역 5번 출구, 487m', '탄두리치킨, 프라운반달루', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (14:30 - 17:00 브레이크타임, 21:00 라스트오더)', '-8474', ''),
	(1185, '수락산풍천장어', '01629  서울 노원구 동일로242길 48 (상계동, 다온빌딩)', 'images/수락산풍천장어_1185.png', '국내산 장어를 갓 잡아 바로 구워주는 장어구이집\n\n한국 등산객들이 수락산 하산 후 체력 보충을 위해 방문하는 장어 음식 전문점으로 요리 직전 바로 갓 잡은 싱싱한 국내산 장어를 사용합니다. 장어구이는 소금구이와 앙념구이로 나뉘는데 장어의 본연의 맛을 느끼기 원한다면 소금구이를 추천합니다. 또한 직접 담근 파김치에 자부심이 있는 가게인 만큼 싱싱한 장어와 가게만의 비법이 담긴 파김치도 함께 드셔보시길 바랍니다.', 37.674784, 127.057756, '', '지하철 7호선 수락산역 3번출구, 340m', '', '', ' https://blog.naver.com/ymj9666', '', '2인 점심 세트는 오후 3시까지 주문가능', '11:00-23:00', '0507-1360-8488', ''),
	(1186, '밀스', '04775  서울 성동구 뚝섬로4길 21 (성수동1가)', 'images/밀스_1186.png', '미슐랭 출신 쉐프가 운영하는 수제 소시지와 사워도우 브레드를 활용한 카페\n\n카페 밀스는 미슐랭 레스토랑 \'모수\' 출신의 쉐프가 운영하는 카페로, 식사 대용으로 적합한 다양한 메뉴를 제공합니다. 밀스만의 사워도우 브레드와 키친에서 직접 만든 소시지, 햄을 이용한 토스트, 샌드위치, 핫도그번 등은 풍성한 내용물로 맛과 영양을 동시에 갖추고 있습니다. 1층에는 키친과 베이커리 진열공간이 있어 1~2인석 테이블로 구성되어 있으며, 단체 이용 시에는 2층을 추천합니다. 커피와 음료는 브레드와 잘 어울리며, 테이크아웃 할인도 제공됩니다. 배리어프리 시설이 완비되어 휠체어 이용도 편리합니다.', 37.538969, 127.050937, '', '지하철 수인분당선 서울숲역 2번 출구, 828m', '', '', ' https://www.instagram.com/milsishappy', '음식점', '', '', '0507-1327-4677', ''),
	(1187, '태양의토마토라멘', '06123  서울특별시 강남구 강남대로106길 7 2층', 'images/태양의토마토라멘_1187.jpg', '일본에서 넘어온 트렌디한 라멘, 태양의 토마토라멘\n\n태양의토마토라멘은 일본식 라멘에 신선한 토마토를 더한 색다른 스타일의 라멘 전문점입니다. 진하게 우려낸 토마토 육수는 상큼하면서도 깊은 감칠맛을 자랑하며, 면과 조화를 이루어 담백하지만 풍성한 맛을 선사합니다. 느끼하지 않고 깔끔한 맛 덕분에 남녀노소 모두에게 인기가 많습니다. 맵기 조절이 가능해 매운 음식을 좋아하는 분들도 만족하실 수 있습니다. 서울 여행 중 특별한 라멘을 찾는다면 꼭 들러보세요!', 37.502977, 127.026224, '', '지하철 9호선/신분당선 신논현역 6번출구 137m', '태양의토마토라멘(9000원),치즈토마토라멘(10,500원)', '', ' https://www.instagram.com/taitoma_korea/', '', '면을 다드시고 남은 국물에 라리죠(밥)까지 비벼 드셔야 맛있게 한끼 마무리 하실 수 있습니다!', '매일 11:00-21:00', '02-501-0120', ''),
	(1188, '빠르크 한남본점', '04348  서울 용산구 이태원로55가길 26-5 나무 계단 위 2층', 'images/빠르크_한남본점_1188.jpg', '속이 편안해지는 건강한 한 끼의 깔끔한 한식당\n\n빠르크(Parc)는 스페인 바르셀로나에서 쓰는 까딸루냐어로 \'공원\'이라는 뜻입니다. 바쁜 도시 생활 중에 공원에 앉아 쉬어가는 한가로운 한때와 같은 느낌을 나누고 싶은 마음을 정성스레 한식으로 담았습니다. 화학 조미료를 쓰지 않고 집에서 엄마가 쓰는 재료들을 그대로 쓰는 엄마의 레시피로 깐깐한 손맛과 정성 가득한 집밥 느낌의 한국 요리들을 주로 선보입니다.', 37.537487, 126.999731, '', '지하철 6호선 한강진역 1번출구, 406m', '', '', ' https://www.instagram.com/parcseoul/', '', '', '매일 11:30-21:00 / 브레이크타임 15:20-17:30 / 라스트오더 20:15', '0507-1409-2022', ''),
	(1189, '엘로치킨', '04407  서울 용산구 우사단로10길 14 (이태원동)', 'images/엘로치킨_1189.png', '한국에 거주하는 무슬림들에게 널리 알려진 프라이드 치킨 전문 매장입니다.\n\n한국에 거주하는 무슬림들에게 널리 알려진 프라이드 치킨 전문 매장입니다. 기존 프라이드 치킨과 비교해 특유의 향신료 맛이 가미되어 무슬림 입맛에 더욱 잘 맞는다는 평가를 받고 있습니다. 무슬림 관광객들도 걱정 없이 이 특별한 프라이드 치킨을 즐길 수 있습니다.', 37.533047, 126.996428, '', '지하철 6호선 이태원역 3번 출구, 353m', '스위트 스파이시 치킨, 크리스피 후라이드 치킨', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '12:00 - 21:00 (매주 월요일 휴무)', '-1903', ''),
	(1190, '춘천집 명가', '05018  서울 광진구 아차산로33길 7 (화양동)  1층', 'images/춘천집_명가_1190.jpg', '클래식한 옛날 닭갈비부터 마늘 닭갈비, 느타리 닭갈비, 쭈꾸미 닭갈비, 낙지 닭갈비 등 다양한 닭갈비를 맛볼 수 있는 식당입니다.\n\n클래식한 옛날 닭갈비부터 마늘 닭갈비, 느타리 닭갈비, 쭈꾸미 닭갈비, 낙지 닭갈비 등 다양한 닭갈비를 맛볼 수 있는 식당입니다. 옛날 닭갈비는 전통적인 양념과 숯불로 구워 깊은 맛을 자랑하며, 마늘 닭갈비는 풍부한 마늘 향이 더해져 감칠맛이 돋보입니다. 느타리 닭갈비는 부드러운 느타리버섯과 함께 조리되어 식감이 좋고, 쭈꾸미 닭갈비는 쭈꾸미의 매콤하고 쫄깃한 맛이 닭갈비와 잘 어우러진다. 각종 닭갈비는 풍부한 맛과 다양한 재료로 개성 있는 조화를 이룹니다.', 37.540709, 127.069929, '', '지하철 2, 7호선 건대입구역 2번 출구, 95m', '명품 옛날닭갈비, 마늘 닭갈비', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '"10:30 - 23:00 (22:20 라스트오더)\n금 - 토 10:30 - 24:00 (23:20 라스트오더)"', '-10043', ''),
	(1191, '대포찜닭', '03788  서울 서대문구 연세로 27-1 (창천동, 대성빌딩)  대성빌딩 3층', 'images/대포찜닭_1191.jpg', '닭 인형으로 주문하고 닭 캐릭터로 인테리어를 하는 등 색다른 경험을 제공하여 젊은 관광객들에게 인기가 많습니다.\n\n닭 인형으로 주문하고 닭 캐릭터로 인테리어를 하는 등 색다른 경험을 제공하여 젊은 관광객들에게 인기가 많습니다. 특히 찜닭 위에 올려주는 귀여운 캐릭터는 연신 기념사진을 찍게 만드는 매력이 있습니다. 이곳의 찜닭은 매콤달콤한 양념과 풍부한 맛이 일품으로, 부드러운 닭고기와 함께 다양한 채소가 조화롭게 어우러집니다.', 37.558055, 126.936714, '', '지하철 2호선 신촌역 2번 출구, 278m', '대포찜닭', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00 (20:40 라스트오더, 매주 일요일 휴무)', '-8459', ''),
	(1192, '홍정기참치', '03991  서울 마포구 동교로27길 47 (연남동, 제이드빌(Jade))  2층', 'images/홍정기참치_1192.jpg', '스페인산 최고급 등급의 참다랑어만을 사용하는 참다랑어 전문점이다. 30년 이상의 일식 경력을 가진 셰프가 정성스럽게 준비한 일품 요리를 맛볼 수 있으며, 참다랑어의 깊고 풍부한 맛을 조화롭게 즐길 수 있습니다.\n\n스페인산 최고급 등급의 참다랑어만을 사용하는 참다랑어 전문점입니다. 30년 이상의 일식 경력을 가진 셰프가 정성스럽게 준비한 일품 요리를 맛볼 수 있으며, 참다랑어의 깊고 풍부한 맛을 조화롭게 즐길 수 있습니다. 정성이 담긴 요리와 함께 편안하고 아늑한 분위기로 친구나 연인과 함께 방문하기에 좋은 장소입니다.', 37.559868, 126.921279, '', '지하철 2호선 홍대입구역 2번출구, 421m', '블루 스페셜, 레드 스페셜', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '10:00 - 22:00', '-1969', ''),
	(1193, '공릉닭한마리', '03778  서울 서대문구 연세로2길 77 (대현동, 부소빌딩)', 'images/공릉닭한마리_1193.jpg', '촉촉하고 야들한 닭고기를 양념장에 찍어 먹고 깊은 국물까지 떠먹으면 닭한마리의 맛을 제대로 느낄 수 있습니다.\n\n촉촉하고 야들한 닭고기를 양념장에 찍어 먹고 깊은 국물까지 떠먹으면 닭한마리의 맛을 제대로 느낄 수 있습니다.  닭한마리는 통째로 조리하여 육즙이 가득한 부드러운 닭고기와 깊은 맛의 국물이 특징입니다. 식사 후 칼국수나 죽을 추가로 주문해 먹는 것이 필수다. 최근에는 외국인 관광객들 사이에서도 인기가 급상승하고 있습니다.', 37.557129, 126.941073, '', '지하철 경의중앙선 신촌역 1번 출구, 417m', '닭한마리', '', '', '음식점', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '11:00 - 22:00', '-9912', ''),
	(1194, '칠갑산', '01414  서울 도봉구 노해로 379 (창동)', 'images/칠갑산_1194.jpg', '곤드레비빔밥이 맛있는 창동 한식당\n\n건강하게 한끼를 든든하게 채워주는 칠갑산 한식당은 자극적이지 않고 담백한 동네 현지인 맛집입니다. 대표 메뉴로는 곤드레비빔밥, 소국밥, 불고기이며 이외에도 다양한 전과 일품요리 메뉴들이 있습니다.', 37.652476, 127.050256, '', '지하철 1호선/4호선 창동역 1번출구, 250m', '', '', '', '', '', '11:00-21:30', '02-996-9997', '매주 토요일'),
	(1195, '인딕슬로우', '06028  서울 강남구 압구정로4길 13 (신사동)', 'images/인딕슬로우_1195.jpg', '인딕슬로우란 인도의 평화로운 하루를 상징하며, 서두르지 않고 모든 것이 천천히 자연스럽게 흘러가는 시간을 담고자 하는 곳 입니다.\n\n식당 이름에서도 알 수 있듯이, 인딕슬로우는 건강하고 모던한 인도 요리를 제공한다. 인딕슬로우란 인도의 평화로운 하루를 상징하며, 서두르지 않고 모든 것이 천천히 자연스럽게 흘러가는 시간을 담고자 하는 곳 입니다. 특히, 다른 곳에서는 보기 힘든 메뉴인 브런치 탈리를 맛볼 수 있다. 여유로운 식사를 즐기고 싶다면 이곳을 방문해 보세요.', 37.521899, 127.020334, '', '지하철 3, 신분당선 신사역 6번 출구, 688m', '브런치 탈리, 탄두리 치킨 플레터', '', '', '음식점', '주류 판매 Ⓧ\n무슬림 조리사 Ⓞ', '11:30 - 21:30 (15:30 - 17:30 브레이크타임, 14:30, 20:30 라스트오더)\n토 - 일 11:30 - 21:30 (16:00 - 17:00 브레이크타임, 15:00, 20:30 라스트오더)', '-570', ''),
	(1196, '외양간', '07014  서울 동작구 동작대로11길 16 (사당동, HS하우스)', 'images/외양간_1196.jpg', '대기줄이 언제나 길 만큼 인기 있는 고기요리 전문점입니다. 특수부위 모듬과 키조개 관자, 묵은지의 조합을 함께 구워먹으면 그 맛이 한층 더 깊어집니다.\n\n대기줄이 언제나 길 만큼 인기 있는 고기요리 전문점입니다. 특수부위 모듬과 키조개 관자, 묵은지의 조합을 함께 구워먹으면 그 맛이 한층 더 깊어진다. 고기를 마음껏 즐긴 후에는 차돌된장 라면으로 깊고 진한 된장 맛을, 차돌볶음밥으로 고소한 차돌박이와 볶음밥의 완벽한 조화를 경험해 보는 것을 추천합니다.', 37.481258, 126.980728, '', '지하철 2, 4호선 사당역 10번 출구, 408m', '특수부위모듬, 키조개관자+묵은지', '', '', '', '주류 판매 Ⓞ\n무슬림 조리사 Ⓧ', '15:00 - 24:00', '-10132', ''),
	(1197, '신라당 익선', '03133  서울 종로구 돈화문로11다길 40 1층', 'images/신라당_익선_1197.jpg', '전통적인 방식 그대로 한과의 정성과 깊이를 이어가는 프리미엄 수제 한과 브랜드\n\n신라당은 전통적인 방식 그대로 한과의 정성과 깊이를 이어가는 프리미엄 수제 한과 브랜드입니다. 매일 아침 수작업으로 빚어내는 한과에는 정성을 가득 담았습니다. 신라당 한과 세트로 소중한 사람에게 마음을 전해보세요!', 37.573799, 126.989955, '', '지하철 1호선/3호선/5호선 종로3가역 4번출구, 177m', '오리지널 주악 3,400원', '', ' https://www.instagram.com/silladang_official/', '', '무료 선물 포장 서비스 운영', '매일 10:30-21:00', '0507-1498-8220', ''),
	(1198, '목석정', '03054  서울 종로구 팔판길 29 (팔판동)  목석정 1', 'images/목석정_1198.jpg', '전통에 뿌리를 두고, 정성으로 차린 맡김 차림 한식 다이닝\n\n목석정은 서울 삼청동의 조용한 골목 안에 숨겨진 보석 같은 한옥 레스토랑으로, 계절에 맞춘 한식 다이닝 스타일의 한식을 선보입니다. 모든 음식을 한 번에 내는 대신, 손님의 식사 속도에 맞춰 차분히 한 코스씩 제공하며, 중심에는 늘 갓 지은 솥밥이 있습니다. 식재료는 매일 아침 가락시장과 마장축산물시장에서 직접 엄선하며, 최상급 한우++와 신선한 제철 해산물을 사용해 한정 수량으로 준비합니다. 이를 통해 모든 요리에 최고의 품질과 계절의 풍미를 담아냅니다. 햇살이 격자 창호 사이로 스며드는 따뜻하고 절제된 한옥 공간은 연인, 가족, 외국인 손님 모두에게 어울리는 아늑한 분위기를 제공합니다. 각 요리는 단순한 플레이팅을 넘어, 그 안에 담긴 이야기와 계절의 감각, 셰프의 정성를 함께 전하며, 식사를 넘어 오래 기억될 특별한 순간을 선사합니다.', 37.583111, 126.981127, '3만원대', '지하철 3호선 안국역 2번출구, 990m', '목(木) 맡김차림 / 석(石) 맡김차림 68,000원', '수요일~일요일', ' https://app.catchtable.co.kr/ct/shop/mokseokjung?from=share&type=DINING', '음식점', '한정식 맡김차림 (코스요리)로 100% 예약제로 운영', '10:00~21:30', '010-2257-1048', '월요일, 화요일'),
	(1199, '레인리포트 레인보우', '03133  서울 종로구 수표로28길 33-7 (익선동)', 'images/레인리포트_레인보우_1199.png', '365일 비가 내리는 한옥 카페, 컬러풀 수제 디저트 전문점\n\n365일 비가 내리는 카페, 레인리포트가 당신의 하루에 색을 더하는 ‘레인보우’를 선보입니다. 무채색의 감성적인 한옥 공간 속에서, 취향에 맞춘 컬러풀 수제 디저트를 만나보세요. 비 오는 무드에 생기를 더하는 디저트 카페, 익선동 레인리포트 레인보우에서 특별한 경험을 선물합니다.', 37.573429, 126.990109, '1만원대', '지하철 5호선 종로3가역 4번 출구, 280m', '클라우드 파블로바, 생과 보틀 음료', '매일', ' https://www.instagram.com/rainreport_official/', '카페, 디저트', '테이크아웃 가능', '10:30~20:30', '02-763-8215', ''),
	(1200, '아벨롭 홍대본점', '04031  서울 마포구 양화로15안길 6 (서교동)', 'images/아벨롭_홍대본점_1200.png', '1세대 건축가 김중업이 설계한 베이커리 카페\n\n아벨롭(Avelop)은 전진(advance) 혹은 예술(art)과 발전(develop)의 합성어로, 계속 전진하며 예술적 깊이를 키워가겠다는 의미의 카페입니다. 20세기 한국 현대 건축을 대표하는 건축가 김중업이 1972년에 지은 주택을 감각적으로 개조한 곳으로, 벽면과 창, 마룻바닥 기존 건축물이 가지고 있는 세월의 이야기를 최대한 살려 현대적으로 재해석했습니다. 베이커리 카페로 운영되며, 베이커리는 당일 생산하고 남은 것은 모두 폐기합니다.', 37.554465, 126.918841, '', '지하철 2호선/공항철도/경의중앙 홍대입구역 1번출구, 468m', '', '', ' https://www.instagram.com/avelop_official?igsh=MWc3enU5dGVja3l6MA%3D%3D', '', '', '월-금요일 08:00~20:00 / 토,일 11:00~21:00', '02-336-8897', ''),
	(1201, '강변서재', '07233  서울 영등포구 의사당대로 1 (여의도동, 국회)  국회 사랑재 옆 건물 2층', 'images/강변서재_1201.png', '여의도 국회의사당에 위치한 한강뷰 카페\n\n강변서재는 여의도 국회의사당에 위치한 카페로 한강을 바라보며 책을 읽을 수 있는 특별한 공간입니다. 한강을 산책하다가 잠시 들러 휴식을 취하기에도, 여행 중 여유로운 시간을 보내기에도 안성맞춤입니다. 전면 유리창 너머로 한강이 탁 트여 있어 한강과 국회의사당의 파노라마 뷰를 즐길 수 있으며 봄에는 벚꽃 구경 명소로도 추천합니다.', 37.532912, 126.916404, '', '지하철 9호선, 국회의사당역 1번 출구, 918m', '', '', '', '', '', '월~금 : 8:30~19:00 / 토요일 : 11:00~19:00', '02-6788-3331', '매주 일요일'),
	(1202, '하우스 오브 신세계 디저트살롱', '04530  서울 중구 남대문로 42 더 헤리티지 5층 하우스오브신세계 디저트살롱', 'images/하우스_오브_신세계_디저트살롱_1202.png', '한국의 전통차와 다과 페어링을 즐길 수 있는 프리미엄 전통차 카페\n\n하우스 오브 신세계 디저트살롱은 한국 전통 디저트와 차의 품격을 느낄 수 있는 카페로  한국의 자연과 계절, 그리고 다과 유산을 연구하여 현대적 감각으로 풀어낸 한국 차와 병과를 선보입니다. 세대에 관계없이 즐길 수 있어 부모님과 함께 방문하기에도 안성맞춤입니다. 또한 다과는 매장에서 먹는 것뿐만 아니라 선물용으로도 판매되고 있어, 센스 있는 선물로도 만족스러운 선택이 될 것입니다.', 37.561036, 126.980506, '', '지하철 4호선 회현역 7번출구, 250m', '', '', '', '', '', '월-목 10:30~20:00 / 금-일 10:30~20:30', '02-310-5060', ''),
	(1203, '켄싱턴 호텔 브로드웨이', '07238  서울 영등포구 국회대로76길 16 (여의도동)  켄싱턴호텔 1층', 'images/켄싱턴_호텔_브로드웨이_1203.jpg', '올데이 다이닝 레스토랑\n\n뉴욕의 브로드웨이 감성을 그대로 연출한 올데이 다이닝 레스토랑.\n\n전문 셰프들이 즉석에서 만들어드리는 다양한 종류의 라이브 음식들과 전문 소물리에가 엄선한 다양한 와인을 즐겨보세요.\n\n\n\n\n[이용시간 및 가격]\n\n■조식\n\n주중 07:00~09:30  /  성인 29,900원 / 소인 19,900원\n\n주말 및 공휴일 07:00~10:00 / 성인 35,900원 / 소인 19,900원\n\n■중식 11:30~14:00                        \n\n주중 성인 69,900원 / 소인 29,900원\n\n주말 및 공휴일 성인 89,900원 / 소인 39,900원\n\n■석식 18:00~21:00  \n\n*주말 2부제 운영 (1부) 17:00~19:00 (2부) 19:30~21:30\n\n주중 성인 89,900원 / 소인 29,900원\n\n주말 및 공휴일 성인 99,900원 / 소인 39,900원', 37.530289, 126.921969, '', '지하철9호선 국회의사당역 1/2/3번 출구, 528m', '', '', ' https://kensington.co.kr/hyd/dining/detail?idx=28', '', '', '07:00 ~ 21:00', '02-6670-7260', ''),
	(1204, '고봉삼계탕', '07238  서울 영등포구 국회대로72길 5 (여의도동, 여의도 플렉시움 오피스텔)', 'images/고봉삼계탕_1204.png', '상황버섯 삼계탕이 유명한 추천 보양식\n\n국회 의사당 인근에 위치한 고봉삼계탕은 국회의원, 공무원, 기자, 방송인들도 즐겨 찾는 맛집입니다. 대표 메뉴는 항암 효과가 있다고 알려진 ‘상황버섯’을 넣고 광천수로 끓여낸 상황삼계탕입니다. 뚝배기 안에서 보글보글 끓는 국물은 진하고, 속에는 찹쌀, 대추, 한약재가 꽉 차 있는 보양식을 즐길 수 있습니다.', 37.530513, 126.920306, '', '지하철 9호선, 국회의사당역 1번 출구, 286m', '', '', '', '', '평일 점심은 인근 직장인들로 붐비니 1시 이후 방문을 추천합니다', '10:00~22:00 (21:30 라스트오더)', '02-785-3877', '');
